INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah korudu', 'allah-korudu-yusuf-koc-wzi53', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gönülde fırtına tayfuna döndü,

Aşık oluyordum Allah korudu,

Gözlerim açıldı gerçeği gördü,

Göçüp gidiyordum Allah korudu.

Bir gecede bin kez adını andım,

Hayalin alevdi onunla yandım,

Toprak oldum her zulmüne dayandım,

Sana geliyordum Allah korudu.

Yıldızlara sordum dediler neden,

Bir senmisin ateşten gömleği giyen,

Dua aldım sanki bir dilenciden,

Yolunda ölüyordum Allah korudu.

Dostlarım şaşırdı garip halime,

Gömülmüştüm her gün daha derine,

Az kalmıştı senin gibi birine,

Vurulup yanmıştım Allah korudu.

İşte böyle idi baharım yazım,

İnsana böylesi bir ibret lazım,

Koç Ozan der gayrı çalmasın sazım,

Seni sevecektim Allah korudu.', 'Gönülde fırtına tayfuna döndü, Aşık oluyordum Allah korudu, Gözlerim açıldı gerçeği gördü, Göçüp gidiyordum Allah korudu. Bir gecede bin kez...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Koç']::text[], 8.5, '{"poet":"Yusuf Koç","poet_slug":"yusuf-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/allah-korudu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ziyaretçi', 'ziyaretci-yusuf-koc-y97k3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Merhaba eski dostum,

hoş geldin..

doğrusu meraklanmaya başlamıştım,

unuttun beni sanmıştım.

Aslında tam geliş sayılmaz bu kez de,

sadece yokladın..öyle değil mi..? 

şöyle bir göründün,

buralardayım der gibi.! 

Meraklanma eski dost,

hazırım her an

kapım açık sana..

çalmadanda girsen içeri,

gücenmem inansana..! 

nasılsa geleceksin..bana ve her insana.

Bir iyilik istiyorum eski dost senden,

gel al ve git...uzatma..

bunu esirgeme benden..! 

Merhaba eski dostum..hoş geldin..

ve şimdilik güle güle..

biraz da arayı uzat..

soluklanalım hele.! !', 'Merhaba eski dostum, hoş geldin.. doğrusu meraklanmaya başlamıştım, unuttun beni sanmıştım. Aslında tam geliş sayılmaz bu kez de, sadece yok...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Koç']::text[], 8.5, '{"poet":"Yusuf Koç","poet_slug":"yusuf-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ziyaretci-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel', 'guzel-musa-oz-wc2qc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çocuk şarkıları, ah bir de

Kuytularda üşüyen

Dalgınca devşirilmiş, al benekli

Güzel bu kırların yüreği

Gülün en durusu çocuğa işlenen

Durgun sulardan sinmiş

Çağla tüten

Hüzünlenmek başını alıp giden yaprağa

Güzel bu şiirlerin ilahesi

Çocukça sevmek, yüreklerde muştu

Okul yolu uzunca bir şiir mi Lorca’dan

Saklar ya hayal kızları bakışlarını

Güzel bu

Sevdadır şiirlere yakışan

Koklamak çoğul göğüslerini kızların

Günbalı, püren ve kekik

Güzel bu öptükçe kuş kanadı

Barış çiğ düşümünde, kuğu fırtınasında

Büyür de yar olur şiire

Güzel bu ergenlik hüzünleri

Buyur edebilmek sevgiliye gülücükle

Gül kokuları, mahmur ve gönül hoşluğuyla

Okumasa da hiç kimse şiirlerini

Uçur sözcükleri uçur güz renkleriyle

Güzel bu', 'Çocuk şarkıları, ah bir de Kuytularda üşüyen Dalgınca devşirilmiş, al benekli Güzel bu kırların yüreği Gülün en durusu çocuğa işlenen Durgun...', ARRAY['Türk Edebiyatı','Şiir','Musa Öz']::text[], 8.5, '{"poet":"Musa Öz","poet_slug":"musa-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/guzel-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakınca O Kıza', 'bakinca-o-kiza-musa-oz-yx6f1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bakınca o kıza

Topukları dolaşıyor

Belleri, kolları

Karışıyor birbirine

İnce kız delişmen

Bir de işveleri

O can içi sızı

Yürüdükçe tozuyor saçları

Döndürüyor başımı

Ergenlik kokuları

Kız bu koku çirkin ya

Kız bu koku güzel

Bakınca o kıza

Gülüşleri dolaşıyor

Sokaklar esriyor her çıkışında

Kanatıyor göğü hırsından

Limon dikenleri

Dokununca koluna

Saçlarını

Yosun uçlarından devşirmiş

Göğüslerini

Ekşi alıçtan

Bakınca o kıza

Bakışları dolaşıyor', 'Bakınca o kıza Topukları dolaşıyor Belleri, kolları Karışıyor birbirine İnce kız delişmen Bir de işveleri O can içi sızı Yürüdükçe tozuyor s...', ARRAY['Türk Edebiyatı','Şiir','Musa Öz']::text[], 8.5, '{"poet":"Musa Öz","poet_slug":"musa-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bakinca-o-kiza-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elâ Bir Güz', 'el-bir-guz-musa-oz-t7ijs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kayıkları taşıyor martılar

Dalga ve yakamozları

Uçuyorlar denizin bittiği yerden

Gagaları çiziyor suları

Kanat vuruşlarıyla oyuluyor iskele

Kaleiçi güz uykuları

Bir çiçekle uçuyorlar

Kokmuyor solan taç yaprakları

Ah unutuldu

Hoş bir adı olacaktı

Boyunları büküktür selvilerin

Uça kona kumrular

Bulutları saçılıyor gül işlemeli

Ezberde evler bahçeler

Kızların sessizce büyüdüğü sofalarda

Güneş serilip üşümeli

Bir çiçekle uçuyorlar

Kekre miydi acı mı

Ela bir adı olacaktı

Uğruyor bağ arasına

Dallara çamur getiren incir kuşları

Sürme çekiyorlar usulca

Gökyüzünün mavi donuna

Çocukların bakışlarıyla olgunlaşan

Üzümleri aşırmaları

Bir çiçekle uçuyorlar

Kokmuyor solan tomurcukları

Unutuldu ah

Hoş bir adı olacaktı', 'Kayıkları taşıyor martılar Dalga ve yakamozları Uçuyorlar denizin bittiği yerden Gagaları çiziyor suları Kanat vuruşlarıyla oyuluyor iskele ...', ARRAY['Türk Edebiyatı','Şiir','Musa Öz']::text[], 8.5, '{"poet":"Musa Öz","poet_slug":"musa-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ela-bir-guz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hareli Yazlar', 'hareli-yazlar-musa-oz-c0ajr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Söylüyor da şiirleri

Çoğaltıyor soluğu Akdeniz’in

Bin yıl dinliyorum çocukça

En haram elalarıyla el ele

Hareli bakıyor bakınca

Atıyorlar kimi de bir ülkeden

İncecik iller büyütüyor

Yaralı turnalar telinde

İz biriktiriyor dişlerinde

Ah zehirli memeleriyle

Emziriyor da özışığını

Ölü olarak geçiyor ele

Usulca örtünüyor dikenlerini

Bir hoyrat at oynuyor

Gökçe gül koynunda

Yaz anlatıyor seviniyorum

Hayal olsa da', 'Söylüyor da şiirleri Çoğaltıyor soluğu Akdeniz’in Bin yıl dinliyorum çocukça En haram elalarıyla el ele Hareli bakıyor bakınca Atıyorlar kim...', ARRAY['Türk Edebiyatı','Şiir','Musa Öz']::text[], 8.5, '{"poet":"Musa Öz","poet_slug":"musa-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hareli-yazlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hangi Birine Yanayım', 'hangi-birine-yanayim-ali-kilic-kakiz-gqn6h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ayak üstü peronlarda aç susuz beklersin. 

Yesin yatsın keyf çatsın, perişan sensin.

Dörpülenen ömrüm tirenlerde mi geçsin 

Günahlarıma mı,çocuklarıma mı yanam. 

Dökülen alın teri,  hiç artmıyan aylık.

Hayat zor, engebeli, hepsi taşlı kayalık. 

Yok bu diyarda deryada mutluluk, sağlık.

Hasta anama mı,kaybettiklerime mi yanam, 

Sadece senmisin ağlayan,hepsi gidecekler. 

Hayat çölünde çektiğim ah ve kederler, 

Rahat bırakmazlar, dert ederler. Seyrederler.

Bağdat''dan,Medineden ayrıldığıma mı yanam.

Nankör insan inatlaştımı asla gelmez beri.

Yok suçum yıllarca kazandığım yalnız alın teri. 

Hani  derlerya,  eşek ölsürse kalır semeri.

Bıraktıklarıma mı vazgeçtiklerime mi yanam. 

Midi Bruxelles /1985', 'Ayak üstü peronlarda aç susuz beklersin.  Yesin yatsın keyf çatsın, perişan sensin. Dörpülenen ömrüm tirenlerde mi geçsin  Günahlarıma mı,ço...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç Kakiz']::text[], 8.5, '{"poet":"Ali Kılıç Kakiz","poet_slug":"ali-kilic-kakiz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hangi-birine-yanayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yad Zamanı', 'yad-zamani-ahmet-aksoy-2o8vi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bileyini yitiriş çocuk gözleri

ufaktın büyüdün

eski  yazlardan kalma bir çağrı

.....ellerindeki şaşkın tüyler

babanın duyarlılığı oğulda yoktur

.........ne kadar uzak görünürse yolu

o kadar az farkındadır insan 

......................ölümü

nerede kaldı o ilk sorular

......hayata karşı bir savcı

her şey ama her şey

.........yerini zamana bıraktı

şimdi bu zamanlar

........yad zamanı', 'bileyini yitiriş çocuk gözleri ufaktın büyüdün eski  yazlardan kalma bir çağrı .....ellerindeki şaşkın tüyler babanın duyarlılığı oğulda yok...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yad-zamani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alda Gel', 'alda-gel-ali-kilic-kakiz-jdem7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hazırlarız öğleye yaprak döner,

Terle dur bunun neresi hüner

Yanar mı gazyasız fitilsiz fener,

Terini silmek için peşkiri alda gel.

İçtikleri sprait,fanta,Turka cola,

Sanki ne kazanıyoruz ver dur mola,

Geceleri dönersin rengin sola sola

Yorgunum, yatağı yorganı sırtlanda gel.

Şatışımız  kâh eksilir kâh artar,

İkisi de acemi  hepsini karışık satar,

Böyle giderse  bu dükkân batar 

Gel kardaş bu işi bir bilene soralım.

Gel görki  günü güne ekliyoruz,

Sabah akşam  müşteri bekliyoruz,

Takatımız yok, vergisini ödeyemiyoruz,

Ya muallim,rehberi kılavuzu alda gel,

Yokmu babandan kalan bir servet 

Sıkma canını,etme kendine dert,

İnsan, bazen yumuşak bazen sert

Bildiğin sureleri, duâları oku da gel.

Dilbeek / Brüksel 2004', 'Hazırlarız öğleye yaprak döner, Terle dur bunun neresi hüner Yanar mı gazyasız fitilsiz fener, Terini silmek için peşkiri alda gel. İçtikler...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç Kakiz']::text[], 8.5, '{"poet":"Ali Kılıç Kakiz","poet_slug":"ali-kilic-kakiz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/alda-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** E l v e d a', 'e-l-v-e-d-a-metin-eser-5u7tt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir tren rayına bıraktım seni,

Söylemem hangi güzergâhta,

Çok değil birkaç dakika sonra,

Herşey bitecek bir an bir solukta.

Çırpınışın son nefeslerindir, 

Sızısı acıdır, belki derindir,

Kalp denen o sırça saray var ya,

Senin hiç uğramadığın yerindir.

Beklenen o tren, geldi gelecek,

Bir demir yığını üzerinden geçecek,

Sen ve bıraktığın ne varsa geride,

Kül kül olup, rüzgara serpilecek.

..................

..................

..................

E L V E D A

27.06.04 / Mörfelden-Walldorf', 'Bir tren rayına bıraktım seni, Söylemem hangi güzergâhta, Çok değil birkaç dakika sonra, Herşey bitecek bir an bir solukta. Çırpınışın son n...', ARRAY['Türk Edebiyatı','Şiir','Metin Eser']::text[], 8.5, '{"poet":"Metin Eser","poet_slug":"metin-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/e-l-v-e-d-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** Oyuncak Bozuldu', 'oyuncak-bozuldu-metin-eser-nqu25', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Son seslenişimdir sana,

Bu son ibrettir,

Duyduğun şu sözler,

Sende sîrettir,

Anla ki artık, ben yokum Sende,

Dahası bir Sen, kalmadı Bende,

Son seslenişimdir Sana,

Bu son sözümdür,

Benim içimse rahat,

Sende hüzündür.

İşte Sana ser levha,

Oku oku ve oku,

Hiç görmedin bilirim,

Böylesine bir şoku.

Oyuncağın bozuldu,

Tamiri olmuyormuş,

Avrupa malı bul artık,

Hem hiç bozulmuyormuş.

Üstelik

Garantisi ömür boyuymuş.

27.06.04 / Mannheim', 'Son seslenişimdir sana, Bu son ibrettir, Duyduğun şu sözler, Sende sîrettir, Anla ki artık, ben yokum Sende, Dahası bir Sen, kalmadı Bende, ...', ARRAY['Türk Edebiyatı','Şiir','Metin Eser']::text[], 8.5, '{"poet":"Metin Eser","poet_slug":"metin-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/oyuncak-bozuldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Ben Köpeklerden Hiç Korkmam', 'ben-kopeklerden-hic-korkmam-guclu-sonmez-yp7f3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kiminle yarıştın ve kendini karşılaştırdın

Bari söyleseydin kimbilir belki de onu severdim

Kendini kendinden kıskandın ve çabuk parladın

Seni söndürmekten bir yudum su bile içemedim 

Ulaşmaya çalışıyorum düşüncelerimin en derinlerine

Bulmak için paylaştığım güzel bir anı seninle 

Silene kadar çektirdiğin işkenceleri yüreğime

Polis beynim kapatmış o yolları kaza olmasın diye 

Binlerce ‘seni seviyorum’ vardı ceplerimde 

Çıkmadı yola senin için bir tanesi bile 

Aylarca yetiştirdiğin kin ve nefreti

Sonunda bırakmaya geldin aşk! mızın meyveleri diye

Ama biliyorsun...

Ben köpeklerden hiç korkmam

Havlamalarına da aldırmam

Isırsalar da 

Parçalasalar da

Ne farkeder ki

Herşey yalan

(Istanbul, Haziran 2004)', 'Kiminle yarıştın ve kendini karşılaştırdın Bari söyleseydin kimbilir belki de onu severdim Kendini kendinden kıskandın ve çabuk parladın Sen...', ARRAY['Türk Edebiyatı','Şiir','Güçlü Sönmez']::text[], 8.5, '{"poet":"Güçlü Sönmez","poet_slug":"guclu-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ben-kopeklerden-hic-korkmam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevmek Ne Kolay', 'seni-sevmek-ne-kolay-i-smet-barlioglu-11rn2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sesin güzel, yüzün ak,

Sanki suda bir zambak

Aynadan daha parlak,

Seni sevmek şok kolay.

Kokun sanki bir ıtır,

Koklayanı bayıltır,

Yürekleri kanatır,

Seni sevmek ne kolay.

Yüzün körpe bir bahar,

Ha ağladı, ha ağlar,

Sesin su gibi çağlar,

Seni sevmek ne kolay.

Adımların küçücük,

Dudağında gülücük,

Gülüşün bir öpücük,

Seni sevmek ne kolay.

Kelebekten körpesin,

Güzel, kibar, incesin,

İnsan nasıl sevmesin,

Seni sevmek çok kolay.

(MELEKLEŞMİR MERMERLER isimli hece şiirlerinden > 95-96/100)', 'Sesin güzel, yüzün ak, Sanki suda bir zambak Aynadan daha parlak, Seni sevmek şok kolay. Kokun sanki bir ıtır, Koklayanı bayıltır, Yürekleri...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/seni-sevmek-ne-kolay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göreyim', 'goreyim-i-smet-barlioglu-6ox84', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bülbülleri sorma, başka güldedir,

Çektirdiğin azap gönüllerdedir,

Kalbimi arama, başka eldedir,

O tatlı günleri bul da göreyim.

Kulun kölen oldum, hiç yüz vermedin,

Harcadım ömrümü, gün göstermedin,

Açık kollarımı asla görmedin,

Sen de bir başına kal da göreyim.

Bilmezsin kalp nasıl yanar alevle,

Can nasıl boğuşur bomboş bir evle,

Kölen savaşırken can verdi, devle,

Şimdi saçlarını yol da göreyim.

Ben kışı yaşarken baharlardaydın,

Ben azap çekerken uzaklardaydın,

Vermiştim gönlümü, tutup alaydın,

Gönlüm burda ama al da göreyim.

Yine de sanmam ki izim silinsin,

Yaptığım ikramlar geri verilsin,

Sanmam ki hayalim geri çevrilsin,

Bensiz bir mutlu ol, ol da göreyim.

(MELEKLEŞMİŞ MERMERLER isimli hece şiirlerinden > 97-98/100)', 'Bülbülleri sorma, başka güldedir, Çektirdiğin azap gönüllerdedir, Kalbimi arama, başka eldedir, O tatlı günleri bul da göreyim. Kulun kölen ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/goreyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tablo Gibisin', 'bir-tablo-gibisin-i-smet-barlioglu-c8998', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir tablo gibisin kumlu sahilde,

Arkanda martılar çığlık çığlığa.

Güneş yeni battı denizde hem de,

Ara vapurları ıslık ıslığa.

Beyaz köpüklerde çiçek gibisin,

Yaprağın yeşile çalan sulardan.

Yıldızlar altında ipek gibisin,

Saçakların simli, ince kumlardan.

Üstten çiseliyor saçına yağmur,

Ayın ışıkları yanaklarında.

Sular omuzunda kırılmış billur,

Nasıl kurban olmam ayaklarına? 

Sakın kıpırdama, bakayım bırak,

Kalbim yanacakmış, yanarsa yansın.

Gönlüm bilme oldu ne dur, ne durak,

Bu zorlu özleme nasıl dayansın? 

(Hikmet BARLIOĞLU (1933 - 2003) '' nun

MELEKLEŞMİŞ MERMERLER isimli Hece Şiirlerinden > 99-100/100)', 'Bir tablo gibisin kumlu sahilde, Arkanda martılar çığlık çığlığa. Güneş yeni battı denizde hem de, Ara vapurları ıslık ıslığa. Beyaz köpükle...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-tablo-gibisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm ve Şehadet', 'olum-ve-sehadet-ahmet-ersin-tasel-ebl6h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ölüm önde gider

Yetişmek için koşarken

Göze

Ölüm önde gider

Arkasından bakarken 

Öze

Ölüm önde gider

Gidenim gelmeyince

Söze

.....

Varlığım varlığına işaret 

Varlığında varlığım

Yokluktan ibaret

Varlığın şayet

Varlığın varlığına

Şehadet', 'Ölüm önde gider Yetişmek için koşarken Göze Ölüm önde gider Arkasından bakarken  Öze Ölüm önde gider Gidenim gelmeyince Söze ..... Varlığım ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ersin Taşel']::text[], 8.5, '{"poet":"Ahmet Ersin Taşel","poet_slug":"ahmet-ersin-tasel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olum-125-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrüm Su Gibi Aktı', 'omrum-su-gibi-akti-i-smet-barlioglu-c61u6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ömrüm su gibi aktı köprülerin altından

Yaralı yüreğimi taşlara vura vura.

Seni sevdiğim için delice aşık oldum

Karanlık gecelere, rüzgarlara, yağmura.

Yağmur çiseledikçe yanımda, karşımdasın,

Damlacıklar halinde saçımda, başımdasın,

Benim için sen hala o eski yaşındasın,

Zamanları durdurdum hayaller kura kura.

Ne kadar acı şeymiş sevip de görememek,

Çiçeklenmiş yollarda el ele verememek,

Eski güzel günlere bir daha dönememek,

Yoruldum rüyaları hayıra yora yora.

Bilmem tatlı sarılar renk midir, saçın mıdır? 

Sevda ölümden zalim, ölümden hırçın mıdır? 

Sevmek eğer suç ise bir benim suçum mudur? 

Yıllarımı tükettim kendime sora sora.

(SAÇIMIZ BİRLİKTE BEMBEYAZ OLSUN isimli hece şiirlerinden > 7-8/100)', 'Ömrüm su gibi aktı köprülerin altından Yaralı yüreğimi taşlara vura vura. Seni sevdiğim için delice aşık oldum Karanlık gecelere, rüzgarlara...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/omrum-su-gibi-akti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kül tutuşur sanma', 'kul-tutusur-sanma-zafer-zengin-etnika-kn709', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dilime sürmüşüm acıyı

Elim sigarayla yandı

Kül tutuşur sanma

Uzak  duruyorsa

Aşk''a

Çay için ateş gerek

Hadi iki şeker at içek

İmlası bozuk/Şiir/Küsmez

Aşk''da

Adam doymuyor

Kadına

Kadını hayat sanma

Aşk adı

ne de olsa

Hadi tut

Sevmek gerek

Demli çay gibi

içek

Aç şiirler/Yazmaya doymaz/Düş(müş) üm

27 Haziran 2004 '' Gül yanarken ağlamaz ''', 'Dilime sürmüşüm acıyı Elim sigarayla yandı Kül tutuşur sanma Uzak  duruyorsa Aşk''a Çay için ateş gerek Hadi iki şeker at içek İmlası bozuk/Ş...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kul-tutusur-sanma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Mektup', 'sevgiliye-mektup-fatih-konuk-9vhxj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey benim güzel sevgilim! 

Sana olan özlemimi nasıl anlatacağımı bilemiyorum

Ama seni herşeyden çook sevdiğimi söylemek isteiyorum

Senin yokluğuna,benim yanlızlığıma dayanamıyorum

Sana yazıyorum bu mektubumu gözyaşlarımla

Birgün dönmeni,

Beni tekrar sevmeni,

Benim olmanı istiyorum

El ele tutuşup derdimi sana açmayı,

Sana*seni seviyorum*demeyi istiyorum.

Gözlerini özledim denizin mavisini aldığı için,

Saçlarını özledim güneşin sarısını aldığı için

Dön artık bana ne olursun 

Her zaman gözlerimden yaşlar akmamasını istiyorsan,

Beni birazcık olsun seviyorsan

Dön artık bana ne olursun 

Tahamülüm kalmadı bu yanlızlığa,

İsyan eder oldum bu anlamsız ayrılığa

Özledim seni ne olursun anla

Beni bırakıp gittin buralarda

Ne olursun sevgilim dön artık bana 

Dön artık bir tanem,dön artık gülüm,

Gel de bitsin şu acı günlerim

Gelde gülsün bu gözlerim

Artık anla sevgilim

Mektubuma son verirken

Seni sevdiğimi söylemek istiyorum

Seni seviyorum

Seni seviyorum.....

___________________________________', 'Ey benim güzel sevgilim!  Sana olan özlemimi nasıl anlatacağımı bilemiyorum Ama seni herşeyden çook sevdiğimi söylemek isteiyorum Senin yokl...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sevgiliye-mektup-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koparılacak Elma', 'koparilacak-elma-ufuk-nazim-ok2sd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşamdan koparılacak

Çok şey var.

Güneşli bir günde

Elmalar 

Sarkarken dallardan.

Elbet bize de düşecek

Alında sonuna ermiş

Bir elma.', 'Yaşamdan koparılacak Çok şey var. Güneşli bir günde Elmalar  Sarkarken dallardan. Elbet bize de düşecek Alında sonuna ermiş Bir elma....', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/koparilacak-elma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savaş Olmasın', 'savas-olmasin-fatih-konuk-xk7zh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine bir savaş olursa

Binlerce insan ölecek

Bir bomba ile bir ülke yıkılacak

Bombanın sonrası; 

Bir yanda zaferin kutlanması

Bir yanda bir yanda ölümler

Bir bomba patlayacak ve bedenler parçalanacak

Ortalık kıyamet havasına dönecek

Feryatlar,figanlar,ağıtlar ve gözyaşları.....

Yine bir savaş olursa

Olanlar yaşlı analara,babalara,

Kadınlara ve çocuklara olacak olanlar

Bir çocuğun anne diye ağlayışı olacak

Annesini arayacak o kıyamet havasının olduğu yerde

Elinde oyuncağı ve birşey bilmeden etrafına bakınacak

Boş boş

Belki de annesinin veya babansının cesidini görecek

Gözleri önünde

Ve ondan sonra yüreğinde bir intikam almak olacak

Yine bir savaş olursa 

Çığlıklar ortalığı saracak

Ambulansların sesleri,

Sirenin çalması

Yürekleri parçalayacak

Ve herşey olup bitecek

Bir yaşlı ana eli yüzünde gözyaşları dökecek

Sevdikleri için

Hüngür hüngür ağlayacak,ağıtlar yakacak

O ana ağlarken yanı başında tabutlar kaldırılacak

İçinde belki oğlu,belki kızı olacak

Ama o bilmeyecek kendi evladı olduğunu

Ellerini semaya açıp Allah''a yalvaracak

Gelin dünyalar birleşip SAVAŞA HAYIR! diyelim

Tek vücüd olup davamızdan vazgeçmeyelim

Ölümler olmadan........

Savaş olmasın 

Savaş olmasın

Ve savaş olup bitecek ortada kalan tablo

Yıkılmış evler,yerlerde kanalar

Ve savaşı anlatan resimler

Savaş olmasın

Canlar yanmasın', 'Yine bir savaş olursa Binlerce insan ölecek Bir bomba ile bir ülke yıkılacak Bombanın sonrası;  Bir yanda zaferin kutlanması Bir yanda bir y...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/savas-olmasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Josef', 'sen-josef-ufuk-nazim-i1ypm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Derin bir yapı

Dördüncü köşesi kayıp

Bir dikdörtgen.

Uzun iki kolunda

Işıl ışıl

Onlarca pencere.

Ortada ki 

Kısa kenarda 

Camlar 

Gizemli bir karanlığa

Boyanmış.

Üst katlar da

Geçmiş den bakan 

Küçük pencereli

Sığınalı sı çatı katları. 

Ve önünde

Sen Josefin heykeli

Önündeki havuza bakıyor

Yüzünde uçuk bir hüzün

Elinde zeytin dalından

Bir asayla

Tanrısını gösteriyor.', 'Derin bir yapı Dördüncü köşesi kayıp Bir dikdörtgen. Uzun iki kolunda Işıl ışıl Onlarca pencere. Ortada ki  Kısa kenarda  Camlar  Gizemli bi...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sen-josef-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şey Anlat', 'bir-sey-anlat-fatih-konuk-f7rvp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Birşey anlat dostum acımı dindiren

Birşeyler anlat

Saatler su gibi akıp gitsin 

Boşver dostum

Saatler isterse gece yarısını bulsun

Sen yeter ki birşey anlat

Aşkı anlat dostum! 

Sonu ayrulık olmayan aşkı anlat

Gözyaşı,hüsran olmayan aşkı anlat

Sevenin sevenine kalbinden duyduğu aşkı anlat

Sevmeyi anlat dostum! 

Delice sevmeyi,kalbten sevmeyi

Ve gönülden sevmeyi anlat,

Hayatı anlat dostum! 

Hayatın zorluklerını anlat

Bir kuruş paranın ne zorluklarla 

Kazanıldığını anlat

Parayı anlat dostum! 

Insan insanlğını para için sattığını anlat

Paranın her yerde geçmediğini anlat

Dostlukta,sevgide,aşkta geçmeyen parayı anlat

Paranın her yerde anahtar olmadığını anlat

Arkadaşlığı anlat dostum! 

Kopulmayan,delicesine bağlı bir arkadaşlığı anlat

Kardeşlikten de öte olana arkadaşığı anlat

Işte bunları anlat dostum

Gerçekleri anlat dostum

Herşeyin hayal olmadığını anlat', 'Birşey anlat dostum acımı dindiren Birşeyler anlat Saatler su gibi akıp gitsin  Boşver dostum Saatler isterse gece yarısını bulsun Sen yeter...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bir-sey-anlat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhtacım Sana', 'muhtacim-sana-fatih-konuk-1uhij', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kurudu dalım yaprağım

Muhtacım sana anla

Kurudu dilim damağım

Muhtacım sana anla

Muhtacım ellerine

Muhtacım gözlerine

Muhtacım sözlerine

Muhatacım sana muhtacım

Çıkarmadım seni kalbimden

Düşürmedim adını dilimden

Sevmişim seni taa yürekten

Muhtacım sana anla

Muhtacım bakışına

Muhtacım gülüşüne

Muhtacım aşkına

Muhtacım sana muhtacım', 'Kurudu dalım yaprağım Muhtacım sana anla Kurudu dilim damağım Muhtacım sana anla Muhtacım ellerine Muhtacım gözlerine Muhtacım sözlerine Muh...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/muhtacim-sana-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Ayrıldık Biz', 'neden-ayrildik-biz-fatih-konuk-302tk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', ',Mutlu günler düşlerken

Bir anda çekip gittin

Düşlerimiz gerçekleşecekken

Ansızın terkedip gittin

Neden ayrıldık biz söylesene

Nedendir bu ayrılığın sebebi

Neden ayrıldık biz konuşsana

Gözlerin konuşmasın sen konuş

Derdini anlatmak,

Oturup konuşmak,

Içini dökmek varken

Neden bırakıp gittin

Neden ayrıldık biz neden neden

Nedir böyle bırakmanın sebebi

Neden ayrıldık biz cevab versene

Neden neden neden ahh neden? ? ? ?', ',Mutlu günler düşlerken Bir anda çekip gittin Düşlerimiz gerçekleşecekken Ansızın terkedip gittin Neden ayrıldık biz söylesene Nedendir bu a...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/neden-ayrildik-biz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teşekkür Ederim', 'tesekkur-ederim-fatih-konuk-8pu0y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bana en büyük mutluluğu tattırdığın için,

Bana en güzel günleri yaşattığın için

Teşekkür ederim

Bana en güzel zamanları paylaştığın için,

Bana en tatlı hayaller düşlettiğin için

Teşekkür ederim

Dertlerime ortak olduğun için,

Gönlüme sultan olduğun için

Teşekkür ederim

Ellerimi tutuğun için,

Gözlerime baktığın için,

Bana aşkı öğrettiğin için

Teşekkür ederim

Üşüdüğümde nefesinle ısıttığın için,

Yüreğime SEVGİyi koyduğun için

Teşekkür ederim', 'Bana en büyük mutluluğu tattırdığın için, Bana en güzel günleri yaşattığın için Teşekkür ederim Bana en güzel zamanları paylaştığın için, Ba...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tesekkur-ederim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Rüzgar', 'mavi-ruzgar-zeki-ergin-qoyyz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'denizden esen

ey mavi rüzgar

sarıp sarmalayalım sevdalarımızı

Egenin nazlı dalgalarıyla

bir şiir olsun

hüzünlü tarafından

ey aşk

elimizden kayan yıllara

bir sen direndin 

zamana

Egede 

özlemler

bu güne taşındı

yıllandı şarap oldu

Yorgonun bağında

yüreklerde 

şarkı türkü oldu

efelerin sazında

muhacir yollarında

_erenköy  27haz04

_dağlara ver sırtını yt:haz09', 'denizden esen ey mavi rüzgar sarıp sarmalayalım sevdalarımızı Egenin nazlı dalgalarıyla bir şiir olsun hüzünlü tarafından ey aşk elimizden k...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mavi-ruzgar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurşun Yedi Sol Yanım', 'kursun-yedi-sol-yanim-kamil-aydemir-xkntm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bu beden dayanmadı mı sıvas’da yakılan canlara

postallı şafaklarda dar ağaçlarında sallananlara

istanbul’da paramparçalananlara

ve geldi buralara

ben alışkınım yüreğimi avuçlayıp gezmelere

bugün ölü bir cumartesi

artık sevda türküleri de çığıramayacak

kurşun yedi sol yanım

hayatın yolunda bu da varmış

canın sağolsun sevdiğim

mahzen gönlüne göm beni

                       26 / 6/ 04  (Cumartesi)', 'bu beden dayanmadı mı sıvas’da yakılan canlara postallı şafaklarda dar ağaçlarında sallananlara istanbul’da paramparçalananlara ve geldi bur...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kursun-yedi-sol-yanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçurumda bir adam', 'ucurumda-bir-adam-mustafa-tugrul-kosar-ct2nk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir adam gördüm

Gün batarken bugün

Tırmanan toprak patikanın sonunda

Uçurumun kenarında

Darmadağan uçuşuyordu saçları

Uzun paltosunu kanatlandırıyordu rüzgar

Elleri cebinde kenti seyrediyordu

Umrunda değildi taşıtların sesleri

İnsanların koşuşturması değildi seyrettiği

Güneşe değiyordu başı gördüğüm kadarıyla

Hafiften beyaz saçlarıyla,

İplik iplik dökülen göz yaşlarıyla

Önündeki kuru dikenleri suluyordu sanki

Izdıraplara meydan okur gibiydi

Ağır ağır sallanırken,

Direniyordu düşmemek için

Zaman zaman fırtınalaşan rüzgara aldırmıyordu

Aldırmıyordu gözlerini kapatan uzun saçlarına

Kimdi? Kimin nesiydi? 

Belki ihanet, belki gönül yarası,

Yada gurbet özlemiydi onu buralara kadar iten

Gözleri rengarenk duman çıkaran,

Uzak fabrikalara bakıyordu

Koyu,mat  dağlarla birleşen fabrikalar

Anlıyordum başka dünyalar düşünüyordu yalnızlığıyla

Birşeylerden kaçmak,

Birşeyleri unutmak istiyordu

Suskun suskun geçerken üstünden karartılı bulutlar

Duyuyordum yüreğinde çığlıklar kopuyordu

Sonra ufuktaki incecik yola çevirdi başını

Yolun kenarında boncuk gibi  ışıklar

Omuzları yükseldi birden

Tuttu nefesini

Çıkardı cebinden ellerini

Üfledi avuçlarını

Ürpertilerden kaçıp koşmaya irkildi bir an

Ayağının altında görünce uçurumdaki şehri

Oturup yavaşca olduğu yere

Çaresizliğini garipseyip

Dizlerine dayadı dirseklerini

Birleştirip ellerini başında

Usulca eğilip saatlerce ağladı', 'Bir adam gördüm Gün batarken bugün Tırmanan toprak patikanın sonunda Uçurumun kenarında Darmadağan uçuşuyordu saçları Uzun paltosunu kanatla...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tuğrul Koşar']::text[], 8.5, '{"poet":"Mustafa Tuğrul Koşar","poet_slug":"mustafa-tugrul-kosar","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/ucurumda-bir-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirin akşamı', 'siirin-aksami-mustafa-tugrul-kosar-favhl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yoksullaşan mavi birazdan dönüşür karanlığa

Güneş başka kıtalara gider

Başka sevdaları aydınlatmaya

Öksüz kalmış duygularım çıkar su yüzüne

Böceklerin ağıtları eşliğinde kabarır ilhamlarım

Akşam doğasının ürkek kokusu uysallaştırır acılarımı

Yıldızlar gibi çoğalır birden dilimde cümleler

Tek bir odaya toplanır bütün karanlıklar

Matem siyahlarını giyinir güzelliklerim

Yalnızlığım gelir oturur karşıma,

Şöyle bir sıvazlar tesellilerimi

Can evimden geçer gider sevgilerim

Avuçlanmış alevden köz gibi

Yanar duygularımın özündeki harfler

Gebe kalmış taakatsizlikler gelir ziyaretime

Kan çanağı,

Kızıl gözlü feryatlarımla bakışır avuntularım

Yankılanan ayin mi desem

Yada bir musiki mi desem

Artar sonsuzluğun suskun dilinde

Raks ederken kağıdın üstünde kalem

Aşka gelir

Gözden süzülen  yaş misali,

Dökülür olduğu gibi kağıda kelimeler', 'Yoksullaşan mavi birazdan dönüşür karanlığa Güneş başka kıtalara gider Başka sevdaları aydınlatmaya Öksüz kalmış duygularım çıkar su yüzüne ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tuğrul Koşar']::text[], 8.5, '{"poet":"Mustafa Tuğrul Koşar","poet_slug":"mustafa-tugrul-kosar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/siirin-aksami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Hadi Ama', 'hadi-ama-ahmet-turan-altunsu-uz9l0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '….(gönül bu, azıverdi / destursuz yazıverdi!)

dinle bak kimsecikler yok

aşk şimdi bambaşka

herkes çekilmiş bir köşeye,

herkes kendi havasında! ..

kapılar açık aşka! 

kimse yok bizden başka! 

heves çok; 

görürlerse görsünler, azalım! 

bir destan yazalım ki

dillere destan olsun:

yazalım! ..

okuyanlar hayran olsun! 

hadi kız, direnme, gel! ..

kıpraş biraz, kıvran biraz…

coşmak vakti geldi.

düşünsene bizsiz geçen

bu kaçıncı yaz? ..

bak, açtım kucağımı; 

atla, fırsat bu fırsat! 

ne itiraz var, ne engel! ..

üstündekileri çıkar! 

kapat ama o ışığı,

perdeleri de kapat! 

hani o kadar da demedik! 

gerçi yerin de kulağı var

fakat

dayanamıyorum artık,

boş yatağın tadı yok:

hadi atla, son fırsat! ..

           25.06.2004 / Ankara', '….(gönül bu, azıverdi / destursuz yazıverdi!) dinle bak kimsecikler yok aşk şimdi bambaşka herkes çekilmiş bir köşeye, herkes kendi havasınd...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/hadi-ama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Tehir', 'son-tehir-ahmet-turan-altunsu-if8gb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '….(sana olduğunu biliyorsun/ onun için mi hin hin gülüyorsun? / çen çen ağlayacağın gün de gelir güzelim? ! .)

El bebek gül bebek besledim seni,

Doyurdum ruhunu aşk sihiriyle…

Kalbimin tahtına sesledim seni

Bir başka sevginin son tehiriyle! 

Son söz senin, artık tahammülüm yok,

Çok naz, bezdirirmiş aşığı, he mi? 

Bundan böyle aşıklara zulüm yok:

Sabır, ezdirirmiş aşığı, he mi? 

Sabır bitti canım, gerçeğe dön, gel! 

Artık çok yoruldum, derim ki sen gel! 

Olmazsa, elimde tuttuğum çengel

Tutturur bedene kuşağı, he mi? 

Turan der ki son söz söylendi gayrı,

Uygun bir şey söyle, görelim hayrı,

Eğer ki öyleyse sen ve ben ayrı,

Sallarız hüsranla beşiği, he mi? ..

                       25.06.2004 / Ankara', '….(sana olduğunu biliyorsun/ onun için mi hin hin gülüyorsun? / çen çen ağlayacağın gün de gelir güzelim? ! .) El bebek gül bebek besledim s...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/son-tehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairin Ölümü', 'sairin-olumu-ahmet-turan-altunsu-1hvh0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'mangal gibi bir yüreği vardı…

oylum oylum oydular,

bir döşeğe koydular…

sevgi sarmaşıkları beslenirdi 

…….düne kadar yüreğinden,

şimdi çepeçevre ökse otları sardı…

dostları gün saydılar…

cananı can sayardı; 

onun dilinden öldü! ..

canan anladı mı bilmem:

ölümü intihardı! ..

                  26.06.2004 / Ankara', 'mangal gibi bir yüreği vardı… oylum oylum oydular, bir döşeğe koydular… sevgi sarmaşıkları beslenirdi  …….düne kadar yüreğinden, şimdi çepeç...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sairin-olumu-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sırıtırım', 'siritirim-ahmet-turan-altunsu-otzcl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sana rağmen seni sevdiğimi biliyorsun,

bana rağmen beni öldürüyorsun! 

aklımı sana verdim…

dövdün ruhumu bir dibekte,

sallayıp karıverdin,

toplayıp sarıverdin! ..

şimdi dibek bile paramparça, kırım kırım…

ben geberdim! ..

mutlu oldun umarım…

o tarafta sanma ki kederimden ağlarım,

bilmez misin be kadın:

kederimden sırıtırım? ! .

                      26.06.2004 / Ankara', 'sana rağmen seni sevdiğimi biliyorsun, bana rağmen beni öldürüyorsun!  aklımı sana verdim… dövdün ruhumu bir dibekte, sallayıp karıverdin, t...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/siritirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayınvalidem - 12 / anı', 'kayinvalidem-12-ani-k-muran-esen-1vvfc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir akşam misafirimiz var. Yemeğimizi yedik, kahvelerimizi içtik, sohbet ediyoruz. İşte  herkes birşeyler anlatıyor. Kimi, başından geçen ilginç bir olayı anlatıyor; kimi fıkra anlatıyor, kimi taklit yapıyor falan.

Derken bir arkadaşımız çok komik bir fıkra anlattı. Bir kahkaha koptu ki odada, sormayın gitsin. Millet çatlayacak gülmekten. Bir baktım kayınvalidem bayılacak neredeyse, o kadar gülüyor.Gülmekten akan gözyaşlarını başındaki yemenisi ile siliyor. Yani anlatılan fıkra, en çok onun hoşuna gitmiş.

Gülmesi geçtikten sonra  bana eğilip, fıkra anlatan arkadaşımızı göstererek  sordu:

-	“ Kemraan!  Neye güldünüz o gadar? Ne anlattı bu? ”.

Dayanamayıp sordum:

-	“ Eeeeee! Siz niye güldünüz ki? ”

Şöyle yanıtladı kayınvalidem:

-	“Ne bilim (bileyim)  ben! Siz güldünüz deye ben de güldüm.', 'Bir akşam misafirimiz var. Yemeğimizi yedik, kahvelerimizi içtik, sohbet ediyoruz. İşte  herkes birşeyler anlatıyor. Kimi, başından geçen il...', ARRAY['Türk Edebiyatı','Şiir','Kâmuran Esen']::text[], 8.5, '{"poet":"Kâmuran Esen","poet_slug":"k-muran-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kayinvalidem-12-ani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Kez Sen Koy Adını', 'bu-kez-sen-koy-adini-ahmet-turan-altunsu-7n47n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sana bu gün dua okudum,

görürsün hayrını belki ey günahkârım! 

bağışla dünkü bedduamı: müsebbibi efkârım! 

dün ben kendimde yoktum,

bir meczup kıvamında, adeta uçuyordum! 

deliliğime ver gitsin…

bir keder mızrabıyla gönül telime vurdum,

hiciv ağıtları yaktım,

kafesimdeki serçeyi azad ettim, uçurdum! ..

dün, ben kendimde yoktum,

bu gün efkârım dağıldı.

serçem döndü kafesine, yuvasıymış yüreğim,

lâkin kırılmış gönül telim…

ağulanmış gibiyim cananın ellerinden,

ölümüme beş kala önümdeki engelim:

ya bir nağme duyarsam gönlünün tellerinden? ..

bende mızrap yok artık,

dokunacak tel de yok! 

beş dakika doluyor, farkında mısın bilmem; 

ben yokum, hâyâl de yok! ..

                                26.06.2004 / Ankara', 'sana bu gün dua okudum, görürsün hayrını belki ey günahkârım!  bağışla dünkü bedduamı: müsebbibi efkârım!  dün ben kendimde yoktum, bir mecz...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bu-kez-sen-koy-adini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acımın Özü', 'acimin-ozu-melek-midikoglu-19fig', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Pervanelerin arasında

Dolandım durdum...

Ve birde baktım ki! 

Küçüldü hayallerim.', 'Pervanelerin arasında Dolandım durdum... Ve birde baktım ki!  Küçüldü hayallerim....', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/acimin-ozu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durağan', 'duragan-umit-terzi-dcsbu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kuş uçmaz kervan geçmez bir dağ başında

Eteklerinde kuru yaprakların oynaştığı bir kulübe

İçinde bitmiş hayallerin külleri

Bekliyor doğmasını kor yuvarlağın.

İç gıdıklayan tutkuların çiçeği,

Kokusu rüzgarda asılı kalmış.

Baştan çıkarıyor yavaş yavaş

Rüzgarda çatırdayan yaşlı çınarı

Damarlarında dolaşan kurtçukların gıdıkladığı çınar,

Koparmak istiyor köklerini

Bir rüyanın bitmemesi için...

Koş koca çınar 

Uç koca çınar

Öl,  koca çınar 

Uğrunda bir anlık özgürlüğün,

Ama ne olur beni bırak...', 'Kuş uçmaz kervan geçmez bir dağ başında Eteklerinde kuru yaprakların oynaştığı bir kulübe İçinde bitmiş hayallerin külleri Bekliyor doğmasın...', ARRAY['Türk Edebiyatı','Şiir','Ümit Terzi']::text[], 8.5, '{"poet":"Ümit Terzi","poet_slug":"umit-terzi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/duragan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal', 'masal-umit-terzi-2uitw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yazıldığı gibi yaşansaydı masallarda

Kim olurdun söyle

Ve kim olurdum? 

Nasıl başlardı 

“Bir zamanlar...”

Ve bitermiydi

“Onlar ermiş muradına...”', 'Yazıldığı gibi yaşansaydı masallarda Kim olurdun söyle Ve kim olurdum?  Nasıl başlardı  “Bir zamanlar...” Ve bitermiydi “Onlar ermiş muradın...', ARRAY['Türk Edebiyatı','Şiir','Ümit Terzi']::text[], 8.5, '{"poet":"Ümit Terzi","poet_slug":"umit-terzi","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/masal-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senle sensiz', 'senle-sensiz-umit-terzi-i693h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öyle huzurluydun ki

Kıyamadım izledim...

Kıvrılmış yatıyordun yanıbaşımda

Kedi gibi sakin, mutlu

Sarmak, sarılmak istedi

Öpmek istedi dudaklarını...

Sadece seyredebildi gönül

Dayanılmaz oldu bir an

Dokunabilecek kadar yakın sen

Acı çeken ben

Attım kendimi dışarıya

Acının dayanılabilir olduğu

Başka yerlere...

Bomboş şimdi odalar

Aldığım nefes gibi anlamsız

Yattığın yastık bir köşede

Kokun sinmiş pijama elimde

Bir burukluk midemde

Ve damarlarımda çekilme...', 'Öyle huzurluydun ki Kıyamadım izledim... Kıvrılmış yatıyordun yanıbaşımda Kedi gibi sakin, mutlu Sarmak, sarılmak istedi Öpmek istedi dudakl...', ARRAY['Türk Edebiyatı','Şiir','Ümit Terzi']::text[], 8.5, '{"poet":"Ümit Terzi","poet_slug":"umit-terzi","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/senle-sensiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki de hiç bilmeyeceksin.!', 'belki-de-hic-bilmeyeceksin-nazife-abayli-svoyf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Belki de hiç bilmeyeceksin.! 

Yokluğunda titrediğimi.

Sevdan ile yandığımı,

Görmeyeceksin..

Kaç gece ağladı  bu yürek? 

Kaç kez sevdiğini söylemek istedi bu dil? 

İstedi de,tutuldu,konuşamadı.

Belki de hiç bilmeyeceksin.! 

Gün batımlarında güneşi izlerken,

Hıçkıra hıçkıra yaş döktü bu gözler.

Kal diyemedi,bakakaldı....

Ben Hazan olduğumda,

Sen! 

Güneşin ardına takılıp giderken..

(Yalova sahilinde güneşin batışını izlerken yazdığım ve 

düzeltme yapmadan hemen yüklediğim bir şiir..Sevgiyle...)', 'Belki de hiç bilmeyeceksin.!  Yokluğunda titrediğimi. Sevdan ile yandığımı, Görmeyeceksin.. Kaç gece ağladı  bu yürek?  Kaç kez sevdiğini sö...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/belki-de-hic-bilmeyeceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek Sevda Masalı', 'gercek-sevda-masali-cafer-tayyar-ozkan-4084a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yelkovanın akreple bir kerecik öpüştüğü,

Günbatımında arzulu dudağın kavuştuğu,

Aşkın ışıl gözden acı yaşlarla savuştuğu,

Saatlerde yazılırdı, gerçek sevda masalı…

Kutsal dileğin canandan umutla beklendiği,

Üryan bedenlerden sevgi çığlığı yükseldiği,

Yüreklerin cehenneme n i s p e t l e yarıştığı,

Vuslatlarla yaşanırdı, gerçek sevda masalı…

Yalan bilmeyen gözünden süzülen bakışlarla,

Sabahın seher vaktinde yenilen lokmalarla,

Şehrin uzak yollarına i ş l e n e n nakışlarla,

Dualarla uzanırdı, gerçek s e v d a masalı…

  

Zamanın direnç kırdığı toz pembe hislerde,

Sevgi dolu bakışları aşkı yücelten sözlerde,

Bir ömürde sığmayanı, yaşayan gönüllerde,

Hayallerle süslenirdi, gerçek sevda masalı…

Tendeki üryan tatlarla, mubah nikah kıyıldı,

Sevdanın taçlı anları, cana g ü n a h sayıldı,

Kaderin soğuk teması, kutlu düğün sanıldı,

Gözyaşıyla yıkanırdı, gerçek sevda masalı…

27 Haziran 2004 Ankara', 'Yelkovanın akreple bir kerecik öpüştüğü, Günbatımında arzulu dudağın kavuştuğu, Aşkın ışıl gözden acı yaşlarla savuştuğu, Saatlerde yazılırd...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gercek-sevda-masali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O şarkıyı', 'o-sarkiyi-mehmet-zeki-akdag-xe8z7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gönlüm o şarkıyı unut sen artık

Çiçeksi köpüklü bir sahimdeki

O tatlı rüyayı tükenmez sandık

Bekleşir bekleşir döneriz belki

Gönlüm o şarkıyı unut sen artık.

Umudumuz dualardan taşardı

Mutluluk şehrine yola çıkardık

Bir alev halkada şafak karardı

Bunca yıl bekleyip ellere verdik

Mutluluk şehrine yola düşerdik.

Hep yorgun akşamlar köhne iskele

Sırlı aynalarda eriyen zaman

Beykoz da mutlu bir tenha iskele

Bir savda yaratır umursamadan

Sırlı aynalarda eriyen zaman.

Sonu çoraklara akan bir selsin

Anayım sen ırak yavrucum

Denizlere inat daha güzelsin

Masallara sığmaz hükmün çocuğum

Anayım senden ırak yavrucum.', 'Gönlüm o şarkıyı unut sen artık Çiçeksi köpüklü bir sahimdeki O tatlı rüyayı tükenmez sandık Bekleşir bekleşir döneriz belki Gönlüm o şarkıy...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zeki Akdağ']::text[], 8.5, '{"poet":"Mehmet Zeki Akdağ","poet_slug":"mehmet-zeki-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/o-sarkiyi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-mehmet-zeki-akdag-s2jwe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir ananın ikiziydik

Bizi bile ayırdılar

Duaya dönen dillerdin

Sözü bile ayırdılar

Yaprağı yitirdi köken

Yetiş artık ulu hakan

Rahlenin dibine çöken

Dizi bile ayırdılar.

Cümle kine sela verdik

Dönülmez bir yola verdik

Son umudu tele verdik

Sazı bile ayırdılar

Kurşunu inkarda fişek

Göze geldi bizim kuşak

Dilsiz mermere döndü aşk

Nazı bile ayırdılan.

Büyü öksüz kuzum büyü

Ninniledik her türküyü

Alafladık yolsuz köyüü

Közü bile ayırdılar.', 'Bir ananın ikiziydik Bizi bile ayırdılar Duaya dönen dillerdin Sözü bile ayırdılar Yaprağı yitirdi köken Yetiş artık ulu hakan Rahlenin dibi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zeki Akdağ']::text[], 8.5, '{"poet":"Mehmet Zeki Akdağ","poet_slug":"mehmet-zeki-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ayrilik-173-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen...', 'sen-derin-deniz-ldicy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen

bıçak ucunde ten

bense giden bir katil

bıçak ağzında

etin anlamına doğru

giden benim

kordaki derin beyazlığa

sonsuz bir uçurum aramaya

gidiyorum.

Olabilirsen,

gel benim uçurumum ol

yada kefenim.

Ben ölümde çekkin

sen cinayette zarf

ödünüm yürekte çömçe.

Yaşamak; 

beni öldürüyor,yokluğum

seni

tenimi keserek arıyorum

elimde işlenmemiş cinayetlerin faturası

yüreğinin esmer döleğinden 

kirli sakallarımla geçiyorum

masun''u aramaya

giden benim

ilahi rahmin avuçlarında patlayan

güneşlerle omuz omuza

çünkü ben gölgenin kafiriyim.

Bursa''da duramıyorum

İzmir''de annem ve aşk var

İstanbul''da kanlıca

Beyrut''a kar yağdı

bana kan...

(arkadaşım iLYaS)', 'Sen bıçak ucunde ten bense giden bir katil bıçak ağzında etin anlamına doğru giden benim kordaki derin beyazlığa sonsuz bir uçurum aramaya g...', ARRAY['Türk Edebiyatı','Şiir','Derin Deniz']::text[], 8.5, '{"poet":"Derin Deniz","poet_slug":"derin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sen-420-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanın İzi', 'zamanin-i-zi-ahmet-aksoy-642xe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'aynada kendini saklar 

....bilinmez asıl niyeti

insan bir camdır zamanla sırlanır

ve onu soymak gizinden

..........çocuklaştırmaktır', 'aynada kendini saklar  ....bilinmez asıl niyeti insan bir camdır zamanla sırlanır ve onu soymak gizinden ..........çocuklaştırmaktır...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/zamanin-izi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölge Oyunu', 'golge-oyunu-ahmet-aksoy-8choq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ışığın ve karanlığın yer değiştirmesi

gölgenin araç olduğu oyunlar

.......belki de ilk isyanı şeytanın

................alacakaranlık insan

bir yanında cennet bir yanında cehennem

...............sırat

..................hayat

masum bir çocuktu o ilk ceren

.........çığlığını 

...............yüreğinde 

........................gizleyen', 'ışığın ve karanlığın yer değiştirmesi gölgenin araç olduğu oyunlar .......belki de ilk isyanı şeytanın ................alacakaranlık insan b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/golge-oyunu-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çınarın Yaprakları...', 'cinarin-yapraklari-i-brahim-ethem-bingul-snbuh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Rüyalarımda bile terk edemediğim

Vazgeçemeyip delice sevdiğim

Aşk öğretmenim,çitlenbiğim

Yoluna yaşamımı serdiğim

Sana gitme bile diyemedim

Sevdiğimi çok söyledim

Sensiz olamam diyemedim

Beni bırakıp gideceğini bilemedim

Kapılıp gittim kara gözlerine

Yüreğimi bırakmıştım ellerine

Bıraktın gittin o çınarın dibine

Sensiz,oldum ben deli divane

Şimdi benim aşkım yaşıyor

O çınar ağacının dallarında

İnan seni bana taşıyor

Yalnız bana saklıyor yapraklarında', 'Rüyalarımda bile terk edemediğim Vazgeçemeyip delice sevdiğim Aşk öğretmenim,çitlenbiğim Yoluna yaşamımı serdiğim Sana gitme bile diyemedim ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cinarin-yapraklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orucum Olsaydın', 'orucum-olsaydin-ferit-teksoy-vos3q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'orucum olsaydın tuttuğum

günün belli saatlerinde yasaklı

bekleseydim yasağın bitmesini özlemle

kavuşsaydım sana

bir bardak suya kavuşur gibi

ya gelebilseydim sana

ya sen bana gelebilseydin

dinseydi susamışlığım akşam vakitlerinde

sıcak bir ekmeği böler gibi aç

iftarım olsaydı gözlerin

ellerinin sıcaklığıyla bitseydi yasak

bir sesle ezan gibi

ızgarada kömür ateşine düşen damlanın

benzeri bir alevle birleşseydi

bir buse tutuşturan yüreğimizi

guguk kuşlu saatin,guguklarıyla

bitseydi orucumuz

bir çilekeşin çilesi biter gibi

ve o açılımla başlayan zaman

akşam vakti,tüm gece boyu

ellerim ellerinde,gözlerim gözlerinde

hiç konuşmasaydık,dursaydı zaman

içseydik sevgimizi,yudum yudum

öyle gelseydi imsak

her gece..

o vakit! ..

çiy yağar gibi', 'orucum olsaydın tuttuğum günün belli saatlerinde yasaklı bekleseydim yasağın bitmesini özlemle kavuşsaydım sana bir bardak suya kavuşur gibi...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/orucum-olsaydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DüNyA', 'dunya-mehmet-selim-tolay-9afab', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her türlü hevesiyle gizemli bir okyanus

bilinir neşesinde nokta nokta kahroluş

yemyeşil iklimlerde yokolan bir varoluş

etrafımda dengesel tastamam bir fanus

DÜNYA! 

Baktıkça aynasında devleşen bir okyanus

yansıyan güzellikler tatlı tatlı kahroluş

yorulan ayaklarda nasırlı bir varoluş

yakınımda şekilsel işlevsiz bir fanus

DÜNYA! 

Balçığında boğulmuş dalgalı okyanus

kasvetli günleriyle parça parça kahroluş

hileli bir oyunda anlamlı bir varoluş

ellerimde kararan bembeyaz fanus 

DÜNYA! 

26.06.2004', 'Her türlü hevesiyle gizemli bir okyanus bilinir neşesinde nokta nokta kahroluş yemyeşil iklimlerde yokolan bir varoluş etrafımda dengesel ta...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Selim Tolay']::text[], 8.5, '{"poet":"Mehmet Selim Tolay","poet_slug":"mehmet-selim-tolay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dunya-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'De bebek', 'de-bebek-zafer-zengin-etnika-tt2uu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'B e b e k

Ölümünden

Hep 

Büyükler

Sorumludur

Y a p ı ş  y a k a l a r ı n a

| Harcınıza karıştırdınız beni

Attınız ıssızlığın ortasına |

De bebek

İçinde c a n

Kaç kere çekip gidecek...

'' Büyüklerin hırsı yüzünden ölen bebelere  ''

20 Haziran 2004 ''Ellerin gül rengi ''', 'B e b e k Ölümünden Hep  Büyükler Sorumludur Y a p ı ş  y a k a l a r ı n a | Harcınıza karıştırdınız beni Attınız ıssızlığın ortasına | De ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/de-bebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümün Soğuk Yüzü', 'olumun-soguk-yuzu-mustafa-toga-v8lk4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sayimbeyli iniş yokuş			

Yayla evi geniş ve loş				

Komam seni bu ellerde			

Geri ver babamı; Tanrım		

						

Sarı saçlar tutam tutam

Kadirli’de kalır bazan				

Konağımıza neşe katan,			

Geri ver babamı; Rabbım.									

Dere kenarı mezarlık				

Sarmaşık, böğürtlen, çalılık			

Ruhu bedenden ayrılık			

Geri ver babamı; Azrail.

				

Sofra serilir akşam erken

Sekiz kardeş hüzünlenen

Benim canım anama sen

Geri ver babamı; Mevlâm.

	

Kısahasanlı ufak çiftlik

Büyütüyor sekiz keklik

Anası var, baba eksik

Geri ver babamı; Yaradan.

	

Toga''m bu sözlerin haktır

Babama özlemim çoktur

Ev ıssızdır babam yoktur

Geri ver babamı; Allahım.

		

Sayimbeyli / ADANA', 'Sayimbeyli iniş yokuş			 Yayla evi geniş ve loş				 Komam seni bu ellerde			 Geri ver babamı; Tanrım		 						 Sarı saçlar tutam tutam Kadirl...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Toga']::text[], 8.5, '{"poet":"Mustafa Toga","poet_slug":"mustafa-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/olumun-soguk-yuzu-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyi Taşımak?', 'neyi-tasimak-baykal-kaanalp-090is', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'demeyi bırak,bırak demeyi

emeği kurtar,kurtar emeği

yemeği taşır,taşır yemeği

emeği kurtar,kurtar emeği

dinlemek o ki,o ki dinlemek

denemek ne ki,ne ki denemek

sevmek ola ki,ola ki sevmek

denemek ne ki,ne ki denemek

yaşamak nedir? nedir yaşamak? 

taşımak neyi? neyi taşımak? 

olmak niye? niye olmak? 

taşımak neyi? neyi taşımak?', 'demeyi bırak,bırak demeyi emeği kurtar,kurtar emeği yemeği taşır,taşır yemeği emeği kurtar,kurtar emeği dinlemek o ki,o ki dinlemek denemek ...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/neyi-tasimak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahpece', 'kahpece-yusuf-ter-9l4hl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sinsi çıyanlar 

Kırk ayaklı yılanlar

Soğurgan gökyüzü

Alabildiğine endişeli

Kapıların ardında

Sessiz, sinsice duruyor

Yüreği masum sevgiye 

Anlamsız düşüverdi yere

Öfke kusuyor, kan olmuş

Çığlıkların arasında aradığı

Yılan sokuveriyor göz demeden

Zehir akıvermiş yiğitlere

Yer gök parçalanıyor

Yağmursuz havada

Dişleri kırılsın zalimin

Çaresiz değildiler

Aslan gibi delikanlıydılar

Kahpece pusuya düştüler

Atıyor nabızları

Paramparça olmadılar

Kenetlenmiş zincir gibi

Boğacaklar yılanı

Sevgiye nişan olmuş

Adımları haykırmak yok

Bozkırların çakıl taşları

Umut yeşeriyor yeniden

Kan damara iniyor

Zehir kendi kendini eritiyor

Hainliğin kapısında

Damlalar serinletsin yürekleri

Kuyruğu koptu yılanların

Dili aktı içine, zehirledi kendini...



 Yusuf  Ter 26.06.04

Saat 23:50 İsviçre', 'Sinsi çıyanlar  Kırk ayaklı yılanlar Soğurgan gökyüzü Alabildiğine endişeli Kapıların ardında Sessiz, sinsice duruyor Yüreği masum sevgiye  ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/kahpece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
