INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devletin Zirvesi', 'devletin-zirvesi-mustafa-toga-ex3um', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ümit verip başımıza gelenler		

Verdiğiniz sözler acep nice oldu.

Yoksulluğa artık paydos diyenler

Yapacağınız işler acep nice oldu.

Önce zamlara paydos diyerek

Vatandaşları kandırdınız tek tek

Medeniyet deyip de gürleyerek

Aldığınız oylar acep nice oldu.

Başbakan koltuğu tatlı mı geldi

Devlet sorunların altında kaldı

Íşsiz kardeşime iş mi sağlandı

Kalkınma planı acep nice oldu.

Aşık Toga’m artık hep bunlar yalan

Mazbatasın yüce meclisten alan

Politika olmuş kuyruklu yalan

Yükselme duygusu acep nice oldu.

Seyhan / ADANA

GÜNÜN SÖZÜ: Dünyanın en yoksul insanı, paradan başka hiçbir şeyi olmayandır.

www.mustafatoga.com', 'Ümit verip başımıza gelenler		 Verdiğiniz sözler acep nice oldu. Yoksulluğa artık paydos diyenler Yapacağınız işler acep nice oldu. Önce zam...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Toga']::text[], 8.5, '{"poet":"Mustafa Toga","poet_slug":"mustafa-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/devletin-zirvesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aman', 'aman-baykal-kaanalp-t35r8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'son sözünü söylediğin zaman

çekip gitmesini bil aman! ! !', 'son sözünü söylediğin zaman çekip gitmesini bil aman! ! !...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/aman-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başkent Ankara', 'baskent-ankara-mustafa-toga-aa4t7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine efkârlandım yeşil sahrada		

Pırıl pırıl yanar başkent Ankara	

Apartmanlar gökyüzünü delende 

Anası kızından güzel Ankara.		

						

Öğrenciler kol kol olmuş dolaşır	

Gençlik parkı neşe ile çınlaşır			

Bekâr, evli, karı koca koklaşır		

Toprakları taştan güzel Ankara.	

Ulus’un da geçilmez insanından	

Kızılay’ı görmek lâzım her yandan		

Cebeci’ye inelim de kaymadan

Çankaya’sı parklardan güzel Ankara.								

Lunaparkı sevindirir gençleri		

Hayat pahalıdır açık kıçları		

Keçiören semtinin yiğit koçları	

Okullardan Orta Doğu güzel Ankara.	

Mayıs 1976 - ANKARA 	

www.togamedya.tr.gg', 'Yine efkârlandım yeşil sahrada		 Pırıl pırıl yanar başkent Ankara	 Apartmanlar gökyüzünü delende  Anası kızından güzel Ankara.		 						 Öğre...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Toga']::text[], 8.5, '{"poet":"Mustafa Toga","poet_slug":"mustafa-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/baskent-ankara-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerimde kal emi..!', 'duslerimde-kal-emi-nazife-abayli-ktwtd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen hep,

Düşlerimde kal emi..! 

Saf,tertemiz aşkım olarak kal.

Kirlenmesin kötü sözlerle,

Ayrılıklarla,

Kırılmasın yüreklerimiz.

Sen hep,

Düşlerimde kal emi..!', 'Sen hep, Düşlerimde kal emi..!  Saf,tertemiz aşkım olarak kal. Kirlenmesin kötü sözlerle, Ayrılıklarla, Kırılmasın yüreklerimiz. Sen hep, Dü...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/duslerimde-kal-emi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokağıma esir düştü damlalar, hem de İstanbul''da', 'sokagima-esir-dustu-damlalar-hem-de-i-stanbul-da-lzcramcil-ceyhun-erdem-n3lxv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Daha üstüme başıma bakmadan sabahın saati,

gülüşün daha aklımdan çıkmadan,

eloğlu sokak sokak kapatmadan memleketim İstanbul''u

sokağıma esir düştü yağmur damlaları,

ay dolu göklerin hürriyetinden,

Taze, yeni dem yaprakları hafif rüzgarla savruldu öte beri dut ağacının

damlalar camdan aşağıya sızıverdi

tenim ürperdi sesinden,

yağmur yüzünü temizleyiverdi memleketimin

üstelik hala gülüşün dudaklarında,

dantelli gömleğini giyiyorsun,

içimdeki tüm iyi hisler sana akıyor gözlerimden,

üstelik hala el oğlu memleketimin sokaklarında...', 'Daha üstüme başıma bakmadan sabahın saati, gülüşün daha aklımdan çıkmadan, eloğlu sokak sokak kapatmadan memleketim İstanbul''u sokağıma esir...', ARRAY['Türk Edebiyatı','Şiir','Lzcramcil Ceyhun Erdem']::text[], 8.5, '{"poet":"Lzcramcil Ceyhun Erdem","poet_slug":"lzcramcil-ceyhun-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sokagima-esir-dustu-damlalar-hem-de-istanbul-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '/Lar', 'lar-ahmet-aksoy-dyyhn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yüzümü saran gölgeler içinde

