INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-- D u d a k l a r ı n..!', 'd-u-d-a-k-l-a-r-i-n-metin-eser-wwdsy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'D u d a k l a r ı n, 

İlk özlemimdi hayallerimin yaşanmışlığına, 

Çöl çiçeği kadar masum, ab-ı hayat gibi berrak, 

Şu utangaç hırçınlıklarımın susamışlığına, 

Tomurcuklar açtırdığın o nadide kızıl toprak. 

D u d a k l a r ı n, 

Vuslata susamış özlem dolu arzular durağı, 

Harladığım yangınların gönüllü tek fedâisi, 

Hasrete adanmış aşka yürüyen öncü burağı 

Dudağımda dört nala koşan meşkin tek süvârisi. 

D u d a k l a r ı n, 

Zincirlerin koptuğu aklın elden gittiği sınır, 

Bedenin sarılmalar öncesi çağladığı şelale, 

Sorguların sustuğu gözlerin kapandığı sınır, 

Sonrası tam depremdir, nefis dayanamaz bu hale. 

D u d a k l a r ı n, 

. 

A h h......O....... 

. 

D u d a k l a r ı n.', 'D u d a k l a r ı n,  İlk özlemimdi hayallerimin yaşanmışlığına,  Çöl çiçeği kadar masum, ab-ı hayat gibi berrak,  Şu utangaç hırçınlıklarım...', ARRAY['Türk Edebiyatı','Şiir','Metin Eser']::text[], 8.5, '{"poet":"Metin Eser","poet_slug":"metin-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/d-u-d-a-k-l-a-r-i-n-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '24,20 Treni', '24-20-treni-behcet-gultekin-ertan-oouqq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Saat 24,20

O, bir geceyarısı treni.

Doğum sancısı çeken gecelerde,

Bu gara mıhladı, bırakıp gitti beni.

Zaman gar saatinin tokmaklarında ölü,

Mevsim yaprak dökümü.

Horasanlı makasçı,

Makas başındaki kırmızı feneri yakar artık giderde

Rayların kilitlenip düğümlendiği,

Geceye uzandığı yerde.

Beni hep bu mevsim kahreder,

Bütün ağırlığı ile üzerime çöker,

Garın pencereleri buğulanır

El ayak çekilir, yollar uyuşur

Islak kaldırımlara dökülür,

Kentin bütün ışıkları,

Uykusuz trenler,

Yük katarları

Üzülme ne olur,

Pekte yalnız sayılmam hani

Bazan uzaklardan bir tren sesi duyulur,

Bazan da kentin kule saati vurur.

Yalnızlığımı alıp götürür,

Yağmur suları,

Sonbahar yaprakları.

Buralarda her şey bıraktığın gibi,

Yalnız, su satan çocukların dolaştığı yerde şimdi,

Destancılar dolaşır, dudaklarında öykü,

Polis Komiserini 3.ncü peronda vurdular,

Gar bekçisi öldü.

Bazan dalar giderim geceleri.

Sonra da sarhoş bulurlar beni,

İlk şafak, sokak devriyeleri. 

Sefilmişim, bir serseriymişim,

Olsun! ne çıkar? 

Soğuk değil, çıplak ayaklarıma kaldırımlar.

Halbuki sen,

Seneler önce gelmiştin.

Bir kolunda kocan,

Bir kolunda gelinlik kızınla,

Kentin en lüks otelini sordun bana.

Sanki bir yerden tanıyor gibiydin,

Gözlerin üzerimde dolaştığında 

Asil taraflarından biriydi bu senin,

Hiçbir şey söylemedin.

Benim için mutsuzmuş diyorlar.

Sevmişte unutulmuş diyorlar

İnanma ne olur,

Yolcuların anlattığı öyküye de boş ver

Şiir olur, şarkı olur, tavernalarda okunur,

Sonrada unutulur gider.

Biliyor musun, artık yanmıyor akşamları

Ne makas başı fenerleri,

Ne sokak lambaları

Sorma ne olur,

Gelip geçtikçe  hatırımı soran yolcuları.

Önemli değil ama hiç biri,

Uğramaz oldu, 24,20 treni.

Bir gün döner gelirsen,

Peronlarda arama, yıldızlara sor beni…', 'Saat 24,20 O, bir geceyarısı treni. Doğum sancısı çeken gecelerde, Bu gara mıhladı, bırakıp gitti beni. Zaman gar saatinin tokmaklarında ölü...', ARRAY['Türk Edebiyatı','Şiir','Behcet Gültekin Ertan']::text[], 8.5, '{"poet":"Behcet Gültekin Ertan","poet_slug":"behcet-gultekin-ertan","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/24-20-treni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakıp daldım', 'bakip-daldim-zafer-zengin-etnika-c57zw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kadın

Biçare

çocuk

halime

saldın

bakışlarını

Ölmezdim

öyle 

güzel

bakmasaydın

İnandım

Yandım

Afalladım

Ayılmadım

Bir 

çift 

siyah 

gözdü

Bakıp 

daldım

Çıplaktım

Dokunmadın

Titriyordu

elin

donup

kaldım

Ah

ahdım

Seni

bırakmayacaktım

Şaşırdım

kaldım

Sözüm

ona

Büyük

adamdım

Şaşırdım

kaldım

Gözlerine

takıldım

Keşke

saklanmasaydım

Utanan

yüzümle

yakalandım

Kaçamadım...

Haziran 2004  '' Onun gözleri kara ''', 'Kadın Biçare çocuk halime saldın bakışlarını Ölmezdim öyle  güzel bakmasaydın İnandım Yandım Afalladım Ayılmadım Bir  çift  siyah  gözdü Bak...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/bakip-daldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-derin-oger-o9y8q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bugün İstanbul da yağmur vardı

gözümde yeni gelin yüzlü iki damla yaş

uykusuz kaldığım bulutlarla kanadı

gökyüzüm bugün derin bir kuyuydu

hasreti sakin kök söktüren suyuydu

yüzüme değen damlaları mahkûmdu 

bugün İstanbul da yağmur vardı

lâkin şu adaletsizliğin bir adaleti de

kurtlar kuşlar ağaçlar tadını almıştı

gökyüzüm ah ömrümün dağlayanı

ah içimde ki deli fırtınanın çağlayanı

sal darağacından sal uçsun  turnalarımı...', 'bugün İstanbul da yağmur vardı gözümde yeni gelin yüzlü iki damla yaş uykusuz kaldığım bulutlarla kanadı gökyüzüm bugün derin bir kuyuydu ha...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yagmur-121-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üçüncü Kampana', 'ucuncu-kampana-behcet-gultekin-ertan-u3t6o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İlk  kez garda başladı mutsuzluğum..

Mototrenin çığlığından sonra.

Gözyaşlarımı götürüyordu rüzgar,

Ağlayamıyordum.

Unutma demiştin.

Sayamadım, bu kaçıncı mevsim.

Kaçıncı ıslanışı kaldırımların,

Unutmadım.

Kurşuni bulutlardı türedi birden.

Bir duvar oldu  aramızda.

Niye bu kadar sabırsızdı zaman,

Ya üçüncü kampana 

Güney rüzgarları uğrar bazan,

Seni sordum, aramış, selam bırakmışsın.

O deniz kentinde bir akşam,

Sende ağlamışsın.

Nice mutsuzların şarkılarını dinledim.

Sarhoş bir meyhanesinde kentin,

Bir yolcuya sordum, seni,

Evlat, “çok içmişsin” dedi.

Artık bütün tren düdüklerini seviyorum

Bak. Üçüncü  kampana vurdu.

“Uçun kuşlar uçun

Sılaya doğru”', 'İlk  kez garda başladı mutsuzluğum.. Mototrenin çığlığından sonra. Gözyaşlarımı götürüyordu rüzgar, Ağlayamıyordum. Unutma demiştin. Sayamad...', ARRAY['Türk Edebiyatı','Şiir','Behcet Gültekin Ertan']::text[], 8.5, '{"poet":"Behcet Gültekin Ertan","poet_slug":"behcet-gultekin-ertan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ucuncu-kampana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışkanlık', 'aliskanlik-behcet-gultekin-ertan-7xoo1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hani, ahşap bir eviniz vardı.

Akasyaların gölgesinde, pembe boyalı

Ne zaman önünden geçsem,

Kendime çeki düzen verir,

Yan gözle de pencerenize bakardım.

Artık o ahşap eviniz virâne.

Camları kırılmış, bacası yıkık.

Pembe sıvaları yerde.

Alışkanlık,

Şimdi ne zaman önünden geçsem,

Yanımda çocuklarım, karım,

Hâlâ kendime çeki düzen verir,

Yan gözle de o, pencerenize bakarım.', 'Hani, ahşap bir eviniz vardı. Akasyaların gölgesinde, pembe boyalı Ne zaman önünden geçsem, Kendime çeki düzen verir, Yan gözle de pencereni...', ARRAY['Türk Edebiyatı','Şiir','Behcet Gültekin Ertan']::text[], 8.5, '{"poet":"Behcet Gültekin Ertan","poet_slug":"behcet-gultekin-ertan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/aliskanlik-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mırnav Kedi, pisi pisi', 'mirnav-kedi-pisi-pisi-canan-ucer-m902j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey, şair! 

Hangi güç tetikledi de seni

sokuluverdin.

Sevgi diye,aşk diye

sarılıverdin, bilinmezliğe..

Aşk ki yarı memnundur 

kendinden.....

Uyur, uyanık halinle

düşerken, düşmeyi

bilmeliydin.

Şimdi bir kedi mırıldanıyor

kapı aralığında,

ağzında bir kuş can veriyor..

Tutkunun kollarında savrulurken

bir sigara içimi, 

tavanlara bakar, ne düşünürsün..

Ciğeri gördü kedi, 

leşini ser önüne........

Kediler ciğer peşinde

yalanırken, 

şehvet kokusu alır burunları,

onlar ki, nankördür............

parçalanır da bedeni

yüreği avuçlarında sımsıkı

yazar şair,

diğerleri miyavlar, durur

Düşerken, düşmeyi

bilmeliydin.......

Bir yafta gibi kazınmıştır 

boynuna..

Şairler üçüncü boyutta yaşar

beşinci mevsimde ölür....', 'Ey, şair!  Hangi güç tetikledi de seni sokuluverdin. Sevgi diye,aşk diye sarılıverdin, bilinmezliğe.. Aşk ki yarı memnundur  kendinden..... ...', ARRAY['Türk Edebiyatı','Şiir','Canan Üçer']::text[], 8.5, '{"poet":"Canan Üçer","poet_slug":"canan-ucer","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/mirnav-kedi-pisi-pisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürek Yurdu', 'yurek-yurdu-adnan-durmaz-vw13d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hattuşaş’tan geliyorum

kaçağım

arkamda bin türlü tanrı izimi sürer

düşüm binmiş bir bulutun terkisine

kör inançlar kanırttım

yoldaşlar bıraktım aylı yamaçlarda

sevgililer yas dokur kilimlerine

son tapınaktan da kovuldum bıldır

ölümleri şaşırttım

kaçağım beş bin yıldır

acı bizi kovaladı dağ bayır

yine de her ölümde daha bir sevdik

ağlama

ne sultanlar ne taht kalır

koparır yüreğimizi kimi sevsek

sevdayı bildik ya bir yol

acı bizden öcün alır

kaçkın akşamlara 

göçmen sabahlara serdik de postu

bilirsin aşk da serseri

yürek kandaşıyız

acıdan akrabayız

insanın yurdudur insan

sen anlarsın beni

derim ki sevdayı yazgı seçmişiz

her bahar açan çiçek

sararıp da dökülür yaprak yaprak

	hüzünlü yüzüne güzün

berbat biri olurum

hoyratlığım azar

çiğnerim tüm kuralları

atar beni tapınaklar kurallar

bin yıllar geçti ey aşk

mezarlıklar iklimidir kucağım

kaçkınım

bana ellerini uzat yoruldum

kendimi öldürerek sana yeniden doğacağım

							Ekim 2001

Adnan Durmaz,Bilirsin Aşk da Serseri,art yay,ank,2003', 'Hattuşaş’tan geliyorum kaçağım arkamda bin türlü tanrı izimi sürer düşüm binmiş bir bulutun terkisine kör inançlar kanırttım yoldaşlar bırak...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/yurek-yurdu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalma Durgun Acılara', 'dalma-durgun-acilara-adnan-durmaz-6ep1h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gözlerin acının bal peteğidir

dalma durgun sularına acının

dökme kirpiklerini dalgın sulara

günlerin çöp yığını

	kokuşurken kaldırımlarda

yüreğinin alanlarında kanlı pankartlar

dalma dalgın sularına acının

yüzümüzdeki bu kırgın bakışın çatısını

giden arkadaşlar kurdu

onlardan kaldı bize yürek kalelerimiz

büyük şehirler gibisin

	darağaçlarını unutmayan

ikindi gününde ışıyan alnında

	silinmez kederlerin kitabı

yağmuru giyinmiş adamlarını unutmayan

kaldırımlara yayılan

	taze simit kokusu

		baharı gülüşünde taşıyan kızlarını unutmayan

şehirler gibisin...

onlar ördü yapısını duruşun

dalma yorgun sularına acının

şimdi sis basmış günlerin dümen suyunda

belkemiği sökülmüş küçük burjuva aşkların

	kirli çamaşırları yıkanmakta...

aşk dedikleri onların

burun sümüğü-göz sidiği-düş sapkınlığı

iki kilo pırasa-üç kilo turp-

aşk dedikleri onların

sarhoşken yatılan adamlar ve kadınlar

uyanınca yaşanan lağımsı duygular

kendini pislikle temize çıkarmak

aşk dedikleri onların

“mükemmel” dedikleri eşlerini aldatmak

sanal bir şey onların aşk dedikleri

beş dakkada başlayıp üç dakkada tükenen

onların aşk dedikleri

aynı anda üç insanla beş insanla yaşanır

mutlaka birilerini yedekte bulundurmak

kusmuk

tırıçkadan tayyare-selam söyle o yare

nezle-grip-davul tozu-minare gölgesi

yürekteki eğrilik

gülüşteki yamuk

ve bütün bunların duldasına oturup

nazımdan okunan dizeler

ustalardan birkaç alıntı

ve bakışlar taklit

ses tonları çalıntı...

gözlerin acının bal peteğidir

dalma durgun sularına acının

toparlan

günlerin yılkısının sağrısı yağır

kalk ve yürü

bulvarlarda alanlarda kırlarda

yolunu bekleyen hayata

şimdi gece bir yerlerde yağmur sağıyor 

yenilgi alanlarında

ağaçlar yeniden çiçek ağıyor...

biz gönül kandaşıyız

can bağımız sevdadan

ve ateşte-kanda-zındanda

kasırgalı sevdaları 

	biz kadar kim bilir başka

dalma kırgın sularına acının

hadi

kalk ayağa...

				

								Ocak 2001

Adnan Durmaz,Bilirsin Aşk da Serseri,art yay,ank,2003', 'gözlerin acının bal peteğidir dalma durgun sularına acının dökme kirpiklerini dalgın sulara günlerin çöp yığını 	kokuşurken kaldırımlarda yü...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/dalma-durgun-acilara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne (dışlanır olduk)', 'anne-dislanir-olduk-aytekin-arik-a7dvx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biz göçmeniz anne:

Kendi yurdumuzdan 

uzakta kilometrelerce.

Ne sağlam bir evimiz, 

ne yarınlara güvencemiz, 

ne yıldızı parlayan gecemiz.

Yalnız tertemizdir içimiz.

Yabancıyız biz, anne:

Dili, dini, kültürü

bizimkini tutmayan 

yabancı bir ülkede.

Günün konusu olduk, anne

Radyo, televizyon

ve basın anketlerinde

çarsılarda, sokaklarda, 

işyerlri ve fabrikalarda 

günden güne 

dışlanır olduk, anne.', 'Biz göçmeniz anne: Kendi yurdumuzdan  uzakta kilometrelerce. Ne sağlam bir evimiz,  ne yarınlara güvencemiz,  ne yıldızı parlayan gecemiz. Y...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Arik']::text[], 8.5, '{"poet":"Aytekin Arik","poet_slug":"aytekin-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/anne-dislanir-olduk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geometri ile cebirin yan yana-dizesel puslu-dizel masalı', 'geometri-ile-cebirin-yan-yana-dizesel-puslu-dizel-masali-akin-akca-ra1ym', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgi ile yoğurduğunda geometri; 

Cebir kısa mesafe yol alır, ölüm’e de.

Gariptir, 

Arada kaynayan bir mollavari’nin 

Dolanıp da durması 

‘Gün ışığı eklemleyen

Buralar’da.

Cenin’ken anne karnında, 

Umut ettin mi? 

Akıl ettin …

Büyüyüp de mi yoksa? 

Her şey iyiydi, güzeldi, herkes sana gülümserdi. 

Sen fakat on beş-civar yaşlarda

Şaşırtırdın onları: 

Bir kaza mıydı şu vakit her şey, 

Yoksa …

Durabilir misin … 

Peki, öyledir, şu an duraksama -

En güzelidir- anını yaşa 

Ve hazır et geleceği, en orta yer’e: 

Sürecek (olan)  bir istisna; 

Takip ettirecek yarın''ı kendisine

(olan)        ya … 

( Olan, gidecek, ölüm’e…)

Ve ölüm’e senin adımların, 

(İster istemez)  saydığın … 

(İç açıların toplamı)      

Yüz seksen derece ile 

… Ve üç yüz atmış derece: üçgen''i döndür, böyle 

Çıkacak ortaya ''bir küp'', ''meydana gelmiş çokgen’den 

Ve sonra ışıktan bir küre, 

Gölgelerinde tabiat duvarlı-labirent’in, 

Uçacak … 

Büyük-bukalemun: 

Şaştı zaman, iç bükey.) 

Olacak ancak geometriden senin çaktıkların! 

Senin cebirden anlamadıkların olacak! 

Çıkacak nitelik ön plana, nicelik bir hiç kalacak: 

(Solmayansa, kurumuş yaprak-çiçek’ler; 

’Ansiklopedi-sararmış sayfaları arasında; 

Büyü yapmış Euclides…)

Yaşama saydıkların; düzdüğün melodi, 

Ağaca, kuşa..

Pi sayısının içinde uzayan bir hikaye, 

Döndürdüğün iç açılar’ın toplamı, senin: 

Eğri bir uzay’ı bir de sen büktün 

Ve zaten hiç katmer olamamış bir tabaka 

Olan cebir’i de

(Hak etmeyen..)        o da kaynadı arada: 

Belki de akıl’dır o, gerekmeyince rafa kaldırılan. 

(Köprü olmadığında, uzlaşı sağlamadığında…)

Ve geometri, bir –sadece- duygu; 

Seziden bile öte …', 'Sevgi ile yoğurduğunda geometri;  Cebir kısa mesafe yol alır, ölüm’e de. Gariptir,  Arada kaynayan bir mollavari’nin  Dolanıp da durması  ‘G...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/geometri-ile-cebirin-yan-yana-dizesel-puslu-dizel-masali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprak Aldı :((', 'toprak-aldi-halil-kesken-h3uf6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karanfil değil, gül getirdim sana

Birkaç damla da yaş düştü gözümden

Sevgini söyleyip açmadan daha

Kara toprak aldı seni elimden

Gönlümü seninle paklayamadan

Aşkını kalbimde saklayamadan

Tenini bir kere koklayamadan

Kara toprak aldı seni elimden

Bu halin ne diye bana hiç sorma

Beyazlar giymemi hayıra yorma

Sözlerim isyandır, ne olur duyma

Kara toprak aldı seni elimden

Sözümüz yokmudu sonsuza kadar

Benden başkasına olamazdın yar

Artık seni saran başka biri var

Kara toprak aldı seni elimden

Halil Kesken               18.07.1998', 'Karanfil değil, gül getirdim sana Birkaç damla da yaş düştü gözümden Sevgini söyleyip açmadan daha Kara toprak aldı seni elimden Gönlümü sen...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/toprak-aldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cinali ve onun civciv-hali & Sakız Dağı - Kapsamsız gerilenler (İki öykü)', 'cinali-ve-onun-civciv-hali-sakiz-dagi-kapsamsiz-gerilenler-i-ki-oyku-akin-akca-uy8i6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sakız dağında yaşayan bir kız vardı.

Bebek mi bebek ve hep öyle olacak:

Bağıracak salladığında, hep gülecek.

Yıldızlar yapışmış  birbirlerine, böyle duracak.

Düşmezlerdi, sönmeyen mumu gökyüzünün.

Dün''ün; kız yapıştırmıştı ışık ampullerini.

Işık çiçeği, yılmayan, elçi düşünen; 

Bugün’ün, rüzgarda çiçek özü toplayanı.

Devrilerek yuvarlandı bir şaşkınlık anında

Keder doğrultusunda, yuvarlandı böyle, bir süre:

Doruğundan aşağı, tepenin.

Otlar nispeten yuvarlaktı:

Hassastı; kızı tuttu (otlar) , taşıdı.

Bir kilometre yuvarlandı belki de; 

Burnu kanamamıştı, kalktığında.

Caymadı, yürüdü dağa tırmandı,

Çalı çırpı ve odun topladı

Eve götürdü,

Yerde kar -eve ulaşana kadar- vardı:

(Ve tipi, sağından ve solundan:

Dalda ‘tiz-duran’, neredeyse savuracak; 

Koptu kopacak-yaprak gibi!) 

Diz boyu -batmıştı, kapı kulbuna dayandı

Çevirdi onu, sobayı hazır etti

Geçti pencerenin karşısına, oturdu

Sıcak çorba artık hazır olduğunda.

Çarşafı gerdi: panjur, kapamaya gerek görmedi; 

Yumuşacık karları, gerdi.

Güneş çıktı.Uyudu uyandı,

(Kalorifer başında düştü kalktı onun başı) 

Uyandığında güneşi aldı gerdi bu sefer.

En ayazında gecenin, kurtları davet etti

(Gece olmuştu)  Karı özlemişti.

*

Cinali’cik sever kesmeşekeri:

Attığı çayın dışında,

Kahverengi onun rengi.

Kahvaltı yapar Cinali’cik:

Uno light kepek ekmeği

Onun kemirdiği.

Bir kahve içer

Hemen kalkar, gider; 

40 yıllık hatır edinir.

Kalkmayanlar,

Koyu sohbettedir.

Işık hızı aracına biner.

Dönüp baktığında

Yaşlı kadınlar gençleşmiş,

Kendisi yaşlanmıştır:

Bu süreci uzayda edinmişti

Buradan yola çıkarken,

Böyle değildi.

Düşünür,

Bir kahve daha yapar 

Kendisine

Ve kalkar hemen yine 

Ayağa.

Oturur bir dizi izler

Televizyonda.

Ara sıra dalar gider,

Düşer onun başı:

Rüyasında ışık hızını 

Da geçer.

Döner bakar kadınlara,

Hala daha (kendisi)  ihtiyardır:

Hemen kalkardı sedirden,

Neden ki?', 'Sakız dağında yaşayan bir kız vardı. Bebek mi bebek ve hep öyle olacak: Bağıracak salladığında, hep gülecek. Yıldızlar yapışmış  birbirlerin...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/cinali-ve-onun-civciv-hali-sakiz-dagi-kapsamsiz-gerilenler-iki-oyku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dizelerimi Hissetmiyorsun V (Gece Öteki Yüzümü Söyledi)', 'dizelerimi-hissetmiyorsun-v-gece-oteki-yuzumu-soyledi-cumhur-boratav-ia1t4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gece öteki yüzümü söyledi.

kaldırıma düşmüş yüzüm aydınlandı

ayın ışığıyla

ve kanımın yere akmasıyla artan susuzluğum

yaşamı hissettirdi bana

uykum, sürekli beni çağıran uykum,

kaldırımlarımdan yatağıma taşıdı beni

-gecenin düşünde

 bir şeyi iki kere yaşayamaz insan

 bir şeyi iki kere göremezsin

 kafanı döndürüp yeniden baktığında 

 biçim değiştirmiştir yaşayan-

düşüm gecenin düşüne karıştı

değişti gece boyunca

ve her şey değişti,

nasıl bir ışık gözlerime değecek

yarın nasıl bir bir şey kalkacak

esneyerek yanımdan,

kollarını açarak gerinen

gövdem, yeni bir uçurumdan bakarak

nasıl bir boşluğu yaratacak

her şey kaldırımın kenarında…

her şey alnımdan, düşüncemden sızan 

bir kaldırımın kenarı

zaman, beni yatağıma taşıdıkları zaman

düşümü görüyorum

not: 

bu notu sana yazıyorum

ama bilmiyorsun

ışık ve gece değişiyor

aynı kalmak istiyorum

ama farkına varamadan

değiştim, değişiyorum

ellerim bile

bir ahtopot gibi

sekiz bacaklı oldu

ben tek bacaklı oldum

sen tek bacaklısın..

(hissetmiyorsun)', 'gece öteki yüzümü söyledi. kaldırıma düşmüş yüzüm aydınlandı ayın ışığıyla ve kanımın yere akmasıyla artan susuzluğum yaşamı hissettirdi ban...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Boratav']::text[], 8.5, '{"poet":"Cumhur Boratav","poet_slug":"cumhur-boratav","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/dizelerimi-hissetmiyorsun-v-gece-oteki-yuzumu-soyledi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Sözler Armonisi-15', 'guzel-sozler-armonisi-15-bayram-tunca-cr8mo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Senden mirastır bu dert bana

Allah’a havale ediyorum sana

B. Tunca/12.12.2003-12.12

İtikadımızda, ölmek hak biliyorum

Ama yine de aşka devam diyorum

B. Tunca/12.12.2003-12.12

Zanaatın yoksa, kanaatin de mi yok

Eğer kanaat yoksa, zanaat olur kok

B. Tunca/12.12.2003-12.12

Benzer mi hiç asker ocağı baba ocağına

Benzer mi hiç dadı kucağı ana kucağına

B. Tunca/12.12.2003-12.12

Bil ki; ayrılık günü mezarım kazılır benim

Yokluğunda toprak olur şu nazenin tenim

B. Tunca/12.12.2003-12.12

Kürek mahkumu gibi yürek mahkumuyum

Ogün bugündür hep aşk çilesi çekiyorum

B. Tunca/12.12.2003-12.12

İkimiz birbirimizi nasıl sevmiştik delicesine

Bizi, acımadan nasıl ayırdılar öldürürcesine

B. Tunca/12.12.2003-12.12

Eğer seni dinlediğim nispette dinlersen beni

Belki o vakit anlarsın, ne çok sevdiğimi seni

B. Tunca/22.01.2004-12.01', 'Senden mirastır bu dert bana Allah’a havale ediyorum sana B. Tunca/12.12.2003-12.12 İtikadımızda, ölmek hak biliyorum Ama yine de aşka devam...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/guzel-sozler-armonisi-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresiz', 'caresiz-zulfikar-yapar-kaleli-tr2n8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

Karanlığa can katan şu bülbülü,

Hece hece okuyorum, çaresiz.

Reyhanı, zambağı, gülü, sümbülü,

Renkten renge sokuyorum, çaresiz.

Hasreti kahreder, yarası derin,

Toprak hararetli, güneşler serin,

Düşünce Allah’ın, varlık bu yerin,

Hasret oldum, bakıyorum, çaresiz.

Bu yüreğin çarpmaktaki kastı ne,

Kurbanlığın amiri ne, astı ne,

Senin içimdeki sevdan üstüne,

Sevdaları yakıyorum, çaresiz.

Sevdasını yakıp pişen güneşle,

Sır gibi tepeyi aşan, güneşle,

Gönlüme kor gibi düşen, güneşle,

Ta göklere çıkıyorum, çaresiz.

Bir zaman dünyaya yıldızdan baktım,

Doğudan, batıya çağlayıp aktım,

Gözyaşımı Balkanlar’a bıraktım,

Tuna olup akıyorum, çaresiz.

Sırtıma yükledim sıkıntıları,

Damlaydı, göl ettim akıntıları,

Gönlüm mekan tuttu yıkıntıları,

Bülbül oldum şakıyorum, çaresiz.

Irmaklardan akar, kardan daha ak,

Güneşe sırt verdim, yıldıza ayak,

Ateşte üşüdüm şu halime bak,

Bulut gibi döküyorum, çaresiz.', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' Karanlığa can katan şu bülbülü, Hece hece okuyorum, çaresiz. Reyhanı, zambağı, gülü, sümb...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/caresiz-169-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Hayallerimin Hoyrat Sevdası', 'hayallerimin-hoyrat-sevdasi-cafer-tayyar-ozkan-06cqe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İnan kendine, hayallerimin hoyrat sevdası,

İçimizde yaşattığımız anı özleyeceksin,

Hiç susmayacak ki, vuslatımızın bu şarkısı,

Başına bela olduğum anı hissedeceksin.

Bak işte, sesini duyamadan yine gün battı,

Bensiz anların hesabını kimden soracaksın,

Yatağa saran hastalığın, kalbimi sızlattı,

Bilirim, bana soluk gözlerinle bakacaksın.

İnan sesin hiç böylesine üzgün gelmemişti,

Gönülden coşan hislerimi, elbet duyacaksın,

Emanetim olan bedenin süzgün kalmamıştı,

Çektiğinden, benimde içtiğimi bileceksin.

Seni aşkımla saracak günleri bekliyorum,

Gel artık can için canan olalım diyeceksin,

Günah zincirlerini, canan için kırıyorum,

Hayallerin bahara döndüğünü göreceksin.

23 Ocak 2003 Ankara', 'İnan kendine, hayallerimin hoyrat sevdası, İçimizde yaşattığımız anı özleyeceksin, Hiç susmayacak ki, vuslatımızın bu şarkısı, Başına bela o...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hayallerimin-hoyrat-sevdasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git', 'git-ahmet-turan-altunsu-cl0ow', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gidiyorsun artık inandım canan,

And olsun, inanmak ölümden beter…

Uzaktan da olsa dön, bana bir bak:

Bir küçük tebessüm etsen de yeter! 

Git ey sevgili git, eylemek olmaz,

Geride nen varsa topla öyle git! 

Giderken kötü söz söylemek olmaz; 

Hüznü bana bırak, pür neş’eyle git! 

Onca yıl ne çabuk geldi de geçti,

Nasıl bir rastlantı ismini seçti? 

Bir akrep misali ağuladında,

Bu fakîr, zehrini dilinden içti! 

Gidiyorsun, artık güle güle git! 

Utanma, koluna takta öyle git! 

Köhnemiş bir aşktan eser kalmasın,

Mutlu bir edayla, şarkı söyle, git! 

Turan’ ın yüreği abaddır aşka,

Bir şen gönül gider,bin gönül gelir…

Kıpraşır dostluklar gidenden başka,

Hayat-aşk kolkola arşa yükselir! ..

                              27.06.2004 / Ankara', 'Gidiyorsun artık inandım canan, And olsun, inanmak ölümden beter… Uzaktan da olsa dön, bana bir bak: Bir küçük tebessüm etsen de yeter!  Git...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/git-69-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz', 'biz-yusuf-koc-es96g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Allah''ın sır hazinesi arş''ın altındadır, anahtarıda şairlerin dilindedir...

                                                                            Hazreti Muhammed

Ne kadar yaşarsak fani dünyada,

Seven gönüllerin ahisiyiz biz,

Günümüz gerçekte gece rüyada,

Acı çekenlerin hamisiyiz biz.

Aşkı da yazarız acıları da,

Anayı yazarız bacıları da,

Kalemi elimden almasın Hüda,

Çaresiz dertlerin sahibiyiz biz.

Nerde görsek akan yaşlı iki göz,

Dilimizde vardır diyecek çok söz,

İçimiz alevden yansada köz köz,

Sahte suretlerin sahisiyiz biz.

Fakiriz zenginiz içimiz dolu,

İşimiz yürümek gönüldür yolu,

İster yırtsın bizi dikenli çalı,

Kanayan yaranın tabibiyiz biz.

Dünyanın malında yok hevesimiz,

Sevdayı soluklar her nefesimiz,

Tüfekle kılıçla yere serseniz,

Ezilen yüreğin dahisiyiz biz.

Kimimiz alaylı kimi mektepli,

Kimisi korkaktır kimi yürekli,

Ama kalemimiz çelik direkli,

Cümle canlıların halisiyiz biz.

Biz de herkes gibi etiz kemiğiz,

Kalemden kağıda düşen emeğiz,

Koç Ozan''da kimmiş sual etseniz,

Şaşarın beşerin şairiyiz biz.', 'Allah''ın sır hazinesi arş''ın altındadır, anahtarıda şairlerin dilindedir...                                                                 ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Koç']::text[], 8.5, '{"poet":"Yusuf Koç","poet_slug":"yusuf-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/biz-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay düşer/ Akşam a/yaz I', 'ay-duser-aksam-a-yaz-i-zafer-zengin-etnika-a5tg7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Durma

Yaz

Yağmur

Sis

Ağır hava

Düşüyor

Damla

Durma

Gel 

Yaz

Ağır mı geliyor gövdene ellerin

Boğazında düğüm mü hıçkırığın

Durma

Yaz/Gelmiyor

Dünya kafayı yemiş

Kendini baharda sanıyor

Gel

Durma/Yaz

Birlikte gelelim mi/Burda dur/Az

10 Haziran 2004 '' Ellerin gül rengi ''', 'Durma Yaz Yağmur Sis Ağır hava Düşüyor Damla Durma Gel  Yaz Ağır mı geliyor gövdene ellerin Boğazında düğüm mü hıçkırığın Durma Yaz/Gelmiyor...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ay-duser-aksam-a-yaz-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay düşer/ Akşam a/yaz II', 'ay-duser-aksam-a-yaz-ii-zafer-zengin-etnika-mnxjd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Durma/Yaz

Hep üşüyor

Küçük burnunda çiçekler

Yavrusu var yeşil gözlü

Çocuk kabadayı

İplemiyor

Anasını aşkını

Durma/Yaz

Park içinde meçli şaçlar

Et almış

Kilolanmış

Beşikte sallanıyor kadınlığı

Meçli şaçlar

Tepede toplanırken

Boyun açık kalıyor

Yazın geldiği yerdir

Sağına soluna

Elim sığınıyor

Durma/Yaz

Haziranda ayaz

Hangi mevsim ismini bilir

Durma/Yaz

Gölgeme sakla ellerini/Ben öpeyim huyundan

Dur bahar/Gel Yaz/Ellerim ayaz

Ne çabuk büyümüş gülüşün/Sevdalı kadın gibi/Öpüvereyim mi

Bak çocuk gibi aklım/Keten helva yiyor

Deli aşk

Deli çocuğa

Hep yaz gelirdi

Her ağustos çeker giderdi

Kim sever gömleğini

Kim yakar gözlerini

Akdeniz çıralı lamba/Ay düşer akşama/Çocuk dokunma sandala/Leylim Leylim*

Durma/Yaz/Ardında/Bırakma en/kaz/Çok/Kaz

* bilinen alıntıdır

10 Haziran 2004 '' Ellerin gül rengi ''', 'Durma/Yaz Hep üşüyor Küçük burnunda çiçekler Yavrusu var yeşil gözlü Çocuk kabadayı İplemiyor Anasını aşkını Durma/Yaz Park içinde meçli şaç...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ay-duser-aksam-a-yaz-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Kafesi', 'ask-kafesi-bekir-gedikoglu-mptxi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Attığın aşk kemendi kurtulup kaçamadım

Kalbim aşk sarhoşuydu boynumdan yakalandım

Sakın sorma halimi cin çarpmıştan beterim

Bir yuvaya hasrettim artık rahat ederim

Korkularım yok oldu gözüne daldığımda

Mutluluğu anladım belini sardığımda

Kelebeğe dönüştüm öpüşün dudağımda

Kaçmam ben artık senden düşmüşüm kucağına

Yaradan dan  sorarım? Rabbim bana ne oldu

Sana kulluk ederdim o gönlümü uçurdu

Ecelim geldi sandım elim kolum tutuldu

Son noktayı koyacağım aşk kafesi bumuydu? 

İstanbul,21 Haziran 2004', 'Attığın aşk kemendi kurtulup kaçamadım Kalbim aşk sarhoşuydu boynumdan yakalandım Sakın sorma halimi cin çarpmıştan beterim Bir yuvaya hasre...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ask-kafesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Kumsalda*', 'kumsalda-kubilay-enginol-ietik', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ve 

Ellerini gökyüzüne kaldırdı

Sen en büyük şahidimsin

Bu kuluna bağlandım,ömrünü adadım

Hep seveceğim,hiç kırmayacağım

Kan kussamda kızılcık şerbeti içtiğimi söyleyeceğim

Gözyaşlarına mahal vermeyeceğim

Rabbim sen yaradansın

Bana bu kulunu nasib eylediğin için

Sana hamdusenalar olsun

Emanetini daima koruyacağım

Kumsalda iki sevgili

Erkek bunları söyledi

Kadının ellerini tuttu

Sarıldılar birbirilerine sevgiyle

Dünyaya ve aşklarına,güneş doğuyordu

İkisinin de gözleri parlıyordu

Yıldızlara aslında gerek yoktu

Bu şiir diasphora''ya ithaf edilmiştir', 'Ve  Ellerini gökyüzüne kaldırdı Sen en büyük şahidimsin Bu kuluna bağlandım,ömrünü adadım Hep seveceğim,hiç kırmayacağım Kan kussamda kızılc...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kumsalda-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyeceğim', 'bekleyecegim-ali-gencay-puezx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gün kısa,ömür ulaşmaz vuslata,zaman yok,yok söz diyeceğim

yol uzun biliyorum,ömür yetmez adımlara,yine de gideceğim

sabahım var,kumrularım,simitçilerim,fesleğenlerim

çıkarıp güneşi, kapkara gecenin kınından,giyineceğim

kahpe yaşam da,zulama kahramanlar doldurup,bileneceğim

ramağında pusuların,bir ışık,bir ak sakallıya kulak vereceğim 

parmaklar beni gösterir,’’işte o ‘’ gözler de ibret,göreceğim

alnımı yere düşürmeden ‘’işte o benim’’  ben de ibret,diyeceğim

ne varsa yalanlar,yaşadığım sevdalar,aşklar,hepsini bir bir sileceğim

yaşama sevdalandım,ne aşk,ne meşk tek bir hece,kapkara bir geceyim

hadi gücün yeterse ve gözün keserse,dön yolumdan ben dönmeyeceğim

bak gözlerime korkma gecenin siyahından,gece,gündüz hep seni bekleyeceğim

olur da dönüşün olmaz yakarsın gemileri,ışığı,ak sakallıyı sana vereceğim

zulamdan çıkarıp tüm kahramanları,bana gelen yolda emrine amade edeceğim

belki bir düş,bir masal,efsane,bilmiyorum nerde,ne edeceğim

gün kısa,ömür ulaşmazsa vuslata,zaman çok,çok diyeceğim

gecem var, kuma kuşlarım,baykuşlarım,meyim,yudum yudum içeceğim 

yarimsin sevdalımsın,sen bende bir ömür,vebalimsin,gelmesen de seveceğim', 'gün kısa,ömür ulaşmaz vuslata,zaman yok,yok söz diyeceğim yol uzun biliyorum,ömür yetmez adımlara,yine de gideceğim sabahım var,kumrularım,s...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bekleyecegim-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Som Mavi', 'som-mavi-tevfik-mengulluoglu-hv9oj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Som mavi düşler damlıyor

ortalıkta  çocuk sesleri.

Ne sen duyabiliyorsun onları,nede ben 

Anlatabiliyorum sana.

Yollardan düş topluyor herkes

Som mavi düşler.

El ayak çekilir

Ve  büyük bir özlem 

Doğudan doğmaya başlar.

İşveli bir sabah musallat olurken

gözlerine,

ilkbaharda aşıklar

Mavi düşler büyütür.

Bahçelerde gardenyalar

Eski bir musiki olur ellerin

nazenin gözlerin çalınır

ilk ışıklarında gönlümün.

Menekşe kokulu ellerin...', 'Som mavi düşler damlıyor ortalıkta  çocuk sesleri. Ne sen duyabiliyorsun onları,nede ben  Anlatabiliyorum sana. Yollardan düş topluyor herke...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/som-mavi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmuyor', 'olmuyor-murat-demir-ii0se', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir yanım üzüntü bir yanım acı

Bakmasam olmuyor baksam olmuyor

Sarmış yüreğimi bir garip sancı

Yakmasam olmuyor yaksam olmuyor

İzanım karışmış var ile yokla

Takmasam olmuyor taksam olmuyor

Boşaltıp dışarı kanımı okla

Akmasam olmuyor aksam olmuyor

Çıkılmaz girdabın içine düştüm

Yüzmesem olmuyor yüzsem olmuyor

Esir gibi kaldım elinde puştun

Gitmesem olmuyor gitsem olmuyor

İzzetli ikramlı sevdası zehir

İçmesem olmuyor içsem olmuyor

Baharı bitmeyen bulanık nehir

Geçmesem olmuyor geçsem olmuyor

Sesine ses katıp ben de bir yandan

Konuşsam olmuyor sussam olmuyor

Bu çekilmez aşkı yağlı urgandan

Asmasam olmuyor assam olmuyor', 'Bir yanım üzüntü bir yanım acı Bakmasam olmuyor baksam olmuyor Sarmış yüreğimi bir garip sancı Yakmasam olmuyor yaksam olmuyor İzanım karışm...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olmuyor-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahpus Damları', 'mahpus-damlari-mustafa-toga-g80rs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana bu satırları,			

Uzaklardan...

Çok uzaklardan yazıyorum.

Anne, 

Benim...oğlun, yavrun.

Telli duvarlar ötesi

Karlı dağlar ardından.

Bu mektubu evir çevir,

Uzun uzun tut ellerinde.

Kokumu hatırlayacak

Oğlum, canım diyeceksin.

Gözlerin dolacak, 

Belki de ağlayacaksın anne.

Ağlama annem ağlama

Ciğerparen yazan ağlama,      

Kader demişler buna,

Karşı durmak boşuna.

Düştüm mapus damlarına.

Demir parmaklık arkasından

Güneşi bir saat gösterirler,

Gündüzler karanlık burda.

Sigara içmek serbest

Türkü söylemek yasak.

Canım annem,

Burası çile çekilen ocak

Ínan............

Oğlun bir gün sana kavuşacak.', 'Sana bu satırları,			 Uzaklardan... Çok uzaklardan yazıyorum. Anne,  Benim...oğlun, yavrun. Telli duvarlar ötesi Karlı dağlar ardından. Bu m...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Toga']::text[], 8.5, '{"poet":"Mustafa Toga","poet_slug":"mustafa-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/mahpus-damlari-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değerlerini bilemedik', 'degerlerini-bilemedik-yusuf-koc-9m2fl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Minnettarım onlara...rahmet diliyorum...unuttuklarım beni bağışlasınlar....

Yürürdü yane yane,boyar aşk onu kane,

Akil değilim derdi denmez ona divane,

Rabbine mısra yazar, okuruz tane tane,

Miskin biriyim derdi Yunus Emre''di adı.

Üç nefes oku bana,Şah''ın adı geçmesin,

Bağışlarım canını, gam yelleri esmesin,

Her nefeste Şah vardı,tükensede nefesim,

Şah uğruna can verdi, Pir Sultan idi adı.

Çile çekmiş yaşamda, dertler ona yazdırdı,

Duygu dolu yüreği, tırnakla yer kazdırdı,

Siper etti göğsünü, kem sözleri durdurdu,

Küreği çok kısaydı, Necip Fazıl''dı adı.

Vatan şairi idi,hizmetler verdi bize,

Çok eziyetler çekti, ama gelmedi dize,

Doğruları okudu, aldırmadı her söze,

Haluk''a defter yazdı, Namık Kemal''di adı.

İstiklale söz yazdı, durur dünya durdukça,

Albayrağı çok sevdi, yoktur başka Tanrıça,

Onun adı silinmez bu millet var oldukça,

Marş oldu dilimize, Mehmet Akif''ti adı.

Yolun yarısı eder, otuzbeş yaş ortası,

Herkes bilirdi bunu, ona düştü tasası,

Ders verdi insanlara, yok elinde asası,

Musalla taşındaydı, Tarancı idi adı.

Güzellere sevdalı pınarlardan su içer,

Taht kurdu gönüllere, aşkı dünyaya bedel,

Kırmaz hiçbir canlıyı, biçilmez ona değer,

Seher yıldızı gibi, Karacoğlan''dı adı.

Gel diyordu bana sen, ne olursan yine gel,

Gerçek sevgiyi bulduk, yoktur orada engel,

Erenlerin şahıdır, her sözü ömre bedel,

Kafir müslim ayırmaz Mevlana idi adı.

İstanbul''a sevdalı geçti çok uzun yıllar,

Sordular bir gün ona Ankara''nın nesi var,

Dedi en güzel yeri oraya giden yollar,

Sessiz gemiye bindi, Yahya Kemal''di adı.

Kendisi bir alemdi, ederdi düzgün kelam,

Küs değildi kimseye, herkese verir selam,

Binlerce şiir yazdı, budur bizlere kalan,

Avrupa görmüş idi, Ümit yaşar''dı adı.

Bir garip diye başlar, fukara yaşam sürdü,

Gönül kapısı açık nice aşkları gördü,

Ellere geniş dünya, yalnız ona mı dardı,

İstanbul''u dinlerdi Orhan Veli''ydi adı.

Yaşayan efsaneydi, sevgi doluydu özü,

Bakamazdı cihana, gönülde vardı gözü,

Elleri sazı çalar, ibret dolu her sözü,

Yari kara topraktı, Aşık Veysel''di adı.

Prangalar eskitti, vatanı çok severdi,

Doğru şiirler yazdı, damda yıllar geçirdi,

Yüreği yanık gitti, kısa ömrü bitirdi,

Vuruldum kirvem dedi, Ahmed Arif''ti adı.

Aşık tüm insanlara, gözleri kan ağlıyor,

Duygu dolu yüreği, cigerleri dağlıyor,

Onu bir kişi değil, bütün millet arıyor,

Fahriye abla dedi, Ahmet Muhip''ti adı.

Tüm ülke memleketi, tapar taş toprağına,

Doyamadı vatanın suyuna toprağına,

Şimdi yok aramızda, girdi irem bağına,

Han duvarları dedi, Faruk Nafiz''di adı.

Şimdide söz edeyim bir dünya şairinden,

Yurdum diyerek öldü negelir ki elimden,

Dar kafalar anlamaz onun sevgi selinden,

Mezarı yadellerde Nazım Hikmet''ti adı.

Onlar var iken orda, benim adım sorulmaz,

Üçbeş satır yazmışım esamesi okunmaz,

Koç Ozan''ım derim ki onlarsız günüm olmaz,

Büyük sözler söyleyen şair onların adı.', 'Minnettarım onlara...rahmet diliyorum...unuttuklarım beni bağışlasınlar.... Yürürdü yane yane,boyar aşk onu kane, Akil değilim derdi denmez ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Koç']::text[], 8.5, '{"poet":"Yusuf Koç","poet_slug":"yusuf-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/degerlerini-bilemedik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Tanımadan Önce', 'seni-tanimadan-once-fatih-taskin-68kfa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dinlediğim şarkıların düşünmezdim anlamını 

Gülüp geçerdim,bu nasıl şarkı... 

Bulamadım hiç gerçek aşkı 

Derdim ben, seni tanımadan önce 

Umutla aradım sevgi ve aşkı 

Ayırt edemedim sahte bakışları 

Siyah gözün hiç yokmuş anlamı 

Derdim ben, seni tanımadan önce 

Bulamadım kendime iyi bir arkadaşı 

Teselli verecek candan bir ahbabı 

En iyi dostum benim şaraptı, 

Derdim ben seni tanımadan önce 

Siyah bereli....... 

Ağustos 2001', 'Dinlediğim şarkıların düşünmezdim anlamını  Gülüp geçerdim,bu nasıl şarkı...  Bulamadım hiç gerçek aşkı  Derdim ben, seni tanımadan önce  Um...', ARRAY['Türk Edebiyatı','Şiir','Fatih Taşkın']::text[], 8.5, '{"poet":"Fatih Taşkın","poet_slug":"fatih-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/seni-tanimadan-once-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bal Olsan Bir Parmak Tatmam', 'bal-olsan-bir-parmak-tatmam-murat-demir-l71qy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüreğin hala senin mi

Başkasına vermedin mi

Senin gibi bir deli yi

Hala bulup sevmedin mi

Bana bakma evde kalman

Benden değil hergün yanman

Bu nedir ki, göreceksin

Daha gelecek yalvarman

Hiç sanma ki güleceksin

Dertten derde gireceksin

Unutma ki yaşadıkça

Daha neler göreceksin

Duruyor mu cımbızların

Fatma ların, yıldız ların

Asker oldu çocukları

Senden sonra ki kızların

Bana bakma ben pas atman

Bal olsan bir parmak tatmam

Bir yastıkta iki başla

Sen olursan asla yatmam

Düşmem artık ocağına

Dönüp bakmam sıcağına

Seni tutup sevmek için

Kimse almaz kucağına', 'Yüreğin hala senin mi Başkasına vermedin mi Senin gibi bir deli yi Hala bulup sevmedin mi Bana bakma evde kalman Benden değil hergün yanman ...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bal-olsan-bir-parmak-tatmam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı Sevdalar', 'yalanci-sevdalar-fatih-konuk-lyn6q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bu dert,bu cefa,öldürecek beni bu azap

bu gönül aşkından oldu viran,oldu harap

ne olur al bu canımı da kurtulayım yarap 

bıktım sahte dostlardan,bu yalancı dünyadan

boşa gitti bu ömrüm boşa gitti,oldu heder 

bu gönle doldu acı,doldu gam,doldu keder

bir kere olsun gülmez mi bu yüzüme kader

bıktım bu sahte dostlar ve yalancı sevdalardan

içimdeki bu deli dolu aşkla,bu sevgiyle,bu ihtirasla

yaşayamam bu isyanla,bu gerilimle ve bu ihtirazla

hayatla ve kaderle aramdaki bu nifakla,bu ihtilafla

bıktım sahte dostlardan,fani hayattan,yalan dünyadan', 'bu dert,bu cefa,öldürecek beni bu azap bu gönül aşkından oldu viran,oldu harap ne olur al bu canımı da kurtulayım yarap  bıktım sahte dostla...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalanci-sevdalar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Atımın Sırtındayım', 'dus-atimin-sirtindayim-necmi-unsal-k2ofg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ruhumun estiği deniz boş,  fırtınalar dinmez.

Benliğim hep düş atının  sırtında, asla inmez.

Dağ tepe düz gidiyorum düş atımın sırtında.

Ağustosları yaşarım baharların martında.

Sıkıntının çökerttiği yüzlerle vurulurum.

Kalbe giren ferahlıkla, hep ben de durulurum.

Düşümün bu yolculuğu devam eder, sana dek.

Belki yapraklarım,  yüzüm sararıp;  solana dek.

İsterim kalmasın benden başka,  solmuş tek bir yüz.

İki cepheli duvardır hayat, ömür tek bir yüz.

Bütün ovaları renk renk  güller, çiçekler bassın.

Sonsuzluk kıyısında,  âh ölüm;  onmaz bir yassın! 

Kalmasın sevinç olmayan hiç kimse  gözlerinde.

Hakiki  kurtuluş O’nda,  o  kutlu sözlerinde.

                       

12 Nisan 2004 Pazartesi, Danimarka-Køge 23:39

8+7', 'Ruhumun estiği deniz boş,  fırtınalar dinmez. Benliğim hep düş atının  sırtında, asla inmez. Dağ tepe düz gidiyorum düş atımın sırtında. Ağu...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dus-atimin-sirtindayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resim', 'resim-fatih-konuk-xqzid', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çok uzun yoldan geldin

Bir gece olsun kal bari

Çok oldu benden ayrılalı

Artık bir daha gitme geri

Kal yanımda,sev beni

Gittiğin günden beri

Çok özler oldum seni

Ne olursun gitme geri

Yar at beni,yak beni ateşte

Değişmem seni hiçbir şeye

Gittiğin günü uzatıp ta

Beni sonra düşürme peşine 

Ellerin değsin ellerime

Kokun karışsın tenime

O günlerden bu günlere

Neler,neler getirdik biz

Uzattın zamanı dön gayrı

Olamıyorum senden ayrı

İçimdeki bu kuşku,bu kaygı

Öldürecek beni galiba

Bu yalan dünya zaten fani

Bugünde yanımda kal bari

Bana verdiğin umutlar hani

Nerde,nerede hani nerede

Düşürmedim elimden resmini

Ayrılığınla aldım ben dersimi

Acıyı,kederi,sevinci ve hepsini

Yaşadım senle,yaşadım seninle

Baykuşlar kondu ağacıma

Dikilip durma yamacıma

Acılar katma acılarıma

Ne olur bir daha gitme

Dön gel başıma taç ol

İstersen en ağır suç ol

Hastalığıma da ilaç ol

Artık bir daha gitme

Yokluğun alçak gibi

Bu hayat gerçek gibi

Kurumuş çiçek gibi

Olmadan gel ne olur', 'Çok uzun yoldan geldin Bir gece olsun kal bari Çok oldu benden ayrılalı Artık bir daha gitme geri Kal yanımda,sev beni Gittiğin günden beri ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/resim-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Yolcu...', 'yolcu-naime-erlacin-gokco', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'efkârın gergefinde dokunur nakışlar

billurlaşır söz 

suyun yorgun teninde

“gönle ulaşmanın tarihidir insanınki” 

der feylesof*

hınzırca gülümser

bir dağ ateşi yakar gözlerine

satırlarda buluşulur sonra

hayal âleminde dolaşılır 

düşler kurulur gönül eri olmak üzre

bütünleşir ruh ve akıl

durulur nöbetlere

-aşk düşünüp 

ölüm konuşmaktan gelmiş

ne geldiyse başına! 

...böyle hikâye eder serüvenini...

kendine özgü bir sestir aranan

özgür ve özgül olan

kalıplara dökeriz bedenlerimizi 

sil baştan libaslar biçeriz 

o bir garip 

bir derviş

ben çilekeş yoldaş

açarız evrenin ‘la’ sesine penceremizi

tutunur kenara dolgun başaklar

dökülür dizeye nakış 

mistik bir rüzgâr eser buralarda

sessizliğe bürünür yol ansızın

kokusundan tanınır yolcu

yel sürükler 

yol sürer izimizi...

(*)       Ahmet İnam

(28 Haziran 2004)', 'efkârın gergefinde dokunur nakışlar billurlaşır söz  suyun yorgun teninde “gönle ulaşmanın tarihidir insanınki”  der feylesof* hınzırca gülü...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yolcu-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Bu sabah sana veda ettim..', 'bu-sabah-sana-veda-ettim-erdal-asik-bnt80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Unutamadığım gecemsin artık

Habersizce söylemeden

Masum temiz duygularla

Günahsız bebek gibi

Uyurken yatağında

Bir gül bıraktım başucuna....

Bülbüller susmadan

Şehvet dolu saatlerin ardından

Serçeler uyanmadan

Ezan sesi duyulmadan

Yağmur bulutlarıyla birlikte

Aşkını gömdüm yüreğime....

Güneş kirli yüzümü göstermeden

Tüm şehir üstüme gelmeden

Sana, sana acı vermeden

Elveda bile demeden

Bu sabah sana veda ettim.....', 'Unutamadığım gecemsin artık Habersizce söylemeden Masum temiz duygularla Günahsız bebek gibi Uyurken yatağında Bir gül bıraktım başucuna.......', ARRAY['Türk Edebiyatı','Şiir','Erdal Aşık']::text[], 8.5, '{"poet":"Erdal Aşık","poet_slug":"erdal-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bu-sabah-sana-veda-ettim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köşe Başında Bekliyorum', 'kose-basinda-bekliyorum-fatih-konuk-3v5fg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Köşe başında bekliyorum

Sokağı dönüp bana koşmanı bekliyorum

Omuza sarılıp seni seviyorum

Demeni bekliyorum

Elini tutup seninle gezmeyi istiyorum

Göz göze olup konuşmayı,

Elini tutup gezmeyi istiyorum

Kırlara oturup çicekler toplayı

Istiyorum

çicekleri bir bir kopartıp

Seviyor sevmiyor falına bakmayı istiyorum

Köşe başında bekliyorum

Ellerimde demet demet çiceklerle

Kaldırımlarda yağmurda ıslanarak

Seni bekliyorum

Kulağına seviyorum sözcüğünü fısıldamayı

Sana güllerin en güzelini sunmayı

Sana doya doya gözlerine bakmayı

Istiyorum

Köşe başında bekliyorum

Geleceksin diye

Kavuşacağız diye', 'Köşe başında bekliyorum Sokağı dönüp bana koşmanı bekliyorum Omuza sarılıp seni seviyorum Demeni bekliyorum Elini tutup seninle gezmeyi isti...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kose-basinda-bekliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Yazıyorum Bu Şiirimi', 'sana-yaziyorum-bu-siirimi-fatih-konuk-mk72l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Elimde kalemim,

dudağımda sigaram

Yanımda çayım,

Önümde sana yazacağım bir sayfa

Sana yazıyorum bu şiirimi 

Seni sevdiğimi yine anlatmak istiyorum

Bu şiirdede her şiirde olduğu gibi

Seni özlediğimi kelimelere dökmek istiyorum

Sana yazıyorum bu şiirimi

Gözlerimin önünde hayalini düşünerek

Sana yazıyorum bu şiirimi

Elimdeki kalemle yine içimi döküyorum satırlara

Dudağımdaki sigaramla son gücümle içime çekiyorum

Yanımdaki çayımlada seni yudumluyorum

Sana olan hasretimi,özlemimi,aşkımı

Bu şiirdede anlatmak istiyorum

Her şiirde olduğu gibi

Sana yazıyorum bu şiirimi

Gözyaşlarımı üzerine dökerek,

Ellerim istemeyerek 

Sana yazıyorum bu şiirimi

Belkide son şiirim bu sana

Yine özlemimi

Yine hasretimi

Ve yine çook sevdiğimi

Anlatıyorum bu şiirde

Her şiirde olduğu gibi...', 'Elimde kalemim, dudağımda sigaram Yanımda çayım, Önümde sana yazacağım bir sayfa Sana yazıyorum bu şiirimi  Seni sevdiğimi yine anlatmak ist...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sana-yaziyorum-bu-siirimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seveceğim', 'sevecegim-fatih-konuk-oc766', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bitmeyen zulüm olsan

Çekilmeyen çile olsan

Gelmeyen bahar olsan

Seveceğim seveceğim

Seveceğim sonuna kadar

Seveceğim sonsuza kadar

Seveceğim ölümüne kadar

Seveceğim seveceğim', 'Bitmeyen zulüm olsan Çekilmeyen çile olsan Gelmeyen bahar olsan Seveceğim seveceğim Seveceğim sonuna kadar Seveceğim sonsuza kadar Seveceğim...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevecegim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Diye Çekeyim?', 'ne-diye-cekeyim-caner-kuru-fi0yc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kendi ettiğini yine kendin bul,

Ne diye çekeyim senin derdini? 

Kendi hatasıdır ağlıyorsa kul,

Ne diye çekeyim senin derdini? 

Sen sevmedin diye ağlayayım mı? 

Bu masum kalbimi dağlayayım mı? 

Çek git gideceksen, bağlayayım mı? 

Ne diye çekeyim senin derdini? 

İnsan hep düşer mi aynı hataya? 

Uzak dur yanımdan gelme buraya

Zaten ömrüm geçmiş dert saya saya,

Ne diye çekeyim senin derdini?', 'Kendi ettiğini yine kendin bul, Ne diye çekeyim senin derdini?  Kendi hatasıdır ağlıyorsa kul, Ne diye çekeyim senin derdini?  Sen sevmedin ...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ne-diye-cekeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşçakal', 'hoscakal-fatih-konuk-nf1y7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Artık gidiyorum hoşçakal sevgilim

Herşeyi sana bırakıp gidiyorum

Gözlerimden yaşları akıta akıta

Gidiyorum çook uzaklara 

Mutlulukları,güzellikleri

Aşkı,sevgiyi ve herşeyi

Ama herşeyi sana bırakıp

Göçüyorum çook uzaklara

Hoşçakal sevgilim

Hoşçakal bir tanem

Hoşçakal gülüm,canım

Hoşçakal mutlu ol

Belki sana aşkı yaşatamadım

Belki seni gerektiği gibi sevemedim

Belki bir başkası aşkı yaşatır diye

Belki başkası seni fazla sever diye

Gidiyorum hoşçakal! .......', 'Artık gidiyorum hoşçakal sevgilim Herşeyi sana bırakıp gidiyorum Gözlerimden yaşları akıta akıta Gidiyorum çook uzaklara  Mutlulukları,güzel...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hoscakal-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeğenim', 'yegenim-fatih-konuk-0m6hd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir kurban daha verildi ölüme

Ablam gitti şimdide yeğenim

O da gitti sonunda gideceği yere

Ama erken vakitte gitti gideceği yere

Daha kokusunu koklayamadan,

Daha kucaklayayıp öpemeden,

Daha anne,baba diyemeden,

Azrail canını aldı yeğenimin

Yerlerde sürünüp apalayamadan

Daha oyuncaklarla oynayamadan

Daha onu sıkı sıkı saramadan

Ecel kapısını çaldı yeğenimin

Dünyaya gelmesiyle gitmesi,

Gözlerini açmasıyla kapaması,

Nefesini almasıyla vermesi

Bir oldu yeğenimin

Topraklar bedenini sardı

Ana kucağı göremeden

Ilk lokmasını yiyemeden

Ilk elbisesini giyemeden

Beyaz kefen giydi yeğenim

(doğmadan ölen yeğenimin anısına)', 'Bir kurban daha verildi ölüme Ablam gitti şimdide yeğenim O da gitti sonunda gideceği yere Ama erken vakitte gitti gideceği yere Daha kokusu...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yegenim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sulugöz', 'sulugoz-caner-kuru-3ku0n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne sulu gözlerin var,

Eksilmiyor hiç yaşlar.

Bir dokun bin ah işit,

Hemen akmaya başlar.

Zaten ezik şu gönlüm,

Zaten yüreğim kırık.

Nereden çıktı şimdi 

Bu anlamsız hıçkırık.

Ah sulugöz, sulugöz,

Niye ağlıyorsun ki? 

Yok yere bu kalbimi

Niye dağlıyorsun ki?', 'Ne sulu gözlerin var, Eksilmiyor hiç yaşlar. Bir dokun bin ah işit, Hemen akmaya başlar. Zaten ezik şu gönlüm, Zaten yüreğim kırık. Nereden ...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sulugoz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyordum Ama Şimdi', 'seviyordum-ama-simdi-fatih-konuk-xg4iw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni öyle çok seviyordum ki anlatamam ki

Anlatmak istesem anlatamam

Seni canımdan bir parça sayıyordum ki

Söylemek istesem söyleyemem

Seni herşeyden çok,

Canımdan çok

Çok ama çok 

Seviyordum ama şimdi...

Sana öyle bir bağlıydım ki

Anlatmak istesem anlatamam ki

Seni kanımda kan gibi görüyordum ki

Söylemek istesem söyleyemem', 'Seni öyle çok seviyordum ki anlatamam ki Anlatmak istesem anlatamam Seni canımdan bir parça sayıyordum ki Söylemek istesem söyleyemem Seni h...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seviyordum-ama-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yarim Olsun İstiyorum', 'bir-yarim-olsun-i-stiyorum-fatih-konuk-fqr9d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir yarim olsun istiyorum

Gözleri kahverengi,yeşil,ela olsun ama

Mavi olmasın

Çünkü senin gözlerin maviydi

Bir yarim olsun istiyorum

Saçları siyah,kumral olsun ama

Sarı olmasın

Çünkü senin saçların sarıydı

Bir yarim olsun istiyorum

Hatice,zeynep,gamze olsun ama

Sevgi olmasın', 'Bir yarim olsun istiyorum Gözleri kahverengi,yeşil,ela olsun ama Mavi olmasın Çünkü senin gözlerin maviydi Bir yarim olsun istiyorum Saçları...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bir-yarim-olsun-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Ankara', 'canim-ankara-fatih-taskin-vfpki', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Özlüyorum seni bu gurbet  ocağında 

Buralar benzemiyor senin taşına toprağına 

Deniz varmış,yeşil varmış kimin umrunda 

Kurban olsunlar senin bozkırına,yokuşlarına 

Dut ağaçlarına,uzun kavaklarına 

İnan bana özlüyorum seni canım ankara 

Yabani gibi bakıyor buranın insanları 

Aaaah...nerde şimdi Sakarya cd.sinin kızları 

Bebek gibidir Bahçeli 7 ve Tunalı hatunları 

Gezmek isterdim delice hem Ulus''u hem Kızılay''ı 

Çok özledim elektronik mekanımı yani bit pazarını 

Soğuğunu,ayazını,kara kışını 

Yüksek yüksek binalarını 

Hatta hatta kaldırım taşlarını 

Özledim seni be..canım ankara 

20 numaraya bindin mi? Saimekadın''dan Batıkent''e 

İnerdim eğer işim varsa Maltepede 

Geçerdim ara sokaktan Necatibeye 

Döner ekmek yemeği ihmal etmezdim köşedeki büfede 

Tabiki yanında ayranı da beleşse 

Uğramadan edemezdim İzmir caddesine 

hele oradaki macig life cafeye 

Gazetemi okur,çayımı içerdim 

İnan bana seni çok özledim...başkent ankara 

Dikimevi-metro bizim eve 10 dakika 

Metroyla giderdim ister batıkent''e ister Kızılay''a 

Hafta sonları uğrardım Akkörüdeki migrosa 

Yazın pikniğe giderdik Çubuk2 ''ye,Karagöl''e 

Hasret kaldım ulan şimdi Mamaktaki boklu dereye 

Derenin bi ucu gider Sincan Fatih''e 

3 ayımı verdim Etimesgut zırhlı birliklere* 

Yıldırım durağından binerdim banliyo trenine 

Gözümü açardım ya Cebeci ya Demirlibahçe 

Koşar adım eve giderdim başımda siyah bereyle 

Aaaaah ah o günler neydi heyt be... 

Özledim seni resimlere baksam bile 

Hasret kaldım sana canım ankara 

*(askerliğimin acemi birliği olan yeri)

Kokoreç yemek için çiftliğe 

Çay içmek için ise K.ören şelaleye 

Ya da H.Bayram camisinin avlusuna gider 

Oradanda kitapçıları gezerdim 

Her ay mutlaka bir kitap alır 

Sonra arkadaşlarıma anlatırdım. 

Öğlen yemeklerinde yolum düşerse 

Ulusdaki aspava pideciye 

Mutlaka uğrar karnımı doyururdum. 

Ne de olsa babadan kalma alışkanlıktı 

Eve dönmek için Bentderesine 

Aaaaah ah özledim seni ellere ne 

Hasret kaldım sana canım ankara 

Demir sanayisinin en büyüğü Ostim''de 

Mobilyanınki ise Sitelerde 

Ama dükkanlar kapalı malesef bu krizde 

Esnaf kan ağlıyor(du)  Kemal Dervişe* 

Adam isyan ettirdi başkentliye 

Sadece başkentemi bütün Türkiyeye 

İşçi -memur giderdi el ele eyleme 

Kızılay kapanırdı yine trafiğe 

Aaah ah..özledim seni başkent ankara 

*(şiiri yazdığım dönem ekonomi bakanıydı)

Amatör ligde lisanslı maçlar oynardım 

19 Mayıs,Y.mahalle,Altındağ,Anıttepe 

Hepside kıran kırana,nefes nefese 

Sonraları ise heves saldım futbol hakemliğine 

Tanımayan kalmamıştı bu alemde 

Kırmızı kart bile göstermiştim Y.mahalleli Erdem''e* 

İlk dayağı ise yemiştim Anıttepede 

Sonra Polatlı,Haymana,Hasanoğlan,Solfasol''de 

Birçok şeyi benden alıp gitsede 

Özledim o günleri heyt be 

Hasret kaldım sana başkent ankara 

*(erdemle askerde karşılaştık.o beni tanıdı ben onu tanıdım..o günü bi 

yad ettik..daha sonra canciğer dost olduk..halen görüşüyoruz)

Her gece dua ediyorum canım babama 

Şuan yatıyor Karşıyaka 4. kapıda 

Allahtan rahmet diliyorum 

Bütüm insanların yakınlarına... 

Gençlik parkı,Altınparkı,Hibodrumuyla 

Zenginiyle Çayyolu,Batıkent,Çankaya 

Yoksuluyla Çinçin,Mamak,Altındağ 

Unutulmayan yüzlerce mekanınla 

Hasret kaldım sana BAŞKENT ANKARA 

Çok özledim seni canım ankara....... 

siyah bereli 

02.09.2002', 'Özlüyorum seni bu gurbet  ocağında  Buralar benzemiyor senin taşına toprağına  Deniz varmış,yeşil varmış kimin umrunda  Kurban olsunlar seni...', ARRAY['Türk Edebiyatı','Şiir','Fatih Taşkın']::text[], 8.5, '{"poet":"Fatih Taşkın","poet_slug":"fatih-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":86,"source_url":"https://www.antoloji.com/canim-ankara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mecbur değilsin', 'mecbur-degilsin-mustafa-tugrul-kosar-xzuid', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dimdik duracaktı gitmesen başım 

Dert etme boşuna bırak eğilsin 

Ardından yol boyu dökülse yaşım 

Birşey söylemeye mecbur değilsin 

Gece de sabah da beddua etsem 

Sayende yaşanır herşeye küssem 

Göz göre göre de ölüme gitsem 

İçine atmaya mecbur değilsin 

Korkutur seni de verdiğin izler 

Korkarsın bakarsa dilenci gözler 

Karşına çıkarsa titreyen eller 

Bir kere tutmaya mecbur değilsin 

Sesini duymadan bu yaşamaksa 

Düşünme uğrunda ölenler varsa 

Arkanda devrilmiş bir sarhoş kalsa 

Dönüpde bakmaya mecbur değilsin 

Yolunda yıkılmış bir sarhoş varsa 

Yüzüne bakmaya mecbur değilsin', 'Dimdik duracaktı gitmesen başım  Dert etme boşuna bırak eğilsin  Ardından yol boyu dökülse yaşım  Birşey söylemeye mecbur değilsin  Gece de ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tuğrul Koşar']::text[], 8.5, '{"poet":"Mustafa Tuğrul Koşar","poet_slug":"mustafa-tugrul-kosar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/mecbur-degilsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maskeler', 'maskeler-fatih-taskin-crr4x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Acaba diyorum çiçeklerin rengide mi? sahte, 

Bakıyorum çevreme kin kusuyorum nefretle 

Samimiyet artık bitmiş yerini maskeler almış 

İkiyüzlülük, riyakarlık artık saltanatmış 

En çok güvendiğin bile yarıda bırakabiliyor 

Menfaati olmadan yanına bile yanaşmıyor. 

Gerçek kimlikleri maskelerin altında. 

Yılan sinsiliği var güleryüzün arkasında 

İnsanlar birbirlerine gerçekten çok yapmacık 

Yanaşıveriyor heman menfaati varsa azıcık 

En iyi arkadaşın oluveriyor eğer çıkarı varsa 

Gözünden düşüyorsun lakin menfaati yoksa 

İşte bütün bu yılanların,timsahların,akreplerin içinden 

Eğer can kardeşini,gerçek dostunu bulabilirsen 

Bırakmayacaksın peşini hayatın boyunca 

Çünkü o el uzatacak sana,düştüğün zaman çukura. 

Mücadeleye gireceksin hayatla zor şartlarda 

Galip gelirsin,eğer verirsen omuz omuza 

Ve birde hiç düşünmeyeceksin bakmadan sonuna 

Gözün kapalı imza atacaksın kader arkadaşlığına.. 

Dünyadaki en güzel olay diye bakarım dostluğa 

Siyah Bereliden armağandır hala dostunu arayanlara............... 

                                                      Siyah bereli.... 2003

YÜREKLER UMUTLARA GEBE OLDUĞUNDAN 

BERİ 

DOSTLUK AYRILIKLARA HİÇ YENİK DÜŞMEDİ.... 

BİZ 

GÖNLÜMÜZ DARAĞACINDAYKEN ÖLÜME 

KÜSÜP 

SADECE DOSTLARIMIZI SEVMEYİ SEVDİK...........', 'Acaba diyorum çiçeklerin rengide mi? sahte,  Bakıyorum çevreme kin kusuyorum nefretle  Samimiyet artık bitmiş yerini maskeler almış  İkiyüzl...', ARRAY['Türk Edebiyatı','Şiir','Fatih Taşkın']::text[], 8.5, '{"poet":"Fatih Taşkın","poet_slug":"fatih-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/maskeler-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Babam', 'canim-babam-fatih-taskin-uhukn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çok bekledim senin için bu yazıyı yazmayı 

Seni çok özledim canım babam.... 

Alın yazın sen doğduğunda kararmış 

Validen Allahın rahmetine kavuşmuş 

Seni gaddar bir babanın eline bırakmış 

Hayatın acımasız olduğu karşına ilk burda çıkmış. 

Çocukluğun sefalet ve yoksullukla geçmiş 

Baba zoruyla okula bile gidememiş 

Hayatın zorlu yükü omuzlarına çocukken binmiş 

Sensizliğe alışamadım canım babam 

Yaşıtların okul sıralarında dirsek çürütürken 

Sen çoktan 20-22 anahtarı almıştın eline 

Fazla para aldığın için,baban seni çekemesede 

Sevgi ve saygını esirgemedin sen ona yinede 

Gençliğin hep çalışmakla geçti 

Baban çoktan hakkın rahmetine erdi 

Çocukları büyüdü,boyunu bile geçti 

Bir baba olarak gururlanmanın vakti çoktan gelmişti 

Hatırladıkça geçmişta yaşadıklarımızı 

Beraber geçirdiğimiz onca hatırayı 

Dolu dolu yaşadın sen bu hayatı 

Seni çok özlüyorum canım babam 

Aramızdaki iletişimi hiç kimse anlayamadı 

Sadece iyi bir baba değil,iyide bir arkadaştın 

Yokluğuna hala alışamadım 

Seni çok özlüyorum canım babam 

Sadece bir baba değil,en iyi arkadaştın 

Ben hangi işe el atsam daima arkamdaydın 

Annem bana kızdığında sen hep benden yanaydın 

Yokluğuna alışamadım canım babam.. 

Bana güvenin hiç eksik olmadı 

Aramızda çok önemli bir bağ vardı 

Bu bağ ne korku nede saygıydı 

Bu resmen arkadaşlıktı.. 

En iyi arkadaşım seni çok özledim 

Daha yapacak çok işimiz vardı 

Bu kadar acele etmene gerek varmıydı 

Mekanın inşallah cennet olur 

Seni çok özledim benim canım babam. 

Çok bekledim senin için bu yazıyı yazmayı 

Seni çok özledim canım babam 

Allah günahlarını affetsin 

BENİM CANIM BABAM...... 

mayıs 2001 

siyah bereli', 'Çok bekledim senin için bu yazıyı yazmayı  Seni çok özledim canım babam....  Alın yazın sen doğduğunda kararmış  Validen Allahın rahmetine k...', ARRAY['Türk Edebiyatı','Şiir','Fatih Taşkın']::text[], 8.5, '{"poet":"Fatih Taşkın","poet_slug":"fatih-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/canim-babam-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Babam ''a Özeldir...', 'canim-babam-a-ozeldir-fatih-taskin-8fgwc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Unutmak isterken geliyor aklıma 

Rüyalarımda görüyorum ara sıra 

Saklasamda çok özlüyorum aslında 

Kalbim dayanmıyor bazen bu heyecana 

Boynuna sarılarak oturabilsem kucağına 

Öpseydik yine birbirimizi yalaya yalaya 

Küfrederdik Galatasaray maçlarında 

Sinirden yakardın hemen bi sigara 

Her zamanki gibi tabiki malbora 

İstikbalim derdin sen hep bana 

İmza bile atmıştık kader arkadaşlığına 

Senin sayende ayak bastım Türkiyenin yarısına 

Beraber yattık olmayan yataklarda 

Rüzgarlarda,fırtınalarda,yağmurlarda 

Hatta bazen demir yüklü kamyonlarda 

Belkide bir elektrik trafosunda 

Ama daima.............lunaparkta 

Her zaman el ele baş başa 

Birlikte imza attık yüzlerce hatıraya 

Lunapark deyince Kütahya gelir aklıma 

Sonra Afyon,Zonguldak,Simav,Sakarya 

Ordan Manisa,Salihli ve Soma 

Ve tabiki Balıkesir,İzmir-Aliağa 

Öncesinde ise Başkent Ankara 

Seni kolay kolay tanımayan yoktu bu camiada 

İsim yapıp meydan okudun yıllara 

Bu alemde bizimde ustamızdın sen; VELİ USTA... 

Öyle iyi birisiydinki herkes severdi seni 

Cömertliğine ve mertliğine çok güvenilirdi. 

Esirgemeden dağıtırdın,bakmadan cebindekine 

Doya doya oturamadın bile kendi evinde 

Hayatını tam yaşamaya başlamışken 

Yenik düştün malesef ecele.... 

Bu ilk yenilgi değildi be ustam 

Biz ne deplasmanlarda mağlubiyetler aldık 

İstikbalimiz için göğüs göğüse savaştık 

Aslanın ağzındakini çalışarak aldık 

Karlara,yağmurlara,çamurlara battık 

Ama daima ayakta kalıp,yıkılmadık 

Çünkü biz; 

Ne civata-somun,ne de antigron kablo ile 

Biz birbirimize sevgi ile bağlıydık 

Ama artık yoksun..... 

Belki gökyüzündeki yıldızlarda 

Belki Akdenizin yakamozlarında 

Belkide hemen  yanıbaşımda 

Belki de Ankara''da Karşıyaka mezarlığında 

Gittiğinde yoktum yanında 

Dokunamadım sana doya doya... 

Seni Çok Özlüyorum CANIM BABAM............ 

Seni unutamıyorum canım babam.. 

haziran 2002 

siyah bereli 

****6 kasım 2000 babamın vefat tarihidir.**** 

***O lunapark ustabaşısıydı****', 'Unutmak isterken geliyor aklıma  Rüyalarımda görüyorum ara sıra  Saklasamda çok özlüyorum aslında  Kalbim dayanmıyor bazen bu heyecana  Boyn...', ARRAY['Türk Edebiyatı','Şiir','Fatih Taşkın']::text[], 8.5, '{"poet":"Fatih Taşkın","poet_slug":"fatih-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/canim-babam-a-ozeldir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Takdim', 'takdim-fatih-taskin-anq1m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ilkokul yıllarım yabancı dizilerin 

çok meşhur olduğu zamanlardı.. 

bu yüzden ailem ve çevremdekiler 

dallas tan dolayı Chanlars dediler bana... 

ortaokulda okul takımındaydım; havam başka

ben gol atmaktaydım; trübünde kızlar bağırınca 

müdürün dikkatini çekmiş gelmiş adam maça

''''-o boyla nasıl vurdun o topa '''' bu çocuk resmen ''BOĞA''

lise dönemleri tecrübe artmasıydı 

futbol kulüblerinde yükselme çağımdı 

bu yüzden takım arkadaşlarımda 

taktılar adımıza TAŞKAFA..... 

merak saldım daha sonra futbol hakemliğine 

sınavlarına girdim kazandım hemde dereceyle 

kırmızı kart bile gösterdim Y.MAHALLE li erdem''e 

sonra adımızı çıkardılar....ne hakeme; 

y.okul(elektronik)   kazandım gittim balıkesire 

ortamlar,muhabbetler,dostluklar süperdi, şahane 

birgün sofra kurup oturduk karşıyakalı serhanların evde 

orda da adımız çıktı....dolduuur SAKİ '' ye.. 

askere gittim tankçı oldum siyah berem başımda 

görev yerim iskenderun gülcihanda... 

sonra; meslekçi(elktrik-elektronik)   oldum özel kampda 

yaptığım işlerden sonra adım çıktı ENSTAİN '' a. 

artık kendi sahamdayım; ankaramdayım evimde, 

tekniker olarak çalışıyorum bilgisayar sektöründe 

şimdi talip oldum dostluğunuza,sevginize,muhabbetinize 

ve karşınıdayım artık  antoloji.com.www. de 

                                                                           siyah bereli....', 'ilkokul yıllarım yabancı dizilerin  çok meşhur olduğu zamanlardı..  bu yüzden ailem ve çevremdekiler  dallas tan dolayı Chanlars dediler ban...', ARRAY['Türk Edebiyatı','Şiir','Fatih Taşkın']::text[], 8.5, '{"poet":"Fatih Taşkın","poet_slug":"fatih-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/takdim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'kapaliyiz', 'kapaliyiz-mustafa-tugrul-kosar-d48vq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu kalbim dertlerin en köhne yeri

Yıllarca gelmedi başka müşteri

Girmeye kalkışma sakın içeri

Doluyuz güzelim,ağzına kadar

Her bir köşesinde o isim yazar

Kapanmaz yarası durmadan azar

Zorlama ne olur patronum kızar

Doluyuz güzelim,ağzına kadar

Emretti yan diye ondan yanarım

Yaktığı bu ateş sönmez sanırım

Ben onu bilirim,onu tanırım

Doluyuz güzelim,ağzına kadar

Hergün ızdırabı zamlı vererek

Ağlattı avansın olsun diyerek

Büyüdü içimde taştı giderek

Doluyuz güzelim,ağzına kadar

Elinden bu hayat zindan olsa da

Geride tarifsiz acım kalsa da

Sevmişim bir kere zalim olsa da

Doluyuz güzelim,ağzına kadar

Kayboldu zamanla avuntularım

Çaresiz yaşattı hep anılarım

Ebedi sürgülü aşk kapılarım

Doluyuz güzelim,ağzına kadar

Kapalı güzelim,sonsuza kadar', 'Bu kalbim dertlerin en köhne yeri Yıllarca gelmedi başka müşteri Girmeye kalkışma sakın içeri Doluyuz güzelim,ağzına kadar Her bir köşesinde...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tuğrul Koşar']::text[], 8.5, '{"poet":"Mustafa Tuğrul Koşar","poet_slug":"mustafa-tugrul-kosar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kapaliyiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öss '' cilere', 'oss-cilere-fatih-taskin-1zxxk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'öss '' cilere 

Ne eşt ağırlığın momenti 

Ne de dairenin pi sabiti 

Olmasada gaaus yöntemi 

seni seviyorum ben,boşver ÖSS''yi 

Atmosferdeki hidrojen ve azot oranı 

Türevi,integrali,determinantı 

Fayda etmez pisagorun bağıntısı 

seni seviyorum ben,unuttum sınavı 

Mayoz ve mitoz bölünmeye 

Aklım ermez civanın çözünürlüğüne 

Hiç inanmadım zaten evrim teorisine 

seni sevdim ben,bakmadım ÖSS''ye 

Kaldıraçı,makarayı,tesisatı,bobinajı, 

Hatta iki zıt kutıplu mıknatısı 

Enerjiyi,akımı,gerilimi,endüktansı 

seni sevdim hep düşünmedim sınavı 

Periyodik cetveldeki element sayısı 

Hidrojeni,atomu,gümüşü,civayı 

Oldum olası sevemedim kimyayı 

Şafak sayar gibi bekledim haziranı 

İç açıların toplamıyla öğrendim geometriyi 

Oklid ve pisagor sevdirdi matematiği 

Bulmacalardaki sorularla biraz kimyayı, 

hep sevmişimdir zaten fiziği, 

ALLAH NASİP ETSİN HEPİNİZE BU SENE 

İSTEDİĞİNİZ ÜNİVERSİTEYİ.. 

                                                       siyah bereli.... 

not:kendim elektronik teknikeriyim.çok mutluyum.ve ben sayısalcıydım.bu yüzden sözelcilerden pek bahsedemedim.inşallah oda bi dahaki sefere', 'öss '' cilere  Ne eşt ağırlığın momenti  Ne de dairenin pi sabiti  Olmasada gaaus yöntemi  seni seviyorum ben,boşver ÖSS''yi  Atmosferdeki hid...', ARRAY['Türk Edebiyatı','Şiir','Fatih Taşkın']::text[], 8.5, '{"poet":"Fatih Taşkın","poet_slug":"fatih-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/oss-cilere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmaz', 'olmaz-fatih-taskin-mzagn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'olur mu...olabilir mi....olacak mı...? 

olmadı...... olmuyor....olmadı da.... 

ona aşık olduğumda gözlerimin içi gülüyordu.... 

kalbim tir tir titreyip yüreğim çarpıyordu.. 

hiç konuşmadan saatlerce bakışlarla anlaşır 

ortak yanlarımızın çoğunluğuyla yakınlaşır 

kafa yapılarımızın uyuşmasıyla gurur duyardım. 

hiç kırmadım ben onu,feda ettim herşeyi uğruna 

kalbimi yerinden sökmüştü,saçlarının arasından bir bakışıyla 

fiziksel reaksiyon,kimyasal tepkime hepsi bende değişti 

gerçek aşk bu olsa gerekti. 

bunca güzel şeyin devam edeceğini sanırken 

ilk defa çok korkmuştum telefondaki sesten 

ayrılmak istadiğini söylediğinde vurulmuştum beynimden 

gözlerim doldu,telefon düştü birden elimden... 

hep söylerdi:beni senin kadar kimse sevmedi 

aşkına layık olamadım ne olur affat beni 

anlam veremedim haliyle sordum nedenini 

gözden uzak olan gönüldende uzak olur gerekçesi 

oysa aşk mesafe tanırmıydı 

kalp çarpması,yürek sızlaması boşunamıydı 

boş kapı bulabilmek için kabul ettim arkadaşlığını 

ama o sert çarpmış malesef kapıyı..... 

denedim arkadaşlığı bakarken gözlerine 

yapmacık hareketler yapamadım nedense.. 

ulaen,çünkü aşık olmuştum ben o gözlere 

hala onu severken nasıl diyebilirdim arkadaş olalım diye 

anlayacağınız dostlar; olmadı...olmadı...olmadı.. 

severken arkadaşlık,aşıkken dostluk olmadı.. 

olanlara saygı duyarım,istisnadır belki... 

hepinize armağan olsun...yazan SİYAH BERELİ..............', 'olur mu...olabilir mi....olacak mı...?  olmadı...... olmuyor....olmadı da....  ona aşık olduğumda gözlerimin içi gülüyordu....  kalbim tir t...', ARRAY['Türk Edebiyatı','Şiir','Fatih Taşkın']::text[], 8.5, '{"poet":"Fatih Taşkın","poet_slug":"fatih-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/olmaz-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benim', 'sen-benim-fatih-taskin-h2zn4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sabah ilk uyandığımda resmine bakarım 

Gözlerinin içine dalar kaybolur giderim 

O ipek saçlarına dokunmak 

Doya doya koklamak isterim 

Yanağındaki gamzeye bir buse kondurmak 

Ve sonra seni doya doya öpmek isterim 

Ellerini,ellerime kenetleyip 

Sonsuza kadar sana SENİ SEVİYORUM demeyi 

Ve gökyüzüne avazım çıktığı kadar 

Ben seni çok seviyorum demeyi isterdim 

Ama karagözlüm... 

Elini tutamasamda,saçlarını okşayamasamda 

Gözlerinin içinde kaybolamasamda 

Şunu bilki; 

Seni yine çok seviyorum 

Senden ayrı gaçen her günüm,her saatim 

Ve hatta hatta her dakikamda 

Bu hasretlik bizi zaman zaman ayırsada 

Sana olan sevgim asla kaybolmayacak 

Sen benim 

Soğuk günlerimde çıkan kış güneşim 

Sen benim 

Baharda açan menekşe çiçeğim 

Sen benim 

Gece ayazlarındaki ılık esintim 

Sen benim 

Uğrunda can verebileceğim meleğim 

Sen benim...... 

Sen benim....... 

11,01,2002 

siyah bereli', 'Sabah ilk uyandığımda resmine bakarım  Gözlerinin içine dalar kaybolur giderim  O ipek saçlarına dokunmak  Doya doya koklamak isterim  Yanağ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Taşkın']::text[], 8.5, '{"poet":"Fatih Taşkın","poet_slug":"fatih-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sen-benim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkardık Evden Bazı Geceler', 'cikardik-evden-bazi-geceler-fatih-taskin-rjtcd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'çıkardık evden bazı geceler 

delice bir sevinçle,gözlerimiz ışıl ışıl 

ertesi gün okula gideceğiz diye 

ütülediğimiz elbiselerin ütüsünü 

bozmanın zevkini tadarak.. 

bir başka gezerdik biz Balıkesir gecelerinde 

delikanlıca! 

çıkardık evden bazı geceler 

osman* abiye gözükmeden 

sessizliği kıskandıracak kadar sessizce 

ve bir o kadarda 

erkekçe! 

(*ev sahibi) 

aramızda topladığımız paralarla çekirdek 

alır,koşar adım giderdik 6eylül parkına 

sabaha kadar oturup muhabbet eder; tekrar 

dönerdik güzel öğrenci evimize 

gizlice! 

çıkardık evden bazı geceler 

otostop yapmak için gar ''ın önüne gider 

her defasında bir kamyon durdurup, 

heyecanla susurluğa giderdik 

delice! 

kamyon sohbetleri güzeldi 

kaptan da kafa dengi olduğunda ise 

sohbet hemen açılırdı. 

orhan baba da çalıyosa radyoda 

o zaman eski aşklar hüzün katardı geceye 

biz bütün bunları meşhur ayran ve tost için yapardık 

ayranı içtikten sonra ise bütün bu eziyete 

deydiğini anlardık...veee 

tekrar otostopla dönerdik balıkesire 

evimize..öğrenci evimize.... 

sevinçle! 

çıkardık evden bazı geceler 

geze geze giderdik terminale ya da gar''a 

istanbula ya da ankaraya veya daha başka yerlere 

gidenleri seyretmeye giderdik terminale 

gazetecinin önündeki dergilere bakardık, 

el sallardık gidenlere..... 

hüzünle! 

uykumuz hala gelmedi ise o zaman 

tren garına giderdik. 

sabah ezanının hemen sonrasında gelirdi 

ege ekspres 

uykudan kanlanmış gözlerle vagondan inen 

yolcularla dolardı 

gar büfesinin ve börekçinin önü 

gürültüyle! 

bizler yerimizde duramaz sabırsızlıkla beklerdik 

trenin hareket düdüğünü.... 

az sonra hantal lokomotif homurdanır 

ihtiyar raylar gıcırdarken 

yüzümüzde o muzip öğrenci gülümsemesi 

el sallardık kimsesiz yolculara 

belki... 

belki hayra gireriz diye! 

çıkardık evden bazı geceler 

serhanlara giderdik 

eğer evde yoklar ise 

kapının yanındaki duvara 

yazı yazmanın keyfini çıkartarak 

yazı yazardık. 

duvara en çok yazıyı ben yazmıştım 

ölümsüzleşen vede tarihleşen yazı da 

yine bana aitti.... 

''''Herkes İçki İçebilir ama Herkes Saki* Olamaz'''' 

(*saki=siyah bereli) 

çıkardık evden bazı geceler 

aklımızda sinemaya gitmek fikri varken 

biz sinemaya gitmez 

hemen oracıktaki Bahadırların eve giderdik 

ev öyle bir yerdeydiki 

ev demek mümkün değil; otel 

şöyle demek daha doğru olurdu: 

''yol geçen hanı'' 

herhalde! 

çıkardık evden bazı geceler 

aklımızda hiç yokken 

birden izmire gitmek 

fikri çıkardı ortaya 

nedense işin en garip tarafı 

bu fikirler hep benden çıkardı 

hemen hazırlık yapar 

en şekil elbiselerimizi giyer 

hiç birşey olmamış gibi 

birden kendimizi EGE Ekspres in 

numarasız ve pis kokulu koltuklarında bulurduk 

bir vururduk kafayı Savaştepede 

gözümüzü açtığımızda İzmir Çiğili, ve 

ve ver elini Basmane....! 

biz en güzel günlerimizi hep böyle yaşadık 

üniversite günleri güzeldi bee... 

bir başka gezerdik biz balıkesir de 

korkusuzca! 

ÇIKARDIK EVDEN BAZI GECELER... 

                                                                 mayıs 1999 

                                                                 siyah bereli', 'çıkardık evden bazı geceler  delice bir sevinçle,gözlerimiz ışıl ışıl  ertesi gün okula gideceğiz diye  ütülediğimiz elbiselerin ütüsünü  bo...', ARRAY['Türk Edebiyatı','Şiir','Fatih Taşkın']::text[], 8.5, '{"poet":"Fatih Taşkın","poet_slug":"fatih-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":98,"source_url":"https://www.antoloji.com/cikardik-evden-bazi-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeryüzü tiyatrocuları', 'yeryuzu-tiyatroculari-mustafa-tugrul-kosar-93fm7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Adem le Havva dan başlayıp, 

Bugünlere getirdik hayat oyununu 

Adı sevgiydi 

Maksat büyük seyirciyi mutlu etmek 

Başroldeki oyuncuya uymak 

Kitaptaki kuralları uygulamaktı 

Bu sahneden ne jönler,ne figuranlar geçti 

Biz son perdeyi oynuyorduk 

Oyun bitince, 

Büyük seyirciyi gururla selamlayacak, 

O da bize çiçekler atacaktı 

Yaşlı salon gül bahcesi olacaktı 

Senaryo da öyle yazıyordu 

Çoğumuz okumadı o kitabı 

Çoğumuz unuta unuta oynadı 

Zamanla oyuncular ikiye bölündü 

Ezberciler, kuralcılar 

Oyunun adı menfaat oldu 

Kötü senaristin yazdıklarına yöneldik 

Her tarafa kan sıçradı 

Tutuşan eller yoktu 

Biz sanat icra etmeyi bırakıp 

Birbirimize girdik 

Alkışlar iyice azaldı 

Beceremedik,ayakta duramadık 

Düşünmedik 

Yok saydık büyük seyirciyi 

İnkar ettik 

O da ibretle bize baktı 

Ne geldiyse eline fırlattı yüzümüze 

Öylesine mahvettik ki oyunu 

Hiç varolduğumuza değmedi 

Yıkılsın bu salon 

Yansın bu sahne 

Çünkü... 

Tanrı bu oyunu hiç beğenmedi', 'Adem le Havva dan başlayıp,  Bugünlere getirdik hayat oyununu  Adı sevgiydi  Maksat büyük seyirciyi mutlu etmek  Başroldeki oyuncuya uymak  ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tuğrul Koşar']::text[], 8.5, '{"poet":"Mustafa Tuğrul Koşar","poet_slug":"mustafa-tugrul-kosar","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/yeryuzu-tiyatroculari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Bir Cuma', 'yine-bir-cuma-fatih-taskin-706c5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hacıbayram camisinin avlusunda 

Bikmem bu kaçıncı cuma 

Allah-ü teala kabul etsin 

Kıldığımız namazı güneşin altında 

Avludaki kalabalığı gördükçe 

Artıyordu sayı gittikçe 

Allah müslümanları birbirinden ayırmasın 

Çok yakıcı olan bu güneşte 

Bazı değerlerimiz hala korunuyordu 

Çok şükür insanlarımız namaz kılıyordu 

İbadetini kimse eksik etmesin 

Çünkü Allah müslümanları seviyordu. 

Bu birlik ve beraberlik eksik olmasın 

Garibanlar zor durumda kalmasın. 

İman ve inancı tam olanlara 

Allahın rahmeti ve bereketi kalsın..... 

17,08,2001 ankara 

siyah bereli', 'Hacıbayram camisinin avlusunda  Bikmem bu kaçıncı cuma  Allah-ü teala kabul etsin  Kıldığımız namazı güneşin altında  Avludaki kalabalığı gö...', ARRAY['Türk Edebiyatı','Şiir','Fatih Taşkın']::text[], 8.5, '{"poet":"Fatih Taşkın","poet_slug":"fatih-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yine-bir-cuma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlü Sözlerim 1', 'ozlu-sozlerim-1-fatih-taskin-5ol5b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tapma dünya malına; hasret kalırsın dostluğa...

Hasret kalırsan dostluğa; fayda etmez dünya malıda....', 'Tapma dünya malına; hasret kalırsın dostluğa... Hasret kalırsan dostluğa; fayda etmez dünya malıda.......', ARRAY['Türk Edebiyatı','Şiir','Fatih Taşkın']::text[], 8.5, '{"poet":"Fatih Taşkın","poet_slug":"fatih-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/ozlu-sozlerim-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duvar saati', 'duvar-saati-mustafa-tugrul-kosar-jcbr5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir başka karanlık bu gece 

Çığlıkların dili kopmuş, sağır duygular 

Her zamanki gibi karamsarlık 

Ne başka türlüdür bu yalnızlık? 

Duvardaki saatin sesi tokatlıyor ümitlerimi 

Ellerim olmayan ellerini tutmuş 

Hırs vermiş bakışların, 

Şimdi...şimdi titreyen bir yumruk alnımda... 

Karanlık odama sinmiş kokun bütün dişiliğiyle 

Kapıda, duvarda, her yerde gözlerin 

Gözlerin...incecikti, ela... 

Bana bakardın 

Beni görürdün 

Dokunur, öperdin birde... 

Nerdesin, nerelerdesin 

Belki fırında kıvılcım gibi parlayan evlerin birinde 

Yada bambaşka bir yerde, bambaşka bir şehirde... 

Duvardaki saatin sesi tokatlıyor ümitlerimi 

Perdeden yüzüme yansıyan sokak lambasının ışığı 

Belki, bir umut 

Ansızın çıkıp gelecekmişsin, 

Dönecekmişsin dağınık saçlarınla 

Saçların... 

Uzundu, tutardım, okşardım, koklardım birde 

Duvardaki saatin sesi tokatlıyor ümitlerimi 

Alıp götürüyor beni uzak yerlere 

Yağmur yağan dağlar 

Karanlık çöken vadiler 

Ay tutulması gibi tutuluyor yüreğim 

Ağlamak mı? 

Ağlamak... 

Dizlerine uzanıpta güzeldi 

Annesine muhtaç çocuk gibi gözlerine bakarak 

Dalarak güzelliğine, 

İçerleyen nefesle adını sayıklayarak 

Bir baykuşun tafrası yankılanıyor sokakta 

Uzak yollardaki arabaların sesleriyle diriliyor, 

Hayalinle perdelenen bakışlarım 

Bir an meçhullerden çıkıp koşmak istesemde 

Bir yıldız ulaşılmazlığında, 

Beraber yürüdüğümüz kaldırımlar 

Ağaçlık, loş ışıklı, 

Defalarca öpüştüğümüz kaldırımlar... 

Duvardaki saatin sesi tokatlıyor ümitlerimi 

Seninle geçen her saniye bir masal gibi şimdi 

En başından başlıyor ilk tanıştığımız an 

İlk utanışın seviyorum derken 

Gözlerime bakamayışın 

Her güzelliğin zirvesinde omuz omuzayken, 

Ansızın habersiz gidişin... 

Tablada söndürdüğüm son sigaram 

Son gözyaşlarım ıslak kağıtda 

Son hayalini kuruşum 

Seni son özleyişim 

Kapıya bakıp son bekleyişim 

Duvardaki saatin sesi tokatlıyor ümitlerimi 

Ağırlaşan başım düşerken 

Biliyorum... 

Bir yerlerde sabah oldu bile 

Çoktan oldu sabah, çoktan...', 'Bir başka karanlık bu gece  Çığlıkların dili kopmuş, sağır duygular  Her zamanki gibi karamsarlık  Ne başka türlüdür bu yalnızlık?  Duvardak...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tuğrul Koşar']::text[], 8.5, '{"poet":"Mustafa Tuğrul Koşar","poet_slug":"mustafa-tugrul-kosar","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/duvar-saati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel', 'guzel-nusret-turan-6mzkn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sence biraz geçkinim

Aşk şarabı içmişim

Kerem gibi yanmışım

Yakma beni sen güzel.

Fidan gibi boyunla

Can alıcı gözünle

İnci gibi dişinle

Kesme beni sen güzel.

Ne güzel gülüşün var

Giydiklerin sana dar

Genç olsam canım kurban

Git yoluna sen güzel.

Yarım kalır aşkımız

Terse döner çarkımız

Bitiverir şarkımız

Yıkma beni sen güzel', 'Sence biraz geçkinim Aşk şarabı içmişim Kerem gibi yanmışım Yakma beni sen güzel. Fidan gibi boyunla Can alıcı gözünle İnci gibi dişinle Kes...', ARRAY['Türk Edebiyatı','Şiir','Nusret Turan']::text[], 8.5, '{"poet":"Nusret Turan","poet_slug":"nusret-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/guzel-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dudağında Dudak İzi Olmasın', 'dudaginda-dudak-i-zi-olmasin-murat-demir-37hwr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Belki diye bekleterek avutma

Sevda aştır yiyeceksen soğutma

Eğer bana geleceksen unutma

Dudağında dudak izi olmasın

Cana, candan arıyorsan bir saha

Al  aşkımı ne vereyim ben daha

Bu sahaya gireceksen sakın ha

Yanağında yanak izi olmasın

Benim kadar seveceksen ben kulu

Olacaksan bu sevdaya tapulu

Güller gibi buram buram kokulu

Saçlarında parmak izi olmasın', 'Belki diye bekleterek avutma Sevda aştır yiyeceksen soğutma Eğer bana geleceksen unutma Dudağında dudak izi olmasın Cana, candan arıyorsan b...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dudaginda-dudak-izi-olmasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kedi', 'kedi-hatice-ari-f6ydk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''''Duvarlara yakın yürürüm,

Kedilerin göçünü engellerim''''

Dedi; 

Çekti gitti...

Geride

Ne taş bıraktı,

Ne duvar,

Üzerine yuva yapan

Kırlangıçlar,

Fısıldamıştı, usulca; 

''''Uzak dur,

Yakından,

Yakın ol,

Uzakken,

Ki,

Ağlama; 

Ardından; 

Giderken...

Gidemez,

Uzakta edemez; 

Kuşlar yalan söylemez,

Kedinin hatırı var...''''

                                     Kedicik', '''''Duvarlara yakın yürürüm, Kedilerin göçünü engellerim'''' Dedi;  Çekti gitti... Geride Ne taş bıraktı, Ne duvar, Üzerine yuva yapan Kırlangıç...', ARRAY['Türk Edebiyatı','Şiir','Hatice Arı']::text[], 8.5, '{"poet":"Hatice Arı","poet_slug":"hatice-ari","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kedi-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun...!', 'yoksun-nazife-abayli-cw6oj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Arkası kesilmiyor yokluğunun, 

Biraz daha üstüme gelirse, 

Gözlerim dolacak. 

Olmamışlığına kaptırdım kendimi, 

Gidiyorum...... 

Yoksun, 

Olamazsın da değil mi......? 

Özlemek nedir bilir misin? 

Gözlerin dolarken özlemekten, 

Yüreğinin çırpınışını, 

Tarif edebilir misin? 

Adını koyabilir misin? 

Hissettiklerinin. 

Olmamışlığına kaptırdım kendimi, 

Gidiyorum..Yoksun...!', 'Arkası kesilmiyor yokluğunun,  Biraz daha üstüme gelirse,  Gözlerim dolacak.  Olmamışlığına kaptırdım kendimi,  Gidiyorum......  Yoksun,  Ol...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yoksun-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Sıkıldı..!', 'canim-sikildi-nazife-abayli-utnv7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne mal ister canım,

Ne mülk.

Ne ekmek ister,

Ne de yemek.

Uçmak ister gönlüm,

Kuş oluvermek.

Derken...............

Oluverdim.

Serçe mi? Bülbül mü? 

Yoksa kanarya mıydım? 

Bilmiyorum.

Dolaştım göklerde,

Yeryüzünü gördüm.

Canım sıkıldı.....

İnsanları gördüm,

Bir tarafta riyakarları,

Diğer tarafta,

Sevda ateşiyle yananları,

Dost dost diye ağlayanları.

Kanatlarımı bir günlüğüne

Takıvarmek geldi onlara.

Benim yerime uçsunlar,

Uyansınlar diye.

Çocukları gördüm,

Sapanla kuşlara,

Taş fırlatan çocukları.

Canım sıkıldı......

Alıp gagamla,

Yuva yaptığım ağaçtan,

Bir zeytin dalı,

Üstlerine atıvermek geldi içimden.

Arabaları gördüm sonra,

Egzosu patlayan arabaları.

Kurşun hızıyla kalkan,

Cayırtıyla duran,

Arabaları gördüm.

Akıttıkları kanı,

Söndürülmüş enkazlarını gördüm.

Canım sıkıldı...

Kilometre göstergelerinden,

Doksandan sonrasını,

Silmek geldi içimden..

Seni gördüm sonra.

Sapsarı olmuş benzin,

Kendi kabuğunun içinde,

Düşler kuruyordun durmadan.

Unutamadığın,

Bir zamanlar gönlünü hoplatan,

Yarinin üstüne,

Düşler kuruyordun.

Canım sıkıldı......

Küçük bir taş alıp gagamla,

Üstüne atıvermek geldi içimden.

Atıp ta kabuğunu kırıvermek.

Kanadımdan bir tüy koparıp,

Adına şiirler yazıvermek..', 'Ne mal ister canım, Ne mülk. Ne ekmek ister, Ne de yemek. Uçmak ister gönlüm, Kuş oluvermek. Derken............... Oluverdim. Serçe mi? Bülb...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/canim-sikildi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklımda Kurt Var', 'aklimda-kurt-var-menevis-koylu-ysd9i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'aklımı

kurt kemiriyor

kelime kelime

harf harf deviriyor

un

ufak

olu-

yorum

kendimle 

baş

edemiyorum

vallahi

tilkilerle değil sorunum

sadece

kuyrukları birbirine değmesin diye

uğraşı-

yorum', 'aklımı kurt kemiriyor kelime kelime harf harf deviriyor un ufak olu- yorum kendimle  baş edemiyorum vallahi tilkilerle değil sorunum sadece ...', ARRAY['Türk Edebiyatı','Şiir','Meneviş Köylü']::text[], 8.5, '{"poet":"Meneviş Köylü","poet_slug":"menevis-koylu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aklimda-kurt-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedenim Zorda', 'bedenim-zorda-yusuf-yalcinkaya-dixa0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gönül bahçesinde hazan rüzgarı

Estikce esiyor bedenim zorda

Takılmış bu gönül hasret ağına

Çırpınsam ne fayda bedenim zorda

Çaresiz dertler hep aşka verildi

Sorunlar engeller ardarda geldi 

Korkusuz gözlerim aşka yenildi 

Aktıkça akıyor bedenim zorda

Dertlerin koruymuş hasret ateşi 

Saplanmış canıma zulmün pençesi 

Sonunda ben oldum aşkın kölesi

Umutlar,hayaller bedenim zorda', 'Gönül bahçesinde hazan rüzgarı Estikce esiyor bedenim zorda Takılmış bu gönül hasret ağına Çırpınsam ne fayda bedenim zorda Çaresiz dertler ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Yalçınkaya']::text[], 8.5, '{"poet":"Yusuf Yalçınkaya","poet_slug":"yusuf-yalcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bedenim-zorda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işık konisi-1', 'isik-konisi-1-akin-akca-u22uk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çarşaf gibi kabarıyor ve gerili-büzüşmüş, deniz 

Ve biliyorum.. kabarık, yaprak yaprak kan, damardaki; 

(Devşiriyor kendini, harmanlayan, burgaçlardan; 

Varılıyor tek bir hortuma, yeryüzünü talan eden.)

Biziz dökülen sonbahar ağaçları gibi. 

Yetkin bir orak, öyleyse getiriniz! 

Hasat mevsimi için değil –

değil ya da sırf dağıtmak adına kendi karanlıklarımızı 

-yeniden başlamak için değil: 

Bulunan tek eminlik, iki-arpa boyu’nda. 

Senin arkandan yaklaşan hayalet şehir 

Bir başkalaşım’da, kasaba cafe’sinde otururken sen: 

Yaş yerine yaş var senin gözbebeklerinde; 

Mutluluk gibi, uçurtma gibi; acıyı da tattın, hüznü de. 

Kanattır senin büyülü peri -olup rüzgar- sürükleyicin 

Ama unutma göze alamadığını düşünmeye

(Ki bir düşüncedir, bir an''lık verilir.) 

Gotik kıvrımlardadır yine, karanlığı kabul etmeyişin. 

 İşte bu ışık konisinin içinde her bir şey.

Her olay, mutlak geçmişten.

An’ını etkileyen, olay’ın ve geleceğe ileten kendisini, 

(  Yürü… tay tay…)        Berduşluk, an’lık. 

Uzay-zaman, dört boyutlu, 

Üç boyutlu’da ifadesini buluyor. 

Fakat anti madde’den sağlanan, 

Duvarlarını uzayın daha bir bükerek 

Işık hızını geçmemizi sağladı bize. 

Sonsuz’du; içine ve dışına yumurtlatan, 

Kabarcıkları; kuantum havuzunda. 

Ve artık bu kum saatini andırır

(Bu kuantum kum havuzunda)        ışık konisi dağıldı. 

Geçmiş, gelecek ile hür artık - 

Kuantum köpüğü, birbirinden bağımsız 

Evrenler oluşturmayacak artık 

(Enerji debeleniyor inanç ile bu ışık konisinde.) 

- Bu koninin içine dahil, öte yer de.

--

uçanbalik can dostumuza bu şiir için ‘düşündüren kısa

konuşmamız’dan ötürü teşekkürlerimi sunarım', 'Çarşaf gibi kabarıyor ve gerili-büzüşmüş, deniz  Ve biliyorum.. kabarık, yaprak yaprak kan, damardaki;  (Devşiriyor kendini, harmanlayan, bu...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/isik-konisi-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işık konisi-2', 'isik-konisi-2-akin-akca-6xm1d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '“Dirlik aslanıyız, dirlik:

Dalga dalga gelenlerin sancısıyız; 

Öyle sendeleyip de durmayız, düşersek düşeriz. 

Kazansın çünkü tecrübe. 

Düşsek de kalkarız, ama az düşeriz; 

Düştükçe düşmeyi öğrenenlerdeniz! ” 

Diye haykırdı, iki ayrı yaka’sını 

Bir arada tutan ortak bölge, 

Işık konisinin: 

Sonra, “karnım acıktı.” dedi. 

Sezgi duyan insanları mı düşlüyorsun çevrende? 

Kişi için pek zor; duymayan, sezgi bile! 

Söz edemeyiz ne olduğundan, varlığın; 

Varlığın ardında ‘olmayan şey’, yok iken. 

Boşluğun dışında ne var denilebilir mi? 

Hiç, bir şey sezilebilir mi, var olan zaten? 

-Öğrenemez tembellik bilmeyen 

Bir ağustos böceği, nağmeleri; 

Ancak bir meşale ilerler güvenle bir mağarada: 

Işığı göremezsin kor gibi yanan alevin içinde; 

Bir ışın, hızını arttırmaz başka bir ışının; 

Onun üzerine binen. - 

(Öte yandan, aslında aynısını demek 

ya -bir ifadesidir matematik veya 

Deneyimleme, bunun da.)

Ya da kum saatinin dışında? 

Işık konisinin dışında - 

Bir yönüyle geleceğe akan; diğeriyle, geçmişe … 

Ve oradadır, orta yerdedir: 

Köprü, gelecek ile geçmişi tutan; 

(Yitiklerden fısıltı seslenen-kadim öngörü’sü.)

Sanki omurgasıdır bu kum saatinin 

Geçmiş etkiler o noktayı, bu omurgayı, 

bu bilyeyi ve aynı konum etkiler geleceği. 

* 

Dikey sırıtan bu kum saati 

Gelecek, yukarısı onun belinden, mazi aşağısı.

Peki geçmiş istikbali doğrudan da etkiler mi; 

Kum saatinin belini- köprü’yü- an’ı etkileyerek, 

Etki istikbale edebilmesi gibi? 

: Sezgi duyan insanları mı düşlüyorsun çevrende; 

Kişi için pek zor; duymayan, sezgi bile! 

Bazıları için diyebiliriz, durum buysa

Doğrudan da etkileyebilir 

Şu halde geçmiş, geleceği.

* 

Işık hızına yakın uzaklaşan galaksilerin; 

Sadece göze aldatmaca olduğuna saplanıp 

Kalmış bir zihin; özgür olabilir, ne kadar? 

‘İnadına sahte kurgulanan bir 

Fiziksel teorem’ gibi anlamsız bir şeydir bu:

Düşünmeseydi Copernicus ve 

Düşünseydi öküzün boynuzlarını; 

O gazaba getirmez miydi asıl, öküzü? 

Batıl’ı savunmadı, düşündü - 

Yine de bir din adamıydı:

Yaratıcı olabilir bir din adamı, düşündüğünde; 

Yarış kazanması en muhtemeldir 

Maratoncunun; olağandır piknik tip olması, 

Tonton, semirtilmiş, besili bir çocuğun. 

Işık hızına yaklaşan bir hızda devinen; 

Yüz milyarlarca güneşi içinde barındıran 

Gökadaların da ışığa yakın hızda oluşu 

Böylesine olağan - 

Göz ile sadece algılanıldığı sanılan. 

Işığın hızını kovalaması galaksilerin 

Göreli bir şey midir sanki? 

Hidrojen burada ve orada aynısı: 

Atom burada ve o kuasar’larda; 

Daha ötede kuasarlar on iki milyar ışık yılından 

-Kolay ise bunu hissetmek, 

Canın’ın kanında … 

* 

İnsanların uzaklaşması değil 

Gidişatına paralel, gökadaların. 

İnsanlardan, kendileri mi sebep oluyorlar; 

Galaksilerin uzaklaşmasının? 

Aslında Copernicus’un,

Çelişmez görüşüyle bu: 

Din adamıydı o; ama gerçeği 

Buldu düşünerek, bir cümle içerisinde. 

Kutsal kitaplardaki umudu bilirsin: 

“Ol! ” der ve ‘Olur’ 

Yani ‘ilham’ = Copernicus’un yanılgı 

Olmayışı, bu da eşittir 

Evrendeki galaksilerin insanlar tarafından 

Uzaklaştırılışının; kotarılmayışı, 

Galaksiler tarafından... 

Ki bunda bir nokta daha var ki önemli: 

İnsanlar bunu yaparken gerçekten bilmiyor; 

Bilmeleri ama onların, 

En güzel’e yol almak için de gerekmiyor.

Yani her şey zaten var; sadece anlık olaylar 

Ortaya cıkarıyor, olabilecek iyi ve kötü''yü. 

Buna karşı, iyi ve kotu içimizde; 

Fakat ayırmak onları birbirinden, elimizde … 

- 

Not: güneyden can dostumuza, bu konuda 

kısa görüş alışverişimiz için teşekkür ederim', '“Dirlik aslanıyız, dirlik: Dalga dalga gelenlerin sancısıyız;  Öyle sendeleyip de durmayız, düşersek düşeriz.  Kazansın çünkü tecrübe.  Düşs...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":99,"source_url":"https://www.antoloji.com/isik-konisi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tiryakiye Nasihat', 'tiryakiye-nasihat-remzi-zengin-mcmx9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mekan küçük, oda dar

Şu sigarada  ne var

Hepten sağlığa zarar

Sakın sigara içme

Parası cepten gider

Dumanı hasta eder

Hele görenler ne der

Sakın sigara içme

Hiçbir faydası yoktur

Zararı dersen çoktur

Zaten kendisi ottur

Sakın sigara içme

Büyük sözünden çıkma

Her yerde çakmak çakma

Paranı boşa yakma

Sakın sigara içme

Dön geriye çark eyle

Sigarayı terk eyle

Kendine ev bark eyle

Sakın sigara içme

Remzi''nin sözün dinle

Ne hasta ol, ne inle

At yere çiğne kinle

Sakın sigara içme

(31 mart 1995)', 'Mekan küçük, oda dar Şu sigarada  ne var Hepten sağlığa zarar Sakın sigara içme Parası cepten gider Dumanı hasta eder Hele görenler ne der S...', ARRAY['Türk Edebiyatı','Şiir','Remzi Zengin']::text[], 8.5, '{"poet":"Remzi Zengin","poet_slug":"remzi-zengin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/tiryakiye-nasihat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızların Altında', 'yildizlarin-altinda-omer-bedrettin-usakli-v0jqz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Benim gönlüm sarhoştur

Yıldızların altında

Sevişmek ah ne hoştur

Yıldızların Altında

Sular rüzgarı dinler

Aşıklar hep serinler

Çoban yolları inler

Yıldızların altında

Yanmam gönlüm yansa da

Ecel beni ansa da

Gözlerim kapansa da

Yıldızların altında

Mavi nurdan bir ırmak

Gölgede bir salıncak

Bir de ikimiz kalsak

Yıldızların altında

Ne keder ne yas olur

Çakıllar elmas olur

Bir kadeh bir tas olur

Yıldızların altında

Ettiğim ah değildir

Bahtım siyah değildir

Buse günah değildir

Yıldızların altında', 'Benim gönlüm sarhoştur Yıldızların altında Sevişmek ah ne hoştur Yıldızların Altında Sular rüzgarı dinler Aşıklar hep serinler Çoban yolları...', ARRAY['Türk Edebiyatı','Şiir','Ömer Bedrettin Uşaklı']::text[], 8.5, '{"poet":"Ömer Bedrettin Uşaklı","poet_slug":"omer-bedrettin-usakli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yildizlarin-altinda-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-unutulmus-adam-14zss', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Herşeyimle gidiyorum bu şehirden

