INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Kişiye Bir Dünya (Senfonik Şiir)', 'i-ki-kisiye-bir-dunya-senfonik-siir-umit-yasar-oguzcan-6d8t3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Birinci Bölüm:

Kader Kapıyı Çalıyor

(Andante) 

Gelme diyorsun

Bu gel demektir

Birazdan güneş doğacak

Dolu dizgin atlılar geçecek yüreğimden

Seni düşüneceğim

Gümüş mahmuzların parlaklığında

Yağmur nal izlerini örtmeden

Sana geleceğim

Bekle beni

Hindistan ‘da Banaras şehrinde seni aradım

Ganj ‘ın sularında lanetlenmiş insanlar yıkanıyordu

Ganj ‘ın suları pisti bulanıktı

İçtim

Bir kadın tanıdım Haydarabat ‘da

Cüzamlıydı güzeldi üstelik

Sana benziyordu

Etli dudakları vardı

Brahman mabetlerinde seviştik üç gün üç gece

Taşların üstünde yattık

Bir hayvan tarafımız vardı alımlı

Bir Tanrı tarafımız vardı iğrenç

Bir insan tarafımız olacaktı

Aradık üç gün üç gece

Bulamadık

Bir Tanrı tarafımız vardı korkunç

Sevemedik

Sonra Nijerya ‘da Mozambik ‘te Altınsahillerinde

Kulaklarımda ulu ormanların uğultusu

Vahşetin musikisini dinledim yeşil yeşil

Zifir gibi bir yalnızlıktı içimde yokluğun

İri bir memeydin kalçaydın avuçlarımda

Belki bir tutam tuzdun kirli

Seni düşündükçe susuyordum

Nehirler göller kandırmıyordu beni

O kadınlara gidiyordum

O bakır tenli kadınlara

O kadınlarla da yattım

Adam boyu yaprakların üzerinde

Boyanıp boyanıp yeryüzüne çıkıyorduk derinlerden

Yorgundum

Kuşkuluydum

İliklerime kadar bendim

Bir yeşildim

Bir beyazdım

Karanlıktım

İnsan eti yiyenler anladı beni

Kanarya adalarında

Bir kamış kulübede iki ayna buldum

Birinde ellerim vardı kemik kemik

Parmaklarım beni çağırıyordu sana

Birinde gözlerim vardı

Ağlıyordum

Çiğnenmiş otlara döndüm

Ağlamaklı denizlere

Köpek balıklarının azı dişleri avutmaz beni

Bir gemiydim 

Battım

Santa – İsabelle adasının önünde

Şimdi 3200 metre derindeyim

Sana ahtapot gözleri topluyorum

Sana mürekkep balıklarının gözyaşlarını getireceğim

Bırak beni

Yosunlarla bir çeşmeden su içiyorum

O derinliklerde bir mağarada buldum kendimi

Önce garipsedim çıplaklığımı

Utandım

Sonraları alıştım güzelliğime

Bir elim sendin

Bir elim ben

Ayaklarımı göremezdin

Öyle uzaktaydı

Sağ kolumu Mekke ‘de kestiler şafak vakti

Utanmaz yalnızlığımla kaldım çaresiz

Bitmez

Haçlı seferleri boyunca anlatsam maceramı

Yakına gel

Dört yanımız iri ıstakozlarla dolu

Yalnız değiliz

Tuk ki bu tuzlu balıklarda benim yüreklerim çarpıyor

Tut ki gözümün yarısı elmada yarısı kapanık

Tut ki ben beyaz peynirim ben zeytinim

Al

Ekmeğine katık et beni

Dufy ‘nin bir sokağı vardı bilir misin

İlkin seni o mor sokakta gördüm

Temmuzun ondördüydü

Bütün itliği üzerindeydi güneşin

Bir yeşil elbisen vardı

Bir siyah ayakkabın vardı

Bir gözlerin vardı

Bir dudakların vardı

Ama ben yoktum o sokakta

Tahiti adalarında

Gaugin ‘le seni düşünüyordum

Absent kadehlerinde ellerini içiyordum yudum yudum

Dufy ‘nin sokağı aklıma nereden geldi

Bir çift zar aldım

Attım gökyüzüne

Adis-Ababa şehrine düştü

Adis-Ababa şehrinde kadınlar

Hepyek bakıyordu yüzüme

Yüzümde cinayetler işleniyordu her gece

Kadmiyum kırmızısından kanlar akıyordu nehir nehir

Sen baksan görürdün

Her gözüme bir düşeş oturmuştu

Sen görsen anlardın

Titanyum beyazı yalnızlığımı

Budapeşte köprüsünün üzerinde

Bir çingene falıma baktı

Dedi üç günde öleceksin

Ben üçbin yıldır seni arıyorum

Kapılara sığmıyor umutsuzluğum

Lağım kokuları gibi çirkef gibi kederliyim

İçimden dünyayı ipe çekmek geliyor

Cümle yıldızlar şahidim olsun

Yapmazsam adam değilim

Şanghay ‘da orospular benimle yatmadı

Çirkinsin dediler

Pissin dediler

Yıkandım arındım

Afyon yüklü mavnalar geçiyordu Çin denizinden

Birisi geçmişime küfretti

Tuttum öldürdüm

Geçmişim seninle güzeldi temizdi aktı

Kirlettim

Affet beni

Hamamatsu ‘da bir geyşa kızı yüzüme tükürdü

Pyong-Yang ‘da kurşuna dizdiler beni

Tiz bir boru sesi üç defa ti çekti

Trampetler başımda zonkluyordu

Kederliydim

Çaresizdim

Canım Tchaikovski ‘yi dinlemek istiyordu

Ah o keman konçertoları öldürdü beni

Dinsizdim İstanbul ‘da minareler üstüme yıkıldı

Yoksuldum Kudüs ‘te kiliseler kabul etmedi beni

Gelme diyorsun

Bu gel demektir

Birazdan akşam olacak

Rachmaninof ‘la bir meyhanede içmeliyim bu gece

Sonra sana gelmeliyim

Rachmaninof nereye giderse gitsin

Şimdi bir derin mavide akşam oluyor

Gök mavi deniz mavi

Mor dağlar yeşil ağaçlar mavi

Bozuk düzen mavi gecelerden sesleniyorum sana

Ne opera aryaları

Ne beşinci senfonisi Beethoven ‘in

Bir yalnızlık marşıdır çalınıyor uzakta

Gün ışığı arkamızda kaldı bak

Tanyerinde unuttuk gözlerimizi

Gel artık

Hayata yeniden baçlayalım

Gel artık

Bu mavilerde kimseler görmez bizi

Solfej anahtarlarını kaldıralım

Do ‘ların mi ‘lerin önünden

Bırakalım bu dünyayı alabildiğine dönsün

Ölmekse daha kolay ne var

Yaşamaksa sensiz mümkün değil

İskender adam edemedi bu dünyayı

Biz mi edeceğiz

Eflatun çözemedi yaşamanın sırrını

Biz mi çözeceğiz

Bütün yataklar bir kişilik

Git diyorsun

Nereye gideyim

Birazdan gece olacak

Ağır kılıçlar parçalayacak yüreğimi

Pis bir koku gibi çökecek üstüme yalnızlığım

Seni düşüneceğim stepler ortasında yorgun kimsesiz

Dolu dizgin atlılar geçmeyecek yüreğimden

Bir gözümde gümüş mahmuzların pırıltısı hazin

Bir gözümde bozulmuş nal izleri

Durup durup ağlayacağım

Sen bu ayrılıklar için mi yaratıldın söyle

Bu zehir zemberek kederler için mi

Bak bütün orkestralar sustu

Bütün ışıkları söndü dünyanın

Korkma

Haydi uzat ellerini

Geçmiş yılları yeniden yaşayalım bir bir

Bak dinle

Bir seslenen var uzaklardan

Bak dinle

Kader kapıyı çalıyor

Gelme diyorsun

Gelme diyorsun

Bu gel demektir.

İkinci Bölüm	:

Seninle Kardeş Değiliz

(Allegro) 

Tanrının bıraktığı yerden biz başlıyalım

Üç milyar insanın yarısını sen öldür yarısını ben

Üç kişi kalsak yetişir yeryüzünde

Yaklaş bana

Seninle kardeş değiliz

Hüzünle karışık sevinçlerden kurtul artık

Arzuların o belli belirsiz sıcaklığını sev

Biliyorsun

Önce Tanrı insanı yarattı

Sonra insan sevgiyi

Ne yapsak boş

Ne kadar çabalasak faydasız

Geriye dönemeyiz

Olanlar oldu iş işten geçti

Çamurumuza sevgi katılmış bir kere

Kim bu şarkıları söyleyen

Karcığar faslından düm tek üzere

Aklım bir yere erişti durdu

Susun

Şimdi üçgenlerle oynuyorum

Kaldırın bu daireleri

Bir model kız geldi soyundu karşımda

Saçlarından üç fırça yaptım

Üç tüp boyan vardı

Verenoz yeşili zümrüt yeşili krom yeşili

Hepsini kattım birbirine

Senin yeşilini buldum

Senin yeşilinde orkestralar Debussy ‘den çalıyordu

Senin yeşilinde unuttum siyahlığımı

Bu deli eden uğultu nerden geliyor

Kim kırdı bu aynaları

Toplayın yüzümüzü görelim

Çirkin değiliz artık

Bir kapı açılda önümüzde ölümsüzlüğe

Güzeliz

Sabahlar bizimle dolu

Işık diyordun al işte

Kör kıyılara kadar ışıdı yeryüzü

Renk diyordun işte bak

Buram buram mavi

Çarşılar dolusu kırmızı

Süt beyazından geceler

Sarı güneşler ortasında turuncu bir gün

Yitirilmiş saadetlerin bahçesinde mor çiçekler

Kardeş değiliz diyorum inanmıyorsun

Yalan bunca faziletler yalan

Bizi bu ciğeri beş para etmez insanlar mahvediyor

Aldırma diyorum sana

Dünya ikimiz için yaratıldı

Üç milyar insan iş olsun diye geldi yeryüzüne

Verdiğin her kederin yüreğimde yeri var

Hangi kitabı açtıysam seni okudum yıllardır

Hangi aynaya baktıysam seni gördüm

Gel desen gelemem

Git desen gidemem

Öl desen kanım akmaz

Anladım artık seni sevmek yüce bir şey

Anladım seni sevmek Tanrı ‘ya yaklaşmak gibi

İnsanlar içinde bir sana inandım

Bir seni sevdim kendimden başka

Uykularımın bölündüğü saatlerde

Sendin düşündüğüm soluk soluk

Sivri bıçaklar gibiydin karanlığımda

Gözümü yumsam seni görüyordum

Oynak türkülere benzeyen yürüyüşünle

Sen çıkıyordun karşıma

Karanlığımda

İki yıldızdı ellerin görülmedik

Karanlığımda

Bir orman yangınıydı dudakların

İstesen hayat verirdim bu karanlıklara

İstersen gökyüzünü bir mendil gibi yırtardım

Denizlerden göllerden nehirlerden

Sana görmediğin renkler yaratırdım

Zamanın ötesinde

Yeni bir dünya kurardım sana

İnsansız Tanrısız kedersiz

Severdin

Dağ rüzgarlarının serinliğince

Yaşardın

Bu sefil dünyamızdan uzak

Bir yanıp bir sönen ışıklar gibiyim

Yumruk kadar yüreğimde sen varsın

Kutsal kederler içinde seninleyim artık

Sarı badanalı evlerde başbaşayız

Bütün duvarlara gölgen kazınmış

Kokun sinmiş bütün perdelere

Kapılarda parmakların beyaz beyaz

Sokaklarda ayaklarının izi

Ben bu sokaklarda ölsem

Kaldırımlar çekmez ağırlığımı

Söylesem aşkımı asırlar boyunca

Bu iki yüzlü insanlar anlamaz beni

Desem ki yeryüzüne beş peygamber geldi

Beşincisi sensin

Desem ki iki kişi kaldık dünyada

İkincisi sensin

Desem ki biri var yeri göğü var eden

O da sen olurdun

Sana tapmak için

Kilden bir heykel yapardım güzelliğince

Bilsem ki sen Tanrı ‘dan iyisin

Bilsem ki Tanrı senden güzel değil

Senin o kocaman kocaman gözlerin yok mu

Nasıl duruyor boşluğunda arzuların anlamıyorum

Nasıl nasıl bakıyor bana

Böyle merhametten uzak

Git diyorsun

Nereye gideyim

Ümitlerim ne olacak

Bunca şiirleri kim söyleyecek sana

Kim anlatacak dünyaya sığmayan güzelliğini

Gitmek mümkün olsa da gitsem uzaklara

Sevmesem seni bir daha

Paramparça etsem yüreğimi cam gibi

Sonra yaksam

Savursam küllerini karlı dağlardan açık denizlerden

Yine seni severdim toz toz

Yine sana tapardım küllerimin ağırlığınca

Bu oksijen gazı olmasa da olurdu

Ama Beethoven gelmeseydi dünyaya

Seni bu kadar sevemezdim

İkimizin ortasında o duruyor

Sağımızda birinci keman

Solumuzda ikinci keman

Karşımızda üçüncü keman

Sonra orglar flütler kontrbaslar

Sustur şu orkestrayı Beethoven

Şimdi dokuzuncu senfoninin sırası mı

Bunca yalnızlıklar bunca yokluklar benim işim değil

Bu çirkinliği ben yaratmadım

Ne de bu kahpe güzellikleri

Bende sevmediğin ne varsa senden türedi

Şu karanlık bakışlar

Şu ellerimin pisliği

Şu dudaklarımdan çıkan iğrenç sözler

Besbelli senin eserin

Ne buldumsa sende buldum kötülükten yana

Ne öğrendimse senden öğrendim

Seni sevdikten sonra başladım yaşamağa

Seni Tanrı yarattıysa beni kim yarattı

Bu azabı kim verdi bana

Çıngıraklı yılanların zehirini içtim

Balinaların kusmuklarını

Kükürt kokulu imkansızlıklar içindeyim

Oysa güzeldim tarihin ilk çağlarında

Görsen şaşardın

Öyle aydınlıktım

Öyle iyiydim

Kobalt mavileriyle doluydu yüreğim

Kurşun beyazlarıyla

Severdin beni

Midye kabuklarının yeşilliğince

Sonunda dediğim çıktı işte

Samanyolundan bir yıldız düştü dünyaya

Sinekler gibi eziliverdi insanlar

Her şey bir anda olup bitti

Yapayalnız kaldık

Ne radyo aktivite ne mantar şeklinde bulutlar

Ne yaşamak sevinci ne ölüm korkusu

Sonunda üç kişi kaldık dünyada

Sen

Ben

Bir de Jiro ‘nun Manon Lesko ‘su

Yine bana bakarken yüzün kızarıyor

Toplum kurallarından kurtulamadın daha

Bütün çayırlar bomboş

Görmüyor musun

Al başını dağlara çık

Avaz avaz şarkı söyle sokaklarda

Bir kibrit çak

Bütün evler yansın

Yüzbin yılın öcünü al bu şerefsiz dünyadan

Sonra kaldır kendini denize at

Biraz serinle

Sevebildiğim kadar insanım ben

On gram arsenik yeter canıma

Beni düşünme

Uzun mistral rüzgarlarının üzerine

Nimbüs bulutları geliyor kaç

Uykumuz bölündü çırıl çıplağız

Kum fırtınaları başladı

Çin seddinin ötesinde

Gölgemizi bir Asya şehrinde unuttuk

Taklamakan çöllerinde kaldı rüyalarımız

Haydi git

Yok olduk iki olduğumuz yerde

Haydi git

Bir kalırsak yine var olacağız.

Üçüncü Bölüm	:

Karanlıkta

(Presto) 

Beşyüz borazan birden çalıyor

Bin davul birden vuruyor başımda

Gök gürültüleri

Çekiç sesleri makine sesleri

Dağlardan kopan kocaman çığlar

Taşlar

Kayalar

Ey üstüme üstüme gelen deniz

Ey cam kırıklarından kader

Yeter artık

Nerdeyse çıldıracağım

Bir yeşil ötesine geldim durdum işte

Merdivenin son basamağındayım

Bir adım daha atsam

Kimseler tutamaz beni

Bir adım daha atsam karanlıktayım

Kaç kere söyledik

Şu potpuriyi çalmayın diye

Anlamıyor musunuz

Fa diyez bemol çaresizlikler içindeyi

Bir duvar yıkılıyor altında kalıyoruz

Bir adam ölüyor bizi gömüyorlar

Susturun şu kemanları

Biraz da ilahlar ağlasın yokluğumuza

Kirli gözyaşları kırık iskemleler

Başı bozuk Çigan havaları

Yeminler notalar akortsuz teller

Ve sakat çocukları Nagazaki ‘nin

Biz bunun için mi geldik yeryüzüne

Devirin şu putları

Mukaddes kitaplar bize göre değil artık

Sinemaskop rezaletler içindeyiz

Café Chantant ‘larda dua ediyoruz

Mabetlerde çiftleşiyoruz artık

Mesuduz

Dokunmayın keyfimize

Saint Pierre ‘in doksandokuzuncu göbekten torunu

Strip tease yapıyor

Foli Bergere revüsünde her gece

Gelsin arkasından şampanya şişeleri

Kauçuk göğüslü kızlarda bir naz bir çalım

On derste aşk

On derste güzellik

On derste cinsiyet

Ve tam onbin yıldır arayıp bulamadığımız fazilet

Sonra mezarlıklar dolusu günah

Genelevler dolusu namus

Velhasıl ailece rock ‘n roll dansı öğrendik

Tepinip duruyoruz

Pirinç tanelerine çizdiğimiz kral resimleri bizi kurtarmadı

Ne de Babil ‘in asma bahçeleri

Hakkını veremedik alın terimizin suçluyuz

Har vurup harman savurduk ömrümüzü

Akıllı bir maymun olmaktan öteye gidemedik

Şimdi bu kördöğüşünde yenildikse suç bizim

Geç anladık zavallılığımızı

Her şeyi bu sağır göklerden bekledik yıllardır

Bizi kimseler inandıramadı ölüme

Bize kimseler öğretmedi insanlığımızı

Kim kurdu bu düzeni nerdeyiz

Bu tekerlekler nasıl dönüyor boşlukta

Bu umutlar bu dualar bu kahrolası hayaller

Nasıl bunca yıldır barındırdı bizi

Bu katı yürekli topraklar

Bu gülünç mezartaşları

Ölümler ölümler ölümler

Ölümlerden beter yalnızlığımız

Bu macera ne zaman bitecek söyleyin

Söyleyin ne zaman aydınlanacak

Bu karanlık alın yazımız

Harun-er Reşidin gazabına uğradık cümlemiz

Başparmaklarımızın birinci boğumundan vurdular bizi

Bir düşüş düştük Eiffel kulesinden

Sersefil oldu ölümüz caddelerde

Nice evlerin nice apartmanların bütün ağırlığı üzerimize kurşun gibi çöktü

Sokak köpekleri işedi kanlı gömleğimize

Yedi yıldız senesi bağırdık ağladık

Kimseler duymadı sesimizi Lili Marlen

Beşyüz sene sonra anlaşıldı yokluğumuz

İşte biz böyle yitirdik inancımızı Tanrıya

Keyfimize dokunmayın

Adamakıllı sarhoşuz

Ya bir gül koparın bahçenizden

Koklayalım

Ya bir yudum su doldurun taslarımıza

İçelim

Ya da bir dilim ekmek verin

Şükredelim yaşadığımız

Karanlıklar içinde

Çamurlar içindeyiz

Tutun kaldırın bizi

O yalancı sevginiz sizin olsun

Biz yaşamak için geldik yeryüzüne

Alın başınıza çalın merhametinizi

Körsünüz ya da sağırsınız

Beyaz çorap giydi diye

Ku Klux Klan derneğinin adamları

Bir zenciyi linç ettiler

Görmediniz

İbni Mansurun beşinci karısını toprağa gömdüler beline kadar

Sabahtan akşama dek yedibin kişi taşladı

Yedibin kişi tükürdü yüzüne görmediniz

Şu gökkubbenin altında

Boşa gitti nice bonjour ‘larımız

Sonra üç kere good night dedik

Duyan olmadı

Ya savaş meydanlarında yitirip bulamadığımız gerçek

Engizisyon işkenceleri yirminci yüzyılın

Fırınlar

Gaz odaları

Kitle halinde ölümler

Kara sineklerin konduğu çürümüş et yığınları

Yaylım ateşlerile delik deşik olmuş insanlığımız

O azgın atların çiğnediği kollar bacaklar

O kan çanağı gözler

O süngü uçlarında yükselen kesik başlarımız

Bizi alçaltan bu kanlı zafer taçları işte

Öptüğümüz o pis eller

O maymun maskara soytarılar

Küçük orospular

Kirli zevklerimiz

Yatağımıza giren frengili kadınlar

Aldığını geri vermez bir karanlık dört yanımızda

Hangi perdeyi aralasak gece

Hangi taşı kaldırsak çaresizlik

Ölüm isli bir fener ışığı bu karanlıklarda

Ölüm yorgun askerlerin tek umudu sıcak

Biz bu ölümlerle yakınız ölümsüzlüğe

Bu karanlıklarla uzak

Siz dilediğiniz şarkıyı söyleyin yine

Yine karamelalarla kandırın küçük kızları

Irzına geçin torunlarınızın

O sapık arzularınız yükseltecek sizi

O karanlık odaların başıboş rahatlığı

Varın dilediğiniz gibi yaşayın artık

Bir gün bütün günahlarınız bağışlanacak Tanrı katında

Ne cehennem ateşleri ne o köprüler kıldan ince

Sizin için değil

Siz öyle Tanrıların böyle kullarısınız işte

Şimdi de oturmuş tuz biber ekiyorsunuz yaramıza

Kiliselerde camilerde öğütler veriyorsunuz Tanrı adına

Sonra her gece bir cinayet işliyorsunuz

Temiz çarşaflarda pis kanınız

Uykularımızda gölgeniz korkunç belalı

Sizi sayıyla mı verdiler bize

Defolun karşımızdan

Bize kendi derdimiz yeter

Kanınızı bulaştırmayın ellerimize

Yüzsüzlüğün bu kadarına pes doğrusu

Haydi biraz eğin başınızı

Bizden af dileyin

Kederimizi anlayın artık

Saygı gösterin sevgimize

Belki sizi affedebiliriz

Ne de olsa insanız biz de

Bir zayıf tarafımız vardır

Nasıl aldandık bunca zamandır

Nasıl inandık güzelliğine hayatın

Bize ne doğan güneşten

Büyüyen buğdaydan akan sudan bize ne

Alabildiğine kederliyiz yorgunuz

Bize dostluğu öğrettiniz

Bize sevmesini öğrettiniz böyle delicesine

Sevdikse günahlarımız Tanrı ‘nın boynuna

Sevilmedikse insanlar utansın kederimizden

Ne aradık ne bulduk dünyanızda söyleyin

Bir sevgiyi bile çok gördünüz bize

Öpüştük uykularımızda ayıpladınız

Kara kara yengeçleri saldınız üstümüze

Şimdi de bir yaşamaktır tutturmuşsunuz

Rahat bırakın bizi

Göğüyle deniziyle

Taşıyla toprağıyla

O yoktan var ettiğiniz Tanrı ‘sıyla

Dünyanız sizin olsun.

Boğaz tokluğuna yaşamalar bizi kurtarmaz artık

Biz oldum olası kör doğmuşuz

Brakisefal kafalarımız bir işe yaramıyor

Hele şu bizimsiz ayaklarımızın haline bakın

Aptallığımız yüzümüzden belli

Aynaya bakıp gülüyoruz

Oysa bütün çirkinliğimiz aşikar ayna gibi

Söyleyin bir Shakespeare mi akıllıydı içimizde

To be or not to be

To be or not to be bir şey değil yine

Sen olmasan benim varlığımdan ne çıkar

Ama sen yoksun işte

Bense bütün insanlar gibi ha varım ha yoğum

Yine sana çıkıyor bütün yollar

Yine bütün iki kere ikiler dört ediyor

Dönüp dolaşıp aynı yere geliyorum.

Dördüncü Bölüm	:

Sana Bir Tanrı Getirdim

(Adagio) 

Hani o iki kişilik dünyalar bizimdi

Hani sen iyiydin

Halden anlardın

Hani sen git demeyecektin bana

Ve ben her şeye rağman gelecektim

İçimde bir umut

Ellerimde olgun meyvalar

Dünya nimetleri

Gözlerimde yanıp yanıp sönen bir pırıltı

Ama ne sen gel dedin

Ne de ben gelebildim her şeye rağmen

Aşkımız ayrılıklarla başladı

Deli dolu akan nehirlerden tas tas sular içtik

Öyle ateşlerle doluydu yüreklerimiz öyle tutkundu

Karlı dağların serinliğinde uyurduk geceleri

Deniz fenerlerinin ışığında yıkanırdık

Köpükten bir çalkantıydı içimizde zaman

Ne yana baksak denizdi maviydi ışıktı

Sonra bir çaresizlikti zifir

Akıntıya kapılmış gemiler gibiydik

Bir org çalınır gibi yanıbaşımızda

Öyle kendinden geçmiş öyle başıboş

Öyle derin duygular içindeydik anlatılmaz

Sarhoş rüzgarlara bıraktık kendimizi

Aldığını geri vermez dalgalara

Görmediğimiz ülkeler gördük gün doğusunda

Tatmadığımız yemişlerden tattık günahkar olduk

Alevden bir tasta eridi günler

Bir cehennem ateşiydi aşk içimizde

Hiç sönmiyecekmiş gibi yanıyorduk

Tutsaklığımız nasıl başladı bilinmez

Paslı demir kapılar kapandı üstümüze

Taş duvarlarda kayboldu boğuk seslerimiz

Çaresizliğimizi bize aynalar söyledi inanmadık

Kuşatıldık ansızın kederle ayrılıkla

Aman vermez karanlıklar sardı dört yanımızı

Yalnızlık bir ağrı gibi çöktü başımıza

Uyuduk bir daha uyanamadık

Şimdi bir kutup var sana çeker beni

Bir kutup var senden öteye

Ben onun için böyle ortalıkta kaldım

Dağ yollarında caddelerde sokaklarda

Onun için bulup bulup yitirdim seni

Hangi kapıyı çaldıysam sen açtın bana

Hangi gözümü yumduysam seni gördüm

Zamandın zamandan öte bir şeydin

Yıllarca bir meşale gibi yandın uzaklarda

Bu manyetik alanda boğulmam senin yüzünden

Bu zincirleri sen vurdun ellerime

Sen getirdin bunca karanlıkları

Al şunu mumu yak

Korkuyorum

Bir taş aldım attım denize

Günahlarımdan kurtuldum

Alfabenin yirmisekizinci harfindeyim

Öteye gidemem

İtme beni

Benim de bir insan tarafım vardı

Bakma böyle kötü olduğuma

Benim de dileklerim vardı

Benim de bir beklediğim vardı yaşamaktan

Yeter artık vurma yüzüme çirkinliğimi

Her gün bir kadın ağlar benim yüzümde

Büyük dertler içinde benim ellerim

Anlamıyor musun

Sen sevildiğin için güzelsin bu kadar

Ben sevilmediğimden böyle çirkinim

Bütün kötü yerlerde ben kokarım

Biliyorum

Bir hayvan leşiyim öleli kırk gün olmuş

Fabrika bacalarında bir kara dumanım

Zehirim akrep kuyruklarında

Kötüyüm sevemediğin kadar

Öyle fenayım

Kapanmamış bıçak yaralarında

Bu pis çöp tenekelerinde unut beni

Unut artık

Bayat bir ekmek gibi

Çürümüş bir elma gibi

Sarın badanalı evlerde kazanlar kaynar

Sarı badanalı evlerde günah işlenir her gece

Sarı badanalı evlerde ölüler yıkanır

Sarı badanalı evleri sev biraz

Bu evlerde zaman benim akşamlarımdır yitirilmiş

Bu kazanlarda benim gözbebeklerimdir kaynayan

Bu sarılarda benim yüreğim bir ölür bir dirilir

Anladım

Bu dünyada benden başka kimse yok beni anlayan

Tosca ‘dan bşir arya hatırlıyorum şimdi

Sus biraz

Ensemde bir akrep yürüyor

Bırak yürüsün

Sabaha asacaklar beni

Dokunma

Yedi canım vardı ikisi gitsin

Bunca ölümler az gelir bana

Kalbimi yardım

Bir damla kan aktı

Kutuplara kar yağıyordu

Üşüdüm

Failatun vezniyle seni çağırıyorum

Bana inbiklenmiş yeşilliğini getir

Dur gitme

Beş kuruşum vardı kaybettim

Dur gitme

Isırgan otlarından kurtar beni

Deniz analarının gözlerini çaldım

Sana bakmak için

Güneşi üçe böldüm

Al biri senin olsun

Yüzümde beş bıçak yarası var

Bir de sen vur

Barut kokusunu severim

Bir portakalı dilim dilim soy

Acıktım

Tut ki ben yoğum artık yeryüzünde

Tut ki bir marul yaprağıydım

Öldüm

Al şu serçe parmağım sende kalsın

Ben kötüyüm

Allahsızım

Korkunç çirkinim

Ben seksensekizinci tul dairesiyim

Sağ gözümün üç kirpiğini kestim

Al

Ben lanetlendim

Chopin ‘in cenaze marşı çalınıyor

Ölüler ayağa kalktı

Görüyor musun

Şu soldan ikinci benim

Senin yüzünden öldüm

Şimdi seni getiriyorlar karanlığıma

Ağlıyorum

Biraz sev beni

Yaklaş biraz

Gül biraz

Seni affediyorum

Kuşkonmaz dallarına astım kendimi

Sedir ağaçlarına gül yapraklarına

Başımı taşlara vurdum

Gözbebeklerimde büyük camlar parçalandı

Tanrısal duygular içindeydim

Bütün Tanrısızlığımdan uzakta

Bir kemiklerinin sertliğini aldım

Bir teninin aklığını

Sonra sıcaklığını dudaklarının

Gel bak

SANA BİR TANRI GETİRDİM

Gel bak

BİR TANRI YARATTIM SENDEN

Ankara / Nisan – Eylül 1957

(Bilgi Kitabevi – 1958 İkinci Baskı) 

(İsmet BARLIOĞLU tarafından Word ortamına aktarılmıştır.)', 'Birinci Bölüm: Kader Kapıyı Çalıyor (Andante)  Gelme diyorsun Bu gel demektir Birazdan güneş doğacak Dolu dizgin atlılar geçecek yüreğimden ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":734,"source_url":"https://www.antoloji.com/iki-kisiye-bir-dunya-senfonik-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-unutulmus-adam-s97kg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Büyük bir dalgayla kıyıya vurmuş bir kalp bu.

Her tarafı yosun tutmuş

Nefes alamıyor! 

Artık kendine gelemez.

Çok belli yorulduğu,

Fırtınanın izlerini taşıyor üzerinde.

Sahip olduğu bedeni kaybetmiş.

Tek başına

Issız bir kumsalda uzanıyor.

Ölüm çoktan gelmiş...

Artık sevemez kimseyi! 

Aşk doşu bir denizde

Fırtınaya kapılmış.

Sebebi Aşk! 

Herkesin uğruna şiirler yazdığı,

Anlatıpta bitiremediği aşk.

Ama aşk; 

Denizin dalgası gibidir,

Ne kadar büyük olursa olsun

Kıyıda biter

Ve geride

Kıyıya vurmuş bir kalp bırakır...', 'Büyük bir dalgayla kıyıya vurmuş bir kalp bu. Her tarafı yosun tutmuş Nefes alamıyor!  Artık kendine gelemez. Çok belli yorulduğu, Fırtınanı...', ARRAY['Türk Edebiyatı','Şiir','Unutulmuş Adam']::text[], 8.5, '{"poet":"Unutulmuş Adam","poet_slug":"unutulmus-adam","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ask-256-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve ben', 've-ben-ozden-cakmak-o34ey', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben buyum işte

Karanlığın unutulmuş bir noktasına yerleşen aydınlık

Aydınlığın doruk noktaya ulaşmasıyla doruklaşan bir karanlık,

Ben buyum işte.

Kapağı dağlar olan bir kutudan

Umutla sızmaya çabalayan bir ışık,

Kapağını devirdiklerinde

Karanlıktan da siyah bir boşluk.

Ben buyum işte,

Erişilmezler içinde çırpınan minik bir canlı,

Erişilmeze ulaşınca patlayan bir volkan.

Amacına can vermek için uğraşan,

Canlanınca da o''nu ezip geçen bir insan

Ben buyum işte.....', 'Ben buyum işte Karanlığın unutulmuş bir noktasına yerleşen aydınlık Aydınlığın doruk noktaya ulaşmasıyla doruklaşan bir karanlık, Ben buyum ...', ARRAY['Türk Edebiyatı','Şiir','Özden Çakmak']::text[], 8.5, '{"poet":"Özden Çakmak","poet_slug":"ozden-cakmak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ve-ben-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pencere', 'pencere-taner-arda-u8eow', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne zaman bir tepeden baksam

bu şehre

Binlerce ışıklı pencere görürüm

Her pencerenin ardında insanlar....

Mutlu...mutsuz insanlar...

..........yalnız insanlar......

ve ben... Hep senin pencerenin

arkasında olmak isterim', 'Ne zaman bir tepeden baksam bu şehre Binlerce ışıklı pencere görürüm Her pencerenin ardında insanlar.... Mutlu...mutsuz insanlar... ...........', ARRAY['Türk Edebiyatı','Şiir','Taner Arda']::text[], 8.5, '{"poet":"Taner Arda","poet_slug":"taner-arda","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/pencere-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'V''el Asr', 'v-el-asr-memet-karabalik-8xqw5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu yol sende başlar

Eğilmiş bir dal gibiyim

Nedenini bildiğim savaşlar zamanında

İyi adamların öldüğü topraklarda

Sevmek her yiğidin harcı yine de

Elini uzat ''iyi çocuklara'', düşenlere

''V''el Asr''

Melekler şahittir hüsrana

Eşyanın adını öğrendiğimiz günden beri

Kafamda parçalanmış çocuk resimleri

Yüreğimde sen ve acı

Ürkek bakışlarıyla bir ceylan içimde hala

Raydan çıkmış trenler şehirlere çarptığında

Eskimeyen ağıtlar sarar ya sokakları

Kolun vücudumu sardığında ahenksiz

İçim cız eder düşen her bombayla

Savaş bu, genzini yakar her lafı geçtiğinde

Taş üstünde taş kalmaz Basra''da

Eğilmiş çocuğuna bir ana, ölür ahıyla

Rezil uçaklar geçer üstümüzden

Sevdam sızlar nefretten

Eşikten bir çocuk seslenir

''Ne güzel elma kokuyor anne''

İçimde Halepçe dirilir

Dünyanın merkezi sallandığında

Ellerini açıp dua edersin sadece', 'Bu yol sende başlar Eğilmiş bir dal gibiyim Nedenini bildiğim savaşlar zamanında İyi adamların öldüğü topraklarda Sevmek her yiğidin harcı y...', ARRAY['Türk Edebiyatı','Şiir','Memet Karabalık']::text[], 8.5, '{"poet":"Memet Karabalık","poet_slug":"memet-karabalik","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/v-el-asr-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğun Hazanı-RPT', 'yoklugun-hazani-rpt-erol-dal-e0np6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine yoksun

Hepte bana düşer ağlamak

Rüzgârlarla konuşmak

Benim derdimdir,

Zaten dumanlarda..

Yine yoksun

Tenindeki koku, vurur beni

Koklarım her yeri

Elimde

Dudak izlerin kalmış

Sigaranın kertiğini

Gezdirir dururum 

sensiz buselerimde.

Yine yoksun 

Atlı arabalar geçer hayalimden

Yaylı, atlı, arabalar.

ırak  koyan 

yaylı arabalar.

maziden hatıralar.

döner, dönerde tepemde.

Uyuya kalırım öylece 

.....

Yine yoksun

bomboş kollarım

arar seni 

Ağlarım gizlice

...

Islanır yatağım

Islak düşler görürüm

Düşler ki.! 

Düşler seni delice.

...

Yine yoksun

Yoksul evimde; 

.....

Yine, yine, yine

Yoksun……

Kahretsin

Yapayalnızım', 'Yine yoksun Hepte bana düşer ağlamak Rüzgârlarla konuşmak Benim derdimdir, Zaten dumanlarda.. Yine yoksun Tenindeki koku, vurur beni Kokları...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/yoklugun-hazani-rpt-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sendin o', 'sendin-o-mahmut-murat-demir-gnrs4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir çığlık

Derin ve burgaçlı

Karanligi yirtarak geldi cok uzaklardan

ÖnÜmden geçti ve yırttığı karanlıkta kayboldu gitti

Ateşi kavurdu ruhumu,

Sesi parçaladı yüreğimi...

Sendin işte o, sesinden tanıdım sıcaklığından, gidişinden.

Öylece gittin işte karanlığımdan.

Yolun açık olsun sevgilim,

Kurtuldun karanlığımdan...', 'Bir çığlık Derin ve burgaçlı Karanligi yirtarak geldi cok uzaklardan ÖnÜmden geçti ve yırttığı karanlıkta kayboldu gitti Ateşi kavurdu ruhum...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Murat Demir']::text[], 8.5, '{"poet":"Mahmut Murat Demir","poet_slug":"mahmut-murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sendin-o-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıla', 'sila-i-smail-sahin-tjsfb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yollar beden götürür

ruh götürür mü? 

yollar; hasret, özlem

sıla götürür mü? 

sıla? 

neresi?', 'yollar beden götürür ruh götürür mü?  yollar; hasret, özlem sıla götürür mü?  sıla?  neresi?...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sila-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretin', 'hasretin-i-smail-sahin-g47ma', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni ne kadar...

Daha ne kadar,

Taşıyabilirim içimde? 

Ağır değil misin? 

Ağır değil mi hasretin? 

Ölmeyebilsem...

Taşısam seni, taşısam! 

Ah, yıkmasa beni eziyetin,

Hep sana düşmeden...

Düşmeden koşabilsem!', 'Seni ne kadar... Daha ne kadar, Taşıyabilirim içimde?  Ağır değil misin?  Ağır değil mi hasretin?  Ölmeyebilsem... Taşısam seni, taşısam!  A...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hasretin-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz', 'biz-reyhan-sur-w4x4y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kadınız biz

üretkeniz

doğurganız

savaşta barışta

yaşam kavgasının tam ortasında

erkeğiyle omuz omuza

evinde sevecen bir eş

şefkatli bir ana çocuklarına

gerektiğinde “saçını süpürge eden”

çekip çeviren

dün

karıştırılmayan “elinin hamuruyla erkek işine”

bugün

imzası olan her başarılı işte

sabır ekip

sevgi biçen

emeği gergefinde işleyen

ana gardaş arkadaş

yar yaren yoldaş...

kadınız biz

bileği bükülmeyen

elbet duyguluyuz

ağlarız, yeri gelince

çiçekler de açtırırız yüreklerde

kadınız biz

seviyoruz erkeklerimizi

onurluyuz birlikte

hep

hep...

biz.. sizinle varız..

siz.. bizimle varsınız', 'kadınız biz üretkeniz doğurganız savaşta barışta yaşam kavgasının tam ortasında erkeğiyle omuz omuza evinde sevecen bir eş şefkatli bir ana ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Sur']::text[], 8.5, '{"poet":"Reyhan Sur","poet_slug":"reyhan-sur","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/biz-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuzluk bir kuş olur konar parmaklarına', 'sonsuzluk-bir-kus-olur-konar-parmaklarina-murat-tali-cxd5e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne çıkar gökler tutuşsa 

Yada yanardağlar buzul olsa 

Yıldızlar silinse gökyüzünden 

Sen yinede ellerinde büyüt güzelliği 

Bilmezsinki; 

benliğim prangalara çalınmış sevdanla... 

gelişinle 

çözülür bütün prangalar, 

zincirler özgürlük olur, 

gün olur, 

gece çöker üstüne 

sonra şafağın kızıllığı gibi kanar yaralarım 

ve yeniden evrilir zamanlar 

sonsuzluk bir kuş olur konar parmaklarına 

usulcacık 

sessizce 

kalırız kendi sessizliğimizle kurduğumuz dünyamızda 

günebakanlar güneşe döner yüzünü 

yüzün güneş olur, rüzgar olur ılık nefesin 

güneş ve rüzgar alır götürür beni 

kimbilir belkide 

kısır tarlaların doğurduğu gün olur 

gün döner 

ay asılır geceye 

yıldızlar asılır 

düşlerime asıldığın gibi 

aysız gecelerde geleceksin diye beklerim. 

karanlıklar 

sığınağım olur 

kaybederim kaybederim de 

kutup yıldızına adarım 

kayboluşlarımı 

bulamam yönümü 

yıldız karayel alır beni 

ne zaman gider bu kentin 

sessizlikleri 

ne zaman çığlık olur isyanım 

ovaların vadilere yayılan sessizliği 

ne zaman biter 

ve bir yıldız asılır incir ağacına 

dudaklarım kanar 

depreşir bütün sancılarım 

dudağımdan akan kan karışır 

toprağa 

oturur ağlarım 

sevda kokar, 

hasret kokar her yanım, 

karanfil olurum.', 'Ne çıkar gökler tutuşsa  Yada yanardağlar buzul olsa  Yıldızlar silinse gökyüzünden  Sen yinede ellerinde büyüt güzelliği  Bilmezsinki;  ben...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/sonsuzluk-bir-kus-olur-konar-parmaklarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birazcık Sevseydin Beni', 'birazcik-sevseydin-beni-i-smail-sahin-zr43v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kızgın suları güneşin

baştan ayağa üstüme

dökülmezdi her sabah

vurmazdı bu kadar yüreğime

çekiç gibi notası türkülerin

birazcık sevseydin beni

hergün kovalamazdım

bırakıp giden hayalini

yatakta döne döne

pencereden izlerken geceyi

yalnızım der miydim

birazcık sevseydin beni

kefen olur muydu ne an baksam

yıkayıp serdiğim gökyüzü

düşer miydi unutmak

şeker diye çay bardağına

ellerinden bir akşam

birazcık sevseydin beni', 'kızgın suları güneşin baştan ayağa üstüme dökülmezdi her sabah vurmazdı bu kadar yüreğime çekiç gibi notası türkülerin birazcık sevseydin be...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/birazcik-sevseydin-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küllenmiş Aşk', 'kullenmis-ask-mehmet-kesen-wn2aa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gözlerinden geçiyorum

yüzünün haritasında

kendimden geçiyorum

tarih kadar eski

asil bir keder karşılıyor beni

asude bir bakış

acılar imzalanıyor 

antik hüzünler kentinde

güller serpiliyor 

küllenmiş bir aşka

zaman rakibim yok diyor usulca

süzülüp gidiyor beklenen sona

gülümseyişler kefil olmuyor yalnızlığa

yalnızlık ağır geliyor nisana

insan yeşille yarışıyor zamanla

gözlerini geçiyorum

küllenmiş bir aşka açıyorum gözlerimi', 'gözlerinden geçiyorum yüzünün haritasında kendimden geçiyorum tarih kadar eski asil bir keder karşılıyor beni asude bir bakış acılar imzalan...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kesen']::text[], 8.5, '{"poet":"Mehmet Kesen","poet_slug":"mehmet-kesen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kullenmis-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçamıyorum Senden', 'kacamiyorum-senden-i-smail-sahin-mae76', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'habersiz kaçıp giderken

sana bırakıp saçlarını

heybemde umut seliyle

nere gitsem eşkıyamsın

ansızın yolumu kesen 

senden gönlümü saklarken

diner diye kanaması

açtığın yaraların sevgime

nere gitsem kartalımsın

gözüyle ruhumu yiyen 

durup tütün çekerken

unuttum sanıp bakışını

koşmaktan bitab hevesle

nere gitsem karşımdasın

yönümü ben bilmiyorken', 'habersiz kaçıp giderken sana bırakıp saçlarını heybemde umut seliyle nere gitsem eşkıyamsın ansızın yolumu kesen  senden gönlümü saklarken d...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kacamiyorum-senden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapama Gözlerini (''? '')', 'kapama-gozlerini-mehmet-kesen-cb3rb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kapama gözlerini 

incilerin değsin isterim tenime

denizinde çırpındığım

saçlarında sürüklendiğim

soluksuz kaldığım incilerin

nefesin okşasın yanağımı

kirpiklerinde soluklandığım nefesin

kapama gözlerini

maviler siyaha çalar yoksa 

siyahlar yalancı olur

kaybolurum gökyüzünde

bulamam kendimi aynalarda

bakamam kendime bir daha

kapama gözlerini

ölürüm yoksa', 'kapama gözlerini  incilerin değsin isterim tenime denizinde çırpındığım saçlarında sürüklendiğim soluksuz kaldığım incilerin nefesin okşasın...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kesen']::text[], 8.5, '{"poet":"Mehmet Kesen","poet_slug":"mehmet-kesen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kapama-gozlerini-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anahtar', 'anahtar-mehmet-kesen-vnswb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'düşlerim var

sana dair kapıların açıldığı

oyun dediğim

bu yaşam uykusunda

aşka kupa kızı dedim anlasana

anahtar sözcük bu olmasada

gönül kapılarını açmasanda

bilmediğin bir şey var aslında

son kartımı oynamadım daha', 'düşlerim var sana dair kapıların açıldığı oyun dediğim bu yaşam uykusunda aşka kupa kızı dedim anlasana anahtar sözcük bu olmasada gönül kap...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kesen']::text[], 8.5, '{"poet":"Mehmet Kesen","poet_slug":"mehmet-kesen","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/anahtar-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Prenses', 'kayip-prenses-i-smail-sahin-rxwwq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yüzün gülerken her an

gözlerinde dolu dolu hüzün

ah keder yükü bakışlarında

çınlarken alem kahkalarından

acı bir name kirpiğinin sazlarında

burası senin ülken değil prenses

tutunamadın mı gökyüzüne

adasında mahsur kalmış mutluluğu

nasıl bulamadın açılıp da

şu bir avuçluk denizlere

çeşmeler vermedi mi suyunu

burası senin ülken değil prenses

bu çorak topraklar filizlenir sanma

bakıp da o eşsiz güzelliğine

köylü kızı gibi al eline kazmayı

vur! hayatın bereketlensin

bırak oturup da rehbere kızmayı

vur! bahçelerin yeşersin', 'yüzün gülerken her an gözlerinde dolu dolu hüzün ah keder yükü bakışlarında çınlarken alem kahkalarından acı bir name kirpiğinin sazlarında ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kayip-prenses-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Natali''ye Mektuplar', 'natali-ye-mektuplar-safak-ozdemir-jih1w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Merhaba! 

Gece saçlım, şiir bakışlım, kadınım benim.

Bir bilsen nasıl özledim seni.

Tütünümde zevk vermez oldu artık.

Şarabım tatsız,

Geceler aysız geçer oldu.

Natali! 

Tenimde özledi seni.

Sahi kaç zaman oldu sevişmeyeli,

Etli dudaklarından öpmeyeli,

Ve sabahlamayalı iri göğüslerinde.

Kaç zaman oldu? 

Şu an ranzama uzanmış,seni düşünüyorum.

Dışarıda inceden kar yağıyor geceye.

Uzaklardan yaban kazlarının sesleri duyuluyor.

Ardından birer ikişer geçiyorlar parmaklıkların önünden.

Düşünüyorumda ne güzel şey uçmak.

Doyasıya göğün maviliklerinde,

Özgürce,alabildiğince.

Ne güzel şey Natali! 

Geçen gün bana gönderdiğin açelyayıda aldılar elimden.

Kitaplarımıda yaktılar, resimlerinide.

Varsın yaksınlar be gülüm, varsın yaksınlar! 

Sevgin işlenmiş yüreğime, ilmek ilmek.

Resmin kazılmış belleğime nakış nakış.

Onuda sökemezler ya! 

Natali! 

Bu sana yazdığım son mektubum.

Yarın şafakla beraber asacaklar beni.

Ardımdan, ağlamanı,üzülmeni istemem bilesin! 

Biz onurumuzla, mücadelemizle yaşadık bunca yıl,

Şerefimizle ölmesinide biliriz elbette! 

Ama sanmasınlarki susacağız.

Düşünceye ilmek olmaz,fikirler boğulamaz.

Yalnızca bir yıldız kayar geceden,usulca yüreklere.

Ve belki bir kaç damla yaş düşer,taze karın üstüne.

Ama açar ardından,

Binlerce milyonlarca kardelenler,aydınlık sabahlara,

Sevgiyle, umutla...

Natali! 

Potinlerimi koğuş arkadaşım, İgor''a verdim.

Kokuşmuş ayaklarını karnına toplayıp yatmasın artık.

Kalpağımıda yan koğuştan İvan''a bıraktım.

İnlemesin ayaz gecelerde sabahlara dek.

Sana Natali! 

Sana sadece aşkımı bırakıyorum.

Elveda canım! 

Elveda.', 'Merhaba!  Gece saçlım, şiir bakışlım, kadınım benim. Bir bilsen nasıl özledim seni. Tütünümde zevk vermez oldu artık. Şarabım tatsız, Gecele...', ARRAY['Türk Edebiyatı','Şiir','Şafak Özdemir']::text[], 8.5, '{"poet":"Şafak Özdemir","poet_slug":"safak-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/natali-ye-mektuplar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her ümidin peşine düşen', 'her-umidin-pesine-dusen-i-skender-anadolu-5y33t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her ümidin peşine düşen

ve her uçurumdan düşen,

çok konuşan,

durmadan; güneşi ilk gördüğü günden beri

yanlış yapan

bir çocuk.

Bu çocuğu büyütmedim ben.

İki kolunuda savaşta kaybetti.

Şimdi sarıldığı herşeye,

güzelleri hatırlatıyor.

Şimdi bu savaştan yadigar

güneyin adresini soran kuşlar,

ilk harflerinden

hiçbir dilde hiçbir anlama gelmeyen 

bir kelime oluşturan

akrostiş şiirler var.', 'Her ümidin peşine düşen ve her uçurumdan düşen, çok konuşan, durmadan; güneşi ilk gördüğü günden beri yanlış yapan bir çocuk. Bu çocuğu büyü...', ARRAY['Türk Edebiyatı','Şiir','İskender Anadolu']::text[], 8.5, '{"poet":"İskender Anadolu","poet_slug":"i-skender-anadolu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/her-umidin-pesine-dusen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Ağlayacak Adammıyım?', 'ben-aglayacak-adammiyim-okan-sungu-6zgi2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben ağlayacak adammıyım

Dans etmek varken

Islak arnavut kaldırımlı sokaklarda

Ay ışığının pembeliğinde 

Yaşlı elleri nasırlı bir kemancının

Sakallarından düşen melodiler eşliğinde

buğday tenli bir menekşe ile', 'Ben ağlayacak adammıyım Dans etmek varken Islak arnavut kaldırımlı sokaklarda Ay ışığının pembeliğinde  Yaşlı elleri nasırlı bir kemancının ...', ARRAY['Türk Edebiyatı','Şiir','Okan Süngü']::text[], 8.5, '{"poet":"Okan Süngü","poet_slug":"okan-sungu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ben-aglayacak-adammiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrıçam', 'tanricam-cetin-usta-jalcf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine sensiz geldi sonbahar tanrıçam

Beni duymasan da dinle

Göklerden inecek şiirler bu akşam

Ben o saatlerde sokaklardayım

Belki anason kokulu bir kahkahada

Belki yağmurlarla secde eden bir duadayım

Ben bir dilim ekmeği ekmekçiye veren adam

Yarın bu kentte olmaya bilirim

Islak saçlarda seni bulmalıyım

Bir yağmur damlasında buluşalım buluşalım bu akşam', 'Yine sensiz geldi sonbahar tanrıçam Beni duymasan da dinle Göklerden inecek şiirler bu akşam Ben o saatlerde sokaklardayım Belki anason koku...', ARRAY['Türk Edebiyatı','Şiir','Çetin Usta']::text[], 8.5, '{"poet":"Çetin Usta","poet_slug":"cetin-usta","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/tanricam-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yamalı Elbiseli Kız', 'yamali-elbiseli-kiz-tulay-sustam-ayz8j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünyaya geldiğimde kundak yerine

Yamalı bir elbise giydirmişler bana

Bütün parçalar ayrı ayrı işlenmiş

Sanki özenle her biri seçilmş

Bana beğendirmeleri için

Üzerine çiçekler serpiştirilmiş

Bir parçası mutsuzluk,

Bir parçası umutsuzluk,

Bir parçası yalnızlık,

Bir parçası çaresizlik,

Bir parçası gözyaşı,

DOSTLUK kemerim olmuş.

Belimi sımsıkı saran, beni hayata bağlayan.

Yalnızca AŞKI eklememişler...

Bu yüzden hayatımda ki tek eksiklik...

Onu da boynuma ben kolye olarak taktım

Onunla yatıyorum, onunla kalkıyorum.

Bir gece ben uyurken çıkarmışlar boynumdan

Şimdi çok sevdiğim kolyemi kaybettim.

Aşk''sız yaşıyorum tabii bu yaşamaksa...

O yüzden mutsuzluğum,

O yüzden umutsuzluğum,

O yüzden yalnızlığım,

O yüzden çaresizliğim,

O yüzden bunca gözyaşım...

Çıkardım artık üzerimde ki yamalı elbiseyi

Yeniden dünyaya gelmek istiyorum...

Bu sefer kundağa sarın beni...

Avuçlarım da  olsun ''AŞKIM''.', 'Dünyaya geldiğimde kundak yerine Yamalı bir elbise giydirmişler bana Bütün parçalar ayrı ayrı işlenmiş Sanki özenle her biri seçilmş Bana be...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yamali-elbiseli-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul ve Sensizlik', 'i-stanbul-ve-sensizlik-ali-i-hsan-gurpinar-ptim6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İstanbul bile yalnız Kalır sensizliğe

Şiirler yetmez Bu sessizliğe

Kanepedeki Tırnak izlerin

Suskunluğuna vurgun bir Perde

Adını  sayıklayan boş duvarlar

Kokunu özleyen bornozum

Tadını sakladığım boş kavanozlar

Sana susamış bir beden

İstanbulda Yalnızlığa hapsolmuş sen

Aylardan gidişinin ertesi

Günlerden sensizlik

Saat  özlem dolu üküdar

Dar ettiğin koskoca ankarada sensiz

Bir başıma divane

Yalnızlığa hüküm giymiş cesedimle

Her kapı çalışında canlanan ben

Sigarada aradığım tesellilere vurgun

Kadehlere dolan çaresizlik

Cam kenarında boynu bükük menekşe

ve seni özleyen geçen senenin takvimi

O kadar çok geçtiki günler saymaya kıyamadım

Her saniye duvarlara civilenmiş bir bakış

Sen istanbulda hapis

Ben yokluğuna kürek mahkumu

Ali İhsan Gürpınar

bu gün', 'İstanbul bile yalnız Kalır sensizliğe Şiirler yetmez Bu sessizliğe Kanepedeki Tırnak izlerin Suskunluğuna vurgun bir Perde Adını  sayıklayan...', ARRAY['Türk Edebiyatı','Şiir','Ali İhsan Gürpınar']::text[], 8.5, '{"poet":"Ali İhsan Gürpınar","poet_slug":"ali-i-hsan-gurpinar","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/istanbul-ve-sensizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '../ Kaldı..!', 'kaldi-hasan-basri-kale-fe727', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'geçti ömür,vuslat bir başka dünyaya kaldı

vîrane gönlüm,yar sînesin asılı kaldı

sevgi ölümsüzdür,seven ölse de derler

sözümüz gider bizimle,gözümüz arkada kaldı..



''bâkî kalan bu kubbede,bir hoş sadâ imiş''', 'geçti ömür,vuslat bir başka dünyaya kaldı vîrane gönlüm,yar sînesin asılı kaldı sevgi ölümsüzdür,seven ölse de derler sözümüz gider bizimle,...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kaldi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mal Beyanım', 'mal-beyanim-erol-dal-wfr6d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her şey elimde

Kalem, kağıt

Sigaram, içkim

ve

Yüreğim...', 'Her şey elimde Kalem, kağıt Sigaram, içkim ve Yüreğim......', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/mal-beyanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Hep İçimde Saklanan Olacaksın', 'sen-hep-i-cimde-saklanan-olacaksin-oguzkan-bolukbasi-daf2h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gün batımında kanat çırpan kuşların

Gagalarında tuttuğu nedir

Sessiz bir sevinci taşıyan

Sinsi bir karanlığın önünde 

Hangi kapılar açılacaktır 

Seni ömrümün güzelliklerine katıyorum

Yapayalnız

Ve senin haberin olmadan

Severek çekiliyorum karanlık kapıların ardına

Benim

 Gagalarındaki

O uzaktaki kuşların

Beni sularına atacaklar

Derinliklerine

Mavi denizlerin

Kaybolmayacağım

Çünkü sevgi taşıyor bedenim

Sular taşıyor

Ansızın

Seni sevdiğimi artık bir ben bileceğim

Bir de kuşlar

Rüyalarım olacak belki

Kendi içimde coşacağım

Kendi içimde taşacağım

Ellerim özleyecek firari ellerini

Bir güzel gülüşüne

Bir dokunuşuna

Her zaman binlerce hoş geldin var

Binlerce merhaba

Ben özlemlerin adamıyım

Özlemin de güzel

Sen hep içimde saklanan olacaksın', 'Gün batımında kanat çırpan kuşların Gagalarında tuttuğu nedir Sessiz bir sevinci taşıyan Sinsi bir karanlığın önünde  Hangi kapılar açılacak...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sen-hep-icimde-saklanan-olacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gregoryan isyanlar', 'gregoryan-isyanlar-yunus-ali-sinanoglu-9bjev', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tanımıyor beni kaldırımlar

Kayboluyor bakışlarım saçlarında

Binbir teline dolanıyor gözlerim

Gözlerim artık senin

Gaip isli gemiyim

Ama bir fırtına

Puslu ada

Bulduğum simsiyah saçlarında

Ve ruhumla beraber gözlerim

Gözlerim ki maalesef senin

Kör kördüğümleri izlerim

İzlediğim esaret

Uslu suskunluklarda uskumrular

GÖğü fetheden güçsüz kumrular

Ve isyankar havası şehrin

Bir deniz taşıyan gözlerim

Fakat maalesef senin

İsyankar gecelerde gemim

Gemiler oysa benim

Gömülür dalgalarında

Çarparlar her yer kaya

Vadetmiyor mutluluk

Düşman galiba bu ada

Üstelik batar gemim

Çünkü gemi benim

Ve isyankarken rengin

Ezer geçer değil kimse dengin

Saçlarında deniz taşıyan

Fırtınalı akrep yelkovan

Ey benim olmayan

olmayacak olan

Körüm kör değilsin ve karanlık

Seviyorum anla artık

Anla anlamlandır

Sende tüm akıl

Ruhum ki akla ziyan

Garip garip garip

Taşımıyor bizi 

İncecik ip

Ve bu deli çizgi 

Kurtar bizi

Ey denizler,

Köleler Sahibi', 'Tanımıyor beni kaldırımlar Kayboluyor bakışlarım saçlarında Binbir teline dolanıyor gözlerim Gözlerim artık senin Gaip isli gemiyim Ama bir ...', ARRAY['Türk Edebiyatı','Şiir','Yunus Ali Sinanoğlu']::text[], 8.5, '{"poet":"Yunus Ali Sinanoğlu","poet_slug":"yunus-ali-sinanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/gregoryan-isyanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arındırılmış Mutluluk', 'arindirilmis-mutluluk-goktu-kara-4a2bs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eminönü''ndeki güvercinleri izleyen

bir bebenin gözlerine baktınız mı hiç

işte arındırılmış mutluluk

sizi bilmem ben o gözlerde yaşıyorum

kırlara koşan bir genç kız ellerinde betikler

uzanır yeşile devleşir birden düşlerde

siz o kızın gözlerine baktınız mı hiç

sizi bilmem ben o gözlerde yaşıyorum', 'Eminönü''ndeki güvercinleri izleyen bir bebenin gözlerine baktınız mı hiç işte arındırılmış mutluluk sizi bilmem ben o gözlerde yaşıyorum kır...', ARRAY['Türk Edebiyatı','Şiir','Göktu Kara']::text[], 8.5, '{"poet":"Göktu Kara","poet_slug":"goktu-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/arindirilmis-mutluluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çakal', 'cakal-sinan-ercan-cdrle', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dengesi bozuk omuzu kırık

Elinde tespih kaşları çatık

Nefsinde kibir güçlüye sadık

İntihar eder aklında mantık

Üstünde bir takım elbise

Gözlerinde nefretlik bakışları

Yakalarını açmış gömleğinin

Tiksindirir kıl tavırları 

Nabzı elinde değil 

Ayak bileklerinde

Kalp atışı topuklarından duyulur

Tak tak seviyesi yerlerde

Birilerinin altında birilerinin üstünde

Kimilerine emreder birçoğunun emrinde

Vatan millet zikrinde para pul fikrinde

Kurt görünür çakallık peşinde

İmrendiği hayat kurşunlu dizilerde

Erkek müsvettesidir erkekliği temsilde

Cesura dost korkağa kabadayı

Karikatüristlere ilham kaynağı

Gecekondu milliyetçiliğin serseri kalfası

İnsanlığın alçağı Türklüğün vebası

Allah''ın belası karizma budalası', 'Dengesi bozuk omuzu kırık Elinde tespih kaşları çatık Nefsinde kibir güçlüye sadık İntihar eder aklında mantık Üstünde bir takım elbise Gözl...', ARRAY['Türk Edebiyatı','Şiir','Sinan Ercan']::text[], 8.5, '{"poet":"Sinan Ercan","poet_slug":"sinan-ercan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/cakal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmadı İşte', 'olmadi-i-ste-ender-altinisik-t7x14', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kuş sesleri gibi

karışıp kaybolmasaydın

şehrin gürültüsünde; 

iliklerime kadar 

ıslatan bu yağmuru da

beraber yürürdük…

Neylersin 

	olmadı işte! ! ! 

Kaybolup gittin ya sen

yağmurların ve rüzgarların

ortasında kaldım ben…

Yanı başımda 

	deniz…

Öyle kaldım

	sessiz…

Öyle 

	sensiz,

		kimsesiz…', 'Kuş sesleri gibi karışıp kaybolmasaydın şehrin gürültüsünde;  iliklerime kadar  ıslatan bu yağmuru da beraber yürürdük… Neylersin  	olmadı i...', ARRAY['Türk Edebiyatı','Şiir','Ender Altınışık']::text[], 8.5, '{"poet":"Ender Altınışık","poet_slug":"ender-altinisik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/olmadi-iste-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümümsün...', 'olumumsun-ender-altinisik-fvxwl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dallara küsen sevdalarda

	tutunduğum dalımsın

		gel

		sensiz bırakma.

Gözlerinden süzülürüm,

	düşer, 	

		bin parçaya bölünürüm

				ölürüm…

Küllerimden her yarattığımda seni

	bir anka kuşu olur

		gidersin masal dağına…

Al beni de yanına; 

	bırakma yalnızlığın koynuna…

Sen  inceden inceye eriten ömrümü

	içimdeki yarasın,

		kalbimde sızı…

Hiç yazmadığım şiir,

yaşamadığım en mutlu günsün.

Sen dünüm,

                bugünümsün…

Sen benim 

               ölümümsün...', 'Dallara küsen sevdalarda 	tutunduğum dalımsın 		gel 		sensiz bırakma. Gözlerinden süzülürüm, 	düşer, 	 		bin parçaya bölünürüm 				ölürüm… K...', ARRAY['Türk Edebiyatı','Şiir','Ender Altınışık']::text[], 8.5, '{"poet":"Ender Altınışık","poet_slug":"ender-altinisik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/olumumsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba’mdan kalan', 'baba-mdan-kalan-ender-altinisik-zi95p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bahçeli bir gecekondumuz,

	eskimiş gocuklarım,yırtık yamalı pantolonlarım,

		su çeken ayakkabılarım vardı benim…

Ve bir de 

	adam gibi bir babam…

Yoksulduk; 

	 yemezdi, yedirirdi

		hiç aç kalmadım…

Her akşam iş dönüşü yoluna bakardım,

onun kadar büyüdüğümü düşleyerek

	hayallere dalardım…

Arka lastiği sekiz çizen bisikletimle

	ondördüme geldiğimde,

gözyaşı dökmeme bile fırsat bırakmadan

	arabaya binip gitmişti babam.

En çok ben ağladım

	ama içimden! 

O’nu sevdiğim gibi

	kimselere fark ettirmeden…

Ölmüştü elleri sıcak,

	yüreği bizim için çarpan 

		o koca adam…

Bir daha baba diyememekti 

	ondan bana kalan…', 'Bahçeli bir gecekondumuz, 	eskimiş gocuklarım,yırtık yamalı pantolonlarım, 		su çeken ayakkabılarım vardı benim… Ve bir de  	adam gibi bir b...', ARRAY['Türk Edebiyatı','Şiir','Ender Altınışık']::text[], 8.5, '{"poet":"Ender Altınışık","poet_slug":"ender-altinisik","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/baba-mdan-kalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Beni Sevmen Hoşuma Gidiyor', 'beni-sevmen-hosuma-gidiyor-nurten-altinok-qfxgp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hani son bir şans tanırlar ya

İdam mahkûmlarına

—ben olsam SU isterdim-

Öylesine tutunmuştum

Uçurum eteklerine 

Gardiyansız

—olsaydı SU isterdim

Cellat cübbesindeydi dünya

SU su yor / um

Bir yıldıza tutunuyorum

Kan revan

Umutlarım sehpada

Yarınlarım da

Bittim bitiyorum

Derken

Sen geliyorSUn

Ve ellerin

Ve yüreğin

Geliyor

Sorsalardı

— SU olmak isterdim 

Yolunda

Bir şiire yazılmak

Ana kucağı sıcaklığında

Bir de sana 

Anla işte! 

Çekim alanındaydım denizin / SU

Kraterinde bir yanardağın / ATEŞ

Beni sevmen hoşuma gidiyor

Uçurumlarda bıraktım gölgemi...', 'Hani son bir şans tanırlar ya İdam mahkûmlarına —ben olsam SU isterdim- Öylesine tutunmuştum Uçurum eteklerine  Gardiyansız —olsaydı SU iste...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/beni-sevmen-hosuma-gidiyor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dost''a', 'bir-dost-a-erol-dal-bsjwl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Buzdan heykellerim,

Yıllardır saklı odamda.

Kardan adamlarım,

Camımda buğular, vardı.

Gördüğüm sadece kardı..

Sobam vardı,

Yaz kış yanardı.

Kırmızıyı oradan bilirdim 

Yaklaşınca yakardı..

Masam vardı, beyaz örtülü

Üstünde, de

Ellerim,

Mor, mor çiçek açmış; 

Ara sıra sızlardı.

Sonra,

Sen girdin odama; 

Beyaz, sarıya döndü,

Kar kalktı,

Güneşi gören soba 

Söndü.

Gözlerime baktın, 

Kızardım, 

Kırmızının yaktığını 

bir kez daha anladım.

Öylece kalakaldım.

Dokundun hafifçe, 

Mor çiçekli ellerimden 

Utandım.

......

Gözlerine ilk baktığımda,

İki satır mısra düğümlendi kalbime,

Tüm, korkuların utanmışlığını bırakarak ardımda,

Söylüyorum işte.

“Sen şairsin,

gözlerinse şiirin; 

Isıtıyor beni 

Dizelerinde.”

ED.', 'Buzdan heykellerim, Yıllardır saklı odamda. Kardan adamlarım, Camımda buğular, vardı. Gördüğüm sadece kardı.. Sobam vardı, Yaz kış yanardı. ...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/bir-dost-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni', 'seni-servet-suner-zj1f0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir ölüm kadar yakınımda,

Bir hasret gibi dağların ardında,

Bir özlem gibi yüreğimde,

Besleyip büyüttüm içimde seni.

Bir göze gibi dağ doruğundan,

Bir dere gibi yaylalardan,

Bir şelale gibi yamaçlardan,

Çağlayıp akıttım gözlerimden seni.

SERVET SUNER', 'Bir ölüm kadar yakınımda, Bir hasret gibi dağların ardında, Bir özlem gibi yüreğimde, Besleyip büyüttüm içimde seni. Bir göze gibi dağ doruğ...', ARRAY['Türk Edebiyatı','Şiir','Servet Suner']::text[], 8.5, '{"poet":"Servet Suner","poet_slug":"servet-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seni-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaylalar', 'yaylalar-mustafa-toga-u6jsx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hasret kaldım göz pınarım çağlıyor	

Al yazmalım yüreğimi dağlıyor

Bülbül gelmiş gül dalında ağlıyor 

Sevdalıya türkü olan yaylalar.

	

Burcu burcu kokar çiçek dağları

Sende suna boylum nerde bağları

Tüm kuşların dönüm yeri durağı

Başı pâre pâre karlı yaylalar.

	

Orta Toroslar’ın yüce bağrında

Tekir yaylasıdır çamlık alanda

Turnaların gökyüzüne dolanda

Kıvrım kıvrım akar suyun yaylalar.

	

Aşık Toga''m soğuk ayran içince

Yavru ceylan seke seke kaçınca

Kayalarda lâle sümbül açınca

Çukurova sıcağına derman yaylalar.

www.togamedya.tr.gg

Tekir Yaylası-Pozantı / ADANA', 'Hasret kaldım göz pınarım çağlıyor	 Al yazmalım yüreğimi dağlıyor Bülbül gelmiş gül dalında ağlıyor  Sevdalıya türkü olan yaylalar. 	 Burcu ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Toga']::text[], 8.5, '{"poet":"Mustafa Toga","poet_slug":"mustafa-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yaylalar-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz|dı istedik', 'yaz-di-istedik-zafer-zengin-etnika-6rppn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eğilmesem önünde

Sessizce gelsen içime

Hani sormasan adımı

Demesen kaşların dağınıktır

Bıyıksız yüzün çocuk

Hani demesen

Sevdiğini söylesen

Kimseye çaktırmadan

Ben ölsem

Ve sen kimseye söylemesen

Çok yakalandım ele

Bu yüzden aşk vurmaz dilime

Sedir diplerinde törpü

Hep ispiyon

Hep gammaz

Haksız olsam gıkım çıkmaz

| Sarmadım meydanlar da ellerini

Seçemedim gözlerini |

Mahalle yollarını arşınlarken

Gözüm hep yollarındaydı

İki adım geçince gözlerini

Ayaklarım geri giderdi

Ne olur

Kimseye söyleme

Kendin için beni sevdiğini

Gül bu adam

İşi bu desen 

Anlarım hallerimi

Cam açık aklımda

Ceryanı tutuyor rüzgarın

Savruluyorum

Oradan oraya

Dar ağacı kuruluyor

Ellerimin ayasına

| Haziran geldi

Ateş tükendi

Mevsime |

Hüzün desem değil

Kuşanmış geliyor ki

Bir yenilgi sanırım

Yarına belki

Bir daha cıkmayacağım

| Gül asılsa tel duvarlara

Rengi vuruyor aklıma |

Hiç kadar

Yorgun dünya

Bir sarılsa hayata

Çok sarhoş olacak daha

Sitemi rüzgara

Sıcakla soğuğun kavuşmasına

Dönüyor mevsim

Sarhoş kafanın ortasına

| İçen bizdik suları

Yaz/dı

İçimiz yangındı

İstedik |

28 Mayıs 2004 '' Kan konuşmaz ''', 'Eğilmesem önünde Sessizce gelsen içime Hani sormasan adımı Demesen kaşların dağınıktır Bıyıksız yüzün çocuk Hani demesen Sevdiğini söylesen ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/yaz-di-istedik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyam', 'siyam-ahmet-aksoy-n1yl1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'insanların gözlerinden

