INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Şarabı', 'askin-sarabi-mehmet-kesen-eouf1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'mevsimsiz açan bir çiçektin

dalından koparılmayı bekleyen

emanet duruyordun zamanın koynunda

harcın topraktı senin

suya hasretliğin bu yüzden

akıt gözyaşlarını kendin adına

çek setlerini dudağına

ve aşkın şarabını yudumla', 'mevsimsiz açan bir çiçektin dalından koparılmayı bekleyen emanet duruyordun zamanın koynunda harcın topraktı senin suya hasretliğin bu yüzde...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kesen']::text[], 8.5, '{"poet":"Mehmet Kesen","poet_slug":"mehmet-kesen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/askin-sarabi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-mehmet-kesen-ckyfr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'veda zamanı geldi

burası son durak

yalnızlığın sevinecek yokluğuma

sessizlik dillenecek

bensizlik boğazında düğümlenecek

bir hesap varsa ödenecek

aşkını verdim sana

üstü kalabilir', 'veda zamanı geldi burası son durak yalnızlığın sevinecek yokluğuma sessizlik dillenecek bensizlik boğazında düğümlenecek bir hesap varsa öde...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kesen']::text[], 8.5, '{"poet":"Mehmet Kesen","poet_slug":"mehmet-kesen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/veda-101-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara''lım', 'ankara-lim-mustafa-toga-wx707', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kara sevda uğruna 				

Dağlarını, ovalarını				

Ormanlarını aşarım

Benim bahtı karalım

Ankara’lım, Ankara’lım.			

Akbenizli, siyah saçlar			

Zarif, ince, kalem kaşlar 			

Yılan derisi pabuçlar				

Benim bahtı karalım				

Ankara’lım, Ankara’lım.

						

Rüzgârda açılan etek 

Dudakları da bal petek

Saçlarında kurdale tek				

Benim bahtı karalım				

Ankara’lım, Ankara’lım.			

www.togamedya.tr.gg				

Aydınlıkevler / ANKARA', 'Kara sevda uğruna 				 Dağlarını, ovalarını				 Ormanlarını aşarım Benim bahtı karalım Ankara’lım, Ankara’lım.			 Akbenizli, siyah saçlar			...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Toga']::text[], 8.5, '{"poet":"Mustafa Toga","poet_slug":"mustafa-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ankara-lim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşıklarımız', 'asiklarimiz-mustafa-toga-g5xlk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'AŞIKLARIMIZ 	

		

Aşıklar toplanıp birlik olalım.		

Sazımız doğrudan dönmez ha dönmez.	

Mahmut Taşkaya’yım çalıp söylerim

Doğru yoldan izim dönmez ha dönmez.

		

Kul Mustafa’m Çukurova düzünü

Hacı Karakılçık almaz hızını

Vahap Kocaman’ım dinlet sözünü

Sözümdeki birlik dönmez ha dönmez.

		

Peymani’yim Kadirli’den ünlerim

Karakoç’um taşmış bendim çiğnerim

Abdurrahim doğru yolda söylerim

Hakyolunda dilim dönmez ha dönmez.

		

Fezahi, Ruhani, Aşık Turan’ı

Dinimiz islamdır, kitap Kuran’ı

Sivas ilinin koca Veysel ozanı

Doğruluktan sazım dönmez ha dönmez. 

		

Aşık Toga’m sende katıl araya

Benden selam olsun Çobanoğlu’ya

Davut Sulari’nin doğru yoluyla

Kaygılı, Reyhani  dönmez ha dönmez. 

Sözün Özü: Mekanı fethetmek bir marifettir, fakat mekanla beraber zamanı da fethetmek yüz misli değerindedir. (Y.K.Beyatlı)   

	

Kadirli / ADANA

www.togamedya.tr.gg', 'AŞIKLARIMIZ 	 		 Aşıklar toplanıp birlik olalım.		 Sazımız doğrudan dönmez ha dönmez.	 Mahmut Taşkaya’yım çalıp söylerim Doğru yoldan izim d...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Toga']::text[], 8.5, '{"poet":"Mustafa Toga","poet_slug":"mustafa-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/asiklarimiz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Misket Kutusu', 'mavi-misket-kutusu-aziz-akgun-b2q2s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mavi misket kutusunda 

Unuttuğum hayat…

Bir mart gecesi koyduğum 

O tozlu rafta mısın hala 

Neler geçer de içimden

Söyleyemem 

Bir bilsen hey hat...

Ben büyüdüm

Akıp giden zamanla

Peki sen

O masum yaşta mısın hala... 

a.z.i.z.  a.k.g.ü.n.', 'Mavi misket kutusunda  Unuttuğum hayat… Bir mart gecesi koyduğum  O tozlu rafta mısın hala  Neler geçer de içimden Söyleyemem  Bir bilsen he...', ARRAY['Türk Edebiyatı','Şiir','Aziz Akgün']::text[], 8.5, '{"poet":"Aziz Akgün","poet_slug":"aziz-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mavi-misket-kutusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıt', 'kayit-elif-sebnem-akal-qp3nk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gittin

her an''ı dikte edilen 

''sensizlik kaydı'' hakim günlere şimdi

kıpırdasam sensizim

put gibi dursam

uyusam 

uyanmasam

nefes alsam da hani

yaşamak denemez buna

koma bu

koma hali

kötü kalpli bir soru hep

'' ya ölürsem... sensiz mi? ''

özledim

kayıt dışı bir aşkı dosyalama peşinde

hafıza sekreterim

gözlerimi ısırırken huzursuz ışıkları 

loş anılı bir evin

anı seçkisi derdim

eline geçmiştir belki

''özleme beyanı''mı da adresine gönderdim

doğru muydu adresin? 

gittin

aman ne iyi ettin! ! ! 

ya ölürsem?', 'Gittin her an''ı dikte edilen  ''sensizlik kaydı'' hakim günlere şimdi kıpırdasam sensizim put gibi dursam uyusam  uyanmasam nefes alsam da han...', ARRAY['Türk Edebiyatı','Şiir','Elif Şebnem Akal']::text[], 8.5, '{"poet":"Elif Şebnem Akal","poet_slug":"elif-sebnem-akal","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kayit-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terkedildim', 'terkedildim-fatih-konuk-kp3el', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gece ansızım terkedildim

Kalpecesine sırtımdan vuruldum

Sevdiğim yar tarafından

Adicesine,kahpecesine

Yar diye sevdiğim tarafından

Ümidimi bağladığım tarafından

Son umut diye sığındığım tarafından

Terkedildim

Canım dediğim tarafından

Uğruna yandığım tarafından

Onun için ağladığım tarafından

Terkedildim acımaksızın', 'Bir gece ansızım terkedildim Kalpecesine sırtımdan vuruldum Sevdiğim yar tarafından Adicesine,kahpecesine Yar diye sevdiğim tarafından Ümidi...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/terkedildim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinle Bu Şarkıyı', 'dinle-bu-sarkiyi-fatih-konuk-9qqmk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dinle bu şarkıyı

Ne anlatmak istiyor mısrasında

Anlamaya çalış,kalbimden hisset

Sana olan aşkımı

Hiç bir şeyde anlayamadın

Bari bu şarkıda anlamaya çalış

Dinle bu şarkıyı

Hangi derdi söylemek isyiyor nakaratında

Benim sana söylediğimi farzet

Kendini benim yerine koy

Ve öyle anlamaya çalış', 'Dinle bu şarkıyı Ne anlatmak istiyor mısrasında Anlamaya çalış,kalbimden hisset Sana olan aşkımı Hiç bir şeyde anlayamadın Bari bu şarkıda a...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dinle-bu-sarkiyi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bak ilk kurşun', 'bak-ilk-kursun-zafer-zengin-etnika-pagbb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bak

ilk kurşun

İki

göze saplandı

Bağlanmış

elleri

Kimseler

açamadı

Asma kilitti

bakış

İçimizde bıraktığı

tadı

Yarım 

yangındı

Üflenince

sönmeyen

Güzel

gülüyor gözlerin

Hırslı

ve koparan

Baktığına

sahip çıkan

| Alıcı bir şeydi bakışın

 Aklım sen de mi kaldı |

25 Haziran 2004 '' Sır Yanarken''', 'Bak ilk kurşun İki göze saplandı Bağlanmış elleri Kimseler açamadı Asma kilitti bakış İçimizde bıraktığı tadı Yarım  yangındı Üflenince sönm...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bak-ilk-kursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunma', 'dokunma-i-kbal-senturk-8gzyl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'artık susmayacağım

yordu beni bu sessizlik

yenildim......

savaşmaya yemin ederek dirildim

ekmeğime,

alın terime

emeklerime dokunma

önlerine başımı boyarım

ölümden önce,geçiş yok

işte meydan

biraz deliyim ben.....

belkide delikanlı..', 'artık susmayacağım yordu beni bu sessizlik yenildim...... savaşmaya yemin ederek dirildim ekmeğime, alın terime emeklerime dokunma önlerine ...', ARRAY['Türk Edebiyatı','Şiir','İkbal Şentürk']::text[], 8.5, '{"poet":"İkbal Şentürk","poet_slug":"i-kbal-senturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dokunma-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tut/mayın beni', 'tut-mayin-beni-zafer-zengin-etnika-iyhct', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dalımdan düşmüşüm

Bastığım yer toprak

İçim şarabi

Dalımdan düşmüşüm

Derdim akıl işi

Tut/mayın beni

Kıyısına düştüm suyun

Deniz bekler ilerde

Bir hasret

Pir hasret

Dalımdan düşmüşüm

Rengim şarabi

Derdim memleket işi

Tut/mayın beni

| Şu ilerideki mavilikte neki |

Çok mu açılmışım 

Sevdanın rengine

Rengimi geri vermiyor ki

Sevgili halil manapın | ASİ YAPRAK | adlı eserinden esinlenilmiştir.

29 Haziran 2004 '' Sır yanarken ''', 'Dalımdan düşmüşüm Bastığım yer toprak İçim şarabi Dalımdan düşmüşüm Derdim akıl işi Tut/mayın beni Kıyısına düştüm suyun Deniz bekler ilerde...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tut-mayin-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Solu/can', 'solu-can-ahmet-aksoy-4nw9x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gelecek günlerin yiğit duruşu

.........................umut

muhtacım diyebilmenin onuru

kan sarnıcına uzanan serum

........her ne kadar artsa da 

.....................boyun borcu

bağlıdır toprağına ruh

.....umut ve serum

acı günah mutlu sevap', 'gelecek günlerin yiğit duruşu .........................umut muhtacım diyebilmenin onuru kan sarnıcına uzanan serum ........her ne kadar arts...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/solu-can-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kozalak', 'kozalak-gulay-morgul-dc5zg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hüzünler içime doldukça

Hani hep yanımda olacaktın

Hani her gördüğün çiçek

Sana beni hatırlatacaktı

Şimdi bahar geçmiş olabilir

Çiçeklerde kurumuş

Lakin beni hatırlatacak

Bir kozalakta mı yoktu senin şehrinde...

GM', 'Hüzünler içime doldukça Hani hep yanımda olacaktın Hani her gördüğün çiçek Sana beni hatırlatacaktı Şimdi bahar geçmiş olabilir Çiçeklerde k...', ARRAY['Türk Edebiyatı','Şiir','Gülay Morgül']::text[], 8.5, '{"poet":"Gülay Morgül","poet_slug":"gulay-morgul","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kozalak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi bana bir şiir yazdır', 'hadi-bana-bir-siir-yazdir-cafer-yilmaz-369qw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hadi utanma kelimelerimden

Çok oldu yazmayalı,

Tut kelimelerimden.

Uzun zamandır...

Hadi bana bir şiir yazdır...

Ben kapını çalmıştım,

Sen kapımı çaldın,

Çok zamandır kapattığım...

Madem ki  açıktır

Hadi bana bir şiir yazdır...

Sana bir şiirim yoksa

Şair olamamamdan değil! 

Aşık olamamamdan...

Kafanı çalıştır,

Hadi bana bir şiir yazdır...

İster bir gemi ol ister bir dalga....

İster havadan ol ister sudan....

Bir kağıt bir kalemle

Beni kandır...

Hadi bana bir şiir yazdır.

Şiirleşirsen büyürsün içimde,

Şirinleşince değil..! 

O yüzden bırak kur yapma! 

Defterimi açtır

Hadi ban bir şiir yazdır...

Benim yüreğimdir şiir

Damarım mısra...

Sevdalarım kandır.

Sen sen ol bir an önce

Hadi  bana bir şiir yazdır.', 'Hadi utanma kelimelerimden Çok oldu yazmayalı, Tut kelimelerimden. Uzun zamandır... Hadi bana bir şiir yazdır... Ben kapını çalmıştım, Sen k...', ARRAY['Türk Edebiyatı','Şiir','Cafer Yılmaz']::text[], 8.5, '{"poet":"Cafer Yılmaz","poet_slug":"cafer-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hadi-bana-bir-siir-yazdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden...', 'neden-cafer-yilmaz-a2hro', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ne kadar yüksekten düşse de bir taş,

bir kovuktur son durağı...

ne kadar yakından gelse de bir laf,

bir doruktur son durağı...

kırılmak sevgiden doğar

parçalanmak,

harap olmak sevgiden...

oysa sevgiler yavaş başlar,

bitişleri aniden...

yaşam da öyle değil midir? 

aylar alır ilk nefes

son nefesi aniden...

bir elmanın yarısı,

derler ya; 

biri sen... biri ben....

oysa her elma beslenir 

aynı kökten...

bir gelişin vardı senin de...

kasıp kavurdun her yüreği.

böyle sessiz,

böyle ani,

görmeden gidişin,

gidişin neden?', 'ne kadar yüksekten düşse de bir taş, bir kovuktur son durağı... ne kadar yakından gelse de bir laf, bir doruktur son durağı... kırılmak sevg...', ARRAY['Türk Edebiyatı','Şiir','Cafer Yılmaz']::text[], 8.5, '{"poet":"Cafer Yılmaz","poet_slug":"cafer-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/neden-89-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sağolun...', 'sagolun-cafer-yilmaz-p9je9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çok uçurum kenarından döndük bir çırpıda...Çırpınarak hatta çırpılarak  omlet olduk sofralara...Birkaç kez düştük hatta, kanadık ölesiye...

Hayat bize sevmek için zamanında fırsat vermedi.Ve sonra zaman geçti çok fırsatlarımız oldu ama biz sevemedik...

Pespembe hayaller kurmaya hiç mi hiç vaktimiz olmadı bizim. Çocuksu duygularımız...  oyunlarımız ve oyuncaklarımız, öğretilerimiz bile  garip bir

yetişkinlik kokardı.

Çocuktuk ve tarih 80 öncesini yaşıyordu. O günlerde tüm maharet akşam eve 

sağ olarak gelebilmekti. Babamızın işten gelişini heyecanla beklerken radyolarda o gün eve gidemeyecek ve çocuklarını göremeyecek olanların sayısını ve isimlerini sayıyordu tek tek...Tarandı bindiğmiz minibüsler, taşlandı, çevrildi çoğu kez bir gece vakti büyükler yüzünden.Bize sevgi yerine

kinler öğretildi daha ilkokula giderken...Öğretmenim koyu bir solcu ailem ise muhafazakardı. İki yüzlü yaşamayı o günlerde öğrendim. Evde dindar sağcı,

okulda solcu...Karıştırdığım zamanlar -çocuktuk işte- şiddetin ne kadar acı 

verdiğini öğrendim. Şimdi bazen duvarlarda olan o “Ayşe Kemal’i seviyor” veya “ seni seviyorum aslı” yada “pazara kadar değil mezara kadar” gibi yazılar 

yerine o zamanlar başka başka şeyler yazardı duvarlarımızda. Sevgiler başka şeylereydi.

Çocuksu da olsa komşu kızını sevmeyi ayıp bildik... Kaçamak sevgiler besliyorduk bu yüzden. Aynada suratımıza itiraf etsek hani yüzümüz kızaracaktı neredeyse...

Okulda kız arkadaşlarımızın yanına oturamadık...Bedenlerimiz yan yana 

gelmedi bir sırada hiç. Bu yüzden bahane oyunlar oynardık tanışsınlar diye.

Bazen kaza süsü verilmiş aşk cinayetleri işlerdi bedenlerimiz. Karanlık basardı ve yalnız olurdu cinayet mahalli... evet, büyüklerimiz bilseydi cinayet sebebi  olurdu kaza süsü verilmiş temaslarımız... Şimdilerde çok masum kalacak temaslarımız...

Beynimde ihtilal çağı geldiğinde bu ülke de bir kez daha yaşamıştı ihtilali. Bu 

seferde kızdan arkadaş olmaz devrimi yaşıyorduk...”peki ne olur? ” diye sorabilme cesaretimiz vardı artık ama cevabını saklama korkaklığımız hala yaşıyordu. Daha birkaç sene önce kaza süslü temas eden parçalarımız sanki ömür boyu birbirini görmeme cezasına çarptırılmıştı.

Ben kadın vücudunu şimdilerde arka sayfa güzeli olarak basılan fotoğrafların,

manşetlerde gezdiği; benden başka insanların aşk hikayelerinin cinsellik kokan yazılarının büyük puntolarla  haber yapıldığı o zamanın meşhur gazetelerinden öğrendim. Ve benim gibi bir gençlik öyle öğrendi kadını yada erkeği...

Ve o gençlik benim yaşımda... Öğrenmeden sınıf geçirdiler... İlerde öğrenirsin dediler...

Öğrendim...

Temelden zayıf yapılmış bir binanın bir gün yıkılacağı gibi insanında hayatta yıkılışını gördüm...

Sağ olun ey benim çocukluk çağımda hayatıma giren insanlar! ! ! 

SAĞOLUN...!', 'Çok uçurum kenarından döndük bir çırpıda...Çırpınarak hatta çırpılarak  omlet olduk sofralara...Birkaç kez düştük hatta, kanadık ölesiye... ...', ARRAY['Türk Edebiyatı','Şiir','Cafer Yılmaz']::text[], 8.5, '{"poet":"Cafer Yılmaz","poet_slug":"cafer-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sagolun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk dediğin...', 'ask-dedigin-cafer-yilmaz-s4aeq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşk dediğin titretmeli adamı

Sıtma geceler yaşatmalı

Durup dururken

Bir güldürmeli

Bir ağlatmalı...

Aşk dediğin çıkarmalı yüreğini

Saklandığı demir kapılar ardından...

Aşk dediğin; 

Kaçıklıklar yaşatmalı

Biraz ihtiyarlıktan,

Biraz çocukluktan..

Beklerken gelmesini

Randevu yerine

Aşk dediğin 

kokusunu getirmeli önce

burun deliklerine...

balık olmalı 

sevdiğinin yüreğinde...

kıyılarına gelmemeli denizin...

ya geri dönmeli

ya ölmeli...

gecelerini kapatmalı hayaller

uykularını bölmeli

aşk dediğin

yatağına getirmeli

nerde olursa olsun,

ilk “ günaydın” ı 

ona dedirtmeli......', 'Aşk dediğin titretmeli adamı Sıtma geceler yaşatmalı Durup dururken Bir güldürmeli Bir ağlatmalı... Aşk dediğin çıkarmalı yüreğini Saklandığ...', ARRAY['Türk Edebiyatı','Şiir','Cafer Yılmaz']::text[], 8.5, '{"poet":"Cafer Yılmaz","poet_slug":"cafer-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ask-dedigin-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhteviyatı yanıltıcı bir duyguydu gözlerin / Hikayeler Dört (4)', 'muhteviyati-yaniltici-bir-duyguydu-gozlerin-hikayeler-dort-4-gencay-coskun-dpnh7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Muhteviyatı yanıltıcı bir duyguydu gözlerin

Görmesem bir gün 

Kalbim Titrerdi 

Ne zaman nerede olduğumu bile 

Unuturdum çok zaman 

Kendime gelmem bir asır sürerdi

Bu asırlar nedense hep 

Benimle buzul çağına denk gelirdi 

Erisin diye beklerken buzlar 

Süzülen ben olurdum derinlere 

Geri dönerken 

Özüm dönerdi özüne 

İlk yıldızın ışığı vururdu gözüme 

Onca yoldan 

Sonra senin kıta sahanlığına gelip

Yelkenlerimi 

Tüm rüzgarlarına 

Katıksız yalansız sana bırakmıştım

Bir şey seziyordum 

Çalı çıtırdamasın da

Her an ortaya çıkacakmış gibi 

Sinsi bir şekilde geliyordu gerçek 

İhaneti sırtıma saplamışlarken 

Ardıma dönüp bakmak bile 

İstemedim 

Göreceklerim 

Asla görmek istemeyeceklerimdi 

Sırtımdaki yara asla 

Geçmeyecekti 

Kanın canın insanlar 

Birlik olup 

Akın ederlerse üstüne 

Uğrunda savaştığın çekip 

Giderse başka bir yere 

Kapısında kalırsın hayatın 

Bir daha asla içeri girmemecesine 

Yaşanan her saniyede 

İzi vardır sevileninin 

Yüreği dağlayan 

Dağları ufalayan 

Birde iklimi 

Ne kardır 

Ne yağmur 

Erozyona uğratan insanı 

Yalandı

Köküne kadar 

Kirleten hayatı 

Ellerin terlemişse onun elinde

Elini elinden Çekmesi 

Kesin hile

Yanında 

Radar gözleri 

Hareketli kayda değer obje arıyorsa 

Önüne gelen bayağı cisimlerde duruyorsa

Mesajı vermeden gitme vaktidir

Bir anlık bakışlarla 

Büyüse bile 

Bu ateş 

Muhteviyatı yanıltıcı bir duyguyla 

Sönüverir 

Külleri ise 

En derin okyanuslara 

Gönülsüz dökülüverirdi

Büyük bir yanılgı olduğunu anladığında 

Kısa metrajlı film şeridinin 

Döngüsünden kurtulmak gerekirdi

Muhteviyatı yanıltıcı bir duygu 

Öylesine dönerdi ki 

Düşüp kırmadan bir yerini 

İçinden çıkmak imkansızdı 

Yanlış dilenen bir dileği bile 

Zamanı geldiğinde 

Geri almak bile

Kahpeliğin karasularında 

En büyük erdemdir.

Güzel günler 

İleride belki 

Yaşananlar 

Küçücük yüreğimi 

Çok fazla acıttı belki 

Belki diye bir ömür geçti 

Belki hiç doğmamalıydım 

Ama doğmuştum 

Yapacak tek şey 

Yaşamaktı acemice her saniyede 

Muhteviyatı yanıltıcı bir duyguydu sözlerin

Bana çok fazlaydı 

Belki sen haklıydın 

Hep ben eksiktim 

Seni tamamlayamadım 

Muhteviyatı yanıltıcı bir duyguydu gözlerin

Başka gözlere aşinaydı 

Bana zoraki bir acımaydı 

Üçüncü nesil birer bahaneydi 

Muhteviyatı yanıltıcı bir duyguydu seninki 

Benimkisi gariban safkandı belki 

Ama çok saftı 

Zamana karışımı 

Uzun sürüyordu', 'Muhteviyatı yanıltıcı bir duyguydu gözlerin Görmesem bir gün  Kalbim Titrerdi  Ne zaman nerede olduğumu bile  Unuturdum çok zaman  Kendime g...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":99,"source_url":"https://www.antoloji.com/muhteviyati-yaniltici-bir-duyguydu-gozlerin-hikayeler-dort-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabah sabah...', 'sabah-sabah-cafer-yilmaz-ntv7s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Birazdan imam efendi ezan okur...

Uyanır insanlar yavaş yavaş.

Güneş parıldar boğazın sularında.

Çocuklar; sabahçı çocuklar

Cıvıl cıvıl çınlar sokaklar.

Balıkçılar açılır denizlere

“ ya kısmet..! “ diye

bilinmeyen bir yere...

sıcak ekmeğin buram buram kokusu yayılır şimdi.

Ve sabahçı olmayan çocuklar 

simit satar.

Şarkısı duyulur uzaklardan bir kumrunun,

Ayakkabı sesi beynime işler

İşten dönen yosma bir yavrunun.

İşe gider birileri,

Sokakta çınlar motor sesleri.

Teker teker yok olur

Karanlığın ayak izleri.

İnsan kokar sokaklar,

Köpek kokar,

Kuş kokar....

Hayat kokar kısaca...

Bir deli pencereden bile korkar....', 'Birazdan imam efendi ezan okur... Uyanır insanlar yavaş yavaş. Güneş parıldar boğazın sularında. Çocuklar; sabahçı çocuklar Cıvıl cıvıl çınl...', ARRAY['Türk Edebiyatı','Şiir','Cafer Yılmaz']::text[], 8.5, '{"poet":"Cafer Yılmaz","poet_slug":"cafer-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sabah-sabah-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Tomurcuğu', 'sevgi-tomurcugu-metin-akil-pj7dx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sebep oldun baharıma yazıma,

         Name oldun dilsiz duran sazıma,

         Yağmur oldun kurumuş dudağıma,

         Bir sel olup sana akasım geldi.

         Diken idim gül bitirdin bağrımda,

         Mecnun ettin beni Leyla yolunda,

         Yaktın beni aşk denilen narında,

         Aşık olup sana yanasım geldi.

         Metin idim kavrulurdum yağımda,

         Fırtınaydım savrulurdum dağımda,

         Kuş uçmaz kervan geçmez bağımda,

         Bir gül olup sana açasım geldi.', 'Sebep oldun baharıma yazıma,          Name oldun dilsiz duran sazıma,          Yağmur oldun kurumuş dudağıma,          Bir sel olup sana aka...', ARRAY['Türk Edebiyatı','Şiir','Metin Akil']::text[], 8.5, '{"poet":"Metin Akil","poet_slug":"metin-akil","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgi-tomurcugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Caka', 'caka-baykal-kaanalp-i313y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'açıkta satılan birkaç parça

çiçek gibiydi

gönül koyan sohbet anlayışı

sözlerini birbirine ekleyişi

ayrı bir tat,ayrı bir hazdı

görülmeye,görülmeye

sakinleşmiş

silikleşmemiş

ama sönmüş bir

gösterim tarzı

dudaklarda,gösteriş,caka

kendini saklamaya

çalışmayan

çekinmeyen

bir maaş bordrosu endamında

burnun alt kenarında

otobüs bekliyordu', 'açıkta satılan birkaç parça çiçek gibiydi gönül koyan sohbet anlayışı sözlerini birbirine ekleyişi ayrı bir tat,ayrı bir hazdı görülmeye,gör...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/caka-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazacak çok şey var', 'yazacak-cok-sey-var-cafer-yilmaz-s79a1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir İstanbul sabahında

Boğazın sularıyla yıkadım yüzümü

Martılar havlumu tuttu,

Ben onlara simit attım...

Tanıdık bir sima aradı gözlerim

Sevilesi bir yürek...

Bir efkar bastı eski günlere

Dalgaları satır satır karaladım...

Bir İstanbul vardı sevdiğim

Bir İstanbul gibi sevdiğim...

Ey İstanbul kokuşlum! 

Kal deseydin, gidermiydim...

Fethedilmiş bir şehrin

Fethedilememiş bir yüreği...

Surlar diktim ben de

Senin başlayıp

Ve senin bittiğin yere....

Arnavut kaldırımlı yüreğin

Kanattı her yerimi.

Kız kulesi gibi uzaktın kıyılarıma.

Ne zaman seni sevsem

Adresim Yedikule zindanlarında...

Boğazında fırtına eser,

Köpürür deniz, çoğalır dalgalar...

Satır satır vurur kıyıma

Sana yazacak çok şey var!', 'Bir İstanbul sabahında Boğazın sularıyla yıkadım yüzümü Martılar havlumu tuttu, Ben onlara simit attım... Tanıdık bir sima aradı gözlerim Se...', ARRAY['Türk Edebiyatı','Şiir','Cafer Yılmaz']::text[], 8.5, '{"poet":"Cafer Yılmaz","poet_slug":"cafer-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yazacak-cok-sey-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amet Dayım', 'amet-dayim-baykal-kaanalp-ma60p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'o benim Amet dayım

buzdan heykelleri var

yontamadığım

sonra sınırsız bir sevgisi

klişeleşmemiş

içine giremediğim

girmeye çalışmadığım

etrafını ağlarla ördüğü

bir dünyası var

yabanıl olmayan

sonra sınırsız bir sevgisi

klişeleşmemiş

o benim Amet dayım

saçlarını yalnızca benim

taradığım,benim boyadığım

benim oyunlar oynadığım

heykellerini yalnızca benim yonttuğum

sonra sınırsız bir sevgisi

klişeleşmemiş', 'o benim Amet dayım buzdan heykelleri var yontamadığım sonra sınırsız bir sevgisi klişeleşmemiş içine giremediğim girmeye çalışmadığım etrafı...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/amet-dayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azap', 'azap-metin-akil-6jx1j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Azaba döndü hayatım 

             Çelik kafesler içinde gibiyim

             Hergün duvar biraz daha yaklaşıyor

             Tavan biraz daha iniyor gibi

             İnan kapılar hiç açılmıyor güzelim

            .....

             Bir menteşe gıcırdıyor yırtılırcasına

             Ben hep seni bekliyorum

             Bazen bir keman sesi yankılanıyor

             Beynimin duvarlarında

             Bazen de ıslık çalınıyor zannediyorum

             Bu ıssız karanlığında zindanın

             Sadece senin ayak tıkırtılarını

             Duymak için yere koydum başımı

             Ne bir ses ne bir nefes

             Kirli bir ayakkabı ökçesi

             Çöküyor eziyor boyun çukurumu

             Artık karşı bile koyamıyorum.', 'Azaba döndü hayatım               Çelik kafesler içinde gibiyim              Hergün duvar biraz daha yaklaşıyor              Tavan biraz dah...', ARRAY['Türk Edebiyatı','Şiir','Metin Akil']::text[], 8.5, '{"poet":"Metin Akil","poet_slug":"metin-akil","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/azap-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşığın Gördüğü', 'asigin-gordugu-baykal-kaanalp-s8wmc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'aşığın gördüğü gönüldeki göz

şairin ördüğü yürekteki söz', 'aşığın gördüğü gönüldeki göz şairin ördüğü yürekteki söz...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/asigin-gordugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kötülük', 'kotuluk-mehmet-halil-p8oep', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yok etmek istemem kötüleri,

iyilikte ve kötülükte sınır bilmiyorum.

Onlar iyi olsaydı, benden ileri.

O zaman, ben kötü olurdum.', 'yok etmek istemem kötüleri, iyilikte ve kötülükte sınır bilmiyorum. Onlar iyi olsaydı, benden ileri. O zaman, ben kötü olurdum....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Halil']::text[], 8.5, '{"poet":"Mehmet Halil","poet_slug":"mehmet-halil","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kotuluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelme geri', 'gelme-geri-yunus-ali-sinanoglu-hqrgp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni sevme diyorsun

Oysa şiiriyorsun

Ellerin ışıyor gözlerim olup

Dört mevsime dönüyor

Haykırıyorsun

Aydınlığın yüzüme vuruyor

Akdeniz akşamı oluyor ilahi

Ve lakin okyanusa çıkmayan

Kadırgaları osmanlının

Uçuyor hikmet bu demek ki

Ve ulaşıyor şangaya

İsmi kanlıca geminin

Dönüyor

Dönüyor ha

kentagi oluyor

kimdir o diyorum

Seni tanımıyor kimse

Oysa  kalabalıksınız ey tuhaf dünya

Bu durumda fuzuli ağırlıksınız

Yazık varlığınız  habersiz gülden

Yazık 

deniz ve bu kayık sizin olsun derim

Çekerim rüyamı yalnız giderim', 'Beni sevme diyorsun Oysa şiiriyorsun Ellerin ışıyor gözlerim olup Dört mevsime dönüyor Haykırıyorsun Aydınlığın yüzüme vuruyor Akdeniz akşam...', ARRAY['Türk Edebiyatı','Şiir','Yunus Ali Sinanoğlu']::text[], 8.5, '{"poet":"Yunus Ali Sinanoğlu","poet_slug":"yunus-ali-sinanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gelme-geri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-metin-akil-eep24', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ellerin,ellerin kan olmuş anne

            Yüzündeki gamzelerin solmuş

            Bir top perçeminde düşmüş yüzüne

            İnciler yüzünde derin iz bulmuş.

            Kabında değilmiki bugün matem

            Beller bükülmüş,eğilmiş başlar neden

            Kimsecikler bana bir şey söylemez madem

            Elveda sizlere merhaba yeni annem.

           ....................

            Dilinde bir türkü oğlum bir tanem

            Dizinde bir yumruk şak şak eden

            Göğsünde hıçkırık kör düğümlenen

            Söylesene bana öldüm mü? annem.', 'Ellerin,ellerin kan olmuş anne             Yüzündeki gamzelerin solmuş             Bir top perçeminde düşmüş yüzüne             İnciler yüzü...', ARRAY['Türk Edebiyatı','Şiir','Metin Akil']::text[], 8.5, '{"poet":"Metin Akil","poet_slug":"metin-akil","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/annem-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İngilizce de sevebilirim', 'i-ngilizce-de-sevebilirim-yunus-ali-sinanoglu-6ceah', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kimdir bu satırlara müptela

Asrımız şiir çağı değil

Humması dört denizin

Ve ışıyan güzel gözlerin

Kimseye yar değil

Kırmızılığın habire benim

Ve bu akşam da seni çok sevmekteyim

Yanlış bir zaman

Yanlış insan

Çekmemeliyim

Aşkı

Yok mu beni kurtaran

East of the love

Nothing to speak

Every way that i can

It is very unlogic

this is crazy or fuzzy

Oh no where to catch

to be in easy

ve giderken saçma kelimeler tek tek

aniden bitirdi bu aşk bizi', 'Kimdir bu satırlara müptela Asrımız şiir çağı değil Humması dört denizin Ve ışıyan güzel gözlerin Kimseye yar değil Kırmızılığın habire beni...', ARRAY['Türk Edebiyatı','Şiir','Yunus Ali Sinanoğlu']::text[], 8.5, '{"poet":"Yunus Ali Sinanoğlu","poet_slug":"yunus-ali-sinanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ingilizce-de-sevebilirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşeye Rağmen', 'herseye-ragmen-fatih-mehmet-karaca-p5gq4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her şeye rağmen dünya

Yaşamaya değer

Her şey güllük gülistanlık

Olamaz hiçbir zaman

   Zaten her şey istediğimiz

   Gibi olsa bile

   Nereden ayırt edebileceksin

   İyiyi,güzeli,çirkini

Sıcak olur,serinlersin

Serinlediğine sevinirsin

Sevindiğin için mutlu olursun

Güzel duygulardır bütün bunlar

   İlkbahar,Yaz,Sonbahar,Kış

   Yaz olmazsa kış olamaz

   Kış olmazsa yaz olamaz

   Hepsinin yeri ayrı ayrıdır

Herşeye rağmen dünya

Yaşamaya değer

Yaşama sevincini kaybetme

Güzellikler dolu bak çevrene.

               Fatih Mehmet KARACA

      (20.06.2004) KIRIKHAN/HATAY', 'Her şeye rağmen dünya Yaşamaya değer Her şey güllük gülistanlık Olamaz hiçbir zaman    Zaten her şey istediğimiz    Gibi olsa bile    Nerede...', ARRAY['Türk Edebiyatı','Şiir','Fatih Mehmet Karaca']::text[], 8.5, '{"poet":"Fatih Mehmet Karaca","poet_slug":"fatih-mehmet-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/herseye-ragmen-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gümüş Gül', 'gumus-gul-baykal-kaanalp-bmxii', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yeni bir dünyaya gebeyken toprak

ağır,sancılı

sakın boş gözlerle onu desteksiz bırakma

seçilmişlerin yurduna girer gibi

ağır aksak,yalınayak

sakın boş gözlerle kendini

dumura uğratma

seçilmek,belli kalıplar

belirlenmiş çizgilerde

fırtınaların arasında

yumuşak bir gün gibi

gözünü kırpıştırarak

ya da ıslanmış bulutların

suyunu sıkar gibi

taze bir sağnakla ıslanmak,ıslanabilmek

seçilmiş bir tek bulut

gözleri sevinç yaşlarıyla dolu

hüzünlü ama sakin

ve dokunaklı,ve oturaklı

ve gözüpek,ve korkusuz,ve canayakın

sımsıcak,çılgın bir gülümseyiş

kimbilir hangi genç kızın

çeyiz sandığında saklı

mutluluk denen bir tutam gümüş gül

belki şu taklacı beyaz güvercinlerimin

ayaklarında

belki de kırmızı güllerin

koruyucu meleği dikenlerinde

lizozomların,amiplerin,çetrefillerin

bir damladan daha az

küçücük yüreklerinde

seçilmiş olabilmek istermiydim? 

bilmiyorum

ben zaten kendim de

seçmeyi pek beceremem

neyi seçeceğim ki

tuttuğum balığın

kıyıda ki son çırpınışlarına

yürek kabartıp suya geri atabilmeyi mi? 

onu tavada kızartıp

güzelce yemek varken

gerisin geri özgürlüğe göndermek! ! !', 'yeni bir dünyaya gebeyken toprak ağır,sancılı sakın boş gözlerle onu desteksiz bırakma seçilmişlerin yurduna girer gibi ağır aksak,yalınayak...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/gumus-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut ister bu gönül', 'umut-ister-bu-gonul-yunus-ali-sinanoglu-tsdyk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ruhumun açılan yeşil vadisi

Ayrılıklardan haber ver

Kavuşmak günü var mı

Bildiğin yerlerden oku

Konuş duyalım

Umuda kes

Umuda yan

Umuda ıslan

Umuda ışı

Umuda dön

Umuda gel

Umuda doyur

Umuda boğ

Umuda yoğur

Umuda taş

Umuda sar

Umuda taşı

Umuda ver

Umuda al

Umuda çıkar

Umuda var

Umuda renklen

Umuda dön

Umuda kır

Umuda sap

Umuda saman

Umuda dal

Ve ey beklenen

Umud ol', 'Ruhumun açılan yeşil vadisi Ayrılıklardan haber ver Kavuşmak günü var mı Bildiğin yerlerden oku Konuş duyalım Umuda kes Umuda yan Umuda ısla...', ARRAY['Türk Edebiyatı','Şiir','Yunus Ali Sinanoğlu']::text[], 8.5, '{"poet":"Yunus Ali Sinanoğlu","poet_slug":"yunus-ali-sinanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/umut-ister-bu-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sulak..', 'sulak-huseyin-umit-cetin-re9pp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey dilber bir isaret bana senden dilegim

Yürege düsen tane nedir? islasam mi bileyim! 

Filiz olsun,fidan olsun göreyim

Bu da degilse tohumu askin

Söyle! kök sürmeden sökeyim.', 'Ey dilber bir isaret bana senden dilegim Yürege düsen tane nedir? islasam mi bileyim!  Filiz olsun,fidan olsun göreyim Bu da degilse tohumu ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ümit Çetin']::text[], 8.5, '{"poet":"Hüseyin Ümit Çetin","poet_slug":"huseyin-umit-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sulak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızıl denizi geçerken', 'kizil-denizi-gecerken-yunus-ali-sinanoglu-2m0tf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kıdırgede don sayi

Unuttum ben asayı

Kızıl denizi yaran var ya

Ha o musaydı

Evet işte o gün

Aylardan kasım ondördün

Neyse kaptırmışız aşıyoruz denizi

Deniz de deniz hani azmış muttaki

Esaretten kurtuluyoruz va mı bunun başka izahat tarzı

O zamanlar yok tabi medya yazı

neyse gidiyoruz efendi

Bizim karı demez mi canım çekti pilaki

Oha dedim karı dolmanın sırası mı

Olsun diyor tam sırası

Ve dönüyorum musaya

Musa yasta

Ulan ne pilakisi diyor

Tarih yazıyoruz

Ve firavun bugün imana gelecek 

Fakat çok geç

Pilakiyi sen en iyisi çabuk geç

Ulan diyorum karı yaktın bizi

Kızdırdık adamı yokmuş pilaki

Ve ne cüretse bu efendimiz

Firavundan bahsetti

Deli

Firavun iman edecekmiş

Hani

Kin ve düşmanlığa sevk ediyor

Bu adam bölücü olaki

Hanım hanım kalk gidiyoruz

Biz orta yolcuyuz

Geriden geliyoruz

ben sana pilaki bulurum

Tanıdık bir lokanta biliyorum

-Sen var ol herif-

Bitti', 'Kıdırgede don sayi Unuttum ben asayı Kızıl denizi yaran var ya Ha o musaydı Evet işte o gün Aylardan kasım ondördün Neyse kaptırmışız aşıyor...', ARRAY['Türk Edebiyatı','Şiir','Yunus Ali Sinanoğlu']::text[], 8.5, '{"poet":"Yunus Ali Sinanoğlu","poet_slug":"yunus-ali-sinanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/kizil-denizi-gecerken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Katil Kim', 'katil-kim-erdal-sayil-hnfjr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''Bir gazete haberinden...'' 

Ocağa iki kesek, 

Odun-kömür yerine tezek; 

Akşamleyin attı.. 

Sıcağına; 

Kendi sıcağını kattı... 

Çocuklarını topladı yanına, 

En küçüğünü aldı kucağına... 

Şefkatle baktı, 

Dört çocuğuna... 

Henüz doğmamıştı birisi, 

Birden sancısı tuttu... 

Kocasını andı... 

Acaba ne iş tutup, 

Gün boyu nasıl çalıştı...? 

Çocuklar aç, 

Hava soguk; 

Vakit akşamdı... 

Tepe ki Bitlis''in tepesi... 

Sapanın en sapası... 

Yola çıkmasın kişi; 

Yanında yoksa sopası... 

Vakit akşam vakti, 

Dağlardan kurtlar aktı... 

Belki ayılarda vardı... 

Ayıdan çok korkardı Sabiha... 

İçerde ne varsa eşya, 

Yardımlaştı bebelerle; 

Yığdı kapı arkasına... 

Kömür-gaz-petrol-kalorifer; 

Değil kendi, adı gelmemişti daha, 

Bir zembil odun, birkaç kütük ver; 

ALLAH''ım tezek dayanmıyor soğuga... 

Bu kar ki kimine eğlencelik, 

Demek yetmiyor yurdumda ki güzellik, 

Bizi bağlıyorken evimize kar; 

Ki gidiyorlar gavur ele üstelik... 

Devlet baba, sen ki; 

Her daim yanımdaydın... 

Duadır dilimde eski; 

''Devlete millete olmasın zeval'' 

Ruh gibi canımdaydın... 

Bu gün benden uzaksın, 

Ne var ki... 

Ulaşmadı elin-kolun... 

Ulaşmadı ışığın-yolun... 

Düşündü bunları Sabiha, 

Bir yandan gözledi kocasını... 

Yalvardı ALLAH''a; 

Kavuşsun sağ-salim kocasına... 

Kapı çalındı birden; 

Geldi vallaha... 

Evin yerine, 

Buraya şöyle çıkılabilir ancak; 

Çıkarken dizin-dizin... 

İnerken sürüne-sürüne... 

Akıl başka yola vermez izin... 

Hayvan çıkamaz kışın, 

Tepeye nalıyla.. 

Nalı söküp nalbant, 

Ayağına lastik çaksın, 

Ki ancak böyle çıksın... 

O da varsa katırı, 

Varsa belki eşeği... 

Yoksa bir degneğin yardımı, 

Adamı yüzükoyun yatırır, 

Cam gibi buz tepeyi sardımı... 

Bu yoldan aşağı, 

Kayaların üstüne, 

Düşenler var başaşağı... 

Yolda maksat can kasdine... 

Kiminin kolu, 

Kiminin bacağı, 

Kırıldı kaldı... 

Sakat olan, 

Şükrederdi ALLAH''a, 

Sönmemişti ocağı... 

Çoktu zira, 

Kolsuz bacaksız hayatta kalan.... 

Nurettin gördü, 

Sabiha sancılanmış... 

Karısına sordu; 

Doğacak olan varmış... 

Yıkılmasın evimin direği... 

Çocuklarım anasız olmasın... 

Gitmesin ana, gitmesin çocuk; 

Evlatlarım bir kardeş eksik kalmasın... 

Nurettin önce, 

Emanet etti Rabbine... 

Evlatlarım korku düşmesin, 

Hiçbirinizin kalbine... 

Gerçi gelen olmaz ya, 

Bu havada, bu sapaya... 

Ses almadan hiçbiriniz, 

Kapıyı açmasın ha...! 

Biz geliriz sabaha... 

Hastane altı kilometre... 

Kar metre-metre... 

Tipi çok zalim; 

Donardı çehre... 

Karısı sırtında, 

Çıktı besmeleyle yola... 

Hastaneye vardı, 

Ancak saatler sonra... 

Hastane ıssız... 

Kalmış tek hastabakıcı, 

Koca binada... 

Bakışları ümit vermiyor, 

Birazda yakıcı... 

Aynı şeyleri dedi, 

Başkalarına dediği gibi; 

Ona da... 

Yere dikti gözünü, 

Utandı söylerken sözünü, 

Senin işin burda olmaz; 

Herman''a git dövme dizini... 

Dinlemedi Nurettin, 

Sevinçliydi ulaştığına hastaneye... 

Hani utanmasa oynardı bile... 

Bağırmak, çağırmak, 

Türkü çığırmak istiyordu... 

Sabiha''sı kurtulsun istiyordu... 

Aldı hekimin, 

Evinin adresesini, 

Çıktı evi aramaya lakin; 

Bıraktı bir sedyeye Sabiha''sını... 

Aradı, buldu doktoru evde... 

Işığı saklamıyordu perde... 

Amma doktorda o hüner nerde...? 

Ben anlamam doğumdan, 

Kardeşim kusura bakma, 

Lütfen gider misin; 

Canımı sıkma...! 

Nurettin, 

Buldu bir şoför... 

Yalvardı şoföre, 

Ne varsa vere... 

Çıktılar yola... 

Amma yol-yol değil... 

Herman o kadar, 

Yakın da değil... 

Onbeş kilometre vardı... 

Yol belli değil... 

Hiç iz kalmamış; 

İz belli değil... 

Vardılar Herman''a, 

Çevrede en büyük; 

Sağlık ocağına... 

Burası demek sağlık ocağı... 

Durmadık geldik, 

Yakın ettik ırağı... 

Etrafı aydınlatmaz olmuş çerağı... 

Kapı duvar, duvar taş, pencereler kapalı... 

Güya bu bina ki, maliki biz, TÜRK''e tapulu.. 

Nurettin bağırdı, 

Yardıma bir hekim, 

Bir ebe, bir hemşire çağırdı... 

Ses gelmedi karşılık; 

Bina sağırdı... 

Düşündü Nurettin, 

''Eskiden öyleydi, 

Şimdi de öyle... 

Benden vergin, 

Benden askerin... 

Bir yaradır, 

İçimde derin... 

Aradım nerdedir, 

Ey devlet baba; 

O eski yerin..? '' 

''Şimdi kendinde kendini, 

Kaybetmiş bir haldesin... 

Yetiştirip öğündüğün aydını, 

Adını bilmediğim gavur ellere, 

Kaçırıp elinden; 

Oralarda kal dersin...! '' 

''Bizim elde doktor kalmamış, 

Yaramıza melhem bile çalmamış, 

Doktorları biriktirip yad elde; 

Niye bizim ele hekim salmamış...? '' 

Yaşı dondu gözünde, 

Bir şey yandı özünde, 

Belki kurtulmak da var; 

Ümit dermandı dizinde... 

Buz cam gibi... 

Görmeye izin, 

Vermiyor tipi... 

Muş Bitlis''e; 

Beş saatlik yol, 

Sık dişini Sabiha''m; 

Dol vaktim dol...! 

Dol vaktim dol...! 

Bismillah, ya ALLAH...! 

Varırız belki vallah...! 

Muş''a vardık, 

Ancak sabaha... 

Arabada yattı, 

Konuşmadı Sabiha... 

Sandım ki soğuktan, 

Dilini tuttu... 

Çıktık çıkalı yola; 

Tek söz etmedi daha... 

Doktor uzattı sedyeye, 

Nazikçe tuttu başını, 

Baş cansız sallandı; 

Her iki yöne... 

Düştü tekrar sedyeye... 

Doktor geç kalmışsınız, 

Kardeşim, çok geç... 

Başın sağolsun dedi; 

Yıktı kaşını... 

İnanmadı Nurettin, 

Baktı, baktı, baktı... 

Sabiha''m ne ettin...? 

Gözyaşın aktı, aktı... 

Kapandı ölüsüne, 

Düştü kolları ölünün; 

Sedyenin örtüsüne... 

Açıktı daha gözleri, 

Bakmıştı arkasına... 

Kalmıştı gözleri; 

Sabiha''nın arkasında... 

Bu kayıp tek can değil, 

Bu mısraları yazdıran, 

Heyecan değil; 

Milletimin gerçeğidir.. 

Bildiğim tek maksat; 

Milletimin layık olduğu yere, 

Erinde, gecinde ereceğidir... 

Bu vazife bizim üstümüze, 

Bu yolda karşımıza, 

Hangi çile çıkarsa; 

Bahtımıza...! 

Bu cinayette katil kim...? 

Sordum kendime, 

Belkide kendim... 

Sürüye kurt girerse; 

Mesulü bendim.. 

Eğer devlette ben varsam, 

İktidar ben olursam... 

Hedefi kadar, 

Büyüktür insan... 

Belki çok var, 

Hedefe daha... 

Sen yakın san... 

Bütün bunlar ar, 

Ne kadar suçsuz olsan; 

Hepsi ortaklar, 

Günahları kadar, 

Sevabımızda payları var... 

Yüz milyonluk Türkiye, 

Hedefine böyle varılamazdı... 

Hain, gafil ve kafir, 

Atardı terkiye; 

Niçin hesap soran, 

Bulunamazdı...? 

İktidar ben olacağım... 

İslamdan el alacağım... 

Eremezsem hedefe; 

Ben bu yolda öleceğim...!', '''Bir gazete haberinden...''  Ocağa iki kesek,  Odun-kömür yerine tezek;  Akşamleyin attı..  Sıcağına;  Kendi sıcağını kattı...  Çocuklarını t...', ARRAY['Türk Edebiyatı','Şiir','Erdal Sayıl']::text[], 8.5, '{"poet":"Erdal Sayıl","poet_slug":"erdal-sayil","theme":"Türk Şiiri","is_hero":false,"total_lines":259,"source_url":"https://www.antoloji.com/katil-kim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ten bozulur', 'ten-bozulur-zafer-zengin-etnika-mgz6a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '| Bakırın harcıdır/Küf

Ceryan yayar rengi |

Tenine sarıldıkça

Saklanır içinde

Kalaycıda biter

Sarılganlık

| Ve kalay düşer içeri

Ayrılık başlar |

Kasaba kasaba gezer

Ayrılır kaçamayanlar

Hasrete döker yüzünü bakır

Bilmez saatleri

Bekler

Kaşık çalan çocuklardır

Bakırı sevdiğine kavuşturan

| Zehirlenme vardır birde |

İstemez bakır

Kıyamaz çocuk gülüşlerine

Bulgur kokar açlık

Yiyin çocuklar yokluğu

Çal/a kaşık

Büyür bakırda yalnızlık

| Derdin biter mi 

 Kaplansan kubbelere

 Çocuklar seni yemese |

Bakıra çalar ömür

Küf kaplar elimizi

Ten bozulur

Susarız

Maşrapa olur avuçlarımız

26 Haziran 2004 '' Sır yanarken''', '| Bakırın harcıdır/Küf Ceryan yayar rengi | Tenine sarıldıkça Saklanır içinde Kalaycıda biter Sarılganlık | Ve kalay düşer içeri Ayrılık baş...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ten-bozulur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belaların en tatlısı', 'belalarin-en-tatlisi-yunus-ali-sinanoglu-7mb8q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sign out ettim completely

Çünkü seni çok sevdim

Denemek ister gibi beni

Sordu sign out edeyim mi

Tercihim no dan yana

Ama elim yes e gitti

Nedersin bitirmek gerek

Sevgi dilenmeyi

Sen anlarsın anlarsan bu şiiri sevgilim

Tabi değilsin yanlış hitap ettik affudersin

Ve akşam oldu yine

ellerim klavye

yazmak sana şiir 

Ah ne mutlu bir hikaye

Gerçek senin saçların 

Ve sınırsız internet

Seni seviyorum

Aşkımı bilmeye devam et

Sen ki en güzel siyahlar sahibi

Ve alabildiğine kırmızı

Kırmızı kırmızı ulan yakışıyor sana

Yalan diyen varsa burdayım

Chat ortamlarında

Ve aşkın en şaşalısını yaşıyorum

kendi başıma fırtına

Gel diyorum sana

Takılalım ortama

Ve yüzyıl aşk görsün

mecnun kalsın hovarda

seviyorum seni

Seviyorum ben anladım

Sende anla

Kuşlar börtü böcek

Seviyorum seni beni mutlu et

Do not regret

Love it çünkü herşeyim sen

Ve tüm ingilizcemsin hakkaten

Türkçemsin Yahya Kemal

Varlığımda varlık kanımda can

Sonsuza dek ismimi an

Biliyormusun adını ezbere biliyorum

Anlıyorum anlamını anlamı içimde saklı

Gel ey İzmirli ama gerçek bağdatlı

Seviyorum seni

Akşamlar senle tatlı

Rüyalar kadar güzel adlı.', 'Sign out ettim completely Çünkü seni çok sevdim Denemek ister gibi beni Sordu sign out edeyim mi Tercihim no dan yana Ama elim yes e gitti N...', ARRAY['Türk Edebiyatı','Şiir','Yunus Ali Sinanoğlu']::text[], 8.5, '{"poet":"Yunus Ali Sinanoğlu","poet_slug":"yunus-ali-sinanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/belalarin-en-tatlisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alüvyon', 'aluvyon-ahmet-aksoy-m0iko', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'farzumuhal dönmüşsün

ellerinde el yüreğinde yürek izi

bir sevdadan düşmüş

.......kırık döküksün

anlamışsın istediğinin olmadığını

bir ben değilim

.........güçsüz ve insan

duygu/lar sürükler toprağı

........asıl olan alüvyon', 'farzumuhal dönmüşsün ellerinde el yüreğinde yürek izi bir sevdadan düşmüş .......kırık döküksün anlamışsın istediğinin olmadığını bir ben de...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/aluvyon-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tam Aşkı...', 'tam-aski-ahmet-agdere-llt5l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tam aşkı yaşayacak yaştayım,

Ama ne bir yâr, ne bir güzel var.

Aşkla aşkı tadacak baştayım,

Ama bir düşeşlik olunmaz kâr.

Kurtuldum da sahte sevdalardan,

Şimdi yüzüme bakan kul olmaz.

Geçtim bir bir çürümüş dallardan,

Gözüm basacak bir dalla dolmaz.', 'Tam aşkı yaşayacak yaştayım, Ama ne bir yâr, ne bir güzel var. Aşkla aşkı tadacak baştayım, Ama bir düşeşlik olunmaz kâr. Kurtuldum da sahte...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tam-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay sadedir', 'ay-sadedir-zafer-zengin-etnika-kon9d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ay 

sadedir

Gece

O

yüzden

parlak

rengi

O

yüzden

sıcak

teni

Sadedir

gece

Ay

varsa

içinde

| İçini ısıtan gülümseme takılmış peşine

  Gece nerdeyse

  O düşer içine

  Ay ağlamaz kendine

  İçi yanar sevdiğine

  Budur merak edilen söylence

  Anlattım işte

  Dilim döndüğünce |

'' Bir dostun şiirinden çıkıldı yola..selamlar ola ''

30 Haziran 2004 '' Selam ışığın rengine ''', 'Ay  sadedir Gece O yüzden parlak rengi O yüzden sıcak teni Sadedir gece Ay varsa içinde | İçini ısıtan gülümseme takılmış peşine   Gece nerd...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ay-sadedir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esrar-ı Zari', 'esrar-i-zari-adnan-durmaz-9qvsc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'keder sağnaklarının bir damlası benim olsun

yıldızlarının en ıssızı düşsün yarama

gözünün yaşlarının bir zerresi benim olsun

şehrin bütün ışıkları sönsün-gece ağsın

senin yelin bana değsin

gecenin merdivenlerinde keder

yıldızsız karanlık ömrüm

gelirsen öyle gel

ateşten sözler yazdılar parçaladılar zamanın zırhını

fermanlar tutuştu dizelerinden

yüzlerinden ışık aldı şafaklar

geldiler bin yıllar öncesinden 

saltanatlar sarsıldı tahtlar diz geldi görkemlerine

ölüme pervasız baktılar-yalın yürek destur dediler zulme

sevdaya kelle koydular-ölümden libas giydiler

zaman ömür dilendi ayaklarından

sonsuz gece gibiydiler onlarsız görünmezdi yıldızlar

gecede ay kesildiler sevda ırmakları ışıdı gözlerinden

evleri dünya oldu-mülkleri sevda 

tav oldular boz toprağa

ateşlere kav oldular

kirkit kirkit umut dokur sözleri

yarınlara can oldular

binyıllar öteye bakar gözleri

vuruldular-asıldılar

ölüme baş eğmez inatlarıyla

zalime isyan oldular

ömrümüz dediğin bir karışlık yol

ne kaldı geriye ertelemekten

dün dünle gitti

yarına çok zaman var

sevdanın perdesini aralarken ellerin

zamanı ürkütmeli saçlarındaki rüzgar

sen ki gözyaşlarına binyılları kat

sevgilim yaşamak

bir deli tutkudur... bütün gövdenle dalarcasına suya

bütün yanlışları ihlal ederek

sevmek bir çılgın sudur

bütün duvarları yıkarak akan

keder sağnaklarından bir damla düş yüreğime

yıldız açar kirpiklerin gözlerinin bahçesinde

bir şarkı süzülür bakışlarından

yüzüne akan yaştan bir zerresi benim olsun

sokak lambaları sönsün-şehir karanlıkta kalsın

sarıl çıplak karanlığa 

tek yıldız görünmez onsuz

ıssız bir çöl geceye seraplar ara

sarıl karanlığa ki 

yıldızlar sunulur onun parmaklarında

bütün zamanlardan akan

ırmaklarla buluşmadan

ne gözler ışıtır ömrü 

ne sözler yalnızlığı dağıtır

yaşamak

isyandır tüm zulümlere

haksızlığa baş kaldırmak

binyılları yarıp gelen 

bir türküye türkü katmak

sevgilim sevdadır yaşamak

aşk buluştur bulutların en tüteniyle

düş buluştur gidenlerden kalan şarkıyla

bana bak

bana karış

bana çağla

beni al

savur rüzgarlarında

yaram derin bakışlarınla dağla

bir gökyüzü taşımak kolay mı yüreğinde

gel ey yar-

gözlerimde ağla

adnan durmaz,bilirsin aşk da serseri,art yay,ank,2003', 'keder sağnaklarının bir damlası benim olsun yıldızlarının en ıssızı düşsün yarama gözünün yaşlarının bir zerresi benim olsun şehrin bütün ış...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/esrar-i-zari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakmam Kimselere', 'birakmam-kimselere-adnan-durmaz-hho3c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'loş havada solunan sidik 

kurumuş kan kokuları içinde

acıdan gevilmiş bir dilin tadı

karanlık dehlizler

tekinsiz sessizlikte uzayan dehşet çığlıkları 

vahşet

dar karanlık hücreler

ve hep onları bekleyen zaman

eli coplu gölgeler

üçer beşer yedişer

üşüşürler

işkenceler

sancılar içinde... 

utancı-onuru-insanlığı

asarlar askılara

sürünürüm

tazyikli su

elektirik

bir yer var üşümek hissedilmez

acı duyulmaz bir yer 

orada büyür insan

tarihin ve zamanın üzerinde

orada küçülür

ellerimde kelepçe 

vampirler-yarasalar

taammüden suçlar

bilmediğim yasalar

seviyorum seni

dayayıp yüreği kedere

ey içimin yıkılmayan kalesi

bu sevgiyi bırakmam kimselere

hep akşamın yoluna serilen bulutlarla geldin

darmadağın oldu tutsaklık

denklerinde yalım

çıkının ateş

çığlığında yangın

yüreğin güneş

allı telli turna geldin

yeşil başlı ördek geldin

baharın dallarda açtığı imge

gül dalında sevda geldin

yasak kitaplar gibi 

gizlice iletilmiş selamlar gibi

sırı dökük aynalarda

ham traş başımda çoğalan aklar

isyanın dallandığı acı yüzümden

kırlaşmış sakallarıma akan

damla damla hüzün geldin

aykırı bir ceylan geldin

yaralanmış bir ömrün yakılmış dağlarına

ormanlarca esen

yellerin hışırtısı

sen kapı aralığından sızan ışık huzmesi

uzak hücredeki türkünün ayışığı 

duvarlara hapsedilmez 

kelepçeyle zaptedilmez düşlere

el ele yürüdük seninle 

bakışının gergefinde dokuduğun şarkıyla

yaramı sardın benim

ölümün kıyısında diş sıkıp direndim de

gözlerini şarap diye damıttım yüreğimde

ve sana sarılmak

bir olmak senle

yaşamak senden

kavuşmak sana

başlamak sende

bu gülüş

bu öpüş

bu düş benim

yüreğimi çiğnerler

bırakmam kimselere

								Mart 2002

adnan durmaz,bilirsin aşk da serseri,art yay,ank,2003', 'loş havada solunan sidik  kurumuş kan kokuları içinde acıdan gevilmiş bir dilin tadı karanlık dehlizler tekinsiz sessizlikte uzayan dehşet ç...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/birakmam-kimselere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bozkır Ağıdının Gözyaşında Islanması', 'bir-bozkir-agidinin-gozyasinda-islanmasi-adnan-durmaz-i75fz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ağlayışların

kırkikindi ağlayışların

yüzüme yonttuğu derin uçurum

ve ayrılıkların

yıldırım düşmeleri

içimde o yangın artığı kentler

ve keder

kum... 

boşalmış köylere vurdum zifiri ıssızlıkta

hayaletler dolaşan yıkık sokaklar

ve silmiş

erguvani süpürgesi ölümün

çocukları-sevdaları-düşleri

her vurgunda biraz daha ıssıza 

vurdum da yürek atımı

peşimde ihanetin

arsız gülüşleri... 

anladım aşk değilmiş benimkisi

aldanışın parçalanmış aynası

kentler tükürüp

kalabalık

taşladıktan sonra düşlerimi

gördüm

yok olan ormanlardan kalan

ardıç ağacıyım bozkırda

bazan

yurtsuz bir karınca

kanlı ayak izleri

hüznün yitik dizeleri 

göğün denizlerinde

yüzerken ay

ben orada

kırık bir hayatın anlamında

tektim

ve yol kıyılarında

hiçliğin girdabı bakışlarıyla

göz göze geldiğimde

ben o ölü köpektim... 

dokundum

sözcüklerden nasıl akar mağmalar

yaşadım

bir köpek

yüreğini nasıl dalar... 

ve anladım

düşlerin maskeleri düştükçe

aşk değilmiş benimkisi

yıldırımın gök fidana çarpması... 

aşk değil-akarsuyun yanılması... 

ve her seferinde

giyinip gece rengi harmanisini hüznün

dönmek

yarasını yalayan yabanıl bir hayvanca

dönmek... 

ıssızlığına... 

ve kaldırımlarda senfonik yağmur

animasyon hüzünler-makyajlı sözler

çalıntı bakışlar-alıntı gülüşler-fabrikasyon düşler

hastane kapılarında ölürken yoksul çocuklar

nasıl tanımlardı

yalnızlığın

yürek kanında yeşeren türküsünü

kuşkusuz aşk değildi benimkisi

bir bozkır ağıdının gözyaşında ıslanması

bir düşün sırtına hançerler saplanması... 

aşk oradaydı işte

bir uzun havanın bin yıllık coğrafyasında

kavalın içinde can olan nefes

kanarken ayışığında... 

ne ses kamışa

	ne kaval nefese sahip değildi aslında

yavri yavri

yel eser

türkü keser kekikler

bir aşk kokusu yayılır havaya... 

yürek

bir yıkık çoban çeşmesiyken dağ yamacında

paylaşılamayan güzellikler gecede sızlarken

onurun kızarmış bıçağıyla 

çıkardım yüreğimden

kür bir kurşun gibi

anladım 

anladım ki

düş değil benimkisi düşaldanması

aah aşk değil aşk değil

kelebeğin ateşlerde yanması... 

								Ağustos 2000

adnan durmaz,bilirsin aşk da serseri,art yay,ank,2003', 'ağlayışların kırkikindi ağlayışların yüzüme yonttuğu derin uçurum ve ayrılıkların yıldırım düşmeleri içimde o yangın artığı kentler ve keder...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":87,"source_url":"https://www.antoloji.com/bir-bozkir-agidinin-gozyasinda-islanmasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köşeler', 'koseler-zafer-ugur-n5583', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mavisi, yeşili ile renk renk köşeler,

Her çıkmazda, her sokakta son köşeler.

Pembesi, moru ile oyalı köşeler,

Göz nuru işli çevreleri köşeler.

Mahkûmun voltası adım adım köşeler,

Günler tespihte tek tek düşen köşeler.

Hülyâlar sınırsızdır, gözlerde köşeler,

Bir hakikat binbir hayâli köşeler.

Gözlerden akan damlalardaki köşeler,

Beşikten mezara bir ömrü köşeler.

Gönüller yol bulur, engel mi hiç köşeler? 

Ruha değil, maddeye settir köşeler.

Bir âh, gönülde saklı bin derdi köşeler,

Çile kaderse, sabır onu köşeler.

Söz yayda bir ok, sükut sadakta köşeler,

Bir lâtife birçok gerçeği köşeler.

Bir fotoğrafta dile gelir de köşeler,

Bazen bir hâtıra bir ömrü köşeler.

Kadın, erkek yaşlı yüzlerdeki köşeler,

O çizgiler tek tek yılları köşeler.

Adım adım, basamak basamak köşeler,

Her adımda yorgun umudu köşeler.

Kimi yalın dostlukları sarar köşeler,

En içten anları da riyâ köşeler.

Bir bizim dilimizde  mi kaldı köşeler? 

Doğruları bile eğriler köşeler...

(1983-2004)', 'Mavisi, yeşili ile renk renk köşeler, Her çıkmazda, her sokakta son köşeler. Pembesi, moru ile oyalı köşeler, Göz nuru işli çevreleri köşele...', ARRAY['Türk Edebiyatı','Şiir','Zafer Uğur']::text[], 8.5, '{"poet":"Zafer Uğur","poet_slug":"zafer-ugur","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/koseler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutma Yıldızlar Yere Düşmez', 'unutma-yildizlar-yere-dusmez-derin-oger-5oj06', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayır diyor kafamın içinde ki bir ses hayır

Uzaklardaki günışığına boş boş bakıyorum 

Korku içermişcesine Marmaranın sularından

Öylesine bir aralıktan dünyayı seyrediyorum

Hayır denizimden ayrılan bir damla olamazsın

Tüm hücrelerimle oradan oraya taşınıyorum 

Acıları tutup kavrayıp içime sindiremiyorum

Denizlere atamıyorum su,da boğamıyorum

Demir parmaklıklar yakıştırıyorum da dertlere

Zincirlere vurup  tutuklayamıyorum

Dur daha güneşi gözlerinde seyretmek var dur

Dur daha avuçlarımda sıcaklığını hissetmek var 

Daha söyleyemediğim bir dolu sevgi sözcüklerim var

Dudağımdaki söz,den tebessümden ayrılamazsın 

Sisler içinde kalan hatıralarım olamazsın dur.........', 'Hayır diyor kafamın içinde ki bir ses hayır Uzaklardaki günışığına boş boş bakıyorum  Korku içermişcesine Marmaranın sularından Öylesine bir...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/unutma-yildizlar-yere-dusmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sığın Yüreğime', 'sigin-yuregime-i-smet-barlioglu-pp5rd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sığın yüreğime darda kaldıysan,

Yüreğim tenine kalkan gibidir.

Buzlar arasında, karda kaldıysan

Isıtır yüreğim; volkan gibidir.

Yüzün andırıyor sedefi, gülü,

Yüreğin yüzünden daha görgülü,

Islanmış gözlerin yaşla örtülü,

Kaderim alnında türban gibidir.

Bir tek gün görmesem kalbim kavrulur,

Görünce ne halse dilim tutulur,

Uğrunda can versem yanlış mı olur? 

Yüreğim yolunda kurban gibidir.

Senden üstününü hiç bulamadım,

Ömrümce dünyayı boşa aradım,

Sana tutuldum da kurtulamadım,

Gönlüm başkasına yaban gibidir.

Gözlerin kıvılcım, bakışın diken,

Kanatır kalbimi merhem ararken,

Kahrın gülü bile kırıp atarken

Herşeye, herkese düşman gibidir.

(SAÇIMIZ BİRLİKTE BEMBEYAZ OLSUN isimli hece şiirlerinden > 25-26/100)', 'Sığın yüreğime darda kaldıysan, Yüreğim tenine kalkan gibidir. Buzlar arasında, karda kaldıysan Isıtır yüreğim; volkan gibidir. Yüzün andırı...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sigin-yuregime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnanmıyorsun', 'i-nanmiyorsun-i-smet-barlioglu-e5wu5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İşte bu gördüğün avuçlarımda

Çırpınan kalbimdir, aldanmıyorsun.

Adın yemin oldu dudaklarımda,

Islandı gözlerim, inanmıyorsun.

Dilimde adından ne türküler var,

Sendendir çektiğim o ızdıraplar,

Vicdan azabından sabaha kadar

Biliyorum asla yatamıyorsun.

Sana aşık olup seni severek,

O güzel kalbine tam güvenerek,

Ben payımı kattım canlar vererek,

Sen aşka payını katamıyorsun.

Aşığın fermanı en yüksek yerden,

Ben sana aşığım gördüğüm günden,

Bana içirdiğin o saf zehirden

Kendin bir tek yudum tadamıyorsun.

Kalbimin her gece beterdir hali,

İdam sehpasında mahkum misali,

Bana yüklediğin ağır vebali

Kaldırıp bir yana atamıyorsun.

(SAÇIMIZ BİRLİKTE BEMBEYAZ OLSUN isimli hece şiirlerinden > 27-28/100)', 'İşte bu gördüğün avuçlarımda Çırpınan kalbimdir, aldanmıyorsun. Adın yemin oldu dudaklarımda, Islandı gözlerim, inanmıyorsun. Dilimde adında...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/inanmiyorsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Medine', 'medine-ali-kilic-kakiz-33ndy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kubâ''nın Hurma bahçeleri değer,görülmeye.

Toplanmış yaşlısı genci kasideler söylemeye, 

Hahamlar, papazlar bile,gelmiş Resûlü görmeye 

Toprağı nur sacan, peygamber şehri Medine. 

''Vadî Ranûna '' ilk cumanın kılındığı yer, 

Şanlı peygamberin çağrısına kulak ver, 

''Topluluktan ve doğruluktan ayrılmayın'' der, 

Kur''an la feth edilen şehirler sultanı Medine. 

Resûlü ekrem oturdular Kûba''daki kuyu başına 

Cennetül- âla, müyesser oldu, bir kaç arkadaşına. 

Çağrıldılar huzuru Resûle, isim isim tek başına, 

Toprağı güzel kokan hicret evi  canım Medine. 

Resûlün gececeği yol üzerine oturmuş Selûl, 

Kin dolu bakışlarla, bakıyor melûl melûl, 

Kursağında kaldı, giyemedi taçını Ubeyy bin Selûl, 

Sırların gizli kalmadığı mukaddes şehir Medine. 

Cıban başı ve fitne ateşinin körükleyicisi. 

Hemen kinini kustu, hicret günlerinin arifesi, 

Resûllah''a kıskançlıkta meşhurdu, Âmir taifesi 

Görülmez ordularla korunan darûl karar Medine. 

Kâb '' Medine''den sorumlu, hem şair hemde kâdı. 

Mü''minlerin annelerine utanmadan şiirle saldırdı. 

Kıyamet saatine dek lânetlenecek, yerlere batsın adı. 

İlâhi tokatla hışmını bulanları temizliyen Medine. 

Deve yürüyüşüyle beşyüz sene gök ile yer arası. 

İns cinse gönderilen peygamberi zişanın uyarısı, 

Evrensel mesajla tamamlandı, asırların hayırlısı.

Allah''ın düşmanlarının susturulduğu yer Medine. 

Severlerdi Resûlü sıkâleyni, bitmez tükenmez hâzla. 

Verdikleri anda ki sevinç nail oldukları sevinçden fazla. 

Taat ve itaat timsali, meleklerin gaslettiği ey Hanzalâ! 

Gönüllerin tacı, cihanın incisi, emsalsiz diyar Medine. 

Kuba / Medine-i Münevvere/1401H.', 'Kubâ''nın Hurma bahçeleri değer,görülmeye. Toplanmış yaşlısı genci kasideler söylemeye,  Hahamlar, papazlar bile,gelmiş Resûlü görmeye  Topra...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç Kakiz']::text[], 8.5, '{"poet":"Ali Kılıç Kakiz","poet_slug":"ali-kilic-kakiz","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/medine-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitip Tükenmesin Tanrım Bu Gece', 'bitip-tukenmesin-tanrim-bu-gece-i-smet-barlioglu-cq1jy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'El açıp inleyip dizler çökerek

Yalvardım Tanrı ''ya candan, gizlice,

Diliyorum her gün yaşlar dökerek

Bitip tükenmesin Tanrı ''m bu gece.

Yarın alacaklar seni elimden,

Okla vuracaklar beni kalbimden,

Yarın bana beter olur ölümden,

Bitip tükenmesin Tanrı ''m bu gece.

İstemem kaybolsun senin izini,

Öpeceğim son kez iki gözünü,

Duyar mıyım bilmem son bir sözünü,

Bitip tükenmesin Tanrı ''m bu gece.

İstemem ayrılıp çekip gidesin,

Beni bırakasın ve terkedesin,

Zira; andolsun ki her gün bendesin,

Bitip tükenmesin Tanrı ''m bu gece.

Kim demiş ki; kalpler kana bulanmaz? 

Kim demiş ki; yanan bir daha yanmaz? 

Zorlu hasretlere gönlüm dayanmaz,

Bitip tükenmesin Tanrı ''m bu gece.

Elinle elimi sık deli gibi,

Bırak ağlayayım serseri gibi,

Mumun son nefesi, son feri gibi

Bitip tükenmesin Tanrı ''m bu gece.

Dur öpeyim bir kez, bin yıla bedel,

Almadan elimden seni bir yad el,

Nasılsa esecek yarın karayel,

Bitip tükenmesin Tanrı ''m bu gece.

Meğer mutluluğun bir sonu varmış,

İnsan mutluluğu bilmez, yaşarmış,

Elden gittiğinden sonra anlarmış,

Bitip tükenmesin Tanrı ''m bu gece.

Ben mahvolup yandım, bittim, tükendim,

Söz büyük lokmaymış, yeni öğrendim,

Tıldım yarınlardan, bıktım, iğrendim,

Bitip tükenmesin Tanrı ''m bu gece.

(SAÇIMIZ BİRLİKTE BEMBEYAZ OLSUN isimli hece şiirlerinden > 29-30/100)', 'El açıp inleyip dizler çökerek Yalvardım Tanrı ''ya candan, gizlice, Diliyorum her gün yaşlar dökerek Bitip tükenmesin Tanrı ''m bu gece. Yarı...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/bitip-tukenmesin-tanrim-bu-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim Öyle Kurban Ki', 'kalbim-oyle-kurban-ki-i-smet-barlioglu-ljkku', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir denizsin kumsalda,

Bir mehtapsın sandalda,

Parlıyorsun kumlarda

Tozu gibi altının.

Cefadan hiç bıkmazsın,

Yüzüme hiç bakmazsın,

Silsem dahi çıkmazsın

Yazısından alnımın.

Kalbim öyle kurban ki; 

Her gün ölür inan ki.

İçindesin sen sanki

Damarımda kanımın.

Kurbanınım her zaman,

Benim uğrunda yanan,

Sana feda olsun can; 

Diyetidir aşkımın.

(SAÇIMIZ BİRLİKTE BEMBEYAZ OLSUN isimli hece şiirlerinden > 32-33/100)', 'Bir denizsin kumsalda, Bir mehtapsın sandalda, Parlıyorsun kumlarda Tozu gibi altının. Cefadan hiç bıkmazsın, Yüzüme hiç bakmazsın, Silsem d...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kalbim-oyle-kurban-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Sesin*', 'sesin-kubilay-enginol-5z69p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hani

Denizler vururya kayalara

Ulaşırsın huzura

Dağcı,çıkarya,karlı dağlara

Çıpasını vurur karlara

Mimozalar sallanırya rüzgardan

Bir nefes gelir uğultulardan

Hani üflerler ya ney''i

Bulursun derinliği

Yağmur yağar ya hani

Dinginliğin içinde ses

Para sesi,su sesi,senin sesin

İşte senin bu nefes', 'Hani Denizler vururya kayalara Ulaşırsın huzura Dağcı,çıkarya,karlı dağlara Çıpasını vurur karlara Mimozalar sallanırya rüzgardan Bir nefes ...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sesin-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşamdan kalma', 'aksamdan-kalma-burhan-kucuk-oe602', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akşamdan kalma

Dalmış akşamdan kalma gözlerim

Kadehimde kalmış dudak izin

Odamda dolanıyor hala kokun

Kulağımda asılı silik sesin

Hayalde miyim,rüyada mıyım

Sabahın köründe seni özlerim

Anladım ki

Ben, bende yokum

Akşamdan  kalma bu sarhoşluğum

Burhan KÜÇÜK

Kdz.Ereğli-30.06.2004', 'Akşamdan kalma Dalmış akşamdan kalma gözlerim Kadehimde kalmış dudak izin Odamda dolanıyor hala kokun Kulağımda asılı silik sesin Hayalde mi...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aksamdan-kalma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyandığım Her Sabah', 'uyandigim-her-sabah-caner-kuru-lcs6d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bana acı veriyor,

Uyandığım her sabah.

Kalbim sanki eriyor,

Uyandığım her sabah.

Bir hasret ki sarıyor,

Yüreğimi yarıyor,

Gözüm seni arıyor,

Uyandığım her sabah.

Derdin beni alıyor,

Tüm aklımı çalıyor,

Kollarım boş kalıyor,

Uyandığım her sabah.

Bırak gönlüm delirsin,

Nasıl sevdim bilirsin,

Aklıma sen gelirsin,

Uyandığım her sabah.', 'Bana acı veriyor, Uyandığım her sabah. Kalbim sanki eriyor, Uyandığım her sabah. Bir hasret ki sarıyor, Yüreğimi yarıyor, Gözüm seni arıyor,...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/uyandigim-her-sabah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk ve Julia ve O', 'ask-ve-julia-ve-o-zafer-zengin-etnika-58lfp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşıksın julia

Aşıksın

Etine et istiyorsun

Telefon yapışmış kulağına

Sesine ses istiyorsun

Aşıksın julia

Ve biliyorsun

Aşk kaçıyor senden

Bunu sen istiyorsun

İçinde tüketiyorsun

Aslında onu istemiyorsun

Aşıksın julia

Düğmeni açıyorsun

Sıcaklığı bekliyorsun

Aramalısın...

Beyaz gömleğin kirlenmemiş

Buruşmamış ipleri

Tüketiyo seni işte

Aşkın gelmeyişi

Beklemelisin...

Senin gibi ağlardı

Fark ettin

Çarkına bağladın ellerini

Sesini duydun yandın

Kavuşmalısın...

Ömrünün sonuna kadar

İşle güçle

Zehredeceksin kendine

Oyalama gecede

Hızlı yürüme terinde

Yanmalısın

Yasak mı 

Kaçtığın bir gecede

Sığınmak ellerime

Kim için biriktirdin

Gece düş ekledin

Meraktasın

Not düşüyorsun aklına

Nasıl sığınmalısın bana

Acımasızım zannınca

Ay saklanıyor buluta

Sen kaçıyorsun yalnızca

Sığınmalısın

Bir kez görmelisin

Nefesi çekmelisin

Tiksinmelisin

Kıl kaçmalı boğazına

Sırtını dönmelisin yabancılığına

Gitmelisin

Işık kaçıyor gözbebeğine

Gölgen düşüyor suyun üstüne

Titriyorsun gizlice

Aklında ben

Aşıksın julia

Kedinin köpeğe yandığı gibi

Koparmalısın

Kendini uçur sarı ışığa

Bakma ele 

Bakma bula

Sakla sesini yalnızlığa

Uyma öğrendiğin akıllara

Onu saflıkta ara

Bir selamla yaklaş yanına

Öpmelisin

Umursamadan

Beni kaçır sığınağına

Sakla ellerini boynuna

Ve ağlama

Yani bir başlangıç daha

Sarılmalısın

Senindir koca ömür

Kat kat fazlanla

Usuldan git

Bir not bırak yanağa

Aşıksın julia

Aşığım sana

Seni anlat bana

Az kaldı kopmaya

Ellerimi bırakma

Bırakma

Su içinde öykülerdi

Havanın ağır serinliği

Sabahı erken getirdi

Dokunduysan boğazıma

Malubiyetimtir besbelli

Yıkılmış zindanım

Aşk seni de getirdi

Yakışıyor

Tanrının yüzüne gülüşü

Sen diye öpsem inanırım

| O / hiç bilemedim / Bilemedim / kimdi |

18 Haziran 2004 Zafer Zengin '' sana kavuşmak beyaz ''', 'Aşıksın julia Aşıksın Etine et istiyorsun Telefon yapışmış kulağına Sesine ses istiyorsun Aşıksın julia Ve biliyorsun Aşk kaçıyor senden Bun...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":92,"source_url":"https://www.antoloji.com/ask-ve-julia-ve-o-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elbet', 'elbet-cafer-tayyar-ozkan-tfuda', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Üzgün tavrınla bakma yüzüme,

Henüz bilmedin benden ihanet,

Umut verdin biçare gönlüme,

Sevdan kalbimde sonsuz ibadet.

Kızgın sözünle vurma kalbime,

Kopar gönülden sessiz kıyamet,

Murat serdin ne çare böğrüme,

Vuslat mahşerde olacak elbet.

09 Nisan 2004 Ankara', 'Üzgün tavrınla bakma yüzüme, Henüz bilmedin benden ihanet, Umut verdin biçare gönlüme, Sevdan kalbimde sonsuz ibadet. Kızgın sözünle vurma k...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/elbet-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor Geliyor İnanmak', 'zor-geliyor-i-nanmak-cemil-akkaya-ua0yy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yeminliğim artık sevmiyeceğim

kırık bir sandala takılmış dalga gibi

hırçın bir akıntı gibi çekip alacağım

sende kalmış yüreğimi

yalansız sanmıştım meğer değilmiş

seviyor zannetmiştim, meğer sevmemiş

nasıl kanarım inanmam bir türlü

nasıl katlarınım ah bilmem 

bilmem sana nasıl bağlanmışım

deli bir sarmaşık gibi

sarılmış sanki her bir yanım

yalanlarınla ayrılmak zor geliyor

birde nedeni olmayınca

ölüm olur be dayanılmıyor

dayanılmıyor, bir anda bitirmek

inanılmıyor, bir anda unutulmak

zor geliyor bu yüreğe', 'yeminliğim artık sevmiyeceğim kırık bir sandala takılmış dalga gibi hırçın bir akıntı gibi çekip alacağım sende kalmış yüreğimi yalansız san...', ARRAY['Türk Edebiyatı','Şiir','Cemil Akkaya']::text[], 8.5, '{"poet":"Cemil Akkaya","poet_slug":"cemil-akkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/zor-geliyor-inanmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalmasın Kalbimde', 'kalmasin-kalbimde-caner-kuru-eoe3u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kırıla kırıla ümit mi kaldı? 

Kalmasın kalbimde senden tek bir iz.

Derin bir pişmanlık ruhumu sardı

Kalmasın kalbimde senden tek bir iz.

Gönlümü yakıp da sömüren sensin.

Ömrümü zindana çeviren sensin

Beni bu canımdan bezdiren sensin

Kalmasın kalbimde senden tek bir iz.

Seninle yaşamak ölüme yakın,

Ne bıraktı bende vefasız aşkın

Bir daha yanıma yaklaşma sakın

Kalmasın kalbimde senden tek bir iz.', 'Kırıla kırıla ümit mi kaldı?  Kalmasın kalbimde senden tek bir iz. Derin bir pişmanlık ruhumu sardı Kalmasın kalbimde senden tek bir iz. Gön...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kalmasin-kalbimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanıma Gelme', 'yanima-gelme-caner-kuru-ldw40', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sorunların varsa, dileğin varsa,

Kendi kendine çöz, yanıma gelme.

Arzuların varsa, dileğin varsa,

Başkasından iste, yanıma gelme.

Avutma boş yere, sözlerin yalan,

Kimdi beni benden koparıp çalan? 

Yüzüne kaparım kapıyı inan,

İstesen de artık yanıma gelme.

Aşkından tutuştum, biliyor muydun? 

Ağlarken gözümü siliyor muydun? 

En muhtaç anımda geliyor muydun? 

Bundan sonra artık yanıma gelme.', 'Sorunların varsa, dileğin varsa, Kendi kendine çöz, yanıma gelme. Arzuların varsa, dileğin varsa, Başkasından iste, yanıma gelme. Avutma boş...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yanima-gelme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yırtar Atarım', 'yirtar-atarim-caner-kuru-v4f3d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çöl ettin gönlümü bir çağlayanken,

Hep gülen sen oldun ben ağlayanken,

Yine kaçıp gittin, bu defa sonken

Gönderme mektubu yırtar atarım.

Yaşattığın ne var, bir bak dünüme,

Saçtığın hep keder, hep dert önüme,

Daha fazla gelme sakın üstüme,

Verdiğin resmi de yırtar atarım.

Kapattım artık ben, bütün sayfayı,

Saymıyorum artık günleri, ayı,

Sanma tekrarlarım aynı hatayı

Gönderme mektubu yırtar atarım.', 'Çöl ettin gönlümü bir çağlayanken, Hep gülen sen oldun ben ağlayanken, Yine kaçıp gittin, bu defa sonken Gönderme mektubu yırtar atarım. Yaş...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yirtar-atarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçim Yanıyor', 'i-cim-yaniyor-caner-kuru-i350j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hanginiz söndürür böyle yangını? 

Evim barkım değil, içim yanıyor.

Aramayın sakın külü, dumanı,

Kor değil, köz değil, içim yanıyor.

Bir bakışta oldu, neler olduysa,

Gelip beni buldu, nasıl bulduysa,

Suçum ne aklımı baştan aldıysa,

Dağ değil, taş değil, içim yanıyor.

Bir sevda bu kadar öldürür mü ki? 

İnsanın başını döndürür mü ki? 

Su sıksanız bile söndürür mü ki? 

Evim barkım değil, içim yanıyor.', 'Hanginiz söndürür böyle yangını?  Evim barkım değil, içim yanıyor. Aramayın sakın külü, dumanı, Kor değil, köz değil, içim yanıyor. Bir bakı...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/icim-yaniyor-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimde bir kuş havalanır', 'i-cimde-bir-kus-havalanir-murat-tali-11i03', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'içimde bir kuş havalanır

kanat çırpar 

tüy düşer 

hapşırırım

konar elime

sıcaklığı 

yakar 

ürperirim

terlerim

su içer 

avuçlarımdan

tuzlu tuzlu

bir kuş havalanır

içimde

kanatlanmak isterim

ayağım 

prangalarda', 'içimde bir kuş havalanır kanat çırpar  tüy düşer  hapşırırım konar elime sıcaklığı  yakar  ürperirim terlerim su içer  avuçlarımdan tuzlu tu...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/icimde-bir-kus-havalanir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evlerimiz Vardı', 'evlerimiz-vardi-necmi-unsal-yidd3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Evlerimiz  vardı.

Onlar  dardı

Ama  huzur vardı.

Huzur soluklanırdı.

Geçim konuklanırdı.

Doğal hislerin uyandığı

Her şeyin güvene dayandığı

Evlerimiz vardı.

Bizi sıcacık  sarardı.

Yuva denirdi,

Ocak denirdi

Paylaşılmak istenirdi

Kanaatle yenirdi

Bir dilim ekmek.

Çizgilerde sekmek,

En büyük sevinçti çocuklarda,

Hanımeli kokan sokaklarda.

Sözler dostluk dokulu.

Döşekler lavanta kokulu.

“Allah rahatlık versin! ” yeterdi.

Misafire yoldaşlık ederdi.

Ak örtülü sedirlerde

Ay sohbetlere şahitti bedirlerde.

Seccadeler kanaviçe işli

Kapılar besmele girişli

Selam verişliydi.

Yorgunluktan muhabbete geçişliydi.

Evlerimiz vardı

Çiçek bahçesi önü ardı.

Edep, hizmet yuvası

Helal haram pusulası

Kul hakkı öğretisi

Doğruluk yetisi.

İlk mektepti bize.

Ninemizle diz dize

Masallarla olurduk.

Dinlerken düşlerde kaybolurduk.

Sevinçlerle coşulurdu.

Hep beraber koşulurdu

Bir bardak vermek için su

Zaman akardı sanki; bir içim su.

Herkesin yeri belliydi orada.

Yukarda,

Baş köşede büyükler.

Dede omzunda küçükler.

Emin kucaklarda.

Meleklere gülümser bebeler salıncaklarda.

Ayağa kalkılırdı yaşlıların geliş anlarında

Hele, ana babanın yanlarında

Hayasızca yatılmazdı.

Bir de hiç mi hiç, ayak ayak üstüne atılmazdı.

Evlerimiz vardı

Onlar dardı

Ama huzur vardı.

Onları kimler bizden kopardı? 

21 Nisan 2004 Çarşamba, Danimarka-Køge 18.46', 'Evlerimiz  vardı. Onlar  dardı Ama  huzur vardı. Huzur soluklanırdı. Geçim konuklanırdı. Doğal hislerin uyandığı Her şeyin güvene dayandığı ...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/evlerimiz-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Her Zaman Galip Gelir...', 'zaman-her-zaman-galip-gelir-hurrem-yalcin-jp468', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşanan her gün 

Geride kalır 

Geride bırakılan 

Her gün 

Gönülsüz 

Anılara bağışlanır... 

... 

Bahara sabırsız açan çiçek, 

Nazlı, narin pırpır eden kelebek, 

Gecenin mağrur, kibirli dolunayı, 

Avucun içinden anide kayan çoban yıldızı, 

Sımsıcacık yüreğiyle umuda doğan güneş, 

Dalını sevinçle terk eden elma, 

Neşeyle cıvıldayan ele-avuca sığmaz serçe, 

Bu gün varsa yarın anılarda... 

Bu günün güzelliği 

Bu güne yazılı kalır... 

Yeni gün pürtelaş geldiğinde 

Çaresiz 

Yaşananlar anılara bağışlanır... 

Ne yaparsan yap! 

Nafile... 

Geçemezsin akıp giden 

Akıp giderken de anıları beraberinde sürükleyen 

Zamanın önüne... 

Zamansa her zaman galip gelir 

Seni hep geride bırakır 

Bununla da yetinmez! 

Döndürüp geri hasretle baktırır... 

Yaşananların keyfi 

Anılarda kalır... 

Yaşanan tüm güzellikler 

Gönülsüz, 

Bir o kadar da çaresiz 

Anılara bağışlanır... 

29 Haziran 2004', 'Yaşanan her gün  Geride kalır  Geride bırakılan  Her gün  Gönülsüz  Anılara bağışlanır...  ...  Bahara sabırsız açan çiçek,  Nazlı, narin pı...', ARRAY['Türk Edebiyatı','Şiir','Hürrem Yalçın']::text[], 8.5, '{"poet":"Hürrem Yalçın","poet_slug":"hurrem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/zaman-her-zaman-galip-gelir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğini Sana Bıraktım...', 'yuregini-sana-biraktim-i-brahim-ethem-bingul-0o9qz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bekledim seni kardan elbisenle

Bir elinde güller, diğerinde kristal yüreğinle

Melekler kıskanırdı seni sevginle

Alamadım seni ama kaderini yazdım elime...

Neden,neden gelmedin bana

Hem severken,hem yaşarken yanımda

Her şey bizim içindi yarınlarda

Neden ordasın,neden benim olmayan kollarda...

O kardan elbisen artık benim

Kristal yüreğin düşerken tuttum,hakikatim

Nasıl kırılırım nasıl, sen benim gerçeğim

Elbisen toprak altında, yüreğini bıraktım sana

O da mezarımın baş ucunda aşkımla yan yana...

www.iebingul.com', 'Bekledim seni kardan elbisenle Bir elinde güller, diğerinde kristal yüreğinle Melekler kıskanırdı seni sevginle Alamadım seni ama kaderini y...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yuregini-sana-biraktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gördüğün Nokta', 'gordugun-nokta-huseyin-sigirtmac-hx8sr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gördüğün noktadan ayır gözünü

Sevgi bir bütündür sınırlar çizme.

Erit gönlündeki kuşku buzunu.

Yürekten dost isen dostluğu bozma.

Sevgi deryasında damlayı görme.

Her beşer onunla duyguyu yerme.

Sen Sultansın ama yerlere serme.

Fikrinle noksanı tamamla kızma.

Gücün yetiyorsa öldür yüreğim.

Ben bana düşmanım sensin uğrağım.

Arada bir hayal hayli ırağım.

Fazla sık dokuyup inceden süzme.

Ne kadar zariftir girdiğin yürek.

Ne kazmaya gelir ne tutar kürek.

Sevgiyi yenmekse ettiğin merak.

Hiçbir güç başarmaz boşuna gezme.

Sığırtmaç özünde gördüğün cevher.

Ne sana ar olur, ne de dert verir.

Koyma cendereye yorduğun yeter.

Yürek bu dinlemez sen şekil çizme.', 'Gördüğün noktadan ayır gözünü Sevgi bir bütündür sınırlar çizme. Erit gönlündeki kuşku buzunu. Yürekten dost isen dostluğu bozma. Sevgi dery...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gordugun-nokta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dila 1', 'dila-1-sair-heja-j3jq2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'AŞKIMI YARATTIM 

KUL OLAN BEN OLDUM

İnsan postuna girmiş hayvanlar 

Sarmış dört yanımı,

Gül gülücüklü kaktüsler,

Dökmüşler kızıl kanımı.

Sevmişim buna rağmen onları,

Dokunmuşum kaktüse,

Dokunmuşum insana.

Dokunmuşum da sonra fark etmişim; 

Gerçeğin yalan olduğunu.

Yalan dünyayı kıskandıracak 

Bir dünya yaratmışım kendime.

Lale kokan,

Aşk kokan bir dünya bu.

Tek yasası var bu dünyanın

Hakimiyet kayıtsız şartsız sevginindir

Hakkıdır aşka tapan yüreğimin mutluluk.

Aşkımı elimle çiziyorum; 

	Ona renkten renge giren bir çift göz,

	Notadan ezgiye dönüşen bir ses,

	Uzun, upuzun bir saç çiziyorum bazen 

		Bazen de kısa ve özgür

Aşkıma pamuk yumuşaklığında 

Bir çift küçük el bağışlıyorum.

	Gülümsediğinde taş kalbimi eriten

	Bir dudak 

	Küçük ve kırmızı

	Evet küçük ve kırmızı bir dudak çiziyorum 

Sonra kaşlarını çiziyorum özenerek,

Yay gibi kaşlar

Ve

  Ve bu yaydan kalbime fırlayan 

  Ok gibi kirpikler yaratıyorum ardından.

Narin bir gerdanı oluşuyor sevgilimin

Ve hayat bağışlayan dik göğüsleri.

İş bununla bitse iyi

Ona meleklerden çaldığım bir ruh armağan ediyorum

İçi dışından daha mükemmel oluyor böylece

Sonra 

Sonrası iyilik sağlık

Yaratıcısı olduğum sevgilime tapıyorum o kadar.

Bu dünya yalan değil 

Sahte değil

Sanal ama

Kurgu değil.

Suskunluk yok bu dünyada

Susarsan yok oluyor

Susarsan yok ediyor.

Susmamalı 

Sonsuz sohbet etmelisin

Susmamalı 

Sonsuz sevgi bulmalısın.

Lale kokuyor ekranım,

Lale yazıyor tuşlarım,

Lale çiziyor mausum,

Lale yaprağının hışırtısını çalıyor hoparlörüm,

Bu dünya benim dünyam

Lalemi ben çiziyorum tanrının kalemiyle

Dila’ yı yüreğimde yaratıyor Tanrısı oluyorum

Sonra kulu oluyorum 

“Harika yarattım “ deyip.

Lale öyle müthiş 

Öyle cezp edici ki 

Yalan dünyadaki kaktüsler,

Dikenlerini döküyor kıskançlıktan

O benim sanal aşkım

O ulaşamadığım

Belki O hiç ulaşamayacağım

Ama O düşleyeceğim

O gerçek aşkım

O Dilam', 'AŞKIMI YARATTIM  KUL OLAN BEN OLDUM İnsan postuna girmiş hayvanlar  Sarmış dört yanımı, Gül gülücüklü kaktüsler, Dökmüşler kızıl kanımı. Sev...', ARRAY['Türk Edebiyatı','Şiir','Şair Heja']::text[], 8.5, '{"poet":"Şair Heja","poet_slug":"sair-heja","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/dila-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dila 2', 'dila-2-sair-heja-kkovr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'DİLA

Son zamanlarda sanallaştım

Uyur gezer mi oldum ne

Bir ses var ki

Bir Dila

Bir Dila var ki

Bir Dila

Hiç çıkmıyor aklımdan

Yüzü bulanık tam göremiyorum

Melek olduğu belli

Sesi çok uzaktan ama 

Tatlı olduğu belli

Bir ses var ki

Bir Dila

Bir Dila var ki

Bir Dila

Bilgisayarın başına oturduğumda 

Ulaşılmazlığını düşünüyorum

Sonra dokunulmazlığını

Vazgeçiyorum ürküyorum sohbetten

Ya kendimi kaybedersem diyorum

Ya kapılırsam ona; 

Her düşümüz aynı

Her sözümüz 

Her arzumuz aynı

Aynılar cüretlendiriyor beni

Sonra yine ulaşılmazlığı geliyor aklıma

Susturuyor beni,

Susuyorum.

Birden anlıyorum ki

Korktuğum şey gelmiş başıma

Sevmişim sevmişim ki 

Tam sevmişim.

Sevmişim öyle bir sevmişim ki Dila’yı

Sussam boş konuşsam boş

Kızlar ölüyor ama

Onlara da kalbim boş.

Bir ses var ki

Bir Dila

Bir Dila var ki

Bir Dila

Kendimi ikna savaşına girdim 

Kalkansız kılıçsız.

Unut dedim kendime

Unut Kaf dağındaki Lale ‘yi

Aylarca direndim 

Ama kazanan ben olmadım.

Bir ses var ki

Bir Dila

Bir Dila var ki

Bir Dila', 'DİLA Son zamanlarda sanallaştım Uyur gezer mi oldum ne Bir ses var ki Bir Dila Bir Dila var ki Bir Dila Hiç çıkmıyor aklımdan Yüzü bulanık t...', ARRAY['Türk Edebiyatı','Şiir','Şair Heja']::text[], 8.5, '{"poet":"Şair Heja","poet_slug":"sair-heja","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/dila-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veremediğim Sınav', 'veremedigim-sinav-burak-killioglu-ntmud', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gönlündeki yara kanamadan

Beyni kanamaz insanın.

Aşık olmadan şiir mi yazılırmış hem? 

Aşk öyle bir ayna ki

aynanın ardını gösteren,

Şekilden öze bir yolculuk

insanı insana döndüren.

Şu an kanamakta beynim

türlü çeşitli düşünceyle hemhal,

bir sen var ki zihnimde

unut dedin mi unutulmaz derhal.

Derlerdi ya; hayat dediğin sınav

Anladım ki, hazırlıksız yakalanmışım.

Sen bir sınavdın bana

Sürekli sen de kalmışım.', 'Gönlündeki yara kanamadan Beyni kanamaz insanın. Aşık olmadan şiir mi yazılırmış hem?  Aşk öyle bir ayna ki aynanın ardını gösteren, Şekilde...', ARRAY['Türk Edebiyatı','Şiir','Burak Kıllıoğlu']::text[], 8.5, '{"poet":"Burak Kıllıoğlu","poet_slug":"burak-killioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/veremedigim-sinav-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Ben', 'sen-ve-ben-ferit-teksoy-0tngl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tanrı dünyayı bizim için yarattı 

iki kişilik

sen ve ben,biliyorum

kalan herşey tabloyu tamamlayan obje

ne yapsak boş

kaçınılmaz seni sevmek

hem biliyorsun sevgi bir damla su

var mayamızda

dinle içini ne diyor

göğsümü yumruklama boşuna

nasıl oluru yok bunun

kendinle savaş yapma

nasıl ki? .. 

her gece uyanmaya mecbur ise sabaha

ben gibi sen de mecbursun bana

hem baştan demedik mi

sen ve ben

yok başka

oku şiirleri

şarkıları dinle

bizden bahsetmeyen bir tane bul

çal kafama

gitsen dünyanın en uzak kıtasına

dalsan okyanusun en derin çukuruna

kaçamazsın benden

tersin akmaz su

ben gibi mecbursun bana

çık ormana

çiçeğe,ağaca,kurda-kuşa

sor börtü-böcek önüne kim çıkarsa

yemin ver,ölü öptür,gırtlağını sık hattâ

tüm sözlerimi yerim

bir tane yalan diyen olursa

ayağımı tekmeleme boşuna

ben gibi mecbursun bana

ben ne yapabilirim

dört kitapta yazılmışsan alnıma

peygamberler yazmışsa hadis kitaplarına

hırsın geçecekse eğer çık üzerime zıpla

kız,bağır,çağır,kır,dök,parçala

ama unutma ki! ..

ben gibi sen de mecbursun bana', 'Tanrı dünyayı bizim için yarattı  iki kişilik sen ve ben,biliyorum kalan herşey tabloyu tamamlayan obje ne yapsak boş kaçınılmaz seni sevmek...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/sen-ve-ben-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelişin', 'gelisin-ersoy-oktay-iis2h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayat akıyorken bir sel gibi iki yanımdan.

Seyre daldım alemi sensizlik salında; 

Varken yanımda gülüşen üçü beşi,

Gülmeyen dudaklarımda buldum seni; 

Uzun gecelerde düşünürken hayatı

Nerde bunun sonu, yada başlangıcı.

Anlamsız geliyorken bana her yaşanan.

Acının acısını öğretti gidişin.

''Azmin ve hırsına aşık oldum'' dedi biri

Kafi gelmediğini görüyorsun.

Yaşamak denilen lütufun sebebi

Gönül bahçesinde açılmış sevgilinin, sevgisi

Gitmek için toplamışken pılıyı, pırtıyı,

Vazgeçirdi, yatağımda kalan tek tel saçı

Ölmek için sözleşme yaparken ecelle

Yaşama bağladı beni gelişin.', 'Hayat akıyorken bir sel gibi iki yanımdan. Seyre daldım alemi sensizlik salında;  Varken yanımda gülüşen üçü beşi, Gülmeyen dudaklarımda bul...', ARRAY['Türk Edebiyatı','Şiir','Ersoy Oktay']::text[], 8.5, '{"poet":"Ersoy Oktay","poet_slug":"ersoy-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gelisin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** Pamuk Tohumu Kadar Soğuk...', 'pamuk-tohumu-kadar-soguk-abir-zaki-a0vhu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Parmak uçlarının arasında

özgürlüğün tohumunu taşıyordu

zahmetli bir emeğin ardından

saçmak için tarlaya, bekliyordu...

gömülmüştü,

tarlanın en sert

ve donmuş toprağına ekilerek

berrak, şeffaf yağmur damlalarını

ta iliklerine kadar emerek...

büyümek, her tarafa yayılmak için

kalktı yerinden usulca, dirilerek...

Oysa,

bırakılmıştı

öylesine

sessizce,

donmuş topraklara

.....TUTULAMAYAN

söylenemeyen VAAT''ler verilerek! 

Çeviren:   M. Çelik   3/6/2004

***************************************************************************************

As Cold As The Cotton Seed… 

carrying between fingertips 

the seed of the free 

through hard labor 

to bring it to yield 

planted in the frozen 

bitter ground of field 

absorbed with 

the soft raindrops so deep 

and slowly 

rising it up 

to grow all around 

yet, 

it laid there 

still and cold 

with promises, 

……….. untold! 

May 28, 2004', 'Parmak uçlarının arasında özgürlüğün tohumunu taşıyordu zahmetli bir emeğin ardından saçmak için tarlaya, bekliyordu... gömülmüştü, tarlanın...', ARRAY['Türk Edebiyatı','Şiir','Abir Zaki']::text[], 8.5, '{"poet":"Abir Zaki","poet_slug":"abir-zaki","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/pamuk-tohumu-kadar-soguk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar', 'sonbahar-mehmet-seyidhasanoglu-cxju1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen neden hüzünlüsün? 

O kadarda garip ve buruk,

Neden bu kadar soğuksun? 

Bir düşünsene, kıştan bile soğuksun! 

Affet ama sevilmiyorsun, eskiden de öyleydi,

Hışırdatan rüzgarının döktüğü yapraklara; 

Ağaçların hüznü karışır,

Rakibin yok ayırmakta sevenleri! çok kötüsün....

                         ...........SONBAHAR! ...........

                                    06.12.2001 / Perşembe

                                                  VAN', 'Sen neden hüzünlüsün?  O kadarda garip ve buruk, Neden bu kadar soğuksun?  Bir düşünsene, kıştan bile soğuksun!  Affet ama sevilmiyorsun, es...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Seyidhasanoğlu']::text[], 8.5, '{"poet":"Mehmet Seyidhasanoğlu","poet_slug":"mehmet-seyidhasanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sonbahar-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KeS.... AmA, ATMA', 'kes-ama-atma-mine-ozdemirtas-157xg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yapma! ! ! 

yenilmiş olamayız.

daha,

seslendirilmedi ki arya.

kapama kulaklarını

ara...

acaba...

hata,

hangi notada? 

yanıldıysam! 

kes beni hayatından

uzamış......

bir tırnak gibi

kes...

ama...... atma

sakla..

sakla ki,

ya,

 lirik bir öykünün

tadında,

ya,

bardağında eksilen

vişne şarabının

kıvamında

veya,

yıllara göğüs geren

teninin kıvrımında

bir

keşke.......

yakaladığında

yeniden

dokunabilesin bana.

sana; 

et tırnaktan ayrılınca,

hiç dinmeyen bir sızının

yerleşeceğini

parmak ucuna.

başka

nasıl anlatsam acaba? 

27/ 06/2004....  havalimanı', 'yapma! ! !  yenilmiş olamayız. daha, seslendirilmedi ki arya. kapama kulaklarını ara... acaba... hata, hangi notada?  yanıldıysam!  kes beni...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/kes-ama-atma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzeldi....', 'guzeldi-ender-altinisik-gx9w1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seninle yürümek istanbul''u,

bir çift güvercin gibi çırpınan ellerinin

yüreğime değmesi.

Ve dudaklarının seviyorumlu şarkılar söylemesi...

Güzeldi...

Yazmaktan bıktığım hikayemi sana anlatmak,

aynı gökyüzünün mavisinde kaybolmak.

Ve aynı aşk''ın sıcaklığında ısınmak.

Güzeldi...

Sana sarılmak rüzgara inat,

hatta sarıldığım için

vapurda sigara içememek bile.

Güzeldi...

Gözlerinin gözlerime değmesi

ve dudaklarının dudaklarımda titremesi.

Güzeldi...

Ve küçüğüm

gerçek aşk saat''lere hapsedilemezdi...

Oysa bu aşk külkedisi masalı gibi

saati gelince bitti...

Zaman bitti

Aşk bitti

Güzel olan herşey 

gecenin karanlığına kaybolup gitti...', 'Seninle yürümek istanbul''u, bir çift güvercin gibi çırpınan ellerinin yüreğime değmesi. Ve dudaklarının seviyorumlu şarkılar söylemesi... Gü...', ARRAY['Türk Edebiyatı','Şiir','Ender Altınışık']::text[], 8.5, '{"poet":"Ender Altınışık","poet_slug":"ender-altinisik","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/guzeldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatım', 'hayatim-halil-kesken-cltpe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anlatacak çok şeyim yok

Hayatım bir çocuğun türkçe defteri; 

Özenle yazılmış sayfalar

Sağa sola karalanmış şiirler,

Hoşlanılan kızların isimleri,

Birazda içinden ok geçen,

Kalp resimleri

Bu çocuğu çok seviyorum

Çünkü asla ortasından yaprak koparmıyor

Tek sorun defterdeki hataların

Silgiyle silinmemesi,

Bu yüzden üzeri karalanmış kelimeler var

Çoğu yerine bakarsanız 

Türkçe defteri demezsiniz

Olsa olsa karalama defteridir...

Ama kalplerin üzeri tertemiz

Hatta etrafı çiçeklerle süslenmiş

Defterin kıvrık uçlarında rengarenk ataçlar var

En önemlisini unuttum,

Defterin orta sayfasında kurumuş bir çiçek var

O ilk öpücüğün ödülü

O ilk aşkın kurutulabileceğinin

Ama unutulamayacağının kanıtı

O aşk varmıdır sorusunun yanıtı

Yalnız kaç tane boş sayfa kaldığı belli değil,

Zaten merak ta etmiyorum; 

İçine yazılanlar işe yarasın yeter.

Nasıl olsa her defter,

Birgün biter...', 'Anlatacak çok şeyim yok Hayatım bir çocuğun türkçe defteri;  Özenle yazılmış sayfalar Sağa sola karalanmış şiirler, Hoşlanılan kızların isim...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hayatim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O An', 'o-an-birhan-suner-aw1ny', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güneş suya yattığında başlar

Günün en güzel zamanı.

Su sanki bir samanyolu olur

parıldar içinde binlerce yıldız,

günışığında  şıkır şıkır.

Paha biçilemez o ana

ne de ondan geçilir.

Gönül ister ki 

ömür boyu sürsün o an,

Ne yerinden kımıldar insan

Ne de can  verir

Azrail gelse o an! .....

Birhan  Haz 04', 'Güneş suya yattığında başlar Günün en güzel zamanı. Su sanki bir samanyolu olur parıldar içinde binlerce yıldız, günışığında  şıkır şıkır. P...', ARRAY['Türk Edebiyatı','Şiir','Birhan Suner']::text[], 8.5, '{"poet":"Birhan Suner","poet_slug":"birhan-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/o-an-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme Kal Biraz Daha', 'gitme-kal-biraz-daha-sair-khan-9bcon', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaç mavi aşk yaşadık seninle, kaç deli gece... 

Düşünse, dolunay bile utanır,yıldızlar çıldırır, ağlar güller

Ben, seni işte öyle bir gecede sevdim, hesapsız. 

Ve düşlerim...Düşlerim sınırsızdı alabildiğine 

Duygularım sabırsız.Bir çocuk kadar günahsız. 

Sahi, sen de sevebildin mi  beni? Seni sevdiğim kadar, 

Bir dokunsana yüreğime,Bak, orada sen varsın. 

''Mutluluk nedir? '' diye sorsalar ''Sen'' derim alabildiğine,

 ''Yalnız sen.''Sesin, gözlerin, ellerin sonra, 

titreyen dudakların ve arzun çekingen 

Sen, benim her şeyimsin. 

Sensiz neye benzer bu ay, bu güneş? 

Sonra, kim aydınlatır benim gecemi,

 Günümü kim paylaşır? 

Kim sorar derdimi,Ben neye sevinirim, 

Kimle gülerim? Kal biraz daha... 

Beraber büyüttük sevinçlerimizi,

 Beraber öğrendik yaşama direnmeyi 

Sevmeyi beraber öğrendik.

Bak, güneşler doğdu üzerimize 

Ağlamak bu kadar kolay mıydı,

Ve güzel miydi gülmek kadar? 

Herkese seni anlatmak istiyorum 

Seni şiirlerimde anlatmak; 

Her dizede senin adının olduğu çığlık çığlık... 

İçimi ısıtan sen, tam şuramda; ılık ılık, 

sen olmalısın kıpır kıpır yüreğimde... 

Sevdan olmalı deli dolu

 Ve çılgınlığın, çılgınlığın olmalı. 

Ben seni sevmeyi seviyorum Ve seni özlemeyi. 

Bu bir itiraftır... 

Aşkın yoksa ben de yokum 

Yetim düşlerimin kimsesizliği kuşatır benliğimi 

Hüzünler yağar gecelerime.

Ben, bir garip ben olurum, Sığamam odalara, 

Taş duvarlar üzerime gelir. 

Ruhum durmaz bedenimde,hücrelerim yaşamaz. 

Kurumuş dallara döner yüreğim, susuz çöllere... 

Bu Gece bu hayat böyle bitemez, ben ölürüm, 

Ölürüm gitme, kal biraz daha... 

GİTME KAL BİRAZ DAHA...', 'Kaç mavi aşk yaşadık seninle, kaç deli gece...  Düşünse, dolunay bile utanır,yıldızlar çıldırır, ağlar güller Ben, seni işte öyle bir gecede...', ARRAY['Türk Edebiyatı','Şiir','Şair Khan']::text[], 8.5, '{"poet":"Şair Khan","poet_slug":"sair-khan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/gitme-kal-biraz-daha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bi Yazının Sesi-1', 'bi-yazinin-sesi-1-sirma-mersin-pt390', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kirli sözler, şifreli kelimeler

Derken tükendi

Anlamlı cümleler...

Sessizliğin sesi gücünü

Kalemle satır arasına,

Bırakmışken...

İmgelerden çalınmış

Dilsiz yazılar yazıldı

Soluksuz kalmış duyguların hesabına...

28.06.04', 'Kirli sözler, şifreli kelimeler Derken tükendi Anlamlı cümleler... Sessizliğin sesi gücünü Kalemle satır arasına, Bırakmışken... İmgelerden ...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bi-yazinin-sesi-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözün Aydın', 'gozun-aydin-i-smail-baharsen-y2ts3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir garip kuşun kırdın kanadını

uçamaz bir daha gözün aydın

bie dev ağacın kırdın dallarını

tutulmaz bir daha gözün aydın

bu zalim dünya kötülerin evi

bütün hainler bilirler kendini

gururla bastırıp ezdin sevgimi

tadılmaz bir daha gözün aydın

ne farkın kaldı topraktan taştan

bağlanmazdım bilseydim baştan

bahsetme artık sevdadan aşktan

anılmaz bir daha gözün aydın

içimde hayalden bir ceset kaldı

kalbim derinden bir darbe aldı

öyle bir kurşunki yaktı yaraladı

sarılmaz bir daha gözün aydın', 'bir garip kuşun kırdın kanadını uçamaz bir daha gözün aydın bie dev ağacın kırdın dallarını tutulmaz bir daha gözün aydın bu zalim dünya köt...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozun-aydin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Rüya', 'beyaz-ruya-i-smail-baharsen-9alih', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir hazan baharı uykusunda gördüm seni

bir şafak atımında tanıştım gözlerinle

seher yeli kokusundaydı gülen güzelliğin

ve güneş gibi parlıyordun yüreğinle

ağlayan bir gecede doğmuştun aniden

uykuyu unutan gözlerime öyle bir süzüldün

kumru kanadı hafifliğindeydi bedenin

gül yaprağında çiy tanesi gibi tazeydin

rüya rüya aradığım o dilberdin yokluğunda

saçları kömür karası o esmer sendin

yıldızlar ülkesinin en suskun yıldızı

büyü tanrıçası şatafatlı peri kızı

ve bu hayali aşkın en büyük armağanıydın

en büyük mutluluktun varlığına sevinemediğim

en beyaz rüyaydın gözlerimde belirdiğin

ve şimdi sen en kayıp sevdamsın

uyurken uymazken dilimdeki duamsın

ulaşılması en zor yerdeki bitecik aşkımsın

uzanıpta ellerimle tutamadığımsın.....', 'bir hazan baharı uykusunda gördüm seni bir şafak atımında tanıştım gözlerinle seher yeli kokusundaydı gülen güzelliğin ve güneş gibi parlıyo...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/beyaz-ruya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrıkotu düşünceler', 'ayrikotu-dusunceler-murat-tali-jl9o5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'elekten sardunyalar eledim

tel tel çiğdem çiçekleri döküldü

leğende kardelenler yıkadım

sıktığımda menekşeler damladı 

bardağıma kenger doldurdum

içtiğimde ısırganotu oldu

tabağımda papatyalar 

çatalımda ayrıkotları

kaşığımda  baldıran otu 

bıçağımda dermansız dertleriyle böğürtlenler

ve 

tereciye tere satmak için bohçamda

deste deste tere

derdimi döktüm ortalığa

binlerce çiçek açtı 

ya sevinçlerimi dökseydim 

ne olurdu acep', 'elekten sardunyalar eledim tel tel çiğdem çiçekleri döküldü leğende kardelenler yıkadım sıktığımda menekşeler damladı  bardağıma kenger dold...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ayrikotu-dusunceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kansersi Öğreti', 'kansersi-ogreti-fatih-aksut-x3k3y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yakama yapışır gönül ihtilalleri

içim salına salına geçer gözlerimden

mahzun haberler hal beyanımı 

verir daraltılmış

tanıdık gözler kan ter içindeyken 

ölümü ayartacak acılar bekler beni

umudun çıkmazıdır -dudaklarımda çürüyen- 

Adı konulmayan umutlarda kalmadı

yüzün/gözün kırılmasıyla 

yansıdı son cemalim

bir solgun cesedim artık 

-toprağın yazına-

son yaprağın hışırtısı kadar kırılgan

mezar kuyusu kadar ağır 

ney deliği kadar derin…', 'Yakama yapışır gönül ihtilalleri içim salına salına geçer gözlerimden mahzun haberler hal beyanımı  verir daraltılmış tanıdık gözler kan ter...', ARRAY['Türk Edebiyatı','Şiir','Fatih Aksüt']::text[], 8.5, '{"poet":"Fatih Aksüt","poet_slug":"fatih-aksut","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kansersi-ogreti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günah Dizeleri', 'gunah-dizeleri-fatih-aksut-y9jlf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Saatin bamteline damlatırken pişmanlığımı

Yıllara meydan oldum şarap kıyısında

Bin bir kaygı içerisinde kaç güneş batırdığımı

Rüzgarına sattım yapraklarımı dehşetin kanatlarında

	Yağız delikanlılar küstü bana

Minarenin endamından kahrolursa bulutlar

Sevecen ruhları asarım sedanın leylasına 

Kırılganlığımı bir melodiye bağışlarım

Denizin mavisindeki şehvetli kabartılar bir yana

	Benliğimi bırakırım caddelerin büyüsüne

Bırakırım bir güzelin eteğine yüreğimi

Makbule geçen gözlerin besmelesinde

Hayatın hangi safındayım

Yüreğim boy atacak rüyaların acziyetinde

El vermeyen masum gece yağmurlarım

	Temmuz geldi gitmeliyim…', 'Saatin bamteline damlatırken pişmanlığımı Yıllara meydan oldum şarap kıyısında Bin bir kaygı içerisinde kaç güneş batırdığımı Rüzgarına satt...', ARRAY['Türk Edebiyatı','Şiir','Fatih Aksüt']::text[], 8.5, '{"poet":"Fatih Aksüt","poet_slug":"fatih-aksut","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gunah-dizeleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cedelleşiyorum', 'cedellesiyorum-fatih-aksut-74hyr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yatağından usulca kalkan düşüncelerim

bir rüzgar eşliğinde serenat çalar ağlayarak

örselenmiş bir kalp tutar

gecenin şehvetinde aklı uyandırmadan

güneşin seyrinden sıyrılan gözlerim

yastığa koyduğundan başlar 

mesaisi kan yaşlarının

hıçkırıklar sarsıyor kalbin odacıklarını

gözyaşlarım yeşil bir kan olup yakıyor

Hiç bir sevdanın azizliğini sormamalı

sarışın gönlüm gözyaşlarımdan

Gülmek bağıra bağıra çekilirken hayatımdan

ben ağlamanın ıslaklığıyla yanıyorum

gece türkülerle sevişirken zifirisinde

ortalama aşkları gavur dağından atacak kadar 

bir yüzüğün ihanetini anlatıyor altın ipekler

tabur tabur gözyaşı asıyorum yıldızlı bulutlara

şimşekler söyleyeceklerimi kırıyor dilimde

dedemin yüzündeki yıllanmış izlere karışıyorum

bir meleğin kanadına zorunlu öpücükler konduruyorum

Teselli vermez şehrin karanlık sokakları

gecenin ışıklarına aydınlık yazmak güç

zaman aheste ilerliyor mezara

bir bahadır kafirliği çöküyor

gözlerimin cesedine

hayat terk ediyor parmak uçlarımı

bir sala düşüyor çatlamış dudaklardan.', 'Yatağından usulca kalkan düşüncelerim bir rüzgar eşliğinde serenat çalar ağlayarak örselenmiş bir kalp tutar gecenin şehvetinde aklı uyandır...', ARRAY['Türk Edebiyatı','Şiir','Fatih Aksüt']::text[], 8.5, '{"poet":"Fatih Aksüt","poet_slug":"fatih-aksut","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/cedellesiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Olmali ki Aşk', 'oyle-olmali-ki-ask-fatih-aksut-5r2fu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Soylu dertlere dalmalıyım

Güneşin gözleri yüreğime değmeli

Bir lahza aşka durmalı gönül

Sisleri dağılmalı hülyalar yolunun

Canan-ı arzularken candan geçmeli

“Ben” olmalı gülün açtığı yerde

Güle tav olmalı ve yanmalı

Gönül bir türküyle gelmeli dile

Yar attığım gülle yaralanmalı

Ferhatça alın teri akıtmalı yar için şehre

Kalbime hücum ederken aşk

Irmaklar gözlerimi hatırlamalı

Karadeniz gibi dalgalanmalı yüreğim

Aşkın zayiat vermeli aklıma

Kalmalı bir öpüşlük can.', 'Soylu dertlere dalmalıyım Güneşin gözleri yüreğime değmeli Bir lahza aşka durmalı gönül Sisleri dağılmalı hülyalar yolunun Canan-ı arzularke...', ARRAY['Türk Edebiyatı','Şiir','Fatih Aksüt']::text[], 8.5, '{"poet":"Fatih Aksüt","poet_slug":"fatih-aksut","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/oyle-olmali-ki-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Talak', 'talak-fatih-aksut-79j4b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tenine dokunan göz, dokunan dudak

geceyi susturan göğsündeki ölüm

İsviçre malı bir tebessümle katledilecek gül

ıslak, sisli ve çığlık yüklü

gözümü eğdiren zarifsizliğiyle

bir eylül bakışında vuslat.', 'Tenine dokunan göz, dokunan dudak geceyi susturan göğsündeki ölüm İsviçre malı bir tebessümle katledilecek gül ıslak, sisli ve çığlık yüklü ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Aksüt']::text[], 8.5, '{"poet":"Fatih Aksüt","poet_slug":"fatih-aksut","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/talak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece ve Ölüm Aşka Musallat Olunca', 'gece-ve-olum-aska-musallat-olunca-fatih-aksut-9ckmu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kaldırıyoruz usulünce geceyi

enaniyetleri tersliyoruz elimizin tersiyle

anlatamadıklarımızı seher vaktine saklıyoruz

şairler ve şiirler geçiriyoruz

gecenin o boylu poslu ellerinden

bir cafer, bir alişan geçiriyoruz

bütün kartları açıyoruz masaya

kanatılmış yanlarımızı türkülere saklıyoruz

gözlerimiz sevdaya nakarat oluyor

caferce ölüm kesin kılınırken

intiharvari cümleler seçiliyor dilinin derisinden.

gözlerimiz güçlü cümleler çekiyor

masadan dehşet yazılar geçiriyoruz 

bir dost geçiriyoruz evimizden 

ve gece sokaklardan seçiyor bizi

gece ve ölüm aşka musallat olunca

böylece yüzleşiyoruz yüzleşmemiz gerekenlerle

zehirli bir ağacın kökünü körüklüyoruz

birkaç nefes çekerken nevalemizden

güneşe bir mızrak yaklaşmayı beceriyoruz.

bir leylek takırtısı kadar şatafatlıda duruyoruz

akıl-sır erdiremediklerimizin üzerine düşüyor

ışığı da yakıyoruz yarı belinden

gerisin geri dualar bizi destekliyor', 'kaldırıyoruz usulünce geceyi enaniyetleri tersliyoruz elimizin tersiyle anlatamadıklarımızı seher vaktine saklıyoruz şairler ve şiirler geçi...', ARRAY['Türk Edebiyatı','Şiir','Fatih Aksüt']::text[], 8.5, '{"poet":"Fatih Aksüt","poet_slug":"fatih-aksut","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gece-ve-olum-aska-musallat-olunca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairler', 'sairler-ali-umran-sonmez-k7ng8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şairlerdir hep halkın önünde giden,

onlardır topluma yön veren.

Yılmaz savaşçılarıdır yazın dünyasının,

Az yaşar şairler nedense hep,

Çileli bir ömürdür onların.

Haksızlıklara tahammül etmezler,

Şiirleri isyan bayrağıdır umutların.

Yalakası olamaz asla çıkar guruplarının,

Çile,zulum,sürgün,işkence,ölüm onların.

Sevilmezler,gittikleri için üstüne doğruların.

Şairleri hep azabın kolları sarar,

Onlar,üzüldükçe ve öldükçe yaşar.

Başları dimdik ölür,adları kalır yadigar.', 'Şairlerdir hep halkın önünde giden, onlardır topluma yön veren. Yılmaz savaşçılarıdır yazın dünyasının, Az yaşar şairler nedense hep, Çileli...', ARRAY['Türk Edebiyatı','Şiir','Ali Ümran Sönmez']::text[], 8.5, '{"poet":"Ali Ümran Sönmez","poet_slug":"ali-umran-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sairler-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Şa ve Man...', 'sa-ve-man-naime-erlacin-rxu2v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'şiirin çıplaklığını giyinmek

çarpılmak 

bölünmek tene dokunuşunda

sıfırları atmak sonra

sadeleşmek hesaplaşma anında

kâinatın güçleri 

ve yazının paganları adına 

yemin olsun ki 

bitmez bu kavga 

gök tengri yaşadıkça 

teraziye vurmak ölümsüzlüğü

kam ananın korunağında 

güneşe yaslanmak 

suyu kutsamak

ateşe varmak ata ocağında

kadim bir hikâye bu

düşmüşse elden davul tokmak 

dönüşmüşse kopuza saza

ne gam! 

varsın çöl olsun dünya

gönül kurar obasını

doğar yeniden can otacısında

''gelir de geçer insanoğlu,

‘tükenmez...’ dedi bilge

aşkmış şiirin kudret od’u

ister Hakasya’da bir dağ başında

ister Anadolu’da Mevlâna’da

yemin olsun ki ''şa'' ve ''man'' adına** 

bitmez bu serüven

aşk bu kürede durdukça

(30 Haziran 2004)  

(*)    Gök Tengri: Atalarımızdan yadigâr; günümüzde çok az sayıda kalan Hakasya Türkleri arasında hayatiyetini sürdüren; özünde doğa ve aşkla bütünleşmeyi saklayan; ''Şamanizm'' olarak da bilinen bir tür inançlar manzumesi…

(**)     Şa(sha) : Kadınlık; Man: Erkeklik. 

 Şaman (=kam) : “Şa” ve “man”  bir arada iken, ruh ve beden arasında iletişim kuran kişiyi tarif etmenin ötesinde, aşkın birlikteliğini simgeler.', 'şiirin çıplaklığını giyinmek çarpılmak  bölünmek tene dokunuşunda sıfırları atmak sonra sadeleşmek hesaplaşma anında kâinatın güçleri  ve ya...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/sa-ve-man-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkına Ben', 'askina-ben-fatih-aksut-3qiwp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu ruhum

Bu bedenim

Aşkla adın andığım Allah’a gidenim…', 'Bu ruhum Bu bedenim Aşkla adın andığım Allah’a gidenim…...', ARRAY['Türk Edebiyatı','Şiir','Fatih Aksüt']::text[], 8.5, '{"poet":"Fatih Aksüt","poet_slug":"fatih-aksut","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/askina-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mecnuna Döndüm', 'mecnuna-dondum-yusuf-yalcinkaya-3kin7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Unuttum mutluluğu fani dünyada 

Aşkını kaybetmiş mecnuna döndüm

Hüsranlar odaklanmış yanık bağrıma 

Dertleri ağırlayan hancıya döndüm

Tek tek kabus oldu tüm ümitlerim 

Kurumak bilmiyor nemli gözlerim 

Sevgiye kapandı gönül defderim 

çaresi bulunmaz garibe döndüm 

Sönmüyor içimde hasret volkanı 

Bitkin bedenimin yoktur dermanı 

Tüketti ömrümü çile rüzgarı

Baharı olmayan kuşlara döndüm', 'Unuttum mutluluğu fani dünyada  Aşkını kaybetmiş mecnuna döndüm Hüsranlar odaklanmış yanık bağrıma  Dertleri ağırlayan hancıya döndüm Tek te...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Yalçınkaya']::text[], 8.5, '{"poet":"Yusuf Yalçınkaya","poet_slug":"yusuf-yalcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mecnuna-dondum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulmuş...', 'unutulmus-baris-pinar-tumer-dpoli', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kurutulmuş güllerin

halindeyim...

Onların kokusu içinde

bir yerdeyim....

Çıkmaz sokakların

gerçekten çıkılamadığının

anlaşıldığı halde...

Unutulmuş bir sürü eşyanın

sessiz anıları geçitinde...

Kurutulmuş güllerin 

siyah bakışları önündeyim...

Kısacası artık

Unutulmuş sözcükler içreyim...

Bir de unutulan ne varsa...', 'Kurutulmuş güllerin halindeyim... Onların kokusu içinde bir yerdeyim.... Çıkmaz sokakların gerçekten çıkılamadığının anlaşıldığı halde... Un...', ARRAY['Türk Edebiyatı','Şiir','Barış Pınar Tümer']::text[], 8.5, '{"poet":"Barış Pınar Tümer","poet_slug":"baris-pinar-tumer","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/unutulmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik Sensizlik Üstüne', 'sensizlik-sensizlik-ustune-i-smail-baharsen-qwi88', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dün yine sensiz geçen bir İzmir günüydü

dalga sesleriyle avundum çaresiz

martıların gürültüsü,İzmir''in sisi sönüktü

Alsancak''tan baktım şöyle bir Bornova''ya

Narlıdere''nin eteklerinden süzülen yine sensizlikti

palmiyelerin gölgesinde düşündüm seni

bir balık ekmek tadındaydı gözyaşım

İzmir''in saat kulesi canıma kıyacaktı belli

hep sensizlik üstüne sensizlik ekliyordu

Mehmet Abi''nin Torbalı''sını soruyorum geçenlere

en azından bir tanıdığım vardı buralarda

çok yolları geçtim şimdiyedek inanmazsın 

kah yarı uyanık kah yarı uykularla

İzmir hey koca şehir hey koca şehir...

bağırıyordum gelip geçen yük gemilerine

İzmir''in balıkçı dolu taş sahillerine

motoru eskimiş küçük teknelere

yığılıp kalıyor sensizlik böyle sensizlik üstüne

kasdediyor çıldırmış yüreğime', 'dün yine sensiz geçen bir İzmir günüydü dalga sesleriyle avundum çaresiz martıların gürültüsü,İzmir''in sisi sönüktü Alsancak''tan baktım şöyl...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sensizlik-sensizlik-ustune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kal Deseydim', 'kal-deseydim-i-smail-baharsen-xjwu9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'dünyaları bırakıp gelsen ardında

kalırmıydın benimle kal deseydim

güneşim ol diye dilek tutsam

doğarmıydın bana doğ deseydim

görmedim senden bir kötülük 

yakışmıyor bana boynu büküklük

sevgi isteseydim bir ömürlük

severmiydin beni sev deseydim 

bir dert varki yüreğimde

çare ne avuçta ne elde

yaram var gönül yerimde

sararmıydın elinle sar deseydim

bir varım yoktur dünyada

gözüm ne para pul nede malda

gönlüm garip şu ıssız handa

bir seveni gerek insan olana

olurmuydun yarim ol deseydim', 'dünyaları bırakıp gelsen ardında kalırmıydın benimle kal deseydim güneşim ol diye dilek tutsam doğarmıydın bana doğ deseydim görmedim senden...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kal-deseydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığımın Gecesi', 'yalnizligimin-gecesi-adnan-yigit-5t8dc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sensiz bu ilk gecem 

yalnızlıgımın gecesi 

her şeyi bu gece ye 

bu karanlık gece ye 

adıyorum 

sen gidiyorsun 

ben sana aglıyorum 

gece gibi karanlık gözlerini arıyorum 

ben bu gece 

yalnızlıgımın geesinde 

seni anıyorum', 'sensiz bu ilk gecem  yalnızlıgımın gecesi  her şeyi bu gece ye  bu karanlık gece ye  adıyorum  sen gidiyorsun  ben sana aglıyorum  gece gibi...', ARRAY['Türk Edebiyatı','Şiir','Adnan Yigit']::text[], 8.5, '{"poet":"Adnan Yigit","poet_slug":"adnan-yigit","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yalnizligimin-gecesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yavrum', 'yavrum-onder-doventas-5i85j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Doğdun bir güneş gibi, ışık ışık.

Birlikte getirdiğine olduk aşık! 

Yaradan''ın sunduğu şerbetinden içtik,

İçtikçe haz içinde kendimizden geçtik

Aydınlığın sildi, bitti içimizdeki loşluk! 

Tutulan bir alevdin, zevkle yandık kavrulduk! 

Sen çiçektin bizlerde bal toplayan arılar,

Doyumsuz balını tadan, yavrum nasıl doyar? 

Dolaştık etrafında durmadan vız vız,

Kanatlar yetmedi, el kullandık aldık hız.

Sen verdin biz topladık, yedik yedik bitmedi,

Misler kokan balımız, içtik içtik yetmedi.

Dolaştık her yanında, bulduk yeni bir pınar,

Gözlerinde gezindik gördük yeni bir çınar.

Yaprakların nurdandı, gövdesi hilal,

Üstünde uçuyordu kuşlar, al al.

Uyuyan bir melektin, uyanınca can! 

Gözlerini özledik, uyan yavrum uyan.', 'Doğdun bir güneş gibi, ışık ışık. Birlikte getirdiğine olduk aşık!  Yaradan''ın sunduğu şerbetinden içtik, İçtikçe haz içinde kendimizden geç...', ARRAY['Türk Edebiyatı','Şiir','Önder Döventaş']::text[], 8.5, '{"poet":"Önder Döventaş","poet_slug":"onder-doventas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yavrum-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı Yazma...', 'sari-yazma-yusuf-ziya-leblebici-xy3gr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Oyaları güneş olur

Sarı yazma bağlayınca

Gözyaşları boncuk olur

Ağlamaya başlayınca

Al yanaklım gül dudaklım

Ateş değmiş al çıralım

Çukur çukur gamzelerin

Saçları sarı yazmalım

Güldüğünde çiçek açar

Gözlerinde sevda saçar

Uzun uzun kipriklerin

Yüreğimde yara açar

Sarı yazma bağlayınca

İpek kemer kuşanınca

Nağme döker o dillerin

İçinden ah boşalınca', 'Oyaları güneş olur Sarı yazma bağlayınca Gözyaşları boncuk olur Ağlamaya başlayınca Al yanaklım gül dudaklım Ateş değmiş al çıralım Çukur çu...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sari-yazma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demir Kapı...', 'demir-kapi-yusuf-ziya-leblebici-ywwup', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Demir kapı vurulmuş 

halkların mutluluğuna,

Maden ocağından 

sızan gaz kadar mutluluk

henüz yerine oturmamışken

Yaşamın faizi konmuş babalarca

her şey onların olmuşken...

Yolun son noktasında,

Umutlara vurmuşlar demir kapıyı.

Ne sağından, ne solundan geçmek var

çare yok, demir kapıyı yıkmaktan başka.

Anahtarı kör kuyuda

kör kuyu çakalların midesinde

elini soksan, yarısı kalır ağızlarında

bu kör kuyunun karanlığında.

Tek çare, demirin karşısında

demirden insan olmak

demir kapıları bir bir yıkarak

umutların önünü açmak! ..', 'Demir kapı vurulmuş  halkların mutluluğuna, Maden ocağından  sızan gaz kadar mutluluk henüz yerine oturmamışken Yaşamın faizi konmuş babalar...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/demir-kapi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...İki kere ölmek...', 'i-ki-kere-olmek-erdal-asik-ps9vm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beni bırakıp gitmiştin

böyle bir gecede,

kan kırmızı olmuş gökyüzü

ay ağlamaklı kızarmış gözleriyle

düşüyor yıldızlar, gözyaşı olmuş 

yakamozlar denizin üstünde,

geçmişim içimde patlamış volkan

lav dolaşıyor damarlarımda

vücudum acılar içinde

dayanamıyorum yaşarken,

bende ölüyorum seninle

her yıldönümünde! ..', 'Beni bırakıp gitmiştin böyle bir gecede, kan kırmızı olmuş gökyüzü ay ağlamaklı kızarmış gözleriyle düşüyor yıldızlar, gözyaşı olmuş  yakamo...', ARRAY['Türk Edebiyatı','Şiir','Erdal Aşık']::text[], 8.5, '{"poet":"Erdal Aşık","poet_slug":"erdal-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/iki-kere-olmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıyamet Günü', 'kiyamet-gunu-mehmet-caner-sumengen-mqkfp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerimde gözlerin

Hep aklımda sözlerin

Özlerim yar özlerim

Günler geçse de beklerim.

Yollarını gözlerim

Umut dolu sözlerim

Özlerim yar özlerim

Aylar geçse de beklerim.

Aşkından deli divaneyim

Yandım yıkıldım viraneyim

Kara sevdalı bir haldeyim

Ömrüm boyunca beklerim.

Giderken dönmem dedin ama

Kalpler ayrılmaz inan bana

Kıyamet günü bile olsa

Son nefesimde beklerim.', 'Gözlerimde gözlerin Hep aklımda sözlerin Özlerim yar özlerim Günler geçse de beklerim. Yollarını gözlerim Umut dolu sözlerim Özlerim yar özl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Caner Sümengen']::text[], 8.5, '{"poet":"Mehmet Caner Sümengen","poet_slug":"mehmet-caner-sumengen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kiyamet-gunu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Perişan', 'perisan-huseyin-sigirtmac-ejo7k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hep doluya bakıp boşu düşündüm.

Üzüntüyle akan yaşı düşündüm.

Hep baharı değil kışı düşündüm.

Yordum hayalimi düşüm perişan.

Karanlığa ışık verse gözlerim.

Kışlarıma güller sunsa yazlarım.

Hayalimde gülen oğlan kızlarım.

Sürüldü savaşa yaşam perişan.

Her gizeme pençe vursa ilmimiz.

Sevgiyi haykırsa şarkı türkümüz.

Aynı gemideyiz yaş ve kurumuz.

Ayaklar yan basar başım perişan.

Ben değil biz ile yola çıkmalı.

Yer dibine değil arşa çıkmalı.

Sığırtmaç savaşa karşı çıkmalı.

Yoksa Mehmet yanar,Paşam perişan.', 'Hep doluya bakıp boşu düşündüm. Üzüntüyle akan yaşı düşündüm. Hep baharı değil kışı düşündüm. Yordum hayalimi düşüm perişan. Karanlığa ışık ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/perisan-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Papatyama', 'papatyama-sedef-unal-gxvqm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Türkü tadında bir sevgi  sana duyduğum

Ürkek olsa da yaklaşımlarım

Lalelerin kokusu karıştı güllerinkine

Ansızın gelişinle hayatıma

Yüreğimden balonlar uçuşuyor, çocuklaşıyorum

Sıcacıktı bakışların ben görmesem de

Usumda kalan bir tablo gibi

Sevinçleri sakladım avuçlarıma

Tarifsiz masal tadında bir dilek sana sunduğum

Ayrılık olmasın dostluğumuzda

Mutluluk resimleri çizilsin aramıza...

29/06/2004

Sevgili  papatyam Tülay Sustama armağanım.', 'Türkü tadında bir sevgi  sana duyduğum Ürkek olsa da yaklaşımlarım Lalelerin kokusu karıştı güllerinkine Ansızın gelişinle hayatıma Yüreğimd...', ARRAY['Türk Edebiyatı','Şiir','Sedef Ünal']::text[], 8.5, '{"poet":"Sedef Ünal","poet_slug":"sedef-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/papatyama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çatal Kazık', 'catal-kazik-i-brahim-bayraktar-e9dbp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hep aynı terane çalar derinden,

Dinleyenler aynı, çalanlar aynı,

Zılgıtı yedikçe oynar yerinden,

Ekmeği yarıya bölenler aynı.

Memura verilen öğünlük azık,

İşçiye atılan toplu bir kazık,

Zevatın ağzından çıkmıyor yazık,

Emeğin hakkından gelenler aynı.

Yabancı destekli ekmeğin tuzu,

Deyyusun elinde işçinin kozu,

“Ne Şam’ın şekeri, arabın yüzü”,

Vatan, millet deyip ölenler aynı.

Asgari ücret mi, çok büyük para?

Bozdur, bozdur harca, düşmezsin dara,

İktidar denilen onulmaz yara,

Bizi bizden etti kalanlar aynı.

25.06.2004/Ankara', 'Hep aynı terane çalar derinden, Dinleyenler aynı, çalanlar aynı, Zılgıtı yedikçe oynar yerinden, Ekmeği yarıya bölenler aynı. Memura verilen...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/catal-kazik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni, sensizlikte aradım...', 'seni-sensizlikte-aradim-arzu-dincer-mkv0q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dipsiz kuyularda aradım seni,

Seni sensizliğin ipinde asılı..

Kalakaldım anılarla baş başa..

Bi çare gönül, fermansız! 

Baş koydu, seni sensizlikte aramalara....

Beni sensiz bıraktığın zamanlarda...', 'Dipsiz kuyularda aradım seni, Seni sensizliğin ipinde asılı.. Kalakaldım anılarla baş başa.. Bi çare gönül, fermansız!  Baş koydu, seni sens...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/seni-sensizlikte-aradim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayâlim Yıktılar', 'hay-lim-yiktilar-mehmet-fatin-baki-10cfv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akrabam, nefsim ve şeytan tende cânım sıktılar,

Tâ ezelden hattedilmiş doğru yoldan çıktılar.

Bahtımın bir lûtfudur bu. Hasma hâcet kalmadı

Hep berâber birleşip toplam hayâlim yıktılar.

Hattedilmiş = yazılmış

Fâilatün    fâilatün    fâilatün    fâilün 

/  .   /   /   /  .   /   /   /  .   /   /   /  .   /', 'Akrabam, nefsim ve şeytan tende cânım sıktılar, Tâ ezelden hattedilmiş doğru yoldan çıktılar. Bahtımın bir lûtfudur bu. Hasma hâcet kalmadı ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hayalim-yiktilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanalım', 'yanalim-safak-ozdemir-xcosq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen, düşlerimin içinden çıkıp geldin ansızın.

Yarı hayal, yarı gerçek.

Hiç sormadın adını.

Tutmadım ellerinden.

Öpmedim dudaklarından, ayak bileklerinden.

Ama yinede sevdim seni.

Tutkuyla sevdim,

Asice sevdim.

Olmadı! 

Uzun kirpiklerini,

Küçük ellerini,

Yeşil gözlerini sevdim senin.

Olmadı! 

Hava,lavanta kırmızı yine.

Rüzgar kırmızı,

Sevda kırmızı.

Gel bebeğim, otur şöyle karşıma.

Bırak aksın duyguların bakışlarına.

Tutuşsun kirpiklerimiz,

Yanalım! 

Şimdi aşkı damıtmanın zamanıdır dudaklarda.

Bırak yanalım, gecenin huysuz maviliğinde.

Yanalım, Nevruz ateşleri gibi dağlarda.

İki küçük can, bir kıvılcım,

Yanalım!', 'Sen, düşlerimin içinden çıkıp geldin ansızın. Yarı hayal, yarı gerçek. Hiç sormadın adını. Tutmadım ellerinden. Öpmedim dudaklarından, ayak ...', ARRAY['Türk Edebiyatı','Şiir','Şafak Özdemir']::text[], 8.5, '{"poet":"Şafak Özdemir","poet_slug":"safak-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yanalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sağ Çıkmadı', 'sag-cikmadi-mehmet-fatin-baki-5i8ux', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '‘Kısmetimdir dehre geldim, zorla gitmem ben’ deme

Âşikardır,  kimse  dünyâ  âleminden  bıkmadı.

Fayda vermez çok direnmek sâbir ol sen, gam yeme

Kimse dünyâ hanesinden sağ ve sâlim çıkmadı.

Fâilâtün    fâilâtün     fâilâtün    fâilün 

/ .   /   /    / .   /   /   / .   /   /    / .   /

Hece: 4 + 4 + 4 + 3', '‘Kısmetimdir dehre geldim, zorla gitmem ben’ deme Âşikardır,  kimse  dünyâ  âleminden  bıkmadı. Fayda vermez çok direnmek sâbir ol sen, gam ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sag-cikmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmece', 'bilmece-mehmet-fatin-baki-esf7d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilin bakım bu nedir

Manzum bir bilmecedir.

Ya beni takip eder 

Ya benden evvel gider

Ya önüme takılır

Ya da yere çakılır.

Yok kendisinde gurur

Dur deyince de durur.

Hep güneşte görünür

Gece ‘zıll’a bürünür.

Koştukça ben o koşar

‘Saye’mde o da yaşar.

Hece:   7

İpucu:

4-14    5-3     6-13    10-1    12-4', 'Bilin bakım bu nedir Manzum bir bilmecedir. Ya beni takip eder  Ya benden evvel gider Ya önüme takılır Ya da yere çakılır. Yok kendisinde gu...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bilmece-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tan Yeli', 'tan-yeli-mehmet-fatin-baki-kpt1j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hadi ayrıl Vero’dan tanyeli-rüzgar

Çabucak git te buluş sevgili yârla.

Vero Beech’ten yolun İstanbula çok var

Gelecek vuslatı sen yârla ayarla.

Vero Beech = Florida’da bir sahil şehri

Feilâtün     feilâtün     feilâtün  

.  .   /   /   .  .   /   /    .  .   /   /', 'Hadi ayrıl Vero’dan tanyeli-rüzgar Çabucak git te buluş sevgili yârla. Vero Beech’ten yolun İstanbula çok var Gelecek vuslatı sen yârla ayar...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/tan-yeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalb Yarasında', 'kalb-yarasinda-mehmet-fatin-baki-5i9p6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aya baksam görürüm vechini saçlar arasında.

Sana baksam görürüm kevkebi bir şeb karasında.

Kamerin şavkını ölçsem gece etraf kararınca

Yüzünün  nûru gelir fazlaca revnak darasında.

Seni andıkça  uzaktan yüreğim parçalanır hep

Kanayan cerhayı gel gör Fatin’in kalb yarasında.

Vech = yüz

Kevkeb = yıldız

Şeb = gece 

Kamerin  şavkı = ayın ışığı

Revnak darası = parlaklık terazisi

Cerha = yara, yarık

Feilâtün    feilâtün     feilâtün   feilâtün 

.  .   /   /  .  .   /   /  .  .   /   /   .  .   /   /', 'Aya baksam görürüm vechini saçlar arasında. Sana baksam görürüm kevkebi bir şeb karasında. Kamerin şavkını ölçsem gece etraf kararınca Yüzün...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kalb-yarasinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Götür', 'gotur-mehmet-fatin-baki-5lz65', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey uçan nemli bulut, gönlümü cânâna götür.

Sulu gözlerde birikmiş yaşı al, câna götür.

İyileşmez yaralar hastasıyım bir süredir

Çaresiz derdimi yüklen de bir ummâna götür.

Senelerdir düşülen zilleti bir ben bilirim

Kötü ahbârı bizim köydeki ihvâna götür.

Eziyet çektiğimiz cevr-ü cefâ arttı bugün

Hepisin benden alıp gökyüzü asmâna götür.

Gülecek, zevk alacak kalmadı bir şey. Henüz akl

Beni terk etmeden al rûhumu Mevlâna götür.

Zillet = aşağılık, alçaklık 

Ahbâr= haberler

İhvân = kardeşler

Cevr-ü cefâ = sıkıntı, incitme 

Feilâtün     feilâtün     feilâtün    feilün

.  .   /   /   .  .   /   /   .  .   /   /   .  .   /', 'Ey uçan nemli bulut, gönlümü cânâna götür. Sulu gözlerde birikmiş yaşı al, câna götür. İyileşmez yaralar hastasıyım bir süredir Çaresiz derd...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gotur-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Güzelim', 'gel-guzelim-mehmet-fatin-baki-gx5g3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nice günler sana vuslat haberin bekliyorum

Eğer akşam gelemezsen bu seher gel güzelim.

Beni hasretle yakan günlere leyl ekliyorum 

Beni bekletme günahtır. Bu sefer gel güzelim.

Bana mektupta geliş vaktini ‘Sen söyle’ dedin

Gelirim belki sabah belkide asr-öğle dedin

Beni irşâd ederek böyle değil şöyle dedin

Beni bekletme haramdır. Bu sefer gel güzelim.

Azıcık kaldı vakit. Tatlı ömür harcanacak

Sana vuslatla da birkaç günümüz ballanacak

Yalınız böylece bir hâtıra bâkî kalacak

Beni bekletme yazıktır. Bu sefer gel güzelim.

Leyl = gece

Asr= öğleden sonra, akşama doğru

İrşad = doğru yolu gösterme

Feilâtün    feilâtün    feilâtün    feilün 

.  .   /   /  .  .   /   /  .  .   /   /  .  .   /', 'Nice günler sana vuslat haberin bekliyorum Eğer akşam gelemezsen bu seher gel güzelim. Beni hasretle yakan günlere leyl ekliyorum  Beni bekl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gel-guzelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balçık', 'balcik-mert-askin-p03yp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'akan nehirlere baraj

güneşe balçık

sanada sevgili olucam

tanrıya kul 

hayata köle

ölümüne nihilist

dogmaların anarşisti olucam

yada seni seveceğim', 'akan nehirlere baraj güneşe balçık sanada sevgili olucam tanrıya kul  hayata köle ölümüne nihilist dogmaların anarşisti olucam yada seni sev...', ARRAY['Türk Edebiyatı','Şiir','Mert Aşkın']::text[], 8.5, '{"poet":"Mert Aşkın","poet_slug":"mert-askin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/balcik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek', 'tek-mert-askin-u6x3l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kabaran yüreğim

Dalgalar yayıyor

Engeller çekilin

Gerçek bulanıyor

Yol verin

Kimseyi tanımıyor

Amaç tek

Uğruna dehşet saçıyor', 'Kabaran yüreğim Dalgalar yayıyor Engeller çekilin Gerçek bulanıyor Yol verin Kimseyi tanımıyor Amaç tek Uğruna dehşet saçıyor...', ARRAY['Türk Edebiyatı','Şiir','Mert Aşkın']::text[], 8.5, '{"poet":"Mert Aşkın","poet_slug":"mert-askin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tek-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölür müsün benimle?', 'olur-musun-benimle-mert-askin-kz46r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bak yukarı beni gör

Öl öl öl yanıma gel

Çıkardığın karbondioksitim ben

Sona doğru atılan adımım 

Huznunum kederinim acının ben

Nefretinin çesmesiyim 

deriden akan kanım 

hayatınım senin ben

Olmazsa olmazların kralıyım

Şeytanın kaynak kitabıyım ben

Ben senin sevginle doğdum

Beni sen aşkınla yarattın

Artık kork

Sarıl bana ben geldim', 'Bak yukarı beni gör Öl öl öl yanıma gel Çıkardığın karbondioksitim ben Sona doğru atılan adımım  Huznunum kederinim acının ben Nefretinin çe...', ARRAY['Türk Edebiyatı','Şiir','Mert Aşkın']::text[], 8.5, '{"poet":"Mert Aşkın","poet_slug":"mert-askin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/olur-musun-benimle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim', 'benim-mert-askin-gpwxo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ruhum göçte

Gözlerim gökte

Ve kan

Ellerim titrek

Kalbim panik

Ve sen

Beynim yok

Göğsüm delik

Ve ben

Çocuklarım plastik

Özlemim garip

İşte biz', 'Ruhum göçte Gözlerim gökte Ve kan Ellerim titrek Kalbim panik Ve sen Beynim yok Göğsüm delik Ve ben Çocuklarım plastik Özlemim garip İşte bi...', ARRAY['Türk Edebiyatı','Şiir','Mert Aşkın']::text[], 8.5, '{"poet":"Mert Aşkın","poet_slug":"mert-askin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/benim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiddet', 'siddet-mert-askin-qjdgy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Öldürmek isteğimin nedenidir

Sana olan nefretim

Nefretimin nedenidir

Sana sevgim

Seni sevmemin nedenidir var olman 

Ve bunlar

kendimi öldürmek isteğimin nedenidir', 'Öldürmek isteğimin nedenidir Sana olan nefretim Nefretimin nedenidir Sana sevgim Seni sevmemin nedenidir var olman  Ve bunlar kendimi öldürm...', ARRAY['Türk Edebiyatı','Şiir','Mert Aşkın']::text[], 8.5, '{"poet":"Mert Aşkın","poet_slug":"mert-askin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/siddet-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artı 1', 'arti-1-mert-askin-fk0cw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yorke''un hesabı banada uyuyor

İki iki daha beş ediyor

hesaplarım planlarım hep bir fazla çıkıyor

İşte aşk işte sevgi diyesim geliyor

Klişe geldi klişe gidiyor

Şiir yine aşk şiiri olmak istiyor

En büyük zaafımın şiiri bu şiir

sadece seni istiyor', 'Yorke''un hesabı banada uyuyor İki iki daha beş ediyor hesaplarım planlarım hep bir fazla çıkıyor İşte aşk işte sevgi diyesim geliyor Klişe g...', ARRAY['Türk Edebiyatı','Şiir','Mert Aşkın']::text[], 8.5, '{"poet":"Mert Aşkın","poet_slug":"mert-askin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/arti-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonunda', 'sonunda-mert-askin-xxfou', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ağlayarak yattım

Gülerek uyandım

Galiba öldüm

İstanbula baktım

Heryer yangın

Özenmiş romaya

Nerdesin neron

Kafayı yedim

Gerisini nasıl yiyeceğim

Eskiden melek gibiydim

Usta cennete nerden çıkarım

Hımm o yangınları şimdi anladım

Özel olmayı isterdim

Özel olmaya koyayım

Özel bi zavallıyım

Hemde en özelinden', 'Ağlayarak yattım Gülerek uyandım Galiba öldüm İstanbula baktım Heryer yangın Özenmiş romaya Nerdesin neron Kafayı yedim Gerisini nasıl yiyec...', ARRAY['Türk Edebiyatı','Şiir','Mert Aşkın']::text[], 8.5, '{"poet":"Mert Aşkın","poet_slug":"mert-askin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sonunda-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* B i l...k i...!', 'b-i-l-k-i-metin-eser-4hx6z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dünya kârı / ahirete geçemez,

Sanat kârı / sanatkârı geçemez,

Ömür fânî / fena ile geçemez.

Bil ki çâre / biçâreye ilaçtır,

Sözün özü / söz ehline gerektir,

Aşkın közü / meşk ehline gerektir,

İlmin safı / cehl ehline gerektir,

Bil ki deva / dert ehline ilaçtır.

Dostun hası / güzel kalbe şiardır,

Gözün yaşı / seven gönle şiardır,

Ömür yaşı / kemalata şiardır,

Bil ki cefâ / hal ehline ilaçtır.

Hakk''a iman / tevhid üzre kabûldür,

Tevhid yolu / teslim üzre makbûldür,

Teslim ise / tevekküle dühûldür,

Bil ki hafâ / setr ehline ilaçtır.

Bütün konu / muhataba duyrulur,

Hayat fonu / inancındır duyrulur,

Yolun sonu / belki yarın duyrulur,

Bil ki ölüm / kâmil ins''e ilaçtır.

30.06.04 / Wiesbaden', 'Dünya kârı / ahirete geçemez, Sanat kârı / sanatkârı geçemez, Ömür fânî / fena ile geçemez. Bil ki çâre / biçâreye ilaçtır, Sözün özü / söz ...', ARRAY['Türk Edebiyatı','Şiir','Metin Eser']::text[], 8.5, '{"poet":"Metin Eser","poet_slug":"metin-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/b-i-l-k-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farkımız', 'farkimiz-erol-dal-47mp1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben her şeyi

Sen bomboş 

Bir şeyi.

Ben ateşi

Sen güneşi.

Ben karanlığı

Sen aydınlığı.

Ben aşkı

Sense neşeyi.

Seviyoruz bir şeyleri

Zorlamı yani.? 

........

Aynı dünyada yaşayan

Farklı uygarlıkların sonucuyuz.

...

Ama,

Biri var

Seni kayıran.', 'Ben her şeyi Sen bomboş  Bir şeyi. Ben ateşi Sen güneşi. Ben karanlığı Sen aydınlığı. Ben aşkı Sense neşeyi. Seviyoruz bir şeyleri Zorlamı y...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/farkimiz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Senin Doğum Günün', 'bugun-senin-dogum-gunun-mehmet-yucel-78v0y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bugün senin doğum günün arkadaş,

olmasın gözlerinde yaş,

mutluluk,sevgi,umut yoldaşın olsun,

yürü üstüne üstüne hayatın,

yıldırmasın engeller,

her doğan güneşi doğum günün sayasın,

geçen zaman olsun tek yasın.

bugün senin doğum günün,

yıllar akıp geçiyor,

bir yaş daha ilerdesin,

gerilerde kalan,

mutluluk,hüzün,gerçek,yalan...

bugün senin doğum günün,

gül,eğlen,

baki kalmaz dünyaya gelen...

bugün senin doğum günün,

geldiğin dünya bu,

ya gördün ya kördün,

her geçen yıl alıp götürsede birşeyler,

yeşersin binlercesi,

bitmesin direncin,

bitmesin yaşama sevincin.

bugün senin doğum günün,

yarınlarını sevgiler süslesin,

nice yıllar kesilmesin sesin...', 'bugün senin doğum günün arkadaş, olmasın gözlerinde yaş, mutluluk,sevgi,umut yoldaşın olsun, yürü üstüne üstüne hayatın, yıldırmasın engelle...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yücel']::text[], 8.5, '{"poet":"Mehmet Yücel","poet_slug":"mehmet-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bugun-senin-dogum-gunun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle neyin nesiydi?', 'soyle-neyin-nesiydi-mustafa-angin-x0jfv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerin mi, saçların mı, bilmem ellerin miydi? 

Sen miydin beni çeken, aşk mı, hâyâl mi dersin? 

Özlem mi, ağrı mıydı, yüreğimde büyüyen,

Büyülü tutku muydu, söyle; neyin nesiydi? 

Kanmadığım su mudur; yoksa iklim mi kurak,

Doyurmayan ekmek mi, doymayan ben miyim ki? 

Bin heyecan içinde kelimelerle sıcak,

Bitmeyen şiir miydi; sen miydin, özlem miydi? 

Ömür boyu dinmeyen sancılara bıraktın:

Aldığın neydi benden, sende kalan neyimdi? 

Şimdi uzaklardasın, çağırsam duymazsın ki! 

Seni seviyorum desem, inanmazsın ki. 

Dağılmadı, unutulmadı o sımsıcak anılar,

Savrulmadı rüzgârda; kuru yaprak misali,

Yaşanmamış,  bir masaldı, sanki o kötü anlar,

Unutma ki senle yaşanacak daha güzel yıllar var.

Mustafa ANGIN

11/12/2003-ANKARA', 'Gözlerin mi, saçların mı, bilmem ellerin miydi?  Sen miydin beni çeken, aşk mı, hâyâl mi dersin?  Özlem mi, ağrı mıydı, yüreğimde büyüyen, B...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Angın']::text[], 8.5, '{"poet":"Mustafa Angın","poet_slug":"mustafa-angin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/soyle-neyin-nesiydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok Öyle Dayı,', 'yok-oyle-dayi-erol-dal-kustq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir ışık görmek

Uzaktan da olsa 

Güneşin sıcaklığını hissetmek yüzümde.

Kuş sesi,ağlayan bebek,koşan çocuklar,

yorgun argın çıkarken

gazete ve ekmeğiyle

Evine doğru…

………..

Hey dayııııııııııııııııı; 

Senin kadar bile değilim,

Hayat taptaze baharında solmuş; 

Benim bahçem, 

Baharın daha ilk aylarında, 

Hazan yaprakları ile dolmuş.

Evine varacaksın birazdan

Yorulmuşta olsa kalbin,

Karşılayan

Elli yıllık laf makinende olsa,

Yüzüne bir kapı açılacak ya.

Kapına benimki gibi 

örümcekler ağ kurmayacak.

Kuşlar  balkonunu kirletmiş

Teyze nasıl temizleyecek

romatizmalı ayaklarıyla 

koca balkonu.

…

Ben çağırıyorum kuşları

Kadere bak,

Evimde kuşların kirleteceği 

balkonum bile yok.

Benim evimde, 

Özgürlüğü tadan 

kuş pisliğine bile yer yok.

…

Çıkarken köprübaşı yokuşunu

Bedenin eziyet çekiyor,

Yaşamın verdiği yorgunluk

Her adımına aksediyor.

Ya benim, ya benim….

Yokuşum,

Yatacak,

Merdiven boşluğum 

bile yok.

…

Yaşamışta üzülüyorsun 

Öleceğim diye.

Bırak aç gözlülüğü, 

Hayatını yaşamışsın

Hatayı kendin yapmış

Doğruyu  kendin bulmuşsun.

..

Benim gibi 

daha ağlamayı bile öğrenemeden,

hayatın baharında tatmamışsın ölümü.

…

Ne mutlu sana.

Yaşamak için geldiğimiz uzayda,

Doğmadan öldürülenlerden 

Olmamışsın

Benim gibi.', 'Bir ışık görmek Uzaktan da olsa  Güneşin sıcaklığını hissetmek yüzümde. Kuş sesi,ağlayan bebek,koşan çocuklar, yorgun argın çıkarken gazete ...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/yok-oyle-dayi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldırırmıyım? Gaziantepli bestekar-şair Erol Güngör şiiri', 'aldirirmiyim-gaziantepli-bestekar-sair-erol-gungor-siiri-erol-gungor-y03c7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İşte çalıyor son yazdığım şarkı

Her sözde sen varsın, mısralarımda

Sevgin dolaşıyor, notalarımda

Saçıma kar yağmış, aldırır mıyım? 

Ellerin ellerimde esir gibi

Gözlerin gözlerimde erir gibi

Nazların en güzel emir gibi

Başıma taş düşmüş, aldırır mıyım? 

Acıyı sevginle paylaşıyorum

Sesini duyunca ferahlıyorum

Yangını aşkınla söndürüyorum

Ateşe düşmüşüm, aldırır mıyım? 

İşte bitiyor, son yazdığım şarkı

Yarın da sen varsın mısralarımda

Başka kimse olamaz hayatımda

En yoksul ben olsam, aldırır mıyım?', 'İşte çalıyor son yazdığım şarkı Her sözde sen varsın, mısralarımda Sevgin dolaşıyor, notalarımda Saçıma kar yağmış, aldırır mıyım?  Ellerin ...', ARRAY['Türk Edebiyatı','Şiir','Erol Güngör']::text[], 8.5, '{"poet":"Erol Güngör","poet_slug":"erol-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aldirirmiyim-gaziantepli-bestekar-sair-erol-gungor-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak...', 'yasamak-mehmet-yucel-1yyr0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yaşamak dün anlam

bugün anlamsızlık

bölünmüş bölük pörçük

yaşamak

kınalı bir tavşanın ürkek,telaşlı su arayışı

susayışı

yeşil kurbağanın her adımda sıçrayışı

kobra yılanın sebepsiz saldırışı

zehirli yaradılışı

üç ayağı seki yuları kır doru bir tay

koştukça anasının ardından

yorgun argın

minik tayın özlemini düşün

yaşamak

kısrak memesinde süt

doru tayın içgüdüsünde dilek

yaşamak

güzel yurdumun her yerinde

istanbul da manisa da çorum da

her mevsimde her durumda.

yaşamak

giresun da afyon da ardahan da

yaşamak o gün o anda

yaşamak

anadolu da trakya da kafkasya da

kapitalist avrupa da sömürülen asya da

yaşamak

gözlerinde,sözlerinde güzel yüzünde

gecesinde... gündüzünde

sevdanın ateşinde közünde,

bir kartal kadar özgür gökyüzünde

yaşamak

kar tanesi saçlarımda,

beyaz

tipi boran ayaz

ölümle pençeleşen bir hastanın umuda sarılışı

depremle yer kabuğunu yarılışı

aç çocukların ekmek özlemi

tokların israf zevki

yaşamak

çiftçinin çorak topraktan beklediği

çatlayan elleri,yetinmeye mecburiyeti

yetmeyen rızkı

şükredişi

yılan hikayesine dönmüş işi

çocuklarına glecek vermeyişi

yarınların ters gelişi

yaşamak

sevgilinin ince beline sarılmak,

kör talihe darılmak,

ziyan olmak,dökülmek,kırılmak...

akşamcıların kadeh kadeh tükenişi,

evsizlerin sokaklarda hayata direnişi...

yaşamak

umutların şehrin karanlığına gömülmesi,

kendi toprağında gurbetçi denilmesi

kurdun kuzuya yenilmesi

yiğitliğin kerizliğe bürünmesi

yaşamak

bulutların ardından ay görünmesi

yaşamak

bir yudum sevgiye verilen bir ömürün hikayesi

müeebete mahkum olmuş birinin tahliye hevesi

yıllarımı verdiğim vicdansızın gaddarlık meselesi

yaşamak

güneşin batışını gözlemek nemrut ta

düden şelalesinde güzelliğine dalmak doğanın

üçbin rakımda yaz ayında kış yaşamak

sevgilinin ellerini okşamak

yaşamak

manasızlığa bürünen hayatı sil baştan

her gün ölüme gidercesine

ekmeği çıkarmak kara elmastan

yaşamak kimi zaman yangın yeri

kimi zaman türlü meyveli bostan

yaşamak

bir şairin yüreğinede kin nefret sevgi sitem özlem

yaşamak türkü şiir felsefe sanat teori gözlem', 'yaşamak dün anlam bugün anlamsızlık bölünmüş bölük pörçük yaşamak kınalı bir tavşanın ürkek,telaşlı su arayışı susayışı yeşil kurbağanın her...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yücel']::text[], 8.5, '{"poet":"Mehmet Yücel","poet_slug":"mehmet-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/yasamak-89-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Yüzüne', 'gun-yuzune-hasan-ates-7m5pi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gün yüzünü çevirmiş yüzüme

sarıca ışıldıyor.

Bense,

çok eskiden kalma bir denizci kalfası,

yüreğime çarpan dalgaların gelgitini sayıyorum

parmaklarımla:

Biri geliyor... Biri gidiyor...

Derken o geliyor:

Kaptan,

“Gel,” diyor,

“Gel seninle açılalım ötelere,

özlemini duyduğum

ta o kadim denizlere,

ufukta köyüm görünüyor,

‘Gel’ diyor ufuk,

‘Gün batımı bensiz olmaz,

seyrine dalınasıyım,

şehrin aşinasıyım,

gün yüzüme ışır

ay üzerime bakar benim.

Gün doğururum

ay batırırım.’”

Gün hazır ışırken

(gün bir göğe ancak bu kadar yakışırken)

ilişelim denizlere,

ışıldayalım günle beraber.

Yelkenli değil

sade bir kayık olmalı vasıtamız.

Pusulamız ne leylek ne de bir ibre parçası olmalı,

hürriyet olmalı o,

alabildiğine hürriyet.

Açılmalıyız,

martılara yoldaş olmalıyız,

gerekirse karalardan sürmeliyiz küreklerimizi,

gerekirse martılarla aynı yöne düşmeliyiz

ve yârenlik etmeliyiz göçmen kuşlara.

Doğuya gittikçe hep batıya varmalı rotamız (olması gerektiğince).

Özlemimiz gitgide artmalı,

artmalı ki daha bir derin solumalıyız denizin o göğe çalınan maviliğini.

Ufukta ise istirahati bilmeliyiz.

Sonra

hiç bilmediğimiz bir yönden

birden bir rüzgâr esmeli:

Bu, karayel olmalı.

Rüzgâr daha bir savurdukça,

daha bir sert estikçe gözeneklerimize değin,

üşür olmalıyız.

Kemiklerimiz titreyinceye dek

o soğuğu (içimizi ısıtan)

en içimizde hissetmeliyiz ölünceye kadar,

hissetmeliyiz ki

nerde o soğuk biterse

nerde tükenirse o rüzgâr

işte orda kahrolmalıyız

kendimizi harap etmeliyiz,

değil mi kaptan?

— “Elbette evlat.

Elbette buralarda ölmeliyiz.

Nerde biterse o soğuk

orda çıkmalı sesimiz boğuk,

orda bitmeliyiz, orda tükenmeliyiz.

Mezarımız olmalı deniz.

Kara toprağımız da o,

taşımız da gene o

o olmalı.

Varımız da

yoğumuz da

ve mümkün olsa

dünyadan götürdüğümüz tek yadigârımız da...”

* * *

Karalar güne indirdi kepenklerini.

Sessiz bir dalga vurdu kıyıya.

Ben bitkin denizci kalfası,

kıyıya meyil ederken

ve çekerken kürekleri geriden geriye

kaptanım

bir yosun kokusunu

yüzüme yüzüme soluyordu

ciğerim teneffüs ettikçe.

Belki de ben bir istavrit kılçığı

belki bir deniz üstünde yüzen zeytin yağı tenekesi pası olma yolunda

çok şey yapmıştım kimbilir.

Ben bilemezdim ki.

Ben sadece bir denizci kalfasıydım altı üstü,

nerden bilebilirdim ki? 

Gün kavuşuyor usulca.

Kaptanım hâlâ yosun kokusu soluyor yüzüme.

Rüzgârsa ufuk kokuyor.

Şimdiden özledik kokusunu.

Bir daha kimbilir ne zaman nasıl eldesine kavuşulur o yerin? 

Yarın mı? 

Hiç sanmam.

Nitekim hayat bir meşgûliyet diyarı dostlarım.

Daldan dala savurdukça benliğinizi

durağınız nere olur bilinmez.

Biz iyisi mi

güne bakalım:

Nasıl da ışıyacak

sabaha erince,

yıldızlar kadar parlak,

göğün pür yüzünde!', 'Gün yüzünü çevirmiş yüzüme sarıca ışıldıyor. Bense, çok eskiden kalma bir denizci kalfası, yüreğime çarpan dalgaların gelgitini sayıyorum pa...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ateş']::text[], 8.5, '{"poet":"Hasan Ateş","poet_slug":"hasan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":101,"source_url":"https://www.antoloji.com/gun-yuzune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merak', 'merak-erol-dal-ht1sw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşamın getireceklerini

Görmek için buradayım.

Belki,

bereketli topraklar kaplayacak benliğimi.

Tıpkı, 

Nehrin, 

bilinmeyenden getirdiği gibi.

…

Belki de bir kil kaplayacak üzerimi, 

Boylu boyunca toprağa. 

Gömüleceğim.

…

Kim bilir,

…

Bekleyip görmek lazım.', 'Yaşamın getireceklerini Görmek için buradayım. Belki, bereketli topraklar kaplayacak benliğimi. Tıpkı,  Nehrin,  bilinmeyenden getirdiği gib...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/merak-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağladım', 'agladim-mustafa-ceylan-rfztc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bütün yürekleri aydınlık tutan 

Kudret kandilini gördüm, ağladım. 

Bütün eğrileri nurla doğrultan 

Işıktan giysiler ördüm, ağladım. 

Cennet kapısından içeri baktım, 

Irmaklar misali çağlayıp aktım, 

Nefsimi iğneli fıçıya soktum, 

Yüzümü toprağa sürdüm, ağladım. 

Buldum Hak diyerek açan gülümü, 

Düğün merasimi saydım ölümü, 

Yavan hesaplardan çekip elimi 

Bağlayıp divana durdum, ağladım. 

Anladım sırrını, arşın, âlemin 

Fâniyi, bâkiyi yazan kalemin. 

Yunus ellerimden tuttu...Yetmiş bin 

Hisardan içeri girdim, ağladım. 

Dost bağında bülbül oldum şakıdım, 

Aşk halısın usta oldum dokudum, 

Doksan bin kelâmı hemen okudum 

Kudret lokmasına erdim, ağladım. 

Canan meclisinde coşan erlere, 

Selâm verdim kutbu devran pirlere. 

Yedi gök yüzüne, yedi yerlere 

Ben’ i zerre zerre serdim, ağladım. 

Perdeyi gözümden açtım kaldırdım, 

Hikmet deryasına bin tas daldırdım, 

Kâmil hayat ile testim doldurdum, 

Dolmayan testiyi kırdım, ağladım. 

Gördüm güzelliği gördüm her yanda, 

Solmayan çiçekler açtı dünyamda, 

Atomdan hızlıca gittim bir anda 

Doksan günlük yola vardım, ağladım. 

Yüzbin bıçak attım kendi derime, 

Nice ilim kattım bildiklerime, 

Şu küçük dünyada gördüklerime, 

Hakikat mührünü vurdum, ağladım. 

Canlar meclisine canan hoş geldin! 

Kanayan yareme bir melhem oldun. 

Ey miskin Ceylan’ ım ölmeden öldün 

Gönül yarasını sardım, ağladım.', 'Bütün yürekleri aydınlık tutan  Kudret kandilini gördüm, ağladım.  Bütün eğrileri nurla doğrultan  Işıktan giysiler ördüm, ağladım.  Cennet ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/agladim-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nuhca', 'nuhca-pasa-ceten-kikx6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Azad ediyorumkötü günleri

''Andolsun kuruyan göğe'' ki artık

Kavgam, geceyle gündüzün ayrıldığı yerde

Yolculuğun sonunda mateme boğulacak deniz

Aydınlık saatlere yaklaşıyorum

Gemi ay yüklü, yalnızca ay

Bir çift Nur yansıyor Rabbimden 

Ben hicret dedim, bana siz kurtuluş deyin.', 'Azad ediyorumkötü günleri ''Andolsun kuruyan göğe'' ki artık Kavgam, geceyle gündüzün ayrıldığı yerde Yolculuğun sonunda mateme boğulacak deni...', ARRAY['Türk Edebiyatı','Şiir','Paşa Çeten']::text[], 8.5, '{"poet":"Paşa Çeten","poet_slug":"pasa-ceten","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/nuhca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşil gül', 'yesil-gul-pasa-ceten-ddzjq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sabrın yeşil gülü çimende yeşerdi

Zaman terazisinde, huyum tartıldı

Beyaz buluttan bir pencere açıldı

Girdim içine, tomurcuk gibi açıldım efendim.

Işık terazisinde, ruhum tartıldı

Yeşil gülün sabrı yeşil çimende yeşerdi

Aşkı hesaba çeken, sevgili de geldi

Sana kavuşmak için, günler tükenmiyor efendim.

Aşkı mihraca götüren gün geldi

Kainatın nuru, iki alemin nuru

Ezeldeki ışığın teninde, ebed yüzüyor

Aşkı insanlığa, yeşil gülle sundu efendim.

Renk yağmurları canımı çaldı

Günahkar kulun yitiğini ver 

Yere göğe sığmıyor feryadım

Aşkı hesaba çeken sevgili gelsin efendim.', 'Sabrın yeşil gülü çimende yeşerdi Zaman terazisinde, huyum tartıldı Beyaz buluttan bir pencere açıldı Girdim içine, tomurcuk gibi açıldım ef...', ARRAY['Türk Edebiyatı','Şiir','Paşa Çeten']::text[], 8.5, '{"poet":"Paşa Çeten","poet_slug":"pasa-ceten","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yesil-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte İsa', 'i-ste-i-sa-pasa-ceten-wg0cy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İşte İsa''yı böyle gerdiler çarmıha

Kiliseler böyle kutsadı

Özgürlük naraları böyle yaratıldı

Karanlık bu infazı izleyerek gerildi göğe

Alın bu haçı, savaşlar çıkarın dediler

Yeni kitaplara saldırmak için bahaneniz tamam

Ey kalbini boşaltarak rahatlayan bedenim

Sevin, akıl bir silah parçasıdır artık

Şimdi soframızda mermiden, zehirden başka ne var? 

İşgal, ilhak, vahşet, kanın yurdundan çıkarılışı

İyilikler baharıydı onlarla yaşadığımız

Yoksa İsa''dan öncede aynıydı dünya, Muhammed'' ten sonrada', 'İşte İsa''yı böyle gerdiler çarmıha Kiliseler böyle kutsadı Özgürlük naraları böyle yaratıldı Karanlık bu infazı izleyerek gerildi göğe Alın ...', ARRAY['Türk Edebiyatı','Şiir','Paşa Çeten']::text[], 8.5, '{"poet":"Paşa Çeten","poet_slug":"pasa-ceten","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/iste-isa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hicret', 'hicret-pasa-ceten-fdyja', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ömürler köprüdür, canlar köprü

Bir hüzün geçer, bir dolu neşe

Bir bizi aldatır bulutların güzelliği

Bir hayal uğruna delikanlıyız

Örümcek ağına takılan bu şehir

Söylen hangi dipcik kurtarır? 

Bir bizim ezgimiz dolanır gökyüzünü

Ağıtlar, dikenli teller mızrabıyız

Bir sabah omuzlarımızda güneş

Sıra dağlar gibi yürürüz

Uykumuz yellere, korkumuz sellere

Artık kırılmış can kafesimiz', 'Ömürler köprüdür, canlar köprü Bir hüzün geçer, bir dolu neşe Bir bizi aldatır bulutların güzelliği Bir hayal uğruna delikanlıyız Örümcek ağ...', ARRAY['Türk Edebiyatı','Şiir','Paşa Çeten']::text[], 8.5, '{"poet":"Paşa Çeten","poet_slug":"pasa-ceten","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hicret-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönülkıran', 'gonulkiran-mustafa-ceylan-gvg8b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '•	Gitti dönmez o ceylan

•	Şimdi yalnız bu Ceylan

Canan dedim, canım gitti  elimden

Döndü gönül evim viranelere...

Ceylanımdı adı düşmez dilimden

Vallahi benzedim divanelere....

Nerde bilmiyorum o gönülkıran? 

Bakışıyla her an aşkı haykıran

Sızlar yârelerim yok işte saran

Düştüm hasretiyle meyhanelere...

Sevda başkentimi yangınlar sardı

Feryâdım, figânım göklere vardı

Sönmeyen ışıktı, ateşti, nardı

Çevirmişti beni pervanelere...

Şimdi öykümüzü şairler yazsın

Şimdi bağımızı yâdeller bozsun

Soruma cevap ver, neden yalnızsın? 

Sığınma ey gönül bahanelere! ..', '•	Gitti dönmez o ceylan •	Şimdi yalnız bu Ceylan Canan dedim, canım gitti  elimden Döndü gönül evim viranelere... Ceylanımdı adı düşmez dili...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gonulkiran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beynimi yıkayan cehennem', 'beynimi-yikayan-cehennem-pasa-ceten-ar5mz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşkın doğuşunu, şehadetin yapısını gördüm

Ey çağın zamanı

Nur pınarının ey; 

Bozulmayan güneş fışkıran bahar

Kur''an'' nın akordu İslam''ın kıvılcımı

Serpildi gönüllere

Diriliyor gök, diriliyor yer

Bütün kainatı bağrında yaşatan denge

Tevhidi çağırsa yaşasa çocuklar

Özürlüğüne hakkın sesini assa

Yaradan unutuldu, Dünya talanda

Hazanı görmüş bezginler gibi azab

İnanç kabuğuna çekilmiş, üstelik tutsak

Kara gecelerde iniltiler insanlığı taşlıyor

Gündüzlerde inanca takılan kilit

Kahkaha zincirinde yokluığa esir vicdanlar

Simgeler tutsak Dünya''nın ekseninde dönüyor

Ey sen madde avcısı; akrepli sarayın kahramanı

Zilletle yıkadın kasıp kavuran zulümün beynini

Kin illeti cehennemin canında kızıl perdedir

Gecenin gözlerini kara elleri ile bağlayan zihniyet

Yılanın kuyruğunda yaralı akıl gibi dayatmacısın

Karanlığın gölgesini ortadan kesiyor hınç bıçağı

Yeniden sanki cahiliye devri başlıyor

Nemrut''dan, Firvun''dan, Ebucehil''den zihniyetleri

Zamanı soyan kara başlı, keskin tırnaklı alçaklık

Hileli terazide tartılan Dünya''nın dertleri bende

Lanet ve nefret birleşiyor inancımın önünde 

Fitne kalbinde zulümün silsilesi eriyecek

Ey zihniyet; Hakkın ateşini haşlayarak sana yolluyorum

Hakkın yeryüzünü cennete cevirip yaşatması hakkıdır

Nur pınarının başında bozulmayan Güneş...', 'Aşkın doğuşunu, şehadetin yapısını gördüm Ey çağın zamanı Nur pınarının ey;  Bozulmayan güneş fışkıran bahar Kur''an'' nın akordu İslam''ın kıv...', ARRAY['Türk Edebiyatı','Şiir','Paşa Çeten']::text[], 8.5, '{"poet":"Paşa Çeten","poet_slug":"pasa-ceten","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/beynimi-yikayan-cehennem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir bahar bir güzele alışmış toprakça', 'bir-bahar-bir-guzele-alismis-toprakca-pasa-ceten-xkt1i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Deniz tadında herşey, düşüncemde yorgunluk

Bir itirafçı damlalar seyre değer

Alçaklarda mor, hain fosforlar

Beynimin çılgın zarını soymakta

Kasırga hem kendini, hem damlaları savuruyor

Hatıraların en ön safında leyla

Sükunet giymiş kıyamda durur gibi

Bir bahar bir güzele alışmış toprakça

Direnerek suya, ışığa ve insan ve 

Ömür denen karanlık okyanusuna

Nedir lisan bilmek yada kürek kullanmak? 

Sömürünün ertelediği üçüncü savaşın eşiğinde

Karnını terk ederken bir bir kardeşlerim

Kurbanlık kaç yumruk büyütüyorsun anne? 

Deniz tadında herşey, düşüncemde yorgunluk', 'Deniz tadında herşey, düşüncemde yorgunluk Bir itirafçı damlalar seyre değer Alçaklarda mor, hain fosforlar Beynimin çılgın zarını soymakta ...', ARRAY['Türk Edebiyatı','Şiir','Paşa Çeten']::text[], 8.5, '{"poet":"Paşa Çeten","poet_slug":"pasa-ceten","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-bahar-bir-guzele-alismis-toprakca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçime içime', 'i-cime-icime-zafer-zengin-etnika-nb25h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Elim yüzünde

Gözüm elinde

Yüreğim sesinde

İçim titriyor

Işık damlıyor

İçime içime

*

Yağmur saçında

Hüzün gözümün yaşında

Ben ankarada

Tek başına

Zaman damlıyor

İçime içime

*

Akşamlar felaketim

Geceler konuşma saatim

Sessizliğin zulüm

Adın damlıyor

İçime içime

25 Haziran 2004 '' Sır Yanarken''', 'Elim yüzünde Gözüm elinde Yüreğim sesinde İçim titriyor Işık damlıyor İçime içime * Yağmur saçında Hüzün gözümün yaşında Ben ankarada Tek ba...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/icime-icime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günün', 'dogum-gunun-mustafa-ceylan-3aawz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tanrı’dan dilerim gülsün gül yüzün

Sarmasın sineni elemle hüzün,

Ey saçı ay ışığı, bakışları gün

Doğum günün kutlu olsun bir tanem...

Daha nice yıla ulaşalım biz,

El ele, göz göze dolaşalım biz,

Destan olsun destan, kutsal sevgimiz

Doğum günün kutlu olsun bir tanem.

Senden başka kimim, kimim var benim? 

Beyaz gelinliğin olsun kefenim,

Her iki cihanda sana kefilim

Doğum günün kutlu olsun bir tanem.

Acımda, neşemde hep yanımdasın

Vallahi, billahi şu canımdasın,

Aşkımızı kelebekler kıskansın

Doğum günün kutlu olsun bir tanem.

Hep sana adadım sana ömrümü,

Sevdanla donattım deli gönlümü

Daim kıskanırım gonca gülümü

Doğum günün kutlu olsun bir tanem.

Şairinim, hediyemdir şiirim

Çağırmasan, kovsan yine gelirim.

İnan bana uğruna can veririm,

Doğum günün kutlu olsun bir tanem.', 'Tanrı’dan dilerim gülsün gül yüzün Sarmasın sineni elemle hüzün, Ey saçı ay ışığı, bakışları gün Doğum günün kutlu olsun bir tanem... Daha n...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dogum-gunun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Menekşe Kokulu Kadın...', 'menekse-kokulu-kadin-i-brahim-ethem-bingul-xh7od', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kendimi unuttuğum yılların

Aşksız geçen her anımın

Mükafatı sen

Menekşe kokulu kadın nerdesin? 

Hatırlattığın her duygumun

Neşeyle gülümsediğim hayatın

Sahibi sen

Menekşe kokulu kadın nerdesin? 

Zindanlarımın penceresi

Kaybolduğum labirentlerimin

Çıkışı sen

Menekşe kokulu kadın nerdesin? 

Rüzgarlarla çağırsam gelir misin? 

Gece bakışlım yoksa

Ölürüm diye diye sen

Başka gönüllere gidenlerden misin?', 'Kendimi unuttuğum yılların Aşksız geçen her anımın Mükafatı sen Menekşe kokulu kadın nerdesin?  Hatırlattığın her duygumun Neşeyle gülümsedi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/menekse-kokulu-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En kolay', 'en-kolay-zafer-zengin-etnika-bpw0f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözün saklanamadı

O kadar çıplaktı

Hele bir gülüşü vardı

Fosforlu

Gece ortasında

Yangındı

Suyla geldik yüreğine/Öptük

İçimiz sallandı

En kolay

Büyümüş

Çocuklar anlardı

16 Haziran 2004 '' sır yanarken ''', 'Gözün saklanamadı O kadar çıplaktı Hele bir gülüşü vardı Fosforlu Gece ortasında Yangındı Suyla geldik yüreğine/Öptük İçimiz sallandı En kol...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/en-kolay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Prenses', 'prenses-yunus-ali-sinanoglu-s74pj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kral oluyorum

Hazır mısın

Geliyorum almaya seni

Yedi düveli 

Dört mevsimi

Sana sunmaya

Tacım tacındır

Yıldızım yıldızın

Gel ufka bak 

Doyalım akşamların

Ve dönüşüne güller

Güller gülsün 

Ateş ol gel

Ellerini bana ver

Hüküm sürsün kader

Prenses

Gelincik çiçeği

Herşeyin en güzeli

Uzakların hanımeli

Gel Gelincik çiçeği

GEL', 'Kral oluyorum Hazır mısın Geliyorum almaya seni Yedi düveli  Dört mevsimi Sana sunmaya Tacım tacındır Yıldızım yıldızın Gel ufka bak  Doyalı...', ARRAY['Türk Edebiyatı','Şiir','Yunus Ali Sinanoğlu']::text[], 8.5, '{"poet":"Yunus Ali Sinanoğlu","poet_slug":"yunus-ali-sinanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/prenses-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Feride', 'feride-yunus-ali-sinanoglu-m4g5z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Feride sen kimsin

? 

Bana ne! 

Güzel gözlerin gece

Rübabı şikeste

Feride

Fecr-i Ati

Dökülen güller gibi

Feride dolmuşta bir kız

Siyah gözleri yıldız yıldız

Feride nazlı feride bahar

Feride aslında yaz

Utangaç biraz

Ve saçları güzel

Kaşları kalem

Feridenin içinde binbir alem

Ve ben ki hoş

Ben ki sarhoş

Konuşmak zor

Varlığım mayhoş

Daha görmek seni

Zor yani bilmem ki

Feride kimse değil

Kimse değil değil

Redifler gibi yani

Tekrar et et emi

Feride sevebilir mi beni

Zor değil mi

Değil değil mi', 'Feride sen kimsin ?  Bana ne!  Güzel gözlerin gece Rübabı şikeste Feride Fecr-i Ati Dökülen güller gibi Feride dolmuşta bir kız Siyah gözler...', ARRAY['Türk Edebiyatı','Şiir','Yunus Ali Sinanoğlu']::text[], 8.5, '{"poet":"Yunus Ali Sinanoğlu","poet_slug":"yunus-ali-sinanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/feride-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serap', 'serap-turgay-kadiroglu-s6wu1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'güneşin doğduğu ve battığı,

ayın yükseldiği ve karardığı vakit

gönül çölümdeki serabın rengi hep aynıydı

varlığı ellerim kadardı,

düşlerim şehirler ötesine uzanır

ve söz ellerimden akardı...

bulut esaretinden kurtulan damla

gurbet diye gözlerine akardı,

ateş yutmuş sus pus dağlar,

yamaçlarında ırmaklar susardı,

bakışları ıslanan balıklar

çöllerimdeki hayaline bakardı...', 'güneşin doğduğu ve battığı, ayın yükseldiği ve karardığı vakit gönül çölümdeki serabın rengi hep aynıydı varlığı ellerim kadardı, düşlerim ş...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kadiroğlu']::text[], 8.5, '{"poet":"Turgay Kadiroğlu","poet_slug":"turgay-kadiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/serap-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilsem saklamazdım', 'bilsem-saklamazdim-zafer-zengin-etnika-jlwdl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kimse 

yok 

diye

ağladım

Senin

olduğunu

bilsem

saklamazdım

Nasıl 

büyümüş

damlalarım

Ah

adamım

Çocuk

Kalsaydım

Yakıştırırdım

Saklamazdım

| İçim sessiz..Aşk gibi..sessiz |

20 Haziran 2004 '' O''nun gözleri  kara ''', 'Kimse  yok  diye ağladım Senin olduğunu bilsem saklamazdım Nasıl  büyümüş damlalarım Ah adamım Çocuk Kalsaydım Yakıştırırdım Saklamazdım | İ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bilsem-saklamazdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığın Koyu Tadı', 'yalnizligin-koyu-tadi-aynur-uluc-29lg4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalnızlığın girdabında sevgiliyi ararken 

Daha da yalnız kalmayı isteyebiliyor insan

Sanki yalnızlık koyulaşınca hayâlde

Katıksız yaklaşmak mümkünmüş gibi 

Sanki ışıklar ve sesler 

Büyüyü baştan bozacak gibi 

Kendimizden bilet alıp girdiğimiz yerde 

Şehvetli kaydıraklar mı yok 

Ucunda dert çeken tahterevalliler mi

Kısır döngüye mahkum dönme dolaplar

Doğru atışa ödül keşifler mi yoksa

Karanlıkta uçuşan renkli lunaparkımızda 

Hangisi yok…', 'Yalnızlığın girdabında sevgiliyi ararken  Daha da yalnız kalmayı isteyebiliyor insan Sanki yalnızlık koyulaşınca hayâlde Katıksız yaklaşmak ...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yalnizligin-koyu-tadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toplu Gösterim', 'toplu-gosterim-baykal-kaanalp-ue2lo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'toplu gösterime  girdi yaşadıklarımız

nefesin tükendiğinden beri

birlikte yazdığımız şarkılarımız

kapıyı çalmadan girdi içeri

''tek perdelik bir donkişot piyesi

duyulmuyor hiç seyircilerin sesi

alkışı hakedecek birşey yok

oyunlar hayatın ifadesi''

toplu gösterim bitti

gözlerim çapak çapak

sensizlik canıma yetti

hiçbir gemi yok kaçacak', 'toplu gösterime  girdi yaşadıklarımız nefesin tükendiğinden beri birlikte yazdığımız şarkılarımız kapıyı çalmadan girdi içeri ''tek perdelik ...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/toplu-gosterim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yargılayın Kendinizi', 'yargilayin-kendinizi-baykal-kaanalp-xccof', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bazen bir arpa boyu

ilerliyemiyorsanız işinizde

yargılayın kendinizi

dökün hislerinizi

belki soğur motorunuz

belki nefes alır

akciğeriniz

paylaşmaktan korkuyorsanız

yorgunluğunuzu

kendinizle

belki barış çubuklarını

tüttürürsünüz 

sevginizle

dostluğunuzla

belki kaçarsınız

başka bir aleme

gönlünüzce

belki de seversiniz

yeniden

korkularınızı

belki açılırsınız

yeniden

mavi denize











i', 'bazen bir arpa boyu ilerliyemiyorsanız işinizde yargılayın kendinizi dökün hislerinizi belki soğur motorunuz belki nefes alır akciğeriniz pa...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yargilayin-kendinizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybolurum Gözünde Türkülerin', 'kaybolurum-gozunde-turkulerin-baykal-kaanalp-3shej', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ben bakarım uzaklara

uzaklar hiç bakmaz bana

yalnızlıkta ararım sevdamı

yalnızlık hiç aramaz beni

kaybolurum gözünde türkülerin

türküler hiç kaybolmaz gözümde

yenilginin içinde yanarım

yenilgi hiç yanmaz içimde

dökerim aşkımı yollara

yollar hiç dökmez aşkını bana

dalgamı geçerim denizle

deniz hiç dalga geçmez benimle', 'ben bakarım uzaklara uzaklar hiç bakmaz bana yalnızlıkta ararım sevdamı yalnızlık hiç aramaz beni kaybolurum gözünde türkülerin türküler hiç...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kaybolurum-gozunde-turkulerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıt Ahenk', 'kit-ahenk-mehmet-yucel-dggxa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir zebra yavrusu siyah çizgili ala,

sevimli,

kopmuş sürüden,annesinden,

sesssiz,sedasız, masum...

aslan siyah yeleli,

kendinden emin

kralı ormanların...

pençesi kanlı...

çakallar bir kenarda,

arta kalanların sevdasında,

ve akbabalar....

gagası iri kurşuni,

gözleri ölüm kusan...

benek benek tüyleri,

kanatları heybetli,

çöreklenmiş oracıkta onlarcası...

kanun bu dercesine,

yalayıp yutma peşinde,

son perdesini kapatmaya bir canın,

hakkı yokmuşçasına yaşamaya.

toprak olmaya gelen,

toprağa doğru yönelen,

insan,

beşer yani,

yetmeyen zaman,

görmeye mani,

geçip gitmiştir giden,

aynı yörüngede aynı saflarda.

ya sanarak,

ya kanarak,

takip edilen iz,

aslında giz.

ötesindeyiz...

ateşi yaratan sandı,

şimşekleri felaket,

kulağı beynine hükmetti,

gereksiz gitti,

orman değil de nedir,

ağaçlar kadar hür olmasada,

suç ve cezaya dayalı,

doğal değil,

boyalı...

boyası renk renk,

kıt ahenk.', 'bir zebra yavrusu siyah çizgili ala, sevimli, kopmuş sürüden,annesinden, sesssiz,sedasız, masum... aslan siyah yeleli, kendinden emin kralı ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yücel']::text[], 8.5, '{"poet":"Mehmet Yücel","poet_slug":"mehmet-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/kit-ahenk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Devam Ediyor,Uğur Mumcu''luk İşler.', 'yine-devam-ediyor-ugur-mumcu-luk-i-sler-yuksel-ozbek-iy51u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Boğazımın manzarasını akbabalar pisler,

İçinde tank gezen savaş kokan gözler.

Mini mini çocukları kurşunları izler.

“Barış”tüccarlaşır, insanlık  dolarla “kişner”! 

Boğazımın manzarasını akbabalar pisler,

“İşkencecim” gelmiş “işbirlikçimi” süsler.

Namzet “öküze özenen kurbağa” timsali şişer! 

Yine devam ediyor,Uğur Mumcu’luk işler! ! 

Boğazımın manzarasını akbabalar pisler,

Uyandı,uyanacak mazlumlar,hazırlandı dişler.

“Bozkırımda” kaşık havası,kardeşlik düşler,

Kendilerini büyük adam sanır,eli kanlı keşler! ! 

Boğazımın manzarasını akbabalar pisler,

Tek taraflı “beslenmiş” düşüncesi obezler! 

İnsanlık zor zanaat; gelmiyor sağduyudan sesler.

Emek,Barış,özgürlük  “haydi”,seni de bekler.', 'Boğazımın manzarasını akbabalar pisler, İçinde tank gezen savaş kokan gözler. Mini mini çocukları kurşunları izler. “Barış”tüccarlaşır, insa...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Özbek']::text[], 8.5, '{"poet":"Yüksel Özbek","poet_slug":"yuksel-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yine-devam-ediyor-ugur-mumcu-luk-isler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebekler Ağlamasın', 'bebekler-aglamasin-murat-nail-guney-skg0i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sevgiliye en yüce sevgilerimle selam,

en büyüğünü yaşıyorum aşkların bu evrende.

zaman dursun istiyorum senle buluştuğumuzda,

güneş çakılıp kalsın gökyüzüne hiç batmasın.

içimden uykusuz trenler geçmesin bundan sonra,

ne yaşadıysam sensiz unutulup gitsin bir bir...

solmasın tomurcuk güller dört mevsim de,

ağlamasın bebekler dünyayı ilk gördüğünde,

rüzgarlar soğuk esmesin üşütmesin ateş böceklerini,

ıslanmasın kelebekler de vakitsiz yağmurlarla,

kaybolmasın hayatın siyah-beyaz nostaljisi,

oyuncaklarını almayın elinden hiç büyümeyen çocukların,

çok kızarım,sakın haaa! sevenleri ayırmayın...

26 kasım 2003 alaçatı/çeşme

murat nail güney', 'sevgiliye en yüce sevgilerimle selam, en büyüğünü yaşıyorum aşkların bu evrende. zaman dursun istiyorum senle buluştuğumuzda, güneş çakılıp ...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bebekler-aglamasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağışlama', 'bagislama-adnan-durmaz-pxzcf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'akşam üzeri bulvar

birinin yüzünde örse iniyor çekiç

bir gülüşün çeliğine su veriliyor

bahar 

damar damar uzanıyor yüzlere

genç gürültüler kavisler çizerek yürüyor

el ele tutuşan sevgililerden belli

güzeldir tüm kadınlar

yolcuyum... uzaklardan geldim

beni nereden bilsin bakıp kaldığım bulvar

çiğnenmiş yapraklar gibi çocukluk yüz-ün

yırtık etekli rüzgarlarda savrulmuş

henüz söze dökülmemiş bir yanık ağıt

kimsesiz ölülerin ardında kalan

zamanın durduğu ana sığınmış boşluk

gibi kavrulmuş yüzün

o senin

o senin kovdukça gitmeyen 

	sokak köpeği gibi

		dalları gülleri kırılmış gözlerin

düşer insan yüzlerinin sularına

keder kokulu lal akşam

kalbimde yaralar bırakan küskünlüğün

iyileşmez yaralar gibi bitmeyen öfke

ıssızlığın gelir durur karşıma 

nereye baksam

akşam üzeri bulvar

yüzümün alnacında ayaz bir rüzgar

ansızın kırılır kanadım

yoruldum bir sitemi kanatmaktan

çoğaltmaktan içimdeki çatlamaları

yoruldum

git gidebildiğin kadar

yolun açık olsun gayri

seni bağışladım

								Mayıs 2002

adnan durmaz,bilirsin aşk da serseri,art yay,ank,2003', 'akşam üzeri bulvar birinin yüzünde örse iniyor çekiç bir gülüşün çeliğine su veriliyor bahar  damar damar uzanıyor yüzlere genç gürültüler k...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/bagislama-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su Nasıl Yıkar Kendini…', 'su-nasil-yikar-kendini-adnan-durmaz-cprty', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bu sancılı soluklar kaldı geriye

kamışlıkta inleyen acı bir rüzgar gibi

sırı erken dökülmüş aynalar tanımlar bakışımı

sular mı çekildi

anlamı ne bu kum sonsuzunun

belki dalgalarda nabız vururdu yaşamanın ahengi

fırtınaların bile şimdi bildim kıymetini

ıssızlığa terk edilen bir kayık gibi

unuttum

nasıldı denizin rengi... 

unuttum nasıldı umut

belki bir ikindi günüydü

ölümünü bekleyen dam dibindeki ihtiyarın yüzünde

karlı zirvelerle tanımladılar ki onu

ki onu kovalamaklara yaşamak dendi

aşılmaz duvar oldu uzaklığının pusu

kirli ve yalınayak çocukların

kahrolan gülüşlerinde yakaladılar

ve her seferinde on beşine varmadan işledi ilk cinayetini

gecenin karanlığında söndü mumu

ve yıldızlar kadar ırak-titrek-imkansız

oysa koyun koyuna uyunmalıydı kardeş ve sevgili gibi

bilmedim nasıldı umudun kokusu

kendimin celladı oldum her şafak sökümünde

gördüm ki hepimiz katiliz haksızlığa sustukça

aşk diye piyasaya sürülen her cendere

son kalan insan yanlarını yağmalarken coşkuların

gördüm ki ilanı aşklarla başlar aşkın ölümü

ve herkes birbirini yiyor,neon ışıklı evlerde

su nasıl vuruyorsa kıyıya cesetleri

gül bülbülü unutuyor kuruduğu yerde

ve hep sordum kendime

hep sordum

su nasıl yıkar kendini

            kirletmişse

								Aralık 1999

adnan durmaz,bilirsin aşk da serseri,art yay,ank,2003', 'bu sancılı soluklar kaldı geriye kamışlıkta inleyen acı bir rüzgar gibi sırı erken dökülmüş aynalar tanımlar bakışımı sular mı çekildi anlam...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/su-nasil-yikar-kendini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşamın Kanayan Sözü', 'aksamin-kanayan-sozu-adnan-durmaz-45y4d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gel ha gayri... meşe selim mor bulutum serçe masumu gözlüm

bu bir kaval kanaması zamanın sinesinden sağılır gelir

bir keder bahçesidir... her gönüle uç verir de açar bir zaman

bir masal bohçasıdır

bu yürek yürek değil

ıssızda bir kuyunun delik kovasıdır

beri gel allı turnam... türkü gülüşler taşısın gözlerin

kendinde bul beni... sana gel... bana git

bu sevdasına yitik karıncanın öyküsüdür

akıp gider de allı telli bu kıraçta

koyunların kukusudur... bulutların kokusudur...

	sabahın kokusudur...

		akşamın teri

gecenin elleridir akıp gider de hayat... dokunur taşa

dokunur ıslığa... onu kavislendirir... 

kayaya gül oyan sevdadır... 

ve biz geliriz... 

bir kahır... bir acı bir hay bir huy

yağma sofrası bir ömrün haritasında

tutsak geldiğini bilemeden sevdik de yaşamayı...

	sevdik teneke barakaları...

		kerpiç damları...

			yağmurda akan evlerde seviştik gece karanlıktı

anlamadık... çözemedik... 

doğuştan hasretli bir suydu işte hayat

ve öldük geride türküler bırakan karasevdalarda yana yana

bir gün belki de bozkırdan kalkan

bir toz hortumu olur da düşlerimiz

savruluruz günahlarımız suçluluk duygularımızla

bir gün belki

adamı eşkıya düşüren sevdanın türküsünü

bir çocuk gelir de söyler yıkılmış evlerimizden kalan 

	son taşın üzerine oturarak

beri gel... belki zaman da hiçtir

her neyse yaşamın anlamı...

	onun en güzel andacı olsun ki aşkım sana

bütün ciddi adamlar sultanlar öfkeler

bar bar bağırmalar... başını taşlara vurmalar da yok olacak

biz varız şimdi... gel de gör senim işte

yokluğun... ömrümün gecesidir

dağlar da ağlar... aslında uzun havalar yankılanır ya

ahını zaptedemeyenin çığlığı kesilir taş olur doruklarında

dağlar da ağlar bulutlar öperken saçlarını... 

	gün her batışında kanatırken yüreğini

taşlar da gülümser... o en eski usta aşkı nakşederken bağrına

güler taş... hüzünden bakışlarında eğirerek sevdayı

ne zaman bir kadın kilim dokusa

sen beni aramaya çıkarsın yüreğinin gergefinde gül sağnar

gel... artık gel

sensizlikte dağlar da ağlar

yıkılmış surların altında kaç ömür rüzgara dönüştü

dağların ardında kaç sevda bulut olup yağdı çöle

ferhadın yüreği sebil

külüngü söz oldu... bütün dinler kovdu onu

yağmalana yağmalana geldim de işte

ömürdü azığım...  sermayem yürek

taşlandım sokaklarda ibreti alem için

sensiz gözlerimi saçtım karanlığa yıldızlardır şimdi

damıttığım düşlerim ekşiyip zehir oldu

yenilgilerden geldim-yorgunum ellerin yok

ve zaman 

ve rüzgar

gel gayri gel

yaşamak seninle başlar

adnan durmaz,bilirsin aşk da serseri,art yay,ank,2003', 'gel ha gayri... meşe selim mor bulutum serçe masumu gözlüm bu bir kaval kanaması zamanın sinesinden sağılır gelir bir keder bahçesidir... he...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/aksamin-kanayan-sozu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz ömrü bıraktık,her gün yeni bir ömür giyeriz', 'biz-omru-biraktik-her-gun-yeni-bir-omur-giyeriz-sair-ahrazi-2bzbt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şu ilâhi kaderde yüküm aşktan ibâret,

Öyle bir yoldayım ki dur desen de duramam.

Maksat yaşamak değil fâni cânı ziyâret,

Aciz kalan bedeni sar desen de saramam.

***

Bak! nasılda âşikar,güneş gibi her nişân,

Gören secdeye vardı görmeyenler perişân,

Medet ummaz dünyâdan yedi kata karışan,

Dardır geniş kapısı gir desen de giremem.

***

Cânın tenden çıkmadan söz bulmadan mezârın,

İnkâr etme ne olur dile gelsin nazârın,

O zamânı kim bilir? bugün değilse yârın,

Misâl sana kâr etmez,ver desen de veremem.

***

Eğer idrâkın varsa,o vakit dinle beni,

Renkten renge ayırmak hayat bulma nedeni,

Nasıl târif eylersin seni senden edeni,

Tek bildiğim Mevlâdır,yor desen de yoramam.

***

Mâdem dirilik sâhi,ölüm ise yalancı,

Bizden bile yakındır,ecel nasıl yabancı? 

Her inançtan âlâdır Hak teâlâ inancı,

Eğer ondan uzaksan var desen de varamam.

***

''''Ben insânı yarattım,Şimdi arzda halife'''',

Binin birden farkı yok dönüp gelsin elife,

Mirâs kalan zamândır halef ile selefe,

Emânet bu saltanât sür desen de süremem.

***

Uyân artık uykudan,uyku seni boğmadan,

Anlar şâhidin olsun tân mahşere doğmadan,

Sevâp eyle mizânı günâh ona sığmadan,

Benim hâlim nicedir,sor desen de soramam.

***

Diyecektir O Mevlâ,ne eyledin dünyâda,

Hangi yüzle burdasın,yüzün var mıdır yada,

Utansan da nâfile kurtuluş yok hayâda,

Al silâhı eline,vur desen de vuramam.

***

''''Kimi var ki şöyle der,keşke turâb olaydım'''',

Bir fidana gireydim yerde harâb olaydım,

Yâhut,Öyle pişmânım,affet Yâ Râb Öleydim,

Artık sende ahrazsın,yer desen de yeremem.

****', 'Şu ilâhi kaderde yüküm aşktan ibâret, Öyle bir yoldayım ki dur desen de duramam. Maksat yaşamak değil fâni cânı ziyâret, Aciz kalan bedeni s...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/biz-omru-biraktik-her-gun-yeni-bir-omur-giyeriz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
