INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mızrap - Mızrak', 'mizrap-mizrak-necat-gundem-fygzn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sazın mızrabıyla gel

Türkü kadar

Hasretliğinle

Yanıklığınla

Gel

Ne duruyorsun

Savaşın mızrağıyla git

Kan kadar 

Nefretinle

Öfkenle 

Git

Ne duruyorsun.', 'Sazın mızrabıyla gel Türkü kadar Hasretliğinle Yanıklığınla Gel Ne duruyorsun Savaşın mızrağıyla git Kan kadar  Nefretinle Öfkenle  Git Ne d...', ARRAY['Türk Edebiyatı','Şiir','Necat Gündem']::text[], 8.5, '{"poet":"Necat Gündem","poet_slug":"necat-gundem","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mizrap-mizrak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerde', 'nerde-necat-gundem-rkcnw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nerde elleri  insanlığın

Nasır bağlayacak kadar

Çalışacak

Barış için.

Nerde elleri insanlığın

Güneşi kaldıracak

Bitmeyecek

Güzel bir gün aydınlığı için

Ve nerde yüreği insanlığın

Hep cesaretli olacak

Umutları için.', 'Nerde elleri  insanlığın Nasır bağlayacak kadar Çalışacak Barış için. Nerde elleri insanlığın Güneşi kaldıracak Bitmeyecek Güzel bir gün ayd...', ARRAY['Türk Edebiyatı','Şiir','Necat Gündem']::text[], 8.5, '{"poet":"Necat Gündem","poet_slug":"necat-gundem","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/nerde-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cep', 'cep-necat-gundem-n9n4t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gülücüğü yakalasın gözlerin

Üşümüş donuk bir bakışı

Koyarken cebine 

Isınmaya başlamıştır ellerin

Doğacağı yakındır

Üşümemiş güneşlerin.

Günlerinin hırsızlığındaki

Para babalarının 

Şerefsizliğini de koy cebine

O da dursun

Cebinin herhangi bir köşesinde

Anlamadın mı hala çocuk

Niye doldurdun ceplerini

Elek artığı şeylerle

Sen daha güzel yaşa diye

Satıver sonra cebini eskiciye

Söküğü yaması bol elbisenle

Birlikte.', 'Gülücüğü yakalasın gözlerin Üşümüş donuk bir bakışı Koyarken cebine  Isınmaya başlamıştır ellerin Doğacağı yakındır Üşümemiş güneşlerin. Gün...', ARRAY['Türk Edebiyatı','Şiir','Necat Gündem']::text[], 8.5, '{"poet":"Necat Gündem","poet_slug":"necat-gundem","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cep-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yılan', 'yilan-orhan-mahir-kizilboga-v82rg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kırmızı bir saatti

Geceye yaklaşıyordu zaman

Bir serçe havalandı çınarımdan 

Bir yaprak özgür bıraktı 

Kendini ölümüne

Karardı gökyüzü

Çirkin bir yılanın nefesi gibi

Salıncak kopuverdi düşlerimden 

Savaş verdim gözlerin için 

Savaş verdim düşlerim için

Ve sen 

Koynumda beslediğim gece gibi 

En mahrem yerimden 

Vurup gittin', 'Kırmızı bir saatti Geceye yaklaşıyordu zaman Bir serçe havalandı çınarımdan  Bir yaprak özgür bıraktı  Kendini ölümüne Karardı gökyüzü Çirki...', ARRAY['Türk Edebiyatı','Şiir','Orhan Mahir Kızılboğa']::text[], 8.5, '{"poet":"Orhan Mahir Kızılboğa","poet_slug":"orhan-mahir-kizilboga","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yilan-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz', 'guz-orhan-mahir-kizilboga-xb0vr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dökülen yapraklardır

Belki de Güz''ü güzel yapan

Yada sürüklemesidir 

Yağmurun kaldırımlar boyunca

Düşlerimi...', 'Dökülen yapraklardır Belki de Güz''ü güzel yapan Yada sürüklemesidir  Yağmurun kaldırımlar boyunca Düşlerimi......', ARRAY['Türk Edebiyatı','Şiir','Orhan Mahir Kızılboğa']::text[], 8.5, '{"poet":"Orhan Mahir Kızılboğa","poet_slug":"orhan-mahir-kizilboga","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/guz-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-zafer-zengin-etnika-2r9tq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Merhaba ile başlar

Dostluklar

Dört mevsim sürer düşler

| ışıldıyor memleketim 

yüzü güleç 

ve sıcak 

ne güzel 

bu memlekette 

yaşamak |

Başkadır

Anadoludan olmak

| Seni gördüm

  Gülen bebelerin yüzünde |

Gördüm ki; Gül/dün

1 Temmuz 2004 '' Yüzü güleç memleketin ''', 'Merhaba ile başlar Dostluklar Dört mevsim sürer düşler | ışıldıyor memleketim  yüzü güleç  ve sıcak  ne güzel  bu memlekette  yaşamak | Başk...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yasamak-90-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Babanın Günüyle Diyaloğu', 'bir-babanin-gunuyle-diyalogu-necat-gundem-r9zy2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ekmek soğanla çorbanın

Soframdan

Derdin tasanın işsizliğin

Kafamdan

Yine eksik olmadığı

Yeni gün; 

Söyle hele

Bugün günlerden nesin

Adın ne

Ötekilerden farkın ne

Diğer gündaşların gibi 

Bütün yaşamımı

Bana söyleyeceğin 

Bir merhaba ve elvedaya mı sığdıracaksın

Yoksa 

Umutlarımın kapısını mı bana aralayacaksın

Hiçbirini yapmayıp da

Defol mu diyeceksin

Ardına kadar açtığın ölüm kapısını göstermekle

Ama bil ki ey günüm

Yiğitlik mertlik demek

Dürüstlük demek

Ne diyeceksen de artık

Çocuklarım beni evde beklemekte

Ağlamasınlar artık

Gözyaşlarına yazık

Ekmek yerine miras diye 

Çocuklarıma bırakacağım

Ama benden çaldığın umutlarımı

İyisi mi ver artık

Sen yoluna akşam karanlığına

Bense bir sonraki sabahıma

Pırıl pırıl güneşime.', 'Ekmek soğanla çorbanın Soframdan Derdin tasanın işsizliğin Kafamdan Yine eksik olmadığı Yeni gün;  Söyle hele Bugün günlerden nesin Adın ne ...', ARRAY['Türk Edebiyatı','Şiir','Necat Gündem']::text[], 8.5, '{"poet":"Necat Gündem","poet_slug":"necat-gundem","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bir-babanin-gunuyle-diyalogu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olumsuzluğu Olmayan', 'olumsuzlugu-olmayan-huseyin-sigirtmac-qjy4f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Olumsuzluğu olmayan,

Bir diyara sürün beni.

Güzelliği hiç solmayan,

Bir Sultana verin beni.

Ne olsun aç ve susuzu,

Ne ezsin güçlü güçsüzü.

Dünya görmesin mutsuzu,

Dost tahtına serin beni.

Üzüntüyü görmesin göz.

Kışları kovsun her yaz.

Benlik bitsin diyelim biz.

Uygarlıkla görün beni.', 'Olumsuzluğu olmayan, Bir diyara sürün beni. Güzelliği hiç solmayan, Bir Sultana verin beni. Ne olsun aç ve susuzu, Ne ezsin güçlü güçsüzü. D...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olumsuzlugu-olmayan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umuttu onun adı...', 'umuttu-onun-adi-yusuf-ziya-leblebici-jsgqm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kilitlenmiş gözleri buz gibiydi elleri

Omuza alınınca kar gibiydi kefeni

Umuttu onun adı yarına az kalmıştı

Davasının uğruna canı çıkarılmıştı

Sağa sola sordular anasını buldular

Sahip çıkan olunca tabutunu koydular

Umuttu onun adı yay misali kaşları

Yerinden bir kalkınca tay gibiydi adımı

Anasının feryadı yıktı dağları taşı

Evladın acısıyla aktı gözünün yaşı

Umuttu onun adı güneşine az vardı

Zapdetmek zor olsa da içinde umut vardı

Söğütlerin yanında yatırdılar toprağa

Umudun yollarında dostları çıktı yola', 'Kilitlenmiş gözleri buz gibiydi elleri Omuza alınınca kar gibiydi kefeni Umuttu onun adı yarına az kalmıştı Davasının uğruna canı çıkarılmış...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/umuttu-onun-adi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sencil Mısralı Şiir', 'sencil-misrali-siir-necat-gundem-9and1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerinin Okyanusunda

Bir Vapurum ben

Kaptanı da 

Rotası da 

Sevgili sen

Beni derin rüyalara 

Sürükleten de 

Rüyalarımdan uyandıran da sen

Beni umutlandıran 

Kahreden 

Kendini özleten de 

Ve bıktıran da

Her daim sen

Neme nem bir şiir ki bu

Hep sencil olan

Beni düşünmeyen

Yarıda bırakayım da

Aklı başına gelsin

Sencil mısraların.', 'Gözlerinin Okyanusunda Bir Vapurum ben Kaptanı da  Rotası da  Sevgili sen Beni derin rüyalara  Sürükleten de  Rüyalarımdan uyandıran da sen ...', ARRAY['Türk Edebiyatı','Şiir','Necat Gündem']::text[], 8.5, '{"poet":"Necat Gündem","poet_slug":"necat-gundem","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sencil-misrali-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünün Ardından...', 'dusunun-ardindan-mehmet-seyidhasanoglu-xdspb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen miydin? 

Dün gece kapımı çalan! 

Çaldıktan sonra apansız karanlığa kaçan,

Düşünden uyandırıp beni; 

Senli düşümü sensiz bırakan! 

Boş bir kuşku muydu bu? 

Yoksa; 

Ben miydim sebepsiz senden kuşkulanan? 

O güzel düşü, senli düşü....

zamansız sonlandıran....

Sen miydin? 

Bu sabah yanımda oturan! 

Yanımda oturupta aklımı başımdan alan,

Kanımın her damlasına portreni çizip! 

Sonra da, beni sensizliğe hapseden,

-ve

Orada bir başıma bırakan! 

Yoksa; 

Yanımda oturan sen değilmiydin? 

Gerçekten çok uzak bir düş müydü yani! 

Kulağıma sevgi sözcükleri fısıldayan,

Beni umuda boğan! 

Daha sonra da yalnız bırakıp beni; 

Sonsuzluğa kaçan! 

Sen değil miydin? .....

Buda mı?  Bir kuşkuydu düşünde gördüğüm,

Düşünün ardından düşündüğüm! .....

               

                    18.05.2002 / Cumartesi', 'Sen miydin?  Dün gece kapımı çalan!  Çaldıktan sonra apansız karanlığa kaçan, Düşünden uyandırıp beni;  Senli düşümü sensiz bırakan!  Boş bi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Seyidhasanoğlu']::text[], 8.5, '{"poet":"Mehmet Seyidhasanoğlu","poet_slug":"mehmet-seyidhasanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dusunun-ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Nedir', 'ask-nedir-ahmet-turan-altunsu-vhzio', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşk nedir, diye sormuşlar bir mecliste Hayyam’ a, 

Hayyam, tereddütsüz: ‘’tendeki fısıltıdır’’ demiş…

-Ya gözlerdeki ve dillerdeki o ifadeler? ... 

Hayyam munisçe bakmış ve sadece gülümsemiş! ..', 'Aşk nedir, diye sormuşlar bir mecliste Hayyam’ a,  Hayyam, tereddütsüz: ‘’tendeki fısıltıdır’’ demiş… -Ya gözlerdeki ve dillerdeki o ifadele...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ask-nedir-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bî Râzıyım', 'b-r-ziyim-ahmet-turan-altunsu-k0yqs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni sevmek suçsa eğer ey sevgili, râzıyım…

Mızrabın vurduğu telde,bir aşığın sazıyım.

Nağmeler hıçkırıyorsa eğer sazın dilinden; 

O dilden bir soluğum, lâkin ondan bî râzıyım! ..', 'Seni sevmek suçsa eğer ey sevgili, râzıyım… Mızrabın vurduğu telde,bir aşığın sazıyım. Nağmeler hıçkırıyorsa eğer sazın dilinden;  O dilden ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bi-raziyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Biliyorum**', 'biliyorum-kubilay-enginol-arndu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biliyorum

Sen, gelince

Ayrılık korkusu sinecek içimize

Biliyorum

Gözlerinden sevgi akacak yüreğime

Ellerini birdaha hiç 

Bırakmıyacağım

Senelerin hasreti ile sarılacağım,sarılacağım

Sevinç gözyaşları nöbeti devralacak

Üzüntü gözyaşlarından

Ve hiç ayrılmayacağız

Biliyorum', 'Biliyorum Sen, gelince Ayrılık korkusu sinecek içimize Biliyorum Gözlerinden sevgi akacak yüreğime Ellerini birdaha hiç  Bırakmıyacağım Sene...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/biliyorum-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşil sonbahar', 'yesil-sonbahar-taner-arda-k07tm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hala yeşil kalmış bir sonbaharım ben

Ne sıcak yaz günlerinden

Nede muhtemel karlı günlerden 

….vazgeçemiyorum

Ruhum en genç sesiyle haykırırken

Aynalar karşısında suskun kalıyorum

Kabul, hayallerim yıkıldı bir bir

Ama ümitlerim hala direniyor..

Bana kalırsa, çok şey de istememiştim 

…….aslında…….

Ne malda gözüm vardı ne de mülkte..

İnsanın içini ısıtan parlak bir gözde 

Bazen bir parmağın elime dokunuşunda aradım,

O hiç vazgeçemeyeceğim zenginliği.', 'Hala yeşil kalmış bir sonbaharım ben Ne sıcak yaz günlerinden Nede muhtemel karlı günlerden  ….vazgeçemiyorum Ruhum en genç sesiyle haykırır...', ARRAY['Türk Edebiyatı','Şiir','Taner Arda']::text[], 8.5, '{"poet":"Taner Arda","poet_slug":"taner-arda","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yesil-sonbahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duyarsızlık', 'duyarsizlik-zulfikar-yapar-kaleli-t5h01', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Olmuşuz  vurdum duymaz

Kuşlar düşer duymayız

Köyün var köye uymaz

Yaşlar düşer duymayız

Tahrifat köşe köşe

Sevdam var sığmaz düşe

Yıldızdan yıldız başa

Taşlar düşer duymayız

Dileklerim yüceye

Meydan kaldı cüceye

Yarı çıplak geceye

Düşler düşer duymayız

Mülküm hayal ardında

Yok mu dedik sordun da

Bu erenler yurdunda

Başlar düşer duymayız', 'Olmuşuz  vurdum duymaz Kuşlar düşer duymayız Köyün var köye uymaz Yaşlar düşer duymayız Tahrifat köşe köşe Sevdam var sığmaz düşe Yıldızdan ...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/duyarsizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanıdık Gelir', 'tanidik-gelir-mustafa-tugrul-kosar-xldoi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu aylar,seneler olur zamanla 

Bir bir takvimlerden yaprak eksilir 

Her günün altında ezilir kalbim 

Duyarsan çığlığı tanıdık gelir 

Tam olmaz herşeyin acır bir yanın 

Bu yarım sevgiyi bulur her anın 

İkiye bölünüp atılan canın 

Boşluğu bir yerden tanıdık gelir 

İlk olmaz ki bu dram neleri bekler 

Gözünün önünde kaç sevgi biter 

Çözülür elleri birisi gider 

Kalanın bakışı tanıdık gelir 

Yandıkca bedenim tüter dumanı 

Rüzgara kapılır bulur alnını 

Kurcalar bakarsın o an aklını 

Kokusu bir yerden tanıdık gelir 

Duygulu şarkılar dokunur sana 

Korkulu çığlıklar tutunur sana 

Kimsesiz her çocuk dert olur sana 

Günahı bir yerden tanıdık gelir 

Kim çıkar karşına nerden bilirsin 

Belki bir deliye karşı gelirsin 

Yıpranmış yüzüne bakar geçersin 

Gözleri bir yerden tanıdık gelir 

Bakışı bir yerden tanıdık gelir', 'Bu aylar,seneler olur zamanla  Bir bir takvimlerden yaprak eksilir  Her günün altında ezilir kalbim  Duyarsan çığlığı tanıdık gelir  Tam olm...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tuğrul Koşar']::text[], 8.5, '{"poet":"Mustafa Tuğrul Koşar","poet_slug":"mustafa-tugrul-kosar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/tanidik-gelir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hele Bir Düşmeye Gör', 'hele-bir-dusmeye-gor-nazife-abayli-9akij', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hele bir düşmeye gör,

Nasıl çiğnerler seni,

Nasıl da binerler tepene,

Dost bildiklerin,kardeş dediklerin..

Varsa elinde,avucunda,cebinde,

Gözleri malındadır ve de mülkünde,

Eğer batarsan bir gün denizin dibine,

İsyan ettirirler imanına,dinine..

Dünyaya kahpe diyenler,

İnsanlığa sövenler,

Onuru uğruna mahpuslarda çürüyenler,

Canına kıyıp gidenler,neyin bedelini ödediler..

Bakmayın dostlar yazdıklarıma,

Kızgınlığım yok insan olan insana,

Tüm sözlerim insanı sırtından vuranlara,

İsyan etsemde zaman zaman,

Yine de severim dostu da düşmanı da..', 'Hele bir düşmeye gör, Nasıl çiğnerler seni, Nasıl da binerler tepene, Dost bildiklerin,kardeş dediklerin.. Varsa elinde,avucunda,cebinde, Gö...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hele-bir-dusmeye-gor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MeTReS,', 'metres-mine-ozdemirtas-vpgws', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ekoseli akşamların alacasına sermeliydiniz yüreğinizi

puantiyeli sabahlara  uyanmaya kim zorladı sizi? 

şemsiyelerin ıslak desenlerine sığındınız madem

ve madem ki, paltonuzun aç gözlü cebine

itinayla katlayıp koydunuz gölgenizi,

o halde dikkatle saymak zorundasınız

ayaklarınızın ucuna basarak ve tutarak nefesinizi

asma köprüden iki yakaya kaç kere geçtiğinizi.

çift yüzlü kartları destede sarhoş kardığınız an

akan suya düşmüş bir parmak izi

hem onurunuzu alacaktır elinizden, hem de metresinizi.

30/06/2004', 'ekoseli akşamların alacasına sermeliydiniz yüreğinizi puantiyeli sabahlara  uyanmaya kim zorladı sizi?  şemsiyelerin ıslak desenlerine sığın...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/metres-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl', 'nasil-memet-karabalik-mh1mg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'nasıl sevilir bir insan,

yüreğin akla isyanı mıdır? 

kavuşursan dırdırıdır sana kalan,

kaçarsa elemdir yüreğine!', 'nasıl sevilir bir insan, yüreğin akla isyanı mıdır?  kavuşursan dırdırıdır sana kalan, kaçarsa elemdir yüreğine!...', ARRAY['Türk Edebiyatı','Şiir','Memet Karabalık']::text[], 8.5, '{"poet":"Memet Karabalık","poet_slug":"memet-karabalik","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/nasil-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşme', 'dusme-memet-karabalik-dq5kc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'serin gecelerin bahar esintisi sarıyor caddeleri

elinde birasıyla adam

meydan okuyor sarhoş gecelere

gökten üç elma düşmüyor artık

bombadır düşen

üç milyon korku sarıyor atmosferi

üç milyon çocuk korkuyor

kaç tane üçü ölüyor kimbilir

gökten üç elma düşmüyor artık

çocuklardır yülselen göğe', 'serin gecelerin bahar esintisi sarıyor caddeleri elinde birasıyla adam meydan okuyor sarhoş gecelere gökten üç elma düşmüyor artık bombadır ...', ARRAY['Türk Edebiyatı','Şiir','Memet Karabalık']::text[], 8.5, '{"poet":"Memet Karabalık","poet_slug":"memet-karabalik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dusme-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu ben değilim', 'bu-ben-degilim-aysel-coban-bxpr9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'BU BEN DEĞİLİM

Bu ben değilim

Hırçın, haşin, huysuz olan

Bir aysbergin görünmeyen yüzü bende

Gördüklerin korkutmasın seni

O dağın yüreği, soğuk suların altında kaynar

Kök salmış korkularım,

İnsancıl hislerden uzak kalmasın ister

Bu ben değilim

Küskün, yılgın, soğuk kalan

Bir kozanın örülüşü yüreğimde

Bildiklerin şaşırtmasın seni

O kelebeğin uçuşu, konacağı alp yıldızını arar

Sürecek ömrüm,

Gün yüzüne çıkmayı bekleyen aşkı tatmak ister

Bu ben değilim

Anlaşılmaz, güvensiz, takıntılı yaşayan

Bir güvercin ürkekliği üzerimde

Öğrendiklerin vazgeçirmesin seni

O güvercinin kanadını, sevgisiyle onaracak kuşbaz gerekir.

Özgürlük için çarpan kalbim,

Gökkuşağı renginde sana uçmak ister.', 'BU BEN DEĞİLİM Bu ben değilim Hırçın, haşin, huysuz olan Bir aysbergin görünmeyen yüzü bende Gördüklerin korkutmasın seni O dağın yüreği, so...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çoban']::text[], 8.5, '{"poet":"Aysel Çoban","poet_slug":"aysel-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bu-ben-degilim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehirler ve Nefret', 'sehirler-ve-nefret-memet-karabalik-yx2kg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'şehirlerden kaçtık

yağmurun kesildiği günlerden beri

gündüzün işkence verdiği

gecenin ağlattığı zamanlardan beri

aşıklar gece ihanete başladığından

çocuklar ağlamaktan korktuklarından beri

analar yol gözlemeye başlayalı

babalar sessiz sessiz ağlayalı 

sırtını döndüğünde bıçaklandığından beri

kaçtık

bir şehri yaşatamayız artık

içimizde kocaman bir şehir nefreti

şehirde kocaman bir insan nefreti', 'şehirlerden kaçtık yağmurun kesildiği günlerden beri gündüzün işkence verdiği gecenin ağlattığı zamanlardan beri aşıklar gece ihanete başlad...', ARRAY['Türk Edebiyatı','Şiir','Memet Karabalık']::text[], 8.5, '{"poet":"Memet Karabalık","poet_slug":"memet-karabalik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sehirler-ve-nefret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen çektin çekeli kendini benden', 'sen-cektin-cekeli-kendini-benden-mahmut-murat-demir-c3v5p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen cektin kendini benden,

bir yaradan hançer çeker gibi.

Oysa girerken değil de çekerken ne çok acıdı bir bilsen,

Akan acıyı bir silsen tenimden, yaramdan.

Yatağım uyumuyor sensiz artık,

Nefesim duyulmuyor kimsesiz artık,

Bedenim yaşamaz oldu, bil bunu.

Sen kendini çektin çekeli benden.', 'Sen cektin kendini benden, bir yaradan hançer çeker gibi. Oysa girerken değil de çekerken ne çok acıdı bir bilsen, Akan acıyı bir silsen ten...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Murat Demir']::text[], 8.5, '{"poet":"Mahmut Murat Demir","poet_slug":"mahmut-murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sen-cektin-cekeli-kendini-benden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoktun', 'yoktun-turkan-sevinc-g37ym', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yolu yokuş bir yolun sonundaydı gözlerimiz.

ben uzanabildiğin kadar masum,

sense, yarım kalıyordum eksilmelere.

bir iç çekiş değildi bu; 

kendi yanılmalarım,

yansımalarım,

ve kırgınlıklarımın üçgenininde çevriliydi yüreğim.

Yoktun! ! ! 

ben saatlere uzak, 

günlere tutsak,

ve tüm ihanetlere yasaktım sevgilim! ...

yoktun! .... 

bu yüzden yanılıyordum belkide...', 'Yolu yokuş bir yolun sonundaydı gözlerimiz. ben uzanabildiğin kadar masum, sense, yarım kalıyordum eksilmelere. bir iç çekiş değildi bu;  ke...', ARRAY['Türk Edebiyatı','Şiir','Türkan Sevinç']::text[], 8.5, '{"poet":"Türkan Sevinç","poet_slug":"turkan-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yoktun-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hünkar Dağlı''ya Selam Olsun', 'hunkar-dagli-ya-selam-olsun-fatih-taskin-2zfm9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Selam Olsun 

Davama dava olan 

Dava da davalanan 

Davasıyla davalandıran 

Hünkar Dağlı ya selam olsun 

Dostluğuma dost olan 

Dostluğumla dostlanan 

Dostluğuyla dostlandıran 

Hünkar Dağlı ya selam olsun 

Yarama yara olan 

Yaramla yaralanan 

Yarasıyla yaralandıran 

Alemin kralına selam olsun..... 

haziran 2004 

siyah bereli......', 'Selam Olsun  Davama dava olan  Dava da davalanan  Davasıyla davalandıran  Hünkar Dağlı ya selam olsun  Dostluğuma dost olan  Dostluğumla dos...', ARRAY['Türk Edebiyatı','Şiir','Fatih Taşkın']::text[], 8.5, '{"poet":"Fatih Taşkın","poet_slug":"fatih-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hunkar-dagli-ya-selam-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk Oldum', 'cocuk-oldum-edip-caki-j4w1c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gün düştü umutlarımın doğduğu yere                                     Eksik verildi çocukluğumun tüm ölü kuşları                       Zamandan çalındı ölü uykularım                                          Hüznüm doğrandı bezirgan sofralarına                             Diyarbekir sokaklarında çocuk oldum tüm asiliğimle Gökkuşağının renkleriyle boyadım sevincimi', 'Gün düştü umutlarımın doğduğu yere                                     Eksik verildi çocukluğumun tüm ölü kuşları                       Zama...', ARRAY['Türk Edebiyatı','Şiir','Edip Çakı']::text[], 8.5, '{"poet":"Edip Çakı","poet_slug":"edip-caki","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/cocuk-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecikti Gülüşlerimiz', 'gecikti-guluslerimiz-turkan-sevinc-rcv0o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yol yokuş...

yokuşlar sonsuz...

sonunu göremediğin,

sonunu bilemediğin,

gittikçe uzayan bir yokuş.

hangi noktasındayım zamanın bilemiyorum.

unutuluyor en güzel ezginin sözleri.

ve çoçukça geçiyor özlemelerim

yaşayamadığım sevmelere sayıyorum

bu çocuksu günlerimi! ... 

zaten bir çocuk  yüreği nasıl anlam verebilirdiki talan olmuş bir kente! 

soluğunu kestiler heyecanlarımızın! 

ve gecikti gülüşlerimiz...

acil gönderilmesi gereken bir mektupta

eksik birer pulduk işte! 

ve yitip gittik öylece...', 'Yol yokuş... yokuşlar sonsuz... sonunu göremediğin, sonunu bilemediğin, gittikçe uzayan bir yokuş. hangi noktasındayım zamanın bilemiyorum. ...', ARRAY['Türk Edebiyatı','Şiir','Türkan Sevinç']::text[], 8.5, '{"poet":"Türkan Sevinç","poet_slug":"turkan-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gecikti-guluslerimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Martı', 'beyaz-marti-zafer-donmez-tmw71', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey mavi gökteki beyaz martı

Aldırma bulutlara 

Sen süzül şiir gibi her daim 

Yerde sürünenlere inat

Bırak kanadını kırmak için

Seni de kendileri gibi yapmak için 

Daha mutlu sürünmeye

Ömrünü verenleri

Süzül bembeyaz şiirler gibi

Gün batımında huzur

Mavi kızıl ufuklarda 

Gün doğumunda umut ol güneşle 

Işık ol, su ol, sevgi ol,

Güneş ol ya da deniz kimi zaman

Aydınlat gönülleri 

Sen süzül mavi gökte şiirler gibi

Yüzyılların şarkıları kanatlarında 

Ölümsüz aşklar gizli tükenmemiş gönüllerde, 

Özgürlük oldun, sevda oldun bak dillerde,

Süzül ki ağlamasın bu deniz,

Kuru gözler nemlensin yeniden,', 'Ey mavi gökteki beyaz martı Aldırma bulutlara  Sen süzül şiir gibi her daim  Yerde sürünenlere inat Bırak kanadını kırmak için Seni de kendi...', ARRAY['Türk Edebiyatı','Şiir','Zafer Dönmez']::text[], 8.5, '{"poet":"Zafer Dönmez","poet_slug":"zafer-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/beyaz-marti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
