INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** O r t a...Y a ş...V a s i y e t i m', 'o-r-t-a-y-a-s-v-a-s-i-y-e-t-i-m-metin-eser-md9yl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Akşamın loş saati, tutuştu kucağımda,

Hep beklenen o ses, koşuştu kulağımda,

Bir kederdir içimde, günlerdir gizlediğim, 

Orta yaş vasiyetim, budur şimdi dileğim,

Canım emanet zaten, sahibine gidecek,

Şu ceset elbisesi, o toprağa girecek,

Bekleyen hayvanatın, nasibi varsa eğer,

Her biri bir parçayı, rızık bilip yiyecek.

Dünya hiç derdim değil, gözüm arkada kalmaz, 

Malım mülküm ve param, zaten bana yar olmaz,

Üşüşen mirasçılar, gözleri varsa eğer,

Her biri ganimeti, sahiplenmezse olmaz.

Çoluk çocuğum garip, mağdur da olmasınlar,

Rabb bildiğim O Hakk''tan, bîhaber olmasınlar,

Günün birinde beni, çok sorarlarsa eğer,

Her biri dua etsin, sulu göz olmasınlar.

Alacaklarım varsa, fakire dağıtılsın,

Boçlularım çıkarsa; Oflu''ya aktarılsın,

Arkamdan kulun biri, kötü söylerse eğer,

Her biriniz sabretsin, mahşere bırakılsın. 

Sevdiğime bu sözüm, ardımdan yas bağlama,

Hatıraları düşün, yüreğini dağlama,

Kolay olmaz bilirim, hüzne düşersen eğer,

Bâkî hayatı düşün, göz yaşını çağlama.

Dostlarım unutmadım, sizleri anmam mı hiç,

Vallahi doyamadım, hatrınız kalmaz mı hiç,

Öyle günün birinde, akla gelirsem eğer,

Bir dua da siz buyrun, bu hakkım olmaz mı hiç.

Ey davam sona kaldın, sen emin ellerdesin,

Gün geldi ki daraldın, şimdi gönüllerdesin, 

Sen ki biraz üzülüp, kederlenirsen eğer,

Sabret ve bekle derim, ehil yüreklerdesin.

Ey emanet sahibi, sözlerim tamam oldu,

Her kim var ise bende, hakkım tüm helal oldu,

Vakit saat gelipte, canım istersen eğer,

Ruhum teslime hazır, Azrail bekler oldu. 

04.07.04 / Frankfurt', 'Akşamın loş saati, tutuştu kucağımda, Hep beklenen o ses, koşuştu kulağımda, Bir kederdir içimde, günlerdir gizlediğim,  Orta yaş vasiyetim,...', ARRAY['Türk Edebiyatı','Şiir','Metin Eser']::text[], 8.5, '{"poet":"Metin Eser","poet_slug":"metin-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/o-r-t-a-y-a-s-v-a-s-i-y-e-t-i-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Aşk', 'i-lk-ask-nur-elif-yilmaz-nggnd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ayağım kesildi yerden 

Bulutlarda uçuyorum

Güneşe yaklaşıyorum

Kızıl gömlekli ilk aşkım

Güneşten el sallar

Ulaşırım kızıl gömlekli aşkıma

Sevgimi teslim eder 

Sevgisini alırım

İnerim yeryüzüne 

Gün gelir güneş batıdan batar

İçinde kızıl gömlekli ilk aşkım.......', 'Ayağım kesildi yerden  Bulutlarda uçuyorum Güneşe yaklaşıyorum Kızıl gömlekli ilk aşkım Güneşten el sallar Ulaşırım kızıl gömlekli aşkıma Se...', ARRAY['Türk Edebiyatı','Şiir','Nur Elif Yılmaz']::text[], 8.5, '{"poet":"Nur Elif Yılmaz","poet_slug":"nur-elif-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ilk-ask-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarimi Tasvir Etmek', 'yarimi-tasvir-etmek-erdal-sayil-as0r2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kiraz alı dediğin,

Yarimin dudağıdır...

Aşkımın ateşiyle kanlanmış...

Narın tatlı pembesi,

Yanağında bahar çağıdır,

Sevdiğim utancıyla allanmış...

Elmanın mayhoş tadı,

Beğendiğim,

Bana yasak olan sanki; 

Kadınımın vuslatıyla canlanmış...

Lezzeti,

Damağımda, elimde,

Canımda, tenimde; 

Benliğimde kalmış...

Armudu benzer göremem,

Yarimin yuvarlaklıklarına...

O zaten bana değil,

Yabaniye,

Nasip olanmış...

Kızılcık o güzelin bana,

Çektirdiklerinden bir iz; 

Bir ağız dolusu boşalttığım,

Kanlı tükrüğüm sayılmış...

Ayva eğer,

O yari evdeşim,

Olarak alırsam; 

Yiyeceğim artık,

Olmayacakmış...', 'Kiraz alı dediğin, Yarimin dudağıdır... Aşkımın ateşiyle kanlanmış... Narın tatlı pembesi, Yanağında bahar çağıdır, Sevdiğim utancıyla allan...', ARRAY['Türk Edebiyatı','Şiir','Erdal Sayıl']::text[], 8.5, '{"poet":"Erdal Sayıl","poet_slug":"erdal-sayil","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yarimi-tasvir-etmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtibarın', 'i-tibarin-baykal-kaanalp-ec41j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'devrildi gözümde itibarın,kredin

sarsıldı güvenim,azaldı aşkım

