INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaralı Melek', 'yarali-melek-artist-tayfun-fmu5w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayata adım atar atmaz, dunya´ya bir melek olarak geldim

Hayat ilerledikçe, değerli meleği herkesin hizmetine serdim

Insanlara butun guzelliklerimi sundum

Durust oldum, guven verdim

Bana karsı yapılan çirkefliklere tanık oldum

Çirkef dolu insanlar benim en buyuk derdim 

Aşk hikayelerini okudum, izledim, oğrendim

Bana kızların birer melek olduklarını soylediler

Aşkı bulmak icin yılmadim cabaladım direndim

Meğerse bu yalan hikayesine inanan TEK bendim

Yalnızlığın acısını bir ben bilirim

karanlığın derinliğinde yapayalnız gecelerde

Allah´a dua ederim,bitsin bu işkenceler derim

Dilerim son bulur benim acılarım yalan nimetlerde

Birzamanlar MELEK olarak dunya´ya geldim

Acımasız dunya´da acımasız insanlar tarafından hırpalandim

Bu dunya´yi bir MELEK icin cehennem bildim

Yalan, Bencil ve Sert bir dunya, bu kanaata vardım

Yolun yarısına geldim, tecrubeler edindim

Gereğinde sert, gereğinde tatlı olabilmeyi ogrendim

Kendimden olumsuz birsey kaybetmedim

Sadece lekelendim, ama O melek hala benim', 'Hayata adım atar atmaz, dunya´ya bir melek olarak geldim Hayat ilerledikçe, değerli meleği herkesin hizmetine serdim Insanlara butun guzelli...', ARRAY['Türk Edebiyatı','Şiir','Artist Tayfun']::text[], 8.5, '{"poet":"Artist Tayfun","poet_slug":"artist-tayfun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yarali-melek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şirin', 'sirin-zafer-zengin-etnika-r34tf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şirin

