INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarali Melek', 'yarali-melek-tayfun-kose-zzj68', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayata adim atar atmaz, dunya´ya bir melek olarak geldim

Hayat ilerledikçe, degerli melegi herkesin hizmetine serdim

Insanlara butun guzelliklerimi sundum

Durust oldum, guven verdim

Bana karsi yapilan çirkefliklere tanik oldum

Çirkef dolu insanlar benim en buyuk derdim 

Ask hikayelerini okudum, izledim, ogrendim

Bana kizlarin birer melek olduklarini soylediler

Aski bulmak icin yilmadim cabaladim direndim

Megerse bu yalan hikayesine inanan TEK bendim

Yalnizligin acisini bir ben bilirim

karanligin derinliginde yapayalniz gecelerde

Allah´a dua ederim,bitsin bu iskenceler derim

Dilerim son bulur benim acilarim yalan nimetlerde

Birzamanlar MELEK olarak dunya´ya geldim

Acimasiz dunya´da acimasiz insanlar tarafindan hirpalandim

Bu dunya´yi bir MELEK icin cehennem bildim

Yalan, Bencil ve Sert bir dunya, bu kanaata vardim

Yolun yarisina geldim, tecrubeler edindim

Gereginde sert, gereginde tatli olabilmeyi ogrendim

Kendimden olumsuz birsey kaybetmedim

Sadece lekelendim, ama O melek hala benim', 'Hayata adim atar atmaz, dunya´ya bir melek olarak geldim Hayat ilerledikçe, degerli melegi herkesin hizmetine serdim Insanlara butun guzelli...', ARRAY['Türk Edebiyatı','Şiir','Tayfun Kose']::text[], 8.5, '{"poet":"Tayfun Kose","poet_slug":"tayfun-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yarali-melek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Kafa Tutmak Hiçe', 'aska-kafa-tutmak-hice-derin-oger-ii1xj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'söz senden açılınca

kan ağlar kalbim,gül sürerim üstüne

kaç kez kaderimizi içeriz de başbaşa

kara çalmam orama burama

gönül yıkılsa da içe

derdin can sızısı,yürek cilası

andıkça sayıkladıkça tozu alınan

özlemi acıyı kederi biriktirdikçe olgunlaşan

hani ayrılık zarar vermez derler ya özlemle yıkanana

hüznü çökse de içe

göğsüm kaderimin ortağı

sana sevgim içimin en ücra köşesinde

her gece sarılırım kalbimin yaramaz çocuğuna

varsın hayalin dolsun da göz göz rüyalarıma

yaşlar da dökülüversin içe

sen boğazımda yürüyen 

sen içimde dalga dalga coşup durulan su

öylesine yudum yudum içiyor ki sevdiğin seni

sınır tanımaz fırtınalar büyüklüğünde

ah gökyüzüm aşka kafa tutmak hiçe...........', 'söz senden açılınca kan ağlar kalbim,gül sürerim üstüne kaç kez kaderimizi içeriz de başbaşa kara çalmam orama burama gönül yıkılsa da içe d...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aska-kafa-tutmak-hice-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Sana Geldim-', 'sana-geldim-semsettin-kaya-sey8t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'tarihin  karanlık derinliklerinden geldim

bin yıllık susamışlığıyla yüreğim

kapında yüzü kara bir dilenci

aşkına aç, varlığına susamış

şiirler biliyor suskunluğum

tarihin ayrıntılarında kaybolanlardan

masallardan geçtim, karanlık zamanlarda

yol boyu insanlar vardı ve kemik olmuş eski sevdalar

sahifeler bıraktım gerimde

yaprak yaprak geçtim bütün efsaneleri

çölün sessizliğinde Mecnun’la yıldızları saydım

Leyla’sına hasret

her çağda insanlar vardı ağlayan çağıran

yol boyu ülkeler, kavgalar ve yeni dinler

durmadım, inanmadım senden ötesine

yürüdüm yüzyıllar boyu

sarp dağlardan geçerken içimde sevdan vardı, kor gibi

kaç ömür yaşadım gelirken sana

neleri geçtim, neler kaldı ardımda

gözlerim suskun, ayaklarım yorgun

aşkına geldim

kapın Sırat Köprüsü şimdi

sana ait bir yüreğim var taşıdığım

itme beni tarihin derinliklerine

beni zamanına al, yani yanına

06.07.2004

Ankara

semsettin.kayahotmail.com', 'tarihin  karanlık derinliklerinden geldim bin yıllık susamışlığıyla yüreğim kapında yüzü kara bir dilenci aşkına aç, varlığına susamış şiirl...', ARRAY['Türk Edebiyatı','Şiir','Şemsettin Kaya']::text[], 8.5, '{"poet":"Şemsettin Kaya","poet_slug":"semsettin-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sana-geldim-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili', 'sevgili-cemil-neseliler-4pmem', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zülüflerini taktın sürüklüyorsun beni sevgili 

Hesapsız kitapsız erişlerdeyim ey sevgili 

Haykırışımı duyuyor musun feryaddayım 

Arzum dileğim ümidim yakarışım tek; 

Seninleyim sevgili... 

Düşler aleminde, sükût bahçesinde kuşlar özgür 

Koyunlar bir başka sıcak, bir başka yaban 

Özlem, vaha kadar ıslak, Afrika kadar sıcak 

Kırlarda yürüyorum ellerim açık, ayaklarım çıplak; 

Benimlesin sevgili... 

Uğuluğulum diplerden gelen ürperişlerinle 

Depremlerin kelimelerimi parçaladı figandayım 

Hasretine alışamadım, etim yangın, elim titrek 

İstemem ne dünya, ne ukba, ne ahret; 

İsterim seni sevgili...', 'Zülüflerini taktın sürüklüyorsun beni sevgili  Hesapsız kitapsız erişlerdeyim ey sevgili  Haykırışımı duyuyor musun feryaddayım  Arzum dileğ...', ARRAY['Türk Edebiyatı','Şiir','Cemil Neşeliler']::text[], 8.5, '{"poet":"Cemil Neşeliler","poet_slug":"cemil-neseliler","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevgili-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarınlar Senin', 'yarinlar-senin-cafer-tayyar-ozkan-x174a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geceler benim, 

Nefsim uykuya galip geldikçe...

Ağıtlar benim, 

Umudum zamana yenik düştükçe...

Sabah güneşi ikimize de 

Güzel doğsun sevgilim,

Dünyalar benim, 

Kalpte sevdan yaşadığı müddetçe.... 

Yarınlar senin,

Mantığın kalbine galip geldikçe...

Hüzünler senin,

Düşlerin gerçeğe yenik düştükçe...

Ümitler kalsın ikimize de

Huzur dolsun sevgilim,

Sevinçler senin,

Bedenin nefes aldığı müddetçe...

04 Nisan 2003 Ankara', 'Geceler benim,  Nefsim uykuya galip geldikçe... Ağıtlar benim,  Umudum zamana yenik düştükçe... Sabah güneşi ikimize de  Güzel doğsun sevgil...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yarinlar-senin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hareme Mesaj', 'hareme-mesaj-can-ceylan-lkuq0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akşamları yitikliğimizden utansın

Sabahları işte biz yaşıyoruz diye ineriz

Aynı minval üzre her zaman böyle denize

Harem pek alıngan

Biz çocukluğumuzsa mesut

İçimizde düğümlü şarkıların itisi bir yana

Tutkularımız boyut boyut

Her gurub vakti yelkenlerce fora şarkılarımız

Kahkahaların alay konusuyuz belki

Ama bütün bunlara ve size inat deniz

O kadar cana yakın dost, o kadar güzel ki

Sanki acılarımız amacımız

Istırabın en güzel şiirini yazarız sulara

Sarayburnu, Cihangir aşınmıştır temaşamızdan

Gönlümüze dar gelir marmara

Ne bir bekleyişin sabırsızlığı

Ne bir ayrılışın acılığı vardır içimizde

Biz sadece o anları yaşamak için hazırız

Gidiş geliş saatlerinizde

Sizin şüphelerinizin çıplaklığı okunur bakışlarınızdan

Bizim vapur saatlerinin mutluluğundan nemlidir gözlerimiz

İnan ki saat saat, dakika dakika, renk renk

Biz sadece Harem''i şarkılarımıza işleriz

Ellerinizin sıcaklığı, gözleriniz daha başka ılık

Anam, babam, kardeşim Metin, Füsun

Hani o katre misali bir gün bir şarkılık

Ruhunuz bu yaşantılardaki ıstırabı duysun

(Şairi:Zeki Ceylan

26 nisan 1960

İstanbul saat:8.30)', 'Akşamları yitikliğimizden utansın Sabahları işte biz yaşıyoruz diye ineriz Aynı minval üzre her zaman böyle denize Harem pek alıngan Biz çoc...', ARRAY['Türk Edebiyatı','Şiir','Can Ceylan']::text[], 8.5, '{"poet":"Can Ceylan","poet_slug":"can-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hareme-mesaj-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklamaz Kağıt Seni', 'aklamaz-kagit-seni-hatice-ari-re7ca', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yollarımda kin var,

Bulaşma yollarıma,

Kinim kadar keskindir,

Bu dava...

Dağlarımda ayaz var,

Tırmanma dağlarıma,

Boranlar seni yıkar,

Sanma sıcak bir dost,

Gençliğim beni yakar...

Ellerimde kan var,

Sarılma kollarıma,

Sıkılır boğulursun,

Kaşla göz arasında...

Kalemimde barut var,

Yaklaşma kağıdıma,

Allara bulanırsın,

Aklamaz kağıt seni...

Yüreğimde yol var,

Düşme sen yollarıma,

Engeldi mesafeler,

Büyük şehir,

Küçük aşklar,

Hadi şimdi yalvar; 

Büyümüşse bebek,

Oyuncak neye yarar? 

Kopmuşsa tüm bağlar,

Salıncak salınır mı,

Rüzgar boşa sallar,

Boşluk sallanır mı?', 'Yollarımda kin var, Bulaşma yollarıma, Kinim kadar keskindir, Bu dava... Dağlarımda ayaz var, Tırmanma dağlarıma, Boranlar seni yıkar, Sanma...', ARRAY['Türk Edebiyatı','Şiir','Hatice Arı']::text[], 8.5, '{"poet":"Hatice Arı","poet_slug":"hatice-ari","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/aklamaz-kagit-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DuLLuK,', 'dulluk-mine-ozdemirtas-js9yx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kayıp  boncuk 

yüzünden 

siz; 

Küçültmüş

olsanız da

göz bebeklerinizi; 

Benim 

umurumda 

bile değil

Abaküsümdeki 

parmak izi.

Mine Özdemirtaş', 'Kayıp  boncuk  yüzünden  siz;  Küçültmüş olsanız da göz bebeklerinizi;  Benim  umurumda  bile değil Abaküsümdeki  parmak izi. Mine Özdemirta...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dulluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AğLaMaK,', 'aglamak-mine-ozdemirtas-udyc6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İğne yapraklı çam ormanlarından mı geçti yolunuz? 

Ki! bu kadar yoruldunuz

Ne çok! mor hıçkırık biriktirmiş dirsekleriniz.

Salın zincirlerini kurtulursunuz.', 'İğne yapraklı çam ormanlarından mı geçti yolunuz?  Ki! bu kadar yoruldunuz Ne çok! mor hıçkırık biriktirmiş dirsekleriniz. Salın zincirlerin...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/aglamak-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MiLaT,', 'milat-mine-ozdemirtas-h0u21', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tarih öncesiydi bilmiyorsunuz

Maşa mangalı karıştırmadaydı.

Ve ateş sönmedeydi susuz.

Sonra siz geldiniz

Geceler kendini aydınlattı mumsuz.

Düşüyordu yamacınızdan çığlık

Eteğimdeki dantellere tutundunuz

Getirdiklerinizi gömdünüz bahçeme

Sıfırdan başlamakmış tek arzunuz

Öyle diyordunuz

O halde, Miladı satarım size

Ne veriyorsunuz?', 'Tarih öncesiydi bilmiyorsunuz Maşa mangalı karıştırmadaydı. Ve ateş sönmedeydi susuz. Sonra siz geldiniz Geceler kendini aydınlattı mumsuz. ...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/milat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İHaNeT ve İNaNNa nın LaNeTi,', 'i-hanet-ve-i-nanna-nin-laneti-mine-ozdemirtas-adqck', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kibele manastırına  gömüyorlar beni.

İzin verecek misiniz Dumuzi? 

Susmayın.

sizde susarsanız; 

zembereği boşalır İnanna nın

Ne Starte, ne İştar, ne Afrodit kalır

lanetim ki Venüse kadar uzanır.

Ningal e sormalısınız yattığım yeri.

Nanna nın hışmından; asırlardır 

O koruyor beni.

Şimdi; Kibele de zaman 

sanki karanlığın siyahına soyundu.

Yoksa! Nintu ihanet meşalesini

yeniden mi tutuşturdu.? 

Savunmazsanız kendinizi

yer altına  çağırmak 

zorunda kalacağımı sizi

biliyor olmalısınız Dumuzi.', 'Kibele manastırına  gömüyorlar beni. İzin verecek misiniz Dumuzi?  Susmayın. sizde susarsanız;  zembereği boşalır İnanna nın Ne Starte, ne İ...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ihanet-ve-inanna-nin-laneti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben jandarma komandoyum', 'ben-jandarma-komandoyum-umut-gungor-kw6dr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dağlara yazdırdım adımı,

Hainler birkaç adım atımı,

Vatanıma adadım canımı,

Ben jandarma komandoyum.

Bu dağlar benden sorulur,

Kim demiş Mehmet yorulur,

Sınırı geçen hain vurulur,

Ben jandarma komandoyum.

Eşkiyanın korkulu rüyası,

Kalleşlerin baş belası,

Komandonun çok sert olur cezası,

Ben jandarma komandoyum.

Anam elim kınaladı,

Babam duayla yolladı,

Vatan millet uğurladı,

Ben jandarma komandoyum.

Bu dağlarda adımız var,

Vatan için andımız var,

İman ile hırsımız var,

Biz jandarma komandoyuz.

Sınırları kanla çizdik,

Nice yiğit canlar verdik,

Vatan dedik millet dedik,

Biz jandarma komandoyuz.

Biz korkusuz kartallarız,

Sınırlarda dağlardayız,

Hainleri hep haklarız,

Biz jandarma komandoyuz.

Yüreğimiz dolu iman,

Hainlere yoktur aman,

Ecdadımdan kaldı ferman,

Biz jandarma komandoyuz.', 'Dağlara yazdırdım adımı, Hainler birkaç adım atımı, Vatanıma adadım canımı, Ben jandarma komandoyum. Bu dağlar benden sorulur, Kim demiş Meh...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ben-jandarma-komandoyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gideceksen Durma Git', 'gideceksen-durma-git-murat-demir-javtl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gideceksen durma git, git geriye bakmadan

Yüreğim kabarmadan, git yaşlarım akmadan

Gözlerinin önünde, sararıp solduğumu

Git ne olur bakıpta, görme kahrolduğumu

Neyleyim gidiyorsan, bir bildiğin var demek

Demek ki ben bu aşka, sarfetmemişim emek

Duysunda sevinsinler, aşk bilmezler yasıma

Şahit olmakta varmış, sevdamın iflasına

Bugünüm dünü özler, sen gidince yanımdan

Yarınım hüzne dalar, senden ayrıldığımdan

Söyleyin ötmesinler, bundan böyle bülbüller

Nasılsa solacaklar, benimle bir bir güller

Beni iyi tanırsın, yanarımda yıkılmam

Perişan olsam bile, namerte muhtaç olmam

Aramam hiç kimseyi, gitsende gönlüm sende

Seni sensiz yaşarım, sarılıp öpmesemde

Birgün komşu oluruz, bakarsın ki bir yerde

Neden olmasın sanki, belkide aynı evde

Gurbet değil mi hayat, eldemi ayrılmamak

Kim demiş ki olmuyor, ayrılıp kavuşmamak

Gideceksen git artık, henüz zaman var iken

Git yollar kapanmadan, git mevsim bahar iken

Yolcu yolunda gerek, bak Güneş yol alıyor

Dağların üzerinden, vakitte daralıyor

Bilmem nasıl geçecek, bilmem sensiz ilk gecem

Eminim kırk, elliye, vuracaktır derecem

Anlımda pul pul terler, sıkıntım depreşecek

Karanlığım zifiri, yaram derinleşecek', 'Gideceksen durma git, git geriye bakmadan Yüreğim kabarmadan, git yaşlarım akmadan Gözlerinin önünde, sararıp solduğumu Git ne olur bakıpta,...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gideceksen-durma-git-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanarım', 'yanarim-hakan-timur-x3ptc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sana harcadığım yıllar önemsiz

hediyeler,katlar köşkler bedelsiz

sevgisiz ortamda herşey değersiz

sana layık gördüğüm güle yanarım

ne paraya ne pula

ne tavaya ne tasa

aldırmam içimdeki yasa

sana yazdığım şiire yanarım

ne varlığa ne yokluğa

ne azlığa ne çokluğa

muhtacım gönüldeki tokluğa

senin için akan yaşa yanarım

ayaktayım yıkılmadım ben

hiçbir beklentim yok senden

hiçbir anın kalmadı dünden

sevgimi bilmeyen kalbe yanarım', 'sana harcadığım yıllar önemsiz hediyeler,katlar köşkler bedelsiz sevgisiz ortamda herşey değersiz sana layık gördüğüm güle yanarım ne paraya...', ARRAY['Türk Edebiyatı','Şiir','Hakan Timur']::text[], 8.5, '{"poet":"Hakan Timur","poet_slug":"hakan-timur","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yanarim-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçlarım Beyazlandı', 'saclarim-beyazlandi-i-smet-barlioglu-agq7p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ateşim alazlandı,

Yüreğim pervazlandı,

Çile çektim ömrümce

Saçlarım beyazlandı.

Aşkına boyun eğdim,

Asla isyan etmedim,

Ben ömrümü tükettim,

O her zaman nazlandı.

Azap içinde kaldım,

Bir tek ona aldandım,

Ona hep kalkan oldum,

Oysa bana gizlendi.

Çilem arttı gittikçe,

Hep istedi verdikçe,

Ben elemler çektikçe

O zevk alıp hazlandı.

(ISLAK RÜZGARLAR isimli hece şiirlerinden > 9-10/100)', 'Ateşim alazlandı, Yüreğim pervazlandı, Çile çektim ömrümce Saçlarım beyazlandı. Aşkına boyun eğdim, Asla isyan etmedim, Ben ömrümü tükettim,...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/saclarim-beyazlandi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip Başım', 'garip-basim-i-smet-barlioglu-0aq8l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gençliğe güvendim, yıllar götürdü,

Şansıma güvendim, sildi süpürdü,

Bir sevda gönlümü yedi bitirdi,

Şu garip başıma gelene bakın.

Böyle mi solarmış yediveren gül? 

Çile mi çekermiş körpecik bülbül? 

Ne çabuk perişan oldu bu gönül,

Şu garip başıma gelene bakın.

Gözyaşım sel oldu yanaklarımda,

Kalbim isyan etti dudaklarımda,

Doğacak gün mü var şafaklarımda,

Şu garip başıma gelene bakın.

Kapısız surlarla çevrildim kaldım,

Kendi çektiğimden kendim utandım,

Canımdan çok çabuk bezip usandım,

Şu garip başıma gelene bakın.

Kervan vurup geçti toza toprağa,

Bir beni bıraktı böyle uzağa,

Boşuna girmişim bülbülsüz bağa,

Şu garip başıma gelene bakın.

(ISLAK RÜZGARLAR isimli hece şiirlerinden > 11-12/100)', 'Gençliğe güvendim, yıllar götürdü, Şansıma güvendim, sildi süpürdü, Bir sevda gönlümü yedi bitirdi, Şu garip başıma gelene bakın. Böyle mi s...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/garip-basim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bülbülüm...', 'bulbulum-yusuf-ziya-leblebici-x56tn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mevsimler kayınca geçen yıllardan

Kurumuş dallara konma bülbülüm

Kafeslere girme medet dağlardan

Vurulup da sonra yanma bülbülüm

Kalbimde bahar var uçuyor kuşlar

Gözümde yaşlar var sevinçten ağlar

Konduğun omuzlar seninle coşar

İhanet edenden olma bülbülüm

Kar yağsa gönlüme seni saklarım

Kan dolsa gözüme sana ağlarım

Kırılsa gülünce senin kanadın

Avcılar gelirse korkma bülbülüm', 'Mevsimler kayınca geçen yıllardan Kurumuş dallara konma bülbülüm Kafeslere girme medet dağlardan Vurulup da sonra yanma bülbülüm Kalbimde ba...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bulbulum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak Rüzgar, Götürme', 'birak-ruzgar-goturme-i-smet-barlioglu-hw0v3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bırak rüzgar, götürme, bu şarkı benim değil,

O bana mahzun yüzlü sevgilimden armağan.

Bırak rüzgar, çıkarma, kanlı ok benim değil,

Kalbimin ortasına saplanmıştı bir zaman.

Bırak rüzgar, götürme, bu şarkı benim değil,

Bu şarkı ihanete uğramış yemin değil.

Bu şarkıyı duydukça titrer elim ayağım,

Gözyaşları içinde kalır gider yanağım,

Ürpererek seğirip yanar iki dudağım,

İsterim kesilmesin, hep söylensin durmadan,

Bırak rüzgar, götürme, bu şarkı benim değil,

Kendinin olduğundan o bile emin değil.

Ben koydum bu şarkıyı tutup onun yerine,

Yüreğimde ne varsa hep onun üzerine,

Çünkü rastlayamadım yıllardır benzerine,

Yine de rastlayamam yıllar geçse aradan.

Bırak rüzgar, götürme, bu şarkı benim değil,

Henüz onu terkedip gidecek günüm değil.

(ISLAK RÜZGARLAR isimli hece şiirlerinden > 13-14/100)', 'Bırak rüzgar, götürme, bu şarkı benim değil, O bana mahzun yüzlü sevgilimden armağan. Bırak rüzgar, çıkarma, kanlı ok benim değil, Kalbimin ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/birak-ruzgar-goturme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mendilimiz kırmızı...', 'mendilimiz-kirmizi-yusuf-ziya-leblebici-lzuh2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mendilimiz kırmızı

Halaya gelin canlar

O güzel kimin kızı

Elversin bana dostlar

Gözlerinde rastık var

Yüzlerinde allık var

Entarisi çiçekli

Onun bende gözü var

Yarime göz koymayın

Onu bana bırakın

Halaya gelin dostlar

Çorum''a el sallayın

Mendilimiz kırmızı

İçime düştü sızı

Halayın bu yıldızı

Acaba kimin kızı', 'Mendilimiz kırmızı Halaya gelin canlar O güzel kimin kızı Elversin bana dostlar Gözlerinde rastık var Yüzlerinde allık var Entarisi çiçekli ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mendilimiz-kirmizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Bu Ya', 'hayal-bu-ya-mehmet-cevik-hazerfen-qoxra', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün gelirsen eğer

Kırmızı halılarla karşılar

Sonra alır karşıma oturturum seni

Sensizliği, 

Senden uzakta kalmayı anlatırım önce

Ne feci bir şey olduğunu...

Belki o zaman hep kalırsın yanımda

Sonra kalkar sana çay demlerim

Evimin her tarafına çiçekler takar

Söndürüp ışıkları

Her köşeye mumlar yakarım

Radyomda sevdiğin türküler

Dilimde bitimsiz özlemler

Ne güzel olurdu be gelsen

Ellerini tutarım sıkıca

Gözlerim gözlerine kilitli

Hadi be meleğim

Birden çık gel

Şaşırsın çocuk yüreğim...

21.06.2004

 Mehmet Çevik (Hazerfen)', 'Bir gün gelirsen eğer Kırmızı halılarla karşılar Sonra alır karşıma oturturum seni Sensizliği,  Senden uzakta kalmayı anlatırım önce Ne feci...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çevik (Hazerfen)']::text[], 8.5, '{"poet":"Mehmet Çevik (Hazerfen)","poet_slug":"mehmet-cevik-hazerfen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hayal-bu-ya-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretin', 'hasretin-mehmet-cevik-hazerfen-fbnjm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hırçın bir yağmurum ben

Bi ağlarsam kimse susturamaz beni

Damlalarım küçük göller olurda 

Yüzdürürüm kağıttan gemileri

Öyle çok şey sığdı ki

Fazla sayılmayacak şu ömrüme

Boşalttığım şişeler şahit

Yalnızca hasretin ağlatır beni

Adın hep dilimde

Duvarlara, yıldızlara kazırım hasretini

Ve de yüreğime

Asi rüzgar alırda seni dudaklarımdan

Dağıtır hiç bilmediğin Ankara sokaklarına

Saksılarda güller goncalanır

Adının değdiği yerlerde

Varoşlarda hasretim yankılanır

25.06.2004

 Mehmet Çevik (Hazerfen)', 'Hırçın bir yağmurum ben Bi ağlarsam kimse susturamaz beni Damlalarım küçük göller olurda  Yüzdürürüm kağıttan gemileri Öyle çok şey sığdı ki...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çevik (Hazerfen)']::text[], 8.5, '{"poet":"Mehmet Çevik (Hazerfen)","poet_slug":"mehmet-cevik-hazerfen","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hasretin-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda 1', 'veda-1-erol-dal-t1cn1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hediyeler,

insanların sevdiklerine söyleyemedikleri

duyguları ifade etmek için kullanılır

çoğu zaman.

Ve hediyeler 

sevilmeyen insanlara verilmezler

çoğu zaman.

bana söyleyecek küçücük bir sözünün, 

sevginin olmadığını anladım.

Bu yüzden hediyeni kabul edemem.

…..

Ama bir hatıra bırakmak istiyorsan yinede; 

…

Zaten kalbimde kalacaksın

Beyhude geçen yıllar yerine.', 'Hediyeler, insanların sevdiklerine söyleyemedikleri duyguları ifade etmek için kullanılır çoğu zaman. Ve hediyeler  sevilmeyen insanlara ver...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/veda-1-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Minare: Kurtuluşa Çağıran Yapı', 'minare-kurtulusa-cagiran-yapi-necmi-unsal-d4x2v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nice cansız taş sütunlar coşkun ezanla şahlanır.

Tevhid saniye saniye şahadetle izahlanır.

Feza,  minareyle çeker vahdaniyeti kendine.

Dolar seherde secdeler, hep dingin gönlün bendine.

Kubbeleri kuşatırlar sülün gibi, elif elif.

Her biri ayrı şaheser, estetik ise muhtelif.

Baltacıoğlu der ki: “Türk demek minare demektir.”

Doğru...  Bu ne güzel usta  ve  bu  ne  güzel  emektir! 

Onlar bu vatanı İslam eden, Türk eden bir hattır.

Taş maddeyi mana  yapan,  âbidevî bir sanattır.

Milli Türk zevki kalemce   yükselir, hep ince ince.

“Buralar hep bizim” diye haykırır sanki kendince.

Minaredir, göz ve gönül aydınlığı sunan yapı.

Kurtuluşa çağırır  '' gel ''  nidasıyla  kapı kapı.

17 Nisan 2004 Cumartesi, Danimarka-Køge 16.19

8+8', 'Nice cansız taş sütunlar coşkun ezanla şahlanır. Tevhid saniye saniye şahadetle izahlanır. Feza,  minareyle çeker vahdaniyeti kendine. Dolar...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/minare-kurtulusa-cagiran-yapi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Gibi', 'hayat-gibi-memet-karabalik-edoqp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'uzun uzun düşünmek gibi

dalıp gitmek gibi bazen

bazen bir çocuk acemiliğinde

bazen de yaşlanan adımların sabrında

yaşanmayan bir aşkı hatırlamak gibi

kendimize kalan sevdaların anısı gibi

her adımdan sonra diğerini atmak gibi

durmayı istememek gibi

azgın bir nehre karşı kulaç atmak gibi

kendini akıntıya bırakmak gibi bazen

her şeyin ötesinde olmak gibi

hayat gibi.........', 'uzun uzun düşünmek gibi dalıp gitmek gibi bazen bazen bir çocuk acemiliğinde bazen de yaşlanan adımların sabrında yaşanmayan bir aşkı hatırl...', ARRAY['Türk Edebiyatı','Şiir','Memet Karabalık']::text[], 8.5, '{"poet":"Memet Karabalık","poet_slug":"memet-karabalik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayat-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairin Nasırlı Elleri', 'sairin-nasirli-elleri-necat-gundem-lcf9k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilmezsiniz belki ama

Nasırlıdır elleri şairin

Kazma kürekle

Değil 

Kalemle

Alınteriyle

Umutlarıyla

Her türden yanlışa karşı

Kardelen kadar asi yüreğiyle

Sevdiğiyle

Sevmediğiyle

İşçisidir insanlığın.

Şiir üretir

Tüketilmesin yok edilmesin diye

Bakar ki 

Gene herkes savaşında

İki yüzlülüğünde

Yalanında

Ve dinlemediğinde hiç kimse onu

Şiirsiz bırakır hepimizi

Grevli günlerinde

İlhamı kapıyı çalsa bile.', 'Bilmezsiniz belki ama Nasırlıdır elleri şairin Kazma kürekle Değil  Kalemle Alınteriyle Umutlarıyla Her türden yanlışa karşı Kardelen kadar ...', ARRAY['Türk Edebiyatı','Şiir','Necat Gündem']::text[], 8.5, '{"poet":"Necat Gündem","poet_slug":"necat-gundem","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sairin-nasirli-elleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Kalbimde...', 'sen-kalbimde-i-brahim-ethem-bingul-hssm6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çiçek açmaya yüz tutmuş hülyalarım,

Aşkım çalındı elimden

Sorgusuzca, hoyratça

Rutubet kokan odamda

Asılı kaldı resmin

Orada...

Okyanus dibi

Mavi, siyah enginlik

Yetmedi de insanlara

Sığdıramadılar bizi midye kabuğuna

Şu dünyada...

Yüzsüz yüzlerin kemiksiz dillerinde

Kiyafetiyle insan kılıklıların

Yüreksiz yüreklerinin tufanlarında

kayboldum ve kaybolduk

Rutubet kokan odamda

Asılı kaldı resmin 

Şimdi duvarda...

www.iebingul.com', 'Çiçek açmaya yüz tutmuş hülyalarım, Aşkım çalındı elimden Sorgusuzca, hoyratça Rutubet kokan odamda Asılı kaldı resmin Orada... Okyanus dibi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sen-kalbimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmeli', 'gitmeli-memet-karabalik-jhk2r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kelimelere sığabilecek bir yol aramalı

kendinden öncesini ve sonrasını bilmeli

kemik seslerinin çıtırtısı ile ürpermeli

bir kuş kanat çırptığında

eli kolu tutmamalı aşıkların

beşik denince hayatı anlamalı

ceylan denince ürkmeli

deniz denince boğulmalı

nehir denince coşmalı hep beraber

gemilere binip gitmeli buralardan', 'kelimelere sığabilecek bir yol aramalı kendinden öncesini ve sonrasını bilmeli kemik seslerinin çıtırtısı ile ürpermeli bir kuş kanat çırptı...', ARRAY['Türk Edebiyatı','Şiir','Memet Karabalık']::text[], 8.5, '{"poet":"Memet Karabalık","poet_slug":"memet-karabalik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gitmeli-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Depresyon', 'depresyon-naime-erlacin-e1sz2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '- Bana daima “hocam” diye hitap eden; çok yetenekli, fevkalade nazik ve saygılı; bugün Antolojiden ayrılma kararı alan genç bir şaire’nin; Sevgi Ulukuş’un gidişi ardından isyan! ! ! ...(Doğaçlamadır. Sözde kusur varsa affola…) 

mutsuzum bugün 

her gün bulutlarda dolaşmaz ki insan! 

söz verdim kendime

bir depresyon edineceğim en kestirme yoldan

böyle bir lüksüm olmamıştı hiç

yüklerimi 

bir bir atacağım sırtımdan

kuruyası o çınar var ya hani

kökünden keseceğim! 

dalını yaprağını budağını

“hiç”liğe adayacağım varlığını

yazılamayacak şiir falan

saçmalama hakkımı kullanacağım yerine

“iyi ki yoksun şair! ” denilecek bundan böyle

piyasası daha yüksek çünkü zırvalamanın! 

kendim için yaşayacağım bugün anlayın! 

başkası dinlesin dertlerinizi

çarenizi başkası bulsun

bunca çirkinliği kaldıramıyorum

iptal ettim “iç ben”lerimi

göreceksiniz en çok faulü ben yapıp

sahanın “en” cezalısı olacağım

“kötü para iyi parayı kovar” der iktisatçılar

söz size: 

niteliksizliğin keyfini çıkartacağım! 

bir depresyon...bir ben

bir ben...bir depresyonum konuşacak

kara gün ilan ettim günü

susturacağım ince nakış işleri

önce seyrüsefer defterini sonra gemileri yakıp

geçilmiş geçilmemiş köprüleri tümüyle yıkacağım! 

bir köpeğim de yok ki

o halde istemem bahçem olmasın

aramasın beni çiçekler kumrular güvercinler

sussun toprak ana fısıldamasın bana

kırlangıçlar içtimaa çıkmasın

saklansın yıldızlar karanlık köşelere

yüz vermeyeceğim Küçük Prens’in asteroidine bile

haber verin tepemdeki dolunaya

nereye giderse gitsin

isterse cehenneme! 

mutsuzum bugün

emeklerimi heba edenler ve kendi adıma mutsuzum 

dünyanın bütün iplerini salsalar da aşağı

çıkmayacağım kuyudan

kusacağım üstüne olan bitenin

sureta çünkü bu yaşam! 

yanılıyor muyum

gün onların değil mi: 

depresif mutsuz sorunlu 

bencil olacaksın oldun mu! 

o halde 

koydum bütün yumurtaları tek sepete

varsın kırılsın hepsi

seyreyle çılgın gönlüm, ey şuara! 

küskünlüğüm ve isyanımı seyreyle

çizildi rotam

bir depresyon aldım kendime

bu kaçıncı örselenme! 

bakmayın hafife aldığıma

Mars’ın gücünden baskındır kızıl ötesi öfkem

söze isyanın mührünü basıyorum! 

yetti bre! 

(7 Temmuz 2004)', '- Bana daima “hocam” diye hitap eden; çok yetenekli, fevkalade nazik ve saygılı; bugün Antolojiden ayrılma kararı alan genç bir şaire’nin; S...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/depresyon-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayın Altında', 'ayin-altinda-memet-karabalik-6dea9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ayın altında uzanmazsak mehtaplı bir gecede

başımıza gelecekleri düşünmezsek savaşan dünyada

cebimize giremeyenlerin hesabını soramazsak hırsızdan

değerini bilmezsek sevdanın

eli kolu bağlı birine el uzatamazsak

fukara görmek üzmüyorsa eğer

ganimet ganimet yaşarsak bu hayatı

hakkında bilmediklerimizden medet umarsak

ılık sular nasip olmasın bedenlerimize

iki dünya arasında köprü kurmasınlar

kapı kapı gezdirsinler, rezil etsinler herkese

liğme liğme etsinler dillerimizi

mor dağların ardını umut etmezsek

nergis kokularını sunmazsak yarin gülüşüne

orta yerde bağırmazsak aşk aşk diye

ölümden gayrı ayrılık durdurmazsa kalplerimizi

pis sularda yıkasınlar cenazemizi

rahat görmeyelim münkir''in elinden

sopalarla yıksın bizi nekir

şafakla beraber koyulmazsak yollara 

tabancadan ziyade güller savurmazsak dünyaya

uykusunda bile sevmezsek o ceylanı

ürkek ürkek ağlamazsak yağmura karşı

ve direnmezsek

ya da savaşmaz isek güzel olan her şeyin uğruna

zebaniler alsın bizi cehennemlerine', 'ayın altında uzanmazsak mehtaplı bir gecede başımıza gelecekleri düşünmezsek savaşan dünyada cebimize giremeyenlerin hesabını soramazsak hır...', ARRAY['Türk Edebiyatı','Şiir','Memet Karabalık']::text[], 8.5, '{"poet":"Memet Karabalık","poet_slug":"memet-karabalik","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ayin-altinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Naturmort', 'naturmort-necat-gundem-eq63e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerin hasret kalırken

Sevgi dolu bir çift göze

Yemyeşil ağaçlara

Akarsulara

Duymaya hasret kalırken 

Kuş ve çocuk seslerini

Yitip giden 

Hayaller olur

Gençliğin olur

Güzel olur

İnsan görüntülerinden

Arta kalan

İnsandışılığıyla

Kana bulanmış naturmort olur

Ezilen

Tank paletlerinin

Üzerinden geçtiği

Bir kır çiçeği olur

Gülücüğü boğazında tıkanık

Bir çocuk olur.

Bilmem farkında mısın

Martıların çığlığında

Hepimizden önce

Ölen doğa olur.', 'Gözlerin hasret kalırken Sevgi dolu bir çift göze Yemyeşil ağaçlara Akarsulara Duymaya hasret kalırken  Kuş ve çocuk seslerini Yitip giden  ...', ARRAY['Türk Edebiyatı','Şiir','Necat Gündem']::text[], 8.5, '{"poet":"Necat Gündem","poet_slug":"necat-gundem","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/naturmort-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizlik', 'sessizlik-necat-gundem-zkqu1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bilir misin

Korkar oldum sessizlikten

Sessizlik  sensizlik 

Olalı  beri.', 'Bilir misin Korkar oldum sessizlikten Sessizlik  sensizlik  Olalı  beri....', ARRAY['Türk Edebiyatı','Şiir','Necat Gündem']::text[], 8.5, '{"poet":"Necat Gündem","poet_slug":"necat-gundem","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sessizlik-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-ali-gencay-7t9nn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tırmandım ulaşılmaz fikrine yel,fırtına,ayaz kesti

Seni sevdim niceleri bir yeldi,tenimi okşadı geçti

Zamanın rençperiyim an,dakika,saat bir gecelikti

Sırtlandım sevdanı,zaman arsız nehir,akıp geçti

Kuzgunlar,akbabalar ve insanlar,vahşiden daha vahşi

Ne zaman yumsam gözümü üşüştüler ruhuma her biri

Değmesin bana kimse ben kimseye yar demedim ki

Girmesinler gecelerime geceleri yanarım,kor ne ki', 'Tırmandım ulaşılmaz fikrine yel,fırtına,ayaz kesti Seni sevdim niceleri bir yeldi,tenimi okşadı geçti Zamanın rençperiyim an,dakika,saat bir...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/isyan-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Kız Ve Hayaller', 'kucuk-kiz-ve-hayaller-sirma-mersin-gtcz7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Küçük bir kız 

Kendinden çok hayallerini sevdi...

Hayallerinle güldü,

Hayallerinle ağladı...

Hayatta değil, hayallerine inandı.

Aklını susturdu,

Duygularını konuşturdu...

Gerçekleri gördükce,

Yaşamın kendisini anladı...

Yaşadıkca öğrendi! 

Pembe gözlüklü hayaller

Sadece

Onun gözlerinde yaşıyordu...

Hayallerle gerçekler arasında 

Denge kurmaya çalışıyor,

Küçük kız...

05.07.04

                '' Adım boyunu geçen yalnızlıkta

                  Sığındığımız sahte dünyadır, hayaller... ''', 'Küçük bir kız  Kendinden çok hayallerini sevdi... Hayallerinle güldü, Hayallerinle ağladı... Hayatta değil, hayallerine inandı. Aklını sustu...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kucuk-kiz-ve-hayaller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yinelemeler', 'yinelemeler-cetin-isik-c2sqd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yine düştüm yollara

ağzımda anamın dillinden bir 

ağıt

satılar bizi düşmana 

lo dılo lo dılo

atılar bizi zındana 

lo dılo lo dılo

kaldık yine duvar diplerinde 

lo dılo lo dılo

biz akşamdan kalma ölüler

lo dılo lo dılo

kaldık bu vadilerin altında

kaldık çöllerin uzaklığında 

lo dılo lo dılo', 'yine düştüm yollara ağzımda anamın dillinden bir  ağıt satılar bizi düşmana  lo dılo lo dılo atılar bizi zındana  lo dılo lo dılo kaldık yin...', ARRAY['Türk Edebiyatı','Şiir','Çetin Işık']::text[], 8.5, '{"poet":"Çetin Işık","poet_slug":"cetin-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yinelemeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bari Onlar Üzülsün', 'bari-onlar-uzulsun-burak-killioglu-uegwe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabret! 

Sabret dedi bir ses,

Sabret! 

Tüm olanı biteni,

Bir karabasan farzet.

Dayan! 

Dayan diye ünledi,

Dayan! 

Aşk diye öğretilen,

Miniminnacık bir yalan.

Yazma! 

Yazma diye ekledi,

Yazma! 

Onu yazacağım diye

Kendi kendine kızma.

Geçmiş gün de, unut git

Rüzgar alsın götürsün.

Ne ismini hatırla,

Ne o güzel yüzü düşün.

Hasret kalsın sokakları

Bir tek onlar üzülsün.

Bir adam geçerdi buradan

Gelmez oldu anlaşılan

Desinler.

Bari onlar üzülsün.', 'Sabret!  Sabret dedi bir ses, Sabret!  Tüm olanı biteni, Bir karabasan farzet. Dayan!  Dayan diye ünledi, Dayan!  Aşk diye öğretilen, Minimi...', ARRAY['Türk Edebiyatı','Şiir','Burak Kıllıoğlu']::text[], 8.5, '{"poet":"Burak Kıllıoğlu","poet_slug":"burak-killioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bari-onlar-uzulsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykusuz Gözler', 'uykusuz-gozler-sirma-mersin-ifh01', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Acı kelimelerin

Keskin hecelerinde çoğalan

Hüzün yalnızlığı

Geceyi sararken...

Hayali aşkların saati başlar

Yüreğin aydınlığında...

Dökülür özlemli seslerin 

Haykırışı, yastığa...

Çözülür sevdalı sevgi dolu

Dizeler satırlara...

Yeni güne gebe kalmış umudun

Dilek tutması ile kapanır

Uykusuz geceler...

05.07.04', 'Acı kelimelerin Keskin hecelerinde çoğalan Hüzün yalnızlığı Geceyi sararken... Hayali aşkların saati başlar Yüreğin aydınlığında... Dökülür ...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/uykusuz-gozler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlan-ı Aşk', 'i-lan-i-ask-can-ceylan-ke3yt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bazen sözler basittir

Sıradan ve renksizdir

Sözlerle süslenmemiş

Ağdasız fakat nettir

Keyifli ve özgürdür

Martı uçuşu gibi

Yiğittir korkusuzdur

Kartal bakışı gibi

Çıkarsız ve mangaldır

Ana yüreği kadar

Yalın ve tertemizdir

Bir çocuk kalbi kadar

Sonuçta diyeceğim

Lafı dolandırmadan

Seni hep seveceğim

Hesapsız ve sıradan', 'Bazen sözler basittir Sıradan ve renksizdir Sözlerle süslenmemiş Ağdasız fakat nettir Keyifli ve özgürdür Martı uçuşu gibi Yiğittir korkusuz...', ARRAY['Türk Edebiyatı','Şiir','Can Ceylan']::text[], 8.5, '{"poet":"Can Ceylan","poet_slug":"can-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ilan-i-ask-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yinelemeler 2', 'yinelemeler-2-cetin-isik-r6qdt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'karadır kapkara bu gece 

gökten gül yağar bu gece

bir kız gördüm

döndüm baktım bir gece

ağzından bal ve gül dökülürdü o gece

yar ehmedo yar ehmedo', 'karadır kapkara bu gece  gökten gül yağar bu gece bir kız gördüm döndüm baktım bir gece ağzından bal ve gül dökülürdü o gece yar ehmedo yar ...', ARRAY['Türk Edebiyatı','Şiir','Çetin Işık']::text[], 8.5, '{"poet":"Çetin Işık","poet_slug":"cetin-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yinelemeler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Atlı *', 'atli-kubilay-enginol-evzti', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayatından bir atlı geçti

Herkesinkinden geçtiği gibi

Kumları savurarak,toz duman

Yağmurlar sanki dökülen

Yılları hüznü heybesinde

Dertler,üzüntüler kalmış gerisinde

Maviydi

Gözleri,geldiği yerdeki denizlere benzer

Çoktan kurumuş,yüreğinde sevgiler

İçinden,bir atlı geçti

Yüreğini acıttı

Heybesinden,yıldız,yıldız umut attı

Ve

Gitti', 'Hayatından bir atlı geçti Herkesinkinden geçtiği gibi Kumları savurarak,toz duman Yağmurlar sanki dökülen Yılları hüznü heybesinde Dertler,ü...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/atli-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dertli Başımın Kârı', 'dertli-basimin-k-ri-abdulkadir-ogdum-87gjl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Efkâr bu, laf anlamaz, anası Aşka çekmiş! 

İçip çıkmış karşıma diyor, vururum seni

En sevinçli gününde gelir bulurum seni...

Hayat yatırmış beni, memat falaka çekmiş...

O gün - bugündür bende memleketin efkârı

Buymuş dertli başımın haram değmemiş kârı!', 'Efkâr bu, laf anlamaz, anası Aşka çekmiş!  İçip çıkmış karşıma diyor, vururum seni En sevinçli gününde gelir bulurum seni... Hayat yatırmış ...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Öğdüm']::text[], 8.5, '{"poet":"Abdulkadir Öğdüm","poet_slug":"abdulkadir-ogdum","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dertli-basimin-kari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Madalyonun Yüzleri', 'madalyonun-yuzleri-aynur-uluc-zrj7r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nasıl bir devinim

O  kaynayan kazan

Şifrelerin çözüldüğü düğüm

Eski yeni yüzüyle çıkıyor karşıma

Renklerin en soysuzu

Çocuğun en mutsuzu

Aşacak içindeki ölümü

Çıkaracak göğsünden

Yaşamı doğurtacak

Ayıklarsa bedeninden

Dönüşümün buzunu', 'Nasıl bir devinim O  kaynayan kazan Şifrelerin çözüldüğü düğüm Eski yeni yüzüyle çıkıyor karşıma Renklerin en soysuzu Çocuğun en mutsuzu Aşa...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/madalyonun-yuzleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldüğün Akşam', 'oldugun-aksam-bedrettin-erol-ih08w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu akşam kederle dolu..bu akşam,

Bu akşam,sinsice düştü odama,

Bu akşam martılar kondu güneşe,

Buakşamı görmeyenler oldu bu akşam.', 'Bu akşam kederle dolu..bu akşam, Bu akşam,sinsice düştü odama, Bu akşam martılar kondu güneşe, Buakşamı görmeyenler oldu bu akşam....', ARRAY['Türk Edebiyatı','Şiir','Bedrettin Erol']::text[], 8.5, '{"poet":"Bedrettin Erol","poet_slug":"bedrettin-erol","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/oldugun-aksam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kartanem baltanem birtanem', 'kartanem-baltanem-birtanem-umut-gungor-20fby', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güllerim sensiz gonca vermedi,

Mehtap ışığını göğe sermedi,

Çiçekler beklenen rengi vermedi,

Kartanem baltanem birtanem.

Gökkuşağı renklerini yine açmadı,

Bir tane kelebek bile uçmadı,

Bahçemde çocuklar bile koşmadı,

Kartanem baltanem birtanem.

Kalem yazmadı inan kırıp attım,

Sabır taşımı uzaklara fırlattım,

Sinirden dağ taş gördüğüme çattım,

Kartanem baltanem birtanem.', 'Güllerim sensiz gonca vermedi, Mehtap ışığını göğe sermedi, Çiçekler beklenen rengi vermedi, Kartanem baltanem birtanem. Gökkuşağı renklerin...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kartanem-baltanem-birtanem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mehtap Işığını Göğe Sermedi', 'mehtap-isigini-goge-sermedi-umut-gungor-s6i76', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güllerim sensiz gonca vermedi,

Mehtap ışığını göğe sermedi,

Çiçekler beklenen rengi vermedi,

Canım kartanem baltanem birtanem.

Gökkuşağı renklerini yine açmadı,

Bir tane kelebek bile uçmadı,

Bahçemde çocuklar bile koşmadı,

Canım kartanem baltanem birtanem.

Kalem yazmadı inan kırıp attım,

Sabır taşımı uzaklara fırlattım,

Sinirden dağ taş gördüğüme çattım,

Canım kartanem baltanem birtanem.', 'Güllerim sensiz gonca vermedi, Mehtap ışığını göğe sermedi, Çiçekler beklenen rengi vermedi, Canım kartanem baltanem birtanem. Gökkuşağı ren...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mehtap-isigini-goge-sermedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoksun', 'sen-yoksun-bedrettin-erol-ayasg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalnızca martılar uçuşmakta sahilimizde,

Bakir kumsalı iğfal edercesine bir de ayak izlerin.

gül idim....soldum.

fenerdim....söndüm.

yağmurdum....dindim.

ararmı beni artık kahverengi gözlerin? 

sorarmı hallerimi dostlarım,sevenlerim? 

bir tek mektubun kaldı,seneler öncesinden,

bir de dudak izlerin...yüreğimde gizlerim.

dönerdim....durdum.

uçardım....kondum.

                           ay idim....battım.

                           güneştim....yittim.

                           aşk idim....bittim', 'Yalnızca martılar uçuşmakta sahilimizde, Bakir kumsalı iğfal edercesine bir de ayak izlerin. gül idim....soldum. fenerdim....söndüm. yağmurd...', ARRAY['Türk Edebiyatı','Şiir','Bedrettin Erol']::text[], 8.5, '{"poet":"Bedrettin Erol","poet_slug":"bedrettin-erol","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-yoksun-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz ve Bir Kimsesiz', 'deniz-ve-bir-kimsesiz-bedrettin-erol-2wqu8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'suya düşen yıldızlar bana selam getirir,

yüreğimi bir hüzün,bin acıyla titretir,

denizin kulağına beni fısıldar rüzgar,

sessizliği yakalar saçlarından dalgalar.....

martılar pike yapıp deler iken denizi,

hicran ankebut gibi örmekte içimizi,

denizin mavi göğsü sevgiyle dolsun diye,

birbirini kucaklar dalgalar her saniye....

zaman renkleri alır acılarımı bekler,

kan mı içmekte artık muhteşem kelebekler,

bilirim ben denizin değişmeyen huyunu,

bazen hırçın dalgalı,bazen uyuduğunu.

deniz de bilir benim kimsesiz olduğumu,

kıyılarında yalnız sararıp solduğumu,

dökülür dudağımdan dualar kervan..kervan,

nemli bakışlar düşer denize kırılmadan,

zamanın sinesinden bir bir düşen yapraklar,

ömrümü bitirmekte denizler ve sonbahar,', 'suya düşen yıldızlar bana selam getirir, yüreğimi bir hüzün,bin acıyla titretir, denizin kulağına beni fısıldar rüzgar, sessizliği yakalar s...', ARRAY['Türk Edebiyatı','Şiir','Bedrettin Erol']::text[], 8.5, '{"poet":"Bedrettin Erol","poet_slug":"bedrettin-erol","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/deniz-ve-bir-kimsesiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-bayram-gokmen-0lhna', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'zaman

Akşamların kızıllığında yandı gönlüm

Yolların uzunluğunda kaldı ömrüm

Kar yağdı saçlarıma maziden tel tel

Duygularım esen  soğuk bir yel

Sabah güneş uyandı her yer nura yandı

Can can bahar uyandı gönlüm uyandı

İkliminde eserken ılgıt ılgıt  akıl yellerim

Türkülerde buldum seni ağıtlarda beklerim

Bir kuştu uçtu gönlüm geçti ömrüm

Hazan soldurdu soldu da açmıyor gülüm

Gökyüzünde asılı kaldı göz yaşlarım

Yağmurlarda ağlıyor bakışlarım

Bir derya içre hayat  bir başka huzur

Varın ortasında yokun sonunda VAR olur

07.07.2004', 'zaman Akşamların kızıllığında yandı gönlüm Yolların uzunluğunda kaldı ömrüm Kar yağdı saçlarıma maziden tel tel Duygularım esen  soğuk bir y...', ARRAY['Türk Edebiyatı','Şiir','Bayram Gökmen']::text[], 8.5, '{"poet":"Bayram Gökmen","poet_slug":"bayram-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/zaman-132-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana suskunum', 'sana-suskunum-zafer-zengin-etnika-dwn4h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana

s u s k u n u m 

