INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AŞK Kazısı - ferhat ile şirin''e', 'ask-kazisi-ferhat-ile-sirin-e-hasan-yasar-y8ebt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''dillere destan aşklara, ''

