INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Harmanı', 'umut-harmani-servet-suner-y66w8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir hayat başlıyor bin bir sevinç,umut ile,

Sürüp gidiyor,hem amaç,hem emek ile.

Bütün çabalar bazen ulaşır beklenen sonuca,

Bazen de karşılaşın bir çok engel ile.

Beklentiler var,meraklar var,özlemler var.

Eğer ulaşılamazsa umulana,zamanla bu duygular

Boşa ise tüm çabalar,boğuyorsa insanı çaresizlik

Ve boğar hayat, hayat git gide büyüyorsa elemler.

İşte ozaman atılır tüm umutlar hüsran çukuruna,

Bende emellerimi attım keder ğirdabına.

Bari siz gömmeyin beni umutsuzluk mezarına.

Katın,karıştırın,savurun yine beni umut harmanına.', 'Bir hayat başlıyor bin bir sevinç,umut ile, Sürüp gidiyor,hem amaç,hem emek ile. Bütün çabalar bazen ulaşır beklenen sonuca, Bazen de karşıl...', ARRAY['Türk Edebiyatı','Şiir','Servet Suner']::text[], 8.5, '{"poet":"Servet Suner","poet_slug":"servet-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/umut-harmani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SARIKAMIŞ GÜNLÜĞÜ-2 bağır da GELSİN BAHAR', 'sarikamis-gunlugu-2-bagir-da-gelsi-n-bahar-hasan-yasar-vqxmi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '^^^^YAZILIYOR^^^^^^LÜTFEN BEKLEYİNİZ^^^^^

hala kara burası

hala kara kışta

ve 

neredeyse hala kar altında

yaz yaklaşmasına rağmen

kimi yerlerde

yazın ortasına

gelinmişken

kimi yerlerde

umut bahrda bu kentte...

yeni yeşillenmeye

cıvıllaşmaya başladı çimenler.

ancak

ne bir erik

ne bir kiraz

ne bir söğüt dalı

ne bir tomurcuklanan sardunya

ve donuyoruz haziranın ortasında.

bak! dedim ya; 

soğudu hava

yağmur indi

indi iyice aşağıya

allah vere de kar yağmaya! 

biliyorum; 

bir güzel anar

bir güzel anar beni

bundan daha yeşil

bundan daha sıcak bir kentte.

baharın kucağında

yazın tam başında

yeşil gölgelerin altında

bir güzel bekler

hasreti takmış koluna

yolumu gözler...

zor geçeceğe benzer oysa

zor

bu hasretle bu kara günler

bu kara yerde

zor geçecek

gelecek günleri getirecek geceler...

güneşin parlaklığının

hiç değiştiremediği evlere bakıyorum

büyük çoğunluğu gece konmuş

çimento yerine

emekle yoğrulmuş

çatıları kar kaysın diye dik

çinkolu evlere...

^^^^^^DEVAMI VAR^^^^^^', '^^^^YAZILIYOR^^^^^^LÜTFEN BEKLEYİNİZ^^^^^ hala kara burası hala kara kışta ve  neredeyse hala kar altında yaz yaklaşmasına rağmen kimi yerle...', ARRAY['Türk Edebiyatı','Şiir','Hasan Yaşar']::text[], 8.5, '{"poet":"Hasan Yaşar","poet_slug":"hasan-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/sarikamis-gunlugu-2-bagir-da-gelsin-bahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savaş Gemilerini İzlediğini Bilmek', 'savas-gemilerini-i-zledigini-bilmek-meral-balci-tanis-gvxhp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Göz bebeklerininin derinliklerinde

Yüzdürmek isterken sevda gemilerimi

Sahiline ''hiç de yakışmadığımı'' bilmek 

Ne zordur bilir misin sevgili

Yüreğin, yüreğime demirlesin isterken

Açıklardaki savaş gemilerini izlediğini bilmek

Ve uzaktan da olsa sana el sallayamamak

Ne zordur bilir misin sevgili

Kulaç kulaç ezber etmişken seni

Şöyle alalade üstünde yürüyeceğin

Bir kaldırım bile olamamak limanına

Ne zordur anlayabilirmisin beni.

Anlayamazsın, 

Anlasaydın 

....................', 'Göz bebeklerininin derinliklerinde Yüzdürmek isterken sevda gemilerimi Sahiline ''hiç de yakışmadığımı'' bilmek  Ne zordur bilir misin sevgili...', ARRAY['Türk Edebiyatı','Şiir','Meral Balcı Tanış']::text[], 8.5, '{"poet":"Meral Balcı Tanış","poet_slug":"meral-balci-tanis","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/savas-gemilerini-izledigini-bilmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanın Ötesi', 'zamanin-otesi-haci-mehmet-erol-w3ymd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir duygu yaşıyorum, içimde sımsıcak,

kuşlar gibi hür, gökyüzü gibi uçsuz bucaksız

gecesiz, gündüzsüz....

yersiz, yurtsuz; zamanın ötesinde', 'Bir duygu yaşıyorum, içimde sımsıcak, kuşlar gibi hür, gökyüzü gibi uçsuz bucaksız gecesiz, gündüzsüz.... yersiz, yurtsuz; zamanın ötesinde...', ARRAY['Türk Edebiyatı','Şiir','Hacı Mehmet EROL']::text[], 8.5, '{"poet":"Hacı Mehmet EROL","poet_slug":"haci-mehmet-erol","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zamanin-otesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yara İzi...', 'yara-i-zi-nihan-demirel-jgnuz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bazen, tek kişilik hayattayım... Canım titriyor, çocukluğumu kokluyorum... Öyle bomboşum ki...

Dolanıyorum, duvarlarımın arasında. Mırıldanıyorum, oturuyorum, kalkıyorum, tekrar oturuyorum...

Olmuyor...Canım titriyor hâlâ....

Sonra ellerime takılıyor  gözlerim; liseden kalma bir yara izine burkuluyor içim. Ne kadar çok kızmış ve ne kadar çok kıskanılmıştım -Ah! kızlar- 

Emre ''yıllardır aynı sırayı, aynı lokmayı, aynı gülümsemeyi paylaşıyoruz. Birgün 30 una geleceksin ve bana dair birşey düşmeyecek aklına...Şimdi kızsanda,birgün gülümsetecek bu iz seni '' demişti; elime kalemin sivri ucunu tüm kuvvetiyle sokuşturken. Haklıymış...

30 una az kalmıştı, yapayalnız duvarlarımın içinde şimdi Emre, hem de bana benim kadar yakın... İyi ki yapmış ve iyi ki izi kalması için o günlerin, dişlerimi sıkıp bazen belki de - ilk zamanlar çok acıyor- izin vemişim; kabuk bağlayıp kapanmasın diye, hergün yolmasına yaramı..

Yaralar gülümsetebililiyor insanı. Hele ki ruhu varsa, bir parça taşıyorlar güzelliklere dair...

Gün gelir, kalbimdeki bir yaraya takılır gözlerim ve gülümsetebiliyorsa beni, gururlanırım ''iyi ki yapmış, iyi ki yapmışım '' derim.

İyi ki sevmişiz, birbirimizi...

01.07.04', 'Bazen, tek kişilik hayattayım... Canım titriyor, çocukluğumu kokluyorum... Öyle bomboşum ki... Dolanıyorum, duvarlarımın arasında. Mırıldanı...', ARRAY['Türk Edebiyatı','Şiir','Nihan Demirel']::text[], 8.5, '{"poet":"Nihan Demirel","poet_slug":"nihan-demirel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yara-izi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Penceresi 3', 'yagmur-penceresi-3-mustafa-tugrul-kosar-9ld8o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Paçaları ıpıslak bitmekte olan gece

Herkez yağmurdan kaçmış

Ben yağmura yürürüm

Günahkar iken,

Seni böylesi aşkla kutsadığım için,

Makyajı akmış kadınlar gibi,

Tanık olur ve ağlar,

Boyasını dökecek kadar tüm binalar

Bir tek ben duyarım onların feryadını

Yükselip sonsuzluğu çınlatacak kadar

Karanlık kavşaklar da bilir beni

Bu yüzden salmamaya direnir asi,kaçak hayalini

Bak işte yeniden geliyorsun! 

Ateş kayıklarının üstünde alev alev

Yine gülüp kaçıyorsun yansan da

Yine de güzelsin

Yine kül olsan da

Akşam sürgününden geldim az önce

Bilmediğim birkaç sokak daha tanıdım

Kırmızı güller bıraktım peşimde

Tükürebildiklerimle

Günbegün beliren kamburumdan,

Dönüpte bakamadım bile

Kırağı sabahların bir bekçisi olmalı elbet

Yapraklardan yuvarlanırken yağmur suları,

Toprağa düşmeden bir duası olmalı

Birçok kimsenin olduğu,

Kendi boyutun da huzurunu dilemeliyim Tanrıdan

Güneş şefkatli elleriyle dokununca toprağa,

İlk ışıklarla geçişini seyretmeliyim,

Yağmur penceresi gözlerimin ardından', 'Paçaları ıpıslak bitmekte olan gece Herkez yağmurdan kaçmış Ben yağmura yürürüm Günahkar iken, Seni böylesi aşkla kutsadığım için, Makyajı a...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tuğrul Koşar']::text[], 8.5, '{"poet":"Mustafa Tuğrul Koşar","poet_slug":"mustafa-tugrul-kosar","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yagmur-penceresi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğacak Aşkın Karın Ağrısı', 'dogacak-askin-karin-agrisi-i-brahim-bayraktar-27m7q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönül eğlemek için sevmedim seni,

Sevdiğimle beraber olmak isterim.

Gözüne girmek için övmedim seni,

Sevgiyi gönlünde hissedenlerdenim.

Bakışların cevaptır kaygılarıma,

Bakışlarım cevaptır kaygılarına,

Tanrı şahit olsun ki duygularıma,

Aşkı için canını verenlerdenim. 

Tatmadığım hazları tattım sayende,

Sevdalarıma sevda kattım sayende,

Geleceğe dilekler tuttum sayende,

Sevdi mi adam gibi sevenlerdenim.

Yine fırtına koptu, yandı ışığım,

İflah olmam artık bir deli aşığım,

Sonsuz umut bağladığım yakışığım,

Mutluluğu seninle görenlerdenim.

07.07.2004/Ankara', 'Gönül eğlemek için sevmedim seni, Sevdiğimle beraber olmak isterim. Gözüne girmek için övmedim seni, Sevgiyi gönlünde hissedenlerdenim. Bakı...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dogacak-askin-karin-agrisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suskun Bir Vadidir Sensizlik', 'suskun-bir-vadidir-sensizlik-mustafa-tugrul-kosar-cmpdo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Suskun bir vadidir sensizlik

Çorak topraklı ağaçsız,yeşilsiz

Katmer katmer taşları

Acılar merdiveni

Çığlıklar atan bir bebek gibi kucaksız

Kuruyan bir mezar

Güneşe hapsedilmiş çaresiz,duasız

Suskun bir vadidir sensizlik

Yarılmış bütün bir dağ

Bir tarafı sen,karşısı ben

Uçurumun ötesinde bakışlarının hayali

Yavaştan çökerken akşamın siyah bulutları

Feryatlarım gündüz öksüzlüğünde

Gecelerde ki güzelliğinin,

Gözlerimden damlayan kanları

Suskun bir vadidir sensizlik

Bir dağ çıkmazında yorgunluk

Allaşan güneş batımında

Tabiatın dilinde esir şarkılar

Gürleşen yüreğimin ağzından,

Doğanın ozanlarından hep aynı yankılar', 'Suskun bir vadidir sensizlik Çorak topraklı ağaçsız,yeşilsiz Katmer katmer taşları Acılar merdiveni Çığlıklar atan bir bebek gibi kucaksız K...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tuğrul Koşar']::text[], 8.5, '{"poet":"Mustafa Tuğrul Koşar","poet_slug":"mustafa-tugrul-kosar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/suskun-bir-vadidir-sensizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeliyiz Dirilişi', 'sevmeliyiz-dirilisi-mustafa-tugrul-kosar-cted1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'El uzat bana çamur kentinden 

Çek beni polen kokulu yanlızlıktan 

Vadilerden,ırmaklardan süzüleyim 

Çilli göğsüne aksın gözlerim 

Soğukmu evin...razıyım 

Kuruysa kuru yatağın yanında uyumalıyım 

Sarışın terlerin işlesin hücrelerime 

Nefret eder gibi öp yine 

Dar sokağından duyulsun utancımız 

Çok mu üşüyormuş orada insanlar 

Isıtalım öyleyse 

İlk önce kendimizden başlayalım 

Öğretelim onlara dudakların kutsal anlamını 

Bu sefer yakalayalım güneşin yaralanışını 

Kanının yansıması gitmesin penceremizden 

Bulutlar leke gibi olsun perdemizde 

Dağınık odan gibi geçmeliyiz dünyayı 

Sevmelisin...sevmeliyim... 

Sevmeliyiz dirilişi... 

El uzat bana zehir dumanlı kentinden 

Üstüne çöreklenmiş kızıllığı delsin tırnakların 

Melekler güzeli serçeler kılavuzun olacak 

Okşayacaksın ceylanların yumuşak derilerini 

Çamlar yükseldikce bulacaksın beni 

Tut ve çek bıktığım makilerin arasından 

Bir ayin edasıyla uçalım ürkekce 

Sevmeye sakla nefesini 

Konuşma... 

Kirpiklerim ıslak bir kabus anlatacak 

Kırılabilir bana doğanın ozanları 

Seni görürler yadırgamazlar o kadarda 

Nemliyse nemli pervazların razıyım 

Özledim günahkar battaniyeni 

Küf sinmiş demir yastığını 

Soğuksa soğuk yatağın yanında uyumalıyım 

Artık sadece sende karar kılmalıyım 

Esmerim öldürdü kurtar sarışınım 

Kan gibi silmeliyiz acı versede 

Sevmelisin...sevmeliyim... 

Sevmeliyiz dirilişi', 'El uzat bana çamur kentinden  Çek beni polen kokulu yanlızlıktan  Vadilerden,ırmaklardan süzüleyim  Çilli göğsüne aksın gözlerim  Soğukmu ev...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tuğrul Koşar']::text[], 8.5, '{"poet":"Mustafa Tuğrul Koşar","poet_slug":"mustafa-tugrul-kosar","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sevmeliyiz-dirilisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asın Beni...', 'asin-beni-tulay-eker-f4wol', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şiirlerimle bölünmek istiyorum

Hece hece,harf harf

Ne ilerisi ne gerisi

Tut ki ağlamıyorum

Tut ki mah karşımda

Sana bakıp inci taneleri 

Diziyorum yüzüne

Kaçıyor gecenin karanlık gizine.

Şiirlerimle ölmek istiyorum

Bir bir kopup gelmeli

Üzerime,şiir yüklü dağlar

Gözlerimin derinliklerinde

Kılıç kalkan ekibi oynar

Yüzün içimde kara üzüm tanesi

Al çıkar gözbebeğimden seni

Son kurşun senin,vur kendini

Kesilsin içimdeki kara trenin sesi

Şiirlerimle gömülmek istiyorum 

Şah damarımdan vursun mısralar

Dökülsün dillerden  merdo türküsü

Ahmed Arif uy havar''ı söylesin

Leylim leylimle rüzgar essin

Sonra yıkmalıyım yere yüzümü

Ne kefen giydirilsin

Ne de açsın dizlerimde gökyüzü

Şiirlerimle örtün beni

Gülsün içimin ağlayan dili

Sen şiirlerim,

Şiirlerim sendin.

Bir türlü elveda diyemedim.

Şimdi asın beni! 

Dizelerimle dize geldim.. 

Elveda vaktim.', 'Şiirlerimle bölünmek istiyorum Hece hece,harf harf Ne ilerisi ne gerisi Tut ki ağlamıyorum Tut ki mah karşımda Sana bakıp inci taneleri  Diz...', ARRAY['Türk Edebiyatı','Şiir','Tülay Eker']::text[], 8.5, '{"poet":"Tülay Eker","poet_slug":"tulay-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/asin-beni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vücut dili', 'vucut-dili-mehmet-halil-7431b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '''''Tek dil biliyorum! '''' diye üzülürken

                 Öğrendim, vücut dilim olduğunu.

                 Dilimin birini dahi kullanamazken,

                 İkincisine sevinemedim doğrusu. 

                 Dilimin ucunda durur da kelimeler,  

                 Bir türlü çıkıp ağzımdan dökülmezler.

                 Ben üzülüp dururken kendi halime,

                 Vücudun çok konuşuyor dediler…

                 Şimdi anladım, az konuşmamın nedenini…

                 Vücut dilim çok konuştuğundan,

                 Öbür dilime sıra gelmediği belli,

                 Çok konuşmaya ihtiyaç duyanlar, 

                 belki, biraz da, 

                 vücut diliyle iyi anlaşamayanlar...

                 biri karşı çıkıyordur, diğerinin yalanına...', '''''Tek dil biliyorum! '''' diye üzülürken                  Öğrendim, vücut dilim olduğunu.                  Dilimin birini dahi kullanamazken, ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Halil']::text[], 8.5, '{"poet":"Mehmet Halil","poet_slug":"mehmet-halil","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/vucut-dili-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarap şişesinde Leylak...', 'sarap-sisesinde-leylak-lzcramcil-ceyhun-erdem-n0szv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Camın üzerinde yağmur lekesi,

ben döndüm ellerin yolundan,

çiçeğin üzerinde suyun damlası,

kökünde kibrit suyu acısı

Balkona çıkmış akşam üstü,

seyre dalmış pazar yerini,

elinde papatya çayı, üstü başı 

insanlık dışı

Terinin tuzu yakmış tenini,

parmak uçlarında soğuk su lekesi,

şarap şişesindeki zambakla konuşurken

sırtında yağmur damlası, yüzünde yaşamın acısı', 'Camın üzerinde yağmur lekesi, ben döndüm ellerin yolundan, çiçeğin üzerinde suyun damlası, kökünde kibrit suyu acısı Balkona çıkmış akşam üs...', ARRAY['Türk Edebiyatı','Şiir','Lzcramcil Ceyhun Erdem']::text[], 8.5, '{"poet":"Lzcramcil Ceyhun Erdem","poet_slug":"lzcramcil-ceyhun-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sarap-sisesinde-leylak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım kardeşim', 'canim-kardesim-hicabi-ceylan-kjel7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen uzaklarda olsan da

Sıcacık sevginle huzur bulur 

Nasırlanmış yüreğim

Karanlıklar seninle aydınlanır 

Sen zuhalyıldızım

Sen yüzünü bile görmediğim canım kardeşim

Benzersin  gözümde barış güvercinine

Su misali akarsın yetim gönlüme

Ne mutlu ki bana 

girebildiysem senin dost yüreğine

Sen zuhalyıldızım

Sen yüzünü bile görmediğim canım kardeşim

Anamız ayrı babamız ayrı ne fark eder

Seni tanıyınca kalmadı gönlümde

Ne tasa nede keder

Senden gelen bir merhaba bile bana yeter

Sen zuhalyıldızım

Sen yüzünü bile görmediğim canım kardeşim

Hangi çiçeğin ismiyle çağırsam seni 

Boz kırlarda açan papatyamı? 

Karlar arasında boy veren kardelen mi? 

Yoksa gülistan bahçesinde

Yeni tomurcuklanmış yedi veren mi? 

Sen zuhalyıldızım

Sen yüzünü bile görmediğim canım kardeşim

(canım kadar sevdiğim kardeşim Nuray  Alper’e)', 'Sen uzaklarda olsan da Sıcacık sevginle huzur bulur  Nasırlanmış yüreğim Karanlıklar seninle aydınlanır  Sen zuhalyıldızım Sen yüzünü bile g...', ARRAY['Türk Edebiyatı','Şiir','Hicabi Ceylan']::text[], 8.5, '{"poet":"Hicabi Ceylan","poet_slug":"hicabi-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/canim-kardesim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey aciz', 'ey-aciz-abdullah-garip-hs2e2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey aciz hakikati, fanide arıyorsun

Saadetin için başkasına felaket hazırlama

Bir gayeye proglanmış gidiyorsun

Sen bir ulaksın, icraat değil

Kendi dinamiklerine dönersen olur

Özüne irtibata geçen, sadakat-ı vefa bulur

Amaçsız,iradesiz insan; şeytanı yanında bulur

Bir gün bizimle olan devamlı vefa bulur', 'Ey aciz hakikati, fanide arıyorsun Saadetin için başkasına felaket hazırlama Bir gayeye proglanmış gidiyorsun Sen bir ulaksın, icraat değil ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ey-aciz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olecegim Senin Icin', 'olecegim-senin-icin-asik-kral-36eof', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kahroluyorum Seni Her Gördügümde

Boynumu Büküp Bakiyorum Yerlere

Kaybolan Benligimi Ariyorum Sanki

Ask Dedikleri Sey Bu Mu Ki? 

Gözlerine Her Baktigimda 

Umutsuzlugu Yasiyorum

Seni Sevdim Seveli

Hergün Ölümü Tadiyorum

Söküp Atacam Birgün Gönlümü

Bilmiyorum Bu Mümkünmü

Benim Halimi Hic Düsündünmü

Ölecegim Senin Için! ! !', 'Kahroluyorum Seni Her Gördügümde Boynumu Büküp Bakiyorum Yerlere Kaybolan Benligimi Ariyorum Sanki Ask Dedikleri Sey Bu Mu Ki?  Gözlerine He...', ARRAY['Türk Edebiyatı','Şiir','Asik Kral']::text[], 8.5, '{"poet":"Asik Kral","poet_slug":"asik-kral","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olecegim-senin-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hizmet', 'hizmet-abdullah-garip-p43pi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yürürken otururken Hizmet düşünen insan

Hizmet boşluğunda iş üreten insan

Uhut, Talha günüdür

Hizmet, adsız kahramanların günüdür

Her ağaç odundur

Meyve ağacı değerlendirir

Her insan insandır

Takva insanı değerlendirir

Şeref, ilim,marifet haslet-i insandır

Hasis,değersiz,zenginlik nedir?', 'Yürürken otururken Hizmet düşünen insan Hizmet boşluğunda iş üreten insan Uhut, Talha günüdür Hizmet, adsız kahramanların günüdür Her ağaç o...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hizmet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece', 'bu-gece-ferit-teksoy-bc4fr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Deniz kıpır kıpır ay ışığında

Yakamozlu yolun ta en başında

Hiçbir şey görünmez senin dışında

Gözlerim takılır kalır bu gece

Hayat akar gider yıldız kayımı

Alır gider günlerimi,ayımı

En çok seni sevdim aldım payımı

Efkâr efkâr dağılırım bu gece

Bu efkârla ne bulunsa içilir

Düşünceler meze olur saçılır

Ne sana gidilir,ne de kaçılır

Adımlar yerinde sayar bu gece

Teraziyle tartılmaz ki,kim suçlu

Hayat mı? ..çok aldı,o bana borçlu

İnişi çok azdı,çoğu yokuşlu

Onun kadar sana kızdım bu gece

Sızıncaya kadar gider bu fasıl

Ben dağıttım sen kendine bak asıl

Haklılar yurdunda hükümdar kesil

Ben suçlarda kalacağım bu gece

07 Temmuz 2004', 'Deniz kıpır kıpır ay ışığında Yakamozlu yolun ta en başında Hiçbir şey görünmez senin dışında Gözlerim takılır kalır bu gece Hayat akar gide...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bu-gece-85-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nesil Sancısı', 'nesil-sancisi-abdullah-garip-n1jd7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karanlık karanlığı kovaladı

Yapraklar dökülüp, tomurcuklar soldu

Asır geçti ümitler ümitleri kovaladı

Beyinlerde yeni nesil sancıları doğdu

Karanlığı delen ışık belirdi ufuklarda

Burcu burcu nesil meltemi şafaklarda

Kelebekler melteme, tomurcuklar filize

Beyinlerde yeni nesil sancısı doğdu', 'Karanlık karanlığı kovaladı Yapraklar dökülüp, tomurcuklar soldu Asır geçti ümitler ümitleri kovaladı Beyinlerde yeni nesil sancıları doğdu ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/nesil-sancisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nurlu Kafile', 'nurlu-kafile-abdullah-garip-e99b5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nurlu bir kafile önümüzden geçti

Gönülleri nurla, etrafı gülle donattı

Asırlar geçti sancak bu milleti seçti

Bugün o gönülleri, o gülleri arıyoruz

Kutlu beyanda kutlu yerini aldı

Zirvelere yükseldi, asırlarca kaldı

Davalarda, gayelerde,hedeflerde

Zirvelerde kalmak çok zordu', 'Nurlu bir kafile önümüzden geçti Gönülleri nurla, etrafı gülle donattı Asırlar geçti sancak bu milleti seçti Bugün o gönülleri, o gülleri ar...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/nurlu-kafile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ram Olup', 'ram-olup-abdullah-garip-et37r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vazifem sunucu değil

Hedefe ram olup, denileni yapmak

Vazifem ağı atmak; ağı çekmek değil

Hizmete ram olup, kapıyı çalmak

Ruha atmosfer lazım, hücre değil

Habil’in çocukları olup, gereğini yapmak

Akıl bir alettir, her şey değil

Yaşarken şoför gibi kolektif dikkati yapmak

Müşavere yolu emin bir yoldur

İnsanlık asr-ı saadeti imanda bulur

Aşk, şevk ve azimle çizilen bir yoldur

Mevzu hasbi vakıflık, akıl ve kalpte makes bulur

İmtihan; uzağınla,yakınınla,ehlinle olur

En büyük imtihan, yalnız kalmakla olur

yalnızken  karşı gelen, hoşnutsuzluk  yok olur

nefsinle baş başa,ona uyan kendini aşağıda bulur', 'Vazifem sunucu değil Hedefe ram olup, denileni yapmak Vazifem ağı atmak; ağı çekmek değil Hizmete ram olup, kapıyı çalmak Ruha atmosfer lazı...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ram-olup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Irmağı', 'sevgi-irmagi-abdullah-garip-kfs3u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sesin, sevgi ırmağı gibi akıyor

Bir demet gönül füsunu

Yüreğimin bam telinde vuruyor

Bir demet ışık saçan gözün

Duygularıma sunulan Kevser

Ruhuma sunulan hakikat

Gönül leblerimde Kevser

Üstünde hissimin, idrakimin, hakikat', 'Sesin, sevgi ırmağı gibi akıyor Bir demet gönül füsunu Yüreğimin bam telinde vuruyor Bir demet ışık saçan gözün Duygularıma sunulan Kevser R...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevgi-irmagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zorbalıktır', 'zorbaliktir-abdullah-garip-0ve2h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Toplum dinamiklerini hiçe saymak zorbalıktır

Tarlada mini etekle çalışmama da zorbalıktır

Kravatı, mini eteği medeniyet saymak sığlıktır

İnsanın insanlığı kalb-i kafasıdır, ne para ne kılıktır

Rüştüne erenler uzlaşabilir, değil çok bilmiş

Çocuklar ve de hayvanlar uzlaşamaz

İdraki gelişmiş, gönlü terakki etmiş

Siz solukları olmadan yaşanmaz', 'Toplum dinamiklerini hiçe saymak zorbalıktır Tarlada mini etekle çalışmama da zorbalıktır Kravatı, mini eteği medeniyet saymak sığlıktır İns...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/zorbaliktir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün martılar senin için umuda kanat açtılar...', 'bugun-martilar-senin-icin-umuda-kanat-actilar-nevin-kalafatoglu-75ozl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugün martılar senin için umuda kanat açtılar... 

demişti..

nisan 

o bir ay

o bir doğumgünü

o bir dost

o bir yağmur

o geçmişteki anılarda bir koca yürekli

o nevbahar ortası aşkı gönlümde

insan

öpsem martılarını uçuşlarındaki zarifliklerinde

umutlarımı toplasam bir kesekağıdına şimdi olmayan

üflesem kırlarında istanbulun 

nisanda açan ponpon ciceklerinde

gibi

bir fellini filminde

yaşasam 

Amarkord 

ben gelmek isteyipte gelemesem

teknelerin aşkları anlattığı dost gecelerine

yüreğim isyan

yüreğim feryat aşk

şiirim vuslat

olurmuydu

sence

dediğin gibi martıları istanbul

umut uçururmuydu bana

kanat seslerinde

nisan

içimde hasret 

özledim nankör anılarımın sehrini 

birtek sizinle tahamülüm

öldürdüğüm aşklarda ki şehirin

benim için toplarmısınız yıldızlarını

bir cam fanus içine

akvaryum 

boğazın işveli sesinde

nağmelerinizde

şiirlerinizde

kadehleriniz kalkarmıydı benim için ey dost

bu mecnun Akdenizde ama suan ruhu bizimle

diye

nisan? 

sorarım solmuş benzimle yolları... 

ararım bana açılmış kolları

ağlarım 

gelememe olasılıklarının 

dayanılmaz ağırlığı üstümde

07.07.2004

17 temmuz için  side karardı...:(', 'Bugün martılar senin için umuda kanat açtılar...  demişti.. nisan  o bir ay o bir doğumgünü o bir dost o bir yağmur o geçmişteki anılarda bi...', ARRAY['Türk Edebiyatı','Şiir','Nevin Kalafatoğlu']::text[], 8.5, '{"poet":"Nevin Kalafatoğlu","poet_slug":"nevin-kalafatoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/bugun-martilar-senin-icin-umuda-kanat-actilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzam', 'uzam-ahmet-aksoy-gog8y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'saat kaçı vurur yalnızlığın ötesinde

