INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bıktım', 'biktim-ozkan-kocak-0ilyu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir uzakdoğu dilinin camkırıkları saçıldı beynime

Yüreğimde eskimiş beklentilerle koşturmaktan bıktım

Tütün kokar ellerim utanırım

Umutlarım yorgun

Karlı dağlar ardına sürdüm hayallerimi

Kendi kendimi yaşatmaktan bıktım

Bıktım hayali sevgililer yaratmaktan

Seni seviyorum

Anla artık

Sözlerim korka korka yığılıyor kapına

Bıktım anlatamamaktan', 'Bir uzakdoğu dilinin camkırıkları saçıldı beynime Yüreğimde eskimiş beklentilerle koşturmaktan bıktım Tütün kokar ellerim utanırım Umutlarım...', ARRAY['Türk Edebiyatı','Şiir','Özkan Koçak']::text[], 8.5, '{"poet":"Özkan Koçak","poet_slug":"ozkan-kocak","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/biktim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmak', 'unutmak-ozkan-kocak-zzc6c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tahmin tutmaz gecelerim gidişinin üstüne

Günlerim uzak

Sebepsiz bir gülüşe benzettin beni

Beklerken bilmeden seni mi ölümü mü

Gözyaşı saklamak gibi seni unutmak', 'Tahmin tutmaz gecelerim gidişinin üstüne Günlerim uzak Sebepsiz bir gülüşe benzettin beni Beklerken bilmeden seni mi ölümü mü Gözyaşı saklam...', ARRAY['Türk Edebiyatı','Şiir','Özkan Koçak']::text[], 8.5, '{"poet":"Özkan Koçak","poet_slug":"ozkan-kocak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/unutmak-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Yollarında...', 'gonul-yollarinda-i-brahim-ethem-bingul-dco5x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seçilmiş hayatların

Karakter oyuncusuyum

Mimik ustalarına ders veriyorum

Ağlarken siyahlarda, 

Gülebilirim gökkuşağı ışığında..

Beyaz tek boynuzlu atım

Görünmez kılıcım

Uçan halım

Hepsi kaldı, 

Sedef dünyamda..

Çocukluk düşlerime sandal yaptım

Mavinin sonsuzluğuna bıraktım ki

Düşlerim bulsun seni

Gözlerin sustuğu gönül yollarında

Güneşin uzaklığnda ki yakınlığında...', 'Seçilmiş hayatların Karakter oyuncusuyum Mimik ustalarına ders veriyorum Ağlarken siyahlarda,  Gülebilirim gökkuşağı ışığında.. Beyaz tek bo...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gonul-yollarinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Neyim', 'ben-neyim-emin-baydil-usto3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hep sorarım kendime: Söyle gönül, ben neyim? ..

Ben, şu yalçın dağlardan, delice akan suyum.

Gecenin sessizliği, yalnızlığı başımda,

Sevginin gündoğumu, sabahın uykusuyum...

Akşamları okşadım, geceleri sevdim ben,

Çiçekleri büyüttüm, dikenleri gevdim ben,

Köprü altı olmadım, ocak idim evdim ben,

Ben ellerin nasırı, toprağın kokusuyum...

El emeği göz nuru, alın terinde vardım,

Zamandı harcım benim, ha bire zaman kardım.

Garibin hasret kokan, ahlarını duyardım,

Sılayım kucak açan, ellerin ayasıyım.

Her menzilde bir handa; konakladım, kaldım ben,

Her yolcudan halleri, haberleri aldım ben.

Kaybetmişim kendimi, bir ummana daldım ben,

Sanki rahmet görmemiş, bir hasret kuyusuyum.

Söyle gönül, ben neyim? ! Bunlardan hangisiyim? 

Neye, niçin âşığım? Hangisine asiyim? 

Sabahların müjdesi, gurbet elin yasıyım,

Ben mendilin oyası, kınalı dokusuyum.', 'Hep sorarım kendime: Söyle gönül, ben neyim? .. Ben, şu yalçın dağlardan, delice akan suyum. Gecenin sessizliği, yalnızlığı başımda, Sevgini...', ARRAY['Türk Edebiyatı','Şiir','Emin Baydil']::text[], 8.5, '{"poet":"Emin Baydil","poet_slug":"emin-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ben-neyim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül''e gül''e', 'gul-e-gul-e-zafer-zengin-etnika-h97bm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güle güle

Hüzünün sahibi

Bir çift küçük el

Selamınla ağlar dağlar

Nasıl kaçışdır

Son bulur gurbet

Öyküne saplanmadım

İçinde kaldım

Kolsuz 

Kanatsızdım

Uçamadım

La havle çektim

Dilime sürdü

Bu neyse

Bebe kaldı aklım

Gül''e gül''e

Ayrılık

Apansız

Hıçkırıksız kaçman

Dilime dolamış mevsimi

Özlesem ayıp mı

Şu gelmeyen sesini

Kaldım

Oldum

Ayrıldım

Günüme dolan rüzgara kapıldım

Hayındın anladım

Çalar kaçardın

Ah sızım

İkidir

Öğütüyorum elimde ne varsa

Ermiyor sonucum başa

Dağılıyorum

Baştan tırnağa

Sen yok musun

Gül''e Gül''e

İsim verdim

Sen diye

Beğenmemişsin

Düşmüşsün el bahçesine

Hüzzam düş şarkıları

Adın anılsın yalnızlıkla

Sana dedim

Gül''e

Gül''e

Gülümse

İş düşmüş başına

İntikam saatini sakla yanına

Zırhını çıkarma

Ölürsün zaten

Gülümsemen olmasa

Gül''e

Gül''e

29 Haz. ''04 '' Kısaldı herşey..yokluğunda ''', 'Güle güle Hüzünün sahibi Bir çift küçük el Selamınla ağlar dağlar Nasıl kaçışdır Son bulur gurbet Öyküne saplanmadım İçinde kaldım Kolsuz  K...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/gul-e-gul-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tuz', 'tuz-zafer-zengin-etnika-i2it4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Olmasa

