INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siz nereden bileceksiniz?', 'siz-nereden-bileceksiniz-arzu-dincer-b7npy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Fırtınaların yıprattığı yolları,

Güneşin tutsak kaldığı ömrü..

Söyleyin siz nereden bileceksiniz? 

Ateşinin donduğu yürekleri,

Yarını göremeyen ümitleri,

Yitip yitip bulmaları,

Kaybetmenin acısını,

Siz nereden bileceksiniz? 

Tam tutmuşken kenarını,

Elden kayan hayatları,

Yaşanmayan yaşanmışlıkları,

Söyleyin siz nereden bileceksiniz?', 'Fırtınaların yıprattığı yolları, Güneşin tutsak kaldığı ömrü.. Söyleyin siz nereden bileceksiniz?  Ateşinin donduğu yürekleri, Yarını göreme...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/siz-nereden-bileceksiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayata Dair (II)', 'hayata-dair-ii-arzu-dincer-54c7a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dilenci yaşayanlar,

Hayatı kendine sananlar,

Vicdan denizinden yoksunlar,

Hayat, size baki kalacak mı? 

Ufukları cüzdanla çizilenler,

Onurunu yemişler,

Kör kuyulara girmişler,

Hayat, size baki kalacak mı?', 'Dilenci yaşayanlar, Hayatı kendine sananlar, Vicdan denizinden yoksunlar, Hayat, size baki kalacak mı?  Ufukları cüzdanla çizilenler, Onurun...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hayata-dair-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne zaman uyudun gözüm...', 'ne-zaman-uyudun-gozum-yusuf-ziya-leblebici-gid6f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu toprakta nefes alıp

İnsan gibi yaşıyorsan

Parmaklığı mektep yapıp

Islahevi görüyorsan

   Vallah billah yalan sözüm 

   Ne zaman uyudun gözüm

Ezilenken şah mı oldun

Padişaha baş mı oldun

Viraneden saraylara

Elmastan bir taş mı oldun

Düşünceni söylediysen

Zındanlara girmediysen

Bir terslik var bu gidişte

Darağcına gitmediysen

   Vallah billah yalan sözüm 

   Ne zaman uyudun gözüm

Gözüstünde kaş mı oldun

Gözlerinde yaş mı oldun

Ayrı yoldan gider iken

Yollarına daş mı oldun

Uyan gözüm bu uykudan

Gördüklerin billah yalan

Sen insansın insan kalan

İnsansın diye suçlanan', 'Bu toprakta nefes alıp İnsan gibi yaşıyorsan Parmaklığı mektep yapıp Islahevi görüyorsan    Vallah billah yalan sözüm     Ne zaman uyudun gö...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ne-zaman-uyudun-gozum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarapçı Baba...', 'sarapci-baba-yusuf-ziya-leblebici-qszf4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Altımdaki halılar yazın karton,

   kışın çim olur ama,

boğazımdan süzülen şu şarabım 

   hiç mevsim tanımaz.

bir rengini bilirim

   kan gibi kırmızı

      su gibi beyaz.

İnsanlardan alamadığım tatta

   sevgi içerim yudum yudum.

Ne işim var mutluluk olmayan sarayda

anlık sevinçler yetiyor bana bu köprü altında.

Ben Şarapçı Baba,

kimine dilenci, 

   kimine kalmamış direnci.

Çocuklar sever beni, 

   analarından korksalar da.

geceler ayyaşım amma,

gündüzlerde bebelere oyundaşım.

Taş atarlar bana,

  babalarının tekme attıkları gibi.

sevilenim ben oyundaşta

itilenim ben tekme attıkça...

Bir şarabım, bir de köprü altım var

      duvarsız sarayım.

İhanetim yok ki kendime kazık atayım.

Param yok ki duyguları satın alayım! 

Ben Şarapçı Baba, 

kimine göre babaların yüz karası,

kimine de şişelerin en babası! 

Babalar sevmez beni

  hükümet baba

    devlet baba

      mafya baba,

bense bunların arasında sahte baba! 

Bir de amca var, 

dedemizin nerden torunuysa! 

Bazen ben de aldatılırım

  dost bildiğim şişelerce.

Bir bakarsın lebelep sevgi dolu

bir bakarsın dibine inmiş, sevgi bitmiş

  bana ihanet etmiş...

Ben de sahip çıkarım denizime sizler kadar

Lakin, siz dışarıda giyinikken ben çıplağım,

Siz burada çıplakken ben giyiniğim.

Yıldızlar benim de yıldızım, benim de ayım,

Lakin, siz sevgilinizle mehtaba giderken

ben şişemle sevişirim.

Siz, cam bardakları şerefinize vururken

ben şişeleri göğsüme çarparım...

Ben Şarapçı Baba; 

Siz yaşarken küçük bahçede

  ben dolaşırım koca evrende

çok şey yaşayamasamda pencerelerde

gerçekleri görürüm gözlerimle! ..

Amcalarım, babalarım takmasalar da beni

takacak şeyler bulurum sevgisizlik, insanlık gibi.

İtilen canlara tekme atmak

   çalanlara madalya takmak gibi.

Köprülerin altında yatmak

   zındanda yatmaktan, 

yargısız insaftan daha da iyi.

Yozlaşmış, 

yozlaştırılmış insanların şerrinden daha da iyi.

Verilseydi insana insan değeri

ne işim vardı bu şaraplarda

yoksa olur muydum ben Şarapçı Baba! ...', 'Altımdaki halılar yazın karton,    kışın çim olur ama, boğazımdan süzülen şu şarabım     hiç mevsim tanımaz. bir rengini bilirim    kan gibi...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/sarapci-baba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün', 'bugun-arslan-arslan-er6ts', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana..

Kalbim bir kuş gibi çırpınırken

Bile....

Senin için

Yinede sen yaralı kanadımı sarmadın

Sana uçmak isteyen kalbimin

Sessiz kaldığını bilerek

Sensiz kaldığını bilerek

Yazmadım

Şu çırpınan küçücük yüreğimde

Kuruyan denizleri,okyanusları

Görmedin mi? 

Aldın bütün benliğimi

Sevgimi,aşkımı

Suyun üzerine mi yazdın

Aşkını 

Yoksa buğulu camlara mı yazdın

Sevgini

Senin için benim anlamım bu kadar mı? 

Manasızmış bütün duyguların

Yoksa

Fırtınadan kaçan bir gemi misali

Sığınmak için liman olarak benimi seçtin

Unutamadığın mı var....

Teselliyi bende mi aradın

Kendini böyle mi avuttun yoksa

Unutma....

Ben ne bir zoraki sığınma limanı

Ne bir dilek ağacı

Ne de bir..

Teselli verecek

Dertlerine bir türbe değilim

Ben sadece

Seni çok seven biriyim

Geçmişinden,yaşanan mazinden

Kurtulduğunda....

Sana kalbim.sana kollarım

Her zaman açık olacak aşkım.

Arslan ARSLAN          24.08.2015', 'Sana.. Kalbim bir kuş gibi çırpınırken Bile.... Senin için Yinede sen yaralı kanadımı sarmadın Sana uçmak isteyen kalbimin Sessiz kaldığını ...', ARRAY['Türk Edebiyatı','Şiir','Arslan Arslan']::text[], 8.5, '{"poet":"Arslan Arslan","poet_slug":"arslan-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/bugun-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Minerva...', 'minerva-naime-erlacin-1hx76', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sözdür boşluğu dolduran

tenhâda ürkülür eksilmekten 

tenhada sevilir çoğalmak 

taşa siner kokusu sessizliğin

sussa da ibadet edercesine

suya aykırıdır kabında durmak

denizi karşılamasından belli

geçmiş hikâyelerin sesi

cama dönüşür ayna

acıyı inler müebbet mermer

altın bir demlik sunulur ruha 

‘sus’ gemisinin son limanında

direnir oysa taşa yontulmuş ölüm 

bir tanrıça 

iğdiş edilmiş dimağa ağıtlar yakar

şafaktan dolunaya uçuşur sözcükler

sindirerek kokusunu zamana

sus’un sonsuz ufkunda 

''konuş! '' der Minerva*:

''her hayat yalanını saklar kaçışlarında! ''

yağmurunda ıslan önce 

dişidir şiir:

konuş

susma! '' 

(*)       Minerva: Bilgelik, zekâ, sanat ve edebiyatı temsil eden Yunan tanrıçası.

(9 Temmuz 2004)', 'sözdür boşluğu dolduran tenhâda ürkülür eksilmekten  tenhada sevilir çoğalmak  taşa siner kokusu sessizliğin sussa da ibadet edercesine suya...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/minerva-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhtiyar Yaş', 'i-htiyar-yas-i-hsan-uncuoglu-k9u6e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İhtiyarlık kaçınılmaz gelir bedene

Gençlik hayal olur uzakta gerilerde

İnsan anlamadan döner bir Meleğe

Gençliğe dön bir daha geçmiyor ki ele,

***

İhtiyarın her an düşüncesinde binbir kanaat

Ey şair yaz aşk, yaz gençleri coştur aydınlat 

Düşe kalka herbir  ihtiyarın yürüdüğü dönüşsüz 

O tek yolda ölüm düğün hak! ,yap bir kıyak,', 'İhtiyarlık kaçınılmaz gelir bedene Gençlik hayal olur uzakta gerilerde İnsan anlamadan döner bir Meleğe Gençliğe dön bir daha geçmiyor ki el...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ihtiyar-yas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alo Dahran!', 'alo-dahran-naime-erlacin-r9dvl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'alo Dahran! 

bugünden tezi yok

huzurlarınızda yeni bir dosya açıyorum

vatana millete hayırlı, falan feşmekân olsun

fiş-mekân da olabilir hani

fişleyelim sizi! 

buyuran sağ olsun 

buyurmayan da

hoş gelmiş 

hoş düşmüşsünuz

çiçeği burnunda saçmalıklarımıza

ding dong! 

emrinize amadedir hanımefendiler

efendilerin hanımları 

emrinize amadedir 

“en” yüksek piyasa! 

alo Dahran

yangın var 

duyamıyorum seni:

-ver abi bir Bodrum

onunla idare ederim ben-

takıntılı 

ve paranoyak olsun

gazozu bol tut mutlaka

içki içmem biliyorsun

Bodrum şişenin dibine 

ben gazozla dünyanın

şerefe barmen! 

bugün de böyle olsun

(9 Temmuz 2004)    – “Yeni Dosya”dan…', 'alo Dahran!  bugünden tezi yok huzurlarınızda yeni bir dosya açıyorum vatana millete hayırlı, falan feşmekân olsun fiş-mekân da olabilir han...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/alo-dahran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köy kütüğü', 'koy-kutugu-burhan-kucuk-myho3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Köy kütüğü

Gün gelir,döner devran

Silinirsin zamandan

Bir ölü köy kütüğünde

Kalır bir zaman adın

Mezarına vurur otoban

Ya da temeli bir evin

Yalnız başına kalırsın

Orta yerinde şehrin

Burhan KÜÇÜK

Kdz.Ereğli-08.07.2004', 'Köy kütüğü Gün gelir,döner devran Silinirsin zamandan Bir ölü köy kütüğünde Kalır bir zaman adın Mezarına vurur otoban Ya da temeli bir evin...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/koy-kutugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazır Bu Ateşle...', 'hazir-bu-atesle-bekir-mutlu-gokcesu-66110', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Korkma

Hadi gel

Güneşin battığı yere

Yangınına gidelim

Bir çift körük yürekle

Hepten yakalım denizleri

Veya yanalım hepten

Hazır bu ateşle...

Ya da kork, gel yine

Bir kayık

Bir çift yürekli kürekle

Geçelim bu denizden

Her gün doğacak olsa da

Geçelim tunçtan tepelerde

Ardında yiten güneşten

Hazır bu ateşle...

Bu defa

Bir dilek tutmayalım

Bir düş de kurmayalım

Sarılıp ağlayalım sadece

Son kez ve özgürce 

Hazır bu ateşle...', 'Korkma Hadi gel Güneşin battığı yere Yangınına gidelim Bir çift körük yürekle Hepten yakalım denizleri Veya yanalım hepten Hazır bu ateşle.....', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hazir-bu-atesle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşkiya', 'eskiya-ali-gencay-7g3cf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ruhumu eşkıyalar başmış,pusuda çok bekleyenlerim

Hadi şimdi uyu nöbetlerimde,kahpedir şer gecelerim

As çaprazına mavzerini,bir atımlık barutu ikiye bölelim

Söndür ateşi, zifiri karanlık da iki eşkıya,ayı ateşe verelim

Sen sevdalarını anlat, ben sana yıldızları sayı vereyim

Eşkıyalarda ağlar, ağla,ben sana yağmurla gelenim

Şafak rengi düşsün gözlerine,güneşe nöbeti devredeyim

Gideceksen durma git, her gece ayı ateşe verip bekleyeceğim', 'Ruhumu eşkıyalar başmış,pusuda çok bekleyenlerim Hadi şimdi uyu nöbetlerimde,kahpedir şer gecelerim As çaprazına mavzerini,bir atımlık barut...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/eskiya-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çivi', 'civi-yildiz-yildiz-4064q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Anlamalarım! ! 

Ahh o anlamalarım! ! ....

Gerçek mi sanrı mı

Bir türlü ayırdına varamadığım

Aklımın çivisi... 

anlamalarım..

Hayal merdiveninden

Yuvarlanırken sanmalarım..

Kıra döke cam basamakları

Mavi kanlar dökerek

Çıktı ilk çivisi aklımın! ..

Tam oraya! ...

Cevizin gölgesindeki 

Kuruntu toprağımın

Hüsnüne gömdüm 

O ilk çiviyi..

Tam orada..

Cevizin dibinde görmüştüm

Bir ceviz kabuğuna tıkıştırmaktaydın

pür telaş bütün kırılgan ışıklarını..

Tam orada..

Tam da cevizin dibinde başardın

Şimdi kim...

Hangi ışık kırıcısı ulaşabilir ki

Çetin ceviz kabuğuna? 

Korkma kırılmaz artık

En kırılgan ışıkların', 'Anlamalarım! !  Ahh o anlamalarım! ! .... Gerçek mi sanrı mı Bir türlü ayırdına varamadığım Aklımın çivisi...  anlamalarım.. Hayal merdiveni...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Yıldız']::text[], 8.5, '{"poet":"Yıldız Yıldız","poet_slug":"yildiz-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/civi-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evlerin Işıkları', 'evlerin-isiklari-hulya-topcuoglu-6ayd5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gecenin içindeyim, sokakta bir başıma 

Evlerin yanan ışıklarını seyrediyorum

Bir eve gözüm takılıyor, nedensiz

Sanki kadının yüzünde bir hüzün 

Görüyor gibi oluyorum, 

Üzülüyorum....

Bir başka eve takılıyor gözüm,

Parlak ışıklar saçılıyor odalarından 

Aydınlık yüzlü, gülen insanlar

Görüyor gibi oluyorum

Seviniyorum...

Evlerin ışıkları gecenin bir yarısında

Yalnızlığımın tek arkadaşı,

Her sönen ışık içimi acıtıyor

Terkedilmiş gibi oluyorum,

Ürperiyorum', 'Gecenin içindeyim, sokakta bir başıma  Evlerin yanan ışıklarını seyrediyorum Bir eve gözüm takılıyor, nedensiz Sanki kadının yüzünde bir hüz...', ARRAY['Türk Edebiyatı','Şiir','Hülya Topçuoğlu']::text[], 8.5, '{"poet":"Hülya Topçuoğlu","poet_slug":"hulya-topcuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/evlerin-isiklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tehditin Titrek Kandili', 'tehditin-titrek-kandili-nal-n-yildiz-2kbul', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''Okuldaki en korkunç rüyayı ben görüyorum'' dedi 

Leyli mektepli,

Anası ağladı...

''Allah''a emanet ol yavrum...'' derken

Çaresiz

Kaybettiklerini hatırladı

Zihninde ufaladı kırıntılarını ümidin

Yüzlerce serçe havalandı

Yağmur duaya açılmış hanımellerine düşüyordu

''Bu defa emanetime ihanet etme'' diyen 

Kadının gözlerinde 

Tehditin titrek kandili de üşüyordu', '''Okuldaki en korkunç rüyayı ben görüyorum'' dedi  Leyli mektepli, Anası ağladı... ''Allah''a emanet ol yavrum...'' derken Çaresiz Kaybettiklerin...', ARRAY['Türk Edebiyatı','Şiir','Nalân Yıldız']::text[], 8.5, '{"poet":"Nalân Yıldız","poet_slug":"nal-n-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tehditin-titrek-kandili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayrağım: Ay Yıldızım, Kan Kırmızım!', 'bayragim-ay-yildizim-kan-kirmizim-necmi-unsal-tg9sm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey gönlümün sultanı, ay yıldızım, kan kırmızım! 

Sensiz mekanlar çöl, sensiz hayata kayıtsızım.

Binlerce yıldır  taşırsın sinende yüce ruhu! 

Barındırmaz şanlı gölgen  hiçbir  hain güruhu.

Sen ocağımın ateşi,  evimin  nazlı süsü.

Sensiz bu gökler hep yaslı,  bozulmuştur  büyüsü.

Sana tüter,  ateşinle yanan gönülde  saygı.

Sensin şanlı şehidimin üstünde  kutlu  yaygı.

Taşırsın, mübarek, kutlu bir zat gibi  vakarı.

Olmasın semada hiçbir bayrak, senden yukarı.

Başın göklerde, rüzgarla, şimşekle iç içe.

Sana ölür can, şahadet  şerbeti içe içe.

Hürriyet  ve iman için akan  al kanlar rengin.

Büyüksün, bütün  alemler taransa  yoktur dengin.

Ay yıldızınla birleşir İslamlık, Türklük,  kaynar.

Seni indirmeye kalkan hep hayatıyla oynar.

20 Nisan 2004 Salı, Danimarka-Køge 21.47 *8+7', 'Ey gönlümün sultanı, ay yıldızım, kan kırmızım!  Sensiz mekanlar çöl, sensiz hayata kayıtsızım. Binlerce yıldır  taşırsın sinende yüce ruhu!...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bayragim-ay-yildizim-kan-kirmizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Adliye Koridorlarında', 'adliye-koridorlarinda-nurten-altinok-z5z6k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '‘‘ Oy kaşına gözüne kurban olduğum

                           Oy yüreğimin dört kapısı oğlum ’’

Mübaşirin sesi duyuldu

Adı Hasan’dı birinin

Diğerinin Hüseyin 

Çağırdığı.

Soyadları yankılandı 

Adliye koridorlarında Bakırköy’ün

Duyulmadı

Duyamadım 

Sis kaplamıştı ayak seslerini

Takım elbise altında gizlenmişti sanki

İki gencecik fidan 

İki delikanlı yüreği

Belliydi,

Yüzlerine vurmuştu ayıbı

İki demir kelepçenin

Bileklerini hapsettiği

Duyacaktım belki 

Kalp atışlarını 

Biraz daha yakınımdan geçselerdi

Soramadım neydi suçları

İki asker sağlı sollu

İki asker

İkisi de silahlı

Görevleriydi...

Görevliydiler besbelli

Kaçmasın diye uçurtmalar umuda

Tutmuşlardı iplerini

Bakışları birleşti ürkek

Bakıştılar 

Kimbilir kaçıncı bin kez

Sorularına yanıt aradılar

Dipfrizde unuttukları canlarında 

/ yarınlarına

Soramadım neydi suçları

Hafiften öksürdü birisi

Diğeri sendeledi

Ha düştü ha düşecek! 

Elim havada kaldı! 

Güneşi aradım

Rüzgarı, bulutları

Betondu adliye duvarları

Karanlıktı koridorları

Kokunun acıydı rengi

İçim acıdı

Yandı

 ‘’Oy kaşına gözüne kurban olduğum

Oy yüreğimin dört kapısı oğlum’’

Bakışlar, ok gibi ayni yöne fırladı

Bir kadın! 

Nasıl toplanır bir gözde 

Ayni anda bu kadar nefret

Kin özlem sevgi

Kimeydi hıncı sesinde hapsettiği 

Koşmak istedi düzeltip başındaki tülbendi

Elinin tersiyle silip gözlerini

‘’Oy kaşına gözüne kurban ''''

Bitiremedi

Yığılıp kalıverdi

Kelepçeler açılmadı! 

Mübaşirin sesi duyuldu

Hasan

Hüseyin

Duruşma başladı

Haydi içeri...', '‘‘ Oy kaşına gözüne kurban olduğum                            Oy yüreğimin dört kapısı oğlum ’’ Mübaşirin sesi duyuldu Adı Hasan’dı birinin ...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/adliye-koridorlarinda-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlü Sözlerim 8', 'ozlu-sozlerim-8-fatih-taskin-yug38', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Saç kadar,başım olsa.....

Hak yoluna olsun  feda.....', 'Saç kadar,başım olsa..... Hak yoluna olsun  feda........', ARRAY['Türk Edebiyatı','Şiir','Fatih Taşkın']::text[], 8.5, '{"poet":"Fatih Taşkın","poet_slug":"fatih-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/ozlu-sozlerim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göçmen kuş...', 'gocmen-kus-i-brahim-ethem-bingul-ztyec', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğim takılı kaldı

Güneye uçan bir göçmen kuşa

Kalbimi alıp da uçtu

Beni yapayalnız bıraktı

Kuzeyin sert kışında

Buz yağan bu dağlarda

Ağaçların beyaz örtülü dallarında

Aşkımın ateşiydi ısıtan seni

Göçmenlere kanıp güneye döndü kanadın

Güneş bir güneyi ısıtır sandın

Bilirsin sen de aslında

Sıcaklık güneşte değildir

Güneşin cihana olan aşkında

Artık baharla gelsen nafile

Dönsen alevler içinde bile

Şimdi ne bahar dinlerim,ne sevda

Affetmem muhtaç ettin beni

Bir damla mutluluk yaşına

www.iebingul.com', 'Yüreğim takılı kaldı Güneye uçan bir göçmen kuşa Kalbimi alıp da uçtu Beni yapayalnız bıraktı Kuzeyin sert kışında Buz yağan bu dağlarda Ağa...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gocmen-kus-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mim Koydum', 'mim-koydum-ahmet-turan-altunsu-vuv0l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '(kime mi yazılmış? .. ismi lâzım değil birine efendim :))) 

Hey, gösterişli adam; alımına mim koydum,

Ne kıvır, ne de kıvırt; çalımına mim koydum,

Caka satma mihrapta; hitabın can sıkıyor,

Senden büyük Allah var; ulumana mim koydum! 

Pöstekinin üstünde duruyorsun, dikkat et! 

Saydırır kıllarını günü gelince millet! ..

Hey gösterişli adam; hiddetinden çok korktum(!) 

Çok büyüksün ya hani; kudretinden çok korktum(!) 

Öyle kükrüyorsun ki; titretir yüreğimi,

Çınlar kulaklarımda; şiddetinden çok korktum(!) 

Pöstekinin üstünde duruyorsun, dikkat et! 

Saydırır kıllarını günü gelince millet! ..

Zam üstüne zam gelir; hayret, enflâsyon düşmüş(!) 

Milletin emeğine akbabalar üşüşmüş! 

Ne kadir, ne de kıymet biliyormuşsun meğer:

Umurunda mı, millet istikbaline küsmüş? 

Pöstekinin üstünde duruyorsun, dikkat et! 

Saydırır kıllarını günü gelince millet! ..

Koyun mu sandın halkı,horlayıp duruyorsun,

Her gün başka bir telden ırlayıp duruyorsun? 

Bol bol gündem kaydedip; elin bilmem nesiyle

Boy gösterip, vecd(!)    ile zırlayıp duruyorsun? ..

Pöstekinin üstünde duruyorsun, dikkat et! 

Saydırır kıllarını günü gelince millet! ..

………………………09.07.2004 / Ankara', '(kime mi yazılmış? .. ismi lâzım değil birine efendim :)))  Hey, gösterişli adam; alımına mim koydum, Ne kıvır, ne de kıvırt; çalımına mim k...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/mim-koydum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilemma', 'dilemma-ahmet-turan-altunsu-i8w7x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bu ateş,

göz göze geldiğimiz an sönecek belki,

ya da yüreklerimizde 

kor ateş oluncaya dek yanacak belki! ...

……………………08.07.2004 / Ankara', 'bu ateş, göz göze geldiğimiz an sönecek belki, ya da yüreklerimizde  kor ateş oluncaya dek yanacak belki! ... ……………………08.07.2004 / Ankara...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dilemma-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kölenim', 'kolenim-ahmet-turan-altunsu-50get', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben; aşkı, yaşamın ta kendisinde görürüm,

Süslememe gerek yok görkemli tasvirlerle…

Bir dişi ve bir erkek… tutkularımız var ya:

Sevgilinin doyumsuz sinesinde görürüm,

Gönlüne teslim olmuş bendesinde görürüm! ..

…………………………08.07.2004 / Ankara', 'Ben; aşkı, yaşamın ta kendisinde görürüm, Süslememe gerek yok görkemli tasvirlerle… Bir dişi ve bir erkek… tutkularımız var ya: Sevgilinin d...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kolenim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vedasız Ayrılık', 'vedasiz-ayrilik-sirma-mersin-zhp44', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anlık mutluluktan sonra

Geri dönüşü olmayan sözlerle

Bıçak yarası gibi iz bırakan ayrılık vardı, yürekte...

Vazgeçilen alışkanlıkların arasına girmiş, bir kadın...

Kaçışın içine sıkıştırılmış,

Acı vedaların seslenişini seslendiren, bir adam...

Farklı yerlerde yaşamaya mecbur kalmış,iki yürek var...

.............................................................................................

.............................................................................................

............................................................................................

Ayrılığın dilsiz oluşunu

Kıldan ince sözlerin

Yüreği kanattıktan sonra...

Tükenmiş bir sevdanın  arkasından kalanlar....

08.07.04', 'Anlık mutluluktan sonra Geri dönüşü olmayan sözlerle Bıçak yarası gibi iz bırakan ayrılık vardı, yürekte... Vazgeçilen alışkanlıkların arası...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/vedasiz-ayrilik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim bilir', 'kim-bilir-halil-i-brahim-ozdemir-4ww5r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ateşine yanmışım, yakmaz cehennem beni

Sularında boğulmuşum, kim kurtarır bu teni

Derin uykudayım hangi ülkelerde yaşarım

Kimler bilir kim getirir ölümlere gideni?', 'Ateşine yanmışım, yakmaz cehennem beni Sularında boğulmuşum, kim kurtarır bu teni Derin uykudayım hangi ülkelerde yaşarım Kimler bilir kim g...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özdemir']::text[], 8.5, '{"poet":"Halil İbrahim Özdemir","poet_slug":"halil-i-brahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kim-bilir-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-adem-kunt-uoy7c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen bir hasret değil,yaşanan düştün,

Bu gece aklıma yine sen düştün…

Bir tatlı hayaldi ki,yaşadım seni,

Bu gece aklıma yine sen düştün…

İşte şimdi karşımda duruyorsun,

Ceylan bakışınla beni vuruyorsun,

Ben seni yazıyorum, sen susuyorsun,

Bu gece aklıma yine sen düştün…

Perçemin başında yedi başlı ejderha,

İçimdeki yangını ne su  söndürür,ne derya,

Bir busen yeter bana,lakin eller ne der ya,

Bu gece aklıma yine sen düştün…

Öyle dur,ben sana bakayım sen gülümse,

Yanağında açan gül,benim son gülümse,

Göz kırpmadan gelirim,sonu dahi ölümse,

Bu gece aklıma yine sen düştün…

Gül yüzünde güller açar sen gülünce,

Gelen sen oldukça beklerim ömrümce,

Şimdi seni, sensiz yaşıyorum kendi gönlümce,

Bu gece aklıma yine sen düştün…

Ben senin kapında aşık-ı biçareyim,

Ya aç kapını,ya yol ver gideyim,

Ama sensiz ellerde acep ben nideyim,

Bu gece aklıma yine sen düştün…', 'Sen bir hasret değil,yaşanan düştün, Bu gece aklıma yine sen düştün… Bir tatlı hayaldi ki,yaşadım seni, Bu gece aklıma yine sen düştün… İşte...', ARRAY['Türk Edebiyatı','Şiir','Adem Kunt']::text[], 8.5, '{"poet":"Adem Kunt","poet_slug":"adem-kunt","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dus-86-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Dağı', 'gonul-dagi-adem-kunt-kgcxf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gel,dedim sana yar,

gelmedin,

niçin? 

Anlayamadım,

gelmen için,

o yüce dağlar mı engel? ..

Bilmez misin ki; 

sevgiliye giden yollar,

dağlarında üstünden geçer…

Gel! ...

Yağmur yüklü bulutlar gibi,

ürün de gel…

Ya uç kuşlar gibi özgürce,

Ya da bir yılan gibi,

sürün de gel…

Ama gel…

Mantıksızda olsa gelmen sence,

akıl işi değilse bile,

gel…

Masum olmasada gözyaşlarım,

sana ulaşmak için,

aşamasada gönül dağını,

inan onlara…

İnan dedim sana yar,

inanmadın niçin? 

Anlayamadım,

inanman için,

gönül dağın mı engel? ...

Bilmez misin ki; 

sevgiliye giden yollar,

dağlarında üstünden geçer…', 'Gel,dedim sana yar, gelmedin, niçin?  Anlayamadım, gelmen için, o yüce dağlar mı engel? .. Bilmez misin ki;  sevgiliye giden yollar, dağları...', ARRAY['Türk Edebiyatı','Şiir','Adem Kunt']::text[], 8.5, '{"poet":"Adem Kunt","poet_slug":"adem-kunt","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gonul-dagi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-adem-kunt-sf8ze', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nedenler, niçinler,nedendir bitmez? 

Yanan gönüllere ab,bulunur bir gün…

Böyle gelmiş ama bu böyle gitmez,

Sorulara bir cevap bulunur bir gün…

Yüreğimde ateş yanar dumanı tütmez,

Gül dalındaki bülbüller nedendir ötmez,

Dertler var dert üstüne çareler yetmez,

Her derde bir çare,bulunur bir gün…

Rest çektim artık dumansız bacalara,

Pes ettim şimdi ben şu bitmez acılara,

Yaşamı zehir eden çekilmez sancılara,

Vardır elbet ilaç,bulunur bir gün…

Herkeste ayrı bir sevda gönüller huzursuz,

Dalında garip solan güller huzursuz,

Solan güle hasretten bülbüller huzursuz,

Huzur veren bir sevda,bulunur bir gün…

Gitti artık gelmez bekleme diyorlar,

Gün aşırı derdine dert ekleme diyorlar,

Düz yolda doğru git tekleme diyorlar,

O gelmezse, gelen, bulunur bir gün…', 'Nedenler, niçinler,nedendir bitmez?  Yanan gönüllere ab,bulunur bir gün… Böyle gelmiş ama bu böyle gitmez, Sorulara bir cevap bulunur bir gü...', ARRAY['Türk Edebiyatı','Şiir','Adem Kunt']::text[], 8.5, '{"poet":"Adem Kunt","poet_slug":"adem-kunt","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/umut-125-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşün', 'dusun-adem-kunt-egcq2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağlayabilsem  bugece,

akıtabilsem,

bütün yaşımı…

Ağlayabilsem bu gece,

duvarlara vurup,

dertli başımı…

Ağlasam,ağlasam,

hep ağlasam,

unutabilsem bir an için,

gülmeyi…

Ağlaya ağlaya,

yüreğimi dağlasam,

düşünebilsem her için,

ölmeyi…

Düşünebilsem,

nerde,ne zaman, nasıl,

uçacak can kuşum bedenden? 

Tenasüh mü? 

Onu bilsem asıl…

Nerden geldi bu can bana,

hangi tenden? 

Nerden geldi,

nereye gidecek bu can? 

Nerdeydi daha önce,

bilmem acaba nerde? 

Gökler su,

hava nefes vermem,

dediği an…

nerde bulurum suyu,

nefesi hangi elde?', 'Ağlayabilsem  bugece, akıtabilsem, bütün yaşımı… Ağlayabilsem bu gece, duvarlara vurup, dertli başımı… Ağlasam,ağlasam, hep ağlasam, unutabi...', ARRAY['Türk Edebiyatı','Şiir','Adem Kunt']::text[], 8.5, '{"poet":"Adem Kunt","poet_slug":"adem-kunt","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/dusun-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uhde', 'uhde-adem-kunt-kh9pj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir uhde…

Korku ve ümitle birlikte,

içimde bir uhde…

Geceleri sıcacık yatağımda,

çayımı yudumlarken sıcak sıcak,

evimin çatısına vururken yağmur..

İşte bu tatlı musikinin yanında,

içimde bir uhde…

Bin dert,

bir direniş

ve yürüyorum sonsuza…

Dağ,taş,sesleniyor,

ova,bayır,ağaç,çimen…

Bir kalp atışı duyuluyor,

derinden,derinden…

Toprak…

Bir toprak yığını duruyor önümde,

ama içimde bir direniş,bir ukde…

Bir sevgi…

Mal,mülk,servet sevgisi değil! 

Bir araba,bir kadın asla değil! 

Sevgim,sevgilim bu,

bir avuç toprak! ..

Ve hasret…

Hasretim,çölde açan gül misali suya…

Hasretim,gül için yanan bülbülün aşkına! 

Buram buram hasret kokan vatan…

Bu ihtiras uğruna geçtik,

anadan,yardan,candan…

Gözyaşıyla ıslanmış güller asla solmaz..

Ana gibi yar,vatan gibi diyar olmaz…

Bizi kendimizden geçirdi,

bu özlem,bu daüssıla…

Senin yolundayız Nebiyy-i Mualla,

dönmeyiz asla! …

Vatanımın uğruna gerekirse veririm başım,

Hasretimim son durağı,işte bu mezar taşım.

Canını veremezsen vatanına, suyu bile haramdır içilmez…

Bizde bu aşk varken, Çanakkale geçilmez…', 'Bir uhde… Korku ve ümitle birlikte, içimde bir uhde… Geceleri sıcacık yatağımda, çayımı yudumlarken sıcak sıcak, evimin çatısına vururken ya...', ARRAY['Türk Edebiyatı','Şiir','Adem Kunt']::text[], 8.5, '{"poet":"Adem Kunt","poet_slug":"adem-kunt","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/uhde-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırlayınca', 'hatirlayinca-caner-kuru-h482v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçimi garip bir heyecan sardı,

O güzel günleri hatırlayınca.

Yanımda ne sen ne başkası vardı,

O güzel günleri hatırlayınca.

Burkuldu yüreğim koptu yerinden

Tarifsiz bir acı duydum derinden,

Hiç farkım kalmadı deli birinden,

O güzel günleri hatırlayınca.

O günler maziye karıştı, gitti.

O çılgın arzular, hayaller bitti.

Gözümden yaşlar gelmeye yetti,

O güzel günleri hatırlayınca.', 'İçimi garip bir heyecan sardı, O güzel günleri hatırlayınca. Yanımda ne sen ne başkası vardı, O güzel günleri hatırlayınca. Burkuldu yüreğim...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hatirlayinca-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine', 'yine-caner-kuru-xldvz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine yağmur yağıyor bak sağnak sağnak

Bu gece bana düşen yine ağlamak.

Yine böyle yağmurlu bir gece vakti,

Sen değil miydin diyen, git beni bırak.

Yine gözümde yaşlar hep aynı sızı,

Yine yükselmiş atar kalbimin hızı,

Yine böyle yağmurlu bir gece vakti,

Uğurladım burada ben bir arsızı.', 'Yine yağmur yağıyor bak sağnak sağnak Bu gece bana düşen yine ağlamak. Yine böyle yağmurlu bir gece vakti, Sen değil miydin diyen, git beni ...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yine-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükeniş', 'tukenis-erol-dal-56ip6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Umudun tükendiği yerde

Bir kadeh bekler sizi

İçilmeye, sevilmeye, unutmaya

Hazırdır hep.

Ne olursa olsun yaşınız

Tükendiyse umutlarınız

Yakında,

Erişilmez bulutlardasınız.

Sağınızda bir melek

Solunuzda bir melek

Sizi izleyecek. 

Erişince arşa

Ne aş bulacaksınız yiyecek,

Nede bir yudum su içecek

Sadece,

Kaynayan kazanda

Umutlar görünecek,

Hep.', 'Umudun tükendiği yerde Bir kadeh bekler sizi İçilmeye, sevilmeye, unutmaya Hazırdır hep. Ne olursa olsun yaşınız Tükendiyse umutlarınız Yakı...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/tukenis-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykusuz kaldınmı hiç bu saatte', 'uykusuz-kaldinmi-hic-bu-saatte-umut-gungor-okjru', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uykusuz kaldınmı hiç bu saatte,

Seviyorum diye uyandığın oldumu,

Sözler yarıştırdınmı hiç bu saatte,

Şiirlerle konuştuğun oldumu.

Sahi benim kadar sevdinmi seni,

Sabaha kadar düşündüğün oldumu,

Hasretle özleyip bekledinmi seni,

Benim gibi duyguların oldumu.

Konuştunmu hiç yağmurlarla,

Islandınmı şiirlerle hiç sırılsıklam,

Dertleştinmi güllerle yapraklarla,

Seviyorum diye bağırdınmı bu akşam.

Çağırdınmı gökyüzünden yıldızları,

Seyreyledinmi samanyolunu,

Ardına ekledinmi umutlarını,

Sahi seyre durdunmu samanyolunu.

İlanı aşk ettinmi çiçeklere,

Hayalinde bana sarıldığın oldumu,

Bilirmisin sevda yazılır yüreklere,

Yazmak için yüreğe sarıldığın oldumu.', 'Uykusuz kaldınmı hiç bu saatte, Seviyorum diye uyandığın oldumu, Sözler yarıştırdınmı hiç bu saatte, Şiirlerle konuştuğun oldumu. Sahi benim...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/uykusuz-kaldinmi-hic-bu-saatte-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erbain', 'erbain-ali-capan-w2xpo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey ölüm! 

Benimle saklambaç oynama

Elma dersem çık

Armut dersem çıkma.

Kırk odalı gönül sarayının

Kapısı kapalı

Kırk birinci odasında

Kırk gün kırk gece

Çile doldurdum

Sabır küpünden sular içtim

Çok üşüdüm

Kırk yıl adını sayıkladım

Canım efendim.

Ey aşk! 

Yeter beklettiğin

Dayanamıyorum 

Gel artık.

Uçurtmamın ipi koptu

Esmiyor o rüzgar.

Ya gel

Ya da elimden tut

Beni de götür

Canım efendim.', 'Ey ölüm!  Benimle saklambaç oynama Elma dersem çık Armut dersem çıkma. Kırk odalı gönül sarayının Kapısı kapalı Kırk birinci odasında Kırk g...', ARRAY['Türk Edebiyatı','Şiir','Ali Çapan']::text[], 8.5, '{"poet":"Ali Çapan","poet_slug":"ali-capan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/erbain-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçurtmamız ''Uçar'' Gider! ...', 'ucurtmamiz-ucar-gider-ozan-si-ar-agdasan-uxua9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne kadar kalın taş olsa duvarlar 

Uçurtmamız UÇAR gider göklerde 

Güneşimiz tümsekleri aşarlar

Işıkları SAÇAR gider göklerde! ...

Yarınlara sarkar, bulut eterden

Çocuklar uçurtur, korur beterden

Göklere ulaşır, yel alır yerden

Gönül evin AÇAR gider göklerde

ŞİAR Can, açların açı ''Odesa''...

Yaşamak, paylaşım ben-sen''biz'' dese

Sevdam zincirlenip düş se; kodese

Kalmaz naçar, UÇAR gider göklerde! ...

Söz ve Müzik:Ozan ŞİAR AĞDAŞAN   ''İnadına Sevdamız'' Can Yayın...

www.siarcan.com

Yorum: Kadın Sanatçı, Ozan Şah Turna  (Aşık Şahturna)

Vokal: ŞAFAK ŞİRİN AĞDAŞAN Türkiye Almanya Müzik 

ŞAHTURNA Uluslararası Kültür ve Sanat Evi

www.sahturna.com', 'Ne kadar kalın taş olsa duvarlar  Uçurtmamız UÇAR gider göklerde  Güneşimiz tümsekleri aşarlar Işıkları SAÇAR gider göklerde! ... Yarınlara ...', ARRAY['Türk Edebiyatı','Şiir','Ozan ŞİAR Ağdaşan']::text[], 8.5, '{"poet":"Ozan ŞİAR Ağdaşan","poet_slug":"ozan-si-ar-agdasan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ucurtmamiz-ucar-gider-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Şehirlere Dair', 'kayip-sehirlere-dair-erdem-nur-cengiz-ng5bm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kayıp şehirler vardır ya hani düşlerde

Bulunmak istenen,

Bir türlü gidilemeyen.

Ve o şehirlerin

Ürkek, küskün gözlerinde 

Asi noktalar

İçlerinde uyutmaya çalıştıkları

Canavarları

Yaşamda yerini bulamamış çocukları

Onların hapsolmuştur

Beyinlerine

Çığlıkları

Hisseder ama

Duyamazsınız.

O kayıp şehirlerin

Hani düşlerdeki

Adamları vardır

Babadır onlar

Yorgun omuzlarında

Yitik melekleri

Uzaklardaki

Vaad edilmiş 

Cenneti arar.

Görünmez gözyaşları vardır onların

Erkekliklerine inat 

Coşkun sevdaların yaşandığı düşleri

Uykusuzluklarına karışır.

Ve kadınlar,

Kadınları vardır o kayıp şehirlerin,

Bacak arasına saklı 

Korku ile karışık umutları

Beşikten kurguludur 

Analığa hayatları.

Dolgun ve sarkık memeleri

Hiç tatmadıkları aşkın

Şehvetine uyanırken

Kimbilir kaç çocuğa 

Karın tokluğu veren.

Bir türlü yaşanamayan

Ama hep düşlenen sevdalara 

Tuzaktır analıkları.

09/07/2004', 'Kayıp şehirler vardır ya hani düşlerde Bulunmak istenen, Bir türlü gidilemeyen. Ve o şehirlerin Ürkek, küskün gözlerinde  Asi noktalar İçler...', ARRAY['Türk Edebiyatı','Şiir','Erdem Nur Cengiz']::text[], 8.5, '{"poet":"Erdem Nur Cengiz","poet_slug":"erdem-nur-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/kayip-sehirlere-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kadın ve Bir Adam', 'bir-kadin-ve-bir-adam-bekir-mutlu-gokcesu-lwhuq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir kadın

Ve bir adam

Uzak diyarlarda...

Şehirler, şehirler vardı

Aralarında...

Bir kadın

Ve bir adam

Aynı rüyalarda

Nehirler, nehirler aktı

Aralarında...

Bir kadın

Ve bir adam

Farklı dünyalarda...

Tek bir gök vardı

Aralarında...

Bir aşk düştü ortalarına...

Kayboldular

Uzayın sonsuzluğunda...

Bir kadın

Ve bir adam

Hiç olmadı aslında...', 'Bir kadın Ve bir adam Uzak diyarlarda... Şehirler, şehirler vardı Aralarında... Bir kadın Ve bir adam Aynı rüyalarda Nehirler, nehirler aktı...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-kadin-ve-bir-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Çiçeklerine Bakar Sevdamız', 'bahar-ciceklerine-bakar-sevdamiz-derin-oger-pt9l1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gözlerini gözlerimden ayıramam

bahar çiçeklerine bakar sevdamız

yıldızlar bir ritim tutturup delice kayarken

aşk ile ay parçalayıp güneş doğarız

sabahın buğusundan dağın kaynağından

titreyen kirpik uçlarından güllere damlarız

güller çift açar sevdanın koynunda

bakış bakış yeşil gölgelere uzanırız..', 'gözlerini gözlerimden ayıramam bahar çiçeklerine bakar sevdamız yıldızlar bir ritim tutturup delice kayarken aşk ile ay parçalayıp güneş doğ...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bahar-ciceklerine-bakar-sevdamiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sınıfta Kalmasın Sevgi!', 'sinifta-kalmasin-sevgi-ozan-sah-turna-agdasan-qwqaq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Harami tutmuş yolları

Tarümar olmasın sevgi

Geçsin bütün okulları

Sınıfta kalmasın sevgi! 

Nakarata:Kin, savaşlar çözmüş neyi

                 İnsanlık''   Barış''la iyi.....

                 ''Umut'' notumuz pekiyi

                 Sınıfta KALMASIN Sevgi! 

Yürekler üşümüş karda

''Ay ışımaz'' gece darda

Çiçek açsın yaz baharda

Sararıp solmasın Sevgi

ŞahTurna arşa varasın

Güzel dünyayı sarasın

Aynada ''aşk-ı'' tarasın

Saç başın yolmasın sevgi! ...

Söz ve Müzik: Ozan ŞahTurna (Barış Kadın Platformu)  www.sahturna.com

 Beste ve yorum: Ozan ŞİAR AĞDAŞAN

''İnadına Sevdamız'' Kitabı. ''Can yanar-acılar bal olur'' müzik albümü

Türkçe, Almanca: ŞİRİN ŞAFAK Ağdaşan

ŞAHTURNA KÜLTÜR ve SANAT EVİ

www.sahturna.com     www.siarcan.com', 'Harami tutmuş yolları Tarümar olmasın sevgi Geçsin bütün okulları Sınıfta kalmasın sevgi!  Nakarata:Kin, savaşlar çözmüş neyi               ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Şah Turna Ağdaşan']::text[], 8.5, '{"poet":"Ozan Şah Turna Ağdaşan","poet_slug":"ozan-sah-turna-agdasan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sinifta-kalmasin-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksunum Senden', 'yoksunum-senden-i-smail-baharsen-3yoh6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ya sabah anarım yada akşam

ismin bir an düşmez dilimden

seni görüyorum nereye bakasam

çok görme yoksunum senden

böylemi olurdum yanımda olsan

mutsuzmu olurdun benimle kalsan

geldin sanıyorum bir ses duysam

çok görme yoksunum senden

seni arar sana adanan şiirler

yazmıyor sensiz elimde kalemler

geçer sanma geçmiyor günler

çok görme yoksunum senden

sence yıllar aşkını silermi dersin

bu garip adam birini severmi dersin

çektiklerim sevdana değermi dersin

çok görme yoksunum senden....', 'ya sabah anarım yada akşam ismin bir an düşmez dilimden seni görüyorum nereye bakasam çok görme yoksunum senden böylemi olurdum yanımda olsa...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yoksunum-senden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakışlarında Dans', 'bakislarinda-dans-cigdem-bir-genc-27om7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ayın şavkı   gözlerinde....

Gözlerin bir çocuk...

Bakışlarında dans eden ben miyim? 

Kaybolmayı düşlüyor ellerim

Ellerinin coğrafyasında bu gece

Lirik bir şiir gibiyim...

Sendeyim...

Gözlerin dolunaya dönerken

Sessizce gideceğim...', 'Ayın şavkı   gözlerinde.... Gözlerin bir çocuk... Bakışlarında dans eden ben miyim?  Kaybolmayı düşlüyor ellerim Ellerinin coğrafyasında bu ...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Bir Genç']::text[], 8.5, '{"poet":"Çiğdem Bir Genç","poet_slug":"cigdem-bir-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bakislarinda-dans-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni İstemek Varya', 'seni-i-stemek-varya-i-smail-baharsen-ubiog', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gözlerine bakmak isterdim doya doya

o gece karası siyah gözlerine

saçlarını almak isterdim avcuma

tutmak isterim kalbini ellerimle

hissetmek isterdim çılgınca duygularını

bana karşı olan aşkını anlamak,

ve seni bir otobüs durağında

ve seni bir şiirin son mısrasında

gözyaşlarıyla beklemek isterdim..

eski günlerimizi yaşamak hatıralarıyla

el ele dolaşmak yalnız parklarda

kaybolmak uzayan ıssız yollarda

ve en tatlı rüyayı seninle görmek

her yeni güne seninle gülmek isterdim...

ıslanmak isterdim yaz yağmurlarında

saklanmak bir mesela bir gece koynunda

güneşten gizlemek isterdim ateş tenini

seninle olmak seninle yaşamak..

ölmekse seninle ölmek isterdim......', 'gözlerine bakmak isterdim doya doya o gece karası siyah gözlerine saçlarını almak isterdim avcuma tutmak isterim kalbini ellerimle hissetmek...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seni-istemek-varya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık Kalplim', 'kirik-kalplim-i-smail-baharsen-7v7sk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bu günde dalgınsın kırık kalplim

gözlerin takılı yine boşluklarda

yüzünden okunuyor neşesizliğin

hüznün çalıyor sanki şarkılarda

bu günde yaslısın kırık kalplim

rüyaların yarım kalmış gibi

uykuların bölünmüş dilim dilim

yanakların yaşla ıslanmış gibi

bu günde yarımsın kırık kalplim

yarısı başka yerde sanki teninin

bulutlar gibi tertemiz yüreklim

hayali dünyamda büyülü perim

bu günde hastasın kırık kalplim

hayat yolundan dönmüşsün sanki

ruhun başkalaşıyor esmer çiçeğim

yaşamıyor der gören ölmüşsün sanki...', 'bu günde dalgınsın kırık kalplim gözlerin takılı yine boşluklarda yüzünden okunuyor neşesizliğin hüznün çalıyor sanki şarkılarda bu günde ya...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kirik-kalplim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ana Yüreği', 'ana-yuregi-mehmet-kindap-oorbl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karlı

Dumanlı

Dağların

Tepelerinde

Bir yaralı ceylan

Unutmuş

Unutmuş

Unutmuş

yarasını

Düşünür maralını ceylan

                                     (2000 Ankara)', 'Karlı Dumanlı Dağların Tepelerinde Bir yaralı ceylan Unutmuş Unutmuş Unutmuş yarasını Düşünür maralını ceylan                               ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kındap']::text[], 8.5, '{"poet":"Mehmet Kındap","poet_slug":"mehmet-kindap","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ana-yuregi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorun Baştadır', 'sorun-bastadir-murat-demir-kr3s2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıkılmış gibisin, sakinleş, anlat

Gözlerinde yaş yok, yüreğin ağlar

Yanıp kavrulmaya, değer mi hayat

Gel otur yanımda sana da yer var

Bu parklar her gece benim yerimdir

Ta ki sabah güneş doğana kadar

Rahat et, burayı say ki evindir

Kar denilen beyaz yağana kadar

Düşünme, onunda çaresi vardır

Ben tavan olurum, sen de tabanım

Su olup gidecek, sonuçta kardır

Sana da, bana da yeter kabanım

Bilirsin acıya, hiçbir şey olmaz

Mehtabın altında sarıl ayaza

Meraklanma bizi kırağı çalmaz

Baksana şu gölde kuğuya kaza

Sanma ki yanlızız koca parkta biz

Şu bank dolar taşar şu bank birazdan

Hepsi de sevdalı, hepsi de temiz

 Hiç biri de korkmaz, kardan ayazdan

Bak biri geliyor sekiz yaşında

Toz toprak içinde yırtık yelekli

Sahipsizdir ama aklı başında

Arada sırada ağlar sürekli

Teselli ederim yanıbaşımda

Ellerimden tutar dalar ve uyur

Ortalıkta kalmış çocuk yaşında

Sevaptır, garibi bugün sen doyur

Benimde bir yuvam vardı geçmişte

Gülüp eğlenmekten başım dönerdi

Şimdi ne haldeyim, şimdi bak işte

Her köşe de mumlar yanıp sönerdi

Anladıysan beni artık gülümse

Her canlının derdi başka başkadır

Sana senin kadar acımaz kimse

Sorun bizde değil, sorun baştadır', 'Yıkılmış gibisin, sakinleş, anlat Gözlerinde yaş yok, yüreğin ağlar Yanıp kavrulmaya, değer mi hayat Gel otur yanımda sana da yer var Bu par...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sorun-bastadir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutuşmuşluğun Ortasındayım', 'tutusmuslugun-ortasindayim-i-smail-baharsen-gzby9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''''ateş gözlerinde kıvılcımlardayım''''

yan yana dizilmiş kadehlerden  biri gibiyim

karşımda alnıma dikilmiş silah namlusu

bir tetiklik hayatımı dilenir gibiyim..

içimde büyüyen bir nedenlik sorgusu

tutuşmuşluğun ortasındayım şimdi

ardımda ne yangınlar ne yanıklar bırakarak

hücrelerime işlemiş ağlatan sızılar

kimsesizlik şehrinin nüfusundayım..

yalnızlık ailesinin mensubuyum şimdi

çok timsah gözyaşları sildim

çok gönülleri avuttum avunacakken

damlacıklara muhtaçken kalbim

ne deli nehirleri akıttım bilmem

kaç yaraya ilaç oldum son diyerek

kaç vedaya boyun büktüm sayamam

hep kısa sürecek ayrılık hayalleriyle

şimdi tutuşmuşluğun ortasındayım

ardımda kaybolan yıllarım anılarım

önümde ellerce yaşanmış yarınlarım

kararsızım ben ne yapayım.....', '''''ateş gözlerinde kıvılcımlardayım'''' yan yana dizilmiş kadehlerden  biri gibiyim karşımda alnıma dikilmiş silah namlusu bir tetiklik hayatım...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/tutusmuslugun-ortasindayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şükran', 'sukran-mehmet-kindap-7vot6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerindeki pırıltı

Yüreğindeki merhamet

Hiç eksilmesin

Nice uzun yıllara gülüm

Bir dilek tuttum ikimiz için

Beraber alsın bizi ölüm

(2004 Ankara)', 'Gözlerindeki pırıltı Yüreğindeki merhamet Hiç eksilmesin Nice uzun yıllara gülüm Bir dilek tuttum ikimiz için Beraber alsın bizi ölüm (2004 ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kındap']::text[], 8.5, '{"poet":"Mehmet Kındap","poet_slug":"mehmet-kindap","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sukran-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞüBüYe', 'subuye-mehmet-kindap-n2w40', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ş arkıdır bir doyumsuz adınız dudaklarımda

Ü mittir gelecek güzel günlerimiz için

K âlbimin uçsuz ve engin denizinde

R esminiz ellerimde Şükran Bülent ve Yeliz

A ysız gecelerimin Güneş''i kadınım ve çocuklarım benim

N erdesiniz hani ah nerdesiniz

(1980 Hakkâri)', 'Ş arkıdır bir doyumsuz adınız dudaklarımda Ü mittir gelecek güzel günlerimiz için K âlbimin uçsuz ve engin denizinde R esminiz ellerimde Şük...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kındap']::text[], 8.5, '{"poet":"Mehmet Kındap","poet_slug":"mehmet-kindap","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/subuye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürü Yalan Dünya', 'yuru-yalan-dunya-mehmet-kindap-jmuf8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yürü yalan Dünya ben de giderim

Kına yak arkamdan bayramın olsun

Uçarım göklere uçar giderim

Etimle kemiğim toprağın olsun

Bugün yaşadığım düne hediye

Bensiz de başlanır bir yeni güne

Gökkuşağı gibi bakıp resmime

Arkamdan dualar okuyan olsun

Kehribar tesbihle çektim zamanı

Tükendi seneler ömrün son anı

Giderken son defa o gün salımı

Elleri üstünde taşıyan olsun

Ömür denilen şey su gibi akan

Bir sevinç bir hüzün anıda kalan

Giderken arkamdan gözyaşı döken

Taşını başıma koyanım olsun

Mor dağlardan serin sular dökülsün

Menevşe yasemen sümbül ekilsin

Seher yeli dosttan selâm getirsin

Mehmet''im yazdığım  hatıram olsun

(2005 Ankara)', 'Yürü yalan Dünya ben de giderim Kına yak arkamdan bayramın olsun Uçarım göklere uçar giderim Etimle kemiğim toprağın olsun Bugün yaşadığım d...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kındap']::text[], 8.5, '{"poet":"Mehmet Kındap","poet_slug":"mehmet-kindap","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yuru-yalan-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönmüşsün...', 'donmussun-ruhsel-bariscimen-45x6s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dönmüşsün! ...

Hiç haber vermeden

Çekip gitmiştin oysa.

Az önce

Kapımı çalan

Sendin demi? 

Bıraktığın gülden

Tanıdım seni...

İlk değil

Bu yaptığın bana...

Daha kaç kere

Gidersin bilemem ama

Her dönüşünde

Daha az

Bulacaksın beni...', 'Dönmüşsün! ... Hiç haber vermeden Çekip gitmiştin oysa. Az önce Kapımı çalan Sendin demi?  Bıraktığın gülden Tanıdım seni... İlk değil Bu ya...', ARRAY['Türk Edebiyatı','Şiir','Ruhsel Barışçimen']::text[], 8.5, '{"poet":"Ruhsel Barışçimen","poet_slug":"ruhsel-bariscimen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/donmussun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can paramparça/usta', 'can-paramparca-usta-zafer-zengin-etnika-24qav', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'oyy havarr

iç yangınım

tutmaz elim

gelmez sesin

yanmışam zemheride

dalmışam

nasıl suskun ellerim

anlamamışam

nasıl kudurgan zaman

doğramış elim

bitmiş sesim

sensizem loo

yanmışam güze doğru

kanatsız ataşım

çırayam

yalnızam

kaçmazam

ölümse yamacım

kalkmazam

oyy havar

havadis var

bir selamın gelmez

yangın içim çürütmez

sensizem loo

erisem gücüme gitmez

bitmişem tüter nefesim

ooy havarr

gelmiş dost selamı

küsmezem

sesin geldi

ölmezem

oy havar

kim dedi

koca şehir sana küstü

ahh ki çaresiz elim ayağım

yangınlara gelmişim

bir yanım tercan

bir yanım ankara

sebebsiz ölmüşem loo

sen ki geldin dağlarıma

ataşımı anlamaya

memnunmusan sıcağımdan

ezik dolu omzumdan

yanağına dokunmuşam

oyy havar

çocuk ettin gönlümü

tutulmuşam

sevdada  eskirmiş looo

çıban kanaması

kaçıp gitmek

çarık yırtıp yollarda

selam durduk anadolu’ya

gitmiş hareleri

düşmüş gözleri

oyy havar yanmışam

ben ay''a tutulmuşam

derde ses olmuşam

bir başına

Yıkılmazam

al kal''a

al diyarbekir

al fırtına

al zozan

kana bulanmışam

ne varsa aşkına yanmışam

oyy havar

ters etme yüzün

yanmışam

kanadın sar

rengime çal fıratı

ateş dök içime

oyy havar

kan değsin ciğerime

memleket yangın

ben yangın

karışmışam düzlere

külüm küle

rengim renge

puşi bağlamışım alnıma

selam durmuşam gardaşa

toprağıma

insanıma

boydan boya

nakış boynuna

sarılmışam

uçmuşam

baktım rüzgara

sesine sardım ayrılığa

nere gittin bilmem

oyy havar

ben sensiz ölmem

dağlara çekilmişem

bakma

kan salmış dodağıma

fesat girmiş aramıza

dağılma

sarıl memlekete

sarıl kal/aya

batısına

doğusuna

ben sensiz kalmışam

ahan sınırdır çanakkale

ahan hakkari yüksekova

bir selam gönder

alırlar ha

kaç kız kaçırdık

kaç kana karıştık

akrabaydık

bırakma

sahip ol insana

sahip ol toprağa

oyy havar

bilmişem seni

sevmişem

gözün karası

kaşın çatığı

canımın yarısı

dicle değmiş içimize

yeşilırmak

kızılırmak

oyy havar

gel işte

ataşlarda biz yanak

memleket loo dirildiğimiz

alnından öptüğümüz

can hüzün

can paramparça *

sen güler yüzümüz

ışık var/aydınlık

kahve söylemişim içiysen 

telvesinde kırk yıl hatıra

| Hamura su isterken..nehirleri gördü gözlerimiz..büyüklerimizin kanlarını karıştırdığı..canın cana sahip çıktığı..böyle bir hasretti kavuşmak..keşke hiç ayrılmasak..*Sevmişem ben sizi..BARIŞA..KARDEŞLİĞE ve BERABERLİĞE |

Bir dostun ısrarıyla yazılmıştır

*Büyük ozan üstad; Ahmet arif’in aziz anısına..saygıyla..hörmetle

Ben de bıraktığı izlerden yola çıktım 

9 Temmuz 2004 “ Memleket ele karşı “', 'oyy havarr iç yangınım tutmaz elim gelmez sesin yanmışam zemheride dalmışam nasıl suskun ellerim anlamamışam nasıl kudurgan zaman doğramış e...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":136,"source_url":"https://www.antoloji.com/can-paramparca-usta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Obsesif İmgeler', 'obsesif-i-mgeler-nazim-ercan-rq8fw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir imgenin paranoyası,

saran bedeni

çığlık çığlığa düşler

gözkapakları külçe, bilinmez; 

belki de; mührü uzakların

saksağan gölgesinin leşinin peşinde

uzak şehirlerden davet edilmiş bir gölge hicabette, davete

sağnak bulutlar halinde umut...! 

yosunumsu güller; yaban mersinleri

kınalı hanım takıştırmış gene 

denizin üzeri sahte yakamoz damlaları

ve; 

incileri kınalı hanımın 

gözkapakları gene de külçe

heybetli kasırgası yüreklerin

bir imge paranoyası yaşanan 

yalnızca; 

kınalı hanım, incileri, damla yakamozları

göz kapakları gene de külçe

beden ise esrik...! 

kösnül düşlere,

ray üzeri ayaküstü odaları eşlikte

istasyon şefi sahte uykusuzluklar

göz kapakları gene de külçe

bu bir imge PARANOYASI

obsesif uykusuzluklara 

daha da; inat yaşamak', 'bir imgenin paranoyası, saran bedeni çığlık çığlığa düşler gözkapakları külçe, bilinmez;  belki de; mührü uzakların saksağan gölgesinin leşi...', ARRAY['Türk Edebiyatı','Şiir','Nazım Ercan']::text[], 8.5, '{"poet":"Nazım Ercan","poet_slug":"nazim-ercan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/obsesif-imgeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Sevda', 'kara-sevda-mehmet-kindap-w1vrh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ah ben bu dağlara ceylan olurum

Elinde mavzeri yâr vursun diye

Yatarım dizine kurban olurum

Kanımı alnına yâr sürsün diye

Bir kara sevdaya yürek olurum

Beklerim yıllarca yâr gelsin diye

Eğer kavuşmazsam deli olurum

Yazın duvarlara yâr görsün diye

Bir garip aşığım sevda yolunda

Saklanmış sır gibi o yâr kalbimde

Söylerim adını son nefesimde

Rüzğarlar götürsün yâr duysun diye

Kara sevda kara sevda yer beni

Mecnun etti Kerem etti yâr beni

Koysunlar toprağa koysunlar beni

Bir dua ruhuma yâr sunsun diye

(2005 Ankara)', 'Ah ben bu dağlara ceylan olurum Elinde mavzeri yâr vursun diye Yatarım dizine kurban olurum Kanımı alnına yâr sürsün diye Bir kara sevdaya y...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kındap']::text[], 8.5, '{"poet":"Mehmet Kındap","poet_slug":"mehmet-kindap","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kara-sevda-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-mehmet-kindap-du0dl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'O siyah gözlerindi gördüğüm 

İlk önce

Ne tatlı bakışları vardı gülüm

Gönlümce

Tutsak kıldı beni 

Ömrümce', 'O siyah gözlerindi gördüğüm  İlk önce Ne tatlı bakışları vardı gülüm Gönlümce Tutsak kıldı beni  Ömrümce...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kındap']::text[], 8.5, '{"poet":"Mehmet Kındap","poet_slug":"mehmet-kindap","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gozlerin-110-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakışın Şiirdi Dört Kıtalık', 'bakisin-siirdi-dort-kitalik-i-smail-baharsen-in9i0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bakışın dört kıtalık şiirdi şiir gözlüm

seni eksiksiz seni yalansız anlatan

mısra mısra vurgusu derinden özlüm

bakınca göz bebeğine gönlümü kanatan

bakışın taşkın sulu nehirdi güzel gözlüm

gördüğümde ılık ılık göğsümden akan

geçtiği yerlere izler anılar bırakan

sonunda sevgilisi deli denize kavuşan

bakışın sihayça bir alevdi ateş gözlüm

eriyen buz kütlesiydim karşında

ilmik ilmik çözülen bir kördüğüm

yasakları çiğnemiş bir kalp mahkumu

bakışın yavaşça ölümdü hançer gözlüm

kalbi ta en dip yerinden yemeye başlayan

beynin en uç noktasına olmazları koyan

bir çalar saat en mutlu anda çalan

rüyamı en güzel yerinde bozan....', 'bakışın dört kıtalık şiirdi şiir gözlüm seni eksiksiz seni yalansız anlatan mısra mısra vurgusu derinden özlüm bakınca göz bebeğine gönlümü ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bakisin-siirdi-dort-kitalik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Kaybedersem', 'seni-kaybedersem-mehmet-kindap-n80rw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşar mıyım

Görmesem gözlerini

Bir an olsun

Yaşar mıyım

Ölürüm

Duymasam sıcaklığını

Avuçlarımda ellerinin

Ölürüm

Ve sancılı betikler başlar özleminden

Seni kaybedersem inan

Ölmem ama 

Sürünürüm

(1971-Ankara)', 'Yaşar mıyım Görmesem gözlerini Bir an olsun Yaşar mıyım Ölürüm Duymasam sıcaklığını Avuçlarımda ellerinin Ölürüm Ve sancılı betikler başlar ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kındap']::text[], 8.5, '{"poet":"Mehmet Kındap","poet_slug":"mehmet-kindap","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-kaybedersem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Böylemisin', 'sen-boylemisin-i-smail-baharsen-8ra8o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hiç tanıyamamışım meğer seni

bir tesadüfle gözüme girmişsin 

bir sen daha var senin içinde

bir oyun gbi sen böylemisin

hayat gözünde küçücük olmuş

geleceğim dediğin çiçeğin solmuş

üç günlük dünyana gurur dolmuş

bir yalan gibi sen böylemisin

sevgiden nasibin kesilmişmi ne

kime bu havan güzelim kime

çocukcasın çok büyüsen bile

bir masal gibi sen böylemisin

dilinden düşen bir avuç sitem

bilmem bu aşka ben ne desem

hayırlıdır buradan çekipte gitsem

bir hayal gibi sen böylemisin', 'hiç tanıyamamışım meğer seni bir tesadüfle gözüme girmişsin  bir sen daha var senin içinde bir oyun gbi sen böylemisin hayat gözünde küçücük...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-boylemisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '****GELİN(Beste:ERSİN KAYIŞLI) ****', 'geli-n-beste-ersi-n-kayisli-mehmet-kindap-9fxn2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karlar uçtu çaylar coştu yeşil kondu dallara 

Bürünmüşler güzeller oy yeşilinen allara 

Benim yârim dar geliyor yollara

Edalım oy al yanakta beni var

Kardan beyaz yumuşacık teni var

Anlatamam dil dökmekle gözlerinin karasını

Doktor sarmaz şu gönlümün hep sızlayan yarasını

Ak ellere sarmış gelin kınasını

Telli duvak gurbet ele gider yârim 

Kara gözlüm kır çiçeğim sevdiğim

(1970 Ankara)', 'Karlar uçtu çaylar coştu yeşil kondu dallara  Bürünmüşler güzeller oy yeşilinen allara  Benim yârim dar geliyor yollara Edalım oy al yanakta...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kındap']::text[], 8.5, '{"poet":"Mehmet Kındap","poet_slug":"mehmet-kindap","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gelin-beste-ersin-kayisli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-i-smail-baharsen-2zpyx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ölüm ne kadarda soğuk söylerken bile 

düşünülmesi hep arka plana koyulan

ölüm ne kadarda soğuk yazarken bile

kalemin ucunda buz gibi donan

ölüm ne kadarda soğuk bakarken bile

bir durgun nehir gibi gözlere dolan

ölüm ne kadarda soğuk görürken bile

orta şiddetli deprem derinden vuran

ölüm ne kadarda soğuk dururken bile

sanki bir saniyelik dönen kısa zaman

ölüm ne kadarda oğuk sıcakken bile

bir nefesle sönen delice zaman 

ölüm ne kadarda soğuk uzakken bile

mesela gözlerini hisstmek en azından

ölüm ne kadarda soğuk kısayken bile

bir tren gibi son istasyondan kalkan....', 'ölüm ne kadarda soğuk söylerken bile  düşünülmesi hep arka plana koyulan ölüm ne kadarda soğuk yazarken bile kalemin ucunda buz gibi donan ö...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olum-128-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Kurşunu Adres Sormaz ki', 'ask-kursunu-adres-sormaz-ki-cafer-tayyar-ozkan-o1e7y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aylar öncesine dönelim diyen,

Bir sevgi sözünü bile çok gören,

Duygularımı bir kalemde silen; 

İnan, kırgınlığım geçmedi hala...

Hastalığıma hal hatır sormayan,

Son demlerde derde ilaç olmayan,

Yeminleri geç, sözünde durmayan; 

İnan, kızgınlığım dinmedi hala...

Ahde vefayı böyle mi bilirdin,

Aşkını bana böyle mi yazardın,

Her günümde hatırımı sorardın; 

İnan, küskünlüğüm gitmedi hala...

Son sözümü sana hiç söylemedim,

Sevgiye dair ne varsa diledim,

Aşk kurşunu adres sormaz ki derdim,

İnan, çılgınlığım bitmedi hala...

31 Mart 2003 Ankara', 'Aylar öncesine dönelim diyen, Bir sevgi sözünü bile çok gören, Duygularımı bir kalemde silen;  İnan, kırgınlığım geçmedi hala... Hastalığıma...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ask-kursunu-adres-sormaz-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-mehmet-kindap-q9cyv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sensizlik gözyaşı sensizlik elem

Sensizlik tek kurşun beynimi delen

Sensizlik hıçkırık boğazımdaki

Sensizlik gönlümü perişan eden

Gündüze umutsun geceye rüya

Kerem''e Aslı''sın Mecnun''a Leyla

Sensizlik bir sancı yüreğimdeki

Ne zaman sensizim dar gelir Dünya

Siyah saçlarında rüzğar eğlensin

Sen benim gönlümde yatan ceylansın

Sensizlik bir şarkı dudağımdaki

Sevdiğim bir tanem nerelerdesin

(1980 Hakkari)', 'Sensizlik gözyaşı sensizlik elem Sensizlik tek kurşun beynimi delen Sensizlik hıçkırık boğazımdaki Sensizlik gönlümü perişan eden Gündüze um...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kındap']::text[], 8.5, '{"poet":"Mehmet Kındap","poet_slug":"mehmet-kindap","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sensizlik-122-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya', 'dunya-i-smail-baharsen-40e62', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kime kızdın böyle kıpkırmızı

niye bana ateşsin dünya

sensin gençliğimin hırsızı

niye bana böylesin dünya

bende doğdum canlı olarak

haklarım vardı insan olarak

seninle hayal mutlu yaşamak

niye bana düşmansın dünya

kime zararım olmuş sorsan

kendi çabam şimdi varsam

nerde anam nerde babam

niye bana yalansın dünya

gözüne batan aşkımmı oldu

o kayıp sevgini kimler buldu

karanlığın geldi bende durdu

niye bana masalsın dünya', 'kime kızdın böyle kıpkırmızı niye bana ateşsin dünya sensin gençliğimin hırsızı niye bana böylesin dünya bende doğdum canlı olarak haklarım ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dunya-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşil', 'yesil-erdal-sayil-dcae1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne güzel sarıyor cismi; 

Resmi ve şekliyle yeşil...

Doğrudur anılır ismi,

Dünya cennetiyle yeşil..

Su desen coşarak olmuş,

Çimenler koşarak olmuş,

HAK''ka el açarak olmuş; 

Ağaç fıtratıyla yeşil..', 'Ne güzel sarıyor cismi;  Resmi ve şekliyle yeşil... Doğrudur anılır ismi, Dünya cennetiyle yeşil.. Su desen coşarak olmuş, Çimenler koşarak ...', ARRAY['Türk Edebiyatı','Şiir','Erdal Sayıl']::text[], 8.5, '{"poet":"Erdal Sayıl","poet_slug":"erdal-sayil","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yesil-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ak Ak', 'ak-ak-aydin-yurtsever-23vqz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eller gördüm

eller nasır

bir güvercin uçtu

kanatları ak

emek ve barış

ikisi de

bulaştı karaya

ak ak

	   Bingöl    1980', 'Eller gördüm eller nasır bir güvercin uçtu kanatları ak emek ve barış ikisi de bulaştı karaya ak ak 	   Bingöl    1980...', ARRAY['Türk Edebiyatı','Şiir','Aydın Yurtsever']::text[], 8.5, '{"poet":"Aydın Yurtsever","poet_slug":"aydin-yurtsever","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ak-ak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözler', 'gozler-aydin-yurtsever-z2ct5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne müthiş duygu o

içime sicim gibi damlayan

o gözler

yaşamak bu yaşayarak

bir özlem

bir şiir

bir sevda bu

düşer hep yüreğime

düşer hep derin derin.

			7/8/1988  -  Bingöl', 'Ne müthiş duygu o içime sicim gibi damlayan o gözler yaşamak bu yaşayarak bir özlem bir şiir bir sevda bu düşer hep yüreğime düşer hep derin...', ARRAY['Türk Edebiyatı','Şiir','Aydın Yurtsever']::text[], 8.5, '{"poet":"Aydın Yurtsever","poet_slug":"aydin-yurtsever","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gozler-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Anamın Ak Sütü Gibi', 'guzel-anamin-ak-sutu-gibi-aydin-yurtsever-vyhox', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevdam

gecenin şafağında

yüreğimin

pullu kelebeğidir

uçuşur diyarlarında ülkemin

kurağında toprağın

sevinç göz 

akar tarlasına

     toprağı delerek

güzel anamın ak sütü

açan gül tomurcuğudur

	

		Bingöl     1986', 'Sevdam gecenin şafağında yüreğimin pullu kelebeğidir uçuşur diyarlarında ülkemin kurağında toprağın sevinç göz  akar tarlasına      toprağı ...', ARRAY['Türk Edebiyatı','Şiir','Aydın Yurtsever']::text[], 8.5, '{"poet":"Aydın Yurtsever","poet_slug":"aydin-yurtsever","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/guzel-anamin-ak-sutu-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizliğe Sitem', 'sessizlige-sitem-mehmet-selim-tolay-w5ou8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gece

sokak lambaları hüzünlü

kaldırımlar derin bir uykuda

gözlerimde gençlikten kalma,

yağmurlar açmada

bir gül kokusu beni yıldızlara salmada

bu gece

etraf dingin

caddelerde sessizlikler

caddelerde ateş böcekleri mevsimler yansıtmada

bu gece kirli odam

tertemiz annem kokmada

yer yer anlayışsal,bilinçsel

nefes azlığı yaşanmada

bir itin rüyasında kediler dolanmada

mavilikten karanlığa seferler yapılmada

bu gece

sokak lambaları hüzünlü

kaldırımlar derin bir uykuda.

09.07.2004', 'Bu gece sokak lambaları hüzünlü kaldırımlar derin bir uykuda gözlerimde gençlikten kalma, yağmurlar açmada bir gül kokusu beni yıldızlara sa...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Selim Tolay']::text[], 8.5, '{"poet":"Mehmet Selim Tolay","poet_slug":"mehmet-selim-tolay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sessizlige-sitem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki', 'i-cimdeki-aydin-yurtsever-lrhjd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Akşam misafir

doğanın bayırında

tacı püsküllü

bir gelin gibi

az sonra karanlığın tohumlarını ekerek

göz kırpıp el sallayacak

geceyi avuçlayan gündüze

bak canım

güneş ne kadar kızıl tepemde

ayrılık hüznüdür içimde

			Ardahan / 1985', 'Akşam misafir doğanın bayırında tacı püsküllü bir gelin gibi az sonra karanlığın tohumlarını ekerek göz kırpıp el sallayacak geceyi avuçlaya...', ARRAY['Türk Edebiyatı','Şiir','Aydın Yurtsever']::text[], 8.5, '{"poet":"Aydın Yurtsever","poet_slug":"aydin-yurtsever","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/icimdeki-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Noktalar', 'noktalar-aydin-yurtsever-ubro0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sıralı noktalardır yaşam

kendi başlarına

her biri bir öküz sanki

peşinde çengelli noktalar

her çengelden

özgün bir gerçek asılı

ve noktalar kümecikleri

almak istedim gerçeği çengelden

çarpılırsın dediler

çünkü yaşam gizidir gerçeğin

ünlem bekliyordu daha arkalarda

kendisinin de çengelliğe asılacağını öğrenecekti sonradan

				Ankara / 1983', 'Sıralı noktalardır yaşam kendi başlarına her biri bir öküz sanki peşinde çengelli noktalar her çengelden özgün bir gerçek asılı ve noktalar ...', ARRAY['Türk Edebiyatı','Şiir','Aydın Yurtsever']::text[], 8.5, '{"poet":"Aydın Yurtsever","poet_slug":"aydin-yurtsever","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/noktalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçları Ak Bulutların', 'saclari-ak-bulutlarin-aydin-yurtsever-s5wf5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugün saçları ak bulutların 

Birazda kıvrım kıvırcık

Güneş 

Arada bir göz kırpar

Koşturan bulutların arasından

Düştü

Martının kanadına

Ve saçları ak köpükten dalgalı

Mavi denize

Sonra Şavkıdı

Buğulu donuk bir çift göze

Gözler denize deniz gözlere sarıldı

Yuvarlandılar köpüklere karışarak 

Boğazın tam orta yerine

Yosun tutmuş

Yitik sevdaların kucağına

Islandılar üşüdüler orada

Bir daha

Bulutların ak saçlarını 

Öremeyen sevdaların

Islak mezar taşlarının uçlarından

Gözler denize deniz gözlere sarıldı

Yuvarlandılar köpüklere karışarak...', 'Bugün saçları ak bulutların  Birazda kıvrım kıvırcık Güneş  Arada bir göz kırpar Koşturan bulutların arasından Düştü Martının kanadına Ve sa...', ARRAY['Türk Edebiyatı','Şiir','Aydın Yurtsever']::text[], 8.5, '{"poet":"Aydın Yurtsever","poet_slug":"aydin-yurtsever","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/saclari-ak-bulutlarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Temmuza mı, yoksa...?', 'temmuza-mi-yoksa-remzi-zengin-r29ga', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dökmek istiyorum dertlerimi, acılarımı

Temmuza mı; yoksa başkasına mı? 

Bilmem anlar mı Temmuz kaygılarımı

Gurbet mi desem, hasret mi desem, yoksa sevda mı? 

Kara kaşlı, ela gözlü, fidan boylu yarimi mi anlatsam

Yoksa başı karlı, dumanlı Topçamlı yurdumu mu? 

Anlatacak dert çok bende, hasret çok bende

Lakin Temmuz anlamaz ki beni, yakar kavurur beni

Oysa ben serin ve yumuşacık yar kucağı isterim.

Dizlerine alsın başımı, dinlesin mısralarımı

Ve fısıldasın kulağıma tatlı sesiyle isterim.

Teselli versin bana, hayat versin can versin

Dindirsin acılarımı sızılarımı, damarlarıma kan versin

Ve ben tatlı yurdumun fısıltılı rüzgarında 

Bir ağacın gölgesinde veya gece mehtabında

Rahat derin bir uyku isterim… Uzaktan uzağa gelen 

Köpek seslerinin, geceyi, gökyüzünü süsleyen yıldızların

Ortasında olmak isterim…  İstemem Temmuzun sıcağını

Benden intikam alırcasına ter döktüren, sıla hasreti, 

Yar hasreti çektiren Temmuzu asla istemem

(28 Temmuz 1973 cumartesi 18:23) 

(DSİ KONYA) 

(Bir vagonda)', 'Dökmek istiyorum dertlerimi, acılarımı Temmuza mı; yoksa başkasına mı?  Bilmem anlar mı Temmuz kaygılarımı Gurbet mi desem, hasret mi desem,...', ARRAY['Türk Edebiyatı','Şiir','Remzi Zengin']::text[], 8.5, '{"poet":"Remzi Zengin","poet_slug":"remzi-zengin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/temmuza-mi-yoksa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Zaman Büyüdün?', 'ne-zaman-buyudun-halil-kesken-uf18t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Daha dün ağlıyordun, kollarımda delice

Kaç günde büyüdünde, sever oldun sen beni

Sözde çoktan yazılmış, kaderim kaderine

Ne zaman büyüdün de, sever oldun sen beni

Daha dün beni ancak, mahremin görüyordün

Peşim sıra abicim, diyerek geliyordun

Hep çocuk reyonundan, giysiler giyiyordun

Ne zaman büyüdün de, sever oldun sen beni

Daha bir kaç gün önce, girmişsin onyedine

Aramızda on yaş var, artık gelsen kendine

Aşkın yaşı yoktur ya, yine de git dengine

Ne zaman büyüdün de, sever oldun sen beni

Daha benim gözümde, küçücük bir çocuksun

Bırak ta minik kalbin, azıcık acı çeksin

İşte o an gerçeği, kendin de göreceksin

Ne zaman büyüdün de sever oldun sen beni', 'Daha dün ağlıyordun, kollarımda delice Kaç günde büyüdünde, sever oldun sen beni Sözde çoktan yazılmış, kaderim kaderine Ne zaman büyüdün de...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-zaman-buyudun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimse yoktu', 'kimse-yoktu-zafer-zengin-etnika-ts646', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kimse yoktu

sezgilere çıkan yolun başında

ay bile karanlıktı

efendilerin verdiği 

ekmek bile yetmedi

can yediler içinden

kan içtiler

kutsal kadehler doldu boşaldı

üstüne sigaralar yakıldı

| Şövalyelere görev..bulun |

sövgü bas seslere 

tınısal açlık katınca

karın kaslarına makara sardılar

cektiler cekebildiğince

kramplar

lif kopmaları

ve acı vardı

naylonlara sardılar

sterilmiş elleri

kancıkca bir şey

ne adama 

ne kadına yakışan

| tanıyorlardı adamı..yalansızdı..olmadık yakıştırmalar ve iftiralar |

ilk ilmekten kan sızdı

bıçak değilmiş kesen

yüzmüş

binmiş giden

ardına nehir ışıkları bağladılar

siz deyin missisipi *

ben deyim yanıyor

köleymiş bu insanlar

| sonra kızdım açlığa..benden daha özgür diye..umursamadı | 

adını bağışladı kör çalgıcı

dünya''yı bizden daha iyi anlardı

| düşünsene renk nedir görmemiş..bir sürü şarkı bestelemiş |

uzun marş gecelerinden sonra

kamplar 

ve insanlar

tok kalktıkları masalara

siyah çiçek bıraktılar

aç çocuklar bir daha doğmadı

gülenler kapı dışarı

dışarda kalanlar linç

birşey bilemeyenler köle

| İşte böyleydi..içini yitir / Burada şiddet var |

yalnızlığına ok atıp

sapı saman edip dişlerine

bir gece vakti belki de

içine dökeceğin elleri

olmayacak güne oldurdular

| hatırlatsınlar yalnızlığa..gerdeğe gireceğiz onunla..

en az iki yalnızlık daha istiyorum..adları hazır..boşluk ve hiçlik |

Sövdü kör şarkıcı

görmediğim şeyleri becerdim

anıtlar

köprüler

kuleler yaptım

yazanın suçu yok

ben yaptım

körlüğümle seze seze

| görmediği sigarasının dumanından halka yaptı..kimse öğretmemişti..ilginç |

üç parça olsa bir apan/sız/dist

kana bulamadan içinden alınacak

mumyalar kıskanır işte

böyle güzellikleri

sanki mezbaa

hep şiddet dediniz

derdiniz ne

neden böyle delirdiniz

| bilmiyorlar..hep fazla durur hayat..içine çek..içine çek..seviş gülün suyunda..ak pak |

nasıl derlerin uğradığı

son bahçevan bakışı

çim gölgelerine gizlenip

ihbar etti dünyayı

atmosfer fazla

gaz fazla

her yan bilgi

kimse mutlu değil

nereye gidilsin ki

aracınız cekin

en ıssız limanlar sizin

yelken takın ucuna

saklanın insanın olmadığı

herkesin korktuğu yalnızlığa

birşey desem

şimdi küsersin

ben en çok gülen insanı sevdim

| değiştim..değiştin..değiştiler..değişecekler..geri burda çay içmeye gelecekler |

-  çay burda paralı

-  bedelsiz ne var

-  aşk var

-  başka

-  bilmem

 bilmeyenler hep gittiler

çok kalanlar fazla istemediler

////çınar ağacına ve yaprağına selam

   ağıt gibi hayat..oy canım..kendi canım  ////

Bu kısmı taksici yazdı..efkarlanmıştı

indiği yerden yürüdü rüzgar

ipin ucuna tahta lehim

belkide sancı bağlayacaktı

Biliyordu işte

bu insanlar

bir kirpi neden var anlamayacaktı

aşk istediler hep

aşık olanları kestiler

lime lime ettiler

defnettiler

güzel söze karşı

| Aşk uğramaz oldu yalnızlığa..sancılara.yaralara..

ne vardı..öpseydiniz yanağından ya da alnından |

merhaba

bilinir sır gibi süzüldü içimize

anladık düşününce

ölü/yordu

* Missisipi yanıyor adlı film

9 Temmuz 2004  '' Gece dırdır etmez ''', 'kimse yoktu sezgilere çıkan yolun başında ay bile karanlıktı efendilerin verdiği  ekmek bile yetmedi can yediler içinden kan içtiler kutsal ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":117,"source_url":"https://www.antoloji.com/kimse-yoktu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenen...', 'beklenen-hasan-akin-k5bu4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uzak diyar yolcularını uğurlayıp; 

sen yine en sonamı 

kaldın .......... ...................   .................................... ..........

Yoksa! ! 

Kızıl akan nehirden

Sandala bindin de

............ .............. yoldamısın.......................

(Dost...Uğur nevruz''a)', 'Uzak diyar yolcularını uğurlayıp;  sen yine en sonamı  kaldın .......... ...................   .................................... ...........', ARRAY['Türk Edebiyatı','Şiir','Hasan Akın']::text[], 8.5, '{"poet":"Hasan Akın","poet_slug":"hasan-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/beklenen-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahkûm Edildim', 'mahk-m-edildim-osman-i-nci-e03tw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mahkemeye çıktım, bağlıydı iki elim,

Gururum savcıydı, sevdam da hakim,

Gözlerinin içine bakan, yaşlı gözlerim,

Davacı oldu benden, mahkûm edildim...

Yasak bir aşkmış bu, kime ne dedim,

Sözlerimi hiç kimseye, dinletemedim,

O saçların vardı ya, çok beğendiğim,

Davacı oldu benden, mahkûm edildim...

Ne avukat savundu, ne ben inkâr ettim,

Yasak olsa da, bu aşkı ben de istedim,

Bir gümüş kolye vardı ya, sana verdiğim,

Davacı oldu benden, mahkûm edildim...

Uğruna akıttığım, kanlı göz yaşlarım,

Boşa geçip giden, toz pembe yıllarım,

Yeşermeden kuruyan, tüm umutlarım,

Davacı oldu benden, mahkûm edildim...', 'Mahkemeye çıktım, bağlıydı iki elim, Gururum savcıydı, sevdam da hakim, Gözlerinin içine bakan, yaşlı gözlerim, Davacı oldu benden, mahkûm e...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mahkum-edildim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kâmil', 'k-mil-sair-ahrazi-dg32j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '‘’Gel! Şu dünyâyı yıkta gel,rûhunu aşkla yakta Gel,

Seni sana veren benim,benliğini bırakta Gel.’’

_Kâmil_

Uzun ve sırlı bir yolda kaderine boyun eğmişti,

Çâresiz,yapayalnızdı lâkin isyân da etmedi,

Her nereye adım atsa ona kırağı değmişti,

Yetişemedi hayâta,umut yaşama yetmedi.

Cândan vazgeçtiği anda,bir ses belirdi o cânda,

Uyân dedi,artık Uyân! Hak’tır seni derde koyan.

***

Nutku tutulmuştu sanki,sözlerden medet bekledi,

Çorak bir topraktı dili,Eyvâhlar bile bitmedi,

Yâ Rab diyebildi ancak,hayât dedi ve ekledi,

Ben kaderimle geldim de bahtım çilesiz gitmedi.

Sitem huzûra varmadan,ilhâm eyledi Yaradan,

Uyân dedi,artık Uyân! o çiledir seni ayan.

***

Bî tâkat kalınca dizi,yere doğru çöküverdi,

Yoluna çıkan gölgesi,sarp dağları aratmadı,

Bir başka göründü artık,beyhûde buldu kederi,

Beni ve dedi her şeyi,Hak’tan başkası yaratmadı.

Kim ne umarsa cihândan,onu seçmiştir ziyândan,

Elbet mahşerde uyanır,cihândayken uyanmayan.

***

Adına büründü Kâmil,kendine misâfir oldu,

Yalan dünyâda sefilken,her âleme sefir oldu.

*****', '‘’Gel! Şu dünyâyı yıkta gel,rûhunu aşkla yakta Gel, Seni sana veren benim,benliğini bırakta Gel.’’ _Kâmil_ Uzun ve sırlı bir yolda kaderine ...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kamil-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçemem', 'vazgecemem-i-smail-senturkyalnizkurt-8skxc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen benim yaban gülüm

Sen benim hüzünlü şarklarda aradığım sevdiğim

Sen benim geçen mevsimlerim

Sen benim beklediğim kadınsın

Senden nasıl vazgeçerim



Gelmeyeceğini bile bile beklediğim günlerden

Beni bırakıp gitmez dediğim o güzel gözlerinden

Nasıl vazgeçerim



Seni görmeyen gözlerim kör olsun

Ellerini tutamayan ellerim kopsun

Artık istemem onları

Sen ol yeter yanımda

Göz yaşlarımı dindir yeter

Vazgeçmemi isteme benden

Vazgeçemem senden vazgeçemem...', 'Sen benim yaban gülüm Sen benim hüzünlü şarklarda aradığım sevdiğim Sen benim geçen mevsimlerim Sen benim beklediğim kadınsın Senden nasıl v...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şentürkyalnızkurt']::text[], 8.5, '{"poet":"İsmail Şentürkyalnızkurt","poet_slug":"i-smail-senturkyalnizkurt","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/vazgecemem-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat''ın Anlamı?', 'hayat-in-anlami-mehmet-yilmaz-ht9g6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'zaman hayatın içindedir.

hayat dediğin bos bir tarih olur kaybolursun içinde

ama farkına varamazsın

Bir olustur cünkü.

Hayat mutluluk dersin simdi,

Ama bununla sınırlı değil.

Mutluluk sadece kavramdır.

Ama sen bu hayatın içine bu kavramı sokamazsın,

Cünkü hayatın mutluluk değil,baska sentezlerle yüklü oldugunun farkına varırsın.

Gerçekleri bir âmâ kadar bile görmediğinde

Ateş kırmızısı umutlar, yanar küllerin ateşinde 

yanıyorsun...heyy sana diyorum.

O boş bir tarih olur, zaman içinde kaybolur 

hayat bu mudur? 

Belkide...

cewabı o kadar cok ki,

bu sözlerin sahibi ben değilim hayat. hayatın ta kendisi.

ama ben söylüyrm

o halde ben hayatım.

hayatı tanımlamaksa bu kadar kolaydır Benim için.

beni düşündüren Mi yasamak istiyorum teorisidir.

Neden mi düşünüyorum? 

bu bana verilen bir ödevdir.

ödevi yapaamazsam zayıf alırım yasayamam.

Anlayamadığımız bizim sorunlarımızdı 

ama ben anlamak istiyorum ve düşünüyorum

beni düşündüren bu olsun daha fazla kavram yüğkleyip kafanın karsımasını istemem.heyy sen sana diyorum duyuyor musun Beni

Yaşarken düşünmediğimiz yarınlarımızdı! ... 

ama ben düşünüyorum.

yeteli mi bu cewab

nerdeyim? 

Ben Kimim...? 

sorun kendinize

biraz felsefik yükleme yapın hayatınıza

nerde olduğunu ne yasadığınız ne yasamak istediğinizi düşünün...

ondan sonra diğer kavramları yükleyin

dedim yaa

Bir merhaba girer önce hayatınıza 

Merhaba bir insana dönüşür sonra 

Hayatın anlamı ise sadece sizin varlıgınızdır? 

Neden mi? 

Yasamayı öğrendiyseniz....', 'zaman hayatın içindedir. hayat dediğin bos bir tarih olur kaybolursun içinde ama farkına varamazsın Bir olustur cünkü. Hayat mutluluk dersin...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz']::text[], 8.5, '{"poet":"Mehmet Yılmaz","poet_slug":"mehmet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/hayat-in-anlami-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kiraz çaldım bahçenizden', 'kiraz-caldim-bahcenizden-zafer-zengin-etnika-g8xaf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eski mahalleden geçtim

Eskimiş sokaklarından

İnsanlarından

Eskimiş evimiz

Çocukken sevdiğimiz

Çalıştığım binalar

Ardiyeler

Üstümüze düşen tomruklar

Ele batan kıymıklar

Dolamalar

Çıbanlar

Ve kurusun diye 

Yüzümüze sürdüğüz çamurlar

İçinden geçtim 

Arz''ı yakınmış elime

Yaşlanmış herşey

Kurşunlanmış direk

Bombalanmış kahvehane

Artık yok yerinde

Duvarlar silinmiş

Sloganlar evine çekilmiş

'' Yaşasın tam bağımsız türkiye ''

O bile silinmiş

Ağaçlar harami gibi

Yaprak aldırmamışlar dallarından

Bükük boyunları

Emekçi gövdesi

Yok artık

Sarı kayısı meyvesi

Babamın diktiği asma

Diktiği kavak

Topraktan o kadar uzak

Gurbet gibi birşey

Böyle yarım kalmak

| Gittim işte

 Erik çaldım

 Kiraz çaldım 

 Bahçenizden

 Hani sizindi eskiden |

Viran olmuş evimiz

İhtiyar bir yüz gibi

Çökmüş kendi içine

Taş duvar yıkılmış

Toprağa karışmış

| Öylece büyüdü zaman.. içimde |

Akşamdı

Yalnızdı

Evimiz ve

Mahallenin kabadayısı

D u t   a ğ a c ı

8 Temmuz 2004 ''Sarı kerpiç un olmuş burada ''', 'Eski mahalleden geçtim Eskimiş sokaklarından İnsanlarından Eskimiş evimiz Çocukken sevdiğimiz Çalıştığım binalar Ardiyeler Üstümüze düşen to...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/kiraz-caldim-bahcenizden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım', 'yarim-omer-faruk-cakir-k6myu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben, birtek

ortadan ikiye bölündüğümde acırım dost! 

Gayrısında incinmem, kanamam,

Beni daha fazla kim incitebilir ki dost

Sevdiğim ayırmış beni ortamdan ikiye,

Ben bir tek

Ortadan ikiye bölündüğümde acırım

Bir yarım bırakılıp

Bir yarım götürülünce acırım benden! 

İşte böyle zamanlarda diyorum çok,

solucan olmalı bazen

Solucan gibi yaşamasanda

toprağın altında, korunaklı

ve serin olmasanda,

Solucan olmalı bazen,

Bir yarın götürüldüğünde

tamamlayabilmeli giden yarını

Bir yarın eksik yaşanmıyor dost!', 'Ben, birtek ortadan ikiye bölündüğümde acırım dost!  Gayrısında incinmem, kanamam, Beni daha fazla kim incitebilir ki dost Sevdiğim ayırmış ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Çakır']::text[], 8.5, '{"poet":"Ömer Faruk Çakır","poet_slug":"omer-faruk-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yarim-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bandroller ülkesi', 'bandroller-ulkesi-can-i-rfan-gzbc2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Parçalayın bakalım

Parçalayın tek,tek

Kurun tekler ülkesini

Kurun birler ülkesini 

Kurun şaşalar ülkesini

A yırın  bu karanlık diye

A yırın bu aydınlık diye

Gönderin a yıran yasalarınızı

Gönderin ölüm saçan aydınlık bombalarınızı

Gönderin karanlık,karanlık diye…

Yok edin sefaletten püfür,püfür esen orman havasını…

Uzaklaştırın sefaletten zümrüt mavisi denizi…

Bırakın pis kokularınızı

Bırakın kirli köpüklü kıyılarınızı

Doyurun sefaleti…

Bağlayın bedenleri pet şişelerine

Bağlayın ciğerleri oksijen çadırlarına

Satın,satın; 

Çeşit,çeşit marka sigaralarınızı

Yazmanıza da gerek yok

 ‘’Sigara sağlığa zararlı’ yazısını

Satın kapak,kapak alkolleri

Yapın spor kumpanyalarında reklamlarınızı…

Doyurun sefaleti…

A yırın ruh’u, a yırın bedeni

Parçalayın bakalım

Parçalayın tek,tek…

Olsa da pet şişesine bağlı bedenim

Kalsa da oksijen çadırına bağlı ciğerim

Ey bandroller ülkesi; 

Topunuz gelseniz de  bu alemde bir araya

A yıramayacaksınız ruhum ile bedeni yine de…', 'Parçalayın bakalım Parçalayın tek,tek Kurun tekler ülkesini Kurun birler ülkesini  Kurun şaşalar ülkesini A yırın  bu karanlık diye A yırın ...', ARRAY['Türk Edebiyatı','Şiir','Can İrfan']::text[], 8.5, '{"poet":"Can İrfan","poet_slug":"can-i-rfan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bandroller-ulkesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Olurdum..!', 'senin-olurdum-nazife-abayli-oez43', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ah dostum..! 

Keşke şimdi yanımda olabilsen.

Yanımda olup,

Yürek yangınlarımı görebilsen..

..........................................................

İçli içli söylenen şu türküler var ya,

Hani insana offf çektirip,

Karşıki dağları yıktırır ya...

Ayrılık acısıyla eridiğin,

Özlemekten bittiğin an,

Yüreğini bir kez daha,

Yaktırır ya..

.....................................................

Ah dostum.! 

Sensiz dinliyorum şimdi o türküleri.

Keşke şimdi gelebilsen.

Gelip te  ellerimi tutabilsen..

Yürek yangınlarımı görebilsen..

Senin olurdum..! ! 

4.Levent-İSTANBUL', 'Ah dostum..!  Keşke şimdi yanımda olabilsen. Yanımda olup, Yürek yangınlarımı görebilsen.. ....................................................', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/senin-olurdum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmek', 'bitmek-ahmet-aksoy-z51ed', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir şeyin bitmesi ne zor

......geçmesi usundan ayakların

ve o durmadan yanan izlerin

........duman kokusu

bitti demek bir şey dışında

.........hükmün sıyrıldı elinden

......ne saadettir yokluk

....................ne de huzur

kaybetmek bir kez avuçlarında olanı

................bilmek zaten

hiç bir şeyinin olmadığını

...............sen, ruh ve boşluk

içindeki vahim gerçek

..........hayalet tutmazlığı

gördüğün hiç bir şey senin değil

...biter her şey bu şiir gibi

............aslın ruh', 'bir şeyin bitmesi ne zor ......geçmesi usundan ayakların ve o durmadan yanan izlerin ........duman kokusu bitti demek bir şey dışında .........', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bitmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '“Aşk olsun çocuk”', 'ask-olsun-cocuk-ozkan-yildirim-cv0d7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '.......    M. Göktepe`nin anısına

Bir çocuk büyüdü

Varoş`ların da şehr-i  Istanbul`un

Kara  yağız  delikanlı 

 Bir genç yürüdü

Onurlu kavgasın da yaşam`ın

 Ilk görüşümdü

Mektep-i  mapusta 

-  ve son…

Bir yürek bulundu

Kirli eller ulaşamamış 

-  Eyüp parkın da…

Resimlerde gülüşüyle

Kavga da yürüşüyle

Güzel gelecek düşleriyle

Susmayan Metin olmak gerek





Ocak 1996', '.......    M. Göktepe`nin anısına Bir çocuk büyüdü Varoş`ların da şehr-i  Istanbul`un Kara  yağız  delikanlı   Bir genç yürüdü Onurlu kavgas...', ARRAY['Türk Edebiyatı','Şiir','Özkan Yıldırım']::text[], 8.5, '{"poet":"Özkan Yıldırım","poet_slug":"ozkan-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ask-olsun-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efenin Müjdesi', 'efenin-mujdesi-omer-bedrettin-usakli-wgao6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çoban yıldızı gibi

Gönlüme kaydın Ayşe! 

Bir peri kızı gibi

Saçını yaydın Ayşe! 

Şanımız, ünümüz var,

Çok sevinç günümüz var

Yarın düğünümüz var:

Gözlerin aydın Ayşe...', 'Çoban yıldızı gibi Gönlüme kaydın Ayşe!  Bir peri kızı gibi Saçını yaydın Ayşe!  Şanımız, ünümüz var, Çok sevinç günümüz var Yarın düğünümüz...', ARRAY['Türk Edebiyatı','Şiir','Ömer Bedrettin Uşaklı']::text[], 8.5, '{"poet":"Ömer Bedrettin Uşaklı","poet_slug":"omer-bedrettin-usakli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/efenin-mujdesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-omer-bedrettin-usakli-5nffh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Arı nasıl ayrılır,

Altın rengi balından..

Gül nasıl koparılır

Mor dikenli dalından? 

Bıraktın ellerimi,

İşte bindiğim gemi

Ayrıldı sandalından...

Son bir defacık görün; 

Denizde güzel yüzün

Batan bir güneş gibi

Değil belki çok uzak

Bir gün yine doğacak

Bu şen güneş denize..

Ruhumuza işleyen

O tatlı yedi günden

Bir rüya kaldı bize..

Elveda ey sevgili! 

Salladığın mendili

Bırak, rüzgar uçursun..

Güç olacak bu hasret,

Bir mabut gibi emret! 

Bindiğim gemi dursun..', 'Arı nasıl ayrılır, Altın rengi balından.. Gül nasıl koparılır Mor dikenli dalından?  Bıraktın ellerimi, İşte bindiğim gemi Ayrıldı sandalınd...', ARRAY['Türk Edebiyatı','Şiir','Ömer Bedrettin Uşaklı']::text[], 8.5, '{"poet":"Ömer Bedrettin Uşaklı","poet_slug":"omer-bedrettin-usakli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/veda-104-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağaç Üstüne', 'agac-ustune-i-lyas-ozmen-5zau3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ağaç deyip geçme sakın

Bir dikeriz yüze döner

Ne verirsek ziyan etmez

Rızık olur bize döner

Meyve olur bahçemizde

Azık olur bohçamızda

Hece -hece lehçemizde

Kalem yazar söze döner

Çiçeklerle süslenince

Türlü renkle beslenince

Bülbül güle seslenince

Bahar gelir yaza döner

Servi olur söğüt olur

Ahlat olur armut olur

Gökte uçan bulut olur

Yağmur olur öze döner

Toprak kaymaz bölgesinde

Hilaf olmaz belgesinde

Sevgililer gölgesinde

Cilve yapar naza döner

Bahçe olur orman olur

Hasat olur harman olur

Çare olur derman olur

Fer olur da dize döner

Eğer dikmez isen ağaç

Yerin yurdun kalır kıraç

Ozanlar sesine muhtaç

Tel takılır saza döner

Özmen der ki okuyorsan

Ağaca hor bakıyorsan

Ormanları yakıyorsan

Yüreğimiz köze döner', 'Ağaç deyip geçme sakın Bir dikeriz yüze döner Ne verirsek ziyan etmez Rızık olur bize döner Meyve olur bahçemizde Azık olur bohçamızda Hece ...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özmen']::text[], 8.5, '{"poet":"İlyas Özmen","poet_slug":"i-lyas-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/agac-ustune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye', 'sevgiliye-omer-bedrettin-usakli-c58es', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yolunda gençliğim sönse de, yine

İçimde kız senin aşkın var, yeter.

Baygınlık çöksün de kirpiklerine

O kumral saçlarla beni sar yeter.

Varlığın düşerken en şakrak çağa

Dolaştım bakıştan,nurdan bir ağa; 

Beni öldürmeğe ve yaşatmağa

O baygın gölgeli bakışlar yeter..

Karşında hasretle gelsem dize de

Anlatsam şu gönül ne felekzede.

Bahar yollarında ikimize de

Manekşe türbeli bir mezar yeter...', 'Yolunda gençliğim sönse de, yine İçimde kız senin aşkın var, yeter. Baygınlık çöksün de kirpiklerine O kumral saçlarla beni sar yeter. Varlı...', ARRAY['Türk Edebiyatı','Şiir','Ömer Bedrettin Uşaklı']::text[], 8.5, '{"poet":"Ömer Bedrettin Uşaklı","poet_slug":"omer-bedrettin-usakli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgiliye-69-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Engin Şarkısı', 'engin-sarkisi-omer-bedrettin-usakli-10i6n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İşte yapayalnızız

Güzelim, altım tacım.

Bırakta sandalımız

Engine yelken açsın; 

Ben senden utangacım

Sen benden utangaçsın..

Meleğim, can kaynağım,

Engine...ah, engine! 

Korkup ta bakmadığım

Gözlerinin rengine

Enginde bakacağım! .

Kıskanç, hain bakışlar; 

Hasutlar görmesin de,

Nefesim nefesinde,

Ne olur görsün bizi; 

Seyretsin ikimizi,

Perişan sesli rüzgar,

Yorgun kanatlı eşler...

Benden yangın akşamlar,

Sanden solgun güneşler...

Utangaç aşıklara

Çok tenha bir yer ister; 

Bu sahiller bize dar,

Bize aşkımız kadar

Derin enginler ister! ..

Meleğim can kaynağım; 

Engine...ah, engine! ..

Enginde bakacağım

Gözlerinin rengine! ..', 'İşte yapayalnızız Güzelim, altım tacım. Bırakta sandalımız Engine yelken açsın;  Ben senden utangacım Sen benden utangaçsın.. Meleğim, can k...', ARRAY['Türk Edebiyatı','Şiir','Ömer Bedrettin Uşaklı']::text[], 8.5, '{"poet":"Ömer Bedrettin Uşaklı","poet_slug":"omer-bedrettin-usakli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/engin-sarkisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paylaşılamayan Dünya', 'paylasilamayan-dunya-salih-gokboru-x2j2z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kahbelik,

Kancıklık ediyorlar...

Döllerinde de var...! 

Kötü yunan,

Kör moskof ve; 

Kendini ki Cihan''a,

Jandarma hayalleyen; 

Yankeeler var...! 

Ortaasya, Kerkük, Balkan; 

Eski köyümdü...

İnsanlar orada da müslümdü..! 

Halife-i Cihan,

Ve padişah-ı ferman; 

Titretip ruy-i zemini,

üç koca kıt''aya,

Hakimdi...

Adildi...

Mertti...

Her zaman böyle idi,

Türk''ün hali...

Yalan mı bunlar tarih...? 

Ses ver derinden..! 

Söyle...! 

Ben ki kavğada şahin,

Harbimde kartal,

Ve mücadelemde,

Azrail''e yamak,

İdim ki; 

Can alırdım...

Sırıt can düşmanım; 

''Son gülen,

İyi güler...! ''

Tek can kalmasa,

Gökbörü''den başka; 

Düşmana Gökbörü yeter...!', 'Kahbelik, Kancıklık ediyorlar... Döllerinde de var...!  Kötü yunan, Kör moskof ve;  Kendini ki Cihan''a, Jandarma hayalleyen;  Yankeeler var....', ARRAY['Türk Edebiyatı','Şiir','Salih Gökbörü']::text[], 8.5, '{"poet":"Salih Gökbörü","poet_slug":"salih-gokboru","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/paylasilamayan-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımın Kini', 'askimin-kini-omer-bedrettin-usakli-herd9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O çoşkun gençliğimi bütün yoluma verdim,

Git, kanlı gözlerimde ateşlenmesin derdim..

İçimde şimdi sana bir fırtına var kinden,

Hicran zamanlarında mesuttum şimdikinden...

Şimdi harap gönlüme ne gelen var, ne giden,

Şimdi öksüz ruhumda eser yok hiç sevgiden,

Gönlüm bahtımdan ölgün, ben gönlümden ölgünüm,

Yakıyor, zehirliyor beni her geçen günüm..

Ruhum serinleyecek, hiç kalmayacak tasam,

O zalim yüreğini bir kere parçalasam! ..', 'O çoşkun gençliğimi bütün yoluma verdim, Git, kanlı gözlerimde ateşlenmesin derdim.. İçimde şimdi sana bir fırtına var kinden, Hicran zamanl...', ARRAY['Türk Edebiyatı','Şiir','Ömer Bedrettin Uşaklı']::text[], 8.5, '{"poet":"Ömer Bedrettin Uşaklı","poet_slug":"omer-bedrettin-usakli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/askimin-kini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esmer Papatya', 'esmer-papatya-adnan-durmaz-y21yu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yurtsuzum

damım da yok

şu arkası dönük oturansa hüznüm olur

lime lime bir gülüş

yama yama bir bakış

ne diyeyim

	buyur

		otur

			kimsesiz kederime

hoş geldin... 

ne yalan söyleyeyim

kendi özlemlerimi

çoktan kaldırıp attım

ev araba kariyer ün vs... 

gerçi bunlar zaten

bana ait değildi

olan birkaç şey

onlar da

tarihimin yol büklerinde

yıktığım köprülerde

batırdığım gemilerde falan kaldı... 

gayri yolculuklar ömrüm

göçmenim

gölgesinde oturacak 

bir ağacım bile yok

ne taş üstünde taşım

ne gökte uçar bir kuşum... 

olmadık bir iklimdi ki geçtiğim

yol yorgunu günlerime hoş geldin

gel otur

yüreğimin terkisine

esmer bir papatya

bir hüzzam uzun hava olarak

gayri

seni de katarım şarkılarıma

ama sen

bu yurtsuza kanma

yurdum ki

koştukça tutulmayan

buldukça yitirilen

	bir yar

ömrüm ki

bir deli düş avcısı

diyar diyar

sen bana yanma... 

susuzsan

bir damla gözyaşım var

kal ağladığım yerde

ama sen

ağlama... 

birazdan bir bulut gelir

ve ben çekip giderim

gülüşün bundan böyle

susuz zamanlarımda

bir pınar olur akar

esmer güzeli papatya

çok yitirmiş gözlerime 

hoş geldin

adnan durmaz,bilirsin aşk da serseri,art yay,ank,2003', 'yurtsuzum damım da yok şu arkası dönük oturansa hüznüm olur lime lime bir gülüş yama yama bir bakış ne diyeyim 	buyur 		otur 			kimsesiz ked...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/esmer-papatya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazık oldu', 'yazik-oldu-mehmet-elmacioglu-zzgbo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yazık oldu tertemiz duygulara,

Şimdi bir sonbahar yaprağı gibi,

Soluyor güller açan yüreğim.

Sevgi dolu sözler artık anlamsız,

Vurulmuş bir ceylan gibi,

Çağlıyor ağlamayı bilmeyen gözlerim.', 'Yazık oldu tertemiz duygulara, Şimdi bir sonbahar yaprağı gibi, Soluyor güller açan yüreğim. Sevgi dolu sözler artık anlamsız, Vurulmuş bir ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Elmacıoğlu']::text[], 8.5, '{"poet":"Mehmet Elmacıoğlu","poet_slug":"mehmet-elmacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yazik-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birgün benim gibi...', 'birgun-benim-gibi-mehmet-elmacioglu-dhmxj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Birgün sende seveceksin,

Yüreğin acıyla tanışacak,

Gülmeyi unutup ağlamayı öğreneceksin,

Benim gibi! 

Belki daha delicesine,,,

Birgün terkedilmeyi tadacaksın; 

Mutluluğunun doruğunda.

Kadehlerde arayıp,

Ömür tüketeceksin meyhanelerde.

Benim gibi! 

Belki daha dayanılmazıyla...

Ve beni anımsayacaksın.

Dostlarım öldüğümü söyleyecekler,

Issız bir anda yanıma gelip ağlayacaksın,

Belki o zaman beni anlayacaksın.', 'Birgün sende seveceksin, Yüreğin acıyla tanışacak, Gülmeyi unutup ağlamayı öğreneceksin, Benim gibi!  Belki daha delicesine,,, Birgün terked...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Elmacıoğlu']::text[], 8.5, '{"poet":"Mehmet Elmacıoğlu","poet_slug":"mehmet-elmacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/birgun-benim-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte ben böyleyim', 'i-ste-ben-boyleyim-mehmet-elmacioglu-e2wkw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İşte ben böyleyim sevdiğim; 

Engin sularda sürüklenen,

Çılgın dalgaların esiri,

Küreksiz bir sandal gibi.

İşte ben böyleyim sevdiğim; 

Çökünce akşamın kızılı ufka,

Yanar sevda yüklü yüreğim,

Düşünce bir yıldızın şavkı suya,

Boşalır çağlarcasına gözlerim.', 'İşte ben böyleyim sevdiğim;  Engin sularda sürüklenen, Çılgın dalgaların esiri, Küreksiz bir sandal gibi. İşte ben böyleyim sevdiğim;  Çökün...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Elmacıoğlu']::text[], 8.5, '{"poet":"Mehmet Elmacıoğlu","poet_slug":"mehmet-elmacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/iste-ben-boyleyim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlahi Sam amca :)))))', 'i-lahi-sam-amca-seref-yildirim-01a9b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sam amcanın kulübesinde

yaşamla ölüm arasında

siyahı var kızılı var ama ille de beyaz

az mı yaktılar katlettiler köleleştirdiler

kızıl derilisini,kara derilisini

gemilerle geldiler beyaz efendiler

yeni kıtanın keyfini çıkardılar

kafatası yığdılar istiflediler koleksiyonlarına

acımadılar kükreyen boğanın barış çubuğuna

acımadılar Afrika dan getirdikleri zencilere

sattılar pazarlarda güçlü ve güzellerini 

emeklerini ırzlarını sömürdüler yıllar yılı 

sonra bir gün kendileri düştüler dara

ikiye ayrıldılar kuzeylere güneylere

kazanan köleliği kaldırdı sözüm ona

kazanan deri ayrımı yapmadı sanırsın

oysa inlettiler kendi renklerini bile

İrlandalısını İsveçlisini  ayırmadan

yetmiş iki millet birleşti Yahudi, Ermeni, Rum lobisi

dünya dize geldi önlerinde sermayelerine,dolarlarına 

emek ucuzluğu silah teknolojisi oldu ülküleri

geliştikçe kudurdular Nikaraguasına,Filipinine,Kübasına 

Koreler de kanlar akıttılar Natosu ile 

Vietnam da kayboldular ormanlarda çaylarda

yetmedi daldılar Libyasına arabına çöllerine

Afganistan Irak son duraklarımı bilinmez 

İranı Suriyesi helede Türkiyesi  mi hedef olacak

kanlı emparyellerin kirli emellerine

cihan savaşından atomundan doymadı da

söndürüyor hala ocakları terörizm diye,ille de İsrail diye

radara yakalanmayan uçaklar dolusu bombalar yağıyor da yağıyor sana bana 

ama dur.! ! ! 

ilahi sam amca :))))    bulaşma bize sömürdüğünle kal yıllardır…

yoksa bilmezmisin  imparatorlukların bir gün tarih olacağını

yoksa bilmezmisin ulusların ne Mustafa Kemaller çıkaracağını…

09.07.2004

Şeref Yıldırım', 'sam amcanın kulübesinde yaşamla ölüm arasında siyahı var kızılı var ama ille de beyaz az mı yaktılar katlettiler köleleştirdiler kızıl deril...', ARRAY['Türk Edebiyatı','Şiir','Şeref Yıldırım']::text[], 8.5, '{"poet":"Şeref Yıldırım","poet_slug":"seref-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/ilahi-sam-amca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLüM KOKAN O SEVDAN', 'olum-kokan-o-sevdan-mehmet-kizilay-eso5t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölüm kokan o sevdan

Düşmedi ki, yakamdan

Sanki gölgemmiş gibi,

Ayrılmadı arkamdan..

(Nakarat) 

Zalimin kızı Suna

Bayıldım kokusuna

Baban düşürdü bizi

Yusuf''un kuyusuna

Leyla ile Mecnun''a

Neden özendik Suna

Sonunu düşünmeden

Düştük aşk mahpusuna.

(Nakarat) 

Gavurun kızı Suna

Ağlıyorum duysana

Derin uykuda sanki

Yatmış kış uykusuna

Bir tas su ver içeyim

Elinden kana kana

Zehir olsa içerim 

Elinden kana kana..

(Noter Onaylı Şarkı Sözü--1999)', 'Ölüm kokan o sevdan Düşmedi ki, yakamdan Sanki gölgemmiş gibi, Ayrılmadı arkamdan.. (Nakarat)  Zalimin kızı Suna Bayıldım kokusuna Baban düş...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kızılay']::text[], 8.5, '{"poet":"Mehmet Kızılay","poet_slug":"mehmet-kizilay","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/olum-kokan-o-sevdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşamdı', 'aksamdi-zafer-zengin-etnika-rp2bk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Akşamdı

anam kayısı toplamıştı

yandan baktım

bir çınar gibi  yaşlanmıştı

az sayılmaz

on iki çocukda haylaz

dördü yolda kalmış

ömürleri pek az

deseler ki bereket

aklıma gelir memleket

içinde anam

doğurgan ve çalışkan

anadolu kadını

topraktan almış inandını

Akşamdı

anam kayısı toplamıştı

yandan baktım

bir ana gibi yaşlanmıştı

muzipim çocuk gibi

yanağını öptüm gül gibi

sevindi mutlu oldu

oda öptü can gibi

Akşamdı

babam yoktu yine

ben küçükken gitti

bir daha dönmedi

çalışkan espirili

ağaç diker

yonca biçer

gül bakardı

bahçevandı

lakin en çok aşkını

anama saklardı

| Ben sevgili koluna düştüğümde

o ağaçtan düştü..yeşildi düşü

yeşile gömüldü..öldüğü yere gül düştü |

aşk dersen usta

babama çekmişim

| gülü sever çaktırmazdı

güzelliği renginde arardı..kokusunda |

hiç aldattığını duymadım

buydu en yakışıklı yanı

bir de karakaş

pala bıyığı

demem o ki usta

adam gibi adamdı

düşmanı gelse 

merhabasını alırdı

çatalyürekli

mertti işte

eskilerin deyişiyle

Akşamdı

anam beni öptü

ben babamı

yorgundum

babam beni öptüğünde

ben hala çocuktum

 | Akşamdı işte..akşam..gün batmıştı..gözüme efkar kaçmıştı |

Anne ve babalara..babalar gününde kutlayamadığım dostlara..saygıyla

yoklukları görülmesin..acıları hissedilmesin

9 Temmuz 2004 '' iç yanar dışı ses ''', 'Akşamdı anam kayısı toplamıştı yandan baktım bir çınar gibi  yaşlanmıştı az sayılmaz on iki çocukda haylaz dördü yolda kalmış ömürleri pek a...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/aksamdi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rastgele', 'rastgele-mehmet-elmacioglu-or9b7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tempo tutmuş sularda kürekleri,

Karanlıkta çınlıyor eski yanık bir ezgi:

Rastgele...Rastgele...

Bir deniz emekçisi atıyor ağlarını,

Umut dolu, özlem dolu, arıyor yarınları! 

Rastgele....Rastgele....

Olmaz bu iş böyle....', 'Tempo tutmuş sularda kürekleri, Karanlıkta çınlıyor eski yanık bir ezgi: Rastgele...Rastgele... Bir deniz emekçisi atıyor ağlarını, Umut dol...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Elmacıoğlu']::text[], 8.5, '{"poet":"Mehmet Elmacıoğlu","poet_slug":"mehmet-elmacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/rastgele-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '19 Mart 2002', '19-mart-2002-mehmet-elmacioglu-s0bl8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tüketmeden daha,

Umutlarını,

Düşlerini,

Ve aşklarını,

Bırakıp ardında,

Gidiyor kardeşim,

Alnı ak,

Ak yüreklim.

Zuhal in anısına', 'Tüketmeden daha, Umutlarını, Düşlerini, Ve aşklarını, Bırakıp ardında, Gidiyor kardeşim, Alnı ak, Ak yüreklim. Zuhal in anısına...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Elmacıoğlu']::text[], 8.5, '{"poet":"Mehmet Elmacıoğlu","poet_slug":"mehmet-elmacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/19-mart-2002-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşadım', 'yasadim-ozkan-yildirim-s34oq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşk`lar yaşadım

Düşman kuşatmaları da

Ihanetler yaşadım 

Dostlar arasında

Ayrılıklar yaşadım

Yolculuklar sırasında



Serüvenler yaşadım

Tutsaklıklar ortasında

Varlıklar yaşadım

Yokluklar koy`unda

Acılar yaşadım

Sevdalar deryasında

Sevdalar yaşadım

S E V D A L A R D A', 'Aşk`lar yaşadım Düşman kuşatmaları da Ihanetler yaşadım  Dostlar arasında Ayrılıklar yaşadım Yolculuklar sırasında Serüvenler yaşadım Tutsak...', ARRAY['Türk Edebiyatı','Şiir','Özkan Yıldırım']::text[], 8.5, '{"poet":"Özkan Yıldırım","poet_slug":"ozkan-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yasadim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durduramazlar Zamanı', 'durduramazlar-zamani-melih-coskun-vyedc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne yaparlarsa yapsınlar 

Durduramazlar zamanı

Yasaklayamazlar aklımdan geçen bir düşünceyi 

Yahut sahip olamazlar geceleyin rüyalarıma 

Bilincim kor bir alevdir aysız gecelerde 

Susuşum en büyüğüdür başkaldırının 

Beynimin her hücresinde bir şiir 

Beynimin her hücresinde yitik bir türkü 

Kağıtsız ve kalemsiz kalırım 

Dağların sırtlarına tırnaklarımla kazırım 

Kanımla yazarım bu şiiri sana

Ne yaparlarsa yapsınlar 

Durduramazlar zamanı 

Yasaklayamazlar düşlerimi 

Yasaklayamazlar gülümseyişimi...

(Tuzla Piyade Okulu acemilik günlerinden)', 'Ne yaparlarsa yapsınlar  Durduramazlar zamanı Yasaklayamazlar aklımdan geçen bir düşünceyi  Yahut sahip olamazlar geceleyin rüyalarıma  Bili...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/durduramazlar-zamani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Kalmış', 'yalniz-kalmis-baykal-kaanalp-olt6x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dokunaklı bir veda

bir tavır,bir eda

sevgilisi terketmiş

yalnız kalmış oda

mutsuz kalarak

karanlığa dalarak

birisi onu terketmiş

her şeyini alarak

yalvar yakar olmuş

gözlerine kan dolmuş

canısı onu terketmiş

bu onun sonu olmuş', 'dokunaklı bir veda bir tavır,bir eda sevgilisi terketmiş yalnız kalmış oda mutsuz kalarak karanlığa dalarak birisi onu terketmiş her şeyini ...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalniz-kalmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar Ağladı', 'ruzgar-agladi-baykal-kaanalp-nbm9h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 've rüzgar ağladı 

sebebsiz yere

düşünü kuramadığı için

yaşayamadığı için

sevdiği dondurmaları

kirlettiği için

için için yandı

duman aldı, duman taşıdı

hortumladı ne varsa

gönül koyduğu

kırgın olduğu

kendisi için değil ama

umutsuzluk taşımadı

hiçbir vakit

bir yerden bir yere

kovulsa bile', 've rüzgar ağladı  sebebsiz yere düşünü kuramadığı için yaşayamadığı için sevdiği dondurmaları kirlettiği için için için yandı duman aldı, du...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ruzgar-agladi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutsuzluk Yok', 'umutsuzluk-yok-baykal-kaanalp-v3eru', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'aç bırakıldı

susuz kaldı yılmadı

kahırlanmadı

alamadıklarına içerlemedi

peşinde olmadı

haklarının,hak ettiklerinin

aldatıldığına üzülmedi

kederlenmedi

keder ona çok uzak

bir sözcük

ortalık da dolaşan

manasız sözler içinde

kim izin veriyor

hiç bilmez bu kadar

kötümser sıralanmış

sözcüklerin yaşamasına

kim koşuyor peşinde

olası kılıksızlıkların

her yerde bembeyaz

bir örtü kaplıyken

her yer taze bir güne

gebeyken (sorumsuz) 

kılçıklara aldırmazken

balık yemeye tutkulu', 'aç bırakıldı susuz kaldı yılmadı kahırlanmadı alamadıklarına içerlemedi peşinde olmadı haklarının,hak ettiklerinin aldatıldığına üzülmedi ke...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/umutsuzluk-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşmüş', 'dusmus-baykal-kaanalp-90wor', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'aşktan aşağı düşmüş

akbabalar üşüşmüş

bacağı iki yerden kırık

hayata küsmüşmüş', 'aşktan aşağı düşmüş akbabalar üşüşmüş bacağı iki yerden kırık hayata küsmüşmüş...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dusmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana şiir yazacaktım / bir', 'sana-siir-yazacaktim-bir-zafer-zengin-etnika-cniks', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kenger toplamaya çıktı

sırtında noel baba işi torba

uğradı işte

kurdun kuşun sofrasına

ilhamsız kalan

tasarlamayan

aklında haber tutmayan

dönen duran

hep suçlayan

göz oburların ortasına

| İşte ora bildiğin |

Bak senden başka

bir kişi biliyor

düştüğüm aşka

| İsim yazmadan söyledim seni |

Aklıma gün batımı geliyor

kara kış kıyamet yok

şöyle hafif rüzgar

saçlarını eziyor

ben düzeltiyorum

| Yalnızlar..benle doyuyorlar |

iki iklim bu şey

mevsim desem değil

belki kuantum

belki varlık

cinayet belki

düzgün cümle kurmasamda

içimdeymiş duygu daha

| biliyormusun..hissettiğim için çok mutluyum..iyi ki varsın ve sıcaksın |

aklım sende kaldı

benden zaman çaldı

sana birşey kalmadı

| elim var bilekten kesik..yüreğim belki |

İmgeler soba taşına yapışmış

kurabiye gibi dumanı

nasıldır bilirsin

en güzel öyküleri sen secersin

| işte öyle.. ne güzel düşündün yine |

Okul gibi şu saatler

sensizliği öğreniyorum

resimlerine bakıyor

güzellik buysa

tanrı var diyorum

o kadar itikat doldu ceplerime

seni gülerken düşündüğümde

| yazdım doğru..biliyorum ki şımaracaksın..aşktan başını alamayacaksın..belki de sen ne ilk

ne de son alacaksın..duyar gibiyim..diyeceksin ve hatta düşünüyorsun..

bir yerin var işte..seslendiğim ben ordayım..umuttayım..gözlerin sevinirken gördüğünde

sakladım ben de gözlerime |

öğreniyorum

meşakkatli kesikleri

diş bilemesi

sövgülü sözleri

tül perdeleri

ve adımları

usta bile aklıma geliyor

ne desem bilmem

sanki bulmaca çözüyor

| asit bile % 99 safken..ben çocuk kalıyorum..dünya dönüyor..peki 

bu kadar asit..dünyayı neden eritmiyor..dünya neden kusmuyor |

*****', 'kenger toplamaya çıktı sırtında noel baba işi torba uğradı işte kurdun kuşun sofrasına ilhamsız kalan tasarlamayan aklında haber tutmayan dö...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/sana-siir-yazacaktim-bir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana şiir yazacaktım / iki', 'sana-siir-yazacaktim-iki-zafer-zengin-etnika-qw7f6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'çelik yelek ısmarladım kendime

yeni bir marka

adı musalla

herhalde cabuk varacağım

aşkın koynuna

| itikatım geldi gül..sana saklasam elimi.. kırarlar..bu defa olacak

kararlıyım..ve ilk düşman..alnından vurulacak..sevda bu..kaya bile bırakmayacak |

Su evrensel dediğin şeyler

sanki yalan gibi

mesela soldayken

sol yumruk iniyor mideme

sağdayken sağ yumruk

ortadan yürüsen saksı düşüyor

Bak ne anladım..boş bu insanlar

insansız dünya yapıyorlar

içine boşluk koyuyorlar

sonra mı

kültür

bilim

sanat

tahta at

ve figüransız kalan dünya

garip bir harp

saldırdığı düşman bile kendileri

Zehirliyorlar bilmeyenleri

hesap kesiyor ileri geri

peki

bilmiyoruz da

hissetmiyoruz da

bunuda mı bilmiyorlar

ne diyelim

cahilin eti sert oluyor

kendi yiyor

bitiremiyor

ciğnedikçe

kan geliyor

| bak yeminle..bana yasakladıkları sevmeyi..onlarda bilmiyorlar |

ne anlarsın bundan

öğretici olacağız değil mi

bir proğram yapsak

ucuna kalem taksak

yok olmaz

dar ağacı yasak bana

kelimeleri toparlayamadım daha

sana şiir yazacaktım

bırakmadılar

aklımı çaldılar

bir gece vakti

seni düşündüm

seni gördüm

büyüdüm

yüreğimden güldüm

bak sana şiir yazacaktım

başıma ne işler açtım

Sen ne yaptın gülüm...meraktayım

10 temmuz 2004 '' önce yürek dolmalı ''', 'çelik yelek ısmarladım kendime yeni bir marka adı musalla herhalde cabuk varacağım aşkın koynuna | itikatım geldi gül..sana saklasam elimi.....', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/sana-siir-yazacaktim-iki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dudaklarımı kurutuyor, ıslaklığı dudaklarının', 'dudaklarimi-kurutuyor-islakligi-dudaklarinin-lzcramcil-ceyhun-erdem-ssrs4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Esiyor camdan içeri sessizlik,

dudaklarımı kurutuyor, ıslaklığı dudaklarının,

tülün göğsüne dolunca nefes, nefessiz kalıyorum

ışığın sade akarlığı,

beni karanlık sokağa götürüyor,

usulca içiyorum ellerinden geceyi...

Sus pus olup oturuyor balkonun ucunda, gece karanlığında

yakarak mumunu, kokusunu duyuyor özgürlüğünün,

yaprakları şakıyor dut ağacının

ve dibinde uyumaya imreniyor balkonunun ucunda oturan genç kız,

gözlerinden okunuyor, nasıl da sevdalı yaşama.

Betonun soğuğundan ayaklarım çekiliyor,

sırtımın ağrısına yoruyorum uykusuzluğumu,

sokaktan geçen kafası kıyak kedi parlak gözleriyle çatıyor, dimdik

dikleniyor,

odanın köşeside, şişelerin içinde

bana ait mi bilmediğim bir yüz,

kimsenin istemediği,

istenmeyen yüz.', 'Esiyor camdan içeri sessizlik, dudaklarımı kurutuyor, ıslaklığı dudaklarının, tülün göğsüne dolunca nefes, nefessiz kalıyorum ışığın sade ak...', ARRAY['Türk Edebiyatı','Şiir','Lzcramcil Ceyhun Erdem']::text[], 8.5, '{"poet":"Lzcramcil Ceyhun Erdem","poet_slug":"lzcramcil-ceyhun-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dudaklarimi-kurutuyor-islakligi-dudaklarinin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can davası', 'can-davasi-zafer-zengin-etnika-vgct4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'urfalı

bir kızı anlatmıştım sana

hani aşk için 

kaybolmuştu

adı gülo

bugün onu buldular

üzülme diye dedim

korkacak bişey yok

sevdasının koynunda vurdular

al almış gözleri

vuranlar anlattılar

can davasına

kan davası kattılar

| insan olmadan birsey olamadılar |

bir de kancık kadın varmış

o ispiyonlamış

öyle anlattılar

10 Temmuz 2004 '' Hani aşk ölmezdi ''

**şiirimi okumak için alan ve başkalarına verip yayınlatan o insana ithaf olunur', 'urfalı bir kızı anlatmıştım sana hani aşk için  kaybolmuştu adı gülo bugün onu buldular üzülme diye dedim korkacak bişey yok sevdasının koyn...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/can-davasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüme yürüyüş uzun sürüyordu', 'olume-yuruyus-uzun-suruyordu-gencay-coskun-7qjd5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yılların yorgunluğunda 

Sirke gibi tortu bırakıyordum 

Bal rengi akşamlar 

Yaşıyordum 

Yaşayamadıklarım 

Yaşatamadıklarım geliyordu 

Aklıma 

Yutkunuyordum 

Susuzluğumu dindirecek

Garip yağmurlar 

Yağsın istiyordum 

Dünyevi pirelerle

Top yekun savaşıyordum 

Girmediğim hiçbir ini kalmamıştı

Ama onlar hala kan emmeye 

Devam ediyordu 

Sokak lambalarında 

Yaşlanıyordum 

Bu meretler 

Gece feci gözümü alıyordu 

İçim acıyordu 

Yalnızdı yürek 

Kelimelerini anlamadığım 

Cümleleri uzun şarkılar çalardı 

Kendi iç seslerimde 

Ölüme yürüyüş uzun sürüyordu 

Yürümekten topuklarım çatlamıştı 

Durmak hiç yoktu 

İşin ucu en büyük sevgiliydi 

Bekletmek olmazdı 

Metalar arasında kaybolmuş bir yaşamı

Yaşatılmaktansa 

Kendi dünyamda 

İçten içe yaşamak 

Daha doğru 

Daha onurluydu 

Dar geliyordu 

Çoktan aşılmış yolları 

Tekrar etmekten sıkılmıştım 

Sonu belli bir filmdi hayat 

Gidişatı çok sıkıyordu beni 

Acı dolu 

Sarı sabır yoluydu

Camlı dikenli yolumda

Sadece sonbaharlar vardı 

Her sonbaharda 

Yalnız çiğdemler çiçek açardı 

Ağlardım 

Son gelen ışığa 

Uzanan bakışları vardı 

Sarı çiğdemlerin 

Ellerimi hatırlatan 

Bir yapısı vardı 

Uzayıp giden yolumda 

Çok hücrem 

İsyandaydı 

Acımasızca 

Kırıyordu beni 

Kendimle

Çıkartıyordu 

Beni benden 

Hızla içimi boşaltılıyordu 

Kansere dönüyordum

Elimde okeyim vardı 

Koyacak gedik bulamamıştım

Ölüme yürüyüş uzun sürüyordu

Sürüldüğüm kasabalardan geçerken 

Dinlenmek bile istemiyordum.

Her geçtiğim yer 

Benimle beraber tanıdık geliyordu 

Kaybolmak istiyordum 

Yaban olmak istiyordum 

Av mevsimi geldiğinde 

Vurulmak için 

Deli esen asi bir rüzgara 

Savrulmak vardı 

Soğuk ama çok soğuk kutuplara 

Hiçbir sesin olmadığı 

Yalnız diyarlarıma gömülmeye gidiyordum 

Tek bir görüntünün olmadığı 

Tek bir ıslığın olmadığı 

Yalnızlığın imparatorluğuna gidiyordum 

Gözlerim dolu dolu 

Oluyordu 

Yaşamı bozanları 

Kumlara boğamadan 

Kulluk fabrikalarının 

Patronlarını tiplerini benzetmeden gidiyordum 

Ölüme yürüyüş uzun sürüyordu

Sıkılıp durmak istediğim 

Kaç istasyon oldu 

Yola çıkılmıştı bir kere 

Onurluca bitirilmesi gerekiyordu 

Gözüme bakan gözler

Yüreğimi ısıtan sözler 

Tenimi terleten tenler 

Çok uzaktaydı bana

Veremli bir hastalıktı gibiydi 

Yalnızlık

Bulaştırma ihtimalim yüksekti 

Ölüme yürüyüş uzun sürüyordu

Asla hiç bitmeyecek gibi değildi', 'Yılların yorgunluğunda  Sirke gibi tortu bırakıyordum  Bal rengi akşamlar  Yaşıyordum  Yaşayamadıklarım  Yaşatamadıklarım geliyordu  Aklıma ...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":102,"source_url":"https://www.antoloji.com/olume-yuruyus-uzun-suruyordu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dogum gunun', 'dogum-gunun-orhan-balta-p6ua8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seher yeli,

hos bir ruzgar,

dag basinda bir adam.

gun dogumu kizil ates,

DOGUM GUNUN.

bir devri alem..

Bir turku,,

yasanmamislara,,,,

aciyi bal eyledik...

Bir feryat 

yasanmislara.

Ah ulan ahhh..

ya sevdadan yana,,

yada ayriliklardaki hasrete,

belkide  uzak ulkedeki yalnizliklara

kolunda kelepce..boynunda zincir..

DOGUM GUNUN

Ne yazik

gece sarhoslugu

koynunda ten kokusu

burnunda kan,

gozunde kin.

beden senin degil sahipsiz! 

sen seni bilmiyorsun..

bildigin intikam

kim icin..niye? 

Duzmece cevaplarin anlamsiz

yoksullugun isyanin.

Dusuncelerin,

,dusuncelerindeki katillikler..

olduruslerin,

olduruslerinin gercegi,

var olusun,

var olusundaki sir,

sessizligin.

Susma desem bir ise yararmi? 

susmanin kime ne faydasi olmuski..

susanlar ne kazanmis,

 yada kazanc dedigin ne? 

DOGUM GUNUN

Ne gomuyorsun bedenini topraga? 

zaten topraktan yaratilmadinmi? 

donusun bir avuc cukur degilmi? 

Geride biraktiklarinin mirasimi,

yasanmamislarindaki  yikinti..! 

Bir dag basi..

Bir ruzgar..

Ruzgarda kor ates..

kor atesten bir sevda.

yakar yuregini ince ince

 zamani geldigince.

.DOGUM GUNUN.

..KUTLU OSLUN..

O.Balta   dokuz temmuz..ikibindort', 'Seher yeli, hos bir ruzgar, dag basinda bir adam. gun dogumu kizil ates, DOGUM GUNUN. bir devri alem.. Bir turku,, yasanmamislara,,,, aciyi ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Balta']::text[], 8.5, '{"poet":"Orhan Balta","poet_slug":"orhan-balta","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/dogum-gunun-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidemem..', 'gidemem-tulay-eker-c8klk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ayrı düşmek canevimden,

Kahreder beni yüreğimden.

Kaburgamın arasında ustura,

Mahşeri bir sabahın alnında

Yatarım en uzak ufkun yanına

Gidemem...

Sensiz bir adım öteye

Tökezlenir yüreğim,örselenirim.

Mavzerler patlar içimde,biterim.

Dökülür matemimden hüzünler

Dişlerim arasında martı sesini gizler.

Bu yürek bu can sensizliği neyler..

Sana uzaktan bakayım yeter.

Ayrılığa gem vurur da

Gözlerim, yollarda kalır.

Bilmeyen ayrılığı bu kadar

Kolay mı sanır? 

Gel...gel sevdiğim..

Sabrım olsun ecelim

Harran ovası olsun üstüne 

Serildiğim..

Gözlerinin baharında

Süngüleneyim..

Gel...gel yeter ki

Güneşin saçlarında

Tutuşsun kimliğim.

^^Mah Gül''de,Gül Sende,Sevdan(m)   Yürekte^^....', 'Ayrı düşmek canevimden, Kahreder beni yüreğimden. Kaburgamın arasında ustura, Mahşeri bir sabahın alnında Yatarım en uzak ufkun yanına Gidem...', ARRAY['Türk Edebiyatı','Şiir','Tülay Eker']::text[], 8.5, '{"poet":"Tülay Eker","poet_slug":"tulay-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gidemem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Umdum Ne Buldum-1-', 'ne-umdum-ne-buldum-1-bayram-tunca-1mxzc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün yine âlî makamdan bir davetiye aldım

Davete icabet etmek için hayallere daldım

Dün bunca sene çalışmamın ödülünü aldım

Ölüm fermanı gibi iş fesih tebligatını aldım

Ah umardım ki bir cani kadar değer verileyim

En azından sanıksam, sanık gibi yargılanayım

Suçluysam boynum kıldan incedir diyebileyim

Gıyabımda verilen fermanı nasıl kabulleneyim

B. Tunca/11.04.1999-11.04', 'Dün yine âlî makamdan bir davetiye aldım Davete icabet etmek için hayallere daldım Dün bunca sene çalışmamın ödülünü aldım Ölüm fermanı gibi...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ne-umdum-ne-buldum-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütünleme', 'butunleme-turgay-kaygi-bh7c7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ne yapacağımızı bilmiyorduk

ellerimizde birer sigara

birbirimize bakıp gülümsüyorduk

serseri serseri yolları arşınlarken

tesadüfen rastlaşmış

iki eski dost gibiydik ikimiz; 

aynadaki suretim ve ben...

birimiz falcı imiş birimiz

kahin

esasında biz kimiz

iki kendinden habersiz yabancı...

geçmişimizi yadedip geleceğimizi

bekliyorduk

birimizin gözüne kestirdiği nokta

diğerimizin en geride bıraktığı yer idi; 

geçmişimizi geleceğimize ekliyorduk...

birimizinkinin biteceği yerde başlayacaktı

diğerinin gailesi

birer kadeh parlatalım dediydik

şerefe tokuştururken kadehleri

birimiz kırılıverdik

kalanımız bütün

gece ağladı durdu...

(inegöl,  29.06.2004)', 'ne yapacağımızı bilmiyorduk ellerimizde birer sigara birbirimize bakıp gülümsüyorduk serseri serseri yolları arşınlarken tesadüfen rastlaşmı...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kaygı']::text[], 8.5, '{"poet":"Turgay Kaygı","poet_slug":"turgay-kaygi","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/butunleme-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alo beyaz masa görevde', 'alo-beyaz-masa-gorevde-can-i-rfan-dpumb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şu işe bak 

Geçenlerde 

Dörtleri yaktım

Asla park yapılmaza park yaptım

Tabi görünce makbuzu ön camda 

Ödedim hemen cezayı biranda

Gördüm ki 

Daha sonra park yaptırıyor görevli orada

Kırmızıda geçirip yeşilde durduruyor birde

Allak bullak oldu  trafik

Allak bulak oldu kafam

Karışık…

Ah, ah! 

 iyi ki de varsın be ışık… 

İyi ki de varsın be levha….

Çağa bak be 

Çağa’

Robotlar falan derken

Şimdide 

Yeni çıktı

Alo beyaz masa… 

Görevli de olmazsa 

Bu iş tam tıkırında…

Çok şükür 

Çok şükür

Çalışan bir

Alo beyaz masamızda 

Var artık…', 'Şu işe bak  Geçenlerde  Dörtleri yaktım Asla park yapılmaza park yaptım Tabi görünce makbuzu ön camda  Ödedim hemen cezayı biranda Gördüm ki...', ARRAY['Türk Edebiyatı','Şiir','Can İrfan']::text[], 8.5, '{"poet":"Can İrfan","poet_slug":"can-i-rfan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/alo-beyaz-masa-gorevde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanıyorum', 'yaniyorum-i-smet-barlioglu-07sj8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne biçim yanıyorum, yüreğim alev alev,

Sensiz geçen her günüm bağrımda hançer gibi.

Özlem sanki çevremi dört yandan saran bir dev,

Tutuşup yanıyorum kendimden geçer gibi.

Her geçen gün içimden birşeyler eksiliyor,

Gün geçtikçe elemler daha bir yükleniyor,

Bir azaptır içime gelip çörekleniyor,

Aşkın sanki kalbimde yaralar açar gibi.

Yüreğim bir kuş uçmaz kervan geçmez han oldu,

Herşey boş ve anlamsız, hayatım zindan oldu,

Boş bir sevda uğruna bedenim candan oldu,

Hangi dala tutunsam elimden kaçar g,bi.

Yolunu bekliyorum bomboş kalmış yollarda,

Ne kalbimde takat var, ne de mecal kollarda,

Varlığım masal oldu nice yaban illerde,

Gerçeklerim tüm serap, düşlerim naçar gibi.

(ISLAK RÜZGARLAR isimli hece şiirlerinden > 38-39/100)', 'Ne biçim yanıyorum, yüreğim alev alev, Sensiz geçen her günüm bağrımda hançer gibi. Özlem sanki çevremi dört yandan saran bir dev, Tutuşup y...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yaniyorum-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayağı Kırılmış Soba Misali! ...', 'ayagi-kirilmis-soba-misali-hulya-topcuoglu-7csrq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Atmışlar tavan arasına, unutmuşlar

Bir zamanlar, soğukta üşüyen ellerini

O ısıtmamış gibi...

Üzerinde kestane pişirdikleri,

Gülüşerek yedikleri,

Sıcaklığında seviştikleri günleri

Unutmuşlar...

Aşkları da bitmiş yabancılar şimdi

Yalnızlıkla üşüyorlar,

Bir zamanlar mutluluklarının şahidi,

Tavan arasına attıkları 

Ayağı kırılmış soba misali....', 'Atmışlar tavan arasına, unutmuşlar Bir zamanlar, soğukta üşüyen ellerini O ısıtmamış gibi... Üzerinde kestane pişirdikleri, Gülüşerek yedikl...', ARRAY['Türk Edebiyatı','Şiir','Hülya Topçuoğlu']::text[], 8.5, '{"poet":"Hülya Topçuoğlu","poet_slug":"hulya-topcuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ayagi-kirilmis-soba-misali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Sahiller', 'sensiz-sahiller-i-smet-barlioglu-k50ni', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sensiz sahillerde güneş batıyor,

Sensizlik canıma yetti, yetiyor,

Gecikme, gel artık; ömür bitiyor,

Sanmam geldiğinde bulacağını.

Ne kumun tadı var, ne sahillerin,

Mazimiz tutsağı tüm gölgelerin,

İçimdeki yaram derin mi derin,

Kalbim artık oldu olacağını.

Dallar soyunuyor, yaprak döküyor,

Sensiz gecelerde şafak sökmüyor,

Islanan gözlerim artık görmüyor,

Nasıl olsa görmüş göreceğini.

Yüreğim tedirgin, ruhum hüzünlü,

Ruhum özlemlere mahkum hükümlü,

Bilmem ki yaşamam artık mümkün mü,

Sanmam elemlerin biteceğini.

(ISLAK RÜZGARLAR isimli hece şiirlerinden > 40-41/100)', 'Sensiz sahillerde güneş batıyor, Sensizlik canıma yetti, yetiyor, Gecikme, gel artık; ömür bitiyor, Sanmam geldiğinde bulacağını. Ne kumun t...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sensiz-sahiller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'II/Zaman', 'ii-zaman-ali-gencay-el91j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kırdım saatin zembereğini,

Zamana uyup bana isyan ediyor,

Akrep,yelkovan isyankar,

Dur dediğim yerde durmuyor

Zaman… 

En güzel anda bir kez dur, 

Dur Allah aşkına

Yırtıyorsun sayfamı,

Yavaş yavaş,boydan boya

Bir yarısında ben, 

Diğer yarısında o,

Hak mı bu yaşanılana

Zaman…

Durduracağım seni

İzin yok ayrılığa

Yok artık tahammülüm

Yok razılığım,

yok oluşlara….', 'Kırdım saatin zembereğini, Zamana uyup bana isyan ediyor, Akrep,yelkovan isyankar, Dur dediğim yerde durmuyor Zaman…  En güzel anda bir kez ...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ii-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Güzel Günleri Gel de Özleme', 'o-guzel-gunleri-gel-de-ozleme-i-smet-barlioglu-ql35g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Rüzgarı dinlerdik ocak başında,

Aklımız denizin haykırışında,

Alevler yansırdı her bakışında,

O güzel günleri gel de özleme.

Elin elimdeydi körpe ve sıcak,

Kalbim ellerinde yandı yanacak,

Ocağa ne hacet; gönlümüz ocak,

O güzel günleri gel de özleme.

Camlarda serçeler ateşe hasret,

Parlak alevlerle dağılmış kasvet,

Çile de neymiş ki? Ne demekmiş dert? 

O güzel günleri gel de özleme.

Sende benim gönlüm, bende seninki,

Sen Leyla, ben ise Mecnun, inan ki,

Kolların boynumda gül dalı sanki,

O güzel günleri gel de özleme.

Dışarda karakış hüküm sürüyor,

Sevgin canevime doğru yürüyor,

Sevda bizle doğmuş, bizle büyüyor,

O güzel günleri gel de özleme.

Kar sanki bir perde penceremizde,

Kahkaha oyuncak ellerimizde,

Bir gençlik masalı dillerimizde

O güzel günleri gel de özleme.

(ISLAK RÜZGARLAR isimli hece şiirlerinden > 42-43/100)', 'Rüzgarı dinlerdik ocak başında, Aklımız denizin haykırışında, Alevler yansırdı her bakışında, O güzel günleri gel de özleme. Elin elimdeydi ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/o-guzel-gunleri-gel-de-ozleme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Yolculuk...!', 'son-yolculuk-hasan-basri-kale-xopia', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ne var kalan

geçmişten

elimizde / avucumuzda

ister dostun olsun

istersen düşman kazan

unutma..

dünya senin olsa da..

sevgin / m,

sevenlerin

eşlik edecek sadece

son yolculuğun(m) da....! 

*Bakî Kalan Bu Kubbede Bir Hoş Sadâ İmiş..!', 'ne var kalan geçmişten elimizde / avucumuzda ister dostun olsun istersen düşman kazan unutma.. dünya senin olsa da.. sevgin / m, sevenlerin ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/son-yolculuk-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram Gibi', 'bayram-gibi-i-smet-barlioglu-vhuda', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen bir gül ki açsın güller,

Alkışlasın bütün eller,

Ne dert kalsın, ne çileler,

Olsun hayat bayram gibi.

Yamaçlarda oturalım,

Binbir hayaller kuralım,

Şarkıdır ki tutturalım,

Olsun hayat bayram gibi.

Güneş vursun yüzümüze,

Kuşlar konsun dizimize

İmrensinler yazımıza

Olsun hayat bayram gibi.

İsteyeyim seni senden,

Sen isterken beni benden,

Tek bir elem göstermeden,

Olsun hayat bayram gibi.

Izdırabın ne tadı var? 

Sadece bir feryadı var,

Mutluluğun kanadı var,

Olsun hayat bayram gibi.

(ISLAK RÜZGARLAR isimli hece şiirlerinden > 44-45/100)', 'Sen bir gül ki açsın güller, Alkışlasın bütün eller, Ne dert kalsın, ne çileler, Olsun hayat bayram gibi. Yamaçlarda oturalım, Binbir hayall...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bayram-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağrım Demir, Gönlüm Taş', 'bagrim-demir-gonlum-tas-i-smet-barlioglu-0nz6a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Izdıraptan, çileden artık korkum kalmadı,

Çile çektim yıllarca, çilem hiç azalmadı,

Kalbim öyle yandı ki; külhan öyle yanmadı,

Ben alıştım çileye; bağrım demir, gönlüm taş.

Başından biliyordum çekeceğim çileyi,

Zaten göze almıştım ağlayıp inlemeyi

Asla yadırgamadım Mecnun ''a benzemeyi,

Ben alıştım çileye; bağrım demir, gönlüm taş.

Artık kalbim çileye bana mısın demiyor,

Razı olmuş haline, usul usul inliyor,

Bütün bunlara rağmen yine seni seviyor,

Ben alıştım çileye; bağrım demir, gönlüm taş.

İsterse aşkın olsun bana yeni bir elem,

Kabul edip çekerim, hiç asla irdelemem,

Zira, senden gayrıyı istesem de sevemem,

Ben alıştım çileye; bağrım demir, gönlüm taş.

(ISLAK RÜZGARLAR isimli hece şiirlerinden > 46-47/100)', 'Izdıraptan, çileden artık korkum kalmadı, Çile çektim yıllarca, çilem hiç azalmadı, Kalbim öyle yandı ki; külhan öyle yanmadı, Ben alıştım ç...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bagrim-demir-gonlum-tas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** Mavi Gezegenin Kızı...', 'mavi-gezegenin-kizi-abir-zaki-wcrg7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çöküp dizlerimin üstüne

seyrettim kristal küreyi

duyulmamış, görülmemiş

kuvvetli çığlıklar

sesli sesli konuşmalar

uzun ve derin bir koydaki

iskeleyi altına çekiyordu 

berrak mı berrak sular…

aktı damarlarımdan 

asırlarca yaşlı kanlar

bir bir geçiyordu içimden

mutluluk ve acı 

gerçek ve yalan 

güneş ve yağmur dolu

yaşanmış her bir canlar, her bir anlar...

terkedilişler, mücadeleler

ve sevinçler şerit şerit çıktılar

yeniden dirilişimin döl yatağından

nefes almalarına cevaz vermeden

geride bırakıyorlardı bir bir yılları

saçlarımın gür gür büyüdüğü yerlerden

bana inat gösteriyorlardı sanki 

içdünyamın en gizemli yerlerini

benim hiç gösteremediğim

gülüşlerimdeki güneş doğumlarını

ruhumdaki dişiliğimin zerafetini

ve yüreğimin kuğu kuşundan bineğini…

göze alınmış risklerin

burukluğunu taşıyorum yüreğimde

leke leke duruyor yaşlar yüzümde

meydan okuyarak seçtiğim yollarda

ölüme mahkum bir suçluyum

yada 

tescillenmiş

tutuklanmış

ve

iyileştirilmis bir deli-divaneyim...

şimdi,

ben bir suç isem,

dua etmelisin bana

sözcüklerimin nefesinden çıkacak

sesime ulaşabilmen için

kollarının açılımı kadar uzağım sana ….

Çeviren:  M.  Çelik         

9/7/2004

***************************************************************************************

DAUGHTER of the earth... 

as I lay down on my knee 

I stare into the crystal 

limpid water beneath the dock 

of a deep bay 

crying with strength 

speaking the voice 

unheard for so long… 

through my veins 

run the blood of ages 

for every life has been lived 

filled with pleasure and pain 

truth and lies 

sunshine and rain… 

from the womb of my rebirth 

many quits, fights and joys 

have been shredded 

held not allowing to breathe 

through passing years 

where my hair outgrows 

showing my inner mystery 

when the sun of my smile 

the grace of my style 

and the ride of my breast 

couldn’t been seen… 

hearts sour for the risks taken 

tears stain my face 

for the path I dare to take 

am I a deceased 

a crime… 

or an insane 

committed, arrested, and healed…. 

But again, 

if I am a sin, 

pray for me 

for the voice you want to reclaim 

through the breath of my words 

is within the reach of your arms… 

July 6, 2004', 'Çöküp dizlerimin üstüne seyrettim kristal küreyi duyulmamış, görülmemiş kuvvetli çığlıklar sesli sesli konuşmalar uzun ve derin bir koydaki ...', ARRAY['Türk Edebiyatı','Şiir','Abir Zaki']::text[], 8.5, '{"poet":"Abir Zaki","poet_slug":"abir-zaki","theme":"Türk Şiiri","is_hero":false,"total_lines":85,"source_url":"https://www.antoloji.com/mavi-gezegenin-kizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Kumrular', 'beyaz-kumrular-i-smet-barlioglu-o056e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir selam gönderdim, getirdiler mi? 

Seni sevdiğimi söylediler mi? 

Sana yandığımı ilettiler mi

O mahzun bakışlı beyaz kumrular? 

Gözlerim yaşarsa yanımda onlar,

Hıçkırıp durmamı seyrediyorlar,

Üzülüp duruyor, bekleşiyorlar

O mahzun bakışlı beyaz kumrular.

Anlayan bir onlar dertten, çileden,

Onlar anlıyorlar bu hasretlerden,

Çünkü yalnız onlar durup dem çeken,

O mahzun bakışlı beyaz kumrular.

Her gün geliyorlar seni görmeye,

Benim selamımla sevindirmeye,

Ondan konuyorlar o pencereye

O mahzun bakışlı beyaz kumrular.

Onlardır avutan garip gönlümü,

Onlardır gösteren sana yolumu,

Onları beklerim akşam oldumu,

O mahzun bakışlı beyaz kumrular.

(ISLAK RÜZGARLAR isimli hece şiirlerinden > 48-49/100)', 'Bir selam gönderdim, getirdiler mi?  Seni sevdiğimi söylediler mi?  Sana yandığımı ilettiler mi O mahzun bakışlı beyaz kumrular?  Gözlerim y...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/beyaz-kumrular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevindim', 'sevindim-zafer-zengin-etnika-jyazi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yanındaydım

Sabahtı

birde

Sen

Uzanmış

yatarken

Ben

baş 

ucunda

Saçlarını

okşuyordum

| Kapattım gözlerimi |

Mutluluk

gibi

birşeydi

Özlemişim

seninle

olmayı

Çocuksun

Diyor/dun/ya

Büyüdüm mü yoksa

Saçlarında

Gülümsedin

Ben taaaaaa

yanından 

sevindim

| Ne kadar uzak bu şehirler

  Sanki bir birine küsler |

Sırası geldi kaşlarının... 

10 Temmuz 2004 “ düşünmek “', 'Yanındaydım Sabahtı birde Sen Uzanmış yatarken Ben baş  ucunda Saçlarını okşuyordum | Kapattım gözlerimi | Mutluluk gibi birşeydi Özlemişim ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sevindim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bilmece', 'bir-bilmece-tahir-bingol-yx3j3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnceden ince bir yol alır

ve kesik çizgiler

Duvar yazıların

Yanık bir türkünün ezgilerinde saklı

Mınnacık yüzlü Yusuf''un 

Gözlerinde

Ellerinde

ve bir tutamlık saçlarında

bir Dünya saklı

Bizler öylesine sevdik

ve öptük gözlerinden mevsimsiz sonbaharları

Ve yıldızları koynumuzda büyüttük 

Okşadık saçlarından 

Ninnilerinde büyüdük koca dağların

ve sevdamız vardı dünyalar kadar güzel 

ve dost gülücükler

ve sıcacık 

öpercesine

Yırtık ve silik defterlerin

bilinmezliğinde 

sır gibi.....

öylesine bir bilmece işte...', 'İnceden ince bir yol alır ve kesik çizgiler Duvar yazıların Yanık bir türkünün ezgilerinde saklı Mınnacık yüzlü Yusuf''un  Gözlerinde Ellerin...', ARRAY['Türk Edebiyatı','Şiir','Tahir Bingöl']::text[], 8.5, '{"poet":"Tahir Bingöl","poet_slug":"tahir-bingol","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-bilmece-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamı Anlamlı Kılan Keşif Turu.', 'yasami-anlamli-kilan-kesif-turu-necmi-unsal-l5wva', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu hayat sırtlara usulca dokunan kutlu kumaş.

Gemiler meçhul bir limana  yanaşır, yavaş yavaş.

Hayalin, varlığın, umudun aslında, hayat bir sır.

Zerreden kürreye bir ölçü, onsuz bu âlem kısır.

Hayat yollardaki imlerle anlamlı, dingin kalıp.

Gözlere bu güzel seyirler  neşve, bir mana dalıp.

Puslu göz, hayata atılan her ilmeği  farketmez.

İbretler görür de, inatla süflî yoldan çark etmez.

Bilinmez ki bu maraton  kat edilir kaç nefeste.

Ne kadar kalır  ruh bedende, bu et kemik  kafeste.

Yaşamı anlamlı kılan şey, kutlu bir keşif turu.

Onu bulamayan ruhlar bir dal, bir odun; kupkuru.

21 Nisan 2004 Çarşamba, Danimarka-Køge 00.46

6+3+7', 'Bu hayat sırtlara usulca dokunan kutlu kumaş. Gemiler meçhul bir limana  yanaşır, yavaş yavaş. Hayalin, varlığın, umudun aslında, hayat bir ...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yasami-anlamli-kilan-kesif-turu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık Harfler', 'kirik-harfler-gulten-ornek-5iek9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kim bilebilirdi

Varoluşun yalınayak ve vahşi olduğunu

Oysa siz

Çağları ayartıp

Sabrı bir çöplüğe akıttınız

Ellerimizde

Üç heceli bedenler kurup

Binlerce ruh fısıldadınız kulaklara

Korkunç muydu

Sefil miydi

Dahi miydi harfleriniz

Hatırlıyorum

Masalarınız sudan

Sandalyeleriniz kireçtendi

Duvarsızdınız

Uçan kapılarınız

Konuşan pencereleriniz vardı

Boğulan ve yakılan

Sınırsız bir boşlukta

İsis’in yarım kalan yasıyla anılıyor isminiz

Geride 

Kuş yağmurları yağıyor

Yırtık ışıklar sızıyor dizlerime

Ve en kötüsü

Tanrılarınız güneşi çalmak üzere', 'Kim bilebilirdi Varoluşun yalınayak ve vahşi olduğunu Oysa siz Çağları ayartıp Sabrı bir çöplüğe akıttınız Ellerimizde Üç heceli bedenler ku...', ARRAY['Türk Edebiyatı','Şiir','Gülten Örnek']::text[], 8.5, '{"poet":"Gülten Örnek","poet_slug":"gulten-ornek","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kirik-harfler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin iki gözüm...', 'neredesin-iki-gozum-yusuf-ziya-leblebici-ro9qr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni andım bu gece de

Her zaman ki huyum gibi

Sana yandım bu gece de

Her zaman ki suyum gibi

Ekmeğimi şarabıma

Bandırıp da bal alırken

Şişeleri gırtlağıma

Dayayıp da zom olurken

Neredesin iki gözüm

Neredesin öbür yüzüm

Ateşini sen verirsin

Yüreğimi hasret yakar

Çeşmesine sen değersin

Gözlerimden yaşlar akar

Geceleri sana serdim

Kapı açık gelmiyorsun

Saatleri sana verdim

Ne haldeyim bilmiyorsun

Neredesin iki gözüm

Neredesin öbür yüzüm', 'Seni andım bu gece de Her zaman ki huyum gibi Sana yandım bu gece de Her zaman ki suyum gibi Ekmeğimi şarabıma Bandırıp da bal alırken Şişel...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/neredesin-iki-gozum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi ordan hadi heri...', 'hadi-ordan-hadi-heri-yusuf-ziya-leblebici-xmnig', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biri yerken biri bakar

Komşu tokken o aç yatar

Elhamdüllah müslümanız

Gözümüzden yaşlar akar

Hadi ordan hadi heri

Büzük mide soyuk deri

Er meydanı bura yeri

İnsanlığa gelin beri

Zemin direk orta direk

Garibana ne giydirek

Küfür etme çarpılırsın

Dindarız ya nere gidek

Hadi ordan hadi heri

Çukur olmuş şu gözleri

Dolmuyor ki mideleri

İnsanlığa gelin beri

Olmuyor ki bütçe delik

Veremeyiz bir metelik

Adalet var kalkınma var

Maaşımız kaç ekmeklik

Hadi ordan hadi heri

Pantolonda yok cepleri

Konuşamaz yok dilleri

İnsanlığa gelin beri', 'Biri yerken biri bakar Komşu tokken o aç yatar Elhamdüllah müslümanız Gözümüzden yaşlar akar Hadi ordan hadi heri Büzük mide soyuk deri Er m...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hadi-ordan-hadi-heri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrı Zamanları Buluşturan An', 'ayri-zamanlari-bulusturan-an-ozkan-yildirim-7ab58', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kırk  yıl kadar önce

Okşarken usulcacık vapuru

Ellerin yanmıştı Nazım,üsümüştün

Anarak Nazım usta`yı

Ayak bastım Varna`ya,toprak sıcaktı.

Kırk yıl kadar sonra

Yüregim yandı Varna`da

Nazım usta, ısındınmı molada

Düşerim yollara  sessizce yine

Şimdi,ayrılıklarda yaşanır sevda



     Varna/1993', 'Kırk  yıl kadar önce Okşarken usulcacık vapuru Ellerin yanmıştı Nazım,üsümüştün Anarak Nazım usta`yı Ayak bastım Varna`ya,toprak sıcaktı. Kı...', ARRAY['Türk Edebiyatı','Şiir','Özkan Yıldırım']::text[], 8.5, '{"poet":"Özkan Yıldırım","poet_slug":"ozkan-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ayri-zamanlari-bulusturan-an-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece', 'bu-gece-mustafa-tanrikulu-eaa8a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Boğazım sık, bir kemend ol bu gece 

Gözlerim ol, yaş ile dol bu gece

Bilmesin kimse senin sırrını hiç

Akıver gönlüme ol sel bu gece

İstemem gitme yanımdan bir ân

Haydi çöz zülfünü de kal bu gece

Sahra-yı aşka düşen ben gibisin

Al da çölden çöle sen sal bu gece

Mustafâ bilmede kadrini senin 

Sen yeter ki  ona bir gül bu gece', 'Boğazım sık, bir kemend ol bu gece  Gözlerim ol, yaş ile dol bu gece Bilmesin kimse senin sırrını hiç Akıver gönlüme ol sel bu gece İstemem ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tanrıkulu']::text[], 8.5, '{"poet":"Mustafa Tanrıkulu","poet_slug":"mustafa-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bu-gece-86-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman sıfır Mekan sabit', 'zaman-sifir-mekan-sabit-nilsu-sari-7nv4i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir mum olsam 

Yanıp erisem 

Aksam aksamda durmak olmasa 

Eriyip sığsam bir oluğa 

Doğsam da gözelerden 

Bağam sırtımda 

Bir kaplumbağa olsam 

Mekan sormasa zaman 

Olsam da Çiçek olsam 

Bu evren vazosunda 

En tatlı sulara susadıkça 

Deyişse suyum 

Değişse huyum 

Hayat kalmayınca 

Sabitleşse bu savrulmalar 

Ne fark eder ha bağa ha toprak 

Ve koparak her şeyden yaprak yaprak 

Sabitleşse zaman 

Sabitleşse mekan 

Hislerin büyülü sislerinde –sessizce 

Lolan''a teşekkürlerle', 'Bir mum olsam  Yanıp erisem  Aksam aksamda durmak olmasa  Eriyip sığsam bir oluğa  Doğsam da gözelerden  Bağam sırtımda  Bir kaplumbağa olsa...', ARRAY['Türk Edebiyatı','Şiir','Nilsu Sarı']::text[], 8.5, '{"poet":"Nilsu Sarı","poet_slug":"nilsu-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/zaman-sifir-mekan-sabit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şu Dağların Ardında', 'su-daglarin-ardinda-abdulkadir-ogdum-ocx3f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen, madeni keşifsiz hicranların kâşifi; 

Neydi gâyen, aslını bilmeden sınardın da? 

Söylenirler; olmuşsun sevdalıların şefi,

Sen ki, derûnî seven kulları kınardın da! 

...............Gittiler bir günahın suyuna banmak için,

...............Yittiler yüzerlerken, geceye kanmak için,

...............Ses verdin de buldular seni, yıkanmak için

...............Ne diye esirgedin suyunu, pınardın da? 

Ellerin... Gelincikler solmuşken Yaz ellerin,

Dalların arka çıkmaz, sibel tutmaz ellerin...

Hangi makamda titrer şu sayrı gazellerin? 

Sen ki, ab-ı hayatı şürbetmiş çınardın da! 

...............Hilkati bu şiirin; gâh haykırır gâh meler! 

...............Aynı çatı altında yazık, lime limeler! 

...............Bitti kafiye, redif... Nanayda kelimeler,

...............Şairi mi sordunuz? Şu dağların ardında...', 'Sen, madeni keşifsiz hicranların kâşifi;  Neydi gâyen, aslını bilmeden sınardın da?  Söylenirler; olmuşsun sevdalıların şefi, Sen ki, derûnî...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Öğdüm']::text[], 8.5, '{"poet":"Abdulkadir Öğdüm","poet_slug":"abdulkadir-ogdum","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/su-daglarin-ardinda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünden..Bugüne...', 'dunden-bugune-nazife-abayli-b44d8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıllar önce gezdim dolaştım,

Şehrinin en ücra köşelerini,

Dümdüz caddelerini.

..........................................

Üzüm topladım bağlarından,

Kirazlarını,

Çağlalarını tattım ağaçlarından.

Hele o ışkınların burukluğu,

Halen gitmedi dilimden,damağımdan..

.......................................................

Sabah oldu mu kuzuların meleyişlerini,

Balkonumda ötüşen kuşların dillenişini,

Müzik kutumda çalan köy türkülerinin ezgilerini,

Tertemiz havasına katık eder,

İçime çekerdim..

.....................................................

Biten günün ardından,

Batan güneşe gülümser,

Hiç bir şeyi dert etmezdim..

....................................................

Acı nedir,ayrılık nedir bilmezdim ki o zamanlar..

Şen şakrak,cıvıl cıvıldım.

Kahkahalar atar yaşama,

Sevgi yayardım..

.........................................

Küçücük şehrinin erkekleri,

Gözümün içine bakarlardı da,aldırmazdım..

Kıskanan da olurdu,yadırgayan da,

Umursamazdım...

................................

İnsanını,toprağını,

Dağlarını,çağlayanını,

Daracık sokaklarını da çok severdim ha...

...................................................

Bilseydim yıllar sonra,

Seni çok uzaklarda bulacağımı,

Şehrinin bağlarından,

Hiç ayrılmazdım...', 'Yıllar önce gezdim dolaştım, Şehrinin en ücra köşelerini, Dümdüz caddelerini. .......................................... Üzüm topladım bağla...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/dunden-bugune-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dipsiz Bir Sonbahar', 'dipsiz-bir-sonbahar-umit-murat-sen-ke4ms', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ölüm kadar yalındı her şey 

Ve şiir kadar kafiyeli 

Ellerin kadar yarımdı aşkın 

Yarım ve kinayeli... 

Belki bundandır 

Dipsiz bir sonbahar oluşum 

Bundandır ürkekliğim, 

Çıkıp çıkıp kaybolmuşluğum... 

Hadi çıkar beni 

Sakladığın kuytulardan... 

Seni bekliyorum, 

Durma çağır beni 

Uyandır artık uykularımdan! ..', 'Ölüm kadar yalındı her şey  Ve şiir kadar kafiyeli  Ellerin kadar yarımdı aşkın  Yarım ve kinayeli...  Belki bundandır  Dipsiz bir sonbahar ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Murat Şen']::text[], 8.5, '{"poet":"Ümit Murat Şen","poet_slug":"umit-murat-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dipsiz-bir-sonbahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost', 'dost-umit-murat-sen-rswbg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eski bi dostun selamı 

Bu yüzümdeki gülücük 

Yılların unutulmamış vefası 

Sefası bu küçücük gülücük 

Ömrümün hak ettiği... 

Kaybedilen yıllarıma üzülmüyorum artık... 

Kaybettikçe kendimi buluyorum yavaş yavaş... 

Öğrendim artık 

Ne bir savaş 

Ne bir komedya 

Bu hayat denilen kıvırım; 

Tatlıca bir telaş; 

Bir gülüşün berraklığı; 

Kalemin alın yazısı... 

Gerisi, 

Karın ağrısı...', 'Eski bi dostun selamı  Bu yüzümdeki gülücük  Yılların unutulmamış vefası  Sefası bu küçücük gülücük  Ömrümün hak ettiği...  Kaybedilen yılla...', ARRAY['Türk Edebiyatı','Şiir','Ümit Murat Şen']::text[], 8.5, '{"poet":"Ümit Murat Şen","poet_slug":"umit-murat-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dost-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda', 'elveda-umit-murat-sen-c9048', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ensemde ölümün öpücüğü 

Tüylerim diken diken 

Karanlık bir kaldırımın bomboş ayak sesleri 

Yüreğimde bir vicdansızın ihaneti... 

Gözlerimi gözlerine diktim ölümün 

Kaçıyor köşe bucak benden 

Hayat tutmuyor şimdi ellerimden 

Kaşları çatık kaldı ömrümün 

Beni sorma artık sevgili 

Yerimi söylemem artık sana 

Arama beni bulman imkansız 

Sana son kez elveda', 'Ensemde ölümün öpücüğü  Tüylerim diken diken  Karanlık bir kaldırımın bomboş ayak sesleri  Yüreğimde bir vicdansızın ihaneti...  Gözlerimi g...', ARRAY['Türk Edebiyatı','Şiir','Ümit Murat Şen']::text[], 8.5, '{"poet":"Ümit Murat Şen","poet_slug":"umit-murat-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/elveda-102-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Hayat', 'ey-hayat-umit-murat-sen-qgs15', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Değişiveriyorum her şeyi 

Bir dost gülücüğüne.. 

Vazgeçiyorum üşümüşlüğümden 

Yağan yağmur serilince üstüme... 

Bir deniz görmeyivereyim 

Yüreğim gemilerin yelkenlerinde... 

Ey hayat; 

Al beni sar yüreğine... 

Seni seviyorum... 

Seni seviyorum....', 'Değişiveriyorum her şeyi  Bir dost gülücüğüne..  Vazgeçiyorum üşümüşlüğümden  Yağan yağmur serilince üstüme...  Bir deniz görmeyivereyim  Yü...', ARRAY['Türk Edebiyatı','Şiir','Ümit Murat Şen']::text[], 8.5, '{"poet":"Ümit Murat Şen","poet_slug":"umit-murat-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ey-hayat-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Faiziyle Yaşamak', 'faiziyle-yasamak-umit-murat-sen-pfm3g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayatımın yarısını ''nasılsınlara'' 

Diğer yarısını da ''çok şükür Allah''a'' yatırdım 

Ve 

Faiziyle 

İdare edip gidiyorum...', 'Hayatımın yarısını ''nasılsınlara''  Diğer yarısını da ''çok şükür Allah''a'' yatırdım  Ve  Faiziyle  İdare edip gidiyorum......', ARRAY['Türk Edebiyatı','Şiir','Ümit Murat Şen']::text[], 8.5, '{"poet":"Ümit Murat Şen","poet_slug":"umit-murat-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/faiziyle-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gayr - î İntiharî', 'gayr-i-ntihar-umit-murat-sen-oypi0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Vuruyor gözüne yalnızlığının, 

Cuvarasından çekiyor, 

Bi daha vuruyor... 

Vuruyor, 

Vuruyor, 

Vuruyor... 

Geziyor gözünde yalnızlığın, 

Silahını çekiyor, 

Vuruyor, 

Vuruyor, 

Vuruyor... 

Gez göz arpacık derken, 

Vuruyor yalnızlığını, 

Ölüm bakıyor gözlerinden...', 'Vuruyor gözüne yalnızlığının,  Cuvarasından çekiyor,  Bi daha vuruyor...  Vuruyor,  Vuruyor,  Vuruyor...  Geziyor gözünde yalnızlığın,  Sila...', ARRAY['Türk Edebiyatı','Şiir','Ümit Murat Şen']::text[], 8.5, '{"poet":"Ümit Murat Şen","poet_slug":"umit-murat-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gayr-i-intihari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmişli Şiir', 'gecmisli-siir-umit-murat-sen-vxrvu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Üstüme çok gelir oldu, 

Karanlık ve suçlu geçmişim.. 

Geçmişim hâyâllerden; 

Mutluluk arıyorum köşe bucak; 

Boşuna.. 

Onu çoktan geçmişim... 

Yolunda gitmiyor işlerim bu mevsim 

Bu mevsim önüme geçmiş kadersizliğim, 

Zamansızlığım önüme geçmiş.. 

Bunlar da yetmezmiş gibi, 

Yüreğin yüreğimden geçmiş... 

Geriye baktım da şöyle bir, 

Aradan ne çok zaman geçmiş.. 

Ey aldanmış ruhum, 

Ey benim zavallım, 

Sana da geçmiş olsun, geçmiş..', 'Üstüme çok gelir oldu,  Karanlık ve suçlu geçmişim..  Geçmişim hâyâllerden;  Mutluluk arıyorum köşe bucak;  Boşuna..  Onu çoktan geçmişim......', ARRAY['Türk Edebiyatı','Şiir','Ümit Murat Şen']::text[], 8.5, '{"poet":"Ümit Murat Şen","poet_slug":"umit-murat-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gecmisli-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Griban Şiir', 'griban-siir-umit-murat-sen-q27g6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Grip oldum, 

Bir güzel grip bulaştırıyorum gökyüzüne... 

Oh olsun sana gökyüzü, 

Beni böyle delirteceğine 

Bir şeyler giyseydin ya üstüne... 

Oh olsun sana gökyüzü oh olsun; 

Gribim ne zaman geçerse 

Sana da o zaman geçmiş olsun...', 'Grip oldum,  Bir güzel grip bulaştırıyorum gökyüzüne...  Oh olsun sana gökyüzü,  Beni böyle delirteceğine  Bir şeyler giyseydin ya üstüne......', ARRAY['Türk Edebiyatı','Şiir','Ümit Murat Şen']::text[], 8.5, '{"poet":"Ümit Murat Şen","poet_slug":"umit-murat-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/griban-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüşünü Değdir Dudaklarıma', 'gulusunu-degdir-dudaklarima-umit-murat-sen-myegd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gülüşünü değdir dudaklarıma hadi, 

Bak zamansızca seni bekliyorum... 

Bir bilsen, 

Yıllar kadar yorgunum... 

Hadi al yorgunluğumu 

Uyut biraz... 

Yollarca seni arıyorum, 

Gözlerim yola aşina 

Sana uzak... 

Hadi 

Al gözlerimi, 

Rahatlat biraz... 

Benden uzakta, beni düşünüyorsun; 

Beni sevmekten vazgeçmiyorsun, 

Hadi gel, 

Al kollarına da 

Sevin biraz...', 'Gülüşünü değdir dudaklarıma hadi,  Bak zamansızca seni bekliyorum...  Bir bilsen,  Yıllar kadar yorgunum...  Hadi al yorgunluğumu  Uyut bira...', ARRAY['Türk Edebiyatı','Şiir','Ümit Murat Şen']::text[], 8.5, '{"poet":"Ümit Murat Şen","poet_slug":"umit-murat-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gulusunu-degdir-dudaklarima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş Gibi', 'gunes-gibi-umit-murat-sen-l1v23', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yakamozumdan gemi geçti bir akşam, 

Dumanı kızıl ötesi, 

Gözleri benden mavi... 

Sabaha kadar şiirler fısıldadık birbirimize, 

Dalgalarımla dalga geçtik, 

Güldük eğlendik... 

Sabahında ne denizliğimi bıraktı, 

Ne gemiliği kaldı geride; 

Bir rüzgar geldi ansızın, 

Onu karaya çıkardı; 

Beni böyle gemisiz bıraktı... 

Ve ben ne zaman bir gemi görsem, 

O''dur diye umutlanırım... 

Boşuna... 

... 

Şimdi.. 

Güneş gibi yalnızım', 'Yakamozumdan gemi geçti bir akşam,  Dumanı kızıl ötesi,  Gözleri benden mavi...  Sabaha kadar şiirler fısıldadık birbirimize,  Dalgalarımla ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Murat Şen']::text[], 8.5, '{"poet":"Ümit Murat Şen","poet_slug":"umit-murat-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gunes-gibi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Payı', 'kara-payi-umit-murat-sen-1o1al', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Denizin ortasına çadır kurdum; 

Anasını satıyorum anakaranın... 

''Alın! '' diyorum, 

''Ne yaparsınız yapın! ..'' 

Temkini elden bırakmıyorum 

Yeniden bağırıyorum; 

''Yine de fazla doldurmayın! ! ! 

Olur ya geri dönersem; 

Birazda bana yer bırakın...''', 'Denizin ortasına çadır kurdum;  Anasını satıyorum anakaranın...  ''Alın! '' diyorum,  ''Ne yaparsınız yapın! ..''  Temkini elden bırakmıyorum  Y...', ARRAY['Türk Edebiyatı','Şiir','Ümit Murat Şen']::text[], 8.5, '{"poet":"Ümit Murat Şen","poet_slug":"umit-murat-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kara-payi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Aşklar Atlası', 'kayip-asklar-atlasi-umit-murat-sen-eeqg1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Senin gözlerinde basım hatası, 

Benim gözlerimde aşkın saf ağrısı, 

Dönüp dönüp kayboluyoruz 

Aramızda labirent bir aşk haritası...', 'Senin gözlerinde basım hatası,  Benim gözlerimde aşkın saf ağrısı,  Dönüp dönüp kayboluyoruz  Aramızda labirent bir aşk haritası......', ARRAY['Türk Edebiyatı','Şiir','Ümit Murat Şen']::text[], 8.5, '{"poet":"Ümit Murat Şen","poet_slug":"umit-murat-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kayip-asklar-atlasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köklü Şiir', 'koklu-siir-umit-murat-sen-bjazp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yeni yeni anlamlar katıyorum bilmediğim şeylere, 

Kelimelerin köküne dalıyorum; 

Köklü köklü yazılar yazıyorum; 

Sonra köklü sayılar aklıma geliyor, 

İğreniyorum... 

Yeni yeni anlamlar sokuyorum ceplerime, 

Cebimi delip düşüyorlar gözlerinin içine; 

Gözlerinin içi, yusuf kuyusu; 

İçine girdikçe çıkamıyorum! ... 

Ne bir anlam değer kazanıyor, 

Ne köklü sayılar, 

Oturup köklü köksüz düşünüyorum... 

Vay anasını, 

Daralıyorum...', 'Yeni yeni anlamlar katıyorum bilmediğim şeylere,  Kelimelerin köküne dalıyorum;  Köklü köklü yazılar yazıyorum;  Sonra köklü sayılar aklıma ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Murat Şen']::text[], 8.5, '{"poet":"Ümit Murat Şen","poet_slug":"umit-murat-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/koklu-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zi.../', 'zi-mehmet-fatih-u6pt9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ve susukun günlüğümden bir vehim geçer

-ölüm

hayatımın büyüklendiği/yüklendiği andır

.

.

Uygarlık ve medeniyet yolunda bir adamın

elleri hiç umursamadan kanlanır

/iş bu hal''de/

anlamını yitirmiş herşey gibi yaşamdan

siperinde uyuklayan bir miğfer kalır

çaresi dudağında saklıdır tarihin-ama yine de-

kahredilir, ağlanır...

.

.

.

Ütopyaların, yağmurların ve coğrafyaların arasından

afişlenmeye götürülür bir gün/bir gül

/ah 

garip endüljans

-baba, oğul ve kutsallığını çoktan kaybetmiş herşey adına

beni hangi iklimin kara cehenneminden kurtaracaksınız/

kimse siyahı temizlemeye kalkışmaz oysa

/zi

zen gibidir 

ucu bucağı belirsiz teslimiyet öğretisi

sahip, köle, anti-sosyal tarihsel devinimler

ve zi

zen gibidir dedim

bir dolu sual-cevap gerisi/

. 

.

.

Siz

yaşayan pedagoji''nin çocukları

toprağı ayakkabılarınızın içinde hissetmelisiniz

çünki ve özellikle

ütopyaların-kimliksiz ideolojilerin-ortasından bir gün

afişlenmeye/fişlenmeye götürülebilirsiniz

/^^ve elleri hiç umursamadan kanlanır^^dedim

aşşağılık soyutlaştırmaların bir ürünü olarak

insan 

toprağa ölür isteksizce.../

''''dem''''



Mehmet Fatih 

.', 'Ve susukun günlüğümden bir vehim geçer -ölüm hayatımın büyüklendiği/yüklendiği andır . . Uygarlık ve medeniyet yolunda bir adamın elleri hiç...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih']::text[], 8.5, '{"poet":"Mehmet Fatih","poet_slug":"mehmet-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/zi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mapus Mapus Yalnızlık', 'mapus-mapus-yalnizlik-umit-murat-sen-saqrz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mapus mapus başıma damlıyor yalnızlık 

Yüreğimde bir vefasızın bıçak yarası 

Dahası 

Hüznün ve gururun safrası... 

Gözlerimde nemli bir hafta sonu 

Kaderimde 

Yıkımların,felaketlerin enflasyonu 

Bilmiyorum ne yapmalı, 

Ne etmeli... 

Bari sen tutaydın ya ellerimden 

Orhan Veli..........', 'Mapus mapus başıma damlıyor yalnızlık  Yüreğimde bir vefasızın bıçak yarası  Dahası  Hüznün ve gururun safrası...  Gözlerimde nemli bir haft...', ARRAY['Türk Edebiyatı','Şiir','Ümit Murat Şen']::text[], 8.5, '{"poet":"Ümit Murat Şen","poet_slug":"umit-murat-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mapus-mapus-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mart Ayı Dert Ayı', 'mart-ayi-dert-ayi-umit-murat-sen-px267', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir acayip bakıyor bugünlerde, 

Üstüme üstüme geliyor; 

Öyle ki, 

Bazan beni korkutuyor.. 

Olmayacak, 

Sanırım orucu bende bozacak; 

Boş bir anımı bulsa 

Beni bir kerede harcayacak.. 

Kedim, 

Bilirsin seni severim; 

''Mart''ı bahane edip de 

Üstüme üstüme gelirsen; 

Çok ciddiyim; 

Kapı dışarı ederim..', 'Bir acayip bakıyor bugünlerde,  Üstüme üstüme geliyor;  Öyle ki,  Bazan beni korkutuyor..  Olmayacak,  Sanırım orucu bende bozacak;  Boş bir...', ARRAY['Türk Edebiyatı','Şiir','Ümit Murat Şen']::text[], 8.5, '{"poet":"Ümit Murat Şen","poet_slug":"umit-murat-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/mart-ayi-dert-ayi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Temmuz Ateşi...', 'temmuz-atesi-i-brahim-ethem-bingul-yqlcb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gece aydınlık kalır sensizliğin yanında

Kor ateşler,alevler bir yangındır içimde

Hicran olur dökülür hasretin yüreğime

İsmim dudaklarında anılırken yaşarım

Temmuz gecelerinde mehtap olup göğümde

Akdeniz sahilinin akşam serinliğinde

Ruhunun beni saran mutlu sakinliğinde

Alemleri dolaşır,dünyaları aşarım

Yar yolunda yorulan,sevgiliye yük olur

Yari güzel olanın derdi de büyük olur

Rüzgarını bulmayan her ateş sönük olur

Vuslatını tatmazsam inan yoktur baharım

Sende senin olmazsam,neye yarar bu canım

www.iebingul.com', 'Gece aydınlık kalır sensizliğin yanında Kor ateşler,alevler bir yangındır içimde Hicran olur dökülür hasretin yüreğime İsmim dudaklarında an...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/temmuz-atesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yennar', 'yennar-mehmet-fatih-ij5i5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yeşeren hayallerde

günleri sayılıdır yennar matemlerinin

bir özge sevgiliye katar ellerini

ırmaklar

inkarcı bir güldür

-solmaya durur bakışlar...-

/ve ıtri den

kürdili-hicazkar bir muamma başlar/

Gün geçer

dem tutar kuytusu hasretlerin

en geniş/ve en basit/zamanlarda şiir

tarihin dudaklarında sevişir

bir mecnun unutulmuş mazisine güler

gözyaşlarıyla

ve umulur ki

soy vermeye devam eder ağaçlar...

''''dem''den..'''' 

Mehmet Fatih 

.', 'Yeşeren hayallerde günleri sayılıdır yennar matemlerinin bir özge sevgiliye katar ellerini ırmaklar inkarcı bir güldür -solmaya durur bakışl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih']::text[], 8.5, '{"poet":"Mehmet Fatih","poet_slug":"mehmet-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yennar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Bir Umut', 'mavi-bir-umut-umit-murat-sen-392te', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gün ağarıyor penceremde; 

Gözlerimde uykusuzluğun külleri, 

Midemde eski bir şarabın rutubeti, 

Tipik yalnızlık senfonileri... 

Nasıl avutmalı gönlümü, 

Bilmem ki ne demeli... 

''Boşver'' diyorum, 

''Gün yeniden doğuyor, 

Masmavi umutlarla bezeli...''', 'Gün ağarıyor penceremde;  Gözlerimde uykusuzluğun külleri,  Midemde eski bir şarabın rutubeti,  Tipik yalnızlık senfonileri...  Nasıl avutma...', ARRAY['Türk Edebiyatı','Şiir','Ümit Murat Şen']::text[], 8.5, '{"poet":"Ümit Murat Şen","poet_slug":"umit-murat-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mavi-bir-umut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nokta', 'nokta-umit-murat-sen-o7utv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Oturdum; 

Nescafe ve sigara keyfi yapıyorum, 

Seni düşünüp seni yazıyorum bir yandan da; 

Kulaklığımda Rum türküleri bezeli, 

Deli deli özlemişim besbelli ellerini.. 

Al gözlerimi de uyut biraz koynunda; 

Göster onlara göremediğim gözlerini... 

..''m benim, 

..''ların en güzeli 

Gel ansızın gecelerime; 

Yalnız bırakma düşlerimi...', 'Oturdum;  Nescafe ve sigara keyfi yapıyorum,  Seni düşünüp seni yazıyorum bir yandan da;  Kulaklığımda Rum türküleri bezeli,  Deli deli özle...', ARRAY['Türk Edebiyatı','Şiir','Ümit Murat Şen']::text[], 8.5, '{"poet":"Ümit Murat Şen","poet_slug":"umit-murat-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/nokta-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unum/Eleğim', 'unum-elegim-mehmet-fatih-e0qu6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Unumu asmışım

eleğim toprakta

bir küçücük/bir ufacık ormanım ben

yeşilim

dallarımdan kervansaraylar kurulur

; 

Oyunlarım 

beceri dışı yanımdır

gecekondular uzanır boylu boyunca

şehrim

böyle bir şehirdir

Hapse düşmedim hiç

dayak yemedim/ekmek yedim

düşünmedim daha

çocuktum

unutmadım

çünki unumu asmıştım

eleğim tel tel istanbul

ve gözlerim

ilk onsekiz yaşımın depreminde

.

.

çok ötelerimde savaş gördüm

nasıl olduysa bana da dokundu

kanatları

ölümü

çok yakınımda,

sabahın suretimdeki yansımasında buldu annem

sarıldı bana

babam sarıldı

.

.

kim ki

köprüyü erken geçmiştir

ununu erken asmıştır

/eleği topraktadır

ve gömleğinde biraz kan lekesi/

öğrendim...

ZEYL; 

gezdim

dört iklim, dört memleket

ve henüz dört yaşındaydı kardeşim

devrimin en cesurunu taşıyordu avuçlarında

''''sıcacık bir kalp''''

çünki eleği yoktu, savaşı yoktu

mevsimleri bir körebeye 

sürgün etmiş dualarıyla

biz nereye gitsek geliyordu....

16 may 2003



Mehmet Fatih 

.', 'Unumu asmışım eleğim toprakta bir küçücük/bir ufacık ormanım ben yeşilim dallarımdan kervansaraylar kurulur ;  Oyunlarım  beceri dışı yanımd...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih']::text[], 8.5, '{"poet":"Mehmet Fatih","poet_slug":"mehmet-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/unum-elegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tepki', 'tepki-mehmet-fatih-r8tbp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karanlıksa da korkmuyorum geceden

yoldaşlığım siyahi bir ülkedir bana

Yaşamaksa bunun adı yaşamdan saymıyorum

yaşamak

eylemimle bütünleşmiş bir ilkedir bana

Sevdaysa; 

adını değiştirmeli güneşin

yanmalı, utanmalı

anla ki közleşmemiş sevdalar

bilincini yitirmiş bir öfkedir bana

Susmaksa

kusura bakma 

artık susamam

çünki susmak en beklenmedik tehlikedir bana', 'Karanlıksa da korkmuyorum geceden yoldaşlığım siyahi bir ülkedir bana Yaşamaksa bunun adı yaşamdan saymıyorum yaşamak eylemimle bütünleşmiş ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih']::text[], 8.5, '{"poet":"Mehmet Fatih","poet_slug":"mehmet-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/tepki-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sual', 'sual-mehmet-fatih-7fgsh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Cevabını alamasam da soracağım ey hayat; 

yıldızları nerede bu şehrin

ve iklimleri üç ayda bir değişirken ülkemin

/üç ayda bir/

ben de değişmek zorundamıyım? 

2.

Ruhumun nadasını biriktiriyorum gizlice

evet bir gün

kendimden bile saklanacağım...

3.

Önce

hep birkaç gün yağmur yağar

ve hep önce başkaları ağlar düşlerime

oysa kırılması çok zor camlara benzese de kalbim

alakasız bir sevda için ağlayabilirim.

4.gün

Hayalimde bir saksı çiçeği büyütmeyi isterdim

/ismi önemli değil/

büyütemediğim üç küçük kedi yavrusuna inat hemde

olmadı

olmayan bir çok yanılışıma saydım

ve şimdi

küçük parantezler açmadan susmak için yaşayacağım...



Mehmet Fatih 

.', 'Cevabını alamasam da soracağım ey hayat;  yıldızları nerede bu şehrin ve iklimleri üç ayda bir değişirken ülkemin /üç ayda bir/ ben de değiş...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih']::text[], 8.5, '{"poet":"Mehmet Fatih","poet_slug":"mehmet-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sual-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazdıklarım', 'yazdiklarim-zafer-zengin-etnika-jfajo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çocuğun

şiir

okuması

gibi 

yazdıklarım

Öyle

küçük

seslerim

| Mırıldanma belki |

Şiiri

onların

gözüyle

severim

Küçükken

büyükmüş

bu

filozoflar

D i n l e r i  m...

10 Temmuz 2004 '' açık kapılar ''', 'Çocuğun şiir okuması gibi  yazdıklarım Öyle küçük seslerim | Mırıldanma belki | Şiiri onların gözüyle severim Küçükken büyükmüş bu filozofla...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yazdiklarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevzi Sağanak Yalnızlık...', 'mevzi-saganak-yalnizlik-hulya-topcuoglu-jm49z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüreğimin havası bozdu yine 

Kara bulutlar kapladı mavilikleri

Semalarında şimşekler çakıyor 

Mevzi sağanak yalnızlık yağıyor

Dindirmek ne mümkün, yürekteki fırtınayı

Esti geçti sensizlik rüzgarları 

Ne bir sevgi, ne bir özlem, ne bir sen kaldı 

Mevzi sağanak yalnızlıkla yıkandı...', 'Yüreğimin havası bozdu yine  Kara bulutlar kapladı mavilikleri Semalarında şimşekler çakıyor  Mevzi sağanak yalnızlık yağıyor Dindirmek ne m...', ARRAY['Türk Edebiyatı','Şiir','Hülya Topçuoğlu']::text[], 8.5, '{"poet":"Hülya Topçuoğlu","poet_slug":"hulya-topcuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mevzi-saganak-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-gokhan-kirman-pz93t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dalgalar sessizliğini bozduğunda gel,

Deniz bağışlamasını bilir sen ilk  baharda gel.

Gönlüm bulutlar gibi kabarmış senin sevginle,

Sen gece karanlık basmadan,

Seni düşünerek geçen gecelerimde,

Işığım olmak için ışığını saçarak gel.

Gökten bir melek inip gözyaşlarımı sildiğinde,

Sende yaralarımı sarmak için gel! ..', 'Dalgalar sessizliğini bozduğunda gel, Deniz bağışlamasını bilir sen ilk  baharda gel. Gönlüm bulutlar gibi kabarmış senin sevginle, Sen gece...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Kirman']::text[], 8.5, '{"poet":"Gökhan Kirman","poet_slug":"gokhan-kirman","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gel-107-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Rapsodi', 'sevda-rapsodi-mehmet-fatih-a328z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Saklama gözlerinde biriken rüyaları

ruhun esir olmasın esrarlı bir uykuya

ardında bir çöl kalır, farkına varamazsın

sen zarif bakışlarla dalıp giderken suya

İlmeği palazlanmış bir cellat gibi gece

ikimizi de boğar hayal denen nehirde

sen oturup gözyaşı döksen de bulutlara

ben şiirler yazarım çok uzak bir şehirde

Direnir sabır taşım, uzadıkça karanlık

şafağa şavkı düşmüş garip bir umut besler

eriyen her damlada zaman kendini bulur

ve güneşi müjdeler kulağımdaki sesler

Sabahına kavuşmuş karanfil gibi sen de

utanma, ufka çevir ay parçası yüzünü

aydınlık bir gün daha görebilmeyi dile

unutarak acıyı, hasreti ve hüzünü...



Mehmet Fatih 

.', 'Saklama gözlerinde biriken rüyaları ruhun esir olmasın esrarlı bir uykuya ardında bir çöl kalır, farkına varamazsın sen zarif bakışlarla dal...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih']::text[], 8.5, '{"poet":"Mehmet Fatih","poet_slug":"mehmet-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevda-rapsodi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günlerden Bu Gün Yine', 'gunlerden-bu-gun-yine-ciselerken-yagmurlar-allb4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Günlerden bu gün yine

İçimde anlatamadıklarım var

Anlatamayıp içimde sakladıklarım

Çıkar bizi burdan diye çığlık çığlığa

Ama ne varki müebbet yemişler öylesine hükümsüz

Sorgu sual yok! 

Kapanmış kapılar ardı ardına

Kilit kilit üstüne vurulmuş

Kimseden habersiz çürüyüp eriyip  gitsinler diye

Aslında kimse görmek istememiş onları

Kendi hallerinde kabullenmek için

Hiç kimse bilmek bile istememiş

Kendi inandıklarına ters olmasın diye

Günlerden siyah

Günlerden karanlık

Günlerden bu gün.....', 'Günlerden bu gün yine İçimde anlatamadıklarım var Anlatamayıp içimde sakladıklarım Çıkar bizi burdan diye çığlık çığlığa Ama ne varki müebbe...', ARRAY['Türk Edebiyatı','Şiir','Çiselerken Yağmurlar']::text[], 8.5, '{"poet":"Çiselerken Yağmurlar","poet_slug":"ciselerken-yagmurlar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gunlerden-bu-gun-yine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heraklıatus’un Nehrinde', 'herakliatus-un-nehrinde-yaser-yilmaz-nep3b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Erden harmanlamışsak sevdaları 

Benzi soluk anaların yüreğinde 

Ve bu yaz 

Savurmuşsak törenin yoz yüzünü ışık hızının küpüyle 

Toylaşır türkülerimiz 

Dönüşür haykırışa suskunluğumuz 

Herakleatus’un devinim nehrinde 

Boş ver Einstein’i 

E=MC kare, değil artık 

Mecali denktir vuruculuğuna sevdaların 

Esersen bir gün dümensiz 

Dönersen yüreğime kedersiz 

Göreceksin ki; bütün bildik formüller 

Artık, orada da geçersiz... 

(Adana NLP)

4.6.2004 /Adana', 'Erden harmanlamışsak sevdaları  Benzi soluk anaların yüreğinde  Ve bu yaz  Savurmuşsak törenin yoz yüzünü ışık hızının küpüyle  Toylaşır tür...', ARRAY['Türk Edebiyatı','Şiir','Yaser Yılmaz']::text[], 8.5, '{"poet":"Yaser Yılmaz","poet_slug":"yaser-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/herakliatus-un-nehrinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadık Dostum Yalnızlık', 'sadik-dostum-yalnizlik-osman-buku-5d4lg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Herkes bir dost arar kendine...

Çare umar dermanı bulunmaz derdine...

Dolaşır gönül bahçelerinde, takılır çıkar bendine... 

Dinler mi seni kimse saatlerce ağlarken...

Çözen bulunur mu,kalbin karaları sımsıkı bağlarken...

Kurtarır mı kimse boğulmadan yalnızlık nehri çağlarken...

Bir tas su veren olurmu çaresizlik içini  dağlarken...

Herkes bir dost arar kendine...

Bulamaz bir dost, misafir olur yalnızlık semtine...

Döner yine sadık dostu, kendi-kendine...', 'Herkes bir dost arar kendine... Çare umar dermanı bulunmaz derdine... Dolaşır gönül bahçelerinde, takılır çıkar bendine...  Dinler mi seni k...', ARRAY['Türk Edebiyatı','Şiir','Osman Bükü']::text[], 8.5, '{"poet":"Osman Bükü","poet_slug":"osman-buku","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sadik-dostum-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aça-69 (Syk-6c) - Düş''ten çıkış fakat böyle bir dualite''de kalış', 'aca-69-syk-6c-dus-ten-cikis-fakat-boyle-bir-dualite-de-kalis-akin-akca-qpjp6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir tek şey insanların kafasını bulandırıyor:

Ölüm; Fakat ben ölümsüzüm; 

(Sezebiliyorum, ölebilmeyi,

Ancak ''öl'' deyince, ölemiyorum)   

Yine de, olacak olan er geç yarına sarkacak -

Pek bir ihtiyaç bırakmadan zamana.

… Er geç var kalacak; böyle, var olacak! 

Sınıf farklılığında bekleyişin; 

Azim, irade demek değildir.

Veya benzetmez kendini bir balık, bir zırh’a; 

Veya sokmaz bir akrep, böyle bir zamanda; 

Çıkıyor bundan, tartışmalar! 

Baş aktörü, komedyanın; 

Uygulamaya şüpheyle yaklaşanıdır da; 

(Blake, Blake, duyuyor musun:

‘Şüpheler bile çocuğun saf kişiliğidir bazen’ -

Ama bu demek değildir ki, benim dediklerim … 

Değil, ‘Masumluk Kehanetleri’

-O vakit, kesin ayrımlar belirsizleşir)   

Şekil açısından ya da niceliksel, şiiri.

Aynen ve, yardımcı oyuncu şüpheyle yaklaşmaz; 

Ama ilham vericidir, yaklaşan için, şüphe ile! 

Bazen bir şüphe, geçen zamana benzer: 

Süreçlere, yol dönemeçlerine.

Ve kişi, dönemeci bulamadığında,

O vakit, hemen ve kolaylıkla yadırgayabilir; 

Tek biri’nde, bin bir şüpheyi! 

Ben yarattım seni, ama cevap veren bana oldun sen: 

Sen yarattın beni, ama cevap veren oldum sana ben! 

Ben yarattım seni, ama cevap veren bana oldun sen: 

Sen yarattın beni, ama cevap veren oldum sana ben! 

Öldüğünde, kalma: ilerle:

(Gitme!)   

Dileğim budur sana; 

Basitçe, seviyorum işte,

Senin kişiliğini, senin (tutkularına)      güzelliğine! 

Bilinçsiz olan ama, ‘timsah gözyaşları’ndan ‘su çıkartan-saflık’,

Yakınlaştır, görmek istiyorum biraz da, berraklık.:

Kan getirdi, has’lık, ‘kuklaların-kukla-tanrısı’nı astılar darağacına; 

Orada öylece sallana, kanaya ve tekrar berraklaşa! 

Yıldızlar üçüz,

Gökadalar beşiz,

Ve altıgen, salkım galaksiler:

Evren “bir balon, dışı’nın,

Anlamı olmayanı”nda; sonsuz! …

Görünce bunu, bazılarımız, kudururuz! ...

Söyleyenin semirtken lafı,

Geride kalanın, dönencesi bekleyen! 

Eller, işte kollardan uzayan eller; 

Savaş üretenler,

Barış törpüleyenler:

(Törpülerinde)      Bekleyişi hazmedenler! 

Fersiz olan göze, nur yok; 

Eğer ki, sen beslediysen onları! 

Fersiz olan göze, nur yok; 

Eğer ki, sen beslediysen onları:

Yaşamda bırakmak zordur ölümü:

Ölümsüzlüğü bahşedersin ölümün içinde,

Ve ölümü de, bir yaşamın içinde! 

-Ölümsüzlüğü, gerçek karanlıkları.

… Gören yüreğe ışık var; 

Eğer ki, sen beslediysen onları! 

Fakat döndüğümüzde yüzümüzü, 

(Tutkularına)      güzelliğine, senin kişiliğinin:

Kolayca denilebilir ki, yine de:

‘Eğer ki, sen beslediysen onları! 

Fersiz olan göze, nur yok! ’

Fakat yine yaratırsan bir mucize:

‘Gören yüreğe ışık var; 

Eğer ki, sen beslediysen onları! ’

Burası ‘Vortex Four’ ve ben Arthur Frayn

Ben de bir tanrıyım: uçan-taş-tanrı Zardoz’um; 

Kuklaların tanrısıyım ve kukla tanrıyım

Eğlence endüstrisindeyim:

İlk gündü, onla tanıştığım; 

Bu lafları, farklı bir dil ile ona söylemiştim:

Geçen üç senenin sonunda üç asır devrildi

Üç yüz ayrılığın hepsini de kendi içimde yaşadım -

Seni, senin içinde (ses -hakkıyla- veremedim)   

Ve ben şimdi karanlıkların sessizinde -

Amacını kaybetmiş olan, ‘soluksuz-bir vampir’im:

Su-Yer Kulesi’nin:

“Dağların zirvesi-karanlığı özütü-envai çiçekleri”nin 

Ve “gür ormanları’nın gölgesinin”

Ve o “dağlar”ın

Ve “Yılbaşı sevinci, resim merakı”nın

Ve o “hülyalı buzdan-rüya mavi’nin -‘orman tutmuş olan”ında

(Ne karmaşa, ne de bir sadelik)   

Ve o “Üst ranzadaki çocukluk-sevinci”nin

Ve o “kar” ve “çiy”in ve “havadaki nem”in

Ve “yükselen hava”nın

Ve o “arızalı-küçük-Çin Seddi”nin -

Ki her şeyin suçlusu odur aslında

(Buz kulesi olurken Su-Yer Kulesi,

Aslında Buz Kulesi’ni kendi içine hapsetmişti!)   

-Çok! …çok ötesindeyim! ...

Ama hala, hani vardı ya: şu teleferiğin içindeyim:

Hareket halindeyim 

“Düş’ten çıkan” fakat ‘dualite’de, çok daha fazla bir sabitlendi -

Düş-sisleri aynıydı, onun karakteristiği; 

Fakat onun tarhı, ''

Düş''ün-karşılık gözetmeksizin icra edilen-bir-ihraç edilişi'':

Seslerin ''daha derinleştirdiği''; 

(Sislerin, daha derinleştirdiği- yerini)   

Çünkü yaptıklarının arkasındaydı.

-

“8, 9 & 10 Temmuz 2004” yansımaları

açıklama:

tarh: çıkarmak, atmak (osmanlıca hukuk terimi)

burdaki anlamıyla: çıkarılış''ı

Vortex Four (burgaç dört) :Zardoz filmindeki ölümsüzlerin yaşadığı, zararlı etkilerden arındırılmış, dünya''daki bir bölge

Arthur Frayn: Yine aynı filmde, uçan bir taş-kfanın içinde yaşayan, ara sıra gelip insanlara brbirlerini öldürmeleri için silah dağıtan bir tanrı rolünde

güzel günler dilerim', 'Bir tek şey insanların kafasını bulandırıyor: Ölüm; Fakat ben ölümsüzüm;  (Sezebiliyorum, ölebilmeyi, Ancak ''öl'' deyince, ölemiyorum)    Yin...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":113,"source_url":"https://www.antoloji.com/aca-69-syk-6c-dus-ten-cikis-fakat-boyle-bir-dualite-de-kalis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek Doldurup Gökkuşağına', 'dilek-doldurup-gokkusagina-kamil-aydemir-cj374', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dilek doldurdum gökkuşağına

sevgimi giyinmiş yarınları vereceğim kucağına

istanbul gibi aşınmış yanaklarımda

suretini bulduğum dudakların

yeniden yapılandırsın yüzümü

toplayıp zamanın dipsiz kuyularına atsın

bendeki hüznü

akdeniz gülüşlerine ektim kendimi

n’olursun soldurma beni

yaşamın dalından dökülürüm yaprak yaprak

her düşüşümde yaralanır

sevdiklerimizi koynuna verdiğimiz toprak

bir yanın karadeniz gibi kıpır kıpr

bir yanın ülkemin doğusu gibi kan ağlıyor

yakınımdaki uzaklıkların beni yaralıyor

gülücüklerini uzatınca bana

yüreğimde güneş dolanıyor

hayatta bir çeşit elek

ayıklar iyiyle kötüyü

az çıkar senin gibi melek

mutsuzluk firarısı ömrüme

hayatı(mı)   n ikramiyesi olarak

seni dilerim dilek

sensiz bomboş sokaklarım

ve ben yarım

hasretinde yarımağız yaşarım

koynunda hazır mı yerim

geleyim gecelerine

yıldızları tuvalımız yapalım

 mutluluk resimlerine

indikçe en derinlerine

merhaba derim yeni güzelliklerine

merhaba aşkım

merhaba bize gülecek yarına

itersen beni bu sevdanın uzağına

bil ki düşürürsün acıların tuzağına

oysa doldurup gökkuşağına

yarınları güzellikleriyle vermek istiyorum kucağına

hazanlar uğramasın kuş cenneti yanaklarına

ben martı gibi süzülürken dudaklarına

dilim sürter memelerin uçlarına

dudakların kıvrımından inerim

göbeğinin çukurundan seni içmeye

aşkın yüzü dönüktür sevişmeye

sahi saçların niye tutsak karanlığa

duyguların yalnızlığa

sevmekten hangi zarar gelmiş insanlığa

üşüyen ellerimle dokunsam sıcaklığına

mutlak beni taşır yarına

geç aynanın karşısına

iyice bak gözlerinin içine

gözbebeğinin birinde şeyh şamil

diğerinde atabarı oynamaktayım

umutlarımı ektim yüreğinin her köşesine

büyümesini beklemekteyim', 'dilek doldurdum gökkuşağına sevgimi giyinmiş yarınları vereceğim kucağına istanbul gibi aşınmış yanaklarımda suretini bulduğum dudakların ye...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/dilek-doldurup-gokkusagina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vur sazının teline', 'vur-sazinin-teline-seref-yildirim-4xpu4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yılların geçer bir gün gelirsen kendine

pişmanlıklarınla solmuş yanmış isen derdine

mutsuzluklar dolmuşsa saplanmışsa beynine

durma sende o zaman vur sazının teline

düzenbazlar haince kıymışlar da diline

zalimler kelepçeler takmışlar da eline

ağalar beyler bindiler sosyalistin beline

durma sende o zaman vur sazının teline

inanmayın canlarım sömürenler sözüne

akrep gibi sokarlar kanlar dolar gözüne

koydular emekcimi hayvanların yerine

durma sende o zaman vur sazının teline

ne mutlu her zaman devrimciyim diyene

inanın yakışmıyor patronlara sövene

fikrimizin amacı pişmanlıkla gelene

durma sende o zaman  vur sazının teline

kapıldım gidiyorum duyguların seline

verdiler ihtiyarı şu güzelim geline

kıydılar acımadan aşıkların kavline

durma sende o zaman vur sazının teline

yiğitlerim inmişler ovaların düzüne

kız, oğlan aşıklarım süzüm süzüm süzüle

her insan geçde olsa dönecektir özüne

durma sende o zaman vur sazının teline

dostlarım dizelerim kıymetini bilene

ömür boyu olacak saygılarım sevene

aydınlık beyinleri gönülleri gülene

durma sende o zaman vur sazının teline

10.07.2004

Şeref Yıldırım', 'yılların geçer bir gün gelirsen kendine pişmanlıklarınla solmuş yanmış isen derdine mutsuzluklar dolmuşsa saplanmışsa beynine durma sende o ...', ARRAY['Türk Edebiyatı','Şiir','Şeref Yıldırım']::text[], 8.5, '{"poet":"Şeref Yıldırım","poet_slug":"seref-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/vur-sazinin-teline-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçini Dök Avuçlarıma', 'i-cini-dok-avuclarima-nihat-tasdemir-jxsq7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Farkını elediysen zamanın,

Unutmak istiyorsan benliğini,

Nihayetindeysen parçalanışının,

Ve dibe çökmüşse yalnızlığın; 

Ansızın lamekan bir sevda sarar bedenini...

Sesin değmez olur artık umursamazlığa,

Elin tutamaz olur firari duyguları

Nasır tutar özlemlerin; 

Korkma! 

İçini dök avuçlarıma, hafiflersin.', 'Farkını elediysen zamanın, Unutmak istiyorsan benliğini, Nihayetindeysen parçalanışının, Ve dibe çökmüşse yalnızlığın;  Ansızın lamekan bir ...', ARRAY['Türk Edebiyatı','Şiir','Nihat Taşdemir']::text[], 8.5, '{"poet":"Nihat Taşdemir","poet_slug":"nihat-tasdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/icini-dok-avuclarima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rus Güzeli', 'rus-guzeli-mustafa-toga-jnp9p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Günlerden cumartesi 

Uzanmışım Kadınlar Denizi’ndeki kumsala 

Karşımda hayal meyal Samos adası. 

Yosunlu çakıl taşları yuvarlanıyor meltem rüzgârıyla 

Dalgalar vuruyor hafiften ayak uçlarıma, 

Çocuklar kumdan kaleler yapıyorlar tuzlu deniz sularıyla 

Güneş ve ucsuz bucaksız masmavi deniz. 

Birisinin başucumda gölgesi, 

Güneşimi çalıyor, rahatım bozuldu 

Manzaramı kapatıyorsun 

Stringli Rus güzeli. 

Plâj kalabalık, iğne atsan yere düşmez 

İnce endamı, lüle lüle sarı saçları 

Balık eti teniyle “ bir ben varım burda ” dercesine 

Süzülür önümde, 

Stringli Nataşa güzeli. 

Gözümü açar kaparım 

Halâ bronzlaşmak için, güneş yağı sürer 

Beyaz etli, mavi gözlü, onsekizlik, 

Rus güzeli. 

Olmaz ki. 

Burnumun ucuna kalçalarını dayayıp 

Böyle de, 

Durulmaz ki. 

14-07-2004 – Kuşadası / AYDIN', 'Günlerden cumartesi  Uzanmışım Kadınlar Denizi’ndeki kumsala  Karşımda hayal meyal Samos adası.  Yosunlu çakıl taşları yuvarlanıyor meltem r...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Toga']::text[], 8.5, '{"poet":"Mustafa Toga","poet_slug":"mustafa-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/rus-guzeli-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah! Dünya', 'ah-dunya-caglar-akarsu-9twrd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ah! Dünya

..

Düşündüm ki, insanlar dünyada,

Her an bir misafir,

Sen dünya,

İnsanoğluna, bin,bir tuzak,

Attığı adımda sonsuz uçurum.

...

Asırlardır kanımıza işlemiş,

Batının kültür ve medeniyeti,

Misyonerler cirit atar meydanlarda,

Televizyonlarda,paparaziler,

Esen bu fırtınada, yıkandı beyinler.

..

Şimdi, ufukta  dalgalanan,

Bayraklarda,masumluk gizli,

Güneşsiz bir sabah,

Aysız gece gibi,kainat,

Gaflet perdesine bürünmüş,

Kalpler ve ruhlar, ıstırap,

..

Her vaktin horozları,

Saat başı ayrı öterken,

Öz benliğin çürümeden,

Gel! artık kendine.

...Gel! ! 

..

2004-07-10

Çağlar Akarsu', 'Ah! Dünya .. Düşündüm ki, insanlar dünyada, Her an bir misafir, Sen dünya, İnsanoğluna, bin,bir tuzak, Attığı adımda sonsuz uçurum. ... Asır...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Akarsu']::text[], 8.5, '{"poet":"Cağlar Akarsu","poet_slug":"caglar-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ah-dunya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gibili istanbul bi de sen', 'gibili-istanbul-bi-de-sen-zafer-zengin-etnika-y24gb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çocuk...

sensizlikten

sonra

bile

Bu

koca

adam

Bu 

suskun

adam

Acılara

alışamadan

yürüyor

hala

Sen

sonra

gelmişsin

| Yüreğime gülmeyi

  öğretir misin |

Olur ya

Deniz

Bile

sevinir

buna

| Kibirin ulaşmadığı yerlere gidildi

  Ne söylenecekse düşünüldü

  Aşk söylendi

  Türkü söylendi

  Gül eklendi|

Özledim

seni

Sabahlar

gibi

İstanbul

Gibi

İstanbul da

Uçuyor

Gözlerim

M a r t ı l a r ı   g i b i ... 

| 10 temmuz 2004 |  “ İyi uykular içim “', 'Çocuk... sensizlikten sonra bile Bu koca adam Bu  suskun adam Acılara alışamadan yürüyor hala Sen sonra gelmişsin | Yüreğime gülmeyi   öğret...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/gibili-istanbul-bi-de-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bildiğim Halde', 'bildigim-halde-devran-ekmekcioglu-t1da5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Özür olsun sana Tanrım

Son söz olsun sana Allah ‘ım

Yine yemin bozdum bağlandım birine

Hem de heran gideceğini bildiğim halde

Yalvarıyorum tekrar sana çare bul bu derde

Yok mu buna bir ilaç? 

Yok mu herhangi bir yerde? 

Biliyorum belki herşey benim elimde 

Aklım almıyor bu olayı reddediyor

Ama onu istiyor kalbim de

Hepsinin aynı olduğunu bile bile

Seni seviyorum onun kokusu bile yetiyor diye

Lanet olsun diyorum 

O nefes alabildiğim heryerde

Ve bırakıp gitmek benim elimde 

Yine de başaramıyorum Allah ‘ım

Yenik bu beden bu aşka bu sevgiye

Eminim ki tekrar son söz ondan gelecek

Selamlar olsun beni sevmeyen sevgiliye...', 'Özür olsun sana Tanrım Son söz olsun sana Allah ‘ım Yine yemin bozdum bağlandım birine Hem de heran gideceğini bildiğim halde Yalvarıyorum t...', ARRAY['Türk Edebiyatı','Şiir','Devran Ekmekçioğlu']::text[], 8.5, '{"poet":"Devran Ekmekçioğlu","poet_slug":"devran-ekmekcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bildigim-halde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana ve Bana', 'sana-ve-bana-caglar-akarsu-9b2zd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana ve Bana

Bu gece,

...

Katlana bilir misin? ? 

...

Velhasıl uzayıp da giden,

Satırlarıma...

Bir yol gibi bitmez,

Aynı zaman da çekilmez,

O,hüzünlü yorgunluğumla; 

Yazacağım,

Daha doğrusu,imla yanlışları

Kelimelerin başıbozuk hali ile,

Yuvarlanan,saçılan  taşların,

Sırtımda  şaklayan  kırbaçların,

“ey şair,kalemi bir mızrak gibi,

  kullanacaksın”

Sözlerini şiar görerek,

Yazacağım,

..

Yeter! ..

Diye bir “not” bırakacaksın.

Yeter! 

..

2004-07-10

caglar akarsu', 'Sana ve Bana Bu gece, ... Katlana bilir misin? ?  ... Velhasıl uzayıp da giden, Satırlarıma... Bir yol gibi bitmez, Aynı zaman da çekilmez, ...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Akarsu']::text[], 8.5, '{"poet":"Cağlar Akarsu","poet_slug":"caglar-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sana-ve-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Yergi I', 'yergi-i-hasan-sakman-i11pj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O derin bakışların ardındaki

sırrı çözmeye vaktim olmadıysa

halkısın,

suçlu benim sevgili! 

Ademoğluyum,

göğüs kafesimde pervasızca vururum,

fırtına olurum,

iklimden iklime kudururum.

Suçlu benim sevgili,

sen sil gözyaşlarını! 

Yüreğinde birgünden fazla kalamadıysam

sebebi ruhumun utangaç yanı

Aşk! ...

Yüce aşk! 

Söyle,

Şimdi hangi güç söndürecek 

yüreğimdeki bu yangını.

Suçlu benim sevgili! 

ben resti kağıtları açmadan çekmişim.

Adına intihar demişler,

ne fark eder,

ben ki sen sevmiyorken beni,

seni yüreğimde büyütüp, beslemişim.

Acılar sevgili,

saf yüreklerde büyür,

saf yürekler yeşilsiz baharlarda! 

Aşk isimsiz bir vapurda 

biletsiz kaçak bir yolcu, 

ispiyon kokuyor ortalık. 

Deniz durgun vapur yorgun. 

Kıyıda barikat kurmuş duygusuz bir kalabalık.', 'O derin bakışların ardındaki sırrı çözmeye vaktim olmadıysa halkısın, suçlu benim sevgili!  Ademoğluyum, göğüs kafesimde pervasızca vururum,...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sakman']::text[], 8.5, '{"poet":"Hasan Sakman","poet_slug":"hasan-sakman","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yergi-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Yergi II', 'yergi-ii-hasan-sakman-kbmpp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kolay mı sanırsın sevgili,

bir sevgiyi dizelerle büyütüp beslemeyi,

notalara dokunmadan bestelemeyi...

Fotoğraflar...

Acımı en güzel onlar anlatır,

bir alsan ellerine sevgili,

ayalarına damla damla gözyaşı bırakır.

Yitirir bir çocuk ellerinden

babasının aldığı balonu,

üstelik uçurtması da terk-i diyar etmiştir.

Diyemez kendi kendine

suçlusu ben miyim bunların,

yoksa kaderin bir oyunu mu? 

Ağlar...

Ağlar ki ne ağlar,

kurur göz pınarları,

Yorulur...

Acılardan uçurtma yapılmıyor sevgili

bir Nevroz bayramında peşine takip uçurasın,

ya da peşine takılıp uçasın.

Yedi yaşın aklıyla da olsa 

semaya boşa bakılmıyor sevgili,

balonumdu o benim,

babam almıştı...

Ah bir bilsen yitirmek ne kadar acı,

sana yabancı bir lisanda 

yüreğimde derin bir sancı.', 'Kolay mı sanırsın sevgili, bir sevgiyi dizelerle büyütüp beslemeyi, notalara dokunmadan bestelemeyi... Fotoğraflar... Acımı en güzel onlar a...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sakman']::text[], 8.5, '{"poet":"Hasan Sakman","poet_slug":"hasan-sakman","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yergi-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmelisin...', 'bilmelisin-derin-deniz-njrnj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu yüz güzellik bir yanılsamadan ibaret

                                                        bilmelisin

Ne bakışların gerçek

Nede parıltıları

bir arada olmamız kaçınalmazdı

belki de gerçek

ama bu gerçek bizim değil

                                      bilmelisin...', 'Bu yüz güzellik bir yanılsamadan ibaret                                                         bilmelisin Ne bakışların gerçek Nede parıltı...', ARRAY['Türk Edebiyatı','Şiir','Derin Deniz']::text[], 8.5, '{"poet":"Derin Deniz","poet_slug":"derin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bilmelisin-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Sigaram', 'sen-ve-sigaram-hasan-dogan-0cjts', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerin akar; 

Sigaramın dumanından,

Güzelliğini çekerim 

İçime.

Seyrederim gözlerini, 

Durmadan.

Güzelliğin beni 

Bitirmedikçe...

                    

 Niğde-2000', 'Gözlerin akar;  Sigaramın dumanından, Güzelliğini çekerim  İçime. Seyrederim gözlerini,  Durmadan. Güzelliğin beni  Bitirmedikçe...         ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Doğan']::text[], 8.5, '{"poet":"Hasan Doğan","poet_slug":"hasan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sen-ve-sigaram-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Parçalandı Bir Yanım...', 'parcalandi-bir-yanim-derin-deniz-ded2o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir yanımı burada bu insanların

-yanına bıraktım-

Korktum,kendimi ele vermekten

Bir yanım çekip gitti

o karanlık ve ibret verici öykülere

Ama farkındayım her şeyin

Ne kadar çelişirsem kendimle

Ne kadar hissedersem parçalanmışlığımı

Aşk o kadar çok birikiyor içimde 

Aşk kuytuluğunda çaresiz bir kuyu

Karanlık öykülerin derinliğine baktıkça

Baktıkça

             Battıkça

Boğuldukça...', 'Bir yanımı burada bu insanların -yanına bıraktım- Korktum,kendimi ele vermekten Bir yanım çekip gitti o karanlık ve ibret verici öykülere Am...', ARRAY['Türk Edebiyatı','Şiir','Derin Deniz']::text[], 8.5, '{"poet":"Derin Deniz","poet_slug":"derin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/parcalandi-bir-yanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorumsuzdur! ...', 'yorumsuzdur-i-lyas-ozmen-javya', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir abimiz bizi anıp

Benzer çaylak kuşa demiş

Gayrı ondan şair olmaz

Uğraşmasın boşa demiş

Okunmuyor yazdıkları

Anlaşılmaz dedikleri

Hep rüyadır gördükleri

Yorsun hayra-düşe demiş

Mısra bilmez uyak bilmez

Hece bilmez ayak bilmez

Arada bir kıyak bilmez

Dönsün tekrar başa demiş

Ne sazı var ne okuyor

Olur olmaz can sıkıyor

Zülfiyare dokunuyor

Yemdir kurda kuşa demiş

(ÖNEMLİ NOT:Yukarıda bahsi geçen ''''abimiz'''' in 

 Antolojiyle alakası yoktur.)', 'Bir abimiz bizi anıp Benzer çaylak kuşa demiş Gayrı ondan şair olmaz Uğraşmasın boşa demiş Okunmuyor yazdıkları Anlaşılmaz dedikleri Hep rüy...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özmen']::text[], 8.5, '{"poet":"İlyas Özmen","poet_slug":"i-lyas-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yorumsuzdur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gören', 'goren-gokhan-oflazoglu-ee7t8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kıran, döken insanlar arasında

zihnimizde cinayetler işler

içimizde cesetlerle dolaşırız.

Ne tutuklanır ne yargılanırız,

günlük yaşayışımız düzen bulur,

biz rahatlamış, biraz daha katlanırız.

Bütün mahkemelerde beraat etmiş,

vicdanımızda acı tebessümler.

Gören insanın yazgısıdır, öfke gezdirir

kalabalıklar arasında ve her yeni tanıdığında.

10/07/2004', 'Kıran, döken insanlar arasında zihnimizde cinayetler işler içimizde cesetlerle dolaşırız. Ne tutuklanır ne yargılanırız, günlük yaşayışımız ...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/goren-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'içimdeki Dalga Sesi', 'icimdeki-dalga-sesi-gulden-karabudak-ljacr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mavisine dolanırdım şehrin

Saçını yosunlarla bezerdim

Köpüğüne el verirdim

Geleceğini bilseydim eğer

Dökerdim beyazlarımı

Parça parça ayıklardım/ ne varsa

Geceyi sırtlardım boynuma

Geleceğini bilseydim eğer

Düne bir mektup salar

Mısralarımı yakardım

Bir kitap daha yazardım sana

Geleceğini bilseydim eğer

Bu kızıl temmuz ayazında

Umudumu terlemezdim

Uzağında üşümezdim yersiz

Döneceğini bilseydim eğer', 'Mavisine dolanırdım şehrin Saçını yosunlarla bezerdim Köpüğüne el verirdim Geleceğini bilseydim eğer Dökerdim beyazlarımı Parça parça ayıkla...', ARRAY['Türk Edebiyatı','Şiir','Gülden Karabudak']::text[], 8.5, '{"poet":"Gülden Karabudak","poet_slug":"gulden-karabudak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/icimdeki-dalga-sesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Bekleyecegim Rabiyam', 'seni-bekleyecegim-rabiyam-emrullah-erdinc-9gu0r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benim halim seni beklemek olucak.

Seni bekleyecegim.

Belki gelirsin diye degil Rabiyam,

Gelecegin ümidi ile degil.

Seni beklemek güzel oldugu icin Rabiyam

Seni beklemek kalbimi aydinlattigi icin,

Seni Bekleyecegim...Rabiyam

Seni öyle bekleyecegim ki  gökyuzuyle yeryuzu,

birlesse  her yerde alevler ciksa dunyanin sonu gelse,

Benim halim seni beklemek olacak,

Sen bekle demesende bekleyecegim,

Unut desende bekleyecegim,

seni bir ömur boyu umutla bekleyecegim,

cunki senin resmini kalbimin,

derinliklerindeki tuvalime cizdim, 

ben yasadikca hep orda kalacaksin,

 taakiii seninle bulusana  kadarrrr,

 ve seni hep bekliyecegim.

Benim halim seni beklemek olucak.', 'Benim halim seni beklemek olucak. Seni bekleyecegim. Belki gelirsin diye degil Rabiyam, Gelecegin ümidi ile degil. Seni beklemek güzel oldug...', ARRAY['Türk Edebiyatı','Şiir','Emrullah Erdinç']::text[], 8.5, '{"poet":"Emrullah Erdinç","poet_slug":"emrullah-erdinc","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seni-bekleyecegim-rabiyam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba', 'merhaba-emrullah-erdinc-3rv1y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hatirlarmisin nasil tanistik.

Hatirla o aksami. 

Hatirla sana o sögledigim tatli sözleri.

Hatirla yesil gözlum.

Her sögledigim sözun degerini dusun.

Hatirla sana nasil yalvardigimi.

Hatirla  bir merhabayla tanistigimizi.

Hatirla ki  anla seni nasil sevdigimi.

Hatirla   gecmiste mazide kalan ask sözlerimizi.', 'Hatirlarmisin nasil tanistik. Hatirla o aksami.  Hatirla sana o sögledigim tatli sözleri. Hatirla yesil gözlum. Her sögledigim sözun degerin...', ARRAY['Türk Edebiyatı','Şiir','Emrullah Erdinç']::text[], 8.5, '{"poet":"Emrullah Erdinç","poet_slug":"emrullah-erdinc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/merhaba-72-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Metre', 'metre-zafer-zengin-etnika-be4n3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ölçe bildiğin

ne var ki

Sarı

sıska

bir 

çocuğun

boyundan

başka

Hiç

düşmez mi

yüreğin

A ş k ’ a

Kalp

çeperi

uzunluğu

Ne 

kadar

anlatsan

Dünya

küçük 

değil mi

Kılcal

damarlar

olmasa

Sırf

şiir

olsun

diye

Sorarlar

sana

Kim

düşte

grilenmiş

aşk’a

Boyunun

ölçüsünü

alıyor

A y r ı l ı k l a

| Bükülen demirin rengi..kendisi gibi |

Akşam

başlar

karanlık

Işığı

biz mi

sakladık

Gülümseme 

nasıl

ölçülür

K i m s e  s ö y l e m e d i... 

| Ölçülmemiş..bir yüreğin ses uzunluğu..dile gelmemiş |

9 Temmuz 2004 “ Ölçüsüz ses yankıdır  “ zafer zengin', 'Ölçe bildiğin ne var ki Sarı sıska bir  çocuğun boyundan başka Hiç düşmez mi yüreğin A ş k ’ a Kalp çeperi uzunluğu Ne  kadar anlatsan Dünya...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/metre-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aça-69 (Syk-6b) - Lalezar ve üç yüzlük-çınar (Dualite ve sonrası)', 'aca-69-syk-6b-lalezar-ve-uc-yuzluk-cinar-dualite-ve-sonrasi-akin-akca-we6m6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Göze sapa, ‘laçin’lerden sapak’,

Bulutları uzak ara aşan bir tepeydi

(Yükselen havanın çekirdeğinde)  

, ‘Sıra dışı-gölgelerin dinamosu:

Bu gölgeler, granitlerden tırmanmıştı.

Ve bu yer üzerinde

Emsali bulunmayan bir lalezar

Varlığını sürdürürdü -

Ceketi, pantolonları onun,

Günün her saati ütülüydü

-En orta yerinde, bu görkemli bahçenin

‘Üç yüz yıllık bir çınar’ı barındıran

-Türdeşleri olan (başkaca 

Bölgelerinde dünyanın)     asırlık

Pantolonları ve ceketi ütülü olurdu

Traş olurken, her sabah

Sinekler kaydıraktan kayardı *

Bunları yapan ‘üç yüz yıl’lık çınardı.

Yapmamaktan ziyade, yapamayansa; 

Lalelerden geçit vermeyen

Ve çok hoş görüntüler arzeden Lalezar’dı.

Çınar, bulunduğu yerden hoşnuttu.

Daha sonra, lalelere ne olduğu bilinmez:

Yamyam bir hortum içinde sinsice yaklaştı

‘Yıldırımlar ve bir şimşek’ habercisiydi gökgürültüsünün 

- Tepenin üzerine -bulutların üzerindeki.

Ve bu hortum, doğası gereği,

Birkaç burgaç doğurdu:

Bu burgaçlardan, sayısız deniz hortumu oluştu; 

(Ama istisnai bir şekilde)     karaya çıktıklarında,

Tornado’lardan ‘daha kesif-tehlike kokan’.

Ortam karışmıştı bir anda ve sonunda; 

Acayip, sıra dışı kasırgalar peydahlandı orta yere:

Karalar üzerinde şiddetlenen; 

Gizli ısı’ydı, yoğunlaşmadan mütevellit, açığa çıkan.

En son, ‘toz çığ’ olarak indi kar; 

Ardışık bir dizilişle, tanecikleri ile -

Giderek büyüyerek, kaldırarak karları

-İniverdi eteklerine -yutarcasına- bu tepenin! 

Kadırgalarda kürek çeken mahkumlar, sırta kırbaç hörgüçlenenler! ..

Karışıklık anında birleşirler, Yuvarlak Masa etrafında, şövalyeler! ..

Büyük bir elektrik boşalmasıydı, çöreklenen! 

En başta, çınar ağacıydı yıldırımları çeken! 

‘Yedi yüz bin’de bir olasılığı harekete geçiren! 

Artı ve eksi parçacıklar, havanın direncini kırdılar:

Laleler, onlar bundan korktular

Laleler, onlar göçe zorlandılar …

Laçin: Çıkması güç kayalık yer', 'Göze sapa, ‘laçin’lerden sapak’, Bulutları uzak ara aşan bir tepeydi (Yükselen havanın çekirdeğinde)   , ‘Sıra dışı-gölgelerin dinamosu: Bu ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/aca-69-syk-6b-lalezar-ve-uc-yuzluk-cinar-dualite-ve-sonrasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidişim', 'gidisim-zubeyde-yilmaz-u4ekz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayatın üç gün deseler

Nefes alışımı,

Kollarında senli BİR GÜNE....

Hayallerimi,özlemlerimi,

Yüreğinde diğer güne....

Sevgimi bütün bütün

Bütün   ömründe benim son günüme

Bırakır öyle giderdim

SESSİZCE......

                       Zübeyde  Yılmaz

                                                    (10.07.2004)', 'Hayatın üç gün deseler Nefes alışımı, Kollarında senli BİR GÜNE.... Hayallerimi,özlemlerimi, Yüreğinde diğer güne.... Sevgimi bütün bütün Bü...', ARRAY['Türk Edebiyatı','Şiir','Zübeyde Yılmaz']::text[], 8.5, '{"poet":"Zübeyde Yılmaz","poet_slug":"zubeyde-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gidisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mizah', 'mizah-gokhan-oflazoglu-hd7v5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yanlış giden işlerimiz,

bozuk düzen ilişkilerimiz.

Her gün bozulan yapı,

yeniden kurma girişimlerimiz.

Cehennem alevleri tükürürüz,

mizah gelir üstüne su sıkar,

gülerken attığımız safralar,

yenilenen derinliklerimiz.

Yaşam sıkıştırır köşeye

Mizah geçici çözümler sunar.

10/07/2004', 'Yanlış giden işlerimiz, bozuk düzen ilişkilerimiz. Her gün bozulan yapı, yeniden kurma girişimlerimiz. Cehennem alevleri tükürürüz, mizah ge...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mizah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Bağa...', 'baga-naime-erlacin-e4vre', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bütün öyküleri dinlerim ben ey sevgili

şükrederek varlığına sahici bir aşkın 

soyluluk 

direnç 

ve azmanlığına

tefekküre eğerim sonra boynumu 

borç ödemeye dururum yazıya

yüreğimde bir bağa büyür 

içimi acıtır ağrılar 

çok acır içim hem de

hikâyeler yazarım 

bir sırat gemisinin sisli güvertesinde

kuma kavuştuğunda güneş 

saatler ikimiz için çalar

sevda büyütür gönül büyücüm 

düşürmeksizin kavlimize gölge

her sabah 

akşam bıraktığın yerde

her akşam sabah bıraktığın gibi 

hükmüne sığınır kalemin 

seni beklerim 

unutulmuş bir yatır sessizliğinde

neyim ben bilmem ki! 

aslımı aşıyor suretim bazen

korkutuyor öyküler

alıcı kuşlar çırpınıyor yüreğimde 

kazınsın bu bağa ne dersin 

bir daha betimle

çöz düğümlerimi 

sararan güzden tüm eskizleri at

yaz beni yeniden 

(10 Temmuz 2004)   - (Aşk Sözcükleri Dosyasından)', 'bütün öyküleri dinlerim ben ey sevgili şükrederek varlığına sahici bir aşkın  soyluluk  direnç  ve azmanlığına tefekküre eğerim sonra boynum...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/baga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha ne istiyorsun? ..', 'daha-ne-istiyorsun-ferit-teksoy-ts075', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerine bakmışım erimiş içim

Sesini duymuşum çıldırmış yürek

Gülüşünde hayallere dalmışım

Hayallerim olmuşsun,daha ne istiyorsun? ..

Umursamaz sanır dışımı gören

Yanardağ misali içten yanmışım

Susamışım,kurumuş dudaklarım

Özlemlerim olmuşsun,daha ne istiyorsun? ..

Saçlarının rengini dolamışım dilime

Tüm renkleri görmüşüm,bakınca gözlerine

Ellerinin sıcaklığı geçince ellerime

Yangınlarım olmuşsun,daha ne istiyorsun? ..

Bu demişim hasretle yolunu gözlediğin

Sana benzeyende seni görmüşüm

Senin için açılmış ellerim gökyüzüne

Dualarım olmuşsun,daha ne istiyorsun? ..

Sensiz geçen yıllara basmışım küfürleri

Uzaklara dalıp dalıp gitmişim

Sigaralar yakımışım sigaralar üstüne

Sevdiceğim olmuşsun,daha ne istiyorsun? ..

10 Temmuz 2004', 'Gözlerine bakmışım erimiş içim Sesini duymuşum çıldırmış yürek Gülüşünde hayallere dalmışım Hayallerim olmuşsun,daha ne istiyorsun? .. Umurs...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/daha-ne-istiyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alo Anlam!', 'alo-anlam-naime-erlacin-rop7l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ne âlemi var 

boşa 

kürek çekmenin 

anlamsızın 

anlamını

anlamayı

anlayana bırakmalı

bir kişi vardır mutlaka 

tek bir şey ya da 

anlamlıyı anlayan

alo anlam! 

şiirler 

sana yazılmalı

(10 Temmuz 2004)     – “Yeni Dosya”dan…', 'ne âlemi var  boşa  kürek çekmenin  anlamsızın  anlamını anlamayı anlayana bırakmalı bir kişi vardır mutlaka  tek bir şey ya da  anlamlıyı a...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/alo-anlam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirle Çıkıyor Sesimiz Şimdi', 'siirle-cikiyor-sesimiz-simdi-esma-ozdemir-33m55', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bütün dünya silahları sussunlar

Şiirle çıkıyor sesimiz şimdi

Savaş, kavga, gürültüler yok olsun

Şiirle çıkıyor sesimiz şimdi

Uyaklı, uyaksız, aruz ve hece

Ölçüsü insanlık, sevgisi yüce

Cehalet illeti yere düşünce

Şiirle çıkıyor sesimiz şimdi

Kadın-erkek gönülden bir olunca

Şiddetin karası yüze vurunca

İnsan eksiğini özde bulunca

Şiirle çıkıyor sesimiz şimdi

Acının kınında boğulur canlar

Sahipsiz iyesiz yiten civanlar

Pazara sürülmez böyle kadınlar

Şiirle çıkıyor sesimiz şimdi

Selam olsun aydın yüzlü erlere

Kadınını “ana” bilen gençlere

Bundan böyle kadın-erkek el-ele

Şiirle çıkıyor sesimiz şimdi

Yunus, Karac’oğlan, Abdal Pir Sultan

Aşk-ı muhabbeti yaydılar candan

Kadın sesi ile Ozan ŞahTurnam

Şiirle çıkıyor sesimiz şimdi

Özdemir der; “kadıncık”tır adımız

“Eksik etek” diye çıkmaz gıkımız

Adem’den bugüne Havva Anamız

Şiirle çıkıyor sesimiz şimdi.', 'Bütün dünya silahları sussunlar Şiirle çıkıyor sesimiz şimdi Savaş, kavga, gürültüler yok olsun Şiirle çıkıyor sesimiz şimdi Uyaklı, uyaksız...', ARRAY['Türk Edebiyatı','Şiir','Esma Özdemir']::text[], 8.5, '{"poet":"Esma Özdemir","poet_slug":"esma-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/siirle-cikiyor-sesimiz-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatanıma Dair', 'vatanima-dair-sih-mahmut-kiran-ardcr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Duyuyorsan,

Yorgun akşamların ıssız bağrından gelen haykırışları; 

Parmağını kaldır gökyüzüne,

Ve kurtuluş gününün geldiğine inan...

Yaprakları solan gülünden bir yaprak da sen kopar...

Ve deki:

''İsyanımı beraberinde büyüten bebeğe haykırıyorum.''

Senin her ağlayışında halkım daha çok gülecek,

Senin her yumruğunu sıkışında insanlarım daha çok birleşecek,

Ve sen yürümeye başladığında bu sürgün bitecek,

Özgürlük kanına işleyecek...

Diyeceğin ilk söz anne olmayacak,

''Uyan yurdum! '' diye haykıracaksın...', 'Duyuyorsan, Yorgun akşamların ıssız bağrından gelen haykırışları;  Parmağını kaldır gökyüzüne, Ve kurtuluş gününün geldiğine inan... Yaprakl...', ARRAY['Türk Edebiyatı','Şiir','Şıh Mahmut Kıran']::text[], 8.5, '{"poet":"Şıh Mahmut Kıran","poet_slug":"sih-mahmut-kiran","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/vatanima-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehrin direkleri', 'sehrin-direkleri-yunus-ali-sinanoglu-zeazm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Direklerine kalbimi astım bu şehrin

Islatacak yağmur her telini

Siyah saçlarını bekleyen sokaklar

Sokakların üzerinde kanayan kalbim var

Şimdi rüzgar tarayacak

İklim değişecek

Saçların siyahına baki

İnadına hür

Hızla delip geçecek kaldırımları

Ateş gibi

Ateşler haklı

Damlalar aşağı düşecek

Alevler yukarı

Ve incitecek kanayan yaramı

Bu şehrin direklerine geçmiş

Binbir delikli al kalbimi

Al kalbimi kurtar

Sonra koynuna sar

Bil sana ihtiyacım

İhtiyacım sana var

Siyah saçlarınla 

Koşan adımlarınla

Gel', 'Direklerine kalbimi astım bu şehrin Islatacak yağmur her telini Siyah saçlarını bekleyen sokaklar Sokakların üzerinde kanayan kalbim var Şim...', ARRAY['Türk Edebiyatı','Şiir','Yunus Ali Sinanoğlu']::text[], 8.5, '{"poet":"Yunus Ali Sinanoğlu","poet_slug":"yunus-ali-sinanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sehrin-direkleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk da yapabilen bir yoğun-sevgi’ye yönelik bir uygarlık türküsü', 'ask-da-yapabilen-bir-yogun-sevgi-ye-yonelik-bir-uygarlik-turkusu-akin-akca-n99c9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kara tahtaya yazmaya çalışıyorsun 0.5 kalemle.

Una buluyorsun ‘beyazımsı-balçıksı hamuru’:

Bembeyaz mezar taşlarından güvercin ama, uçuruyorsun; 

Gecenin zifiri karanlığında, alacakaranlığın geceyi terk edişinde:

Tütün çiğniyorsun, sakız çiğnerken, iyi, hoş da; 

Yaparken bunu, sararıp düşmesin, ilkbaharı gibi hazanın:

Una buladığın hamurun, tümden beyaz olsun.

Sen bu aykırılığın içindeki sıra dışılığın,

Götürdüğünü uzlaşıya fark ettiğinde …

Elbet, düşüneceksin de: 

Uğraşırken, “bekleyeceğim”, sen de; 

Zamanı ellerinde yoğur -çocuk-oyun-hamuru gibi -o halde.

Alaca karanlık bir dikta, şimdilerde; 

Saklı gözbebeğinde, ortaçağ’ın:

Uygarlığın türküsü bu, sanki, yaşananlar; 

Kotarılmaya çalışılanlar, yılmadan, kan ter içinde', 'Kara tahtaya yazmaya çalışıyorsun 0.5 kalemle. Una buluyorsun ‘beyazımsı-balçıksı hamuru’: Bembeyaz mezar taşlarından güvercin ama, uçuruyor...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ask-da-yapabilen-bir-yogun-sevgi-ye-yonelik-bir-uygarlik-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'At', 'at-yunus-ali-sinanoglu-vfelb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Siyah bir atım

Alev kesmiş çöllerde

Doludizgin denize koşuyorum

Etraf kum

Dalgalara basıyorum adımımı

Masmavi

İsmini yazıyorum heryer eğri

Yükseliyorum göklere

Dalgalardan ismine

Taş sayıyorum göklere tırmanıyorum

Tenim buz kesiyor

Ellerim yok

Ben siyah yeleli kara atım

Adım Arap

Bulutları dağıtıyorum

Dört yan harap

Hayrette kuşlar

Kuşlar da arap

Sonra ismin büyüyor

Dalgalar okyanuslar

Basıyorum sırtına

Şimdi yıldızlar

Kapkara tenim ateş keser gözlerim

Burçlarda gezmedeğim

Rengim öğlesine kızıl

Kuyruklu yıldız sanıyorsun

Oysa kara atım adım arap

Yanlış dilek tutuyorsun

Vay be diyorum

Ayağım şimdi ayda

O da yanılıyor

En nihayetinde beşer o da şaşar

Ve diyorum kara at

Seviyor

Bilmiyor

Kişniyorum

Dört nal 

Sevincimden

Çöllere dönüyorum

Sırtım ter

Aşkım eyvallah ateş keser', 'Siyah bir atım Alev kesmiş çöllerde Doludizgin denize koşuyorum Etraf kum Dalgalara basıyorum adımımı Masmavi İsmini yazıyorum heryer eğri Y...', ARRAY['Türk Edebiyatı','Şiir','Yunus Ali Sinanoğlu']::text[], 8.5, '{"poet":"Yunus Ali Sinanoğlu","poet_slug":"yunus-ali-sinanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/at-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aslolan Aşktı', 'aslolan-askti-huseyin-cayikli-9u21s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sırt çantamı alıp bir şehrin bilmediğim yollarında yürüyordum.yorgundum..bir aşkın acısı ve elimde ki terden başka hiçbirşeyim yoktu.Açtım... aşka belkide.isim isimsizliğim oluyordu ben bu şehrin sokaklarında yürüyordum belki sana rastlarım diye elimde adresin sadece taksiciye verilmek üzere duruyordu gitsem birşey değişmeyecekti ve yorgundum.Ayaklarım ne idüğü belirsiz bir koşuşturmayla ve hızlı adımlarla sana koşuşturuyordu sen bilmiyordun...ben hep sana koştum oysa bilmediğim sokaklarda aramadığım telefon hatlarında sana hep koştum.Anlayamadın beni oysa ben anlamlam yükleriyle karşına çıkmıştım bir adım ve bana kalan yalnızlık vardı...hediye sepetinden aşkını çıkartmıştın anlayamadan hediyeni çekip gittin birgün...

yoruldum seni beklerken sokak başlarında senden sonrada çok kadınlar tanıdım sevdim onları ellerim ellerine değemedi tiksindim...aklıma bir mızrak gibi girmiştin tanrıça filan olamazdın çünkü tanrılar onları sevenleri terketmezdi...Acılar çektim... gece terleyerek uyandığım yastığım gibi sırılsıklamdı gözlerim.ben seni ne zaman sevdim anlayamadım.o şehre geldiğim bilmediğim sokaklarında kaybolurken ellerin bir yerden çıkar dedim.çıkartabilirdin aslında ama sen hep gitmeyi denedin. seni hiçbir zaman suçlamadım ben.yaşam farlı bir anlayış açısıyla bizi kavuşturmuştu ve farklı anlayış açısıyla bizi ayırdı.senle beraber uçakları sevdim sevgililer getiren gemiler gibi uçakları bekledim.ben seni hep beklerdim oysa...gözlerimle elllerim ve dudaklarımla bekledim.bir şehre gittim kayboldum orada.ben seni hep sevdim.sevmediğim gün yoktu sana kötü şeyler söylerkende seni sevdim.ben sana aşık olmuştum sadece elimde olanla yetindim...senin için o kadar çok şeyden vazgeçmiştim ki kendimden bile...şimdi sana aşık olanlar listesindeyim ve kavuşamayanlar.ellerim hala yalana dair yazabiliyor unuturum belkide seni bu ellerle çünkü aslolan aşktı...

09,07,2004

bursa-kitapevi', 'sırt çantamı alıp bir şehrin bilmediğim yollarında yürüyordum.yorgundum..bir aşkın acısı ve elimde ki terden başka hiçbirşeyim yoktu.Açtım.....', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/aslolan-askti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gördüm Asuman''ı...', 'gordum-asuman-i-i-brahim-ethem-bingul-0ikj9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zaman eşkiya, çaldı benden

En güzel anlarımı

Kayboldum harami gönüllerin

Sevda çıkmazlarında..

Bir ışık hüzmesi

Bir yürek atımı nefes

Değmeliydi acılara, en onulmaz yaralara

Sürülmeliydi merhem yaralara..

Aramadım, bekledim

Biliyordum beni seyrettiğini

Beni her yanımdan kucakladığını

Başımı kaldırdım ve baktım sadece

Gördüm tüm güzelliği ile Asuman''ı...', 'Zaman eşkiya, çaldı benden En güzel anlarımı Kayboldum harami gönüllerin Sevda çıkmazlarında.. Bir ışık hüzmesi Bir yürek atımı nefes Değmel...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gordum-asuman-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geleceğim Korkutuyor Beni..!', 'gelecegim-korkutuyor-beni-nazife-abayli-8bpds', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dört duvar arasına girdim yine.

Şu sıcak yaz gününde.

Herkesin kolunda eşi,

Ya da sevgilisi..

Ben ise ölü aşkların ardından hüzün döken,

Sarı yapraklı sonbahar serserisi..

.....................................................

Ağlamalı mıyım? Yoksa gülmeli mi? 

Unutmalı mıyım? 

Geçen mevsimleri..

Hazmetmeli miyim? 

Yediğim darbeleri.

Ne yaparsam yapayım...

Ölümün ne zaman geleceği değil,

Geleceğim korkutuyor beni...!', 'Dört duvar arasına girdim yine. Şu sıcak yaz gününde. Herkesin kolunda eşi, Ya da sevgilisi.. Ben ise ölü aşkların ardından hüzün döken, Sar...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gelecegim-korkutuyor-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çınarım', 'cinarim-derin-oger-8q4bk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ey gökyüzüm,rüzgârın fırtına esti 

gücüne dal kırıldı,kırık içime yürüdü

ateşte yanamadım uykuya sığamadım

ince ince doğrandım iri iri yuttum

geceyi taş gibi yüreğime doldurdum da

kimse çalmasın diye yıldızlarımızı sakladım

safı çıplağı koşulsuz sevenimdin

bir suçum yanılgım varsa üstüme aldım

herşeyi kabullendim de gerçeğe sığamadım

sana değil yağmuruna bulutuna küstüm

yürek vuruşlarım bir mahkum gibi volta atarken

seni seninle seni sensizlikle usulca öptüm öptüm

biliyormusun saksıdaki fesleğene çınarım dedim

umuda gelsin diye gözlerime yeşilinden sürdüm

ilk kez denizin göğün mavisini sevmedim

sonra bir sigara yaktım kitaplarımı da yanıma aldım

sanki bir fincan kahve misali elimi sımsıcak tuttun

sen gönlümün deryası ben başının belası oldum....', 'ey gökyüzüm,rüzgârın fırtına esti  gücüne dal kırıldı,kırık içime yürüdü ateşte yanamadım uykuya sığamadım ince ince doğrandım iri iri yuttu...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cinarim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşveli', 'i-sveli-bekir-mutlu-gokcesu-0zd1w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tutardım nefesimi

Benden gayrı

Neye baksa

Gezinir gibi gelirdi

Yudumlarcasına

Bedenimi

Usulca kaydırıverdiği

Dudaklarıyla ritmik

Gözleri...

Bilirdi izlediğimi

Ve ona bittiğimi...

Sonra 

Süzmeye başlardı

Baştan sona

Ben kaçırırken gözlerimi

Avlardı işveleri

Gencecik hislerimi

Ben konuşamazdım bile

Gülerdi...

Kim bilir içinden ne derdi?', 'Tutardım nefesimi Benden gayrı Neye baksa Gezinir gibi gelirdi Yudumlarcasına Bedenimi Usulca kaydırıverdiği Dudaklarıyla ritmik Gözleri... ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/isveli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arada kalan yüreğimdi..', 'arada-kalan-yuregimdi-ersin-altioglu-yd3ov', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her şey bir şaka ile başladı ya da arada kalan yüreğimdi. Korkularımı 

gizlerken yalnızlığımın esaretinde kim kalırdı benden geriye 

bilmiyordum. Sürgündüm sana ve yolculuklarıma sensiz başladım. Yoksuldum üç kuruşluk aşklar ertesinde. Göçerken yüreğim büyük aşkların ardından bana kalırdı en yoksul yanlarım. Senden kalanlar matem renginde bir terk ediş ve umursamaz bir bakıştı. Yorgundum, sen ağır bir yüktün yüreğimdeki düşlere ve ben eziliyordum. Çatışıyordum içimdeki benle. İçinden çıkamadığım sorulardı 

senden geriye kalan. Şimdi ise bu soruların cevabını arıyorum. Kime soracağımı bile bilmeden senden bana kalan yalnızlığımla, loş sokak lambalarının altında dolaşıyorum, boş ama bomboş sokaklarında. Az sonra güneş açacak ve gece gündüze dönecek. Ortalıkta bir ben kaldım, bir yüreğim kaldı arada ve bir de gecenin hüzünlü nemi.', 'Her şey bir şaka ile başladı ya da arada kalan yüreğimdi. Korkularımı  gizlerken yalnızlığımın esaretinde kim kalırdı benden geriye  bilmiyo...', ARRAY['Türk Edebiyatı','Şiir','Ersin Altıoğlu']::text[], 8.5, '{"poet":"Ersin Altıoğlu","poet_slug":"ersin-altioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/arada-kalan-yuregimdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kül Eyledim', 'kul-eyledim-cengiz-oyke-xuze8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öyle bir zalimi sevdimki ben 

Dikenmiş gönlümde gül eyledim

Ne dediyse kırmadım hatrını 

Gönlümü gönlüne kul eyledim

Arı misali kondu gülüme

Soktuğu iğneyi bal eyledim

Önünde duran karlı dağları

Taşsız dikensiz bir yol eyledim

Öykenin kimseye yoktur hıncı

Değirmende hıncı un eyledim

Artık gönlümde yok zerre sancı

Gönlümde gönlünü kül eyledim.

Cengiz ÖYKE', 'Öyle bir zalimi sevdimki ben  Dikenmiş gönlümde gül eyledim Ne dediyse kırmadım hatrını  Gönlümü gönlüne kul eyledim Arı misali kondu gülüme...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Öyke']::text[], 8.5, '{"poet":"Cengiz Öyke","poet_slug":"cengiz-oyke","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kul-eyledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Bahçesi', 'askin-bahcesi-guner-kaymak-roj40', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşkın Bahçesine uğradı yolum 

Kırılmış dalları güller perişan 

Isırgan otuna kapıldı kolum 

Szılıyor yüregim halim perişan 

Kurumuş çeşmesi sular akmıyor 

Bülbül güle dargın dönüp bakmıyor 

Hazan gelmiş bahçe güzel kokmuyor 

Kırıldı ümitlerim halim perişan 

Her bir yanı sarmış ayrılık otu 

Şimdi durum eskisinden çok kötü 

Nasıl aşacağız bu koca seti 

Dikenler batıyor halim perişan 

Papatya falına artık bakan yok 

Lale boynun egmiş koyun kuzu çok 

Karanfiller güzel yakasına takan yok 

Çiçekler yasta gönlüm perişan 

Utancından çiğdem sararmış solmuş 

Menekşeye nergise bir haller olmuş

Bu güzelim bahçeye hoyratlar girmiş 

Dostlar kan ağlıyor ruhum perişan 

Baykuş gelmiş hazin hazin ötüyor 

Aşk sevgi nerdeyse bitti bitiyor 

Sadakat dostluk vefat etti ölüyor 

Param parça gönlüm halim perişan 

Ozan Güner aşkta yüzüm gülmedi 

Vefasız yar hiç kiymetimi bilmedi 

Çok susadım kimse bir su vermedi 

Kızgın çöllerdeyim halim perişan 

Güner Kaymak / Amsterdam 3 temmuz 2004', 'Aşkın Bahçesine uğradı yolum  Kırılmış dalları güller perişan  Isırgan otuna kapıldı kolum  Szılıyor yüregim halim perişan  Kurumuş çeşmesi ...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/askin-bahcesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'insan-sevince', 'insan-sevince-bekir-mutlu-gokcesu-ihssr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçimde sen

Sığmaz içim içime

Yıldızlar sığar

Ben sığmam

Sensiz geceye...

Uykulara sığınmak

Dalmak gözlerimden

Gözlerindeki sevince

Kaybolmak isterim gecede...

Uyku tutmaz

Sen tüterken gözlerimde

Ve sızarken hücrelerimden

Geceye...

Sen gece olursun nihayetinde

Yıldızlarda sığar bende

Fakat yanar içim

Yanar sensizliğine...', 'İçimde sen Sığmaz içim içime Yıldızlar sığar Ben sığmam Sensiz geceye... Uykulara sığınmak Dalmak gözlerimden Gözlerindeki sevince Kaybolmak...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/insan-sevince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş/le/rin/den', 'dus-le-rin-den-ahmet-aksoy-78s5o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yırtılsa da en derin yerinden gökkuşağı

renkler birbirinden dağılır mı

usundaki kemirgen kavkı

taşır mı seni zamanın ötesine

dönse de güne bakanlar yeni günlere

kenetlenmiş ruhlar ayrılır mı

ki sen her ne kadar çıkarılsan da

bir işlemin en sağlanmışından 

bırakabilir misin kaybettiklerini 

düş/lerinden düşle /rinden düşlerin/den', 'yırtılsa da en derin yerinden gökkuşağı renkler birbirinden dağılır mı usundaki kemirgen kavkı taşır mı seni zamanın ötesine dönse de güne b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dus-le-rin-den-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Going nowhere', 'going-nowhere-akin-akca-ojogq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'If you can not hold your breath, 

Your imagination becomes real. 

And it is good. 

Push yourself through imagination.

So, crucifixation’s hush. 

You, goin’ nowhere! 

: So, there’s ''a hyperactive volcano-alike-kangroo'' around: 

Best of the best’s; 

To see the infant, 

You carry in your pocket. 

- 

türkçesi: 

(Trakya’nın yıldırım merhameti)

Tutmazsan nefesini, 

Hayallerin gerçek olur 

Ve bu iyidir: 

Rüyalarından doğru kendini ittir; 

Ve, bir –sadece

- suskunluk, çarmıh’a gerilme. 

Sen, hiçbir yere giden! 

Bir hiperaktif-kanguru, böylece; volkanın kustuğu –

sıçrayan- oluştu: 

Küçücük çocuğunu görmektir, 

‘En iyinin en iyisi’; 

Kanguru için, cebindeki.', 'If you can not hold your breath,  Your imagination becomes real.  And it is good.  Push yourself through imagination. So, crucifixation’s hu...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/going-nowhere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* T r a f i k...A ş k ı m..! (1-2-3-4-SON)', 't-r-a-f-i-k-a-s-k-i-m-1-2-3-4-son-metin-eser-lahot', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güzel bir Pazar günü, geziyorken çarşıda, 

Derken bir hatun gördüm, gülüyordu karşıda, 

Şaşırdım afalladım, bana mıydı bu gülüş, 

Acaba olur muydu, güzel zevkli bir sürüş, 

Hayalime düştü aşk, yarınlarım kurguda, 

Meraklı birçok konu, teker teker sorguda, 

Varsaydım ki bu aşkı, trafikte yaşadım, 

Sonra dizeye döküp, bu şiire taşıdım, 

Aldığım bir bakışla, bastım gaza aniden, 

Geçtim karşı tarafa, ben anlamam maniden, 

Otobandayım gibi, yüklenmişim son sürat, 

Bir kelime konuşsam, geri kalan küsürat, 

''Merhaba'' ydı ilk sözüm, hız limiti yok idi, 

O da ''Merhaba'' dedi, samimiyet yok idi, 

Sanki bana ilk anda, kırmızıyı yakmıştı, 

Duygular frenlenmiş, trafik karışmıştı, 

Bir duvara toslayıp, kaza yapmak da vardı, 

Yada bir manevrayla, hali kurtarmak vardı, 

''Pardon hataydı'' dedim, ''belki çok ani oldu'', 

Bu sözlerin üstünden, yüzde tebessüm oldu. 

Anladım ki ışıklar, şimdi sarı yanmıştı, 

Samimi yüreğime, sanırım inanmıştı, 

Tek şeritli bir yolda, daha rahattım şimdi, 

Gönlüm bas gaza diyor, merakımsa ''bu kim ki''. 

10.07.04 / Frankfurt

..................dünden devam..................

Ne gelmişse başıma, hep meraktan gelmiştir,

Merak hocadır “ilm” e, bazen fayda vermiştir,

Ya nasip deyip hemen, adını sordum O’nun,

Ne yapacaksam adını, işte maksat laf olsun,

“Zeliha” dedi bana, “burada yabancıyım”,

“Görünüşüme bakıp, sanmayın yalancıyım,

Çok ta dikkatlisiniz, bakışlarınız kurnaz,

Çünkü şu trafikte, burda araba durmaz.”

Gülmüşüm kendisine, lakin içimde sızım,

Adım konulmuş çapkın, bundan da rahatsızım,

Hemen bir U dönüşü, yapmayı düşünürken,

Sağa mecburi yönü, gösterdi gülüşürken,

“Haydi bekliyorum ben, davet etseniz” dedi,

“Bir de güzel ismini, söyleyiversen” dedi,

Anladım hız sınırı, yavaş yavaş kalkmıştı,

Çünkü yeşil gözleri, çok manalı bakmıştı,

Görüyordum ilerde, ne virajlar var idi,

Konuşma ilerledi, bazen yol kaygan idi,

Arasıra fikirler, uyuşmadı elbette,

Malum böyle kasisler, normaldi trafikte,

Kah bu yolda gidiyor, kah etrafa bakıyor,

Tali yollar çıkınca, dönesim de geliyor,

Ama gönül istekli, ikide bir “gaz” diyor,

Akıl zaten iflasta, “ne istersen yap” diyor.

Ve artık başlamıştı, iki yönlü trafik,

Bir demiryolu ile, iki de kavşak geçtik,

Ciddi bir problemi, aşmıştım ki yeni,

Sonra bir iniş/eğim, çok korkutmuştu beni,

Hayatımda hiç böyle, bir aşk yaşamamıştım,

Zaten böyle güzele, hiç de rastlamamıştım,

İstiyordum bu aşkım, hep otobanda sürsün,

Bakalım ne olacak, sabret sen de görürsün. :-)))    

12.07.04 / Frankfurt

..................dünden devam..................

Yolda çalışma varmış, bir adam elde kürek,

İçimden bir ses dedi, ''haydi şu yöne sürek'',

Birazcık yavaşladım, ilk çıkışı görünce,

Kız biraz rahatladı, tali yola dönünce,

İstemiyordu herhal, çok hızlı ilerlemek,

Tatlı aşk şarabını, hemencik tekerlemek,

Aha dedim içimden, bu kız “kalite” yani,

Aşkın lezzetlerini, tatmak istiyor yani,

“Ama biraz yavaş git, çek ayağını gazdan”,

Diyemiyor açıkca, zannedicem bu nazdan,

Anladım ben olayı, dönel kavşak ortada,

Birkaç tur atacağız, birazcık etrafında,

Hani zaman geçecek, belki benzin bitecek,

Sanıyor ki sabrım yok, ben vazgecip gidecek,

Güldürme beni güzel, benim adım kül yutmaz,

Göle çalınan maya, bu aşkıma hiç tutmaz,

Derken lafın içinde, “ne iş yaparsın” dedi,

“Böyle hep trafikte, aşk mı ararsın” dedi,

Dedim “mesleğim süper”, hespsinin efendisi,

Boş gezenin kalfası, kaldırım mühendisi,

Kahkahayla güldü ya, “alem adamsın” dedi,

Benim yüzümse pancar,”çok da şekersin” dedi,

“Gaz”  bana ait ama, kız bizi bastıracak,

Böyle giderse eğer, şoförlüğü kapacak,

Seslendim tez şair’e, “hey dostum baksana bir”,

“Değiştir senaryoyu, bu şiirde başrol bir”,

“O da yanılmıyorsam, bana verilmiş idi”,

“Ama gel gör ki hatun, direksiyonda şimdi”,

Şair tez toparlandı, “pardon Metinim” dedi,

“Birazcık şekerleme, uyuklamışım” dedi,

“Hey Zeliha kalk ordan, senaryoda bu yoktu”,

Anladım bu şairle, iş ve yolumuz çoktu.

Leyla mısın be adam, burada aşk yaşıyoz,

Adam gibi yaz şunu, köşe bucak koşuyoz,

Yanımızda bir hatun, yakma benim fırsatı,

Sonra yırtar atarım, vallahi bak ruhsatı,

13.07.04 / Frankfurt

..................dünden devam..................

Biliyorsunuz dostlar, dün biraz gergin idi,

Bizim uyuşuk şair, uyumuş kalmış idi,

Sanki otel burası, adam gibi şair ol,

Yapamıyorsan eğer, pazarda kabzımal ol,

Haydi al şu kalemi, başla artık yazmaya,

Bu kız da gider ise, sap olucaz kazmaya,

Şöyle yanaşayım az, yakın temas durumu,

Tekrar lafa gireyim, “nasıl hava durumu”,

Yüzü kah gülümsüyor, “sollamak serbest diyor”,

Bir de bakıyorum ki, “işte orda “DUR” diyor”,

Birazcık sokulayım, elin tutayım desem,

İşte şimdi olmadı, “Taşıt Giremez” diyor,

Hay Allah ne yapsam da, şu hatuna yamansam,

Yerler kayganmış deyip, üstüne mi abansam,

Yakında da hiç yok ki,  hız yapılacak zemin,

Kız da şüphelenecek, sert baktı zaten demin,

Hiç bir sebep yok iken, birden tahditler kalktı,

Yüzümde gülücükler, moralim şaha kalktı,

Uzattı ellerini, ellerimin üstüne,

Sonra baktı yüzüme, gözü gözüm üstüne,

Haydi çek şu kenara, başıma vurdu artık,

Anladım sende iş yok, kontrolse bende artık,

“Şimdi dediğimi yap, pantolonunu çıkar”,

“Sonra da gömleğini, çoraplarını çıkar”,

Aha dedim n’oluyoz, karizma çiziliyor,

İçimdense gür bir ses, boşver çizilsin diyor,

Dedi “arzun bu idi, işte sana bir fırsat”,

Dedim “ben utanırım, önce gözünü kapat”,

“Arkanı dön o zaman, utangaç sensin” dedi,

“Sırtımı döner dönmez, Hadi elveda” dedi,

Döndüm aniden geri, arabam uçuyordu,

Hatun direksiyonda, tam gazla kaçıyordu.

Trafikte bir aşka, tam “gaz” vericez dedik,

Hesap çarşıya uymaz, esas gazı biz yedik,

Ama ben biliyorum, bu neden oluyordu,

Bu şair bozuntusu, benimle oynuyordu,

14.07.04 / Langen

..................dünden devam..................

Arabam elden gitti, hatun hayalim bitti,

Şiirinse son günü, ümidim kayıp / yitti,

Trafikte bir aşktı, henüz yaşayamadım,

Suretinden geçipte, gönle ulaşamadım,

Lakin ben bir şiirin, adsız kahramanıyım,

Şairse yazar durur, ben onun ilhamıyım,

Lâkin aşkım uğruna, çekilmedim hiç geri,

Bana bak artık şair, geri dur benden geri,

Ne vardı şimdi böyle, senaryoyu bozacak,

Yok mu senin de duygun, güzel bir aşk yazacak,

Ne olurdu şu işi, tatlıya bağlasaydın,

Hem okuyanı hem beni, şöyle kucaklasaydın,

Hey “Metin” bana bak, sen şiirde kahraman,

Ve bunu hiç unutma, ben şairim her zaman,

Senaryoyu yazarım, seni içine katarım,

Kafam rahattır benim, yan gelirim yatarım.

Ben şairim sen şiir, bunu yaz bir kenara,

Anlamam ben tehditten, bunu da koy kenara,

Bil ki kalem elimde, ister isem yazarım,

Yada kalemi kırıp, seni hayal yaparım,

Sana bir rol verdiysek, bu bendendir onu bil,

Seni aşık ettiysem, öyle yazdım bunu bil,

Ama istersem seni, senaryodan atarım,

Boş kalan rolü ise; gerekirse oynarım,

Sustun değil mi şimdi, anladın mı durumu,

Her zaman haddini bil, yaz kenara yorumu,

Ve şimdi sana dersi, kendimce vereceğim,

Seni bu senaryodan, sessizce sileceğim,

Bak hiç sesin çıkmıyor, çünkü çıkartmıyorum,

Adın bile geçmiyor, çünkü ben yazmıyorum,

Sana uğurlar olsun, şimdi sıranı bekle,

Belki başka şiirde, verir isem rol bekle.

Evet sevgili dostlar, şiirin sonu geldi,

En başından sonuna, içte ibretle geldi,

Aşkı araç yapanlar, bir yanda yapmayanlar,

Bir ömüre bir sevda, ya da yanaşmayanlar, 

Bu “Trafik Aşkını”, belki herkes yaşadı,

Hayat trafik idi, şu bedenle yaşadı,

Aşk yürektir be dostlar, beden bir ihtirastır,

Doğru söze ne hacet, AŞK en güzel libastır.

...........................S O N...........................

15.07.04 / Frankfurt', 'Güzel bir Pazar günü, geziyorken çarşıda,  Derken bir hatun gördüm, gülüyordu karşıda,  Şaşırdım afalladım, bana mıydı bu gülüş,  Acaba olur...', ARRAY['Türk Edebiyatı','Şiir','Metin Eser']::text[], 8.5, '{"poet":"Metin Eser","poet_slug":"metin-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":178,"source_url":"https://www.antoloji.com/t-r-a-f-i-k-a-s-k-i-m-1-2-3-4-son-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalmışken sensiz', 'kalmisken-sensiz-omer-gungor-aj4no', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bügün bir şeyler yazmak istesem 

neleri aşarım kim bilir

ve karamsarlarlıklar sarar beni 

ne olurdu gerçek ol 

ne olur anla

 aşamıyorum hayatı

çünkü hayat sendin

 ne bileyim söylesene 

unutmak zor son bakış  aklımdayken

olmaz imkansız aşma beni 

gelme üstüme

sendin gerçek ve biten bendim', 'bügün bir şeyler yazmak istesem  neleri aşarım kim bilir ve karamsarlarlıklar sarar beni  ne olurdu gerçek ol  ne olur anla  aşamıyorum haya...', ARRAY['Türk Edebiyatı','Şiir','Ömer Güngör']::text[], 8.5, '{"poet":"Ömer Güngör","poet_slug":"omer-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kalmisken-sensiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönüm Noktası', 'donum-noktasi-omer-gungor-tqiof', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'zorluklar çekiyorum

anlamıyorum hiç kimseyi

anlamazken kendimi

senden sonra anlamsızım karışığım zordayım

bul beni

kurtar ben bulamazken seni

ne olur son kez hayattan 

bir dilek çık gel ve konuş

başlasın artık yaşamım', 'zorluklar çekiyorum anlamıyorum hiç kimseyi anlamazken kendimi senden sonra anlamsızım karışığım zordayım bul beni kurtar ben bulamazken sen...', ARRAY['Türk Edebiyatı','Şiir','Ömer Güngör']::text[], 8.5, '{"poet":"Ömer Güngör","poet_slug":"omer-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/donum-noktasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazmışken 1', 'yazmisken-1-omer-gungor-ab0go', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sen uçsuz bucaksız bir yerdesin

benim düşüncelerim yetmez seni görmeye

uzaksın çok uzak

paralısın zenginsin

belkide bende zenginim ama benim sadece karnım tok

eskimişim ben yaşlıyım

sen se tazesin hayatta benim için gençlik

zorsa seni görmek

bende daha zoru seçerim

seni severim.........................,', 'sen uçsuz bucaksız bir yerdesin benim düşüncelerim yetmez seni görmeye uzaksın çok uzak paralısın zenginsin belkide bende zenginim ama benim...', ARRAY['Türk Edebiyatı','Şiir','Ömer Güngör']::text[], 8.5, '{"poet":"Ömer Güngör","poet_slug":"omer-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yazmisken-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denemek', 'denemek-omer-gungor-hb4zu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'merhaba hayat desem

acaba bir anlamı olurmu

biraz umursamaz olsam

hayat güzel olurmu

peki hayat güzel olurda ya ben

ben ben olurmuyum

sessiz karamsar

ve savaşçı

bitmeyen huzursuzluklarımda', 'merhaba hayat desem acaba bir anlamı olurmu biraz umursamaz olsam hayat güzel olurmu peki hayat güzel olurda ya ben ben ben olurmuyum sessiz...', ARRAY['Türk Edebiyatı','Şiir','Ömer Güngör']::text[], 8.5, '{"poet":"Ömer Güngör","poet_slug":"omer-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/denemek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen- Ben (Akrostiş) 3’lü', 'sen-ben-akrostis-3-lu-halit-demir-ov1lt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'S  ana güzel baharlar,	B  ana kurak çöl düştü

E  ser rüzgar savurur,	E  ndâma bir dert düştü

N  asıl istemem seni,	N  âzende gülüş düştü

S  ana aşkın şerbeti,	B  ana zakkum su düştü

E  fsunlu günler sana,	E  lem gün başa düştü

N  ev-bahârım sensiz,	N  âçâr bir derde düştü

S  ana pembe hayatlar,	B  ana yalın düş düştü

E  rvâhlar bu mecliste,	E  lkan dil bana düştü 

N  azra-i mahmûr bakma,	N  abz atmaz yere düştü

S  ana güler yaşamlar,	B  ana ağlamak düştü 

E  lsen konuşur diller,	E  ğik baş bize düştü

N  e günah işledim ki,	N  iye sevmez yar düştü

Halit Demir   Erzincan - 10.07.2004', 'S  ana güzel baharlar,	B  ana kurak çöl düştü E  ser rüzgar savurur,	E  ndâma bir dert düştü N  asıl istemem seni,	N  âzende gülüş düştü S  ...', ARRAY['Türk Edebiyatı','Şiir','Halit Demir']::text[], 8.5, '{"poet":"Halit Demir","poet_slug":"halit-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-ben-akrostis-3-lu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-murat-bulus-dokrq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'koca yıllarım karanlıklar icinde gecdi,bilmiyerek umutsuzca sokak kenarlarında yarını olmayan bir ruh parcasıydım..taki seni tanıyana dek,bilmezdim yıldızların bu kadar parlak oldugunu,hayatın ne denli güzel oldugunu,sadece bir ruhdan değilde,yüregiminde bir anlamı oldu  sen dünyama girince güllüm..bazen ne kelimeler nede cümleler yetiyor seni anlatmaya..hani sonsuza dek ve ötesi diyorum ya..seni ne sonsuz nede ötesi seviyorum..ben seni bilinmeyen kelimelerle seviyorum...', 'koca yıllarım karanlıklar icinde gecdi,bilmiyerek umutsuzca sokak kenarlarında yarını olmayan bir ruh parcasıydım..taki seni tanıyana dek,bi...', ARRAY['Türk Edebiyatı','Şiir','Murat Bulus']::text[], 8.5, '{"poet":"Murat Bulus","poet_slug":"murat-bulus","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/sen-426-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arz-ı Hâl', 'arz-i-h-l-vedat-sahin-szebz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sorma dostum halim nice

Gamla doldum gündüz gece

Arz-ı hâli hece hece

Yazar oldum yazar dostum

Burda herkes aynı telden

Anlamazlar benim hâlden

Gurbet denen yaban elden

Uzar oldum uzar dostum

Çoğu zaman berduş gibi

Sokaklarla sırdaş gibi

İnle cinle gardaş gibi

Tozar oldum tozar dostum

Erken küstü hayat bana

Gitti kervan kaldım sona

O gün bugün yana yana

Gezer oldum gezer dostum

Gönül evim sanki pazar

Her kareye kanım sızar

Mezarımı azar azar

Kazar oldum kazar dostum

12.01.2001 Esting', 'Sorma dostum halim nice Gamla doldum gündüz gece Arz-ı hâli hece hece Yazar oldum yazar dostum Burda herkes aynı telden Anlamazlar benim hâl...', ARRAY['Türk Edebiyatı','Şiir','Vedat Şahin']::text[], 8.5, '{"poet":"Vedat Şahin","poet_slug":"vedat-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/arz-i-hal-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanete Dair...', 'i-hanete-dair-vedat-sahin-qw9qy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elde olsa kazısam, sözcüklerden kökünü

Kaldırsam gönüllerden, katır çekmez yükünü

Çıkarsam ipliğini, beş paraya pazara

Bir ikindi göndersem, sonsuza dek mezara

Beklese yılan çiyan, dört gözle yollarını

Ayırsa birbirinden, o cansız kollarını

Ve eylese gönüller, manzarayı temaşa

İzinden eser kalmaz, tüm gönüller pür neşe

O günleri görürsem, ihanet bir gün elbet...

Her gün benden ruhuna, yedi defa el Tebbet! ! ! 

19.06.2004 Esting', 'Elde olsa kazısam, sözcüklerden kökünü Kaldırsam gönüllerden, katır çekmez yükünü Çıkarsam ipliğini, beş paraya pazara Bir ikindi göndersem,...', ARRAY['Türk Edebiyatı','Şiir','Vedat Şahin']::text[], 8.5, '{"poet":"Vedat Şahin","poet_slug":"vedat-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ihanete-dair-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MaT', 'mat-ahmet-aksoy-9lrmu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'aklını törpülerken günler

toplumu dermek derdi şiir

o büyük bir düştür kendi küçük

.....çocuklar gibi

*

kalpazanlar dört döner

.....erdemler türer pisliklerden

insan derin siyah

....karanlıkdır gölgesinden

ışıktan kaçar 

/

derindir şairin düşü

.............kendi ödün

kopar bir gün zembereğinden

umarsız ölür 

+

siyahı yak 

...henüz vakit varken

gerisi boşdur 

....ne kalır 

erkinin izinden başka

-

büyük aydınlık 

..yok edecek her rengi

yalnız uyum kalacak', 'aklını törpülerken günler toplumu dermek derdi şiir o büyük bir düştür kendi küçük .....çocuklar gibi * kalpazanlar dört döner .....erdemler...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/mat-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzam II', 'uzam-ii-ahmet-aksoy-h0sgu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'her nokta kendini simgeler

yaşam büyür kök

dallandı budaklandı o ilk söz

bahsi ateş ve duman

evrenine kaçtı 

.......evrenden doğan

........................yalnızlık

süzüldü ruh

..........meleklerden

..........................ardıl

tan ağarmamışdı henüz

..........çocukluk

tek noktaya tapındı ilk insan

........diğerleri gibi

peki ya kalem dedi şair

.....noktayı yazan

her nokta bir noktadansa

o ilk nokta nerde ve nasıl

............doğruldu olduğu noktaya?', 'her nokta kendini simgeler yaşam büyür kök dallandı budaklandı o ilk söz bahsi ateş ve duman evrenine kaçtı  .......evrenden doğan ............', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/uzam-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanca III', 'i-nsanca-iii-ahmet-aksoy-1uq8d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'insanız, uzuvlarımız kısa

ermek bir noktaya

.........yetersizdir ruha

erilmek gerek onmaya', 'insanız, uzuvlarımız kısa ermek bir noktaya .........yetersizdir ruha erilmek gerek onmaya...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/insanca-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durgundu Aksin', 'durgundu-aksin-ahmet-aksoy-keom3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kefen sarısı,

........sarmıştı seni,

ölüydün onmaya,

ayrılık yetmezdi şüphesiz,

....bilinçlere ulaşmaya,

daha fazla daha fazla', 'kefen sarısı, ........sarmıştı seni, ölüydün onmaya, ayrılık yetmezdi şüphesiz, ....bilinçlere ulaşmaya, daha fazla daha fazla...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/durgundu-aksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '***Olsaydı Yıkılırdı Karşı Dağlar', 'olsaydi-yikilirdi-karsi-daglar-nurten-altinok-ixgkx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşatmaktı tüm çaban bubam

Yorgun ellerindi tek servetin

‘yarın’ öyle karanlıktı ki! 

İki dönüm toprağın yoktu ekeceğin

Oturup umut edeceğin

Ana yok, buba yok 

	

Bubaların en iyisi

Benim öksüzüm 

Hasan agam

Biz iki kızandık, bir de anam

Bilirim acıydı çektiklerin bubam

Bayram günlerini sorma

Anlatamam

Çocuktuk işte, istedik bir şeyler

Bulamayınca ağladık belki

Affeder misin  bubam

	

Bubaların en iyisi

Benim canım 

Hasan agam

Aç gezdin mi bizim için 

Bilemem 

Söylemedin ki

O sessiz duruşun var ya

Gözlerin bir noktaya çivili

Önce ölümler yıktı seni

Fakirlik kırdı belini

Sonra evlat hasreti

Hep içinde büyüttün derdini

Sığındığın

Bir:	

‘’ Off! Off! ‘’

—Olsa da 

Yıkılsa karşı dağlar-

Hepsi bu

Yok ötesi

Bubam

	

Bubaların en iyisi

Benim dertlim 

Hasan agam...', 'Yaşatmaktı tüm çaban bubam Yorgun ellerindi tek servetin ‘yarın’ öyle karanlıktı ki!  İki dönüm toprağın yoktu ekeceğin Oturup umut edeceğin...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/olsaydi-yikilirdi-karsi-daglar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bey Dağı', 'bey-dagi-yasar-yildiz-y65rc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bey Dağı..! 

Bey Dağı..! 

Saklama başını bulutlara.

Yüzün varsa,

aç gözlerini de bak bana.

Bilesin ki komam yanına.

Geri ver benden aldıklarını.

Üzerinde turnalar uçurtmam.

Ağaçlarına eşli üveyikler kondurmam.

Buz gibi pınarların olsa da,

yavrulu ceylanlara su içirtmem.

Kuruturum yeşilini.

Ne kar,

ne yağmur,

bir damla su yağdırmam.

Bey Dağı..! 

Vermezsen yine de aldıklarını,

Ferhat ın olurum.

Un ufak ederim koyaklarını.

Toz ederim, savururum

taşlarını kayalarını.

Kerem in olurum 

Bey Dağı

Yüreğim yanar köz gibi.

Bedenim,

tırnak uçlarıma kadar.

Yanarım, yanarım da,

seni de yakarım Bey Dağı.

Dağların şahısın sen.

Dağların padişahısın sen.

Büyüklük sende kalsın.

Hadi ver Bey Dağı.

Benden koparırcasına aldıklarını.', 'Bey Dağı..!  Bey Dağı..!  Saklama başını bulutlara. Yüzün varsa, aç gözlerini de bak bana. Bilesin ki komam yanına. Geri ver benden aldıklar...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Yıldız']::text[], 8.5, '{"poet":"Yaşar Yıldız","poet_slug":"yasar-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bey-dagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Sağnağı Gözlüm', 'gece-sagnagi-gozlum-adnan-durmaz-9j253', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dünyalar açılır püren dalında

can sığınır kevene

susuz vadilerden esen yel

	kovgun bir ağıt

sen de bu sürgünü

var git arama

ko duldasız kalsın yürek

kekiğim 

türkü bakışlım... 

bin yıllar sayfa sayfa devrildi

bin yıllar savruldu

deli taylarla ardarda aşılan dağlar

hep aynı yere vardı

hiçbir sayfasında bozkırın

	yüreklerde gül açmadı

		gönüllerde kan açtı

yürekte hançer oldun ey aşk

ihanet oldun bunlu zamanda

kara gurbet oldun

	geri dönmemesine

umut oldun da 

	yaktılar sabrın ateşlerinde

düş oldun

kanayan zamanlarda

baş koymak nazlı yarin

umut goncası memelerine

uyumak

	ve arınmak acıdan

		sonsuzca

zulüm oldun ey aşk

binyılların cümle kitaplarında

can aldın kıran kıran

	kan döktün

şahan boylar devirdin

her dağın ardında

umutlar beklerdi de

acı yağması keserdi

	sevda sağları

insan ki hasretlerde 

	tepeden tırnağa gönül kesilirdi

küçülürdü can

	sonsuz karanlıklarda

		büyürdü kaygı

umutlar yana yana

	kül kesilirdi

ferhatı ferhat eyledin ey aşk

deldi dağları dağları

madem ki sevdamıza

	kavuşmamak biçilmiş

ko gitsin

yana yana bozkırlarda

kekiğim

gece sağnağı gözlüm...

adnan durmaz,bilirsin aşk da serseri,art yay,ank,2003', 'dünyalar açılır püren dalında can sığınır kevene susuz vadilerden esen yel 	kovgun bir ağıt sen de bu sürgünü var git arama ko duldasız kals...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/gece-sagnagi-gozlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalmadı', 'kalmadi-yusuf-koc-qxhcb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Daha ne diyeyim sevda üstüne,

Kelime kalmadı dilimde benim,

Bilmem kimler kulak verir sesime,

Umarım kalmadı elimde benim.

Büyük dağın eteğinde yol olur,

Kıvrılır bükülür sonu sel olur,

Bu gidişle aklım fikrim del olur,

Düşünce kalmadı serimde benim.

Terkediyor aşık yurdu vatanı,

Bulamaz aşkına çatı çatanı,

İpek diye giyer çulu keteni,

Mintanım kalmadı tenimde benim.

Çareler ilaçlar bir gün bitecek,

Canlı olan hep bu yoldan geçecek,

Kalan.. aciları yine çekecek,

Hevesim kalmadı gönlümde benim.

Nasılsa tükenir sayılı nefes,

Rüzgara buyurdum başka yerde es,

Gün olur kesilir Koç Ozan''da ses,

Kimseler kalmadı türümde benim.', 'Daha ne diyeyim sevda üstüne, Kelime kalmadı dilimde benim, Bilmem kimler kulak verir sesime, Umarım kalmadı elimde benim. Büyük dağın eteği...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Koç']::text[], 8.5, '{"poet":"Yusuf Koç","poet_slug":"yusuf-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kalmadi-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelme Bana', 'gelme-bana-mehmet-kindap-m2jc2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yağmur yağıyor,sarhoşum

Sırılsıklamım üstelik

Ayakuçlarıma çaresizliğim akıyor gözlerimden

Yok,yok bu karanlık gecelerin sabahı biliyorum

Yok o en güzel aydınlık

Artık,artık bir başka ıklimin 

Rüzğarları yalayacak saçlarını

Başka sevdalar çiçek açacak gönlünde

Renk renk,mevsim mevsim biliyorum

Ben hergün biraz daha unutulmuş

Biraz daha sırılsıklam

Hergün biraz daha yitik ben

Sensiz insanca yaşamak

Sensiz mutluluk yok biliyorum

Sarhoş nağraları başlıyor uzaklarda

Rezilce bir arzu beliriyor yüreğimde

İçmek istiyorum

Sensiz şarkılar başlıyor gecelerde

Seni içtiğim zamanlar

Daha iyi düşünebiliyorum

Yokluğuna her kadeh kaldırışımda

Hayalin geçiyor gözlerimden

Özlem özlem

Sen kilometrelerce uzakta bile olsan 

Tutabiliyorum ellerinden

Saçlarını okşıyabiliyorum üstelik

Bana her kadehte biraz daha yaklaşıyor varlığın

Çaresizim ama mutluyum

Benim için sen varsın hala

Ebediyen yaşayacak anılarımız var

Aşkımız var

Senin için acı çekmek bile güzel..

İstemem yanımda olmanı gelme bana

Okşamak istemem avuçlarımda saçlarını

Bir şarkı gibi kal çook uzaklarda

Yokluğun aşkların en güzel olanı

(Eylül-1969- Konya)', 'Yağmur yağıyor,sarhoşum Sırılsıklamım üstelik Ayakuçlarıma çaresizliğim akıyor gözlerimden Yok,yok bu karanlık gecelerin sabahı biliyorum Yo...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kındap']::text[], 8.5, '{"poet":"Mehmet Kındap","poet_slug":"mehmet-kindap","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gelme-bana-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-mehmet-kindap-5a791', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün son defa buluşacak bakışlarımız

Ellerimiz son defa birbirine değecek

Gözlerimizden okunacak ayrılığımız

Sonra aramıza seneler girecek

Yoluna serdiğim umutlarımı çiğniyerek 

Biliyorum bugün bırakıp gideceksin

O güzelim yüzünle gülümseyerek

Ne yapalım kader bu diyeceksin

Dudaklarımda acı bir tebessüm belirecek

Deliler gibi kendime güleceğim

Saatimde ayrılık vaktimiz demirleyecek

Sana ve aşkıma veda edeceğim

Sonra tanımamış olacağız birbirimizi

Yaşantılarımıza başkaları girecek

Bir gün gelin götürecekler seni

Duvağını yaban eller derecek

Hergün mutluluğunu müjdeliyecek karayel rüzğarı

Senin için çocuklar gibi sevineceğim

Örtüp ellerimle eski hatıraları

Yeni aşkına ve saadetine içeceğim

                            (1967 Ankara)', 'Bugün son defa buluşacak bakışlarımız Ellerimiz son defa birbirine değecek Gözlerimizden okunacak ayrılığımız Sonra aramıza seneler girecek ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kındap']::text[], 8.5, '{"poet":"Mehmet Kındap","poet_slug":"mehmet-kindap","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ayrilik-176-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dikmen Sırtlarında', 'dikmen-sirtlarinda-mehmet-kindap-njo5o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dikmen sırtlarında bir rüzğar eser

Eser incecikten sevda rüzğarı

Dağıtır gönülde tüm efkarları

Ellerini bende unutmuşsun sen

Dikmen sırtlarında bir rüzğar eser

Eser incecikten sevda rüzğarı

Dağılır rüzğarda güzel saçların

Ümitsiz ve mutsuz o akşamların

Kopar karanlıkla bütün bağları

Eser incecikten sevda rüzğarı

Dağılır rüzğarda güzel saçların

Bakışlarım arar da gözlerini

Bir bilinmez derde götürür beni

Seni kaybetmekten korkarım aşkım

Dağılır rüzğarda güzel saçların

Bakışlarım arar da gözlerini

Yaşantılar susar da gecelerde

Yeniden yaşantım başlar gözlerinde

Anlarım seni ne denli sevdiğimi

Bakışlarım arar da gözlerini

(1970 Ankara)', 'Dikmen sırtlarında bir rüzğar eser Eser incecikten sevda rüzğarı Dağıtır gönülde tüm efkarları Ellerini bende unutmuşsun sen Dikmen sırtları...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kındap']::text[], 8.5, '{"poet":"Mehmet Kındap","poet_slug":"mehmet-kindap","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dikmen-sirtlarinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adsız', 'adsiz-yusuf-koc-qd74w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Usandım zamanın çilelerinden,

Yarın ne olacak göremiyorum,

Bunaldım yaptığı yanlış işlerden,

Şu insanoğlunu çözemiyorum.

Bugün dediğini yarın unutur,

İp üstünde beyaz unu kurutur,

Yeri gelir der ki tuzum kurudur,

Dilim tutuluyor diyemiyorum.

Söz tutulmaz çek senetler iddalı,

On kişiyi saysam dokuz davalı,

Köylü garip şehirlisi havalı,

Bir ucdan bir uca eremiyorum.

Erkekler değişmiş halleri bir hoş,

Bazısı adına dedirtir nonoş,

Bu hali görürüm olurum sarhoş,

Adam diye göğsümü geremiyorum.

Burnuna kaşına halkalar takmış,

Sırtında döğme var göbeği açmış,

Başında rengarenk bir şey var..! saçmış,

Nasıl moda imiş bilemiyorum.

Ben mi kaldım çok gerisinde çağın,

Renkleri değişti yeşil yaprağın,

Fosilsin diyorlar yerin toprağın..! 

Uymuyor elbise giyemiyorum.

Hani nerde mert yürekli efemiz,

Hep yanlış tartıyor şimdi kefemiz,

Kadınlar silikon adamlar semiz,

Doğru kapılardan giremiyorum.

Hukuk var diyorlar paran var ise,

Fakirin şansı yok girsin meclise,

Aybaşı gelmiyor..! haklı delirse..! 

Maaşlı memuru yeremiyorum.

Şimdi Koç Ozan''a kuşkulu bakın,

Kırın kalemini kelepçe takın,

Yakın bu şiiri gönlünü yıkın,

Daha ağır ceza veremiyorum.', 'Usandım zamanın çilelerinden, Yarın ne olacak göremiyorum, Bunaldım yaptığı yanlış işlerden, Şu insanoğlunu çözemiyorum. Bugün dediğini yarı...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Koç']::text[], 8.5, '{"poet":"Yusuf Koç","poet_slug":"yusuf-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/adsiz-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şiirlerim', 'bu-siirlerim-bayram-tunca-85l1k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu şiirlerim ölümümden sonra yayınlansın

Şairler ve ozanlar, tarafından yorumlansın

Eğer ki suçluysam yargılasın beni hakimler

Bir aşığa verilecek en ağır cezayı versinler

Gerekirse mezarımı açıp otopsi yaptırsınlar

Kalbimdedir tüm sırlarım kalbime baksınlar

Eğer suçluysam idamlık mührünü bassınlar

Aşka ihanetten, saçlarım adedince assınlar

B. Tunca/11.07.2004-11.11', 'Bu şiirlerim ölümümden sonra yayınlansın Şairler ve ozanlar, tarafından yorumlansın Eğer ki suçluysam yargılasın beni hakimler Bir aşığa ver...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bu-siirlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağıt I', 'agit-i-ahmet-aksoy-0vgow', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'geç kaldığım çocukluk

...........hayatımın güzel yanı

merak ve sorgu çağı

.......her şey pembedir

............duyumsamalar bildirir

yaşayamadığım gençliğim

......parasız, aşksız

ve çoğu zaman işsiz

dertten fırsat bulamadığım 

......................mutluluk

hissetiğim yaşlılığım

.........her şeyin gerçek yüzü

ağır ve keskin bir kokuydu

..................................zaman

.......tutamadım burnumu', 'geç kaldığım çocukluk ...........hayatımın güzel yanı merak ve sorgu çağı .......her şey pembedir ............duyumsamalar bildirir yaşayama...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/agit-i-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsteyiş', 'i-steyis-deniz-onderoglu-cxoez', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akşam olduğunda 

Yatağına yattığında

Gözlerini kapadığında

Karşında beni görmeni isterim

Sabah olduğunda

Yatağından kalktığında

Pencereni açtığında

Karşımda seni görmek isterim', 'Akşam olduğunda  Yatağına yattığında Gözlerini kapadığında Karşında beni görmeni isterim Sabah olduğunda Yatağından kalktığında Pencereni aç...', ARRAY['Türk Edebiyatı','Şiir','Deniz Önderoğlu']::text[], 8.5, '{"poet":"Deniz Önderoğlu","poet_slug":"deniz-onderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/isteyis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-deniz-onderoglu-eqsip', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu dünyada herşeyi sevmek istedim

Ağaçları, kuşları, bulutları ve gökyüzünü

Fakat, bir gün seni gördüm

Ve tüm sevgimi sana verdim', 'Bu dünyada herşeyi sevmek istedim Ağaçları, kuşları, bulutları ve gökyüzünü Fakat, bir gün seni gördüm Ve tüm sevgimi sana verdim...', ARRAY['Türk Edebiyatı','Şiir','Deniz Önderoğlu']::text[], 8.5, '{"poet":"Deniz Önderoğlu","poet_slug":"deniz-onderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevgi-129-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir ara herşeyi sen zannetim, belkide öyleydi...', 'bir-ara-herseyi-sen-zannetim-belkide-oyleydi-lzcramcil-ceyhun-erdem-ml3j1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gökyüzünü sildi bakışlarım,

ve bir ara herşeyi sen zannettim

öyle çok karardı ki gözlerim; rengini gördüğümde güzelliğinden 

içim burkuldu yeşilinden, mavisinden gözlerinin, 

teninin esmerliğinden

-balkondaki iplerine çamaşır asamıyor karşıdaki komşu teyze-

-kıyamıyor çiçeklerinin yapraklarına değip zarar vermeye-

Gökyüzünü sildi bakışlarım,

düşüp toprağa yüz sürdüm...

koşup peşimden gelmişsin şimdi anladım,

yeniden dünyaya gelişimde yüzün ilk gördüğüm.

üstüme sinmiş kokun...

-her tümsekten geçişinde tekerlekler bir adım daha yaklaşıyorum tenine-

-ne olurdu biraz daha yaklaşabilsem-

-hani ellerini öpmek filan olsa-', 'Gökyüzünü sildi bakışlarım, ve bir ara herşeyi sen zannettim öyle çok karardı ki gözlerim; rengini gördüğümde güzelliğinden  içim burkuldu y...', ARRAY['Türk Edebiyatı','Şiir','Lzcramcil Ceyhun Erdem']::text[], 8.5, '{"poet":"Lzcramcil Ceyhun Erdem","poet_slug":"lzcramcil-ceyhun-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-ara-herseyi-sen-zannetim-belkide-oyleydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Peri', 'mavi-peri-mustafa-demirbas-mnaof', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mavi peri isminde, bir masal kızı varmış,

Dinlediği hakikat, anlattığı masalmış,

Aşk demiş, sevda demiş, avunup durmuş işte,

Taş kalbinin içinde hayaller kurmuş işte.

Saatlerce muhabbet, kendinden geçiyormuş,

O kendine her dönem bir sevda seçiyormuş,

Tuzağını kurmuştu, örümcek geldi bize,

Nice sahte sözler var, şeytanlar gelir dize...

Dulkurusu kaprisli, kibirli ve ahlaksız,

Bana göre bu peri, şeytandan daha farksız,

Bir kelime etmeden kapıları kapatmış,

Gerçeklerden kaçmışta, ruhunu pula satmış.

Her zaman ağlamaya mahkum ol sahte peri,

Kendinden kaç kendinden beter ol kahpe peri...

Allah''ın kullarını hor görür durursun hep,

Sevenleri değil de kendini vurursun hep...

Aşk atın sakatlandı artık yürümez seker,

Kimse bakmaz yüzüne tümseğe düşer Teker

Kalana selam olsun. Vay burnu büyük peri,

Ben yokum artır dersin, Vay budala serseri...

Kutlarım seni peri, güzelini yapmışsın.

Kendini ilah sanıp tek kendine tapmışsın.

Görme sakın kimseyi, girme sakın kanına...

Elli Üçün güzeli, bu yakışmaz şanına...

Yalnızlığa mahkumsun, bunu kendin istedin,

Benden daha güzeli, soylusu yoktur dedin,

Aynan kandırır seni, ama sen göremezsin,

Ağlamaya mahkumsun ömrünce gülemessin', 'Mavi peri isminde, bir masal kızı varmış, Dinlediği hakikat, anlattığı masalmış, Aşk demiş, sevda demiş, avunup durmuş işte, Taş kalbinin iç...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Demirbaş']::text[], 8.5, '{"poet":"Mustafa Demirbaş","poet_slug":"mustafa-demirbas","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/mavi-peri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Körpecik Haylaz', 'seni-korpecik-haylaz-i-smet-barlioglu-wv77p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni küçük işvebaz,

Yapma bana fazla naz,

Gönlüm nazdan anlamaz

İltifat sanır bunu.

Seni şirin düzenbaz,

Yüreklerle oynanmaz,

Gönlüm bunlara kanmaz

Şatafat sanır bunu.

Seni tatlı hiylebaz,

Sevilmeyen aranmaz,

Gönlüm buna inanmaz

Letafet sanır bunu.

Seni kurnazdan kurnaz,

Gülden yağrak budanmaz,

Kalp aldanır aldanmaz

Marifet sanır bunu.

Seni körpecik haylaz,

Sevmeyen mektup yazmaz,

Gönlüm neden aramaz

Muhabbet sanır bunu.

(ISLAK RÜZGARLAR isimli hece şiirlerinden > 50-51/100)', 'Seni küçük işvebaz, Yapma bana fazla naz, Gönlüm nazdan anlamaz İltifat sanır bunu. Seni şirin düzenbaz, Yüreklerle oynanmaz, Gönlüm bunlara...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/seni-korpecik-haylaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olur', 'ne-olur-i-smet-barlioglu-uj7k2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Rüzgarda ufanmış kumlara döndüm,

Parıltısı bitmiş pullara döndüm,

Senin eşiğinde kullara döndüm,

Ne olur bir dön bak, bir kez ilgilen.

Gündüzlerim oldu tükenmez gece,

Sabah zor oluyor insan sevince,

Bana bir kez olsun şöyle gönlünce

Ne olur bir dön bak, bir kez ilgilen.

Kuşatıp yağmayan bulut gibisin,

İçimde yeşeren umut gibisin,

Ateşe serpilen barut gibisin,

Ne olur bir dön bak, bir kez ilgilen.

(ISLAK RÜZGARLAR isimli hece şiirlerinden > 52-53/100) 

Ne olur bir dön bak, bir kez ilgilen.', 'Rüzgarda ufanmış kumlara döndüm, Parıltısı bitmiş pullara döndüm, Senin eşiğinde kullara döndüm, Ne olur bir dön bak, bir kez ilgilen. Gündü...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ne-olur-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usanamadım', 'usanamadim-i-smet-barlioglu-of0op', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüreğimde gamsın, gözlerimde yaş,

Damla yanağıma, düş yavaş yavaş,

Meğer seni sevmek ne tatlı uğraş; 

Bir ömür sevdim de usanamadım.

Rüzgarda sen varsın, yağmurlarda sen,

Güllerde nakışsın, tüllerde desen,

İçinde sen varsın her neyi görsem,

Esirin oldum da kurtulamadım.

Sallanan mendilsin giden gemide,

Hayalin ardından çeker beni de,

Tutunduğum dallar kaldı elimde,

Şansıma bir tek kez yaranamadım.

Bazan bir feryatsın kulaklarımda,

Bazan bir sızısın şakaklarımda,

Bir buruk türküsün dudaklarımda,

Kaç kere ağladım, dayanamadım.

Güneş batar batmaz artar elemim,

Herbiri bir yüzyıl olur gecemin,

Ömrümü tükettim ardında senin,

Bıkmadım, yılmadım, duralamadım.

(ISLAK RÜZGARLAR isimli hece şiirlerinden > 54-55/100)', 'Yüreğimde gamsın, gözlerimde yaş, Damla yanağıma, düş yavaş yavaş, Meğer seni sevmek ne tatlı uğraş;  Bir ömür sevdim de usanamadım. Rüzgard...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/usanamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '***Karanlığında Boğuldu Yalnızlık', 'karanliginda-boguldu-yalnizlik-nurten-altinok-2sr1q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biz ne fırtınalar atlattık gülüm

Ne gemiler batırdık karada

Geceler yaşadık

Karanlığında boğuldu yalnızlık

Sevdik / sevildik

Gözyaşı

Unuttuk / unutulduk 

Sabır taşı

Olmasını bildik

Yeri geldi

Ekmeğimizi batıracak suyumuza

Yüreğimizi tas eyledik

Yeri geldi

Bir güle 

Bin dikeni

Sineye çektik

Sen hafif kalırsın gülüm

Ne eski yaraya 

Tuz 

Olursun

Ne yeniye

Umut

Varsa toprağın 

Git

Ser bulutlarını oraya 

Varsa kapın 

Git 

Onu tıkla

Sen hafif kalırsın gülüm

Haydi, başka kapıya...', 'Biz ne fırtınalar atlattık gülüm Ne gemiler batırdık karada Geceler yaşadık Karanlığında boğuldu yalnızlık Sevdik / sevildik Gözyaşı Unuttuk...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/karanliginda-boguldu-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tamlanmaz', 'tamlanmaz-ahmet-aksoy-hnw0n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kirlenmiş bir çarşaf gibi

..........sıyrılmışım yüreğimden

hani kimsenin istemediği

....tozlanmışım

..........terk edilmiş bir kitap gibi

içi meçhul yazarı belli

ne sırlar saklamışım

.......ne de sevgiler

oralı olmamış hiç kimse

kendiyle yetinir insan

............ben sen ve onlar

bizi arzularken

...........tekil usum

......çölde serapmış ortaklıklar

kılcal soru 

....kim kimi tamlar', 'kirlenmiş bir çarşaf gibi ..........sıyrılmışım yüreğimden hani kimsenin istemediği ....tozlanmışım ..........terk edilmiş bir kitap gibi iç...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tamlanmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağladım Kana Kana', 'agladim-kana-kana-i-smet-barlioglu-d3xi2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün de yağmur yağdı, sızlattı yüreğimi,

Yine maziyi andım yakılıp yana yana.

Özlemler engelledi biricik dileğimi,

Ağladım pencerede, ağladım kana kana.

Yağmuru görmeyeyim; dönüyorum maziye,

Budur yağmurun bana getirdiği hediye,

Ömrüm tükenip gitti hep bekleye bekleye,

Bir gün yağmur altında dönersin sana sana.

Yağmur yağıp durdukça ıslanıyor yanağım,

Yanıyor kavrularak senin için dudağım,

Ben mahzun sonbaharda daldaki tek yaprağım,

Şu eriyip tükenmiş duruşuma baksana.

Seni böyle yağmurda uğurladım mendille,

Kanattım yüreğimi en yabani dikenle,

Sevmeyen bir olur mu, hiç yürekten sevenle? 

Seviyorsan gelsene, bu kadar durmasana.

(Hikmet BARLIOĞLU (1933-2003)  ''nun

ISLAK RÜZGARLAR isimli hece şiirlerinden > 58-59/100)', 'Bugün de yağmur yağdı, sızlattı yüreğimi, Yine maziyi andım yakılıp yana yana. Özlemler engelledi biricik dileğimi, Ağladım pencerede, ağlad...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/agladim-kana-kana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtulamadım', 'kurtulamadim-i-smet-barlioglu-ik7cu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çiçekli bahçeler yine mi sensiz? 

Yine mi yamaçlar kimsiz kimsesiz? 

Seni özlüyorum ağızsız dilsiz,

Özlemden ömrümce kurtulamadım.

(ISLAK RÜZGARLAR isimli hece şiirlerinden > 60/100)', 'Çiçekli bahçeler yine mi sensiz?  Yine mi yamaçlar kimsiz kimsesiz?  Seni özlüyorum ağızsız dilsiz, Özlemden ömrümce kurtulamadım. (ISLAK RÜ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kurtulamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ab-u Hayatımsın', 'ab-u-hayatimsin-muammer-celik-x5uvx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sen,

kendi içinde biriken 

yeraltı gölüsün

ben 

kıvrım kıvrım denize giden

yeraltı ırmağıyım…

Yatağım boş

sularınla coş

ve ak içimden

doldur aşk ırmağımı

sularınla

sulansın tüm içdünyam

mavi gezegenin

yeşiline, mavisine

can verelim canımızdan

besleyelim duyguların en güzelini

gül kırmızısı akan

damarımızdaki sevda mavisi kanımızdan...

Ben bir şey yapmıyorum sana

sen çok şey yapıyorsun bana

içgölündeki suları salıyorsun sel sel üstüme

doluyor ırmak yatağım

taşıyor damarlarım

ve akıyorum seni yer yer

kıvrım kıvrım içimden

senin aşk gölünden

doyumun deryasına

sevdanın dünyasina

mavi gezegen denilen

yer kürenin göbeğine

Alp dağlarının karlarından eriyip

çaylarından, yar’larından süzülüp

Ponte Tresa gölüne dökülüp

öylece duruyorum

suyunla coşuyorum

suyunla duruluyorum

suyuna dalıyorum

suyunda yüzüyorum

Suyundan içip kanıyorum

suyunda boğuluyorum

ve seninle ölüp ölüp diriliyorum…

İşte böylesine sende

Ab-u Hayat buluyorum…! 

BirDeli

11.07.2004', 'sen, kendi içinde biriken  yeraltı gölüsün ben  kıvrım kıvrım denize giden yeraltı ırmağıyım… Yatağım boş sularınla coş ve ak içimden doldur...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/ab-u-hayatimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık o zamana geri dönemem', 'artik-o-zamana-geri-donemem-hasan-can-viqar', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana birşey diyemem 

Yaramı tekrar deşemem 

Sorma bana geçen zamanı 

Artık o zamana geri dönemem...', 'Sana birşey diyemem  Yaramı tekrar deşemem  Sorma bana geçen zamanı  Artık o zamana geri dönemem......', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/artik-o-zamana-geri-donemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuz Olan Sevgiler', 'sonsuz-olan-sevgiler-hasan-can-feis8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgiler yasaklıdır

