INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimseye', 'kimseye-alper-gultekin-vsnts', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kimseye; 

Zengin Diye Sevgi Duymadım 

Alkışlayıp ellerimi yormadım 

Kimseyi Fakir Diye Küçümsemedim 

Hor Görüp bir tarafa itmedim 

Kimseye Güzel diye aşık olmadım 

Sırılsıklam yanıp tutuşmadım 

Kimseyi çirkin diye incitmedim 

Çirkini güzeli görebildim 

Kimseyue çıkar için boyun eğmedim 

İki yüzlülük etmedim 

Kimseye yapma gülücükler iltifatlar sunmadım 

Gerçek duygularımla haykırmaya çalıştım 

İnsan olarak geldim şu dünyaya 

Sadece dürüst olarak yaşamaya çalıştım...', 'Kimseye;  Zengin Diye Sevgi Duymadım  Alkışlayıp ellerimi yormadım  Kimseyi Fakir Diye Küçümsemedim  Hor Görüp bir tarafa itmedim  Kimseye G...', ARRAY['Türk Edebiyatı','Şiir','Alper Gültekin']::text[], 8.5, '{"poet":"Alper Gültekin","poet_slug":"alper-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kimseye-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliğin Sesi', 'sensizligin-sesi-alper-gultekin-qcdvy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akşamı getiren sesler susunca 

Gönül rıhtımına bir gemi yanaşır 

Hayalin gelir gözlerimin önüne 

Seni alır benden sessizce uzaklaştırır 

Artık sensizlik ve sessizlik vardır 

Yıuldızlarla dertleşirim anlamazlar beni 

Sorarım karanlık geceye çarem nerede diye 

Bilmezki derdimin sensizlik oldugunu 

Birazdan şafak söker güneş doğar umutlara 

Alır götürür beni kaybolan duygulara 

İsyanları acıları terk ederim dağlara 

Özleminle sarılırım gelecek yarınlara...', 'Akşamı getiren sesler susunca  Gönül rıhtımına bir gemi yanaşır  Hayalin gelir gözlerimin önüne  Seni alır benden sessizce uzaklaştırır  Art...', ARRAY['Türk Edebiyatı','Şiir','Alper Gültekin']::text[], 8.5, '{"poet":"Alper Gültekin","poet_slug":"alper-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensizligin-sesi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçmalığa Övgüler-11', 'sacmaliga-ovguler-11-oguzkan-bolukbasi-dorgx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Devrilmiş bir gecenin ardından

Bakakalırım hayatıma

Güneşin tutsağı

Sinsice işler damarlarıma sıcağı

Kımıldayamam 

Sana bakmama izin verdiğin için

Müteşekkir olayım

Sorma nedendir

Kimbilir

Kımıldamak içindir belkide

Belkide kaybolmak içindir

Nefesimi tutuyorum sen yanımdan geçince

Nefesimi tutuyorum ki

Belki zaman durur

Güzel bir anında hayatın

Ve bakarken ölürüm gözlerine

De gözlerinle giderim bilinmeyen yerlere

Bilinmeyen gemilerde

Zaman yürür

Ben yapışmış olurum bir resmin ucuna

Gözlerim göreceğini görmüştür

Bir film senaryosundaki gibi

Alaycı kader

Ağlarını örmüştür

Sen geçip gidersin

Ben o camın ardında kalırım

Yağmurda 

Sadece benim yaşadığımla baş başa

Haberin bile yoktur

Ben senin gözlerine asılacağım

Çek ipimi

Ölmeyi beceremiyorum gözlerinde', 'Devrilmiş bir gecenin ardından Bakakalırım hayatıma Güneşin tutsağı Sinsice işler damarlarıma sıcağı Kımıldayamam  Sana bakmama izin verdiği...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sacmaliga-ovguler-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kilitli Kaldı...', 'kilitli-kaldi-i-brahim-ethem-bingul-6u03d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kırmızı akşam üstlerinde

Gözümde yaşanmışlıkların mutluluğu

Kaybedilmiş uçurtmaların hüznü

Bu kısır döngüde

Alırım her nefesi,her anı...

Özlemlerim özüme bina kurdu

Sözlerim,sözcüklerin esiri

Gözlerim kırmızı akşam üstlerinde

Asuman''a kilitli kaldı...

www.iebingul.com', 'Kırmızı akşam üstlerinde Gözümde yaşanmışlıkların mutluluğu Kaybedilmiş uçurtmaların hüznü Bu kısır döngüde Alırım her nefesi,her anı... Özl...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kilitli-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol', 'yol-eren-evren-ieece', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ölümün soğuk ateşi 

Yavaş yavaş eritiyor içimi 

Aynalar artık yalan söylemiyor

Yaşanan ve biten 

Koskoca bir ömrün izlerini taşıyor gözlerim', 'Ölümün soğuk ateşi  Yavaş yavaş eritiyor içimi  Aynalar artık yalan söylemiyor Yaşanan ve biten  Koskoca bir ömrün izlerini taşıyor gözlerim...', ARRAY['Türk Edebiyatı','Şiir','Eren Evren']::text[], 8.5, '{"poet":"Eren Evren","poet_slug":"eren-evren","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yol-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Sırtımdan Vurma..! !', 'beni-sirtimdan-vurma-nazife-abayli-dt920', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Değmesin elime,

Elinden başka el.

Değmesin tenime,

Teninden başka ten..

Beni bir yaşam boyu seveceksen eğer..

Kır yasakları,

Yüreğini de al öyle gel.

............................

Yitirmek nedir bilirim..

Ben ne aşklar yitirdim..

Vuruldum can evimden..

Tükendim,bittim,yerlere serildim..

Şimdi yorulsa da bedenim..

Doymadı ki aşka sevgiye,

Uslanmadı,aç yüreğim..

....................................

Sonsuza dek sadık kalırım sana..

Sev yeter ki,istersen gelme aylarca...

Hissedeyim varlığını,

Canınla can kat canıma..

Sakın ha sakın...

Asla..! ! 

Beni sırtımdan vurma..! !', 'Değmesin elime, Elinden başka el. Değmesin tenime, Teninden başka ten.. Beni bir yaşam boyu seveceksen eğer.. Kır yasakları, Yüreğini de al ...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/beni-sirtimdan-vurma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhtıra', 'muhtira-gulden-karabudak-gak03', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Vakti zamanıdır ahuzar gönlümün

Sevda neferi çöllerde direnmesi

Acıya sinmez,

Aşka tükenmezlik veren 

çocuk ruhumun…/

Yorgun gönüllerde dillenmesi

Ben olmadan da geçer zaman

Yordamını bilmediğim dünkü ellerde

Vakitsiz çığıran isyandır bakışım.

Zamanıdır gitmenin…

Boş gönüllerde boy göstermenin

Ehemmiyetsiz gülümsemelerin/…

Durağı değildir aşk! 

Varsın sevdalansın sinsi yorgunluk

Düşler çöksün üstüne apansız

Göğsüne kurdelalar bağlasın kara yemiş

Yeter ki bitmesin…

Duru bir ölüm değil midir! /

Ölümüm değil midir aşk! !', 'Vakti zamanıdır ahuzar gönlümün Sevda neferi çöllerde direnmesi Acıya sinmez, Aşka tükenmezlik veren  çocuk ruhumun…/ Yorgun gönüllerde dill...', ARRAY['Türk Edebiyatı','Şiir','Gülden Karabudak']::text[], 8.5, '{"poet":"Gülden Karabudak","poet_slug":"gulden-karabudak","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/muhtira-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşil gül', 'yesil-gul-zafer-zengin-etnika-tu0yh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sana

bırakılan

gül 

