INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '5Para', '5para-mehmet-dogan-9-geuwx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Daha arkadaşken verdiğin oyuncağı 

dün sattım oyuncakçıya.. 

5 paradan fazla veren olmadı 

senin ve aşkın gibi 

oyuncağında etmedi 

5 para....', 'Daha arkadaşken verdiğin oyuncağı  dün sattım oyuncakçıya..  5 paradan fazla veren olmadı  senin ve aşkın gibi  oyuncağında etmedi  5 para.....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Doğan 9']::text[], 8.5, '{"poet":"Mehmet Doğan 9","poet_slug":"mehmet-dogan-9","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/5para-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acaba', 'acaba-mehmet-dogan-9-a62t5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'şu yalan dünyada 

aşık olduklarım inletirken beni 

acaba platonik olanlar 

daha mı değerli?', 'şu yalan dünyada  aşık olduklarım inletirken beni  acaba platonik olanlar  daha mı değerli?...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Doğan 9']::text[], 8.5, '{"poet":"Mehmet Doğan 9","poet_slug":"mehmet-dogan-9","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/acaba-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuyorum', 'korkuyorum-mehmet-dogan-9-dwwqo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'öfkemin altında gizlidir sevgim 

ne kadar kızıyorsam 

o kadar seviyorum seni 

korkuyorum seni cok sevmekten...', 'öfkemin altında gizlidir sevgim  ne kadar kızıyorsam  o kadar seviyorum seni  korkuyorum seni cok sevmekten......', ARRAY['Türk Edebiyatı','Şiir','Mehmet Doğan 9']::text[], 8.5, '{"poet":"Mehmet Doğan 9","poet_slug":"mehmet-dogan-9","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/korkuyorum-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadberk', 'sadberk-mehmet-dogan-9-c2nb1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seninle basladı 

Akmaya zaman 

Dakika dakika saniye saniye 

Belki simdi daha cabuk 

Ebediyete intikal edeceğim ama olsun 

Razıyım buna üzülmüyorum 

Kalbimi sana verdim ölmüyorum...', 'Seninle basladı  Akmaya zaman  Dakika dakika saniye saniye  Belki simdi daha cabuk  Ebediyete intikal edeceğim ama olsun  Razıyım buna üzülm...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Doğan 9']::text[], 8.5, '{"poet":"Mehmet Doğan 9","poet_slug":"mehmet-dogan-9","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sadberk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selam', 'selam-mehmet-dogan-9-2uvel', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'şu kısa ömrüme ne aşklar sığdırdım 

kiminin platonikliği vardı 

kiminin yaşanmışlığı 

ya da benim yaşadığımızı sanmışlığım 

beni bir bir terkeden eski sevdiklerime 

şimdi senden selam söylüyorum 

terkettiklerine belki de ilk defa şükrediyorum...', 'şu kısa ömrüme ne aşklar sığdırdım  kiminin platonikliği vardı  kiminin yaşanmışlığı  ya da benim yaşadığımızı sanmışlığım  beni bir bir ter...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Doğan 9']::text[], 8.5, '{"poet":"Mehmet Doğan 9","poet_slug":"mehmet-dogan-9","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/selam-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alo Yalıkavak!', 'alo-yalikavak-naime-erlacin-kzj25', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'alo Yalıkavak

alo halk plajı

hazır et sofrayı

birlikte yiyeceğiz kafaları 

neyim mi var: 

hiç! 

taktım takıntılarıma sen gibi 

dellendim yalnızca

“ne işim var” dedim bu âlemde 

dolanırken gece gündüz üç gün üst üste

rehin verdim canımı şurada burada 

buza düşmüş kaz gibi her yerde

hepsi bu işte! 

tel’e net’e ne hacet

her zaman haklısın Yalıkavak

“şiir okumak bile intihardır” derken

aksisedan oldukça net

deniz kadar mavisin dostum

ak köpüklü

berrak 

ve yalansız

canlanıyor bozkır 

kükreyen nefesimde

döşümdeki sağır çölün 

çığlıkları inliyor sesimde

merak etme 

bir zarar gelmez kafa yemekten 

“akla ziyan” 

aklı dengeler bazen

geceden açılır gündüzün yolu

boşalır kütükler bağbozumunda

aydınlanır zihinler

keskin sirke değiliz küpümüze! 

(14 Temmuz 2004)    – “Yeni Dosya”dan…', 'alo Yalıkavak alo halk plajı hazır et sofrayı birlikte yiyeceğiz kafaları  neyim mi var:  hiç!  taktım takıntılarıma sen gibi  dellendim yal...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/alo-yalikavak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Renkler Ve Ben', 'renkler-ve-ben-sirma-mersin-5vrua', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kırmızı öfkem

Sarı hüznüm

Pembe sevgim

Beyaz yaşam

Siyah isyanım

Mavi mutluluğum

Yeşil umudum

Gökkuşağından çaldığım tüm renkleri

Kendi dünyamın içine döktüm...

Ruhumun her yansımasında

Renklerle seslendim, kadere...

06.07.04

''Renklerin Alemine Düştüğüm Bi Anda...''', 'Kırmızı öfkem Sarı hüznüm Pembe sevgim Beyaz yaşam Siyah isyanım Mavi mutluluğum Yeşil umudum Gökkuşağından çaldığım tüm renkleri Kendi düny...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/renkler-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Aşk Olsun', 'adi-ask-olsun-orhan-tuncay-5wmob', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Esen meltem kulağıma seni fısıldarsa

Kalbim kanat çarpan kuş hızıyla atarsa

İçim biteviye özleminle dolup taşarsa

Bunun adı aşk olsun

Görmezse gözlerim başka kimseyi

Tatmamışsam önceleri böyle sevmeyi

Bilmiyorsam artık gündüzle geceyi

Bunun adı aşk olsun

Sen bulutlarda dolaşıp, ben peşindeysem

Sen erişilmez, ben zavallı biçareysem

Sevginle deliysem, sevginle divaneysem

Bunun adı aşk olsun

Ben Mecnun gibiyken sen Leyla olsan

Bu sevda pınarından kanarak içiyorsam

Kor gibi yakıp ok gibi işlediyse sevdan

Bunun adı aşk olsun

Aşık Orhan der ki “Aşk her şeye değer”

Ateşinle ısındı,  gün gibi aydınlandı her yer

Bu ateşte eriyip,  yok olup gideceksem eğer

Bunun adı aşk olsun.', 'Esen meltem kulağıma seni fısıldarsa Kalbim kanat çarpan kuş hızıyla atarsa İçim biteviye özleminle dolup taşarsa Bunun adı aşk olsun Görmez...', ARRAY['Türk Edebiyatı','Şiir','Orhan Tuncay']::text[], 8.5, '{"poet":"Orhan Tuncay","poet_slug":"orhan-tuncay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/adi-ask-olsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamansız', 'zamansiz-cigdem-bir-genc-ggm6j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Adı yok bu şiirin

Sen varsın...

Adın yok...

Ansızın bastıran biz yaz yağmuru gözlerin

Sağanağındayım...

Tedbirsizim...

Yüreğim çırılçıplak...

Sen vakitsiz...

Oysa  prangaya vurmuştum  her bir bulutu kendi ellerimle tek tek...

Kim çözdü kilitlerini zamansız?', 'Adı yok bu şiirin Sen varsın... Adın yok... Ansızın bastıran biz yaz yağmuru gözlerin Sağanağındayım... Tedbirsizim... Yüreğim çırılçıplak.....', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Bir Genç']::text[], 8.5, '{"poet":"Çiğdem Bir Genç","poet_slug":"cigdem-bir-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/zamansiz-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-halil-i-brahim-ozdemir-vppzm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gurbetteyim, yorgunum, esiyorum yel gibi,

Caddeler ve sokaklar, kovalıyor el gibi 

Memleket hasretiyle o kadar doluyum ki

İçimde patlayacak, volkan gibi sel gibi…', 'Gurbetteyim, yorgunum, esiyorum yel gibi, Caddeler ve sokaklar, kovalıyor el gibi  Memleket hasretiyle o kadar doluyum ki İçimde patlayacak,...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özdemir']::text[], 8.5, '{"poet":"Halil İbrahim Özdemir","poet_slug":"halil-i-brahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hasret-179-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başka Bir Deyişle...', 'baska-bir-deyisle-can-ceylan-ftcae', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'S evgi

E n

N amuslu

İ htirastır

S öylenmesinin

E rişilmezliği

V e

İ mkansızlığı

Y oktur

O nsuz

R üyalarda

U nutulmaya

M ahkumdur', 'S evgi E n N amuslu İ htirastır S öylenmesinin E rişilmezliği V e İ mkansızlığı Y oktur O nsuz R üyalarda U nutulmaya M ahkumdur...', ARRAY['Türk Edebiyatı','Şiir','Can Ceylan']::text[], 8.5, '{"poet":"Can Ceylan","poet_slug":"can-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/baska-bir-deyisle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizlik ve Tedai', 'sessizlik-ve-tedai-ersen-i-bis-hwlv8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '..................................''Yeryüzünün, bütün işitme engellilerine, gözyaşımla,,,''

Gökyüzü karanlık kümbet

Renkler, şekiller izafiyet

Ruhum sessizliğe kefenli

Her doğan gün 

Umutsuz bir kaçış 

İstikametsiz ütopyalara

Acımasız karanlığında

Labirentlerin

Uyku dipsiz kuyu

Uyanış: deprem, yıkılış

Acı, serzeniş ve yalvarış

Kuru derelerin beslediği 

Bulanık bir göl gözyaşı.

Şafaklar firari

Umutlar yüzbiryıl biçâresi

Ayrı bir hicran 

Yüz kelimelik dostluklar

Yok işte yok sessizliğin sesi.

Göznuru akıp giden

Beyhude nehir

Yarın karabasan

Bugün işkence

Boyveren başaklar

Hoyrat ellerin

Zafer kumandana ait

Ölüm kaderidir neferlerin.

Ve sessizlik

Ve boyun bükme

Ve nihayetsiz sabır

Kader meçhûlün manası, 

Geceler kadar esrarlı

Geceler kadar derin

Geceler kadar sessiz

Kördüğüm

Bir nokta söz 

Sûkuttan öte

Hayalden heyûladan

Daha belirsiz

Ve kadere

Ve sessizliğe

Ve sonu gelmeyecek tükenişe

Zalim bir mahkûmiyet

Sessizlikten beter

Sessizliğin tedaisi...', '..................................''Yeryüzünün, bütün işitme engellilerine, gözyaşımla,,,'' Gökyüzü karanlık kümbet Renkler, şekiller izafiyet...', ARRAY['Türk Edebiyatı','Şiir','Ersen İbiş']::text[], 8.5, '{"poet":"Ersen İbiş","poet_slug":"ersen-i-bis","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/sessizlik-ve-tedai-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mother (Ing.)', 'mother-ing-umit-kilislioglu-ozger-9xhi0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'I am your mother

I have nothing to hide

I do not want anything but to share

My embrace is so wide

When you need my affection and care.

  

(2.12.1998)', 'I am your mother I have nothing to hide I do not want anything but to share My embrace is so wide When you need my affection and care.    (2...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/mother-ing-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Colors (Ing.)', 'colors-ing-umit-kilislioglu-ozger-xlnv6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anything that hurts you 

Gives a pain to my heart

A perfect mixture of seven colors

Including blue

Is white you know

As white as snow

This is really an art!', 'Anything that hurts you  Gives a pain to my heart A perfect mixture of seven colors Including blue Is white you know As white as snow This i...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/colors-ing-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seek and Find (Ing.)', 'seek-and-find-ing-umit-kilislioglu-ozger-9fp24', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seek and find 

What is pure and real.

Leave everything else behind

See, hear, and feel.', 'Seek and find  What is pure and real. Leave everything else behind See, hear, and feel....', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/seek-and-find-ing-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şu Su Sesi Var Ya', 'su-su-sesi-var-ya-bekir-mutlu-gokcesu-bq6r4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hazırım uçmaya akşamlarına

An meselesi dokunmam sanki

Göz kapaklarına

Şu su sesi var ya

Bakışın gelir aklıma

Ve teması ellerinin suya

Akar içim akar avuçlarına...

Ayaklarımda ıslaklık hissi çimenlerin

Yürümek isterim altından fıskiyelerin

Sırılsıklam olana dek...

Sonra koşmak deniz kokusuna

Ve fırlatmak isterim kendimi

Duru bir denizin ortasına...

...

Şu su sesi var ya

Bakışın gelir aklıma

Ve teması ellerinin suya...', 'Hazırım uçmaya akşamlarına An meselesi dokunmam sanki Göz kapaklarına Şu su sesi var ya Bakışın gelir aklıma Ve teması ellerinin suya Akar i...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/su-su-sesi-var-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'One Day...In a Way (Ing.)', 'one-day-in-a-way-ing-umit-kilislioglu-ozger-r1v4o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'All dreams come true one day

Never let go of your hopes

If you have anything to say,

If your land is full of crops,

It will be heard in some way.', 'All dreams come true one day Never let go of your hopes If you have anything to say, If your land is full of crops, It will be heard in some...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/one-day-in-a-way-ing-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dua', 'dua-seyhan-kurt-nyvk4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dilimden kerpetenle sökülen dua

Bende sır sana ihtar

Kendisiyle buluşmayı kısa kestiğinden insan

döner dönülmeyecek o en başkasına

Bütün odalar bomboş

kapılar sağır,acılar tekil

ayrılık iki ucu keskin yadigar

ancak ölümle uyutulur

Hayat seni tasarlanmış bir arıza yapar

sana önceden yürünmüş yollar düştüyse eğer

kaç köprüden geçtiğini bilmeden

aşk susturur

konuşturmaz

sabahın tamirhanesinden geçmez

geceden ödünç aldığın kusursuz sezenişler

Dilinden usulca dökülen dua

bana sır senden ihbar

Yüreğinin atlasında çırpınan kedi

sokaktan kadim yalnızlığımın cımbızıyla topladığın insanlar

kaç dalda yarıştı ömrün diyecekken

seni oyuncağı yapan bu şiir,zaman

kalbine koşan aklının maktulünden başka

ertelenmiş bir intihar mı kalır geriye

vaad edilmiş toprakları mı aynalarının

defnedilen bunca hayal arasında

dirilen tel sultadır: şimdiki zamanın hikayesi

dilimden düşmez dua.', 'Dilimden kerpetenle sökülen dua Bende sır sana ihtar Kendisiyle buluşmayı kısa kestiğinden insan döner dönülmeyecek o en başkasına Bütün oda...', ARRAY['Türk Edebiyatı','Şiir','Seyhan Kurt']::text[], 8.5, '{"poet":"Seyhan Kurt","poet_slug":"seyhan-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/dua-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğul, Hey! !', 'ogul-hey-zulfikar-yapar-kaleli-7zqq9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hasretini çekiyorken seherin

Senin yarasalar anmasın oğul

Biçare gönlüne kurulan erin

Baykuşlar bağına konmasın oğul

Attığın her okun hedefi bulsun

Muradın adalet hakikat olsun

Konuş alev sönsün  hüzün kaybolsun

Lafazan baykuşlar onmasın oğul

Garipliğe volkan hüzne çığ gibi

Acı çığlıklara donan çağ gibi

Hasretin büyüsün ıssız dağ gibi

Gönlünde nefretin dinmesin oğul

Yıl küser çığ düşer kahırlarına

Öfkeler emanet olsun yarına

Artık kar yağıyor baharlarına

Damarında kanın donmasın oğul

Bir elin Hirada bir elin Turda

Bir elin yıldızı indirsin yurda

İçerinde nurdan köprüler kur da

Sakın nefsin seni yenmesin oğul

Nurlu şafaklara çengel atsan da

Vahşi karanlığa ışık tutsan da

Garip sokağında hüzün satsan da

Kuzgunlar gemine binmesin oğul

Hayat bir rüyadır bak yaşlılara

Hüznün feryadını onlarda ara

Boş başak misali dik başlılara

Gönlün aldanmasın kanmasın oğul

Kinden uzak dursun gönlün kalesi

Çekilen korkunun soldu lalesi

Sana rehber olsun ötenin sesi

Yürekler kavlinden dönmesin oğul

Ayaklar başlarda geziyor niçin

Kavlin seni siler hep için için

Ruhuna çakılıp sivrilen perçin

Kanına tuz biber banmasın oğul

Ne bugünden vazgeç ne dünü unut

Güneş soban olsun gökyüzü konut

Gevşeme çözülme işi sıkı tut

Sunaların gülsün yanmasın oğul

Hükmüne eğilen sultanlık mısın? 

İçimde yeşeren insanlık mısın

Beş bin yıllık değil bir anlık mısın? 

Bu bayrak yerlere inmesin oğul

Hüsrandır bayrağın yere inmesi

Gariptir yüzyılın güne sinmesi

Sendedir umudun filizlenmesi 

Bu aşkın bu sevdan sönmesin oğul

                                                          1997', 'Hasretini çekiyorken seherin Senin yarasalar anmasın oğul Biçare gönlüne kurulan erin Baykuşlar bağına konmasın oğul Attığın her okun hedefi...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/ogul-hey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heeey Istanbul! ..', 'heeey-istanbul-ferit-teksoy-dspnu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Haydi gel..

Bir anlaşma yapalım

Sen benim istediğimi ver

Ben senin dilediğini yaparım.

İstersen tüm sokaklarını süpürür,

Caddelerini yıkarım

Tek istediğim var senden

Onu alırım 

İstersen bütün insanlarının ellerini öperim

Ayaklarına varırım

Bir gülüm var sende

Onu alırım 

Heeey Istanbul..

Yeter artık..hatır saydık,dil döktük

Ben başka türlü de alırım senden

İstedim ki; gönlünü de alıyım! ..', 'Haydi gel.. Bir anlaşma yapalım Sen benim istediğimi ver Ben senin dilediğini yaparım. İstersen tüm sokaklarını süpürür, Caddelerini yıkarım...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/heeey-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnanmak Zor', 'i-nanmak-zor-ugur-bostan-z1mmv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnanmak zor baharın geldiğine

Gönlüme kar yağmıyor artık

Hazan devri çoktan kapandı

Yağmurlar durdu yağmuyor artık

Kalbimde ki buzlar eridi su oldu

Aşk badesi doldu hedefini buldu

Dört mevsimin hepside bahar oldu

Kuşlar durdu buzlar eridi damla oldu

Leylak açtı, gül açtı, menekşe açtı

Irmaklar yeşil yeşil mavi mavi aktı

Aşk iksiri oldu damlalar dolup taştı

Bahar geldi,sevgi verdi gönlüme

Umut ektim dört mevsim yüreğime 

Yılmadım, beklemekten yorulmadım

Ümit kuşum sonunda kondu elime 

Bahar geldi, sevgi verdi gönlüme', 'İnanmak zor baharın geldiğine Gönlüme kar yağmıyor artık Hazan devri çoktan kapandı Yağmurlar durdu yağmuyor artık Kalbimde ki buzlar eridi ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Bostan']::text[], 8.5, '{"poet":"Uğur Bostan","poet_slug":"ugur-bostan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/inanmak-zor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masalmış', 'masalmis-talip-kaplan-q8kcx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Pek çok zaman,

Dert olmuştur mutluluğun adı.

Güzelle çirkin karışımıdır

Kalpten kalbe yolun harcı.

Busedir mutluluk,

Gözyaşıdır, kahkahadır.

Aşktır mutluluk.

Kederdir aşk, sevinçtir

Hasretliktir sevgiliye, hüzündür.

Bazen darılmaktır,

Korkmaktır ahu gözlü yardan.

Çirkindir kimi zaman,

Küfürdür terkedene.

İhanettir bazı bazı,

Aldatmacadır, oyundur...

(03 Aralık 1994)', 'Pek çok zaman, Dert olmuştur mutluluğun adı. Güzelle çirkin karışımıdır Kalpten kalbe yolun harcı. Busedir mutluluk, Gözyaşıdır, kahkahadır....', ARRAY['Türk Edebiyatı','Şiir','Talip Kaplan']::text[], 8.5, '{"poet":"Talip Kaplan","poet_slug":"talip-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/masalmis-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemiyorum', 'bilemiyorum-ugur-bostan-bgos9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçimde kopan fırtınalara

Savaşlara...

Artık dur dedim

Dur dedim yetti,

Sonunda durdu işte

Bütün fırtınalar savaşlar

Ve ben beni buldum

İsterklerimi emellerimi

Sen dottum yüreğimdeki boşluğu

Hatırlatma...

Kinin mi var yoksa garezin mi

Yoksa kıskanıyormusun beni

Neden hatırlatıyorsun öyle ise 

Yüreğimin boşluğunu

Neden soruyorsun ikide bir 

Sahibi kim diye

Kolay mı sevmek  kolaymı

Kolaymı benim kalbime girmek

Sevmek istesemde sevemiyorum

Kalbime söz geçiremiyorum

Sebebini bende bilmiyorum...', 'İçimde kopan fırtınalara Savaşlara... Artık dur dedim Dur dedim yetti, Sonunda durdu işte Bütün fırtınalar savaşlar Ve ben beni buldum İster...', ARRAY['Türk Edebiyatı','Şiir','Uğur Bostan']::text[], 8.5, '{"poet":"Uğur Bostan","poet_slug":"ugur-bostan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bilemiyorum-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret Var', 'hasret-var-ugur-bostan-386ae', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir hasret var yüreğimde

Öyle bir hasret işte

Bazen deli poyraza tutulmuş gibi

Bazen durdun dalgalar gibi

İçimde taşan seller misali

Koparıp atamadığım 

Kimseye satamadığım 

Vede tutamadığım

Öyle bir hasret işte..', 'Bir hasret var yüreğimde Öyle bir hasret işte Bazen deli poyraza tutulmuş gibi Bazen durdun dalgalar gibi İçimde taşan seller misali Koparıp...', ARRAY['Türk Edebiyatı','Şiir','Uğur Bostan']::text[], 8.5, '{"poet":"Uğur Bostan","poet_slug":"ugur-bostan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hasret-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşeren Bir Gülü Sevdim', 'yeseren-bir-gulu-sevdim-ugur-bostan-e74dj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeşeren bir gülü sevdim

Pembe pembe al açarken

Devşirip derleyiverdim

Gönlüme sevda şaçarken

Yaban gülü olma gel

Kalbe hicran koyma gel

Ele gidip solma gel

Sana kimse olmasın engel

Son versen hüzünlere

Gözlerimden kalbime...

Süzülerek bakta gel...', 'Yeşeren bir gülü sevdim Pembe pembe al açarken Devşirip derleyiverdim Gönlüme sevda şaçarken Yaban gülü olma gel Kalbe hicran koyma gel Ele ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Bostan']::text[], 8.5, '{"poet":"Uğur Bostan","poet_slug":"ugur-bostan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yeseren-bir-gulu-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Farketmez', 'farketmez-talip-kaplan-9nnh7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kediyi anlatıyordum, 

Belli etmedi manda sandığını. 

Ve karınca dedi... 

Sonra yürüdük biraz 

Konuyu dağıttık. 

Birer sigara yaktık... 

Fil diyerek başladı söze 

Manda sandığı kediyi, 

Anlatıyordu evire çevire... 

Bir anlam veremedim 

Sigara ikram ettim 

Ve güldüm sadece, 

_________ içimden... 

Ne farkeder ki; 

Yürüyorduk ve yürüyeceğiz... 

(01 Mayıs 1995)', 'Kediyi anlatıyordum,  Belli etmedi manda sandığını.  Ve karınca dedi...  Sonra yürüdük biraz  Konuyu dağıttık.  Birer sigara yaktık...  Fil ...', ARRAY['Türk Edebiyatı','Şiir','Talip Kaplan']::text[], 8.5, '{"poet":"Talip Kaplan","poet_slug":"talip-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/farketmez-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağla Çocuğum', 'agla-cocugum-erdogan-ergin-6up10', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ağla çocuğum,

Ağlamak güzel,

Ruhunda yaşanan ızdırap,

Bedenini acıtmasın

Ağla çocuğum ağla,

Bu, sen

	/sen olursan eğer

bu ben

	/varlığına değer

ve hayat yaşadıkça

	/kardır öğrenilenler

ağla çocuğum ağla

gülenlerin memleketinde

	/ağlamak seninle güzel', 'Ağla çocuğum, Ağlamak güzel, Ruhunda yaşanan ızdırap, Bedenini acıtmasın Ağla çocuğum ağla, Bu, sen 	/sen olursan eğer bu ben 	/varlığına de...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/agla-cocugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fidan,Toprak ve İnsan', 'fidan-toprak-ve-i-nsan-erdogan-ergin-kuiuf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sormuşlar insana; 

Kime benzer bir yanın,

Ya da ne benzer sana? 

Ben bir ağaca benzerim demiş,

Aynasıdır belki insanın.

Bir tohum atmışlar toprağa

Tohum kendi düşmemiş

Toprağı kazıp gömmüşler

Küçücük bir tohum,

İnsanın köküne benzeyen,

Sadece bir tohum atmışlar

Aynı insan gibi, toprağa…

Bakmışlar, özen göstermişler

Tohum kök salmış toprağa…

Ben gibi, sen gibi topraktan beslenmiş

Tohuma bakmışlar,

Sabretmişler,

Bir filiz vermiş yeryüzüne

Küçücük bir filiz başını uzatmış toprağın üstüne

Merhaba! demiş yeryüzü

İyi bak ben geliyorum

Her yere uzanıp,

Can vereceğim çevreme…

Ama ne çare,

Biçare.

Ne kendine yetermiş, ne çevresine

Bakım gerekmiş, yoksa bir yaban olurmuş

Çevresindekiler gibi

Korumak, bakmak ve beslemek gerekmiş

Birinin onunla ilgilenmesi

Ve yahut son adım çevresine

Büyümüş filiz,

Fidan olmuş.

Dalları toprağa dönmüş,

Lakin yanlışmış dönmesi

Düzeltmek gerekirmiş,

Faydası olsun diye

Bir örnek bulmuşlar, dosdoğru

O da onun gibi olsun diye

Birleşmiş fidan onunla, dosdoğru olma yolunda

Büyümüş fidan, kökü gövdesi sağlamlaşmış

Ama yine de eğilmekteymiş dalı

Korumak gerekmiş çevreden

Onu eken, onu toprağa veren

Korumuş onu gözünden, gözlerden

Bakmış ona onun geleceği imiş fidan

Güneşten korumuş

Zaman, zaman yağmurdan

Büyüyüp de meyve versin diye

Zaman ağaca dönmüş,

Ağaç zamana…

Günler geçmiş, ağaç artık kendini korur olmuş

Olmuş da bir küçük böcek yiyip bitirmiş içini.

Sen kök sal toprağa,

Bin bir cefa ile baksın sana,

Yinede topraktan korkma…

Ve bir gün içinin boş olduğunu hissetmiş,

Zamanın geçişini görmüş,

Ve sormuş kendine; 

Küçük bir tohumdum ben de

Çıkıpta yeryüzüne

Gördüğün bir hayaldir zaman

Lakin yıkılmakta iken gövdem

Toprağa düşmekte', 'Sormuşlar insana;  Kime benzer bir yanın, Ya da ne benzer sana?  Ben bir ağaca benzerim demiş, Aynasıdır belki insanın. Bir tohum atmışlar t...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/fidan-toprak-ve-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gazel', 'gazel-abdulkadir-karaman-utrgg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mâşukum, hiç aşklarla aşkımı seyrelttirme

Nazargâhın kâlbimi gayrıya meylettirme. 

Pervâneler misâli hayâlinle döneyim

Her kahrına râzıyım, başka kahır çektirme. 

Ruhum, her an katına yüz sürsün aciz, aciz

İstemem, özleminden başka özlem çektirme. 

Hep hüsnünü ekeyim, kıraç duygularıma

Ne olursun hüsnünden gayrı hüsnü ektirme. 

Sana daima açtır benliğim biliyorsun

İzin ver de geleyim yolda tökezlettirme. 

Duam, âhım katına yükselsin, kıymet bulsun

Eğer lâyık değilse, katına yükselttirme. 

Başkaları teselli edemez şu derdimi

Yüz suyumu insaf et muhannete döktürme. 

www.kadirkaraman.com', 'Mâşukum, hiç aşklarla aşkımı seyrelttirme Nazargâhın kâlbimi gayrıya meylettirme.  Pervâneler misâli hayâlinle döneyim Her kahrına râzıyım, ...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gazel-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaderimmiş...', 'kaderimmis-fatih-taskin-r9z03', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nedenlerle dolu hayatım

Bu benim kara bahtım

Sensiz bu gönül tahtım

Kaderimmiş ne yapayım...

Gözlerindeki aşk dolu ifadeler

Sana söylediğim güzel nağmeler

Bana söylediğin yalan sözler

Kaderimmiş ne yapayım...

Seni uyuyarak düşünmek

Rüyalarımda hep seni görmek

Sensizlikten acı çekmek

Kaderimmiş ne yapayım....

Seni her yerde özlemek

Seni ölesiye sevmek

Senin için dağlar delmek

Kaderimmiş ne yapayım...', 'Nedenlerle dolu hayatım Bu benim kara bahtım Sensiz bu gönül tahtım Kaderimmiş ne yapayım... Gözlerindeki aşk dolu ifadeler Sana söylediğim ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Taşkın']::text[], 8.5, '{"poet":"Fatih Taşkın","poet_slug":"fatih-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kaderimmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Yüzün*', 'yuzun-kubilay-enginol-zcqvl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yataktan kalktığında saçların nasıl olur

Kimbilir

Yada,sahte ölüm bütün gece

Yüzünü köpekler gibi yaladığında

Ne kadar da masumdur kimbilir

Çehren ay ışığında

Şiirlerdemi sevişeceğim hep seninle

Yada elini tutacağım

İnan

Sahte ölümünde

Azrailin olacağım', 'Yataktan kalktığında saçların nasıl olur Kimbilir Yada,sahte ölüm bütün gece Yüzünü köpekler gibi yaladığında Ne kadar da masumdur kimbilir ...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yuzun-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklentisiz Sevmeyi Denediniz mi Hiç?', 'beklentisiz-sevmeyi-denediniz-mi-hic-i-rem-yitmen-f3dsc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgileri  düşünüyorum,soruyorum kendime  dünyada gerçek sevgi varmıdır diye? 

Geçenlerde bir yazı okuyordum,yazıyı aynen şöyleydi:

BEKLENTİSİZ SEVMEYİ DENEDİNİZ Mİ? 

 Hiç beklentisiz sevdiniz mi? Yani ''Bugün telefon etmedi'' demeden''Şu an nerede acaba? '' diye kendi kendinizi yemeden ''Yaş günümü hatırlayacak mı acaba? '' diye bir beklenti içine girmeden... Sevdiniz mi hiç? Onun size ait olmadığını kabul edip, onu özgür yaşamı ile sevmeyi denediniz mi? Yanındaki erkek arkadaşına aldırmamayı öğrenip ama aldırmıyormuş gibi yapmadan, gerçekten aldırmadan, ''Bitecekse biter bunu ben değiştiremem beni sevmeyi bırakmasını değiştiremeyeceğim gibi'' diye düşünüp Onu yersiz kıskançlıklara boğmaktan ve kendinizi yıpratmaktan vazgeçebildiniz mi hiç? Hiç beklemeden çalan bir kapıda onu karşınız da görmek ne güzeldir bilir misiniz? Beklemediğiniz bir anda hediye almak en sevdiğinizden... Ve beklemeden gelen bir ''seni seviyorum'' mesajının tadına varabildiniz mi hiç? Siz istediginiz için degil, o istiyor diye yapildi mi tüm bunlar? Ve beklentisiz sevmenin tadina bakabildiniz mi hiç? ''Bugün beni hatirlamadi'' yerine ''Hiç beklemiyordum senin gelecegini'' diyebilmek ne güzeldir oysa... Onu bogmadan kendinizi bogmadan sevebilmek ne güzeldir... Sahiplenme duygusundan uzak, sevmenin sevilmenin tadina varabildiniz mi hiç? Yapilmamis davranislar söylenmemis sevgi sözcükleri ile kendi kendinizi ask çikmazinda kaybedeceginize Hiç beklenmeyen bir demet çiçekle mutlu oldunuz mu? Beklentisiz sevin... Ben, beklentisiz seviyorum... ''Niye aranmadim'' diye düsünüp kendini kendinizi yiyeceginize hiç beklenmedik bir ''Seni özledim'' mesaji ile aski yakalayin.. Beklentisiz sevin... Ben, beklentisiz seviyorum... O, sizin sevgiliniz oldu için degil. Ona tapulu maliniz gibi, çantaniz, arabaniz gibi davranma hakkiniz oldugunu düsünmeden. Onu sevdiginiz onun da sizi sevdigi için sevin... Sevgiye karisan ''beklenti'' denen illeti hemen silin askin ak sayfalarindan... Göreceksiniz ki o zaman ask baska bir güzel... Göreceksiniz ki o zaman sevgili daha bir romantik... Göreceksiniz ki o zaman sevmek ve sevilmenin damaklarda biraktigi tat, yillanmis sarap gibi, beklenti zehrine karismadan bir baska döndürüyor insanin basini.. Ben, beklentisiz seviyorum... Onun nerede oldugunu merak etmiyorum... ''Beni bugün neden aramadi'' diye geçirmiyorum içimden, aramadigi zamanlarda... Gelecege dair hayallerim de yok zaten... Ben sevgiyi yasiyorum... Onun yanimda oldugu anlar o kadar degerli o kadar kiymetli ki... Gerçeklesmemis ve gerçeklesmeyecek beklentilerle mahvetmiyoruz o anlari... Beklentisiz seviyoruz... Sevdigimiz için seviyoruz... Hayalsiz, geleceksiz beklentisiz... Anlik seviyoruz... Deneyin... Beklentisiz, sevmeyi deneyin bir gün... Beklentilerle boğduğunuz aşklariniza aciyacaksiniz... 

 Geçmişi  düşünüyorum,yaşadıklarımı…Acaba  bunları başarabildim mi? 

Hayatıma giren insanları düşünüyorum.’’Herbiri  hayal kırıklığıydı’’ demek istemiyorum. 

Beni olduğum gibi kabulenemediler,değişmemi istediler.Kişiliğimden ödün vermemi 

istediler.Aşırı sahiplendiler,oysa yürekten güvenmeyi hiç denemediler.Kendilerini

yani zayıflıklarını  saklamayı denediler,oysa  kimse mükemmel  değildir.Herkesin zayıf 

tarafları mutlaka vardır,önemli olan bunları  kabullenip  geliştirmeyi bilebilmektir.

Ya ben  beklentisiz sevmeyi başarabildimmi,sanırım kısmen,bunu ben de tam olarak  başaramadım. 

 Asla   aşka dair inancımı hiç kaybetmedim.Birgün aradığım gerçek  aşkı mutlaka bulacağıma inanıyorum. 

Oysa geç kalmış değiliz,şu andan itibaren başlayarak beklentisiz sevmeyi deneyebiliriz.Sadece anları yaşayarak,yanımızda olduğu her saniyeye şükrederek,geleceğe dair kaygılar duymadan,çünkü  ben bile bir saniye sonra ne olacağını bilmiyorum.Ölümle yaşam arasındaki o çok ince çizgiyi çok iyi  biliyorum,bir zamanlar bende  ölümle yaşam arasındaki o  ince çizgide dans ettim ve hayatın aslında  çok kısa olduğunu  ve anların çok değerli  olduğunu anladım.

Ellerimizi  kavuşturup  Tanrı’ya  şükredeilim,yaşıyoruz  sevgiyle sarılı olarak,

sevdilerimiz yanımızda olarak…

Tanrı  kusurlarımızdan dolayı bizleri bağışlasın ve onları  geliştirip olgunlşamamız için bize gerekli gücü  bağışlasın…

‘’Tanrım  sana şükürler olsun yaşıyorum  sevdiklerim yanımda olarak,yaşamın o sonsuz tadına  varabilmek ve sevginin gerçek gücüne erişebilmek için  gözlerimi ve tüm yolları  önümde aç.Sonuçta senin  sonsuz sevginden yaratıldık ve  yine tüm yollar sonuçta  o sonsuz sevgine çıkacak…’’', 'Sevgileri  düşünüyorum,soruyorum kendime  dünyada gerçek sevgi varmıdır diye?  Geçenlerde bir yazı okuyordum,yazıyı aynen şöyleydi: BEKLENTİ...', ARRAY['Türk Edebiyatı','Şiir','İrem Yitmen']::text[], 8.5, '{"poet":"İrem Yitmen","poet_slug":"i-rem-yitmen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/beklentisiz-sevmeyi-denediniz-mi-hic-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beddua', 'beddua-husamettin-gunacti-agi3w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ihtirasların denizse,

girdabının tadına bak.

ısmarlama aşklar seninse,

sonunda hep ağıt yak...', 'ihtirasların denizse, girdabının tadına bak. ısmarlama aşklar seninse, sonunda hep ağıt yak......', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/beddua-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili Eşim Arzu''ya', 'sevgili-esim-arzu-ya-erdogan-ergin-h0s9e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen güldükçe gülen kalbim

Dudaklarıma yansıyan göz yaşların,

Bir çocuk gibi buruk,

Ve bir sürgün belki beynime,

Bana kızışların,

Ya da bir şairin dediği gibi; 

yansıyan kalbime

Baş harflerindir,

Ve eğikliği veriyor acıyı,

Adının…', 'Sen güldükçe gülen kalbim Dudaklarıma yansıyan göz yaşların, Bir çocuk gibi buruk, Ve bir sürgün belki beynime, Bana kızışların, Ya da bir ş...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevgili-esim-arzu-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna', 'ayna-erdogan-ergin-loexa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bıraktığım gençliğim var ardımda,

Aynalara günlerce bakıpta,

Tanıyamadığım bu yüz.

Çocukluğumun izlerini taşısa da ruhum,

Beden eski yabancı bana', 'Bıraktığım gençliğim var ardımda, Aynalara günlerce bakıpta, Tanıyamadığım bu yüz. Çocukluğumun izlerini taşısa da ruhum, Beden eski yabancı...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ayna-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli', 'deli-sedat-tuvar-7lob0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Denize doğru akar

Akar yamaç boyu

Ağaçsız topraksız sessiz sessiz

Akar dar sokaklar

Varamadan denize

Sahiller boyu

Keser önlerini birer geniş cadde

Akar insansız akar kimsesiz

Bir çatının tepesindeyim

Elimde uzaktan kumandam

Oynarım şehrin ışıklarıyla

Açarım kaparım gecenin ateşi bende

Elimde koca bir hortum

Ben silerim ben temizlerim

Bu şehir benim

Ta ki martılar acıkana dek

Tepelerinde döner

Günler geceler boyu

Döner sessiz sessiz

Söylediğim türküler

Bu şehir sadece benim

Ben bir damdan düşüp ölene dek

Ben mi kimim

Bu şehrin delisi', 'Denize doğru akar Akar yamaç boyu Ağaçsız topraksız sessiz sessiz Akar dar sokaklar Varamadan denize Sahiller boyu Keser önlerini birer geni...', ARRAY['Türk Edebiyatı','Şiir','Sedat Tüvar']::text[], 8.5, '{"poet":"Sedat Tüvar","poet_slug":"sedat-tuvar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/deli-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-erdogan-ergin-5djnt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaybolup giden yüzleri görüyorum,

Kapının ardında

Yerine yenileri geliyor,

Her ayrılıkta yeni bir kavuşma

Ayrılığın böylesi dedirtiyor, insana…', 'Kaybolup giden yüzleri görüyorum, Kapının ardında Yerine yenileri geliyor, Her ayrılıkta yeni bir kavuşma Ayrılığın böylesi dedirtiyor, insa...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ayrilik-178-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsrâil’in Abdullâh’a garezi', 'i-sr-il-in-abdull-h-a-garezi-sair-ahrazi-fby3h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey câhil,mâsumun âhı,Mevlâ’ya ulaşır elbet,

Yakındır,târihin kanı,sana da bulaşır elbet.

***

Not: İsrâil,ibrânice Abdullâh’la aynı mânâdadır.', 'Ey câhil,mâsumun âhı,Mevlâ’ya ulaşır elbet, Yakındır,târihin kanı,sana da bulaşır elbet. *** Not: İsrâil,ibrânice Abdullâh’la aynı mânâdadır...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/israil-in-abdullah-a-garezi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim ol', 'benim-ol-tayfun-akman-0r7bi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Benim umudum olurmusun, 

yaşama sevincim, 

Sebebim ol benim, 

özlemim, 

Güneşim olurmusun benim, 

hayallerim, 

Bitanem olurmusun 

Sevdiğim aşkım ol benim.

BENİM OL', 'Benim umudum olurmusun,  yaşama sevincim,  Sebebim ol benim,  özlemim,  Güneşim olurmusun benim,  hayallerim,  Bitanem olurmusun  Sevdiğim a...', ARRAY['Türk Edebiyatı','Şiir','Tayfun Akman']::text[], 8.5, '{"poet":"Tayfun Akman","poet_slug":"tayfun-akman","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/benim-ol-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-erdogan-ergin-ro54z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalan olmasaydı insanların dilinde

Neye yarardı ki doğru söz,

Yaşamın en güzel yerinde,

Mükafattır belki,

Belki de bir çeşit sınav,

Yalana karşı doğru söz', 'Yalan olmasaydı insanların dilinde Neye yarardı ki doğru söz, Yaşamın en güzel yerinde, Mükafattır belki, Belki de bir çeşit sınav, Yalana k...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yalan-103-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben zâten ordayım(Hasret)', 'ben-z-ten-ordayim-hasret-sair-ahrazi-rzs84', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hasret,uçsuz bucaksız bir yerdir,bilirim,

Zindânmış,prangaymış boş ver,anlatma ne olur,

Ben zâten ordayım,O yer benim gözlerim', 'Hasret,uçsuz bucaksız bir yerdir,bilirim, Zindânmış,prangaymış boş ver,anlatma ne olur, Ben zâten ordayım,O yer benim gözlerim...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/ben-zaten-ordayim-hasret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuğunu Kaybetmiş Adam', 'cocugunu-kaybetmis-adam-erdogan-ergin-hn1dr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ve ben çocuğunu kaybetmiş adam

Hüznünü duvara yansıtan

Ağladığında tüm duvarları

Ağlama duvarı olan adam

Ve ben çocuğunu kaybetmiş adam

Onca sessiz hıçkırıklar arasında

Bir damla gözyaşı dökmeden

Sel olup akan adam

Ve ben çocuğunu kaybetmiş adam

Ağlayan annenin kirpikleri olamayan

Sessiz sözcükleri arasında kaybolan

Kendine yer arayan sesli adam

Ve ben çocuğunu kaybetmiş adam

Giden çocuğu ardından

Hayallerini on kuruşa satan

İki mürekkep olup yazamayan adam', 'Ve ben çocuğunu kaybetmiş adam Hüznünü duvara yansıtan Ağladığında tüm duvarları Ağlama duvarı olan adam Ve ben çocuğunu kaybetmiş adam Onca...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cocugunu-kaybetmis-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gûstah', 'g-stah-sudamlasi-yagmur-49xwc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ruhuma

               ''Kerem et ''

Çığlık ve yağmur

Martı ve ihanettir

Bilir inceden

Kabaca...

               ''Bu dil-i perişâne''

Yastık ve gözyaşı

Sızar

Aşk bir eski zaman şarkısı

Bile değil

Güler kabaca

İnceden...

               ''Dokunma''

Ruhuma bir karanfil daha

Naif ve yâd 

Tüllenir hüsran

İntizar hayır, imdat evet! 

               ''Senin sadakatli kulundur''

Kabına sığmaz gülüşü

İncelir bilişi

Dokunur...', 'Ruhuma                ''Kerem et '' Çığlık ve yağmur Martı ve ihanettir Bilir inceden Kabaca...                ''Bu dil-i perişâne'' Yastık ve g...', ARRAY['Türk Edebiyatı','Şiir','Sudamlası Yağmur']::text[], 8.5, '{"poet":"Sudamlası Yağmur","poet_slug":"sudamlasi-yagmur","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gustah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz', 'biz-erdogan-ergin-3zvzm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün denizden, hatıra topladım

Yırtılmış resimler,

Yazılmış şiirler,

Ve yakılmış öyküler.

Bugün denizden hatıra topladım; 

Bir sepet içine doldurulmuş,

Kırık bir kalbin,

Eğrelti parçaları..

Bugün denizden hatıra topladım; 

Bir şehrin ucuz sevgileri,

Boşa harcanmış zamanlar,

Lise sevdalarına benzeyen,

Aşk kaçamaklarını,

Bugün denizden bizi topladım,

Niçin attılarsa denize?', 'Bugün denizden, hatıra topladım Yırtılmış resimler, Yazılmış şiirler, Ve yakılmış öyküler. Bugün denizden hatıra topladım;  Bir sepet içine ...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/biz-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgeler', 'golgeler-erdogan-ergin-aczrv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gölgeleri yere değdiğinde

Büyüklüğü ile gururlanır insanlar,

Basmamak için birbirinin üzerine,

Üst üste, alt alta yığılır insanlar

Ne alttakinin haberi olur

Ne üsttekinin,

Gölgesi küçülür büyüdükçe,

Üst üste insanlar', 'Gölgeleri yere değdiğinde Büyüklüğü ile gururlanır insanlar, Basmamak için birbirinin üzerine, Üst üste, alt alta yığılır insanlar Ne alttak...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/golgeler-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Empati', 'empati-erdogan-ergin-4quif', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kendi penceremden bakmadım hiç

Empati denilen bir bilginin ardında

Bir çok pencere dolaştım

Her yerden gördüm kendimi

Bir tek kendimden göremedim

Kendimi', 'Kendi penceremden bakmadım hiç Empati denilen bir bilginin ardında Bir çok pencere dolaştım Her yerden gördüm kendimi Bir tek kendimden göre...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/empati-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınlar', 'kadinlar-erdogan-ergin-s0s43', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kadınları anlamak diyorsan eğer,

O zor elbet; 

Hangisi güzel, hangisi çirkin bilirim de; 

Hangisi kolay, hangisi zor,

Onu bir başkasına sor.

Kadınlar,

Bilmem ki,

Kim onlar?', 'Kadınları anlamak diyorsan eğer, O zor elbet;  Hangisi güzel, hangisi çirkin bilirim de;  Hangisi kolay, hangisi zor, Onu bir başkasına sor....', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kadinlar-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İthaf', 'i-thaf-erdogan-ergin-yxa71', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İlk çirkinliğini gördüm insanlığın.

Verilen onca güzel şeyin üzerine,

Bir şişe zehri boşlatılışını,

Ve ondan yıkanan yüzlerin

Lekesini…

Belki de ilk defa

bende sizin yüzünüzden,

Sürdüm yüzüme…

Yüzsüzlüğüme inat edercesine

Yüzümde bir şişe zehrin,

Kırmızı,

İzleri', 'İlk çirkinliğini gördüm insanlığın. Verilen onca güzel şeyin üzerine, Bir şişe zehri boşlatılışını, Ve ondan yıkanan yüzlerin Lekesini… Belk...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ithaf-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostu Ziyaret', 'dostu-ziyaret-erol-dal-9p764', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Benden başka gelen olmamış ki mezarına

Defnederken koyduğum çiçeklerde solmuş; 

Başucunda birkaç,

filika benzeri tuğla; 

Toprak, 

sandığımdan da soğukmuş.

-2000/Mekan', 'Benden başka gelen olmamış ki mezarına Defnederken koyduğum çiçeklerde solmuş;  Başucunda birkaç, filika benzeri tuğla;  Toprak,  sandığımda...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dostu-ziyaret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Sevdiğini Söyle de Bitsin', 'gel-sevdigini-soyle-de-bitsin-halil-kesken-p5c6r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben sana mahsup ettim hayallerimi,

Aşkımı sana ciroladım,

Biliyorsun ki şakaya gelmez

Karşılıksız çıkarsa yanarım

Eller herşeyin sende bittiğini bilmez

Gel sevdiğini söyle de bitsin

Benim adımı hırsız,

Aşkımın adını karşılıksız koymasınlar

Ellerim açık, 

Kapında bekliyorum günlerdir

Bir aşkın ispatı bu kadar mı zor? 

Uğrunda ölmekse; ona da varım

Ama bu; 

Gerçeği aklına,

Beni ise mezara kor...

Gel sevdiğini söyle de bitsin

Benim adımı dilenci,

Aşkımın adını yalancı koymasınlar

Bana karşı bir ışık varsa eğer

Önce yüreğinde, 

Sonra güneşte sakla.

Yüreğinde sakla ki ölene,

Güneşte sakla ki; 

Kıyamete kadar sürsün

Yıllardır bir kelimen için, ağzına bakıyorum

Gel sevdiğini söyle de bitsin

Benim adımı arsız,

Aşkımın adını karşılıksız koymasınlar

Ben burada tek başına,

Sen orada tek başına

Sen benim aşkıma muhtaçsın,

Bense senin aşkına

İzin ver ömrümüz beraber geçsin

Yalnızlığa son vermek senin elinde

Gel sevdiğini söyle de bitsin

Benim adımı yarsız,

Aşkımın adını karşılıksız koymasınlar...', 'Ben sana mahsup ettim hayallerimi, Aşkımı sana ciroladım, Biliyorsun ki şakaya gelmez Karşılıksız çıkarsa yanarım Eller herşeyin sende bitti...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gel-sevdigini-soyle-de-bitsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Sonra', 'senden-sonra-ali-aydin-eh96n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yorgun martıların hıçkırıkları yankılanır,

Gün gecenin alacakaranlığına esir düşerken.

Meçhul kadının gölgesi dalgalanır yakamozlarda,

Gözyaşlarında lav, dudağında acıklı hüzün türküsü.

Yüreğim çılgın tay kahverengi gözlerinde,

Martıların kanatlarında soluk soluğa nefesimiz.

Bitimsiz sevdanın kıyılarında nilüferler açarken,

Sensizliğin sarhoşluğu şarap kadehlerinde.

Seni tanımadan önceydi, başımda kavak yelleri,

İki elle sarılışım hayatın renklerine, senden sonra.

13.07.2004', 'Yorgun martıların hıçkırıkları yankılanır, Gün gecenin alacakaranlığına esir düşerken. Meçhul kadının gölgesi dalgalanır yakamozlarda, Gözya...', ARRAY['Türk Edebiyatı','Şiir','Ali Aydın']::text[], 8.5, '{"poet":"Ali Aydın","poet_slug":"ali-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/senden-sonra-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haksız', 'haksiz-talip-kaplan-npz1k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biz, falan küsür kişiydik

Tütün yanığı çekerdik ciğerimize.

Koklardık dumanı ayrı ayrı

Sırasız bir sırayla birer birer,

..............................hep birden.

Bana hep izmarit kalırdı

Kimine ben sahip çıkardım

Kimi de bana mal edilirdi,

Pislik diye bilinenlerin.

Aman aman aman of...

Ah şu haksızlıklar.

Onlar müptela mı bana

Yar mı bellediler beni...

(13 Mart 1994)', 'Biz, falan küsür kişiydik Tütün yanığı çekerdik ciğerimize. Koklardık dumanı ayrı ayrı Sırasız bir sırayla birer birer, .......................', ARRAY['Türk Edebiyatı','Şiir','Talip Kaplan']::text[], 8.5, '{"poet":"Talip Kaplan","poet_slug":"talip-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/haksiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtuluş', 'kurtulus-engin-ozcan-osh0g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kurtuluş ulaşılmaza ulaşmak değildi bizim için..

yıldızlara uzanmak yada başka birşey...

Kurtuluş hüzünlere boğmadan yaşamaktı bizi...

Ağlarken gülebilmek...

Gülerken kahkahalarla.. gözlerimizden yaşlar gelmesi..

bütün şehri griye boğan hazana inat....

kurtuluş.. insanın yüreğiydi...

kurtuluş.. herşeyimizdi...

esaretimiz... ve dinginliğimizdi...

04/07/2004 

istanbul', 'Kurtuluş ulaşılmaza ulaşmak değildi bizim için.. yıldızlara uzanmak yada başka birşey... Kurtuluş hüzünlere boğmadan yaşamaktı bizi... Ağlar...', ARRAY['Türk Edebiyatı','Şiir','Engin Özcan']::text[], 8.5, '{"poet":"Engin Özcan","poet_slug":"engin-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kurtulus-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Yüce Sevgimi Vereceğim', 'sana-yuce-sevgimi-verecegim-cafer-tayyar-ozkan-u1o89', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her seferinde sana çok seviyorum diyorsam,

Ukdeler boğazımda, amansız boğuluyorsam,

Sabahları umudu, akşam hüznü yaşıyorsam,

Belki bir gün geleceğini beklediğimdendir.

Kısmeti bekleyen acemi balıkçıya döndüm,

Seninle ben kendime apayrı bir dünya kurdum,

Düşlerimde o nurlu yüzüne yüzümü sürdüm,

Bir gün çağrıma koşacağını bildiğimdendir.

And olsun ki, sana yüce sevgimi vereceğim,

Sözümü bağışla, vuslatı hep isteyeceğim,

Biliyorum, sana kavuşmak inan çok zor ama,

Bildiğim tek şey, aşkından vazgeçmeyeceğimdir. 

13 Mart 2003 Ankara', 'Her seferinde sana çok seviyorum diyorsam, Ukdeler boğazımda, amansız boğuluyorsam, Sabahları umudu, akşam hüznü yaşıyorsam, Belki bir gün g...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sana-yuce-sevgimi-verecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretim Gülsün', 'hasretim-gulsun-derin-oger-zjvs5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sen bendin ben de sendim

narım çiçeğim sevdiğimdin

sevdayı telledik duvakladık

bir tepeye bir dağa vurduk

ince ipek büyümüş sevdam

sürüye sürüye dolanamam

hatrını yükseklerden atsam

candan can düşer kıyamam

göğe dedimki bir daha ağla

göğsümle tuttuğum yollara

usulca yağ bu kuytu sona

birik yüreğimin çukurunda

yağmur damladı dudağıma

gözyaşı gül oldu yanağımda 

merhamet neylesin ki cefaya

hasretim gülsün yeter bana...', 'sen bendin ben de sendim narım çiçeğim sevdiğimdin sevdayı telledik duvakladık bir tepeye bir dağa vurduk ince ipek büyümüş sevdam sürüye sü...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hasretim-gulsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorduğun', 'sordugun-i-lyas-ozkan-6in6l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '*İlk gözyaşımdı; uzaklara düştü...

Sorup durma, deşme yaramı be hey! 

Gönlümün küllenmiş Kerbela’sıdır sorduğun! 

Adım adım gölgem olup hayali; 

Başımın uslanmaz belasıdır sorduğun! 

Bir kez saplanmaya görsün hançeri sevdanın; 

Derin izlerle yılların yarasıdır sorduğun! 

Zaman geçmiş, heyhat unuturum sanma; 

Apaydın günümün karasıdır sorduğun...! 

(19.05.2004

Çarşamba)', '*İlk gözyaşımdı; uzaklara düştü... Sorup durma, deşme yaramı be hey!  Gönlümün küllenmiş Kerbela’sıdır sorduğun!  Adım adım gölgem olup haya...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özkan']::text[], 8.5, '{"poet":"İlyas Özkan","poet_slug":"i-lyas-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sordugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dön Geri...', 'don-geri-mehmet-yilmaz-ll2tc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne güzel günlerdi seninle yasadıklarımız...

O günler gözümün önünde canlandıkca icim ürperiyor,gözlerim doluyor....

Hani derler ya ''''erkekler aglamaz'''' diye...

Ben sensizlige kahrediyorum... her gece aglıyorum...

Bana o bakısların Yok muydu? 

Beni bambaska diyarlara götürüyordu...

Hayatın o acımasız, o kalles tarafı sen yanımdayken ucup gidiyordu... Bir baska dünya kuruluyordu sanKi...

Ama simdi hersey tersine döndü...hatıralar bi basımda ve ben yoklugunu onlarala avunmakla geciriyorum...

Cok yalnız kaldım... kalabalıkta bile kendimi yalnız hissediyorum...

Neydik biz sevgili ? 

Bir ask böyle bitmemeliydi...

Ne olur dön geri,bırakma beni...

İnan artık hayat anlamsız geliyor bana,

Cok yalnızım.. güzel günlerin hatrına gel bana.. 

Sana artık uzaktan bakıyor gözlerim,

Unutmak o kadar kolay mı sandın! ...

Yüregime girdigin ilk günden beri,gittigin son günden beri benim askım hiç değişmedi ben hala aynıyım... 

Ayrılmak o kadar kolay mı sandın! ...

Ben senden ayrılamadım,

Ben senden kopamadım,

Ben seni unutamadım sevgili! ...

Ne olur...Ne olur dön geri...

Asık olmak sucunu beraber isleyelim,

Hic bir sey sormayacagım sana,

Herseyimle,herseyinle seninim.

Utangaclıgınla,vurdumduymazlıgınla,kıskanclıgınla,cocuksulugunla,aglamanla gülmenle,herseyinle seninim...

Sana askını anlattırmayanlardan yasattırmayanlardan uzak dur artık! ...

Onlar kimligini caldılar senin.

Sen ask icin savasırken,onlar her seferinde kanattılar yüregini,

Hadi ne olur sevgili...Dön geri...

Yüregimin kapıları ardına kadar acık.. hiç bir zamanda kapanmadı,kapanmayacakta..

Bir bakısına canınımı veririm...

Aglatma beni, yaralama..

Ve... Korkma! ...

Bu ask icin her seyi yapmaya hazırım...

Gel sevdaLım...

Hayatın o ask dolu,güzel tarafını beraber paylasalım...

Gercek sevgi neymis? 

Gel adını Biz Koyalım...

(14/07/2004)', 'Ne güzel günlerdi seninle yasadıklarımız... O günler gözümün önünde canlandıkca icim ürperiyor,gözlerim doluyor.... Hani derler ya ''''erkekle...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz']::text[], 8.5, '{"poet":"Mehmet Yılmaz","poet_slug":"mehmet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/don-geri-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babanın Bekleyişi', 'babanin-bekleyisi-erol-dal-prjhe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Baba, 

üşüdün.

Gir artık içeri.

Gelmeyecek belli.

Kim geldi ki zaten 

Gittiğinden beri geri.

Baba,

Üşüdün.

Gir artık içeri.

O,sımsıcak toprağında

Mışıl, mışıl uyuyor şimdi.

Baba,

Yıldızlar da matemde bak,

Peş peşe kayıyorlar işte.

Hüznün orta yerinde 

Bir sen varsın

Bir de hazan ayları.

Baba,

Üşüdün

Gir artık içeri.

2000/Mekan', 'Baba,  üşüdün. Gir artık içeri. Gelmeyecek belli. Kim geldi ki zaten  Gittiğinden beri geri. Baba, Üşüdün. Gir artık içeri. O,sımsıcak topra...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/babanin-bekleyisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitsin! :.', 'bitsin-mehmet-yilmaz-sfkmy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayatım bir rüzgar misali savrulmaya basladı...

HayaTım asktı benim....

Ama simdi her sey tersine gidiyor...

Bana ''''ask nedir''''? diye sorduklarında cevap veremez hale geldim...

Ask herseyle güzel duyguydu.

Ama incitti beni,yaraladı yüregimi...

Sevmekten korkar hale getirdi...

Her sevgimde acılar cektim.. yalanlarla yüzlestim...

Her askım hüzünle bitti...

Ask; Hayatımın her asamasında karsıma dikildi...

Duygularım o kadar saftı ki; 

Kapıldı,sürüklendi askın varlıgına,

Sevmek istedi...

Hayallerini süsleyen sevgiliyi istedi.

Yasamayı öğreten sevgi istedi.

Sevmek istedi...

Gerekirse ugruna canını vermek istedi...

Dedim ya; Her defasında hüzünle bitti..

Simdi bana ''''ask nedir'''' diye sormayın! ..

Aglamayı,karanlık dünyamı, ne acılar cektigimi sorun! ..

Onlarda hayatın acımasız yönünü göstermek istedi...

Acı cektirmeyi, yürek kanatmayı istedi...

Biliyorum, sevmek suc haline geldi,

Sucluyum! .. cezamı hakketmeliyim...

Hadi zindana mahkum edin beni! ..

Hadi durmayın! .. öldürün beni! ..

Bitsin artık bu hayatın cilesi...', 'Hayatım bir rüzgar misali savrulmaya basladı... HayaTım asktı benim.... Ama simdi her sey tersine gidiyor... Bana ''''ask nedir''''? diye sorduk...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz']::text[], 8.5, '{"poet":"Mehmet Yılmaz","poet_slug":"mehmet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bitsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Buraya Uğramıyor...', 'ay-buraya-ugramiyor-hurrem-yalcin-jhg9x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ay buraya uğramıyor

Kömür karası gece

Kara çalınmış yıldızlara

Her nedense

Ay buraya uğramıyor

Bu gece...

Belki der Şair

Her biri karanlığa

Uzanmış ayrı bir el! 

Ya da,

Sessiz şarkılara esirler

Durur düşünür

Anlamı yok der...

Omuz silker! 

Ay ve yıldızlar neredeler? 

Neden? 

Buraya uğramaktan vaz geçtiler? 

Korsanlara mı esir düştüler...

Sevdaları mı yitirdiler...

Kimlere yenik düştüler...

Ve

Dudak büker Şair...

Neden olduğunu bilemeden

Gözleri kömür karası gecede

Sevdalısı asılı yüreğinde

Ve

Der yeniden ümitsizce

Artık ay bile uğramıyor buralara! 

Ölme vakti mi yakın olan

Yoksa ayın parlak yüzümü sadece kayıp olan

Bilinmez... 

Ve

 İnen iki damlayı

Sevdalısı şefkatle siler gözlerinden....

Yüreği aydınlanır aniden

Sevdalısının sevdası 

Ay ve yıldızlar gibi 

Işıtır tüm dünyasını...

09 Temmuz 04/Kuşadası', 'Ay buraya uğramıyor Kömür karası gece Kara çalınmış yıldızlara Her nedense Ay buraya uğramıyor Bu gece... Belki der Şair Her biri karanlığa ...', ARRAY['Türk Edebiyatı','Şiir','Hürrem Yalçın']::text[], 8.5, '{"poet":"Hürrem Yalçın","poet_slug":"hurrem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/ay-buraya-ugramiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorguların izinde', 'sorgularin-izinde-mehmet-selim-tolay-wse65', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İkibinli yıllara

girdik kardaş aşk ile

kelime-i tevhidi

söktük kalpten ah ile

öyle bir yoklukta

varlığa inandık ki

imanlı hallerimiz

etmez iman vecd ile

sömürülmüş her yanı

bak sen kardaş bu hale

güya islam adına

yapılır olmuş her gaye

Allah ismi sahnede

iblislerin dilinde

peygamberse ağlamaklı

kasetler kisvesinde.

unutulmuş nedense

o ilahi güzel emir

neydi kalem süresinden selam eden ol emir

oku ile başlayan.....hak bir rahim bir

gel gör ki

yaşıyoruz bilmem kaçıncı cahili boyutta

elalem incirlikte elalem marsta

kalmışız günahkar içimizdeki fanusta

yanmışım geçmişine

bizi yobaz görenin

yahudinin dölüne döl atıp çimlenenin

merkeb-i ekber olan AB...''nin

ekmeğine yağ sürüp döneklik diretenin

bu kışlar bu boranlar

billahi bitmez tükenmez

ebu cehil dirilse

inanki kardaş bizimkilere su dökmez

kahrolası yağmacı düşünceden vazgeçmez

inadına sürüklenir cehennem diplerine.

12.07.2004', 'İkibinli yıllara girdik kardaş aşk ile kelime-i tevhidi söktük kalpten ah ile öyle bir yoklukta varlığa inandık ki imanlı hallerimiz etmez i...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Selim Tolay']::text[], 8.5, '{"poet":"Mehmet Selim Tolay","poet_slug":"mehmet-selim-tolay","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sorgularin-izinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükeniş', 'tukenis-masut-toprak-xxjjv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'nesnelerim tükendi 

hayatım zehir.

kapılar kapandı! 

zamanın sesleri; 

tik tak tik tak...

kalem düştü

canım çıktı! 

uçmadı ruhum

günahlarımın ağırlıyla 

kıtlık yaşandı! 

açlık başıma vurdu

başım kırıldı....', 'nesnelerim tükendi  hayatım zehir. kapılar kapandı!  zamanın sesleri;  tik tak tik tak... kalem düştü canım çıktı!  uçmadı ruhum günahlarımı...', ARRAY['Türk Edebiyatı','Şiir','Masut Toprak']::text[], 8.5, '{"poet":"Masut Toprak","poet_slug":"masut-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tukenis-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Gece', 'dun-gece-talip-kaplan-749gm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün gece sabahlara kadar içtim

Her damlayı iki kadehe biçtim

Dört yanımdaki duvarla dertleştim

Dün gece sensiz bir hiçtim

Yıldızlarla kadeh tokuştururken

Hep senin şerefine içtim birtanem

Ve gece yarısı sarhoş olmuşken

Bu şiiri sana yazdım birtanem', 'Dün gece sabahlara kadar içtim Her damlayı iki kadehe biçtim Dört yanımdaki duvarla dertleştim Dün gece sensiz bir hiçtim Yıldızlarla kadeh ...', ARRAY['Türk Edebiyatı','Şiir','Talip Kaplan']::text[], 8.5, '{"poet":"Talip Kaplan","poet_slug":"talip-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dun-gece-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazen Geç Kalabiliyor İnsan', 'bazen-gec-kalabiliyor-i-nsan-melih-coskun-p895w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bazen geç kalabiliyor insan 

Bazı şeyleri yaşamak için 

Çoktan vazgeçmiştim çocukluğumdan 

İlk defa gördüğümde ateş böceklerini 

(Bir yanım hep çocuk kalsa da) 

Ve bundan mıdır bilinmez

Utandım ağlamaktan sevdiklerimin ölümlerine 

Çoktan vazgeçmiştim çocukluğumdan 

Gerçek bir mermi geçtiği zaman üzerimden 

Yüzleri asıktı 

Belki de hiç gülmemişlerdi ömürleri boyunca 

Öldür dediler sadece ölmemek için 

Ölmeyecek kadar çocuktum oysa ben 

Ve öldüremeyecek kadar insan 

Başka şeyler vardı oysa beynimde 

İnsanca ve insana dair 

Aşk gibi hürriyet gibi 

Dağ başlarında değil 

Bir sevgilinin gözlerinde sabahlamak mesela 

Işıl ışıl bir şehrin tan yerinde 

Yorgun argın uzanmak sımsıcak yatağıma

Seni sevmek gibi bir şey vardı oysa beynimde

Bazen öyle geç kalıyor ki insan 

Yaşamak için bir çok şeyi

Yirmi yaşımı çoktan geçmiştim 

İlk defa gördüğümde ateş böceklerini 

Ondandır sürekli çocuk gülümseyişi yüzümün...

(En gerçek türküyü söylemek için uzun bir süre Şırnak Milli''de olacağım. Dönüşümde o türküleri hep birlikte okumak dileğiyle...) 

Jandarma Komando Asteğmen- Melih COŞKUN', 'Bazen geç kalabiliyor insan  Bazı şeyleri yaşamak için  Çoktan vazgeçmiştim çocukluğumdan  İlk defa gördüğümde ateş böceklerini  (Bir yanım ...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bazen-gec-kalabiliyor-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çelişki', 'celiski-osman-i-nci-mf68h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey aşk,

Ey sihirli kelime...

Beni dünyaya küstüren, 

Dertlerle inletip,

Eriten sendin...

Yaşamı sevdiren,

Ümitler verip,

Güldüren de sen oldun...

Boynumu büken,

Kolumu bağlayıp,

Bekleten yine sensin...

Söyle bana şimdi; 

Bu çelişki neden? ..', 'Ey aşk, Ey sihirli kelime... Beni dünyaya küstüren,  Dertlerle inletip, Eriten sendin... Yaşamı sevdiren, Ümitler verip, Güldüren de sen old...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/celiski-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedeni Yok', 'nedeni-yok-osman-i-nci-apkoo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu sevdaya düşeceğime,

Kumar oynasaydım keşke...

Ya da içkiye başlayıp,

Alkolik olsaydım...

Onlardan kurtulmam,

Kolay olurdu belki...

Ama hayır! 

O zaman,

Seni sevemezdim,

Bu duyguları yaşayamaz,

Aşkı tanıyamazdım...

Ölüm cezamı,

Seni sevmekle onayladım,

Ama pişman değilim...

Şunu bil ki; 

Bir kez daha,

Doğma imkânım olsa,

Öleceğimi bilerek,

Yine seni severdim...

Bakma,

Nedeni yok...

Severdim işte! ..', 'Bu sevdaya düşeceğime, Kumar oynasaydım keşke... Ya da içkiye başlayıp, Alkolik olsaydım... Onlardan kurtulmam, Kolay olurdu belki... Ama ha...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/nedeni-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunduğumda', 'dokundugumda-guler-ilgaz-62d4d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dokundum ağaca

Yaprağa, kuma, börtü böceğe

Dokundum taşa

Yaprağa yosuna uçana kaçana

Dokundum havaya

Rüzgara şimşeğe kasırgaya hortuma

Dokundum ateşe aleve ışığa

Bir gözdü

Dokundum kabullenmişti

Teslim olmuştu var oluşuna

....................................

Dokundum insana

Bir figan bir isyan

Bir feryat ki ver yansın

Ortalık toz duman

Göz gözü görmüyor ki

İnsan olmak

Dokunmak üstünde

Var olmayı bilmek anlamak

İnanmak ötesinde

Görebilmek duyabilmek ihtiyacı

İçinde

O......... gözün

Yu-bal-dik

Kor-sun-se

Af-ke-ke-su-len

Bal-bal-dik

Ön-diz-üst

Tu-sun-san

A-se-ke-kı-mun

Bil-se

Ar-a-le-mun', 'Dokundum ağaca Yaprağa, kuma, börtü böceğe Dokundum taşa Yaprağa yosuna uçana kaçana Dokundum havaya Rüzgara şimşeğe kasırgaya hortuma Dokun...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/dokundugumda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenen Bahar', 'beklenen-bahar-osman-i-nci-7happ', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Başlayan bu fırtına,

Ayrılık habercisi...

Çakan şimşekler,

Yaşanan krizlerdir...

Dökülen yapraklarsa,

Aşkımızın gözyaşları...

Bırak birtanem,

Kış geliyor desinler,

Öyle bilsin el alem...

Gerçeği biz biliyoruz,

Aşkımızın hazanı bu...

Ve bu hazanında,

Bir baharı olacaktır...

İşte o bahar,

Bir gün mutlaka,

İnan yaşanacaktır...', 'Başlayan bu fırtına, Ayrılık habercisi... Çakan şimşekler, Yaşanan krizlerdir... Dökülen yapraklarsa, Aşkımızın gözyaşları... Bırak birtanem...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beklenen-bahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlüm', 'gonlum-osman-i-nci-fmoud', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Rotası olmayan,

Bir gemi gibi,

Hedefi bulamayan,

Serseri mermi gibi,

Gezip dolaşıyor,

Diyar diyar...

Uslanmadı bir türlü,

Ah şu gönlüm,

Divane gönlüm...', 'Rotası olmayan, Bir gemi gibi, Hedefi bulamayan, Serseri mermi gibi, Gezip dolaşıyor, Diyar diyar... Uslanmadı bir türlü, Ah şu gönlüm, Diva...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gonlum-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek', 'sevmek-osman-i-nci-jz9o5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevmek...

İçtenlikle,

Yürekten,

Derinlerden sevmek...

Sonsuz bir aşkla,

Taparcasına,

Ölesiye sevmek...

Ama; 

Karşılıksız sevmek,

Sevilmemek...

Aşkını yüreğine gömüp,

Yıkılıp kahrolmak,

Ve bir gün,

O sevdayla ölmek...

Hem de; 

Yaşarken ölmek...

En acı ölüm de,

Bu olsa gerek...

Ben,

Böyle öldüm işte...

Tanrı,

Böyle ölümlerden,

Sizleri korusun...', 'Sevmek... İçtenlikle, Yürekten, Derinlerden sevmek... Sonsuz bir aşkla, Taparcasına, Ölesiye sevmek... Ama;  Karşılıksız sevmek, Sevilmemek....', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sevmek-78-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-osman-i-nci-4p3bx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Öyle sevinçli,

Öyle heyecanlıyım ki,

İçim içime sığmıyor...

Hayat fakültesinden,

Mezun oluyorum...

Azrailin elinden,

Diplomamı alıp,

Sonsuzluk diyarına,

Master''a gidiyorum...', 'Öyle sevinçli, Öyle heyecanlıyım ki, İçim içime sığmıyor... Hayat fakültesinden, Mezun oluyorum... Azrailin elinden, Diplomamı alıp, Sonsuzl...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/olum-129-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorum', 'biliyorum-osman-i-nci-2ojlv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her yağmur sonrası,

Hava açarmış derler...

Senin gözyaşın da,

O yağmura benziyor...

Hava bir açsa diye,

Dualar ediyorum...

O güneşle birlikte,

Güller açacak yanağında,

Biliyorum...', 'Her yağmur sonrası, Hava açarmış derler... Senin gözyaşın da, O yağmura benziyor... Hava bir açsa diye, Dualar ediyorum... O güneşle birlikt...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/biliyorum-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorma-Aldırma-Paylaş', 'sorma-aldirma-paylas-guler-ilgaz-ou0bi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'I

Soru sorma aldırma

El salla ardına bakma

Bil ki her soru bir cevaptır

Her cevap yeni bir sorudur

Dönersin en başa sorarsan

Sus dinle sadece

Boşluğun sesini

El salla döngülerine

Bırak gitsin kapılma

II

Soru sorma

Yaşa deneyimle boş veeer gerisini deee

İlerle korkmadan

Git yüreğinin gösterdiği yere

Nerede olduğunu görebilmen için

Ara sıra bak geriye

Nereye varabilmeyi düşlüyorsan

Oradasın işte

III

Çetindir cevizdir

Zorludur tozludur

Dikenlidir yokuştur

Savaşçı olmalısın yolda başarabilmek için

Terlerin gözyaşları gibi akmalı önüne

Terlerin kan olur sonunda

Serttir kabukları cevizlerin

Bunuuu

Göze alman gerek

IV

Soru sorma biliyorsun ki

En olgun meyve

En yüksek daldadır

Bunca mücadele bunun içindir

Görmen gerek

Kırman gerek kabuğunu

İçin içini 

Yemeden önce

V

Soru sorma yarısını ye

Yarısını dik soru sormadan önce

Tüm savaşının bu olduğunu

Bilene dek', 'I Soru sorma aldırma El salla ardına bakma Bil ki her soru bir cevaptır Her cevap yeni bir sorudur Dönersin en başa sorarsan Sus dinle sadec...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/sorma-aldirma-paylas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'iTiraf', 'itiraf-baykal-kaanalp-j7rpe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'içimde bir savaş var

anlatılmaz duygular

ne seni unutabiliyorum

ne de kendimi

ne bir çiçek açıyor gönlümde

ne de güllere su veriyorum

ne sana bakıyorum doyasıya

ne de kendi kendime

sanmaki ayrılmaz ikiliyiz

kalplerimiz bitişik

ne sana kızabiliyorum sinirsizca

ne de kendime

kapılmazdım senin aşkına

fırtınalar dinmişti

ne seni unutabiliyorum aylarca

ne de kendimi', 'içimde bir savaş var anlatılmaz duygular ne seni unutabiliyorum ne de kendimi ne bir çiçek açıyor gönlümde ne de güllere su veriyorum ne san...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/itiraf-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Çıktın Karşıma', 'neden-ciktin-karsima-baykal-kaanalp-jbyun', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'neden çıktın

son demlerinde hayatımın

seni tanıdım 

sana kapıldım

neden çıktın karşıma bilmem

yaşayıp gidiyordum kararsız

son demlerinde hayatımın

seni gödüm 

seni tanıdım

keşke ilkbaharda olsaydı

karşılaşmamız

keşke yağmur yağmasaydı

ak saçlarıma

son demlerinde hayatımın

seni soludum

seni düşledim

neden çıktın önüme bilmem

kaldırımda bile yürüyeme', 'neden çıktın son demlerinde hayatımın seni tanıdım  sana kapıldım neden çıktın karşıma bilmem yaşayıp gidiyordum kararsız son demlerinde hay...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/neden-ciktin-karsima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitirdiklerimize', 'yitirdiklerimize-mehmet-elmacioglu-bl5dm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hani bir mayıs akşamı ikimiz,

Düşmüşüz buz gibi rakının içine de,

Kağıttan gemilerimizi yapıyoruz,

Ulaşabilmek için yitirdiklerimize.

Meydanlarda tükenen gençliğimize,

Biz ilk kez kendimize ağlıyoruz.

Direnmişiz çözülmeden işkencelere de

Yaşanmamış aşklara yenilmişiz.

Atıldı en iyilerimiz kurşunların önüne,

Daha mı kötüydü içeride çürüyenlerimiz,

Aldırmadan sırtımızdaki hançerlere,

Biz dışarıda her gün ölenlerDENİZ', 'Hani bir mayıs akşamı ikimiz, Düşmüşüz buz gibi rakının içine de, Kağıttan gemilerimizi yapıyoruz, Ulaşabilmek için yitirdiklerimize. Meydan...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Elmacıoğlu']::text[], 8.5, '{"poet":"Mehmet Elmacıoğlu","poet_slug":"mehmet-elmacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yitirdiklerimize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resimler', 'resimler-osman-i-nci-dx3of', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sanki canlı gibi, sohbet ederiz,

Eski günlerimizi anar, güleriz,

Piste çıkar, bir de dans ederiz,

Albümdeki o resimlerle...

Öyle dans etmekten, yoruluruz,

Karşı karşıya geçip, otururuz,

Birbirimize, şiirler okuruz,

Albümdeki o resimlerle...

O tatlı günleri, böyle anarız,

Geleceğimize, ümitle bakarız,

Tanyeri ağarınca, vedalaşırız,

Albümdeki o resimlerle...

Diyar diyar gezer, sabah ederiz,

Uykusuzluktan, şişer gözlerimiz,

İşte böyledir, tüm gecelerimiz,

Albümdeki o resimlerle...', 'Sanki canlı gibi, sohbet ederiz, Eski günlerimizi anar, güleriz, Piste çıkar, bir de dans ederiz, Albümdeki o resimlerle... Öyle dans etmekt...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/resimler-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'neDen ÖYLE baktın', 'neden-oyle-baktin-baykal-kaanalp-dojr8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'başka yolu kalmadı

kendin istedin

ne kadar uğraşsam nafile

gözümden atamıyorum seni

seni ve de yakıcı bakışlarını

neden öyle naktın ki? 

sanki oyuncak bebeği

elinden alınmış

bir kız çocuğu gibi

baktın ve de yaktın

kendime çok güvendiğim

aşılmaz bir surla çevirdiğim

gönlümü

yakmayı başardın

bense bi ton odunla

ısıtamıyordum

sense bir bakışınla 

yaktın geçtin

kül olmaya ramak kaldı

iyi ki zamanında

yetiştimde

bi kova suyla

ıslattım

söndüremedim

sadece ıslattım

senin anlayacağın

günü kurtardım

zaten benim olmayan günü

günlerim ve de gecelerim

benim değil artık

otomatik plota bağlanmış gibi

sana doğru akıp gidiyor

allah verede bir kazaya

kurban gitmese

zaten fark etmezde

zaten yanmışım

ateşli gözlerinde

zaten kül olmuşum

bir de kazaya kurban gitsem

ne olur? 

söner mi? 

şehrin ışıkları

üzerimizde', 'başka yolu kalmadı kendin istedin ne kadar uğraşsam nafile gözümden atamıyorum seni seni ve de yakıcı bakışlarını neden öyle naktın ki?  san...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/neden-oyle-baktin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
