INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben ve Bizim Çocuklar(Barış Aluk ve Mutlu Ayar dostlarıma)', 'ben-ve-bizim-cocuklar-baris-aluk-ve-mutlu-ayar-dostlarima-ahmet-aksoy-vl3jz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '...................Barış ve Mutlu dostlarıma

