INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dizelerimi Hissetmiyorsun VI (Gen Bencildir*) **', 'dizelerimi-hissetmiyorsun-vi-gen-bencildir-cumhur-boratav-p6vbc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '*Richard Dawkins''in Gen Bencildir (Selfish Gene)  kitabını okudunız mu? 

**Dostum Haldun Hakman''a

Gün ışığının keskin kenarını

Bilediği günlerdi

Aslında zaman gün değildi

Boştu

O sıralar 

Sen bir hiç bile değildin

Fazla sıcak 

Ve fazla soğuktun

Buradan baktığımda karanlıktın

Benim noktacık gölgem

Su ve ışık, işte sen bundan doğdun

Kendine sarmalanmamıştın bile daha

Hapşırmak ya da burnunu silmek

Heyecanlanmak, sevişmek

Uzak biçimlerdi bunlar

Yapacak bir şeyin yoktu, 

Amaç

Varmak istediğin yer 

Hepsi hepsi bir rastlantının keskin kenarı

Belki de bir olasılık

Hani olabilme olasılığı

Yaşamda kalabilmek bir bencillikti

Çoğalmak bir yoketme

Bencil olmadan ben olamazdın

Sana bir sır

İnsan olacağını bilmiyordun aslında

Sen en bencil olasılıktın

Artık ne fazla sıcaksın

Ne de fazla soğuk, ama derini ve kaslarını

Kemiklerini

Üstünden sıyırarak bak

Noktacıklarındaki gün ışığı hala keskin

İçindeki küçük su hala dansediyor onunla

Hala kaynıyorsun

Ve sen

Hala daha bir rastlantısın

(Hissetmiyorsun)', '*Richard Dawkins''in Gen Bencildir (Selfish Gene)  kitabını okudunız mu?  **Dostum Haldun Hakman''a Gün ışığının keskin kenarını Bilediği günl...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Boratav']::text[], 8.5, '{"poet":"Cumhur Boratav","poet_slug":"cumhur-boratav","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/dizelerimi-hissetmiyorsun-vi-gen-bencildir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne?', 'ne-fatih-soyler-pl7gq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ona “bey” demezler,

          demesinler zaten:

bey değildir o

ne de efendi.

o bir garip adem; 

çantasında bir defter, bir kalem,

yüreğinde vazgeçemediği fırtınalar…

an olur, şimşek çakar,

aydınlanır günleri… 

(Temmuz, 2004, İstanbul)', 'ona “bey” demezler,           demesinler zaten: bey değildir o ne de efendi. o bir garip adem;  çantasında bir defter, bir kalem, yüreğinde ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Söyler']::text[], 8.5, '{"poet":"Fatih Söyler","poet_slug":"fatih-soyler","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ne-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirimin Yıldız Örgüsü', 'siirimin-yildiz-orgusu-necmi-unsal-quxnq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Menekşe kokulu dağın garip bülbülü benim.

Bir pınarım...    Yamaçlardan  akarım yavaş yavaş.

Ateşini tutuşturdu zümrütlerden  bedenim.

Hararetim sevdalardan,  ne su isterim, ne  aş.

Hallacın külleri ile buluştum nur gölünde.

Sevgi yıldızından esin, şiirimin  örgüsü.

Coşar iman çağıltısı  gönlümün pak tülünde.

Ezelî yazıt alnıma, bâkî birlik çözgüsü.

26 Nisan 2004 Pazartesi, Danimarka-Køge 23.26

8+7', 'Menekşe kokulu dağın garip bülbülü benim. Bir pınarım...    Yamaçlardan  akarım yavaş yavaş. Ateşini tutuşturdu zümrütlerden  bedenim. Harar...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/siirimin-yildiz-orgusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** Çelişkilerin Kadını -1', 'celiskilerin-kadini-1-abir-zaki-ycmi0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dostum… 

şaşırtmasın, 

uğratmasın hayal kırıklığına sözlerim 

cehennemin olurum yasak aşklarında 

cennetin olurum aşka susamışlığında 

ben çelişkilerin kadınıyım... 

sürmeli bakar dünyaya gözlerim 

kurşun gibi deler geçer sözlerim 

bozgunların, yenilgilerin 

ve hezimetlerin kadınıyım 

gün batımlarıyla oynaşır yatarım 

gece yarısında uyanır 

gitar ritmlerine raks ederek kalkarım... 

dalmayı hiç deneme sakın 

böyle bir kadının okyanusuna 

henüz uzanırken onun kıyılarına 

ve demir atarken limanlarına 

başlamadan biter tüm yolculuklarım... 

kırılmasın düşlerin 

çelişkili düşüncelerimden 

çünkü ben yüzeyselim, derinliğim

oldukça şefkatli 

aynı zamanda esen rüzgarım 

ve yerden yere vuran boranım... 

kendine aşık bir kadınım 

hem erkeksi hem dişiyim 

dünyanın tüm kadınlarıyım 

melek kadar temiz 

şeytan kadar kötüyüm ben... 

ben bir çocuğum

kendi içinde işkence görmüş bir kadınım 

inatçılık ve yaramazlık 

dişi dünyamdaki çocuğun yankıları 

ve

benim yüzümdür 

bileziklerim, aynalarım 

söylediğim mahremlerim 

ve sırlarımdır... 

her yaşta mücadele veren kadınlar gibi 

yastığıma baş koyan kadınım 

rüya görürüm, düşlerim bazen 

ilahiler mırıldanır, dualar okurum 

şarkılar söylerim kimi zaman 

gülümserim bilinmeyenlere içimdeki kadınla 

onun beklediği ve hiç başlamayan yolculuğunda... 

işte böyle inatçı bir kadın bu

hoşlanır oyuncak bebeğime bağırmaktan 

sınırlarımı zorlamaktan 

gözlerimin rengine alaylı gülmekten 

ve zaferini tüm dünyaya haykırmaktan... 

Dostum...

her an, her zaman 

seni özleyen, seni arzulayan 

hasretini çeken 

düşlerinde seninle saraylar inşa eden 

bir an seninle 

öteki an sana karşı duran 

günlere ve kaderine meydan okuyan 

bu kadında ne bulursun ki 

ümitsiz ve imkansız bir aşk olur 

henüz başlamadan.... 

bu kadın ki, 

sana en güzel giysileri giydirir 

gücünü Samson’dan alarak 

siyah saçlarını tıraş edip tarayarak 

sana gizemler, sırlar getirir

yenilgiye uğramış, zafer kazanmış 

elinde bir püro ve 

peçelerle örtülmüş 

hem kötü tercihlerini

ve yanlış seçimlerini 

sana anlatabilecek kadar cesur kalmış... 

şarkılar söyleyip yuhalanınca 

tereddüt etmeye bile zaman bulamadan 

kaçacaksın biliyorum! 

kendine çekip 

kalbini çalan bu kadından 

çelişkilerle dolu bir kadınım ben 

evet! 

aynı anda 

ateş ve buzla oynayan

etrafı güneşle sarılmış bir kadın 

avuçlarında mehtap açan 

yıldızları tutan 

...bir kadın... 

Dostum... 

şaşırtmasın sözlerim seni 

giyinen ve soyunan 

bir kadından daha ihtişamlı 

başka bir şey olamaz 

böyle bir kadına 

dünya gelse karşı duramaz

ve

şaşırmaktan kendini alamaz... 

Ve Sen... 

hep çamur ve kerpiçten bir adam olarak kalacaksın 

sözlerimin peşinden koşacaksın 

ve seni her teslim alışımın ardından 

şaşacaksın her an

şaşıracaksın her zaman

evet şaşacak... ve şaşıracaksın... 

her yağışımın ardından eriyecek 

ve her esintimden sonra yıkılacaksın...

Temmuz 2004

“BU MUHTEŞEM ŞİİRİ ÇEVİRMEK VE ORİJİNAL ANLAMLARINI AKTARMAK ÖYLE ZORDU Kİ, ANLATAMAM. ELİMDEN GELDİĞİNCE, DİLİM DÖNDÜĞÜNCE BU KADAR YAPABİLDİM, AFFOLA! DOSTLAR BU GÜZEL ŞİİRİ OKUYABİLSİN DİYE. SEVGİLER.”  Muammer Çelik. 

Sevgili okurlar, bu şiirim bir çeviriden daha çok, sayın M. Çelik tarafından yeniden Türkçe yazılmıştır ve orijinal şiirimin altında yazdığı dip notu sizlerle paylaşmak istedim. Emeğine ve kalemine teşekkürlerimi sunuyorum..... Sevgiler.... Abir

***************************************************************************************

A Woman of Contradiction...1 

My Friend…. 

don’t be puzzled and confused at my words 

I am the woman of contradictions 

I am the heaven and I am the hell …

I am the woman with darken eyes 

with the most brutal words 

a defeated woman 

who slumbers with the sun set 

who stays up at night playing guitar… 

do not try to sail in a woman’s ocean 

when you reach her shore and anchor at her harbor 

the journey ends… 

do not get confused with my thoughts 

I am the surface and I am the depth 

I am the most compassionate, 

I am the wind and I am the hurricane… 

I am the woman who is in love with herself 

both the male and the female 

I am all the women of the world 

angelical and evil … 

I am a child and within me a tortured woman 

In my stubbornness and naughtiness 

are the echoes of the children 

In my feminine world 

are faces, bracelets, and mirrors 

they confide and converse… 

like all women of all ages who struggle, 

I am like 

the woman who sleeps on my pillow 

at times she dreams and sometimes she hymns 

and sometimes she sings 

at times she smiles at the unknown 

and I smile with her at her journey of waiting … 

and here’s a stubborn woman 

she likes to bawl at my dolls 

and exceeds my limitations 

she laughs and mocks at the color of my eyes 

and then she publicizes her victory… 

my friend, what do you see in a woman 

who all the time longs for you 

who builds a castle with you 

one who is with you and against you 

and challenges the days and the destinies… 

the woman who dresses you with the most beautiful clothes 

cuts your beautiful black hair 

the hair of the powerful Samson 

the woman who conveys you secrets and mysteries 

who is defeated and triumphed 

who is veiled and with a cigar 

and who dares to confess to you of her ill choices…. 

a woman who approaches your heart 

and when it chants and hisses, 

you don’t hesitate to run away...and you do… 

I am a woman full of contradictions 

yes, I am the one who plays with the fire and ice at the same time 

I am the one who is encompassed by the sun 

and in my palms are the moons and the stars 

my friend, don’t be confused… 

there’s nothing more magnificent than a woman 

who puts on a dress and takes it off 

and with her, the world can’t help but be confused... 

And 

you will always be a man from a brick…from clay…. 

you will always come after my words…after the invader… 

you will always be confused… confused… confused…. 

2003', 'Dostum…  şaşırtmasın,  uğratmasın hayal kırıklığına sözlerim  cehennemin olurum yasak aşklarında  cennetin olurum aşka susamışlığında  ben ç...', ARRAY['Türk Edebiyatı','Şiir','Abir Zaki']::text[], 8.5, '{"poet":"Abir Zaki","poet_slug":"abir-zaki","theme":"Türk Şiiri","is_hero":false,"total_lines":174,"source_url":"https://www.antoloji.com/celiskilerin-kadini-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otobüs', 'otobus-i-brahim-yamac-bmja0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'herkes aynı demiri tutuyor

bir tomruğa omuz vermiş köylüler örneği

selamı unutmuş insanların icadı

bu yeni bir tokalaşma yolu olmalı

/şehirde demir her işe yarar

insanlar soğuktur demir kadar/

bir çocuk uyuyor

başı babasının kucağında 

ayakları annesinin...

insanlara el değmemiş

hallerini resmediyor

biri katlamış gazete okuyor

biri gazeteyle kaplanmış kitap...

bir genç geometri çözüyor

/ikiye bölünmüş sayfalar

sayfabaşı altı üçgen var/

üniversiteye girecek

dünya pembeliğe bırakacak kendini

dağın ardında dağ var; bilmiyor

bir genç oturmuş yanılıyor

bir oğlan bir kız 

açığa vurmuşlar hallerini

aşkı ıskalıyorlar

birinin kafası camda

uykuyla uyanıklık arasında 

hercai bir halin adamı

tek derdi ikide bir

otobüsün tiril tiril titreyen camı

biri dışarıya bakıyor biri içeriye

biri havaya bakıyor biri yere

birbirine bakan kimse yok

motor homurdanıyor insanlar dinliyor

yadırgamak gelmiyor kimsenin aklına

herkes alışık; heryerde makinalar inliyor

motorlar hareket veriyor şehrin çarkına

biz atlarımızı özledik', 'herkes aynı demiri tutuyor bir tomruğa omuz vermiş köylüler örneği selamı unutmuş insanların icadı bu yeni bir tokalaşma yolu olmalı /şehird...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yamaç']::text[], 8.5, '{"poet":"İbrahim Yamaç","poet_slug":"i-brahim-yamac","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/otobus-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İm/di | Basit mi |', 'i-m-di-basit-mi-zafer-zengin-etnika-upmzu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İm/di

idi

şimdi

Geçti

Biçti

Ses kesti

Suskunluk içti

İm/di

biçip gitti

Yok ki

Yandı kül oldu

çekti gitti

19 Temmuz 2004', 'İm/di idi şimdi Geçti Biçti Ses kesti Suskunluk içti İm/di biçip gitti Yok ki Yandı kül oldu çekti gitti 19 Temmuz 2004...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/im-di-basit-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tik Tak - Tik Tak', 'tik-tak-tik-tak-can-ozeken-5ajb8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Saat karşımda

Durmadan işliyor,

On geçiyor onbiri

Onbir geçiyor 

Oniki

Onüç

Ondört

Onbeş.

Bitmeyecek mi bu hesap? 

Bitecek, bitecek; 

Beyaz bir mermerde

Siyah bir yazıyla

Bir toprağın başında

Doğum tarihi ölüm tarihi diyecek

Peki saat? 

Tik tak, Tik tak

On geçecek onbiri

Onbir geçecek 

Oniki

Onüç

Ondört

Onbeş...

Bitmecek mi bu tik tak? 

Bitecek, bitecek 

İşte o gün büyük bir alanda

Herkes hesap verecek...!', 'Saat karşımda Durmadan işliyor, On geçiyor onbiri Onbir geçiyor  Oniki Onüç Ondört Onbeş. Bitmeyecek mi bu hesap?  Bitecek, bitecek;  Beyaz ...', ARRAY['Türk Edebiyatı','Şiir','Can Özeken']::text[], 8.5, '{"poet":"Can Özeken","poet_slug":"can-ozeken","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/tik-tak-tik-tak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağımsızlık Destanı...', 'bagimsizlik-destani-seref-yildirim-cwkhl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'zor günlerdi zor ki ne zor /

emperyalistlerin işgalindeki günler...

yurdumuzun her yanı işgal edilmiş,

silahsız korunmasız bırakılmıştı

koskoca imparatorluk dağılmış

padişah çaresiz,ordu başsız kalmıştı

süperlerin palikaryaları Helenist hayalleriyle  

adileştikçe adileşmiş,ırz namus tanımaz olmuştu

işte böyle günlerin birinde...19 mayıs 1919 da 

Bandırma vapuru umut taşımıştı Samsundan  

Mustafa Kemal ve arkadaşlarıyla

genelgeler,kongreler sonunda çizilmişti Misaki  milli sınırları

yurdun her sathı korunacaktı karış karış

temizlenecekti  işgalci  pisliklerden

ninesi,dedesi.kızı,kızanı el ele verdilerde

bağımsızlık mücadelesinin şanlı bayrağını diktiler 

Kuvayi- Milliye si, batıda tek güç olarak görünürken

Çerkez Ethemi,Yörük Ali si,.Demirci Efesiyle...

bir bütün boğdular düşmanı  püskürtüler gerilere

artık tüm ulus uyanmıştı özgürlüğüne

düzenli ordular kurulmuşdu bin bir fedakarlıkla

silahları giysileri  aşlarında tüm insanların emeği yatıyordu 

yirmi yedi milyon tek yürek atıyordu 

başardılar...sonunda

İnönü de,Sakarya da,Dumlupınar da 

ve nihayet; 

Baş komutanlık Meydan Muharebesinde

binlerce şehit ve gazi uğruna

kazmasıyla küreğiyle dişiyle tırnağıyla

koskoca bir bağımsızlık destanı yazdı Türk ulusu 

tarihin sayfalarına...

Baş Komutanları Mustafa Kemali

İsmet İnönü’sü,Kazım Kara Bekir’i,Fevzi Çakmağı 

binlerce yiğit adsız kahramanlarıyla...

Türklerin atası ATATÜRK kurtuluş mücadelesi devrimleri  ilkeleriyle

ve  dehasıyla yüzyıllara damgasını vurarak

düşmanlarının bile takdirini kazanarak kurdu bu CUMHURİYETİ

bizlere de sonsuza dek yaşatmak kalıyor 

laik ve çağdaş medeniyet seviyesinde...

19.07.2004

Şeref Yıldırım', 'zor günlerdi zor ki ne zor / emperyalistlerin işgalindeki günler... yurdumuzun her yanı işgal edilmiş, silahsız korunmasız bırakılmıştı kosk...', ARRAY['Türk Edebiyatı','Şiir','Şeref Yıldırım']::text[], 8.5, '{"poet":"Şeref Yıldırım","poet_slug":"seref-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/bagimsizlik-destani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyü bozucu ellerin', 'buyu-bozucu-ellerin-ozgur-doran-vsv5l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşk birbirinin ardındaki 

                     P

                     E

                     N

                     G

                     U

                     E

                     N 

               sırası

                             gibi

Her aşk öncekinin

T     A        K         İ          P           C          İ        S           İ

Ellerin değiyor yüzüme.........

Büyü bozucu ellerin sıcak...', 'Aşk birbirinin ardındaki                       P                      E                      N                      G                      U...', ARRAY['Türk Edebiyatı','Şiir','Özgür Doran']::text[], 8.5, '{"poet":"Özgür Doran","poet_slug":"ozgur-doran","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/buyu-bozucu-ellerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçek', 'cicek-ozgur-doran-ecv4h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'içimde çiçekler açıyor yüzüne baktığımda 

ellerim...

yüzüne uzanıyor..

dokunmak için...

gittikçe çiçek..

oluyorum..', 'içimde çiçekler açıyor yüzüne baktığımda  ellerim... yüzüne uzanıyor.. dokunmak için... gittikçe çiçek.. oluyorum.....', ARRAY['Türk Edebiyatı','Şiir','Özgür Doran']::text[], 8.5, '{"poet":"Özgür Doran","poet_slug":"ozgur-doran","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/cicek-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rahmin', 'rahmin-ozgur-doran-csaad', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'beni doğur sevgilim...

seni yeniden sevebilmem için.

rahmin de bir acı olmalı

aşk..', 'beni doğur sevgilim... seni yeniden sevebilmem için. rahmin de bir acı olmalı aşk.....', ARRAY['Türk Edebiyatı','Şiir','Özgür Doran']::text[], 8.5, '{"poet":"Özgür Doran","poet_slug":"ozgur-doran","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/rahmin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neye Yarar Mehtabım', 'neye-yarar-mehtabim-murat-demir-a13nq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayalimden çıkmıyor giderken son duruşun

Boğazıma sarılıp hıçkırıkla vuruşun

Kaç yaz geçti aradan bakarım yollarına

O gün bugün almadım kimseyi kollarıma

Çok acılar çekmişim sen bilmezsin sensizken

Karanlığında kaldım güneş doğacak derken

Çıkmasın ay ve yıldız  yanımda olmayınca

Neye yarar mehtabım seninle dolmayınca

O ağacın altında artık hiç yatmıyorum

Bilir misin denize taş bile atmıyorum

Uzaklara çoğu kez yüzer gibi dalarım

Artık eskisi gibi tadı yok buraların

Yorgun argın gözlerim görmüyor ırağını

Bana aşk ayazının yedirdin kırağını

Can dediğin taş değil atılmaz ki atasın

Sen yoksan neye yarar varsın o da olmasın

Aramızda aşılmaz dumanlı dağlar mı var

Hala yıkılmadı mı senin orda duvarlar

Yoksa seni dünyanın dışına mı attılar

Sevda kitabımızı böyle mi kapattılar', 'Hayalimden çıkmıyor giderken son duruşun Boğazıma sarılıp hıçkırıkla vuruşun Kaç yaz geçti aradan bakarım yollarına O gün bugün almadım kims...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/neye-yarar-mehtabim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çirkinlikler...', 'cirkinlikler-sirma-mersin-zpkxq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beynimin içinde

Zehir zemberek sözleri...

Yılanın çatal dilinden akıtır gibi, boşaltıyorsun 

Düşüncelerime...

Yarasa gibi, yaşama ters bakan

Timsah gibi sahte gözyaşları döken

Baykuş gibi acı sesinle...

Hangi hayvana benzeteceğimi şaşırdım

Hangi kötülüğü taşıdığını

Bilmiyorum...

Korkunç ve ürkütücü alemin içinde

Kabusa dönüyor hayatım...

Hadi git, yanımdan...

Hatırlamak istemiyorum,

Hiçbirşeyi...

18.07.04

                 '' Gözümün önünde geçen kavgada, 

                    İnsanların sergilediği çirkin hallerden sonra... yazılmıştır! ''', 'Beynimin içinde Zehir zemberek sözleri... Yılanın çatal dilinden akıtır gibi, boşaltıyorsun  Düşüncelerime... Yarasa gibi, yaşama ters bakan...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cirkinlikler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Sevgiliye 1', 'ey-sevgiliye-1-fatih-taskin-53imr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şeytanın şerrinden kaçtım,sana sığındım

İmanımı madalya gibi göğsüme takdım

Tövbe ederek içimdeki aşkı yaktım

Ben hep seni aradım namazlarımda....

Ama sen yoktun gözyaşlarımda....

Aşkın alevlenmişti günahkar yüreğimde

Helalime bereket geldi,haramdan elimi çekince

Huzuruna çıkıyorum günde beş vakitle..

Ben hep seni aradım namazlarımda...

Ama sen yoktun gözyaşlarımda...

Abdest alırken vardım suyun sırrına

İsraf etmedim hiç, vardır muhtaç bir  bardağına

Aklım almadı,nasıl dayanmışlar o çöl sıcaklarına

Ben hep seni aradım namazlarımda...

Ama sen yoktun gözyaşlarımda...

Aşkın alevine kibrit olur, okunuca ezan

İçimdeki şeytan  çıldırır feryat figan

Ter basar beni, aklıma düşünce yaradan

Ben hep seni aradım namazlarımda...

Ama sen yoktun gözyaşlarımda....

İşime bereket,evime huzur geldi günaha girmeyince

Yaradanıma sığındım, uydukça şeytanın şerrine 

Peygamber efendimiz şahit olsun inananlara ahirette

Ben arayınca seni buldum namazlarımda

Seni bulunca,kendim kayboldum gözyaşlarımda....

Seni bulunca kendimi buldum ben aşkınla.....

temmuz....2004

siyah bereli...', 'Şeytanın şerrinden kaçtım,sana sığındım İmanımı madalya gibi göğsüme takdım Tövbe ederek içimdeki aşkı yaktım Ben hep seni aradım namazlarım...', ARRAY['Türk Edebiyatı','Şiir','Fatih Taşkın']::text[], 8.5, '{"poet":"Fatih Taşkın","poet_slug":"fatih-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ey-sevgiliye-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boğuluyorum', 'boguluyorum-orhan-mahir-kizilboga-bdrcn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Parçalarına ayırdığım bir silahtı zaman

Birleştirip birleştirip beni vurduğum.

Küçük bir kuştu sevgim sende 

Uçup gittiğin an yitirdiğim.

İnadına savaştım 

İnadına yazmadım gecelerce.

Unutmuşum en güzel düşler

Sensizlikle başlar 

Senle biterdi.

Aslında neler unutmadım ki

Geride bıraktığım benleri mi? 

Ölümüne yaşadığım gözleri mi? 

Hey hat...

Dışarıda yağmur

Islak bir ilkbahar,

Ve yemyeşil bir deniz senin gözlerin,

BOĞULUYORUM...', 'Parçalarına ayırdığım bir silahtı zaman Birleştirip birleştirip beni vurduğum. Küçük bir kuştu sevgim sende  Uçup gittiğin an yitirdiğim. İn...', ARRAY['Türk Edebiyatı','Şiir','Orhan Mahir Kızılboğa']::text[], 8.5, '{"poet":"Orhan Mahir Kızılboğa","poet_slug":"orhan-mahir-kizilboga","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/boguluyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalem Kağıt', 'kalem-kagit-orhan-mahir-kizilboga-4etwg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Özgür bıraktım bu gece düşlerimi 

Alabildiğine yazsınlar diye.

Beyazı özlemişim, siyahla dansını

Ve umudumu atmışım sandala

Açıkta bir yerlere bırakmışım...

Hadi! 

Umutsuz yaşayamam ki

ŞİİRSİZ..

Yıllarca yazmışım her şeyimi.

Kendimi bulmuşum.

Sen mi alıkoyacaksın beni onlardan,

Sen mi sileceksin dertlerimi

Benim yazan 

Kalem ben,

Kağıt ben...

Ne ilhan ne irem 

Alamayacaklar benden.

Şiir kızım bu

Varlığımın varlığında buluştuğu,

Bitirilmemiş dizelerde

Gözlerindeyim her dem...', 'Özgür bıraktım bu gece düşlerimi  Alabildiğine yazsınlar diye. Beyazı özlemişim, siyahla dansını Ve umudumu atmışım sandala Açıkta bir yerle...', ARRAY['Türk Edebiyatı','Şiir','Orhan Mahir Kızılboğa']::text[], 8.5, '{"poet":"Orhan Mahir Kızılboğa","poet_slug":"orhan-mahir-kizilboga","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kalem-kagit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aylardan Temmuz', 'aylardan-temmuz-burhan-kucuk-k1tng', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aylardan Temmuz

Aylardan Temmuz

Ortalık boz bulanık

İçimde yanar ateş

Kalbim bir kalıp buz

Aylardan Temmuz

Soğuk mu soğuk deniz

Gönlümde sen

Senin kalbin yap boz

Aylardan Temmuz

Geçip gidiyor amansız

Uğramıyor yüzüme güneş

Ay ışığına hasret yakamoz

Burhan KÜÇÜK

Kdz.Ereğli-18.07.2004', 'Aylardan Temmuz Aylardan Temmuz Ortalık boz bulanık İçimde yanar ateş Kalbim bir kalıp buz Aylardan Temmuz Soğuk mu soğuk deniz Gönlümde sen...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/aylardan-temmuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolcu', 'yolcu-melek-ozgoz-4cdf3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çokça zaman geçti üstünden

Çok şeyin gelmişken ben üstesinden

Bu geliş aniden niye,,

Kaybedilen herşeyi bulman için

çok geç değilmi

aşkta zaman diye birşey yoktur.

çünkü zamanla ölçülemez verdiği acılar

ve mutluluklar

zamanı doldu diye düşünülemez

anlaman için yaşadıklarımızı

görmen için gerçekleri

bir süre yoktuki sana tanıdığım

gel geri dön diye,

pişman olup ağla karşımda diye

bir ah''tım yoktuki

Ne yaparsan onu görüyorsun bak

Koparken içindeki mevsim yaprak yaprak

Bir zamanlar bana yolcu ismini vermiştin

Bu isimle yaşadım

Yaşlandım anlamayarak

saçlarımda sazının telleri bembeyaz oldu

bana verdiğin gül gidişinle sarardı soldu

şimdi sana diyeceğim ey yolcu...

Bende sana verecek ne aşk,

Nede bir ben kaldı...

19.07.2004', 'Çokça zaman geçti üstünden Çok şeyin gelmişken ben üstesinden Bu geliş aniden niye,, Kaybedilen herşeyi bulman için çok geç değilmi aşkta za...', ARRAY['Türk Edebiyatı','Şiir','Melek Özgöz']::text[], 8.5, '{"poet":"Melek Özgöz","poet_slug":"melek-ozgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yolcu-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümidim Kalmadığından', 'umidim-kalmadigindan-caner-kuru-auq7i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu gece nedense uykum gelmiyor,

Belki de huzurum kalmadığından.

Geceler bir türlü bitmek bilmiyor,

Her halde yanımda olmadığından.

Ben aşkı, sevdayı böyle sanmazdım,

Söyleseler bile hiç inanmazdım

Ateşe atsalar böyle yanmazdım,

Belki de canımı almadığından.

Bir arasan, sorsan ne olur yani,

Hiç vicdanın yok mu, insafın hani? 

Yırttım mektupları, resimlerini,

Artık hiç ümidim kalmadığından.', 'Bu gece nedense uykum gelmiyor, Belki de huzurum kalmadığından. Geceler bir türlü bitmek bilmiyor, Her halde yanımda olmadığından. Ben aşkı,...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/umidim-kalmadigindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Kelebeğim', 'beyaz-kelebegim-i-brahim-ocak-onc48', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ya kara bulutlar perde olursa güneşe

Ya yağmurlar düşerken çiçeklere

Ya bir damlası narin kanatlarına değerse

Ya sen bir daha uçamazsan kelebeğim

Korkma, korkma sen hiç buna izin verir miyim

Kıyamam sana benim biricik bebeğim

Sen benim nadide beyaz kelebeğim

Senindir gönlüm yüreğim ve tüm düşlerim

Aşkımın ve sevdamın ihtişamıyla

Özlem ve sevgimin sadakatıyla

İçinde renk renk yalnız senin için açan çiçekleriyle

Bir köşk yaptım gönül bahçeme

Biricik kelebeğim içinde özgürce uçsun diye', 'Ya kara bulutlar perde olursa güneşe Ya yağmurlar düşerken çiçeklere Ya bir damlası narin kanatlarına değerse Ya sen bir daha uçamazsan kele...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ocak']::text[], 8.5, '{"poet":"İbrahim Ocak","poet_slug":"i-brahim-ocak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/beyaz-kelebegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'en-parlak-yildiz', 'en-parlak-yildiz-muammer-celik-x93d1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gecenin lacivertinde 

ay ışığı ile dans eden 

en parlak yıldıza merhaba… 

O yıldız ki, doğar karanlığıma her gece 

kaybolur her sabah, gözümde bir hüzünle…

BirDeli

19.07.2004', 'gecenin lacivertinde  ay ışığı ile dans eden  en parlak yıldıza merhaba…  O yıldız ki, doğar karanlığıma her gece  kaybolur her sabah, gözüm...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/en-parlak-yildiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alelacele', 'alelacele-zeycan-monteleone-bn4gg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Son nefesi de çekip 

Alelacele kalkıyorsun masadan

Senin hayatın

Bir yudumda içtiğin kahve

Üç lokmada yediğin yemek

Yazık

Ardında kalan bir çift göz için

Zamanın yok demek', 'Son nefesi de çekip  Alelacele kalkıyorsun masadan Senin hayatın Bir yudumda içtiğin kahve Üç lokmada yediğin yemek Yazık Ardında kalan bir ...', ARRAY['Türk Edebiyatı','Şiir','Zeycan Monteleone']::text[], 8.5, '{"poet":"Zeycan Monteleone","poet_slug":"zeycan-monteleone","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/alelacele-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-zeycan-monteleone-bz6b1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Alabildiğine sarkıtacaksın yaşama yüreğini

Bedenini,

En derin okyanuslara bırakacaksın

Gözünü kırpmadan güneşe bakacak

Kendini fırtınaya atacaksın.

Gözün kara olacak, olmalı,

Çıkmaz sokağa gireceksin mesela,

Düz duvara tırmanacaksın,

Ve inmek yerine,

Hep çıkacaksın.

Dedim ya,

Alabildiğine sarkıtacaksın yaşama yüreğini,

Yani yaşayacaksın,

Ama önce

Oltayı denize salacaksın.....', 'Alabildiğine sarkıtacaksın yaşama yüreğini Bedenini, En derin okyanuslara bırakacaksın Gözünü kırpmadan güneşe bakacak Kendini fırtınaya ata...', ARRAY['Türk Edebiyatı','Şiir','Zeycan Monteleone']::text[], 8.5, '{"poet":"Zeycan Monteleone","poet_slug":"zeycan-monteleone","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yasamak-93-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gidince', 'sen-gidince-fahri-ozturk-q2puw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıldızlar düşer gözlerimden

Ay ışımaz semalarda

Zindan olur tüm Evrenin

Çiçek açmaz baharlarda.', 'Yıldızlar düşer gözlerimden Ay ışımaz semalarda Zindan olur tüm Evrenin Çiçek açmaz baharlarda....', ARRAY['Türk Edebiyatı','Şiir','Fahri Öztürk']::text[], 8.5, '{"poet":"Fahri Öztürk","poet_slug":"fahri-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sen-gidince-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arzu', 'arzu-zeycan-monteleone-jp2qj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir kapı aralığından gördüğüm 

Elleri kolları dolu şu adam

Nicedir gönlüme astığım bir resim siyah beyaz

O bazen

Dokuz yaşıma çivilenmiş babam

Bazen de beklediğim sen biraz', 'Bir kapı aralığından gördüğüm  Elleri kolları dolu şu adam Nicedir gönlüme astığım bir resim siyah beyaz O bazen Dokuz yaşıma çivilenmiş bab...', ARRAY['Türk Edebiyatı','Şiir','Zeycan Monteleone']::text[], 8.5, '{"poet":"Zeycan Monteleone","poet_slug":"zeycan-monteleone","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/arzu-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gençliğim', 'gencligim-fahri-ozturk-xb425', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir yaz yağmuru gibi

Geçtim bu diyarlardan.

Kasırga misali estim

Gençliğimde sevdalardan.', 'Bir yaz yağmuru gibi Geçtim bu diyarlardan. Kasırga misali estim Gençliğimde sevdalardan....', ARRAY['Türk Edebiyatı','Şiir','Fahri Öztürk']::text[], 8.5, '{"poet":"Fahri Öztürk","poet_slug":"fahri-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gencligim-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biraz sen', 'biraz-sen-zeycan-monteleone-i4vyb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir kapı aralığından gördüğüm 

Elleri kolları dolu şu adam

Nicedir gönlüme astığım bir resim siyah beyaz

O bazen

Dokuz yaşıma çivilenmiş babam

Bazen de beklediğim sen biraz', 'Bir kapı aralığından gördüğüm  Elleri kolları dolu şu adam Nicedir gönlüme astığım bir resim siyah beyaz O bazen Dokuz yaşıma çivilenmiş bab...', ARRAY['Türk Edebiyatı','Şiir','Zeycan Monteleone']::text[], 8.5, '{"poet":"Zeycan Monteleone","poet_slug":"zeycan-monteleone","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/biraz-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin', 'nerdesin-fahri-ozturk-tvl5r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nerdesin Evrenin her yerini verdiğim

Nerdesin mekanı belirsiz, bir yerde oturmayan

Nerdeisn yıldızları ayağına serdiğim

Nerdesin nehirinden çakıl taşı almayan.', 'Nerdesin Evrenin her yerini verdiğim Nerdesin mekanı belirsiz, bir yerde oturmayan Nerdeisn yıldızları ayağına serdiğim Nerdesin nehirinden ...', ARRAY['Türk Edebiyatı','Şiir','Fahri Öztürk']::text[], 8.5, '{"poet":"Fahri Öztürk","poet_slug":"fahri-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/nerdesin-81-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En sevdiklerim', 'en-sevdiklerim-zeycan-monteleone-0p7ox', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kimi zaman açılır kapısı gözlerimin

Birer birer dolar içeriye 

Görmek istediklerim

Ve,

Gönlümde en güzel köşeye kurulur, 

Onlar ki,

Artık benim en sevdiklerim.', 'Kimi zaman açılır kapısı gözlerimin Birer birer dolar içeriye  Görmek istediklerim Ve, Gönlümde en güzel köşeye kurulur,  Onlar ki, Artık be...', ARRAY['Türk Edebiyatı','Şiir','Zeycan Monteleone']::text[], 8.5, '{"poet":"Zeycan Monteleone","poet_slug":"zeycan-monteleone","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/en-sevdiklerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaylada Ölüm', 'yaylada-olum-fahri-ozturk-9gnon', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tatlı bir rüzgar eser

Bu akşam üzerimden.

Yaylalar ıssız

Yaylalar sessiz

Yaylalar o denli kalaba.', 'Tatlı bir rüzgar eser Bu akşam üzerimden. Yaylalar ıssız Yaylalar sessiz Yaylalar o denli kalaba....', ARRAY['Türk Edebiyatı','Şiir','Fahri Öztürk']::text[], 8.5, '{"poet":"Fahri Öztürk","poet_slug":"fahri-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yaylada-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçmem', 'vazgecmem-zeycan-monteleone-cojid', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben vazgeçmem,

Bırakmam kendimi yarı yolda

Kaybolmuş bir çocuk gibi 

Sokak ortasında.

Vazgeçmem,

Vız gelir dikenli tellerin,

Kar fırtınan, çöl ateşin.

Başında bile olsam bir bitişin,

Bana yazmaz.

Ben vazgeçmem, vazgeçemem, 

Sözüm var kendime,

Dönemem.', 'Ben vazgeçmem, Bırakmam kendimi yarı yolda Kaybolmuş bir çocuk gibi  Sokak ortasında. Vazgeçmem, Vız gelir dikenli tellerin, Kar fırtınan, ç...', ARRAY['Türk Edebiyatı','Şiir','Zeycan Monteleone']::text[], 8.5, '{"poet":"Zeycan Monteleone","poet_slug":"zeycan-monteleone","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vazgecmem-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mehmet Ağa ve Kır Yele', 'mehmet-aga-ve-kir-yele-fahri-ozturk-9flk9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eflani

Soğuk bir düzlüktü kışın

Yeşil bir halıydı bahar

Eflani''nin üstünde

İkisinden namlı ne var?', 'Eflani Soğuk bir düzlüktü kışın Yeşil bir halıydı bahar Eflani''nin üstünde İkisinden namlı ne var?...', ARRAY['Türk Edebiyatı','Şiir','Fahri Öztürk']::text[], 8.5, '{"poet":"Fahri Öztürk","poet_slug":"fahri-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/mehmet-aga-ve-kir-yele-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'El Beni', 'el-beni-mumtaz-begen-0t0at', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gamdan kasavetten usandım bıktım,

Çaldım kılıcımı gururu yıktım.

Ezildikçe daha yükseğe çıktım,

Yere sığamıyor, sanır el beni…

Bazen gözde, bazen dildeki bendim,

Bazen geçip gitti boyumu fendim,

Bütün zorlukları sabırla yendim,

Zora kıyamıyor, sanır el beni…

Göklerde süzüldüm, yerde süründüm,

Zaman geldi renkten renge büründüm,

Bazı Mansur gibi darda göründüm,

Dara doyamıyor, sanır el beni…

Olanı dara da, yâra da verdim,

Bencilliği vura vura devirdim,

Aşkın ataşını nura çevirdim,

Nara boyanıyor, sanır el beni…

Ne usandım ondan ne de bîzarım,

Ne küserim ona ne de kızarım,

Nicedir onunla canda gezerim,

Yâre varamıyor, sanır el beni…', 'Gamdan kasavetten usandım bıktım, Çaldım kılıcımı gururu yıktım. Ezildikçe daha yükseğe çıktım, Yere sığamıyor, sanır el beni… Bazen gözde, ...', ARRAY['Türk Edebiyatı','Şiir','Mümtaz Beğen']::text[], 8.5, '{"poet":"Mümtaz Beğen","poet_slug":"mumtaz-begen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/el-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al Götür Beni..', 'al-gotur-beni-tulay-eker-0bxpw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Al götür beni.. 

Gözlerimden sürükle 

Gözlerinin derinlerine 

Zincirle kirpiklerimi 

Yeter ki sen ol içinde 

Al götür beni.. 

Nefesimden adım adım 

Soluğumdan dökülsün adın 

Aynı havayı soluyayım 

Yeter ki koynun olsun 

Yatağım. 

Al götür beni.. 

Yüreğimden koparırcasına 

Yüreğine serileyim 

Cennetinin rahiyasında 

Serinleyim 

Yeter ki seninle sevineyim 

Al götür beni.. 

Tut ellerimden 

Özlemlerime 

Sar tenimi 

Yeter ki senin yanında 

Bağdaş kursun ecelim 

Al götür beni 

Çocuk elleri ellerim 

Emanetimdir bedenim 

Diz çöktü yüreğim 

Seni sensiz yaşarken 

Yeterki senli günlere 

Şükür diyeyim 

^^Mah Gülde,Gül Sende.Sevda Yürekte^^', 'Al götür beni..  Gözlerimden sürükle  Gözlerinin derinlerine  Zincirle kirpiklerimi  Yeter ki sen ol içinde  Al götür beni..  Nefesimden adı...', ARRAY['Türk Edebiyatı','Şiir','Tülay Eker']::text[], 8.5, '{"poet":"Tülay Eker","poet_slug":"tulay-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/al-gotur-beni-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gelince', 'sen-gelince-fahri-ozturk-ri5op', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen gelince gönlüm değişir

Sen gelince gün dolar penceremden

Sen gelince

Ayın ondürdü görülür gecelerimden.', 'Sen gelince gönlüm değişir Sen gelince gün dolar penceremden Sen gelince Ayın ondürdü görülür gecelerimden....', ARRAY['Türk Edebiyatı','Şiir','Fahri Öztürk']::text[], 8.5, '{"poet":"Fahri Öztürk","poet_slug":"fahri-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sen-gelince-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoktan Bıraktım.!', 'coktan-biraktim-nazife-abayli-dfeap', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kenetlemişsin ellerini birbirine,

Dikmişsin gözlerime mayhoş gözlerini,

Geçmişi anımsatırcasına,

İhaneti tekrar yaşatırcasına bakıyorsun..

Kaç kez söylemiştim ben sana? 

Gelme demiştim düşlerime.

Gelme zamansız,gelme benden habersiz,

Bakma gözlerime..

Tutma ellerimi demiştim..

Anlamadın..

Kendini zorla düşlerime aldırdın..

Sahi..! 

Şimdi anımsadım..! 

Senin gözlerin koyu kahveydi değil mi? 

Ellerinde esmer..

Uzun uzundu parmakların.

Ellerimi,ellerinin içine aldığında kaybolurdum.

Kollarında uzundu ellerin gibi.

Yokolurdum sardı mı bedenimi..

Yüreğin vardı bir de..

Cesurdu, tertemizdi,mertti o yüreğin..

Sevdimi tam severdi.

Ölürcesine,bitercesine,erircesine severdi..

İhaneti sevmezdi..

Yediğim kurşunlar canımı acıtmasın diye,

Önüme kendini siper ederdi.

O öyle bir yürekti değil mi? 

Sahi sen..! ! 

İçerdin değil mi? 

İçince,adam gibi içerdin sevmelerin gibi..

Rakı,bira,şarap demezdin....

Vururdun şişenin dibine dibine...

''Bu gece bütün meyhanelerini dolaştım İstanbul''un'' 

Şarkısını söylerdin.

''Doldur be meyhaneci doldur,sabaha kadar doldur.! ! '' derdin..

Sen içince adam gibi içerdin değil mi? 

Tıpkı sevmelerin gibi....adam gibi..! ! 

Ama bitti...

Ne adam gibi sevmelerin,ne gözlerin,

Ne kadehin,ne de yüreğin kaldı...

Ben..! 

Senden kalan ne varsa..

Hepsini çoktan bıraktım..!', 'Kenetlemişsin ellerini birbirine, Dikmişsin gözlerime mayhoş gözlerini, Geçmişi anımsatırcasına, İhaneti tekrar yaşatırcasına bakıyorsun.. K...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/coktan-biraktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neresinden Tutulur ki Yalnızlığın?', 'neresinden-tutulur-ki-yalnizligin-omer-dilsoz-495lz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Neresinden tutulur ki yalnızlığın? 

Omer Dilsoz 

Deprem korkusu gibi

Hani gece yarısı ansızın çökünce üstüne

Bir telaş,

Bir çaresizlik,

Bir korku, 

Ve bir kaçışma başlar sağa sola

Kaybolursun

Neye sarılacağını bilmezsin

İşte o zaman yalnızsız

          Söyle bana,

Allah aşkına söyle,

“Neresinden tutulur ki yalnızlığın? ”

Ateş gibidir o

Alev alev sarar seni

Yakar içten içe

Kemirir,

Eritir,

Küle dönüştürtür,

Ve rüzgarlara savurur seni.

Ölüm gibidir yalnızlık

Neresinden tutulur ki ölümün 

Bitişidir o her şeyin

Sonudur yani hayallerinin

Neresinden tutulur ki bitişin…? 

Ansızın çöker üstüne

Bir çığ gibi

Ve kırar bellini

Şimdi söyle

Allah aşkına söyle,

“Neresinden tutulur ki yalnızlığın? ”

Neyi anlatsam ki,

Nereden başlasam ki anlatmaya

Hangi yarayı,

Hangi yarayı deşsem ki? 

Kime,

Kimlere,

Neler anlatsam ki,

Neresinden tutsam ki yalnızlığın? 

Neresinden….

Bu öyle bir acı ki,

Hani yaşamda tutunacak dalın kalmadığında

Her şey…

Ama her şey tadını yitirdiğinde

Seni yaşamdan biraz daha kopardığında

İnancını,

Yaşama sevincini,

İrsi bağlarını,

Dostluk hissini,

Aitlik duygusunu,

Yani özgüvenini,

Ve nihayet içindeki “o gizemli kendini” kaybettiğinde

Kime nereye gideceksin ki? 

Neye tutunacaksın ki…

Söyle,

Allah aşkına söyle,

“Neresinden tutulur ki yalnızlığın? ”

Kangren gibidir o

İçten içe kemirir,

Ve bulaşır her damarına

Eritir içten farkına bile varmazsın

Elini versen ona

Yüreğini alır senden

……..

Anlıyor musun,

Anlayabiliyor musun? 

Şimdi söyle,

Allah aşkına söyle,

“Neresinden tutulur ki yalnızlığın? ”

Tutulmuyor ki….

Tutunmuyor ki yalnızlığa

Ateş gibidir o

Yakar seni içten içe

Farkına bile varmazsın….

2004-07-19', 'Neresinden tutulur ki yalnızlığın?  Omer Dilsoz  Deprem korkusu gibi Hani gece yarısı ansızın çökünce üstüne Bir telaş, Bir çaresizlik, Bir ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dilsoz']::text[], 8.5, '{"poet":"Ömer Dilsoz","poet_slug":"omer-dilsoz","theme":"Türk Şiiri","is_hero":false,"total_lines":76,"source_url":"https://www.antoloji.com/neresinden-tutulur-ki-yalnizligin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dêdem', 'd-dem-omer-dilsoz-vo9bv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dêdem

Omer Dilsoz

1

Dêdem, dîdem ma tu bêzar nebûyî ji payîna deman! 

Istirî bi şûna wuslatê dikevin riya te,  li her fetlokan

Li xwe binêr; hişyar be û bihêle vê rojiya bêzeman; 

Şîv û paşîva te, ma dê her tim bibe ew jana bi kovan? 

Ax û fîxan ma dê tim li derdora te biçerxînin perwazan? 

De bişkêne vê rojiya giran; ne Beraet e, ne jî Remezan! 

Dêdem, êdî vehêle vê sûnda rikîn, vê asoya bêsînor! 

Wekî bilbilê tûxwer gêj û mendehûş digerî li derdor

Ev çi rojiya bêwerz e, ku berê te dide riyeke kendekûr? 

Dil li ser kaniyên sar re dibore bê ku qurçekê bidaûr! 

Çav ji bendemaniyan westiyan, rijiya tev fer û nûr

Bila cejna dil bêtin; bi dûmahîk bêt, disoje ev tenûr! 

        

2

Şêrekî qefeskirî ye ev dilê birîndar

Umreke sax lê borî her daxîdar

Ken mişext bû, rondik hatin xwar

Roj û şêvê bê navber her hêvîdar

Ariya dil her gur bû, ma bê hawar

Nema tu hatî ser vî dilê tar û mar! ...

                &

Dilê birîndar her bi dax û janan gevizî

Inta evînê vegirt û gurçik pê derizî

Lêvan ken ji bîr kir, rondik her dilîzî

Ser rûyê şikestî tên xwar û her direqisî 

Ofên û axîn ji zimên tên bi merezî

Zû were dêdem ev dil bi eşqa te rizî! ...', 'Dêdem Omer Dilsoz 1 Dêdem, dîdem ma tu bêzar nebûyî ji payîna deman!  Istirî bi şûna wuslatê dikevin riya te,  li her fetlokan Li xwe binêr;...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dilsoz']::text[], 8.5, '{"poet":"Ömer Dilsoz","poet_slug":"omer-dilsoz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/dedem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fayton', 'fayton-ahmet-hakan-yilmazturk-bs3w2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Körüklü tente, düğmeli koltuk

Sallanır ponponu, içine kurulduk

Suadiye Caddebostan on lira

Saltanatı olur dertlere deva

Tıngır mıngır, faytoncu lak lak

Atlar kurum, keyifler kıyak

Bas çanına yollar açılsın

Şaklat kırbacı atlar ayılsın

Renkli püskülü sarkar kenarda

Fiyakalı faytonlar bizim durakta

Tıngır mıngır, faytoncu lak lak

Atlar kurum, keyifler kıyak

Pala bıyık bu işin raconu

Faytoncu yanı çocuğun oyunu 

Kırbacı da aldı mı eline

Değmeyin sakın siz keyfine

Tıngır mıngır, faytoncu lak lak

Atlar kurum, keyifler kıyak

19.07.2004

Çok uzak değil 70’li yıllarda fayton pek olağandı bizim buralarda…', 'Körüklü tente, düğmeli koltuk Sallanır ponponu, içine kurulduk Suadiye Caddebostan on lira Saltanatı olur dertlere deva Tıngır mıngır, fayto...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hakan Yılmaztürk']::text[], 8.5, '{"poet":"Ahmet Hakan Yılmaztürk","poet_slug":"ahmet-hakan-yilmazturk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/fayton-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sever Bu Gönül', 'sever-bu-gonul-cafer-tayyar-ozkan-qeyu2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hasret kaldı cananının kokusuna,

Esen yelden medet umar bu gönül,

Boyun büken sultanının korkusuyla,

Günleri yıllar gibi sayar bu gönül...

Ebedi mutluluğu buldu sevginle,

Seni içmeyi istedi mevsimlerce,

Seninle esen umut rüzgarlarıyla,

Maziyi gerçek gibi yaşar bu gönül...

Hiç kırılmayacak zincirleri kırdı,

Sevdanın tarifini sil baştan yazdı,

Kara bahtı silen huzurun hayaliyle,

Sevgini seller gibi içer bu gönül...

Beni de imkansızlığına katsan da,

Saygına sevdamızı mağlup kılsan da,

Tatlı sevgini yaşamaya ant içip,

Hazanı canan gibi sever bu gönül...

Kolay değil vefasız fırtınalarda,

Hazanı gören yaprak gibi solmamak.

Vuslata esir düşmüş seher vaktinde,

Cananı kefen gibi sarar bu gönül...

Gecelere kara çadırları kurup,

Hayali umut gibi çeker bu gönül,

Ukdelerine değil, bahtına küsüp,

Kaderi kılıç gibi keser bu gönül...

06 Eylül 2003 Ankara', 'Hasret kaldı cananının kokusuna, Esen yelden medet umar bu gönül, Boyun büken sultanının korkusuyla, Günleri yıllar gibi sayar bu gönül... E...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sever-bu-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi boncuk', 'mavi-boncuk-ferit-teksoy-ziexp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gemiler yakar gider

kanatlar takar gider

ne çeyiz ister

ne de elmalı şeker

ayağını yerden kessin yeter

dünyanın ucunda olsa gider

sokak çocuğu

ah bir bulsa

bir bulsa..

ömrünce aradığı

mavi boncuğu! ..', 'gemiler yakar gider kanatlar takar gider ne çeyiz ister ne de elmalı şeker ayağını yerden kessin yeter dünyanın ucunda olsa gider sokak çocu...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mavi-boncuk-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Şiir gemisi*', 'siir-gemisi-kubilay-enginol-rgxfu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gemi kalktı beşiktaş iskelesinden

Bir huşu yükseldi engin yüreklerden

El salladı kız kulesi hüzünle

Deniz kucakladı onları sevgiyle

Pera şiirinden çıkmış gelmiş Arslan Baykara

O da heyacanlıdır mutlaka

Aynur Özbek Uluç yanıbaşımda

Heyecan mutluluk dorukta

İşte karşımda İbrahim Ethem Bingül

Yüzü güller bahçesi,yüreği engin

Ellerine yansımış güzel sevgin

Gemini köpüklerine bakan Rahim Taş

İyiki varsın be arkadaş

Şule Aydemir koştu geldi çingeneler zamanından

Aldı gitti,gözlerimdeki ışıltılardan

Yürekler birleşti kocaman ışık oldu

Yükseldi,yükseldi

Etrafında yıldızlar oluştu

Yıldızların yazdığı

Engüzel şey DOSTLUK tu

Bu şiir tüm şiir dostlarına ithaf edilmiştir', 'Bir gemi kalktı beşiktaş iskelesinden Bir huşu yükseldi engin yüreklerden El salladı kız kulesi hüzünle Deniz kucakladı onları sevgiyle Pera...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/siir-gemisi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölebilirim', 'olebilirim-zafer-zengin-etnika-k9ekb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Acınızı

Bulaştırmayın

Bana

Tazeyim

Kurumadı

Cesedim

Üstüme

Gül

Serpin

Dirileyim

Ölmeye

Bilirim

Her

Aşk

Söker

Bir 

Yanımı

Ölebilirim

Aşk olunca

Derin

Olmuyor

Cümlelerim

Bu

Yüzden

Ölebilirim

Ne 

Bileyim

Ad

Bulamadım

Ayrılığa

Aşk’a Kavuşmaya

19 Temmuz 2004', 'Acınızı Bulaştırmayın Bana Tazeyim Kurumadı Cesedim Üstüme Gül Serpin Dirileyim Ölmeye Bilirim Her Aşk Söker Bir  Yanımı Ölebilirim Aşk olun...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/olebilirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Aşk Ölüyorsa...', 'ask-oluyorsa-guclu-sonmez-uxok0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşk ölüyorsa, aşk için ölünür mü? 

Yazılır mı şiirler, şarkılar

Aşılır mı çöller, dağlar

Kaç “Seni Seviyorum” dan sonra tükenir aşk...

Tükenir mi ki Aşk! ! 

Aşk bu Aşk! ! 

Ne okyanustaki dalgalar

Ne de çöllerdeki fırtınalar

Batıramazlar

Uçuramazlar

Yüreğimden söküp atamazlar

Taş gibi, ateş gibi

Dağ gibi, volkan gibi

Sapasağlam

Cayır cayır

Yıkılmayan yıkan

Yanarken yakan...

Aşk bu Aşk! ! 

Onun aşkı

Aklımı başımdan alan

Beni sonsuza dek Onun yapan

(Istanbul, Temmuz 2004)', 'Aşk ölüyorsa, aşk için ölünür mü?  Yazılır mı şiirler, şarkılar Aşılır mı çöller, dağlar Kaç “Seni Seviyorum” dan sonra tükenir aşk... Tüken...', ARRAY['Türk Edebiyatı','Şiir','Güçlü Sönmez']::text[], 8.5, '{"poet":"Güçlü Sönmez","poet_slug":"guclu-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ask-oluyorsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Sen**', 'sen-kubilay-enginol-myrl3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen gittin,ışığın kaldı

Bedenin gitti,kokun kaldı

Gözlerin gitti,ışıltısı kaldı

Sevgin zaten hep vardı', 'Sen gittin,ışığın kaldı Bedenin gitti,kokun kaldı Gözlerin gitti,ışıltısı kaldı Sevgin zaten hep vardı...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sen-430-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asansör Müziği', 'asansor-muzigi-nal-n-yildiz-3nmav', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tanımadığım bir odanın kapısını çalsam

Ya da daha iyisi çalmayıp aralasam

Ve içerde bana yabancı gelen adamın

Tanıdık sesine sarılsam

Sussak

Mesafeli 

Okuyup unuttuğu bir şiir gibi

Unutsa beni

Ben de seni unutsam

Bir saat gibi tıkırtılı, uğultulu, kurgulu...

Kalbin kapısında bir levha burgulu

''İçerdeki gürültüden kör olabilirsiniz'' 

Çalar saatler ömrümüzü çalıyorlar; 

Dik-kat, dik-kat, dik-kat...

Hatırlamıyorum şimdi

Senin fikrin miydi

Benimle ihanet etmek bana? ..

Sedir ağacının dibine kıvrılsam

Uyusam 

Ve saatler çalacak birşey bulamasa

Asansör müziği bile olabilir

İçimdeki kıpırtıları

pıtırtıları, tıkırtıları sustursa...

Sedir ağacının dibine kıvrılsam...

Uyusam

Uyanmasam', 'Tanımadığım bir odanın kapısını çalsam Ya da daha iyisi çalmayıp aralasam Ve içerde bana yabancı gelen adamın Tanıdık sesine sarılsam Sussak...', ARRAY['Türk Edebiyatı','Şiir','Nalân Yıldız']::text[], 8.5, '{"poet":"Nalân Yıldız","poet_slug":"nal-n-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/asansor-muzigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan Dünya', 'yalan-dunya-ahmet-agdere-ox33a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geldin güzel bir zarfla,

Uçarak geldim sana.

Bilmezdim  böyle fena,

Yalansın, yalan dünya.

Gözleri açtım ama,

Yaşı oldu muamma.

Bin neşeden geçmedi,

Yalansın, yalan dünya! 

Düştüm ana bağına,

Yaşadım doya doya.

Kandım gurbet çağrına,

Yalansın, yalan dünya! 

Gezdim, tozdum, eğlendim,

Bin bir türden zevklendim.

Sonda tükenen bendim,

Yalansın, yalan dünya! 

Sevdim nazlı bir güzel,

Okudum dört yüz gazel.

Nihayet dürttü bir el,

Yalansın, yalan dünya!', 'Geldin güzel bir zarfla, Uçarak geldim sana. Bilmezdim  böyle fena, Yalansın, yalan dünya. Gözleri açtım ama, Yaşı oldu muamma. Bin neşeden ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yalan-dunya-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dön artık', 'don-artik-sair-errool-1gw78', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'seni özlüyorum 

istiyorum her an 

yokluğun yakıyor içimi 

nefes alamıyorum 

seni senile bile özlerken 

yokluğun kahrediyor artık 

bitmiyor 

tükenmek bilmiyor 

geceler sabah olmuyor 

dön artık 

bitsin bu hasret 

benim ol yine 

hayatımı geri ver...', 'seni özlüyorum  istiyorum her an  yokluğun yakıyor içimi  nefes alamıyorum  seni senile bile özlerken  yokluğun kahrediyor artık  bitmiyor  ...', ARRAY['Türk Edebiyatı','Şiir','Şair Errool']::text[], 8.5, '{"poet":"Şair Errool","poet_slug":"sair-errool","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/don-artik-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arama Kendini Götürmüşüm Giderken', 'arama-kendini-goturmusum-giderken-nevin-kurular-8q3yu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Döndüm işte! 

Döndüm acımasız hasretinden.

Kavuştum sana gelen yollara

Kapalı ve çıkmaz sokaklardan bezdim yokluğunda

Bezdim engellerden.

Sensiz olmak  değilmiş sensizlik

Yalnız bırakmadı  varlığın beni

Işığı  benimleydi  gözlerinin

Kokusu  teninin

Daha ne olsun ki

Olmadığın kadar benimdin.

Böyleyken

Yine de.

Yine de özledim

Yetmedi bana 

Yavaştı, yavandı,   eksikti

ışığım benim

Güllerin

Gülümlerin

Gülümsemelerin eksikti  gülemedim

Yaralıydı sevinçlerim.

Döndüm işte! …', 'Döndüm işte!  Döndüm acımasız hasretinden. Kavuştum sana gelen yollara Kapalı ve çıkmaz sokaklardan bezdim yokluğunda Bezdim engellerden. Se...', ARRAY['Türk Edebiyatı','Şiir','Nevin Kurular']::text[], 8.5, '{"poet":"Nevin Kurular","poet_slug":"nevin-kurular","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/arama-kendini-goturmusum-giderken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakınma', 'yakinma-emel-manav-tto5s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gülen yüzüm solar oldu 

Bakan gözüm görmez oldu. 

Gülüm senden ayrılalı. 

Yatak bana mezar oldu! 

Açıldı yaram durmaz kanıyor! 

Tenim acımıyor, içim yanıyor 

Hüznümü resmettim buğulu cama 

Ölüm kollarını açmış çağırıyor. 

Canıma can katan beste. 

N’olur kulak ver bu söze 

Sonra ne istersen iste 

Uyma ele,kıyma bize!', 'Gülen yüzüm solar oldu  Bakan gözüm görmez oldu.  Gülüm senden ayrılalı.  Yatak bana mezar oldu!  Açıldı yaram durmaz kanıyor!  Tenim acımıy...', ARRAY['Türk Edebiyatı','Şiir','Emel Manav']::text[], 8.5, '{"poet":"Emel Manav","poet_slug":"emel-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yakinma-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim Kara Duman', 'yuregim-kara-duman-emel-manav-2lpt6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İçimde sıkıntı 

Kafamda takıntı var.. 

Dertlerim coştu, 

İçimi yaktı 

Bir doluyum, bir boş... 

İçmeden de insan olurmuş sarhoş! 

Laf dinlemez,adam olmaz, bu gönül... 

Avare gönül... 

Düşmüş bir kere kora 

Durmadan yanar durur! 

Sevda ateşi bu, 

Çaresi yok sönmüyor 

Kulaklar işitmez, gözler görmüyor. 

Çaresiz bu yürek, katlanıyor. 

Dayan bakalım dayan, 

Geçer elbet bu zaman. 

Olsa da her halin 

Kapkara duman...', 'İçimde sıkıntı  Kafamda takıntı var..  Dertlerim coştu,  İçimi yaktı  Bir doluyum, bir boş...  İçmeden de insan olurmuş sarhoş!  Laf dinleme...', ARRAY['Türk Edebiyatı','Şiir','Emel Manav']::text[], 8.5, '{"poet":"Emel Manav","poet_slug":"emel-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yuregim-kara-duman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öz', 'oz-cigdem-bir-genc-omu1v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çık gel...

sıyrıl  yalancı maskelerinden yaşamın

soyun...

kutsayacak seni nehirler

çoğul bir yalnızlığa sürükleniyoruz zamanda

katılmalı mı  her zaman orkestranın ritmine? 

o zaman sen sen olabilir misin? 

hadi soyun kuşandığın elbiselerinden

vakit  yok...

ritimsizliği vuruyor her ritim

duymuyor musun?', 'Çık gel... sıyrıl  yalancı maskelerinden yaşamın soyun... kutsayacak seni nehirler çoğul bir yalnızlığa sürükleniyoruz zamanda katılmalı mı ...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Bir Genç']::text[], 8.5, '{"poet":"Çiğdem Bir Genç","poet_slug":"cigdem-bir-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/oz-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Ürperme', 'beni-urperme-nal-n-yildiz-67uwq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beni ürperme! ..

Üzerlik tohumundan kolye yapmayı öğretti bana kör bir çingene

Sana dizelerimden başka bırakabileceğim bir şey yok.

Beni ürperme! ..

Şimdi gelsem ve sevişsek

Biliyorum yine gökkuşağını örtersin üstüme...

Sonrası bildik terâne

Ya ben önce gideceğim

Ya sen

Birlikte girilmiyor ki şu kara deliğe', 'Beni ürperme! .. Üzerlik tohumundan kolye yapmayı öğretti bana kör bir çingene Sana dizelerimden başka bırakabileceğim bir şey yok. Beni ürp...', ARRAY['Türk Edebiyatı','Şiir','Nalân Yıldız']::text[], 8.5, '{"poet":"Nalân Yıldız","poet_slug":"nal-n-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/beni-urperme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Durak', 'son-durak-ozgur-kizilkaya-40qqh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beyhude akıp giden ömrümün 

En güzel yerinde bir duraksın Sen 

İsterim ki; 

Son durağım olasın 

Olmasın senden öte 

Bu kadar sevebilceğim 

Hiç ama hiç bir kimse', 'Beyhude akıp giden ömrümün  En güzel yerinde bir duraksın Sen  İsterim ki;  Son durağım olasın  Olmasın senden öte  Bu kadar sevebilceğim  H...', ARRAY['Türk Edebiyatı','Şiir','Özgür Kızılkaya']::text[], 8.5, '{"poet":"Özgür Kızılkaya","poet_slug":"ozgur-kizilkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/son-durak-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siz hep gittik, Biz hep gittiniz! ..', 'siz-hep-gittik-biz-hep-gittiniz-mutlu-ayar-1iwji', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'siz hep gittiniz 

omuzlarınızda kurtulmuşluğun gülümsemesi, 

gözlerinizde hayal kırıklıklarınızdan kalma

acımasızlaşmış merhamet görüntüsü altında 

siz hep terk ettiniz 

kiminiz çok sevdi yalan değil kiminiz az 

kiminiz sevmedi, kiminiz sevemedi suç değil

kiminizin elleri bomboş kiminizin gözleri aç

tıkanmış yarınlarınıza her gidişinizde yenik gözler ekleyip

ardınıza yarım ağız bile bakmayarak 

siz hepiniz birilerini terk ettiniz

gittiğiniz yer, hep gideceğiniz yerler oldu

kiminiz göz göre göre yaptı bunu, suçlu oldu

kiminiz kör yaptı cahildi, unuttu unutuldu

siz kimseyi kendiniz kadar sevemediniz

akşam güneşi vurduğunda yüzünüze

hayallerinizin o güzel sarhoşluğuyla 

halinize şükrettiniz

siz mutlu olduğunuzda verdiniz bütün vaatleri kendinize bile

mutsuzken kimseyi umutlandırmadınız 

mutsuzken kimseyi mükafatlandırmadınız...

siz kimseyi olduğu gibi kabul etmediniz

öyle olduğu için takdir etmediniz

işinize gelmedi mi hep gitmekle 

hep gitmekle tehdit ettiniz

siz, sen gelirken 

ben gidiyordum demeyi 

hep marifet bildiniz! ..

17:15 / 19.o7.o4', 'siz hep gittiniz  omuzlarınızda kurtulmuşluğun gülümsemesi,  gözlerinizde hayal kırıklıklarınızdan kalma acımasızlaşmış merhamet görüntüsü a...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Ayar']::text[], 8.5, '{"poet":"Mutlu Ayar","poet_slug":"mutlu-ayar","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/siz-hep-gittik-biz-hep-gittiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Toprakları', 'dus-topraklari-gokhan-oflazoglu-y38pv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen ben gideriz sevgilim

adımız anı bile olmaz

esen rüzgarda.

Hangi özelliğimiz karşılar

bizi o yaban diyarlarda.

Sorulur mu burda yaptıklarımız...? 

üzdüklerimiz, sevdiklerimiz.

Ne oluruz biz o uçurumlarda...

ve nasıl barınırız bu günahlarla.

Düşlerin toprağı yumuşaktır

sevgilim. Çekip alır içine.

Birdenbire olur da herşey.

Adımız anı bile olmaz

esen rüzgarda.

15/11/96', 'Sen ben gideriz sevgilim adımız anı bile olmaz esen rüzgarda. Hangi özelliğimiz karşılar bizi o yaban diyarlarda. Sorulur mu burda yaptıklar...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dus-topraklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hırçın Eylül...', 'hircin-eylul-emirhan-bala-2evbr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'delicesine tellerime vuran mızrap misali, 

üfleyen rüzgarın nefesi ile, 

eylül geliyor… 

kopardığım bütün yalnızlıklarımla, 

sevgi ödleklerinin gömüldüğü 

eylül geliyor… 

bir dirhem dilberlerin kaybolduğu, 

iğfal edilmiş duygularımla 

eylül geliyor… 

saklayamadığım hırçın tutkularım, 

kokuşmuş zevkleri ezercesine 

eylül geliyor… 

sarıya çalan kızıllığın gölgesinde, 

darmadağın nabzımın hızıyla 

eylül geliyor… 

fısıldaşan garip ruhumun ötesinden 

devirdiğim zamanların yerine 

eylül geliyor… 

eylül geliyor… 

camlı köşkteki saklı yüreğime 

ayağım yere değsin diye, 

eylül geliyor…eylül…', 'delicesine tellerime vuran mızrap misali,  üfleyen rüzgarın nefesi ile,  eylül geliyor…  kopardığım bütün yalnızlıklarımla,  sevgi ödlekleri...', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hircin-eylul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Genç Kız', 'genc-kiz-gokhan-oflazoglu-akf0z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Göğümüzde yansıyan

en parlak yıldızdır genç kız.

En derine işleyen bıçak,

alıp götüren girdap ve

geçen zamana en yetkin

cevaptır. Vahşi bakışları,

içten yönelişleriyle, yüreğe

coşku veren kandır.

Yorgun akşamlarımızda,

karanlığı ağartan, teninden

fışkıran candır.

O neşeli bir türkü; 

bütün kayıpları unutturan

armağandır.

26/12/96', 'Göğümüzde yansıyan en parlak yıldızdır genç kız. En derine işleyen bıçak, alıp götüren girdap ve geçen zamana en yetkin cevaptır. Vahşi bakı...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/genc-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küsmedim', 'kusmedim-gokhan-oflazoglu-kix5n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben ona hiç küsmedim,

umudumu kesmedim,

gelen günü reddetmedim,

önümdeki yeter bana.

Güldü uzun uzun

yalanına kızmadım,

dileğince üzdü beni,

dirilten sesi yeter bana.

Kan çekilir damarımda,

hüzün yerleşti canıma,

değinmedim boş lafına

sohbeti yeter bana.

Burda bıraksak yükü

gönlümüz kalsa açıkta

beni yorar soruları

itirazı yeter bana.

11/06/96', 'Ben ona hiç küsmedim, umudumu kesmedim, gelen günü reddetmedim, önümdeki yeter bana. Güldü uzun uzun yalanına kızmadım, dileğince üzdü beni,...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kusmedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yaz Sabahı', 'bir-yaz-sabahi-metin-usengec-x4scd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sıcak bir yaz sabahı

Yine rüyamda gördüm seni

Bilsen ne çok özlemişim

Bir sıcaklık çöktü o an içime

Gül yüzün güneş gibi ısıttı yüreğimi

Şükür ettim Allah''ıma

Çaresiz yanan yüreğimi

Hasretine bir nebze doyurduğu için

Bir hayal bir rüyada olsa seni görmek

Sanki bir ömre bedel..

12-Temmuz-2004  09:00

Adı Bende Saklı..', 'Sıcak bir yaz sabahı Yine rüyamda gördüm seni Bilsen ne çok özlemişim Bir sıcaklık çöktü o an içime Gül yüzün güneş gibi ısıttı yüreğimi Şük...', ARRAY['Türk Edebiyatı','Şiir','Metin Üşengeç']::text[], 8.5, '{"poet":"Metin Üşengeç","poet_slug":"metin-usengec","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-yaz-sabahi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suyun Çıktığı Yer', 'suyun-ciktigi-yer-taha-nur-ki4tq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İki şey coşturur beni.

Bir tarihten kopup gelen mehter,

Bir de kaynağından akıp gelen su.

Huzur verir bana,

İki yer.

Bir camii köşesi,

Bir de suyun çıktığı yerdeki,

Çınarın gölgesi...

Suyun çıktığı yerde huzur vardır.

Suyun kaynağında sürur vardır.

İki sesten feyizlenirim ben.

Bir göklere uzanan,

Ezan sesi.

Bir de suyun çıktığı yerdeki,

Kuşların hoş nağmesi...

Suyun çıktığı yerde hayat vardır.

Suyun kaynağında tat vardır.

İki yerde zamanı durdurmak isterim.

Bir güneş batarken tepede,

Ufukta.

Bir de suyun çıktığı yerde,

Kaynakta...

Suyun çıktığı yer yeşildir.

Güzeldir.

Suyun çıktığı yer özeldir.

İki varlığımla hoşnutum.

Şükür Allah’a,

Bir imanım var,

Bir de Cennet Anadolum.

Ben çadırımı suyun çıktığı yerde,

Kurdum.

İşte benim güzel yurdum...

Suyun çıktığı yerde kuş vardır,

Kurt vardır.

Suyun kaynağında ev vardır,

Yurt vardır.', 'İki şey coşturur beni. Bir tarihten kopup gelen mehter, Bir de kaynağından akıp gelen su. Huzur verir bana, İki yer. Bir camii köşesi, Bir d...', ARRAY['Türk Edebiyatı','Şiir','Taha Nur']::text[], 8.5, '{"poet":"Taha Nur","poet_slug":"taha-nur","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/suyun-ciktigi-yer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk reçetesi', 'ask-recetesi-husamettin-gunacti-d2i3k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir tutam duygu, bir çimdik umut,

boşver dünya''yı geçmişi unut.

bir ölçek güven, biraz da sevgi gölgesi,

aklında tut, bu aşkın reçetesi...', 'bir tutam duygu, bir çimdik umut, boşver dünya''yı geçmişi unut. bir ölçek güven, biraz da sevgi gölgesi, aklında tut, bu aşkın reçetesi......', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ask-recetesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye', 'sevgiliye-orhan-mahir-kizilboga-pug6y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni seviyorum demek istiyorum bazı zaman  sana,

Ama ben seni hiç bilmedim

Sadece olmanı istedim 

Şu an ve bazı zamanlarda.

Ben seni bilmek istiyorum

Oysa ben neyi neden istiyorum? 

Ben seni hissediyorum.

Hıı.... 

Oysa hiç hissetmedim hissetmeyi

Düşünürken gözlerini

Aklıma geliyor bazen

Gözlerini hiç mi hiç görmediğim.', 'Seni seviyorum demek istiyorum bazı zaman  sana, Ama ben seni hiç bilmedim Sadece olmanı istedim  Şu an ve bazı zamanlarda. Ben seni bilmek ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Mahir Kızılboğa']::text[], 8.5, '{"poet":"Orhan Mahir Kızılboğa","poet_slug":"orhan-mahir-kizilboga","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgiliye-70-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah AŞK', 'ah-ask-husamettin-gunacti-oljz3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'süründeki duygular  neden  çobansız,

bilmez misin aşk yakalar insanı apansız.

baksana duvarındaki eski kilime,

leopar ceylanı  avlamış  bile...', 'süründeki duygular  neden  çobansız, bilmez misin aşk yakalar insanı apansız. baksana duvarındaki eski kilime, leopar ceylanı  avlamış  bile...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ah-ask-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazık Değilmi?', 'yazik-degilmi-necati-kavak-zfqtd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzaktan kopup geldiğimiz,

Gelirken dağlar deldiğimiz,

Uğrunda canlar verdiğimiz,

Bu vatan bizim değilmi? 

Dağı,denizi,ovasıyla,

Eşi bulunmaz doğasıyla,

Günahıyla ve sevabıyla,

Bu vatan bizim değilmi? 

İki kıtaya köprü olan,

Her karışında tarih kokan,

Düşmana ise mezar olan,

Bu vatan bizim değilmi? 

Şehitler tükürmesin bize,

Düşman gülmesin yüzümüze,

Sahip çıkmazsak ülkemize,

Bizlere yazık değilmi?', 'Uzaktan kopup geldiğimiz, Gelirken dağlar deldiğimiz, Uğrunda canlar verdiğimiz, Bu vatan bizim değilmi?  Dağı,denizi,ovasıyla, Eşi bulunmaz...', ARRAY['Türk Edebiyatı','Şiir','Necati Kavak']::text[], 8.5, '{"poet":"Necati Kavak","poet_slug":"necati-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yazik-degilmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Gözlerinde Utanmalar Var', 'guzel-gozlerinde-utanmalar-var-i-smet-barlioglu-3qetj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kırpma gözlerini üstüste yine,

Güzel gözlerinde utanmalar var.

İmrenir ağzının güller rengine,

Körpe dudağında ne yanmalar var.

Saçların güneştir karageceye,

Serpme ibrişimdir ta enginlere,

Kaçırma başını benden öteye,

Seğiren gamzende nazlanmalar var.

Sessizliğin sanki sinmiş fırtına,

Kokun havanlarda döğülmüş kına,

Güllere benzeme bakıp boyuna; 

Gülün kaderinde budanmalar var.

Binbir güzellik var herbir sözünde,

Seni buluyorum her gelen günde,

Güzel gözlerinde, körpe yüzünde

Ne büyük yeminler, ne yalanlar var.

(BİR YORGUN FIRTINA isimli hece şiirlerinden > 43-44/100)', 'Kırpma gözlerini üstüste yine, Güzel gözlerinde utanmalar var. İmrenir ağzının güller rengine, Körpe dudağında ne yanmalar var. Saçların gün...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/guzel-gozlerinde-utanmalar-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şilêr', 'sil-r-omer-dilsoz-8wp1x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şilêr

        omer dilsoz

şilêr,

tu ji bo çi serê xwe nixwîn dikî

qey tu digrî şilêr…

qey tu birîndarî,

an evîndar…? 

bibêje şilêr

ji bo çi stûyê te daketiye

li pala te şikêr

beramberî te belekî ye

te çî ye şilêr

ji bo çi rûyê te şil bûye

ji bo çi şilêr 

derdê te çî ye…? 

şilêr

piştî ku min tu dîtî

ez bi rojekê hezar salan jiyam

hezar caran mirim

piştî her mirinekê bi rondikên te

hezar caran vejiyam

hezar caran şilêr…

şilêr

êvar e li çiyan

ewran xwe daye ber rojê

ji kûratiya newalan 

deng vedide dengê dengbêjekî

sîber daketine xwarê

teyr difirin ber bi asîmanan

tu nabînî

lê nanihêrî şilêr

qey tu xeyidî ji me

qey tu dilmayî şilêr

tu ji bo çi sernexwînî şilêr

ka bibêje te şerma kê bar kiriye

te raza kê pişt kiriye

te dilê kê veşartiye

te xwîna kê hewandiye

tu zêmara kê dikî

şîna kîjan terotolî digerînî

te dengê xwe li ku berze kiriye

di nalîna kîjan dayîkê de

di awaza kîjan dengbêjî de

di girîna kîjan zarokî de

tu şerma kê dikî şilêr

kê….? 

şilêr

hezar dilên min te ji min dizîn

hezar caran te ez çal kirim

li nava axê

li beyareke çiya

li bereheke şikêran

di nava xwîdana şermê de

gotinên min li ser zimanê min hişk bûn

şilêr

guhdariya çîroka min bike

ez ji bo te dibêjim ha,

hezar gotinên xwe yên  zîz

yên di sîtavka spêdeyekê de

li ber bayê felekê baligî ne

ez li nava xunava te dihêwirim

riyên min girtî ne

evîna min ji min dizî ne

dizî ne şilêr…

de serê xwe rake şilêr

li nav çavên min bimêzîne

şilêr

ji axa tu li ser şînhatî

pêjnên têvel tên ber guhê min

nalîn,

qêrîn,

qîjîn,

gazî

hemû pêkve olan didin

ev çi ye şilêr

qey tu li wan dengan dinêrî

ew dengên li pêş çavên te

di sînga axê de çal kirine

qey tu jî şahidê wan rojan î

wan….

         rojan… 

                   şilêr… 

şilêr

ji ser rûyê te xwîn diniqute

xwîn û av

tîna janekê kel vedide

kel û jan

rondik têne xwarê

kel û girîn

lê şilêr

min gelekî mereq kiriye

ka kena te çawaye

bişîrîneke sivik dê çend li te bê

ez nizanim şilêr

ez ninazim çi û çi ne razên te

xemên te,

keyfên te,

henekên te…? 

tu cîhaneke cudayî şilêr

di rojekê de hezar salan dijî

di şevekê de hezar tofanan radikî

di mistekê de deryayan

oqyanûsan dihewînî şilêr

şilêr

êvar e, şev sar dibe

her kes diçe

xwe dispêre hêlîna xwe

berxik vedigerin ber makê

teyr xwe dadidin ser lîsên xwe

mirov dinişin nav şaristaniyê

masî xwe davêjin nav pêlan

kêzik bi axê şa dibin

………

û ez û tu şilêr

em bi tenê dimînin

li qontara çiyayeke jibîrbûyî

li nav rûpelên dîroka nezayî

li ser axeke nekêlayî

xav,

       xwas,

             û damayî

şilêr

êdî tu dikarî serê xwe rakî

ji bilî min kes nemaye li vir

qey tu xwe ji min jî vedişêrî

na şilêr na, 

jixwe em ji rayên hev dertên

ji dilê axê

ji kopê hêviyan şilêr! 

2003-12-26/Amed', 'Şilêr         omer dilsoz şilêr, tu ji bo çi serê xwe nixwîn dikî qey tu digrî şilêr… qey tu birîndarî, an evîndar…?  bibêje şilêr ji bo çi ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dilsoz']::text[], 8.5, '{"poet":"Ömer Dilsoz","poet_slug":"omer-dilsoz","theme":"Türk Şiiri","is_hero":false,"total_lines":130,"source_url":"https://www.antoloji.com/siler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ezê Dîtir', 'ez-d-tir-omer-dilsoz-7d6vn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'omer dilsoz

1

ew ezê ku di kûratiyên ''min'' de veşartiye

ewê ku ''ez'' wî nas nakim

ewê bo min biyanî…

ewê li kûratiya dil xwe li min veşartiye

ew ezê ku ''ez'' qet nizanim çawaye

ew ezê dîtir yanî

ezê ku min qet nedîtiye

ezê ku di nepeniyan de digere

û veşartokê bi min re dilîze 

2

ew ezê di nava min de 

ku dişibe darkirokê

her êvarî tobe dike

û her spêdeya piştî wê êvarê jî

toba xwe betal dike…

3

ew ezê du perçe…

ewê bêpêjn xwe dikuje

û dîsa piştî her xwekuştinekê

bi xweliya xwe ve xwe vedijîne

4

ew ezê ku ''min'' berze kiriye

û hinde sal in bêrawestan lê digerim

li ser rûyê cîhanê

hin caran di tîna awirên xezalekê de

hin caran di çirûska dilê dayikekê de

hin caran di bişirîna zelal a zarokekê de

5

ew ezê ku bi qasî dîroka mirovahiyê kevin

bi qasî teyrê eylo resen

û bi qasî ''xwe'' jî têkçûyî

ew ezê dîtir,

ewê ku bi çarlepkî xwe gihandiye asoyên winda

ewê bi dewisandinan re tixûb çirandine

û xwe gihandiye stêrkan…

ew ezê bûme stêrk

6

ew ezê dengê xwe di nalîna bilûrekê de berzekiriye

ewê di nav pêlên evînê de serobin bûye

ew ezê ji bo evîneke pak birçî

ji bo evîndareke dilsoz bûye derwêş

û xwe bera nav çol û çolistanan daye

7

ew ezê dîtir…

ezê ku di xewnên zaroktiyê de maye

hê jî bi dileke zarokane 

bi çirûskekê şad dibe,

bi dilopekê xemgîn…

yanî ew ezê qet mezin nebûyî

qet hînî jiyanê nebûyî

qet neketiye gengeşiyên serdemê

û qet bera nav bayên derdorê nedayî

8

ew ezê min di riya lêgerînê de winda kiriye

ezê winda…

ezê kena ''wî'' li ser rû tirş bûye

rondik di çavan de hişk bûye

ezê di nava peyvên tûle de gêr dibim

li ser hişkerûyê kaxezên qirmiçî

9

ezê ne ji bo ''xwe'' bikarî bijî

ne jî mifadarê derdora xwe

ezê dîtir…

ewê ku ji nava hemû lîsteyan hatiye renîn

ji hemû heyiyan hatiye vederkirin

ezê ji marî rûstir, ji gurî birsîtir

ezê ku ''min'' hilma wî seh nekiriye

10

ezê delodîn

ezê bo xweziyeke avis fêk bûye

di nav mij û morana jiyanê de

xwe li hespê hêviyên winda siwar kiriye

û dajot…dajot

li şevexwînên dûvedirêj

ber bi bayê kur,

li gel afriya karwankujan

di nav dilê çiya û baniyan re…

11

ezê ku di şopa xezaleke kûvî de winda bûye

bi tena serê xwe…

li çiyayeke dûr î pişt asoyan

di rojeke ne li salnameyan hatiye tomarkirin de

ne jî di nava rûpelên dîrokê qeyd bûyî de

12

ezê ku bi zêmarên dayikan hişyar bûye

li ser kêliya goreke nenavkirî

ezê bi janên ''min'' di xwe de çûye

li nav nameyeke qet rênekirî

13

ezê dîtir yanî

ew ezê ku qet nizane derewan bike

nizane bi ristên ''lê ferz dikin'' bilîze

û rûpoşan li rûyê xwe bipêçe

di nav dubendiyê de bikare bimîne

ew ezê lawaz,

ewê têkçûyî…

ji ber ku nezaniye bilîze

14 

ew ezê ku bi senfoniyeke dengketî

strana ''yên dîtir'' dinehwirîne

15

ew ezê dîtir,

ezê ku li ''min'' digere

ji bo ''min'' têdikoşe

ji ber ''min'' diêşe

ew ezê ji bo ''min'' xwe dikuje

û bi xweliya xwe ve ''min'' diafirîne

ezê xwe gorî ''min'' kirî…

li welateke hemû êşan pêçayî,

hemû jan lê akincî bûne

û ''jiyanê'' di bin xweliya ''mirinê'' de aj dayî

16

ezê dîtir,

ango ezê azad 

ew ezê ku hê jî kariye xweser bimîne

hê jî kariye bêhna axê jê bifûre

ew ezê ku hê jî ''ez'' im…    

    

2003-12-11/ Amed', 'omer dilsoz 1 ew ezê ku di kûratiyên ''min'' de veşartiye ewê ku ''ez'' wî nas nakim ewê bo min biyanî… ewê li kûratiya dil xwe li min veşartiye...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dilsoz']::text[], 8.5, '{"poet":"Ömer Dilsoz","poet_slug":"omer-dilsoz","theme":"Türk Şiiri","is_hero":false,"total_lines":120,"source_url":"https://www.antoloji.com/eze-ditir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...İç Göç...', 'i-c-goc-naime-erlacin-pz559', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kuş göçü

kış göçü derken

iğdeler geldi

...ve gittiler...

zamanın sesinde sarkaç oluyorum

aykırı bir kimya özüyorum 

Yuda’nın son nefesinde

dinlenirken iç göçümle erguvanın gizinde

kutsalı yeşile, yeşili maviye

ruhun kalkanına sessizliği emanet ediyorum

iğdenin mahşerlik gölgesinde

“yaz bitti” diyor şair

başladı mı yaz

ben neredeydim o halde? 

“yaslan” diye sesleniyor çınar

acı gülümsüyor salkım söğüt

zait ufuklar umuyor hayattan

onuruna yakışır boyluca 

borçsuz ve alacaklı

yere selamında bile

gitti iğdeler 

siyahî bir ânın gözünde nöbetteyim

oysa hüznün gölgesinde ey şiirim 

mavisin yine

erguvan kadar anlaşılmaz o yerde

iç göçe çıkmış kuştur kalbim

taze bir gün umuyor hayattan

sade bir yolculuk başlıyor Atlantis’e

magmada döllenen krater ve

yıkıntıyı taç eden münzevi tüm kentlere 

ak sütü gibi anamın

zamandan bağışlanmış bir ondalık

bir yankıdır yaşam bazen 

hüznü vuruyor saatler

eprimiş bir sayfasına belleğin 

ânı mıhlarken ben

iğdeleri düşlüyorum 

iç göçümün tik-tak sesinde

“iğdeler gelir”

diyor ses

“iğdeler gider yine…”

(19 Temmuz 2004) 

(''ŞİKÂYETNAME'', Hayal Yay. Temmuz 2010, Sayfa 66)', 'kuş göçü kış göçü derken iğdeler geldi ...ve gittiler... zamanın sesinde sarkaç oluyorum aykırı bir kimya özüyorum  Yuda’nın son nefesinde d...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/ic-goc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akarı Destan', 'akari-destan-zulfikar-yapar-kaleli-tmoiv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Okyanustan derin gönlünün içi 

Kimseye göstermez yanar kavrulur! 

Drama dönüşür hayat sikeçi 

Buna aklı ermez yanar kavrulur! 

Arif kişi her çileyi hoş görür 

Cahil, nadan bu dünyayı boş görür 

Bir insan ki her insanı baş görür 

Her kusuru görmez yanar kavrulur! 

Güller hoyrat elde, umut çalıda 

Mal mülk düzenbazda, sabır velide 

Arzu yüce dağda, heves yalıda 

Asla aman vermez, yanar kavrulur! 

Zaman uzamakta, geçmede ara 

Dost dostun gönlüne açmada yara 

Kalbin çekülünü asmış duvara 

İpine el sürmez, yanar kavrulur! 

Gonca boyun eğer, güller sarardı 

Arının o gülde muradı vardı 

Hasretin ateşi sineyi sardı 

Vuslat ele girmez, yanar kavrulur! 

Çabalar kabını dolduramazsın 

Olmaya uğraşır olduramazsın 

İstesen de gülü solduramazsın 

Kimseyi küstürmez, yanar kavrulur! 

Gönlümün gözünde saklarım seni 

Cevherine bakar, yoklarım seni 

Uzaktan uzağa koklarım seni 

Bu gönle şerbet ez, yanar kavrulur! 

Yadında yarı var, sanırsın canlı 

Yanında hayali, çok heyecanlı 

Elleri nasırlı, gözleri kanlı 

Dosta yel estirmez, yanar kavrulur! 

Dikkatlice oku bu son heceyi! 

Uğraş o ki, gündüz ede geceyi! 

Gönlün günü tutsa, ünün yüceyi 

Güneşe un sermez, yanar kavrulur! 

Gönlümün gözüne teperim seni, 

Bilmişim korganım, siperim seni 

İki gözlerinden öperim seni 

Bu baş çam devirmez, yanar kavrulur!', 'Okyanustan derin gönlünün içi  Kimseye göstermez yanar kavrulur!  Drama dönüşür hayat sikeçi  Buna aklı ermez yanar kavrulur!  Arif kişi her...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/akari-destan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Ele Verir Aynalar!', 'seni-ele-verir-aynalar-omer-dilsoz-fntur', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Omer Dilsoz

Of aynalar of! 

Yıllardan sonra

Seni ele verir aynalar 

Yüzündeki o derin hatlar

Ve yılların yorgunluğunu anlatan o çukurlar

Seni ele verir...

O zaman içinden kayar derin bir “of”

Ve kendi kendine söylene durursun; 

“aslında her şey farklı olabilirdi”

“farklı yaşayabilirdim” diye...

ama  seni ele verir aynalar. 

Of aynalar of! 

Yıllardan sonra

Seni ele verir aynalar

Saçındaki şu aklar

Yüreğin yorgun, titrer ayaklar

Yaşamda tükenince heyecanlar

Seni ele verir aynalar

Ve ardına baktığında; 

Geride bırakılmış sadece yürekteki yaralar

Ve hala içinde kaynayan yapamadıkların

Ve ömrünün yetmediği planlar...

O zaman içinden geçer; 

Ve kendi kendine mırıldanırsın; 

“aslında her şey farklı olabilirdi”

“ben farklı yaşayabilirdim” diye...

ama seni ele verir aynalar! 

Of aynalar of! 

Seni ele verir aynalar...

İçinde kanar

Yüreğindeki şu derin yaralar

Yetişemediğin şu zaman fırtınası

Akar gözpınarlarından

Her damlasında bir acı gizli,

Bir yara kanar...

Ama seni ele verir aynalar.

Gözlerinin içi artık gülmez

Ve yorgun yorgun bakarsın bir boşluğa

Anlam veremediğin şu yaşamın ardından

İşte o zaman

Seni ele verir aynalar; 

Ve ansızın dilinden dökülür bir-iki satır; 

“aslında her şey farklı olabilirdi”

“ben farklı yaşayabilirdim” diye...

ama seni ele verir aynalar.

Of aynalar of! 

Bir ömrün ardından

Seni ele verir aynalar

Kamburlaşan omuzların

Ve yere hafifçe deyen şu titrek ayakların

İçindeki umutsuzluğun,

Yaşayamadığın yaşamının itirafçısı olur

Yere bakan yorgun gözlerin

Kaybettiğin sevdanın habercisi olur

Ve yalnızlık 

Soğuk bir nefes gibi hep seni bulur

İçinde gezer; 

Uykularını böler

Ve seni ele verir aynalar

İşte o zaman; 

Gözlerinden akar iki soğuk damla,

Yapamadıklarını anımsatırcasına

İşte o zaman; 

Dilinden sökülür iki cümle,

“aslında her şey farklı olabilirdi”

“ben farklı yaşayabilirdim” diye...

ama seni ele verir aynalar.

2004-05-10', 'Omer Dilsoz Of aynalar of!  Yıllardan sonra Seni ele verir aynalar  Yüzündeki o derin hatlar Ve yılların yorgunluğunu anlatan o çukurlar Sen...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dilsoz']::text[], 8.5, '{"poet":"Ömer Dilsoz","poet_slug":"omer-dilsoz","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/seni-ele-verir-aynalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anılar öptü dudaklarımı', 'anilar-optu-dudaklarimi-pelin-onay-x0zsn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '(..çok zaman sonra belki de sen..)

sesi soluğu kesilmiş bir aşkın ortasından yürüyoruz 

acılarımızı saramayacak kadar uzağız artık 

kirpiklerimizde beslenen düşler, 

yeni doğacak sevgililere miras 

düşünüyorum da, 

belki biz sevgiyi değil, hep ayrılığı büyüttük seninle 

çıplak bedenlerimizden akan özlemler yanılttı bizi 

yağmur yağarken anımsadığın ben değil, 

yalnızlığındı belki de 

ve ben yalnızlığını bile özledim desem, 

beni duyamayacak kadar sessizsin artık 

nakaratındayım anıların 

beni bu gece dehlizlere sürükleyen Timur Selçuk, 

babasının şarkılarını söylüyor 

öyle hüzünlü, öyle hasret, öyle tutkulu 

ben de senin şarkılarını söylüyorum 

is gibi, sus gibi, öyle vurgulu 

kaçırıp getireyim kendimi yanına bir an için desem, 

sana sarılamayacak kadar yorgunum artık 

dağınıklığını toparlarken odamın, 

elimde kaldı bir kitabın içinden düşen resmin 

göz göze geldik bir an, 

gözlerinde ''seni seviyorum'' bakışın 

kara çalılar ardına saklanan sinsi bir isyan kaşıdı yüreğimi 

resimlerde kalacak kadar yabancı değildik o zaman 

her şeyden önce dostumdun, 

ıslak hüznümü bile varlığınla gülümsetebildiğim 

şimdi gözlerinde yeniden kulaç atmak istiyorum desem, 

mavilerinde yüzemeyecek kadar bitkinim artık 

nerede yanlış yaptığımı itiraf etmedi aşk 

ilam kağıtları birikmiş bir sevda duluyum 

şarkıların sakiliğini tek başıma yapıyorum, 

rakı makamına göre kadehe doluyor 

bilirsin işte, artık sevmek istemeyen kadınlık halleri 

an geliyor, 

kalbim kanatlanıp göğüs kafesine girmek istiyor desem, 

semalarında süzülemeyecek kadar yaralıyım artık 

ağdalı sevdim seni ama yapışkan değil 

sevmek çekip gitmekti gerektiğinde, bunu bildim 

sadece şiirlerimde konuşabildim, bağıra..çağıra 

kızdın ve kırıldın sitemlerimin tavşan dudaklarına belki ama 

sevdim seni, ayazda..boranda 

ah o sadekâr ellerin bedenime yeniden dokunsa desem, 

ellerini bedenimde tutamayacak kadar titriyorum artık 

bir kedi gözlerimin içine baktı 

ruhumdan bir deniz geçti, dalgaları göğsüme çarpttı 

antika bir fincanda iç çekişlerim kaldı 

gül kurusu perdeler, mutluluğuma kapandı 

anılar dudaklarımı öptü, dudaklarım sızladı 

çok zaman sonra sen de öp beni desem, 

öpüşlerimiz bizi yakacak kadar sıcak değil artık 

ve sen, her şeye rağmen gelip, ''seni seviyorum'' desen, 

bu iki kelimeden ölesiye korkuyorum artık..', '(..çok zaman sonra belki de sen..) sesi soluğu kesilmiş bir aşkın ortasından yürüyoruz  acılarımızı saramayacak kadar uzağız artık  kirpikle...', ARRAY['Türk Edebiyatı','Şiir','Pelin Onay']::text[], 8.5, '{"poet":"Pelin Onay","poet_slug":"pelin-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/anilar-optu-dudaklarimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Geceye Kavuşurken', 'gun-geceye-kavusurken-umit-terzi-gbec0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gün geceye kavuşurken

güneş denize

eğer kollarımdaysan sen

var mı başka diyarlar 

başka kokular 

başka yürek çarpıntıları

ya uzaktayken

yalnızken ben var mı

var mı başka 

ufka dalıp gidenler

sigara dumanında hayaller kuranlar

dalıp gidenler gölgelere

kafamda, içimde 

bende, benle,senden, herkesten

uzak,yakan,acıtan,ağrıtan

ama istediğim,onsuz olamadığım

yaşayamadığım

o his...', 'gün geceye kavuşurken güneş denize eğer kollarımdaysan sen var mı başka diyarlar  başka kokular  başka yürek çarpıntıları ya uzaktayken yaln...', ARRAY['Türk Edebiyatı','Şiir','Ümit Terzi']::text[], 8.5, '{"poet":"Ümit Terzi","poet_slug":"umit-terzi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gun-geceye-kavusurken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-umit-terzi-an1av', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hani o insanların hep renkli rüyalar gördüğü yerden gelen güzel,

Nasıl oldu, nasıl başladı sevmek seni... 

Nefes almak gibi,

Doğar doğmaz, ilk defa ...

Yazın bir hamakta uyuya kalmak gibi

Yapraklarla ışık oyun oynar göz kapaklarında

Rüzgarı, kuşları ve suyu dinlerken...', 'Hani o insanların hep renkli rüyalar gördüğü yerden gelen güzel, Nasıl oldu, nasıl başladı sevmek seni...  Nefes almak gibi, Doğar doğmaz, i...', ARRAY['Türk Edebiyatı','Şiir','Ümit Terzi']::text[], 8.5, '{"poet":"Ümit Terzi","poet_slug":"umit-terzi","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ruya-128-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-umit-terzi-7ht16', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sokak lambasının yalnızlığına özenirim bazen

Donuk ışığımla  çiseleyen yağmuru, kaldırımı aydınlatmaya

Ama hiç istemedim neonlar kadar yalnızlığı, 

Uzak unutulmuşlar gibi

Yanıp bitip kendimi tüketmeyi...', 'Bir sokak lambasının yalnızlığına özenirim bazen Donuk ışığımla  çiseleyen yağmuru, kaldırımı aydınlatmaya Ama hiç istemedim neonlar kadar y...', ARRAY['Türk Edebiyatı','Şiir','Ümit Terzi']::text[], 8.5, '{"poet":"Ümit Terzi","poet_slug":"umit-terzi","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yalnizlik-177-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağrı', 'agri-umit-terzi-pyn7y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir ağrı var bu akşam... 

Tam göğüs kafesimin altında,

Kalbimle midemin arasında.

Dinlendim, soğuk sular içtim, unutmaya çalıştım 

Geçmedi burukluğu, ağrısı...

Seni düşünürken birden, 

Sancıya dönüştü ağrılar...

Dinmedi, dinemedi acı 

Sensiz... 

Bir uyuyabilsem,

Belki diner.

Hem belki seninle olurum rüyamda.

Dokunuşundaki o his, bakışın

Farkında olmayan

Haykıran sesin boşluğa

Boşluktan yansıyıp yüreğime

“Kumral olmalı sevdiğim

Ela gözleri olmalı mutlaka”

 Bilerek mi söyledin bunları 

Neden büyüyor umudum? 

Kardelen gibi ansızın.

Yoksa ela mı gözlerim?', 'Bir ağrı var bu akşam...  Tam göğüs kafesimin altında, Kalbimle midemin arasında. Dinlendim, soğuk sular içtim, unutmaya çalıştım  Geçmedi b...', ARRAY['Türk Edebiyatı','Şiir','Ümit Terzi']::text[], 8.5, '{"poet":"Ümit Terzi","poet_slug":"umit-terzi","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/agri-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmiyorum', 'bilmiyorum-umit-terzi-hrycf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilmiyorum neler oluyor

Bana, bize 

Neden öyle bakıyorsun bana? 

ben mi? 

Seni düşünüyorum.

Ya son günüm olsaydı hayatta ne yapardım? 

.

.

.

.

Sana sarılır, seninle sevişir, kokunu içime çeker 

Özümle, içimle dışımla, tüm duygularımla seni

Sensizliği her şeyiyle yaşamak isterdim.

Ya sen? 

? 

? 

? ? ?', 'Bilmiyorum neler oluyor Bana, bize  Neden öyle bakıyorsun bana?  ben mi?  Seni düşünüyorum. Ya son günüm olsaydı hayatta ne yapardım?  . . ....', ARRAY['Türk Edebiyatı','Şiir','Ümit Terzi']::text[], 8.5, '{"poet":"Ümit Terzi","poet_slug":"umit-terzi","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bilmiyorum-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalgın, Nereye Böyle?', 'dalgin-nereye-boyle-umit-terzi-9aloe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir adam düşün sıradan,

Yürürken, yaşarken, nefes alırken...

Seviyor hayatı, yaşamayı.

Ama birşeylerin eksikliğini hissediyor.

Etrafına bakıyor...

Düşünüyor...

Farkında olamadığı şey,

aslında hep yanında olan,

Heryerde gördüğü, 

orada olduğunu hissettiği,

Ama yoksunluğunu çektiği şey,

Bu kocaman kürede,

Hayatı var eden, sürdüren...

Her yerde parıltısını görse de,

Görmesi için etrafını gerekse de... 

Bakmamış gökyüzüne, 

hissetmemiş sıcaklığını hayatın kaynağının...

Bu adam ben miyim? 

Belki...

Çok benzese de bana, 

bir fark var aramızda,

Yapması gereken tek şey,

Başını kaldırıp bakmak...

Oysa benim güneşi görmek için, 

beklemem gerek...

Yaşamak için, beklemem...', 'Bir adam düşün sıradan, Yürürken, yaşarken, nefes alırken... Seviyor hayatı, yaşamayı. Ama birşeylerin eksikliğini hissediyor. Etrafına bakı...', ARRAY['Türk Edebiyatı','Şiir','Ümit Terzi']::text[], 8.5, '{"poet":"Ümit Terzi","poet_slug":"umit-terzi","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/dalgin-nereye-boyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serin Sular, Bulutlar...', 'serin-sular-bulutlar-umit-terzi-rkbla', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Serin sular içtim,  uzak yollar gezdim, nice yağmurlar gördüm

Nice soğuklarda üşüdüm ve kim bilir kaç defa büyüsüne kapılıp bir bütün olduğumu anladım her şeyle,........        her şeyimle........

Ve kim bilir kaça defa içim doldu ama ağlayamadım yokluğuna 

O duygu.O  duyguyu hissedince unutuyordum her şeyi ve her şeyi anlıyordum o anda her şey benle ve bende onlarda birim aslında

mat,donuk, ama derin yağmur bulutları benim aslında, veya belki de bendim bir zamanlar....

kanları donuyor herkesin o günlerde, o bulutlu günlerde, ama benim içimde  bir neşe ateşi yanıyor o zamanlarda

anladım ki şimdi ne ben yağmur bulutuyum ne de sen yakın 

sadece ilk anladığım gündü sevdiğimi yağmurlu bulutlar ve sen bana yakın', 'Serin sular içtim,  uzak yollar gezdim, nice yağmurlar gördüm Nice soğuklarda üşüdüm ve kim bilir kaç defa büyüsüne kapılıp bir bütün olduğu...', ARRAY['Türk Edebiyatı','Şiir','Ümit Terzi']::text[], 8.5, '{"poet":"Ümit Terzi","poet_slug":"umit-terzi","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/serin-sular-bulutlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş', 'ates-umit-terzi-gyjig', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Neden dedim kendi kendime bu halim son zamanlarda, 

ve nerede O şu an 

Belki de onunda bağrında, 

titreyerek yanan, dumanı boğazını yakan bir ateşi vardır,

yanan, 

yakan.... 

yok eden', 'Neden dedim kendi kendime bu halim son zamanlarda,  ve nerede O şu an  Belki de onunda bağrında,  titreyerek yanan, dumanı boğazını yakan bi...', ARRAY['Türk Edebiyatı','Şiir','Ümit Terzi']::text[], 8.5, '{"poet":"Ümit Terzi","poet_slug":"umit-terzi","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ates-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedir ki?', 'nedir-ki-umit-terzi-xy5hb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nedir ki sözcükler

Donmuş güller, 

Gökyüzünde yanan kuşlar,

Yalnızlığım, sana aşkım

Dünyam, her anım

Nedir ki uçup giden 

Benden başka...', 'Nedir ki sözcükler Donmuş güller,  Gökyüzünde yanan kuşlar, Yalnızlığım, sana aşkım Dünyam, her anım Nedir ki uçup giden  Benden başka......', ARRAY['Türk Edebiyatı','Şiir','Ümit Terzi']::text[], 8.5, '{"poet":"Ümit Terzi","poet_slug":"umit-terzi","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/nedir-ki-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyküler - 1', 'oykuler-1-i-rfan-sen-qd3r6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zaman farkı...

İnsanı durup dururken hiçbir dış etken yokken mutlu kılan duygu nedir? 

Bu anlatılması mümkün olmayan birkaç özellikten birisi insan için. Zaten onlar çözülmüş olsa herhalde bir anlamı kalmayacak hayatın. Düşünsenize; neyi ne için yaptığınızı ve nasıl davranacağınızı bildiğinizde bugünün yarının ve yarından sonrakilerin ne önemi var ki. 

İnsan bildiklerinin değil bilemediklerinin peşinden koşuyor. Belki de son yıllarda adrenalin peşinden koşma tutkusu da bunun için. Sonucu ölüme götürebilen bu deneyimler hayatta zevk alma noktalarımızın çok çok azaldığının bir göstergesi değil mi? 

Her bireyin kendi başına kendisi için ne ifade ettiği önemli muhakkak. Yalnız bunu keşfetmeden diğer insanlar için nasıl bir görüntü teşkil ettiğinin peşine düşüp sırf burada puan kazanmak için yaptıkları kendi iç dünyasında kendini sıfırlamaya giden yoldur ki en tehlikelisidir. Bu sebeple etrafımızda çok iyi niyetli olduğunu düşündüğümüz birçok insanı kaybettik ve kaybetmekteyiz. İnsanı tüm bu olayların arasında dolandırıp duran istek duygu ve hissiyat ne kadar önemli ise, onun varlığını keşfedip yönlendirebilmekte o kadar zordur. Bunları biliyor olmak maalesef kurtarmıyor bizleri...

 Yüzmeyi bilen hemde iyi bilen insanların denizde boğulması gibidir ki örneği sayılamayacak kadar çoktur.

 Schopenhaur derki; 

 “Bir adamın onuru, onun yaptıklarına değil,hangi acıları çektiğine, başına neler geldiğine bağlıdır.”

Kişiyi olgunlaştıran ve yaşam içindeki yerini belirleyen mademki yaşam koşullarının onun için sunduklarıdır o halde kişi yaşam koşullarının imkanlarını zorlamalı ve hep yaşamadıklarını istemelidir. İşte biz yaşam içindeki hata diye nitelendirdiğimiz tüm olgularla burada tanışmaya başlıyoruz. Başta söylediğimiz gibi, kendimiz için var olan kişiliğin  diğer insanlar için yapılan tutumlardan ayrıştırılamaması halinde böyle bir arbededen kendimizi kurtarabilmek neredeyse imkansız.

İnsanlar yaradılış ve yaşam şekli olarak birbirlerine ne kadar yakın gözükürse gözüksün, bir birlerinin göremediği iç dünyalarında bir o kadar uzaktırlar birbirlerine. Hiç kimse yanlış bir yolda olduğuna inanıp hareket etmiyorken bile bir tek ortak doğru tespit etmek mümkün değil bütün insanlık arasında. On kişinin  doğrusu bir on birinci kişi tarafından rahatlıkla kabul edilmeyebilir. O on kişinin içindeki başka bir fikir de kendi içlerinde bir başka kişi tarafından.

Yani milyonlarca insanın yaşadığı dünyada enteresan bir düzen veya düzensizlik söz konusu.

O halde mutluluk bir dış etken değil kişinin iç dünyasında oluşturduğu bir değerdir fakat bunun oluşmasına da kendi karar veremez.

Hayat bir tiyatro olarak algılanırsa; bilim adamları, felsefeciler ve sanatçılar bu metni defalarca okumuş ve insanlara en uygun şekilde sunmaya çalışan senaristler gibidir. Diğerleri ise oyunu ilk defa izleyen veya ikinci yada üçüncüyü seyreden sıradan insanlar. Her Tarihte senaryo insanların yaşam standardı ve algılama şekillerine göre güncelleniyor. Lakin metin hep aynı metin.

Her dönem için hayat hep aynı hayat, sunumlar farklı...', 'Zaman farkı... İnsanı durup dururken hiçbir dış etken yokken mutlu kılan duygu nedir?  Bu anlatılması mümkün olmayan birkaç özellikten biris...', ARRAY['Türk Edebiyatı','Şiir','İrfan Şen']::text[], 8.5, '{"poet":"İrfan Şen","poet_slug":"i-rfan-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/oykuler-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saraylım...', 'saraylim-i-brahim-ethem-bingul-hykkc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senin için nice saraylar yaptırdım

Kimselere göstermedim

İçimde saklı tuttum

Bir kaçı benzer bilinen bir kaç saraya

Senin gönlümde ki sarayların hepsinden âlâ..

Sen, gönlümde ihtişamlı Topkapı sarayı

Ve hatta, hatta Dolmabahçe sarayı

Ayrılık günlerimizde Ihlamur Kasrı''sın

Gönül sularımın karşı yakasında

Sen Beylerbeyi Sarayı''sın..

Ölü Aşklar gecesi''nde

Tekneyle dolaştık ve uğradık bir kaçına

Bomboştu koca saraylar

Bomboştu salonlar, odalar..

Sen yoksan sarayları neyleyim

Sen yoksan saraylar içimde de

Ben sanki viraneyim

Sen yoksan

Hüzün var içimde....

www.iebingul.com', 'Senin için nice saraylar yaptırdım Kimselere göstermedim İçimde saklı tuttum Bir kaçı benzer bilinen bir kaç saraya Senin gönlümde ki sarayl...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/saraylim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyüsün', 'buyusun-mehmet-fatih-67gtf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Büyüsün

Anne karnında bebek

büyüsün

evlerde hüzün

büyüsün

sokakta barikat,sapanda çocuk

büyüsün

sarayevo''da azim,grozni''de iman

ramallah''ta şehadet

büyüsün

çelikte mermi

atomda bomba

hidrojende su

büyüsün

katillerin yüreğinde vurulmak korkusu

büyüsün

çağda yangın

dağda cesaret

büyüsün

küresel özgürlükle sınanmış esaret

büyüsün

sandalyede sanık

cübbede savcı

tezgahta dava

büyüsün

ekmek ve su parayla çünki

büyümek

bedava...', 'Büyüsün Anne karnında bebek büyüsün evlerde hüzün büyüsün sokakta barikat,sapanda çocuk büyüsün sarayevo''da azim,grozni''de iman ramallah''ta ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih']::text[], 8.5, '{"poet":"Mehmet Fatih","poet_slug":"mehmet-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/buyusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Burdasın çünki.../', 'burdasin-cunki-mehmet-fatih-bahsz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Göğü yırt

göğü kar

gök çift saçaklı zencefildir

ucuna bucağına yapışır hareleri

ay batar nehrimin aksinde

...iç ve kan

tersimdesin çünki

düşersem altta kalır çöl olursun

savrulursam

alaca ve karanlık

/düş tutar uykuları annemin/

  .

  .

göğü yırt

göüğ kar

gök yanbakışlı külhanidir

ine çıka incelir

piyer loti yokuşunda

maviliği

sıyırdığı terimdir/

tenimdir biraz da

...iç ve yan

yanımdasın çünki

tutarsam alazlanıp çürürsün

patlarsam

yarımca ve yanık

/kas tutar tüfekleri.../

   11 temmuz 2004', 'Göğü yırt göğü kar gök çift saçaklı zencefildir ucuna bucağına yapışır hareleri ay batar nehrimin aksinde ...iç ve kan tersimdesin çünki düş...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih']::text[], 8.5, '{"poet":"Mehmet Fatih","poet_slug":"mehmet-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/burdasin-cunki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgem', 'golgem-mehmet-fatih-lrfeq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karanlık sokaklarda 

uzayıp giden gölgem

aşılmaz yasaklarda

beni ben eden gölgem

gündüzler sana gece

geceler iki hece

güneş doğmadan önce

ayrılık neden gölgem...', 'Karanlık sokaklarda  uzayıp giden gölgem aşılmaz yasaklarda beni ben eden gölgem gündüzler sana gece geceler iki hece güneş doğmadan önce ay...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih']::text[], 8.5, '{"poet":"Mehmet Fatih","poet_slug":"mehmet-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/golgem-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakamoz', 'yakamoz-mehmet-fatih-fw6pq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ay ışığında her gece

bir küçük yakamoz vardı

denizi,kumsalı,aşkı

onun parıltısı sardı

bir sevdayı tutardı o

gözyaşlarını yutardı

o bir küçük yakamozdu

yüreğe yürek katardı

o kumsaldaki fenerdi

o aşkı alıp satardı

o yanık türkülerdeki saz

o ezgilerdeki gitardı...', 'Ay ışığında her gece bir küçük yakamoz vardı denizi,kumsalı,aşkı onun parıltısı sardı bir sevdayı tutardı o gözyaşlarını yutardı o bir küçük...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih']::text[], 8.5, '{"poet":"Mehmet Fatih","poet_slug":"mehmet-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yakamoz-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devran...', 'devran-mehmet-fatih-agfg5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kocaman bir hataydı

gözlerinde kaybolmak

çıkmaz sokaklar varken...

hasret çölüne düştüm

kainat atlasını

ellerinden sorarken...

gizemli bir bakışa

ve güze hasret kaldım

yaz sıcağı sararken...

mecnun müsveddesiyim

aleme rezil olmuş

leylasını araken...

bu hep böyle sürer mi

yolumdan dönemezsem

daha çok vakit varken...', 'Kocaman bir hataydı gözlerinde kaybolmak çıkmaz sokaklar varken... hasret çölüne düştüm kainat atlasını ellerinden sorarken... gizemli bir b...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih']::text[], 8.5, '{"poet":"Mehmet Fatih","poet_slug":"mehmet-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/devran-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Yârim', 'guzel-y-rim-i-brahim-karatas-nm5m0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benim yârim sudan bile güzel,

Periler ki yanında halt etmiş.

Âşka döktüm gazeller bir güzel,

Bülbüller yanımda kemküm etmiş.', 'Benim yârim sudan bile güzel, Periler ki yanında halt etmiş. Âşka döktüm gazeller bir güzel, Bülbüller yanımda kemküm etmiş....', ARRAY['Türk Edebiyatı','Şiir','İbrahim Karataş']::text[], 8.5, '{"poet":"İbrahim Karataş","poet_slug":"i-brahim-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/guzel-yarim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Güzel Şimdi', 'ne-guzel-simdi-i-brahim-karatas-a7ssc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne güzel şimdi! 

Sessiz odamda oturacağım 

sessiz ve loş odamda 

oturacağım ve şiir okuyacağım

ne güzel şimdi! 

Sıcak ve loş odamda

sessizce oturacağım

şiir okuyacağım

ve sıcak odamın 

sessiz ve loş havasında

belki de sana 

bir şiir yazacağım

ne güzel şimdi!', 'Ne güzel şimdi!  Sessiz odamda oturacağım  sessiz ve loş odamda  oturacağım ve şiir okuyacağım ne güzel şimdi!  Sıcak ve loş odamda sessizce...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Karataş']::text[], 8.5, '{"poet":"İbrahim Karataş","poet_slug":"i-brahim-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ne-guzel-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalarım...', 'sevdalarim-mehmet-fatih-ogwia', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir rüzgardı sevdalarım

fark etmeden geldi geçti

ve kayboldu rüyalarım...

bir ateşti sevdalarım

her biri apayrı yaktı

ardında beni bıraktı...

bir yağmurdu sevdalarım

her damlası yüreğimde

varım diyor bende varım

bir denizdi sevdalarım

içinde ben şaşkın balık

ve etrafım kalabalık...

kaybolurken rüyalarım

hasret oldu sevdalarım...', 'Bir rüzgardı sevdalarım fark etmeden geldi geçti ve kayboldu rüyalarım... bir ateşti sevdalarım her biri apayrı yaktı ardında beni bıraktı.....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih']::text[], 8.5, '{"poet":"Mehmet Fatih","poet_slug":"mehmet-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevdalarim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir şey..', 'bir-sey-mehmet-fatih-azai5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sırrını çözemedi

gözlerim gözlerinin

büyüsüne kapılıp

yitiverdi sonunda

bir şey vardı içimde

adını koymadığım

tam sevda diyecektim

bitiverdi sonunda...', 'Sırrını çözemedi gözlerim gözlerinin büyüsüne kapılıp yitiverdi sonunda bir şey vardı içimde adını koymadığım tam sevda diyecektim bitiverdi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih']::text[], 8.5, '{"poet":"Mehmet Fatih","poet_slug":"mehmet-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-sey-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedir ki?', 'nedir-ki-mehmet-fatih-6fqmp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben değildim

sen değildin

dünyaya yar olmayan

bir düş kurdum ki zihnimde

aslında var olmayan...

güller topla benim için

ve sonra aşkı hatırla

sevdasız da yaşayalım

akıla zarar olmayan..', 'Ben değildim sen değildin dünyaya yar olmayan bir düş kurdum ki zihnimde aslında var olmayan... güller topla benim için ve sonra aşkı hatırl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih']::text[], 8.5, '{"poet":"Mehmet Fatih","poet_slug":"mehmet-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/nedir-ki-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susmak.../', 'susmak-mehmet-fatih-ct5xj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Susmak

bir delişmen korkudur

yakar damar damar,tel tel çığlığını cümlelerin

kuş olur tünerim alacakaranlığına yoksa

aşka susarım

başka

su 

    sa

         mam....

2.

susamam

sivrilir kayaları dağların

ölüm yanıbaşım olur kimseler duymaz

yutkundukça  boğulur ses tellerimde şiir

susamam,sağırım çünki zaten bu

kesmek olur bileklerimden parmaklarımı

3.

dedim ki susmak

miş''li geçmiş zamanın cinayetidir

katline ferman çıkar da dokunamam

binbir kere bükülür şehadet parmağım/şehrazat gibi gecelerime

4.

susamam

ne idüğü belirlenir/deşifre olur sessizlik halim

çatırdar tahtaları odamın

neft sızar gövdemdeki yarıklardan

susamam ve çünki susmak

en kötü halidir fikrin...', 'Susmak bir delişmen korkudur yakar damar damar,tel tel çığlığını cümlelerin kuş olur tünerim alacakaranlığına yoksa aşka susarım başka su   ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih']::text[], 8.5, '{"poet":"Mehmet Fatih","poet_slug":"mehmet-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/susmak-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapamam mı..?', 'yapamam-mi-mehmet-fatih-wylg0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Giderim

ardımda bir ayak izi olur suretim

tanınmaz olurum şehrimde

belirsizleşir kimliğim...

giderim...

kalırsam vurular çünki

yarımlanır yüreğim

içim çekilir ve

her lodosta kurur

 gözlerim

giderim...

oturuşum kalkışım zarardır

yürüyüşümle bulanır çöllerim

mevsimlere vururum gövdemi

gittikçe durulur zihnim

giderim...

der-top olur cümlesi

                                 dertlerim

çantamda herşeye biraz yer vardır

biraz da çantamdır zaten herşeyim

giderim; 

derler ki gitmek gibidir ölüm

ölümlü olmaksa benim kaderim...

                     9 temmuz 2004', 'Giderim ardımda bir ayak izi olur suretim tanınmaz olurum şehrimde belirsizleşir kimliğim... giderim... kalırsam vurular çünki yarımlanır yü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih']::text[], 8.5, '{"poet":"Mehmet Fatih","poet_slug":"mehmet-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yapamam-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Dayanmazsam Geçmeyecek...! ..! ..! ..!', 'dayanmazsam-gecmeyecek-metin-eser-oq5nz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hüzünlü başlayan bir haftanın,

Sevinçli bir Salı günüydü sanırım,

Gülücüklerim deste deste,

Sözlerim beste besteydi,

Vardı bir hal, keyfim yerindeydi elbette,

Gerçi sabaha kadar hüzün hakimdi ya,

Şükürler olsun, kurtuldu dertlerinden....

Kanser hastası bir dostum vardı,

Haftalardır hastahanede, tedavide

Ve son birkaç gündür komadaydı,

günler sonra bekleyişlerin ardından 

bu sabah ameliyattan çıkmıştı....

Bütün gece uyumamıştım,

Gözlerim, 

kan çanağı olmuştu ağlamaktan,

Seccadem şahittir bu duruma,

Secde yeri varya hani,

Alnımın değdiği yer,

İşte oradan doğrulurken ezan sesleriyle,

Gözyaşlarım yanaklarımdan aşağı,

bardaktan boşanırcasına çağlamıştı....

Ve yeni doğmakta olan güne,

Hayırlı sabahlar diyen Güneş''e

Ve daha ne varsa hayatıma gerekli,

Hepsi bana yabancı olmuştu,

Kulağım sağır, düşüncem kahır,

Bedenim 

her zamankinden daha ağırdı...

Hayalim yüksek bir duvarın önünde 

çaresiz gibiydi....

Ve neden sonra acı bir zil sesiydi,

evimin yarı boş odalarında yankılanan...

Gelense dostumun kardeşiydi,

Seslendi telaşla, ''aç abi aç'' dedi,

''Müjdem var sana...''

Ve çakılıp kaldım öylece, 

boğazımda bir yumruk düğümlüydü,

Durdum bir an ve gelen haber,

müjdelerin hangisiydi...

öyle ya, müjde vardı, müjde vardı...

Hep derdi bana ''ölsem benim için kurtuluş'',

herkes bilirdi söylediklerini....

Bana göreyse müjde hayata dönüş...

O benim dostumdu, can dostum.....

Ve beklediğim o müjdeli haber, 

benim müjdemdi ve o yaşıyordu.....

İşte bugün bu sebepten neşeliyim...

Tuttum hastahanenin yolunu,

ayaklarım dolaştı kaç kere,

gece 

baş ucunda beklemek istemiştim oysa,

izin vermeyip, git dinlen demişlerdi....

günlerdir nerede yaşadığımı bilmeden

almıştım nefeslerimi oysa....

Ve şimdi ona koşuyordum tekrar,

merdivenleri bir çırpıda çıkıp,

odasının önüne geldiğimde,

heyecanım öyle çoktu ki,

yüreğim dışarı çıkacaktı sanki,

ve dediler,

''Biraz beklemeniz gerek.''

Çekildim bir köşeye ve bekledim...

Eski neşeli günlerimiz geçti gözümden,

''Var mıydı bizim gibi dost'' dedim kaç kere....

İç çekerek ne hatıralar film oldu 

ve aktı hayal perdelerimden....

Ben bu minval üzere iken,

O sıra bir çocuk getirdiler,

Beş altı yaşlarında ha var ha yok,

yüzünde çektiği acının gerçek izleri

fotoğraf fotoğraf işleniyordu hafızama...

içim acıdı, yüreğim yandı,

annesiydi herhalde yanındaki,

ve ''kanser tedavisi görüyor abisi'' dedi,

gözlerim doldu, nutkum tutuldu,

sanki bir an nabzım durdu,

Ve çekinerek sordum,

''çok mu canın yanıyor'',

Verdiği cevap çok manalıydı,

tam bir gerçek ve imalıydı,

''Evet abi'' dedi, ve ardından,

''Ama biliyor musun dayanmam gerek''

''Çünkü, dayanmazsam geçmeyecek...''

...............

dayanmazsam geçmeyecek...

dayanmazsan geçmeyecek...

dayanmazsak geçmeyecek...

...............

kulaklarımda çınladı dakikalarca....

Yere çökmüşüm, dizlerimin bağı çözülmüş,

Göz yaşlarım çoktan özgür olmuşlar,

Belki de hiç dinmeyecek,

Ve o çocuk, 

..............dağlardan büyük bir yürek taşıyordu,

ser levha oldu bana, 

..............o küçücük ağızdan çıkan, büyük söz,

''Dayanmazsam geçmeyecek''

19.07.04 / Frankfurt

- Hayatın her döneminde ne kadar içinden çıkılmaz durumlar olsa da, öğrendim ki, dayanmazsam geçmiyor, geçmesi için sabır, azim ve irade ile dayanmak gerek....', 'Hüzünlü başlayan bir haftanın, Sevinçli bir Salı günüydü sanırım, Gülücüklerim deste deste, Sözlerim beste besteydi, Vardı bir hal, keyfim y...', ARRAY['Türk Edebiyatı','Şiir','Metin Eser']::text[], 8.5, '{"poet":"Metin Eser","poet_slug":"metin-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":99,"source_url":"https://www.antoloji.com/dayanmazsam-gecmeyecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kul man', 'kul-man-yunus-ali-sinanoglu-9m9cj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yeryüzünü ben yaratmadım

Yedi mevsim onbir ay

Yapardım ben olsaydım

Yansın mart ayrılıktır gereksiz

Yedi mevsim yemez yedirmez

Dört sevdayı anlatmaya yetmez

Ben yaratsaydım öyle

İşte böyle

Tabi ki benim fikrim

Şimdi sen yeşilsin

Seni yaratsaydım

Aşık olamazdım sana

Ve yeşil olurduk

Kırmızı sen de güzel oysa

Ve demek ki kul olmak

Güzel yaratmaktan

Sana da kul olmak an be an

Ne güzel olur hem de ne güzel

Gece sen de başlar sen de biter

Yaratmak kulluğundadır

Kulluğun aşkını yaratmada

Ne olur hiçbirşey anlama', 'Yeryüzünü ben yaratmadım Yedi mevsim onbir ay Yapardım ben olsaydım Yansın mart ayrılıktır gereksiz Yedi mevsim yemez yedirmez Dört sevdayı ...', ARRAY['Türk Edebiyatı','Şiir','Yunus Ali Sinanoğlu']::text[], 8.5, '{"poet":"Yunus Ali Sinanoğlu","poet_slug":"yunus-ali-sinanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kul-man-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onüç', 'onuc-yunus-ali-sinanoglu-wc9l1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Onüç hangi sayıdır

Birşeyin altı katıdır

Onüç dört mevsim gibi

Biri erkek hepsi dişi

Onüç kadar sevdim

Onüçüncü olmayı seçtin

Onüç ıssız ada

Külahıma anlatsana

Üstünden geçer gemiler

Onüç gerçekte bir deniz eder

Onüç satır onüç iyi

Onüç sevgililerimin ismi

Ve hepsini sevdim senin gibi', 'Onüç hangi sayıdır Birşeyin altı katıdır Onüç dört mevsim gibi Biri erkek hepsi dişi Onüç kadar sevdim Onüçüncü olmayı seçtin Onüç ıssız ada...', ARRAY['Türk Edebiyatı','Şiir','Yunus Ali Sinanoğlu']::text[], 8.5, '{"poet":"Yunus Ali Sinanoğlu","poet_slug":"yunus-ali-sinanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/onuc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Meteorları...', 'ask-meteorlari-i-brahim-ethem-bingul-w3ibp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karanlık suların mavi soluğunda

İki tarafı ışıklı bir yolda

Yüreğinin eşsiz dokumalı kumaşında

Madalyonun iki yüzü gibiydik...

Yakamozlara düşen aşk meteorları

Ve bunlara eşlik eden martıların çığlıkları

Aşkı taşıyan yelkenlinin kanat çırpışları

Kavuşmuş kol düğmeleri gibiydik...

Tesadüflerin güldüğü o anda

Olmazların inatla olduğu o zamanda

Kaybolmuş ruhların sığındığı o limanda

Dalgalarla kayaların öpüşmesi gibiydik...

www.iebingul.com', 'Karanlık suların mavi soluğunda İki tarafı ışıklı bir yolda Yüreğinin eşsiz dokumalı kumaşında Madalyonun iki yüzü gibiydik... Yakamozlara d...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ask-meteorlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldanış', 'aldanis-akin-tekin-rci1f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Suya yazmışım düşlerimi

Düşüncelerimi rüzgara

Boş bulunmuşum bir an

Aşık olmuşum

Bir kuş misali yüreğimi

Avuçlarımda sunmuşum

Sevmişim insanları,sevin demişim

Yalan sevgiden gayrısı

Yalan severlermiş meğer

Nasıl da aldanmışım', 'Suya yazmışım düşlerimi Düşüncelerimi rüzgara Boş bulunmuşum bir an Aşık olmuşum Bir kuş misali yüreğimi Avuçlarımda sunmuşum Sevmişim insan...', ARRAY['Türk Edebiyatı','Şiir','Akın Tekin']::text[], 8.5, '{"poet":"Akın Tekin","poet_slug":"akin-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/aldanis-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sever Şiir', 'seni-sever-siir-yunus-ali-sinanoglu-emtf4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu sokaklar bizim

Meşhur oldu terörizm

Gözlerinde izim

Seni sürmekteyim

Ağrıyor dizim

Ben seni seviyorum her gece

Sayıyorum delice

Koyun saymak gibi

Seviyorum bir iki

Sonsuza uzanıyor bu

Limit almaya çalışıyorum

Ama bilmiyorum

Çünkü matematiği satıp işletme okuyorum

Ve seni seviyorum

Türevlerden ötede

Sen ne güzel şeysin

İnci dişli olmayan gelin', 'Bu sokaklar bizim Meşhur oldu terörizm Gözlerinde izim Seni sürmekteyim Ağrıyor dizim Ben seni seviyorum her gece Sayıyorum delice Koyun say...', ARRAY['Türk Edebiyatı','Şiir','Yunus Ali Sinanoğlu']::text[], 8.5, '{"poet":"Yunus Ali Sinanoğlu","poet_slug":"yunus-ali-sinanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/seni-sever-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahve Falı', 'kahve-fali-ahmet-hakan-yilmazturk-02pnp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kahveler nasıl olsun

benimki orta şekerli

köpüğü de  hareli

fincanı kısmetle dolsun

hoş geldin beş gittin

üç beş sohbet ettin

Sade rica edeyim

zahmet olmasın

kırk yıl hatırım kalır

içmeyene aşk olsun

hoş geldin beş gittin

üç beş sohbet ettin

Aman dikkatli yap

kısık ateşte pişsin

köpüğünü dağıtma

ay ay sakın taşırma

hoş geldin beş gittin

üç beş sohbet ettin

Yarısını doldur

pişir, taşır

tekrar doldur

azıcık hile serbest

hoş geldin beş gittin

üç beş sohbet ettin

Al kaşığı köpük aktar

fincandan fincana

söylemezsen kim bilecek

olsa olsa kısmeti artar

hoş geldin beş gittin

üç beş sohbet ettin

Kızım fincana bakma

karşıya bak ki dökülmesin

bak gördün mü döküldü

üzülme kısmetin taştı dersin

hoş geldin beş gittin

üç beş sohbet ettin

Pek lezzetli olmuş

eline koluna sağlık

bir de bana sor beyim

piştim ki ne piştim

hoş geldin beş gittin

üç beş sohbet ettin

Ah yavrum bilseydin 

kahvecisi ne yaparmış

Mustafa Kemal’in 

dinle de ustalık öğren 

hoş geldin beş gittin

üç beş sohbet ettin

Sade, orta hem de şekerliyi

aktara aktara fincana

ekleye ekleye tadını

tek cezvede yaparmış

hoş geldin beş gittin

üç beş sohbet ettin

Pek becerikliymiş

yüz kırk yıl hatırlı 

kahveci dediğin

işte böyle olmalı

hoş geldin beş gittin

üç beş sohbet ettin

Fal bunun neresinde

Allah iyiliğini versin

buncacık anlattım

ona da artık sen bak 

hoş geldin beş gittin

üç beş sohbet ettin

19.072004', 'Kahveler nasıl olsun benimki orta şekerli köpüğü de  hareli fincanı kısmetle dolsun hoş geldin beş gittin üç beş sohbet ettin Sade rica edey...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hakan Yılmaztürk']::text[], 8.5, '{"poet":"Ahmet Hakan Yılmaztürk","poet_slug":"ahmet-hakan-yilmazturk","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/kahve-fali-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun gözlerimdeki kahverengi', 'yorgun-gozlerimdeki-kahverengi-lzcramcil-ceyhun-erdem-7lqk0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerim,

gözlerim yorgun,

kendimden bir usanç var, kendimden

gözkapaklarım soğuk, ayaklarım ateş, sözcüklerim sus pus.

yorgun, bitkin gözlerimdeki kahverengi.', 'Gözlerim, gözlerim yorgun, kendimden bir usanç var, kendimden gözkapaklarım soğuk, ayaklarım ateş, sözcüklerim sus pus. yorgun, bitkin gözle...', ARRAY['Türk Edebiyatı','Şiir','Lzcramcil Ceyhun Erdem']::text[], 8.5, '{"poet":"Lzcramcil Ceyhun Erdem","poet_slug":"lzcramcil-ceyhun-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yorgun-gozlerimdeki-kahverengi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Kadar Kolay mı', 'bu-kadar-kolay-mi-akin-tekin-82c6t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'mutlu olmak bu kadar kolay mı

seni düşlediğim anlarda

tatlı bir huzurla doluyor gönlüm

masmavi bir nehir akıyor içime

koyu karanlıklar içinden

aydınlık şiirler uçuyor ellerime

yağmur bulutlarının ardında

güneşin sıcaklığını duyabiliyorum

gözlerine baktığımda gözlerinde

bir çift kedi yavrusu görüyorum

haddini aşan bir masumiyet

kayıtsız şartsız teslim alıyor beni

bu kadar kolay mı', 'mutlu olmak bu kadar kolay mı seni düşlediğim anlarda tatlı bir huzurla doluyor gönlüm masmavi bir nehir akıyor içime koyu karanlıklar içind...', ARRAY['Türk Edebiyatı','Şiir','Akın Tekin']::text[], 8.5, '{"poet":"Akın Tekin","poet_slug":"akin-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bu-kadar-kolay-mi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel İskenderun', 'guzel-i-skenderun-fatih-mehmet-karaca-fd8wd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karşımda yeşil Amanos Dağları

Gözlerini kaydır aşağıya in

Masmavi parıldayan körfez suları

Akdenizin tertemiz suları

  Dünyada görülmemiş güzellikler var

  Sahilde otur denizi seyret

  Başını kaldır yeşilliklere bak

  Şehrin süsü palmiye ağaçları

Büyük İskender’in kurduğu şehir

Perslerle savaşmış bu yer için

Doğu Akdenizin liman şehri

Türkiyemin güzel şehri İskenderun

  Kimleri barındırmadı ki bağrında

  Buram buram tarih kokar heryer

  Kırk asırlık Tür Yurdu içerisinde

  Güzel şehirdir İskenderun

Belen Geçidinden geç in de

İskenderun’a süzül

Bu güzel  yemyeşil şehri

Görmeden geçip gitme

   (19.07.2004) İskenderun', 'Karşımda yeşil Amanos Dağları Gözlerini kaydır aşağıya in Masmavi parıldayan körfez suları Akdenizin tertemiz suları   Dünyada görülmemiş gü...', ARRAY['Türk Edebiyatı','Şiir','Fatih Mehmet Karaca']::text[], 8.5, '{"poet":"Fatih Mehmet Karaca","poet_slug":"fatih-mehmet-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/guzel-iskenderun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelen Kutusu', 'gelen-kutusu-baykal-kaanalp-ap31b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hep sevda bulutları

üzerimdeyken yaşıyorum

güzellikleri

bir de sen olunca

gelen kutusunda

hep umutlanıyorum

yağmur yağınca

güneşle birlikte

aşkın doyumsuzluğuna

varıyorum

solunca karanlık

gelince aydınlık

habercileri

bir de sen olunca 

gelen kutusunda

bütün bulutları

yakıyorum,yanmıyorlar

onlarda inanıyorlar

aşkın büyüsüne

gözyaşının buğusuna

aşk olunca

işin içinde

illede gözyaşı arıyorum

sonunda

sonucunda

gözyaşsız bir aşk

düşünemiyorum

bir de sen olunca

gelen kutusunda

''düşünmek,yaşamaktır

atılan her çentiği

düşünmek umuttur

geleceğe dair

cevap aramaktır

sorulara

düşünmek beklemektir

baharı

kıştan sonra

zaten her zaman

gelir bahar

bana''

bir de sen olunca 

gelen kutusunda', 'hep sevda bulutları üzerimdeyken yaşıyorum güzellikleri bir de sen olunca gelen kutusunda hep umutlanıyorum yağmur yağınca güneşle birlikte ...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/gelen-kutusu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serçeyim', 'serceyim-baykal-kaanalp-h63ir', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ben aşık olmak isteyen

bir serçeyim

köşebaşındaki ağacın

dallarında yuvalanırım

her sabah ve akşam

sen geçerken

seni görebileyim diye

geceleri uyumam,uyuyamam

seni düşünmekten

ağlamak isterim bazen

kendi halime

ama ağlayamam

ben ağlamasını da bilmem

hiç öğrenemedimde

ben aşık olamk isteyen

bir serçeyim

evinin damında yuvalanırım

her sabah ve akşam

soluduğun havadan

bir nefes alabileyim diye

ama hiç alamam

alsam bile doyamam

sana nasıl doyulur ki? 

sensiz nasıl olunur ki?', 'ben aşık olmak isteyen bir serçeyim köşebaşındaki ağacın dallarında yuvalanırım her sabah ve akşam sen geçerken seni görebileyim diye gecele...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/serceyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ansiklopedik Hatırlatma', 'ansiklopedik-hatirlatma-ahmet-aksoy-03vji', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'zaman makinesini buldum 

tek gereken dört vida dört somun

dedi kendi kendine Huygens Christian

ki o gün bugündür saat çalışmakta

................................................bir akrep bir yelkovan.', 'zaman makinesini buldum  tek gereken dört vida dört somun dedi kendi kendine Huygens Christian ki o gün bugündür saat çalışmakta ..............', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ansiklopedik-hatirlatma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekçi Kalsın Düşlerim', 'bekci-kalsin-duslerim-baykal-kaanalp-chiow', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yaşıma bakan benim

yaşantıma sen

kalpsiz olan benim

kalpten seven sen

içime doğansın güneş gibi

aydınlatan iklimleri

sevdayla yanar gözlerin

beni de yakar ateşin

yaşlı gözler benim

kurulasın ellerin

belki dönersin diye

bekçi kalsın düşlerim', 'yaşıma bakan benim yaşantıma sen kalpsiz olan benim kalpten seven sen içime doğansın güneş gibi aydınlatan iklimleri sevdayla yanar gözlerin...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bekci-kalsin-duslerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun Artık (Olmayacaksın...)', 'yoksun-artik-olmayacaksin-hasan-can-mq5vb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dün gece seni bekliyordum

Gelecektin biliyordum

Bütün engeller yolunu kapatsa da

Aşacaktın söylemiştin

Kimseye uğramadan

Vakit geçirmeden gelecektin

Nerde kaldın söyle

Revamı bu bana söyle

Yeminler etmiştin

Bana kavuşmadan ölmeyecektin

Beni yapayanlız bırakmayacaktın

Acı çektirmeyecektin bana

Sırtımdan vurmayacaktın

Hala yaşıyormuşsun

Öyle söylediler...

Pişman değilmişsin

Yaşamak güzel demişsin

İhanet etmedim uğradım demişsin

Kirli yalanlarına beni alet etmişsin

Sen artık yoksun sevdiceğim

Benim kara gözlüm değilsin

Uğrunda ölmem artık

İncittin beni be..yazık ettin bana

Göreceksin sende

Yanlışları göreceksin

Kendine acıyacaksın

Ben bumuyum diye

Sonra anlayacaksın ki

Pişman olmakta yetmiyormuş...

Sen yoksun artık

Ve ben varolduğum sürece sen olmayacaksın...', 'Dün gece seni bekliyordum Gelecektin biliyordum Bütün engeller yolunu kapatsa da Aşacaktın söylemiştin Kimseye uğramadan Vakit geçirmeden ge...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yoksun-artik-olmayacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Semada-56', 'semada-56-ahmet-kose-gcqch', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüreğimde 

yeni yürüyen bir bebenin heyecanı

nereye bastığımı bilmeden..! 

Henüz bitmiş bir şiirin

bilinmeyen yorumunu taşıyorum

soğurken kalemim kandillerde.

Kanıma akan tınılar var

bir üstadın inleyen nağmelerinden

kaç vuruş aldırmadan hayatın tuşlarına

akord.! ..hep şırıl tadında.

Maviliğimden kayan

o ışıltısız yıldızlar

bir yana....

Yeni başlayan günlerden

yeni açan gecelerden

yeni doğan yıldızlardan

söz etmek istiyorum

ayrık otları bir yana

ben bir yana

tekbirsiz

salavatsız

bu hayatı gezdirmek istiyorum 

uykusu gelene kadar.

''87/selçuk', 'Yüreğimde  yeni yürüyen bir bebenin heyecanı nereye bastığımı bilmeden..!  Henüz bitmiş bir şiirin bilinmeyen yorumunu taşıyorum soğurken ka...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Köse']::text[], 8.5, '{"poet":"Ahmet Köse","poet_slug":"ahmet-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/semada-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Sordum Mor Sümbüle', 'bir-gun-sordum-mor-sumbule-ali-dost-aydin-8fylh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gün Sordum Mor Sümbüle 

         O yar Beni severmi diye

boynunu büktü önce

neden sonra irkildi 

hesap sorarmış gibi

Önce kendine sor dedi

Mor Sümbül

O yari 

ne kadar sevdiğini

Senin gibi bir şair bilmezmi

Sevdlalıların

Karşılık beklemeden 

              SEVİLDİĞİNİ

Bırak beni Mor Sümbülüm

bırak kendi halime

düşüreyim adını

düşüreyim

dillerime

Mecnun gibi çöle düşüp,

Ferhat gibi dağlar delip,

kavuşayım

SEVDİĞİME

Bırak Beni

MOR GÜLÜM

20/07/2004

03:00', 'Bir gün Sordum Mor Sümbüle           O yar Beni severmi diye boynunu büktü önce neden sonra irkildi  hesap sorarmış gibi Önce kendine sor de...', ARRAY['Türk Edebiyatı','Şiir','Ali Dost Aydın']::text[], 8.5, '{"poet":"Ali Dost Aydın","poet_slug":"ali-dost-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bir-gun-sordum-mor-sumbule-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel bi havada yazılan şiir', 'guzel-bi-havada-yazilan-siir-ahmet-kose-mnj79', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dinlenmek ne güzel bir şey! 

kımıltısız

oturup,ayakları uzatıp

soğuk bira

limon damlatılmış salatalık

dost telefon sohbetleri

kikirikli

hava rüzgarlı hafiften

küllerini savuruyor geçmişin

deniz

gün batımı görevinde kımıltısız

karşı komşu adanın ışıltıları yanıyor

huu komşu akşam oldu..! 

balıkçı esnafı

dönüyor pazarından

patpat ritmleriyle

kimbilir kaç gülücükler yakaladı

tuzlu bıyık uçlarında.

Sessizlik ne hoş

yalnızlık çok hoş..! 

bu sessiz yaşam renkleri kovasında.

Sahiden mi bunlar? diyesim geldi

yürüyen hayatın beyaz perdesinde.

Kaç kez izlediğime aldırmadan..! bu filmi...

temmuz/2003/kadıkalesi', 'Dinlenmek ne güzel bir şey!  kımıltısız oturup,ayakları uzatıp soğuk bira limon damlatılmış salatalık dost telefon sohbetleri kikirikli hava...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Köse']::text[], 8.5, '{"poet":"Ahmet Köse","poet_slug":"ahmet-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/guzel-bi-havada-yazilan-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Narım Can Yarım', 'narim-can-yarim-derin-oger-ps4rb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dağlar suya susar

dağlanan yüreğimdir narım

bulutlara uzar dalım ile budağım

göğü dinleyen ben olduğumu bilesin göknarım

gel dalımda baharım ol

umutlarım çiçeğe dursun al al narım 

gül sanıp bülbül imrensin rengine

yeşiline aşk ben olduğumu bilesin köknarım

her yeni gün sürgünlerini

içime saldığımı bilesin narım

suyu hep diplerinde özlediğimi

hayatı sende bulduğumu bilesin can yarım....', 'dağlar suya susar dağlanan yüreğimdir narım bulutlara uzar dalım ile budağım göğü dinleyen ben olduğumu bilesin göknarım gel dalımda baharım...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/narim-can-yarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınlar Ne İster?', 'kadinlar-ne-i-ster-nilay-aksu-aygki', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '(Mizah)

„Kadınlar ne ister? “ Son günlerin bu hayli moda olan sorusunun yüzlerde yarattığı muzip gülümsemeyi, sorunun içeriğindeki hinliğe bağlarsak çok rahat bunun „erkek“ orjinli bir soru olduğu sonucuna varabiliriz elbette. 

Kanalların birinde, Oya Aydoğan’ın sunduğu bu isimle bir sabah programı yayınlanmakta ve sunucumuz, yayına telefonla bağlanan kadın izleyicilerine yönelttiği „ sööyle bakalım hayatıııım, sence kadınlaaaar nee isteeeer“ sorusuna gelen yanıtların hiç birinin bir diğeriyle aynı olmaması da erkeklerin aslında biz kadınları neden bu derece anlaşılmaz yaratıklar olarak gördüğünün de yanıtı oluyor aslında. 

„Bi kadın en başta sadakat ister“ diyor bir izleyici… Hıımmm, yüzler buruşuyor, „ayyy kaç senelik evlisin anacıııım? “ Bunu söylerken aslında, „kaç senenin üstüne seni aldattı bakiiim o hayvaaaan“ denmek istendiği belli. İzleyici afallıyor, „ben evli değilim Oya ablacıııım“… Hıımmm… Durum daha vahim, „kızım sadakat diye tutturursan, tabii evde kalırsın! “ bakışı bu kez. 

İlgi isteyenler, sadakat isteyenler, anlayış isteyenler, nezaket isteyenler… Biri çıkıp da „gomşumun bilenziğinden istiyom“ ya da „ eltimin arabasına ölüyorum ama ses edemiyorum“ ya da „yazlık istiyorum, kışlığımız bile yok“ demiyor… Yani bir izleseniz, „ kadınlar hiç bir şey istemiyormuş yahu, ama sans yok adamına düşmemisler adamınaa“ diye ağlayasınız gelir vallahi… Geçenlerde yoldan geçen iki erkeğe uzatmışlar mikrofunu…. Oya ablamız soruyor, „ sence kadınlaaaar nee isteeeeerleeeeer“ Yaşlı olanı yanıtlıyor: „ Şinci Oyaanıım, baaayanlar çiçeh kibidir…Onları hiç soldurmamah lazımdır, gadınları üzmeyelim, onlar çiçehtir, narin bi çiçehtir“… İyi de bu amca evde eşine gidip de „ garıcığııım çiçeh kibisin, bi goglayayım seni“ diyor mudur acaba? Dese bile „ dellendin mi ulen, de get işine“ diye bir dirsek darbesi almayacağı ne malum… Ne de olsa kadınların sağı solu belli olmaz… İlgi istedikleri gibi, ilginin fazlasıyla da böğürme moduna girdikleri bilinen bir şey ne de olsa. 

Soruyu bu kez genç olana yöneltiyor ablamız… “valla abla” diyor, kısa pantalonlu, günes gözlüklü, vücut kılları yün kazak görünümünden aşağı kalmayan genç oğlan: “kadınlar her şeyi ister, neyi sayayım ki! ” 

Hah! İşte bu cevap …Beklediğim bu muydu ne? « E valla doğru » diyorum…hem de sesli diyorum, hay allah filmin kötü adamına küfredip terlik fırlatan yaşlı teyzelere döndüm ben de… 

« E ama çocuk haklı » diyorum… Kadınlar her şeyi ister… vallahi de ister, billahi de… Bir seyi istemek icin o şeyin adını duymaları bile yeterlidir üstelik, ne olduğunu bilmelerine gerek yok. 

“ Balayımızda Bahama Adalarına gitmek isterim” 

“ Iyi de Bahama nereee, Sinop nere? ...Neresidir biliyo musun? ” 

“Yok bilmiyorum ama Viktor, Eşli’yi götürüyodu yaa orası işte” 

Buyrun… Hanım kızımız Antalya’yı dünya gözüyle bir kere görür mü belli değil, ama Bahama istiyor… İsteeer, istek degil mi? 

“Adamına düşmedik kardeş, bak elalem elleri kolları dolu geziyo… Gördün mü Safiye’nin bileziklerini? ” 

“E onun adamı kaçakçı diyolar amaa” 

“ Olsun, kaçakçı maçakçı... karısı havasını atıyo ya” 

Kocasının kaçakçı olduğu söylenen, eli kolu altın dolu Safiye’ye sorsanız, kocasının Romen metresinden ağlanıp “kuru ekmekle soğan yiyeydim de, erkeğimi kimseye vermiyeydim” diye sızlanacaktır mutlaka. Oysa Safiye’nin bileziklerine özenen diğer kadınmız kaçakçılık yapmayan kocasının ardından “ kaçakçılığı bile beceremez” diye sövecektir büyük ihtimalle. 

Yani kadınları mutlu etmek, deveye hendek atlatmaktan zordur diyen erkeklere hak mı vermeliyiz ne? 

Sahiden ne isteriz biz? Anlaşılmak isteriz… Ama anlayan kişi, bizim bayılıp öldügümüz kişi olmalıdır… Diğer anlayanlar? Iıı ıh, yok, onlar anlasa da yanlış anlar zaten. Bizim bayılıp öldüğümüz kişinin bizi anlaması yeter mi? Hadi canım, kupkuru anlaşılmak kimi mutlu etmiş ki… Zaaflarımızı önümüze dökenleri bir kere hiç sevmeyiz… Bizi anlayan kişi, bizim aslında ne harika, ne dayanılmaz, ne çekici, ne akıllı, ne iyi, ne becerikli, ne vazgeçilmez olduğumuzu anlayan kişidir… Yani anlaşılmak demek, değerimizin anlaşılıp hayran olunmamız demektir aslında. 

Düsünsenize… „senin kafan var yaa..aslında hiç çalışmıyor“ diyen bir erkek, aslında pek de yerinde bir tespit yapmış ve sizi anlamış olabilir. Peki bu anlaşılmanın sizi mutlu etme yüzdesini düsünürsek… ya da vazgeçelim… bu sözü söyleyen erkeğin, bu sözü söyledikten sonra başına gelecekleri yüzdeler halinde düsünmek daha mantıklı geliyor nedense. 

Haa bir de kadınlar, kendilerinin yanında hemcinslerinden sürekli olumsuz olarak bahsedilmesini ister… Düsünsenize, „Naci’nin karısının elmacık kemikleri ne güzel değil mi, hayatım’ diye soran bir adamın akıbetini… Bizler, Naci’nin karısının çarpık bacaklarından başlar, seyrek saçlarından çıkana kadar zavallı kadını, onu övme gafletinde bulunan erkeğimizin gözünde bir tarla faresi yapana dek kötüleriz ve de işin ilginç tarafı her seferinde bu karalama kampanyasi iyi iş yapar. Yani aklı başında hiç bir erkek, Hülya Avşar’in topuzuna bile iltifat edip de yanındaki kadının iç ve dış dünyasını alt üst etmez. 

Aslında biz kadınlar ne istedigimizi bir bilsek, erkeklere yardım olsun diye hayrına söyleyeceğiz söylemesine de… ah bir bilsek! ... 

İnsan tarafımızın gözardı edilip sadece „kadın“ olarak görülmesi bizi incitir… Ama bazı insanların da (genelde bayılıp öldüklerimiz) , bizim insanlığımızın yanında “kadın” tarafımızı görmemesi bizi deliye çevirir. 

Işte bazı kadınların birer hafta arayla saçlarını..sırasıyla kızıl, sarı ve siyaha boyatması, kestirmesi, saç ekletmesi, yağ aldırması ya da ne bileyim, yeme krizine girmesi genellikle böyle bir bunalım sırasında olmaktadır aslında… “İlle de beğendigi bir tip vardır” deyip bütün tiplere iki hafta içinde girip çıkmaya çalışan kadının, yine de “kadın” tarafını göremeyen özel erkeğe farkedilmeye calışmaktan yorgun düşüp “kesin eşcinseldir” teshisini koyma olasılığı hayli yüksektir. 

Yani uzun sözün kısası, kadınlar en başta hem insan, hem kadın olarak görülebilmek ister… 

Daha sonra mı? …Ne yoksa onu ister :)', '(Mizah) „Kadınlar ne ister? “ Son günlerin bu hayli moda olan sorusunun yüzlerde yarattığı muzip gülümsemeyi, sorunun içeriğindeki hinliğe b...', ARRAY['Türk Edebiyatı','Şiir','Nilay Aksu']::text[], 8.5, '{"poet":"Nilay Aksu","poet_slug":"nilay-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kadinlar-ne-ister-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pusuda Ölüm', 'pusuda-olum-orhan-tuncay-sunc7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sazlar sarıydı, sazlar sıcak ve ıslaktı

Genç adam yorgundu, gözleri çakmak çakmaktı

Puslu ovalar ürkütücü düşlerle bezenmiş

Göl adeta yorgun adam için kadife yataktı.

Süngüsü, palaskası ve belinde matarası

İçten içe sızlayan yeni kapanmış yarası

Puslarla gizlenmiş düşmana kilitlenmişti genç adam

Yorgun düşlerde kavrulurken buğulu anısı.

Bir kurşun zıpkın gibi ayırdığında pusları

Kana bulayıp, kızartıp, daha da ısıtınca sazları

Bir çığlık yaşama takılı kaldı bulutlarda

Silip, süpüren, dümdüz eden tüm düşleri, korkuları.

Sıcak sazlar bile ısıtamaz göle sızan yaşamı

Bir eksik, bir fazla, bir rakam hayatın anlamı

Genç adam artık bir meçhul asker bir yerlerde

Onu tek adlandıran tahtaya çakılı nişanı.', 'Sazlar sarıydı, sazlar sıcak ve ıslaktı Genç adam yorgundu, gözleri çakmak çakmaktı Puslu ovalar ürkütücü düşlerle bezenmiş Göl adeta yorgun...', ARRAY['Türk Edebiyatı','Şiir','Orhan Tuncay']::text[], 8.5, '{"poet":"Orhan Tuncay","poet_slug":"orhan-tuncay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/pusuda-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen uyandığında (Üç dakika yirmi bir saniye)', 'sen-uyandiginda-uc-dakika-yirmi-bir-saniye-emre-senkal-2np6l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen uyandığında (Üç dakika yirmi bir saniye) 

Sen uyandığında sarıyor hayat etrafımı

Sen gözlerini açtığında, ben uyanıyorum aslında.

Yüzünü yıkadığında başlıyor hayat,  ayılıyorum.

Uykun geldiğinde hayat ağır basıyor bana

Sen uyandığında yaşıyorum aslında.

Bir yavaşlayıp bir, hızlı atıyor kalbim.

Dünyama ışık geliyor, güneşin doğuyor gecelerime

Içimdeki çocuklarım uyanıyor sen uyandığında.

Gece uyurken bir bıçak gibi kestiğin,

Bu kocaman şehirdeki tüm ışıklar aydınlanıyor,

Içimde bir üfle söndürdüğün mumlar yanıyor,

Yıldızlarım kayboluyor gökyüzümde sen uyandığında.

Sen uyandığında yaşıyorum galiba,

Saniyeler dönmeye başlıyor,

Içimde biri yeklovanlarımı çeviriyor

Zaman kayboluyor sen uyandığında

Sen uyandığında gazete atıyorlar çocuklar kapıma,

Sen uyandığında bir süt şişesi var kalbimde

Içimdeki saatler çalıyor,

Aşka geç kalıyorum sen uyandığında

Ağlamak için yaşlar doluyor gözlerime,

Mendiller atıyorlar çocuklar üzerime,

İçimde kopan tüm fırtınalar diniyor,

Yanaklarıma yağmurlar yağıyor, sen uyandığında

İçimdeki sevgililer kavuşuyor,

Su veriyor bir baba kızına,

Bir çocuk bir hastalıktan kurtuluyor,

bebekler melekleri görüyorlar, sen uyandığında.

Seviyorum diyebiliyorum sen uyandığında,

Uyuduğundaki acılarım kayboluyor,

Bitmeyen özlemlerim başlıyor,

Özlemlerim bitmiyor sen uyandığında.

Içimde unuttuklarını almaya geliyorsun

Bir ateş sigara yakıyor kalbimde,

Içimdeki küller uçuşmaya başlıyor

Rüzgarın ateşlerimi söndürüyor sen uyandığında

Sen uyandığında biri ezan okuyor içimde,

Tüm çanları çalıyor kilisemin, sinagoglarım kapılarını açıyor,

Rahipler koşuşturuyor manastırlarımda

Içimde bir peygamber doğuyor sen uyandığında

Ve içimdeki elmayı ısırıyorum,

Şeytanlarım melekleşiyor,

Yarım kalan herşeyim tamamlanıyor,

Aç kalmış yanlarım doyuyor gökyüzüm, huzurlu yanım

Ve anlıyoruzki uyandığında

Ben senin oğlunum, sende benim kızımsın aslında', 'Sen uyandığında (Üç dakika yirmi bir saniye)  Sen uyandığında sarıyor hayat etrafımı Sen gözlerini açtığında, ben uyanıyorum aslında. Yüzünü...', ARRAY['Türk Edebiyatı','Şiir','Emre Şenkal']::text[], 8.5, '{"poet":"Emre Şenkal","poet_slug":"emre-senkal","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/sen-uyandiginda-uc-dakika-yirmi-bir-saniye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onlar ve ben', 'onlar-ve-ben-yusuf-koc-q0uq3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bizi bize bırakmadılar,kader diyemiyorum...68 kuşağının yitilmişliğidir belki de...kendimi anlatmaya çalıştım ama o dönemin kurbanlarınadır sözüm..! 

Böyle olmalısın diyorlardı,

çocuktum...babam ilkiydi isteyenlerin,

yaşamı olduğu gibi kabullenen,

zorlamayan... rüzgarın estiği yöne giden..

zor kullanırdı bize çoğu kez,

zayıf kişiliğini örtmek için..! 

aile adı verilen o küçük krallığında,

erkini yürütmek için..

mavi gözleri buz gibi bakardı,

bana başımı öne eğmek kalırdı..! 

ve böyle olmalısın diyordu,

benim fikrimi sormuyordu! ..

Hakkımı helal etmem diyordu annem,

din ve ahlak adına...

örf ve töre adına..benim istediğim gibi olmazsan..! 

dar hayat görüşüyle,

kendi döneminin ezilmişliğiyle,

ana sevgisinin ardına saklanarak..! 

ve en doğrusunun kendi bildiği olduğunu sanarak..

ona olan hoşgörüme sığınarak,

sertleşse de zaman zaman..çoğu kez ağlayarak..

ibadeti ve tapınmayı yaşamın..en önemli şartı sayarak...

ve böyle olmalısın diyordu,

benim fikrimi sormuyordu...

Bütün şirinliğini takınıyordu karım..! 

ona layık koca olmamı istiyordu,

kendi ölçülerine göre..

at gözlükleriyle bakarken yaşama,

farketmiyordu ekmeksiz olmamız akşama..

yeterki ayıp olmasın konuma komşuma,

ayıptır, günahtır, yazıktır diyerek,

kınayarak bakıyordu sosyal yaşama..gülümseyerek..! 

ve elde edemediği isteklerini almak için,

kullanıyordu kadınlığının gereklerini...

ve böyle olmalısın diyordu,

benim fikrimi sormuyordu...! 

Dostumsun sen diyerek yaklaşıyodu,

kimbilir o gözlerin ardındaki beyninde,

neler düşünüyordu...

yoklarım çok iken yanımda olmayan,

varım çok iken benden ayrılmayan..

aziz ve kadim dostum! ....

gözünü basılı kağıt parçalarına dikmiş,

koluma giriyordu,

ve öğütlüyodu...

çıkar hesabına dayanan...bir mevsimlik ömrü olan..

yaratıklar gibi..

hayatı öğretmek istermiş gibi görünüyordu,

oysa yalnızca kendini düşünüyordu...

ve böyle olmalısın diyordu,

benim fikrimi hiç sormuyordu! ...

Er kişi niyetine avazlarıyla başlıyordu yolculuk,

bir avuç kalabalık,

ağlarmiş gibi görünen gözler,

üzülmüş gibi duran yüzler,

giden benim ama sözde üzülen onlar..! 

yine her an ki ifadeler..

burada kalacaksın..

burada yatacaksın..! 

ve böyle olmalısın diyorlardı,

kimse benim fikrimi sormuyordu.! !', 'Bizi bize bırakmadılar,kader diyemiyorum...68 kuşağının yitilmişliğidir belki de...kendimi anlatmaya çalıştım ama o dönemin kurbanlarınadır ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Koç']::text[], 8.5, '{"poet":"Yusuf Koç","poet_slug":"yusuf-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/onlar-ve-ben-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapmışsam Yapmışımdır', 'yapmissam-yapmisimdir-murat-demir-mxxy4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşıyor isem eğer,aklım ile yaşarım

İstersem durulurum,isterisem taşarım

Var mı bundan ötesi,bugün var yarın yoğum

Gelmişsem gideceğim,bittiğinde soluğum

Din,iman,imansızlık,benim özel meselem

Gizlidir ecirlerim,başkasına göstermem

İster insan saysınlar,isterse saymasınlar

Canımı alsınlar da,yeter ki soymasınlar

Günahkar olsam bile,sanmam tövbe ederim

İstenilen huzura ben böylede giderim

Ne kimseden af diler,ne başımı eğerim

Yapmışsam,yapmışımdır,nede pişmanım derim

Secdeye başım gitmez,el alem görsün diye

Gül,çiçek vermek varken,elimle sevgiliye

Yaram yok kim ne derse,gücenmem hiç kimseye

Ne haddime karışmak, gidene kiliseye

İnsansam, insan gibi yaşamayı yeğlerim

Anam oğlu olsa da,riyakarı neylerim

Olmazsa daha evla,topluma huzur gerek

Vurur günah işlerim,olurya bilmeyerek

İnsan beşer dir şaşar,derlerya şaşıranlar

İşte onlar değil mi,şaşırıp aşıranlar

Nasılsa tövbesi var,işin kolay tarafı

Çaldığını geri ver,demiyor ki Allahı

İşim olmaz tövbeyle,inanıp yapmış isem

Cezamı da çekerim,haramdan tatmış isem

Kime ne helalimle,oturup içmiş isem

El ense çakırkeyif,uzanıp yatmış isem

Ne işinden anlarım,ne nurundan yobazın

Ölsem de kaşık atmam,aşına düzenbazın

Yaşarım abdal gibi,insanca orda burda

Helal benim özümdür,işim olmaz haramda', 'Yaşıyor isem eğer,aklım ile yaşarım İstersem durulurum,isterisem taşarım Var mı bundan ötesi,bugün var yarın yoğum Gelmişsem gideceğim,bitti...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yapmissam-yapmisimdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yunus Balıklarına Mektuplar (2)', 'yunus-baliklarina-mektuplar-2-canan-ucer-bcfoo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Korkularından boğulduğun an

çekiyor seni geçmişin

o bildik ölümlerine.......

Toy bir çocuğun,

İlk öpüşü gibi

titriyor dudakların..

İrkiliveriyor eşkiya cüssen

korkularının önünde..

Gözlerin yuvalarından fırlayacak,

vakitli vakitsiz bölünecek

uykuların.......

Bak kar kaplamış yolları,

fırtına kopmuş dehlizlerinde..

Ferhat çirkin Şirin’ine 

canını vermiş.

İrkilme,

Titreme,

Diril, diril, diril.........

Vakit yok ki gidenin ardından

ağıtlar çekmeye.

Hangi biri durdurabildi ki 

o suyun akışını...

Ürkme

geçmişinden.

Bir gelincik açar da dağın yamacından,

kan kırmızı rengiyle

akıverir tuvalinde.

Çaylak bir kuş uçmaya başlar...

Bir kadın bebesini doğurur bağ bozumu....

Şehvetinin fosforları dökülüverir

evladını özleyen babanın,

içini kaplayan aynasında.......

Ne olur gül, gül ki

karışıversin yunuslar

gülen gözleriyle sürülerine............

Duy içindeki ölüyü,

Ben ağlarım, yarın geçer,

senin yolun çok uzun....................', 'Korkularından boğulduğun an çekiyor seni geçmişin o bildik ölümlerine....... Toy bir çocuğun, İlk öpüşü gibi titriyor dudakların.. İrkiliver...', ARRAY['Türk Edebiyatı','Şiir','Canan Üçer']::text[], 8.5, '{"poet":"Canan Üçer","poet_slug":"canan-ucer","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/yunus-baliklarina-mektuplar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Harami / Kırmızı', 'harami-kirmizi-zafer-zengin-etnika-koa8f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şarap

