INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babam', 'babam-ali-gencay-o01tj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kuşları çok uzaklara süren mevsim,ekim

soğuk günde doğmuşum,sıcağına hasretim

Toprağı ayazlanmış, boynu bükük karanfilin

Son darbesini indirmiş ayaz,yavru serçenin

Avuçlarını ovan adam,senide harcadı zaman

Yoksun şimdi,en heybetli duruşuyla,babam', 'kuşları çok uzaklara süren mevsim,ekim soğuk günde doğmuşum,sıcağına hasretim Toprağı ayazlanmış, boynu bükük karanfilin Son darbesini indir...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/babam-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğime', 'sevdigime-serap-demirturk-xb1lr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu gurbet illerin dili olsa da 

Anlatsa derdimi, söylese sana. 

Ellerim kuş olup kanatlansa da, 

Sarılsa sevdiğim, yüreğini bir sarsa. 

Dağların ötesinde kalıvermişim, 

Gözlerimin yaşını silivermişim, 

Sensiz uzaklarda gülememişim, 

Özlemim sevdiğim, sevdiğim sana. 

Bir garip akgüvercin olmuş da kalmış, 

Boynunu büküp yayla gülü olmuş, 

Kırık kanadını güllerle sarmış, 

Ağlar bu gözlerim sadece sana.

20.7.2004/SERAP HOCA', 'Bu gurbet illerin dili olsa da  Anlatsa derdimi, söylese sana.  Ellerim kuş olup kanatlansa da,  Sarılsa sevdiğim, yüreğini bir sarsa.  Dağl...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevdigime-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşteki Korku', 'dusteki-korku-serap-demirturk-1w9cf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Korkuyu gördüm düşümde, 

Çığlık çığlığa ağlıyordu. 

Özlemin kucağına oturmuş, 

Tir tir titriyordu. 

Korkuyu gördüm düşümde, 

Bir volkanın içine taht kurmuş, 

Kahkahalar atarak ağlıyordu. 

Korkuyu gördüm düşümde, 

Yüzünü almış avuçlarının içine, 

Kan kırmızısı ağıtlar yakıyordu. 

Korkuyu gördüm düşümde, 

Hoşgörüyü tekmeliyordu kahkahalarla, 

Sevdayı bıçaklıyordu naralarla. 

Korkuyu gördüm düşümde, 

Gözyaşları deniz olmuş; 

Korku,içinde boğulmuş. 

Sıçrayarak uyandım, 

''Canımsın'' deyişine yandım.', 'Korkuyu gördüm düşümde,  Çığlık çığlığa ağlıyordu.  Özlemin kucağına oturmuş,  Tir tir titriyordu.  Korkuyu gördüm düşümde,  Bir volkanın iç...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dusteki-korku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek', 'gercek-serap-demirturk-edp08', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düşten kopuş, 

Gökkuşağının bitişi, 

Ormanın kimsesizliği, 

Dipsiz bir kuyu, 

Saltanat süren kılıç, 

Cesareti şahlanışı, 

Huzura kucak açış, 

Umudun eriyişi, 

Uzakların öyküsü, 

Bilinmedik insanlar, 

Görülmedik düşler, 

Dalgaların savaşı, 

Kum gibi olan kaya, 

Yüze vurulan şamar. 

İşte gerçek!', 'Düşten kopuş,  Gökkuşağının bitişi,  Ormanın kimsesizliği,  Dipsiz bir kuyu,  Saltanat süren kılıç,  Cesareti şahlanışı,  Huzura kucak açış,...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gercek-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çığlığım', 'cigligim-serap-demirturk-ku8wu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tükenen, öz müydü? 

Yiten, umut muydu? 

Biten, gözyaşın mıydı; anlamam ki... 

Dağların ötesine, 

Duvarların gerisine, 

Sonsuzluğun ötesine gidemem ki... 

Denizin dalgasında, 

Rüzgarın kucağında, 

İçindeki çığlıkta olamam ki... 

Verdiğin sevgi miydi, 

Uzattığın zakkum muydu, 

Ağlayan şu gül müydü, bilemem ki... 

Bildiğimi unutsam, 

Elindeki kalem olsam, 

Buluttaki damla olsam, olamam ki... 

Özlemimi attım yangına, 

Çığlığımı verdim dalgalara. 

Ellerimi veremedim, 

Sevgimi veremedim, 

Gülen yüzün solsun istemedim ki...

www.mavikurgu.com', 'Tükenen, öz müydü?  Yiten, umut muydu?  Biten, gözyaşın mıydı; anlamam ki...  Dağların ötesine,  Duvarların gerisine,  Sonsuzluğun ötesine g...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/cigligim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak', 'birak-serap-demirturk-qwppn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bırak yüzsün özlem, alevlerin kucağında. 

Bir bebeğin gülüşünde kalsın sevincin. 

Solmuş bir yaz gülü 

Ya da dağlarda bir zakkum, 

Acı bir sevdanın çiçeği. 

Denize vuramamış ay ışığı, 

Boynunu bükmüş dalga, 

Beklemekten yorulmuş martı... 

Bir balığın kanadında pul, 

Uçurtmanın kuyruğunda renkler 

Ve tükenmeyen kalem olmak... 

Olmazı düşleme bırak! 

Bırak gitsin sana gelemeyen, 

Bırak uçsun sırtında taşla 

Kanadı bağlı güvercin. 

Bırak alevinde yansın sevda, 

Yandıkça büyüyerek.', 'Bırak yüzsün özlem, alevlerin kucağında.  Bir bebeğin gülüşünde kalsın sevincin.  Solmuş bir yaz gülü  Ya da dağlarda bir zakkum,  Acı bir s...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/birak-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Ağacı 3', 'hayal-agaci-3-salih-ozalasan-d9zq6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Adını hayal ağacı koymuştum

Dalların uzayacaktı ben hayal kurdukça

Sevdalara seninle yol almıştım

Yaprağını dökmeyecektin ben hasret kaldıkça

Toprağını sulayacaktı yüreğine sevda düşenler

Adaklar asılacaktı uzanan dallarına

Gelin başına dönecekti gövden

Şahit olacaktın sevenlerin dualarına

Anlatılacaktın nesilden nesil-e

Şiirler şarkılar yazılacaktı adına

Hasret kalmayacaktın dört mevsim kuş sesine

Aşiyanlar yapılacaktı boy, boy dallarına

Senin gölgende söyleyecekti mahcup sevgililer

İlk kez sevdiğine delicesine sevdiğini

Seni seviyorum derken titreyen bedenler

Öne süreceklerdi senin gölgenin serinliğini

Başın gökleri delercesine uzanacaktı

Bulutlar düşecekti eteklerine

Heybetine Uludağ saygı duyacaktı

Korku düşmeyecekti gölgende sevenlerin yüreğine

Hatıra diye saklanacaktı

Yere düşen kurumuş yaprakların

Odun niyetine yakılmayacaktı

Kuruyup kırılsa da yaşlı dalların

Sen hayal ağacıydın

Otağıydın sevip aşık olanların

Dünya durdukça mekanıydın

Sevip sevilenlerin hayal kuranların

Senin toprağını sulamıştı

Yağmur yerine sevenlerin gözyaşı

Bir sana derdini anlatmıştı

Sevilmeden sevenler darda kaldığında başı

Sırdaştın sevene sevilene

Sevilmeden sevip yüreği yangın yerine dönene

Ayrı düşmüşlere hasret olanlara sevdiğine

Sen bir/şeyler katmıştın, beyinlerindeki hayallerine

Sana ne oldu.? ? ? ? 

Kurumaya yüz tutmuşsun

Kalmamış uğrayıp gölgende hayal kuran

Kalmadı mı yoksa.? Allah korusun! ! ! ! 

Sevip sevilen delicesine aşık olan

Esmiyor başında deli rüzgarlar durgunsun

Yok mu artık dua eden.? Adaklar adayan

Seven yürek bir sende kalmış üzgünsün

  

Bir sen bir ben mi kaldık? 

Bu dünyada sevgi için yaşayan

Ben yine ağalarım senin gölgende delicesine aşık

Göz pınarlarım kurusun, seni asla kurutmam

Hayaller var oldukça sen yaşa

Bildiğim tüm duaları okurum susmam

Senin dalların yine uzansın delercesine arş-ı

Sen kuruma; ben sevdiğime asla kavuşmam

Yazım Tarihi 27-05-04

Salih ÖZALAŞAN', 'Adını hayal ağacı koymuştum Dalların uzayacaktı ben hayal kurdukça Sevdalara seninle yol almıştım Yaprağını dökmeyecektin ben hasret kaldıkç...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/hayal-agaci-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tesbih Bahane', 'tesbih-bahane-salih-ozalasan-toirq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir çift kestane rengi göz

Hap/solmuş camdan gözlüğe

Bakışlar yorgun ve mahzun

Hüzün çökmüş endamıyla kirpiğine

Eline almış çelikten bir şiş

El örgüsüne dalmış yine

Sabırdan halkalar peş/peşe

Desen veriyor ipliğe

Küçülmüş mercan gözbebeği

Pür/dikkat önündeki desene

Sordum nedir gözün nurun döktüğün

Dedi sorma tespihime kese

Dedim tespih değil mi sabır taşı

Ne gerek var koymaya onu keseye

Dedi maksat gözün yormak

Tespihe kese bahane

Yandı yüreğim ta derinden

Bir/şeyler koptu içimde

Ben bakmaya doyamam

O inadına eza ediyor gözlerine

Tespih olup gelsek mi dile

Benim için değer mi yeter bu çile

Akmasın gözün nuru

Sabrın sonu selamet beni sakla yüreğinde

Y.Tarihi 15/16-07-04

Salih Özalaşan', 'Bir çift kestane rengi göz Hap/solmuş camdan gözlüğe Bakışlar yorgun ve mahzun Hüzün çökmüş endamıyla kirpiğine Eline almış çelikten bir şiş...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/tesbih-bahane-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başkalaşım', 'baskalasim-i-brahim-karatas-0mwtz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni gördüğü zaman

Tebessümlü yüzünde dalgalar belirirdi.

Göz yaşları yelken açmış

Bir tekne misali dalgalanırdı.

Şimdilerde ise 

Ölü bir balık karaya oturmuş,

Ay yüzün yerine 

Durgun bir deniz soğumuş.', 'Beni gördüğü zaman Tebessümlü yüzünde dalgalar belirirdi. Göz yaşları yelken açmış Bir tekne misali dalgalanırdı. Şimdilerde ise  Ölü bir ba...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Karataş']::text[], 8.5, '{"poet":"İbrahim Karataş","poet_slug":"i-brahim-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/baskalasim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayamadım...', 'anlayamadim-ferit-teksoy-6gqez', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'seni tanıdığıma pişman mı olmam lâzım? 

mutlu mu olmam gerek? 

anlayamadım

aslında çok şey bilir

birazcık da anlardım

seni öğrenemedim

seni anlayamadım

arkadaşmısın desem? 

dostum mu? 

bilemedim..

hep öğrenmek istedim

fakat öğrenemedim

sevgili gibi gördüm

yanıldım olamadım

neyimsin bilemedim

seni öğrenemedim

dengelerim bozuldu

şaşırdım ki..

ne yapsam? 

gelsem gelemiyorum..

kaçamıyorum kaçsam

kızamıyorum kızsam

küsemiyorum küssem

beynime de girmişsin

atamıyorum atsam

ya hepten gir dünyama

ya da beni azad et

ya isim koy bu hale

ya da beni yok farzet

ya geldim de burdayım

ruhunla,fiziğinle

ya git rahat edeyim

sen de git ve rahat et', 'seni tanıdığıma pişman mı olmam lâzım?  mutlu mu olmam gerek?  anlayamadım aslında çok şey bilir birazcık da anlardım seni öğrenemedim seni ...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/anlayamadim-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aşk Hikayesi', 'bir-ask-hikayesi-i-brahim-karatas-zwxta', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bulut gibi aşık oldum

