INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlananın umut olduğu', 'baslananin-umut-oldugu-akin-akca-84rai', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1.

Umutla başlayalım 

Güzel günlere, umutla! 

Ve çevreleyen “asalak,

Kara-perdesini” 

Aralayalım.

Umut vardır, olduğu

Yerde ufkun

Ve ufuktur, fırlatır

Kederi, umudun.

*

Sezinlemek

Bir kaç düstursudur,

Sezdi mi

Tam sezebilen

Bir düşün

İçin.

Sezgi’nin bu tür

‘Bir hamle’de yaptığını,

“Var olduğu 

Anlaşılmadan-

Farkına varılan”

İcra eder de,

… Kendi olamazsa yine

De bir varlık:

Güç, bitmez! ! ! 

: Derim, canına 

Onun, sağlık.

“Kendisi olmadığı

Kendinin”: (Böyle; 

Ya da,‘böyle olsa bile’:

Ama bence,’ böyle’ -

Üzse bile her 

Halikarda)  

Vardır, bir büyük

Varlık.

*

Küçük bir akrep

Var,

Başlananın

Umut olduğu

Ve elde edilenin,

Olduğu kendisi; 

Bir yerde.

Ve akrep sokar; 

Hava sıcak iken,

Sözde! …

Buzdolabına

Girebilir de; 

Sıra dışı olanı,

Aynı akrep

2.

Güneş açsın

Ve kapansın Güneş.

Ölsün yıldızlar

‘Beyaz cüce’ ölmesin,

Ya da.

Musluk aksın.

(Asanızı tepelere asın! 

Atlas gibi,

Yerküreyi sırtınızda

Taşıyın!)  

Musluk akmasın -

Ne çıkar- veya? 

*

Ve ben bir beşik buldum 

Orda:

İçinde,

Timsah gözyaşları

Döken … 

: Ormanda giderken

Korucu’yu gördüm

… Dedi:

“Korkan birileri vardı,

Sen kesme ağaçları …”

(Gökte, 

Aramayalım.) 

-

beyaz cüce: güneşimiz kütlesindeki bir yıldızın öldükten sonraki hali.

güneşimiz 5 milyar yıllık ömrünü tamamlayarak, bir 5 milyar yıl daha yaşayacak.', '1. Umutla başlayalım  Güzel günlere, umutla!  Ve çevreleyen “asalak, Kara-perdesini”  Aralayalım. Umut vardır, olduğu Yerde ufkun Ve ufuktur...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/baslananin-umut-oldugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Hasret*', 'hasret-kubilay-enginol-cq0z2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çocuğun süte

Yemeğin,tuza

Hasreti gibi,hasretim ben sana

Toprağın,yağmura

Bulutun yağmaya hasreti gibi

Hasretim

Çayın şekere,dudağın öpücüğe

Canın bedene,hasreti gibi

Hasretim ben sana', 'Çocuğun süte Yemeğin,tuza Hasreti gibi,hasretim ben sana Toprağın,yağmura Bulutun yağmaya hasreti gibi Hasretim Çayın şekere,dudağın öpücüğe...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hasret-181-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybettim', 'kaybettim-yusuf-koc-jwabe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayatın çamurlu tozlu yolunda,

Baharı görmeden yazı kaybettim,

Güllerim kurudu dikenli dalda,

Tezeneyi buldum sazı kaybettim.

Sevdalandım ateş ile kavruldum,

Boran esti seller ile savruldum,

Acılarla kederlerle yoğruldum,

Yokuşlar çoğaldı düzü kaybettim.

Mabede sığındım duada dilim,

Uzanmadı dostum boş kaldı elim,

Günüm gece oldu yıllarda zulüm,

Yaşama şevkini hazzı kaybettim.

Huzurunda dizi bükmeye geldim,

Mazhar olamadım geri çevrildim,

Boş çınarlar gibi düştüm devrildim,

Ayağım duruldu hızı kaybettim.

Benim gibi yalnız bir kadın buldum,

Nasip almak için hayatı yoldum,

O da vefasızmış artık bir duldum,

Karımı oğlumu kızı kaybettim.

Şiirlerim para etmez satılmaz,

Gördüm ki zenginin beli bükülmez,

Gönülde olmayan dilden dökülmez,

Sustu dilim gayrı sözü kaybettim.

Tükeniyor artık hayat yollarım,

Sarmak hasretiyle yandı kollarım,

Kalana selamlar sevgi yollarım,

Beni değil Koç Ozan''ı kaybettim.', 'Hayatın çamurlu tozlu yolunda, Baharı görmeden yazı kaybettim, Güllerim kurudu dikenli dalda, Tezeneyi buldum sazı kaybettim. Sevdalandım at...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Koç']::text[], 8.5, '{"poet":"Yusuf Koç","poet_slug":"yusuf-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kaybettim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '68 Kuşağı', '68-kusagi-yusuf-koc-v43co', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kılıçlarımız kınlarında,

gömdük savaş baltalarını...

anımsamıyoruz artık,

kan kokan,çürümüş, isli..

vuruşma anlarını..! 

Bir nifak ki..

özümüze kazılmıştı..

düşünmeyen bizim gibi..! bizden değildi..

ve bu düşünce yıllarca egemendi..

eğitimsiz eğiticilerin elindeydik,

ilk saflarda vuruşan amaçsız köleydik..! 

Bir gün...günlerden bir gün, 

dikildi önümüze ekonomik engeller,

yalnızdık..herbirimiz biryerlerdeydik..

ve yeni bir savaş başlıyordu,

yaşam savaşı..! 

Ama bırakmıyordu yakamızı,

geçmişin kütüğümüze yazılmış anılarl..! 

her an karşımızda.. her an peşimizde..

kanayan yara,irin üreten çıban..

ve bu savaşın da yenilecek olanıydık..! 

Hani nerede heyecanlar,

nerede özgürlük diye haykıranlar..! 

bize baş olan başkanlar,

şimdi ceplerini doldurmaktalar..! 

Ve biz amaçsız köleler,

savaşamıyoruz özgürlük için..! 

savaşamıyoruz yaşam için..! 

işte bu yüzden..

kılıçlarımız kınlarında,

gömüldü artık savaş baltaları da.! !', 'Kılıçlarımız kınlarında, gömdük savaş baltalarını... anımsamıyoruz artık, kan kokan,çürümüş, isli.. vuruşma anlarını..!  Bir nifak ki.. özüm...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Koç']::text[], 8.5, '{"poet":"Yusuf Koç","poet_slug":"yusuf-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/68-kusagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Rüzgarın Efendisi!', 'ey-ruzgarin-efendisi-gulay-yildiz-amkyg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çiçek üstü polen gibisin; 

Uçuşup duruyor yüreğin.

/ Biliyorum /

Gözyaşına emanetim

Gelecek o gün 

        ve akıp gideceğim...', 'Çiçek üstü polen gibisin;  Uçuşup duruyor yüreğin. / Biliyorum / Gözyaşına emanetim Gelecek o gün          ve akıp gideceğim......', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ey-ruzgarin-efendisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yola Çıkarsam', 'yola-cikarsam-banu-aka-8mfww', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yola çıktım mı ben

Koşmaktan nefesim kesilir

Dizlerim paralanır düşüp kalkmaktan

Sadece daha hızlı koşabilmek için

Ayağıma batan çakıl taşlarını temizlerken

Soluklanırım bir an

Kanatlanırım dağları aşarken

Anahtarını bulamazsam

Karşıma çıkan kapının

Anahtarıma uyan bir kapı bulurum

Yola çıktım mı ben

Durduramaz beni kimse

Yavaşlatamaz

Çekil yolumdan çocuk

Nefesin yetmez

Benimle koşmaya', 'Yola çıktım mı ben Koşmaktan nefesim kesilir Dizlerim paralanır düşüp kalkmaktan Sadece daha hızlı koşabilmek için Ayağıma batan çakıl taşla...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yola-cikarsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam', 'yasam-banu-aka-1j41u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayallerim değil sadece

Umutlarım var 

Bugünüm için

Düşüncelerim var

Şimdi’lerim için

Ve beklediklerim var

Ellerimle yazdığım

Gelecekten

Ve bildiklerim var 

İşte bu yüzden

Hala 

Arsızca yaşama tutunuşum', 'Hayallerim değil sadece Umutlarım var  Bugünüm için Düşüncelerim var Şimdi’lerim için Ve beklediklerim var Ellerimle yazdığım Gelecekten Ve ...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yasam-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkım', 'askim-banu-aka-y5vp2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana olan aşkımı düşününce

Anlıyorum

Bir karıncanın

Yanından geçen insan karşısında

Nasıl hissettiğini', 'Sana olan aşkımı düşününce Anlıyorum Bir karıncanın Yanından geçen insan karşısında Nasıl hissettiğini...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/askim-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Sevgilim', 'benim-sevgilim-banu-aka-ddpwv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benim sevgilim

Buluta benzer 

Ne zaman hüzünlenip ağlar

Ne zaman sevinir oyun oynar 

Bilemezsiniz

Benim sevgilim

Yıldızlara benzer 

Nerede olduğunu bilirsiniz

Ama yanına nasıl gidilir 

Bilemezsiniz

Benim sevgilim

Saklambaç oynaya mızıkçı çocuğa benzer

Tam buldum dersiniz

Çanak çömlek patlar

Benim sevgilim 

Güneşe benzer

Bir yandan hayat verir 

Bir yandan yakıp kavurur

Benim sevgilim

Atlıkarıncaya benzer 

Neşe mi mutluluk mu

Yoksa dönüp durmak mı 

Başınızı döndürür 

Bilemezsiniz

Benim sevgilim

Yaşamaya benzer

Tam vazgeçtim dediğimde 

Hep yeni bir sürprizle

Çıkar karşıma.', 'Benim sevgilim Buluta benzer  Ne zaman hüzünlenip ağlar Ne zaman sevinir oyun oynar  Bilemezsiniz Benim sevgilim Yıldızlara benzer  Nerede o...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/benim-sevgilim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Zulüm', 'bir-zulum-ozgur-sirius-4nll3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilmedim sevginle kendi derdimi 

Hasretin yolunda yaşamak zulüm 

Kaybettim aşkınla şimdi kendimi 

Verdiğin yangınla üşümek zulüm 

Soruyor gözlerim sensiz gönlüme 

Sabırsız bekleyiş sığmaz ömrüme 

Kaderim bak seni koymuş önüme 

Sevgisiz gönlünü okşamak zulüm 

Böyle mi duracak yanlış duygular 

Yokluğun ardında kalmış saygılar 

Sensiz bir sevgiye dalmış uykular 

Kırdığım aşkınla barışmak zulüm 

Gururum bir engel değil sevgilim 

Kovarsa ellerim gitme der kalbim 

Aşk mıdır Allah’ım nedir bu halim 

Kapanmış yarayı kaşımak zulüm', 'Bilmedim sevginle kendi derdimi  Hasretin yolunda yaşamak zulüm  Kaybettim aşkınla şimdi kendimi  Verdiğin yangınla üşümek zulüm  Soruyor gö...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-zulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İster', 'i-ster-ozgur-sirius-gxzrn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Burası bir yangın yeridir gönül 

Ateşi sönmeden harlamak ister 

Gözlerim kalbimin dilidir gönül 

Yaşları dinmeden ağlamak ister 

Kimlerden saklarsın aşık adını 

Günlerce kazırlar mezar taşını 

Bir damla akıtma sil göz yaşını 

Sellere kapılıp çağlamak ister 

Yalnızlık mahkûmu tanırlar beni 

Umudu tükenmiş bir garip gibi 

Anlatma halini tut nefesini 

Gönlüm bu yarayı dağlamak ister 

Özgürüm sormazlar halin nicedir 

Yokluktan kaçışın gündüz gecedir 

Amacın sadece tekbir hecedir 

Adını aşk ile bağlamak ister', 'Burası bir yangın yeridir gönül  Ateşi sönmeden harlamak ister  Gözlerim kalbimin dilidir gönül  Yaşları dinmeden ağlamak ister  Kimlerden s...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ister-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ele geldi', 'ele-geldi-ozgur-sirius-eep4n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ayrı kaldım soldum yine 

Sıkıca dost oldum kine 

Günah sığmaz iken sine 

Sevaplarım ele geldi 

Görki fena kimin yari 

Bumu beni etti zari 

Dünya ahret sustum bari 

Gönül şimdi dile geldi 

Aşk yoluna düştü gönül 

Hemrah oldu bana bülbül

Uğraşımız belki bir gül 

Sanma yüzbin ile geldi 

Belki anlar aşka eren 

Yokmu benle kalbe giren 

Sözlerini size veren 

Garip gönlüm yele geldi 

Aşık Özgür bilin beni 

Bu aşıklık sanma yeni 

Zerre yokken dertli teni 

Hak yoluna öle geldi

(hemrah – yoldaş)', 'Ayrı kaldım soldum yine  Sıkıca dost oldum kine  Günah sığmaz iken sine  Sevaplarım ele geldi  Görki fena kimin yari  Bumu beni etti zari  D...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ele-geldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşkiya', 'eskiya-ozgur-sirius-pi7y4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gönlüm eşkiyadır bu sevda ilinde 

Mecnun olursa birgün çıkar dağlara 

Yalnızlık mahkûmudur adım dilinde 

Sensiz ölürse gönlüm yakar dağlara 

Gülmedim ki dünyaya geldim geleli 

Yoldaşım ben Mecnuna bildim bileli 

Vefasız bir güzeli sevdim seveli 

Gönlüm acı içinde bakar dağlara 

Günahımda bitmiyor seni severken 

Sonsuz acı çekerim kabre girerken 

Bir gün olsun kalbini aşkı dilerken 

Günahkar şu yüreğim çatar dağlara 

Aşık özgür kendini yakar derinden 

Söylediği sanmayın kendi dilinden 

Eşkiyalık gelmiyorsa da gönlünden 

Alır belki aşkını kaçar dağlara', 'Gönlüm eşkiyadır bu sevda ilinde  Mecnun olursa birgün çıkar dağlara  Yalnızlık mahkûmudur adım dilinde  Sensiz ölürse gönlüm yakar dağlara ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/eskiya-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevenler', 'sevenler-ozgur-sirius-hlxsz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bozulmuş aşkların düzeni yine 

Kâr etmez inan ki ağlamak bile 

Gelirse utanma dertlerin dile 

Sakınma söyle de sevenler duysun 

Sanmayın hayatım neşeyle dolu 

Gülerek geçtiğim çilekeş yolu 

Anladım zamanla gelmiyor sonu 

Sakınma ağla da sevenler duysun 

Kokusu sinmişti üstüme kanın 

Aşkların katili bir beni yazın 

Tükenir de çalmaz olursa sazın 

Sakınma aşkını sevenler duysun 

Özgürüm dünyadan kul geldi geçti 

Kalbine aşıklık hal geldi geçti 

Mezarım üstünden yol geldi geçti 

Sakınma kabrini sevenler duysun', 'Bozulmuş aşkların düzeni yine  Kâr etmez inan ki ağlamak bile  Gelirse utanma dertlerin dile  Sakınma söyle de sevenler duysun  Sanmayın hay...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevenler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidersen', 'gidersen-ozgur-sirius-du9po', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bülbül güle aşkım ile ötüştü 

Bir günüme canlar bile çatıştı 

Deli ömrüm dost gönlünde yatıştı 

Selam söyle gönül dosta gidersen 

Eğer oldu bensiz güller başını 

Sanma mutlu sensiz mezar taşımı 

Ne olursun silme gözüm yaşını 

Aksın söyle gönül dosta gidersen 

Değmiş gönle bir dost eli hanidir 

Giymiş ömre zalim dünya fanidir 

Yerim yurdum gönül dostun yanıdır 

Bilsin söyle gönül dosta gidersen 

Garip Özgür adın niye anılmaz 

Kalbe girsen aşk kadehi sunulmaz 

Bir gün gelir kabrin bile tanınmaz 

Beni söyle gönül dosta gidersen', 'Bülbül güle aşkım ile ötüştü  Bir günüme canlar bile çatıştı  Deli ömrüm dost gönlünde yatıştı  Selam söyle gönül dosta gidersen  Eğer oldu ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gidersen-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terk eyle', 'terk-eyle-ozgur-sirius-l2h8e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kimler geldi kimler geçti buradan 

Boşa kürek çekme sal’ı terk eyle 

Özün mecnun değil aşkın sıradan 

Gönül Kabil olma kibri terk eyle 

Almış sazın ele gönül dağlıyor 

Ayan olmuş mana telin bağlıyor 

Aşık sözün duyan melek ağlıyor 

Damlar gözün yaşı dili terk eyle 

Kalbin duymaz beni gözün kararmış 

Gönül ehli derviş kendin ararmış 

Bülbül yaralanıp güller sararmış 

Vuslat yolun gözler hali terk eyle 

Aşık Özgür adın dilde kalır mı? 

Derdin öyle çok ki sinin alır mı? 

Ferhat dost belledi Kerem tanır mı? 

Cana şüphe girse aşkı terk eyle', 'Kimler geldi kimler geçti buradan  Boşa kürek çekme sal’ı terk eyle  Özün mecnun değil aşkın sıradan  Gönül Kabil olma kibri terk eyle  Almı...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/terk-eyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sever mi sandın?', 'sever-mi-sandin-ozgur-sirius-g2q98', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yokluğun ardından ne diye gittin 

Hasretin gönlüme yeter mi sandın 

Dermansız derdinden hediye ettin 

Aldanıp ömrüme çeker mi sandın 

Feryadım anlamsız kaderim öyle 

Özgürüm sevgisiz yaşanmaz böyle 

Dünyada bir günah sevmek mi söyle 

Sevmeden günahım biter mi sandın 

Böyle mi olacak bu aşkın sonu 

Ne oldu sevecek sandım da onu 

Dinle bak sevdiğim unutma bunu 

Verdiğin dertlere değer mi sandın 

Sevgimi hor görüp beni kırsan da 

Gönlüne sevmeyen biri bulsan da 

Bir değil belki bin dua kılsan da 

Gönlümü bir daha sever mi sandın 

(Üç günlük dünyada sana doymadım)

(Gönlüme başka yar sevgi koymadım)

(Sensizken günleri korkup saymadım)

(Güneşsiz bir sabah geçer mi sandın)', 'Yokluğun ardından ne diye gittin  Hasretin gönlüme yeter mi sandın  Dermansız derdinden hediye ettin  Aldanıp ömrüme çeker mi sandın  Feryad...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sever-mi-sandin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevemem demektir', 'sevemem-demektir-ozgur-sirius-fi65l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şu garip gönlümü bırakıp da gittin 

Böyleyse kaderim gülemem demektir 

Ne yazık sen beni aşka mahkum ettin 

Öyleyse bir daha sevemem demektir 

Bu kadar kolay mı sevmiyorum demek 

Yok olup harcanır bunca zahmet emek 

Verdiğim sevgiyle gönlümü bilmemek 

Aşkımdan habersiz ölemem demektir 

Dertlerim benimdir derman senin olsun 

Dünyada mutluluk aşklar seni bulsun 

Günahsız gönlüme günah dolu yolsun 

Korkarım aşkından gelemem demektir 

Sevgisiz yaşamak ölmekten de zormuş 

Ziyankar gönlümü senin aşkın yormuş 

Habersiz sevgime yarim tuzak kurmuş 

İsyana gücüm yok sevemem demektir', 'Şu garip gönlümü bırakıp da gittin  Böyleyse kaderim gülemem demektir  Ne yazık sen beni aşka mahkum ettin  Öyleyse bir daha sevemem demekti...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevemem-demektir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereye kadar', 'nereye-kadar-ozgur-sirius-smy4q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşkınla belki de gerçeği gördüm 

Sevgiden ders alış nereye kadar 

Ayrılık için de bir hayat sürdüm 

Kuralsız bu yarış nereye kadar 

Doğarken bahtıma hançer vurulmuş 

Günahsız gönlüme günah sorulmuş 

Şu gönül tahtıma dertler kurulmuş 

Anlamsız haykırış nereye kadar 

Özgürüm dünyanın düzeni böyle 

Biter mi bir günde dertlerin öyle 

Anlayan gönüller bulursan söyle 

Zamansız bekleyiş nereye kadar', 'Aşkınla belki de gerçeği gördüm  Sevgiden ders alış nereye kadar  Ayrılık için de bir hayat sürdüm  Kuralsız bu yarış nereye kadar  Doğarken...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nereye-kadar-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül dağı', 'gonul-dagi-ozgur-sirius-nnjr5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşılmıyor bir heceyle şu gönül dağı 

Bin Aşk ile huzuruna çıksam ne olur 

Bülbül idim bir gül için kaybettim bağı 

Ferhat olup şimdi dağı delsem ne olur 

Geçer oldu şu günlerim ahu zar ile 

Yangın yeri sönmez artık gönlüm kar ile 

Gönül dağı göğü aştı zalim yar ile 

Hûma kuşu önüm açıp geçsem ne olur 

Söyle aşık gönül dağı senden yücemi 

Veysel ile yolun birlik gündüz gecemi 

Bunca derdin anlatılmaz tek bir hecemi 

Varın yoğun aşk dolupta sevsen ne olur 

Derdin alıp bir bedenle çıkmıştın yola 

Garip gönlün çekinmeden açmıştın kula 

Neden söyle bunca uğraş bu kadar çaba 

Gönül dağın bu gün yarın aşsan ne olur', 'Aşılmıyor bir heceyle şu gönül dağı  Bin Aşk ile huzuruna çıksam ne olur  Bülbül idim bir gül için kaybettim bağı  Ferhat olup şimdi dağı de...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gonul-dagi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin değil', 'senin-degil-ozgur-sirius-xggsp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sabır eyle gönül dost bahçesinde 

Bülbül benim derdin gül senin değil 

Gezme bir gün olsun bağın üstünde 

Yolcu benim derdin yol senin değil 

Gönül derde düşmüş derman arıyor 

Aşık çoktan içmiş dünya soruyor 

Kalbin kibir dolmuş arş’a yürüyor 

Yarın benim derdin gün senin değil 

Derdim böyle bitmez aşk kadehinde 

Tenim yokluk bulur ruhum elinde 

Sürüklenir canım varlık selinde 

Umman benim derdin sal senin değil 

Mutluluk rüzgarın gökte eserken 

Darılmış kaderin aşka küserken 

Gün olur eğlenip Mecnun yaşarken 

Aşık benim derdin aşk senin değil', 'Sabır eyle gönül dost bahçesinde  Bülbül benim derdin gül senin değil  Gezme bir gün olsun bağın üstünde  Yolcu benim derdin yol senin değil...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senin-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevip de ölmek', 'sevip-de-olmek-ozgur-sirius-scsk1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yeminler etmiştim kendi kendime 

Nasibim olursa bir kere gülmek 

Versinler dertleri garip gönlüme 

Benim tek korktuğum sevip de ölmek 

Gelişin bir veda rüzgarı sanki 

Gidişin cehennem koru inan ki 

Bilirim dünyayı öyle yalan ki 

Benim tek korktuğum sevip de ölmek 

Varlığım elinde yokluğu buldu 

Önüme ne yüce dağlar kuruldu 

Günahım sevmekti sevap soruldu 

Benim tek korktuğum sevip de ölmek 

Özgürüm yaklaştın yolun sonuna 

Ayrılık damgası vurdun koluna 

Zamansız şirinler çıksa yoluna 

Benim tek korktuğum sevip de ölmek', 'Yeminler etmiştim kendi kendime  Nasibim olursa bir kere gülmek  Versinler dertleri garip gönlüme  Benim tek korktuğum sevip de ölmek  Geliş...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevip-de-olmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varlığın yeter', 'varligin-yeter-ozgur-sirius-bid5k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gün gelip gönlümden uzağa gitsen 

Üzülmem sevgilim varlığın yeter 

Canıma kastedip beddua etsen 

Darılmam tek senin varlığın yeter 

Varlığım sevgiden hakkın kuluyum 

Sevip de sevilmez garip yoluyum 

Bak bana aşkından artık ölüyüm 

Yazılmam mehtaba varlığın yeter 

Kimliğim gerçeğe uymaz bilirim 

Sarhoşum gönlümde aymaz bilirim 

Sevenler ismimi saymaz bilirim 

Sevilmem dünyada varlığın yeter 

Güllerim açıyor bak gülmesen de 

Sabahı bekledim dün gelmesen de 

Sevdiğin gidiyor sen bilmesen de 

Sezilmem sevgilim varlığın yeter', 'Gün gelip gönlümden uzağa gitsen  Üzülmem sevgilim varlığın yeter  Canıma kastedip beddua etsen  Darılmam tek senin varlığın yeter  Varlığım...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/varligin-yeter-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyleyemedim', 'soyleyemedim-ozgur-sirius-demr1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Umutla gelmiştim yanına önce 

Kalbimle sevgimi söyleyemedim 

Derdimi hor görüp sonra gülünce 

Utandım aşkımı söyleyemedim 

Seversen ağlarsın demiştin oldu 

Yalnızlık gözyaşı gönlüme doldu 

Bahçeler hüzünlü çiçekler soldu 

Bir güle ömrümü söyleyemedim 

Zamanım azaldı ömrüm bitiyor 

Varlığın kalbime sanma yetiyor 

Bülbüller lâl olmuş güller ötüyor 

Ben sana gönlümü söyleyemedim 

Özgürüm yakınma aşkın büyüktür 

Sarhoşum sevginle gönlüm ayıktır 

Bilmiyor sevgimi boynum eğiktir 

Gücenme sevdiğim söyleyemedim', 'Umutla gelmiştim yanına önce  Kalbimle sevgimi söyleyemedim  Derdimi hor görüp sonra gülünce  Utandım aşkımı söyleyemedim  Seversen ağlarsın...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/soyleyemedim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevseydin beni', 'sevseydin-beni-ozgur-sirius-67k50', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zamansız sevişim günahmı söyle 

Derdimle yanardım sevseydin beni 

Ne olur uzakta durmasan öyle 

Gönlüne dolardım sevseydin beni 

Söylerim diyordum belkide bir gün 

Yasaklar dünyası gönlüme sürgün 

Bırakıp gittiğin kalbime kırgın 

Aşkımla bakardım sevseydin beni 

Kavuşmak hayalim sevilmek rüyam 

Sarhoşum aşkınla ben nasıl ayam 

Dua et ardımdan sesini duyam 

Melekle ağlardım sevseydin beni 

Varlığım elinde pamuk ipliği 

Halatlar kıskanır sevseydin beni 

Bilinmez Özgürün kimi sevdiği 

Söylerdim aşkımı sevseydin beni', 'Zamansız sevişim günahmı söyle  Derdimle yanardım sevseydin beni  Ne olur uzakta durmasan öyle  Gönlüne dolardım sevseydin beni  Söylerim di...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevseydin-beni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönmeyeceksin', 'donmeyeceksin-ozgur-sirius-flc1c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu aşkın sonunda unut diyorsun 

Kararı vermişsin sevmeyeceksin 

Usulca kalbimden bak gidiyorsun 

Anladım sevgilim dönmeyeceksin 

Bilirsin aşkımı ölsem gam yemem 

Ağlamak kaderim belki gülemem 

Sıkarım dişimi sana sev demem 

İstesem kalbini vermeyeceksin 

Muradım var ise aşkın elinden 

Damlaya muhtacım sevgi selinden 

Duysan da derdimi elin dilinden 

İnan ki sevgilim gülmeyeceksin 

Dokunma kalbime aşkınla yansın 

Bülbüller Özgürce adımı ansın 

Ölsem de mezarım şimdi kapansın 

Ne yazık aşkımı görmeyeceksin', 'Bu aşkın sonunda unut diyorsun  Kararı vermişsin sevmeyeceksin  Usulca kalbimden bak gidiyorsun  Anladım sevgilim dönmeyeceksin  Bilirsin aş...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/donmeyeceksin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlhamlarımı Güneşe Verdim', 'i-lhamlarimi-gunese-verdim-necmi-unsal-yljfs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Okunup da boşalan bu şiir kadehleri,

İmgeden mısra mısra  mana sarhoşluğumdur.

Sevdalara koşan bu atların deeeh  dehleri

Telaşlı arzulardan  dipsiz bir boşluğumdur.

Bakma bu sarhoşluktan serkeş yığılışıma! 

Köhne gemileri hep  birden ateşe verdim.

Aldanma her gün  şiir şiir  sağılışıma! 

İlhamlarımı  dünya  için güneşe verdim.

27 Nisan 2004 Salı, Danimarka-Køge 21.45

7+7', 'Okunup da boşalan bu şiir kadehleri, İmgeden mısra mısra  mana sarhoşluğumdur. Sevdalara koşan bu atların deeeh  dehleri Telaşlı arzulardan ...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ilhamlarimi-gunese-verdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanca yaşadım...', 'i-nsanca-yasadim-yusuf-ziya-leblebici-1ndhw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kimi zaman üç beş haneli köylerde

pınar başında ıslık çalan,

gazlambalı, kerpiçli evlerde

bulgura kaşık sallayan

     bir çobandım ben

     Anadolu''nun nefesinde...

Poyrazların ıslıklarına

kavalımla eşlik ederken,

koyunlar tempo tutardı oynaşarak.

Dağların adına, gırtlağımı yırtarcasına

uzun havalarda gezerken

     ormanlar ağlardı

     gözyaşlarına boğularak...

Bir kurttum ben; 

Yufka ekmeğinin arasında

soğanı bal eylerken.

Bağlardaki ağaçlarda

kanatsız bir teyyareyken...

Bir ekin tanesiydim,

     harmanlarda savrulan.

Çeltik destesiydim,

     ırmaklarla sulanan.

Bozkırlara alabildiğine uzanan

     ceylandım ben

     gençliğimi koşturan...

Kuş oldum, çiçek oldum, dağ oldum

Ben bozkırların çocuğu

ben ırmakların torunu.

Ben insanca yürüdüm

bu uzun

   ve de doğru yolu...', 'Kimi zaman üç beş haneli köylerde pınar başında ıslık çalan, gazlambalı, kerpiçli evlerde bulgura kaşık sallayan      bir çobandım ben      ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/insanca-yasadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerede', 'nerede-ozgur-sirius-gazkj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Değiştin sevgilim neden bilemem 

Gönlüme sığmayan aşkın nerede? 

Alıştım dertlere şimdi gülemem 

Şu seven kalbime bakın nerede? 

Belki de bu aşkın kaderi budur 

Sevgimi öğrensin dileğim odur 

Geçtiğim çilekeş garip yoludur 

Bu yolda yalnızım seven nerede? 

Açmadan soluyor gonca güllerim 

Sevgiye muhtacım seni özlerim 

Gönlünü arıyor bomboş ellerim 

Aşkımla girdiğim kalbin nerede? 

Çekilmez nazına nasıl dayandım 

Bir rüya yaşadım şimdi uyandım 

Dünyada böylesi boşuna yandım 

Özgüre verdiğin gönlün nerede?', 'Değiştin sevgilim neden bilemem  Gönlüme sığmayan aşkın nerede?  Alıştım dertlere şimdi gülemem  Şu seven kalbime bakın nerede?  Belki de bu...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nerede-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şovalye...', 'sovalye-yusuf-ziya-leblebici-vqtym', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen eşek üstünde bir şovalye,

bense bir karıncayım 

bir devenin hörgücünde.

İster mızrak at, ister kılıç salla

vuramazsın, göremezsin beni

bense, bir bir çizerim senin portreni...

İster Don Kişot''u çağır yardıma

ister Nasrettin Hoca''yı! 

Ben, ne değirmeni düşman sayar

ne de gölde maya çalarım.

Ne eşeğe bile yukardan bakar

ne de ağaçta balık tutarım...

Köşe olsan da köşe başlarında

aş pişirsen de birilerinin yağcılığında

evinde, caddede, aynalarda

bir halk olurum, çıkarım karşına...

Eğer ki, insanlığa soyunursan

kendini satmayıp yeşil dolarlara

seninle hasta, seninle savaşta

ben olurum, biz oluruz

hemen yanında, yanıbaşında...', 'Sen eşek üstünde bir şovalye, bense bir karıncayım  bir devenin hörgücünde. İster mızrak at, ister kılıç salla vuramazsın, göremezsin beni b...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sovalye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzle beni...', 'i-zle-beni-yusuf-ziya-leblebici-el405', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İSahilleri bir bir adımlayarak

bu gece yarısı beni izle.

Dalgalara bak 

benim berraklığımda

izle gölgeleşen gemileri.

Uzat ellerini

alabildiğince ıraklara

orada kendini göreceksin.

İşte bak

tam karşında

kendi kendini izleyen

birini hissedeceksin.

Bu gece yarısı izle beni

iyi bak gözlerime

daha neler göreceksin.', 'İSahilleri bir bir adımlayarak bu gece yarısı beni izle. Dalgalara bak  benim berraklığımda izle gölgeleşen gemileri. Uzat ellerini alabildi...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/izle-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazlı kız', 'nazli-kiz-ozgur-sirius-if6v0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dertlerim elinden düştü düşecek 

Hor görüp aşkımı sevin nazlı kız 

Bedenim canımdan göçtü göçecek 

Marifet bilip de övün nazlı kız 

Verecek neyim var sevgiden başka 

Dön artık sevdiğim değer ver aşka 

Ben seni sevmeden ölseydim keşke 

Ağlayıp ardımdan avun nazlı kız 

Uzakta mutlusun demek ki bensiz 

Bahtıma ağlarım sessiz nedensiz 

Bırakıp gitsen de gönlümü sensiz 

Kalbime dönecek yolun nazlı kız 

Sevmezdim böylesi ahir bilseydim 

Teselli bulurdu gönlüm gülseydim 

Sevgimi bir değil bin söyleseydim 

Değişmez sözlerim dilim nazlı kız', 'Dertlerim elinden düştü düşecek  Hor görüp aşkımı sevin nazlı kız  Bedenim canımdan göçtü göçecek  Marifet bilip de övün nazlı kız  Verecek ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nazli-kiz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıkılmış adam...', 'yikilmis-adam-yusuf-ziya-leblebici-mcha8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir adam yıkılıyor

daha doğrusu yıkılmış bir adam.

Sanki delicesine sendeliyor

sarhoşluğundan değil, darbeden.

Kaderine kızıyor, isyan ediyor.

Bu gününe küfrediyor

''ayaktayım'' diyor, daha yıkılmamış

''dünyayı yıkmadan yıkılmam'' diyor...

Nasıl yıkılmamışsın be adam

sevenin seni nasıl da yıkmış

söylesene, oturduğun bankın

neresi senin yattığın odan

Ne zamandan beri ocağın yanmamış

hangi yemeği yapmış bekleyen kadının...

Cebinden çıkardığı bir kaç solmuş resim

kimbilir, kaç yıllık mazisi.

''yıkılmadım'' diyor ama, ben yıkılıyorum.

Tutamıyorum kendimi, gözlerim doluyor

yaşlarımı silerek; 

''topla kendini be adam'' diyorum...

O nasihatları veren ya ben? 

Nasıl da yıkılmıştım birden

nasıl vurulmuştum o şimşeklerden

ne yaralar almıştım şu yüreğimden..

Yıkılan adam o değildi

o adama nasihatları veren ben! 

Kendi yıkılmışlığını saklayan

düşmancasına günlere küfreden

yıkılan bendim, karanlıklarda yaşayan.

Bankları mesken tutan, bendim yıkılmış adam

Kendine nasihatlar çeken

o deli adam bendim! ..', 'Bir adam yıkılıyor daha doğrusu yıkılmış bir adam. Sanki delicesine sendeliyor sarhoşluğundan değil, darbeden. Kaderine kızıyor, isyan ediyo...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yikilmis-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hediyem olsun', 'hediyem-olsun-ozgur-sirius-3mykt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tesellim oluyor belki bilişin 

Gönlümü yakıyor böyle sevişin 

Nedensiz olsa da bu son gelişin 

Bırakıp gidişin hediyem olsun 

Sevgimi yasladım kızgın duvara 

Kalbimi bıraktım azgın sulara 

Varlığın elimde bir dal sigara 

İçtikçe dumanın hediyem olsun 

Madem ki aşkımız bensiz bitecek 

Saatler sevgisiz sensiz geçecek 

Gönlüne başkası ansız girecek 

İzin ver hayalin hediyem olsun 

Sevginle örülüp kalbe serilsem 

Aşkları öldürüp katil görülsem 

Unutma ne olur bir gün ölürsem 

Bir dua edişin hediyem olsun', 'Tesellim oluyor belki bilişin  Gönlümü yakıyor böyle sevişin  Nedensiz olsa da bu son gelişin  Bırakıp gidişin hediyem olsun  Sevgimi yaslad...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hediyem-olsun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmesin dostlar', 'bilmesin-dostlar-ozgur-sirius-sdieu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnızlık yoldaşım aşkın yolunda 

Söyleyin sevdiğim gelmesin dostlar 

Derdimle yaşayıp ölsem uğrunda 

Mutluyum yeter ki bilmesin dostlar 

Varlığım değersiz yâr aleminde 

Kusurdan habersiz dil söyleminde 

Sevgiye güvensiz aşk eyleminde 

Yazılmış kaderim silmesin dostlar 

Kırılmış dalların gonca gülüyüm 

Yakılmış aşkların ince külüyüm 

Varlığım gösteriş sence ölüyüm 

Böylesi yaşamak olmasın dostlar 

Böyleyim aşkımı belli edemem 

Kovsan da kalbimi belki gidemem 

Madem ki kadere rüşvet ödemem 

Bırakın talihim gülmesin dostlar', 'Yalnızlık yoldaşım aşkın yolunda  Söyleyin sevdiğim gelmesin dostlar  Derdimle yaşayıp ölsem uğrunda  Mutluyum yeter ki bilmesin dostlar  Va...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bilmesin-dostlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağdaş kuran sen...', 'bagdas-kuran-sen-yusuf-ziya-leblebici-0os6l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her gece koynuma giren

beni benden eden

uykumu bölen de sen

kabusuma

    bağdaş kuran da sen...

Sen, aynada gördüğüm göz

gırtlağımdan dökülen

    şairimsi söz...

Her nefesimde içime dolan

ciğerlerimde dolanan

bir nefes, bir hava

Bir sen, beni benden çalan...

Sen; 

Ruhumun alabildiğine uzanan

    benim dediğim rüya.

Tel tel baktığım

    bebek kadar temiz papatya.

Bir yağmur,

    bir bulut yukarıda.

Sen; 

    Benim yarımımsın bu dünyada

Sen; 

    Kalkansın, mantığımla

    yüreğimin savaşında....', 'Her gece koynuma giren beni benden eden uykumu bölen de sen kabusuma     bağdaş kuran da sen... Sen, aynada gördüğüm göz gırtlağımdan döküle...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bagdas-kuran-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın ömrü yar elinde', 'askin-omru-yar-elinde-ozgur-sirius-kcc2y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşkın ömrü yar elinde 

Değer vermez öleyim mi 

Derdim çoktur aleminde 

Gözü yaşlı güleyim mi oy..oy.. 

Bu dert beni nur eyledi 

Gönlüm yakıp kül eyledi 

Ferhat,Kerem bir eyledi 

Söyle bende geleyim mi oy..oy.. 

Yunus adım Ferhat sanım 

Aşk yoluna damlar kanım 

Ne bir tarif ne bir tanım 

Yoktur böyle bileyim mi oy..oy.. 

Aşkın ömrü yar elinde 

Bülbül öter gül dilinde 

Zari Özgür dert selinde 

Göz yaşımı sileyim mi oy..oy..', 'Aşkın ömrü yar elinde  Değer vermez öleyim mi  Derdim çoktur aleminde  Gözü yaşlı güleyim mi oy..oy..  Bu dert beni nur eyledi  Gönlüm yakıp...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/askin-omru-yar-elinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağınık dugular', 'daginik-dugular-ozgur-sirius-v1keu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşkınla,Sevginle bin bir parçayım 

Toplama sevgilim dağınık kalsın 

Kaderin elinden nasıl kaçayım 

Götürme aşkını benimle kalsın 

Dağılır nedensiz bazen duygular 

Nefrete dönüşür böyle kaygılar 

Nerede o sevgi aşka saygılar 

Dokunma yüreğim sevgisiz kalsın 

Değişmez yüreğim aşkın eliyle 

Kurumuş yapraklar sevgi seliyle 

Bilsen de gönlümü birlik deliyle 

Sakınma ezelim divane kalsın 

İstemem bu aşkı böyle bir yârsa 

Yorulmam kabrimi ayrılık sarsa 

Sevgilim birazcık gururun varsa 

Koparma güllerim dalında kalsın', 'Aşkınla,Sevginle bin bir parçayım  Toplama sevgilim dağınık kalsın  Kaderin elinden nasıl kaçayım  Götürme aşkını benimle kalsın  Dağılır ne...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/daginik-dugular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git artık', 'git-artik-ozgur-sirius-drucf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Elveda diyecek gücüm kalmadı 

Ne olur ardına bakma git artık 

Saatler vuslatı dönüp bulmadı 

Utanma aşkınla çekip git artık 

Bilirsin aşkımı dağdan yüceydi 

Sevgimi anlatan tekbir heceydi 

Seninle belki de bu son geceydi 

Sabahı bulmadan hadi git artık 

Başkası girmesin diye ömrüme 

Yaşattım aşkını koydum önüme 

Yalandır inanma sakın gönlüme 

Sevgimi anlarsın durma git artık 

Özgürüm burada,gönülde yerin 

Sevgiye muhtacım aşkımı verin 

İşte bak kalbinden gidiyor yarin 

Ağlama kaderim sende git artık', 'Elveda diyecek gücüm kalmadı  Ne olur ardına bakma git artık  Saatler vuslatı dönüp bulmadı  Utanma aşkınla çekip git artık  Bilirsin aşkımı...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/git-artik-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlarım', 'aglarim-ozgur-sirius-vlrjk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gönlüme doluyor o güzel yüzün 

Sarhoşum sevginle içer ağlarım 

Tesellim oluyor verdiğin hüzün 

Sensizim cenneti geçer ağlarım 

İşledim bir kere ben bu günahı 

Bugün de birini ekler ağlarım 

Düşledim seninle geçsin sabahı 

Umutsuz bir aşkı bekler ağlarım 

İstedin kalbine başkası dolsun 

Dileğim dünyada seveni bulsun 

İzin ver ahretim seninle olsun 

Bihaber gönlüne düşer ağlarım 

Sevgimi bırakıp nereye gittin 

Gönlüme hançeri ne diye ittin 

Söyle sen aşkıma bana ne ettin 

Şu garip halime şaşar ağlarım', 'Gönlüme doluyor o güzel yüzün  Sarhoşum sevginle içer ağlarım  Tesellim oluyor verdiğin hüzün  Sensizim cenneti geçer ağlarım  İşledim bir k...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aglarim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilseydin', 'bilseydin-ozgur-sirius-auxzt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Haklısın sevdiğim hata benimdir 

Ağlardın düştüğüm hali bilseydin 

Sevginle kavrulup yanan tenimdir 

Dağlardın ruhumu yara bilseydin 

Sevmeyi öğretip sevme diyorsun 

Aşkımı götürüp gelme diyorsun 

Yaşayan sevgimi yok ediyorsun 

Böyle mi yapardın aşkı bilseydin 

Derdinle tükendi kalmadı sözüm 

Sevginin yolunda olmadı düzüm 

Sen gittin gideli gülmedi yüzüm 

Sulardın kalbimde gülü bilseydin 

Nereye giderim sensiz her yanım 

Görünen halime yoktur bir tanım 

Hasretin aşkıyla bulanmış kanım 

Böylesi sevmezdim seni bilseydim', 'Haklısın sevdiğim hata benimdir  Ağlardın düştüğüm hali bilseydin  Sevginle kavrulup yanan tenimdir  Dağlardın ruhumu yara bilseydin  Sevmey...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bilseydin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemedim ki!', 'bilemedim-ki-ozgur-sirius-08zcn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevmeyi seninle öğrendim inan 

Bu aşkın sonunu bilemedim ki! 

Verdiğin sevgiler anladım yalan 

Gerçeğin yolunu bilemedim ki! 

Anlatmak öyle zor aşka hasreti 

Sus gönlüm kendine alma nefreti 

Sevip de sevgisiz kalmak öğreti 

Ben seni sevmeden bilemedim ki! 

Ferhat’a dağları deldiren neydi 

Yunusa dünyalar sorduran neydi 

Şimdi de bak benim boynumu eğdi 

Aşkına düşmeden bilemedim ki! 

Bülbülün geçmiyor nazı gülüne 

Ağlattın ne geçti bu gün eline 

Güvenip girdiğim zalim kalbine 

Verdiğim kıymeti bilemedin ki', 'Sevmeyi seninle öğrendim inan  Bu aşkın sonunu bilemedim ki!  Verdiğin sevgiler anladım yalan  Gerçeğin yolunu bilemedim ki!  Anlatmak öyle ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bilemedim-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vurma beni', 'vurma-beni-ozgur-sirius-fzwmg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşkımı bırakıp yanıma gel de 

Hasretin yolunda yorma beni 

Kalbine verdiğim değeri bil de 

Yaralı aşkımla vurma beni 

Cezamı çekerim dersimi almam 

Belki bir aşk ile yetinip kalmam 

Günaha girerim aşkınla yanmam 

Kaybedip sevaba sorma beni 

Ayrılık belki tek hediyen bana 

Bitmiyor çektiğim sevgiden yana 

Kadehim,doldurup iç kana kana 

Değersiz taşlara vurma beni 

Sayende bir garip aşığa döndüm 

Kalbimi aşkınla toprağa gömdüm 

Kaderin elinde nasıl da söndüm 

Gönlüme gir öldür durma beni', 'Aşkımı bırakıp yanıma gel de  Hasretin yolunda yorma beni  Kalbine verdiğim değeri bil de  Yaralı aşkımla vurma beni  Cezamı çekerim dersimi...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/vurma-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülmeyen kader', 'gulmeyen-kader-ozgur-sirius-nz930', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gençliğim dert dolu hayatım keder 

Mutluluk sonunda gelsin istemem 

Ferhada,Kereme gülmeyen kader 

Bu aşkın yolunda gülsün istemem 

Sel gibi çağlarım derdi izlerim 

Gizlice ağlarım aşkı gizlerim 

Umutsuz anımda yine özlerim 

Böyleyim sevenler bilsin istemem 

Ne oldu sevgiden aşka döndüm de 

Dertlere alıştım garip gönlümde 

Sevdiğim böylesi varsa ömrümde 

Sensiz bir cenneti kalsın istemem 

Sus gönlüm sus artık seni kim duyar 

Her damla göz yaşı yokluğa kayar 

Verdiği dertleri bilmeyen bir yar 

Gönlümü dermana salsın istemem', 'Gençliğim dert dolu hayatım keder  Mutluluk sonunda gelsin istemem  Ferhada,Kereme gülmeyen kader  Bu aşkın yolunda gülsün istemem  Sel gibi...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gulmeyen-kader-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmam gerek', 'unutmam-gerek-ozgur-sirius-oukrb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Unutmam gerekli çok sevdiğimi 

Seninle yaşayan çarpan kalbimi 

Gönlümde duyguyu ümitlerimi 

Belki de her şeyi (seni)  unutmam gerek 

Bir yerin yok muydu bana ömründe 

Nedir bu çektiğim dertler önünde 

Sevgiye susamış garip gönlümde 

İçtiğim hasreti (seni)  unutmam gerek 

Nerede o sevgi beni bulacak 

Günlümü kurtarıp aşka salacak 

Korkarım yüreğim sensiz kalacak 

Maziyi düşleri (seni)  unutmam gerek 

Ne dersin Özgürüm böyle kadere 

Bir seven bulunur girme kedere 

Dönerse sevdiğim benden betere 

Ettiğim günahı (seni)  unutmam gerek', 'Unutmam gerekli çok sevdiğimi  Seninle yaşayan çarpan kalbimi  Gönlümde duyguyu ümitlerimi  Belki de her şeyi (seni)  unutmam gerek  Bir yer...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/unutmam-gerek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya canımdan Ya gülümden', 'ya-canimdan-ya-gulumden-ozgur-sirius-5wc67', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dertlerin bağrında solmayan gülüm 

Sormadan aşkıma savrulmuş külüm 

Hasretin yolunda kalmış bülbülüm 

Ya canımdan ya gülümden olurum 

Dön desem maziye döner mi söyle 

Hor görme gönlümü derdimi öyle 

Her günün sonunda sevgilim böyle 

Ya canımdan ya gülümden olurum 

Bu kadar kolay mı gönlümü kırmak 

Yakışmaz sevgilim olur mu vurmak 

Tehdittir kalbimle karşında durmak 

Ya canımdan ya gülümden olurum 

Zannetme sevgiye aşka doymuşum 

Sevmeyen gönlüne sanma uymuşum 

Ben senin uğrunda beni koymuşum 

Ya canımdan ya gülümden olurum', 'Dertlerin bağrında solmayan gülüm  Sormadan aşkıma savrulmuş külüm  Hasretin yolunda kalmış bülbülüm  Ya canımdan ya gülümden olurum  Dön de...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ya-canimdan-ya-gulumden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim dünyam', 'benim-dunyam-ozgur-sirius-8up1r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gülmeden kaderim sevemem diyor 

Dertlerin yolunda bu benim dünyam 

Gelmeden sevdiğim dönemem diyor 

Hasretin uğrunda bu benim dünyam 

Gönlüme yokluğun göze yaş doldu 

Diktiğim güllerim bir günde soldu 

Soramam rabbime neden var oldu 

Bir zalim kulunda bu benim dünyam 

Nereden geldin de gönlümü sardın 

Günahsız ömrümden ah ı mı aldın 

Sahte bir dünyada, düşlerde kaldın 

Üzülme sonunda; bu benim dünyam 

Gel Özgür sabreyle marifet budur 

Her bir dert ne ise derman da odur 

Geçtiğin mutluluk aşkın yoludur 

Sevdiğim bak işte bu benim dünyam', 'Gülmeden kaderim sevemem diyor  Dertlerin yolunda bu benim dünyam  Gelmeden sevdiğim dönemem diyor  Hasretin uğrunda bu benim dünyam  Gönlüm...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/benim-dunyam-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırla beni', 'hatirla-beni-ozgur-sirius-9ezmk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çizdiğin ömrüme dertle kedersin 

Girdiğin gönlüme ziyan edersin 

Ardına bakmadan çekip gidersin 

Kırdığın kalbimle hatırla beni 

Seninle yaşayıp seninle ölsem 

Günlünü aşıp da yanına gelsem 

Ne olur aşkınla bir kere gülsem 

Verdiğin derdinle hatırla beni 

Gönlüme hasretin aşkın dalıyor 

Ardımda nefretim derdim kalıyor 

Her gelen kalbimden bir şey alıyor 

Çaldığın sevgimle hatırla beni 

Gözüne değersiz yaşlar dolunca 

Kalbine verdiğim aşklar solunca 

Çekinme sevenler beni sorunca 

Yaktığın gönlümle hatırla beni', 'Çizdiğin ömrüme dertle kedersin  Girdiğin gönlüme ziyan edersin  Ardına bakmadan çekip gidersin  Kırdığın kalbimle hatırla beni  Seninle yaş...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hatirla-beni-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir haber eyle', 'bir-haber-eyle-ozgur-sirius-5kjm0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öldürür sevdiğim beni hasretin 

Nereye gittiysen bir haber eyle 

Güldürür gerçeğe aşka nefretin 

Yalana kattıysan bir haber eyle 

Yazılmış kadere karşı gelemem 

Ağlayan gözlere aşkı seremem 

Yinemi diyorsun seni sevemem 

Gönlümü attıysan bir haber eyle 

Yaşlandı bedenim derdi överken 

Şahlandı kalbimi aşkla döverken 

Ne oldu sen beni böyle severken 

Aşkımı sattıysan bir haber eyle 

Tutsaklık doluydu Özgür yapında 

Dertlerin yoluydu hasret çapında 

Bir aşkın kuluydu gönül kapında 

Mabedim bittiysen bir haber eyle', 'Öldürür sevdiğim beni hasretin  Nereye gittiysen bir haber eyle  Güldürür gerçeğe aşka nefretin  Yalana kattıysan bir haber eyle  Yazılmış k...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-haber-eyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir aşk borcun var', 'bir-ask-borcun-var-ozgur-sirius-oyawn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bıraktın gönlümü yine derdinle 

Çektiğim hasreti beni gel dinle 

Beklemek faydasız zalim elinle 

Kırdığın kalbime bir aşk borcun var 

Kaybettim her şeyi seni bulunca 

Gülerim sanmıştım yarim olunca 

Gönlümde çiçekler güller solunca 

Çaldığın ömrüme bir aşk borcun var 

Bilirsin bu gönül fazla dayanmaz 

Garip bir uykuya dalmış uyanmaz 

Derdine atarken sandın ki yanmaz 

Yaktığın gönlüme bir aşk borcun var 

Bu aşkın yolundan çekil Özgürüm 

Geçmiyor çilesiz dertsiz bir günüm 

Sevgiyle çözülmez garip düğümüm 

Sardığın düğüme bir aşk borcun var', 'Bıraktın gönlümü yine derdinle  Çektiğim hasreti beni gel dinle  Beklemek faydasız zalim elinle  Kırdığın kalbime bir aşk borcun var  Kaybet...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-ask-borcun-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende gel', 'sende-gel-ozgur-sirius-ih1k4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gönül yolunda aşka doğru giderim 

Yalnızım sevdiğim düş peşime sende gel 

Çektiğim dertlerden belki daha beterim 

Şanssızım kaderim gir ömrüme sende gel 

Bu kadar sevinme daha nice dertler var 

Sevgisiz geçipte aşksız biten günler var 

Hasrete sığamam bana karşı kalbin dar 

Sebepsiz beklerim gel yanıma sende gel 

Kırdığın gönüldür insan denen bir canım 

Yaptığın bu zulme yoktur inan bir tanım 

Verdiğin derdinle dolmuş seven her yanım 

Gönlümde saklarım vur gönlüme sende gel 

Mutluluk göz yaşı sensiz göze dolunca 

Herşeyden uzakta bir tek aşkın kalınca 

Unutmam sevgilim gerçek beni alınca 

Sevgisiz kalbinle sar hasreti sende gel', 'Bir gönül yolunda aşka doğru giderim  Yalnızım sevdiğim düş peşime sende gel  Çektiğim dertlerden belki daha beterim  Şanssızım kaderim gir ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sende-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geç kalacaksın', 'gec-kalacaksin-ozgur-sirius-vpmgb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zannetme bu dünya ebedi alem 

Aşkımla ağlıyor kağıt ve kalem 

Şu garip halimi bilirsin madem 

Dön artık sevgilim geç kalacaksın 

Demek ki sevgime ölümdür yargın 

Ne olur gönlüme kalmasan dargın 

Bilseydin her yerim aşkına vurgun 

Korkarım sevgilim geç kalacaksın 

Gönlümü anlamaz,bilemez oldun 

Çağrıma bir cevap veremez oldun 

Ne yazık bugün de gelemez oldun 

Sonunda sevgilim geç kalacaksın 

Dostlarım sevgiyle aşka erdiler 

Mutluluk dünyada sevgi derdiler 

Gönlüme sev diye seni verdiler 

Kaderim sevgilim geç kalacaksın', 'Zannetme bu dünya ebedi alem  Aşkımla ağlıyor kağıt ve kalem  Şu garip halimi bilirsin madem  Dön artık sevgilim geç kalacaksın  Demek ki se...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gec-kalacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Ölü Aşklara...', 'olu-asklara-erdal-asik-rw6jk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'baş kaldırıyor kalemim

hücresinde hapsolmuş

sayfaları parçalarcasına

parça parça aşkı yazıyor

hançer gibi batırıyor

her harfin haznesinde

kelimelere isyankar

dizelerinde tutuklu

müebbet kelimelere

intihar ediyor

idam mahkumu her dörtlükte

gözyaşı yok arkasından ağlayan

aşk mahkumlarına, 

ölü aşklara

bir mezar taşı bile yok....

Not; Ölü aşklar derneğine çam sakızı 

çoban armağanı naçizane bir hediyemdir...', 'baş kaldırıyor kalemim hücresinde hapsolmuş sayfaları parçalarcasına parça parça aşkı yazıyor hançer gibi batırıyor her harfin haznesinde ke...', ARRAY['Türk Edebiyatı','Şiir','Erdal Aşık']::text[], 8.5, '{"poet":"Erdal Aşık","poet_slug":"erdal-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/olu-asklara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-yusuf-ziya-leblebici-hru7q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kafiyelerin konu kavgasında

Harflerdir, bir şiirdir nefes almak

Başkaldırının doruk noktasında

Kalemlerin rotasıdır yaşamak

Taşdevrinden bilgilerin çağına

Bebeğin yürümesidir yarına

İsa''dan bu günün insanlarına

Rahimlerden mezaradır yaşamak

Tarlanda ekininle sevişirken

Gözde canlanır harman savrulurken

Sedirde tahta kurusunu ararken

Tandırdaki çöreğindir yaşamak

Kına gecelerinin havası

Davullarla sarar dört bir yanı

Yaktıkça ellere kızıl kınayı

Gelinin avucundadır yaşamak

Akan alın terini namus bilmek

Kilimi işlemektir ilmek ilkmek

Görevdir emeğine savaş vermek

Yüreğinde ameledir yaşamak

Rahimde yürüyen cenindir doğmak

Bir yanda gülmek, bir yanda ağlamak

Tarlada, fabrikada emek sağmak

Savaşındır insanca yaşamak

Hitler''in kuduran fırınında

Hiroşima''yı yakan atomunda

Mustafa Kemal''in devrim yolunda

Dünümüzdeki tarihtir yaşamak', 'Kafiyelerin konu kavgasında Harflerdir, bir şiirdir nefes almak Başkaldırının doruk noktasında Kalemlerin rotasıdır yaşamak Taşdevrinden bil...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yasamak-95-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sustuğum yer m.ö. 700''ler', 'sustugum-yer-m-o-700-ler-zafer-zengin-etnika-8wrqd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kat kat

Bu ayrılık

Yüksekçe

Sarı yüzler takılmış üstüne

Kaçacak yerler

Bildiriler

İlanlar

Taziyeler

Kat kat

Bu ayrılık

Kaçamadık

Ayrılığı kaçmak sandık

Şehir karanlık

Şehir yağma

Kaçmak kolay değil anla 

Saklanmış adam

Kadın koynuna

Büyüyor

Ellerinden habersiz

Ellerde habersiz

Sarılır sıcak ayrılığa

İçinde yanlış anlamalarla..çıkılmış yola..hesap kesilir hep aşka |||

Ateş doğasında anla

Prometeus bu

Vurma  topuğuna

Koparma

Koparma

Kat kat

Bu grilik

İçinde gezindik

Gülmedik

Umut dolu o gözleri

Sen diye sevdik

Kırmızı yanımızı gösterdik

Grileri bildirmedik

Punto punto dil..siyah baskılar..ayrılıklar..ağlamalar |||

Nereye gittin ses

Sustuğum yer zaman

Uzak dayan dayan

M.Ö.700 dolayları..burada kimse kimseyi tanımazdı.

Herkesin anlayacağı tarih yoktu..bu yüzden atmadık.', 'Kat kat Bu ayrılık Yüksekçe Sarı yüzler takılmış üstüne Kaçacak yerler Bildiriler İlanlar Taziyeler Kat kat Bu ayrılık Kaçamadık Ayrılığı ka...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/sustugum-yer-m-o-700-ler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyam, Duygularım ve Ben - 17', 'dunyam-duygularim-ve-ben-17-ozden-cakmak-69282', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yağmur yağıyor karanlıklardan,

Solgun sensiz yaprakların üzerine.

Ben, işte o yapraklarda gizliyim,

Sense düşen her bir damlada.

Hatırlıyormusun yeşil bir Nisan''dı,

Sessizce düştün gönlüme.

Seninle yaşamak güzeldi,

Sevgin vardı sevgimde

O güzel günlerde seni aradım hep sende,

Gülen dudaklarına saklanmıştın belkide.

Ama hayır, sen benim içimdeydin

Unutamadığım kokun ve her şeyinle.

Kırmızı bir Temmuz gününde,

Sen, sesizsce uçtun gönlümden.

Ben,sensiz bir yaprak, sen, damla olduğun sürece

Yemin ediyorum, hep kalbimde kalıcaksın ve içimde bir ukte..', 'Yağmur yağıyor karanlıklardan, Solgun sensiz yaprakların üzerine. Ben, işte o yapraklarda gizliyim, Sense düşen her bir damlada. Hatırlıyorm...', ARRAY['Türk Edebiyatı','Şiir','Özden Çakmak']::text[], 8.5, '{"poet":"Özden Çakmak","poet_slug":"ozden-cakmak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dunyam-duygularim-ve-ben-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Geçen Bir Yıl..', 'sensiz-gecen-bir-yil-adem-tetik-psjf0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şimdi mevsimlerden hazan

Aylardan boran bu gönülde

Günler geceler hep aynı zifiri karanlık

Ve ben sensiz gecen bir yılın ardından 

Yalnızlığın pençesinde can çekişmekteyim

Artık gel diyemiyorum 

Üzülmüyorum sensiz geçen zamana

Biliyorum ki ne yapsamda artık gelmeyeceksin 

Olamayan mutluluklarımı sana bıraktım

Bu diyardan ebediyen gidişinin yıl dönümde

Hazanların ve boranların yamacında

Yalnızlığın kollarında  uğurladım

Sensiz geçen bir yılı bin yıl ederek yalnızlığın kollarında

     *** Ölümünün yıl dönümünde Rahmetle andığım Sevgili  arkadaşım  kardeşim Orhan TURCAN için yazılmıştır... ***

      20 / 07 / 2004

         02:38', 'Şimdi mevsimlerden hazan Aylardan boran bu gönülde Günler geceler hep aynı zifiri karanlık Ve ben sensiz gecen bir yılın ardından  Yalnızlığ...', ARRAY['Türk Edebiyatı','Şiir','Adem Tetik']::text[], 8.5, '{"poet":"Adem Tetik","poet_slug":"adem-tetik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sensiz-gecen-bir-yil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgara Karşı Aşk Şarkıları', 'ruzgara-karsi-ask-sarkilari-orcun-oruc-aykac-h8fto', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zarif bir özneden yoksun 

Bir cümle düşmüş şairin biçare diline

Hani ne söylesen 

Eksik bir şey var söylenecek sözlerden öte

Unut şimdiden diyor rüzgar

Aklına gelecek sevda sözlerini

Ne senden bahseder masallar, ne de benden

Kaybettiğinde bulursun ancak şarkıların öznelerini.', 'Zarif bir özneden yoksun  Bir cümle düşmüş şairin biçare diline Hani ne söylesen  Eksik bir şey var söylenecek sözlerden öte Unut şimdiden d...', ARRAY['Türk Edebiyatı','Şiir','Orçun Oruç Aykaç']::text[], 8.5, '{"poet":"Orçun Oruç Aykaç","poet_slug":"orcun-oruc-aykac","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ruzgara-karsi-ask-sarkilari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Janda', 'janda-omer-demir-d50vc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Janda! ... 

Dengê şevê bi ser min de tê; 

Xew diçe ji welatê min. 

Li ber pencereyê tava heyvê, 

Hêdî hêdî xwe davêje oda min. 

Û hingê; 

Hingê ji nav birka bîrhatinan, 

Tu dikevî ser pêlan, 

Û diherikî li nava hestên min. 

Janda! ... 

Bê te me vê şeva lal; 

Li ser zimanê min du peyvên tal, 

Ji çavên min du fêrmiskên zelal, 

Û dilekî westiyayî pîr û kal; 

Te dipê, te dipê Janda! ... 

Janda! ... 

Li ber guhê min pêjna te; 

Ji nediyariyekê vedigeze. 

Awirên te zindî dibin, 

Dinya min pê diheje. 

Janda! ... 

Tu dibihîzî! ... 

Min gelek bêriya te kiriye. 

Bêriya çavên te, 

Dengê te, 

Pêjna te, 

Bejna te, 

Xemla te, 

Ravêja te, 

Û te; te Janda! ... 

Janda! ... 

Biharê bêhnên xwe ji te dizî ne; 

Sosin, 

Alal, 

Beybûn, 

Binevş, 

Nêrgiz; tev ji te afirî ne. 

Avzen ji zelaliya çavên te hiltavêjin 

Kaniya jiyanê yî tu! ... 

Kaniya jiyana min! ... 

Janda! ... 

Jehrkuşa koremarên sedsalê yî, 

Jankuja dilê min ê kovandar î, 

Dilopek ji derya evînê yî, 

Bijûn û paqij... 

Zelal û şirîn! ... 

Janda! ... 

Şev e; şev diqulipe hêdî hêdî. 

Hingorê tarîsanê dadikeve êdî 

Xew dikeve rehên mirovên vî şarî; 

Lê ez, 

Ez çavrêyî te, 

Li ber pencereyê, 

Di nava efsûna heyvtavê de; 

Riya te dipêm! ... 

Riya te Janda! ... 

Janda! ... 

Sal çûn; 

Demsalan rengê xwe avêtin, 

Biharan xwe gihand payizan, 

Salmane hatin guhartin; 

Dinya guherî, 

Xwerist guherî, 

Heyam guherî... 

Şer çû, 

Dijwarî bidawî bû 

Li şûna bêhna barûtê, 

Gul û kulîlk bişkiftin... 

Dijmin bûn dost, 

Hewa şikest, 

Tahlî ma bêpişt... 

Maran koç kir. 

Dûpişkan bi jehra xwe ve xwe kuşt. 

Bes, tu... 

Tu nediyar î hê jî, 

Tu Janda! ... 

Janda! ... 

Berfa spî lêkir, 

Çiya vehûnandin; 

Newal rast kirin, 

Aşût û renî hatin. 

Tavê lêda; 

Germ bû, 

Berf heliya. 

Çiya û berdol şîn bûn; 

Canemergan cih guhast, 

Panav têrxwer bûn; 

Pez lê çêrî, 

Dewar lê beziyan, 

Golik lê boriyan... 

Janda! ... 

Qedexe çiriyan... 

Dîsa bêrîvanan berê xwe da zozanan, 

Li wir kon vegirtin. 

Careke din newalan deng veda, 

Ji dengê bilûra zîz a şivanan. 

Meşk helawîstin, 

Mast kiya; 

Nîvişk bi ser ket, 

Kire penîr û lorik; 

Dagirtin tijî pîsk û telîskan. 

Bes... 

Bes tu venegeriya, 

Venegeriya ji wexerê! ... 

Janda! ... 

Careke din heyvtava kewçerê dibiriqe, 

Leylan dide ser pêlên çemên welatê me; 

Ferat û Dîcle, Xabûr û Zê... 

Careke din di kamla xwe de ne ew, 

Bêdeng, 

Bêpêjn, 

Bê hebûna te diherikin. 

Diherikin ligel mezinbûna hesreta dilê min; 

Diherikin ber bi deryayekê ve, 

Ber bi zeryayekê ve... 

Janda! ... 

Rê û dirb dûr in; 

Bi kend û bend in, 

Asê ne; 

Û pêlên wan rûbaran dialîsin tahtikan, 

Bi sebreke Eyûbî, 

Dimêjin dilê wan ê hişkeber. 

Ji bo ku lê vebibe rê, 

Lê biherike verêj, 

Û geş bibin gul û kulîlkên rengîn. 

Janda! ... 

Heyvtava rengiz; 

Li ber pencereyê, 

Di giraniya xeweke reviyayî de; 

Dipêçe hişê min, 

Vedigire dilê min, 

Dikole sînga min; 

Û pêl bi pêl diweşe ser min! ... 

Janda! ... 

Bi navê Xwedê! ... 

Bi sûnda mezin; 

Bi serê te yê nazdar, 

Bi wan herdu çavên qendîl, 

Bi wî dilê tijî evîn! ... 

Sûnd bi navê xudanê mirazan! ... 

Min gelek bêriya te kiriye! 

Min gelek hesreta te kişandiye! 

Hesreta wan herdu çavên te yên belek; 

Bejna narîn, 

Bişirîna şirîn, 

Rawesta melûl, 

Meşa mexrûr, 

Bêhna porê te yê bêhn-çiyayî; 

Ango te.. 

Te Janda! ... 

De were êdî, bes e! ... 

Bes helişkivîne vî dilî, 

Bes kûr bike birînên min! ... 

Kengî be ne dereng e; 

Tenê hema tu were! ... 

Janda! ... 

Heyv, 

Tîrêj, 

Hewa, 

Payîz, 

Û tu! ... 

Bêdengî, 

Tenêtî, 

Xerîbî, 

Hesret, 

Û tu Janda! ... 

Tu Janda! ... 

Evîna min ya şermoke, 

Kula min a delodîn! ... 

Ew gotina biefsûn; 

Ewa ji her tiştî bêtir min dixwest ji te re vegota, 

Aniha, va ye diqêrînim 

Û direşînim ser bêdengiya şevê: 

''Ma tênegihîştî hêj? '' 

''Min tu divêyî Janda! '' 

2002-09-15', 'Janda! ...  Dengê şevê bi ser min de tê;  Xew diçe ji welatê min.  Li ber pencereyê tava heyvê,  Hêdî hêdî xwe davêje oda min.  Û hingê;  Hi...', ARRAY['Türk Edebiyatı','Şiir','Ömer Demir']::text[], 8.5, '{"poet":"Ömer Demir","poet_slug":"omer-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":176,"source_url":"https://www.antoloji.com/janda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neresinden tutulur ki yalnızlığın?', 'neresinden-tutulur-ki-yalnizligin-omer-demir-81ikm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Deprem korkusu gibi 

Hani gece yarısı ansızın çökünce üstüne 

Bir telaş, 

Bir çaresizlik, 

Bir korku, 

Ve bir kaçışma başlar sağa sola 

Kaybolursun 

Neye sarılacağını bilmezsin 

İşte o zaman yalnızsız 

Söyle bana, 

Allah aşkına söyle, 

“Neresinden tutulur ki yalnızlığın? ” 

Ateş gibidir o 

Alev alev sarar seni 

Yakar içten içe 

Kemirir, 

Eritir, 

Küle dönüştürtür, 

Ve rüzgarlara savurur seni. 

Ölüm gibidir yalnızlık 

Neresinden tutulur ki ölümün 

Bitişidir o her şeyin 

Sonudur yani hayallerinin 

Neresinden tutulur ki bitişin…? 

Ansızın çöker üstüne 

Bir çığ gibi 

Ve kırar bellini 

Şimdi söyle 

Allah aşkına söyle, 

“Neresinden tutulur ki yalnızlığın? ” 

Neyi anlatsam ki, 

Nereden başlasam ki anlatmaya 

Hangi yarayı, 

Hangi yarayı deşsem ki? 

Kime, 

Kimlere, 

Neler anlatsam ki, 

Neresinden tutsam ki yalnızlığın? 

Neresinden…. 

Bu öyle bir acı ki, 

Hani yaşamda tutunacak dalın kalmadığında 

Her şey… 

Ama her şey tadını yitirdiğinde 

Seni yaşamdan biraz daha kopardığında 

İnancını, 

Yaşama sevincini, 

İrsi bağlarını, 

Dostluk hissini, 

Aitlik duygusunu, 

Yani özgüvenini, 

Ve nihayet içindeki “o gizemli kendini” kaybettiğinde 

Kime nereye gideceksin ki? 

Neye tutunacaksın ki… 

Söyle, 

Allah aşkına söyle, 

“Neresinden tutulur ki yalnızlığın? ” 

Kangren gibidir o 

İçten içe kemirir, 

Ve bulaşır her damarına 

Eritir içten farkına bile varmazsın 

Elini versen ona 

Yüreğini alır senden 

…….. 

Anlıyor musun, 

Anlayabiliyor musun? 

Şimdi söyle, 

Allah aşkına söyle, 

“Neresinden tutulur ki yalnızlığın? ” 

Tutulmuyor ki…. 

Tutunmuyor ki yalnızlığa 

Ateş gibidir o 

Yakar seni içten içe 

Farkına bile varmazsın…. 

2004-07-19', 'Deprem korkusu gibi  Hani gece yarısı ansızın çökünce üstüne  Bir telaş,  Bir çaresizlik,  Bir korku,  Ve bir kaçışma başlar sağa sola  Kayb...', ARRAY['Türk Edebiyatı','Şiir','Ömer Demir']::text[], 8.5, '{"poet":"Ömer Demir","poet_slug":"omer-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":74,"source_url":"https://www.antoloji.com/neresinden-tutulur-ki-yalnizligin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dêdem', 'd-dem-omer-demir-0l1vn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1 

Dêdem, dîdem ma tu bêzar nebûyî ji payîna deman! 

Istirî bi şûna wuslatê dikevin riya te, li her fetlokan 

Li xwe binêr; hişyar be û bihêle vê rojiya bêzeman; 

Şîv û paşîva te, ma dê her tim bibe ew jana bi kovan? 

Ax û fîxan ma dê tim li derdora te biçerxînin perwazan? 

De bişkêne vê rojiya giran; ne Beraet e, ne jî Remezan! 

Dêdem, êdî vehêle vê sûnda rikîn, vê asoya bêsînor! 

Wekî bilbilê tûxwer gêj û mendehûş digerî li derdor 

Ev çi rojiya bêwerz e, ku berê te dide riyeke kendekûr? 

Dil li ser kaniyên sar re dibore bê ku qurçekê bidaûr! 

Çav ji bendemaniyan westiyan, rijiya tev fer û nûr 

Bila cejna dil bêtin; bi dûmahîk bêt, disoje ev tenûr! 

2 

Şêrekî qefeskirî ye ev dilê birîndar 

Umreke sax lê borî her daxîdar 

Ken mişext bû, rondik hatin xwar 

Roj û şêvê bê navber her hêvîdar 

Ariya dil her gur bû, ma bê hawar 

Nema tu hatî ser vî dilê tar û mar! ... 

& 

Dilê birîndar her bi dax û janan gevizî 

Inta evînê vegirt û gurçik pê derizî 

Lêvan ken ji bîr kir, rondik her dilîzî 

Ser rûyê şikestî tên xwar û her direqisî 

Ofên û axîn ji zimên tên bi merezî 

Zû were dêdem ev dil bi eşqa te rizî! ...', '1  Dêdem, dîdem ma tu bêzar nebûyî ji payîna deman!  Istirî bi şûna wuslatê dikevin riya te, li her fetlokan  Li xwe binêr; hişyar be û bihê...', ARRAY['Türk Edebiyatı','Şiir','Ömer Demir']::text[], 8.5, '{"poet":"Ömer Demir","poet_slug":"omer-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/dedem-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Piştî Te', 'pist-te-omer-demir-epm6m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Piştî te, 

Gotinên min miçiqîn, 

Sohbetan tama xwe winda kir. 

Êdî ez nema çûm ber awêneyê, 

Nema kenî nava çavên min 

Êdî min kelecan ji bîr kir. 

Xweşî ji dest da, 

Bêdengiyeke mirinî kete ser min. 

Êdî min dilê xwe jêvekir 

Avêt ber derî 

Lanet bi qederê kir 

Bi her du çavan kire girî 

Ez bûm serhildêrek hesthar 

Min her tişt şikand, 

Ji hev xist 

Û bê serûber kir. 

Piştî te, 

Kaniya hestên min ziwa bû 

Pênûsa min şikest, 

Dilê min herişî 

Xewnên min li nav hev ketin 

Xeyalên min koç kir 

Xweziyên min çilmisîn 

Ez req bûm, 

Hişk bûm. 

Û min dilê xwe jêvekir 

Avêt ber derî 

Da ku herkes pêpes bike! 

Ma dilekî bê te min ji bo çi ye? ! 

Min lanet li wê rojê kir; 

Roja ku tu çûyî... 

Na na! 

Roja ku ez hatime dinyayê 

Min nifir reşandin 

Kerb vereşand 

Û dijûn li xwe barandin. 

Piştî te, 

Çûçikên dilê min firiyan 

Pelên dargulê weriyan 

Di nava min de 

Valahiyeke bêbinî despêkir 

Ez tirsiyam 

bo halê xwe 

min kire girî 

Ez mame bi tenê; 

Bi tena serê xwe 

Bê hêvî, 

Bê evîn, 

Bê xwezî... 

Û min dilê xwe jêvekir 

Avêt ber derî 

Da ku ez te ranebihîzim 

Jana te seh nekim 

di nava dilê xwe de. 

Wekî zarokê ji şîrî vekirî 

Na na, 

Wekî berxikê bizmêkkirî 

Bi dû serê xwe 

Li der û kolanan ketim 

Ji tiştî, 

Ji her kesê 

Min tu pirs kirî 

Lewma piştî te 

Min dilê xwe jêvekir 

Avête ser çopdankan 

Û ber sêdara çavên te 

Min dilê xwe li dar vekir 

2003-09-17', 'Piştî te,  Gotinên min miçiqîn,  Sohbetan tama xwe winda kir.  Êdî ez nema çûm ber awêneyê,  Nema kenî nava çavên min  Êdî min kelecan ji bî...', ARRAY['Türk Edebiyatı','Şiir','Ömer Demir']::text[], 8.5, '{"poet":"Ömer Demir","poet_slug":"omer-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/pisti-te-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İğne Ne?', 'i-gne-ne-olgun-keskin-smf9x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aynalardan yansıyan gündüze inat

Karanlığa gömülen ısrarlı gözlerde var

Korkuluğa sığınmış kargadan rest

Korkuya, ona-buna şuna inat

Kudurmuş duyguların gündönümüdür bugün

Sonbahar yaprağı üstüne düşmüş umut

.. ve onunla sararıp toprağa dokunan sancı

Tutup rüzgarın elinden rotasız uçan bir rüya

Ölü sularından yapılmış kurabiye arzusu

Ruhunu tadından çalma komplosu

Ötesinde çabasız bir ölüme kavuşma sanki

Yükümü bilenmeyene satayım bari 

dedi.

Samanlığa atılmış bir iğne sankî

Adını bilmeden aranıp durmuş bir deli

Yüzüne bakmaya indiğinde dibe

Aklına gelmiş iğne 

Dalmış karanlığa

                          sormuş

 iğne ne?', 'Aynalardan yansıyan gündüze inat Karanlığa gömülen ısrarlı gözlerde var Korkuluğa sığınmış kargadan rest Korkuya, ona-buna şuna inat Kudurmu...', ARRAY['Türk Edebiyatı','Şiir','Olgun Keskin']::text[], 8.5, '{"poet":"Olgun Keskin","poet_slug":"olgun-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/igne-ne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şilêr', 'sil-r-omer-demir-jywkh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'şilêr, 

tu ji bo çi serê xwe nixwîn dikî 

qey tu digrî şilêr… 

qey tu birîndarî, 

an evîndar…? 

bibêje şilêr 

ji bo çi stûyê te daketiye 

li pala te şikêr 

beramberî te belekî ye 

te çî ye şilêr 

ji bo çi rûyê te şil bûye 

ji bo çi şilêr 

derdê te çî ye…? 

şilêr 

piştî ku min tu dîtî 

ez bi rojekê hezar salan jiyam 

hezar caran mirim 

piştî her mirinekê bi rondikên te 

hezar caran vejiyam 

hezar caran şilêr… 

şilêr 

êvar e li çiyan 

ewran xwe daye ber rojê 

ji kûratiya newalan 

deng vedide dengê dengbêjekî 

sîber daketine xwarê 

teyr difirin ber bi asîmanan 

tu nabînî 

lê nanihêrî şilêr 

qey tu xeyidî ji me 

qey tu dilmayî şilêr 

tu ji bo çi sernexwînî şilêr 

ka bibêje te şerma kê bar kiriye 

te raza kê pişt kiriye 

te dilê kê veşartiye 

te xwîna kê hewandiye 

tu zêmara kê dikî 

şîna kîjan terotolî digerînî 

te dengê xwe li ku berze kiriye 

di nalîna kîjan dayîkê de 

di awaza kîjan dengbêjî de 

di girîna kîjan zarokî de 

tu şerma kê dikî şilêr 

kê….? 

şilêr 

hezar dilên min te ji min dizîn 

hezar caran te ez çal kirim 

li nava axê 

li beyareke çiya 

li bereheke şikêran 

di nava xwîdana şermê de 

gotinên min li ser zimanê min hişk bûn 

şilêr 

guhdariya çîroka min bike 

ez ji bo te dibêjim ha, 

hezar gotinên xwe yên zîz 

yên di sîtavka spêdeyekê de 

li ber bayê felekê baligî ne 

ez li nava xunava te dihêwirim 

riyên min girtî ne 

evîna min ji min dizî ne 

dizî ne şilêr… 

de serê xwe rake şilêr 

li nav çavên min bimêzîne 

şilêr 

ji axa tu li ser şînhatî 

pêjnên têvel tên ber guhê min 

nalîn, 

qêrîn, 

qîjîn, 

gazî 

hemû pêkve olan didin 

ev çi ye şilêr 

qey tu li wan dengan dinêrî 

ew dengên li pêş çavên te 

di sînga axê de çal kirine 

qey tu jî şahidê wan rojan î 

wan…. 

rojan… 

şilêr… 

şilêr 

ji ser rûyê te xwîn diniqute 

xwîn û av 

tîna janekê kel vedide 

kel û jan 

rondik têne xwarê 

kel û girîn 

lê şilêr 

min gelekî mereq kiriye 

ka kena te çawaye 

bişîrîneke sivik dê çend li te bê 

ez nizanim şilêr 

ez ninazim çi û çi ne razên te 

xemên te, 

keyfên te, 

henekên te…? 

tu cîhaneke cudayî şilêr 

di rojekê de hezar salan dijî 

di şevekê de hezar tofanan radikî 

di mistekê de deryayan 

oqyanûsan dihewînî şilêr 

şilêr 

êvar e, şev sar dibe 

her kes diçe 

xwe dispêre hêlîna xwe 

berxik vedigerin ber makê 

teyr xwe dadidin ser lîsên xwe 

mirov dinişin nav şaristaniyê 

masî xwe davêjin nav pêlan 

kêzik bi axê şa dibin 

……… 

û ez û tu şilêr 

em bi tenê dimînin 

li qontara çiyayeke jibîrbûyî 

li nav rûpelên dîroka nezayî 

li ser axeke nekêlayî 

xav, 

xwas, 

û damayî 

şilêr 

êdî tu dikarî serê xwe rakî 

ji bilî min kes nemaye li vir 

qey tu xwe ji min jî vedişêrî 

na şilêr na, 

jixwe em ji rayên hev dertên 

ji dilê axê 

ji kopê hêviyan şilêr! 

2003-12-26/ Amed', 'şilêr,  tu ji bo çi serê xwe nixwîn dikî  qey tu digrî şilêr…  qey tu birîndarî,  an evîndar…?  bibêje şilêr  ji bo çi stûyê te daketiye  li...', ARRAY['Türk Edebiyatı','Şiir','Ömer Demir']::text[], 8.5, '{"poet":"Ömer Demir","poet_slug":"omer-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":128,"source_url":"https://www.antoloji.com/siler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sosinê', 'sosin-omer-demir-b2iu5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Lê Sosinê, malxirabê tu çi dikî li çiyayên Gûzereşa malxirab, hin melûl û stûwxarî, lê Sosinê! ... 

Ka were bêhna xwe ya xweş berde nava van hinavên min ên şewitî û min bibe zozanên Gare, Sermedar û Geraşîn e. Lê Sosinê! ... 

Lê malxirabê! Tu min zozana Berçelan û Feraşînê bike mêvanê kewên ribat ku Ligel tavdana spêdeyan pirî xweş dixwîne. 

Na na, ne weleh tu min bibe ser wan kaniyên sar û xweş, li terazinên dora keviyan dane; 

Bila bilbilê malikxirab bêt û strana ''xunava gulê'' ji bo dilê me yê kovandar û xwerûjan velorîne... 

Hey Sosina minê, Sosê! 

Hey Sosinê! Da nebêjin ev gelê han bê xwedî ye, kesê xwe nîne! ... 

Serê vê salê, danê vê biharê evdala Xudê ev revendê malxirab bi rêketine, 

Ka bo min bibêje; ewê biçin zozanan, an fermana Roma reş a xayîn li ser dagirtine... 

Lê Sosinê, davziravê; tuyê wan davên xwe didî ber bayê sira sihara vî welatî, radimûsî tîrêjên roja nû ye 

Malxirabê, tuyê were bo dilê min ê birîndar bibe nûja jînê, kulan li ser dilê min hilavêtî ye, 

Roja xweş li ser min ava bûye; 

Feleka me li me wergerî ye, 

Riya me çol û kûstanin, kolanên xelkê biyanî ye, 

Danê vê biharê xweşiya dinyayê li ber dilê me ''Evdala Xudê'' herimî ye... 

Hey Sosina minê, bextê te me; tu dav bi dav xemla xwe ya xweşik berde ser welatê me yê talan bûye, 

Xudê pê dizane sala îsal, danê vê biharê emê berê xwe bidin welatê xerîb û xurbetan, 

Kî dizane emê li çolan bibin xwerekê dirindan, 

Teyr û tilûr dê me hincirînin li ber nik û pencan, 

An jî hemû dê ji ta û birsê, tazî bêfathe bimirin li ber cergê tavê, li serê vê bihara xwedê! 

Ma tu nabînî malxirabê eve fermana serê me rabûye! 

Lê Sosina minê Sozê! ... 

05-06-1995', 'Lê Sosinê, malxirabê tu çi dikî li çiyayên Gûzereşa malxirab, hin melûl û stûwxarî, lê Sosinê! ...  Ka were bêhna xwe ya xweş berde nava van...', ARRAY['Türk Edebiyatı','Şiir','Ömer Demir']::text[], 8.5, '{"poet":"Ömer Demir","poet_slug":"omer-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sosine-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ezê Dîtir', 'ez-d-tir-omer-demir-ku833', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1 

ew ezê ku di kûratiyên ''min'' de veşartiye 

ewê ku ''ez'' wî nas nakim 

ewê bo min biyanî… 

ewê li kûratiya dil xwe li min veşartiye 

ew ezê ku ''ez'' qet nizanim çawaye 

ew ezê dîtir yanî 

ezê ku min qet nedîtiye 

ezê ku di nepeniyan de digere 

û veşartokê bi min re dilîze 

2 

ew ezê di nava min de 

ku dişibe darkirokê 

her êvarî tobe dike 

û her spêdeya piştî wê êvarê jî 

toba xwe betal dike… 

3 

ew ezê du perçe… 

ewê bêpêjn xwe dikuje 

û dîsa piştî her xwekuştinekê 

bi xweliya xwe ve xwe vedijîne 

4 

ew ezê ku ''min'' berze kiriye 

û hinde sal in bêrawestan lê digerim 

li ser rûyê cîhanê 

hin caran di tîna awirên xezalekê de 

hin caran di çirûska dilê dayikekê de 

hin caran di bişirîna zelal a zarokekê de 

5 

ew ezê ku bi qasî dîroka mirovahiyê kevin 

bi qasî teyrê eylo resen 

û bi qasî ''xwe'' jî têkçûyî 

ew ezê dîtir, 

ewê ku bi çarlepkî xwe gihandiye asoyên winda 

ewê bi dewisandinan re tixûb çirandine 

û xwe gihandiye stêrkan… 

ew ezê bûme stêrk 

6 

ew ezê dengê xwe di nalîna bilûrekê de berzekiriye 

ewê di nav pêlên evînê de serobin bûye 

ew ezê ji bo evîneke pak birçî 

ji bo evîndareke dilsoz bûye derwêş 

û xwe bera nav çol û çolistanan daye 

7 

ew ezê dîtir… 

ezê ku di xewnên zaroktiyê de maye 

hê jî bi dileke zarokane 

bi çirûskekê şad dibe, 

bi dilopekê xemgîn… 

yanî ew ezê qet mezin nebûyî 

qet hînî jiyanê nebûyî 

qet neketiye gengeşiyên serdemê 

û qet bera nav bayên derdorê nedayî 

8 

ew ezê min di riya lêgerînê de winda kiriye 

ezê winda… 

ezê kena ''wî'' li ser rû tirş bûye 

rondik di çavan de hişk bûye 

ezê di nava peyvên tûle de gêr dibim 

li ser hişkerûyê kaxezên qirmiçî 

9 

ezê ne ji bo ''xwe'' bikarî bijî 

ne jî mifadarê derdora xwe 

ezê dîtir… 

ewê ku ji nava hemû lîsteyan hatiye renîn 

ji hemû heyiyan hatiye vederkirin 

ezê ji marî rûstir, ji gurî birsîtir 

ezê ku ''min'' hilma wî seh nekiriye 

10 

ezê delodîn 

ezê bo xweziyeke avis fêk bûye 

di nav mij û morana jiyanê de 

xwe li hespê hêviyên winda siwar kiriye 

û dajot…dajot 

li şevexwînên dûvedirêj 

ber bi bayê kur, 

li gel afriya karwankujan 

di nav dilê çiya û baniyan re… 

11 

ezê ku di şopa xezaleke kûvî de winda bûye 

bi tena serê xwe… 

li çiyayeke dûr î pişt asoyan 

di rojeke ne li salnameyan hatiye tomarkirin de 

ne jî di nava rûpelên dîrokê qeyd bûyî de 

12 

ezê ku bi zêmarên dayikan hişyar bûye 

li ser kêliya goreke nenavkirî 

ezê bi janên ''min'' di xwe de çûye 

li nav nameyeke qet rênekirî 

13 

ezê dîtir yanî 

ew ezê ku qet nizane derewan bike 

nizane bi ristên ''lê ferz dikin'' bilîze 

û rûpoşan li rûyê xwe bipêçe 

di nav dubendiyê de bikare bimîne 

ew ezê lawaz, 

ewê têkçûyî… 

ji ber ku nezaniye bilîze 

14 

ew ezê ku bi senfoniyeke dengketî 

strana ''yên dîtir'' dinehwirîne 

15 

ew ezê dîtir, 

ezê ku li ''min'' digere 

ji bo ''min'' têdikoşe 

ji ber ''min'' diêşe 

ew ezê ji bo ''min'' xwe dikuje 

û bi xweliya xwe ve ''min'' diafirîne 

ezê xwe gorî ''min'' kirî… 

li welateke hemû êşan pêçayî, 

hemû jan lê akincî bûne 

û ''jiyanê'' di bin xweliya ''mirinê'' de aj dayî 

16 

ezê dîtir, 

ango ezê azad 

ew ezê ku hê jî kariye xweser bimîne 

hê jî kariye bêhna axê jê bifûre 

ew ezê ku hê jî ''ez'' im… 

2003-12-11/ Amed', '1  ew ezê ku di kûratiyên ''min'' de veşartiye  ewê ku ''ez'' wî nas nakim  ewê bo min biyanî…  ewê li kûratiya dil xwe li min veşartiye  ew ezê...', ARRAY['Türk Edebiyatı','Şiir','Ömer Demir']::text[], 8.5, '{"poet":"Ömer Demir","poet_slug":"omer-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":119,"source_url":"https://www.antoloji.com/eze-ditir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gulhinarê', 'gulhinar-omer-demir-rcubl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Li ser asoyên zirav 

Digel helesorka berbeyanê 

Awirên min ên vala dişkên 

Li valahiyê dinêrim 

Heçko tiştekî min winda bibe 

Li te digerim 

Li te Gulhinarê 

Û strana te dibêjim: 

Reng biharê 

Gul hinarê 

Çav belekê 

Gerden spîndarê 

Bi hesteke zarokane 

Dilê min diperpite ji ber te 

Ligel her hilavêja rojê 

Wexta çavên min hişyar dibin ji xewê 

Tiştê yekem tê bîra min 

Tenê tuyî Gulhinarê 

Û strana te distêrim: 

Reng biharê 

Gul hinarê 

Çav belekê 

Gerden spîndarê 

Li dawiya her rojê 

Ligel xatirxwestina ronahiyê 

Wexta stêrk diçilvilin li asiman 

Awirên min ên xemgîn 

Li nav hemû stêrkan 

Tenê li te digerin Gulhinarê 

Û strana te dinihwêrînim: 

Reng biharê 

Gul hinarê 

Çav belekê 

Gerden spîndarê 

2004-04-02', 'Li ser asoyên zirav  Digel helesorka berbeyanê  Awirên min ên vala dişkên  Li valahiyê dinêrim  Heçko tiştekî min winda bibe  Li te digerim ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Demir']::text[], 8.5, '{"poet":"Ömer Demir","poet_slug":"omer-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/gulhinare-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Arayan Deliyim', 'seni-arayan-deliyim-mustafa-tugrul-kosar-8eyp4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sözüm geçmedi yıllara 

Belki diye yola düştüm 

Aldırmam yağan yağmura 

Ben zaten herşeye küstüm 

Karanlığın gölgesinde 

Binbir hatıra gözümde 

Bitkin ifade yüzümde 

Seni arayan deliyim 

Bir yalnızlığın şarkısı 

Titreyen dudaklarımda 

Özlemlerin haykırışı 

Kararlı adımlarımda 

Nerelerdesin bilmeden 

Bir umut için direnen 

Saatlerce üşenmeden 

Seni arayan deliyim 

Sen yazlardasın ben kışta 

Aklım o çılgın bakışta 

Loş ışıklı akşamlarda 

Seni arayan deliyim', 'Sözüm geçmedi yıllara  Belki diye yola düştüm  Aldırmam yağan yağmura  Ben zaten herşeye küstüm  Karanlığın gölgesinde  Binbir hatıra gözümd...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tuğrul Koşar']::text[], 8.5, '{"poet":"Mustafa Tuğrul Koşar","poet_slug":"mustafa-tugrul-kosar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-arayan-deliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen İyi Ol Sevdiğim', 'sen-i-yi-ol-sevdigim-tunahan-ermihan-ruv3r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nedendir bilmem sevdiğim

Korkular düşüyor kaç gecedir

Yüreğimin tam orta yerine

Kimi zaman eskilerden bir şarkı dinlerken

Kimi zaman adını hatırlamakta zorlandığım

Bir filmin sahnelerini düşünürken

Kimi zaman ağlıyorum sırf bu yüzden

Kimi zamansa yorganıma sarılıp seni düşünüyorum

Biliyor musun bu ikinci durum beni daha çok rahatlatıyor

Ama bu korkular kaç gecedir bende misafir

“en azından ben misafir olmalarını ümit ediyorum”

Ya gitmezlerde kalmayı tercih edip

Bunun içi hayatımdan bir bedel alırlarsa

İşte bu düşünce

Uykuyu haram ediyor sensiz gecelerin karanlığında

Adını bilmediğim korkular salındı gecelerime sevdiğim

Ya sen iyi ol yada ben kötü oluyorum', 'Nedendir bilmem sevdiğim Korkular düşüyor kaç gecedir Yüreğimin tam orta yerine Kimi zaman eskilerden bir şarkı dinlerken Kimi zaman adını h...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-iyi-ol-sevdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sordum Arif''i', 'sordum-arif-i-i-lyas-ozmen-cudbl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gördüğüm herkesten sordum Arif''i

Arılar; çiçektir baldır dediler

Her canlıya göre başka tarifi

Balıklar,deryadır göldür dediler

Dört mevsim baharmış bilmezmiş kışı

Muhabbet kokarmış hayali düşü

Sevda yollarının çileli kuşu

Bülbüller; goncadır güldür dediler

Sözleri şiirle türkü kokarmış

Yüreği sevgiden bir dağ kadarmış

Onsuz sazlarının sesi çıkmazmış

Aşıklar; mızraptır teldir dediler

Eskiye yeniden hayat verirmiş

Diken tarlasından sümbül derermiş

Leylayı araken Mevlaya ermiş

Erenler; hikmeti boldur dediler

Riyadan yalandan medet ummazmış

Gururla kibirle işi olmazmış

Kimseyi incitmez gönül kırmazmış

Bilenler; hayırlı kuldur dediler

ÖZMENEM hilafsız hepisi doğru

Dostluğu aranır bir adem oğlu

Melekler kıskanıp kestiler yolu

Uçamaz! kanadı yoktur dediler

(Şiiri kendisine okuduğumda mütevaziliğinden yüzü 

 kızaran dostum Arif Aktaş''a,aslında şiiri yazarken

 abartı yapmayıp ben mütevazi davrandım bu yüzden

 affını dilerim.Saygılarımla)', 'Gördüğüm herkesten sordum Arif''i Arılar; çiçektir baldır dediler Her canlıya göre başka tarifi Balıklar,deryadır göldür dediler Dört mevsim ...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özmen']::text[], 8.5, '{"poet":"İlyas Özmen","poet_slug":"i-lyas-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sordum-arif-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyun İçinde Oyun', 'oyun-i-cinde-oyun-cigdem-bir-genc-zt6nb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kağıttan gemiler yüzdürüyor

Annesinin çamaşır leğeninde bir çocuk

62’den tavşanları

düşlerinin arka bahçesinde...

ansızın  gelen

koca  adamlar 

kurşun askerlerini alıp kaçtılar

koşarak geldi hüzün

bir çocuğun gözlerindeydi ben gördüm....', 'Kağıttan gemiler yüzdürüyor Annesinin çamaşır leğeninde bir çocuk 62’den tavşanları düşlerinin arka bahçesinde... ansızın  gelen koca  adaml...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Bir Genç']::text[], 8.5, '{"poet":"Çiğdem Bir Genç","poet_slug":"cigdem-bir-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/oyun-icinde-oyun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günah Pazarı', 'gunah-pazari-i-smail-baharsen-wdabq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'her gözde ayrı bir yalan 

ne bu dünyanın kötü tuzağı

şeytan efendi kölesi insan

her köşede bir günah pazarı

haram karışmış helale artık

zaman zalim, gönüllere yazık

kara denen kaderler batık

her köşede bir günah pazarı

gün gün yaklaşıyor ölüm

tenedir bu sonsuz zulüm

gelir geçerken görür gözüm

her köşede bir günah pazarı', 'her gözde ayrı bir yalan  ne bu dünyanın kötü tuzağı şeytan efendi kölesi insan her köşede bir günah pazarı haram karışmış helale artık zama...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gunah-pazari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asla', 'asla-mustafa-tugrul-kosar-5xjyd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Üç nefes bir isim var üstünde bu kentin

Ne yağmur yıpratır,

Ne kar,ne de güneş

Herhangi bir yerde,herhangi bir zamanda,

Bir çift göz gölge gibi önümde

Yudum yudum sevgi tatmalıyken,

Bırak yarınları,

Hayatı burnundan gelmiş,

Birisi var sanki içimde

Kolay...,

İnan ki çok kolay çıkartacaksın beni aklından

Fakat içimdeki seni asla alamayacaksın,

Asla...

Bakma hiç düşünmez,

Umursamaz göründüğüme

Ben bir kaya,

Bir demir parçası değilim ha...

Bana her bakışında,

Sana verecek sevgi yok dercesine,

Hitab ederken sen,

Sanma ben üzülüp,

Kahrolmadım hiç kimse kadar

Hayır...

Artık sevmeyi bilmeyen,

Binlerce kişiye pay edeceğim duygularmı

Sana da titrek dudaklarla,

Dualar okumayı unutmayacağım

Hayallerimi yıkabilirsin,

Hemde nasıl yıkabilirsin

Gözlerime gözlerinle diktiğin,

Sevda abidesini asla...

Benim aynalara itimatım kalmadı,

İltifatlara ihtiyacım yok

Dalga dalga,

Rengarenk sevdalara vursun kaderin,

Ne romanlar kıskansın,

Ne şarkılar söylensin,

Güzelliğinin üstüne

Şairlerin elinde kalemler kırılsın,

Öylesine etkilensinler ki

Ebediyen güleceğini bilsem,

Sevinçten ağlarım hemde çok

Bir nefeslik canımı al istersen

Ama yok öyle yoook...

İçimde ki seni asla alamayacaksın,

Asla...

Bahar rüzgarları gibi,

Gelip geçici umutlarım

Kemandan çıkan melodi gibi,

Ağlar duygularım

Eski bir trende gibiyim

Her saniyesi geçmiş kokan

Duygu kokan,insanlık kokan

Bir saç teline muhtaçken,

Sevdiğinden olan,

Bir hayal yolcusu gibi,

Sensizliğin herhangi bir koynuna,

Ölesiye bırakacağım kendimi

Fakat seni asla unutmayacağım...

Asla...

Asla...

Asla...........', 'Üç nefes bir isim var üstünde bu kentin Ne yağmur yıpratır, Ne kar,ne de güneş Herhangi bir yerde,herhangi bir zamanda, Bir çift göz gölge g...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tuğrul Koşar']::text[], 8.5, '{"poet":"Mustafa Tuğrul Koşar","poet_slug":"mustafa-tugrul-kosar","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/asla-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Perde', 'mavi-perde-mustafa-tugrul-kosar-4s5bt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün... Bilmiyorum 

İnanmak istedim gittiğine 

Belki geç, belki zamansız 

Laçkalaşmış bir hatıraya yenildim 

Balkonumun korkuluklarıda ıslandı gözlerimle beraber 

Akşam olmuştu artık... 

Daldım gittim yabancı bir perdeye 

Kıpırdar sandım! 

Özlemlerin işareti başlar sandım! 

Nasıldı yıllar önce? 

Kulaklarını açar beni beklerdin, bilirdim 

Bir ıslık: pencereye çık! 

İki ıslık: yarın buluşalım! 

Üç ıslık...: seni seviyorum... 

Bir tebessüm parıltısı olurdu gözlerimde 

Kırpmaksızın bakardım 

Artık sıra sendeydi 

Yanar sönerdi mavi perde 

Bir ışık:babam evde! 

İki ışık: yarın aynı yerde! 

Üç ışık:bende seni... 

Masmavi olurdu gecem, 

Perdenizin gizemli renginden 

Hayallerim süslenirdi yatamazdım 

Kalkar belki bakarsın diye, 

Kaç kez uyuklardım pencerede 

Sen o evdesin, ben burda 

Boşluğu öper üflerdim sana, 

Dokunur diye yanaklarına 

Sabahı getiremez bağırmak isterdim, 

Gecenin suskun boşluğuna... 

Çil çil aya yansırdı yüzün 

Küçük büyük her rüzgara canım derdim, 

Uykunda gider diye sana 

Kendi saçlarımla, kendi dudaklarımla avunurdum 

Geceleri hayallerimde hep gelindin 

Zarif, kibar bir çiçektin 

Lalelerin sevimli ablası... 

Var mı daha ötesi mutluluğun? 

Ellerimi tutardın ya ne isteyebilirdim başka? 

Bakışınla ısınır, nefesinle serinlerdim 

Dizlerinde uyur, öpülerek uyanırdım 

Seni kaybederim diye nasılda korkardım... 

Uzun zaman geçti...Farkedemedim... 

Şimdi tuhaf bir renk bürüdü, 

Bir zamanlar boş kalan o evi 

Gülmek için değil, 

Artık ağlamak için çıkıyorum balkona 

Gözlerimdeki dikkat yok, 

Kısık, yorgun bakıyorum sıradan bir eve 

Gölgen yok artık yabancı perdede 

Görsen nasıl değiştim! 

Herşey değişti bıraktığın mahallede 

Bir ıslık...: uzaklardamısın? 

İki ıslık...: beni unutmadın ya? 

Üç ıslık...: seni seviyorum... 

Hala seviyorum...', 'Bugün... Bilmiyorum  İnanmak istedim gittiğine  Belki geç, belki zamansız  Laçkalaşmış bir hatıraya yenildim  Balkonumun korkuluklarıda ısla...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tuğrul Koşar']::text[], 8.5, '{"poet":"Mustafa Tuğrul Koşar","poet_slug":"mustafa-tugrul-kosar","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/mavi-perde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erguvanmış Sesin', 'erguvanmis-sesin-yildiz-yildiz-jdr0m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Başlık Etiketleri-2

Varsın aşk yüklemesin yağmura bulutlar

Sesin damladı  yüreğime! ! ..

Gönlüm engin dağ  doruklarında alır soluğu,

Ayaklarımda köpük köpük denizler...

Saçlarım bulutlara karışır

Aşk şarkılarını düşürür kırar,

taşıyamaz rüzgarlar..

Dudağın sedası

Kulağımda meltem fısıltısı

Şimdi bu rüzgarla ben

Mavi, erguvan ufuklara pupa yelken..', 'Başlık Etiketleri-2 Varsın aşk yüklemesin yağmura bulutlar Sesin damladı  yüreğime! ! .. Gönlüm engin dağ  doruklarında alır soluğu, Ayaklar...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Yıldız']::text[], 8.5, '{"poet":"Yıldız Yıldız","poet_slug":"yildiz-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/erguvanmis-sesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayata Dair Dipnotlarım *2*', 'hayata-dair-dipnotlarim-2-tulay-sustam-9jquf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aldanma! ...

Takmadır tırnaklarım, dişlerim porselen, saçlarım boyalı

Adam gibi çıkmışım karşına...

Hiç olmasa gece, gündüz maskesizim

Elimde meşalem; yüreğim yürektir, bileğim bilek

*

Bacaklarımı parçalara bölmüşüm

Tekerlekli sandalye de her bir çocuğa dağıtmışım

Yeter ki onlar koşsun, yürüsün diye...

O yüzden sana gelemiyorum sevgili...

Böyle oturduğum yerde seni izlemek daha iyi...

*

Benim hiç bez bebeklerim olmadı

O yüzden bebek, çocuk hastası olmuşum

Şimdi bütün sokak çocuklarının ablası da benim,

Anneleri de benim...

Onlar nerede görseler tanırlar beni

Biri elimden tutar, biri eteğimi çekiştirir

Annelik ne kadar zormuş, gece gündüz yavrularım için ağlarım

*

Aşklarımın ilki de aynı sonuncusu da...

Baştan bir ilmeğini kaçırmışım sonu da hep öyle gitmiş

Öyle giymişim üzerime bütün gözler kaçmış...

*

Hayatın yarı bodrum katında yaşıyorum

Işıksız, kimsesiz, aç ve susuz...

Küçük bir kız çocuğu gülümseyerek pencereden bana bakar durur

Ben onun gözleriyle bakarım hayata onun gördüğü gibi görürüm

Karnım da doyar, karanlıktan da kurtulurum. 

O kız hiç gitmez yanımdan ve hiç büyümez içimde

(Bu şiirimi Elif Şebnem Akal, Ayten Çolakoğlu ve Çağıl Ener dostlarıma

hediye ediyorum.)', 'Aldanma! ... Takmadır tırnaklarım, dişlerim porselen, saçlarım boyalı Adam gibi çıkmışım karşına... Hiç olmasa gece, gündüz maskesizim Elimd...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/hayata-dair-dipnotlarim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Duymadığım Bir Tek Söz Söyle', 'bana-duymadigim-bir-tek-soz-soyle-i-smet-barlioglu-xkw5w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bana duymadığım bir tek söz söyle; 

Sevgiler, saygılar, gönül üstüne.

Bırak hasbahçeler perişan olsun,

Sen şarkılar söyle bülbül üstüne.

Işıklar oynarken yanaklarınla,

Saçını tararken parmaklarınla,

Konuş gülden güzel dudaklarınla

Toprağa renk veren sümbül üstüne.

Sitemli konuşma; dil yaralanır,

Irmağa taş atma; sel yaralanır,

Merhametsiz olma; kul yaralanır,

Söz et mor menekşe ve gül üstüne.

(BİR YORGUN FIRTINA isimli hece şiirlerinden > 84-85/100)', 'Bana duymadığım bir tek söz söyle;  Sevgiler, saygılar, gönül üstüne. Bırak hasbahçeler perişan olsun, Sen şarkılar söyle bülbül üstüne. Işı...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bana-duymadigim-bir-tek-soz-soyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalanmış', 'yalanmis-olgun-keskin-arf6o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Katı hale gelmiş rüyalarda yapboz oynamak mı var olmak? 

Düşlere dokunup gülmek mi? 

Rüyalarla gelen bir toz tanesinde saklı.. 

Gün ışığında gizli, gecenin soğuk teninde belki (?)   

Kuyruğa girmiş acı taneleri içinde, gözyaşıyla avuntu 

Unutulmuşlugun içinde madde olma telaşı sanki..

Halisilasyonlar ortasında gerçeği arama hevesi

Belki de; bir adam var sokak lambamın altında..

Elinde kendiyle bütün olmuş bir şişe..

Kollarıyla sarmalamış, dünyadan sakınıyor sanki..

Var olmak, kollarının arasında saklı 

Sordum....Evet.. buramda, buramda saklı dedi..

             ............gitti......

                              ..sondayım şu an..  YALANMIŞ! ...', 'Katı hale gelmiş rüyalarda yapboz oynamak mı var olmak?  Düşlere dokunup gülmek mi?  Rüyalarla gelen bir toz tanesinde saklı..  Gün ışığında...', ARRAY['Türk Edebiyatı','Şiir','Olgun Keskin']::text[], 8.5, '{"poet":"Olgun Keskin","poet_slug":"olgun-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yalanmis-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bir Yanındayım, El Bir Yanında', 'ben-bir-yanindayim-el-bir-yaninda-i-smet-barlioglu-0mz5b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çocukken evcilik oynardık senle,

Evlenirdik güya binbir törenle,

Yolumu beklerdin bebeklerinle,

Sümbül bir yanında, gül bir yanında.

Yoktu aramızda dikenli çalı,

Sen bana, ben sana nasıl sevdalı,

Her geçen günümüz bir Hint masalı,

Orman bir yanında, göl bir yanında.

Sorunumuz yoktu, gamımız yoktu,

Sinip sığınacak damımız yoktu,

Ayrı geçen bir tek anımız yoktu,

Irmak bir yanında, sel bir yanında.

Şimdi sen bir alem, ben başka alem,

Hala seviyorum ama diyemem,

Git desen gidemem, gel de, gelemem,

Ben bir yanındayım, el bir yanında.

(BİR YORGUN FIRTINA isimli hece şiirlerinden > 86-87/100)', 'Çocukken evcilik oynardık senle, Evlenirdik güya binbir törenle, Yolumu beklerdin bebeklerinle, Sümbül bir yanında, gül bir yanında. Yoktu a...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-bir-yanindayim-el-bir-yaninda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Varken Karanlık Işıl Işıldır', 'sen-varken-karanlik-isil-isildir-i-smet-barlioglu-aoqjs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aldırmam baharın güzelliğine; 

Yapraklar sen varken yeşil değildir.

Geceler zindandan farksız da olsa; 

Sen varken karanlık ışıl ışıldır.

Sadece sen varken deniz anlamlı,

Köpükler düzenli, kumlar planlı,

Çiçekler dallarda daha gümanlı,

Çimenler, yapraklar hışıl hışıldır.

Ne kadar kuş varsa dallarda uyur,

Ne kıpırtı olur ne ses duyulur,

Denize bir düzgün çarşaf yayılır,

Dalgalar sahilde mışıl mışıldır.

(BİR YORGUN FIRTINA isimli hece şiirlerinden > 88-89/100)', 'Aldırmam baharın güzelliğine;  Yapraklar sen varken yeşil değildir. Geceler zindandan farksız da olsa;  Sen varken karanlık ışıl ışıldır. Sa...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-varken-karanlik-isil-isildir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökelbet Gürleyecek', 'gokelbet-gurleyecek-firat-tasan-3i9i8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gökelbet gürleyecek

                                             suyun nöbetini tutan çocuğa

uçurumlara inat haytalığınla

nöbetini tutuğun ölüm değil

kaybolacak nefesimizdi

da kurşunlandın.

ortaklarımızla pazarladık kinini

nöbetini tuttuğun yitik ülkeden

ağlama duvarlarına fotoğrafsın şimdi

herkes ağlar, kalp bükülür

salıncak diye oyalar mevsimleri

niyesi önce denmiş

eylemleri olur herkesin

herkesin bi tanrısı var ve bahanesi

nisanda doğan oğlan

babacığın unutmaz

yurduna adayacak verdiğin son nefesi

nisan bu, kalbin bu oyalanacak

elbet,amcaoğulların da eğlenmeni

bekleyecekler

bir dilimlik naz için,

ateş menziline girdin mi? girdim.

bir kurşun keser salıncağının zincirini

deli ve sarhoş artık

suvardığın kuşkular

eylemi bozan sözü doğrayan

birer haşiye döktüğün herbi damla kan

incir ve zeytin incisi toprakların varisi

son oğul, son ay, son ismail', 'Gökelbet gürleyecek                                              suyun nöbetini tutan çocuğa uçurumlara inat haytalığınla nöbetini tutuğun ö...', ARRAY['Türk Edebiyatı','Şiir','Fırat Taşan']::text[], 8.5, '{"poet":"Fırat Taşan","poet_slug":"firat-tasan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gokelbet-gurleyecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mumlar Nasıl Erirse Gümüşten Şamdanlarda', 'mumlar-nasil-erirse-gumusten-samdanlarda-i-smet-barlioglu-24svj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mumlar nasıl erirse gümüşten şamdanlarda; 

Nasıl batarsa güneş yorulmuş ufuklarda; 

İnsan nasıl kaybolup giderse uykularda; 

İşte senin uğrunda tükendim aynen öyle.

(BİR YORGUN FIRTINA isimli hece şiirlerinden > 90/100)', 'Mumlar nasıl erirse gümüşten şamdanlarda;  Nasıl batarsa güneş yorulmuş ufuklarda;  İnsan nasıl kaybolup giderse uykularda;  İşte senin uğru...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/mumlar-nasil-erirse-gumusten-samdanlarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selam', 'selam-halil-i-brahim-ozdemir-nz038', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Toprağa güneşe denize selam

Bahara, yaprağa ve güze selam

Yüce bir kaynağa yönelen dosta,

Sımsıcak yüreğe ve size selam', 'Toprağa güneşe denize selam Bahara, yaprağa ve güze selam Yüce bir kaynağa yönelen dosta, Sımsıcak yüreğe ve size selam...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özdemir']::text[], 8.5, '{"poet":"Halil İbrahim Özdemir","poet_slug":"halil-i-brahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/selam-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Masal Anlat Telli - Telekli', 'bana-masal-anlat-telli-telekli-i-smet-barlioglu-2vabw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bana masal anlat telli-telekli,

Melekleri olsun; başı çelenkli,

Kuşları dallarda hevenk hevenkli

Fakat prensesi sadece senden.

Bana masal anlat öpücük dolu,

Sevgiler, saygılar, gülücük dolu,

Dağları, tepesi gelincik dolu,

Gül kokan nefesi sadece senden.

Bana masal anlat, ruhum durulsun,

Kaf Dağı ardına tahtım kurulsun,

Yüreğim bir beyaz güvercin olsun,

Altından kafesi sadece senden.

Masalda mutlaka kavuşalım biz,

Murada erelim en son ikimiz,

Mutlulukla dolsun sırça köşkümüz,

Bülbüllerin sesi sadece senden.

(BİR YORGUN FIRTINA isimli hece şiirlerinden > 91-92/100)', 'Bana masal anlat telli-telekli, Melekleri olsun; başı çelenkli, Kuşları dallarda hevenk hevenkli Fakat prensesi sadece senden. Bana masal an...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bana-masal-anlat-telli-telekli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meçhul Eşim', 'mechul-esim-talip-kaplan-071xu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Elveda sevgilim

Ayrılıyorum artık senden

Elveda meçhul eşim

Boşanıyorum artık senden

Bunca yıl hep seni aradım

Sana hiç rastlamadan tanıştım

Değmeden saçlarını okşadım

Görmeden gözlerinle bakıştım

Değişik bir duygu,

Olmayan sevgiliyi sevmek

Benimkisi saçma bir tutku

Düşünceler beni nasıl sevecek

.                                                 .aşkı nerden bilecek

Telefonun ahizesini kaldırmak

Tuşlara basmadan konuşmak

Hayallere espiri yapmak

Düşüncelerin derdine ağlamak

Ayrılıyorum şimdi hiç olmayandan

Kopuyoruz birbirimizden hiç kavuşmadan.

Mutluyuz tatmadığımız güzelliklerden

Bir bak sana geriye; 

Kalakaldık yaşanmamış bir maziyle...

(13 Kasım 1993)', 'Elveda sevgilim Ayrılıyorum artık senden Elveda meçhul eşim Boşanıyorum artık senden Bunca yıl hep seni aradım Sana hiç rastlamadan tanıştım...', ARRAY['Türk Edebiyatı','Şiir','Talip Kaplan']::text[], 8.5, '{"poet":"Talip Kaplan","poet_slug":"talip-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/mechul-esim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Değil', 'ask-degil-talip-kaplan-wq8y9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nedir bu tutkunluğum sana

Bunun tanımını ararım hep

Nedir senin çekici kuvvetin

Bunun kaynağını ararım hep

Aşk değil sana tutkunluğum

Ben aşkta Mecnun''u geçerim

Sevgi değil sana tutkunluğum

Sevgiden yana herkese tutkunum

Fiziğin değil çekici tarafın

Güzellik bugün var yarın yok

Ses tonun değil bu gücün

Ben senden şarkı dinlemedim

Sebebini, ben henüz bilemedim.

(06 Aralık 1993)', 'Nedir bu tutkunluğum sana Bunun tanımını ararım hep Nedir senin çekici kuvvetin Bunun kaynağını ararım hep Aşk değil sana tutkunluğum Ben aş...', ARRAY['Türk Edebiyatı','Şiir','Talip Kaplan']::text[], 8.5, '{"poet":"Talip Kaplan","poet_slug":"talip-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ask-degil-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ata''nın Göz Yaşları', 'ata-nin-goz-yaslari-sabri-gunaydin-upy6u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Buğulanan gözlerden

Bir damla yaş aktı.

Her yer titredi birden

San ki toprak yarıldı.

Atam  titrek bir sesle

Haykırdı vatan diye

Öpüp kanlı bayrağı

Sımsıkı bağrına bastı.

Atamın gözyaşları 

Arşa kadar ulaştı

Sesini duyan tanrı

Yeter diye haykırdı.

Birden dirildi şehit

Hiddetlendi aniden

Atamı ağlatmayın

Hür yaşarız ezelden.', 'Buğulanan gözlerden Bir damla yaş aktı. Her yer titredi birden San ki toprak yarıldı. Atam  titrek bir sesle Haykırdı vatan diye Öpüp kanlı ...', ARRAY['Türk Edebiyatı','Şiir','Sabri Günaydın']::text[], 8.5, '{"poet":"Sabri Günaydın","poet_slug":"sabri-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ata-nin-goz-yaslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avare Sokakların İsyankar Delikanlısı', 'avare-sokaklarin-i-syankar-delikanlisi-sabri-gunaydin-sqqba', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gece sessiz ve karanlık, dalmak üzereyim

İçim ürperiyor aniden bir baykuş sesiyle,

Korkuyorum, ve iliklerim donuyor soğuktan

Sığınacak bir yer arıyorum bulamıyorum.

Doğruluyorum; ilerliyorum ağır ağır

Attığım her adım ölüm eridiğimi hissediyorum

Karanlığa dalıyorum giderek, evler gitgide kayboluyor

Dönüp ardıma bakıyorum her şey yalan, her şey viran.

İsyan ediyorum kadere ve yalnızlığıma; 

Avazım çıktığı kadar haykırıyorum

Aklıma eski dostlar geliyor; susuyorum

Ve kendimi tutamıyorum, ağlıyorum

Bir  sarhoş geliyor yanıma, beni avutmaya çalışıyor,

Başımı kaldırıyorum bakıyorum.

Kendime kıyacak bir yer arıyorum

Beni öldüren sokaklara sonunda ruhumu da veriyorum.', 'Gece sessiz ve karanlık, dalmak üzereyim İçim ürperiyor aniden bir baykuş sesiyle, Korkuyorum, ve iliklerim donuyor soğuktan Sığınacak bir y...', ARRAY['Türk Edebiyatı','Şiir','Sabri Günaydın']::text[], 8.5, '{"poet":"Sabri Günaydın","poet_slug":"sabri-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/avare-sokaklarin-isyankar-delikanlisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu sevdadan Çıkış yokmuş', 'bu-sevdadan-cikis-yokmus-sabri-gunaydin-9fhkw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '30.06.2004

Bu sevdadan çıkış yokmuş

Bunu şimdi anlıyorum

Meğer ne çok sevmişim seni

Hasretinden yanıyorum

Beyhude oldum,yalnızım şimdi

Anladım çarem kalmadı senden başka

Ne insanlar sevdim, ne ateşlerde yandım

Anladım bütün yollar sana çıkmakta

Al yüreğim de senin olsun

Zaten çoktandır küskün bana

Bir canım vardı  oda Hakka ait

İnan aklımda firar eder yakında', '30.06.2004 Bu sevdadan çıkış yokmuş Bunu şimdi anlıyorum Meğer ne çok sevmişim seni Hasretinden yanıyorum Beyhude oldum,yalnızım şimdi Anlad...', ARRAY['Türk Edebiyatı','Şiir','Sabri Günaydın']::text[], 8.5, '{"poet":"Sabri Günaydın","poet_slug":"sabri-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bu-sevdadan-cikis-yokmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Figan', 'figan-sabri-gunaydin-98tmu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Böyle güldüğüme bakma bebeğim

İçimde volkanlarım var benim.

Gülümsememe bakma sakın

Yüreğimde figanım var benim.

Hayırsız kim varsa beni buldu 

Bir zamanlar çağlar iken

Şimdi kalbim ağlar oldu.

Yarınımı arar iken

Bu günümde kayboldu

Tükendi acıyla yıllarım.', 'Böyle güldüğüme bakma bebeğim İçimde volkanlarım var benim. Gülümsememe bakma sakın Yüreğimde figanım var benim. Hayırsız kim varsa beni bul...', ARRAY['Türk Edebiyatı','Şiir','Sabri Günaydın']::text[], 8.5, '{"poet":"Sabri Günaydın","poet_slug":"sabri-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/figan-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşey Biterken', 'hersey-biterken-sabri-gunaydin-uek7x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Umutlarım intiharın eşiğinde

Yarınlarım yok artık.

Sevgiler hayallerde kaldı

Hayallerimde yok artık.

Ne ecel ayırır seni benden

Nede daha fazlası 

Seni bir kez sevdiysem

Yalan benden başkası

Sen benden kaçsan da

Sevgim bırakmaz yakanı

Yine bana kalırsın

Ömrünün son akşamı.', 'Umutlarım intiharın eşiğinde Yarınlarım yok artık. Sevgiler hayallerde kaldı Hayallerimde yok artık. Ne ecel ayırır seni benden Nede daha fa...', ARRAY['Türk Edebiyatı','Şiir','Sabri Günaydın']::text[], 8.5, '{"poet":"Sabri Günaydın","poet_slug":"sabri-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hersey-biterken-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğlence İşçisi', 'eglence-i-scisi-fatih-taskin-7f2lq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dışarıdan bakınca ebem kuşağını andırıyordu

İçerisi ise kurt kapanlarıyla  doluydu

Bu hayat başka bir hayattı

Kural nizam intizam hiç birşey yoktu..

Burada küsülmüş kaderler,terk edilmiş aşklar

Yalancı hayatlar ve her türlü sahtekarlıklar vardı..

Eğlenenlerden para kazanan, jilet yaralarıyla 

hayata asılan,kanayan gönülleriyle perişan insanlar vardı..

Burası :                                                                                                                    Pekçok insan için eğlence yeri,                                                                      Yeni aşıkların  buluşma  günü,

Çoçukların ise hayaliydi..

Oradakiler için ise; gurbet yeri, umut tacirliği,

Ve bol para gelmesiydi....

Yaşam ne garip değilmi.? 

Sen para verip eğlenirken 

Seni eğlendiren dertli, ızdıraplarla dolu.

Hatta  psikopat...

Ama senin için ne önemi var....

Eğlence olsun da 

Kim eğlendirirse eğlendirsin......

İşte bende böyle bi gün:

Döner dolaba binip gülümseyen,

çocuğun saflığıyla asıldım hayata...

Babasının ona gelecek için duyduğu umutla,

bağlanmak istedim kara yazılı yazıma....

Annesinin aman bişey olmasın diye duyduğu,

heyecanla karşı koydum bütün zorluklara..

Onlar eğlenirken ben içimden ağladım..

Ben içimden ağladıkça yüreğimi dağladım... 

Yaşam çok farklıydı burada,demir parmaklıklar ardında; 

Ne polis,ne jandarma,ne vali değildi bunun farkında..

Rüşvetlerle  halledilirdi bütün iş,tüm riyakarlığıyla; 

Yalan çoktan gerçek olmuş,gerçek zaten kaybolmuştu...

Evden kaçan,anasını - babasını kesen,

Cinayetten çıkan; askerden kaçan  ve

Esrarı sigara gibi içenlerin yeriydi....

Burası:

Senin eğlence yerin;  seni 

eğlendirenlerin ise acıyan gönülleriydi....

Buradaki demirlerin paslanması gibi,

paslandı ömürleri...

iltihaplanırdı o pasla kanayan yaraları..

Ama onlara; 

Mutluluk,sağlık,para yoktu bu hayatta

Gelecek kaygısı hiç taşımıyorlardı  nasılsa

Çünkü; 

Bilmiyorlardı aile yaşantısını..

Baba şefkati,anne kucağı hiç 

olmadı geçmişlerinde

Onlar için hep bügün,bu an vardı.

Yarın hiç yoktu düşüncelerinde....

Belki de... belki de çoktan unutmuşlardı

Anne  ve babasının isimlerini bile

Dedim ya; 

Burası:

Senin için eğlence yeri; 

Onlar için ise gönüllerinin yanan mahşeri...

Yaz güneşinin altında sarılırlardı sökmek için demire

Kamyonlarla taşırlardı,bir şehirden bir şehire

Gittikleri yerlere yaralarınıda,acılarınıda 

yanlarından ayırmazlardı....

Aşkı sevdayı belki hiç tatmamışlardı...

Belki de onları bu yollara atan vefasız aşklarıydı.

Sevginin anlamını ömür boyu yaşamamışlardı..

Kimseye yan gözle bakmaz,kendileriyleydi kavgaları

Ama onlar harbi delikanlılardı.

Dedim ya:

Ben senin için eğlence işçisi; 

sen benim için ekmek teknesi...

Yaşıtlarım okul sıralarında dirsek çürütürken

Ben geleceğimi manevila yapıp,altına takoz koyardım

Onlar yaşamlarını okuyarak,tahsille kurarlarken

Ben alınterimi civatanın üzerine akıtırdım.

Hep kavuşurlardı düşledikleri hayatlara

Ben düş bile kuramazdım olmayan yarınımla...

Dedim ya:

Ben senin için eğlence işçisi; 

Sen benim için basit bir müşteri..

Dedim ya: 

Burası senin için eğlence yeri; 

Benim ise gönlümün yanan ateşi...

Burası çocukların pembe hayali; 

Benim için ise gülümsemenin sahtesi....

Burası  aşıkların buluşma buluşma yeri; 

Benim için ise hayatın ihaneti......

Burası....

Burası...

Lunapark.......

Siyah bereli

temmuz.....? ? ? ?', 'Dışarıdan bakınca ebem kuşağını andırıyordu İçerisi ise kurt kapanlarıyla  doluydu Bu hayat başka bir hayattı Kural nizam intizam hiç birşey...', ARRAY['Türk Edebiyatı','Şiir','Fatih Taşkın']::text[], 8.5, '{"poet":"Fatih Taşkın","poet_slug":"fatih-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":89,"source_url":"https://www.antoloji.com/eglence-iscisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Gözlüm', 'kara-gozlum-sabri-gunaydin-1qze8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '23.07.2004,18:30

                            

Kara sevdaya daldım seninle

Meğer aşk ne garip duyguymuş

Önce sevdadan kaçar idim

Meğer aşktan kaçış yokmuş.

Yıldızlarda uçtum, yüreğini gördüm

Hülyalara daldım seninle

Gülmez idim çağlar oldum

Yüreğimi verdim ellerine

Aşkın beni yakar durur

Gözlerin sinemden vurur

Bırakıp gitmen sonum olur

Bu yürek sensiz nasıl durur.', '23.07.2004,18:30                              Kara sevdaya daldım seninle Meğer aşk ne garip duyguymuş Önce sevdadan kaçar idim Meğer aşktan...', ARRAY['Türk Edebiyatı','Şiir','Sabri Günaydın']::text[], 8.5, '{"poet":"Sabri Günaydın","poet_slug":"sabri-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kara-gozlum-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Kolaymış', 'ne-kolaymis-sabri-gunaydin-vxv2k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Meğer unutması ne  kolaymış

Canım diyenler unuttu usta,

Bir zamanlar onlara inanmıştım

Hepsi teker teker bıraktı usta

Hepsini canıma kazımıştım

Hepsi canımı yaktı usta,

Yüreğimi ayaklarına sermiştim

Yüreğimi ezip geçtiler usta

Küçücük dünyamı yıktılar

Yüreğimi yıkamadılar usta,

Bir sen kaldın vefalı dost,birde yalnızlığım

Sende bırakıp gitme usta

Kimim var ki şu yalan dünya da

Bir anam, bir de sen usta

Tek gerçek var, gerisi hep yalan

Bir Allah, bir sevgim usta.

Bir yarim vardı,birde sevdam

Onu da yaşatmadılar usta,

Yüreğimi ateşlerde yaktılar

Yinede yılmadım usta

Sevgim düzene yenik düştü

Bu, ne kahpe felek usta

Şimdi bir canım kaldı, oda yorgun

Yine sevmekten bıkmadım usta.', 'Meğer unutması ne  kolaymış Canım diyenler unuttu usta, Bir zamanlar onlara inanmıştım Hepsi teker teker bıraktı usta Hepsini canıma kazımış...', ARRAY['Türk Edebiyatı','Şiir','Sabri Günaydın']::text[], 8.5, '{"poet":"Sabri Günaydın","poet_slug":"sabri-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ne-kolaymis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahte Sevgiler', 'sahte-sevgiler-sabri-gunaydin-ejcjp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '27,04,1999

Yağmur yağıyor yine  bir nisan akşamında

Maziye dalıyorum Yağmura aldırmadan

Aklımdan sahte sevgiler geçiyor

Seni arıyor gözlerim attığım her adımda.

Neden geceler bu kadar boş, sevgiler neden sahte,

Bakışlar bile anlamsız aşklar can çekişmekte

Neden gözler hep yaşlı, gönüllerse virane

Dile tabire sığmaz şu figan sitem etsem aleme.

Nefret ediyorum artık,şu  paslanmış sahte kalpten,

Anlamsızca yaşıyorum ne yaptığımı bilmeden  

Sesiz bir sonsuza gidiyoruz aldırmadan hayata

Yaşayan bir ölüyüz şu anlamsız dünyada.', '27,04,1999 Yağmur yağıyor yine  bir nisan akşamında Maziye dalıyorum Yağmura aldırmadan Aklımdan sahte sevgiler geçiyor Seni arıyor gözlerim...', ARRAY['Türk Edebiyatı','Şiir','Sabri Günaydın']::text[], 8.5, '{"poet":"Sabri Günaydın","poet_slug":"sabri-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sahte-sevgiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Mecburum', 'sana-mecburum-sabri-gunaydin-rpgr2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana mecburum  güzelim 

Bunu sen bilemezsin

Vuslat kadar yakınım sana 

İstesende  göremezsin.

Varlığın varlığımı incitir

Aşkın beni eritir, bitirir

Seninle cehennemede gidilir

Olmasan yanımda candan bile geçilir.

Ecel kadar seviyorum seni

Bunu herkes öğrensin

Aşkından ölürsem eğer

Tanrı beni affetsin.', 'Sana mecburum  güzelim  Bunu sen bilemezsin Vuslat kadar yakınım sana  İstesende  göremezsin. Varlığın varlığımı incitir Aşkın beni eritir, ...', ARRAY['Türk Edebiyatı','Şiir','Sabri Günaydın']::text[], 8.5, '{"poet":"Sabri Günaydın","poet_slug":"sabri-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sana-mecburum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgim Ecelin Olacak', 'sevgim-ecelin-olacak-sabri-gunaydin-7nmgl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgim ecelin  olacak

Boğulacaksın sevgimle

Ardından meleklerim ağlayacak

Yalvaracaklar ölme diye

Ölmek bana zevk verir,sana acı

Bana huzur verir sana korku

Yaşarsan dünyadaki o karanlık zulmü

Dünyayı yıkarım sakın unutma 

Dünyadaki tek sevgi sende

Gerisi hep yalan hep sahte

Ağlatırlarsa seni günün birinde 

Dünya yıkılır  sakın unutma

Gariplerin sevdası gibi safsın sen

Karanlıklar içindeki aksın sen

Yaşamamın tek sebebisin sen

Sen ölürsen bende ölürüm unutma', 'Sevgim ecelin  olacak Boğulacaksın sevgimle Ardından meleklerim ağlayacak Yalvaracaklar ölme diye Ölmek bana zevk verir,sana acı Bana huzur ...', ARRAY['Türk Edebiyatı','Şiir','Sabri Günaydın']::text[], 8.5, '{"poet":"Sabri Günaydın","poet_slug":"sabri-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevgim-ecelin-olacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutursun', 'unutursun-sabri-gunaydin-8npr0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Unutursun her şeyi, 

Sevdanı da  zamanla,

Hayat her acıyı öğretir

Ağlamak çare değil.

Unutursun gülmeyi

Başka çaren kalmaz

Yüreğin kan ağlar

Kimse derdine yanmaz.

Ölümlerden geçersin 

İnsanları tanırsın

Yaşamayı öğrenirsin

Kahpelikler içinde

Hayat mecbur eder 

Unutmaya ve unutulmaya

Hain yaşam kavgasında

Yok olup kaybolmaya.', 'Unutursun her şeyi,  Sevdanı da  zamanla, Hayat her acıyı öğretir Ağlamak çare değil. Unutursun gülmeyi Başka çaren kalmaz Yüreğin kan ağlar...', ARRAY['Türk Edebiyatı','Şiir','Sabri Günaydın']::text[], 8.5, '{"poet":"Sabri Günaydın","poet_slug":"sabri-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/unutursun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atatürk''ü Anarken', 'ataturk-u-anarken-sabri-gunaydin-aou0k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O dehşetli sabahta

Yer yerinden oynadı,

Türk’ün vatan sevgisi

Göğü bile ağlattı.

O dehşetli savaşta,

Şimşekler çaktı gökyüzünde.

Hedefimiz zaferdi 

Uğrunda ölsek bile.

Atamın yüzünde sevinç

Ağlıyordu sevgiyle

Ya zafer ya ölüm 

Milletimin süngüsünde.

Düşman serseme döndü 

Türk’ün vatan sevgisiyle

Ay ve yıldız birleşti

Topraktaki kan ile.', 'O dehşetli sabahta Yer yerinden oynadı, Türk’ün vatan sevgisi Göğü bile ağlattı. O dehşetli savaşta, Şimşekler çaktı gökyüzünde. Hedefimiz z...', ARRAY['Türk Edebiyatı','Şiir','Sabri Günaydın']::text[], 8.5, '{"poet":"Sabri Günaydın","poet_slug":"sabri-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ataturk-u-anarken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Garip Dünya', 'bir-garip-dunya-sabri-gunaydin-7507x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hani vardır ya dara düşersin ara sıra

Bundan bir türlü kurtulamazsın

İçinde sitem yatar

Ölesiye haykıramazsın

Sonra ağlarsın çaresizlikten

İçindeki dert seni yer

Aşina bir yüz ararsın sonra

Ama kimseyi bulamazsın.

Sonra bir çıkış arasın

Sokakların o zifiri karanlığında

Her seferinde sona yaklaşırsın

Ama hiçbir zaman varamazsın.

İşte böyle gariptir dünya

Çoğu zaman acı çekersin

Çoğu zaman ağlarsın

Mutluluk sana haram gibidir

Hep derdinle yanarsın.', 'Hani vardır ya dara düşersin ara sıra Bundan bir türlü kurtulamazsın İçinde sitem yatar Ölesiye haykıramazsın Sonra ağlarsın çaresizlikten İ...', ARRAY['Türk Edebiyatı','Şiir','Sabri Günaydın']::text[], 8.5, '{"poet":"Sabri Günaydın","poet_slug":"sabri-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-garip-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygular Mahkum', 'duygular-mahkum-sabri-gunaydin-4d53z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Duygularınızı  zindanlara attınız

Terk ettiniz bilerek yalnızlığa

Yalnızlığı da sevdanınız sandınız

Utandınız sevginizi söylemeye

Kaçırdınız gözlerinden gözlerinizi

Belkide sevdadan korktunuz

Açıkça söylemek varken her şeyi

Siz hayallerle avundunuz.

Mahkum ettiniz duyguları

Hayatın pembe yüzüne aldandınız

Doyasıya yaşamak varken sevdayı

O sevdikçe siz kaçtınız.', 'Duygularınızı  zindanlara attınız Terk ettiniz bilerek yalnızlığa Yalnızlığı da sevdanınız sandınız Utandınız sevginizi söylemeye Kaçırdınız...', ARRAY['Türk Edebiyatı','Şiir','Sabri Günaydın']::text[], 8.5, '{"poet":"Sabri Günaydın","poet_slug":"sabri-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/duygular-mahkum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-sabri-gunaydin-udlwc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Görünce bilinmezlerde kaybolurum

Derin bir uçurum  sanki gözlerin

Her bakışta yeniden vurulurum                     

Karanlık bir ölüm sanki gözlerin.

Gözlerim gözlerine vurgun

Yüreğim çoktandır esarette                          

Bedenim yangınlara mahkum 

Yüreğimi gömdüm gözlerine.', 'Görünce bilinmezlerde kaybolurum Derin bir uçurum  sanki gözlerin Her bakışta yeniden vurulurum                      Karanlık bir ölüm sanki...', ARRAY['Türk Edebiyatı','Şiir','Sabri Günaydın']::text[], 8.5, '{"poet":"Sabri Günaydın","poet_slug":"sabri-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gozlerin-112-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Sevda Bu', 'i-ste-sevda-bu-sabri-gunaydin-c2lhr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '(30,11,2002)

Hani vardır yas özlemezsin bir türlü

İşte, bu adamın içini yer

Kahr olursun, yüreğin ağlar

Her şeyi düşünürsün o an

Aklından ölüm bile geçer

Ama ne yapacağını bilemezsin

Ağlarsın içli içli haline 

Sonra mecnun olursun düşersin sokaklara

Haline herkes güler, acıyanlarda çıkar arada

Avare gibi gezersin, yırtık kirli eşyalarla 

Kabuslar dostun olur, sokaklar arkadaşın

Herkes seni dışlar, hatta anan bile

İşte buna dayanamazsın

Canından geçersin sevda uğruna 

Sokaklar ağlar ardından 

Kabuslarda kaybolursun.

İşte sevda bu dostum 

Ağlatır, yıkar adamı

Yıllar sonra hatırlanmazsın bile

Sevdiklerin unutur gider adını.', '(30,11,2002) Hani vardır yas özlemezsin bir türlü İşte, bu adamın içini yer Kahr olursun, yüreğin ağlar Her şeyi düşünürsün o an Aklından öl...', ARRAY['Türk Edebiyatı','Şiir','Sabri Günaydın']::text[], 8.5, '{"poet":"Sabri Günaydın","poet_slug":"sabri-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/iste-sevda-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Neden Gittin', 'neden-gittin-nurten-altinok-stkkp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öyle olsun hadi git 

Korkular pes etti zavallı karanlığımda 

Mum ışığında 

Kanadı kırık bir pervane 

Yalnızlığımı yazıyor gözyaşlarıyla 

Ayak sesleri besteleniyor 

Anahtar çevirmelerinde 

Kapı eşiğinde çöküp kalmışım 

..............SEN Mİ GELDİN

Dilimde bir şiir dualaşmış: 

..............'''' kapım çalınsa sen gelsen 

................kim o demeden açsam 

................boylu boyunca içeri girsen 

................sana sıcacık sıcacık sarılsam '''' 

Sokak başlarında köpek ulumaları 

Boş arsada kedilerin mart kutlamaları, hala devam ediyor 

Başı boş sarhoşların  TAŞ'' a tuttuğu 

Oynaşıyor 

Köşe başı cilvesi 

Bekçi, ağzında düdük 

Sesi, gecede büyük bir delik 

Her düdük sesinde balkona çıkıyorum 

...................SEN Mİ GELDİN

............’'' tövbeler tövbesi 

...............yemin ediyorum 

...............bir daha kimseyi sevmeyeceğim 

...............peki ama 

...............o zaman ben 

...............kimi özleyeceğim '''' 

Yıldızlardan utanıyorum 

Sessiz tanık 

Göz kırpmalarından 

Karanlık ayıbımı örtüyor 

Gittin 

Olması gereken en son şeydi oysa bu 

Nasıl yaptın 

Neden 

...............'''' tek tek her damarıma yazdım adını 

.................mim koydum 

.................her nabızda sen atıyorsun 

.................her atışta ben yaşıyorum 

.................zehir zemberek '''' 

Bakışlarım dondu sesini duyunca 

O kadar uzaktan ve derin:

-''''BENİ BEKLEME''''

Ağlamaklı sesime karıştı sesin

Kulaklarım çınladı 

Kalbimde yerin 

Yandı,

Yankılandı...

Ellerimde çaresizliğin teri 

Birden susuverdi karanlığın elleri 

Karanlığın elleri YAĞMUR  kadar küçük değil 

-''''GELEMEZDİM'''' 

Yığılıp kalmışım 

Bulutlar siper oldu yıldızlara 

Sesler seslere karıştı 

Bir kadının çığlığı 

Dudak boyasında yakalandı 

Sağa sola koşturdu 

Kediler, köpekler, yarasalar 

Hemcinslerinin peşinde 

Karanlığın elleri çelik bir yumruk 

- ''''ÖZÜR DİLERİM ''''

Gittin! 

Sen gittin, 

Yollar gitti...

Sen gittin,

Zaman gitti... 

Bir şeyler bitti içimde 

Tarifi yok 

Bir şeyler eridi 

Yok oldu tükendi 

Acıdım! ! ! 

Yapma be gülüm 

Gülüm 

Yapma... 

Kokun sinmiş yastığıma 

Duvarlara gölgen 

Aynadan söküp atamadığım yüzün 

Sabun köpüğünde hala elinin teri

Oda oda seni aradım umut dolu 

Ta en köşelerine kadar yatak altlarında 

Ne sen vardın 

Ne senden kalan bir şey geri 

Ne de dudağının izi

Keşke yıkamasaydım o su içtiğin bardağı 

Kahve fincanını 

Yemek yediğin tabağı 

Keşke yıkamasaydım 

Keşke...

Sıyrılırcasına bir düşten 

Kaçıyorum 

Kaçıyorum bu şehirden 

Gittin! 

Olması gereken en son şeydi oysa bu...

En son şey! ...

En son...

En...', 'Öyle olsun hadi git  Korkular pes etti zavallı karanlığımda  Mum ışığında  Kanadı kırık bir pervane  Yalnızlığımı yazıyor gözyaşlarıyla  Aya...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":99,"source_url":"https://www.antoloji.com/neden-gittin-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kolay mı Güzelim', 'kolay-mi-guzelim-sabri-gunaydin-quj3m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni unutmak kolay mı güzelim

Alışkanlık yaparım damarlarında

Ben olmayınca yaşayamazsın

Ararsın beni rüyalarda.

Gözlerinin karasında ararsın beni

Hiç sevmediğin kabuslarda

O zaman belki bulursun 

Maziyle kavrulmuş sevdalarda.

Söylemiştim güzelim

Söylemiştim yanarsın diye

Beni gömdüğün gözlerinle

Gün gelir ağlarsın diye.', 'Beni unutmak kolay mı güzelim Alışkanlık yaparım damarlarında Ben olmayınca yaşayamazsın Ararsın beni rüyalarda. Gözlerinin karasında ararsı...', ARRAY['Türk Edebiyatı','Şiir','Sabri Günaydın']::text[], 8.5, '{"poet":"Sabri Günaydın","poet_slug":"sabri-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kolay-mi-guzelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Değer', 'sana-deger-sabri-gunaydin-h5flb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beni mahfet güzelim 

Parçalarıma böl teker teker

Kahret beni sözlerinle

Seni sevmiyorum diyerek.

Bana acı çektir

Ölümüm gittikçe zorlaşsın

Tam öleceğim vakit

Kıyamam çünkü orda sen varsın.

Sen yoksan yanımda her şey orda biter

Gerisi hep palavra, hep gam, tasa, keder

Yokya canıma verdiğin en ufak bir değer

Olsun be güzelim sana her şey değer.', 'Beni mahfet güzelim  Parçalarıma böl teker teker Kahret beni sözlerinle Seni sevmiyorum diyerek. Bana acı çektir Ölümüm gittikçe zorlaşsın T...', ARRAY['Türk Edebiyatı','Şiir','Sabri Günaydın']::text[], 8.5, '{"poet":"Sabri Günaydın","poet_slug":"sabri-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sana-deger-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Dedikleri', 'sevda-dedikleri-sabri-gunaydin-nunyf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevda bu değil bebeğim

Birkaç iyi söz, biraz tebessüm, birazda kahkaha

Sevdayı gün gelecek öğreneceksin

Canını yoluna koyuyorsan, sevdayı sende bileceksin.

Gerektiğinde ezeceksin gerektiğinde güleceksin

Canını feda edip 

Uğrunda zevkle öleceksin

Servetini sereceksin, ruhunu vereceksin

Gözlerinin içine bakıp

Tebessüm bekleyeceksin, sevgi dileneceksin.

Dağları deleceksin.

Çöllerden geçeceksin.

Aşık olduğun zaman

Sende sevgi isteyeceksin.

O zaman belki anlayacaksın

Beni ve uğruna yaptıklarımı…', 'Sevda bu değil bebeğim Birkaç iyi söz, biraz tebessüm, birazda kahkaha Sevdayı gün gelecek öğreneceksin Canını yoluna koyuyorsan, sevdayı se...', ARRAY['Türk Edebiyatı','Şiir','Sabri Günaydın']::text[], 8.5, '{"poet":"Sabri Günaydın","poet_slug":"sabri-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevda-dedikleri-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'sona Ermeden', 'sona-ermeden-sabri-gunaydin-z8obw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Duygularım boğulmuş sayenizde 

Sevmekten bile tat almıyor artık

Umutlarım kararmış yüreğinizde                     

Ölmekten bile korkmuyor artık.

Her şeyin sonu gelmiş gibi

Aldırmıyoruz hiçbir şeye                                    

Sıradan yaşıyoruz hayatı

Biteceğini bile bile.

Kıymet bilmiyoruz bitmeden 

Anlayamıyoruz değerlerini                                

Sevdiğimizi bile söyleyemiyoruz

Her şey sona ermeden.', 'Duygularım boğulmuş sayenizde  Sevmekten bile tat almıyor artık Umutlarım kararmış yüreğinizde                      Ölmekten bile korkmuyor ...', ARRAY['Türk Edebiyatı','Şiir','Sabri Günaydın']::text[], 8.5, '{"poet":"Sabri Günaydın","poet_slug":"sabri-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sona-ermeden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biyolojik aşk..!', 'biyolojik-ask-metin-yildirim-rz1sc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Göz, gördü,

Kalp, sürdü,

Biyoloji terse döndü….

Sen, hücredeki hareket,

Damardaki kan….

Ben sadece bir iskelet,

Organları taşıyan…..

Kapanır dünyaya duyarga,

Uçar gönül,

Boşalır aşiyan……

Bir tebessümün,

En tatlı besin,

Bir dokunuşta kemik eritirsin…..

Solusam ciğerimdeki oksijen; 

Terk edişinde ise; 

En illet kansersin…..! 

Eklem donar; 

Beyni felç edersin…….

Adını koyamadım bir türlü; 

Sen….Nesin……? 

Bir küsersin; 

Biyolojimi katledersin…..

Ayrılık dersin; 

Sindiremez sistem, 

Dengeleri alt üst edersin,

Gevşer bütün kaslar,

Kalp kasına; 

Güç, yetiremezsin…..

Hormon olur düşersin; 

Büyüdükçe ben,

Yok olurum sende….

Sinir sistemim emrinde,

Biyolojime hükmedersin….. 

Dokularım çözülür,

Sen, nasıl bir şeysin…….? 

Sana bürünür organizma,

Damara neşter atsan, 

Akıp gidersin……..

Ayrılık dersin; 

Tek hücreliyim zaten…..! 

….……...Onu da öldür….! 

…………….…….Sen bitersin…...!', 'Göz, gördü, Kalp, sürdü, Biyoloji terse döndü…. Sen, hücredeki hareket, Damardaki kan…. Ben sadece bir iskelet, Organları taşıyan….. Kapanır...', ARRAY['Türk Edebiyatı','Şiir','Metin Yıldırım']::text[], 8.5, '{"poet":"Metin Yıldırım","poet_slug":"metin-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/biyolojik-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan Sevgi', 'yalan-sevgi-sabri-gunaydin-ev9qv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir dakika güzelim

Birkaç damla sahte yaş

Biraz ağıt birazda feryatla

Aşkı bu kadar indirgeyemezsin.

Gerçekten sevmiş olsan 

Ölmeyi düşünürsün bir an

Bir an cesaretlenirsin

Ama sevgin gelir aklına

Hayattan geçemezsin.', 'Bir dakika güzelim Birkaç damla sahte yaş Biraz ağıt birazda feryatla Aşkı bu kadar indirgeyemezsin. Gerçekten sevmiş olsan  Ölmeyi düşünürs...', ARRAY['Türk Edebiyatı','Şiir','Sabri Günaydın']::text[], 8.5, '{"poet":"Sabri Günaydın","poet_slug":"sabri-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yalan-sevgi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Ele Verir Aynalar!', 'seni-ele-verir-aynalar-omer-demir-4wzp0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Of aynalar of! 

Yıllardan sonra 

Seni ele verir aynalar 

Yüzündeki o derin hatlar 

Ve yılların yorgunluğunu anlatan o çukurlar 

Seni ele verir... 

O zaman içinden kayar derin bir “of” 

Ve kendi kendine söylene durursun; 

“aslında her şey farklı olabilirdi” 

“farklı yaşayabilirdim” diye... 

ama seni ele verir aynalar. 

Of aynalar of! 

Yıllardan sonra 

Seni ele verir aynalar 

Saçındaki şu aklar 

Yüreğin yorgun, titrer ayaklar 

Yaşamda tükenince heyecanlar 

Seni ele verir aynalar 

Ve ardına baktığında; 

Geride bırakılmış sadece yürekteki yaralar 

Ve hala içinde kaynayan yapamadıkların 

Ve ömrünün yetmediği planlar... 

O zaman içinden geçer; 

Ve kendi kendine mırıldanırsın; 

“aslında her şey farklı olabilirdi” 

“ben farklı yaşayabilirdim” diye... 

ama seni ele verir aynalar! 

Of aynalar of! 

Seni ele verir aynalar... 

İçinde kanar 

Yüreğindeki şu derin yaralar 

Yetişemediğin şu zaman fırtınası 

Akar gözpınarlarından 

Her damlasında bir acı gizli, 

Bir yara kanar... 

Ama seni ele verir aynalar. 

Gözlerinin içi artık gülmez 

Ve yorgun yorgun bakarsın bir boşluğa 

Anlam veremediğin şu yaşamın ardından 

İşte o zaman 

Seni ele verir aynalar; 

Ve ansızın dilinden dökülür bir-iki satır; 

“aslında her şey farklı olabilirdi” 

“ben farklı yaşayabilirdim” diye... 

ama seni ele verir aynalar. 

Of aynalar of! 

Bir ömrün ardından 

Seni ele verir aynalar 

Kamburlaşan omuzların 

Ve yere hafifçe deyen şu titrek ayakların 

İçindeki umutsuzluğun, 

Yaşayamadığın yaşamının itirafçısı olur 

Yere bakan yorgun gözlerin 

Kaybettiğin sevdanın habercisi olur 

Ve yalnızlık 

Soğuk bir nefes gibi hep seni bulur 

İçinde gezer; 

Uykularını böler 

Ve seni ele verir aynalar 

İşte o zaman; 

Gözlerinden akar iki soğuk damla, 

Yapamadıklarını anımsatırcasına 

İşte o zaman; 

Dilinden sökülür iki cümle, 

“aslında her şey farklı olabilirdi” 

“ben farklı yaşayabilirdim” diye... 

ama seni ele verir aynalar. 

2004-05-10', 'Of aynalar of!  Yıllardan sonra  Seni ele verir aynalar  Yüzündeki o derin hatlar  Ve yılların yorgunluğunu anlatan o çukurlar  Seni ele ver...', ARRAY['Türk Edebiyatı','Şiir','Ömer Demir']::text[], 8.5, '{"poet":"Ömer Demir","poet_slug":"omer-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/seni-ele-verir-aynalar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pes Ettim!', 'pes-ettim-nazife-abayli-lgu2u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana,

''Seni daha fazla sevmeden git..! '' demiştim.

''Nereye? '' dediğinde,

Bu kadar çabuk gideceğini,

Düşünmemiştim.

Gittin....

Gittin ama! 

Ben pes ettim!', 'Sana, ''Seni daha fazla sevmeden git..! '' demiştim. ''Nereye? '' dediğinde, Bu kadar çabuk gideceğini, Düşünmemiştim. Gittin.... Gittin ama!  B...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/pes-ettim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Taşıyacağım?', 'nasil-tasiyacagim-nazife-abayli-5tedl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni tanıyana kadar,

Aşk acısını,

Bir tek ben yaşıyorum,

Yalnızlığı,

Sadece ben tadıyorum sanırdım.

......................................................

Kendi yükümü kaldıramazken,

Şimdi her ikisini birden,

Nasıl taşıyacağım?', 'Seni tanıyana kadar, Aşk acısını, Bir tek ben yaşıyorum, Yalnızlığı, Sadece ben tadıyorum sanırdım. ...........................................', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/nasil-tasiyacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayamadım Ardından.!', 'aglayamadim-ardindan-nazife-abayli-3ylar', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seslendin,ses verdim.

Çağırdın geldim.

Sevdalıydı gönlün,

Dinledikçe dertlendim.

Yaralarının kanına bulandım,

Doldu gözlerim.

Yalnızlığına ortak ister gibi,

Bakışlarından yüreklendim..

Doyasıya sarılıp sana,

Ben olayım diyemedim..

Gitmekti niyetin,

Daha en başından.

Şimdi bir gül soldu,

Düştü dalından.

Ümidim kalmadı,

Sensiz yarınlardan.

Veda ederken uzaktan uzağa,

Buğulu camından,

İki damla yaş döküp,

Ağlayamadım ardından..!', 'Seslendin,ses verdim. Çağırdın geldim. Sevdalıydı gönlün, Dinledikçe dertlendim. Yaralarının kanına bulandım, Doldu gözlerim. Yalnızlığına o...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aglayamadim-ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SEVGi SEFER', 'sevgi-sefer-cihan-altay-aygkv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seferim var sevgiye susamis gonullere,

Ab-i Hayat cesmesi gonlumde akar benim.

Insan olmayan insan, anlamaz sozlerimi.

Insan olan, sozumden alir hayat dersini...

Insanoglu fanidir, kalicidir sevgiler,

Baslara tac edilir tek, riyasiz ovguler.

Deger bulur, olursa karsilikli duygular,

Yok eger olmaz ise, yitirilir umutlar...

Size dost nasihati, cok sevin insanlari,

Kimse kusursuz degil, vardir kotu yanlari,

Duyun gonlumdeki su ASK ASK vuran canlari,

Askin tarifi olmaz, bunlar SEVGi HALLERi...

                                     07.01.1999 - BALIKESIR', 'Seferim var sevgiye susamis gonullere, Ab-i Hayat cesmesi gonlumde akar benim. Insan olmayan insan, anlamaz sozlerimi. Insan olan, sozumden ...', ARRAY['Türk Edebiyatı','Şiir','Cihan Altay']::text[], 8.5, '{"poet":"Cihan Altay","poet_slug":"cihan-altay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevgi-sefer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
