INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alsam Taaa Yüreğime Seni', 'alsam-taaa-yuregime-seni-ali-osman-yilmaz-ijn96', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sarılsam sımsıkı sana,

Alsam taaa yüreğime seni,

Bir daha bırakmasam,

Benim gözlerimden baksan,

Aşka,sevgiye,hayata,bana,

Çıkıp geliversen şimdi,

Giriversen yüreğimden içeri,

Kapatsam ardından gözlerimi,

Bir daha açılmamacasına,

Sonsuza kadar bırakmasam,

O küçücük,güzel ellerini.', 'Sarılsam sımsıkı sana, Alsam taaa yüreğime seni, Bir daha bırakmasam, Benim gözlerimden baksan, Aşka,sevgiye,hayata,bana, Çıkıp geliversen ş...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/alsam-taaa-yuregime-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonuna dek,Sonuma Dek', 'sonuna-dek-sonuma-dek-ali-osman-yilmaz-1k9o8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Benim için,

Bir düştün.

Öyle bir düştün,ki,

Yüreğimden yerlere,

Peşinden yüreğim de,

Gitti yad ellere.

Şimdi gelsen geriye,

Çalsan kapımı yine,

Alsam seni yüreğime,

Bir daha aşık olsak,

Mutluluk vaad etsek,

Yeniden bir birimize,

Sonuna dek,Sonuma dek,

Yani sonsuza dek,

İkimiz,birbirimize.', 'Benim için, Bir düştün. Öyle bir düştün,ki, Yüreğimden yerlere, Peşinden yüreğim de, Gitti yad ellere. Şimdi gelsen geriye, Çalsan kapımı yi...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sonuna-dek-sonuma-dek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarına Gebe Kadın', 'yarina-gebe-kadin-ali-osman-yilmaz-r0eru', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güneşe aşık doğa,

Yağmura hasret ağaç,

Yarına gebe kadın,

Aşk için savaşan erler,

Sevda şarkısı söyler,

Kızıl güle,bülbüller.

Açar yaprağını ağaç,

Yeşillenir çimenler,

Açar kırmızı güller,

Dillenir yine bülbüller.

Hazan mevsimi gelir,

Sararan yapraklar,

Bir bir dökülürler.

Ezilir teknede üzümler,

Yeni aşklara sunulur,

Hayyam’dan öğütle,

Şarap dolu kadehler.', 'Güneşe aşık doğa, Yağmura hasret ağaç, Yarına gebe kadın, Aşk için savaşan erler, Sevda şarkısı söyler, Kızıl güle,bülbüller. Açar yaprağını...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yarina-gebe-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşüme Düşmeni, Düşlerim', 'dusume-dusmeni-duslerim-ali-osman-yilmaz-wiqjc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana mektup yazarken,

Kalemin ucu kırıldı,

Seni sevdiğimi yazarken,

Kalem bile sana darıldı.

Gece yıldızların altında,

Oturuyorum köşedeki parkta,

Dalmışken geçmişin anılarına,

Canlandı birden düşlerim,

Seninle yan yana bu parkta,

Oturup seviştiğimiz,

O geceleri düşlerim.

Başını omzuma dayadığın,

Sarı saçlarını okşadığım,

Gözlerinin maviliklerinde,

Enginlere daldığım,

Yıldızlı geceleri düşlerim.

Sensiz yaşamak zor,

Her gün,her gece,

Divane gezer,düşlerim,

Yalnız geçen gecelerimde,

Düşüme girmeni düşlerim.', 'Sana mektup yazarken, Kalemin ucu kırıldı, Seni sevdiğimi yazarken, Kalem bile sana darıldı. Gece yıldızların altında, Oturuyorum köşedeki p...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dusume-dusmeni-duslerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Düştün Düşüme', 'neden-dustun-dusume-ali-osman-yilmaz-gybfj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sarı saçlarını,

Ellerimle ördüm,

Aşkına ihanet eden,

Bir vefasız sevgili,

Ben seni gördüm.

Kabuslar içindeyim,,

Neden düştün düşüme? 

Tüm kapıları kapattım,

Sen girmeyesin diye,

Ne yaptım da girdin? 

Uykularımda düşüme.', 'Sarı saçlarını, Ellerimle ördüm, Aşkına ihanet eden, Bir vefasız sevgili, Ben seni gördüm. Kabuslar içindeyim,, Neden düştün düşüme?  Tüm ka...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/neden-dustun-dusume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müstehcen Şiir', 'mustehcen-siir-metin-yalti-lqqdg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'giysilerini hep kırmızılardan al

salınıp gezdiğinde savrulsun al, al

gülümse, öpücükleri gamzelerinden al

sev insanları, iyi kötü ayırmadan

beni de sev hep yanımda kal

sevmezsen beni almazsan beni

bir stadyum dolusunca 

al sana al,al,al...

83 AliSamiYen', 'giysilerini hep kırmızılardan al salınıp gezdiğinde savrulsun al, al gülümse, öpücükleri gamzelerinden al sev insanları, iyi kötü ayırmadan ...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mustehcen-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beşinci Cemre', 'besinci-cemre-umut-gungor-igzii', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne olur tut şu kalbimi düşecek,

Gönül mevsimim hasretinle bitecek,

Yüreğe hasretinin cemreleri inecek,

Beşinci cemremiz düşmek üzere.

Elim kolum tutmaz oldu nicedir,

Uykuyu unuttum onca gecedir,

Sevgi gönüllere inen hecedir,

Beşinci cemremiz gelmek üzere.

Beşinci cemremiz girdi sıraya,

Kızlar haber salsın şimdi sılaya,

Getirmedik hiç onu kolaya,

Bu sevgiyi aşkı görüpte geldi.', 'Ne olur tut şu kalbimi düşecek, Gönül mevsimim hasretinle bitecek, Yüreğe hasretinin cemreleri inecek, Beşinci cemremiz düşmek üzere. Elim k...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/besinci-cemre-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardeleni ben buldum', 'kardeleni-ben-buldum-umut-gungor-86fj0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kardeleni ben buldum aramayınız,

Hüzünle saçları taramayınız,

Söylüyorum merakta kalmayınız,

Seven yüreklere ilettim bile.

Sevmeyen yüreklere derilemez,

Çok değerlidir kolay serilemez,

Narindir her ele verilemez,

Seven kalplere ilettim bile.

Sevenleri karda bile bırakmaz,

Zaten kıştan başka mevsimde açmaz,

Asla sevmekten sevilmekten kaçmaz,

Sevenler çiçeksiz kalmasın diye.

Sevenlere sırdaş olur yaprağı,

Sıcacık sarmalar onu toprağı,

Sevenler tutsun sevgi bayrağı,

Seven yüreklere ilettim bile.', 'Kardeleni ben buldum aramayınız, Hüzünle saçları taramayınız, Söylüyorum merakta kalmayınız, Seven yüreklere ilettim bile. Sevmeyen yürekler...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kardeleni-ben-buldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz hayat', 'sensiz-hayat-umut-gungor-ejih7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kırdın dallarımı açmadı çiçek,

Gönül hazanını nasıl biçecek,

Sensiz şimdi günüm nasıl geçecek,

Gündüzüm kış oldu geceler ayaz.

Sensiz hayatım hep zindan oluyor,

Zavallı gönlüme hazan doluyor,

Diktiğimiz güller bir bir soluyor,

Fırtınada kaldı bedenim benim.

Rüzgarlar savurdu kıyıya attı,

Bulutlar ruhumu yağmura kattı,

Gözüm kaşım bile hep bana çattı,

Sensiz günlerim azapla dolu.', 'Kırdın dallarımı açmadı çiçek, Gönül hazanını nasıl biçecek, Sensiz şimdi günüm nasıl geçecek, Gündüzüm kış oldu geceler ayaz. Sensiz hayatı...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensiz-hayat-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorma kalbimi', 'sorma-kalbimi-umut-gungor-q861a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sorma kalbimi nerdedir diye,

Arama gereksiz yerdedir diye,

Kalbim sende güzelim baksana,

Benden olsun kalbim sana hediye.

Gözlerim sende kalıp takıldı,

Yüreğim dururmu hemen atıldı,

Ben sendeyim güzelim baksana,

Yüreğim beynim sana takıldı.

Ayaklarım durdu eller biçare,

Düşünmede haydi bul bir çare,

Beni bende hiç sorma güzelim,

Dillerim lal oldu konuşamamki.

Yüreğim durmuşta kalbim atıyor,

Kirpiklerin kaşlarıma çatıyor,

Şu güneşte hala neden batmıyor,

Geceye kızacağım gelmiyor diye.', 'Sorma kalbimi nerdedir diye, Arama gereksiz yerdedir diye, Kalbim sende güzelim baksana, Benden olsun kalbim sana hediye. Gözlerim sende kal...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sorma-kalbimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Özledim', 'seni-ozledim-ali-gencay-33o4e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biliyor musun? 

Seni gerçekten sevdim

Yangınlarım

Yıllanmışlığım

Sigaram 

çayımda dudak payım

Geceye gizlediğim düşlerim

Kağıda dizdiğim şiirlerim

Hecelerim

                  Seni özledim

Biliyor musun? 

Seni gerçekten istedim

Arzularım

Avuntularım

Kıvranışlarım

Şarkılara yatırılmış kulaklarım

Bak yine terliyor avuçlarım

Sevgilim

                 Seni özledim', 'Biliyor musun?  Seni gerçekten sevdim Yangınlarım Yıllanmışlığım Sigaram  çayımda dudak payım Geceye gizlediğim düşlerim Kağıda dizdiğim şii...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seni-ozledim-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Var', 'ask-var-oguzkan-bolukbasi-lobb1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yaşamak 

hangi tarifte

ve hangi tarihte

sensiz

yaşamak oldu

yine de çelişki

hayat mı güzel 

sen mi

var oluşum tercihim mi

sensiz yaşamaya alışmak

mümkün mü

derken

o gözleri bir başka güzele

yazılan şiirdeki sen

sen değilsin

ben 

ben değilim

ben kimim

sen kimsin

ne sen var

ne de ben

aşk var', 'yaşamak  hangi tarifte ve hangi tarihte sensiz yaşamak oldu yine de çelişki hayat mı güzel  sen mi var oluşum tercihim mi sensiz yaşamaya al...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ask-var-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deprem Şurası', 'deprem-surasi-hafize-zuluflu-26p9q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şöyle bir görünüp gittiğinden beri

Hasretin zehir gibi

Her gün vurdu yüreğimi

Dün kaç kez aradım

Telefonun ulaşılamazdı

O anda güneş söndü

Gözlerim karardı

Uyandı Kuzey Anadolu Fay hattı

Başladı bütün şehirde

Tarifsiz bir sallantı

Rihter ölçeğine göre

Haftadan daha büyük

Şiddetli bir sarsıntı

Her yerim kırık dökük

Yokluğunun enkazında

Ağır yaralandım

Hadi

Kurulsun hemen kriz masası

Acil toplansın

Deprem şurası', 'Şöyle bir görünüp gittiğinden beri Hasretin zehir gibi Her gün vurdu yüreğimi Dün kaç kez aradım Telefonun ulaşılamazdı O anda güneş söndü G...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/deprem-surasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahretsin', 'kahretsin-hikmet-yakisir-1u631', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu sabah yine bendesin.

Bende olmadığın an yok ki.

Ama bu sabah bir başka bendesin.

Nesin sen? 

Nasıl olurda hep bendesin? 

Kanatlı bir melek mi? 

Sihirli bir değnek mi? 

Yoksa uçan bir kelebek mi? 

Kahretsin...

Bu sabah bir başka bendesin

Hangi yöne baksam karşımda gözlerin,

Neye el atsam avucumda ellerin,

Dokunduğum her yerde tenin.

Düşünüyorum beynimde sen,

Dalıyorum gözlerimde sen,

Yazıyorum şiirlerimde sen,

Yaşıyorum kalbimde bir ok gibi yine sen.

Sen...sen...sen.

Kahretsin...

Bu sabah bir başka bendesin.

Çayımın deminde,

Kahvemin telvesinde.

Sigaramın dumanında,

Kadehteki rakıda

Dinlediğim şarkıda,

Her yanımda,

Her adımda,

Her anımda,

Bir başka çarpıyor kalbim bu sabah.

Kahretsin...

Bu sabah bir başka bendesin.

27 Temmuz 2004', 'Bu sabah yine bendesin. Bende olmadığın an yok ki. Ama bu sabah bir başka bendesin. Nesin sen?  Nasıl olurda hep bendesin?  Kanatlı bir mele...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Yakışır']::text[], 8.5, '{"poet":"Hikmet Yakışır","poet_slug":"hikmet-yakisir","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kahretsin-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemine özlem', 'ozlemine-ozlem-burhan-kucuk-vb10k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Özlemine özlem

Sensizliğe akarım

Gecenin koynunda

Buğulanır gözlerim

Önüne geldiğinde

Boşluğa sarılırım

Sarılır gibi sana

Yokluğunu anlarım

Kollarım boş kalınca 

Gölgen gezinir odamda

Ben peşinde pervane

Sabah uyandığımda

Kokun hala odamda

Burhan KÜÇÜK

Kdz.Ereğli-28.07.2004', 'Özlemine özlem Sensizliğe akarım Gecenin koynunda Buğulanır gözlerim Önüne geldiğinde Boşluğa sarılırım Sarılır gibi sana Yokluğunu anlarım ...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ozlemine-ozlem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak', 'sokak-aynur-baydar-gyx0q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Özlüyorum yaprak arası sızan güneşi 

Avluya vuran gölgecikleri

Bahçede koşup oynamaktan 

Yerlere düşüp, kanayan dizlerimi

Sokak başında babamın işten dönüşünü beklemeyi

Görünce taaa uzaklardan deli koşup

Kocaman elinden tutarak sürüklercesine eve götürmeyi

Kokuları evlerden gelen mis gibi yemekleri

Can havli arkadaşlarımı şikayet etmeyi 

Bahçede gördüğüm kertenkeleyi

Abimin kırdığı cam haberlerini bir solukta söylemeyi

Avluda komşularla kurulan ortak sofraları

Büyükler yerken, sevinçten sağa sola koşmayı

Komşu teyzenin mahalleyi çınlatan kahkahalarını

Mısır püsküllerini örüp, kara tokalarla saçıma tutturmasını

Sarı peliklerimi neşeyle sallayıp, herkese göstermeyi

Eve gelen misafir kadınların topuklu pabuçlarıyla sokağa fırlamayı

Annemin delicesine peşimden koşmalarını

Hatta hatta abimin ayağına ip bağlı kargaları üstüme salmasını

Avaz avaz cıyak cıyak bağırmayı

Arı sokmalarını, zonklayan parmağıma sürülen çamuru ve annemin kucağına sığınmayı

Ablaların makyaj malzemeleriyle palyaço gibi boyanmayı

Büyüklerin gülüşmeleri arasında salınmayı

Özledim bahçemi, özledim masumiyeti 

Çocuk gibi çocukları

Komşunun üzüntüsünü paylaşmayı 

Muradı olanların sevinç sofralarını

Otobüslerle çalgı çengi piknikleri

Attığım çığlıklarla 

Nadide hanım teyzenin namazını bozmayı

Babamla berbere gitmeyi 

Mis kokulu traş sabunundan burnuma sürmeyi

Ramazan için yapılan yufka dağlarını, bayram baklavalarını

Güneşte bekleyen salça kaplarını 

Güzine de pişen patatesleri, kiremitte balıkları

Evde yapılan sucuk ve tarhanaları

Acıktım mı ne? 

Sade ben değil, cümleten acıktık

İnsanı insan yapan değerlere

Paylaşmaya, hoşgörüye, sevgiye ve iyi niyete', 'Özlüyorum yaprak arası sızan güneşi  Avluya vuran gölgecikleri Bahçede koşup oynamaktan  Yerlere düşüp, kanayan dizlerimi Sokak başında baba...', ARRAY['Türk Edebiyatı','Şiir','Aynur Baydar']::text[], 8.5, '{"poet":"Aynur Baydar","poet_slug":"aynur-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sokak-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zararsız', 'zararsiz-burak-killioglu-rbd9h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sıcacık bir akşam sahile inerken

Ve mevsimlerden hala buruk bir yaz iken

Yaşadığım anın anlamsızlığına teslimim.

Halbuki en sevdiğim mevsimdir yaz

Pırıl pırıl bir güneş, masmavi bir deniz

İçimi titreten ayaz

Yalnızca sen olursun.

Burum buram sıcakta ter boşanırken

Vücudumdan

Ve ben her sabah ümidimi kuşanırken

Ruhumdan

Kararsız kalırım birden

Sorarım kendime aniden

Bu gidiş nereye? 

Bu bekleyiş niye? 

Bulamam cevapları

Hataları ve sevapları ile birlikte 

Geçer bir ömür

Geçer zamansız

Beni sorarsan, ben yine kararsız

Hiç korkmana gerek yok

Bir o kadar da zararsız.', 'Sıcacık bir akşam sahile inerken Ve mevsimlerden hala buruk bir yaz iken Yaşadığım anın anlamsızlığına teslimim. Halbuki en sevdiğim mevsimd...', ARRAY['Türk Edebiyatı','Şiir','Burak Kıllıoğlu']::text[], 8.5, '{"poet":"Burak Kıllıoğlu","poet_slug":"burak-killioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/zararsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüme Gidiş', 'olume-gidis-i-nan-alver-qzi1o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir bakta maziye hatırla beni

Unuttuğun köşede gel bul beni

Mavi derinliklerin olmadan

Tut elimi sar beni

Yağmura kızarım

Alır teninin kokusunu benden

Gündüze kızarım

Alır hayallerini benden

Ya gitmesen,Ya beni öldürmesen,

Uzun gecelerde beni özlesen,

Geçmiş bugün olsa,

Bugünlerim hep senle dolsa..

Unutma beni sevdiğim

Sensin tek özlediğim

Ölüme giderken,bilki; 

Yanlız seni seveceğim', 'Bir bakta maziye hatırla beni Unuttuğun köşede gel bul beni Mavi derinliklerin olmadan Tut elimi sar beni Yağmura kızarım Alır teninin kokus...', ARRAY['Türk Edebiyatı','Şiir','İnan Alver']::text[], 8.5, '{"poet":"İnan Alver","poet_slug":"i-nan-alver","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olume-gidis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk Kahvesi', 'turk-kahvesi-aynur-baydar-8dfc2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Taze ve güzelse, mis gibi kokutur ortalığı, açılınca kabının kapağı

Kahveyi tutmak gerek 

Ağzı sımsıkı kapalı, kokusu çıkmamalı

Güzelliğini misliğini kıymet bilene sunmalı

Anlamayanı sadece dışından cam kabından bakanı 

Hepsini eşit tutanı, renkleri aynı, tazesi bayatı

Kahve atılır cezveye tepeleme iki çay kaşığı 

Bazen şekeri arkadaşı

Kimisi sade sever, kimi orta, kimi şekerli

Tazeyse ve kıvamında pişirilirse 

Şekeri fark etmez, seçkin tadı değişmez

Cezvede kahve ve şeker 

Bunların üstüne bir fincan ölçü soğuk su ister

Karıştır ağır ateş de 

Sakın acele etme güzel sonuç için biraz sabırla bekle

Öyle su döker dökmez 

Çamur rengine bakıp yüzünü buruşturma az bekle

Malzemeler mükemmel, bak gör o çamur renk ne güzelliğe dönecek

Az kabardı sinirlendi 

Silip atma belki haklı bir nedeni var aslında

Kahve bu politik olamaz, sen beğen diye istediğin rengi anında alamaz

Sabır az daha sabır, bak gördün mü güzelliği, rengi mis kokusu taaa nerelere gitti

Bu arada fincanını da ısıt, dökülünce şaşalamasın, uyumu azalmasın, ıvırıp kıvıramaz,

Samimiyetsiz buz ortamlara uyum sağlayamaz.

Cezvesine sığmıyor, gelişiyor büyüyor, üst katını al, dök sıcacık fincanına, yer aç geride kalanlara

Bekleme kıvamına gelenleri, olgunlaşıp pişenleri hemen uygun yerine dökmeli, fincanına yerleştirmeli

Bir yudum su iç hazırla lezzete kendini, 

İşte kültür zevki, derin sohbetlerin yari durma keyiflen hadi.

Bayatsa malzemen 

Sıcak suyla pişireyim, soğuk fincana dökeyim, taşırayım acele edeyim.

Sonunda ay bu niye köpürmedi, bundan bir şey olmazdı kötüydü zaten

A ziyankar beceriksiz, ne istersin bir kahvenin bile kıymetini bilmeyen

Sana yakışmaz kalite nefaset kültür

Çorba çanağı sıcak suya, at içine granürü karıştır 

Al sana kahve oldu bitti bu işte

Telve su hepsi homojen, nasılsa miden götürür her türünü

İçilmeyecek kısım telve fark etmez, ayırımın yok iyi kötü

Kalite, kalite ister ancak alt yapı, kültür kültürü bekler

Kırk yıl hatırı olur elbet bir fincan kahvenin 

Kıvamında kahve sevgi, sabır değer bilme

Hırsına kıskançlığına cezve sıcağı gibi yanmağa, zamanında gem vuran

Gördüğü iyiliği sıcacık, ömür boyu hatırlayan, fincanını ısıtan

Kabaran öfkesini cezveden boşaltıp atan

Sözünde hareketinde saygı ve sevgisinde sabırlı ölçülü kıvamı tutturan, hayatı lezzetli kılan

Selam size, bilinsin kıymetiniz ömrünüzce saygı bin kere hakkınız

Serilsin hep önünüze, tüm kahve sevenlere…', 'Taze ve güzelse, mis gibi kokutur ortalığı, açılınca kabının kapağı Kahveyi tutmak gerek  Ağzı sımsıkı kapalı, kokusu çıkmamalı Güzelliğini ...', ARRAY['Türk Edebiyatı','Şiir','Aynur Baydar']::text[], 8.5, '{"poet":"Aynur Baydar","poet_slug":"aynur-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/turk-kahvesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar', 'kar-aynur-baydar-lksph', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gökte savrulup dönen 

Zaman zaman yön değiştiren

Ne tarafından çekiştirse de 

İstediği şekli veremeyen

Yere düşmekten kurtulamayan 

Bir kar tanesiyim ben... 

Rüzgara kapılıp hızla uçmak

Yada ağır aksak serseri dolaşmak

Olmuyor olmuyor 

Düşüyorum çaresiz sessiz

Ne yapsam boş 

Her kaçış 

Yeryüzüne biraz daha yaklaşmak

Yok olmak nihayet 

Yok olmak sonsuzluk

Mantık plan boşluk 

Gerçek tek... 

O da yokluk

Var olma çabası 

Daha çok yaklaştırmakta hiçliği

Kaçınılmaz son 

Yapışmak toprağa... 

Erimek umutsuzca

Etrafım benden gayrı 

Dolu sayısız karlarla

Herkes başına buyruk güya 

Özgür gibi ufuklarda

Hikaye bu

Aldatmaca

Nihayet toprakta 

Her kar zanneder 

Varlığı hep sürecek

Ancak görebildiğinde anlar 

Toprakça emilecek

Sanki önceden bilse 

Gerçeğini değiştirebilecek.

Hızla sertçe savrul 

İster gelin misali uysal süzül

Varılacak  son nokta 

Toprak sonuçta

Taneciğim, taneciksin, taneciksiniz

Anladım anlayın 

Kendini çığ gören

Her şeyi 

Gümbür gümbür ezeceğini

Zanneden...

Minnacık bir kar tanesisin sen', 'Gökte savrulup dönen  Zaman zaman yön değiştiren Ne tarafından çekiştirse de  İstediği şekli veremeyen Yere düşmekten kurtulamayan  Bir kar ...', ARRAY['Türk Edebiyatı','Şiir','Aynur Baydar']::text[], 8.5, '{"poet":"Aynur Baydar","poet_slug":"aynur-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/kar-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilaram', 'dilaram-aynur-baydar-q4hv6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Masalların  gerçek olmasını istiyorum, 

Gerçek olmalı masallar

Mutlaka, bir gün mutlaka 

İyiler kötüleri yenmeli

Çocuklar benim çocukluğumdaki gibi 

İnanmalı masallara

İnanmalı ki 

Düşene el uzatsın 

Haksız güce özenmesin, zayıfı ezmesin.

Öğrenmeli 

Asıl gücün doğrudan gelen güç olduğuna 

Zayıftan ve haklıdan yana olanına

Haksız ejderin ateşinde

Dimdik durmalı 

Minik karınca olsa bile

Kül olacağını bile bile

Emeksiz, bilgisiz makama güce özenmemeli 

Tiksinmeli, hor görmeli ejderi

Saygı duymalı minik karıncaya 

Onun ulvi, yanmış kül olmuş makamına

Bilmeli, öğretmeli ona 

Kula kul olmayan canın

Sonsuza kadar süren köle candan onurlu olduğuna.

Bir kez 

Sadece bir kez, insanın can sahibi olduğuna

Onunda yalakalıkla 

Rahatlık adına ayaklar altına alınamayacağına

Bebeğim DİLARAM son sözüm sana…

Gerçekler gerçek kadar gerçek

Yalanlar yalan 

Masalda da hayatta da

Bil ki işte o zaman hesap tamam 

Hem canda, hem sonsuzlukta

Annen hakkını helal eder sana

Kuzusu ejderin karşısında 

Dimdik minik bir karınca olmuşsa.', 'Masalların  gerçek olmasını istiyorum,  Gerçek olmalı masallar Mutlaka, bir gün mutlaka  İyiler kötüleri yenmeli Çocuklar benim çocukluğumda...', ARRAY['Türk Edebiyatı','Şiir','Aynur Baydar']::text[], 8.5, '{"poet":"Aynur Baydar","poet_slug":"aynur-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/dilaram-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Sıcağının Buzuda Yeter', 'bana-sicaginin-buzuda-yeter-murat-demir-abnxc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İndi perdeleri hayat sahnemin

Yanarken ocağı söndü hanemin

Sevdası bol olsun elin alemin

Bana gidişinin izide yeter

Ne resim isterim ne de hatıra

Boynum kıldan ince vursa satıra

Aksın gözlerimden yaş sıra sıra

Bana mendil denen bezide yeter

İstemem arayıp sormasın kimse

Ben buyum adıma deli de dense

Taşıdığım bu can onun içinse

Bana ayağının tozuda yeter

Kalsada yüreğim dertte hicranda

Hasreti işkence olsada canda

Ecel döşeğine düştüğüm anda

Bana sıcağının buzuda yeter

Ağlasam sızlasam ölsem of demem

Gayrısından asla aman dilemem

Yeter ki hoş olsun fazla istemem

Bana sevgisinin azıda yeter', 'İndi perdeleri hayat sahnemin Yanarken ocağı söndü hanemin Sevdası bol olsun elin alemin Bana gidişinin izide yeter Ne resim isterim ne de h...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bana-sicaginin-buzuda-yeter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost', 'dost-aynur-baydar-x1sck', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sessiz ortalık... 

Çökük omuzlu birkaç adam, birde imam

Hınca hınç kalabalık yok, 

Çelenkler, kara gözlüklüler

Ağlaşmalar, taziyeler, methiyeler.

Musalla da bir garip, sessiz kişi, 

Sonsuz yolculuğa çıkmış belli

İmamın nasıl bilirdiniz sorusu bile, cansız

Cılız cemaatin üç beşi, 

İyi bilirdik dedi 

Haklarını ÖYLESİNE helal etti.

Alındı garip kişi, çökük omuzlar birden dikleşti

O da ne Yarabbi 

Yer gök cıvıl cıvıl kuş sesi

Cılız cemaatin ayak sesi... 

Sanki evliyalar ordusu geldi

Cami avlusunda uyuklayan köpekler 

Ürkerek çekildiler.

Başladı gökyüzü usul usul ilahiye

Toprak saldı miski amberini her yere

Ağaçlar en güzel yapraklarını döktüler 

Geçerken garibe

Yeryüzünde kelebekler bile değil 

Bu güzellikte

Gökkuşağı belirdi sonsuz renkli... 

Cemaat şaşkın, imam şaşkın

Kimdi bu garip deli, 

Mahallenin eğlencesi

Kimse bilmez neydi, kimlerdendi.

Kabristana girdiklerinde 

Sanki koca selviler eğildi.

Kazmak zor olmadı kara toprağı 

Yumuşacık pudraydı

Yarini koynuna almak için sabırsızlanan bir sevgili

Tabut açılıp... 

Garip kişi ele alınmadı 

Ağırlıksız süzüldü gitti.

Sonsuzluk yari

Şefkatle içine buyur etti

Onlar mı toprak attı, 

Yoksa kabir aniden kapandı…

Hiç biri anlamadı hatırlamadı

Kabirden ayrılırken 

İmam ve birkaç kişi... 

Hepsi sessiz ağlamaklı.

Konuşmağa cesaret edilmedi

Belki de sözcüklerin geçmediği 

Farklı bir boyuta girildi

Kimisi bu bir hayaldi, 

Kimisi rüyadayım dedi

Hepsinin ortak düşüncesi

Acıyıp kızdıkları, 

Hatta tiksindikleri, itip kaktıkları zavallı

Gözlerinin önünde, 

Bedbah görünen ömrüyle 

Nasıl bu makamı kazandı

Garip deli  DOSTTU... 

Ömür boyu belli olmadı, anlaşılmadı

Bilerek bilmeyerek saklandı.

Nefes bitti... 

Dosta kavuşma vakti geldi

Kuşlar, toprak, ağaç, gökyüzü gizleyemedi

Saygısını, sevgisini

Sessizlerin alkışlarıyla 

Gerçek saltanatla dostuna gitti.', 'Sessiz ortalık...  Çökük omuzlu birkaç adam, birde imam Hınca hınç kalabalık yok,  Çelenkler, kara gözlüklüler Ağlaşmalar, taziyeler, methiy...', ARRAY['Türk Edebiyatı','Şiir','Aynur Baydar']::text[], 8.5, '{"poet":"Aynur Baydar","poet_slug":"aynur-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/dost-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özür /Çanakkale Aslanlarına', 'ozur-canakkale-aslanlarina-aynur-baydar-mgdk9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yeryüzünde var mı böyle bir şey

Sırtlanmış top mermisini gidiyor

Mantık akıl bilim

Hiç bir şey söyleyemiyor

Sevgin bu kadar büyükse 

İnancın yüceyse 

Yazarsın tarihi dev yüreğinle

Eloğlu açıklasın bakalım bunu teknolojisiyle

Siperden başını çıkardığı an 

Öleceğini bile bile 

Emri aldığında... 

Yağmur kurşunlar karşısında 

Süngüsü elinde

Tereddütsüz şehadet şerbetini içenlere....

Anaları saçlarını kınalayıp 

Kuzularını göndermiş cepheye 

On beşinde

Amaç ya şehit ya gaziyse... 

Yazarsın tarihi minik bedenin dev yüreğinle

Daha on yedi, on sekizinde

Tıbbiye o yıl bir mezun vermese de

İstanbul lisesi 

Sarı rengine karayı katsa da 

Mezuniyet zamanı öğrencilerine

Diploma yerine, bir fatiha sunsa da

Yazarsın tarihi körpecik bedenin, dev yüreğinle

Üşüsen de açlıktan ölsen de 

Çarığını ağzına alıp çiğnesen de

Yazarsın tarihi dev yüreğinle

Kara toprak olmuş ıslak kızıl... 

Doymuyor hep kan içiyor.

Bağrında yatanlar 

Bu bizim toprağımız 

Bu bizim halkımız mı diyor

Özür layık olamadığımız aslanlara

Özür Çanakkale geçilmezi yazanlara

                             43-ncü Alay 1-nci P. Tb. 1-nci Bölük

1917 YILI YEMEK LİSTESİ

GÜN         SABAH                        ÖĞLE             AKŞAM                       EKMEK

15HAZ     ÜZÜM HOŞAFI	         YOK              YAĞLI  BUĞDAY      TAM 

26HAZ      YOK  	                           YOK             ÜZÜM  HOŞAFI      TAM			 

18TEM    ÜZÜM HOŞAFI                 YOK               YOK	              YARIM				

8AĞUS   YARIM EKMEK         YOK                 ŞEKERSİZ ÜZÜM HOŞAFI

          

 NOT: 21 TEMMUZ 1917''DEN İTİBAREN BAŞLAYARAK ORDU EMRİYLE EKMEK İSTİHKAKI 500 GRAMA İNDİRİLMİŞTİR. ÇÜNKÜ UN VE EKMEK KALMAMIŞTIR.', 'Yeryüzünde var mı böyle bir şey Sırtlanmış top mermisini gidiyor Mantık akıl bilim Hiç bir şey söyleyemiyor Sevgin bu kadar büyükse  İnancın...', ARRAY['Türk Edebiyatı','Şiir','Aynur Baydar']::text[], 8.5, '{"poet":"Aynur Baydar","poet_slug":"aynur-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/ozur-canakkale-aslanlarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık IV', 'ayrilik-iv-orcun-oruc-aykac-n60t2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Akıp dolar akşam üstü 

Kızıl bir ışık odanın içine.

Ne kadar kapatsan da perdeleri

Sevgili girer içeri.

Düşünür, düşünürsün.

Gece olur 

Ve yalnızlık ağarır ansızın…

Kızıl artık odanı kaplayan kandır.

Akar damla damla gözlerinden

Kuruyup teninde kalır gözyaşı gibi.', 'Akıp dolar akşam üstü  Kızıl bir ışık odanın içine. Ne kadar kapatsan da perdeleri Sevgili girer içeri. Düşünür, düşünürsün. Gece olur  Ve y...', ARRAY['Türk Edebiyatı','Şiir','Orçun Oruç Aykaç']::text[], 8.5, '{"poet":"Orçun Oruç Aykaç","poet_slug":"orcun-oruc-aykac","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ayrilik-iv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cam Lekeleri', 'cam-lekeleri-aynur-baydar-cm932', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Camdaki lekeler saydam

Tıpkı kötülerin yüreklerini 

Kendilerinden saklayamadığı

Dıştan huzur maskeli görünseler de

Camda ki pis karalar gibi

İnsanoğlu hata yapar elde olmasa da

Art niyet yoksa, minik ellerin camdaki izi

Sevimli mi sevimli

Bu leke silinmez kalır süs misali

Camdaki yağmur izleri inci inci

Pişmanlıkların olgunlaşmanın tövbeleri

Affet affet

Kul hakkı olmayan şahsi lekeleri

Sürekli devir daim

Selam hayata lekesiz, saydam cama

Olacak elbet lekeler  izler yaşadıkça

Sonsuz ihtiras 

Kıskançlık ve kinlerin kara izleri

Yer almasın yeter ki

Başlanılan ikinci hayatta 

Camdaki izler

Olsunlar 

Kristal üzerinde ki 

Göz alıcı ışıklar, nurlar

Bu dünyada vitraylarla saklanan kara camlar

Bin bir parça, diken diken

Kanatsın kara yürekleri', 'Camdaki lekeler saydam Tıpkı kötülerin yüreklerini  Kendilerinden saklayamadığı Dıştan huzur maskeli görünseler de Camda ki pis karalar gibi...', ARRAY['Türk Edebiyatı','Şiir','Aynur Baydar']::text[], 8.5, '{"poet":"Aynur Baydar","poet_slug":"aynur-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/cam-lekeleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstedim', 'i-stedim-cafer-tayyar-ozkan-umob8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İçten içe atan çığlığımı,

Haykırıp, acı bağırışımı,

Tanrının hiç bir kulu duymadan,

Onca ağlayıp sızladığımı,

Sadece sen bilesin istedim.

Okyanusların umurunda mı? 

Minik bir balığın hıçkırığı,

Çektiğim sevdanın acısını,

Gözümden süzülen yaşlarımı,

Sadece sen silesin istedim.

Gönlümün penceresi güneşli, 

Yüreklerimizse kor ateşli,

O hayalin sürekli karşımda,

Ufka dalıp seyrederken seni,

Sadece sen göresin istedim.

Işıl gözünle bakarken bana,

Bak gönülden seslenirim sana,

Seni seviyorum anlasana,

Şu candaki ölümsüz ukdemi,

Sadece sen sevesin istedim.

Sana ah yazan elim kırılsın,

Vuslatınla bedenim yok olsun,

Seni istiyorum anlasana,

Arzunla büzülen ak yüzümü,

Sadece sen öpesin istedim.

21 Nisan 2004 Ankara.', 'İçten içe atan çığlığımı, Haykırıp, acı bağırışımı, Tanrının hiç bir kulu duymadan, Onca ağlayıp sızladığımı, Sadece sen bilesin istedim. Ok...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/istedim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık Olursun Unutursun Dünyayı', 'asik-olursun-unutursun-dunyayi-ali-i-hsan-gurpinar-w0ut8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşık olursun,

unutursun dünyayı,

yalnızca sen varsındır Aşk gezegeninin

Sevgi ülkesinde, Onu arayan.

Bütün yolların Ona çıktığı,

uçsuz bucaksız bir ülke,

ve sen her susadığında,

çeşmeden su yerine Onu içersin,

karnın açıkmaz hiç Onu düşünürken.

O ile başlayan ve bitmesini hiç istemediğin cümleler kurar,

hikaye diye Onu yazarsın kağıtlara.

Kağıtlar artar,

hikayeler uzar,

yollar uzar.

Ama sen sevmişsindir bile,

yani girmişsindir tek yönlü çıkmaz sokağa,

çıkşı Onun elinde,

Sevginse senin yüreğinde,

bazen çıkmak istersin,

başaramaz geri dönersin.

Artık zaten bir anlamı da yoktur çıkmanın,

çünkü sen,

O seni bilmese de,

O seni sevmese de,

girmişsindir Aşk adındaki girdaba,

hızlanan dönüşler,

büyüyen çöküşler içinde,

sonunda düşersin bir daha kalkmamak üzere…

Kalkmaya çalışırsın,

başaramazsın…

Gerek de yoktur zaten,

çünkü dimdik ayaktadır yüreğin,

bedenin yerde,

yüreğinse sadece Sevenlerin ulaşacağı yerde…

O yerdedir,

ve O yeri tüm Sevenler çok iyi bilir…

__________________

SEN ve sensizlik, aynı

son ve sonsuzluk gibi.

Beğendiğim bir şiir', 'Aşık olursun, unutursun dünyayı, yalnızca sen varsındır Aşk gezegeninin Sevgi ülkesinde, Onu arayan. Bütün yolların Ona çıktığı, uçsuz bucak...', ARRAY['Türk Edebiyatı','Şiir','Ali İhsan Gürpınar']::text[], 8.5, '{"poet":"Ali İhsan Gürpınar","poet_slug":"ali-i-hsan-gurpinar","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/asik-olursun-unutursun-dunyayi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutsak', 'tutsak-galip-ozdemir-pgsd0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yıldız tarlasında demlenirken

sürdüler kalbimi…

ay bulutlara saklandı,

yağmur kuşları dolandı ayaklarıma

torlara, zorlara sığındım

durulamadım..

mil çektiler gözlerime 

lâl ü zâr eylediler dilimi

ağlayamadım…

kor düştü avuçlarına babamın

sözümü bağlayamadım', 'yıldız tarlasında demlenirken sürdüler kalbimi… ay bulutlara saklandı, yağmur kuşları dolandı ayaklarıma torlara, zorlara sığındım durulamad...', ARRAY['Türk Edebiyatı','Şiir','Galip Özdemir']::text[], 8.5, '{"poet":"Galip Özdemir","poet_slug":"galip-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tutsak-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölgün Geceler', 'olgun-geceler-galip-ozdemir-e812w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'böyle dingin

       böyle ruhsuz geceler

          şâd edemez

             eşkıya gönlümü...

bir yanım

      korsan olmalı

           bir yanım harami

bir esrar içmeli gözlerim

ve yakmalı ellerimi 

      bir efsun

          bir acemi

kudurmalı kanım...', 'böyle dingin        böyle ruhsuz geceler           şâd edemez              eşkıya gönlümü... bir yanım       korsan olmalı            bir ya...', ARRAY['Türk Edebiyatı','Şiir','Galip Özdemir']::text[], 8.5, '{"poet":"Galip Özdemir","poet_slug":"galip-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olgun-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan Söyle', 'yalan-soyle-aynur-baydar-2a2lx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kırılıp döküldüğümde... 

Parçalarımı topla

Düştüğümde... 

Tut elimden kaldır.

Güvenmeliyim... 

Yaslanmalıyım sana.

Yoksan bile varım de

Kandır beni yalan söyle.

Senin niyetine toplanayım 

Yerden doğrulayım

Varlığını düşünmek 

Destek olsun bana

Zannetme... 

Bir an bile düşme şüpheye

Hayatımdaki önemde, öncelikte... 

Asla olamazsın ikide.

Varsın, var olmalısın 

Dik durayım

Abartma değil gerçek 

Yoksan içi boş bir çuvalım

Mecbur değilim 

Bana ne demek hakkın

Öyle olsa bile

Lütfen... 

Alıştıra alıştıra söyle

Gerçi... 

Bunun alışması nasıl olur? 

Bilmem

Öğrenmekte istemem

Geç dersen alıştırmayı

En iyisi hayalime 

Duvarlara söyle

Yalan söyle 

Kandır aldat

Çoktan razıyım... 

Varlığıma sebep 

Yalanlarını dinlemeye

Olmasan bile varım de

İçinden hoşça kal derken

Döneceğini söyle

Yalan söyle.', 'Kırılıp döküldüğümde...  Parçalarımı topla Düştüğümde...  Tut elimden kaldır. Güvenmeliyim...  Yaslanmalıyım sana. Yoksan bile varım de Kand...', ARRAY['Türk Edebiyatı','Şiir','Aynur Baydar']::text[], 8.5, '{"poet":"Aynur Baydar","poet_slug":"aynur-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/yalan-soyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak Kedisi', 'sokak-kedisi-aynur-baydar-4k9td', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ev kedisi ayrılır ikiye

Cins olanlar güzel ve akıllıdır

Birde sokak kedisi soyundan gelme şans gülmüş yüzüne 

Terfi etmiş ev kediliğine olanlar vardır

Ev kedilerinin ortak özellikleri

Dövülmeyip sevilmeleri, hazır aşlarının önlerine gelmesi

Terk dertleri arsızca sürekli hep ilgi, sevgi beklemeleri

Gelelim sokak kedisine 

Çöpte buldukları yemekleri, bir an önce kaptırmadan yemeli

Ay bide köpek gelirse, çocuk tekmelerse

Çok dikkat etmeli, hayatta kalabilmeli

Her tehlikeyi düşünüp tetik de beklemeli

Bir anlık gafletinde canı elinden gitmemeli

Analık işte yavruları da ölmemeli

Kaçtı, kaçtı kötülerden olmadı can için

Tırnaklarını çıkarmalı, oda düşmanlarına 

Köşeye sıkıştığında cırmık atmalı

Aptal, düşünemeyen sokak kedileri hayatta kalamaz

Sokak kedileri zorlukların sonucu akıllı ve çalışkan olmalı

Ufacık bir pisi pisiye kanıp, kuyruğa teneke bağlatmamalı

Hayatta ve işte kişiler iki çeşit kedidirler

Sahip olduğun aklın,  dayın yoksa, kişiliğin çıkara uymuyorsa olur tırnakların

Alın teri, çok çalışmak, hatasız iş yapmaksa dişlerin 

Hep mükemmel çalışmak mecburiyeti

En ufak falsoda tekme yemek tehlikesi

Açar gözlerini, beynini 

En zor zifiri karanlıkta görürsün ayna gibi

Sakın aferin bekleme gün ışığı aydınlıkta bile kör

Dayılı çıkarlı ev kedileri senin sırtından kapar ciğeri

Ah bide soyun acımasızlarca sokağa atılan cins kediden geliyorsa

Sokağın kirleri güzelliğini örtemiyorsa vah ki ne vah sana

Soysuz çirkin ev kedileri hepten kıskanıp cırmalar seni

Soylu çalışkan, akıllı sokak kedisi

Bin kere hakkın gel seveyim seni pisi pisi', 'Ev kedisi ayrılır ikiye Cins olanlar güzel ve akıllıdır Birde sokak kedisi soyundan gelme şans gülmüş yüzüne  Terfi etmiş ev kediliğine olan...', ARRAY['Türk Edebiyatı','Şiir','Aynur Baydar']::text[], 8.5, '{"poet":"Aynur Baydar","poet_slug":"aynur-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/sokak-kedisi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerime Sitemim Var', 'gozlerime-sitemim-var-zulfikar-yapar-kaleli-xsawu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

El yettikçe ahvalini sorardım

Şimdi unutulmuş izden usandım.

Ben derdim içinde derman arardım

Yüreği yakmayan közden usandım.

Postalın kopuğu koçaklanıyor

Deniz kabarınca, su aklanıyor

Hakikat arkadan bıçaklanıyor

Sohbete gücendim, sözden usandım.

Çınar gibi düşer evin direği

Korkunun bir adı işin gereği

Anaların kan ağlıyor yüreği

Görüp kızarmayan, yüzden usandım.

Hep lâf ettik, gelemedik yüz yüze

Aldandık arkadan söylenen söze

Bir gönülde iki sevda çok bize

Bire meyletmeyen özden usandım.

Geniş yaşar, dar günümü özlerim

Bilmem, dalgın dalgın neyi izlerim

''Ne durursun, ağlasana gözlerim''

Sendeki cilveden, nazdan usandım.', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' El yettikçe ahvalini sorardım Şimdi unutulmuş izden usandım. Ben derdim içinde derman ara...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gozlerime-sitemim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su geldi', 'su-geldi-zafer-zengin-etnika-9ebam', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eğrilmişim

Kavis kırılmış

Kap içinde

Kenar ilişgeni acı

Kırılmasın diye çeperler

Sarılmışlığa ne lazımsa

Ağır aksak söylenen

|| Nenni ağıt belki ||

Sırrım yok

Yazdığından beri/Gel

Kirlenme

Uzağa yapışan bakış

Gülen son kedinin de

Bıyıkları terledi

Sormalı

Kim kırkında büyür aşka

Kim kapılır heyecana

Kim günah işler

Kim gülerken dişlerini döker

Kanıyor burnu sorma

Her yol dört misal

Neresi ak

Neresi kara

Unutuyor insan vebali

Aşka sarılınca

O ki

Büyüyor kendinden habersiz

İç biçe biçe

Sessiz sessiz

Yer düşündü

Gök parelendi

Su geldi

Yüz sildi

Buruşmalar düzeldi

Can geldi

Direndi

27 Temmuz 2004 '' Yalpa üşür elinde ''', 'Eğrilmişim Kavis kırılmış Kap içinde Kenar ilişgeni acı Kırılmasın diye çeperler Sarılmışlığa ne lazımsa Ağır aksak söylenen || Nenni ağıt b...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/su-geldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olursun', 'olursun-i-smet-barlioglu-ie4mh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ardarda konuşma, ara vermeden; 

Ellere akıldan noksan olursun.

Dersen çok kısa de, çok uzatmadan,

İnsanın gözünde insan olursun.

Kusuru yüze de, arkada deme,

Namerdin malını sakın elleme,

Cahil konuşunca fazla dinleme; 

Olur ki; alışıp nadan olursun.

Kendinden gençlerle geçir gününü,

Görsünler yüzünün hep güldüğünü,

Ağırla ellerin hor gördüğünü; 

Sevilir, sayılır, handan olursun.

İki kez söylersen; sekiz kez dinle,

Başına iş açma kendi dilinle,

Gücünü övene sakın güvenme; 

Belki boş bulunur candan olursun.

Asılacak olsan bozma ahdini,

Bayrak gibi kaldır, yücelt cehdini,

Arsızla geçirme tek bir vaktini; 

Zamanla hayadan, ardan olursun.

Barlıoğlu söyler sözü tartarak,

Sohbete bal ile yağı katarak,

Yolu işaretler mumlar tutarak,

Nereye yönelsen ordan olursun.

(ERZURUM SANKİ YAYLA isimli hece şiirlerinden > 37-38/100)', 'Ardarda konuşma, ara vermeden;  Ellere akıldan noksan olursun. Dersen çok kısa de, çok uzatmadan, İnsanın gözünde insan olursun. Kusuru yüze...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/olursun-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tren', 'tren-aynur-baydar-ogc9a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Komşumuz vardı, hafif kaçık

Geçen her trene el sallardı 

Kollarını açıp açıp

Kara çerçeveli kalın camlı gözlükler

Buna ilaveten yüzünde

Kocaman gülücükler

Bir keyif, bir neşe 

Sanki düğün eğlence.

Tren geçmezken 

Uzun suratı asık 

Sessiz içine kapanık

Her birimiz gibi 

Görünürde normal sanki

Trenler geçerken 

Bir çocuk gibi neşeli

Nedense aklıma geldi birden,

Bizim komşuyu çözdüm aniden

Elbet benzetti 

Hayatı raylara

İstasyonlar ise durulması zorunlu mola

Çocukluk, okul, evlilik, iş 

Hepsi sıra sıra

Yük treni belli 

Hayatı zor geçireni

Ağır ağır katar katar 

Sesi bile az çıkar.

Yolcu treni 

Kendi görünmeden gelir sesi

Her kompartmanda vagonda...

Aynı anda 

Belki bir kahkaha, yada cenaze haberi

Bizim komşuda besbelli

İyi kötü, kin, nefret, yaş, baş 

Hepsine tren dedi.

Yaşarken ağır gelen hayatına

Trenlerle son hızla 

Son istasyonuna, sabırsızca

Yürekten heyecanla ulaşmak istedi.

Tabutu çıkarken evden...

Sanki kondüktör çaldı düdüğü

Son istasyon, yolcu kalmasın.', 'Komşumuz vardı, hafif kaçık Geçen her trene el sallardı  Kollarını açıp açıp Kara çerçeveli kalın camlı gözlükler Buna ilaveten yüzünde Koca...', ARRAY['Türk Edebiyatı','Şiir','Aynur Baydar']::text[], 8.5, '{"poet":"Aynur Baydar","poet_slug":"aynur-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/tren-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyin Göçüne Dur Diyelim', 'beyin-gocune-dur-diyelim-esin-ege-ul4qc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnsanlık tarihi kadar eski dememden kasıt sömürgecilik döneminde Afrika kıtasından Amerika ve Avrupa ya köle ticareti adı altında başlayan göç bu gün sadece şekli ve içeriği değişmiş olsa da göç yüzyıllar da geçse özde anlamını yitirmemiş ve göçmenleri göç ettikleri ülkelerde yabancı bir anlamda da  sığınmacı tiplemesinden uzaklaştıramamıştır.

Önce emek sonra beyin göçü veren ülkelerin ekonomilerine kısaca her alanda gelişmişlik düzeylerine bakacak olursak gelişmeleri göç alan ülkelerin ekonomilerinden geride kalmıştır. Durum böyle iken beyin ve emek gücüne dur diyememişlerdir.  Emek göçünün büyük dalgalar halinde yaşandığı  altmışlı yılları bizzat yaşamadığım büyüklerimizden ve yazılı kaynaklardan incelediğim üzere bir furya halinde başlayan emek göçü kendi yağınla kavrulan Türk toplumun tam ortasına öyle bir düşmüş ki belki önüne geçilmek istense de dev dalgalar halinde  büyümüş ve   kar topunun yuvarlanması ile dev bir çığa dönüşmesi şeklinde olmuştur.  O dönemde her kez için göç tek çare olmuş ve hızla büyük yığınlara ulaşarak kısa zamanda Türkiye ‘ nin tüm illerine yayılmıştır.

İlk giden kitleler yabancı ülkelerde en zor ve en çetin şartları olan hatta o ülkenin insanlarının yapmasına razı olunmayan işleri yapmışlardır. Yapmak zorunda bırakılmışlardır çünkü bir kere ev köy mal mülk satılmış ve yaban ellere gidilmiş dönülmek olmaz dönülürse köyde ki eş dost akrabaya alay konusu olmak vardı bu şartlarda başa gelen her şeye boyun eğildi ve göçün acımasız şartları ve getirileri sineye çekilerek yabanda yeni hayatlar kuruldu. İlk giden gruplar kendi örf ve adetleriyle uzun yıllar yaşadılar bir kısım kesin dönüş yaptılar halen kalanlar ve halen hayatta olanlarda yine kendi örf ve adetlerini devam ettiriyorlar ama ilk günlerdeki yaşadıkları da hatırlamak bile istemiyorlar. Onlardan ve yabanda doğan ilk yeni kuşak ebeveynleri gibi örf ve adetlere bağlı olamadılar  ama tam olarak da dışlayamadılar. Çünkü bambaşka bir dünyada bambaşka bir örf ve adetin içinde sadece anlatılarak bir şeyler verilmek istendi.

Bu ilk yabanda doğan nesil belki en zorunu yaşadı. Çünkü sadece evde anne babadan anlatılanları dinlediler; adetleri, gelenekleri,  dinlerini hep ebeveynler anlattı ve onlardan sadece böyle olunması istendi. O dönemlerde kitle iletişim  araçlarından en etkilisi olan tv  uydu yayınları yoktu. Bu çocuklar evlerde hep bunları dinlediler oysa sokağa çıktıklarında gördükleri hayatlar adetler gelenekler ve din bambaşkaydı,sonuç da iki toplum iki kültür iki din iki millet iki vatan arasına sıkışıp kaldılar.

Ben bu grubu göç den en kötü etkilenen grup diyorum çünkü doğru yada yanlış insanın bir taraf da olması farklıdır doğru yada yanlışın tam ortasında olması bambaşkadır.

İşin en entresan tarafı birinci kuşak  doğan Türkler,  Avrupa ülkelerinin hiçbir zaman hedefi olmadı. O dönemlerde Türk milletini tam olarak algılamayan Avrupa bizlere sadece emekçi gözüyle baktı,ne tam sahip çıktı ne tam ilgisiz kaldı onların amacı ilk doğan grubun çocukları yani ikinci kuşak gurbetçiler olarak tayin edildi. Çünkü sonuçta bu grup  bir şekilde Türk kültür ve tarihine dinine çok da uzak değildi, içtiği suda, yediği ekmekte,ruhunun derinliklerinde  Türk topraklarının parçaları vardı  ve bu grubu asimile etmek zor olacaktı. Bırakın bildikleri gibi yaşasınlar  mantığını güttüler ve yakın tarih de gelecek olan ikinci kuşağa kucaklarını sonuna kadar açtılar,sebep ise iki toplum arasında sıkışmış insanlar bu çocuklara hiçbir şey veremeyecek ve bu çocuklar Avrupa ruhuna çok daha çabuk asimile edilecekti. Uzan vadeye yayılmış ama kalıcı ve etkili bir yöntemdi bu.

Şimdi Avrupa ülkelerinin caddelerinde gezerken karşılaştığımız gençlerden başlarında örtüleri olmaz ise kaç tane  kızımızı  gerçek bir Avrupalı kızlardan ayırt edebiliyoruz.

Şimdi ise, sinema salonu aynı filmin ismi aynı ama konusu başka. Yine bir göç  ama bu beyin göçü.Üniversitelerde okuyan çoğunluk gencin ideali okulu bitirip Amerika ya gitmek yada ekonomik durumu iyi ailelerin çocukları eğitimlerini dışarılarda yaparak bir şekilde orada yaşama şanslarını garantilemeye alıyorlar ve artık bunlara ailelerde destek veriyor çünkü biliyorlar ki kendi ülkelerinde yaşadıkları sürece çocukları aynı yerde sayacaklar. Evini barkını satarak çoluk çocuk toparlanarak yasal yollarla Avrupa ülkelerinin yollarına düşün hatta canlarına tak edip de gayri yasal yollarla ülke sınırları dışına çıkmayı oralarda yaşamayı hatta dönmemeyi bile düşün yüzlerce aile olduğunu kabul etmek gerekir.

Bunları fazlada kınamaya hakkımız yok gibi. Hiçbir zaman sonuçları değil nedenleri araştırmamız gerekli hatta nedenleri ortadan kaldırırsak bu ve bunun gibi sonuçlara çözümler arama yoluna gitmeyiz.

Avrupa gençlerimize kucak açıyor gelin diyor okuyun diyor akademik araştırmalarınız için en iyi şartlar burada diyor. Hepinize bir bilgisayar hatta hepinize tek tek diz üstü bilgisayarı var, Korkmayın aç ve de açık da kalmazsınız bizde insan hakları var her insan dini dili fark etmez adalet önünde eşittir diyor hastalansanız size ana kucağından daha iyi bakarız sararız sarmalarız burada en değerli varlık insandır diyorlar.  Barınmayı sorun yapmayın burada koruyucu aile kurumu var sizi tek tek aile ortamı olan mekanlara yerleştiririz diyorlar. Geçmişi unutun yani ilk giden altmışlı kuşağın yaşadıklarını eleştirmeyin onlar cahil ve de eğitimsizdiler  bizler onların emeğinden faydalandık sizler aydın ve de eğitimlisiniz size ancak Avrupa istediklerinizi verebilir diyorlar. 

Uzan vadede müthiş asimile entrikaları hemde bizim gençlerimiz üzerinde. Sonuç olarak yığınlar kadar gencimiz ellerlimizin arasından yüreklerimizin içinden sessiz sedasız  değil çatır çatır kopartılarak götürülüyor. Ama yalanlarla değil hep doğrularla yapılıyor bunlar gençlere vaat edilen bütün imkanlar ne yazık ki Avrupa ülkelerinde mevcut.

Ama bu gençlere kucak açan Avrupa ülkeleri neden bu kadar peşinde koştukları gençlerin öz memleketleri olan Türkiye yi   Avrupa topluluğuna almak istemediklerini hatta kapının önünde yıllardır bekleterek yalvar yakar duruma getirdiklerini mantıklı bir şekilde açıklayabilirler mi.

Bu gençler bizim bu insan bizim, aslını inkar edene bizim toplumumuzda iyi gözle bakmazlar büyükler devlet adamlarımız öyle bir politika izlesinler ki bu vaadlerin yarısını bile olsa gençlere versinler çok veren maldan az veren candan verir bizim gencimz bunu anlayabilecek duyarlılığa sahiptir,onlar bizim aydınlık ülkemizin tertemiz beyinleri gelecek onların ellerinde şekillenecek ülkesinden kaçarcasına gitmek isteyen bu gençlerin çağdaş Türkiye ye nasıl faydası dokunsun ki, ülke yönetimine geçtiklerin de birazcık zorda kalsalar kendi menfaatlerini ülke menfaatlerinden üstün tutmazlar mı o zaman,  gençleri başı boş bırakırda beyin göçünün önüne geçemezsek işte o zaman biz o gençleri değil aslında geleceğimizi Avrupa ülkelerine vermiş olacağız çünkü unutmayalım ki bu yalnız bizim ülkemizde değil bütün dünyada gelecek gençlerin elinde inşa bulacaktır.', 'İnsanlık tarihi kadar eski dememden kasıt sömürgecilik döneminde Afrika kıtasından Amerika ve Avrupa ya köle ticareti adı altında başlayan g...', ARRAY['Türk Edebiyatı','Şiir','Esin Ege']::text[], 8.5, '{"poet":"Esin Ege","poet_slug":"esin-ege","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/beyin-gocune-dur-diyelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biter mi Bu Acılar?', 'biter-mi-bu-acilar-i-smet-barlioglu-gh57f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalbim yine yollandı seninle gurbetlere,

Bilmiyorum, biter mi yaşarken bu acılar? 

Gözyaşım yağmur gibi yine yağmak üzere,

Bilmiyorum, biter mi yaşarken bu acılar? 

Kader niçin peşimde atıyla, kılıcıyla? 

Neden beni eziyor öfkesiyle, hıncıyla? 

Alıştım yaşamaya içimdeki acıyla,

Bilmiyorum, biter mi yaşarken bu acılar? 

Yollara düşüyorum açar açmaz gözümü,

Ben yollarda tükettim bu değerli ömrümü,

Kaderim hüzne boğdu her başlayan günümü,

Bilmiyorum, biter mi yaşarken bu acılar? 

Vardıkça uzaklaşan dağlara benziyorsun,

Sanki bitmez yollarda sabrımı deniyorsun,

Ne beni bekliyorsun ne bana geliyorsun,

Bilmiyorum, biter mi yaşarken bu acılar? 

(ERZURUM SANKİ YAYLA isimli hece şiirlerinden > 39-40/100)', 'Kalbim yine yollandı seninle gurbetlere, Bilmiyorum, biter mi yaşarken bu acılar?  Gözyaşım yağmur gibi yine yağmak üzere, Bilmiyorum, biter...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/biter-mi-bu-acilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öpülmeye Değersin, Kırılsada Kalemim', 'opulmeye-degersin-kirilsada-kalemim-muammer-celik-81wbg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'öpüverdim

dokundurmadan

yanaklarından

allandı

pullandı

kızardı

utancından

kaçıverdi, 

elimde olmadan

tutundu 

dudakların kenarından

yasaktı dudakların

çürümüş vişne rengi

bulaştı kenarlarından

silinmez, 

silemez artık hiç bir şey

bu lekeyi alnından

kırsa da kalemimi

yoksun olanlar sevdadan…

BirDeli

28.07.2004', 'öpüverdim dokundurmadan yanaklarından allandı pullandı kızardı utancından kaçıverdi,  elimde olmadan tutundu  dudakların kenarından yasaktı ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/opulmeye-degersin-kirilsada-kalemim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serçe', 'serce-i-smet-barlioglu-6zua0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey serçe, güzel serçe,

Dost olalım erkekçe,

Gel ye verdiklerimi

Seyredeyim yedikçe.

Bak, doğa bembeyaz kar,

Üşür minik ayaklar,

Gel seni ısıtayım

Yüreğimde güneş var.

Güzel serçe cik, cik, cik,

Yüzün-gözün minicik,

O küçücük gagandan

Öpeyim bir kerecik.

Serçem, ben kimsesizim,

Halsizim, çaresizim,

Gel de başını yasla

Seni bekliyor dizim.

Aldırma ötesine,

Sen bedelsin hepsine,

Dayasam da ağlasam

Ben başımı göğsüne.

(Hikmet BARLIOĞLU (1933-2003)  ''nun

ERZURUM SANKİ YAYLA isimli hece şiirlerinden > 41-42/100)', 'Ey serçe, güzel serçe, Dost olalım erkekçe, Gel ye verdiklerimi Seyredeyim yedikçe. Bak, doğa bembeyaz kar, Üşür minik ayaklar, Gel seni ısı...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/serce-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Cennetten Bir Meyve Dişledim', 'cennetten-bir-meyve-disledim-necmi-unsal-26bfo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dağlarım yıkıldı.

Zirveler yerle yeknesak şimdi.

Boynuma kement takıldı.

Aşk celladı hayata imdi.

Ömrümde bir suç işledim.

Adı sevda.

Cennetten bir meyve dişledim.

Tadı sevda.

18 Haziran 2004 Cuma, Danimarka-Køge  18.39', 'Dağlarım yıkıldı. Zirveler yerle yeknesak şimdi. Boynuma kement takıldı. Aşk celladı hayata imdi. Ömrümde bir suç işledim. Adı sevda. Cennet...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/cennetten-bir-meyve-disledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günah', 'gunah-kadir-koc-jrbyp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yasaktı benim aşklarım yasak

her sefeinde gecelerde saklı ve yine 

her seferinde avucumda yandı

yasaktı bizim sevişmelerimiz tüm güzelliklere rağmen

çaresiz hepsi eskide kaldı

sadece yokluğun değil şu an elimde kalan

yanıyor anılar baş ucumda 

yanıyor avcum yanıyor cayır cayır

günahtık biz hayata, 

günah başladık 

yasak meyveyi biz yedik

yaratana inat,adem havva misali.

bilmem neyimize güvendik.

akacaktı günahlarımız parmaklarımızın ucundan

akacaktı günahlarımız avuçlarımızdan 

akcaktı günahlarımız aşkın tadına

şerbet şerbet süzülüp.

yanıyor yatak yanıyor

yanıyor avuçlarım yanıyor 

günahlar avcumda duruyor 

bir bebeğin vücudu her gece yanımda uyuyor

sonumuz nereye kadar ayrıdır bimem,

bunca günahla dua edemem

geri dön bir tanem geri dön bunca günahla ölünmez', 'yasaktı benim aşklarım yasak her sefeinde gecelerde saklı ve yine  her seferinde avucumda yandı yasaktı bizim sevişmelerimiz tüm güzellikler...', ARRAY['Türk Edebiyatı','Şiir','Kadir Koç']::text[], 8.5, '{"poet":"Kadir Koç","poet_slug":"kadir-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gunah-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masa', 'masa-i-smet-barlioglu-m3bqz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her masa bir ayrı hüzün masası,

O yüzden bambaşka devranlardayız.

Herkeste bir ayrı gönül yarası,

Engin denizlerde, ummanlardayız

Binlerce dert varken her gözyaşında

Nasıl ağarmasın saçlar başında? 

Herkes bir Mecnun ''dur Leyla peşinde,

Ondan ateşlerde, külhanlardayız.

Mahzun gönüllere gündüz gecedir,

Sohbet meneviştir, kanaviçedir,

Şarap kadehlerde pençe pençedir,

Çöllerde kaybolan kervanlardayız.

Tokuşur kadehler, ses gelir camdan,

Çirkin resmiyetler kalkar aradan,

Sohbet daha tatlı en süzme baldan,

En tatlı dillerle meydanlardayız.

Uzan bir mezeye, bir de rakıya,

Devir kadehleri arka arkaya,

Ne pula değer ver ne de hırkaya,

Martılar uçuşan limanlardayız.

Barlıoğlu der ki; ahırzamandır,

Arkadaş herşeyden daha kutsaldır,

Kaldır kadehini, şerefe kaldır,

Bir eşsiz-benzersiz zamanlardayız.

(ERZURUM SANKİ YAYLA isimli hece şiirlerinden > 43-44/100)', 'Her masa bir ayrı hüzün masası, O yüzden bambaşka devranlardayız. Herkeste bir ayrı gönül yarası, Engin denizlerde, ummanlardayız Binlerce d...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/masa-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmiyorum Desem...', 'sevmiyorum-desem-halil-kesken-94el3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu kadar sevmezdin eskiden beni

Kim derdi omzuma yaslanacaksın

Öyle sahiplendin, öyle sevdin ki

Elime taş değse kıskanacaksın

Boynuna asarsın vebalin olsam

Bağrına basarsın günahın olsam

Bu kadar sevmezdin sevabın olsam

Sanki ben olmazsam yakılacaksın

Tek yolun olmuşum, ben tek amacın

Ölüm döşeğinde en son ilacın

Dün sevmediğinken, bu gün baş tacın

Sevmiyorum desem yıkılacaksın', 'Bu kadar sevmezdin eskiden beni Kim derdi omzuma yaslanacaksın Öyle sahiplendin, öyle sevdin ki Elime taş değse kıskanacaksın Boynuna asarsı...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevmiyorum-desem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kutsal Çocukluk', 'kutsal-cocukluk-i-smet-barlioglu-l9xif', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilyelerimi verin; o kadar üzgünüm ki; 

Kutsal çocukluğuma sığınmak istiyorum.

Yaşlılıktan, ölümden öyle tedirginim ki; 

Kutsal çocukluğuma sığınmak istiyorum.

Sığınmak istiyorum o bahar günlerine,

Kırk gün-kırk gece süren masal düğünlerine,

Koşup katılmak için Kaf Dağı devlerine

Kutsal çocukluğuma sığınmak istiyorum.

Annemin saçlarımda elini gezdirdiği,

Babamın bin gururla okula yazdırdığı,

Dedemin masraf için Reşat ''lar bozdurduğu

Kutsal çocukluğuma sığınmak istiyorum.

Açıl susam, ineyim bu yaşımda o yaşa,

Uçan Halı ''ma binip varayım Padişah ''a,

Ejder kızı yemeden gideyim koşa koşa; 

Kutsal çocukluğuma sığınmak istiyorum.

Oklavadan kargımla, bezlerden kuşağımla,

Tahtadan kılıcımla, filelerden ağımla,

Altımda söğüt atım, yanımda uşağımla

Kutsal çocukluğuma sığınmak istiyorum.

Büyülü külahımla billur sarayım nerde? 

Onlara çok muhtacım bu tükenen günlerde,

Ölümü bekliyorum yaşlanmış sürgünlerde,

Kutsal çocukluğuma sığınmak istiyorum.

Lambadır okşuyorum cin yine çıksın diye,

Beni çocukluğuma alıp bıraksın diye,

O baykuşlu büyücü falıma baksın diye

Kutsal çocukluğuma sığınmak istiyorum.

Yalnızlıktan tükenmiş, bunamış bir kafayla,

Kurt Adam ''la, Vampir ''le, Firavun ''la, Mumya ''yla,

Bir Santor ''un sırtında, arkamda dolunayla

Kutsal çocukluğuma sığınmak istiyorum.

Boş odamda dolaşan Brem Çalgıcıları

Unutmak istiyorum bu derin acıları,

Verin bana cinleri, verin umacıları; 

Kutsal çocukluğuma sığınmak istiyorum.

Şimdi Kırk Haramiler sinmiştir biryerlere,

Vezirlerim çöllerde binmiştir develere,

Razıyım Kırk Satır ''ı hala tutan ellere; 

Kutsal çocukluğuma sığınmak istiyorum.

Verin ellerinizi, yaşlıları evrenin,

Hüsranı yok benimle atbaşı gidenlerin,

İnanın ki; çocukluk baştanbaşa bizlerin.

Kutsal çocukluğuma sığınmak istiyorum.

(ERZURUM SANKİ YAYLA isimli hece şiirlerinden > 48-50/100)', 'Bilyelerimi verin; o kadar üzgünüm ki;  Kutsal çocukluğuma sığınmak istiyorum. Yaşlılıktan, ölümden öyle tedirginim ki;  Kutsal çocukluğuma ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/kutsal-cocukluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Bu Halim', 'ah-bu-halim-fatih-ozkonyali-ly11o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Anlatamaz luğat çaresiz halimi, kaldım yaya,

Tutmadı bir türlü mutluluğa çaldığım maya. 

Esir düştüm, zaptetti kalemi tek başına bir er, 

Tutamadım zamanın koptu lifleri birer birer.

Yok mu şu yüreğimin surlarında açtığın yara,

Durmuyor  kanı, hekimler usandı sara sara.

“

Şimdi vakti değil” dedim, sanki söz mü dinledin,

Uyudun uyandın durmadan adımı inledin.

Kapıldım apansız, bir girdaptı, çekti beni içine,

Ayırdı canımdan bedeni, soktu başka biçime.

Şimdi söylüyorum kendime, ister ağla ister sızla,

Baştan yola çıkılmayacağı belliydi bu hayırsızla.

Ah bu halim, yine sana uykusuz geceler düştü! 

Ya anlatamadın kendini  doğruca, ya dilin sürçtü.', 'Anlatamaz luğat çaresiz halimi, kaldım yaya, Tutmadı bir türlü mutluluğa çaldığım maya.  Esir düştüm, zaptetti kalemi tek başına bir er,  Tu...', ARRAY['Türk Edebiyatı','Şiir','Fatih Özkonyalı']::text[], 8.5, '{"poet":"Fatih Özkonyalı","poet_slug":"fatih-ozkonyali","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ah-bu-halim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Psikolojik aşk..!', 'psikolojik-ask-metin-yildirim-5ezd8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Göz duyum,

Beyinde farklı bir algı,

Etkiye tepkiydi,

Kalpteki yangı...

Sendin davranış adı,

Organizmada hümanist yaklaşım…

Bilişsel yaklaşım geride kaldı,

Biyolojik yaklaşım aynı safta,

Olgu mantığı bağladı… 

Ve, aşk bacayı sardı……! 

Hislerdi dürtü,

Duygulardı güdü, 

Aşk bir ihtiyaç,

Doyum olsa bile; 

Yine çalışır bu kısır döngü...

Çünkü organizma,

Aşka kalbini sürdü… 

Duyular ona büründü,

Vız geliyor artık

Toplumsal güdü…

Aşk öğreniyorum… 

Aşka beleniyorum… 

Merhaba hayat,

Yüzüm güldü…

Seviyorum her şeyi,

Üzerimde güneşler,

Önümde sevda yürüdü… 

Varlığın adeta bir kanat,

Uçuyorum sanki,

Her şey yeniden anlam kazandı…

Bir gittin; 

Bilinç sağıldı,

Gönül  aklı çaldı,

Belleğimde aşk kaldı,

Psikolojim dağıldı... 

Ruhum yok artık; 

Zeka ve kişilik kalmadı…

Direnç bitti,

Tükenmeler başladı…

Yeteer; Aşk…..! 

Her yanı stres sardı,

Ruhum daraldı,

İmgeler dağıldı,

Depresyonlardayım, 

Çatışmalar çıktı; 

Üzerime kurşunlar yağdı…

Vuruldum, 

Yerde bir beden,

Yüreğim dağlandı,

Gözlerim, onda kaldı…

………Vefalar  yandı,

....................Tetikteki, O YÂR dı …!', 'Göz duyum, Beyinde farklı bir algı, Etkiye tepkiydi, Kalpteki yangı... Sendin davranış adı, Organizmada hümanist yaklaşım… Bilişsel yaklaşım...', ARRAY['Türk Edebiyatı','Şiir','Metin Yıldırım']::text[], 8.5, '{"poet":"Metin Yıldırım","poet_slug":"metin-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/psikolojik-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '48 Saat', '48-saat-cafer-yurtsever-xganf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tamı tamına 48 saat

gözlerim sularda 

Marmara dalgasız

yürüyorsun suların üstünde 

Marmara silme sen

gözlerin deniz mavisi

ellerinde bir halka dalga; 

Montaigne’yenin yeni denemelerini

Yani Essais’lerini okuduğundan beri

okyanuslara açıldın 

ve yeni bir sevgilin var

marmara yetmiyor artık

gemilerin eski korsan gemileri

sen bir korsana tutuldun

Marmara silme korsan.

Bilirsin

yalnızlık çekilmiyor

ve bir martının çığlığı da

yetmiyor.

Taranmış saçlarını

bir uzun yola çekmek

geçiyor içimden; 

delirmiş olmalıyım

duvarlara adını yazıyorlar 

kar yağıyor gözlerime

sular basıyor hanları.

Ve akşamlardan

çıkıyor en güzel resimler

soluğumda bir bulut

yükseliyor güzelim,

pek ağlamaklı geçti

bir ömür

sardığımız yaralar azdı,

bazen kabuk bağladı

ve gözgöze gelmenin

hüznünü gördüm

çarpıldık bi’kez

ne fark eder artık

varsın kalsın yerlerde

sevda ilanım.

20.02.1995', 'Tamı tamına 48 saat gözlerim sularda  Marmara dalgasız yürüyorsun suların üstünde  Marmara silme sen gözlerin deniz mavisi ellerinde bir hal...', ARRAY['Türk Edebiyatı','Şiir','Cafer Yurtsever']::text[], 8.5, '{"poet":"Cafer Yurtsever","poet_slug":"cafer-yurtsever","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/48-saat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek istiyorum', 'sevmek-istiyorum-orhan-mahir-kizilboga-p9ois', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerin tutsak eder beni yarınlara

Dayanamam dalar giderim uzaklara

Ayrılık acı verir hayatlara

Son defa seni sevmek istiyorum', 'Gözlerin tutsak eder beni yarınlara Dayanamam dalar giderim uzaklara Ayrılık acı verir hayatlara Son defa seni sevmek istiyorum...', ARRAY['Türk Edebiyatı','Şiir','Orhan Mahir Kızılboğa']::text[], 8.5, '{"poet":"Orhan Mahir Kızılboğa","poet_slug":"orhan-mahir-kizilboga","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevmek-istiyorum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgim', 'sevgim-orhan-mahir-kizilboga-cybtg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni ne kimse alır senden 

Ne de kopartabilirler yüreğimden

Bülbülün gülü sevdiği kadardır sevgim

Denizlerin bulut olup yağmasıdır,

Yağmur olarak yeryüzüne

Sevinçler görürüm etrafımda

Ve yalan olduklarını bilirim

Dünya en büyük sahne 

Oynar insanlar her defasında ısrarla

Korkarak,

Severek,

Zorla,

Kendi oyunlarını,

Ve benim hayatım gerçek diyenin

Yalanı kadardır

Sevgim...', 'Beni ne kimse alır senden  Ne de kopartabilirler yüreğimden Bülbülün gülü sevdiği kadardır sevgim Denizlerin bulut olup yağmasıdır, Yağmur o...', ARRAY['Türk Edebiyatı','Şiir','Orhan Mahir Kızılboğa']::text[], 8.5, '{"poet":"Orhan Mahir Kızılboğa","poet_slug":"orhan-mahir-kizilboga","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevgim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen vardın', 'sen-vardin-orhan-mahir-kizilboga-e4q9x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bulutların arasından geçen ışık demetleri 

Isıtırdı kalbimi o zamanlar 

Dökülen her damla yağmur

Bir anlam taşırdı.

Gümüş rengi günlerimin içinde

Mor dağların seslerini duyardım

Yaprakların sararışında

Bir hüzün ve  mutluluk vardı

Kapkara bir dumanla kaplanmış bu şehirde

Düşlerim olup çıkardın.

Dökülen çam yapraklarımın

Farkına bile varmazdım ben

Sonbaharın ayrı bir yeri vardı gözlerimde

Şarkılar içimi acıtmazdı

Çünkü sen yanımdaydın.', 'Bulutların arasından geçen ışık demetleri  Isıtırdı kalbimi o zamanlar  Dökülen her damla yağmur Bir anlam taşırdı. Gümüş rengi günlerimin i...', ARRAY['Türk Edebiyatı','Şiir','Orhan Mahir Kızılboğa']::text[], 8.5, '{"poet":"Orhan Mahir Kızılboğa","poet_slug":"orhan-mahir-kizilboga","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sen-vardin-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışmak', 'alismak-cafer-yurtsever-61op7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Alışırsın, bana da alışırsın

ben iki de bir 

seni düşünürüm

seni kollarımda

seni soframda

seni balkondan balkona

seni soluk soluğa

seni bir tül perdenin gerisinden

bir sokak lambasının altında

bir silik düş gibi.

Dersin ki

biz ayrılığın iki ucunda

hem varız hem yokuz

bir eylemden

çıktık ya, adımıza

bir şarkı söylenir

bir düğün yapılır

biz ki uzak denizlerden

biz ki deniz aşırı

ülkelerden gelmişiz

bizim adımıza

ağlanır, gülünür

acılara alıştık; 

hani imkanı yoktu

hani dünyada olmazdı

böyle şeyler

hatırladın mı biz

her akşam bir ayrılığı yaşarken.

03.09.1993', 'Alışırsın, bana da alışırsın ben iki de bir  seni düşünürüm seni kollarımda seni soframda seni balkondan balkona seni soluk soluğa seni bir ...', ARRAY['Türk Edebiyatı','Şiir','Cafer Yurtsever']::text[], 8.5, '{"poet":"Cafer Yurtsever","poet_slug":"cafer-yurtsever","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/alismak-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşil', 'yesil-orhan-mahir-kizilboga-4kwe4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yemyeşil bir yokluğa dalardım

Gözlerine her bakışımda

Yemyeşil bir sen 

Oyuncak olmuş bir bene 

Acı verirdi.

Halbuki benim en sevdiğim renk yeşildi

Yazılar yazmıştım duvarlarıma

Posterler asıp mumlar almıştım odama

Sırf sen geleceksin diye

Ama her kapı çalışında 

Benden gidişinin bana 

Gelişine yolları uzuyordu.

Ve yollar bir gün bitti. 

Çiselen yağmurdan ıslak yollarımın

Gözlerinin yeşilinde son kayboluşumun

Dudaklarımda dudaklarının ilk ve son çığlığının 

Sesi yankılanırken kulaklarımda,

Sevda atlasımın hiç olmayan orta dünyasında

Kadim zamanlardan gelen bir düşün 

Verdiği acıyla

Bir ben ilk kez bende tükendi.', 'Yemyeşil bir yokluğa dalardım Gözlerine her bakışımda Yemyeşil bir sen  Oyuncak olmuş bir bene  Acı verirdi. Halbuki benim en sevdiğim renk ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Mahir Kızılboğa']::text[], 8.5, '{"poet":"Orhan Mahir Kızılboğa","poet_slug":"orhan-mahir-kizilboga","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yesil-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzmir', 'i-zmir-orhan-mahir-kizilboga-x07x8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şu anda şehrindeyim

Yemyeşil bir deniz

Ve teninin kokusunu getiriyor 

Uzaklardan rüzgar,

Acılarımı hatırlatıyor

Ama sevinçlerimi de

Az sonra ayrılacak bu şehirden otobüsüm

Ah ne olurdu,

Biraz rüzgar alabilseydim yanıma

Ah ne olurdu,

Beni anlayabilseydin?', 'Şu anda şehrindeyim Yemyeşil bir deniz Ve teninin kokusunu getiriyor  Uzaklardan rüzgar, Acılarımı hatırlatıyor Ama sevinçlerimi de Az sonra...', ARRAY['Türk Edebiyatı','Şiir','Orhan Mahir Kızılboğa']::text[], 8.5, '{"poet":"Orhan Mahir Kızılboğa","poet_slug":"orhan-mahir-kizilboga","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/izmir-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamalıyım', 'yasamaliyim-orhan-mahir-kizilboga-nzju5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Neden insanları tanıyorum? 

Neden sevgiler acı veriyor bana? 

Arkadaş olamıyorum güvenemiyorum kimseye

Başlı başına sorunsun diyorlar bana

Yeni bir ben için çıkmıştım yola

Yeni bende acı veriyor.

Kokuları geliyor aşklarımın odama.

İstemiyorum.

Gittikçe karanlığa sürükleniyorum,

Belki çok cazip geliyor ama

Acılardan kurtulamıyorum.

Yalnızlık paylaşılmaz ki

Paylaşılırsa yalnızlık olmaz.

Gayret et mahir gayret et,

Mağaradan çıkmak senin

Tek şansın,

Yaşamalısın. 

Yaşamalısın.

Yaşamalısın.', 'Neden insanları tanıyorum?  Neden sevgiler acı veriyor bana?  Arkadaş olamıyorum güvenemiyorum kimseye Başlı başına sorunsun diyorlar bana Y...', ARRAY['Türk Edebiyatı','Şiir','Orhan Mahir Kızılboğa']::text[], 8.5, '{"poet":"Orhan Mahir Kızılboğa","poet_slug":"orhan-mahir-kizilboga","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yasamaliyim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soru', 'soru-orhan-mahir-kizilboga-wi65e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir deniz bir denize sormuş uzakta

Taa kadim zamanlarda.

Sever misin beni diye

Deniz taşmış fırtınalar koparmış

Hayır demiş küçük fakat büyük olana

Niye diye karşı çıkmış deniz

Seni bilirim,

Seni anlayabilirim.

Ve sevgimiz okyanusu verir insanlara

Sinirlenmiş taşan deniz

Hayır dedim sana

Ben mutluyum yuvamda

Büyümek korkutur beni

Şimdiden korkutuyorsun zaten düşlerimi

Sözünü kesmiş küçük olan,

Özür dilerim senle okyanus olabilirim sanmıştım.

Yanılmışım.

Bilirsin okyanuslar 

Büyük düşler taşır.

Derin derinliklere atar yalnızlıkları

Ve bana her gelişinde

Çok uzaklardan 

Aslında yüreğimin yanından sesin.

Yüreğim sana seslenir

Sen kimsin?', 'Bir deniz bir denize sormuş uzakta Taa kadim zamanlarda. Sever misin beni diye Deniz taşmış fırtınalar koparmış Hayır demiş küçük fakat büyü...', ARRAY['Türk Edebiyatı','Şiir','Orhan Mahir Kızılboğa']::text[], 8.5, '{"poet":"Orhan Mahir Kızılboğa","poet_slug":"orhan-mahir-kizilboga","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/soru-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akvaryum balığı', 'akvaryum-baligi-orhan-mahir-kizilboga-c5dz5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çok doluyum bu gün

Şiir yazmak istiyorum yeniden

Yine yeniden her seferinde

Küçük bir akvaryum balığına benzetiyorum seni

Sana okyanusları vaat ediyorum

Sen istemiyorsun.

Tıpkı bir insan gibi

Ama sen farklı olmalıydın,

Farklı olman gerekliydi

Okyanusu istemeliydin,

Fırtınalar tatmalıydım seninle

Tüm dünyayı sular altına almalıydık.

En yüksek tepelerde yuvalar yapmalı,

En derin derinliklerde dolaşmalı

Tüm çiçekleri beraber koklamalıydık

Sen farklı olmalıydın.

Sen gerçeği elde etmeli

Sen hayatı bilmeli

Sana seni her verdiğimde

Beni anlayabilmeliydin.

Şimdi bir hayal kırıklığı daha

Şimdi bir ölüm daha bekliyor beni

Daha kaç kere ölürüm bilmem ama

Acele etmeliyim

Gerçek ölüm gelmeden

Hayat sillelerini vurmadan

Bilmeyi öğrenip

Gerçek beni bulmalıyım

Sana da akvaryumunda mutluluklar

Sınırlarla ne kadar mutlu olunursa

O kadar...', 'Çok doluyum bu gün Şiir yazmak istiyorum yeniden Yine yeniden her seferinde Küçük bir akvaryum balığına benzetiyorum seni Sana okyanusları v...', ARRAY['Türk Edebiyatı','Şiir','Orhan Mahir Kızılboğa']::text[], 8.5, '{"poet":"Orhan Mahir Kızılboğa","poet_slug":"orhan-mahir-kizilboga","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/akvaryum-baligi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ufaklık', 'ufaklik-orhan-mahir-kizilboga-oeytu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Duymazsın bu söylediklerimi

Duyamazsın

Bilemezsin içimdekileri ufaklık

Yeşil gözlerin her aklıma geldiğinde

Ki aklımdan hiç çıkmazsın bu aralar,

Gözlerim dalar ağlayamam.', 'Duymazsın bu söylediklerimi Duyamazsın Bilemezsin içimdekileri ufaklık Yeşil gözlerin her aklıma geldiğinde Ki aklımdan hiç çıkmazsın bu ara...', ARRAY['Türk Edebiyatı','Şiir','Orhan Mahir Kızılboğa']::text[], 8.5, '{"poet":"Orhan Mahir Kızılboğa","poet_slug":"orhan-mahir-kizilboga","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ufaklik-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz doğan güneşin,bir gün öncesi', 'sensiz-dogan-gunesin-bir-gun-oncesi-seyit-ahmet-duzen-xqfp6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sensiz doğan güneşin

Bir gün öncesi; 

Denize çiziyor resmini ay

Gece hiç bu kadar güzel olmamıştı

Balıklar öpüyor dudaklarını

Dudakların deniz.

Esince fırtınalar kopuyor yanında

Sensiz doğan güneşin

Bir gün öncesi; 

Uykudaydık...

Başını yaslamışsın göğsüme

Saçların kucaklıyor tenimi

Şükranlarımı iletiyorum Tanrı''ya

Ne büyük hediyesin bana...

Sensiz doğan güneşin

Bir gün öncesi; 

Aksam haberlerini izliyoruz

Ekranda; hızlandırılmış tren enkazı

Şaşkınsın...

Söyleyecek sözümüz yok

Ağlıyoruz hıçkıra hıçkıra

Sensiz doğan güneşin

Bir gün öncesi; 

İstanbul ayaklarımızın altında

Son kahvaltımızı yapıyoruz

Pierre Loti de, habersiz

Çayının şekerini eritiyor,karıştırıyorum

Karışıyor ortalık

Sensiz doğan güneşin

Bir gün öncesi; 

Kaşlarını çatmış küsüyorsun

Düşünüyorum,Acaba neyi unuttum

Sabah çöpleri attım

Öğleye eksik listesi tamam

Balıklara yem verildi

Eyvah! Yine unuttum

Hatırlatmayı sana sevildiğini

Sensiz doğan güneşin

Bir gün öncesi; 

Mostar köprüsü yeniden inşa edilmiş

Tüm Bosna şen ve mutlu

Boşnakça şarkılar dinliyoruz

Sırp topları mı? 

Aramızdaki köprüleri yıkan

Sensiz doğan güneşin

Bir gün öncesi; 

Kör, sağır, dilsiz…', 'Sensiz doğan güneşin Bir gün öncesi;  Denize çiziyor resmini ay Gece hiç bu kadar güzel olmamıştı Balıklar öpüyor dudaklarını Dudakların den...', ARRAY['Türk Edebiyatı','Şiir','Seyit Ahmet Düzen']::text[], 8.5, '{"poet":"Seyit Ahmet Düzen","poet_slug":"seyit-ahmet-duzen","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/sensiz-dogan-gunesin-bir-gun-oncesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneye Mektup', 'anneye-mektup-yuksel-kasim-jnizy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Anne bayramın kutlu olsun

Şu asi Cudi’nin tüm kır çiçekleri

Sana hediyem olsun

Anne elbet biter bir gün bu hasret

Biter elbet

Boynumu oluklu bıçakla kesmişlercesine

Nefes alamadığım mor geceler

Allah bilir ya

Belki bir kurşun

Türkü söyler kulağıma

Belki de sinemde patlar bir bomba

Kefensiz mezara konsam da

Kabrimden en son ayrılan sen ol anne

Bir menekşe dik toprağıma

Mor olsun

Ortasında da

Kırmızı benekleri olsun

Bir uğur böceği konsun yaprağına

O da senin oğlun olsun

Yarimin gözleri yaşla dolsa da

Anne senin bağrın taş olsun

Aldırma sen bunlara

İnadına beni

Bayramda göm toprağa

Hem üzülme o kadar

Bu bayram da kurbanın Allah’a

Oğlun olsun

Şimdi Peygamber’in yanındayım anne

Haşire kadar sabır

Sırat’tan geçerken

Bu satırlar şahidin olsun

Son sözüm şu ki anne

Bu şiir

Vatan hainlerine yafta

Senin de seccaden olsun.

10 Mayıs 1998

Aydın', 'Anne bayramın kutlu olsun Şu asi Cudi’nin tüm kır çiçekleri Sana hediyem olsun Anne elbet biter bir gün bu hasret Biter elbet Boynumu oluklu...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Kasım']::text[], 8.5, '{"poet":"Yüksel Kasım","poet_slug":"yuksel-kasim","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/anneye-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masallardan Gerçeklere Çıkamayan Şiirler-01', 'masallardan-gerceklere-cikamayan-siirler-01-oguzkan-bolukbasi-4seza', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kördüğüm

bu gördüğüm 

tek ayak üzerinde bin yalan

bir küçük yürekte tükenmeyen sevdalar

ve hatıran

ilk günkü tazeliğinde

akşam 

gün kızıla çalar

gözlerin tutar kaldırır beni

kumsala atar

neden diye soramam

bir bildiğin vardır

bilmediğim

seni bu denli çok sevdiğim

burgu burgu delerken ciğerimi

bir bakışta

seni bulmak için kanatlandığım

her saklanışta

gökyüzünü daha bir sevmeye başladım

yere inmek istemiyorum

bulutlar vefasız

yerinde durmuyor

mekan kuramıyorum

birdenbire

çıkıp geliveriyorsun

hayallerim yer değiştiriyor

şekilleri bozuluyor

böyle aniden

kuşkularımın arttığı anda 

çıkıp gelme

şiirlerim bozuluyor

saçmalıyorum

ve 

fakat

yine de kaçmıyorum

acısından

yüreğimi delen bakışlarının', 'kördüğüm bu gördüğüm  tek ayak üzerinde bin yalan bir küçük yürekte tükenmeyen sevdalar ve hatıran ilk günkü tazeliğinde akşam  gün kızıla ç...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/masallardan-gerceklere-cikamayan-siirler-01-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derindeyim', 'derindeyim-zafer-zengin-etnika-4nfnu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sıfattan anlamaz

Yüz diyelim

İki yüz olsun

Kimse boğulmasın

Mavi solmasın

| Göbek adı umut

He canım

He gülüm

Sen gül

Bana gelsin ölüm

Bana gelsin zulüm |

Biçilmiş el usulü

Ne kadar sıcak

Ne kadar aç hava

Aşkı saklamışlar kuytulara

Örselenen zaman

Dönüyor durmadan

Bir yol yürümeli şu kumrular

Kaç bucak ki kavuşmak

O gülü düşün

Düşün gülü düşün

Gülsün yüzün

Kulağa fısıldanır

En güzel sözün

| Benden habersiz söyleyin..seni seviyorumlarınızı..bilmesem de olur..

  bir yeter..sayması kolay..bir yeter..bir yeter..sayması kolay |

Issız yoların adı yalnızlık

Ve sessiz her adım

İçinde yankılanan

Doğurgan saklanbaç

Sesin gelsin balçıktan

Yoksa niye varsın

Nasıl saklansın

Çatlağımda kil

Odalar taş duvar

Kendini sınar ayrılıklar

Der miyim

Her şey kolay

Ne zordur

Ölüp yalnız kalmak

Bunu kimseden duymamak

Gök kafes küçülüyor derinlerde

Derindeyim 

Silme beni

İnme

İnme

Sen dokundun öncelerime

27 Temmuz 2004 “  elin yanağında “', 'Sıfattan anlamaz Yüz diyelim İki yüz olsun Kimse boğulmasın Mavi solmasın | Göbek adı umut He canım He gülüm Sen gül Bana gelsin ölüm Bana g...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/derindeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'adini-sen-koy', 'adini-sen-koy-halit-demir-zwshp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seninle bir sonbahar akşamı

İş çıkışı tanışmıştım

Ürkek ve çekingen tavırlarımla yaklaşıp

“ Şey…şey…Benimle arkadaş olur musun” demiş

Sonrada “Hayır” sözcüğünü işitip

Yanından uzaklaşıp gitmiştim...

Bu masum sevdam böyle kalmadı..

Giderek bedenimi saran,

İçimi yakıp kavuran 

Bir alev ve kor misali yangına döndü. 

Sende  farkındaydın artık,

Sana…..

Günden güne deliler gibi

Yanarak kavrulduğumu..

Artık seninleydim…., 

Beraberdik….

Şimdi sadece kim olduğum değil di artık beni düşündüren

Sen olduğun için, ben’liğinin anlamını sevdiren

Sen….

İçinde saklı olan o çocuksu sevgilerini 

Hiç menfaat beklemeden sevdiğini veren…

Seni tüm benliğimle hissettiğimde,

Sevgilere susamış  bu  kalp 

Üzüntüleri ve sıkıntıları atıyordu üzerinden...

Şimdiye kadar hiç kimsenin başaramadığını

Seninle iken, sen başardın

Ve hiç algılamadığım  o sıcaklığı, o içtenliği de

Seninle iken, sende görmüş, sende yaşamıştım.

İçimdeki o karanlığı senin ışığın aydınlatmıştı

Hayatıma başka bir pencereden bakıyordum artık

Hiç şiir yazmayan bu adam

Kalemi elinde, 

Şimdi şiirler yazıyordu artık sayfalarca …...

Oysa sen neler kazandırdın bana neler! 

Şimdiye kadar hiç kimsenin  kazandıramadığı şeyleri kazandırdın.

Önce kendimle dost ve barışık olmayı

Sonra Sevmeyi ve sevgiyi

Daha sonra sevilmeyi kazandırdın

Hiçbir zaman tadamadığım kadar mutlu olmamı

Ve en önemlisi de 

Kendimin! kim olduğumu tanıdım…

Onun için senin bendeki yerin başka

Bunu sen tarif et

Bunun adını sen koy

……………………….İstersen……..

İstersen “AŞK” de, 

İstersen “SEVGİ” de

İstersen “SAYGI” de

İstersen “SEVGİLİM” de

Ama yeter ki adını sen koy 

………………………………..OLUR MU? 

Halit Demir- 24.07.2004- Erzincan', 'Seninle bir sonbahar akşamı İş çıkışı tanışmıştım Ürkek ve çekingen tavırlarımla yaklaşıp “ Şey…şey…Benimle arkadaş olur musun” demiş Sonrad...', ARRAY['Türk Edebiyatı','Şiir','Halit Demir']::text[], 8.5, '{"poet":"Halit Demir","poet_slug":"halit-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/adini-sen-koy-168-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Sevdalar', 'yagmur-sevdalar-yuksel-kasim-gjm0y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biz küçüktük

Hayatın hoyratlığı ile

Karşılaşmamıştık daha

Ama yüreklerimiz büyüktü,

Büyüktü hayallerimiz.

Sonra büyüdük…

Kocaman adamlar olduk yani

Ve hayat acımadan vurdu bize

Önce hayallerimiz küçüldü

Sonra birer birer yok oldular.

Ama daha yüreklerimiz büyüktü

Ve o kocaman yüreklerimiz

Gençlik aşklarına yenik düştü

Hazanda kuruyan yapraklar gibi

Darmadağın olduk.

Yürek; yürektir insanı büyük yapan

Cesareti de yürek taşır,sevdayı da

Biz yüreklerimizden daha büyük

Sevdalara tutulduk,

Yağmurları avuçlarımıza sığdıramadık

Ve kapıldık sel sularına

Şimdi bütün sevdalarda yüreklerimiz; 

Yağmur sevdalarda.

Yağmur sevdası

Kahramanların sevdası

Yeniklerin sevdası bizim sevdamız

Kayıp bir neslin sevdası.

Biz,yağmurlar gibi sevdik...

28 Ocak 2003 

Arga', 'Biz küçüktük Hayatın hoyratlığı ile Karşılaşmamıştık daha Ama yüreklerimiz büyüktü, Büyüktü hayallerimiz. Sonra büyüdük… Kocaman adamlar old...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Kasım']::text[], 8.5, '{"poet":"Yüksel Kasım","poet_slug":"yuksel-kasim","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yagmur-sevdalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YaNgıN YeRi', 'yangin-yeri-mine-ozdemirtas-b642q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Keşke; 

siyaha sarmak zorunda kalmasaydınız  diğer renkleri.

Bulutun buluta dolanmasındaki

o bir tek anın sonunda

kopacak olan kıyameti

düşünüyormuşsunuz gibi.

karartmışsınız kendinizi

Sanki biri; 

itina ile silmiş ayak izlerinizi.

Sonra, ansızın arkanızdan itmiş de sizi

kınalı bir parmağın ucundan

sonsuz kere yerin dibine

düşüyormuşsunuz gibi

çığlıklara asmışsınız sesinizi

Belli ki; 

hala soğumamış içinizdeki yangın yeri.

Minik bir kıvılcım

yeniden ateşlerken sönmüş külleri

teninize  yerleşen donuk bir gri

morartmış dudaklarınızı

üşüyormuşsunuz gibi

Peki......

neden titriyorsunuz ki? 

Yoksa! erken mi çektiniz

anıların üstündeki ıslak örtüleri.?', 'Keşke;  siyaha sarmak zorunda kalmasaydınız  diğer renkleri. Bulutun buluta dolanmasındaki o bir tek anın sonunda kopacak olan kıyameti düşü...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yangin-yeri-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece Benimlesin', 'bu-gece-benimlesin-nail-yavuz-oj59u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dudakta biriken söz çürüğüdür............

vakitlerden akşam üstü 

birini bekliyor gözlerim 

dört yanım dört aşılmaz duvar 

içimde bir barut çizgisi 

ve meridyende saat yirmi 

bekliyorum gelmiyor 

kırıyorum yönümü yalnızlığa 

gece başlıyor dudağımda 

eşkiya artığı gülüşüyle 

tüm gece biliyor kederimi 

bir dili olsada anlatsa 

dudakta biriken söz çürüğüdür

kül kor ateşi gizliyor 

mermeri andırıyor yüzüm 

bir sigara yakıp diğerini söndürüyorum 

giderek çoğalıyor kül 

zehir sızdırıyor içime pişmanlıklar 

uzamasını biliyor gece 

liman sanıyor yüreğimi 

ışıklar eritmiyor karanlıklarımı 

grilik siyahlaşmamak gibi bir inat ki

kıvrılıp yanıma ben olmaya soyununca 

usulca tarıyorum gecenin saçlarını 

karanlıklar salkım saçak 

gülmeler talan olmuş 

uykudan korkuya geçme sularında 

mirascısı olduğum 

acılarımın başında nöbet tutuyorum 

hüznü demliyor gece 

bağışıklık kazanıyor sızılarım 

ellerimde acıların tarihi 

ellerim ki bağlı gözlerimde 

ahtapot kollarıyla karanlık 

g e c e y i s a r m ı ş k e n 

bende senden gidiyorum 

iki mavi arasındaki karanlıkta......

y o k o l u y o r u m............. 

NAİL YAVUZ.... İ Z M İ R....', 'dudakta biriken söz çürüğüdür............ vakitlerden akşam üstü  birini bekliyor gözlerim  dört yanım dört aşılmaz duvar  içimde bir barut ...', ARRAY['Türk Edebiyatı','Şiir','Nail Yavuz']::text[], 8.5, '{"poet":"Nail Yavuz","poet_slug":"nail-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/bu-gece-benimlesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruz-i Mahşer', 'ruz-i-mahser-aziz-ahmet-bulut-mqwx2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seyrü sefer eyledim Şar Dağı nda

Sanma ki Ceyhan Suyu zevkü sefada

Nikahlanmış Karadeniz ile Marmara karatoprakta

Sefaletin yaşınla artsın cihanı alemde.

Buluşmuş Sümmani ile Gülperi

Körkütük sarhoş dadaşlar diyarı

Biraya gelmiş acı ile tatlı

Göz yaşların yaşınla artsın cihanı alemde.

Hüyücek Köyünü aşıpta ulaşırsan Kaf Dağı na

Görürsün Adem ile Havvay ı, anka kuşunu da.

Bilmez misin bülbülün güle olan figanınıda

Acıların yaşınla artsın ruz-i mahşerde de.', 'Seyrü sefer eyledim Şar Dağı nda Sanma ki Ceyhan Suyu zevkü sefada Nikahlanmış Karadeniz ile Marmara karatoprakta Sefaletin yaşınla artsın c...', ARRAY['Türk Edebiyatı','Şiir','Aziz Ahmet Bulut']::text[], 8.5, '{"poet":"Aziz Ahmet Bulut","poet_slug":"aziz-ahmet-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ruz-i-mahser-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Varsan', 'sen-varsan-aynur-baydar-qz37e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Soğuk kuru dallı ağaçların

Gri olan hayatımın, güneşi oldun

Sesinle çoşturdun, içimde kuş cıvıltılarını

İnen gözyaşlarım olsa da...

Düştüklerinde toprağa,hayatıma...

Ara sıra gelen bulutlardan, can verdi yeşertti.

Öğretti aşkı çorak yüreğime.

Ufku göremediğimde, sonsuz gri okyanusda

Palmiye yeşilli kıyı cenneti

Gösterdi gözlerime, yeşil gözlerin.

Ceviz kabuğu sandalımla ve böyle sürüp gidecek derken

Dev dalgalarla mücadele ederken

Bembeyaz yelkenli gemiyle

Çıkarttın beni mavi yolculuklara.

Beyaz siyah ve gri renkli ruhumu

Ayrıştırdın bin bir gökkuşaklarına

Tırmanmam için sonunu göremediğim 

Dik dağların zirvesinde durdun

Gülümsedin, güç verdin

Asil, mağrur ve çekici

Gel dedin...

Her zorun bir zirvesi var

Kardelen çiçekleriyle süslü ödülleri var

Yeter ki başını dik tut ve görmeyi bil.

Aceleci karakterime öğrettin

Sabrında beklemeninde güzel olduğunu...

Çöllerde de en güzel kaktüs çiçeklerinin

Rüya vahaların gerçekleşebileceğini.

Sabır sen varsan acısız...

Umutsuzluk, sen varsan umut

Hep dünler sen varsan, sonsuz yarınlar

Özlemek, ödül sensen, güzel

Kış hayat, sert rüzgarlar, fırtınalar

Tatlı bir meltem

Bir bahar seninle olmak.

Yarınlar mümkün sen varsan

sen varsan.', 'Soğuk kuru dallı ağaçların Gri olan hayatımın, güneşi oldun Sesinle çoşturdun, içimde kuş cıvıltılarını İnen gözyaşlarım olsa da... Düştükle...', ARRAY['Türk Edebiyatı','Şiir','Aynur Baydar']::text[], 8.5, '{"poet":"Aynur Baydar","poet_slug":"aynur-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sen-varsan-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik, Sessiszik, Yalnızlık', 'sensizlik-sessiszik-yalnizlik-bilgin-subasi-y9knl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sensizlik, sessiszik, yalnızlık

yalnızlığımda aradım teslim olacağım sevgiyi

önce kandime baktım tanıdım

tüm silahlarıyla geldi nesne, eşya, şey..

teslim olmadım

güçlenip ayrıldım...

sessizliğimde sorguladım sevgiyi

günlerce zindanda yatırdım

aç bıraktım, susuz bıraktım

işkence üstüne işkence yaptım

kanattım tüm yaralarını

tuz bastım

konuşmadı, ağlamadı...

güçlenerek çıktı aydınlığa.

başı hep dik durdu, dikte duracaktı....

bilmedi, bilemedi bir gün

kısık bir göz aralığından

ince uzun bir sevda yolculuğuna çıkacağını...

uzayıp giden yollarda

uzayıp giderken sonraya

kurguyla gerçeğin nasıl savaştığını..

.............../.............', 'sensizlik, sessiszik, yalnızlık yalnızlığımda aradım teslim olacağım sevgiyi önce kandime baktım tanıdım tüm silahlarıyla geldi nesne, eşya,...', ARRAY['Türk Edebiyatı','Şiir','Bilgin Subaşı']::text[], 8.5, '{"poet":"Bilgin Subaşı","poet_slug":"bilgin-subasi","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sensizlik-sessiszik-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizim', 'denizim-bekir-mutlu-gokcesu-fugaf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben denizin

Kokusunu sevdim

Dudağımdaki tuzunu

Sahipsizliğini sevdim...

Uçsuz bucaksız 

Yapayalnızlığına

Sahip oluşumu sevdim

Aklımda...

Sokuluşunu şehre

Ve koynunda 

Uyuyuşunu sevdim

Usulca...

Ben denizin

Dokunuşunu sevdim

Çıplak ayaklı

Sırlarıma...

Ve suskunluğunu

Sevdim rüyalarımda...

Ben denizin

Bende başlamayışını

Ve bende bitmeyişini

Sınırsızlığını sevdim

Uzaklarda...

Ben denizin

Bendeki sen hallerini

İçimde çoğalışını sevdim

Sonsuzluğa...

Ben seni sevdim...

Denizim bildim aslında...', 'Ben denizin Kokusunu sevdim Dudağımdaki tuzunu Sahipsizliğini sevdim... Uçsuz bucaksız  Yapayalnızlığına Sahip oluşumu sevdim Aklımda... Sok...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/denizim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık Bizi Kolları İle Sarsın..', 'karanlik-bizi-kollari-i-le-sarsin-tulay-eker-5fc39', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '________Karanlık. 

Çarmığa gerilmiş 

_______Aydınlık 

_____ Ve ben 

Kara kapkara karanlık 

Dişleri parlıyor parıltılarla 

Canım darda 

Dönüyorum etrafımda 

Ellerin hani 

Tutup durdursana beni 

Kara kapkara karanlık 

Salmışım kendimi 

Gözkapaklarım yaralı 

Çeperine kan oturmuş 

Hani gözlerin gözlerimdi 

Acımıyor mu şimdi 

Kara kapkara karanlık 

Şimşek pusuda 

Dostlar uykuda 

Yangın var yangın! 

Buz kesmiş sol yanım 

Hani hep yanımdaydın 

Damarlarımda,aradığımda

Canım yorgun... 

Serilmiş kör kuytuda 

_____________Ve biz 

Kara kapkara karanlık 

Bigünah değiliz hiçbirimiz 

Gül dalında eğreltiyiz 

Zırhlarımızı kanatlarımız 

Kanatlarımızı yaşamımız sandık 

Bu ismi koyup bel bağladık 

Neden sarılamadık 

Kara kapkara karanlık 

Aslında.. 

Ne dövüştüğümüz vardı 

Ne de vuruştuğumuz 

Sanki bir arayıştı... 

Göğe karşı duruşumuz 

Biz bizi,biz sizi 

Siz bizi vurduk her darbe! 

Kendimizi vuruşumuz. 

_____Acı 

________Hüzün 

_____Kan 

____________Zulüm.. 

Hepsi halka 

Boynumuza takılı 

Alışkanlık olmuş 

Fotokopileri bile yaslı 

____________Ve dönence 

Kanıyor yaram bilirim 

Yüreğimin katiliyim 

Gelmişi geçmişi sildim 

Desemde ışık benim.. 

Kör bir damla o da 

Yanıyor hala.', '________Karanlık.  Çarmığa gerilmiş  _______Aydınlık  _____ Ve ben  Kara kapkara karanlık  Dişleri parlıyor parıltılarla  Canım darda  Dönüy...', ARRAY['Türk Edebiyatı','Şiir','Tülay Eker']::text[], 8.5, '{"poet":"Tülay Eker","poet_slug":"tulay-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/karanlik-bizi-kollari-ile-sarsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölge', 'golge-elif-ardic-orkxf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gölgemi bırakırım her şehre 

Yok ki hiçbir şeyim

Alır mı hiç beni koynuna

Yabancı kokarım her yerde

Seyrettiklerim kalır içimde

ellerinin izi saçlarımda 

Beni silkelesen 

Sadece küskünlüğüm düşer,

Niye geldin ki sen

Özensiz dokundun

uyuyan aşkıma 

Öyle garipti ki 

Kapattım bir odaya

Kimseler görmesin

Bıkmayacağım saklamaktan 

sırra sadık insanlarız 

suskunluk, yakışır bize

tekrar yan yana olamamak 

ihtimaline karşı 

sessiz  oturup bir çay içelim

saatte kaç kilometre hızla

yaşlanıyorum bilemezsin', 'Gölgemi bırakırım her şehre  Yok ki hiçbir şeyim Alır mı hiç beni koynuna Yabancı kokarım her yerde Seyrettiklerim kalır içimde ellerinin iz...', ARRAY['Türk Edebiyatı','Şiir','Elif Ardıç']::text[], 8.5, '{"poet":"Elif Ardıç","poet_slug":"elif-ardic","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/golge-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiya li çiyan dinêrin', 'ciya-li-ciyan-din-rin-omer-dilsoz-791xx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nameya min ji çiyan re. Ji bêhna axê, ji dengê avê, ji tîna rojê re… Nameya min ji evîndara min re. Ji gula çiyan re. Ji stêrka berbangê re. Ji ava ber keviyan re. Ji axa ku ew girtiye nava xwe re. Ji axa ku bêhna wê jê difûre re. Ji wan kulîlkên li ser girê axê şînhatî re… Ji wê re… Ji çi tiştê ku bêhna wê, tîna wê, pêjna wê jê tê re! ... Ji dilê min re; ji dildara min re… 

Çiya bilind in û li çiyan dinêrin.

Qontêra çiyan tev bi zinar û şikêrin

Danê sibehan heta danê êvarî

Min çav bi rêka te ve kor kirin   

Çiya li hev dinêrin. Ew bi heybet in. Bi sehm in. Bi deng; deng ji çiyan tê; dengên hezar salan. Dengê hezar celebê jîndaran. Dengê jiyanê, dengê mirinê û dengê xweziyan ji çiyan tê. Dengê azadî û serbestiyê. Dengê miletan ji çiyan tê. Dengê te ji çiyan tê…

Çiya li çiyan difikirin

Rondikên min tên û qet xwe nagirin

Heke tu dûr bî, ez ji te dûrtir im

Heke tu xerîb bî, ez ji te xerîbtir im.

Çiya tu digirtî nava xwe; tu cezb kiribûyî û tu bi xwe re dibirî. Çiyan gotinên te ji te dizîbûn. Dilê te bi xwe ve girêdayî bû. Tu ji min dûr dixistî; çiya hesûd bû. Li ser evîna xwe dilerizî. Ji bo evîna xwe har dibû. Wê evîn tenê ji xwe re diviya; çiya çavnebar bû li hemberî hezkirina min a ji bo te. Çiyan tu ji min dizî û tu bi xwe ve girêdayî. Wê rojê min radibîst ku tiştek bi te hatiye.

      

Gotinên te sist bûn wê rojê,

Keneke tirş li ser rûyê te niştibû

Awirên te pir sar dinihêrtin

Hişkebayên payîzî ji peyvên te dihatin 

Tu li ser çûyînê bûyî

Li ser riya oxireke nediyar

Erê, ezê vê nameya xwe ji çiyan re binivîsim. Ji bo çiya darêsim gotinên xwe. Bila peyvên min ji çiyan re biherikin. Ezê çiyan bînim ser gotinê û ezê bo çiyan bigerînim zêmarê û ji bo çiyan lidarxînim govendê, semahê… Ezê ji bo çiyan xeml û rapêça zavatiyê li xwe bipêçim û ezê ji bo çiya evînê bihewînim di nava dilê xwe de…

Çiya bilind in ez te nabînim

Teyr û tilûr li ser zinaran datînin

Kew û kewderî li hindav dixwînin

Nêçîrvan dewsê li dû xezalan digerînin  

Çiya bi derd in; derdê wan giran e. Derdê çiyan deştên pahn in, geliyên kûr in, avên sar in. Çiya dinalin. Çiya bêhalin… Derdê çiyan viyan e. Ew bi viyanê hene; bi viyanê ser xwe ne. Çiya bêviyan tune ne, mirî ne. 

Çiya bilind in mijê baldayê

Keviyên berfê rêz girêdayê

Dilê malwêran ketiye derdê evînê

Dinale heçko dûpişkan pê vedayê 

Çiyan tu vexwarî. Tu bûye çiya û di nava çiyan de berze bûyî. Wê rojê min dizanî ku tuyê ber bi wî dengî ve biçî. Wî dengê berz ê ji çiyan dihat. Lê min qet ji wî dengî heznekiribû; mîna velerzekê di hişê min de diteqiya. Tezing dida laşê min. Ez digevizîm; nexasim wê kêliya min li nav çavên te nihêrt her tiştî tê de  xwe dida der. Tu li ser çûyînê bûyî. Tîna çavên te ne ez lê ew dixwest; ew, ango çiya… Lewma hingê qirpînek ji dilê min çû, xwîdanê ez pêçam, tayeke sar xwe berî dilê min da û hema demildest cihê xwe ji tayeke germ re guhast… Ji ber ku min winda dikir; tu diçûyî.

Wê rojê rûyê te guherîbû

Awirên te sist dinêrtin

Keniya ser lêvên te tal bû

Gotinên te her tişt vedigotin

Çiya li ber hev rawestiyane. Tu dibêjî qet li benda kesekê ne; jivana wan heye qey! Erê, niha çiya careke din ketine bêdengiyê; careke din ew biserketin; ji ber ku wan tu ji min standî. Ew bi evîna te ve man. Ew bi evîna te ve vejiyan. Qey kulîlkên wê bê tov mabûn? Qey axa wê bê xwîn mabû..? Lewra wisa har bûbû… Erê, min radibihîst ku ew harbûn ne harbûna xêrê bû. Wan evîna min ji min dixwest. Wan tu ji min dixwestî… Vaye tu standî… Ma tu qet têr nabî ji evîna dilan çiya! De bila li te pîroz be! ...

Çiya li ber çiyan çendî stûxwar in

Bi terazin û mêrg in, tev avên sar in

Rûbar dikişin tu dibêjî qey mar in

Her bihosta wan ji te re war in…

2004-01-21/ Amed', 'Nameya min ji çiyan re. Ji bêhna axê, ji dengê avê, ji tîna rojê re… Nameya min ji evîndara min re. Ji gula çiyan re. Ji stêrka berbangê re....', ARRAY['Türk Edebiyatı','Şiir','Ömer Dilsoz']::text[], 8.5, '{"poet":"Ömer Dilsoz","poet_slug":"omer-dilsoz","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/ciya-li-ciyan-dinerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Hepsi Bu', 'i-ste-hepsi-bu-semra-karabag-yrffc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '(Damla damla  hasretimi suladığım Papaz karası

Usulca karışıyor kanıma, döndürüyor başımı

Senden çok uzaklarda seninle baş başa kaldığım 

Bu ıssız dağ başı.)

Vazgeçtim senin şehrinin denizinden.

bütün minarelerinden, bütün kulelerinden 

ve yıldız yıldız yanan yakamozlarından vazgeçtim.

Görmeyecektim, duymayacaktım, bilmeyecektim,

İnan ki gelmeyecektim,

Sıcak yaz gecelerinin kollarında

Ilık bir yağmur gibi başka hayatlara yağdığını görmeseydim.

Gelmeyecektim inan ki, 

Yorgun dudaklarından öpecektim,

Gülümseseydin vazgeçecektim.

Olmasaydı dudaklarımda senden kalan bu elma tadı. 

İnan ki öpecektim.

Ve gelmeyecektim.

Terk ettim işte,

Bütün masum aşkların buruşturulup içine atıldığı

Bir çöplük gibi şehrini.

Burada minareler, kuleler ve yıldız yıldız yakamozlar yok,

Gökyüzüne alabildiğine uzanan serviler var.

Bir göl, geceleri kör kuyular gibi karanlık

Gündüzleri ışıl ışıl.

Bir de yıldızlar var 

Senin şehrinin gökyüzüne sığmayacak kadar çok.

Neye içtiğimi bilmeden içiyorum.

Kadeh kadeh tüketiyorum etrafıma sinmiş karanlığı,

Her yudumda bir çığlık,

Her yudumda zehir gibi bir ayrılık yutuyorum.

Son yıldız da düşüyor gölün derinlerine.

Puslu bir aydınlık akıyor servilerden.

Gözlerin beliriyor kıpkızıl gökyüzünde

İçimde fırtına, içimde bulut, içimde yağmur

Susuyorum... susuyorum...

Kurtulacaktım, unutacaktım, yaşayacaktım.

Çıkmasaydı valizimden tek tek katlanmış anıların,

Gelip oturmasaydı göğsümün tam ortasına bu ıssızlık

İnan ki unutacaktım.

Bak, mavi gömleğime damlattığın kan kırmızı yakut

Hayatımdan silinmek istemeyen bir gölge gibi 

Asılı duruyor

Ve çıkarmaya yetmiyor gözyaşlarım

İhanetin yüreğimde bıraktığı lekeyi.

İnan ki unutacaktım ve yaşayacaktım

İçine sindiğin her şeyi yanıma almasaydım.

Sinsi bir kurt gibi kapımda bekleyen yalnızlık

Koynuma uzanıyor her fırsat bulduğunda

Sinsi bir kurt gibi içimi kemiren sensizlik

Git diyor, bul diyor, al diyor

Durmuyor içimdeki sana ayarlı saat

Beni, altmış defa sana bölüyor

Altmış kere altmış seni vuruyor, 

Ölçülebilen her şeyi döndüren zaman

Ölçemediğim her şeyle beni vuruyor...

Bütün saatleri  kırmak istiyorum.

Zamansız yaşamak, zamansız ölmek,

Sensiz olmak istiyorum alabildiğine.

Yalnızlık, sensizlik...işte adı her neyse

Bütün göğü kaplayan bu müebbet boşluğu

Altmış kere altmış kendimle çarpıp

Senin kollarına vermek istiyorum.

Yapraklar böyle neden titrer bilir misin? 

Ve neden yemyeşil bir dağ hüzünle bakar? 

Hani her ayrılığın ardından, 

Ne yapacağını bilemez bir duygu sarar ya 

İşte öylesine bir hal var. 

Biliyorsun değil mi? 

Uzak, yakın her yere sinmiş anlıyorsun,

Çiçeklerden bile fışkıran bu zehir,

Bu nankör ölüm uykusu.

Ve ayrılık dediğimiz şey sadece

Hiç beklemediğimiz anda avucuna düştüğümüz

Kahpe bir yalnızlık korkusu.', '(Damla damla  hasretimi suladığım Papaz karası Usulca karışıyor kanıma, döndürüyor başımı Senden çok uzaklarda seninle baş başa kaldığım  Bu...', ARRAY['Türk Edebiyatı','Şiir','Semra Karabağ']::text[], 8.5, '{"poet":"Semra Karabağ","poet_slug":"semra-karabag","theme":"Türk Şiiri","is_hero":false,"total_lines":74,"source_url":"https://www.antoloji.com/iste-hepsi-bu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
