INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaprağın Öyküsü', 'yapragin-oykusu-erol-dogan-bploi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dalından kopan bir yaprak gibiyim adeta

  Ardında pişmanlık bırakan her fırtınada

  Bir o tarafa savruluyorum bir bu tarafa.

  Toprağa göz yaşı bırakan her yağmurda

  Sırılsıklam oluyorum sudan çıkmışcasına

  Gölgesinde volta atılan her güneşli havada

  Sararıp soluyorum ölümü hatırlarcasına.

  Yıkılan hayallerimi arıyorum savrulduğum yerlerde

  Aldığım nefesleri özlüyorum batınca dibe

  Solmuş sevgilerin inadına yaşıyorum yine 

  Bırakıp gidenleri düşününce.

  Umutlar tekrar yeşerince bir dalda

  Yeri olmayacak pişmanlığın hayatımda

  Savrulsam da en derin uçurumlara bir daha...', 'Dalından kopan bir yaprak gibiyim adeta   Ardında pişmanlık bırakan her fırtınada   Bir o tarafa savruluyorum bir bu tarafa.   Toprağa göz y...', ARRAY['Türk Edebiyatı','Şiir','Erol Doğan']::text[], 8.5, '{"poet":"Erol Doğan","poet_slug":"erol-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yapragin-oykusu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim İzin Veriyor', 'kim-i-zin-veriyor-baykal-kaanalp-yktgl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'aç bırakıldı

susuz kaldı,yılmadı

kahırlanmadı

alamadıklarına içerlemedi

peşinde olmadı

haklarının,hak ettiklerinin

aldatıldığına üzülmedi

kederlenmedi

keder ona çok uzak

bir sözcük

ortalıkta dolaşan

manasız sözler içinde

kim izin veriyor

hiç bilmez,bu kadar

kötümser sıralanmış

sözcüklerin yaşamasına

kim koşuyor peşinde

olası kılıksızlıkların

her yerde bembeyaz

bir örtü kaplıyken

her yer taze bir güne

gebeyken(sorumsuz) 

kılçıklara aldırmazken

balık yemeye tutkulu', 'aç bırakıldı susuz kaldı,yılmadı kahırlanmadı alamadıklarına içerlemedi peşinde olmadı haklarının,hak ettiklerinin aldatıldığına üzülmedi ke...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kim-izin-veriyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm korkusu (aforizmal)', 'olum-korkusu-aforizmal-mutlu-ayar-or0ku', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hiç anlamam 

Niçin korkulur ölümden

En çok korkanlar bile 

Ölmeyi başarırken! 

17.o3.o4', 'Hiç anlamam  Niçin korkulur ölümden En çok korkanlar bile  Ölmeyi başarırken!  17.o3.o4...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Ayar']::text[], 8.5, '{"poet":"Mutlu Ayar","poet_slug":"mutlu-ayar","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/olum-korkusu-aforizmal-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çırak', 'cirak-baykal-kaanalp-iux7r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'tamam dedi çocuk

ustasına

gönül koymadan

''başını eğmeden''

çok seviyordu

''canı gibi''

bir dediğini iki etmezdi

ustasının

sevmezdi bir şeyin

iki defa tekrar

edilmesini

istemezdi ardından 

konuşulmasını

istemezdi komşuluğunu

yaramazlıkların

yaramaz bir çocuk 

sayılmazdı

biraz tembeldi

o kadar

sabah geldiğinde

etrafı silip süpürür

makinaları yağlardı

sonra tembellik etmek

hoşuna gidiyordu

makina kokuları

onu mest ediyordu

tamam dedi çocuk

ustasına

gönül koymadan

''karşı gelmeden''', 'tamam dedi çocuk ustasına gönül koymadan ''başını eğmeden'' çok seviyordu ''canı gibi'' bir dediğini iki etmezdi ustasının sevmezdi bir şeyin ik...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/cirak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerimde Ararken Seni', 'duslerimde-ararken-seni-erol-dogan-vi3ui', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şimdi yıldızlar kadar uzaksın bana

   Uzanıp gökyüzüne tutmaya çalışırken seni.

   Şimdi gözyaşım kadar yakınsın bana

   Her damlasında  ararken seni. 

   Şimdi kurduğum hayaller kadar gerçeksin bana

   Düşlerimde ararken seni.

   Şimdi unutulup giden aşklar kadar yalansın bana

   Deliler gibi severken seni.

   Şimdi geri gelmeyen dünlerim kadar özgürsün bana

   Yarınlarımda ararken seni.

   Şimdi yaşamak kadar yasaksın bana

   Her nefeste içime çekerken seni.', 'Şimdi yıldızlar kadar uzaksın bana    Uzanıp gökyüzüne tutmaya çalışırken seni.    Şimdi gözyaşım kadar yakınsın bana    Her damlasında  ara...', ARRAY['Türk Edebiyatı','Şiir','Erol Doğan']::text[], 8.5, '{"poet":"Erol Doğan","poet_slug":"erol-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/duslerimde-ararken-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak Zor Gelir İnsana Bazen', 'yasamak-zor-gelir-i-nsana-bazen-erol-dogan-5ebh3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşamak zor gelir insana bazen

    Zehir zemberek geçen yıllarını düşünürsün

    Dayanamaz bir off çekersin duvarları inleten. 

    Sonra derin bir nefes alırsın sigarandan

    Gecenin karanlığına birde sessizliğin eklenince

    Kalan son umutlara sığınırsın gizlice.

    Hele birde tutulmuşsan vefasızın birine

    Yedi gök bir araya gelse ne çare

    Uzadıkça uzar güne hasret gecelerin

    Haykırmak gelir içinden vazgeçersin dünyadan

    Sonra derin bir nefes alırsın sigarandan

    Yaşamak zor gelir insana bazen...', 'Yaşamak zor gelir insana bazen     Zehir zemberek geçen yıllarını düşünürsün     Dayanamaz bir off çekersin duvarları inleten.      Sonra de...', ARRAY['Türk Edebiyatı','Şiir','Erol Doğan']::text[], 8.5, '{"poet":"Erol Doğan","poet_slug":"erol-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yasamak-zor-gelir-insana-bazen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmuyor', 'olmuyor-baykal-kaanalp-vo507', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'anladım ki yalnız olmuyor

ne yapsam da yerin dolmuyor

mazide kalsa da bir hayat

ne yapsam da yerin dolmuyor

aradım bir başkasını

bozamadım fiyakasını

bulsam da sevginin hasını

ne yapsam da yerin dolmuyor

olmuyor,kalbim boş olmuyor

yüreğim sevgi,gözüm neşe dolmuyor

pınarlar kurudu içi boş olmuyor

ne yapsam da yerin dolmuyor', 'anladım ki yalnız olmuyor ne yapsam da yerin dolmuyor mazide kalsa da bir hayat ne yapsam da yerin dolmuyor aradım bir başkasını bozamadım f...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olmuyor-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Filim', 'filim-baykal-kaanalp-1980n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gördüğümüz filim

biraz uzak ta olabilir

ama yaşanmaz değil

hayalperest değil

yaşamdan bir parça

bir hediye sana bana

gördükçe sevimli

yaşanılası,heyecanlı

filimler kopabilir

yaşam solgun

eklenmesi sana bana

vurdumduymaz, canlı', 'gördüğümüz filim biraz uzak ta olabilir ama yaşanmaz değil hayalperest değil yaşamdan bir parça bir hediye sana bana gördükçe sevimli yaşanı...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/filim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızız', 'yalniziz-yagmur-damlasi-tmllb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Savrulsun içimizde 

Aşkın külleri,

Yandığımız yetişirse 

Yetişir  artık! 

Bahçemizde en güzel aşk gülleri

Elimiz bağlı dilimiz suskun

Koynuna sarılıp uyurken yokluğun

Bir çaresizlik türküsü 

Dilimize düştü

Söylemekten bıktık

Dinlemekten  usandık

Yinede anlatamadık

Hep aynı daldayız

Yalnızlık yalnızlık yalnızlık', 'Savrulsun içimizde  Aşkın külleri, Yandığımız yetişirse  Yetişir  artık!  Bahçemizde en güzel aşk gülleri Elimiz bağlı dilimiz suskun Koynun...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Damlası']::text[], 8.5, '{"poet":"Yağmur Damlası","poet_slug":"yagmur-damlasi","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yalniziz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çekirdek', 'cekirdek-zafer-zengin-etnika-osjn5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir

hayat

buldum

sert

kabuk

içinde

küçük

bir

dev

içinde

canı

koca

bir

ev

sığındığım

11 Temmuz 2004', 'bir hayat buldum sert kabuk içinde küçük bir dev içinde canı koca bir ev sığındığım 11 Temmuz 2004...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cekirdek-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Mutluluğun Ertesidir..', 'ayrilik-mutlulugun-ertesidir-mehmet-kizilay-edqoe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ayrılık 

mutluluğun ertesidir

vuslat

ayrılığın başlama kertesidir.

sevmek ise; 

ölesiye sevişmelerin,

yapışıp kalmayan öpüşlerin

buruş buruş yatak örtülerinin

suda kirlenmesidir.

eeee

kalk 

uyuklama artık

uyandır şu gafil sabahı

bir de

seher vakti rüzgarının

resmini çekiver

deklanşöre basacak

yüreğin varsa tabii.', 'ayrılık  mutluluğun ertesidir vuslat ayrılığın başlama kertesidir. sevmek ise;  ölesiye sevişmelerin, yapışıp kalmayan öpüşlerin buruş buruş...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kızılay']::text[], 8.5, '{"poet":"Mehmet Kızılay","poet_slug":"mehmet-kizilay","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ayrilik-mutlulugun-ertesidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zengine liman', 'zengine-liman-zafer-zengin-etnika-pg0am', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir liman tutalım beyler

Bir liman ki

Yatımızın kokusuna 

Gelmesin balıklar

Takalar zincirlemesin ağacımıza

Kim gelirse

Hele parolayıda bilmezse

Alnın çatına kuralım tüfeğimizi

Öldürürüz bel ki canımız çekerse

Ah ulan deniz

Hep zenginleri sevdin

Elimiz mi dokundu sana

Ekmek koyarken kursağa

Kimi belledin yabana bırakmadan

Hep garibanları aldın

Zengine dokunmadın

Sövdüm ulan sövdüm/Suyuna/Hep garip boğuşuna

Yüzme bilmeyen bir alabalıktır/F a k i r l i k

30 Mayıs 2004', 'Bir liman tutalım beyler Bir liman ki Yatımızın kokusuna  Gelmesin balıklar Takalar zincirlemesin ağacımıza Kim gelirse Hele parolayıda bilm...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/zengine-liman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşgal', 'i-sgal-adnan-durmaz-txqq6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bakışım sonsuz bir tan sökümüydü

bombalanmış  coşkuları bilmeden önce

yürürken  kaldırımlar çiçek açardı

ayak izlerime kan dolmadan önce

insanlar gülüşümü güneş sanırdı

keder bulutları silmeden önce

zulümler ansızdan geldi küçüğüm

göğü ziftle  kapladılar

yeri tuzakla-

suyun aynası çatladı

kan karıştı şarkısına

kuşlarımız bombalandı bahar dallarında

kuşlarımız

milyonlarca

sanki ayak değildi

çelik postallarının içinde yere basan

ve metal ellerinin devamıydı silahları

yürekleri yoktu sanki

anaları yoktu yollarına bakan

ne bir sevgilileri

ne damarlarında kan

ne de sesleri insan...

sevda yağmaladılar

kan içtiler

zulüm kaleleri

zından diktiler

köşe başlarında korku nöbette

ve tren raylarında katloldu zaman

oysa ürperir ihtişamla

süt mavi karanlıkta

yıldızlar küçüğüm

tıpkı gözlerin gibi

zulmün gücü yetmese de bülbülün türküsüne

katledilmiş insanlar bakamaz gökyüzüne...

anaların ninnisini yaktılar

aşıkların düşlerini vay

yüreklerin kapıları kapandı

ışıklar korku yandı

unutuldu gecede bir başına ay

derler ki 

-o iyi insanlar

o güzel atlara

binip  gitti...

gencecik cesetler yatar yüreklerinde

yürekleri ki yaralı

tek sığınaklarıdır

ve tek silahları

cehennem  alanlarından kalan

şarkılarını toplamışlar

ve yalnızlık oturur terkilerinde



derler ki

o  iyi insanların

başka yerlerde her biri

bir büyük şarkının kıyısında yaşarlar

dilleri rüzgârın dilinden

kaşları çatılmış silahlar gibi

bir sevda bekler gibi tetikte yürekleri

derler ki

insanlığın yarasıdır yaramız

haksızlığa uğrayanın öz kardeşiyiz

okulda-sokakta-fabrikada tarlada

özgürlük kuşlar gibi şakımadıkça

ahd ettik

ölmeyeceğiz

senin gülüşlerin   gibi

çiçekler açmadıkça dünya

mutlu olmaya yetmez küçüğüm

sevgiler bizim için

umutlar bekleyecek

dağlar denizler kadar

ve kelle vereceğiz

eksilmesin diye coşkular

çalınmasın diye

avuçlarımızdan rüzgâr...

   l4.l2.l994 - Balçova

ADNAN DURMAZ

ben gidersem ay sendeler,art yay,ank', 'bakışım sonsuz bir tan sökümüydü bombalanmış  coşkuları bilmeden önce yürürken  kaldırımlar çiçek açardı ayak izlerime kan dolmadan önce ins...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/isgal-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çözümsüz', 'cozumsuz-gokhan-oflazoglu-7vg4l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beni oluşturan güçler,

benden yana değil.

Gideceğim bir yer yok,

burası da tekin değil.

Mutluluk yok ötelerde,

ben kalacaksam o yerde.

Eğer başka olacaksam,

o zaman ben nerde.

Bütün sorunlar çözülmüş bir gün

İçimdeki bu sıkıntı ne.....? 

30/07/2004', 'Beni oluşturan güçler, benden yana değil. Gideceğim bir yer yok, burası da tekin değil. Mutluluk yok ötelerde, ben kalacaksam o yerde. Eğer ...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/cozumsuz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulamayacaksın', 'bulamayacaksin-gokhan-oflazoglu-d8onj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İstediğin kadar ara, bulamayacaksın.

Saklandığı yeri neden söylesin.

Önemli olduğunu sen söylüyorsun,

öyle olsa, sana hayatı neden zehir etsin.

Hiçbir mesajı almadın, bütün bilgilere direniyorsun.

Böyle kurulmuş yapın, sen dünyaya bırakıldığın yerdesin.

Ama, gene de ara, başka ne yapabilirsin.

30/07/2004', 'İstediğin kadar ara, bulamayacaksın. Saklandığı yeri neden söylesin. Önemli olduğunu sen söylüyorsun, öyle olsa, sana hayatı neden zehir ets...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bulamayacaksin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim Sende Kaldı', 'kalbim-sende-kaldi-fatih-konuk-ttqjg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'KALBİM SENDE KALDI

Karanlık gecenin sabahında

Bu aşkın en ağır günahında

Genç ömrümün baharında

Seni kaybettim,seni kaybettim

Seni kaybettim been 

Umutlarım yarım kaldı

Hayallerim yarım kaldı

Her şeyin yanı sıra aah

Damarımda dolaşan kanımda

Seninle dolu dört yanımda

Ne sağımda nede solumda

Şimdi yoksun,şimdi yoksun

Şimdi yoksun seen', 'KALBİM SENDE KALDI Karanlık gecenin sabahında Bu aşkın en ağır günahında Genç ömrümün baharında Seni kaybettim,seni kaybettim Seni kaybettim...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kalbim-sende-kaldi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Ver Gülüm', 'bos-ver-gulum-fatih-konuk-ov8pg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '...BU ŞİİR 12’Lİ HECE ÖLÇÜSÜ İLE YAZILMIŞTIR...

BOŞ VER GÜLÜM

Uğrunda bir can yanmış neye değer ki

Yansın,yansın varsın yansın boş ver gülüm

Senin sevda ateşin bu bedenimi

Yaksın,yaksın varsın yaksın boş ver gülüm

Hayatın tadı,ömrünün son durağı

Hayatın güneşi,derdinin ortağı

Bu gönül seni son umudu,çaresi

Sansın,sansın varsın sansın boş ver gülüm

Her sabah üstüme doğmasın güneşim

Sen olmazsan olmasın bu güzel aşkım

Bir köşede hayatım ve yaşamım son

Bulsun,bulsun varsın bulsun boş ver gülüm

Ferhat,Mecnun ve ilk insan Adem bile

Bu alemde,on sekiz bin alem bile

Seni ne çok sevdiğimi ailem bile

Duysun,duysun varsın duysun boş ver gülüm 

Gökyüzünde uçan,süzülen kuşlarda

Yan yana sıralı bu yüce dağlarda

Seni sevdiğimi arkadaşlarında

Bilsin,bilsin varsın bilsin boş ver gülüm

Fatih derki ‘’sevdamız her şeyden öte

Ayrılığın sürükler bir avuç hapa’’ 

Bu şiirim kulağınıza da küpe

Olsun,olsun varsın olsun boş ver gülüm', '...BU ŞİİR 12’Lİ HECE ÖLÇÜSÜ İLE YAZILMIŞTIR... BOŞ VER GÜLÜM Uğrunda bir can yanmış neye değer ki Yansın,yansın varsın yansın boş ver gülüm...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bos-ver-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Revaneya Evînê', 'revaneya-ev-n-omer-demir-wsup7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Min diviya hez bikim

Te nediviya

Lê min hez nedikir

Te ji nû diviya

              -te hez dikir

Min bawer nedikir

Tu li rêyan digeriyayî

Min bawer dikir

Tu ji rêyan vedigeriyayî

Min diviya te bibînim

Tu direviyayî

Min diviya te nebînim

Tu li min digeriyayî

Tirs li te peyda dibûn

Te ji min dipirsiya

Kul li te peyda dibûn

Te ji min dipirsiya

Te ji jiyanê hez dikir

Tu ji min digeriyayî

Jiyanê bêbextî li te dikir

Tu li min digeriyayî

Ne te ji min hez kir

Ne ji min geriyayî

Ne te dilê min geş kir

Ne jî ji min veqetiyayî

Niha tu li aliyekê bêdeng

Ez li aliyekê

Lê em herdu ditirsin

Hem ji xwe

            -hem ji felekê.

2004-07-31', 'Min diviya hez bikim Te nediviya Lê min hez nedikir Te ji nû diviya               -te hez dikir Min bawer nedikir Tu li rêyan digeriyayî Min...', ARRAY['Türk Edebiyatı','Şiir','Ömer Demir']::text[], 8.5, '{"poet":"Ömer Demir","poet_slug":"omer-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/revaneya-evine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsterdim...', 'i-sterdim-ceyhan-i-cel-1wa69', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karanlık her gecede,

Bir sokak lambasının aydınlatan ışığında,

Çiseleyen yağmurun ardından seni beklerim,

Yine sen gelmesende,

Senin hayalimde canlanmanı,

Pencerenin kenarında oturupda,

Perdeyi aralayıp ve bakmanı isterdim.

Her geçtiğin yolun, her durduğun sokak

köşelerinin, her attığın adımın benim,

olmasını isterdim.

Akıttığın her gözyaşının,

Sana benzeyen her gülün,gönlümdeki,

Her yerinin benim olmasını isterdim.

İsterdim seninde benim yanımda olup,

Bana teselli olmanı, isterdim seni kollarımda

tutmak, saçlarını okşamak isterdim.

Ama sen yine yoksun,

Sen yoksun sen.....', 'Karanlık her gecede, Bir sokak lambasının aydınlatan ışığında, Çiseleyen yağmurun ardından seni beklerim, Yine sen gelmesende, Senin hayalim...', ARRAY['Türk Edebiyatı','Şiir','Ceyhan İçel']::text[], 8.5, '{"poet":"Ceyhan İçel","poet_slug":"ceyhan-i-cel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/isterdim-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbin Söylüyor', 'kalbin-soyluyor-ceyhan-i-cel-wbpo1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her doğan güneş, benim için doğacak,

Her yağan yağmur, benim için yağacak,

Her baharda açan gül, benim için kokacak,

Sen bunu bilmesende kalbin söylüyor..

Aşkımız bir olup yuva kuracak,

Sevgimiz gönlümüze neşe katacak,

Dertlerimize derman Allah olacak,

Sen bunu bilmesende kalbin söylüyor...

Hep seni aradım sokak aralarında,

Yine yalnız kaldım köşe başlarında,

Bırakıp gitmek, senin için kolay olsada,

Sen bunu bilmesende kalbin söylüyor...

Yıllarımı verdim ben hep sana,

Yine başbaşa bıraktın beni anılarla,

İsmin dilimde, sevgin gönlümde,

Sen bunu bilmesende kalbin söylüyor...', 'Her doğan güneş, benim için doğacak, Her yağan yağmur, benim için yağacak, Her baharda açan gül, benim için kokacak, Sen bunu bilmesende kal...', ARRAY['Türk Edebiyatı','Şiir','Ceyhan İçel']::text[], 8.5, '{"poet":"Ceyhan İçel","poet_slug":"ceyhan-i-cel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kalbin-soyluyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...ŞaFTı KaYMıŞ DüZeNiN...', 'safti-kaymis-duzenin-erdal-asik-ww7gs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hep karamsar kara gece

Sabahına dek bir eğlence

Çözebilen var mı sanki bilmece

Çözdüm diyenler yollarda

Çözemeyenler hepsi rüyada

Kimileri ağlıyor kaderine

Kimileri barların köşesine

Çalışanlar güneşin anlında

Çalışmayanlar gecenin ışıklarında

Sabaha kadar uyumuyor zenginler

Gündüzleri koşuşturuyor garipler

Hep oturuyorlar baş köşede

İşçiler üç kuruş maaş peşinde

Böyle gelmiş gitmez dedik 

Sonunda yine darbeyi yedik

Şaftı kaymış bu düzenin

Değiştirecek var mı söyleyin', 'Hep karamsar kara gece Sabahına dek bir eğlence Çözebilen var mı sanki bilmece Çözdüm diyenler yollarda Çözemeyenler hepsi rüyada Kimileri a...', ARRAY['Türk Edebiyatı','Şiir','Erdal Aşık']::text[], 8.5, '{"poet":"Erdal Aşık","poet_slug":"erdal-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/safti-kaymis-duzenin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esrik zamanlar', 'esrik-zamanlar-ozgur-doran-nsg8f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Esrik zamanlar toplamı öpüşlerin

Üzgün zamanların tadı var ellerinde

Gözlerin sessiz bir vazgeçiş oluyor

Sen kalsan bile giden bir şeyler var sesinde

Bakmak kalıyor benim payıma…

Bıraktığın palyaço ise gülüyor ışıldayan gözleri ile yeni güne', 'Esrik zamanlar toplamı öpüşlerin Üzgün zamanların tadı var ellerinde Gözlerin sessiz bir vazgeçiş oluyor Sen kalsan bile giden bir şeyler va...', ARRAY['Türk Edebiyatı','Şiir','Özgür Doran']::text[], 8.5, '{"poet":"Özgür Doran","poet_slug":"ozgur-doran","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/esrik-zamanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrümüz Bitmeden...', 'omrumuz-bitmeden-ceyhan-i-cel-zuu0z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şu fakir ömrümüz gelmiş geçiyor,

Her güneşin doğuşu, cefa ile batıyor,

Şu dünyanın sefasını sürenler sürüyor,

O sefayı sürermiyiz, ömrümüz bitmeden...

Ne vardı şu üçgünlük dünyada bizde gülseydik,

Şu dünyayı azda olsa bizde sevseydik,

Mutluluk, gülmek nedir bizde görseydik,

Şu kadersiz ömrümüz, sona ermeden...

Her zaman her yerde hor görülüp ezildik,

Garipler kervanına her zaman biz dizildik,

Vezirler ordusunda daima, biz rezildik,

Kurtar şu gariplikten, ömrümüz bitmeden...

Ne istedikse hiç alamadık, üzüldük,

Hep başkasına eğilip, her zaman büküldük,

Hor görüldük, her zaman küçük düşürüldük,

Güldür yüzümüzü şu ömrümüz bitmeden...', 'Şu fakir ömrümüz gelmiş geçiyor, Her güneşin doğuşu, cefa ile batıyor, Şu dünyanın sefasını sürenler sürüyor, O sefayı sürermiyiz, ömrümüz b...', ARRAY['Türk Edebiyatı','Şiir','Ceyhan İçel']::text[], 8.5, '{"poet":"Ceyhan İçel","poet_slug":"ceyhan-i-cel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/omrumuz-bitmeden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoksun Yanımda...', 'sen-yoksun-yanimda-ceyhan-i-cel-56cka', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karanlık gecelerde,

dışarıda öyle bir soğuk var ki,

öyle bir kuru ayaz,

iliklerime kadar işliyor sanki.

Ben bilirim bunları, o soğuklarda,

dışarıda yalnız kalmaları,

Çünkü sen yoktun yanımda....

Karanlık gecelerde,

sen sıcak yuvanda,

dertsiz ve tasasız,

ben dışarıda yapayalnız,

tek dostum sarıldığım gazete parçaları,

derdimi paylaştığım sokak kaldırımları

ve dolaşan siyah, beyaz renkli,

yavru kedilerdi, arkadaşım.

Ben bilirim bu hayatın,

acı günlerini,

Çünkü sen yoktun yanımda...

Karanlık gecelerde,

çaresiz geçiyordu günlerim,

hayat öyle acımasız ki,

zaman öyle çabuk geçiyor ki,

kaybolmuştu bütün hayallerim,

bir ümüt ışığı aradım  o yerlerde,

aç ve susuz beklediğim saatlerde,

yapayalnız tek başımaydım, yine gecelerce.

Ben bilirim bunları,

Çünkü sen yoktun yanımda...

Karanlık gecelerde

kulaklarımı sağır edercesine,

esen rüzgarın uğultusunu,

denizdeki dalgalar coştukca,

sahile vuran suyun sesini.

Yüreğimde senin için yanan hasret ateşini,

gözlerimden  akan yaş yerine, kan damlalarını,

 seni her zaman seven, ceyhan''ın acısını,

ben bilirim bunları,

Çünkü sen yoktun yanımda...', 'Karanlık gecelerde, dışarıda öyle bir soğuk var ki, öyle bir kuru ayaz, iliklerime kadar işliyor sanki. Ben bilirim bunları, o soğuklarda, d...', ARRAY['Türk Edebiyatı','Şiir','Ceyhan İçel']::text[], 8.5, '{"poet":"Ceyhan İçel","poet_slug":"ceyhan-i-cel","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/sen-yoksun-yanimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol', 'yol-yusuf-koc-hornw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaktım yeşil ışığı,

yol verdim sevdalara...

tek yönlü yol bu,

dönüşü yok...

artık aramayacağım aşkı..! 

puslu bir göz bakışında...

Yol verdim sevdalara,

tam gaz gitsinler diye açtım önlerini..

kalbimi kıramayacaklar artık...

gönlümü çelemiyecekler artık...

ben...ben olacağım artık.! !', 'Yaktım yeşil ışığı, yol verdim sevdalara... tek yönlü yol bu, dönüşü yok... artık aramayacağım aşkı..!  puslu bir göz bakışında... Yol verdi...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Koç']::text[], 8.5, '{"poet":"Yusuf Koç","poet_slug":"yusuf-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yol-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Gidiyorum', 'ben-gidiyorum-esin-ege-psb2b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben çok uzaklara  gidiyorum

Aranmazlara, sorulmazlara,uğranmazlara

Bulunmaz diyarlara gidiyorum bir başıma

Ben çok uzaklara gidiyorum

Ben bir sevda uğruna gidiyorum uzaklara

Sonu olmayan,ümidi olmayan,yasa dışı bir sevda

Bir memleketim varmıydı bir zamanlar

Hiç bir şey bilmiyorum yersiz yurtsuzum ben

Memleket bildiğim bana gurbet bile olamaz artık

Adını unuttum yollarını unuttum kendimi kaybettim

Sıcacık sevgiler yüklü diyarımdan 

Ben çok uzaklara gidiyorum sevdiceğim

Yıkılıp düştüğüm yer bilki mekanım', 'Ben çok uzaklara  gidiyorum Aranmazlara, sorulmazlara,uğranmazlara Bulunmaz diyarlara gidiyorum bir başıma Ben çok uzaklara gidiyorum Ben bi...', ARRAY['Türk Edebiyatı','Şiir','Esin Ege']::text[], 8.5, '{"poet":"Esin Ege","poet_slug":"esin-ege","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ben-gidiyorum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Genç Öldün Sevdiceğim', 'genc-oldun-sevdicegim-esin-ege-s22t2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bazıları yaşarken ölüdür

Bazıları ölürken yaşarlar

Bazıları genç bazıları yaşlı ölür

Bir tanem

Sen hem gençtin hem genç öldün

Ben yaşadıkça sen hep genç kalacaksın

Ben yaşamasamda yine yaşlanmayacaksın', 'Bazıları yaşarken ölüdür Bazıları ölürken yaşarlar Bazıları genç bazıları yaşlı ölür Bir tanem Sen hem gençtin hem genç öldün Ben yaşadıkça ...', ARRAY['Türk Edebiyatı','Şiir','Esin Ege']::text[], 8.5, '{"poet":"Esin Ege","poet_slug":"esin-ege","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/genc-oldun-sevdicegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonu Bölüşeceğiz Seninle', 'sonu-bolusecegiz-seninle-esin-ege-0cnqz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ötesi yok, çaresi yok, kurtuluşu yok

Tutacaksın elimi ve geleceksin benimle

Arkamıza bakmadan alev ateş engelleri

Yada sonumuz olacak o ateş

Arkaya bakmak en tehlikelisi işin

Bir göz takılır yüreklerimize bi çare

Sonumuz olur gitmelerimizin

Haydi tut ellerimi vakit gitmek zamanı 

Seni bırakıpda gidemem o hayal ülkesinde

Engelmiş, yokuşmuş, sonsuzlukmuş

Vız gelir sevda yüklü yüreyime

Unutturamayacak seni hiç birşey

Ben yaşadıkça sende bende yaşayacaksın

Aldığım tek nefesi  bölüşeceğim seninle

Ve o korkunç gün gelip çattığında İşte o anda 

Bölüşeceğim son nefesimi bile seninle

Yaşarken bu dünyada

Ölümden kaçamadığım gün mahşerde

Sımsıkı tutacağım ellerini bende olacaksın

Günahlarını paylaşacağım seninle', 'Ötesi yok, çaresi yok, kurtuluşu yok Tutacaksın elimi ve geleceksin benimle Arkamıza bakmadan alev ateş engelleri Yada sonumuz olacak o ateş...', ARRAY['Türk Edebiyatı','Şiir','Esin Ege']::text[], 8.5, '{"poet":"Esin Ege","poet_slug":"esin-ege","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sonu-bolusecegiz-seninle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müjdeler olsun', 'mujdeler-olsun-esin-ege-wjrc0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Doğumu bekleyen gözü yaşlı sancılı kadınlar

Müjdeler olsun 

Söküp alacağım içinizden o acıyı

Bu gece ben doğuracağım 

Doğurup atacağım yanlızlığımı içimden', 'Doğumu bekleyen gözü yaşlı sancılı kadınlar Müjdeler olsun  Söküp alacağım içinizden o acıyı Bu gece ben doğuracağım  Doğurup atacağım yanlı...', ARRAY['Türk Edebiyatı','Şiir','Esin Ege']::text[], 8.5, '{"poet":"Esin Ege","poet_slug":"esin-ege","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/mujdeler-olsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok öyle şey', 'yok-oyle-sey-yusuf-koc-ketgz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öyle planlı, programlı yaşamak mı dileğimiz.? 

ölçülmüş hayatımızın her milimetre karesini..! 

kemikleşen alışkanlıklarımızı mı sürdürüyoruz..tik takların gölgesinde...

Yok öyle................

ne yandan geldiği bilinmeyen,

belki paslı bir namludan,

belki bir kara elden,

değeri üç para bile olmayan..! 

mermiye hedef olmak ta var...yaşam da..

Ya da.......

ne idüğü belirsiz birine tutulmak ta..

ve o zaman bir şarkı gelir akla..! 

''''seyret ki şafakları akşam olmak ta,,', 'Öyle planlı, programlı yaşamak mı dileğimiz.?  ölçülmüş hayatımızın her milimetre karesini..!  kemikleşen alışkanlıklarımızı mı sürdürüyoruz...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Koç']::text[], 8.5, '{"poet":"Yusuf Koç","poet_slug":"yusuf-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yok-oyle-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Gökleri Ağlatır', 'ayrilik-gokleri-aglatir-necmi-unsal-5h8e5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ulaşılmaz sisli hayalin zirvesi

Akseder serabın kara gölgesine.

Sevda ateşinde anılar cezvesi

Kaynayıp dökülür gönül bölgesine.

Ateş böcekleri sürgün kör bir aşka.

Ay ışığı hüznü, kederi damlatır.

Bu yorgun dağların derdi daha başka.

Ayrılık gökleri sarsar da, ağlatır.

21 Mayıs 2004 Cuma, Danimarka-Køge 00.19

6+6', 'Ulaşılmaz sisli hayalin zirvesi Akseder serabın kara gölgesine. Sevda ateşinde anılar cezvesi Kaynayıp dökülür gönül bölgesine. Ateş böcekle...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ayrilik-gokleri-aglatir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aforizmalar I', 'aforizmalar-i-zafer-zengin-etnika-3osem', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '~| o uzun metni yazdım

en kısa sürede göreceksin

olmuyorla başlayacak başlığı |~

En uzun şiirleri

Biz yazacaktık

Uzattıkça uzattık

Sesimizi kopardık

Kısa yazsam olmaz

Gül düşmüş yüzünü

Kısa anlatayım

İyi ki aklımdasın

30 Temmuz 2004', '~| o uzun metni yazdım en kısa sürede göreceksin olmuyorla başlayacak başlığı |~ En uzun şiirleri Biz yazacaktık Uzattıkça uzattık Sesimizi ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aforizmalar-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar', 'yar-ali-gencay-nt6ga', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'düştüm elinden, 

düştüm yar dilinden

ben beni dedim,

dinledin kendi dilinden

koca acın,

ateş kusan ejderha devasa sancın

ne kadar incesin içimde,

dağ deviren ince sızın

iki omzum,meleklerin 

biri kal der diğeri sen bilirsin

evet ben bilirim 

bildiğim yanan hasretin', 'düştüm elinden,  düştüm yar dilinden ben beni dedim, dinledin kendi dilinden koca acın, ateş kusan ejderha devasa sancın ne kadar incesin iç...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yar-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Köşede...', 'bir-kosede-ceyhan-i-cel-kw97f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sabah olupda gün ağardığında

güneşi göremezsen.

Fırtınalar koptuğunda dalgaların

feryatlarını duyamazsan.

Gece olurda, karanlık çöktüğünde

yıldızları seçemezsen.

Arama beni,  bir köşede kaybolmuşumdur...

Bahçende çiçekler açtığında, onların

kokusunu alamazsan.

Damla damla yağmur, pencerene değdiğinde

yokluğumdan korkarsan.

Kapının her sefer vuruluşunda

geldiğimi zannedersen.

Boşuna bekleme, bir köşede kaybolmuşumdur...', 'Sabah olupda gün ağardığında güneşi göremezsen. Fırtınalar koptuğunda dalgaların feryatlarını duyamazsan. Gece olurda, karanlık çöktüğünde y...', ARRAY['Türk Edebiyatı','Şiir','Ceyhan İçel']::text[], 8.5, '{"poet":"Ceyhan İçel","poet_slug":"ceyhan-i-cel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-kosede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pantolon Cepleri', 'pantolon-cepleri-esma-ozdemir-v9p3n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Herşeyidir

Bir erkeğin pantolon cepleri…

En kıymetli hazineleri

Ve sesli ve sessiz

Bütün malzemeleri

Ceplerinde gizli…

Anahtarları

Evinin, işinin, arabasının

Manitasının…

Çakmağı, cüzdanı, tespihi

Bozuk parası, kâğıt parası

Sürpriz yumurtası, misketi

Damla sakızlı naneli cikleti

Buruşmuş kağıt mendili

Pasaportu, kimliği, ehliyeti

Telefonu, kredi kartı

Çakmağı, kürdanı, kibriti 

Vesikalık fotoğrafı

Aynası, tarağı, çakısı

Jetonu, akıllı kartı

Tırnak makası

Ve hatta otobüs bileti

Daha neleri, neleri, neleri..!

Şimdi düşünün ki bir erkek

Sağ eli pantolon cebinde

Sürekli oynamadan

Karıştırmadan

Ne var ne yok, diye bakmadan

Anahtarları, canım!

En basiti...

Ya kaybederse..!

Değil mi? 

Başını göğe dikip 

Gözlerini devirmeden 

Hayal kurmadan

Onlarla nasıl yaşasın ki! ...

Hooop..! Bir dakika lütfen

Orada durun!

Yanlış anlamayın millet! 

Allah daha çok versin! 

Maksat, muhabbet…!

Neticede

Kimsenin pantolon ceplerinde

Gözümüz yok ki!', 'Herşeyidir Bir erkeğin pantolon cepleri… En kıymetli hazineleri Ve sesli ve sessiz Bütün malzemeleri Ceplerinde gizli… Anahtarları Evinin, i...', ARRAY['Türk Edebiyatı','Şiir','Esma Özdemir']::text[], 8.5, '{"poet":"Esma Özdemir","poet_slug":"esma-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/pantolon-cepleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül! .', 'gonul-abdusselam-bugur-sy5nn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne akşamın belli, ne de sabahın

''''Senin ile bir türlü uyuşamadım gönül.

Kayb olup gitti bu kargaşada sevdalarım

Beni yollara-Beni dillere savurdun gönül! .

Vefasız yürekler hep bana mi çattı? 

Yaktıkça yaktılar kül oldum gönül! .

Mutluluk denizlerinde hayallerim battı

Yağmurlar bekleyen çöl oldum gönül! .

Artık her şey bitti bulutlar''da çekildi

Yağmurlar bize yağmaz gönül

Artık her şey bitti sevdalar''da son bahar

yarınları bekleme bize gün doğmaz gönül! .

Düşün ki, ferhat neden dağ deldi? 

Ya mem''ı alan zindan''da can verdi gönül! ...', 'Ne akşamın belli, ne de sabahın ''''Senin ile bir türlü uyuşamadım gönül. Kayb olup gitti bu kargaşada sevdalarım Beni yollara-Beni dillere sa...', ARRAY['Türk Edebiyatı','Şiir','Abdüsselam Bügür']::text[], 8.5, '{"poet":"Abdüsselam Bügür","poet_slug":"abdusselam-bugur","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gonul-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başkası Yok', 'baskasi-yok-i-smet-barlioglu-bmle4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şükür sana yaratan ''ım,

Ey, darlardan kurtaranım,

Ben kulunum, ben kurbanım,

Büyük sensin. Başkası yok.

Merhametli ve cömertsin,

Kainatta tek mert sensin,

Sen yücesin, sen Hazret ''sin,

Ulu sensin. Başkası yok.

Her zerrenin kanadı var,

Akıl almaz sür ''ati var,

İnanılmaz takati var,

Alim sensin. Başkası yok.

Cansız canlı yaratamaz,

Varlıkları yaşatamaz,

Çapsız alem kuşatamaz,

Dahi sensin. Başkası yok.

Sen kaadirsin, kuvvetlisin,

Lütufkarsın, himmetlisin,

Azametli, heybetlisin,

Yüce sensin. Başkası yok.

Sana huylu, huysuz birdir,

Sana nurlu, nursuz birdir,

Sana hırlı, hırsız birdir,

Adil sensin. Başkası yok.

Cennet verdin. Aradılar,

Lutfeyledin. Doymadılar.

Hep göründün. Görmediler,

Mevcud sensin. Başkası yok.

Eşin yok ki; benzeteyim,

Seni nasıl methedeyim? 

Mümkün mü ki; bilmeyeyim? 

Aziz sensin. Başkası yok.

(ERZURUM SANKİ YAYLA isimli hece şiirlerinden > 83-85/100)', 'Şükür sana yaratan ''ım, Ey, darlardan kurtaranım, Ben kulunum, ben kurbanım, Büyük sensin. Başkası yok. Merhametli ve cömertsin, Kainatta te...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/baskasi-yok-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim...Öldüm....', 'sevdim-oldum-fatih-taskin-0jcte', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '.........sevdim

Dehlizlere düşmüş yüreğimle

Yalanlarla çevrili gölgemle

Gönlümde soldurduğum çiçeklerle

Öperken yaşadığım titremeyle

.........sevdim...............

.............geldim

Kavuşmanın verdiği heyecanla

.......doğup,dudaklarında yok olmaya

Yaşanan onca güzel hatıramla

Ve tabiki aşkım sana

................geldim...........

...........gördüm

Bana yaşattığın ihanet anını

Bu yüzden çektiğin vicdan azbını

Gözlerini gözümden kaçırışını

Hançerli kalbime vefasızlığını

...........gördüm...........

............kaçtım

Dost görünüp yüzüme gülen yılanlardan

..................,pırlantalı aşklardan

Yalnızken bile,yanlızlığımdan 

Sevemediklerimden  ve hayattan

.............kaçtım.............

............öldüm

Ebede kadar aşkı içime gömerek

Üzerine vefasızlık gülleri dikerek

Onları sevda kor''umda kinle besleyerek

Yaşamazken bile yaşadığımı zannederek 

...........Öldüm...........

Balıkesir  2003

Siyah bereli......', '.........sevdim Dehlizlere düşmüş yüreğimle Yalanlarla çevrili gölgemle Gönlümde soldurduğum çiçeklerle Öperken yaşadığım titremeyle ..........', ARRAY['Türk Edebiyatı','Şiir','Fatih Taşkın']::text[], 8.5, '{"poet":"Fatih Taşkın","poet_slug":"fatih-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sevdim-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İdrak Edemezsin', 'i-drak-edemezsin-i-smet-barlioglu-l0wuy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilyenin, balonun güzelliğini

İdrak edemezsin çocuklaşmazsan.

Hayatın tadını, derinliğini

İdrak edemezsin çocuklaşmazsan.

Çocuk kanatlanıp göğe yükselir,

Toz-toprak içinde bile eğlenir,

Toprak dile gelir, taşlar dillenir,

İdrak edemezsin çocuklaşmazsan.

Sular içebilir söğütten atlar,

Uçmaya elverir bezden kanatlar,

Bulvarlara döner keskin sıratlar,

İdrak edemezsin çocuklaşmazsan.

Kiremit biberdir, çamurlar ekmek,

At olup şahlanır kurumuş değnek,

Aslan bir babadır, anadır leylek,

İdrak edemezsin çocuklaşmazsan.

Cinler arkadaştır, periler de dost,

Uçmaya hazırdır halılarla post,

Buyruk alır heykel, buyruk verir büst,

İdrak edemezsin çocuklaşmazsan.

Kumlardan sarayı kim yapabilir? 

Kral kızlarını kim alabilir? 

Kim tahta kılıcı kuşanabilir? 

İdrak edemezsin çocuklaşmazsan.

Çocuğa saraydır, ''Çöplük'' dediğin,

Ona bilinendir bilemediğin,

Çocuğa görünür göremediğin,

İdrak edemezsin çocuklaşmazsan.

Çocuk olmazları olur edendir,

Çocuk mucizeyle dolu bedendir,

Çocuğun ülkesi tam bir evrendir,

İdrak edemezsin çocuklaşmazsan.

(ERZURUM SANKİ YAYLA isimli hece şiirlerinden > 86-88/100)', 'Bilyenin, balonun güzelliğini İdrak edemezsin çocuklaşmazsan. Hayatın tadını, derinliğini İdrak edemezsin çocuklaşmazsan. Çocuk kanatlanıp g...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/idrak-edemezsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk Hamamları', 'turk-hamamlari-i-smet-barlioglu-zqxae', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tepede bir kubbe, yanda kubbeler,

Petekler halinde tüm pencereler,

Camlar binbir renkte güneşi eler,

Bir düştür, masaldır Türk Hamamları.

Kapıdan girince başlar ferahlık; 

Kubbeli bölmeler, mermer sahanlık,

Somaki mermerden bir de selamlık,

Bir düştür, masaldır Türk Hamamları.

Ortada bir güzel, görkemli havuz,

Muhteşem fıskiye sanki kesme buz,

Bembeyaz mermerden dilimli karpuz,

Bir düştür, masaldır Türk Hamamları.

Havlular, peştemal gül gibi kokar,

İnsan imrenerek, severek bağlar,

Takılır ayağa süslü nalınlar,

Bir düştür, masaldır Türk Hamamları.

Adım çalımlıdır yüksek nalınla,

Azamet taslarsın peştemalınla,

Bambaşka olursun herbir halinle,

Bir düştür, masaldır Türk Hamamları.

Önünde bir kapı; mermer kemerli,

Belli; yapan usta yaman hünerli,

Zemzemle yıkanmış o usta eli,

Bir düştür, masaldır Türk Hamamları.

Serin bir koridor kapı arkası,

Mermerden her yanı ve taraçası,

Burası sıcakla soğuk arası,

Bir düştür, masaldır Türk Hamamları.

Taraça önünde levha çift sıra,

Petek göz açılmış levhalıklara,

Mermerler döşenmiş basamaklara,

Bir düştür, masaldır Türk Hamamları.

Yeniden bir kapı. Ötesi hamam,

Öyle güzelliği pek anlatamam,

Onca hücre var ki; kalkıp sayamam,

Bir düştür, masaldır Türk Hamamları.

Hücre girişleri mermer kemerli,

Hem yaman görkemli hem de değerli,

San ''atı döktürmüş ustanın eli,

Bir düştür, masaldır Türk Hamamları.

Hücrede kurnalar, mermer sedirler,

Kurnaları gören hayretten titrer,

Kabartmalar, süsler ve gravürler,

Bir düştür, masaldır Türk Hamamları.

Daire şeklinde içi hamamın,

Biri obirinden güzel kurnanın,

Mest olası gelir gören insanın,

Bir düştür, masaldır Türk Hamamları.

Ortada mermerden bir göbek taşı,

Yatanın dinlenir ayağı, başı,

Yerine oturur göz ile kaşı,

Bir düştür, masaldır Türk Hamamları.

Şırıl şırıl taşar kurnalardan su,

Bedenler ferahlar, kalmaz kaygusu,

İncelir ruhların kalın duygusu,

Bir düştür, masaldır Türk Hamamları.

Natırlar ovarlar mafsallarını,

Gövdeni, başını, el ve kolunu,

Işıklar andırır Çin Masalı ''nı,

Bir düştür, masaldır Türk Hamamları.

Değişir ıslanan havlu, peştemal,

Sularda yıldızlar, kubbede hilal,

Çıkılır hamamdan yanaklar al al,

Bir düştür, masaldır Türk Hamamları.

Serinlikte biraz soluk alınır,

Dışarda yeniden havlu sarılır,

Yıkanan yerine geçer, kurulur,

Bir düştür, masaldır Türk Hamamları.

Kasede sunulur buz gibi şerbet,

Başlar başkasıyla sohbet, muhabbat,

İstersen gir dene, istersen seyret,

Bir düştür, masaldır Türk Hamamları.

(ERZURUM SANKİ YAYLA isimli hece şiirlerinden > 89-93/100)', 'Tepede bir kubbe, yanda kubbeler, Petekler halinde tüm pencereler, Camlar binbir renkte güneşi eler, Bir düştür, masaldır Türk Hamamları. Ka...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/turk-hamamlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhammed Mustafa', 'muhammed-mustafa-i-smet-barlioglu-85wo2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Muhammed Mustafa var kalbimin merkezinde,

O ''nu ölüden saymam; O en diri olandır.

En büyük peygamberlik mührü O ''nun elinde,

Yalnız peygamber değil, O en büyük insandır.

Yüzyıllardan beridir güzelliği solmadı,

Milyonlar O ''ndan başka nefesi solumadı,

Bir seldir ki; tek engel O ''nu durduramadı,

Sönmeyen ateş gibi yüreklerde yanandır.

Davranışlarına bak, tek yanlış bulur musun? 

Sözü bir, yaptığı bir, hiç karşı durur musun? 

Öyle berrak kaynağa tozlar kondurur musun? 

O, hayırsız çöllerde hayırla uyanandır.

Güneştir ki; ışığı ne söndü, ne eksildi,

Yağmurdur ki; hep yağdı. Ne durdu, ne eksildi,

Tanrı ''nın buyruğunu hep aldı, hep bildirdi,

Menzilleri aşarak vahaya uzanandır.

O ''nunla cana geldi kurumuş, bitmiş hayat,

O bir kapı; ardında hayır, hayrat, hasenat,

Ardından gidilecek durdukça bu kainat,

Muhammed bir kıblegah, Muhammed bir canandır.

(ERZURUM SANKİ YAYLA isimli hece şiirlerinden > 94-95/100)', 'Muhammed Mustafa var kalbimin merkezinde, O ''nu ölüden saymam; O en diri olandır. En büyük peygamberlik mührü O ''nun elinde, Yalnız peygambe...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/muhammed-mustafa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aç Kollarını Sonsuzluk Geliyorum', 'ac-kollarini-sonsuzluk-geliyorum-atilla-guler-tqi9t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hiç eksilmedi adımlarım sana doğru

Her gün

Her saniye

Kanım çekilse de damarlarımdan

Hep sana

Sevişme saatlerini çaldın benden

Uçurumlara düştü aklım

Gözyaşları çaldı kapısını sevenlerin

Karanlık konuk oldu odama

Kırmızı bir çiçek bıraktı aşk

Yakılan her yasak umarsız şehrin yollarında

Fahişe sokaklarda

Müşteri avına çıktı soğuk ölüm

İstemedim

istemedin

Kapımızın önüne çöreklendi yılan misali

Oradan hiç ayrılmadı

Biz konuk etmedik onu içeri

İstedi ve aldı

Kısır bir döngüye bıraktık hayatı

Doğduk

Büyüdük

Ölümden kaçamadık

Aç kollarını sonsuzluk

Geliyorum', 'Hiç eksilmedi adımlarım sana doğru Her gün Her saniye Kanım çekilse de damarlarımdan Hep sana Sevişme saatlerini çaldın benden Uçurumlara dü...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ac-kollarini-sonsuzluk-geliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın İntiharı', 'askin-i-ntihari-yasar-pullu-fy627', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Balık yağından gözlerin vardı

bir seferde yutulan

ağır kara saban gibi bir yürek

sürdü gözlerini

büyümedi aşk.

Ben uzakara

haydutuydum şehirlerin

hep bir yanım çıplak

reklamların kenarından geçerdim

-bu hesap 2010 da kapanacak-

sürüngen bir sevda dökülürdü ceplerimden

Babam abdest alırdı her sabah

ben çoktan kılmıştım namazını

öldü aşk.

-----

Namaza duruldu

hoca sordu

nasıl bilirdiniz

herkes sustu

kimse bilmiyordu

-------

İki kişilik bir savaştı aşk

kazanan yoktu

görgü tanıklarına göre vurulmuştu

bana göre intihar.

Bu yamalı yorgunlukları kentin

bu terlemiş orospular

spermli duvarlar

ve boyalı adamlar

utanmıştı aşk

yok yok 

bu kesin intihar.', 'Balık yağından gözlerin vardı bir seferde yutulan ağır kara saban gibi bir yürek sürdü gözlerini büyümedi aşk. Ben uzakara haydutuydum şehir...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Püllü']::text[], 8.5, '{"poet":"Yaşar Püllü","poet_slug":"yasar-pullu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/askin-intihari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennetin Ortası', 'cennetin-ortasi-i-smet-barlioglu-dpykz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Süslendi yine gök, yine bulutlar,

Yıldız yağmurları arasındayım.

Yine filizlendi solan umutlar,

Bir yeni cennetin ortasındayım.

Mehtaplar altında ellerim, yüzüm,

Bir şarkıya döndü en yavan sözüm,

Renkler avucumda bir salkım üzüm,

Eriyen bir hüznün ortasındayım.

Ruhum vecde gelmiş hasret içinde,

Aklım bir kervanın yorgun göçünde,

Bedenim yücelmiş binbir biçimde,

Bir yeni temelin binasındayım.

Kalsam da, ölsem de, değişen olmaz,

Zira; iz bıraktım, izim kaybolmaz,

Sanma ki; hatıram asla bulunmaz,

İnce parmakların kınasındayım.

(ERZURUM SANKİ YAYLA isimli hece şiirlerinden > 96-97/100)', 'Süslendi yine gök, yine bulutlar, Yıldız yağmurları arasındayım. Yine filizlendi solan umutlar, Bir yeni cennetin ortasındayım. Mehtaplar al...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cennetin-ortasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayan İhtiyar', 'aglayan-i-htiyar-i-smet-barlioglu-lp3pg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ağlama ihtiyar, yüreğim kanar,

Sana her bakışta yaralanırım.

Böyle mi ıslanır çökmüş yanaklar? 

Halini gördükçe paralanırım.

Yemedin yedirdin çocuklarına,

Kulla-kurban oldun ayaklarına,

Canından can verdin varlıklarına,

Düşünüp durdukça duyarlanırım.

Herbiri büyüdü geçen zamanda,

Birer iş kurdular şu ve bu yanda,

Kızların evlendi gereken anda,

Duydukça öğrenir, yararlanırım.

Derken eşin öldü, kaldın çaresiz,

Sığındın onlara ayaksız-elsiz,

Yaşadın korkarak ağızsız-dilsiz,

Yerlerinde olsam; çok arlanırım.

Sevmedi gelinler, irdedi damat,

Seni yük saydılar evlada inat,

Onlara kalsaydı bari kainat,

Aklım zorlanır da zararlanırım.

O attı top gibi bunun sırtına,

Bunun evinde de koptu fırtına,

Varsın ellerine yaksınlar kına,

İnsanım; onlarla karalanırım.

Sonunda attılar huzurevi ''ne,

Büyük iş yaptılar sevine-güle,

Yıllarca bekledin; biri görüne,

Yanarım yerine, çıralanırım.

Bayrama güvendin ta arefeden,

Ne bir gelen oldu, ne de bir giden,

Ağlamaktan başka ne gelir elden? 

Ağlama. Yerine sıralanırım.

(Hikmet BARLIOĞLU (1933-2003)   ''nun

ERZURUM SANKİ YAYLA isimli hece şiirlerinden > 98-100/100)', 'Ağlama ihtiyar, yüreğim kanar, Sana her bakışta yaralanırım. Böyle mi ıslanır çökmüş yanaklar?  Halini gördükçe paralanırım. Yemedin yedirdi...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/aglayan-ihtiyar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yırtıp Atma Resmimi, Bir Köşede Yaşlansın', 'yirtip-atma-resmimi-bir-kosede-yaslansin-i-smet-barlioglu-q36x3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yırtıp atma resmimi, bir kçşede yaşlansın,

Gözyaşını elimle sildiğimi unutma.

Resmime gülümse ki; yüreğim telaşlansın,

Seni candan yürekten sevdiğimi unutma.

Saçlarını tararken bir kristal aynada

Unutma ki; ben varım senle aynı odada,

Bir ömür bakmak için durmuşum bir kenarda,

Saçında tel tel olup durduğumu unutma.

Unutma gönüllerden gönüllere yol vardır,

Kalplerdeki uzaklık incecik kıl kadardır,

Seven uzak da olsa; inan ki; yakondadır.

Gönlümde sana bir yer verdiğimi unutma.

Ne unut ellerimi saçlarına değerken,

Ne unut gözlerimi sana dalıp giderken,

Mazimiz eski değil, unutmak henüz erken,

Kollarımı boynuna sardığımı unutma.

(BAYRAM AKŞAMLARI isimli hece şiirlerinden > 7-8/100)', 'Yırtıp atma resmimi, bir kçşede yaşlansın, Gözyaşını elimle sildiğimi unutma. Resmime gülümse ki; yüreğim telaşlansın, Seni candan yürekten ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yirtip-atma-resmimi-bir-kosede-yaslansin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beşinci Mevsim', 'besinci-mevsim-caner-kuru-pwcqk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kulun bu kadar güzel olamaz,

Onu anlatacak bir söz diyemem.

Tanrım yarattığın insanla kalmaz,

Sanki ay parçası, bir yüz diyemem.

Görünce tutuldum, çıkmadı sesim

Çarpıldım sanki ben, geldi ölesim

Havası, kokusu beşinci mevsim

Bir bahar diyemem, bir yaz diyemem.

Merhemler faydasız yaktığı yere,

Kapılan gidiyor aktığı yere,

Yıldırım düşüyor baktığı yere,

Sanki yakan alev, bir göz diyemem.', 'Bir kulun bu kadar güzel olamaz, Onu anlatacak bir söz diyemem. Tanrım yarattığın insanla kalmaz, Sanki ay parçası, bir yüz diyemem. Görünce...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/besinci-mevsim-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yelkenli', 'yelkenli-caner-kuru-hhee3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gecelerin en siyahı,

Yine çöktü üzerime.

İşlemezdim bu günahı

Felç inseydi yüreğime.

Aşktır derler, yalan diye,

Duyguların en güzeli.

Benzer aynı yelkenliye,

Ters taraftan eser yeli.

Mutluluğa gitmek için,

Çekersin hep küreğini.

Alabora etmek için

Yıkar bile direğini.

Kapılalı ben bu aşka,

Gözlerimde fer kalmadı.

Bir Allah var, inan başka

Sığınacak yer kalmadı.', 'Gecelerin en siyahı, Yine çöktü üzerime. İşlemezdim bu günahı Felç inseydi yüreğime. Aşktır derler, yalan diye, Duyguların en güzeli. Benzer...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yelkenli-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İste', 'i-ste-ali-gencay-gj7c5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I-

İste benden

Yangınlarımı

Tanı ateşi hapsedeni

Yanarımda 

Ateşim avutamaz üşümelerini

II-

İste benden

Mavilerini 

Kırmızılarını 

Pembelerini

Yıka yüzünü

Akıt tüm boyalarını

Aynaya ver güzelliğini

Ver ki  kırılsın 

Sana benden çok bakan

Aynanın şehveti

III-

İste benden

Geyve‘nin güllerini

Mono rosa şiirlerini

Ihlamurlar açarken geleceğim

Al mendile sar

Telli turnayla haber sal

iste

Özlemlerini

IIII-

İste benden

Bende ki seni

İste ki

Azat et esirini', 'I- İste benden Yangınlarımı Tanı ateşi hapsedeni Yanarımda  Ateşim avutamaz üşümelerini II- İste benden Mavilerini  Kırmızılarını  Pembeleri...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/iste-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Habersizce Gidiş', 'habersizce-gidis-muammer-celik-t4q03', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'biliyordum böyle ansızın

atıp gideceğini bir gün

biliyordum bölye cansızın

yığılıp kalacağımı bir gün...

BirDeli

27.07.2004', 'biliyordum böyle ansızın atıp gideceğini bir gün biliyordum bölye cansızın yığılıp kalacağımı bir gün... BirDeli 27.07.2004...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/habersizce-gidis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aforizmalar II', 'aforizmalar-ii-zafer-zengin-etnika-c2x3p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '~| olabilirliği olan her şeyi sende ret edeceksin |~

İçinde

Her şey

Attığın kadar

Yakaladığın

Sonuçsuz olan

Yenilginin sesi

Nasıl gür değil mi

Olamayanları

Bekleyelim

Ya soğuksa uzayın koyuluğu

Sıcak ay

Nasıl ısınacak

Erirse

İçimizi su basacak

Kıyısız kalmadık değil mi

Deniz dağa kavuşunca

| Buz vardı kutuplarda..mum olup eriyen..içinde düşüncen |

30 Temmuz 2004', '~| olabilirliği olan her şeyi sende ret edeceksin |~ İçinde Her şey Attığın kadar Yakaladığın Sonuçsuz olan Yenilginin sesi Nasıl gür değil ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/aforizmalar-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ses(im) duvardan düştü../..kaldırın', 'ses-im-duvardan-dustu-kaldirin-pelin-onay-8s19t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '- pardon,''seni seviyorum'' diyen bir ses buradan geçti mi acaba? 

- hayır bayan, görmedik

bir adam çıplak sesle şarkı söylüyor,

sesi üşeyecek diye çok korkuyorum

bir kadın limanda günah çıkartıyor,

günahları denizi kirletecek diye tedirgin oluyorum

tut(ma)  beni gece

karanlığında şarkılara gebe kalıyorum

- pardon, ''seni özledim'' diyen bir ses uğradı mı acaba buraya? 

- hayır bayan, uğramadı

tutkularım çiçek verdi, kokusunu saldı

satamadım biriktirdiğim dağ özlemlerini

İsmet Teyze yaşasaydı söylerdi, anılarla nasıl başa çıkılacağını

herkes ölüyor, sevdaların öldüğü gibi

kandır(ma) sın beni şiirler,

yokluğumu isimlendirmeye gidiyorum

- pardon, ''kadınım'' diyen bir ses bir not bıraktı mı acaba? 

- hayır bayan, bırakmadı

cinayeti ellerim gördü

bir de yüreğim

gözlerim inanmaz yüze değmeyen bakışlara

beni rahmine al ve yeniden doğur anne

yanılgılarımın kapısını tekrar çalmayacağım

kuş tüyü vaatlerde kaybettim gerçeğimi

kandır(ıl) dığımı bırak unutayım

- pardon, ''sen benim elma şekerimsin'' diyen bir ses sizde kaldı mı acaba? 

- hayır bayan, kalmadı

yorgun turuncu açtı gözlerini, 

geceye tutundu

kıskanmasın canım mavi, onu da unutmadı

sır küpüdür şehvet bedenimde,

kapıma dayan(ma) dı

bacaklarım mecalsiz artık aşk

sana kapıları açamayacağım diye korkuyorum

- pardon, ''artık bensiz bir yaşamın olsun'' diyen bir ses ağladı mı acaba? 

- hayır bayan, duymadık

kanım çekiliyor dostlar

ayrılıkların en dokunulmaz şahidiyim', '- pardon,''seni seviyorum'' diyen bir ses buradan geçti mi acaba?  - hayır bayan, görmedik bir adam çıplak sesle şarkı söylüyor, sesi üşeyecek...', ARRAY['Türk Edebiyatı','Şiir','Pelin Onay']::text[], 8.5, '{"poet":"Pelin Onay","poet_slug":"pelin-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/ses-im-duvardan-dustu-kaldirin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece''den Gündüz''e...', 'gece-den-gunduz-e-i-brahim-ethem-bingul-u7p57', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben Gece''yim,sen Gündüz

Bizim aşkımız Gece''yle Gündüz

Olamayız ben sensiz sen bensiz 

Aşkımız başlamış varoluşta,değil sebepsiz...

Ben gelirim sen gidersin

Bir kovalamacadır bu,sürer gider

Sen gerçekleri apaçık sergilersin

Bense saklarım onları birer birer...

İhtiyacı var bu dünyanın bize

Ama bil ki kavuşmamız kıyamette

Aşıklar için vuslatın gereği ise

Bir etsinler gönüllerinde gündüzü geceyle...

www.iebingul.com', 'Ben Gece''yim,sen Gündüz Bizim aşkımız Gece''yle Gündüz Olamayız ben sensiz sen bensiz  Aşkımız başlamış varoluşta,değil sebepsiz... Ben gelir...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gece-den-gunduz-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Kaplım', 'kara-kaplim-burak-killioglu-mwur6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kara kaplım

Gönüldaşım

Dert seferlerindeki biricik yoldaşım

Yürek hazinemin bekçisisin

Sanma ki seni unuttum

Sende saklı tüm sevincim, kederim

Mümkün mü sensiz olmak

Kara kaplı defterim', 'Kara kaplım Gönüldaşım Dert seferlerindeki biricik yoldaşım Yürek hazinemin bekçisisin Sanma ki seni unuttum Sende saklı tüm sevincim, keder...', ARRAY['Türk Edebiyatı','Şiir','Burak Kıllıoğlu']::text[], 8.5, '{"poet":"Burak Kıllıoğlu","poet_slug":"burak-killioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kara-kaplim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cevapsız Sorular', 'cevapsiz-sorular-burak-killioglu-6su4x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayat nedir? deseler

İlk çığlıktan son nefese

Akıp giden bir yoldur,

Derdim.

Güzel midir? deseler

Ne O''nla, ne de O''nsuz

Gün geçmiyor ki, 

Derdim.

Hatta, sormadıkları halde dedim.

Günahlarımı ise çok pahalı ödedim.

Sevmekmiş benim cezam...', 'Hayat nedir? deseler İlk çığlıktan son nefese Akıp giden bir yoldur, Derdim. Güzel midir? deseler Ne O''nla, ne de O''nsuz Gün geçmiyor ki,  D...', ARRAY['Türk Edebiyatı','Şiir','Burak Kıllıoğlu']::text[], 8.5, '{"poet":"Burak Kıllıoğlu","poet_slug":"burak-killioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/cevapsiz-sorular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masalcı', 'masalci-cigdem-bir-genc-92z0i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aynı masalın  kısırdöngüsündeyiz 

Farklı düşsel zamanlarda 

Geç kalınmışlıklar diz boyu

Sular yükseliyor...

Çözüm değil sevmeler

Sen de....

Ben de....

Masal da...

Uydurma...

Bir başka masala göç edebilir miyim masalcı?', 'Aynı masalın  kısırdöngüsündeyiz  Farklı düşsel zamanlarda  Geç kalınmışlıklar diz boyu Sular yükseliyor... Çözüm değil sevmeler Sen de.... ...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Bir Genç']::text[], 8.5, '{"poet":"Çiğdem Bir Genç","poet_slug":"cigdem-bir-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/masalci-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Dilenci Vapuru...', 'dilenci-vapuru-erdal-asik-wk8pm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Siz hiç dilenci vapuruna bindiniz mi? 

Sabah herkesten önce uyanır 

Birde neşeli bekleyişi var görmeyin 

Düdüğünü çaldı mı başlar 

Bir koşuşturma bir telaş 

Uykulu gözler mağrur yüzler 

Kimisi akşamdan kalma yorgun 

İşçi karıncalar hakim olur çevresinde. 

6:30''da Beykoz'' dan hareket eder 

Boğazın ilk ışıklarında süzülür 

Paşabahçe'' ye 

Akraba olmuş günaydınlı yüzler 

Bölük bölük toplaşırlar her köşesinde 

Bir muhabbet bir keyif deymeyin 

Hazlarına diyecek yok 

Niceleri aşık olmuş bu yolda 

Niceleri yuva kurmuş sonunda 

Ayrılıkları da olmuş, acıları da 

Berrak sakin nehrinde akar 

Çubuklu'' dan Kanlıca'' ya geçer 

Boğazın Yeni gerdanının altından 

Kuğu gibi süzülür Anadoluhisarı'' na 

Endamıyla var mı benden zengini? 

Der gibi nispet yapar yalılara 

Eli boş çevrildiği görülmez 

Dilenir her yerden biner sevgiler 

Kandilli, Bebek, Arnavutköy'' e 

Yolcuları İndirmeye başlar Ortaköy'' de 

En çok Beşiktaş'' ta bekler 

Karıncaların yarısı burada iner 

Dolmabahçe önünden geçer

Başlangıcın sonu Eminönü'' ne 

Akşam buluşmak üzere 

Vedalaşır her biriyle lakin üzülmez 

Gelecekler nasıl olsa geriye! ..', 'Siz hiç dilenci vapuruna bindiniz mi?  Sabah herkesten önce uyanır  Birde neşeli bekleyişi var görmeyin  Düdüğünü çaldı mı başlar  Bir koşuş...', ARRAY['Türk Edebiyatı','Şiir','Erdal Aşık']::text[], 8.5, '{"poet":"Erdal Aşık","poet_slug":"erdal-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/dilenci-vapuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulutlu Gece', 'bulutlu-gece-gullu-alemdar-qqt86', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her gece içerlenir gönlüm,

Artık saklayamaz

Haykırırcasına ağlar durur

Unutmak o kadar kolay mı sandın

Gittiğini bilmek, seni sonsuza dek 

Kaybettiğimi düşünmek; 

İçimdeki duyguyu daha da büyütüyor

Nedir bu çektiğim, hiç anlamı yok

Sebepsiz ağlıyorum sessizce

Şu derbeder gönlümü

Avutmak kolay mı sandın! 

Ağlamak, yalnızlığım ve çektiklerim

Aşktır artık bana

Belli  belirsiz sızı içimdeki

Yer yer sağnak,yer yer bulutlu

Efkarlı bu gönül; 

Hep bekler o bulutlu gecedeki

Belli olmayan yıldızın parlamasını

Bilmez kimseler nasıl sevdik birbirimizi

Yavaş yavaş ciseler 

Sessizce döker içini yağmur bulutu

Sonra haykırmak gelir 

Neyi neyi mi? 

Seni ölümden öte sevdiğimi...

                                (Gülnida)', 'Her gece içerlenir gönlüm, Artık saklayamaz Haykırırcasına ağlar durur Unutmak o kadar kolay mı sandın Gittiğini bilmek, seni sonsuza dek  K...', ARRAY['Türk Edebiyatı','Şiir','Güllü Alemdar']::text[], 8.5, '{"poet":"Güllü Alemdar","poet_slug":"gullu-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bulutlu-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arayış', 'arayis-gullu-alemdar-bjt5t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İşte geldi ayrılık vakti

Nasılda kendi ellerinle 

Azat ettin! 

Ah bir bilsen sensiz 

Daha kötü olacağını

Say ki savunmasız bir kuşum

Sevilmemişim ki bırakıp da gittin

Kurtlar sofrasına beni

Kendi ellerinle verdin verdin

Dön desen döner miyim bilmem,

Kader, nasıl geldiysen aniden

Çıkarır mı karşıma dersin istesem

Bana sormadan girdin hayatıma

Benim rızam olmadan nasıl çıkarsın! 

İçimdeki feryatlar bir türlü susmadı

Yıllardır aradım durdum; 

Neden bu arayışın sonu sen olmayasın

Sen istesen bende her şey biter 

Bu sonsuz arayış diner... 

                                        (Gülnida)', 'İşte geldi ayrılık vakti Nasılda kendi ellerinle  Azat ettin!  Ah bir bilsen sensiz  Daha kötü olacağını Say ki savunmasız bir kuşum Sevilme...', ARRAY['Türk Edebiyatı','Şiir','Güllü Alemdar']::text[], 8.5, '{"poet":"Güllü Alemdar","poet_slug":"gullu-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/arayis-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasak Meyva', 'yasak-meyva-hamdi-keskin-6cwhy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen  aşk  nedir  bilirmisin  güzelim

Dünya niçin güneş etrafında raks ediyor

Gel   birlikte  yıldızları  gezelim

Aşkın  gücü   her şeye  yetiyor

Bulutlar  ağlamazdı  aşk   olmasa

Ay gülümsemezdi taa uzaklardan

Toprak çiçek açmazdı suyu bulmasa

İnsan kahrolmazdı ayrı düşmese yardan

Şarkılar söyler sevgililerine kuşlar

Yıldızlar  göz  kırpar  sevdiklerine 

Aşk evrenin varoluşuyla birlikte başlar

Tanrı aşkı nasip eder övdüklerine

Bülbül  güle aşıktır  onun için şakır

Kraliçeye aşkı sunar  erkek  arılar

Gül haya edip utanmış, kızarmıştır

Papatyalar kara sevdalarından sarardılar

Dağların gözyaşıdır hırçın akan ırmak

Dereler okyanuslara kavuşmak emelindedir

Sevince   işten   değil   çıldırmak

Sonsuzluk   iksiri  yarin  elindedir

Sen   aşkı   bilirmisin   gülüm

Bir kalbin  bir kalple uyuşmasıdır

Karşı konulmaz cazibe ne ki ölüm

Bir dağın, bir dağa kavuşmasıdır

Aşk yasak meyvadır cennette varolan 

Havva bu yemişi sevdiğine sundu

Ademi   cennetten    kovduran 

Meyva değil  aşk denilen efsundu

Cennet  ne ki sevdiğin  yanında  yoksa

Havva dayanamadı, koştu ademe kaçtı

Biz olurmuyduk; adem olmasa, aşk olmasa

Yeryüzü  cennet  oldu, aşka kucak açtı', 'Sen  aşk  nedir  bilirmisin  güzelim Dünya niçin güneş etrafında raks ediyor Gel   birlikte  yıldızları  gezelim Aşkın  gücü   her şeye  yet...', ARRAY['Türk Edebiyatı','Şiir','Hamdi Keskin']::text[], 8.5, '{"poet":"Hamdi Keskin","poet_slug":"hamdi-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yasak-meyva-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'G e l', 'g-e-l-gullu-alemdar-thyt8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün gidiyorum doğduğum yere....

Aşkın doğum günüm

Seni bulduğum yer

Doğduğum yer

Sensizlik yer yer esen 

Deli bir rüzgar benliğimde

Söylesene öylesine sen kokan

Sen dolu o hırçın kente

Sensiz nasıl ayak basılır

Bu şehirde yabancı sensiz

Bir başıma, yapa yalnızım aslında 

Canımdan can olmuşsun

Öldürmeye çalışsam

Yaşayan bir beden kalır bende

Hiç kurtuluşu yok belki

Çaresi yok bunun

Gel de bitsin! 

Yeniden başlasın gölümde

Yeşeren baharlar

Gel de bitsin! 

Sabahsız geceler

Gel de bitsin! 

Nedensiz dökülen göz yaşlarım...

                                     (Gülnida)', 'Bugün gidiyorum doğduğum yere.... Aşkın doğum günüm Seni bulduğum yer Doğduğum yer Sensizlik yer yer esen  Deli bir rüzgar benliğimde Söyles...', ARRAY['Türk Edebiyatı','Şiir','Güllü Alemdar']::text[], 8.5, '{"poet":"Güllü Alemdar","poet_slug":"gullu-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/g-e-l-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'E y S e v d i ğ i m!', 'e-y-s-e-v-d-i-g-i-m-gullu-alemdar-j55nu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kokun sinmiş yatığıma,tenime,

Ölürcesine sevdiğim

Yüzüne bakmaya kıyamadığım,

Benliğim! 

Ben özlüm,

Sensizlik ölüm fermanım oldu

Kaybını bile düşünemezken

Ellerimden  su gibi,

Akıp gidişine

Sadece seyirci kalabildim

Kapılar kapandı yüzüme

Ağlayamaz oldu 

O çok sevdiğin gözlerim

Taş oldu yüreğimde sızın

Kayboldu gidişinle benliğim...

                            (Gülnida)', 'Kokun sinmiş yatığıma,tenime, Ölürcesine sevdiğim Yüzüne bakmaya kıyamadığım, Benliğim!  Ben özlüm, Sensizlik ölüm fermanım oldu Kaybını bil...', ARRAY['Türk Edebiyatı','Şiir','Güllü Alemdar']::text[], 8.5, '{"poet":"Güllü Alemdar","poet_slug":"gullu-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/e-y-s-e-v-d-i-g-i-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'S u s k u n l u k', 's-u-s-k-u-n-l-u-k-gullu-alemdar-8duoa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mıknatısın iki zıt kutbu gibi

Nasılda itiyoruz birbirimizi

Oysa ki bizi biden daha iyi

Kimse anlayamaz ki

Gerçekleri bir kabullensek

Çeker miyiz birbirimizi ömür boyu

Neredesin! 

Sorularım hep cevapsız,

Yarım kaldım

Nerdesin diğer yarım

Biraz olsun kendi mutluluğumuz için

Çaba verseydik eğer

Şimdi ne ben sensiz olurdum

Ne de sen! 

Yine susuyorsun...

 Gerçek sevgiye

 Hiç rastlamadım,

Galiba bu yüzdendir

Bu bitmez tükenmez suskunluklar...', 'Mıknatısın iki zıt kutbu gibi Nasılda itiyoruz birbirimizi Oysa ki bizi biden daha iyi Kimse anlayamaz ki Gerçekleri bir kabullensek Çeker m...', ARRAY['Türk Edebiyatı','Şiir','Güllü Alemdar']::text[], 8.5, '{"poet":"Güllü Alemdar","poet_slug":"gullu-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/s-u-s-k-u-n-l-u-k-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Y a n ı y o r u m', 'y-a-n-i-y-o-r-u-m-gullu-alemdar-od3ao', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gün gelir unutursun! 

Diyorlar,

İçimi rahatlatmaya,

Yüzümü güldürmeye

Çalışıyorlar; 

Oysa ki! 

Aşk, ateş gibi kor

Oluyor zaman zaman

İçimde yanan ateşin 

Alevleri sarmış etrafımı

Kaçsam, kaçılmıyor

Söndürmeye çalıştıkça

Çoğalıyor,yanıyorum

İçin için yanıyorum

Sensizlik alevlerinde

Ne git diyebiliyor

Nede dön diyebiliyorsun

Nasıl bir çelişkidir bu

Yoksa aşk zerreleri mi? 

Serpiliyor etrafıma...

 Nasılda canını acıtıyor

Görünmeyen bir şekilde

Başlangıçta deli bir heyecan

 Kısa bir mutluluk sarar sıcacık

Sonrada iznin almadan 

Çekip gider uzaklara

Derin izler bırakarak

Başka gönüllerinde canını acıtmaya

Belki de hayatın ta kendisidir aşk

Deniz kadar gerçek

Dalgalanır, durulur zaman zaman

As olan! 

Sevdiğine kavuşmaktır

Son nefes tükenmeden...

                         (Gülnida)', 'Gün gelir unutursun!  Diyorlar, İçimi rahatlatmaya, Yüzümü güldürmeye Çalışıyorlar;  Oysa ki!  Aşk, ateş gibi kor Oluyor zaman zaman İçimde ...', ARRAY['Türk Edebiyatı','Şiir','Güllü Alemdar']::text[], 8.5, '{"poet":"Güllü Alemdar","poet_slug":"gullu-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/y-a-n-i-y-o-r-u-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlızlığım', 'yanlizligim-gullu-alemdar-v9njg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün gelsen aniden,

Bana hiç sormadan

Tutup kolumdan, alıp götürsen

Nereye mi? 

Şimdi sensizim

Senle her yere

Ah bir bilsen,bu benliğin altında

Aşkı sevgisi uğruna 

Mertçe ölümü bile

Göze alabilen bir yürek olduğunu

O zaman hala sever miydin? 

Konuşur muydun eskisi gibi

Yoksa seninde biter miydi sevgin

Korkuyorum allah’ım! kurtar beni

Sevmek,aşk sonum olur

Anladım ki sonu yok yalnızlığımın

Ne kadar kısa,bir o kadarda acı

Alışır mıyım dersin bu duruma 

Ben alışsam da o bırakır mı

Bir gün yakamı

Yalnızlığım,yalnızlığım...

Nereye gitsem gölgem gibi

Beni izleyen yalnızlığım

    	

                               (Gülnida)', 'Bir gün gelsen aniden, Bana hiç sormadan Tutup kolumdan, alıp götürsen Nereye mi?  Şimdi sensizim Senle her yere Ah bir bilsen,bu benliğin a...', ARRAY['Türk Edebiyatı','Şiir','Güllü Alemdar']::text[], 8.5, '{"poet":"Güllü Alemdar","poet_slug":"gullu-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yanlizligim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor Aşk', 'zor-ask-gullu-alemdar-8pry4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ellerimi tuttun yalanlar söyledin

Aklınca sırrımı öğrenip,	

Beni keşfettin; 

Geç dalganı övün 

Yalan her şey,yalan bu sözler

Derdime çare olmanı bekledim

İlk adımı hep benden bekledin

Ben yadırgamam,

Hep sana gelirdim

Bunları dahi yanlış anladın

Kim bilir kaç kişiyi

Böyle kaçarak elde ettin

Artık nafile hiçbir şeyin 

Telafisi yok! 

Erkekçe gelip de; 

Seni seviyorum desende

Çok geç be türkü gözlüm

Ne ben seni tanıyabildim 

Nede sen beni tanımışsın

Kayıp aşk bizimkisi,başlamadan biten

Dudağımda umut şarkılarıyla

Nereye taşırım bu yaralı yüreği

Bilinmez...

Geçmişe dönüp baktığımda kayıp

Geceleri ateşler içinde,

Uykularım bölük bölük

Seni düşünmenin bile 

Bana haram olduğunu 

Bile bile seni daha bir seviyor,

Seni yaşıyorum sessizce

Yaram geçmiyor

Senemi terk etmiyor bu sevda

Bil ki sadece seni istiyorum

Seni bekliyorum...

                           (Gülnida)', 'Ellerimi tuttun yalanlar söyledin Aklınca sırrımı öğrenip,	 Beni keşfettin;  Geç dalganı övün  Yalan her şey,yalan bu sözler Derdime çare ol...', ARRAY['Türk Edebiyatı','Şiir','Güllü Alemdar']::text[], 8.5, '{"poet":"Güllü Alemdar","poet_slug":"gullu-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/zor-ask-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'K a r', 'k-a-r-gullu-alemdar-6lfp8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nasılda lapa lapa yağıyor kar

San ki seni kalbimden silecek gibi! 

Unutturur mu? 	

Kaplayabilir mi içimde ki 

Ateşin üzerini...

Bir anda buz tutan kalbimi,

Eritip bitiriyor sızın

En acısı da ne biliyor musun? 

Birbirini delicesine severken

Sebep her ne olursa olsun

İki yabancı olmak 

Ne demek bilir misin? ...

Bile bile vazgeçmek sevdiğinden,

Dön demeye hakkın olmadan

Ömrünün sonuna kadar

Gel diyemeden; 

Pencerenin önünde 

Belki gelir diye beklemenin

Izdırabı ne demek  bilir misin? 

(Gülnida)', 'Nasılda lapa lapa yağıyor kar San ki seni kalbimden silecek gibi!  Unutturur mu? 	 Kaplayabilir mi içimde ki  Ateşin üzerini... Bir anda buz...', ARRAY['Türk Edebiyatı','Şiir','Güllü Alemdar']::text[], 8.5, '{"poet":"Güllü Alemdar","poet_slug":"gullu-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/k-a-r-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıkık ve Harap', 'yikik-ve-harap-gullu-alemdar-olbxg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çöle dönen gönlümde

İçekler açtı

Kuruyan damarlarıma 

Su serpti senin sevdan

Hayatım yeniden yeşerdi

Senin gidişin benim sonum 

Yokluğun ise derin sızılar,

Yaralar açar yüreğimde

Seni seviyorum dedikçe

Hayat buldu bende tüm umutlar

Bir daha beni sakın

Yokluğunla sınama gece gözlüm

Bu yorgun yürek daha ne kadar

Dayanır hiç bilinmez! 

Hasretinden taş oldu gönlüm

Gel desem gelir misin? 

Ya da beni çağırır mısın

Sensiz bu gece,bu şehir

Ne kadarda bulutlu ve sisli

Geliyor gözlerime (gece gözlüm)

Sensiz halim duman anlayacağın

Yıkık ve harap bir haldeyim 

Daha ne kadar yaşarım sence; 

Seninle nefes alan bu bedende...

                                         (Gülnida)', 'Çöle dönen gönlümde İçekler açtı Kuruyan damarlarıma  Su serpti senin sevdan Hayatım yeniden yeşerdi Senin gidişin benim sonum  Yokluğun ise...', ARRAY['Türk Edebiyatı','Şiir','Güllü Alemdar']::text[], 8.5, '{"poet":"Güllü Alemdar","poet_slug":"gullu-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yikik-ve-harap-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saadet Dileğiyle...', 'saadet-dilegiyle-i-lyas-ozkan-jag8p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '*Bekarlar kervanına vedâ eden 

can dostum Muhammed Karakış’a...

A dostum seni de kaybettik bu kervandan; 

Şimdi ayrılık vaktidir dosttan, yârândan.

Alışmıştı gönül, dostların ülfetine; 

Böyle katlanırdık dünyanın külfetine.

Hatıralarda kaldı acı-tatlı günler,

Bazen karışırdı gözyaşına hüzünler.

Dert ortağıydık; gönül birden incinirdi,

Sevinç birdi; cümle beraber sevinirdi.

Vedâ türküsü tutturup gider dilimiz,

Can dosta, bu hayatta saadet dileriz.

Huzur göresin; bereket dolsun ev-barkın,

Sonsuza değin sürsün bu mutluluk şarkın...

(31.07.2004

Cumartesi)', '*Bekarlar kervanına vedâ eden  can dostum Muhammed Karakış’a... A dostum seni de kaybettik bu kervandan;  Şimdi ayrılık vaktidir dosttan, yâ...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özkan']::text[], 8.5, '{"poet":"İlyas Özkan","poet_slug":"i-lyas-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/saadet-dilegiyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalga Dalga', 'dalga-dalga-gullu-alemdar-9uwig', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geldiğimde kimseler yoktu 

Bomboştu bütün kordon 	

Deniz sessizdi, hiç olmadığı kadar

İçten içe dalga geçiyor gibiydi

Oysa dalgalarının gücü yetmez

Düşlerimi kıyıya vurmaya

Üstüme sıçrıyor hırçın dalgalar

Korkmuyorum 

Ölümün diğer yüzü gibi

Karanlık ve soğuk 

Hayat görünmeyenlerin ardında

Gel de bitsin! 

Bu koşuşturma 

Dalgalar durulsun hayatımda

Güçleri yetmez seni unutturmaya

                                       (Gülnida)', 'Geldiğimde kimseler yoktu  Bomboştu bütün kordon 	 Deniz sessizdi, hiç olmadığı kadar İçten içe dalga geçiyor gibiydi Oysa dalgalarının gücü...', ARRAY['Türk Edebiyatı','Şiir','Güllü Alemdar']::text[], 8.5, '{"poet":"Güllü Alemdar","poet_slug":"gullu-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dalga-dalga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Hıçkırık', 'sessiz-hickirik-i-lyas-ozkan-3lqlt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hasretin düştü yüreğime, anne

Oturup ağladım bir kenarda.

Hâlimi, kim nerden bile? 

Yandıkça yandım kimsesiz diyarda...

Özledim köyümü, memleketimi; 

Vatan toprağının buğusunu-kokusunu, anne! 

Yüreğime akıttım gözyaşımı, hasretimi; 

Yandıkça yandım kimsesiz diyarda...

(31.07.2004

Cumartesi)', 'Hasretin düştü yüreğime, anne Oturup ağladım bir kenarda. Hâlimi, kim nerden bile?  Yandıkça yandım kimsesiz diyarda... Özledim köyümü, meml...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özkan']::text[], 8.5, '{"poet":"İlyas Özkan","poet_slug":"i-lyas-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sessiz-hickirik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle Onlara', 'soyle-onlara-i-lyas-ozkan-xcuhn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '9/81: “De ki: Cehennem ateşi daha sıcak.

           Keşke anlasalar...”

Bir şirzime-i kalîl ki; 

Başladı güft ü gû’ya:

- Nasıl gideriz? 

Yol uzak,

Hava sıcak,

Düşman kavî! 

Aklınız mı yitirdiniz? 

Yollar geçit vermez! 

Söyle ki onlara; 

Misk ü amber diye,

Sürdükleri göze; 

Kokuşmuş balçığıdır

Şu vefasız yerin! 

Söyle ki; 

Yakınmaktalar

Yolun uzaklığından; 

Bir devin yuvarlanmasıdır,

Bir fındık akabesinde.

Çekinmekteler,

Bulanmaktan toza toprağa.

Söyle ki; 

Debelenip durmaktalar,

-Hem de bir ömür boyu-

Hülyalarının bataklığında.

Güneş kavuruyormuş,

Üstten tüm yakıcılığıyla.

Belli ki farkında değiller; 

Kemikleri bile erimekte,

Hırslarının yangınında.

Söyle ki onlara; 

Feryat edip kıvılcımdan,

Salmasınlar tatlı canlarını

Amansız azaplara...! 

(19.05.2004 

Çarşamba)', '9/81: “De ki: Cehennem ateşi daha sıcak.            Keşke anlasalar...” Bir şirzime-i kalîl ki;  Başladı güft ü gû’ya: - Nasıl gideriz?  Yol...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özkan']::text[], 8.5, '{"poet":"İlyas Özkan","poet_slug":"i-lyas-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/soyle-onlara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'K o r k u!', 'k-o-r-k-u-gullu-alemdar-x62t1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Korkuyorum; 

Hayallerimi yıkmalarından 

Biliyorum! 

Bütün zorluklar aşılmak içindir.

Sevmekte sevilmekte 

Yaşamak için; 

Bunlar hayatın vazgeçilmezidir.

İşte sevilmediğimi düşündüğüm an

Yok mu? 

Kopuyor her şey,anlamını yitiriyor

Ve kendimi güçsüz,

Savunmasız hissediyorum.

Bir şeylere sığınmak geliyor içimden 

Arıyorum,arıyorum bulamıyorum

 Dediğim anda! 

Yine sen çıkıyorsun karşıma…(suyum)

                         (Gülnida)', 'Korkuyorum;  Hayallerimi yıkmalarından  Biliyorum!  Bütün zorluklar aşılmak içindir. Sevmekte sevilmekte  Yaşamak için;  Bunlar hayatın vazg...', ARRAY['Türk Edebiyatı','Şiir','Güllü Alemdar']::text[], 8.5, '{"poet":"Güllü Alemdar","poet_slug":"gullu-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/k-o-r-k-u-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Çekişim', 'can-cekisim-gullu-alemdar-fpsbw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni ufak ufak terk edişlerim

Can çekişlerim olur

Sen yoksan her şey yarım 

Senle iken korkunç bir

Huzur kaplar bedenimi

Balık nefes alabilirse

Çiçek solmazsa susuz

İşte o zaman doğrudur her şey

Yalandır bu dünya yalandır aşklar

Su gibi saf ve temiz olmalı sevgiler

İçtikçe kanamamak,içine dalınca

Bir daha çıkamamak misali

Yaşanmalı sevgiler

Aşkın bende bir çağlayan

Her ayrılıkta daha da büyüyor

Uzanıp gidiyor dağlar ardına 

Sonra kavuşuyor! 

Engin denizlere,

Ucu bucağı görünmüyor

Sonu hiç olmuyor...

                 (Gülnida)', 'Seni ufak ufak terk edişlerim Can çekişlerim olur Sen yoksan her şey yarım  Senle iken korkunç bir Huzur kaplar bedenimi Balık nefes alabili...', ARRAY['Türk Edebiyatı','Şiir','Güllü Alemdar']::text[], 8.5, '{"poet":"Güllü Alemdar","poet_slug":"gullu-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/can-cekisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklımı Seninle Bozmuşum *3*', 'aklimi-seninle-bozmusum-3-tulay-sustam-hlnnm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerimin,

Beynimin, 

Ellerimin,

Yüreğimin adı-sen

Aklımı seninle bozmuşum

Ateşin,

Közün,

Sigaranın,

Dumanın adı-sen

Aklımı seninle bozmuşum

Gecenin,

Gündüzün adı-sen

Mektubun,

Zarfın adı-sen

Aklımı seninle bozmuşum

Peynirin,

Ekmeğin,

Çayın,

Şekerin,

Tuzun adı-sen

Aklımı seninle bozmuşum

Müziğin,

Notanın,

Sazın,

Sözün adı-sen

Aklımı seninle bozmuşum

Mecnun''un,

Kerem''in,

Ferhat''ın adı-sen

Aklımı seninle bozmuşum

Yatağın,

Yorganın,

Yastığın adı-sen

Aklımı seninle bozmuşum

Her annenin,

Her babanın,

Her kardeşin,

Her dosttun,

Her kundakta ki bebeğin adı-sen

Aklımı seninle bozmuşum

Hayatımda ki her şeyin adı-sen

Ben artık baştan sona sen olmuşum

Aklımı seninle bozmuşum...', 'Gözlerimin, Beynimin,  Ellerimin, Yüreğimin adı-sen Aklımı seninle bozmuşum Ateşin, Közün, Sigaranın, Dumanın adı-sen Aklımı seninle bozmuşu...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/aklimi-seninle-bozmusum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümcek Ağı', 'olumcek-agi-rahim-tas-vox43', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölümcek Ağı 

Takıldık 

Anayurdu dört baştan saran 

Demir ağlara 

Hırslandırılmış tren

Can gidiyor

Takıldık 

Katran ağlara 

Araçlar yollarda mayın 

Aşırı hırs hatalı kaplama

Kan gidiyor

Takıldık 

Örümcek ağlarına 

Enstitülerin kilitli kapılarında 

Öğretmensiz okullarda 

Hırslandırılmış eğitim

İnsan gidiyor

Deldi ağlarımızı 

Demokrasi okyanusunda 

Cehalet giymiş anarşist balıklar 

Hırslandırılmış siyaset

Can gidiyor 

Kan gidiyor 

İnsan gidiyor



31.7.2004

Rahim TAŞ', 'Ölümcek Ağı  Takıldık  Anayurdu dört baştan saran  Demir ağlara  Hırslandırılmış tren Can gidiyor Takıldık  Katran ağlara  Araçlar yollarda ...', ARRAY['Türk Edebiyatı','Şiir','Rahim TAŞ']::text[], 8.5, '{"poet":"Rahim TAŞ","poet_slug":"rahim-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/olumcek-agi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim tabut bekliyor cami avlusunda', 'benim-tabut-bekliyor-cami-avlusunda-can-i-rfan-mrxld', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Benim tabut bekliyor cami avlusunda

Duahan tekmeliyor boş 

Sende kurudun elinden

Beni de kuruttun hasebinden diye.

Hal böyle işte 

Akıttım kurbanlık ruhumun kanını.', 'Benim tabut bekliyor cami avlusunda Duahan tekmeliyor boş  Sende kurudun elinden Beni de kuruttun hasebinden diye. Hal böyle işte  Akıttım k...', ARRAY['Türk Edebiyatı','Şiir','Can İrfan']::text[], 8.5, '{"poet":"Can İrfan","poet_slug":"can-i-rfan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/benim-tabut-bekliyor-cami-avlusunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir tanem', 'bir-tanem-ali-hamdi-eray-ogm4l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni üzen varlığa 

Ömrüm boyunca dargınım.

Sen sevdiğin için,seviyorum; 

İnsanları,hayvanları,herşeyi; 

Sen sevdiğin için.

Sen baktığın için seviyorum doğayı,

Elbiselerini,çoraplarını,ayakkablarını,

Sen giydiğin için seviyorum.

Sen sevdiriyorsun onları sen.

Ama ben; 

Yalnız seni seviyorum,

Yalnız seni,

Bir tanem.

1962', 'Seni üzen varlığa  Ömrüm boyunca dargınım. Sen sevdiğin için,seviyorum;  İnsanları,hayvanları,herşeyi;  Sen sevdiğin için. Sen baktığın için...', ARRAY['Türk Edebiyatı','Şiir','Ali Hamdi Eray']::text[], 8.5, '{"poet":"Ali Hamdi Eray","poet_slug":"ali-hamdi-eray","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-tanem-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayış', 'anlayis-talip-sinecikli-ol88h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güneş eskisi gibi doğacaksa penceremden.

Kuşlar yine cıvıl cıvıl ötecekse,

Özgürlüğe çırpacaksa kanatlarını.

Çiçekler rengarenk açmaya devam edecekse.

Hayat sürecekse acılara rağmen.

Gülmeyi öğrenecekse yeniden gözlerim.

Tüm duygularım yeniden tertemiz olacaksa. 

Senin beni sevmemende, 

Hiçbir sakınca yok.

Anlıyor musun?', 'Güneş eskisi gibi doğacaksa penceremden. Kuşlar yine cıvıl cıvıl ötecekse, Özgürlüğe çırpacaksa kanatlarını. Çiçekler rengarenk açmaya devam...', ARRAY['Türk Edebiyatı','Şiir','Talip Sinecikli']::text[], 8.5, '{"poet":"Talip Sinecikli","poet_slug":"talip-sinecikli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/anlayis-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çilli Bebek', 'cilli-bebek-ali-hamdi-eray-0p0sz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Canımın içi,

Hayatım çilli bebek.

İnan bana,

Seni gözlerimin ilk öpmesinde; 

Sevği taştı gönlümden,öbek,öbek.

Seviyorum seni seviyorum çilli bebek,

Gerçek sevenler gibi,

Sevdalı sevğiler gibi,

Kimsenin sevmediği,

Sevemeyeceği kadar.

Seviyorum,

Seviyorum,çilli bebek.

Sen benim öğretmenim,

Sen benim canım,

Özüm,sözüm,herşeyim,

Çilli bebeğim.

Mısralar diziyorum adına,

Çocukça saf saf

Güzelliğini anlatması için cihana,

Yapamıyorum bebek

Anlatamıyorum,sevğimi,özlemimi.

Çilli bebek,

Anlatmak için ömrümü versemde inan,

Sana sevgimi ben anlatamam.

1962', 'Canımın içi, Hayatım çilli bebek. İnan bana, Seni gözlerimin ilk öpmesinde;  Sevği taştı gönlümden,öbek,öbek. Seviyorum seni seviyorum çilli...', ARRAY['Türk Edebiyatı','Şiir','Ali Hamdi Eray']::text[], 8.5, '{"poet":"Ali Hamdi Eray","poet_slug":"ali-hamdi-eray","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/cilli-bebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklemek', 'beklemek-talip-sinecikli-i26vf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Siz ne biçim adamsınız

Siz,

Siz ikiniz,

Sarışın ve esmer olan 

Hani kardeştik ne değişti? 

Oldu mu bu yaptığınız? 

Üç saattir bekliyorum,gelmediniz,

Olmadı arkadaşlar yanlış yaptınız.

Siz,

Siz ikiniz.....', 'Siz ne biçim adamsınız Siz, Siz ikiniz, Sarışın ve esmer olan  Hani kardeştik ne değişti?  Oldu mu bu yaptığınız?  Üç saattir bekliyorum,gel...', ARRAY['Türk Edebiyatı','Şiir','Talip Sinecikli']::text[], 8.5, '{"poet":"Talip Sinecikli","poet_slug":"talip-sinecikli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/beklemek-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çilingir Sofrası', 'cilingir-sofrasi-talip-sinecikli-6uq7e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Saat ilerlemeye başladımı,

Cebimizde parada varsa,

Kurarız çilingir sofrasını,

Var mı bizden kralı? 

İçer içer şarkı söyleriz,

Şarkı söyler içereriz.

Dertliyiz hepimiz biliriz,

Yinede acılara kahkahalarla güleriz.

Yok öyle içerken ağlamak,

Oyun bozanlık yapmak yok.

Neşelenmek bizim için kuraldır,

Ne geçim derdi,

Ne esaret,

Ne de aşk yarası.

Hiç birşey üzemez bizi o zaman,

Güleriz.

Ama dedim ya hepimiz dertliyiz,

Ve bunu çok iyi biliriz.', 'Saat ilerlemeye başladımı, Cebimizde parada varsa, Kurarız çilingir sofrasını, Var mı bizden kralı?  İçer içer şarkı söyleriz, Şarkı söyler ...', ARRAY['Türk Edebiyatı','Şiir','Talip Sinecikli']::text[], 8.5, '{"poet":"Talip Sinecikli","poet_slug":"talip-sinecikli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cilingir-sofrasi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülsude', 'gulsude-batuhan-batu-qj7iv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gülsude

Sevmek nedir  bilir misin Gülsude? 

Buram buram hasret kokan akşamlarda

Gece yarılarına kadar şiirler yazıp

Hayaller kurup uzak diyarlara 

Gitmeyi bilir misin ? 

Ağlamak nedir bilir misin Gülsude? 

Göz yaşlarınla avuçlarını doldurursun

Aşka susadığın zamanlarda

Her gün içini yakan mutluluğu 

Perçinlemeyi bilir misin? 

Ölmek nedir bilir misin Gülsude? 

Her gece yatmadan ellerini açıp

Sabah musalla taşında uyanmayı

Sensizliği ölümden zor sayanın

Canını almayı bilir misin? 

Mutluluk nedir bilir misin Gülsude? 

Aşk kitaplarında yer almayan

Yaşamam sensiz imkansız olan

Sen yazmadan okunmayacak olan 

Bu duyguyu bilir misin? 

Söyle sen aşkı bilir misin Gülsude? 

Çöllere düşürüp, dağları deldiren

Uğruna sevenleri zindanlarda çürüten

Ve bu zamana kadar unutulmayan aşkları

Leyla’yı Mecnun u bilir misin? 

Sen beni bilir misin Gülsude? 

Çöl  vardı da biz mi  düşmedik,

Dağ mı kaldı  delinmedik

Geceleri zindan yapıp da mı yatmadık

Sen Batu yu  bilir misin?', 'Gülsude Sevmek nedir  bilir misin Gülsude?  Buram buram hasret kokan akşamlarda Gece yarılarına kadar şiirler yazıp Hayaller kurup uzak diya...', ARRAY['Türk Edebiyatı','Şiir','Batuhan Batu']::text[], 8.5, '{"poet":"Batuhan Batu","poet_slug":"batuhan-batu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gulsude-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aryemüs', 'aryemus-batuhan-batu-cfz6d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beni ne bir zehir, ne bir ateş 

Nede dinmek bilmeyen cehennem korları

Beni güzelliğin yaktı gerisi yalan

Bitmek bilmeyen sevdan düştüğünde içime

Bak pencereden dut ağaçlarına

Temmuz geldi de takvimlere

Dutlar da mevsimini beklerde

Aşk hiç zamansız olur mu Aryemüs

Seni ayın ilk dördün de gördüm 

İlk ve son kez dünya gözüyle

Dinmek bilmeyen yaz yağmurlarında

Yazıldı  adın kalbime damla damla 

Şimdi uzaklardasın uzaklardan ötede

Yollarım kavuşmaz senin yoluna

Gittin gönül verdin zenginin dölüne

Aşk parayla alınır mıydı Aryemüs

Duygular anlamsız değilmiş oysa ki 

Anladım adını dut ağacına  kazırken

Harfler bile uzaktı birbirine

İstesen yakın olabilirdik Aryemüs

Ve ben yine Elazığ da sensizim 

Dutlar dört dem oldu silkileli

Bak  ay bu kez son dördünde

Aylarda zamanla değişiyor da

Bir ben değişmedim Aryemüs', 'Beni ne bir zehir, ne bir ateş  Nede dinmek bilmeyen cehennem korları Beni güzelliğin yaktı gerisi yalan Bitmek bilmeyen sevdan düştüğünde i...', ARRAY['Türk Edebiyatı','Şiir','Batuhan Batu']::text[], 8.5, '{"poet":"Batuhan Batu","poet_slug":"batuhan-batu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/aryemus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Of Of...', 'of-of-talip-kaplan-411ll', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Of ulan of...

Hep böyle kahpe midir dünya

Ben dertlerden kaçarım köşe bucak

Onlar gelir gelir sarılır boynuma

Of ulan of, of of da of...

Çare bulunmaz oldu çaresize

Çaresizliğin üzerine gittim hep

Bir bakıma mecbur kaldım buna

Çaresizlikler doldurdu, çarenin boşluğunu

Of ulan of, of of da of...

Neden susuyor herhes

Ve, nedir bunca haykırışlar

Bu yakarışlar, imdat çığlıkları

Çevreme bakar bakar dalarım

Of ulan of, of of da of...

Ne anlamdadır bunca oflar

Bir kaçış, sözde bir çıkış

Bazen de bir sigara yakış

Hepsi çaresizliğin feryatları

Bıkkınlığın ifadesi değil mi

Zırt bırt oflar, şu nakaratlar

Of ulan of, of of da of...

Of ulan of, of of da of...

(27 Aralık 1993)', 'Of ulan of... Hep böyle kahpe midir dünya Ben dertlerden kaçarım köşe bucak Onlar gelir gelir sarılır boynuma Of ulan of, of of da of... Çar...', ARRAY['Türk Edebiyatı','Şiir','Talip Kaplan']::text[], 8.5, '{"poet":"Talip Kaplan","poet_slug":"talip-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/of-of-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Askerleri (deneme)', 'ask-askerleri-deneme-nedim-saatcioglu-4bufv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Duvarları yıkmak istersin.bütün tabuları yerle bir etmek...

kim ne derse desin hayatı ilk defa yüreğinin sesinden dinlemek

istersin.bırakırsın her şeyi bir kenara ve her şeyi göze alırsın. 

umudun tükendiği anda telaş da biter yüreğinde. artık zaman çok 

geçtir...umut tetiğini çekmiştir...beklenen kapıya gelmiştir...

	“ne olursan ol gel”*** der yüreğin mantığına inat gözlerin 

bakışlarıyla bitirir kavgasını,kirpikler artık birleşmeden bakar 

karşındaki hayale ve sen belki de hayatında ilk defa bir şarkı 

söylersin yürek sesinle...

	pembe tohumlar serpersin yüreğinin toprağına ve sularsın

mutluluk gözyaşları ile...umutla büyüsün diye...

	uzak bir medeniyetin devrik krallığıdır artık sol yanın.yıkılır

yüreğinin kerpiç duvarları.bütün kilitler sökülür yürek kafesinden.

başını sol yanına yaslarsın,ruhuna kılıf olan bedeninin hükmü yoktur artık.hayalin gerçeğe dönüştüğü andır o an.kızgın çöl kumlarından

yemyeşil bir vahaya uzanır bakışların.duygular; denizin kumundan 

sıyrılan milyonlarca kabarcık tanesidir,aynı noktadan devleşmek 

üzere yola çıkmış.tüm zamanlar anlamını yitirir gözlerinde,mutlu-

luğun ayak seslerini duyarsın kirişte ve tenini yırtarcasına bir çığlık 

yükselir yüreğinden...

GELDİ...

	hayat en güzel oyuncağını sunmuştur sana,yaşlar titrer gözle-

rinde “Allah’ım ne olur bu düşsel yolculuğum hiç bitmesin” diye

dualar edersin mum ışıklarında ve uçarsın.oysa ne kanat vardır be-

deninde ne de bir akım savrulduğun göklerde...ruhun bedenine dar 

gelir.aniden aklına gelir arkanı döner yüreğine göstermeden silersin 

yalnızlığı avucundaki parmak izlerini...

	yanında yüreğinde,yüreğin kadar yanındadır.elini sol yanına 

koyarsın ve sımsıcak sarılırsın en saf yanınla.çünkü artık oradadır.

ruhunda onunla olmanın mutluluğunu kelimelerle anlatamadığın için 

kızmazsın kendine.

	isterse bütün saatler ayrılığı göstersin bütün dakikalar hüzünleri

sen yüreğinde yaşarsın hayalindeki  birlikteliği.adımların geçmişi 

sürüklemez ardından.her adım yeni bir nefes her nefes yeni bir heves 

için uzanır boşluklara.çırpınışın bittiği andır o an.

	her kelime ayrı çizersin onu yüreğine her harfte başka şekildir.

bulutların pamuğundan damıttığın saf bir safrandır sevgin.öyle çok 

birikir ki içinde artık her anın onunla doludur ve mutluluk yüreğinin 

tek yoludur.

	ıslandığın her yağmur damlasında gözyaşlarını görmezsin.yalnız-

lığın yasını tutmaz gözlerin uykusuz geceler boyu.soğuk odalarda kandil ışıklarıyla ısıtmaya çalışmazsın ruhunun üşüyen öteki yanını.her şey bir 

düş ötesidir.her şey bir izdüşüm.hani vardır ya “hayat bir film şeridi gibi gözlerinden akıp gitti” akıp gider zaman,sele kapılır bütün yoklar ve sen

varların tadına alıştırmaya çalışırsın damaklarını.dudakların tebessümle 

kıvrılır yukarı doğru. doğru zamanda doğru insanı bulmak adına...

	yaşam perdesini yeniden açmıştır senin için.bambaşka bir dekor 

vardır karşında ve hayatı anlatan bambaşka bir senaryo AŞK ASKERLERİ gelmiştir ihtilal vardır duygularında isyan bitmiştir.yüreğin yalnızlığın köleliğinden kurtulmuştur artık...

*** mevlana', 'Duvarları yıkmak istersin.bütün tabuları yerle bir etmek... kim ne derse desin hayatı ilk defa yüreğinin sesinden dinlemek istersin.bırakırs...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/ask-askerleri-deneme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçme,Vazgeçemem..', 'vazgecme-vazgecemem-i-nan-alver-eb8of', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Vazgeçme gülmekten,

Vazgeçemem gülüşünden.

Vazgeçme mutluluktan,

Vazgeçemem mutluluğundan.

Vazgeçme sevmekten

Vazgeçemem sevginden..', 'Vazgeçme gülmekten, Vazgeçemem gülüşünden. Vazgeçme mutluluktan, Vazgeçemem mutluluğundan. Vazgeçme sevmekten Vazgeçemem sevginden.....', ARRAY['Türk Edebiyatı','Şiir','İnan Alver']::text[], 8.5, '{"poet":"İnan Alver","poet_slug":"i-nan-alver","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/vazgecme-vazgecemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hangimiz..', 'hangimiz-i-nan-alver-qsumi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hangimiz bir sevda denizinde yelken açmadı ki,

Çoşkun dalgalara,

Bitmeyen fırtınlara,

Hangimiz sevdası için mücadele etmedi ki,

Kimileri küçük gördü bizi,

Acınacak bakışlarla,Alaycı sözlerle,

Kimler dalga geçmedi ki sevenle,

Peki hangimiz vazgeçtik sevdamızdan,

Hiçbirimiz,

Yılmayan duygularla,Bitmeyen sevdamızla

Bizde dalga geçtik,sevgimizle alay edenle,

Sevdayı öğrenememiş olduğundan,

Kalbinde sevgiyi yaşayamadığından,

Uzaklara yelken açar her seven

Yanına sevdasını alır,

Ta uzaklara götürür,

Kırılmaktan,incinmekten korkarak,

Sevda denize yelken açmamış,

Sevdasız yüreklerden kaçar', 'Hangimiz bir sevda denizinde yelken açmadı ki, Çoşkun dalgalara, Bitmeyen fırtınlara, Hangimiz sevdası için mücadele etmedi ki, Kimileri küç...', ARRAY['Türk Edebiyatı','Şiir','İnan Alver']::text[], 8.5, '{"poet":"İnan Alver","poet_slug":"i-nan-alver","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hangimiz-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böl Geceyi', 'bol-geceyi-batuhan-batu-8fb14', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Böl geceyi seher yerinden 

Yalnızlık bıraksın gecelerin peşini

Eğer karanlıklar alacaksa kahpeyi

Vur geceyi tam orta yerinden

Aksın kanları,sulasın caddeleri

Al al olsun sessizliğin yankısı

Bir ağıt yakıp  uzaklara

Kaç yolun tam orta yerinden

Saklan en kuytulara gözükme

Tanıyan olur enselerler seni

Öldürmek ti suçun yalnızlığı

Çek perdeyi tam orta yerinden

Dondur nefesini sesin duyulmasın

Kahpeler arıyor seni her yerde

Aç susuzsun kaç zamandan beri

Böl ekmeği tam orta yerinden', 'Böl geceyi seher yerinden  Yalnızlık bıraksın gecelerin peşini Eğer karanlıklar alacaksa kahpeyi Vur geceyi tam orta yerinden Aksın kanları,...', ARRAY['Türk Edebiyatı','Şiir','Batuhan Batu']::text[], 8.5, '{"poet":"Batuhan Batu","poet_slug":"batuhan-batu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bol-geceyi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdamın Sesi..', 'sevdamin-sesi-i-nan-alver-8v2v5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uzaklardan bir ses duyarsan seni çağıran,

Sevdamın sesidir,sana hasrettir,

Kalbinde bir sızı hissedersen,

Unutmaktandır,unutuluşumdur,

Yıldızlara bakıp daldığın her efkarda,

Bırakılıp gidişim vardır,

Buğulu camlara yazacaklarında,

Seni seviyorum deyişlerinin sonunda adım vardır,

Sevilmeyi özlersen..

Sınırsızca..

Özgürce..

Delicesine..

Unutma kalbimde her zaman yerin vardır...', 'Uzaklardan bir ses duyarsan seni çağıran, Sevdamın sesidir,sana hasrettir, Kalbinde bir sızı hissedersen, Unutmaktandır,unutuluşumdur, Yıldı...', ARRAY['Türk Edebiyatı','Şiir','İnan Alver']::text[], 8.5, '{"poet":"İnan Alver","poet_slug":"i-nan-alver","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevdamin-sesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlar…', 'i-nsanlar-hikmet-feridun-demir-fr7az', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İnsanlar,

Birilerini ederler Veli,

Birilerini ederler Deli…

Birilerini ederler Alim,

Birilerini ederler Zalim,

Birilerini ederler Serseri…

Kimini İmanlı, kimini İmansız..

Kimini inanan, kimini inanmayan…

Aslında aynı Tas aynı Hamam…

Kainatın sınırları, 

Milyarlarca ışik yılı, daha uzaktayken bizlerden…

Anlıyamıyorum,

Kainat için bu kadar anlamsız olduklarını,

Neden anlamazlar kendi Manasızlıklarını, 

Basit yorumlarla.. 

Duygusuz çıkarcı kalblerle..,

Hissız duygularla...

İnsanlık çok daha uzaklarda, Ondan... 

Hadi senin olsun… 

Zenginlik dediğin herşey…

Nedir o zenginliklerin,

yaşamınla ve Ömrünle olan oranları? ? ? ...

Tümünün değeri ile Ömründen bir saniye dahi artıramazsın…

Manasız, Manasız ve Anlamsız….

MANA olan duruyor yerli yerinde…..! ! ! ! ! ! ! ! ! ? ? ? ? ? ? ? ? ? ? 

Wermelskirchen 

Almanya….', 'İnsanlar, Birilerini ederler Veli, Birilerini ederler Deli… Birilerini ederler Alim, Birilerini ederler Zalim, Birilerini ederler Serseri… K...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Feridun Demir']::text[], 8.5, '{"poet":"Hikmet Feridun Demir","poet_slug":"hikmet-feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/insanlar-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Perşembe', 'uc-persembe-batuhan-batu-9kozu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gittin ya

Her gece bu saatlerde hasret türküsü çalar sazım

Sen gideli üç Perşembe kopardım takvimlerden

Ama sazımdaki türkü bir türlü değişmedi

Kalbimdeki sızı da mızrabın ilham kaynağı

Gözlerim her yerde seni arıyor yatakta,sandalyede

Yok diyemiyorum o gitti demek gelmiyor içimden 

Olur da o da bırakıp gider bir başıma kalırım buralarda

Hani o son gecemiz vardı bilmem hatırlar mısın

Yıldızların altında el ele diz dize oturuyorduk

Sen ‘’bak kaydı biri daha gördün mü ‘’? diye bağırdın

Oysa benin ne yıldızlar nede gök yüzü umurumda idi

Güneşim gidiyordu, bana ne yıldızlardan,aydan

Hazan rüzgarları yağmur kokusu getirince 

Mor menekşeli çıplak dağlardan

Gözlerime bakıp ağlamaklı bir sesle yavaşça 

‘’ben de bu yağmurla gideceğim ’’ diye ağlardın

her gidişin bir dönüşü vardır derdim ya sana

yanılmışım sevgilim. Gidenler dönmüyor sılaya

hasret çekilecek yük değilmiş be sevdiğim

yoksa bu yüz bizim omuzlarda daha mı ağır

alışmadık beklide onun için zor geliyor

hangi düşlere dalıyorsun beni almadan koynuna

kim bilir şimdi hangi rüzgar ıslatıyor saçlarını

saçlarını ellerinle okşa ıslak mı tenin 

üşütmüyor mu yatak seni bensiz

uyu sevgilim uyu,ben yine zamansız nöbetteyim', 'Gittin ya Her gece bu saatlerde hasret türküsü çalar sazım Sen gideli üç Perşembe kopardım takvimlerden Ama sazımdaki türkü bir türlü değişm...', ARRAY['Türk Edebiyatı','Şiir','Batuhan Batu']::text[], 8.5, '{"poet":"Batuhan Batu","poet_slug":"batuhan-batu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/uc-persembe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Hakkın Vardı', 'ne-hakkin-vardi-salih-ozalasan-rf2wu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne hakkın vardı? Böyle güzel

Ceylan gözlü erişilmez olmaya

Ne hakkın vardı? Ayaktan başa özel

Mitolojik ilâhelere taş çıkartmaya

Hayallerime beş çekmeye

Gördüğümde yüreğimi titretmeye

Kâlbimdeki belkileri tüketmeye

Böyle erişilmez olmaya ne hakkın vardı? 

Elin güzel, dilin güzel, tenin güzel

Tanrım yaratmış seni sanki özel

Karşımda huysuz birini beklerken

Böyle melek huylu olmaya ne hakkın vardı? 

Evim şenlendi yüreğim yasta

Yüreğim sana sevdalıydı, şimdi birde hasta

Bir gram aklım vardı, oda kalmadı başta

Aklımı başımdan almaya ne hakkın vardı? 

Bir/anda kendine bağladın çevreni

Merak edeni, aykırı gözle göreni

Ardında bıraktın onlarca seveni

Böyle gönül dostu olmaya ne hakkın vardı? 

Nisan yağmuru gibiydi gelişin

Aniden ve kısacık yağışın

Gelişinde mutlu gidişinde üzgün bakışım

Toprağım sana kanmadan gitmeye ne hakkın vardı? 

Yine kaldı bir başına sonserseri

Dolanıyor seninle dolaştığı yerleri

Kokun sinmiş açmıyorum penceremi

Geldiğine inanamadan gitmeye ne hakkın vardı

y. tarihi 29-07-04 Saat 16.000

Salih ÖZALAŞAN

(Şiirlerimin annesine ithaf olunur)', 'Ne hakkın vardı? Böyle güzel Ceylan gözlü erişilmez olmaya Ne hakkın vardı? Ayaktan başa özel Mitolojik ilâhelere taş çıkartmaya Hayallerime...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ne-hakkin-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlediğim', 'dusledigim-yusuf-koc-afwnm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zaman daraldıkça ümitler kısalıyor,

ümitler kısaldıkça da böyle şiirler yazılıyor.

...................................................................! ! 

Her zaman düşlediğim şey,

anafor gibi beni derinlerine çekecek..

her saniyesi sevda dolu,

her an gönlümde kıpırdanan...bir aşktı..! 

şöyle adamakıllı bir aşk..

varolmakla yokolmak arasında ki ince çizgi gibi..

başlayan ve biten gibi..

çağrışımlarda yaşayan,

her an ilkmiş gibi başlayan...bir aşk..! 

Bu hazzı yaşamak isterken...gördüm ki..

akıp gitmiş seneler..! 

korkarım onu bulduğumda,

artık zamanı geçmiş olacak,

diye düşünüyorum..

sabahları kendime bakarken aynalarda.! !', 'Zaman daraldıkça ümitler kısalıyor, ümitler kısaldıkça da böyle şiirler yazılıyor. ............................................................', ARRAY['Türk Edebiyatı','Şiir','Yusuf Koç']::text[], 8.5, '{"poet":"Yusuf Koç","poet_slug":"yusuf-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dusledigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-yusuf-koc-pvqrl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey hayat,

ne garipsin..

güldürmeyi beceremedin..

ağlatmak ta ustasın..

hiç olmazsa,

tebessüm etmeme fırsat ver.! !', 'Ey hayat, ne garipsin.. güldürmeyi beceremedin.. ağlatmak ta ustasın.. hiç olmazsa, tebessüm etmeme fırsat ver.! !...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Koç']::text[], 8.5, '{"poet":"Yusuf Koç","poet_slug":"yusuf-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hayat-146-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Kale', 'son-kale-i-smail-haki-simsek-8721g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşam iki iklim 

İki kalp

Dağ taş diyar diyar bağrımda

Yeşeren her yeni filizle

Ey sevgili merhaba! 

Sensizlik  sancıdır canımda

Ellerim siyah

Geceleri tutmuşum biraz

Ufuk bulut içre yokluk

Yara tutunmuşum biraz

Dağ yamacında papatyalara

Naz bırakmışım

Son kale yüreğimde

Surlarını...

Bırakmışım ellerine', 'Yaşam iki iklim  İki kalp Dağ taş diyar diyar bağrımda Yeşeren her yeni filizle Ey sevgili merhaba!  Sensizlik  sancıdır canımda Ellerim siy...', ARRAY['Türk Edebiyatı','Şiir','İsmail Haki Şimşek']::text[], 8.5, '{"poet":"İsmail Haki Şimşek","poet_slug":"i-smail-haki-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/son-kale-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maskeli', 'maskeli-damla-uysal-ke9ei', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayat bazen bir gülüş,

Maskeli,yüzü saklının yaptığı.

Bazen yüzyüze geliş...

Belki de yapmacıklıktan,sahtekarlıktan kaçış.

Hayat=SEN

Ya maskelisin,ya sahtekar

Ya da yüzüne gülünen...', 'Hayat bazen bir gülüş, Maskeli,yüzü saklının yaptığı. Bazen yüzyüze geliş... Belki de yapmacıklıktan,sahtekarlıktan kaçış. Hayat=SEN Ya mask...', ARRAY['Türk Edebiyatı','Şiir','Damla Uysal']::text[], 8.5, '{"poet":"Damla Uysal","poet_slug":"damla-uysal","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/maskeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki Yarasıdır Birbirinin Ayrılanlar', 'belki-yarasidir-birbirinin-ayrilanlar-adnan-durmaz-rmegt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Alevdir ağızda dil sözcükler yanar 

Neylesen anlatılmaz çekilen acı 

Yürek parçalanır can darmadağan 

Taşar bir damla gözyaşına 

Kan seli bir çığlıkla yıldırımlar savurur 

Zaman suratına çarpan beton bir duvar 

Susar saatlerin çanı 

Yanarsın zındanın ışımaz 

Ne bir tek düş- ne de anı 

Taşımaz vurgun yürek taşımaz 

Yere göğe sığmayan kederi 

Yaşarken öldürür insanı 

Yüreğe saplanan yâr hançeri... 

Ey yarası bağrında dağlanan yetim yürek 

Şimdi ağla ağlamanın vaktidir 

Hiç bir söz anlatamaz ahını 

Ne desem yalan 

Tökezleyip düşmüşsün dipsiz uçurumlarda 

Ayrılık doğmuş ufkundan 

Kimsesizsin- ıssızsın 

Hangi kapıyı çalsan kilitli 

Filizkıranlar dalamış çıvgalarını 

Darmadağınsın işte 

Belki yarasıdır birbirinin ayrılanlar 

Belki de hiç bir şeyi 

Artık ne dost kalınabilir 

ne düşman 

ne sevgili 

Çünkü çıkaramaz bunlar 

yürekten 

kanatan hançeri 

Ağızda alevdir dil- sözcükler yanar gider 

Dağların gazel dökmüş yitirmiş şarkısını 

Kalmışsın işte 

Yuvası tütsülenmiş bir tilki gibi 

Nacâr 

Kar altında 

Ve ayrılıklarda yağmalanmış gençliğin 

Orada 

Bir başına ölmek istersin 

Bilirsin ağlamak isyan etmek boşuna 

Yürekte açılan çatlak 

O gelse de kapanmayacak 

Başka yolu yok 

Bir düş gibi silin git 

Bu sevgisiz ummanda yit 

O bulamasın seni 

Ve bütün köprüleri yık geçtiğin yollardan 

Arayamasın seni.. 

Ağustos-94 

Adnan Durmaz

yarın yeniden,gerçek sanat yay,ist', 'Alevdir ağızda dil sözcükler yanar  Neylesen anlatılmaz çekilen acı  Yürek parçalanır can darmadağan  Taşar bir damla gözyaşına  Kan seli bi...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/belki-yarasidir-birbirinin-ayrilanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehr-i İstanbul', 'bu-sehr-i-i-stanbul-zafer-ugur-88kv0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen her zaman bir başkasın İstanbul.

''Taşın toprağın altın''

Derlerdi bir vakitler.

Belli! 

Altını üstüne getirmişler.

''İstanbul bir âlem'' diyorlar şimdi de.

O da yalan; 

Ne bilsinler,

İstanbul''da yaşıyor milyonlarca insan,

Apayrı milyonlarca âlem! 

(1975)', 'Sen her zaman bir başkasın İstanbul. ''Taşın toprağın altın'' Derlerdi bir vakitler. Belli!  Altını üstüne getirmişler. ''İstanbul bir âlem'' di...', ARRAY['Türk Edebiyatı','Şiir','Zafer Uğur']::text[], 8.5, '{"poet":"Zafer Uğur","poet_slug":"zafer-ugur","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bu-sehr-i-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuluk', 'korkuluk-adnan-durmaz-g0tau', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kemirmiş ruhunu bir kurt gibi 

Yüzyıllardır bu anlamsız suskunluk 

Sen bozkırlar ortasında kalmış zavallı korkuluk 

Deryalar toplansa 

Bir daha yeşermeyecek odunlardan habersiz 

            beklersin 

Çoktan karışmış toprağa 

Seni çakan adamın lanetli parmakları 

Başında kuş pisliklerinden aslını yitirmiş şapkan 

Şükredersin bu uğursuz yalnızlığına 

Bilmezsin 

Artık ne çekinen var senden 

Ne korkan 

         ne sakınan 

Korku bile utanır bu ahmak duruşundan 

Suskunluğun gecesisin 

    şarkısız

         yıldızsız

              aysız 

Kuşların eğlencesisin 

       onursuz

            hayasız

                   arsız 

Rüzgârlar küfreder sana değince 

Tükenmişsin sen 

           coşkusuz ve hülyasız... 

Ceketini giydiğin delikanlıyı 

Vurdular bir kavgada 

Ödünç aldı akarsular-bulutlar 

              dudağında yarım kalan şarkıyı 

Şapkan ölmüş bir ağadan kaldı marabasına 

Sonra on baş değiştirdi babadan oğula... 

Zulümlere tapındın sen korkuluk 

Ölüm aşın oldu- kıran ekmeğin 

Umurunda bile olmadı 

          dışında çekilen acılar 

Dalına konan kuşları 

             pusuya düşürür oldu avcılar 

Ve hep talanı yazdı tarih 

               güzelim ay çiçeği tarlasında 

Senin yüzünden.. 

Senin yüzünden bu yağma saltanatı 

Bu kement

         bu duvar

                bu kan

                        bu yara 

Sen kul olup yaşadıkça bu zincirli korkulara 

Bir lânet de benden sana 

Bütün korkuluklara... 

Adnan Durmaz

  yarın yeniden,gerçek sanat yay,ist', 'Kemirmiş ruhunu bir kurt gibi  Yüzyıllardır bu anlamsız suskunluk  Sen bozkırlar ortasında kalmış zavallı korkuluk  Deryalar toplansa  Bir d...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/korkuluk-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzünleme', 'huzunleme-funda-ozdemir-nnjxp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '(I) 

..

Selâ  vakti

Defn edilmiş bir meftadır gece

birazdan ayyuka çıkacak güneş

kimle oynaşmışsa yıldızlar

hapsedecek altın okuyla

üşüyünce üzerini örten birileri olmalı insanın

kırılınca yanağına dokunacak

gitme seanslarında

dur,dön diye çağıracak

her vedasında ardına bırakıp gittiğinde

gitmemiş sayacak

ne çok kesik ellerim

boş ver kesiği

yüreğin damlıyor....! 

(II) 

eylülden önce dökülüyorum

yeşerip yetişmeliyim baharlara

güneş bütün teleklerimde şavkımalı

menekşe koyuluğu vurmalı göz pınarlarımıza

akdıkça arınmalı 

üşüdüğümde üzerimi örtmeli 

sevdalım

kırılınca değmeli yanağı

alnımın ortasına

dur …! 

nereye bensiz demeli

kesikleri temizlemeli

eylülden önce,ben gitmeliyim', '(I)  .. Selâ  vakti Defn edilmiş bir meftadır gece birazdan ayyuka çıkacak güneş kimle oynaşmışsa yıldızlar hapsedecek altın okuyla üşüyünce...', ARRAY['Türk Edebiyatı','Şiir','Funda Özdemir']::text[], 8.5, '{"poet":"Funda Özdemir","poet_slug":"funda-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/huzunleme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgârın Dilinden Gülümser Hâlâ', 'ruzg-rin-dilinden-gulumser-h-l-adnan-durmaz-oii3h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Rüzgârın Dilinden Gülümser Hâlâ 



Onun adı çiçekti ve bulvarlar 

Baharla çalkalanırdı o yürüdükçe 

Başaklar hışımla çoğaltırdı tanelerini 

Bereketli bir umut tarlasıydı gülüşü 

Adı bir çağlayanın kepire dökülüşü 

Türküleri ateşten ve hüzünden biçilirdi 

Özlemle tomurcuk vururdu gözlerinde 

Kaç körpecik baş sunulmuş yarınlar 

Dirençler yaprak yaprak boy atar akşamlarında 

Ki onun adı rüzgâr 

Kaç denizi ateşe vermiş öfkesi 

Yemyeşil bir düğünde coşturur bozkırları 

Dağ kesilmiş kederler diz çöker bakışlarında 

Halaya durur sarı 

Sonra ansızdan yitti 

Bir isyan şarkısına karıştı sesi 

Derler ki 

Filistin askısında ölümle alay etti 

Derler ki 

Rüzgârların dilinden gülümser hâlâ 

Bilinen son adı kardelendi 



 



Adnan Durmaz

yarın yeniden,gerçek sanat yay,ist', 'Rüzgârın Dilinden Gülümser Hâlâ  Onun adı çiçekti ve bulvarlar  Baharla çalkalanırdı o yürüdükçe  Başaklar hışımla çoğaltırdı tanelerini  Be...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ruzgarin-dilinden-gulumser-hala-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sigara', 'sigara-zafer-ugur-emx7w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Duman duman duygular

Karanlığa karışan.

Gecelerde kaybolan

Tül tül insanlar, yollar.

Tül tül saçlar omuzda

Saçılan / yağmur gibi.

Duman duman bu gece

İstanbul sokakları.

Karanlığa karışan

Duman duman kaygılar.

(1976)', 'Duman duman duygular Karanlığa karışan. Gecelerde kaybolan Tül tül insanlar, yollar. Tül tül saçlar omuzda Saçılan / yağmur gibi. Duman duma...', ARRAY['Türk Edebiyatı','Şiir','Zafer Uğur']::text[], 8.5, '{"poet":"Zafer Uğur","poet_slug":"zafer-ugur","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sigara-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dert', 'dert-zafer-ugur-1ibdy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hıııh, hııh

Çökmüş bir köşeye,

İç çekip duruyor.

Gözleri dalmış bir noktaya; 

Kararsız...

Sıkıntılı...

Hâlinden belli.

Ya âşık bu adam,

Sırılsıklam.

Ya da akşam yedikleri

Oturmuştur midesine belki.', 'Hıııh, hııh Çökmüş bir köşeye, İç çekip duruyor. Gözleri dalmış bir noktaya;  Kararsız... Sıkıntılı... Hâlinden belli. Ya âşık bu adam, Sırı...', ARRAY['Türk Edebiyatı','Şiir','Zafer Uğur']::text[], 8.5, '{"poet":"Zafer Uğur","poet_slug":"zafer-ugur","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dert-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayrat Çeşme', 'hayrat-cesme-mustafa-ceylan-rtjjb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '---''Can Kardeşim AsiÇiçek''e Saygılarımla...---

Bilir misin gecelerin koynunda

Bir çeşme var, akar akar, hep akar...

Erenlerin, kitapların içinde

Bir çeşme var, akar akar, hep akar...

Gece gündüz dost yolunda eğleşen

Kuşlar ile, yolcularla söyleşen

Bayram günü yetimlerle ağlaşan

Bir çeşme var, akar akar, hep akar...

Düşüvermiş dertlilerin derdine

Dertlerimi zevk edinmiş kendine

Asırlardır sevenlerin gönlüne

Bir çeşme var, akar akar, hep akar...

Bilir misin suladığı ağacı? 

Yaprakları, çiçekleri duacı...

Yüreğimden sana doğru ey bacı

Bir çeşme var, akar akar, hep akar...

Ufukların yangınını söndüren

Yanlış yoldan yolcuları döndüren

Bulutları çekip çekip indiren

Bir çeşme var, akar akar, hep akar...

İşittim de çölün-gülün sesini

Sevinçimden göğe attım fesimi; 

Hikmet ile dolduracak tasımı

Bir çeşme var, akar akar, hep akar...

''Hayırlıdır alan elden veren el''

Gariplerin rüyâsına giren el,

Susuz kalma sevdiceğim durma gel

Bir çeşme var, akar akar, hep akar...

Bilir misin bulutları, buharı? 

Her çeşmenin gök yüzünde baharı,

Sağa, sola, aşağı ve yukarı

Bir çeşme var, akar akar, hep akar...', '---''Can Kardeşim AsiÇiçek''e Saygılarımla...--- Bilir misin gecelerin koynunda Bir çeşme var, akar akar, hep akar... Erenlerin, kitapların iç...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/hayrat-cesme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözümüz Yok Bu Dünyada', 'gozumuz-yok-bu-dunyada-mustafa-ceylan-5qfax', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gönlümüz yok bu dünyada

Alan alsın, satan satsın...

Ellerimiz nefsimizin

Yakasından tutup atsın...

Bir menzile ulaşalım,

Alev alev tutuşalım

Bir mecliste buluşalım

Dost söylesin, dost anlatsın...

Ne ararsan var insanda,

Gözümüz yok ün''de-şan''da

Can gizlidir nice canda

Can canânı geldi sansın...

Terkederek maddiyatı

Yola düşsün gönül atı...

Bu dünyada iyi, kötü

Zerre zerre aydınlansın...

Bu dünyaya göz koymadık

Çağrısını hiç duymadık,

Nefsimizi yere çaldık

Ruh kökümüz bir uyansın...

İsteyenin olsun dünya

Bize gerek kutlu rüya

Sevgi varken boştur kavga

Gönül elbet barıştansın...', 'Gönlümüz yok bu dünyada Alan alsın, satan satsın... Ellerimiz nefsimizin Yakasından tutup atsın... Bir menzile ulaşalım, Alev alev tutuşalım...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gozumuz-yok-bu-dunyada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düzene İsyanlardayım..! (1)', 'duzene-i-syanlardayim-1-nazife-abayli-zi2xm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Heeeyyy! Şair yüreklim..! 

D u y s e s i m i! 

İster kelepçelet elimi,

İstersen at dört duvar arasına,

S u s t u r  n ef es i m i..! 

Ne vaatlerle geldin sen şu makama,

Hatırlıyor musun? 

Milyonlarca insanı,

Gözünün içine baka kandırıyorsun.

Sana ne mesajlar gönderdim ama okumuyorsun.

Göndersene iki tane polis,

Alnım açık bekliyorum…

Neden beni   t u t u k l a t m ı y o r s u n..? 

Gözüm kara benim,

Sana meydan okuyorum.

Sanma ki susacağım,

Zaten yaşamım bitmiş benim..

Kalk bir,silkelen,koltuğunda zamanın dolmuş senin,

Halen ne peşindesin? 

S a k  l an m ı y o r u m..! 

Memurunum ben senin..! 

Seçim sandıklarının başında,

Seçimini senden yana kullanmış,

Binlerce insandan,

Bir tanesi bile değilim (siyasi bir partiye üye olma hakkım yok ama

seçim zamanı oyum istenir benim..yoksa ceza yerim…) 

Memurunum,öğretmeninim ben senin..! ! 

Heeeyyy! Şair yüreklim..! 

D u y s e s i m i! 

İster kelepçelet elimi,

İstersen at dört duvar arasına,

S u s t u r  n ef es i m i..! 

Boğsan da beni…

Susmayacağım..! 

Kesemezsin sesimi..! ! 

Kesemezsin sesimizi…! ! 

Yaşamı bitmiş benim gibi,binlercesini..! ! 

S u s t u r a m a z s ı n..! ! 

Zorlasan da bu insanları,

Bu ülkeden,

A t t ı r a m a z s ı n..! 

(Düzene İsyanlardayım)', 'Heeeyyy! Şair yüreklim..!  D u y s e s i m i!  İster kelepçelet elimi, İstersen at dört duvar arasına, S u s t u r  n ef es i m i..!  Ne vaa...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/duzene-isyanlardayim-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düzene İsyanlardayım..! (2)', 'duzene-i-syanlardayim-2-nazife-abayli-9g0zc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Deli miyim neyim ben? 

Dilime vurdu isyanlarım..

Kalemi kağıdı aldığımda elime,

Küfretmek geliyor içimden,

Aydınlık değil yarınlarım..! 

Şair değilim ki şiir yazayım,

Aşklarımı,ihanete uğrayışımı anlatayım.

Güzeldir belki sesim,

Anlar ancak beni duvardaki sazım.

Ben söylerim,ben çalarım,

Sanatçı da değilim ki,sahneye çıkayım..! 

Dertlileri rahatlatayım..! 

Sadece konuşurum,tatlıdır belki dilim,

Süsleyemem sözlerimi,edebiyatçı değilim.

Mevlana’dır yolum,Yunus’tur Pirim,

Dilime de sahibim,belime de ama,

Gelmez ki canımı alacak  Eren’im.

Gel artık dost! 

Ruhumun aynasıdır bu! 

Hata arama! 

Geçmedim nağmert köprüsünden,

Seçmedim odunun eğrisinden.

Sabrettim bak! 

Hazırım geçmeye sırat köprüsünden! 

Bin bir türlü belaya,dosta,düşmana,

Seslendim ozanım gibi,

Sazımı çalan ozanım gibi,

Çaldım söyledim acemice sözümü,sazımı,

Duyuramadım.

Ozanlıkta usta da değilim ki,

Düzene sesimle,sazımla karşı koyayım.! ! 

(Düzene İsyanlardayım)', 'Deli miyim neyim ben?  Dilime vurdu isyanlarım.. Kalemi kağıdı aldığımda elime, Küfretmek geliyor içimden, Aydınlık değil yarınlarım..!  Şai...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/duzene-isyanlardayim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rastgele..!', 'rastgele-nazife-abayli-jtfhv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seveceksen adam gibi sev,sözcük ukalılığı yapma! 

Zamanı yok boş laflara,hadi ordan,çeneni yorma! 

Gireceksen eğer yatağına çıkamazsın bir daha..

Zaman eğlence zamanı değil,rastgele..! 

Kandıramazsın karnı tok tutulmayan sözlere,

Yaşı gelmiş kırka uğraşmaz çocuklarla,

Sen yolun başındayken daha iki kez bitirmişti o, hergele..! 

Zaman eğlence zamanı değil,rastgele…! 

Yanlış insanı seçtin,meyil vermez ki  sana,

Düşmez tuzağına,erkeksiz kalsa da yıllarca,

Onur,şeref,namus der,harcama boşuna çaba,

Zaman eğlence zamanı değil,rastgele..! 

Nasılda dil dökersin kazanmak için yüreğini,

Üçüncü gün görmezsin gönül yarasını, ah bir aralasa eteğini,

Gece gündüz uyutmaz çalarsın kapısını,istersin bedenini,

Zaman eğlence zamanı değil,rastgele..! 

İster Hasan,ister Mustafa,isterse Özgür olsun adın,

Kokladın mı tenini, ardına bakmazsın yarın,

O güzel sözlere hasrettir aslında evdeki kadının,

Zaman eğlence zamanı değil,rastgele..! 

Balık değil,attımı oltanı avlayasın,

Senden akıllıdır,düşersen tuzağına anlayamazsın,

Batırır ocağını,dağıtır evini barkını toplayamazsın,

Zaman eğlence zamanı değil,rastgele..! 

Sana söylüyorum,aklı bacak arasında sıkışmış geri zekalı,

Ne sandın sen kadınları,her şeyden değerlidir aşkları,

Aşık oluyorlar diye,herkese açık değildir yatakları,

Zaman eğlence zamanı değil,rastgele..! 

Hep aynı sözler dilinde,anlaşmış gibi,

Eşin mutlu edemez,ararsın kendine benzeyeni,

Çoluk çocuk bir yana,nikahtır bağlayan sizi

Zaman eğlence zamanı değil,rastgele..! 

Ne günahı var peki,yaşamla savaşan yalnızların,

Girmek istersin gönlüne,ekmek arayan garibanların,

Elde edince kaçarsın,değmez kıçına topukların,

Zaman eğlence zamanı değil,rastgele..! 

(Düzene İsyanlardayım)', 'Seveceksen adam gibi sev,sözcük ukalılığı yapma!  Zamanı yok boş laflara,hadi ordan,çeneni yorma!  Gireceksen eğer yatağına çıkamazsın bir d...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/rastgele-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kobaya', 'kobaya-ersin-goktas-bq4t6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'içimden geçeni yazarım geçtiğigibi...  bastıra bastıra yazarım aldırmadan etrafa aldırmadan zamana  mekana yalın ve yalnız kalmışcasına koskoca dünyada

    bir cigara yetişir imdadıma boğuluyormuşcasına birnefes çekerim birnefes daha uzun birgece olacak yetsin götürsün beni sabaha ciğerim çaresiz ciğerim bitik ve ezik  yüreğim yaşanmış sevdaların altında...  cigaram dostum  benim yanar ha yanar yanar tüter efkar yanar dumanı sarar bedenimi cigaram yalnızlığıma  deva dertlerime çare....', 'içimden geçeni yazarım geçtiğigibi...  bastıra bastıra yazarım aldırmadan etrafa aldırmadan zamana  mekana yalın ve yalnız kalmışcasına kosk...', ARRAY['Türk Edebiyatı','Şiir','Ersin Göktaş']::text[], 8.5, '{"poet":"Ersin Göktaş","poet_slug":"ersin-goktas","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/kobaya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rağbet', 'ragbet-mustafa-ceylan-1t3ei', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gönül burçlarında aşkın bayrağı

İlâhi rüzgâra bin yıldır hasret

Bayrağın gölgesi sarmış toprağı

''Hakk! '' diyen yerlerden sanadır rağbet...

Kurtuldum, kurtuldum nefis ağından

Duruyor içimde devamlı gurbet.

Elbise giyindim gök kuşağından

''Rabb! '' diyen göklerden sanadır rağbet.

Bayrağım, toprağım seslenir bana:

''Az kaldı, az kaldı ey Ceylan sabret! ''

Hakikat mührünü vurmuş cihana,

''Rabb! '' diyen kırlardan sanadır rağbet.

Daneyi, tohumu yaratan sensin

Cümle tarlalarda heyecan, gayret.

Yedi renk, dört kapı donatan sensin,

''Hakk! '' diyen sırlardan sanadır rağbet.

Yoktur senden önce yada sonrası

Senden bekliyoruz, senden mağfiret! 

Mülkün, melekut'' un sonsuz sevdası

''Rabb! '' diyen sur''lardan sanadır rağbet...

Semâvat ve arz''ın Kayyum'' u Rabb''im

Ben âciz kulunum, sense Azâmet.

Nurunla infilâk etmeli kalbim,

''Hakk! '' diyen nurlardan sanadır rağbet...

Kulunun Hakk''ına kavuşması hak

Senden bekliyoruz kullara rahmet.

Aşkın yağmurunu çöllere bırak,

''Hakk! '' diyen çöllerden sanadır rağbet...

Dönüşler sanadır, tevekkül sana

Rızan ile olur elbet selâmet.

Kara sevdalıdır bu gönül sana

''Rabb! '' diyen gönülden sanadır rağbet.

...........................', 'Gönül burçlarında aşkın bayrağı İlâhi rüzgâra bin yıldır hasret Bayrağın gölgesi sarmış toprağı ''Hakk! '' diyen yerlerden sanadır rağbet... K...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ragbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göz Altında', 'goz-altinda-mustafa-ceylan-ockxb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dikenleri goncasını

Bulundurur göz altında.

Bahçıvanı bahçesini

Bulundurur göz altında

Kaplumbağa kabuğunu

Yağız atlar topuğunu

Sulak tarla boz tohumu

Bulundurur göz altında

Gönül kuşu kafesini

Bulutlar dağ tepesini

Hakk aşığı nefesini

Bulundurur göz altında

Gökyüzünü yıldızları

Aynaları yaldızları

Çılgın dili ağızları

Bulundurur göz altında

Dallarımız çiçekleri

Toprağımız böcekleri

Anaları çocukları

Bulundurur göz altında

Güvenlikçi mahpusları

Fitilleri fânusları

Yeşil kabuk karpuzları

Bulundurur göz altında

Nurdan sistem gezegeni

Elektronlar çekirdeği

Cümle sözler son gerçeği

Bulundurur göz altında

Şairimiz şiirini

Alimimiz fikirini

İnanan dost, zikirini

Bulundurur göz altında

Ceylanlarım ceylanını

Mehmetçik de vatanını

Mü'' min elbet kelâmını

Bulundurur göz altında', 'Dikenleri goncasını Bulundurur göz altında. Bahçıvanı bahçesini Bulundurur göz altında Kaplumbağa kabuğunu Yağız atlar topuğunu Sulak tarla ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/goz-altinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birini Arıyorum', 'birini-ariyorum-mustafa-ceylan-3wthz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Acıyı bal sayacak

Birini arıyorum.

''Daha var mı? ''diyecek

Birini arıyorum.

Dünyaya sırt dönecek

Aşkına can verecek

Ölmeden ölüver''cek

Birini arıyorum.

Kendini yok sayacak

Peygamber''i duyacak

Yunusca şakıyacak

Birini arıyorum.

Mevlâ'' dan gayrisi boş

Ölüm mü? Ne kadar hoş! 

Aşkıyla deli, sarhoş

Birini arıyorum.

Ancak O'' nu bilecek

Ancak O''na gidecek

Hep O'' ndan dileyecek

Birini arıyorum.

Bakmayan mülke, mala

İçinden taşan sıla

Hasretim diyen sala

Birini arıyorum.

Şöhreti, şanı atan

Hoşgörü, ilim satan

Gökyüzünü ağlatan

Birini arıyorum.

Çağrıyı duymuş olan

Dünyaya doymuş olan

Yola baş koymuş olan

 Birini arıyorum.

Ey Ceylan''ım Hakk''a dayan

Gerisi boş ve yalan

Ceylan''da ceylan olan

Birini arıyorum...', 'Acıyı bal sayacak Birini arıyorum. ''Daha var mı? ''diyecek Birini arıyorum. Dünyaya sırt dönecek Aşkına can verecek Ölmeden ölüver''cek Birini...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/birini-ariyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanfiller 1', 'karanfiller-1-erol-dal-dn3tt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ay’a sakladığım mektuplarımı yırtma ne olur.

Adın, ay’a ulaşsa da

Bana bırak

Buruşmuş geleceği.

yalnızım nasılsa.

Adını, andığım 

ay parlak gecelerimde

Ansızın, geldiğin gecelerde 

parlaktı, ama neyse.

Bakışlarımız, birbirine 

Birer hile,

Açtığımız, şarap

Aldığımız kadeh,

Yasaktı.

>>>>>

Şimdi efkârı dağıtma vakti

Şeyhin emrinden çıkan olmaz

Şeyh ki, 

Şarkılardan hikâye.

Şövalye gençliğimin

Şövalyesi o.

Patlayan son ses de

Patırtıdan seçemedim.

Papatyamı soluyordu serçeyi

Sokan yoksa arımıydı? 

Polen, polen dökülen 

yüreğime.', 'Ay’a sakladığım mektuplarımı yırtma ne olur. Adın, ay’a ulaşsa da Bana bırak Buruşmuş geleceği. yalnızım nasılsa. Adını, andığım  ay parlak ...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/karanfiller-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beri Gelsin', 'beri-gelsin-mustafa-ceylan-btj7u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşk şehrinde deli deli

Gezebilen beri gelsin

Mansur olup candan teni

Yüzebilen beri gelsin

Bulutlarda ak kefeni

Sezebilen beri gelsin

Defterine Yüce DİN''i

Yazabilen beri gelsin

Hoşgörüyle öfkesini

Ezebilen beri gelsin

Maldan, mülkden kendisini

Süzebilen beri gelsin.

Hakk Hakk! diye nefesini

Dizebilen beri gelsin

İmanıyla hedefini

Çizebilen beri gelsin

İmansızlar cephesini

Bozabilen beri gelsin

Elleriyle kabirini

Kazabilen beri gelsin...', 'Aşk şehrinde deli deli Gezebilen beri gelsin Mansur olup candan teni Yüzebilen beri gelsin Bulutlarda ak kefeni Sezebilen beri gelsin Defter...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/beri-gelsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık-1', 'ayrilik-1-mustafa-ceylan-c1gtm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bulutsuz, rüzgârsız, karsız olsa da

Dağları yerlere yıkan ayrılık...

Gönül okyanusta tutuşan ada,

Suyu alev alev yakan ayrılık...

Canım aradığı ufku bulsa da

Apansız karşıma çıkan ayrılık...

Hem gurbet elde, hem de sılada

Bir şimşek misali çakan ayrılık...

Bin nesil geçse de cümle insanda

Çağlaya çağlaya akan ayrılık...

Vakti geldiğinde sevdalı can''da

Misk-i amber gibi kokan ayrılık...

Sabır ağacından koptuğun anda

Başını belâya sokan ayrılık...', 'Bulutsuz, rüzgârsız, karsız olsa da Dağları yerlere yıkan ayrılık... Gönül okyanusta tutuşan ada, Suyu alev alev yakan ayrılık... Canım arad...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ayrilik-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adak', 'adak-ali-galip-sari-u6qz2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '(Görürsen gözümde gizli bir hüzün ;) 

Ben senin sevdana ramımdır hala,

Hülyan gözlerimden silinmemiştir''

Bu kadar sevmemiş  Mecnun''u Leyla,

Hiç   kimse bu kadar sevilmemiştir! 

Ferhat delmemiştir bu koca dağı,

Bu dağ şirin için delinmemiştir! 

Kmse adamamış bu zor adağı,

Evelce can adak edilmemiştir! 

Ki bir ben adadım bu zor adağı,

Evvelce olmayan adanmayanı,

Canına katıver bendeki canı,

Hangi can demiştir? -Denilmemiştir!', '(Görürsen gözümde gizli bir hüzün ;)  Ben senin sevdana ramımdır hala, Hülyan gözlerimden silinmemiştir'' Bu kadar sevmemiş  Mecnun''u Leyla, ...', ARRAY['Türk Edebiyatı','Şiir','Ali Galip Sarı']::text[], 8.5, '{"poet":"Ali Galip Sarı","poet_slug":"ali-galip-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/adak-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diriliş', 'dirilis-mustafa-ceylan-v0njp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kar yağarken yamaçlarda direnen

Bir kardelen çiçeğidir diriliş.

Al, kırmızı, gonca gonca görünen

Goncaların gerçeğidir diriliş.

Dost dağından yere düşen çığ gibi

Fatihlerin açtığı bir çağ gibi

Ferhatların yüreğinde dağ gibi

Sevdaların ölçeğidir diriliş.

Mevsim mevsim, adım adım yürüyen

Bulutların saçlarını tarayan

Minnacık bir mutluluğu arayan

Sevenlerin merceğidir diriliş.

İnsan insan doldurandır bulvarı

Binbir renge boyayandır duvarı

Gönlümüze sarmalayan baharı

Sevgilinin kucağıdır diriliş.

İnançsızın kafasını oynatan

Türküsünü dağa, taşa dinleten

Damar damar sancıları kaynatan

Umutların ocağıdır diriliş.', 'Kar yağarken yamaçlarda direnen Bir kardelen çiçeğidir diriliş. Al, kırmızı, gonca gonca görünen Goncaların gerçeğidir diriliş. Dost dağında...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dirilis-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmişim Seni', 'sevmisim-seni-mustafa-ceylan-bqcv1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Esiyor içimde tayfun, fırtına

Beden gömleğini giyemiyorum.

Düştüm sanki yanıp duran fırına

Suskunum, hiç bir şey diyemiyorum.

Ten kafesim can kuşuma dar gelir

Geçen zaman şimdi bana zor gelir

Hesabın sonunda mutlak BİR gelir

BİR'' den başkasını sayamıyorum.

Kur''an merceğinde içsel seçimler

Yâre yüreğimi bağlar sicimler

Dar geliyor elde duran hacimler

Nedense kabımda duramıyorum.

Çağırıyor almak için kabristan

Kabristan ki inanana bir bostan

Bir düzen tuttursam ben yeni baştan

Çalışıp düzeni kuramıyorum.

Kimi gün âcizim, kimi gün atak

Çepçevre kuşatmış dünyamı batak

Günah çivisiyle donanmış yatak

Başımı yastığa koyamıyorum.

Affeyle ey Rabb''im! Affeyle beni! 

Bize de nasip et, bir dünya, yeni...

Kabul et duamı, sevmişim seni

Asla başkasını sevemiyorum...', 'Esiyor içimde tayfun, fırtına Beden gömleğini giyemiyorum. Düştüm sanki yanıp duran fırına Suskunum, hiç bir şey diyemiyorum. Ten kafesim ca...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevmisim-seni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarhoşun Çağrısı', 'sarhosun-cagrisi-mustafa-ceylan-7caa9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu sarhoş nereden gelmiş diyerek

Meydana bağlayıp taşlayın dostlar.

Millet ağlar iken gülmüş diyerek

Kızgın sular ile haşlayın dostlar.

Bitirdim içimde olan savaşı

Yok ettim ruhumda, derdi-telâşı

Ağır ağır kesin isyânkâr başı

Derimi yüzmeye başlayın dostlar.

Kendimden geçmişim, mülkten bana ne? 

Sarhoşum, bir hoşum, oldum şahane

Vurun kırbaçları bulman bahane

Al - kırmızı renkle hoşlayın dostlar...

Efkârı, kavgayı bir yana attım

Bunca yıl boşuna konuşup öttüm

Kabına sığmayan nice lâf ettim

Kemal bıçağıyla şişleyin dostlar.

Bitmeyen sevdanın destanlarına

Gönül bekçisinin bostanlarına

Söz duymaz beylerin kaftanlarına

Beni sırma sırma işleyin dostlar.', 'Bu sarhoş nereden gelmiş diyerek Meydana bağlayıp taşlayın dostlar. Millet ağlar iken gülmüş diyerek Kızgın sular ile haşlayın dostlar. Biti...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sarhosun-cagrisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Çöplüğü', 'yalnizlik-coplugu-mehmet-caner-sumengen-cilu4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalnızlık çöplüğüne atılmış bir aşığım

Ayrılık pazarında bedavaya satıldım

Eremeden vuslada karardı son ışığım

Severek ölenler kervanına katıldım...', 'Yalnızlık çöplüğüne atılmış bir aşığım Ayrılık pazarında bedavaya satıldım Eremeden vuslada karardı son ışığım Severek ölenler kervanına kat...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Caner Sümengen']::text[], 8.5, '{"poet":"Mehmet Caner Sümengen","poet_slug":"mehmet-caner-sumengen","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yalnizlik-coplugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duvar', 'duvar-kadri-erdem-imr5f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Duvarda kendime baktım 

Gördüğüm duvar ta kendimdim

Yaşayan beni göremedim

Ben hiç yaşamıyor muşum

                                    04/07/2003                 00:55', 'Duvarda kendime baktım  Gördüğüm duvar ta kendimdim Yaşayan beni göremedim Ben hiç yaşamıyor muşum                                     04/07...', ARRAY['Türk Edebiyatı','Şiir','Kadri Erdem']::text[], 8.5, '{"poet":"Kadri Erdem","poet_slug":"kadri-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/duvar-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acıların', 'acilarin-zafer-zengin-etnika-c7h6i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüzüne salaklık sürdün

Sen nerden bilirsin sevdayı

Aşıksın zaten

Düş pencereden

Düşeydin düşüne

Üşenme

Sarıl ince beline

Nasıl severdin bilmem

Gecenin bir vaktinde

Vapuru yok kavuşmanın

Bu şehrin ve acıların

Kaçırdık

Zaman sarhoş

Bizi içmiş yine

seve seve

Dilinde bir şarkı

Güvercin sesi

Nerden bilsin şehir

Sevgimizi

Vapuru yok kavuşmanın

Bu şehrin ve acıların

Ayrıldık

21 Temmuz 2004', 'Yüzüne salaklık sürdün Sen nerden bilirsin sevdayı Aşıksın zaten Düş pencereden Düşeydin düşüne Üşenme Sarıl ince beline Nasıl severdin bilm...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/acilarin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buradayız', 'buradayiz-zafer-zengin-etnika-6ftyh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Taşıdığın yükün eğrisi

Elim kazalara benzerken

Yüreğim masum ölümler görüyor

Gülerken uğurladığımızdı

Kendimiz sakladığımız gölge

Sen alışkındın harplere

En çok sevgiyle

Hüzünle gülümser gönderirdin

Sayabildin mi ellerini

En çok kime değdi

Gururlu kemikleri 

kim iyileştirdi

Sızı kalem kalem düşüyor

Hiç dokunulmayacak belki

Kirpiğinin sesine

Kırptıkça içten öten

Belki hiç göremeyeceksin

Soruları kalacak aklında

Cevabı cevremiz

Oysa biz onun içindeyiz

Sızım

Dalgasız deniz 

Tepkisizlik içinde kaçan

Yakın durduğun kara

Şekilsiz karanlık

Gözümün içine diktiğin

Farkındasın

Başka bir şey bu

Yanarken 

Rüzgara karşı koşmalar

| Düştüm kurtar |

Küçük tepelerde oyalama ellerini

Karlı şeyler aç

Yüksek yeşil yerler

Sıcak içim

Birazdan düşeceğim

| Kaşlarına sürdüm ellerini |

Tuhaf koşu

Hep yabancısın aşka

| Yanağına sürdüm yanağımı |

İç kıpırdıyor

İçindeyiz sırrın

| Köşe kenar dudakların |

Kan süzülüyor bak

Bir olmak adın

Ne bekler ki başka

| Kapat gözlerini |

Burdayız

yanlızız

Sus

Her uykuda rüya gereksiz

Buradayız

Yalnızız

25 Temmuz 2004', 'Taşıdığın yükün eğrisi Elim kazalara benzerken Yüreğim masum ölümler görüyor Gülerken uğurladığımızdı Kendimiz sakladığımız gölge Sen alışkı...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/buradayiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamöyküsü', 'yasamoykusu-nilay-aksu-r1k8t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ben şimdi 

göğünü kendi seçen 

uçarı bir uçurtmayım mesela 

kökü kucağında çelebi ağaç 

deli bi’ yelkenliyim 

gecenin bir vakti demir alıp giden 

şimdi ben, haylaz bir otobüsüm 

göğsündeki tabelaya aldırmadan 

dağ yollarına dalan 

senden önce 

‘ne yaşadıysam yaşamış, unutmuşum’ 

vurup sırtıma geliyorum: 

acı sancı gözyaşı 

yani ortalama bir yaşam özetinde ne varsa 

bir avuç ellenmemiş düş var eteğimde 

tartaklanmış ömrümün kalanı bir de', 'ben şimdi  göğünü kendi seçen  uçarı bir uçurtmayım mesela  kökü kucağında çelebi ağaç  deli bi’ yelkenliyim  gecenin bir vakti demir alıp g...', ARRAY['Türk Edebiyatı','Şiir','Nilay Aksu']::text[], 8.5, '{"poet":"Nilay Aksu","poet_slug":"nilay-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yasamoykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakıp Gİtmek Hayatı', 'birakip-gi-tmek-hayati-esin-ege-q8k1c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yinede zor olanı yapmak erdemli 

Bırakıp gitmek değil hayatı

Saplandığın bataktan çıkmak mesele

Yada çıkmaz denilen sokaklardan yol bulup dönmek

Sevdiğin için acı çekiyorsan

Ve sevdiğin için yapayalnızsan

Değmez büyük günahların bedellerine

Hep böyle kalmaksa alnına yazılan

Ve payına düşen kadar mutluluksa

Sebep sorma

Ne yazdıysa güzel yazmıştır yaradan

Yazılanı görür ancak yaşarken insan

1998', 'Yinede zor olanı yapmak erdemli  Bırakıp gitmek değil hayatı Saplandığın bataktan çıkmak mesele Yada çıkmaz denilen sokaklardan yol bulup dö...', ARRAY['Türk Edebiyatı','Şiir','Esin Ege']::text[], 8.5, '{"poet":"Esin Ege","poet_slug":"esin-ege","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/birakip-gitmek-hayati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlardan Çağıldayan Sulara Kulak Ver', 'daglardan-cagildayan-sulara-kulak-ver-halil-manap-t24pw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '..................................................................12 eylül döneminde henüz 

...................................................................18 yaşını doldurmamış 

....................................................................idam edilen genç

....................................................................''Erdal Eren''in anısına''

Kemendi boğazına geçirmeye 

...........................................gelince cellat

Gözlerin gülümseyecek

Işıyıp 

........sulara 

..................yansıyan yıldızlar

.....................................Özgürce 

..........................................yan-ma-ya-cak

Ve güvercinler 

.................kanatlarında barışı taşımayacak

Ama senin özlemin bitmeyecek 

.............................................çocuklara

Baharla sevişen çiçeklere

Ve başı dik onurun 

...........................sevdana

Delikanlı 

..........öyleyse 

Dağlardan çağıldayan 

.........................sulara kulak ver

Bak nasılda sunuyor özgürlüğü

Uğruna ölümlere soyunduğun güller

Belki yüreğinde yeşertiğin sevdanla 

.............................................se-viş-me-ye-cek-sin

Belki yüzün bir daha 

.....................gülümsemeyecek

Ama izin verme

Yüreğinden kopan çiğlığınla

Kanlı 

........kirli 

.............elleriyle

İpi boğazına geçirmesinler

Haykır 

.............bir şarkı

Ve 

..........t-e-k-m-e-l-e     s-eh-pa-la-r-ı-n-ı

.............................................................zülmün

Gözleri dona kalsın kurt sürülerinin 

Ardında bıraktığın 

...........................bir bayrak olacak ölümün

Okyanuslarda köpüren dalgalara

Karlı dağ zirvelerinde 

..............................çığlaşan şarkılara

Ve dalga dalga çoğalan milyonlara 

Bir selam v-e-r çeliği eri-ten iradenle

Bin selam ver vatanına halkına

...................

...................Ey halkım tarih okumak zamanıdır

...................Ey halkım anadoluyu tanımak zamanıdır

...................Ey halkım anadolu mozayiğinde güzelleşmek zamanıdır

...................', '..................................................................12 eylül döneminde henüz  ...................................................', ARRAY['Türk Edebiyatı','Şiir','Halil Manap']::text[], 8.5, '{"poet":"Halil Manap","poet_slug":"halil-manap","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/daglardan-cagildayan-sulara-kulak-ver-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avuçlarında Kesildi Nefesim', 'avuclarinda-kesildi-nefesim-mehmet-kizilay-rgr38', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'nefesleri güneş kokan

yangından bir tutam ateş alacaklı

bozkır tenli çocukların

avuçlarında kesildi nefesim.

Gözlerimin görebildiği küçücük nasırlardı.

Onlara ağıt yakacak değildim ya..

acısı geçmiş 

bir süre sonra da kendisi iyileşecekti.

Hem iyileşmeye ne hacet

nasılsa yenileri yetişecekti.

Asıl görmediklerim:

doygun gözlerin göremeyeceği,

çılgın sağanaklar yaşamamış gözlerin

bakışlarına tevessül etmeyen

bu güngörmüş bakışların sahipleri olan

çocukların

avuçlarında kopan fırtınadan

batan gemilerin acizliğini

nasıl bilebilirdim ki..

Boğulacağım..! ! ! ! ! ! ! ! 

Elimden tutacak

Çocuk arıyorrum', 'nefesleri güneş kokan yangından bir tutam ateş alacaklı bozkır tenli çocukların avuçlarında kesildi nefesim. Gözlerimin görebildiği küçücük ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kızılay']::text[], 8.5, '{"poet":"Mehmet Kızılay","poet_slug":"mehmet-kizilay","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/avuclarinda-kesildi-nefesim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sal', 'sal-ahmet-aksoy-i2rgc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kılık değiştiren yalnızlık

yürüyor kainin kalbine doğru

yankılanırken sesteş çığlıklar

kaos gökyüzünden düşen yıldırım

eşitlik hengamesinde ayrılmış ruhlar

insanın içinde büyüyen sarmaşık

sustalanmış düşkünler düşgeninde

karanlıkta belirsiz ışık

herkes tekdir! yaradılış! 

gecenin ucunda uyurken ulur ölüm', 'kılık değiştiren yalnızlık yürüyor kainin kalbine doğru yankılanırken sesteş çığlıklar kaos gökyüzünden düşen yıldırım eşitlik hengamesinde ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sal-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğmamış', 'dogmamis-zafer-zengin-etnika-stagj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mesela ben

Aristoya sövüverdim

Yüzyıllarca

Çok sonra söyledim

Sağır kalınca

Bilmiyorum ki; 

Çok şey biliyorsun

Benim gibi hissetmiyorsun

Acı şey

Acısını hissetmek

Ölmek demek

Biliyorum

Acımı seviyorum

Hayat biz/siz

Erken ölecek

Seziyorum

Acı silip süpürecek

Püsküllü doğanın altına

| Hoş kokuyor toprak |

Kaç can geçti içinden

Ben aristoya sövmeden

Gözleri güzel

Hiç dokunulmamış

Çok ağlamış

Ben aristoya söverken

Daha doğmamış

30 Temmuz 2004', 'Mesela ben Aristoya sövüverdim Yüzyıllarca Çok sonra söyledim Sağır kalınca Bilmiyorum ki;  Çok şey biliyorsun Benim gibi hissetmiyorsun Acı...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/dogmamis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gevşemek ölüm bize', 'gevsemek-olum-bize-zafer-zengin-etnika-bmpa9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gevşedik elbet

Ağrılar varmış mapusta

Çözüm hazır zulumda

Ağrı kesici

Kas gevşetici

Mermi yerine geçermi ki

Geçer elbet

Gevşemiş yüreği

Küçükmüş düşleri

Bilmem çocuk

İmdat diyen parmak gördün mü

Gevşeriz elbet ölünce

Gözü doymaz bunlar

Bir bir ölüp gideriz gençce

Gevşemek ölüm bize

| Artar ağrılarımız |

Ağrı kesiciler*

Kas gevşeticiler**

Kramplar

Ve açlıklar

Sökerken içimizi

Biz kas geveşetiriz

Sonra ölü veririz

Bir bir 

Hepsi biziz

Üç kurşun olur

Üç ilaç

Ancak öyle gideriz

Biz ölürken çocuk

Hep genciz

*Acılar dinsin diye verilir. [doktor kontrolünde]

**Kaslar gevşesin diye [ doktor kontrolünde ] verilir

Günlük gazetenin birinde [ cumhuriyet 31 temmuz]..bir mahkuma verilen ilaçları yazmışlar

Ağrı kesici ve kas gevşetici [ 3 adet bir defada ] Malum kalp kas''tan oluşur

Fazla gevşerse ne olur.. biz kaza diye duyduk..bilenler neder acaba..dilim varmıyor

Hipokratta duymuyor..Hem açlık hem böylesi tedavi..iyice insanlıktan cıktık..neler oluyor bize...

1 Ağustos 2004', 'Gevşedik elbet Ağrılar varmış mapusta Çözüm hazır zulumda Ağrı kesici Kas gevşetici Mermi yerine geçermi ki Geçer elbet Gevşemiş yüreği Küçü...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gevsemek-olum-bize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Değilmisin İstanbul', 'sen-degilmisin-i-stanbul-hasan-can-93241', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İstanbul getirdi seni bana

İstanbul sevdirdi seni deliler gibi...

İstanbul`dan ayrılamıyorum

İstanbul`du seni bana bağlayan

İstanbul çaldı yüreğimi sana getirdi

Sen İstanbul`dasın hala biliyorum

Beni sana gösteriyor seni saklıyor

            Neden İstanbul, sen değilmisin 

            Sen değilmisin beni bu çıkmaza sokan

   İstanbul ver onu bana 

Saklama benden biliyorsun seviyorum onu

İstanbul haykırıyorum sana biliyorum duyuyorsun

Cevap ver çığlıklarıma acılarıma

Tamam İstanbul gidiyorum...

Seni sevmiştim gerçekten 

Her ne kadar acı verici de olsa 

Onu sende bırakıyorum

Tüm yalnızlığımla gidiyorum

Tek birşey bırakıyorum İstanbul sende

Aşk duygusunu....

Umarım sende bu çıkmaza girersin 

Bu duygu sende ne bırakır bilmiyorum

Adı aşk bilemezsin...

İstanbul acılar seninle olsun 

Acılar bağrın da kavrulsun...

İstanbul eyvallah...gidiyorum.', 'İstanbul getirdi seni bana İstanbul sevdirdi seni deliler gibi... İstanbul`dan ayrılamıyorum İstanbul`du seni bana bağlayan İstanbul çaldı y...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sen-degilmisin-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tek Sen', 'bir-tek-sen-mine-gul-r5ama', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir tek sen vardın,

Yalnız sen...

Gecemde,

Yıldızlarımda,

Ve sığındığım karanlığımda.

Sen vardın....

Hayallerimde,

Yalnızlığımda,

Ve üşüten sessizliğimde,

Bir tek sen...

(31 Temmuz 2004)', 'Bir tek sen vardın, Yalnız sen... Gecemde, Yıldızlarımda, Ve sığındığım karanlığımda. Sen vardın.... Hayallerimde, Yalnızlığımda, Ve üşüten ...', ARRAY['Türk Edebiyatı','Şiir','Mine Gül']::text[], 8.5, '{"poet":"Mine Gül","poet_slug":"mine-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bir-tek-sen-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-yasam-arzusu-shpcr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İşte o gün sen bile insan oglunu tanımamış oldugunu anlayacak ve sen onlara yaklaşmakta zorluk cekecek kıskanacaksın onların yasam arzularını görecek ve tekrar cıkıp yoluna devam edeceksin ama unutma ki ben senden korkmuyor degilim ama bunu sana belli edecek kadar pasif ve korkak degilim. işte o gün seni tüm hayatım boyunca yasanmıs ve yasanacak asklarıma,kurulmuş ve kuulacak dostluklarım, ve eldegmemiş güzel güllere inat o gün seni inadına şiir okuyarak karsılayacagım   Hos geldin 

                                                                 HOSGELDİN

                                                                     ÖLÜM', 'İşte o gün sen bile insan oglunu tanımamış oldugunu anlayacak ve sen onlara yaklaşmakta zorluk cekecek kıskanacaksın onların yasam arzuların...', ARRAY['Türk Edebiyatı','Şiir','Yasam Arzusu']::text[], 8.5, '{"poet":"Yasam Arzusu","poet_slug":"yasam-arzusu","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/olum-133-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdan Içimde Bir Sürgün', 'sevdan-icimde-bir-surgun-karahan-yilmaz-yjgr7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşlerime kelepçe vurdular

Bana ayrılığın rengini sordular

Susmasın gözlerinde hasretim

Gülüşün şimdi bende bir firar

Islanır gözlerimde hüznün

Cıkmaz aklımdan o yüzün

Bu kaçıncı ayrılık böyle yar

Sevdan içimde bir sürgün.

Gün batımlarında her akşam

Gözlerinde bir mülteci olsam

Yağmurun olur yağardım yar

Tepende bir bulutun olsam.

Sicilime sakıncalı yazmışlar

Meslek hanemi boş bırakmışlar

Aşka yasak söker mi ay yüzlüm

Şiirlerimde seni aramışlar..

26 temmuz 2004 – Metz', 'Düşlerime kelepçe vurdular Bana ayrılığın rengini sordular Susmasın gözlerinde hasretim Gülüşün şimdi bende bir firar Islanır gözlerimde hüz...', ARRAY['Türk Edebiyatı','Şiir','Karahan Yılmaz']::text[], 8.5, '{"poet":"Karahan Yılmaz","poet_slug":"karahan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevdan-icimde-bir-surgun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Güzeli', 'en-guzeli-hasan-can-nyady', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'En güzel aşk yalnızlıktır ve en kutsal sevgi uzaktan sevmektir

yaşamadan, öğrenmeden, acı çekmeden, kaçmadan, ayrılık korkusu olmadan.', 'En güzel aşk yalnızlıktır ve en kutsal sevgi uzaktan sevmektir yaşamadan, öğrenmeden, acı çekmeden, kaçmadan, ayrılık korkusu olmadan....', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/en-guzeli-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalleri Bende Kaldı', 'hayalleri-bende-kaldi-karahan-yilmaz-gk0n1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu şehirde her akşam

Hüzünlü bir ayışığı olsam

Aşkı ararken gözlerinde

Gülüşüne teslim olsam

Iki odalı bir evde

Ne gündüz dedik,ne gece

Esip durdu bir rüzgar

Kelimeler yetmedi bize

Duruşu aşkıma limandı

Gülüşü beni benden aldı

Cekip gitti bir sabah

Hayalleri bende kaldı

Dün gece onu aradım

Sesine dayanamadım

Günler su gibi aksada

Ben onda rehin kaldım

31 temmuz 2004 - Metz', 'Bu şehirde her akşam Hüzünlü bir ayışığı olsam Aşkı ararken gözlerinde Gülüşüne teslim olsam Iki odalı bir evde Ne gündüz dedik,ne gece Esip...', ARRAY['Türk Edebiyatı','Şiir','Karahan Yılmaz']::text[], 8.5, '{"poet":"Karahan Yılmaz","poet_slug":"karahan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hayalleri-bende-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çöl Kasidesi', 'col-kasidesi-adnan-durmaz-qszff', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çöl 

Bedevi özgürlük 

Göğü tefekkürün açık risalesi 

Yeşilini- mavisini- denizini 

Ve gök kuşağını gül bahçesini 

Yüreğinde taşıyabilenlerin şiir ülkesi 

Çöl... 

Gâhi Hasan Sabbah''ın cennetinden 

Haşhaşı bir keyif tutu boşluğa 

Gâhi Alamut Kale'' si 

Dahi Babil'' in Asma Bahçeleri 

Yıkıldı tanrının gözleri önünde 

Ve Hayyam rubailer bıraktı 

Gözleri yıldızlarda 

Sözleri rûzigârda 

Ve cümle günahtan aşikâr olanların beldesi 

Çöl... 

Mevsimler ki ömrün geçen demleri 

Aruzun düz kalıbında eser rüzgâr 

Hurmaları elif elif sallanır 

Kum solur kervanlar 

Develer şedde şedde aşar zamanı 

Me fa i lün- me fa i lün başlar aşkları 

Ağlar müs te''fi la tün''den 

Güzellik serabı kasideler 

Gazeller hüzün tarlası 

Mesneviler göl göl 

Yârin kusuruna tecahül-i ârif 

Yarin nazına hüsn-i tâlil 

Çöl... 

Ya İmrül Kays 

''Şeytanın cehennem yolundaki 

Yardakçısı'' dediler sana 

Dediler 

''Şiirleri müselman 

Kendisi kâfir'' 

Selam olsun ruhuna 

Yüzyıllardır koşan şarkı 

(Çöle gezmeğe giden kızların 

Ardından gizlice iz süren 

Ve onlara devesini kesip yediren 

Bebesini emziren kadının 

Diğer memesine yanaşan deli)

Ölüme yapılmış arabî şaka 

Selam sana ya İmrül Kays 

Halâ asılı gökyüzünde Muallâka 

Çöl hâlâ duruyor yerli yerinde 

İnsanı kum gibi savrularak 

Yağmalana yağmalana 

Kan göletleri bırakıp 

Nice cellatlar geçti 

Ve aşk meşk içinde inat 

Sen geçtin 

Ya İmrul Kays 

Ora nere- bura nere 

Deli ruhunu sokacak 

Başka beden kalmadı mı 

Neden beni seçtin? 

Adnan DURMAZ 

Mart 95-İzmir 

yarın yeniden,gerçek sanat yay,ist', 'Çöl  Bedevi özgürlük  Göğü tefekkürün açık risalesi  Yeşilini- mavisini- denizini  Ve gök kuşağını gül bahçesini  Yüreğinde taşıyabilenlerin...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/col-kasidesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakikatli Aşklara Gazel', 'hakikatli-asklara-gazel-adnan-durmaz-1mr98', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşıklar meclisinde bize külhan dediler 

Sordum aşkın anlamı- pinhan pinhan dediler 

Bazan sevdan kavgadır- bazan da kavgan sevda 

Her savaşçı aşıktır- her aşk militan dediler 

Dedim- her güzelde başka bir güzellik bulur gönlüm 

Gönül arı değildir-utan be utan dediler 

Zulümler besler aşkı- çoğaltır engebeler 

İnsanın vatanı insan- aşkınsa cihan dediler 

Bu zamanda aşk büyütmek amansızdır çetindir 

Ölümün kapı komşusu- hicran hicran dediler 

Mem û zin- ferhat şirin- nazım -ritsos- aragon 

Ki niceleri geçti aşka sultan dediler 

Sordum acı çığlığımı duyacak kimse yok mu 

Hakikâtli aşıkların meskeni zindan dediler 

Adnan DURMAZ 

 

yarın yeniden,gerçek sanat yay,ist', 'Aşıklar meclisinde bize külhan dediler  Sordum aşkın anlamı- pinhan pinhan dediler  Bazan sevdan kavgadır- bazan da kavgan sevda  Her savaşç...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hakikatli-asklara-gazel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günler ki Savrulan Yapraklardır', 'gunler-ki-savrulan-yapraklardir-adnan-durmaz-yx8k7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Günler ki savrulan yapraklardır ömrümüzün dalında 

Geceye söylenmiş bir şiirdir aşkımız 

ki tam alnından vurulan.. 

O her gidişinden geriye kırılmış gül tenhalığı 

Ayrılığın da bir kokusu var 

gözbebeklerinden yayılan... 

Deniz fenerlerim yıkılmış 

Yerle bir olmuş nem varsa 

kalelerim-ağaçlarım-düşlerim 

Hunharca yağmalanmış aşklar bıraktım ardımda 

Hasretin de bir rengi var 

nasıl desem 

Hiç bir renkle tanımlanamayan... 

Bir ömrü koymak bilirdim 

Sevgilere bedel diye 

Ne namusperestler gördüm 

Bakışları fuhuş fuhuş 

Yüreğinin kâsesinde kendini pazarlayan 

Gülleri ve maviliği 

Bir yosmayla keşfet 

Yüreğin basıyorsa 

Deli bir serüvencidir aşk 

Hiç bir kural tanımayan... 

Oysa tahkatsızım gidişinle 

Karanlığın dehşet bastı 

Yüreğim yenik 

Hangi bahar gül açtırır 

Bu deli yalnızlığında 

Ne tuhaf bir şarkıymış aşkın 

Yarısı gül gülistan 

Ayrıldıktan sonrası sancıyan... 

Günler ki savrulan yapraklardır 

Ömrümüzün dalından 

Geceye söylenmiş bir şiirdir aşkımız 

ki tam alnından vurulan... 

Adnan Durmaz

 yarın yeniden,gerçek sanat yay,ist', 'Günler ki savrulan yapraklardır ömrümüzün dalında  Geceye söylenmiş bir şiirdir aşkımız  ki tam alnından vurulan..  O her gidişinden geriye ...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gunler-ki-savrulan-yapraklardir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Güneşli Günler', 'son-gunesli-gunler-baykal-kaanalp-2hhcz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Son güneşli günler

Bıçak kesti kesti bitiremedi

Bir tek damarım kaldı

Bana ait

Onu da gönüllü vermeyeceğim

Gelmesini istemediğim kış

Kapımı çaldı

Ne kadar kapalı tutabilirim bilmem

Belki de bir daha hiç dışarı çıkmam

Kapılar bana bakıyor

Duvarlar saatime

Bir çalsa da kurtulsak diyorlar

Şu geçimsiz ihtiyardan

Boşuna beklemeyin baykuşlar

Guguk kuşunu denize attım

Saatin gongu yok artık

Boşuna beklemeyin kargalar

Size yok

Bir damla kanlı et

Boşuna beklemeyin

Tarla fareleri

Kar yağmayacak

Boşuna beklemeyin

Yarasalar

Güneş hiç batmayacak', 'Son güneşli günler Bıçak kesti kesti bitiremedi Bir tek damarım kaldı Bana ait Onu da gönüllü vermeyeceğim Gelmesini istemediğim kış Kapımı ...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/son-gunesli-gunler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Kaldı?', 'ne-kaldi-baykal-kaanalp-8w2be', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gözlerimde iki damla yaş

taş bastım bağrıma taş

ayrılıyoruz artık ikimiz

üzüntüden ne göz kaldı,ne de kaş', 'gözlerimde iki damla yaş taş bastım bağrıma taş ayrılıyoruz artık ikimiz üzüntüden ne göz kaldı,ne de kaş...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ne-kaldi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
