INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Anladı Ki Senelerce Aynı Yaşta Kaldığımı,Zaten...', 'kim-anladi-ki-senelerce-ayni-yasta-kaldigimi-zaten-tugba-gurelli-wi269', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ruhlarınızı emzirmeye geliyorum,

İçinizin göletlerini geçmeye...

İçimin güvercin boşluklarına yara bandı yapıştırıp geliyorum,

Ellerimin ağlayan sesleriyle...

Saman rengi acılarınızı öpmeye geliyorum

Öpülmüş gözlerimin sessiz çığlıklarıyla...

Kanayan dizlerimi gölgeleyerek geliyorum,

Bıçaksırtı anılarınızı ayrıştırmaya...

Kimse kollarını açmıyor

Ama ben geliyorum,size

İçimin yazlık sinemalarıyla...', 'Ruhlarınızı emzirmeye geliyorum, İçinizin göletlerini geçmeye... İçimin güvercin boşluklarına yara bandı yapıştırıp geliyorum, Ellerimin ağl...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Gürelli']::text[], 8.5, '{"poet":"Tuğba Gürelli","poet_slug":"tugba-gurelli","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kim-anladi-ki-senelerce-ayni-yasta-kaldigimi-zaten-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendime saklandım...', 'kendime-saklandim-emirhan-bala-l6nm5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'içime sakladım kendimi, 

fırtınalarımı, 

papatyalarımı, 

azaplarımı, 

satırlarımı, 

tıkadım anahtar deliğini bile, 

unuttum adını sanını, 

şeklini şemalini 

hafıza haritamdan sildim 

yinede sakladım içime kendimi 

biri buluncaya dek...', 'içime sakladım kendimi,  fırtınalarımı,  papatyalarımı,  azaplarımı,  satırlarımı,  tıkadım anahtar deliğini bile,  unuttum adını sanını,  ş...', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kendime-saklandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Nefeste Yeni Baştan', 'her-nefeste-yeni-bastan-batuhan-batu-fugto', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen; dermanım olan kadın! 

Hadi Gel! 

Dudaklarımda dudaklarının tadı var. 

Dilim damağım kurumakta, 

Bekleme,Aşk saatim geçiyor.

Doldur kırmızıyı yavaş yavaş, 

Her yudumda yeni bir arzu.

Sevaba değil günaha varsın sonu.

Düşürme kadehi ürkmesin gece. 

Önce izleri çıksın dudaklarımıza, 

Sonra öpüşelim yıldızlar duranadek. 

Gezinelim vücud atlasımızda; 

Keşfedelim en ücra yerleri.

Demir atalım dipsiz kuyulara.

Ayrı gayrı olmaz birleşsin heryer....

Al içine kaybet neyim varsa! 

Kanter içinde kalsın gece, 

Doruklara vursun şehvet ibresi, 

inandır beni dişiliğine...

Yorulmak yok; her nefeste yeni baştan

Taki güneş bizi görenedek. 

.....

Sabahı koynunda gördüğüm yabancı 

Gözlerime değil,semaya bak! 

Kayan yıldızlar var.....', 'Sen; dermanım olan kadın!  Hadi Gel!  Dudaklarımda dudaklarının tadı var.  Dilim damağım kurumakta,  Bekleme,Aşk saatim geçiyor. Doldur kırm...', ARRAY['Türk Edebiyatı','Şiir','Batuhan Batu']::text[], 8.5, '{"poet":"Batuhan Batu","poet_slug":"batuhan-batu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/her-nefeste-yeni-bastan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm... Nuray Alper''e...', 'gulum-nuray-alper-e-tulay-sustam-drmmk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senden daha güzeli hiç yok en güzeli sensin

Sen değeri biçilmez, en nadide bir çiçeksin

Sana bakmasam solarım, beni mutlu edersin

Çiçeğimsin benim______________gülüm

Herkes gibi bir senin güzelliğine aşığım

Sevgi seninle söylenir, ben seni anlatırım

Ömrümü ömrüne katarım, öyle yol alırım

Aşkımsın sen benim____________gülüm

Dikenlerin batmasın sana getir benim olsun

Al beyaz yapraklarımın hepsini senin olsun

Biz aşk için çiçek olmuşuz, sen en iyi dostsun

Dosttumsun sen benim____________gülüm

Bütün gönül bahçelerinde sen ve ben yanyana

Nazlı çiçeğim benim hergün dert yanarım sana

Söyle senden başka kim anlar bu deliyi cana

Mutluluğum benim________________gülüm

Uykusuzum, yorgunum, çaresizim, dinmez sızım

Ey benim en güzel renkteki çiçeğim, kırmızım

Hadi bir tek kelime söyle, sensiz çok yalnızım

Dermanımsın benim_______________gülüm

(Papatya; Gül olmadan yaşayamaz...)', 'Senden daha güzeli hiç yok en güzeli sensin Sen değeri biçilmez, en nadide bir çiçeksin Sana bakmasam solarım, beni mutlu edersin Çiçeğimsin...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gulum-nuray-alper-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Ben', 'sen-ve-ben-yuksel-kasim-gzyse', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen gülersin de

Ben kanmaz mıyım

Sen geçersin de

Ben kalmaz mıyım

Senin saçların var gece gibi

Sen onları savurursun da

Ben savrulmaz mıyım.

Sen yürürsün de

Ben gitmez miyim

Sen basarsın

Ben ezilmez miyim

Sen üzülürsün

Ben ağlamaz mıyım

Sen olmaz dersin de

Ben boyun eğmez miyim

Senin gözlerin var namlu gibi

Sen vurursun onlarla beni

Ben ölmez miyim.

6 Mart 2003

Arga', 'Sen gülersin de Ben kanmaz mıyım Sen geçersin de Ben kalmaz mıyım Senin saçların var gece gibi Sen onları savurursun da Ben savrulmaz mıyım....', ARRAY['Türk Edebiyatı','Şiir','Yüksel Kasım']::text[], 8.5, '{"poet":"Yüksel Kasım","poet_slug":"yuksel-kasim","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-ve-ben-79-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben biraz daha ağlıyacağım', 'ben-biraz-daha-agliyacagim-omer-dilsoz-ddiz4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'anlıyor musun? ....... 

ben biraz daha ağlıyacağım..... 

lülfen...! 

lülfen gözlerini çek oradan... 

geçme karşıma... gülme... gülümseme... 

seni görmemeliyim.... 

bırak beni... 

ben acınacak durumda değilim ki.... 

hayır... sevgi dilemiyorum kimseden... 

hele senden...asla! 

-neyse- 

bak güneş yine karanlığa bırakıyor bu şehri... 

ben karanlıkları çok severim aslında... 

hele bu şehrin karanlık geceleri... 

bir başka olur inan...hele sensizken... 

aslında ben seni hayallerde daha seviyorum... 

çünkü orada hiç yoktur kaybetme ihtimali... 

sen hep benimsin... 

yalnızca benim... 

-ama- 

oysa gerçekte...hiç benim olmadın... 

bir kez bile öpmedim seni... tutmadım ellerini... 

ve hiç söyleyemedim sana ''o beni içten yakan... 

sarsan... o en ürktüğüm...ama en sevdiğim kelimeyi'' 

anlamadın mı? 

-seni ne kakar sevdiğimi- yani ''çılgınca seviyorum seni'' 

-neyse- 

biraz daha ağlamak istiyorum.... 

ben ağlarken her şeyi unutuyorum... 

içimdeki o birikmiş 

''o kimseye açamadığım dertlerim'' sanki biraz hafifliyor... 

ağlayınca ben... seni nasıl sevdiğimin günahını.... 

sana nasıl tutulduğumun sızısı yüreğime iner sanki... 

senden kaçmak...

senden kaçıp yalnızca hayallerime gömülmek istiyorum... 

çünkü olmuyor... dayanamıyorum... hep uzaklardan.. 

başkasıyla kolkola gezerken... 

başkasıyla yaşadığın maceralarını dinlerken... 

içime bir öfke... 

bir acı iner.... 

-çünkü bir çocuk kadar saf sevdim seni- 

Lülfen... 

Allah aşkına yaklaşma bana... 

ben yalnız kalmak istiyorum 

ve biraz daha ağlamak... 

çünkü ben hep ''ihtimallerle'' hep belkilerle seni hatırlamaktan... 

senin hayallerini kurmaktan yorgun düştüm artık... 

-bırak beni ya- 

bırak da biraz daha ağlayayım.... 

çünkü ağlayınca ben kendime geliyorum... 

seviyorum... 

senden uzaklaşıyorum... 

kendimden geçiyorum çünkü... 

bırak beni... 

-ben biraz daha ağlayacağım-', 'anlıyor musun? .......  ben biraz daha ağlıyacağım.....  lülfen...!  lülfen gözlerini çek oradan...  geçme karşıma... gülme... gülümseme... ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dilsöz']::text[], 8.5, '{"poet":"Ömer Dilsöz","poet_slug":"omer-dilsoz","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/ben-biraz-daha-agliyacagim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka ve Sevgiye Dair', 'aska-ve-sevgiye-dair-yuksel-kasim-gmc29', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşk ikidir sevgi bir; 

Aşk yalan,sevgi gerçektir.

Aşk sudur,sevgi susuzluk.

Bu yüzden sevgi hasrettir,

Özlemektir,beklemektir.

Asıl maharet:

Susuzken suyu içmek değil

Karşısına geçip seyretmektir.

Aşk haykırmaktır,sevgi ağlamak; 

Aşk açmaktır,sevgi katlamak.

Sevgi saklamaktır

Yüreğini,gözlerini

Ve de ellerini saklamak

Bahar geldiğinde…

Bir çiçeğe,yeşile,çimene

Aşık olamazsın ama seversin.

Arkadaşına aşık olamazsın

Ama seversin.

Toprağa fidanı aşkla değil

Sevgiyle dikersin.

Sevgi için ölünür,aşk öldürür.

Aşk kıskançtır,nankördür

Sevgiyi öldürür.

Aşk Kabil’dir,sevgi Habil.

Aşkla sevgi aslında kardeştir

Babaları insandır,Adem’dir

Aşk için şiirler yazarsın,

Şarkılar yaparsın; 

Sevgiyi anlatamazsın.

Çünkü yüreğine sığdıramazsın.

Kalbini aşka kapatabilirsin

Ama sevgiye kapatamazsın

Sevgi gizli,aşk aşikardır.

Yüz vermeyince unutursun

Sen aşığım diye daha kendini kandır.

Dedim ya sevgi gerçek,aşk yalandır.

Dahası da var:

Aşkın gözü kördür,

Fazla naz aşık usandırır; 

Aşk oyun,aşık oyuncaktır.

Sevgi ise yaşamdır,hakikattir.

Aşk aceledir,

Sevgi usul usul sabırlıdır.

Acele işe hem şeytan karışır.

Aşk ateşlidir

Çünkü hastalıklıdır.

Sevgi ılıktır

Çünkü sağlıklıdır.

Velhasıl bu iki kardeşin hikayesidir

Aşka ve sevgiye dair…

26 Ocak 2002

Aydın', 'Aşk ikidir sevgi bir;  Aşk yalan,sevgi gerçektir. Aşk sudur,sevgi susuzluk. Bu yüzden sevgi hasrettir, Özlemektir,beklemektir. Asıl maharet:...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Kasım']::text[], 8.5, '{"poet":"Yüksel Kasım","poet_slug":"yuksel-kasim","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/aska-ve-sevgiye-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilistan', 'dilistan-omer-dilsoz-axxpb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Heke dil, dil bûya; 

Dilê wêran bê rik û bê kul bûya 

Minê dil bikira warê jiyanê 

Gulistana hemû rengên gulan lê 

Heke dil, dil bûya; 

Wekî dilopek ji barana havînî bûya 

Minê dil bikira qesra evînê 

Li wê dîwana reqs û semah tê. 

Heke dil, dil bûya; 

Dil bi ray û tevbîr bûya 

Minê dil bikira hêlîna evînan 

Li cîhaneke hemî azadî lê. 

2003 /Duhok', 'Heke dil, dil bûya;  Dilê wêran bê rik û bê kul bûya  Minê dil bikira warê jiyanê  Gulistana hemû rengên gulan lê  Heke dil, dil bûya;  Wekî...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dilsöz']::text[], 8.5, '{"poet":"Ömer Dilsöz","poet_slug":"omer-dilsoz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dilistan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiçbir Sebep Yokken', 'hicbir-sebep-yokken-efe-gursoy-1r9l4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalemim yazmak istemiyor, bir sebepten,

Daha doğrusu, sen varken, hiçbir sebep yokken,

Sözlerini, güzel sürme gözlerini,

Yazmak istemiyor bu gece, nedendir bilmem...', 'Kalemim yazmak istemiyor, bir sebepten, Daha doğrusu, sen varken, hiçbir sebep yokken, Sözlerini, güzel sürme gözlerini, Yazmak istemiyor bu...', ARRAY['Türk Edebiyatı','Şiir','Efe Gürsoy']::text[], 8.5, '{"poet":"Efe Gürsoy","poet_slug":"efe-gursoy","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hicbir-sebep-yokken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorunum Var! .. (Düz Yazı)', 'sorunum-var-duz-yazi-naime-erlacin-3jskv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Benim bir derdim var. Bir değil, çok aslında... 

Hangi birinden başlasam? İlk olarak içimi susturmalıyım. Öylesi bet bir sesle konuşuyor ki bu “iç”, eleştirmene falan hacet yok. Kimseleri beğenmez ukala. En başta da beni. Anlayacağınız akut safhada paranoik-şizofrenik, zaman zaman da obsessive-megalomanik bir vaka. Aklı sıra bende panik ataklar yaratacak ama beceremedikçe hırslanıyor. Yarım asırdır bu sesi dinlemekten bıktım, usandım artık. Üstelik 50 -0 da galibim. O ne kadar çok konuşursa, ben iki misli konuşuyorum anlayacağınız. Ama yoruluyorum. Karar verdim; bugünden tezi yok idam hükmünü imzalayacağım. İlk söz olarak söyleyeyim ki kayıtlara geçsin; belgelensin ve böylece temelli rahatlayayım dedim hani… 

Şimdi bu vatandaşın iç sesinden size ne, değil mi? Oysa benim için çok şey demek. Günümüze kadar beni oyalayan oydu. Maçı kazandığım halde, sahanın dışına çıkamıyordum bir türlü. Bu nedenle fermanını mühürlüyorum bugün. O gidiyor ve ben bütün hayallerim, kavgalarım, düşünce ve duygularımla birlikte geliyorum… 

Merhaba dostlar!

Gelelim ikinci sorunuma. Daha önce de yazdım ve dillendirdim. Kimsenin umurunda olmadı. Ben bu teknoloji işine akıl sır erdiremiyorum. İşe yaramaz bir dolu ıvır-zıvır icat etme peşinde harcanan bütçelerle arzu etseler Mars’ta koloniler; Ay’da, haydi haydi yazlık siteler kurarlardı. Oysa alt tarafı bir “düşünce teybi” istemiştim onlardan. Yani haksız mıyım şimdi? Ayakta çalışmak zorunda olan insana sırt masajı yapan alete kafa yoracak ve bunun da altından kalkamayacaksın. Zira yüklediğin onca kiloluk donanımla adamı rahatlatmak yerine bel fıtığına mahkum edeceksin. Sonra da benim düşüncelerim uzay boşluğunda hovardaca akıp giderken, kalem ve klavyeyi saf dışı bırakacak; onları düşünme hızında kaydedecek bir düşünce teybi icat edemeyeceksin. Var mı böyle bir şey? O araştırma bütçelerini karşılamak için her birimizin kanı emiliyor. Kendi adıma ben günde dört paket sigara içerek neredeyse kırk yıldır dolaylı vergi ödeme dilimlerindeki yüksek ve onurlu (!)   yerimi muhafaza etmeyi ısrarla sürdürüyorum. Aynı zamanda sigaradan vazgeçirme fonları üretiyorum. İçiriyorsun ey sitem! Gençliğimde az reklamını yapmamıştın hani. Sonuçta içiyorum işte ve ödüyorum. Vazgeçirdiğin kurbanlar ise başka bağımlılıkların kucağına düşüyorlar. Bir de onları doğrultmak için ödüyorum. Bu nasıl hesap, anlamadım doğrusu. Benden tahsil ettiğiniz vergilerle söz gelişi sarımsağın kokusunu yok etmeyi başarmış olabilirsiniz pekala. İyi de, bunun bana veya mideme ne faydası var? Yani şimdi kokusuz sarımsağı yiyince midem ağrımayacak mı? Ayrıca “sen vergini devletine ödüyorsun “ demeye falan kalkışmayın sakın çokuluslular! . Ulu devletim benden alıp size borç ödüyor. Hem de ta Osmanlı’dan beri!

Ben ise halen düşünce teybimi bekliyorum… 

Düşüncelerimiz kayboluyor ilim irfan sahibi efendiler, baylar, bayanlar, düşünceli ve düşüncesizler! 

Öncelikle onlara sahip çıkalım. İnsanın beynine bilgisayar yerleştirmekten söz ediyorlar durmaksızın. İleride neler olacağını şimdiden görür gibiyim. Dünya pazarı, çokuluslu iki şirket arasında paylaşılır ve acımasız rekabet başlar. Bunu izleyen Allah’ın her günü ise, gelsin güncelleme fasılları. Herhalde beynimize “ding! , yeni güncellemeniz var” diyen bir uyarı merkezi yerleştirecekler. Ama ne fayda! Adaletsiz rekabetin gözü kör olsun. Bir gün mutlaka rakip şirket beyninizde bir boşluk, bir aralık kapı yakalar. O gün fena halde aşıksınızdır mesela. Veya işle ilgili sorunlarınızda boğulmuşsunuzdur. Ödemeniz vardır ama banka hesabınız “S.O.S” veriyordur. Ya da kapı komşunuzda çocukları vuruyorlardır. İsyandasınızdır ve beyninize çoktan inmeler inmiştir bile. Kısaca, beyniniz, ruhunuz, kalbiniz korunmasız ve zayıftır demek istiyorum. Böylece virüslenirsiniz. Yarın “hack”lenir, öbür gün de çökersiniz. “Update” olayım derken dümdüz (down)      edilip kalırsınız. Olur biter!

İkinci olasılık ise, programlar mükemmel çalışır. Yeryüzünde aniden binlerce benzeriniz türer. Koro halinde davranır, mantarca şarkılar söyler, koro halinde düşünür, koro halinde eksilir çoğalır; hissetmez ve hatta düşünmezsiniz bile. Programınız var ya, oh ne ala! Sorunları program çözümler ve bilgisayarınıza gerekli ayarları kaydeder. Bireysel yaratıcılıktan yoksun olarak aşk yaptığınızı düşünün bir de. Bu da laf mı şimdi? Kocaman bir mantık hatası! ''Kısıtlanmış makine düşünürleri'' olduğumuzu unuttum bir an. Bu durumda aşk bizim neyimize? Kuru bir cinsellik çok bile! Hele şiire hiç gerek kalmadı. 

Düşünen insan faktörü olmayınca bu alemi yönetmek fevkalade kolay. İlim irfan sahibi çokuluslular iyi bilirler bu gerçeği. Canlıları koyun gibi gütmekte ustalaşmışlardır adeta. “Koyun” derken, ne için olduğunu dahi bilmeksizin tüketenleri; sormayan, sorgulamayan, “öteki”ler için acı çekmeyen, insani sorumluluk taşımayan ve başını dik tutmayı beceremeyen kurbanları kast ediyorum.. Sonuç ne peki? Dünya genelinde büyük şirket bilançolarında az emek karşılığında bol kazanç görünür. Çağımızın yükselen değeri o sayfalarda yıldız gibi parlar. Ne acıklı değil mi? 

O halde, hep birlikte gülelim ağlanacak halimize!

……………. 

Ütopik bir düş dünyasında sizleri bir gezintiye davet ettim bugün. Çocukluğumda Jules Verne ile çok dolaştım da ondandır belki bu kusurum. Düşünceleri kaydetmek keşke mümkün olabilseydi. En çok da ben mutlu olur ve düşler aleminde böylesi uzun yolculuklara çıkmak zorunda kalmazdım. Ama ne yazık ki hayallerimin gerçekleşmesi mümkün değil. 

İmkan dahilinde olan somut bir şey var ama. Düşüncelerimize sahip çıkmak; onları para ve güç makinelerine kaptırmamak; tarlayı sürüp ekmekten asla vazgeçmemek ve düşünce ürünleri toplamak gibi… 

Tarlanız verimli, hasadınız bol, yolunuz açık olsun dostlar! 

Kalınız sağlıcakla … 

(31 Temmuz 2004)  - ''Gençler İçin Denemeler'' dosyasından...', 'Benim bir derdim var. Bir değil, çok aslında...  Hangi birinden başlasam? İlk olarak içimi susturmalıyım. Öylesi bet bir sesle konuşuyor ki ...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sorunum-var-duz-yazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Jivanî', 'jivan-omer-dilsoz-xgcv8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dilên me yên şikestî, 

bi tîna jivaniya biharekê 

her riyan dipên. 

lewma êdî çavan, 

xewên şevan 

li xwe herimandin. 

debar li me bû nanoziko, 

war bû navnîşaneke nediyar, 

kolan bûne spartgeh, 

bûne qada jivaniyê bo me... 

bi hêviya jivanê; 

li welatekî azad, 

me berê xwe da çiyan 

em bûne agir, 

bûne ax, 

bûne hewa, 

bûne av 

û me ''jiyan'' ava kir. 

em bûne dilop, 

niqut bi niqut herikîn; 

bi hedareke bêwest, 

me nexwar, 

venexwar; 

têr nenivistîn, 

nekenîn, 

bi zikekê têr, 

bi dehan mane birsî 

da ku sibe xweş bibin 

li vî welatî... 

bi jivana warekî ava, 

cîhaneke têr evîn, 

welatekî azad, 

jiyaneke birûmet; 

me bend şikandin 

demsal rakirin, 

hevseng guhartin, 

kozik kolan li şkêran, 

çiya kirin bihuşt 

û lê bi cih bûn. 

bê west, 

bê xew, 

bi jivana dilên bijûn 

me şikeft kolan, 

tov lê reşand 

û mirovahî tê de çand. 

bi jivana wê rojê, 

ew roja ku bihar dê vejî 

em li ser piyan, 

her hişyar in... 

dê di wexta xwe de 

xwe bigihînin jivanê 

ji ber ku, 

wê rojê, 

li vî welatî dê şên û şeng be; 

dê geş bibin hemû kulîlk, 

bifûrin hemû rûbar, 

bikenin hemû însan... 

û 

dê roj were hinda me; 

tîrêj bide 

û geş bike welatê me. 

2003-07-16', 'dilên me yên şikestî,  bi tîna jivaniya biharekê  her riyan dipên.  lewma êdî çavan,  xewên şevan  li xwe herimandin.  debar li me bû nanozi...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dilsöz']::text[], 8.5, '{"poet":"Ömer Dilsöz","poet_slug":"omer-dilsoz","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/jivani-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Revaneya Evînê', 'revaneya-ev-n-omer-dilsoz-829yg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Min diviya hez bikim 

Te nediviya 

Lê min hez nedikir 

Te ji nû diviya 

        -te hez dikir 

Min bawer nedikir 

Tu li rêyan digeriyayî 

Min bawer dikir 

Tu ji rêyan vedigeriyayî 

Min diviya te bibînim 

Tu direviyayî 

Min diviya te nebînim 

Tu li min digeriyayî 

Tirs li te peyda dibûn 

Te ji min dipirsiya 

Kul li te peyda dibûn 

Te ji min dipirsiya 

Te ji jiyanê hez dikir 

Tu ji min digeriyayî 

Jiyanê bêbextî li te dikir 

Tu li min digeriyayî 

Ne te ji min hez kir 

Ne ji min geriyayî 

Ne te dilê min geş kir 

Ne jî ji min veqetiyayî 

Niha tu li aliyekê bêdeng 

Ez li aliyekê 

Lê em herdu ditirsin 

Hem ji xwe 

        -hem ji felekê. 

2004-07-31', 'Min diviya hez bikim  Te nediviya  Lê min hez nedikir  Te ji nû diviya          -te hez dikir  Min bawer nedikir  Tu li rêyan digeriyayî  Mi...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dilsöz']::text[], 8.5, '{"poet":"Ömer Dilsöz","poet_slug":"omer-dilsoz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/revaneya-evine-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Strana Evînê', 'strana-ev-n-omer-dilsoz-4jzoa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Strana evîna min; 

Ji dengekî kelegirî, 

Çend peyvên zîz, 

Wekî dilopa ava keviyan 

Zelal, 

Lê tijî merem... 

Dû hev, 

Bişid û herîkbar 

Ji nava nefeseke westiyayî; 

Di kuna bilûra bilûrvanekî re; 

Dû hev rêz dibin; 

Rêz dibin çend gotinên sotî, 

Bi kela dilekî bihujî, 

Û hişîmend... 

Ji dengekî xeyîdok; 

Bi awazeke xwerû-gazinc 

Pey hev, 

Kom dibin çend gotin, 

Û ref bi ref tên ser zimên. 

Ji gewriyeke tî û zuha, 

Bi daxwaza şerbikekî ava zelal; 

Ya wekî şîrî spî, 

Sar û qerimî. 

Wekî dewê rex rûbarî 

Yê sibitkirî 

Ji destê xweşdiviyê; 

Tevî ava avzemên çiya, 

Lîlava ber keviya... 

Qurt bi qurt daqultînin; 

Çend biwêjên têrtijî, 

Bi ser hinavên kelijî re 

... 

Hingê; 

Bayê xeyalên min diçe, 

Digere li deverên veşartî; 

Li gundekî xweş, 

Li nav çar çiya, 

Di newaleke kûr de rûniştî. 

Û aveke sar, 

Bayekî hûnik, 

Xwezayeke paqij 

Di nav hev de... 

Ji dengekî westiyayî; 

Hin gotinên bêhn xwêdangirtî, 

Digel awazeke cotkar û rêncber 

Tevî du eyhotkên pale 

Û nefeseke têraxînk... 

Dû hev, 

Hûnandî, 

Lihevhatî, 

Xweşik û fesîh, 

Zelal û vekirî 

Rêz dibin û tên ser zimên. 

Wekî stranekê, 

Strana evînekê, 

Evîna mirovekê, 

Mirovê welatekê... 

Di dileke kesertijî de 

Çend xwezî, 

Wekî kulmeke agir, 

Nexêr, xwelîmora dil, 

Heye ku bizoteke gur 

Ji nava rêzikên rêsayî, 

Li ser tevnê hinavan 

Di nava kovanan de 

Tên raçandin û der birîn; 

Ji gewriyeke tal û tî... 

Bayê xeyalên min diçe; 

Digere, 

Vedinêre dinyayê. 

Li nîvê şeveke daçûyî, 

Piştî hingorê razanê, 

Di xewneke hilçûyî de 

Ji dengê têla tembûrvanekî şareza, 

Çend dilopên gotinan 

Yên jibîrbûyî, 

Mîna xiltê sorikê hildidin; 

Di nav bîrhatinên kevin de 

Pir dijwar... 

Dû êk, 

Mil bi mil, 

Bi perwer, 

Çav-vekirî 

Tên serdana guhçikê dilê min; 

Û ji nişka 

Mîna jehra dûvpişka 

lê digezin... 

Hingê, 

Deng... 

Dengê dil... 

Dengê Janan 

Lêdana rajenê bi têrguman, 

Û hesteke di navbera tirs û kêfê de 

Yanî kelecan... 

Kelecan vedigire min. 

Vêca, diherikin ji kûrahiyan, 

Dû hev, 

Rêz bi rêz, 

Çend dilopên zelal, 

Germ û sûr tên ser hinarîkên rûyan; 

Û li hevokan dibe zêmar... 

Hingê, 

Ew stran, 

Strana ji harmoniya dengan 

Û pêjnên têvel afirî 

Diherike ser ziman: 

Xwerû gazind, 

Têr merem, 

Tijî keser, 

Bes mişt hêvî... 

Rêz bi rêz; 

Dû êk, 

Pişt êk, 

Neql bi neql, 

Vehûnandî, 

Rêsandî, 

Û weribandî... 

........ 

Dilop bi dilop diherikin 

Tên li ser ziman dipengizin 

Û di navbera çav û birûyan de; 

Ji xeleka strana evîneke dilsoj tên pê 

Û dibin helqek ji strana evîna min. 

2002-10-17 /Gûzereş', 'Strana evîna min;  Ji dengekî kelegirî,  Çend peyvên zîz,  Wekî dilopa ava keviyan  Zelal,  Lê tijî merem...  Dû hev,  Bişid û herîkbar  Ji ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dilsöz']::text[], 8.5, '{"poet":"Ömer Dilsöz","poet_slug":"omer-dilsoz","theme":"Türk Şiiri","is_hero":false,"total_lines":124,"source_url":"https://www.antoloji.com/strana-evine-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tenê me', 'ten-me-omer-dilsoz-fpvb8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dilê min dinale, 

bêhal im. 

xwîn dikeve ser kezebê, 

diqehir im, 

naxêr, xwerû qehr im! 

Di bêdengiya şevê de 

dicemid im, 

direcif im, 

sebra min nema tê, 

xewn bo min tal in 

şev meh in; 

naxêr, wekî sal in. 

Ango ez bi tenê me, 

dilkovan im, 

çaverêyî te me, 

bê xudan im. 

naxêr, bê te nikarim! 

Di nepenîtiya awirên te de, 

razzan im, 

li ser deryaya evîna te 

keştîvan im, 

melevan im, 

naxêr, çav-giryan im! 

Qet nizanim ez xwe bêyî te; 

hêr û gêj nav jiyan im, 

dajon min tirsên bê wate 

dinalim, 

birîndar im, 

naxêr, evîndar im! 

05-12-2001', 'Dilê min dinale,  bêhal im.  xwîn dikeve ser kezebê,  diqehir im,  naxêr, xwerû qehr im!  Di bêdengiya şevê de  dicemid im,  direcif im,  se...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dilsöz']::text[], 8.5, '{"poet":"Ömer Dilsöz","poet_slug":"omer-dilsoz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/tene-me-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vebêjim', 'veb-jim-omer-dilsoz-lhcj6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Divê ez vebêjim; 

Hemû xewnên xwe 

Ji bayê spêdeyan re 

Kîte bi kîte... 

Divê ez rave bikim; 

Hemû çîrokên xwe 

Ji rûbarên geliyan re 

Tîp bi tîp... 

Digel sîtavkên berêvarî 

Li ser sînga çiyayên bilind 

Li dora agirekê; 

Bi qirçîna sotina bizotan re 

Heko dilore lûliya çaydanka reş 

Di bin çilvilîna stêran de 

Rojekê... 

Rojeke biharê, 

Şevekê... 

Şeveke havînê, 

Li welatekê... 

Welatê Rojê; 

Divê ez vebêjim 

Hemû stranên xwe 

Ji evîndaran re 

Rêzik bi rêzik... 

21-03-2003', 'Divê ez vebêjim;  Hemû xewnên xwe  Ji bayê spêdeyan re  Kîte bi kîte...  Divê ez rave bikim;  Hemû çîrokên xwe  Ji rûbarên geliyan re  Tîp b...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dilsöz']::text[], 8.5, '{"poet":"Ömer Dilsöz","poet_slug":"omer-dilsoz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/vebejim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İbadet', 'i-badet-mir-ay-nsp84', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Deştim gizli dehlizlerini

Savunulmuş 

ve hatta

kurtarılmış sandığın

bütün kaleleri...

Figanın boşadır,

Havarlar nafile

Suskunluğumla doldurdum mabedini

sana tapınmayı bıraktım,

Kazanmanın umarsızlığıyla 

büyük kayıplar bıraktım

Sana kalan

bulmaktır,

asıl kazancın 

sevi''lerde yer edinmiş kayıplar olduğunu...', 'Deştim gizli dehlizlerini Savunulmuş  ve hatta kurtarılmış sandığın bütün kaleleri... Figanın boşadır, Havarlar nafile Suskunluğumla doldurd...', ARRAY['Türk Edebiyatı','Şiir','Mir Ay']::text[], 8.5, '{"poet":"Mir Ay","poet_slug":"mir-ay","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ibadet-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı neydi?', 'adi-neydi-salih-ozalasan-1mqqi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adı neydi? Günlerdir koyamadığımız

Sevdalar yaşanır; asla engel olamadığımız

Bir çift göz her zaman vardır doyamadığımız

Gönülden gönül-e bir yol ki! ! Göremediğimiz

Adı neydi? Ayşe Fatma, bilmediğimiz

Eller uzanır bazen tutamadığımız

Kör olmak vardır bakıp göremediğimiz

Bir de yüreğin sesi vardır ki! ! Duyamadığımız

Adı neydi? Dost arkadaş sevgili ayırmadığımız

Edilen sözler vardır acıda olsa darılmadığımız

Gizli kelimeler hep kalır, yutkunup haykıramadığımız

Öyle sevişmeler vardır ki! ! Tenine dokunamadığımız

Adı neydi? Sevgi; Arzu; Özlem seçemediğimiz

Can tatlı vazgeçilir; yar-ise asla vazgeçemediğimiz

Her gönülde bir sevgili bakmakla göremediğimiz

Öyle sevgililer vardır ki! ! Can vermekle ayrılamadığımız

Adı neydi? Bazen nokta, nokta tanımladığımız

Yüreklerde tomurcuk gül gonca gözyaşıyla suladığımız

Sevdalar vardır içimizde bir özlem hiç yaşayamadığımız

Sevmek o kadar güzel ve zor ki! Yaşamaya asla doyamadığımız

Adı neydi? Geçmiş gelecek yada daha yaşayamadığımız

Her yürekte bir sultan yaşar hatırını kıramadığımız

Her şeye doyulur bir tek sevgilidir sevmeye doyamadığımız

Öyle sevgililer vardır ki! Yanı-başımızda arayıp bulamadığımız

Y tarihi 05-08-04 Saat 10.00

Salih ÖZALAŞAN', 'Adı neydi? Günlerdir koyamadığımız Sevdalar yaşanır; asla engel olamadığımız Bir çift göz her zaman vardır doyamadığımız Gönülden gönül-e bi...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/adi-neydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol', 'yol-nilay-aksu-1sbpr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ne yana yürüsek 

hayat sırtını dönüyor 

ne yana baksak hayat 

bir başka hayatla sınanıyor', 'ne yana yürüsek  hayat sırtını dönüyor  ne yana baksak hayat  bir başka hayatla sınanıyor...', ARRAY['Türk Edebiyatı','Şiir','Nilay Aksu']::text[], 8.5, '{"poet":"Nilay Aksu","poet_slug":"nilay-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yol-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kibrit Kutusu', 'kibrit-kutusu-goktu-kara-n4tsa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yağmur yağarken hızla geçen caddeden

bir yoksul çocuk taşıyordu kibrit kutusunu

sıkıca canı gibi sıkıca

sımsıkı sarılmıştı paltosuna

çap çup çap çup

çamur değiyordu çıplak ayaklarına

hızlanıyordu yağmur

sığınacak bir yer aradı çocuk

bulamadı 

çaresiz

koşmaya başladı

kibrit kutusunu islatmamaya çalışıyordu

düştü suların içine

ama kibrit kutusu ıslanmamıştı

ıpıslak eve geldi

yağmur yağarken gözlerinden

kibrit kutusundan düşen boya kalemleriyle

 resmini yaptı yağmurun', 'yağmur yağarken hızla geçen caddeden bir yoksul çocuk taşıyordu kibrit kutusunu sıkıca canı gibi sıkıca sımsıkı sarılmıştı paltosuna çap çup...', ARRAY['Türk Edebiyatı','Şiir','Göktu Kara']::text[], 8.5, '{"poet":"Göktu Kara","poet_slug":"goktu-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kibrit-kutusu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir hikayemiz var mı?', 'bir-hikayemiz-var-mi-pelin-onay-bdai2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '(bence var../ yoksa bu hasret neden tüter..? ..)

imgelerin izdüşümünde dansa kaldır beni 

uyuklayan bedenimi uyandır 

yüreğimi uçuklatan satırlarına sarıldım 

hadi beni yeniden kandır 

hala çocuğum sevdalarda 

yalpalayarak yürürsem yüreğinde, 

ayağım takılıp da düştüğümde adını sayıklarsam, 

mimiklerim çıldırırsa seni görünce, 

beni bağışla 

her şeyin sebebi hasretindendir 

hangi geceydi, 

her gece miydi susuzluğum sarılmalara..? 

gökten üç elme düştüğünde, 

biri de bana değmiş miydi..? 

kaç yaşında fark ettim 

unuttum 

hatırladım kadın olduğumu..? 

hangi şarkı kesti göbek bağımı, 

bağladı beni hayata..? 

beni bu soruların cevaplarından tutar mısın..? 

gecenin bilmem kaçı 

aklımın kaçışı 

sorgu sual dinlemiyor saatler 

önce hangimizin yüreğinde yıldız kaydı..? 

tuttuğum dileklerde unuttum kayıplarımı 

kime baksam üzgün 

ağlamaklı 

yaralı 

haydi gel 

şu uzaklığın kopçasını tek bir hareketle çıkart üzerimden 

şehveti bir bıçak gibi sapladım bedenime 

göğüslerim değil, 

yüreğim dirileşiyor 

sana öyle bakma demiştim, 

beynim tahrik oluyor 

zaten kandıramadım geceyi 

gündüzün koynuna girmek için hızla geçiyor 

gecelelerde benim gibi sevgilim 

sabırsız 

isyankar 

laf dinlemez 

işin ucunda sevda olunca, 

saatleri bile saymıyor.. 

......... 

...... 

.... 

ama sen../..bir hüzzam makamında uyut beni 

adını sayıklayan dudaklarımı ıslat 

gözlerimi güldüren renkli düşlerine sarıldım 

haydi../..bana hikayemizi anlat 



hazan/ ''03', '(bence var../ yoksa bu hasret neden tüter..? ..) imgelerin izdüşümünde dansa kaldır beni  uyuklayan bedenimi uyandır  yüreğimi uçuklatan sat...', ARRAY['Türk Edebiyatı','Şiir','Pelin Onay']::text[], 8.5, '{"poet":"Pelin Onay","poet_slug":"pelin-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/bir-hikayemiz-var-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara kızım Holstein', 'kara-kizim-holstein-mustafa-toga-3n5yp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Onbeş ile başladık

Şimdi oldunuz doksan.

Benim ağzı var dili yok 

Siyah beyaz kızlarım.

Hepinize ayrı ayrı isim verdim

Hem adınız var, hem kulaklarda numara.

Buzağılar, danalar, düveler

Nedense,

Ayrı ahırlarda yatar tosun ile boğalar.

Sağmallar başlar sabah beşte koroya,

Süt güğümleri boy boy dizilir sıraya.

Sabah akşam dökeriz önünüze bolca süt yemi, 

Ot, saman, slaj, yonca ise cabası.

Memeleri mastitsiz, ağızları şapsız kızlarım.

Hepinizi tek tek sevmeye, okşamaya doyamam

Hele hele su içip, geviş getirmenize

Saatlerce baksam kanamam.

Günlük; 

On kilo süt verenin de, otuz kilo verenin de

Sevgisi yanımda aynı,

Değerinizi külçe altın ile ölçemem.

Ama; 

Bambaşkaydı

Kara kızım …..

Konuşurduk. Ínanın dinlerdi beni

O benim yüzümü yalar, bende onun anlını kaşırdım

Dört köşe olurdu zevkten.

Sığır sürümün sembolüydü.

Duruşuyla, yürüyüşüyle, süzülüşüyle

Kırk kilo süt verişiyle

Íkiz buzağı doğuruşuyla.

Siyah beyaz beneklim

Íç kanamanı durduramadık.

Gitmiyor gözümün önünden,

O heybetinle yere yıkılışın

Kalkmak için çırpınışın,

Kara gözlerini gözlerime dikip

Yavrularım sana emanet dercesine

Uzun uzun möö..leyişin.

Ağladım,

Ínan

Ardından üç gün yas tuttum.

Ciğer parem, 

Can dostum,

Sırdaşım,

Holstein’im; Kara kızım. 

Mastit: Sığırlarda görülen meme hastalığı

2001-Salihli / MANÍSA

SÖZÜN ÖZÜ: 

“Çiftçiyim” diye güvenme zahran ambara girmeyince, “Evlâdım var” diye güvenme el kızı koynuna girmeyince,

“Ahbabım var” diye güvenme başına bir iş gelmeyince.

www.mustafatoga.com', 'Onbeş ile başladık Şimdi oldunuz doksan. Benim ağzı var dili yok  Siyah beyaz kızlarım. Hepinize ayrı ayrı isim verdim Hem adınız var, hem k...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Toga']::text[], 8.5, '{"poet":"Mustafa Toga","poet_slug":"mustafa-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/kara-kizim-holstein-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Kara Sevda', 'kara-sevda-nurten-altinok-k2xlh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tek kurşunla ölmem ben

Yıldız yağmurlarına tutun bedenimi

Bende bu yürek, lebiderya

Yeşerdikçe kara sevda

Nice rüzgarlara yaprak olurum

Nice gecelere gözyaşı

Nice şiirlerin o şuh kadını

Kalbimi bana bırakın...', 'Tek kurşunla ölmem ben Yıldız yağmurlarına tutun bedenimi Bende bu yürek, lebiderya Yeşerdikçe kara sevda Nice rüzgarlara yaprak olurum Nice...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kara-sevda-171-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemiyorlar', 'i-stemiyorlar-ali-fikri-karadeniz-kxo6n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ölüm; bir adım ötemde olsa da,

Toprak kabul etmiyor beni.

Kabul etmiyor içimdeki sevgiyi

''Çıkart'' diyor... ''Çıkart

Beni lekeleme, çıkartta öyle gel,

Bağrıma basayım seni...''

Söyle sevgi; 

Nasıl atacağım ben Seni? 

Allah''ım, diri diri yak beni...! 

Küllerim savrulsun

AR - DA ''nın gölgelerine

Sende mi? 

Sende mi rüzgar istemiyorsun beni? 

Denizler yıka beni,

Göller, pınarlar....

Güneşte ıslat ta

Yağmurda kurut beni

Yeter Yarabbim yeter; 

Ne olur... Ne olur yok et beni...! ! !', 'Ölüm; bir adım ötemde olsa da, Toprak kabul etmiyor beni. Kabul etmiyor içimdeki sevgiyi ''Çıkart'' diyor... ''Çıkart Beni lekeleme, çıkartta ö...', ARRAY['Türk Edebiyatı','Şiir','Ali Fikri Karadeniz']::text[], 8.5, '{"poet":"Ali Fikri Karadeniz","poet_slug":"ali-fikri-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/istemiyorlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bende', 'bende-cem-kadri-korkmaz-1ee5v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir yaş var gözümde

Seni düşündükçe akan

Aktıkça ömrümden gün çalan

Bir kalp var bende

Beni sevdiğini düşündükçe

Deliler gibi çarpan

Bir yürek var karşında

Seni sevdiğini dağlara

Haykıracak kadar cesur olan

Bir ömür var bende

Beni sevmediğini öğrenince

Benden koşarak uzaklaşan', 'Bir yaş var gözümde Seni düşündükçe akan Aktıkça ömrümden gün çalan Bir kalp var bende Beni sevdiğini düşündükçe Deliler gibi çarpan Bir yür...', ARRAY['Türk Edebiyatı','Şiir','Cem Kadri Korkmaz']::text[], 8.5, '{"poet":"Cem Kadri Korkmaz","poet_slug":"cem-kadri-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bende-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Boş EV...', 'bos-ev-erdal-asik-58fsl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yokluğunda boş bir eve girerim

Yalnızlığım ve ben

Seni ararım bilirim boşluğunu

Her adımda düştükçe

Nefesim yankılanır sessizliğinde

Odaların köşelerinde 

Özlerim yudum yudum 

Hasret göz yaşları dökülür kadehime

İçmeden yalnızlığın sarhoşu olurum

Dönmeyecek zanneder ağlarım

Çırılçıplak olmuş hayellerimi

Sererim yatağıma

Düşlerimle yatarım yokluğunda 

Buram buram sen kokarsın

Tenin kokar saçların kokar 

Seni koklarım 

Sarılıp yastığıma uykuya dalarım 

Senin yokluğunda..', 'Yokluğunda boş bir eve girerim Yalnızlığım ve ben Seni ararım bilirim boşluğunu Her adımda düştükçe Nefesim yankılanır sessizliğinde Odaları...', ARRAY['Türk Edebiyatı','Şiir','Erdal Aşık']::text[], 8.5, '{"poet":"Erdal Aşık","poet_slug":"erdal-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bos-ev-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlım Yine', 'yalnizlim-yine-i-smail-ozabaci-8f9cw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'akşam üstleri oturup bir bankta

güvercinleri izlemek ve çocukları

çiçekcilerin önünden geçmek

duymak seni hatırlatan kokuları

şimdi yalnızlığımın elinden tutup

ona anlatıyorum olanları

onu bekliyorum artık,ismin silinirken kalbimden

şimdi bırakıp güvercinleri ve çocukları

ona yüklüyorum hayatımdaki tüm anlamları...', 'akşam üstleri oturup bir bankta güvercinleri izlemek ve çocukları çiçekcilerin önünden geçmek duymak seni hatırlatan kokuları şimdi yalnızlı...', ARRAY['Türk Edebiyatı','Şiir','İsmail Özabacı']::text[], 8.5, '{"poet":"İsmail Özabacı","poet_slug":"i-smail-ozabaci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yalnizlim-yine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İç koparken | üç |', 'i-c-koparken-uc-zafer-zengin-etnika-0vxzb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'benim yazdığım değil 

kimindi bilmem

içime şarkı sözleri

 '' kadınlar yürüyor dağlara doğru''

sarhoşken dinlerim desem

diyemem

hiç sarhoş olmadım ki

bel ki oldum

sezmedim

sevdim aslında sezmediğim şeyleri

birşeyler olacaksa

onları bilmemek daha iyi

en son bir kitap keşfettim

sanki  ben ahrazken

biri içimi anlatmış

şimdi bana sorsan

küserim ben buna

büyük bir merakla

nerden saklamışlar içime bu kadını 

anlamadım daha

çocuğum işte

aklım  herşeye kesmiyor

büyüsem filozofum belki

çok kitap okuyorum çok

senede beş tane

içime gülene

gülemeyene bir şey yok

bilmiyorum

acım var dedinya

elimi sürsem geçer mi dedim

peki öpseydim

epey düşündüm

aslında içimdeyken bile uzaksın

yaralarını

acılarını sen sarıyorsun

kendimi hayalet gibi

ölüp gitmiş birinin resmi gibi düşünüp

öyle baksan bana 

acılarını sarsan kağıdıma diyorum

senden o kadar çok ki

ben bilmiyorum

içim seyyahken 

ilk seni görüyorum

el uzatayım diyorum sivilceli yanağına

yolda kuruyor saatim

olmuyor

sohbet vardı

konu günahtan açıldı

nasıl desem

günah niye vardı

anlatsan aklım almazdı

hayat gibi yabancıydı

içimde patlayan tabancaydı

kurşunu acımış turşu

yaktıkça su

yandıkça su

iflah olmaz koruluklar

sürüyorum ellerimi söndürmeye

olmuyor

sahi

acımı sarsaydın acına

acımazmıydı

alışkanlık olmasa diyorum

kendime sövüyorum

beceriksizliklerim diz boyu

bileğim gibi

oyana buyana dönüp duruyor

arada bir kütür dedikçe

kültür anlıyorum

yüreğimden ses geliyor

neleri hissetmemişim

neleri görmemişim

sana nasıl seslenmişim

bilmiyorum

olmuyor

gecenin bir vakti

hani saat iki gibi

düşündüm yine

döndüm içime

madem dedim

acı cekenler hissediyor hayatı

öyle yaşıyor

ya da ölüyor

en cok 

hissetmeyenler konuşuyor

peki onlara ne oluyor

içi sesi böyle dağınık kalıyor

| haklı belki de kadın

  içini yazıyor |*

sanki tanıştım kendisiyle

öykülerimiz öpüşüyor her gece

bende hece

onda söze

cümle kurmadan konusuyorum artık

ellerimi zapt etmekte zorlanıyorum

dokunduğum dişiler ki

doğa öyle diyor

ad koymaya bile uğraşmıyorum

sonra yaradılırken 

insanlar neden az gülüyor diyorum

sonra ölürken

içerde susanlar kim

merak etmekten

nefret edemiyorum

olmuyor

***** sürecek ilerde ilk köşeden başlıyor..eğil ve oku..çürüt dizlerini.

*Ece temelkuran '' İç kitabı ''', 'benim yazdığım değil  kimindi bilmem içime şarkı sözleri  '' kadınlar yürüyor dağlara doğru'' sarhoşken dinlerim desem diyemem hiç sarhoş olma...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":107,"source_url":"https://www.antoloji.com/ic-koparken-uc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Harabeler', 'harabeler-mehmet-sakalar-x75py', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Harabeler, onlar benim gözlerimdi aslında,

Aslında sözlerimdi sana ulaşma çabasında.

Yığın yığın seni düşündüm yıkılırken,

Aslında düşüncelerimdi.

Toz, toprak birbirine karıştı fikirlerimde ama

Sonunda seni dudaklarımda düşündüm,

Düşüncelerimdi harabeler.

Aslında harabeler sendin,

Sana sığındım kışın o sert ayazlarında,

Sıcacık göğsüne yaslandım,uyudum aslında kollarında.

Yine sen korumuştun beni,

Çaldığım mutlu rüyaları gizlemeye çalışırken 

                                         gece bekçilerinden.

Harabeler aslında benim dünyamdı,

Evim, saraylarım, asma bahçelerimdi aslında.

Evim diyorum affet, sensiz yaşanan yere ev denmese de.

Harabeler mi? Mezarımdı aslında.

Yıkık dökük duvarlar mezar taşımdı,

Çakıltaşı melekler arkadaşımdı aslında benim.

Harabeler sendin, ben harabelerdi.', 'Harabeler, onlar benim gözlerimdi aslında, Aslında sözlerimdi sana ulaşma çabasında. Yığın yığın seni düşündüm yıkılırken, Aslında düşüncele...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şakalar']::text[], 8.5, '{"poet":"Mehmet Şakalar","poet_slug":"mehmet-sakalar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/harabeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amed', 'amed-umut-karakas-bltgv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bu hüzündaş Amed akşamında

bir sensin düşündüğüm

bir de yoksul, kederli ülkem 

bu hüzündaş Amed akşamında 

bir hıçkırık, boğazım düğüm düğüm

ağlayacağım ama henüz erken 

iki damla yaş dökülecek gözlerimden 

bu hüzündaş Amed akşamında 

neye baksam bir yalnızlık gördüğüm

yüreğimi bir şiire gömerken 

kendimi ölüme terk ederken

bu hüzündaş  Amed akşamında

yol alıyorum usul usul, severken', 'bu hüzündaş Amed akşamında bir sensin düşündüğüm bir de yoksul, kederli ülkem  bu hüzündaş Amed akşamında  bir hıçkırık, boğazım düğüm düğüm...', ARRAY['Türk Edebiyatı','Şiir','Umut Karakaş']::text[], 8.5, '{"poet":"Umut Karakaş","poet_slug":"umut-karakas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/amed-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sigarayı İstediğim Zamanlar', 'sigarayi-i-stedigim-zamanlar-abdurrahman-cankaloglu-diqj9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bıraktım lanet olasını, üç ay oldu.

Ne zaman içen biri görsem; 

Aklıma gelir Esentepe Yolu

Ne olur canım bir kere çeksem? 

Belkide başlarım yeniden,

İçeceğim ne ki? İki paket,

Zamanımı avutur,şöyle inceden

Başlarım belki kim bilir,

Bıyığımı kestiğim gün, aniden.', 'Bıraktım lanet olasını, üç ay oldu. Ne zaman içen biri görsem;  Aklıma gelir Esentepe Yolu Ne olur canım bir kere çeksem?  Belkide başlarım ...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahman Çankaloğlu']::text[], 8.5, '{"poet":"Abdurrahman Çankaloğlu","poet_slug":"abdurrahman-cankaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sigarayi-istedigim-zamanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin Zaferi', 'sevginin-zaferi-talip-kaplan-0r3e1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Neden kimse anlayamaz beni

Neden hiç anlayamazsın beni

Ve, neden anlayamam ben beni

Birşeyler yapmaya çalışırım hep

Güzel şeyler aktarmak isterim

Çarpışırım tertibimle, neslimle

Bırakın kavgayı, silin nefreti.

Aldım elime manevi bir silah

Sevgiden yapılmış, sevgiyle boyanmış

Vur sevgi kılıcını nefretin boynuna

Kesmez kılıcım, kesmez nefreti

Öyle kalındır ki onun kafası

Ve, öyle işlemiştir ki bilinçlere.

Körelir kılıcımın ağzı, körelir

Vurdukça nefretin beynine beynine.

Yorulur sevgim, yorulur fikrim

Uzanır boylu boyunca yerlere

Ağlamaya başlar hıçkırıklar içinde

Acı gözyaşları çaredir tüm derdine.

Utandırır nefreti, ağlayan sevgi

Kırılır bacakları, sürünür yerlerde

Nefretlerde biter, sevgi alır yerini

Ağladıkça güçlenir sevginin temeli

Yükselir sevginin dimdik direği

Eritir negatifi, namerti, nefreti...

Şimdi anladın mı tertibim

Anladın mı ey neslim

Sil artık o gözyaşlarını

Bir bak şu dalgalanan sancağa

Senin sevgindedir bu zafer

Sevginin zaferidir bu zafer

Yine biz kazandık,

Yine bizimdir zafer

Bizim olacaktır nice zafer...

(07 Ocak 1994)', 'Neden kimse anlayamaz beni Neden hiç anlayamazsın beni Ve, neden anlayamam ben beni Birşeyler yapmaya çalışırım hep Güzel şeyler aktarmak is...', ARRAY['Türk Edebiyatı','Şiir','Talip Kaplan']::text[], 8.5, '{"poet":"Talip Kaplan","poet_slug":"talip-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sevginin-zaferi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İç koparken | üç''ün devamı |', 'i-c-koparken-uc-un-devami-zafer-zengin-etnika-7mytl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'japon

hintli

bolivyalı arkadaşım olmadı

onlar beni sever miydi

sen beni sevenleri sever miydin

ne varsa düşünüyorum

hani gelsen

kaçacak delik arıyorum

kendimden o kadar az şey istiyorum ki

sanki iflas etmiş bir oyuncak gibi

her yanımı kırıyor

ağdalı yapışkanlarla

ellerime tutturuyorum

dağılıyorum tabi

olmuyor

neden olan içime oluyor

kadın düşünmemek için

her işi düşlere yükledim

her ayrım

her koparma

bir adım uzak bana

iki kafam bir arada değil sanki

sen hangisini sevdin bilmem ki

gece uzun işte

düşünüyorum kendimce

ne çok sey var

sahiplenemediğimiz değil mi

mesela 

derde tasaya sahibiz

gam duvar yıkıyor

el atıp tutmuyoruz

içimiz su koyuveriyor

bacağımıza ip bağlamıyoruz

yüzümüze gülüp bizi satanlara

sen bendensin diyoruz

kötülere 

iyiyiz diye sahip çıkıyoruz

doğa affeder mi bizi

çekmez mi kulağımızı

midas yapmaz mı

yapar diyorsun

olmuyor

içimden ağrılar

başıma uğradı

kuru kalabalık gibi

benimmiş ağrı

atmayım lazım olur belki

daha kötüsü vardır kesin

hepsi bitsin

herkes gülsün

diyorum

olmuyor

çok uzun yazacaktım

toparlayamadım

sınıfta kalmışım

en uslu kara önlük bendim

neden kara önlük giyerdim bilmeden

hep yaslıydım öğrenmeye

şöyle mavi olsa elbisem

saçlarını çekerdim yinede ben

öperdim sonra

barışmam için

sen gülerdin

ben düşerdim

sonra kalkardım

olmuyor

******* camlardan ışık düşüyor.. resmini çektim..güzel elbise..aklım başımda değilken giysen..harami kesilirdim..biraz şehirli..kaç kişi küfretti bana bir bilsen..belki içlerini çözdüğümden..varsaysınlar yokum..', 'japon hintli bolivyalı arkadaşım olmadı onlar beni sever miydi sen beni sevenleri sever miydin ne varsa düşünüyorum hani gelsen kaçacak deli...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/ic-koparken-uc-un-devami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazı Şeyler', 'bazi-seyler-baykal-kaanalp-wha55', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bazı şeyler yaşanır olsalar da sıradan

çok şey öğretir insana bıkıp usanmadan

olgunlaşmak lazım,anlatmak gerek,sıkmadan

kimliğinde kötü bir huy,tavır taşımadan

mutlu olamaz kişi bazı şeyler olmadan

ulaşamaz isteğine peşinde koşmadan

emek sarfetmelidir insan haddi aşmadan

bu yolculuk sonuçlanmaz süresi dolmadan

kalp kırılır,aşk azalır,kimseye sormadan

bir kaç yıldız daha kayar,gökte ki formadan

terkeder bizi dünya sana bana sormadan

sevmek lazım,inanmak da,kimseyi yormadan', 'bazı şeyler yaşanır olsalar da sıradan çok şey öğretir insana bıkıp usanmadan olgunlaşmak lazım,anlatmak gerek,sıkmadan kimliğinde kötü bir ...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bazi-seyler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Binlerce Gece', 'binlerce-gece-baykal-kaanalp-0th01', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'binlerce gece konup konup

göçtü

hiç bilmediği sahillere

binlerce ay battı 

yüreğine

kanadı acısız

ağrısız

bir damla yaşanmışlık

öyküsü

tutunamadığı saatlere

inat,ağlamadı

üzülmedi,acısına

kapılmadı rüzgarın 

uğultusuna

binlerce aşık konup konup

göçtü

hiç bilmediği gönüllere

binlerce hasret battı

sevgisine

bundan gocunmadı

üzüntü duymadı

yerinmedi unutulduğunda', 'binlerce gece konup konup göçtü hiç bilmediği sahillere binlerce ay battı  yüreğine kanadı acısız ağrısız bir damla yaşanmışlık öyküsü tutun...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/binlerce-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aniden', 'aniden-baykal-kaanalp-1t0w1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir bağışıklık sistemi

kurulmak üzereyken

birden koptu ilmek yerinden

kararsızlık densizliği

sarmıştı ki tozlu rafları

lekeler küf tuttu aniden

kapkacak ne varsa

yerlerde,kilerde,beton

seyreyledi cümbüşü yerinden

kızılca kıyamet koptu

kırıldı bütün camlar

dile geldi kırık eşyalar aniden', 'bir bağışıklık sistemi kurulmak üzereyken birden koptu ilmek yerinden kararsızlık densizliği sarmıştı ki tozlu rafları lekeler küf tuttu ani...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aniden-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaktan Sevişmek', 'uzaktan-sevismek-adnan-durmaz-t2zwz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'insanın vatanı insan bilmişiz

gayri uzaklıklar bağlamaz bizi

acı dedikleri gelir de gider

akışı durmayan sulara benzer

sevda dal dal uzar-yaprağı keder

acıya kök salan ağaca benzer

biz ayı suların yüzünde sevdik

gayri ateş bile dağlamaz bizi

zulüm gördük-ölüm gördük-kanadık

yaramızı yangınlarda sınadık

gül büyüttük hasretlerde

ayrılıkta fırınlandık

elsiz kolsuz kalmalara dayandık

umuttan gayrisi eğlemez bizi

yalnızlığı gül yatağa çevirdik

geceler sevdanın bağı kesildi

yağmurlar yağdırdık yüreğimizden

gözyaşlarımızı bulutlar sildi

ne para-ne servet-ne şan-ne şöhret

bir damla çoğaltmaz gülüşümüzü

zulme karşı çıkıp kelle koyanlar

yürekler dolusu vurulmuş yatar

kanadı buluta değen türküler

gelir de yüreğin dalına konar

zından tutsak etmez düşlerimizi

soytarı tarihler söylemez bizi

acımasız zaman bir bizden ürker

eskimez sevdalar ülkesindeniz

ayartmaz sunulan sahtekar düşler

sahte makamları teper geçeriz

yalnızlık verdiler sevda çoğalttık

zındanlarda bükülmeyen inattık

hayata dört elle sarılıp tattık

sevdadan gayrısı çağlamaz bizi

unut dillerini sevdaca söyle

beni yarana bas düş kat acıma

gel benim can suyum-hüzün güzelim

tül bulutlar senden gelir dağıma 

bir saman çöpüyüm sen kehribarım 

ayrı tutma senden şiir ülkemsen

kirpiği yıldızlım-deli rüzgarım

insanlık sevdasında yurtsuz ırmağım

yabanılım-bulutlarca dağlarca 

bana ak ansızın-sana akayım

suyumuz tutuşsun buluşmamızda

gel ey zaman gözlüm-öteki yarım

sevdadan gayrisi eğlemez bizi

adnan durmaz,bilirsin aşk da serseri,art yay,ank,2003', 'insanın vatanı insan bilmişiz gayri uzaklıklar bağlamaz bizi acı dedikleri gelir de gider akışı durmayan sulara benzer sevda dal dal uzar-ya...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/uzaktan-sevismek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı', 'kirmizi-kenan-aglaklar-jwg9b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yalnızlığın tek ve büyük ödülü hatırlanmak

Hatırlanmak gözyaşı ile andırılan

''İyi dayandı aslında iyi insandı''

Lafları ile değil.

Hatırlanmak ''Doğruları için yalnız kalmayı göze aldı.''

Denilerek hatırlanmak.', 'Yalnızlığın tek ve büyük ödülü hatırlanmak Hatırlanmak gözyaşı ile andırılan ''İyi dayandı aslında iyi insandı'' Lafları ile değil. Hatırlanma...', ARRAY['Türk Edebiyatı','Şiir','Kenan Ağlaklar']::text[], 8.5, '{"poet":"Kenan Ağlaklar","poet_slug":"kenan-aglaklar","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kirmizi-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhamet', 'merhamet-zafer-zengin-etnika-6mkh7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kapansın

kardan

yollar

bahar

beklensin

merakla

beklenen 

o yüzün

o bakışın

seninle

sesinle

gelsin

yüzünden

gülücük

içinden

merhamet

eksilmesin

Bir 

bana

küs

dünya

sana 

gelsin

içimden

| iç |in

gitmesin

3 Ağustos 2004', 'kapansın kardan yollar bahar beklensin merakla beklenen  o yüzün o bakışın seninle sesinle gelsin yüzünden gülücük içinden merhamet eksilmes...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/merhamet-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nur IV', 'nur-iv-ahmet-aksoy-36ih4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'tek gerçeğim sendin

şimdiyse her şey yalan', 'tek gerçeğim sendin şimdiyse her şey yalan...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/nur-iv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Güzel Şarkının Seni Düşünmek Olduğunu Öğreniyorum', 'en-guzel-sarkinin-seni-dusunmek-oldugunu-ogreniyorum-karahan-yilmaz-75yiv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biliyorum seni düşünmek serseri bir aşka yenik düşmektir.Seni sevmek kalbimin duvarlarına resmini çizmektir. Seni özlemek bir sevda şarkısı mırıldanmaktır. Oysa ben seni sana sormak, seni senden öğrenmek ve seni sende yaşamak istiyorum.

Biliyorum, belki bir gece belki de bir sabah, kalbimin kiblesine bir sevda gemisi gibi yanaşacaksın. Ağır ağır sokulacaksın kalbimin başkentine doğru... Aşkın anadilinde düşünecek ve aşkın anadilinde şarkılar soyleyeceksin bana..

Gülüşünü taşıyorum içimde aylardır. Bir aşk öncesi bana davetiye çıkaran gülüşünü...Gülüşün sayesinde yaşamayı seviyorum, gülüşün sayesinde yalnızlıklarımı tutukluyorum. Anlayacağın seninle azalıyor hayatım, seninle çoğalıyor. Seninle buluyor anlamını en anlamsız sözlerim. Zaman ve mekan seninle kayboluyor hayatımda böylesine ilk kez. Ve en güzel şarkının seni düşünmek olduğunu öğreniyorum. Başlıyorum  seni bir şarkı söyler gibi düşünmeye.

Yeniden yazıyorum belleğimdeki tarihi. Senden önce, senden sonra diye başlıyor içimdeki aşkların miladı.

Biliyor musun, ben sana her dokunuşumda aklımla yüreğim arasındaki köprüyü yıkıyorum... Asırlık işgallerden, amansız ve anlamsız ahlak kurallarından, günlük hayatın kirlenmiş ilişkilerinden ve yalnızlıklarım-

dan kurtuluyorum. Yıllardır benim olduğunu sandığım bir aşkın bana ait olmadığını anlıyorum.

Birileri israrla masum aşklarımı kirletiyor. Hatta   seni sevemeyeceğimi ispatlamaya çalışıyor. Bırak çalışsınlar. Çünkü ben seni tanıdığım ilk günden beri, tüm yasaklarımı yasakladım

Evet, günlerdir istemeden, farkında olmadan ve kararsız davranarak beni güçsüzlüğe mahkum ettiğini bilmem biliyor musun. Bu güçsüzlük sayesinde belleğimin tüm ara sokakları fantezilerimin işgaline uğruyor. Böyle olduğunu ve olacağını çok iyi biliyorsun. Ama bilerek ve isteyerek geliyorsun üstüme üstüme.

Evet, kölenim belki, ama ben seçtim bu köleliği, ben tasarladım. Yasalarını, zaman ve mekan sınırlarını ve iklimini ben belirledim. Hatta öyle yalnızlıklar yaşadım, öyle acılar çektim ki, bu muhteşem duyguları bir anda olsa yaşamadığın için, senin adına üzülüyorum.

Biliyor musun, ben geçmişimi seninle öğrendim. Seninle tuttum elinden gençliğimin. İlk yürek depremini, ilk şiirimi ve bir kadını ilk öpüşümü seninle  yeniden yaşadım.

Sen benim cebimde yırtık bir resim, kırık bir ayna gibisin. Öyle yalnız, öyle eksik ve öyle paramparça...

Sen benim hayatımda uzun ve çetin bir yolculuksun. Bir yalnızlık şarkısısın. Düşselliğimin en son sınırısın. Seni arıyorum içimde aylardır, seni soruyorum, neredesin? 

13 ocak 2001 / Metz', 'Biliyorum seni düşünmek serseri bir aşka yenik düşmektir.Seni sevmek kalbimin duvarlarına resmini çizmektir. Seni özlemek bir sevda şarkısı ...', ARRAY['Türk Edebiyatı','Şiir','Karahan Yılmaz']::text[], 8.5, '{"poet":"Karahan Yılmaz","poet_slug":"karahan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/en-guzel-sarkinin-seni-dusunmek-oldugunu-ogreniyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulmazım..', 'unutulmazim-i-nan-alver-qsxo3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gidişlerin kadar,dönüşlerin kolay olmuyor,

Anılarım düşler denizinde sahipsiz kalıyor,

Kendime ayırdığım gecelere,

Sensiz ne ay,ne de yıldız doğuyor.

Vakit var mı daha? 

Sana sınırsızca doymaya,

Anılara sığınmadan,

Hayatı kollarında yaşamaya.

Gidişinle dünlere dalarım,

Gelişinle yarınlara hayal kurarım,

Ne zaman bugün''ü yaşamak istesem,

Bakışlarında kaybolurum.

Unutulmazım oldun bu hayatta,

Ardına sevda yaşamaktansa

Yakarım bu bedeni,

Seninle dolu anılarımın anısına..', 'Gidişlerin kadar,dönüşlerin kolay olmuyor, Anılarım düşler denizinde sahipsiz kalıyor, Kendime ayırdığım gecelere, Sensiz ne ay,ne de yıldız...', ARRAY['Türk Edebiyatı','Şiir','İnan Alver']::text[], 8.5, '{"poet":"İnan Alver","poet_slug":"i-nan-alver","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/unutulmazim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Bakışın..', 'son-bakisin-i-nan-alver-aa4g2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ayrılık çökerken yüreğime,

Anılar canlanırken gönlümde,

Bırakıp gitmeye razı olmayan gözlerinin,

Son bakışı hala gözlerimde.

Dudaklarından yorulmuş bir aşkın sözleri döküldü,

Geçen yıllara pişmanlığın dile geldi,

Ama saklıyamadı gözlerin ele verdi seni, 

Son bakışın gizleyemedi; kalbindeki sevgiyi,.', 'Ayrılık çökerken yüreğime, Anılar canlanırken gönlümde, Bırakıp gitmeye razı olmayan gözlerinin, Son bakışı hala gözlerimde. Dudaklarından y...', ARRAY['Türk Edebiyatı','Şiir','İnan Alver']::text[], 8.5, '{"poet":"İnan Alver","poet_slug":"i-nan-alver","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/son-bakisin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gibiyim', 'gibiyim-mustafa-yigit-morpheus-cn508', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senden uzakta yalnız başıma

Yolunu şaşırmış yolcu gibiyim

Senin o sıcaklığın yok ya

Sanki kimsesizim, öksüz gibiyim

Gittiğim her yerde seni arıyorum

Günümün her anında seni düşünüyorum

Her şeyimle inan seni yaşıyorum

İnan içmedim ama sarhoş gibiyim

Sensiz sokaklarda dolaşıyorum

Dertleşecek bir dost bulamıyorum

Böyle yaşamak istemiyorum

Ne yaptığımı bilemiyorum divane gibiyim

Gurbet ellerde her anım böyle

Yıllardır aradıklarım hepsi sende

İsteklerime kavuşamadığım için bende

Garip Durağım sanki ölü gibiyim

 Mustafa Yiğit (Morpheus)', 'Senden uzakta yalnız başıma Yolunu şaşırmış yolcu gibiyim Senin o sıcaklığın yok ya Sanki kimsesizim, öksüz gibiyim Gittiğim her yerde seni ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gibiyim-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzünlerdeyim', 'huzunlerdeyim-i-nan-alver-8nocf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rüzgarla savrulan başak tarlasında,

Filizlenen hüzünlerdeyim,

Her savruluşta tohumlar can olup,

Toprağa hayat  verir.

Benim toprağa vereceğim,

Sensizlik için gözyaşlarım.

Bir ucundan yaksaydın bu sevdayı,

Tarlaları ateşe verirdim,

Hüzünleri sevda yangınında eritirdim,

Geçilmez dağları,

Ucunda sevdasını bekleyen yollara çevirirdim,

Titreyen dudaklarına ilk öpücüğü ben,

Sensizlik için ilk gözyaşını Yine,

Ben dökerdim.', 'Rüzgarla savrulan başak tarlasında, Filizlenen hüzünlerdeyim, Her savruluşta tohumlar can olup, Toprağa hayat  verir. Benim toprağa vereceği...', ARRAY['Türk Edebiyatı','Şiir','İnan Alver']::text[], 8.5, '{"poet":"İnan Alver","poet_slug":"i-nan-alver","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/huzunlerdeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git', 'git-mustafa-yigit-morpheus-gwejx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Boynumun bükük bırakıp gitme

Ne olur arkandan sitem ettirme

Şu fani dünyada acı çektirme

Önce beni öldür, sonra git

Umutsuzca yollara düşmeyeyim

Sensiz bu alemi hiç görmeyeyim

Sensiz ben cenneti neyleyim

Cehenneme at, sonra git

Dünya malı görünmez gözümde

İnan yalan yoktur sözümde

Resminin hayali gitmez gözümde

Gözlerimi kör et, sonra git

Dünya servetini artık istemem

Sensiz rüyalarımda bile gülemem

Akan gözyaşlarımı yalnız silemem

Gözyaşlarımı sil, sonra git

 Mustafa Yiğit (Morpheus)', 'Boynumun bükük bırakıp gitme Ne olur arkandan sitem ettirme Şu fani dünyada acı çektirme Önce beni öldür, sonra git Umutsuzca yollara düşmey...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/git-72-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmeseydin', 'gitmeseydin-mustafa-yigit-morpheus-w8twy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne hayaller kurardım senden uzakta

Mutlu olurdum seni hatırladıkca

O güzelliğini unutmazdım yaşadıkça

Eğer sen beni bırakıp gitmeseydin

Dislerine kapanır yalvarırdım sana

Nelerimi vermezdim senin uğruna

İdam etselerde alışamazdım yokluğuna

Eğer sen beni bırakıp gitmeseydin

Gözlerim her yerde seni arardı

Kalbim yalnız aşkın ile atardı

Dünyama güneş senin ile doğardı

Eğer sen beni bırakıp gitmeseydin

Mutlu olurdum ömrümün her saniyesinde

Yalnız seni arardım sevgi denizinde

Hiç üzülmezdim aşkın uğruna ölsem bile

Eğer sen beni bırakıp gitmeseydin

Gülüşünle güller açar, bülbüller öterdi

Şu gönlüm kül olsada yine seni severdi

Kalbim senisiz olmayı ömür boyu istemezdi

Eğer sen beni bırakıp gitmeseydin

 Mustafa Yiğit (Morpheus)', 'Ne hayaller kurardım senden uzakta Mutlu olurdum seni hatırladıkca O güzelliğini unutmazdım yaşadıkça Eğer sen beni bırakıp gitmeseydin Disl...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gitmeseydin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin', 'gittin-mustafa-yigit-morpheus-l84nr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerin yok mu, o kara gözlerin

Kalbimi yaralayan o sözlerin

Bilsen seni ne kadar özledim

Kuru odun gibi, yaktında gittin

Oysa ben sana kalbimi vermiştim

Bırakıpta beni gitmez demiştim

İnan bütün benliğimle sevmiştim

Yüzüme bile, bakmadan gittin

Senin uğruna nelerimi vermezdim

Gönlümü halı yapar yoluna sererdim

Senden tatlı bir söz beklerdim

Çok acı sözler, ettinde gittin

Benim perişan halimi hiç görmedin

Yanan kalbimi aşkınla söndürmedin

Garip Durağı dünyada güldürmedin

Cehennem ateşine attında gittin

 Mustafa Yiğit (Morpheus)', 'Gözlerin yok mu, o kara gözlerin Kalbimi yaralayan o sözlerin Bilsen seni ne kadar özledim Kuru odun gibi, yaktında gittin Oysa ben sana kal...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gittin-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlüm Serseri', 'gonlum-serseri-mustafa-yigit-morpheus-91x68', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beni benden alıp eyledin virasn

Senin o güzelliğine olurum kurban

Haykırışlarımı ah bir duysan

Geçmeyen yaramın melhemi olsan

Bir gülüşü ile eyledi deli

Güzeldir yüzü, incedir beli

Yalnız ona verdim kalbimi

Onun sevgisi ile gönlüm serseri

Gittiğim her yerde onu ararım

Her güneş doğuşunda ufka bakarım

Gece gündüz durmadan ağlarım

Avunması için gönlüme taş basarım

Gönlüm bir serseri gezer avare

Onun aşkı ile oldum divane

Sevdim onu bütün benliğimle

Ah çekip ağlarım boş yere

 Mustafa Yiğit (Morpheus)', 'Beni benden alıp eyledin virasn Senin o güzelliğine olurum kurban Haykırışlarımı ah bir duysan Geçmeyen yaramın melhemi olsan Bir gülüşü ile...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gonlum-serseri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eymir Güzeli', 'eymir-guzeli-mustafa-yigit-morpheus-fu2mm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ceylan gibi geziyorsun

Etrafına mutluluk saçıyorsun

Ama halimi hiç anlamıyorsun

Çok duygusuzmuşsun eymir güzeli

Senin güzelliğine bağlanmıştım ben

Ama hiç ümit vermiyorsun sen

Seni nasıl seviyorum bir bilsen

Halimi o zaman anlardın eymir güzeli

Şimdiye kadar hiç dinlemedin beni

Beni görünce gülümseyip girdin içeri

Her akşam görüyorum senin hayalini

Beni senden mahrum etme eymir güzeli

Çok güzelsin inan çiçek gibisin

Bir daha gülümsede ruhum sevinsin

Gecem gündüzüm her eşyim sensin

Hayatımın güneşi ol eymir güzeli

Seni üzemem ben Allah''dan korkarım

Seni seviyorum derken inan utanırım

Umut vermediğin garip aşığınım

Umutsuzluğa düşürdün eymir güzeli

Garibim diye bana hiç bakmadın

Hareketlerimden sevdiğimi anlamadın

Durağım seni bir türlü anlayamadım

Garipler insan değilmi eymir güzeli

 Mustafa Yiğit (Morpheus)', 'Ceylan gibi geziyorsun Etrafına mutluluk saçıyorsun Ama halimi hiç anlamıyorsun Çok duygusuzmuşsun eymir güzeli Senin güzelliğine bağlanmışt...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/eymir-guzeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benden Şair Olmaz...', 'benden-sair-olmaz-halil-kesken-rcnih', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Herkesi, herşeyi sevmeli şair,

Nasıl olduğunu iyi bilirim.

Kimseyi sevmedim kalemim kadar

Benden şair olmaz, özür dilerim...

Okyanusa atın dizelerimi,

Evimden toplatın kalemlerimi,

Okumadan yakın şiirlerimi,

Benden şair olmaz, özür dilerim...

Aşkımı kağıda dökemiyorsam,

Ruhumu şiire ekemiyorsam,

Sevdiğim uğruna ölemiyorsam,

Benden şair olmaz, özür dilerim...

Şiir sevmeyeni hoş görmedikçe

Yoluma gül değil, taş sermedikçe

Haksız görene de hak vermedikçe

Benden şair olmaz, özür dilerim...', 'Herkesi, herşeyi sevmeli şair, Nasıl olduğunu iyi bilirim. Kimseyi sevmedim kalemim kadar Benden şair olmaz, özür dilerim... Okyanusa atın d...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/benden-sair-olmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül', 'gonul-mustafa-yigit-morpheus-4sy54', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yollara çıkıpta bekleme boşuna

O gitti bir daha dönmeyecek

O beni bırakmaz diye bekleme

Terketti artık seni, dönmeyecek

Gidereken her şey bitti demişti

Bu sevgi artık sona ermişti

Her şeyiyle seni bırakmıştı

Sever diye bekleme, sevmeyecek

Günler geçti seni hiç aramadı

Uzaktan selam dahi yollamadı

Sen yaklaştıkca o uzaklaştı

Onu sevdiğini bilmedi, bilmeyecek

Garip Durağı dinle gönlüm

Hep dert çekmekle geçti ömrüm

Onun aşkı ile ölürsem bir gün

Niçin öldü diye sormadı, sormayacak

 Mustafa Yiğit (Morpheus)', 'Yollara çıkıpta bekleme boşuna O gitti bir daha dönmeyecek O beni bırakmaz diye bekleme Terketti artık seni, dönmeyecek Gidereken her şey bi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gonul-66-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gördün mü?', 'gordun-mu-mustafa-yigit-morpheus-frca7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Vurulmuş yüreğinden yaralı gezer

Sekerek kaçan ceylanı gördün mü? 

Aşk pınarından kanarak içer

Sevdasına koşan ceylanı gördün mü? 

Dağ başında süzülerek giden

Gördüğü gözleri yerle bir eden

Kartal misali havada süzülen

Uçarak giden ceylanı gördün mü? 

Kayalarda sekerek gidişi vardı

Yıllarca yağmamış bir ahuzardı

Eeline geçirse beni boğardı

Aşkını arayan ceylanı gördün mü? 

Hüzünle arardı hep dağlarda

Aşk gülünü ekerdi gönül bağında

Hasretine dayanamadı Garip Durakta

Kınalı kuzusu, ceylanını gördün mü?

 Mustafa Yiğit (Morpheus)', 'Vurulmuş yüreğinden yaralı gezer Sekerek kaçan ceylanı gördün mü?  Aşk pınarından kanarak içer Sevdasına koşan ceylanı gördün mü?  Dağ başın...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gordun-mu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet Akşamları', 'gurbet-aksamlari-mustafa-yigit-morpheus-eqlun', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Üzerime kabus gibi geldiniz

Beni benden alıp gittiniz

Bir umut ışığı bile bırakmadınız

Mezarım oldugunu gurbet akşamları

Yalnız başıma Ankara''da dünyam karardı

Mektup yazayım dedim ellerim bağlandı

Gülmek istedim ama bırakmadı

Tabutum oldugunuz gurbet akşamları

Gurbetlik meğerse ne kadar zormuş

Mutluluğun yerini hasretlik almış

Her yanımı büyük bir özlem sarmış

Hayatımı zehir ettiniz gurnet akşamları

Hatıralara dalayım dedim bırakmadınız

Günün 24 saatinde hep ağlattınız

Durağa hiçbir zaman acımadınız

Yaşarken öldürdünüz gurbet akşamları

 Mustafa Yiğit (Morpheus)', 'Üzerime kabus gibi geldiniz Beni benden alıp gittiniz Bir umut ışığı bile bırakmadınız Mezarım oldugunu gurbet akşamları Yalnız başıma Ankar...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gurbet-aksamlari-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet', 'gurbet-mustafa-yigit-morpheus-72psy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni sevdiklerimden ayırdığın yetmedi mi? 

Gençliğimi zehir ettiğin yetmedi mi? 

Bir çiçek gibi soldurduğun yetmedi mi? 

Daha benden ne istiyorsun gurbet

Bir kurt gibi içten çürüttün beni

Söyle bana nasıl seveyim seni

Anlayamıyorum senin bu kinini

Söyle nasıl öveyim seni gurbet

Buradakilerin hepsi dert küpü

İnan hasretlik belimi büktü

Yetimmi bırakmak istersin öksüzmü

Neyini seveyim ben senin gurbet

İki dağ arasına sıkışmış ihtişamın 

Sen kendini çokmu büyük sandın

Dünya parası ile beş kuruş etmez fiyatın

Sus, konuşma yeter artık be gurbet

 Mustafa Yiğit (Morpheus)', 'Beni sevdiklerimden ayırdığın yetmedi mi?  Gençliğimi zehir ettiğin yetmedi mi?  Bir çiçek gibi soldurduğun yetmedi mi?  Daha benden ne isti...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gurbet-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbetlik', 'gurbetlik-mustafa-yigit-morpheus-hps63', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aramızda aşılmaz dağlar var

Bizi birbirimizden ayırdı bu gurbetlik

Aramızda ulaşılmaz yollar var

Beni yaşarken öldürdü bu gurbetlik

Benim halimi hiçbir zaman anlamadı

Hep ağlattı henüz hiç güldürmedi

Garipleri hiçbir zaman sevindirmedi

Yaşarken mezara koydu bu gurbetlik

Sen neredesin ben neredeyim

İzin vermiyorki sana geleyim

Senin yokluğunda bir divaneyim

Hasretinle yalnız bıraktı bu gurbetlik

Hasretin yüreğimi parçalar

Derdim çoktur yüce dağlar kadar

Halimi görse bulutlar ağlar

Ama halimi anlamadı bu gurbetlik

Hayalin gözümden hiç gitmiyor

O sevdan yüreğimde bitmiyor

Durağım artık gücüm yetmiyor

Saçlarıma kar yağdırdı bu gurbetlik

 Mustafa Yiğit (Morpheus)', 'Aramızda aşılmaz dağlar var Bizi birbirimizden ayırdı bu gurbetlik Aramızda ulaşılmaz yollar var Beni yaşarken öldürdü bu gurbetlik Benim ha...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gurbetlik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbeteller Aldı', 'gurbeteller-aldi-mustafa-yigit-morpheus-jevib', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşk,

Mahsende kilitli yıllanmış şarap gibi

Çok özledim seni

Eğer istiyorsan beni

Ne olur,

Ne olur gel sar beni

Biliyorum olmaz dersin

Bana bu yakışmaz

Biz sevgimizi gönülde

Aşkımızı kalbimizde hissederiz

Biz entel takılamayız

Aşkımızı sokakta 

Avazımız çıkana kadar

Haykıramayız.

Biz gönlümüzde yaşayan

Kalplerimizde okyanus misali

Dalga olup coşan

Gözyaşımızla sulayıp

Büyüttüğümüz

Sevgi çiçeklerimizi

Diskolarda arayamayız

Biz! ...

Kanımızla suladığımız

Uğruna baş koyduğumuz

Ne diyebilirim ki! 

Gönlümüzün sultanını

Gül bahçelerinde

Beklemek isteriz.

İsterse,

Bize ihanet etsin

Biz yine de

Ölümüne sevenlerdeniz.

Sus konuşma bana 

Aşk perisi

Sorma sakın olanları

Dinleyemem 

Aartık o yalanları

Beni seviyormuş

Beni özlüyormuş

Ne yazar

Şimdide onu benden

Gurbeteller aldı

 Mustafa Yiğit (Morpheus)', 'Aşk, Mahsende kilitli yıllanmış şarap gibi Çok özledim seni Eğer istiyorsan beni Ne olur, Ne olur gel sar beni Biliyorum olmaz dersin Bana b...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/gurbeteller-aldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm', 'gulum-mustafa-yigit-morpheus-mx5l7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biz aşkı kadehlerde içenlerden değiliz

Biz aşkı ölümüne yaşayanlardanız gülüm

Biz sevdayı diskolarda arayanlardan değiliz

Biz sevdayı gönüllerde bulanlardanız gülüm

Biz bilmeyiz ışıklı salonlarda eğlenmeyi

Biz bilmeyiz sevdiğine ihanet etmeyi

Biz bilmeyiz her gün başka kızlarla gezmeyi

Biz sevdiği için ölüme gidenlerdeniz gülüm

Biz ayrılık hasretini kalbimize gömdük

Gönlümüzün sultanını herşeyimiz ile sevdik

Biz ihanetin acısını kalbimizde yaşadık

Biz aşk ateşi ile yananlardanız gülüm

Ferhat aşkı için dağları delmedi mi? 

Mecnun yâri için çöllere düşmedi mi? 

Kerem Aslısı için tutuşup yanmadı mı? 

Biz aşk bahçesinde sevgisiz kalanlardanız gülüm

Biz hasretlik ile dağlara çıkanlardanız

Biz turnalarla selam yollayanlardanız

Biz kalabalıkda yalnız kalanlardanız

Biz gönül bahcesinde gülenlerdeniz gülüm

 Mustafa Yiğit (Morpheus)', 'Biz aşkı kadehlerde içenlerden değiliz Biz aşkı ölümüne yaşayanlardanız gülüm Biz sevdayı diskolarda arayanlardan değiliz Biz sevdayı gönüll...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gulum-93-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-mustafa-yigit-morpheus-4cu7h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Oturdum köşeye seni yaşadım

Belki bir gün gelir kavuşuruz diye

Oturduğum yerde saatlerce ağladım

Biz neden ayrıldık, sebep ne diye

Selvi boylum kurtar artık hasretinden

Olalım yine eskisi gibi seninle bir beden

Beni artık olduğum gibi kabul et istersen

Belki gün gelirde mutlu oluruz diye

Siyah saçlım, kara gözlüm her şeyimsin sen

Yeniden filizlenip büyüyen aşkımsın sen

Yıllardır bulamadığım mutluluk tacımsın sen

Ümitsizliğe kapılmadan arıyorum bulurum diye

İnce bellim, güzel huylum gel artık bana

Sen bana niçin inanmıyorsun inan artık aşkıma

Ben durmadan arıyorum uzaklarda

Gün gelir belki karşıma çıkar diye

 Mustafa Yiğit (Morpheus)', 'Oturdum köşeye seni yaşadım Belki bir gün gelir kavuşuruz diye Oturduğum yerde saatlerce ağladım Biz neden ayrıldık, sebep ne diye Selvi boy...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hasret-184-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Meydana', 'bu-meydana-sabit-i-nce-1dlff', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '-Usta hicivci Rasim Köjroğlu''na-

Aşığım sazım elimde, 

Köroğluca gel meydana, 

Hak kelamıdır dilimde, 

sözlerim gül bu meydana. 

Akılım kendime yetmez, 

efkarım başımdan gitmez, 

söyle söyle sözüm bitmez, 

deryalarca dol meydana. 

Ceylanlar hep ürkek olur, 

nider eder bir yol bulur, 

Köroğlu''ndan ilham alır, 

Bazen dalar şol meydana. 

Klavuz arar dururum, 

dostlara rehber olurum, 

istersen Ayvaz olurum, 

sererim şal bu meydana. 

Kellik hakdan değil ona, 

saç mı kalır yana yana, 

Sen eline yak bir kına, 

İsmailce dol meydana. 

Bolat boş yatmaz Kemer''de, 

Çoşar durur kan damarda, 

Kim kazanır bu kumarda, 

Ustaları sal meydana. 

Köroğlu''sun namın yüce, 

Uyutmadın gece gece, 

İnce sorar halin nice, 

olurum kul bu meydana. 

SABİT İNCE Kayseri', '-Usta hicivci Rasim Köjroğlu''na- Aşığım sazım elimde,  Köroğluca gel meydana,  Hak kelamıdır dilimde,  sözlerim gül bu meydana.  Akılım kend...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bu-meydana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Düzer Ölüm', 'huzun-duzer-olum-necmi-unsal-e69i5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ömrün satıldığı hayat çarşımızda,

En değersiz maden, mat  sim-ü zer ölüm.

Her an bitiverir dimdik karşımızda.

Kalanları acı ile üzer ölüm.

Bu acı gerçekle gülen yüzler solar.

Şakrak dudakları gamla büzer ölüm.

Umutsuz bir visal yüreklere  dolar.

Ağıtlara yaslı hüzün düzer ölüm.

Aramızda seyran eder  gemisiyle.

Ömür denizinde mertçe  yüzer ölüm.

Sohbettedir, sükut eder  kimisiyle.

Bazımızı ilgi ile süzer ölüm.

9 Haziran 2004 Çarşamba, Danimarka-Køge 19.18

6+6', 'Ömrün satıldığı hayat çarşımızda, En değersiz maden, mat  sim-ü zer ölüm. Her an bitiverir dimdik karşımızda. Kalanları acı ile üzer ölüm. B...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/huzun-duzer-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalin', 'hayalin-mustafa-yigit-morpheus-3lcnr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir hüzün kapladı içimi

Her yerde sen varsın

Çalıştığım odada

Koğuşta ve yattığım ranzada

Hayalin kaplıyor tüm alemi

Aağaçlarda, kuşlarda

Ufukta sen varsın

Bana mahsunca bir

Bakışın varki

Vücudum eriyor sanki

Hafifce gülümseyip

Boşluğu gösteriyorsun! 

Karanlığın odak noktasında

Senin hayalin gözümün önüne geliyor

Beyaz bir gelinlik giymişsin

Gelinlik! ...

Sana öyle yakışmış ki,

Sanki bir çiçek gibisin

Gel artık! ..

Fazla bekletme gel

Diyorsun! ...

Seni ölesiye sevdim

Ne olur

Sende beni sev diyorsun.

 Mustafa Yiğit (Morpheus)', 'Bir hüzün kapladı içimi Her yerde sen varsın Çalıştığım odada Koğuşta ve yattığım ranzada Hayalin kaplıyor tüm alemi Aağaçlarda, kuşlarda Uf...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hayalin-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Yılları', 'huzun-yillari-mustafa-yigit-morpheus-5nmwi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hava sıcak, rüzgarın soluk alışı kesildi

Ufukta sessizce hayalin belirdi

Sanmaki divane gönlüm yine delirdi

Sensizmi geçecek hüzün yılları

Bak seni bekliyorum hiç uyumadan

Mektubunu soruyorum her gelen postadan

Usandım artık inan ağlamaktan

Sensizmi geçecek hüzün yılları

Bırakma beni dert küpünde yalnız başıma

Sen iste yeterki, hemen koşarım sana

Gonca güller takarım, o ipek saçlarına

Sensizmi geçecek hüzün yılları

Gözümden hayalin hiç silinmiyor

Verdiğin o sözler artık tesellim olmuyor

Kalbim artık resminle avunmuyor

Sensizmi geçecek hüzün yılları

 Mustafa Yiğit (Morpheus)', 'Hava sıcak, rüzgarın soluk alışı kesildi Ufukta sessizce hayalin belirdi Sanmaki divane gönlüm yine delirdi Sensizmi geçecek hüzün yılları B...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/huzun-yillari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yozgat Güzeli', 'yozgat-guzeli-mustafa-yigit-morpheus-ps2ao', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüreğimi yaktı benim

Her yerde arar oldu gözlerim

Yalnız ona bağlandı kalbim

Kalp hırsızıdır yozgat güzeli

Elinde testisi pınara gider

Bir bakışı beni divane eder

Bütün kötülükleri ezerde geçer

Sanki bir melektir yozgat güzeli

Bir gülüşü ile güller açıyor

Eerafına hep neşe saçıyor

Tertemiz hislerle bir kalp taşıyor

İçmeden sarhoş eder yozgat güzeli

Aşıkları çoktur gezer peşinde

İsmi hiç düşmez her an dillerde

Rengarenk giyinir, ince belinde

Kırmızı kuşak taşır yozgat güzeli

Başında eşarbı elinde kına

Kurban olurum o selvi boyuna

Hafifden gülümseyip kendi yoluna

Salınarak gider yozgat güzeli

Durağım anlatamam aşkımı

Dünyalara değişmem bir tel saçını

Gönülden sevdiği gerçek aşkını

El üstünde tutar yozgat güzeli

 Mustafa Yiğit (Morpheus)', 'Yüreğimi yaktı benim Her yerde arar oldu gözlerim Yalnız ona bağlandı kalbim Kalp hırsızıdır yozgat güzeli Elinde testisi pınara gider Bir b...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yozgat-guzeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstek', 'i-stek-mustafa-yigit-morpheus-g6h10', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gün öldüğümde mezar taşıma

Bir garip oğlandı diye yazsınlar

Hep sevdi ama hiç sevilmedi

Güller içerisinde bir dikendi yazsınlar

Ömrünce ağladı güldüğü görülmedi

Hep çile çekti hiç mutlu olmadı

Dertlerine derman bulamadı

Garip bir çilekardı yazsınlar

Bir sevdiği kız vardı ihanet etti

Mutluluklarının hepsini alıp gitti

Mutluluk göstermedi hep çile verdi

Yaşarken mezara koydu yazsınlar

Dünya nimetlerinden yararlanmadı

Hep gezerdi Garip Duraktı adı

Yalnızca seven bir kalbi vardı

Henüz 30 yaşında öldü yazsınlar

 Mustafa Yiğit (Morpheus)', 'Bir gün öldüğümde mezar taşıma Bir garip oğlandı diye yazsınlar Hep sevdi ama hiç sevilmedi Güller içerisinde bir dikendi yazsınlar Ömrünce ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/istek-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koltuklar', 'koltuklar-orcun-oruc-aykac-jvh0v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Merhaba destursuz tozlu adımlarına.

Hoş geldin hüzün! 

Sil ayaklarını kirlenmiş tenime.

Gel yanıma, gel, öyle kal aklımda 

Yüreğimin ortasında senin koltuğun.

İkramım bir avuç gözyaşı…

Dur, sakın sevinme,sil gözlerindeki sevinci! 

Bu koltuklar da hüküm vazgeçilmez…,rahattır.

Ama bir bilsen ne cesetler topladım ben içimdeki odalardan.', 'Merhaba destursuz tozlu adımlarına. Hoş geldin hüzün!  Sil ayaklarını kirlenmiş tenime. Gel yanıma, gel, öyle kal aklımda  Yüreğimin ortasın...', ARRAY['Türk Edebiyatı','Şiir','Orçun Oruç Aykaç']::text[], 8.5, '{"poet":"Orçun Oruç Aykaç","poet_slug":"orcun-oruc-aykac","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/koltuklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İster', 'i-ster-mustafa-yigit-morpheus-kre6r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gel arkadaş soframızı donatalım

Bugün divane gönlüm içmek ister

Şöyle beraberce bir dertleşelim

Dertli gönlüm kendinden geçmek ister

Yaralarım eski değil çok yeni

En yakın bildiğim öldürdü beni

Çok iyi dinle şu sözlerimi

Kalbim sarhoş olup uçmak ister

Fazla konuşup yaramı deşme

İyileşirim diye sakın bekleme

Benden artık mutlu olmamı isteme

Artık fani vücudum ölmek ister

Ölmek daha kolay geliyor bana

En yakınlarım darbe vuruyor bana

Ne olur sus artık allah aşkına

Gönlüm bu dünyadan gitmek ister

Durağım yaralarım kanıyor

Akrabalarım gelmiş mezarımı kazıyor

Annem oturmuş ağıtlar yakıyor

Bedenim kaybolup yitmek ister

 Mustafa Yiğit (Morpheus)', 'Gel arkadaş soframızı donatalım Bugün divane gönlüm içmek ister Şöyle beraberce bir dertleşelim Dertli gönlüm kendinden geçmek ister Yaralar...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ister-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayşe kız', 'ayse-kiz-seyhmus-sait-aydin-711ji', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Azap Ramazanın kızı oldu dediler

Soğuk höllüğe belediler

Dogduğunda çileydi alın yazısı

Yoktu anansının sütü 

Ala inegin

sütüyle beslediler. 

Ayşe anamız gibi kısmetli olsun diye

Adına ayşe dediler

Baba el kapısında azap

Sabah beş akşam sekiz çalışmakta,

kışın koyun kuzu mal,davar,

Baharda,ot, çayır

yazları ekin ekenekte

Zamanla yarışmakta

Bir yıl hasan aganın kapısında

bir yıl mehmet aganın

sekizine basınca anladı

zorlugunu süt sagmanın,

tezek yapmanın.

.

hani adını ayşe koymuşlardı

haniya bol olacaktı kısmetin

Bahtı açık kısmeti bol 

Ayşe Kızı olacaktın memleketin

.

Okuma yazma netsin ayşe kız

Babası azap,

Anası ırgat

Okul onun neyine 

Alfabesi olmazki

Aga kapısında yetişen beslemenin.

Beliklerine Güneşin sarısını ördü anası

Gögüslerinde Anadolu ayvası

Ve mahzun gülüşlerle buzülen dudaklarında

Kiraz meyvası.

Yaş onbeş

Başında ergenlik sevdası.

Aganın genç çobanı

Gözleri siyah’mı siyah 

kömür karası

Yanakları al al

Ayşeyle yatar ayşeyle kalkar

Azap ramazanın kızıdır 

uykularında gördüğü tüm rüyası

çobandır kendisi ama

Azap ramazandan neyi eksik

Çobanlıktır meslegi

Bugüne bugün altın bilerzik

Davarı suya indirirken

kavalıyla çaldıgı nagme

Akşam olup sürü 

yaklaştıgında köye

Hep ayşeye seslenir ezik mi ezik.

‘’Altın saçlarına gönül bagladım

Sevdicegim beni Anla nolursun

Aşkımı kavalla seslemdiririm

Gönlüme gönlünü bagla nolursun.; ; 

Ayşenin umrunda degil

Ne yanık yanık çalan kavalın sesi

Nede kendine seslenen çoban bestesi.

Ayşe hülyalarda

Ayşe başka Dünyalarda

Ayşe,aganın evinde seyretmiş dizileri

Nesine gerek çobanın ezgileri

Serpildikçe serpiliyor ayşe kız

Sarı saçlar mavi gözler bir afet

Çoban dahil tüm köy genci yanıyor

Yaş on dokuz,

Ayşe kız’ sa bir afet.

Cobanı hiç görürmü gözü

İnsan gibi yaşamı istiyor özü.

Büyük bir şeherde yaşamaktır hülyası

Babayı azaplıktan kurtarmak

Anayı ırgatlıktan

Sevdiği bir erkek  olsun kocası

Birkaç cocuk

İnsan gibi yaşamaktır rüyası

Sabahın seherinde birgün

Takıyor bohçasını koluna

Atıyor kendini şeher yoluna,

Bindiği otobüsün şöförüne veriyor ilk meyvasını

Sonra kaldıgı otel katbine

Şimdi Ayşe kız otuz yaşında

Ve

Hatırlamak istemiyor ilk günden sonrasını.

Nice ilden ile atıldın

Rüyan gerçek olmadımı Ayşe kız

Nice hal bilmeze satıldın

Hala çilen dolmadımı ayşe kız.

            

04.078.2004', 'Azap Ramazanın kızı oldu dediler Soğuk höllüğe belediler Dogduğunda çileydi alın yazısı Yoktu anansının sütü  Ala inegin sütüyle beslediler....', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sait Aydın']::text[], 8.5, '{"poet":"Şeyhmus Sait Aydın","poet_slug":"seyhmus-sait-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":90,"source_url":"https://www.antoloji.com/ayse-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm bile korkuyor', 'olum-bile-korkuyor-seyhmus-sait-aydin-pq76v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her sözümün başında seni sevgiyle andım 

En ufak siteminde cehennem olup yandım 

Ben merhamet dedikçe sen yarama tuz bandın 

Tenine dokunmaktan elim bile korkuyor. 

Keremi hara yakan aslıdan da betersin 

Ferhata dag deldiren şirin misin sen nesin 

yar merhamet dedikçe arşa yükseldi sesim 

Sana canım demekten dilim bile korkuyor. 

Çektirdiğin cefadan bıktım usandım artık 

Zulmün ile kavruldum,piştim,uslandım artık 

Azraile yakardım gelsin alsın bu canı 

Verdiğin acılardan ölüm bile korkuyor.

18.07.2004', 'Her sözümün başında seni sevgiyle andım  En ufak siteminde cehennem olup yandım  Ben merhamet dedikçe sen yarama tuz bandın  Tenine dokunmak...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sait Aydın']::text[], 8.5, '{"poet":"Şeyhmus Sait Aydın","poet_slug":"seyhmus-sait-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/olum-bile-korkuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerimi Kapatıyorum', 'gozlerimi-kapatiyorum-umit-akkemik-fu5je', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerimi kapatıyorum

Denizin içindeki derinliklere dalabilmek için

Gözlerimi kapatıyorum

Her bir canlının seni bana anlatması için

Gözlerimi kapatıyorum

Gökyüzündeki yıldızlara...

Yıldızlar... Yoklar, orada değiller

Gözlerim kapalı belki ama,

Orada olduklarını görebiliyorum

Belki onlar da denizin taa dibindedirler..

Seni anlamak için

Yoo,hayır seni ancak ben anlarım

Yıldızlar bile değil

Gözlerimi kapatıyorum

Yoruluyorum,yıpranıyorum

Gözlerimi kapatıyorum

Bu kez açmamak için.', 'Gözlerimi kapatıyorum Denizin içindeki derinliklere dalabilmek için Gözlerimi kapatıyorum Her bir canlının seni bana anlatması için Gözlerim...', ARRAY['Türk Edebiyatı','Şiir','Ümit Akkemik']::text[], 8.5, '{"poet":"Ümit Akkemik","poet_slug":"umit-akkemik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gozlerimi-kapatiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümü Anlat bana', 'olumu-anlat-bana-seyhmus-sait-aydin-c35gz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çölde kalmış sararmış kuruyan bir dal iken 

Göz yaşımla sulayıp tomurcuk gül yaptıgım 

Ömür boyu ömrümden ömür verip baktıgım 

Bir inada yoldugun,gülümü anlat bana 

Ellerimle oşayıp saçına öykü yazdım 

Gözlerinin rengine binlerce mısra dizdim 

Ölürcesine sevdim,Ama nazından bezdim. 

Nazdan geri ne kaldı, nazını anlat bana 

Sana taptım dedikçe sen hep yokuşa sürdün 

Bense yürekten sevdim,sen bana acı verdin 

Acıma dert ekledin bıyık altından güldün 

Bunlar zulüm degilse, zulümü anlat bana 

Sen bana güldüğünde gönlüm bahar olurdu 

Zemheri ayazında vucudum har olurdu 

Önce yagmur yagarda sonrası yaz olurdu 

Gözümden akan yaşı, selimi anlat bana 

Bunca cefa çektirdin yinede uslanmadın 

Seni seven şu gögse bir defa yaslanmadın 

Öyle acı verdinki ölüm bile vız gelir 

Bu acı yetmiyorsa ölümü anlat bana. 

02.07.2004', 'Çölde kalmış sararmış kuruyan bir dal iken  Göz yaşımla sulayıp tomurcuk gül yaptıgım  Ömür boyu ömrümden ömür verip baktıgım  Bir inada yol...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sait Aydın']::text[], 8.5, '{"poet":"Şeyhmus Sait Aydın","poet_slug":"seyhmus-sait-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/olumu-anlat-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çarmıha gerilmiş İsa gibiyim', 'carmiha-gerilmis-i-sa-gibiyim-seyhmus-sait-aydin-fnjhs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çarmıha gerilmiş İSA gibiyim 

Asası kaybolmuş musa gibiyim 

Mezar kabul etmez nere gideyim 

Yar gögsünü mezar eyle koy beni 

Yadına düşmüşüm yakta kor eyle 

Ne istersin bu garipten,sor,söyle 

Yaşanmazki sevdicegim bu böyle 

Kulun olan kölelerden say beni 

Kan yerine dolaşırsın kanımda 

Ben yok oldum sen yaşarsın canımda 

Musallsa taşında tekbir anında 

İanmazsan hocalara sor beni 

Hakkın helal etme o son durakta 

Mezarıma gelme dur sen ırakta 

Öldüm artık şu nazını bırakta 

Sana zahmet fatihayla an beni. 

19.07.2004', 'Çarmıha gerilmiş İSA gibiyim  Asası kaybolmuş musa gibiyim  Mezar kabul etmez nere gideyim  Yar gögsünü mezar eyle koy beni  Yadına düşmüşüm...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sait Aydın']::text[], 8.5, '{"poet":"Şeyhmus Sait Aydın","poet_slug":"seyhmus-sait-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/carmiha-gerilmis-isa-gibiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsterim', 'i-sterim-mustafa-yigit-morpheus-d0qzv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen bir ömre bedelsin inan

Her anımı seninle yaşamak isterim

Öyle güzelsinki tıpkı melek gibisin

Senin sevginle çölde kalmak isterim

Sensiz büyuük bir konakda değil

Sensiz ihtişamlı şatoda değil

Sensiz gösterişli şatoda değilL

Seninle bir kulübede yaşamak isterim

Sensiz dünyayı ben neyleyim

Sensiz yeryüzünü nasıl göreyim

Sensiz gül bahçesini hiç istermiyim

Seninle dağ başında kalmak isterim

Sen olmadan cennetde yaşamak değil

Senden uzakda güzel kızlarla gezmek değil

Başkasının elinden aşk şarabını içmek değil

Aşkınla cehennemde yanmak isterim

 Mustafa Yiğit (Morpheus)', 'Sen bir ömre bedelsin inan Her anımı seninle yaşamak isterim Öyle güzelsinki tıpkı melek gibisin Senin sevginle çölde kalmak isterim Sensiz ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/isterim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Kalbimi Hapsettim', 'ben-kalbimi-hapsettim-seyhmus-sait-aydin-4qfkq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben sevince uğruna ölmeliyim bil bunu 

Benim sevgim derrindir anlatamaz dil bunu 

Öyle bir yanışki bu söndüremez sel bunu 

Eski volkan tutuştu,ahh yenisi kül artık. 

Ben gönlümü hapsettim,Kapıları kapattım 

Seni bana baglayan halatları koparttım 

Ayagıma paranga, kalbime zincir taktım 

Zincirleri kırıpta sana gelmek zor artık. 

mazimdeki tek aşkım seni belki yaralar 

Ben mazimi unutsam mazim beni kovalar 

Unuttum attım desem kalbim beni yargılar 

Mazimi unutupta senle olmam zor artık. 

Seni senden alıpta üzmek bana zor gelir 

Önce bahar olurda arkasından kar gelir 

Gönül başka severken senle olmak ar gelir 

Ben böyle yaşayamam beni anla gör artık. 

Andığım bu sevgiye Ben ömrümü vermişim 

Onda bahar yeşertip onda güller dermişim 

Söz vermişim bir defa,görülmemiş dönüşüm 

Sen bir başka bahar bul,beni senden sil artık 

25.03.2004', 'Ben sevince uğruna ölmeliyim bil bunu  Benim sevgim derrindir anlatamaz dil bunu  Öyle bir yanışki bu söndüremez sel bunu  Eski volkan tutuş...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sait Aydın']::text[], 8.5, '{"poet":"Şeyhmus Sait Aydın","poet_slug":"seyhmus-sait-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ben-kalbimi-hapsettim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahrolurum', 'kahrolurum-mustafa-yigit-morpheus-lwqfp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen gözkyüzünün parlak yıldızısın

Ben bilinmez yerlerin garip yolcusuyum

Sen büyük şehirlerin süslü kızısın

Ben dağların sefil çocuğuyum

Arama beni gül bahcelerinde

Ben diken ağaçlarının umuduyum

Boğma sakın beni aşk denizinde

Ben ayrılık deryasında boğulurum

Gülme sakın bana al yazmalım

Sonra sana kalpten vurulurum

Üzülme sakın pembe yanaklım

Yaşadıkca ben kahrolurum

Sakın kalbini bana verme

Orada mutluluğu bulurum

Beni sılada bırakıp gitme

Gurbette yalnız başıma kahrolurum

 Mustafa Yiğit (Morpheus)', 'Sen gözkyüzünün parlak yıldızısın Ben bilinmez yerlerin garip yolcusuyum Sen büyük şehirlerin süslü kızısın Ben dağların sefil çocuğuyum Ara...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kahrolurum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hele Dur bir bakalım', 'hele-dur-bir-bakalim-seyhmus-sait-aydin-gigxw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hele dur bir bakalım, dün birdi bugün iki

Sevgi zamana muhtaç,Aşk ta olacak belki

Beni iyce tanıyıp,tanıyıpta sev beni,

Sen kendini yakmışın, benide yakarmısın

Bugün diktiğin fidan,Yarın çiçek verirmi

Daha kökün salmadan bedeni güverirmi,

Buz ateş görmeyince bir lahzada erirmi,

İçimdeki ateşi söndürecek kar mısın

Benim yüregim volkan,Ateş olur lav olur

Kıymetini bilene,Bahçe olur bag olur

Bazen deli bir rüzgar eser eser savrulur

Sende durulacagım  sakin bir limanmısın.

Gönlüm şimdi coşmada çılgınca kabarıyor

Nereye demirlesem beni hüzün sarıyor

Ömrünce baglanacak sakin liman arıyor

Bu liman sen olupta,Bagrına basarmısın.

24.03.2004', 'Hele dur bir bakalım, dün birdi bugün iki Sevgi zamana muhtaç,Aşk ta olacak belki Beni iyce tanıyıp,tanıyıpta sev beni, Sen kendini yakmışın...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sait Aydın']::text[], 8.5, '{"poet":"Şeyhmus Sait Aydın","poet_slug":"seyhmus-sait-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hele-dur-bir-bakalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaldı', 'kaldi-mustafa-yigit-morpheus-up1ib', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çöllerde gözyaşım ile yetiştirdiğim

Gönül gözüm ile görüp sevdiğim

Canımı uğruna feda ettiğim

Umudum kaf dağının ardında kaldı

Onı görmesem gözüm dolardı

Kalbimde büyüttüğüm gülüm solardı

Ayrılık acısı ile gözüm ağlardı

Umudum kaf dağının ardında kaldı

Dudağı kiraz, yanakları elma

Her zaman muhtacım ona ve aşkına

Oondan ayrılalı döndüm şaşkına

Umudum kaf dağının ardında kaldı

Öyle bir bakardı yüreğimi yakardı

Sevdası ile aşk denizine atardı

Yanıma bin türlü dertler katardı

Umudum kaf dağının ardında kaldı

Gözyaşını görsem yüreğim parçalanır

Kalbim onu kendinden bile kıskanır

Vücudum hasreti iel her an ıslanır

Umudum kaf dağının ardında kaldı

Durağım hasretlik kaderin oldu

Gönül bahçende açan çiçeğin soldu

Hüzün, dert, keder hep seni buldu

Umudum kaf dağının ardında kaldı

 Mustafa Yiğit (Morpheus)', 'Çöllerde gözyaşım ile yetiştirdiğim Gönül gözüm ile görüp sevdiğim Canımı uğruna feda ettiğim Umudum kaf dağının ardında kaldı Onı görmesem ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kaldi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun degirmen', 'yorgun-degirmen-seyhmus-sait-aydin-fdpn4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gencecik tazeydim.

Taşımı ustam elleriyle dişlemişti

Suyum çağlayıp aktı,

Ne buğdayları un eyledim,

Ne bulgurlar öğüttüm

döndükçe Öğüttüm,

Öğüttükce yiğittim

Değirmendi adım,

Suyum aktıkça döndüm..

İki böğrüm iki domuzluk

Boş kaldıkça boğardı beni susuzluk.

Kara sevdalıydım,

Buğdaya, arpaya, yulafa

İnce oldu, kalın oldu,

Aldırmazdım boş lafa.

Kimi ekmeklik isterdi kimi çöreklik

Ne ayarlar verirdi bana ustam rahmetlik..

Ustam yaşlandı ben yaşlandım.

Suyumu türbünlere verdiler.

Ustamı mezar, Beni betonlar aldı,

Geçmişteki hizmetim geçmişte kaldı,

30.09.2003', 'Gencecik tazeydim. Taşımı ustam elleriyle dişlemişti Suyum çağlayıp aktı, Ne buğdayları un eyledim, Ne bulgurlar öğüttüm döndükçe Öğüttüm, Ö...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sait Aydın']::text[], 8.5, '{"poet":"Şeyhmus Sait Aydın","poet_slug":"seyhmus-sait-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yorgun-degirmen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-serdar-uzunoner-fvg3u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Takviminden dökülmemiş yapraktır ayrılık.

Kapı girişinde duvara asılı,

“Hoş geldin” yazılı bir tarla korkuluğu gibi

Dönüşünü dört gözle beklediğin özlemin gelir diye

Bir umut kırıntısı birikmiş yüreğinde.

Teninin vadisinde soğuk bir nehir gibi

Akarken kanın

Aşkının zirvesinden bırakmış kendini bir uçuruma

Senide yalnızlığa', 'Takviminden dökülmemiş yapraktır ayrılık. Kapı girişinde duvara asılı, “Hoş geldin” yazılı bir tarla korkuluğu gibi Dönüşünü dört gözle bekl...', ARRAY['Türk Edebiyatı','Şiir','Serdar Uzunöner']::text[], 8.5, '{"poet":"Serdar Uzunöner","poet_slug":"serdar-uzunoner","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ayrilik-182-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaziye', 'saziye-seyhmus-sait-aydin-ufkak', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne o kız Şaziye

Paranmı bitti

Telefonu tek çaldırıp kapatıyorsun.

Hani sen hep göklerde gezerdin,

Kanatlarına sumu degdi? 

Bune çabuk iniş,şimdi yerdesin.

Kazamı geçirdin? 

Yine daramı düştü başın? 

Ne bu telaşın.

Yapma be Şaziye

Hiç sevmezdim o çirozu

Bırak kaburgalarının sayılmasını

Belkemiği uymuştu araziye.

Yürürken iki büklüm

Palavraya geldimi dim dik

Sanki iskeletti mübarek,

Bir deri bir kemik

Çokmu hırpaladı

O çiroz seni? 

Ahbe  can dostum

Çok söyledim sana

Bu adamdan yar olmaz diye.

Dinlemedinki beni.

Anladım 

Çok hüzünlü geliyor sesin

Anladım bir dosta ihtiyacın var,

Şimdi nerdesin.

15.08.2003..', 'Ne o kız Şaziye Paranmı bitti Telefonu tek çaldırıp kapatıyorsun. Hani sen hep göklerde gezerdin, Kanatlarına sumu degdi?  Bune çabuk iniş,ş...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sait Aydın']::text[], 8.5, '{"poet":"Şeyhmus Sait Aydın","poet_slug":"seyhmus-sait-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/saziye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Gözlerin', 'kara-gozlerin-mustafa-yigit-morpheus-pn4wz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir bakışın ile bağladın kendine

Şimdi avunuyorum bak hayalinle

Öyle muhtacımki senin sevgine

Beni perişan etti o kara gözlerin

Şimdi uzaklarda derbeder oldum

Geceleri inan resminle avundum

Seni yanımda değil rüyalarımda buldum

Beni ateşe attı o kara gözlerin

Dermanı olmayan dertlere düşürdün

Beni ankarada yaşarken öldürdün

Beni yalnızca rüyalarımda güldürdün

Beni divane yaptı o kara gözlerin

Senden aşkımı hep gizledim

Ssana olan duygularımı hissetmeni istedim

Beni dünyada hiç güldürmedin

Cehennem ateşine attı o kara gözlerin

Suçumu biliyorum cezamı çekeceğim

Ölürken bile inan ismini söyleyeceğim

Son nefesimde bile yanına geleceğim

Beni aşk ateşine attı o kara gözlerin

Gözlerine baktığımda dünyaları görüyorum

Senden ayrı kaldıkca hep seni özlüyorum

Hayalin karşımda gözlerine bakıyorum

Beni kalbimden vurdu o kara gözlerin

Gözlerindeki manayı bir türlü anlayamadım

Ağlamak istedim onuda başaramadım

Senin hasretine bir türlü alışamadım

Kendi mezarımı kazdırdı o kara gözlerin

 Mustafa Yiğit (Morpheus)', 'Bir bakışın ile bağladın kendine Şimdi avunuyorum bak hayalinle Öyle muhtacımki senin sevgine Beni perişan etti o kara gözlerin Şimdi uzakla...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kara-gozlerin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluklarımız', 'dostluklarimiz-seyhmus-sait-aydin-jt5bt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dostluklarımız bu kadar hafifmiydi,

Saman çöpleri gibi savrulup dagıldık,

Cılız bir esintide.

Bu kadarmı sanaldı sevgilerimiz,

Neçabuk sanallaştı,

Dost bildiklerimiz.

Şirlerimiz, şarkılarımız sustu,

Sustu gönül sesimiz,

Sustu kalemlerimiz.

Söyleyin ey dostlar,

Biz bu sanal alemin 

Neresindeyiz.

26.11.2003

                   Şiiri  ses olan,nefes olan, Yorumlayan Sayın Aysun ASAR hanfendiye Sonsuz saygı  ve teşekkürlerimle.', 'Dostluklarımız bu kadar hafifmiydi, Saman çöpleri gibi savrulup dagıldık, Cılız bir esintide. Bu kadarmı sanaldı sevgilerimiz, Neçabuk sanal...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sait Aydın']::text[], 8.5, '{"poet":"Şeyhmus Sait Aydın","poet_slug":"seyhmus-sait-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dostluklarimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelebeğimsin', 'kelebegimsin-mustafa-yigit-morpheus-p9lha', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalbim kırık, umudum kaf dağına gitti

O ulaşılamaz dediğimiz sevdamız bitti

Hayatımı versemde yine beni sevemedi

Can kuşum, mahsun bakışlım, kelebeğimsin

Beni sevmesede, gönül vermesede razıyım

Mutlulukların kalsın, kederi ben alayım

Dağ başında vurulmuş ceylan bakışlım

Can kuşum, mahsun bakışlım, kelebeğimsin

Bilirmisin, çöllerde çiçekler gözyaşı ile büyür

İnsanları gidecekleri yere sevgileri götürür

Kederler birden değil ağır ağır çürütür

Can kuşum, mahsun bakışlım, kelebeğimsin

Senin uğruna her derdi çekmek ne güzel

Gözlerine bakmak, ellerini tutmak ne güzel

Durağın kalbini aşkı ile dağlayan güzel

Can kuşum, mahsun bakışlım, kelebeğimsin

 Mustafa Yiğit (Morpheus)', 'Kalbim kırık, umudum kaf dağına gitti O ulaşılamaz dediğimiz sevdamız bitti Hayatımı versemde yine beni sevemedi Can kuşum, mahsun bakışlım,...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kelebegimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar bana', 'yar-bana-seyhmus-sait-aydin-w6s9s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tek bir söz etmeden ayrılıp gittin.

  Oturalım konuş bana sor bana, 

  Ne yaptımda ayrılığı hak ettim,

  Bu ayrılık cezamıdır yar bana.

İsmin tabu idi,Aşkınsa mabed

Ne şuç işlemişim bana izah et

İzah etki anlayayım öyle git

Bu tavırlar revamıdır yar bana.

 Çaldığım nağmenin sazı kurudu

Yaptığım bestenin sözü kurudu

 İçimde yaşamın özü kurudu

 Sensiz dünya mezar olur yar bana

                                  13.07.2003', 'Tek bir söz etmeden ayrılıp gittin.   Oturalım konuş bana sor bana,    Ne yaptımda ayrılığı hak ettim,   Bu ayrılık cezamıdır yar bana. İsmi...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sait Aydın']::text[], 8.5, '{"poet":"Şeyhmus Sait Aydın","poet_slug":"seyhmus-sait-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yar-bana-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlumusun', 'mutlumusun-mustafa-yigit-morpheus-33do2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gördüğümüzde birbirimize bakardık

Göz göze geldiğimizde neşe ile gülerdik

Herkes gibi bir zamanlar bizde severdik

Ayrıldık işte, şimdi mutlumusun

Benim sevgimi yerlere attın

Gururumla oynayıp kalbimi kırdın

Beni kahrımdan öldürdün

Geceler boyu ağlıyorum, mutlumusun

Beni mahvetmekmiş senin isteğin

Gülüp dalga geçmekmiş senin bildiğin

Sevenlerle alay etmekmiş senin yaptığın

Benimlede dalganı geçtin, mutlumusun

Unutma sevdiğim sende seversin

Sevdiğiyin uğruna her şeyini verirsin

O gidince sevdiğine pişman olursun

Benide pişman ettin, artık mutlumusun

 Mustafa Yiğit (Morpheus)', 'Gördüğümüzde birbirimize bakardık Göz göze geldiğimizde neşe ile gülerdik Herkes gibi bir zamanlar bizde severdik Ayrıldık işte, şimdi mutlu...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mutlumusun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anam', 'anam-seyhmus-sait-aydin-wzxbn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anaların anası

Benim canım can anam

Damarımda kan anam

Bakda gör Dünya’ya ne hale geldi

Kuzular Kurt

Kurtlar hep çakal oldu

Herkes çıkarın peşinde

Memleket hortumcu doldu

Anaların anası 

Can anam 

Garip Anam

Hep meşağğat hep eziyet

Dünya yaşanmaz oldu

Orası buradan rahat

Allah yardımcın olsun

Sevdiklerin yanında

Mekanın cennet olsun

2003.Anneler Günü', 'Anaların anası Benim canım can anam Damarımda kan anam Bakda gör Dünya’ya ne hale geldi Kuzular Kurt Kurtlar hep çakal oldu Herkes çıkarın p...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sait Aydın']::text[], 8.5, '{"poet":"Şeyhmus Sait Aydın","poet_slug":"seyhmus-sait-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/anam-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olursun', 'ne-olursun-mustafa-yigit-morpheus-jkzn7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Genç yaşta saçlarım aklarla doldu

Gözlerim yollarda seni arar oldu

Gönlüm kendisini gurbette buldu

Uzaklarda durma gel ne olursun

Esen rüzgar bağrımı deldi geçti

Kalbim sevmek için seni seçti

Gözlerim yalnıuzca seni sevdi

Sende artık sevgini, ver ne olursun

Ağaçlar inadına gülüyor sanki

Uçan kuşlar alay ediyor sanki

Bulutlar göz kırpıyor sanki

Gönlüme bir ümit ver ne olursun

Sensiz buralarda günlerim yıl oldu

Geçmeyen saatler bana mezar oldu

Postacı artık mektup getirmez oldu

Bir mektup gönder artık ne olursun

 Mustafa Yiğit (Morpheus)', 'Genç yaşta saçlarım aklarla doldu Gözlerim yollarda seni arar oldu Gönlüm kendisini gurbette buldu Uzaklarda durma gel ne olursun Esen rüzga...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ne-olursun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kula Sesleniş', 'kula-seslenis-seyhmus-sait-aydin-eo45k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Haramı sen yemiş hiyle yapmışsın;                                      

Süt içine bulanık su katmışsın; 

Bire alıp yüzbinlere satmışsın.

Söyle seni ben nereye göndersem

Halı almış çul parası vermişsin.

Yanından geçene, yol parası demişsin,

Hakkım benim kul parası demişsin,

Söyle seni ben nereye göndersem		

Ağzından düşmemiş ALLAH’ın adı

Dilinde her zaman haramın tadı.

Dünyada olsaydın ne derdi kadı? 

Söyle seni ben nereye göndersem

                                               

Sana ömür verdi Rabbim al diye

KURAN’ı gönderdi oku kul diye

Sen sarıldın paraya önce mal diye

Söyle seni ben nereye göndersem

Hadi susma söyle varmı  sevabın,

Haram, hiyle, zina bumu cevabın,

Sen bilmezsin Rabbim bilir AHVALİN.

Söyle seni ben nereye göndersem

15.06.2003', 'Haramı sen yemiş hiyle yapmışsın;                                       Süt içine bulanık su katmışsın;  Bire alıp yüzbinlere satmışsın. Söy...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sait Aydın']::text[], 8.5, '{"poet":"Şeyhmus Sait Aydın","poet_slug":"seyhmus-sait-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kula-seslenis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niye', 'niye-mustafa-yigit-morpheus-l7oar', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Neden bu çile bu ızdırap niye

Hiç ızdırap çektirilirmi seven kalplere

Allah''ım sabır ver seven kalplere

Yaşamak dururken ölmek niye

Gözlerim her gün yaşlarla dolar

Hayat ağacımda bir yaprak solar

Ruhumu derin bir hüzün sarar

Gülmek dururken ağlamak niye

Deli ırmak gibi coşuyorum ben

Asi rüzgar gibi esiyorum ben

Kimsesiz garip gibi geziyorum ben

Sevmek dururken bu nefret niye

Kurumuş ağaç gibi, soldurdun hayatımı

Sakın güzelim alma benim ahımı

Bırak ben çekeyim senin günahını

Dostluk dururken bu kibir niye

 Mustafa Yiğit (Morpheus)', 'Neden bu çile bu ızdırap niye Hiç ızdırap çektirilirmi seven kalplere Allah''ım sabır ver seven kalplere Yaşamak dururken ölmek niye Gözlerim...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/niye-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-mustafa-yigit-morpheus-tkpky', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beyaz bir gelinlik giymiştin

Ellerini uzatıp gel demiştin

Her şeyimle sana gelmiştim

Yalnızca bir rüya imiş sevdiğim

Güzel bir düğünle evlenmiştik

Hayatlarımızı birleştirmiştik

Paylaşmayıda öğrenmiştik

Yalnızca bir rüya imiş sevdiğim

Ömrümüz boyunca mutlu oluyorduk

Birbirimize delicesine bağlanıyorduk

Mutluluğumuzu etrafımıza yansıtıyorduk

Yalnızca bir rüya imiş sevdiğim

 Mustafa Yiğit (Morpheus)', 'Beyaz bir gelinlik giymiştin Ellerini uzatıp gel demiştin Her şeyimle sana gelmiştim Yalnızca bir rüya imiş sevdiğim Güzel bir düğünle evlen...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ruya-131-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sar beni', 'sar-beni-seyhmus-sait-aydin-n1o5j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kapına köle geldim,Hem terlet hem yor beni

Çal duvardan duvara,taştan taşa vur beni,

Öyle çok özlemişim,öyle çok hasretimki,

Kolların ulaşmazsa, bakışınla sar beni

Nice tufanlar görüp,nice sele dayandım,

Nice cehennem görüp nice kora dayandım.

Ömrüm çarık, eskitip,bak kapına dayandım

Seninle ölecegim,sevmiyorsan kov beni.

20.10.2003', 'Kapına köle geldim,Hem terlet hem yor beni Çal duvardan duvara,taştan taşa vur beni, Öyle çok özlemişim,öyle çok hasretimki, Kolların ulaşma...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sait Aydın']::text[], 8.5, '{"poet":"Şeyhmus Sait Aydın","poet_slug":"seyhmus-sait-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sar-beni-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakın', 'sakin-mustafa-yigit-morpheus-097d5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karanlık geceme güneş gibi doğdun

Mutluluğa giden yolu ben sende buldum

O güzelliğin ile yaşama ümidim oldun

Beni bırakıp uzaklara gitme sakın

Bir çocuk hiç büyümek istermi

Aşık olan hiç ayrılmak istermi

Seven gönül hiç unutmak istermi

Gönlümü kahırla boğup gitme sakın

Sen kalbimin aşk perisisin

Garip gönlümün ilham güneşisin

Yalnız benim için açan güneşsin

Mahşere kadar kalbimden çıkma sakın

Kalbim hassastır sakın kırma

Yol uzun olsada beni unutma

Sevdalı olan gözlerimi ağlatma

Beni gurbette bırakıp gitme sakın

 Mustafa Yiğit (Morpheus)', 'Karanlık geceme güneş gibi doğdun Mutluluğa giden yolu ben sende buldum O güzelliğin ile yaşama ümidim oldun Beni bırakıp uzaklara gitme sak...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sakin-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zemzem', 'zemzem-cafer-petek-a0c9w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bileysiz bıçakların gülüşleri boğazımda

Yama tutmayan düşlerde

Rehin kaldım bozuk saat ayarında

Güneşin utandığı bu şehrin

Suçlu bir kedi sessizliğinde yürünen

Sokakları tükenirken ellerinde

Umudun iğreti bağlacı

Gözlerin de tükenir

Boğazımda bileysiz bıçakların gülüşleri

Daraltır zamanı

Dar zamanda yaşamak

Bir kadının yazdan kalma elleri gibidir

Elleri gibidir bir kadının

Çölden getirdiği

Ne Hacer annemdir

Ne adım İsmail

Neredesin sonsuz teslimiyetim', 'Bileysiz bıçakların gülüşleri boğazımda Yama tutmayan düşlerde Rehin kaldım bozuk saat ayarında Güneşin utandığı bu şehrin Suçlu bir kedi se...', ARRAY['Türk Edebiyatı','Şiir','Cafer Petek']::text[], 8.5, '{"poet":"Cafer Petek","poet_slug":"cafer-petek","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/zemzem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selvi Boylum', 'selvi-boylum-mustafa-yigit-morpheus-1s1i2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Duydumki evleniyormuşsun düğünün varmış

Kendini fazla üzme gül selvi boylum

O ince belini bir başkası saracakmış

Fazla düşünme gül selvi boylum

Benim yerimi artık başkası almış

İpek saçlarını yabancı eller okşarmış

O kara gözlerinden hep yaş akarmış

Ağlama, sil gözyaşlarını gül selvi boylum

Ne yapalım yazılan gelirmiş başa

Kurtulamassın kaderinden çabalama boşuna

Bir kötülük yapan olursa sana

Yalnız bir haber, ver selvi boylum

Kaderimmiş diye mutlu olmana bak

Mutlu ediyormu söyle ağlamak

Her sevgide vardır böyle aldanmak

Boşver artık dünyaya, gül selvi boylum

 Mustafa Yiğit (Morpheus)', 'Duydumki evleniyormuşsun düğünün varmış Kendini fazla üzme gül selvi boylum O ince belini bir başkası saracakmış Fazla düşünme gül selvi boy...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/selvi-boylum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Varsın', 'sen-varsin-mustafa-yigit-morpheus-tp32m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geçen günler seni unutturmuyor

Çünkü her yerde sen varsın

Kalbim hiç yalnızlık hissetmiyor

Dertli kalbimde hep sen varsın

Artık gözlerimden yaş akmıyor

Ağaçlar bana seni hatırlatmıyor

Artık hasretlik rüzgarı esmiyor

Esen rüzgarlarda hep sen varsın

Sigaram dertlerimi hiç dindirmiyor

Yanan bedenim sönmek bilmiyor

Gözlerim her yerde seni arıyor

Ruhumda, düşüncemde hep sen varsın

Saçıma akların düşmesi farketmiyor

Gözlerim senden başkasını görmüyor

Uzaklarda olsanda hasretliğin anlaşılmıyor

Gurbette, sılada hep sen varsın

 Mustafa Yiğit (Morpheus)', 'Geçen günler seni unutturmuyor Çünkü her yerde sen varsın Kalbim hiç yalnızlık hissetmiyor Dertli kalbimde hep sen varsın Artık gözlerimden ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-varsin-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kin', 'kin-seyhmus-sait-aydin-o1u4w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgimin yerini kin aldı benim,

Hem kendini hem ismini yel aldı senin.

Öyle bir tükeniş tükendinki sen,

Hem ruhun hem bedenin, kül oldu senin.

.', 'Sevgimin yerini kin aldı benim, Hem kendini hem ismini yel aldı senin. Öyle bir tükeniş tükendinki sen, Hem ruhun hem bedenin, kül oldu seni...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sait Aydın']::text[], 8.5, '{"poet":"Şeyhmus Sait Aydın","poet_slug":"seyhmus-sait-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babama', 'babama-seyhmus-sait-aydin-xwotm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dünya çok değişti yaşam zorlaştı

Kötünün menzili iyiyi aştı

Eskiden dost arkadaş hepsi gardaştı

Şimdi tek dostumuz para be baba

Lüks yaşam uğruna namus satanlar

Devlet parasıyla caka atanlar

Kocayı bırakıp elle yatanlar

Namus bezirganı oldu be baba

Yol yordam kalmadı sevgi kayboldu

Açılıp saçıldık iffet kayboldu

Beleşe alıştık külfet kayboldu 

Avrupa sevdasında kaybolduk baba

Ar namus kalmadı hep zillet olduk

Sevgisiz saygısız bir millet olduk

Paraya tapınan bir illet olduk

Ölmek daha iyi değilmi baba

Mekanınız cennet olur inşallah

Bize de bir himmet olur inşallah

Bedava bir mezar kalır inşallah

Musalla taşına gelince baba

Gün bitiyor yol yakın güneş batıyor

Yakında yanında olurum baba

Elini uzatıp himmet edersen

inanki cennetlik olurum baba

15/06/2003

 babalar günü 

.', 'Dünya çok değişti yaşam zorlaştı Kötünün menzili iyiyi aştı Eskiden dost arkadaş hepsi gardaştı Şimdi tek dostumuz para be baba Lüks yaşam u...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sait Aydın']::text[], 8.5, '{"poet":"Şeyhmus Sait Aydın","poet_slug":"seyhmus-sait-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/babama-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Ben', 'sen-ve-ben-mustafa-yigit-morpheus-6ab8a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'SEN; gül bahcelerinin eşsiz sümbülü

BEN; yalçın dağların ayrık otuyum

SEN; sonsuz kainatın eşsiz güneşi

BEN; kara toprakta bir kör kuyuyum

SEN; dört mevsim yeşeren ağaç

SEN;  mutluluğa muhtaç, sevgiye aç

SEN; hasta olan kalplere ilaç

BEN; kimsesiz yerlerde mezar taşıyım

SEN; canda cansın seven kalplere

SEN; gıda gibisin biçare gönüllere

SEN; umutsun kalpten sevenlere

BEN; umut yolunun yolcusuyum

SEN; gönlümün solmayan çiçeği

SEN; gecelerimin batmayan güneşi

SEN; hayatımın aşkı, neşesi

BEN; aşkınla yanan dilenciyim

SEN; damarlarımda dolaşan kan gibisin

SEN; canımın içerisinde can gibisin

SEN; Durağa hayat verensin 

BEN; sana vurulmuş aşk hançeriyim

 Mustafa Yiğit (Morpheus)', 'SEN; gül bahcelerinin eşsiz sümbülü BEN; yalçın dağların ayrık otuyum SEN; sonsuz kainatın eşsiz güneşi BEN; kara toprakta bir kör kuyuyum S...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit (Morpheus)']::text[], 8.5, '{"poet":"Mustafa Yiğit (Morpheus)","poet_slug":"mustafa-yigit-morpheus","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-ve-ben-80-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk İle Ateşin Dostluğu Yaman', 'ask-i-le-atesin-dostlugu-yaman-i-smet-barlioglu-ykgbo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yağmurlar kalbime yağıp duruyor

Yaktığın ateşi söndürmek için.

Aşkın yüreğime bağdaş kuruyor

Külleri ateşe döndürmek için.

Aşk ile ateşin dostluğu yaman,

Birisi kıvılcım, birisi duman,

Yüreğim yanıyor asla durmadan,

Daha ne gerek ki; öldürmek için? 

Seni merhem ettim yürek yarama,

Kalbimi, ruhumu boyadın kana,

Bu böyle giderse; çıkmam akşama,

Uğraşma derdimi dindirmek için.

Sana aşık olmak neden bir elem? 

Kederler içinde gündüzüm-gecem,

Seni sevmek oldu bitmeyen çilem,

Boşa uğraşmışım bitirmek için.

(BAYRAM AKŞAMLARI isimli hece şiirlerinden > 89-90/100)', 'Yağmurlar kalbime yağıp duruyor Yaktığın ateşi söndürmek için. Aşkın yüreğime bağdaş kuruyor Külleri ateşe döndürmek için. Aşk ile ateşin do...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ask-ile-atesin-dostlugu-yaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Gemiler, Ne Rüzgar Alıp Getirdi Seni', 'ne-gemiler-ne-ruzgar-alip-getirdi-seni-i-smet-barlioglu-9n8bo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıllardır dıhtımlarda esen rüzgara baktım,

Bekledim martılarla gelecek gemileri,

Kalbimi fener edip kayalara bıraktım,

Ne gemiler, ne rüzgar alıp getirdi seni.

Martılar çığlık çığlık karanlıklar içinde,

Çöreklenmiş hasretin kalbime bin biçimde,

Gizledim ateşimi yine kendi içimde,

Aşkın kasırga olup tuttu savurdu beni.

Kendini taşa vurdu dalgalar kükreyerek,

Sanki aynı hasretle yanarak, titreyerek,

Seni ne çok bekledim denizi dinleyerek,

Gelmedi yüreğimin denizden bekleneni.

Eğer meraj edersen, bil ki rıhtımlardayım,

Ruhum denizde kalmış, bense kıyılardayım,

Bir de akşam olmuşsa; çok aşırı dardayım,

Beni sevindirecek belki bir gün bir gemi.

(BAYRAM AKŞAMLARI isimli hece şiirlerimden > 91-92/100)', 'Yıllardır dıhtımlarda esen rüzgara baktım, Bekledim martılarla gelecek gemileri, Kalbimi fener edip kayalara bıraktım, Ne gemiler, ne rüzgar...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ne-gemiler-ne-ruzgar-alip-getirdi-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeminler Olsun Sana', 'yeminler-olsun-sana-i-smet-barlioglu-aldq9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senden başka yar sevmem,

Yeminler olsun sana.

Ben ahdımı çiğnemem,

Yeminler olsun sana.

Mehtap bayram kandili,

Gönlüm mehtaptan diri,

Unutmam o günleri,

Yeminler olsun sana.

Kavrulmuşum yanarım,

Kurumuş dudaklarım,

Elinde rüyalarım

Yeminler olsun sana.

Öğüt verdim kalbime,

Sana meyletsin diye,

Asla dönmem geriye

Yeminler olsun sana.

Bu olup olacağım,

Ya seni alacağım,

Ya ölüp kalacağım

Yeminler olsun sana.

(BAYRAM AKŞAMLARI isimli hece şiirlerinden > 93-94/100)', 'Senden başka yar sevmem, Yeminler olsun sana. Ben ahdımı çiğnemem, Yeminler olsun sana. Mehtap bayram kandili, Gönlüm mehtaptan diri, Unutma...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yeminler-olsun-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Çimen Üstünde Bir Çiğ Damlası', 'sen-cimen-ustunde-bir-cig-damlasi-i-smet-barlioglu-wn7c7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen çimen üstünde bir çiğ damlası,

Ben çiğle çimenin yorgun hastası,

Gülüşün kalbimin tek sadakası,

Ömrümce dilensem doyar mıyım ki? 

Sen durgun denizde bir altın mehtap,

Ben sular üstünde bekleyen hesap,

Yüreğim tümüyle olsa da harap

Yerine elleri koyar mıyım ki? 

Sen masalda kalmış İrem Bahçesi,

Bense hasretlerin yorgun kölesi,

Var mıdır dünyada aşkın böylesi? 

Ben bunu lütuftan sayar mıyım ki? 

Sen belki günlerin en güzelinde,

Ben belki gecenin elemlerinde,

Bir gün sayıklarken bir iniltinde

Acaba adımı duyar mıyım ki? 

(BAYRAM AKŞAMLARI isimli hece şiirlerinden > 95-96/100)', 'Sen çimen üstünde bir çiğ damlası, Ben çiğle çimenin yorgun hastası, Gülüşün kalbimin tek sadakası, Ömrümce dilensem doyar mıyım ki?  Sen du...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-cimen-ustunde-bir-cig-damlasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Islandı Saçların Mavi Sularda', 'islandi-saclarin-mavi-sularda-i-smet-barlioglu-7lncb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Denizin köpüğü, sahilin kumu

Ayak izlerinde durdu, birleşti.

Islandı saçların mavi sularda,

Aşkım saçlarında kristalleşti.

Alev mi saçların? Tutuştu sular,

Yaldıza boyandı koyda martılar,

Altın rengi oldu beyaz dalgalar,

Gönlüm ateşinle yandı, titreşti.

Bir anda kalbimde koptu birkaç tel,

Sen yorgun sularda alevden heykel,

Gel artık, yanmaya razı oldum, gel,

Tutuşmak gözümde çok şirinleşti.

(BAYRAM AKŞAMLARI isimli hece şiirlerinden > 97-98/100)', 'Denizin köpüğü, sahilin kumu Ayak izlerinde durdu, birleşti. Islandı saçların mavi sularda, Aşkım saçlarında kristalleşti. Alev mi saçların?...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/islandi-saclarin-mavi-sularda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni ki Tek Bir An Unutamadım', 'seni-ki-tek-bir-an-unutamadim-i-smet-barlioglu-u89td', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geçip gitti ömrüm, saçım ağardı,

Seni ki tek bir an unutamadım.

Saçların sonbahar, yüzün bahardı,

Kaldırıp bir yana fırlatamadım.

Her soluk alışta zikrettim seni,

İkinci bir kalbim zannettim seni,

Dünyada herşeye benzettim seni,

Perişan gönlümü yanıltamadım.

İlk göz ağrısını arıyor insan,

İçtiklerim haram, yediğim haram,

Seni arıyorum her an durmadan,

Senmişsin lezzetim, senmişsin tadım.

Her nereye baksam sen orda varsın,

Gönlüm başkasını neden arasın? 

Sen kışa son veren taze baharsın,

Rüzgarın ıslığı benim feryadım.

İnanmam saçının ağardığına,

İnanmam tutuşup kavrulduğuna,

İnanmam yaşlanıp yorulduğuna,

Senin hayallerin benim imdadım.

(BAYRAM AKŞAMLARI isimli hece şiirlerinden > 99-100/100)', 'Geçip gitti ömrüm, saçım ağardı, Seni ki tek bir an unutamadım. Saçların sonbahar, yüzün bahardı, Kaldırıp bir yana fırlatamadım. Her soluk ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/seni-ki-tek-bir-an-unutamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ihanet', 'ihanet-betul-turk-7yrvj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen baskasinla ates olurken

Ben bunu bilmekle dertlerime dert ekliyorum

Sen hep cift uyanirken

Ben uyandigim her sabah ölmek istiyorum

Sen yabanci dudaklardayken

Ben dokundugun tenimi kesip atiyorum

Sen unutmussundur bile ismimi

Ben sana her gün daha fazla beddua buluyorum

(almanya 30.05.2001)', 'Sen baskasinla ates olurken Ben bunu bilmekle dertlerime dert ekliyorum Sen hep cift uyanirken Ben uyandigim her sabah ölmek istiyorum Sen y...', ARRAY['Türk Edebiyatı','Şiir','Betül Türk']::text[], 8.5, '{"poet":"Betül Türk","poet_slug":"betul-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ihanet-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
